ZET_QUALITY_MARKDOWN_TABLE_SEPARATOR_RE = re.compile(r"^\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|?\s*$")
ZET_QUALITY_SOURCE_METADATA_FIELDS = (
    "acquired_at",
    "acquired_by",
    "acquisition_method",
    "verification_status",
)
ZET_QUALITY_SOURCE_RIGHTS_FIELDS = (
    "public_report_allowed",
    "rights_status",
    "copyright_status",
)
ARCHIVE_DEV_PROJECT_MARKERS = (
    "package.json",
    "package-lock.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "node_modules",
    ".next",
    ".vercel",
    ".env.local",
    "src",
    "public",
    ".vercelignore",
    "next.config.js",
    "next.config.mjs",
    "vite.config.ts",
)


class ArchiveServiceError(Exception):
    pass


class PublicationOutcomeUnverified(ArchiveServiceError):
    """A final path may have changed but cannot be bound to expected bytes."""


class ArchiveIndexReadBoundaryError(ArchiveServiceError):
    """The generated index cannot be opened without violating read-only I/O."""


class ObjetRediscoveryArchiveBoundaryError(ArchiveServiceError):
    """The plan cannot enumerate local zettels without crossing an unsafe path."""


class ZetTitleRemapInputError(ArchiveServiceError):
    """A title-remap input error whose fixed code/message are safe to print."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code


class NotionProviderRequestError(ArchiveServiceError):
    def __init__(
        self,
        message: str,
        *,
        http_status: int | None = None,
        notion_code: str | None = None,
        failure_category: str = "provider_request_failed",
        stop_condition: str = "provider_fetch_failed_raw_error_redacted",
        retryable: bool = False,
        action_hint: str = "Review the local connection setup and retry after the human fixes the provider-side issue.",
    ) -> None:
        super().__init__(message)
        self.http_status = http_status
        self.notion_code = notion_code
        self.failure_category = failure_category
        self.stop_condition = stop_condition
        self.retryable = retryable
        self.action_hint = action_hint


def connect_archive_index(
    db_path: Path,
    *,
    write: bool = False,
    row_factory: bool = False,
    immutable_read: bool = False,
) -> sqlite3.Connection:
    if write and immutable_read:
        raise ValueError("immutable_read cannot be combined with write")
    if (
        (not write and not immutable_read)
        or (write and os.path.lexists(db_path))
    ):
        _require_archive_index_delete_read_boundary(db_path)
    if immutable_read:
        # This inspection path must not create WAL/SHM sidecars.  `immutable=1`
        # is intentionally limited to dry-run evidence summaries: it reads the
        # last complete SQLite snapshot and makes no concurrent-freshness claim.
        database = db_path.resolve(strict=True).as_uri() + "?mode=ro&immutable=1"
        conn = sqlite3.connect(
            database,
            timeout=ARCHIVE_INDEX_BUSY_TIMEOUT_MS / 1000,
            uri=True,
        )
    elif not write:
        database = db_path.resolve(strict=True).as_uri() + "?mode=ro"
        conn = sqlite3.connect(
            database,
            timeout=ARCHIVE_INDEX_BUSY_TIMEOUT_MS / 1000,
            uri=True,
        )
    else:
        conn = sqlite3.connect(
            db_path,
            timeout=ARCHIVE_INDEX_BUSY_TIMEOUT_MS / 1000,
        )
    if row_factory:
        conn.row_factory = sqlite3.Row
    try:
        conn.execute(f"PRAGMA busy_timeout = {ARCHIVE_INDEX_BUSY_TIMEOUT_MS}")
        if not write:
            conn.execute("PRAGMA query_only=ON")
        if write:
            journal_mode = conn.execute(
                "PRAGMA journal_mode=DELETE"
            ).fetchone()
            if (
                journal_mode is None
                or str(journal_mode[0]).lower() != "delete"
            ):
                raise sqlite3.OperationalError(
                    "archive_index_delete_journal_mode_unavailable"
                )
            conn.execute("PRAGMA synchronous=NORMAL")
    except sqlite3.Error:
        conn.close()
        raise
    return conn


def _require_archive_index_delete_read_boundary(db_path: Path) -> None:
    """Require a clean rollback-mode snapshot before SQLite opens the file."""

    descriptor: int | None = None
    try:
        path_before = os.lstat(db_path)
        open_flags = os.O_RDONLY | getattr(os, "O_BINARY", 0)
        open_flags |= getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(db_path, open_flags)
        opened_before = os.fstat(descriptor)
        header = os.read(descriptor, 20)
        opened_after = os.fstat(descriptor)
        path_after = os.lstat(db_path)
    except OSError:
        raise ArchiveIndexReadBoundaryError(
            "archive_index_read_preflight_failed"
        ) from None
    finally:
        if descriptor is not None:
            os.close(descriptor)

    def identity(observed: os.stat_result) -> tuple[int, ...]:
        return (
            int(observed.st_dev),
            int(observed.st_ino),
            int(observed.st_mode),
            int(observed.st_nlink),
            int(observed.st_size),
            int(observed.st_mtime_ns),
            int(getattr(observed, "st_file_attributes", 0)),
        )

    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x00000400)
    if any(
        stat.S_ISLNK(observed.st_mode)
        or not stat.S_ISREG(observed.st_mode)
        or observed.st_nlink != 1
        or getattr(observed, "st_file_attributes", 0) & reparse_flag
        for observed in (path_before, opened_before, opened_after, path_after)
    ) or not (
        identity(path_before)
        == identity(opened_before)
        == identity(opened_after)
        == identity(path_after)
    ):
        raise ArchiveIndexReadBoundaryError("archive_index_rebuild_required")
    header_is_delete_mode = (
        len(header) == 20
        and header[:16] == b"SQLite format 3\x00"
        and header[18:20] == b"\x01\x01"
    )
    sidecars = tuple(
        db_path.with_name(db_path.name + suffix)
        for suffix in ("-wal", "-shm", "-journal")
    )
    try:
        sidecar_present = any(
            _archive_index_path_is_lstat_present(sidecar)
            for sidecar in sidecars
        )
    except OSError:
        raise ArchiveIndexReadBoundaryError(
            "archive_index_read_preflight_failed"
        ) from None
    if not header_is_delete_mode or sidecar_present:
        raise ArchiveIndexReadBoundaryError(
            "archive_index_rebuild_required"
        )


def _archive_index_path_is_lstat_present(path: Path) -> bool:
    try:
        os.lstat(path)
    except FileNotFoundError:
        return False
    return True


def require_yaml() -> None:
    if yaml is None:
        raise ArchiveServiceError("PyYAML is required. Install it with: python -m pip install PyYAML")


def load_yaml(text: str) -> Any:
    require_yaml()
    loader = getattr(yaml, "CSafeLoader", yaml.SafeLoader)  # type: ignore[union-attr]
    return yaml.load(text, Loader=loader)  # type: ignore[union-attr]


class ApprovalYamlDuplicateKeyError(ValueError):
    """Static approval-boundary error for an ambiguous YAML mapping."""


class ApprovalYamlValueError(ValueError):
    """Static approval-boundary error for a non-JSON YAML value tree."""


APPROVAL_YAML_MAX_DEPTH = 64
APPROVAL_YAML_MAX_NODES = 100_000


def load_approval_yaml_without_duplicate_keys(text: str) -> Any:
    """Load approval-bound YAML while rejecting duplicate keys at every depth."""
    require_yaml()
    base_loader = getattr(yaml, "CSafeLoader", yaml.SafeLoader)  # type: ignore[union-attr]

    class DuplicateRejectingApprovalLoader(base_loader):  # type: ignore[misc, valid-type]
        def construct_mapping(self, node: Any, deep: bool = False) -> Any:
            if not isinstance(node, yaml.MappingNode):  # type: ignore[union-attr]
                return super().construct_mapping(node, deep=deep)
            self.flatten_mapping(node)
            mapping: dict[Any, Any] = {}
            for key_node, value_node in node.value:
                key = self.construct_object(key_node, deep=deep)
                if not isinstance(key, str):
                    raise ApprovalYamlValueError("approval_yaml_mapping_key_invalid")
                try:
                    duplicate = key in mapping
                except TypeError as exc:
                    raise ValueError("approval_yaml_mapping_key_invalid") from exc
                if duplicate:
                    raise ApprovalYamlDuplicateKeyError("approval_yaml_duplicate_key")
                mapping[key] = self.construct_object(value_node, deep=deep)
            return mapping

    return yaml.load(text, Loader=DuplicateRejectingApprovalLoader)  # type: ignore[union-attr]


def normalize_approval_json_tree(value: Any) -> Any:
    """Copy an approval YAML value into one bounded, acyclic JSON value tree."""
    active_containers: set[int] = set()
    visited_nodes = 0

    def normalize(item: Any, depth: int) -> Any:
        nonlocal visited_nodes
        visited_nodes += 1
        if visited_nodes > APPROVAL_YAML_MAX_NODES:
            raise ApprovalYamlValueError("approval_yaml_node_limit_exceeded")
        if depth > APPROVAL_YAML_MAX_DEPTH:
            raise ApprovalYamlValueError("approval_yaml_depth_limit_exceeded")
        if item is None or isinstance(item, (str, bool, int)):
            return item
        if isinstance(item, (date, datetime)):
            # Preserve the project's documented compatibility treatment for
            # unquoted YAML timestamps while still returning a JSON string.
            return item.isoformat()
        if isinstance(item, float):
            if not math.isfinite(item):
                raise ApprovalYamlValueError("approval_yaml_non_finite_number")
            return item
        if isinstance(item, dict):
            identity = id(item)
            if identity in active_containers:
                raise ApprovalYamlValueError("approval_yaml_cycle_detected")
            active_containers.add(identity)
            try:
                normalized: dict[str, Any] = {}
                for key, child in item.items():
                    if not isinstance(key, str):
                        raise ApprovalYamlValueError(
                            "approval_yaml_mapping_key_invalid"
                        )
                    normalized[key] = normalize(child, depth + 1)
                return normalized
            finally:
                active_containers.remove(identity)
        if isinstance(item, list):
            identity = id(item)
            if identity in active_containers:
                raise ApprovalYamlValueError("approval_yaml_cycle_detected")
            active_containers.add(identity)
            try:
                return [normalize(child, depth + 1) for child in item]
            finally:
                active_containers.remove(identity)
        raise ApprovalYamlValueError("approval_yaml_value_type_invalid")

    return normalize(value, 0)


def dump_yaml(data: Any) -> str:
    require_yaml()
    return yaml.safe_dump(data, sort_keys=False, allow_unicode=True)  # type: ignore[union-attr]


def parse_frontmatter(text: str) -> str | None:
    if text.startswith("\ufeff"):
        text = text[1:]
    match = FRONTMATTER_RE.match(text)
    if not match:
        return None
    return match.group(1)


def split_zettel_text(text: str) -> tuple[dict[str, Any], str]:
    if text.startswith("\ufeff"):
        text = text[1:]
    frontmatter_text = parse_frontmatter(text)
    frontmatter = load_yaml(frontmatter_text) if frontmatter_text else {}
    if not isinstance(frontmatter, dict):
        frontmatter = {}
    body = text[FRONTMATTER_RE.match(text).end() :].lstrip() if frontmatter_text and FRONTMATTER_RE.match(text) else text
    return frontmatter, body


def blocked_zettel_content_boundary(reason: str) -> dict[str, Any]:
    """Return a content-free result for an untrusted zettel boundary.

    This is deliberately separate from ``split_zettel_text``.  The tolerant
    parser remains useful for import/capture workflows, while any surface that
    may expose an existing archive zettel must fail closed when its frontmatter
    boundary, YAML, shape, or lifecycle status cannot be trusted.
    """
    return {
        "state": "blocked",
        "reason": reason,
        "frontmatter": {},
        "body": "",
    }


def redacted_zettel_safe_frontmatter(frontmatter: dict[str, Any]) -> dict[str, str]:
    """Return only validated scalar fields from the public redaction envelope."""
    safe_frontmatter: dict[str, str] = {"status": "redacted"}
    zettel_id = frontmatter.get("id")
    if isinstance(zettel_id, str) and ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(zettel_id):
        safe_frontmatter["id"] = zettel_id
    kind = frontmatter.get("kind")
    if isinstance(kind, str) and SOURCE_INTAKE_ARTIFACT_KIND_RE.fullmatch(kind):
        safe_frontmatter["kind"] = kind
    for key in ("created_at", "updated_at"):
        value = frontmatter.get(key)
        if isinstance(value, str) and len(value) <= 64 and valid_iso_timestamp(value):
            safe_frontmatter[key] = value
    return safe_frontmatter


def parse_zettel_content_boundary(text: str) -> dict[str, Any]:
    """Parse a zettel for a body-exposing boundary without fail-open fallback."""
    if text.startswith("\ufeff"):
        text = text[1:]
    match = FRONTMATTER_RE.match(text)
    if match is None:
        return blocked_zettel_content_boundary("frontmatter_boundary_invalid")
    try:
        loaded = load_yaml(match.group(1))
    except Exception:
        return blocked_zettel_content_boundary("frontmatter_yaml_invalid")
    if not isinstance(loaded, dict):
        return blocked_zettel_content_boundary("frontmatter_not_object")
    frontmatter = json_safe(loaded)
    status = frontmatter.get("status")
    if not isinstance(status, str) or status not in ZETTEL_CONTENT_STATUSES:
        return blocked_zettel_content_boundary("frontmatter_status_invalid")
    body = text[match.end() :].lstrip()
    if status == "redacted":
        # Only the pre-existing, explicitly public redaction envelope crosses
        # this boundary.  The source body and all other frontmatter stay out.
        safe_frontmatter = redacted_zettel_safe_frontmatter(frontmatter)
        return {
            "state": "redacted",
            "reason": None,
            "frontmatter": safe_frontmatter,
            "body": "",
        }
    return {
        "state": "readable",
        "reason": None,
        "frontmatter": frontmatter,
        "body": body,
    }


def parse_approval_zettel_content_boundary(text: str) -> dict[str, Any]:
    """Parse one approval-bound zettel with duplicate-key rejection."""
    if text.startswith("\ufeff"):
        text = text[1:]
    match = FRONTMATTER_RE.match(text)
    if match is None:
        return blocked_zettel_content_boundary("frontmatter_boundary_invalid")
    try:
        loaded = load_approval_yaml_without_duplicate_keys(match.group(1))
    except ApprovalYamlDuplicateKeyError:
        return blocked_zettel_content_boundary("frontmatter_duplicate_key")
    except Exception:
        return blocked_zettel_content_boundary("frontmatter_yaml_invalid")
    if not isinstance(loaded, dict):
        return blocked_zettel_content_boundary("frontmatter_not_object")
    try:
        frontmatter = normalize_approval_json_tree(loaded)
    except (ApprovalYamlValueError, RecursionError):
        return blocked_zettel_content_boundary("frontmatter_yaml_invalid")
    status = frontmatter.get("status")
    if not isinstance(status, str) or status not in ZETTEL_CONTENT_STATUSES:
        return blocked_zettel_content_boundary("frontmatter_status_invalid")
    body = text[match.end() :].lstrip()
    if status == "redacted":
        return {
            "state": "redacted",
            "reason": None,
            "frontmatter": redacted_zettel_safe_frontmatter(frontmatter),
            "body": "",
        }
    return {
        "state": "readable",
        "reason": None,
        "frontmatter": frontmatter,
        "body": body,
    }


def read_zettel_content_boundary(path: Path) -> dict[str, Any]:
    """Read a zettel into the fail-closed content boundary without raw errors."""
    try:
        text = path.read_text(encoding="utf-8")
    except UnicodeError:
        return blocked_zettel_content_boundary("frontmatter_unicode_error")
    except OSError:
        return blocked_zettel_content_boundary("frontmatter_io_error")
    return parse_zettel_content_boundary(text)


def require_readable_zettel_text(text: str) -> tuple[dict[str, Any], str]:
    """Unwrap a validated non-redacted zettel text or raise a static error."""
    boundary = parse_zettel_content_boundary(text)
    if boundary["state"] == "redacted":
        raise ArchiveServiceError("Redacted zettel content is unavailable for this operation.")
    if boundary["state"] == "blocked":
        raise ArchiveServiceError(
            "Zettel content is unavailable because its frontmatter could not be validated."
        )
    return boundary["frontmatter"], boundary["body"]


def require_readable_zettel_content(path: Path) -> tuple[dict[str, Any], str]:
    """Return validated non-redacted zettel content or raise a static error."""
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        raise ArchiveServiceError(
            "Zettel content is unavailable because it could not be read safely."
        ) from None
    return require_readable_zettel_text(text)


def validated_approval_zettel_snapshot(
    path: Path,
    *,
    max_bytes: int,
    expected_zettel_id: str | None,
    expected_archive_id: str | None,
    expected_status: str,
) -> dict[str, Any]:
    """Expose one exact zettel snapshot only after full approval validation.

    Rejected bytes never cross this boundary, so callers cannot accidentally
    turn malformed, redacted, wrong-identity, or wrong-lifecycle content into
    a trusted hash, equality result, plan digest, or write candidate.
    """

    def blocked(*issue_codes: str) -> dict[str, Any]:
        return {
            "ok": False,
            "issue_codes": unique_preserve_order(
                [code for code in issue_codes if code]
            ),
            "bytes": None,
            "frontmatter": {},
            "body": "",
        }

    if max_bytes < 1:
        return blocked("zettel_size_limit_invalid")
    try:
        before = os.lstat(path)
    except OSError:
        return blocked("frontmatter_io_error")
    if not stat.S_ISREG(before.st_mode):
        return blocked("zettel_not_regular_file")
    if before.st_size > max_bytes:
        return blocked("zettel_size_limit_exceeded")

    try:
        with path.open("rb") as handle:
            opened = os.fstat(handle.fileno())
            if (
                not stat.S_ISREG(opened.st_mode)
                or (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino)
                or opened.st_size != before.st_size
            ):
                return blocked("zettel_snapshot_changed")
            raw_bytes = handle.read(max_bytes + 1)
            opened_after = os.fstat(handle.fileno())
    except OSError:
        return blocked("frontmatter_io_error")
    if len(raw_bytes) > max_bytes:
        return blocked("zettel_size_limit_exceeded")
    try:
        after = os.lstat(path)
    except OSError:
        return blocked("zettel_snapshot_changed")
    before_generation = (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
    opened_generation = (
        opened.st_dev,
        opened.st_ino,
        opened.st_size,
        opened.st_mtime_ns,
    )
    opened_after_generation = (
        opened_after.st_dev,
        opened_after.st_ino,
        opened_after.st_size,
        opened_after.st_mtime_ns,
    )
    after_generation = (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
    if (
        before_generation != opened_generation
        or opened_generation != opened_after_generation
        or opened_after_generation != after_generation
        or len(raw_bytes) != before.st_size
    ):
        return blocked("zettel_snapshot_changed")

    try:
        text = decode_utf8_with_universal_newlines(raw_bytes)
    except UnicodeError:
        return blocked("frontmatter_unicode_error")
    boundary = parse_approval_zettel_content_boundary(text)
    if boundary.get("state") == "blocked":
        return blocked(str(boundary.get("reason") or "frontmatter_boundary_invalid"))
    frontmatter = boundary.get("frontmatter")
    if not isinstance(frontmatter, dict):
        return blocked("frontmatter_not_object")

    issues: list[str] = []
    actual_zettel_id = frontmatter.get("id")
    if (
        not isinstance(actual_zettel_id, str)
        or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(actual_zettel_id)
    ):
        issues.append("frontmatter_identity_invalid")
    if expected_zettel_id is not None and actual_zettel_id != expected_zettel_id:
        issues.append("frontmatter_identity_mismatch")
    if (
        expected_archive_id is not None
        and frontmatter.get("archive_id") != expected_archive_id
    ):
        issues.append("frontmatter_archive_identity_mismatch")
    if frontmatter.get("status") != expected_status:
        issues.append("frontmatter_status_mismatch")
    if boundary.get("state") != "readable":
        issues.append("frontmatter_status_mismatch")
    if validate_schema(frontmatter, "zettel-frontmatter.schema.json"):
        issues.append("frontmatter_schema_invalid")
    if issues:
        return blocked(*issues)
    return {
        "ok": True,
        "issue_codes": [],
        "bytes": raw_bytes,
        "frontmatter": frontmatter,
        "body": str(boundary.get("body") or ""),
    }


def require_existing_archive_root(archive_root: Path | str) -> Path:
    root = Path(archive_root).resolve()
    if not root.is_dir():
        raise ArchiveServiceError(f"Archive root does not exist or is not a directory: {root}")
    return root


def archive_internal_path(archive_root: Path, relative_path: str) -> Path:
    try:
        return resolve_archive_relative_path(archive_root, relative_path)
    except ArchivePathError as exc:
        raise ArchiveServiceError(f"Archive path is unsafe: {relative_path} ({exc})") from exc


def read_archive_text(archive_root: Path, relative_path: str) -> str:
    path = archive_internal_path(archive_root, relative_path)
    if not path.is_file():
        raise ArchiveServiceError(f"Archive file is missing: {relative_path}")
    return path.read_text(encoding="utf-8")


def list_zettels(archive_root: Path | str, status: str = "canonical", limit: int = 100) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    if status not in {"all", "draft", "canonical"}:
        raise ArchiveServiceError("status must be one of: all, draft, canonical")
    limit = max(1, min(int(limit), 500))

    if status == "all":
        folders = [("zettels", "canonical"), ("inbox", "draft")]
    elif status == "draft":
        folders = [("inbox", "draft")]
    else:
        folders = [("zettels", "canonical")]

    zettels: list[dict[str, Any]] = []
    for folder, expected_status in folders:
        folder_root = root / folder
        if not folder_root.is_dir():
            continue
        for path in safe_archive_glob(folder_root, "*.md", root, recursive=True):
            zettels.append(zettel_summary(path, root, expected_status))
            if len(zettels) >= limit:
                break
        if len(zettels) >= limit:
            break

    return {"zettels": zettels, "count": len(zettels)}


def archive_status_item(
    path: Path,
    archive_root: Path,
    frontmatter: dict[str, Any],
    *,
    folder: str,
    expected_status: str,
) -> dict[str, Any]:
    raw_status = str(frontmatter.get("status") or expected_status)
    status = raw_status if raw_status in {"draft", "canonical", "archived", "redacted"} else "other"
    raw_document_type = zettel_quality_scalar(frontmatter, "document_type")
    document_type = raw_document_type if raw_document_type in ZET_QUALITY_DOCUMENT_TYPES else None
    raw_audience = zettel_quality_scalar(frontmatter, "audience")
    audience = raw_audience if raw_audience in ZET_QUALITY_AUDIENCES else None
    return {
        "path": archive_relative_path(path, archive_root),
        "zettel_id": frontmatter.get("id") if isinstance(frontmatter.get("id"), str) else path.stem,
        "folder": folder,
        "status": status,
        "title_present": bool(str(frontmatter.get("title") or "").strip()),
        "document_type": document_type,
        "document_type_present": bool(raw_document_type),
        "audience": audience,
        "audience_present": bool(raw_audience),
        "redacted": raw_status == "redacted",
    }


def append_limited(items: list[dict[str, Any]], item: dict[str, Any], max_items: int) -> None:
    if len(items) < max_items:
        items.append(item)


def zettel_mint_receipt_gap(root: Path, frontmatter: dict[str, Any]) -> str | None:
    mint = frontmatter.get("mint") if isinstance(frontmatter.get("mint"), dict) else {}
    receipt_ref = mint.get("receipt_path")
    if not receipt_ref:
        return None
    try:
        receipt_path = resolve_archive_relative_path(root, str(receipt_ref))
    except ArchivePathError:
        return "mint_receipt_path_unsafe"
    if not receipt_path.is_file():
        return "mint_receipt_missing"
    return None


def archive_status_board(
    archive_root: Path | str,
    *,
    dry_run: bool = True,
    max_items: int = 20,
    include_quality: bool = False,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    max_items = max(1, min(int(max_items), 100))
    blockers: list[str] = []
    if not dry_run:
        blockers.append("status-board is read-only and requires --dry-run.")

    counts: dict[str, int] = {
        "canonical": 0,
        "draft": 0,
        "archived": 0,
        "redacted": 0,
        "unreadable_zettel": 0,
        "other_status": 0,
        "inbox_draft": 0,
        "canonical_folder": 0,
        "minted_draft_pending_retire": 0,
        "active_draft": 0,
        "canonical_lifecycle_metadata_missing": 0,
        "mint_receipt_gap": 0,
        "document_type_missing": 0,
        "audience_missing": 0,
        "source_metadata_gap": 0,
        "derived_artifact_gap": 0,
        "quality_blocker_candidate": 0,
        "quality_warning_candidate": 0,
        "first_read_explicit": 0,
        "first_read_compatibility_only": 0,
        "first_read_missing": 0,
        "first_read_unreadable": 0,
        "first_read_redacted": 0,
        "first_read_attention": 0,
    }
    boards: dict[str, list[dict[str, Any]]] = {
        "canonical": [],
        "active_drafts": [],
        "minted_drafts_pending_retire": [],
        "canonical_lifecycle_metadata_missing": [],
        "mint_receipt_gaps": [],
        "document_type_missing": [],
        "audience_missing": [],
        "source_metadata_gaps": [],
        "derived_artifact_gaps": [],
        "quality_attention": [],
        "first_read_attention": [],
    }

    for folder, expected_status in [("zettels", "canonical"), ("inbox", "draft")]:
        folder_root = root / folder
        if not folder_root.is_dir():
            continue
        for path in safe_archive_glob(folder_root, "*.md", root, recursive=True):
            boundary = read_zettel_content_boundary(path)
            if boundary["state"] == "blocked":
                counts["unreadable_zettel"] += 1
                counts["other_status"] += 1
                item = {
                    "path": archive_relative_path(path, root),
                    "zettel_id": None,
                    "folder": folder,
                    "status": ZETTEL_QUARANTINED_STATUS,
                    "title_present": False,
                    "document_type": None,
                    "document_type_present": False,
                    "audience": None,
                    "audience_present": False,
                    "redacted": False,
                    "frontmatter_readable": False,
                    "content_issue_code": boundary["reason"],
                    "abstract_status": "frontmatter_unreadable",
                }
                if folder == "zettels":
                    counts["canonical_folder"] += 1
                    counts["first_read_unreadable"] += 1
                    counts["first_read_attention"] += 1
                    append_limited(boards["canonical"], item, max_items)
                    append_limited(boards["first_read_attention"], item, max_items)
                else:
                    counts["inbox_draft"] += 1
                continue
            frontmatter = boundary["frontmatter"]
            body = boundary["body"]
            item = archive_status_item(path, root, frontmatter, folder=folder, expected_status=expected_status)
            status = item["status"]
            if status in {"canonical", "draft", "archived", "redacted"}:
                counts[status] += 1
            else:
                counts["other_status"] += 1

            if boundary["state"] == "redacted":
                item["abstract_status"] = "redacted"
                if folder == "zettels":
                    counts["canonical_folder"] += 1
                    counts["first_read_redacted"] += 1
                    append_limited(boards["canonical"], item, max_items)
                else:
                    counts["inbox_draft"] += 1
                # The small existence envelope above is intentional. Do not
                # derive lifecycle, quality, link, or completeness findings
                # from redacted content.
                continue

            if folder == "zettels":
                counts["canonical_folder"] += 1
                if item["redacted"]:
                    abstract_status = "redacted"
                elif not frontmatter:
                    abstract_status = "frontmatter_unreadable"
                else:
                    _abstract, _source, abstract_status, _truncated = zet_catalog_abstract(
                        frontmatter,
                        [],
                    )
                item["abstract_status"] = abstract_status
                abstract_count_key = {
                    "explicit": "first_read_explicit",
                    "compatibility_field": "first_read_compatibility_only",
                    "missing": "first_read_missing",
                    "frontmatter_unreadable": "first_read_unreadable",
                    "redacted": "first_read_redacted",
                }.get(abstract_status, "first_read_missing")
                counts[abstract_count_key] += 1
                if abstract_status not in {"explicit", "redacted"}:
                    counts["first_read_attention"] += 1
                    append_limited(
                        boards["first_read_attention"],
                        {
                            **item,
                            "next_command": (
                                "archive first-read-readiness <archive-root> "
                                "--dry-run --progress --format json"
                            ),
                        },
                        max_items,
                    )
                append_limited(boards["canonical"], item, max_items)
                if "mint" not in frontmatter and "promotion" not in frontmatter:
                    counts["canonical_lifecycle_metadata_missing"] += 1
                    append_limited(boards["canonical_lifecycle_metadata_missing"], item, max_items)
                gap = zettel_mint_receipt_gap(root, frontmatter)
                if gap:
                    counts["mint_receipt_gap"] += 1
                    append_limited(boards["mint_receipt_gaps"], {**item, "gap_code": gap}, max_items)
            elif folder == "inbox":
                counts["inbox_draft"] += 1
                twin = is_minted_inbox_draft_twin(root, path)
                if twin:
                    counts["minted_draft_pending_retire"] += 1
                    append_limited(
                        boards["minted_drafts_pending_retire"],
                        {
                            **item,
                            "canonical_path": twin.get("canonical_path"),
                            "retire_receipt_path": twin.get("retire_receipt_path"),
                            "next_command": f"archive retire-draft <archive-root> --path {item['path']} --dry-run",
                        },
                        max_items,
                    )
                else:
                    counts["active_draft"] += 1
                    append_limited(boards["active_drafts"], item, max_items)

            if not item["document_type_present"]:
                counts["document_type_missing"] += 1
                append_limited(boards["document_type_missing"], item, max_items)
            if not item["audience_present"]:
                counts["audience_missing"] += 1
                append_limited(boards["audience_missing"], item, max_items)

            source_summary = source_ref_metadata_summary(frontmatter)
            if source_summary.get("missing_metadata_count") or source_summary.get("rights_review_missing_count"):
                counts["source_metadata_gap"] += 1
                append_limited(boards["source_metadata_gaps"], {**item, "source_metadata": source_summary}, max_items)

            artifact_summary = derived_artifact_summary(frontmatter)
            if artifact_summary.get("missing_source_link_count") or artifact_summary.get("missing_sync_status_count"):
                counts["derived_artifact_gap"] += 1
                append_limited(boards["derived_artifact_gaps"], {**item, "derived_artifacts": artifact_summary}, max_items)

            if include_quality:
                quality = zettel_quality_assessment(root, path, frontmatter, body)
                blocker_count = int(quality.get("blocker_count") or 0)
                warning_count = int(quality.get("warning_count") or 0)
                if blocker_count:
                    counts["quality_blocker_candidate"] += 1
                if warning_count:
                    counts["quality_warning_candidate"] += 1
                if blocker_count or warning_count:
                    append_limited(
                        boards["quality_attention"],
                        {
                            **item,
                            "quality_state": quality.get("quality_state"),
                            "blocker_count": blocker_count,
                            "warning_count": warning_count,
                            "issue_count": int(quality.get("issue_count") or 0),
                            "next_command": f"archive zet-quality-check <archive-root> --path {item['path']} --dry-run --format json",
                        },
                        max_items,
                    )

    next_actions: list[str] = []
    if counts["minted_draft_pending_retire"]:
        next_actions.append("Review minted inbox drafts and close them with retire-draft after dry-run verification.")
    if counts["document_type_missing"] or counts["audience_missing"]:
        next_actions.append("Add document_type and audience to zets that will feed external artifacts.")
    if counts["source_metadata_gap"]:
        next_actions.append("Review source_refs with missing acquisition, verification, or rights metadata.")
    if counts["derived_artifact_gap"]:
        next_actions.append("Add source links and sync status to derived_artifacts before treating reports as current.")
    if counts["first_read_attention"]:
        next_actions.append(
            "Run first-read-readiness before claiming that every canonical zet has an explicit compact first read."
        )
    if not include_quality:
        next_actions.append("Rerun status-board with --include-quality when you want body-inspecting quality counts.")

    return {
        "ok": not blockers,
        "dry_run": True,
        "lifecycle_action": "archive_status_board",
        "archive_id": read_archive_id(root),
        "counts": counts,
        "boards": boards,
        "include_quality": include_quality,
        "max_items": max_items,
        "blockers": blockers,
        "warnings": [],
        "next_actions": next_actions,
        "would_change": [],
        "privacy_guards": {
            "body_text_echoed": False,
            "abstract_text_echoed": False,
            "title_values_echoed": False,
            "unrecognized_frontmatter_values_echoed": False,
            "source_ref_values_echoed": False,
            "provider_urls_echoed": False,
            "local_absolute_paths_echoed": False,
            "writes": False,
        },
    }


def comparable_datetime(value: datetime | None) -> datetime | None:
    if value is None:
        return None
    if value.tzinfo is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def public_timestamp(value: datetime | None) -> str | None:
    value = comparable_datetime(value)
    if value is None:
        return None
    return value.replace(microsecond=0).isoformat().replace("+00:00", "Z")


def zettel_frontmatter_modified_time(path: Path, frontmatter: dict[str, Any]) -> datetime | None:
    for key in ["updated_at", "modified_at", "created_at"]:
        parsed = parse_receipt_time(frontmatter.get(key))
        if parsed is not None:
            return comparable_datetime(parsed)
    try:
        return datetime.fromtimestamp(path.stat().st_mtime, timezone.utc)
    except OSError:
        return None


def derived_artifact_sync_time(artifact: dict[str, Any]) -> datetime | None:
    for key in ["last_synced_at", "synced_at", "updated_at"]:
        parsed = parse_receipt_time(artifact.get(key))
        if parsed is not None:
            return comparable_datetime(parsed)
    return None


def normalize_derived_source_zettel_ref(ref: Any) -> dict[str, str] | None:
    if isinstance(ref, str) and ref.strip():
        value = ref.strip()
        if value.startswith(VALID_ZETTEL_FOLDERS):
            return {"relative_path": value}
        return {"zettel_id": value}
    if isinstance(ref, dict):
        for key in ["path", "relative_path", "zettel_path"]:
            value = ref.get(key)
            if isinstance(value, str) and value.strip():
                return {"relative_path": value.strip()}
        for key in ["zettel_id", "id"]:
            value = ref.get(key)
            if isinstance(value, str) and value.strip():
                return {"zettel_id": value.strip()}
    return None


def derived_artifact_source_zettel_refs(artifact: dict[str, Any]) -> list[dict[str, str]]:
    raw = artifact.get("source_zettels")
    if raw is None:
        raw = artifact.get("source_zettel")
    items = raw if isinstance(raw, list) else [raw] if raw is not None else []
    refs: list[dict[str, str]] = []
    for item in items:
        normalized = normalize_derived_source_zettel_ref(item)
        if normalized is not None:
            refs.append(normalized)
    return refs


def derived_artifact_staleness_item(
    path: Path,
    archive_root: Path,
    frontmatter: dict[str, Any],
    artifact: dict[str, Any],
    artifact_index: int,
    *,
    state: str,
    source_paths: list[str] | None = None,
    unresolved_source_count: int = 0,
    newer_source_count: int = 0,
    last_synced_at: datetime | None = None,
    newest_source_modified_at: datetime | None = None,
) -> dict[str, Any]:
    return {
        "path": archive_relative_path(path, archive_root),
        "zettel_id": frontmatter.get("id") if isinstance(frontmatter.get("id"), str) else path.stem,
        "artifact_index": artifact_index,
        "artifact_ref_present": bool(artifact.get("artifact_ref")),
        "sync_status_present": bool(artifact.get("sync_status")),
        "state": state,
        "last_synced_at": public_timestamp(last_synced_at),
        "newest_source_modified_at": public_timestamp(newest_source_modified_at),
        "newer_source_count": newer_source_count,
        "source_paths": source_paths or [],
        "unresolved_source_count": unresolved_source_count,
    }


def derived_artifact_staleness_check(
    archive_root: Path | str,
    *,
    dry_run: bool = True,
    max_items: int = 20,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    max_items = max(1, min(int(max_items), 100))
    blockers: list[str] = []
    if not dry_run:
        blockers.append("derived-artifact-staleness is read-only and requires --dry-run.")

    counts: dict[str, int] = {
        "zets_checked": 0,
        "zets_with_derived_artifacts": 0,
        "artifact_count": 0,
        "current_artifact": 0,
        "stale_artifact": 0,
        "unknown_sync_time": 0,
        "missing_source_zettels": 0,
        "unresolved_source_zettels": 0,
        "unreadable_zettels": 0,
        "redacted_zettels_excluded": 0,
    }
    boards: dict[str, list[dict[str, Any]]] = {
        "stale_artifacts": [],
        "unknown_sync_time": [],
        "missing_source_zettels": [],
        "unresolved_source_zettels": [],
    }

    zettel_frontmatter_by_path: dict[Path, dict[str, Any]] = {}
    zettel_path_index: dict[str, Path] = {}
    for candidate in iter_zettel_paths(root):
        inspection = inspect_zettel_frontmatter_boundary(candidate)
        if not inspection["metadata_readable"]:
            counts["unreadable_zettels"] += 1
            continue
        frontmatter = inspection["frontmatter"]
        if frontmatter.get("status") == "redacted":
            counts["redacted_zettels_excluded"] += 1
            continue
        zettel_frontmatter_by_path[candidate] = frontmatter
        zettel_id = str(frontmatter.get("id") or "").strip()
        if zettel_id and zettel_id not in zettel_path_index:
            zettel_path_index[zettel_id] = candidate

    for path, frontmatter in zettel_frontmatter_by_path.items():
        counts["zets_checked"] += 1
        if not frontmatter:
            continue
        frontmatter = json_safe(frontmatter)
        raw_artifacts = frontmatter.get("derived_artifacts")
        if raw_artifacts is None:
            raw_artifacts = frontmatter.get("external_artifacts")
        if raw_artifacts is None:
            raw_artifacts = frontmatter.get("projections")
        if not isinstance(raw_artifacts, list) or not raw_artifacts:
            continue
        counts["zets_with_derived_artifacts"] += 1

        for artifact_index, artifact in enumerate(raw_artifacts):
            if not isinstance(artifact, dict):
                continue
            counts["artifact_count"] += 1
            refs = derived_artifact_source_zettel_refs(artifact)
            if not refs:
                counts["missing_source_zettels"] += 1
                append_limited(
                    boards["missing_source_zettels"],
                    derived_artifact_staleness_item(
                        path,
                        root,
                        frontmatter,
                        artifact,
                        artifact_index,
                        state="missing_source_zettels",
                    ),
                    max_items,
                )
                continue

            resolved_sources: list[tuple[str, datetime | None]] = []
            unresolved_source_count = 0
            for ref in refs:
                try:
                    source_path = resolve_zettel_path(
                        root,
                        zettel_id=ref.get("zettel_id"),
                        relative_path=ref.get("relative_path"),
                        zettel_path_index=zettel_path_index,
                    )
                except ArchiveServiceError:
                    unresolved_source_count += 1
                    continue
                source_inspection = inspect_zettel_frontmatter_boundary(source_path)
                if (
                    not source_inspection["metadata_readable"]
                    or source_inspection["frontmatter"].get("status")
                    not in ZETTEL_QUERYABLE_STATUSES
                ):
                    unresolved_source_count += 1
                    continue
                source_frontmatter = source_inspection["frontmatter"]
                resolved_sources.append(
                    (
                        archive_relative_path(source_path, root),
                        zettel_frontmatter_modified_time(source_path, source_frontmatter),
                    )
                )

            if unresolved_source_count:
                counts["unresolved_source_zettels"] += 1
                append_limited(
                    boards["unresolved_source_zettels"],
                    derived_artifact_staleness_item(
                        path,
                        root,
                        frontmatter,
                        artifact,
                        artifact_index,
                        state="unresolved_source_zettels",
                        source_paths=[source for source, _time in resolved_sources],
                        unresolved_source_count=unresolved_source_count,
                    ),
                    max_items,
                )
                continue

            last_synced_at = derived_artifact_sync_time(artifact)
            source_times = [item_time for _source, item_time in resolved_sources if item_time is not None]
            newest_source_time = max(source_times) if source_times else None
            if last_synced_at is None:
                counts["unknown_sync_time"] += 1
                append_limited(
                    boards["unknown_sync_time"],
                    derived_artifact_staleness_item(
                        path,
                        root,
                        frontmatter,
                        artifact,
                        artifact_index,
                        state="unknown_sync_time",
                        source_paths=[source for source, _time in resolved_sources],
                        newest_source_modified_at=newest_source_time,
                    ),
                    max_items,
                )
                continue

            newer_source_count = sum(1 for _source, item_time in resolved_sources if item_time and item_time > last_synced_at)
            if newer_source_count:
                counts["stale_artifact"] += 1
                append_limited(
                    boards["stale_artifacts"],
                    derived_artifact_staleness_item(
                        path,
                        root,
                        frontmatter,
                        artifact,
                        artifact_index,
                        state="source_newer_than_artifact_sync",
                        source_paths=[source for source, _time in resolved_sources],
                        newer_source_count=newer_source_count,
                        last_synced_at=last_synced_at,
                        newest_source_modified_at=newest_source_time,
                    ),
                    max_items,
                )
            else:
                counts["current_artifact"] += 1

    findings = (
        counts["stale_artifact"]
        + counts["unknown_sync_time"]
        + counts["missing_source_zettels"]
        + counts["unresolved_source_zettels"]
    )
    next_actions: list[str] = []
    if counts["stale_artifact"]:
        next_actions.append("Review stale derived artifacts and refresh the external report from the current source zets.")
    if counts["unknown_sync_time"]:
        next_actions.append("Add last_synced_at to derived_artifacts after a reviewed report sync.")
    if counts["missing_source_zettels"]:
        next_actions.append("Add source_zettels to derived_artifacts before relying on freshness checks.")
    if counts["unresolved_source_zettels"]:
        next_actions.append("Fix derived_artifacts source_zettels that do not resolve to archive zets.")

    return {
        "ok": not blockers and findings == 0,
        "dry_run": True,
        "lifecycle_action": "derived_artifact_staleness_check",
        "archive_id": read_archive_id(root),
        "counts": counts,
        "boards": boards,
        "max_items": max_items,
        "blockers": blockers,
        "warnings": [],
        "next_actions": next_actions,
        "would_change": [],
        "privacy_guards": {
            "artifact_ref_values_echoed": False,
            "zettel_body_text_echoed": False,
            "zettel_titles_echoed": False,
            "provider_urls_echoed": False,
            "local_absolute_paths_echoed": False,
            "external_artifact_body_read": False,
            "writes": False,
        },
    }


def safe_operator_feedback_id(value: str | None) -> str | None:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if not OPERATOR_FEEDBACK_ID_RE.match(text):
        return None
    if contains_forbidden_location_reference(text) or source_intake_has_provider_url(text) or source_intake_secret_like(text):
        return None
    return text


def safe_operator_feedback_scalar(value: str | None, *, max_length: int = 240) -> str | None:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if not text or len(text) > max_length:
        return None
    if not safe_source_intake_plan_scalar(text):
        return None
    return text


OPERATOR_FEEDBACK_TITLE_LINE_BREAKS = ("\r", "\n", "\x85", "\u2028", "\u2029")
OPERATOR_FEEDBACK_TITLE_TOKEN_RE = re.compile(
    r"(?i)(?:\bgithub_pat_[A-Za-z0-9_]{20,}\b|\bsk-[A-Za-z0-9_-]{8,}\b"
    r"|\b(?:secret|ntn)_[A-Za-z0-9_-]{12,}\b)"
)


def normalize_operator_feedback_title(
    value: str | None,
    *,
    max_length: int = 240,
) -> tuple[str | None, str | None, bool]:
    """Return a safe title, a value-free rejection reason, and normalization state.

    Feedback titles are descriptive prose, so words such as ``credential`` and
    ``token`` are not secrets by themselves.  The shared source-intake scalar
    guard intentionally rejects those words and is therefore too broad for this
    field.  This field-specific boundary rejects actual assignment/token shapes,
    provider locators, email-like values, local paths, NULs, and line breaks.
    It never returns the rejected value or a matched substring.
    """

    if not isinstance(value, str):
        return None, "not_string", False
    if "\x00" in value:
        return None, "nul", False
    if any(marker in value for marker in OPERATOR_FEEDBACK_TITLE_LINE_BREAKS):
        return None, "multiline", False

    # Normalize only horizontal presentation whitespace.  This keeps the title
    # readable and deterministic without changing its words or punctuation.
    normalized = re.sub(r"[\t\f\v ]+", " ", value).strip()
    if not normalized:
        return None, "empty", normalized != value
    if len(normalized) > max_length:
        return None, "too_long", normalized != value
    if "@" in normalized:
        return None, "email_or_at_sign", normalized != value
    if source_intake_has_provider_url(normalized):
        return None, "provider_url", normalized != value
    if contains_forbidden_location_reference(normalized):
        return None, "local_path", normalized != value
    if DRAFT_SECRET_VALUE_RE.search(normalized) or OPERATOR_FEEDBACK_TITLE_TOKEN_RE.search(normalized):
        return None, "secret_value_shape", normalized != value
    return normalized, None, normalized != value


def operator_feedback_record_relative_path(feedback_id: str) -> str:
    return f"{OPERATOR_FEEDBACK_DIR}/{feedback_id}.yml"


def operator_feedback_receipt_relative_path(
    feedback_id: str,
    timestamp: str,
    record_sha256: str | None = None,
) -> str:
    compact = re.sub(r"[^0-9TZ]", "", timestamp)
    digest_suffix = f".{record_sha256[:16]}" if record_sha256 else ""
    return f"{OPERATOR_FEEDBACK_RECEIPTS_DIR}/{feedback_id}.{compact}{digest_suffix}.json"


class _OperatorFeedbackRecordLock:
    """Serialize cooperating feedback writers without storing operator content."""

    def __init__(self, root: Path, feedback_id: str) -> None:
        lock_dir = archive_internal_path(
            root,
            f"{OPERATOR_FEEDBACK_RECEIPTS_DIR}/.locks",
        )
        lock_dir.mkdir(parents=True, exist_ok=True)
        lock_name = hashlib.sha256(feedback_id.encode("utf-8")).hexdigest()
        self._path = lock_dir / f"{lock_name}.lock"
        self._handle: Any = None

    def __enter__(self) -> "_OperatorFeedbackRecordLock":
        self._handle = self._path.open("a+b")
        self._handle.seek(0, os.SEEK_END)
        if self._handle.tell() == 0:
            self._handle.write(b"\0")
            self._handle.flush()
            os.fsync(self._handle.fileno())
        self._handle.seek(0)
        if os.name == "nt":
            import msvcrt

            while True:
                try:
                    msvcrt.locking(self._handle.fileno(), msvcrt.LK_LOCK, 1)
                    break
                except OSError:
                    continue
        else:
            import fcntl

            fcntl.flock(self._handle.fileno(), fcntl.LOCK_EX)
        return self

    def __exit__(self, *exc_info: Any) -> bool:
        try:
            self._handle.seek(0)
            if os.name == "nt":
                import msvcrt

                msvcrt.locking(self._handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl

                fcntl.flock(self._handle.fileno(), fcntl.LOCK_UN)
        finally:
            self._handle.close()
        return False


def _write_bytes_create_if_absent(path: Path, value: bytes) -> None:
    """Publish complete bytes atomically and never replace an existing file."""

    expected_digest = hashlib.sha256(value).hexdigest()

    def verify_exact_regular_file(candidate: Path) -> tuple[int, int]:
        before = os.lstat(candidate)
        reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        if (
            not stat.S_ISREG(before.st_mode)
            or stat.S_ISLNK(before.st_mode)
            or (
                reparse_flag
                and getattr(before, "st_file_attributes", 0) & reparse_flag
            )
            or before.st_size != len(value)
        ):
            raise OSError("create_only_publication_not_exact_regular_file")
        digest = hashlib.sha256()
        with candidate.open("rb") as handle:
            opened = os.fstat(handle.fileno())
            if (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino):
                raise OSError("create_only_publication_identity_changed")
            while True:
                chunk = handle.read(1024 * 1024)
                if not chunk:
                    break
                digest.update(chunk)
            opened_after = os.fstat(handle.fileno())
        after = os.lstat(candidate)
        identity = (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
        if identity != (
            opened.st_dev,
            opened.st_ino,
            opened.st_size,
            opened.st_mtime_ns,
        ) or identity != (
            opened_after.st_dev,
            opened_after.st_ino,
            opened_after.st_size,
            opened_after.st_mtime_ns,
        ) or identity != (
            after.st_dev,
            after.st_ino,
            after.st_size,
            after.st_mtime_ns,
        ):
            raise OSError("create_only_publication_identity_changed")
        if digest.hexdigest() != expected_digest:
            raise OSError("create_only_publication_verification_failed")
        return before.st_dev, before.st_ino

    path.parent.mkdir(parents=True, exist_ok=True)
    temporary_path: Path | None = None
    descriptor: int | None = None
    try:
        for _ in range(8):
            candidate = path.with_name(f".{path.name}.{secrets.token_hex(8)}.tmp")
            try:
                descriptor = os.open(
                    candidate,
                    os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                    0o600,
                )
                temporary_path = candidate
                break
            except FileExistsError:
                continue
        if temporary_path is None or descriptor is None:
            raise OSError("could_not_reserve_create_temporary_file")
        with os.fdopen(descriptor, "wb") as handle:
            descriptor = None
            view = memoryview(value)
            offset = 0
            while offset < len(view):
                written = handle.write(view[offset:])
                if written is None or written <= 0:
                    raise OSError("create_only_temporary_write_incomplete")
                offset += written
            handle.flush()
            os.fsync(handle.fileno())
        temporary_identity = verify_exact_regular_file(temporary_path)
        os.link(temporary_path, path)
        fsync_directory(path.parent)
        if verify_exact_regular_file(path) != temporary_identity:
            raise OSError("create_only_publication_identity_changed")
    finally:
        if descriptor is not None:
            os.close(descriptor)
        if temporary_path is not None:
            temporary_path.unlink(missing_ok=True)


def operator_feedback_runtime_routing() -> dict[str, Any]:
    return {
        "schema": "wom-kit/operator-feedback-runtime-routing/v0.2",
        "canonical_metadata_dir": OPERATOR_FEEDBACK_DIR,
        "canonical_receipt_dir": OPERATOR_FEEDBACK_RECEIPTS_DIR,
        "user_knowledge_objets_are_canonical_feedback_tracker": False,
        "sequence": [
            {
                "step": 1,
                "action": "read_feedback_policy",
                "command": (
                    "archive operator-feedback-plan <archive-root> "
                    "--dry-run --format json"
                ),
                "writes": False,
            },
            {
                "step": 2,
                "action": "inspect_feedback_ledger",
                "command": (
                    "archive operator-feedback-ledger <archive-root> "
                    "--dry-run --format json"
                ),
                "writes": False,
            },
            {
                "step": 3,
                "action": "preview_feedback_body",
                "command": (
                    "archive operator-feedback-compose <archive-root> "
                    "--request profiles/local/operator-feedback/requests/<private>.json "
                    "--dry-run --format json"
                ),
                "writes": False,
            },
            {
                "step": 4,
                "action": "human_review",
                "command": None,
                "required_gate": True,
                "meaning": (
                    "A human reviews the existing ledger, content-free body plan, "
                    "and intended feedback metadata before either approval."
                ),
                "writes": False,
            },
            {
                "step": 5,
                "action": "approve_feedback_body",
                "command": (
                    "archive operator-feedback-compose <archive-root> "
                    "--request profiles/local/operator-feedback/requests/<private>.json "
                    "--expected-plan-sha256 <sha256> --reviewed-by <human-actor> "
                    "--approve --format json"
                ),
                "requires_completed_human_review": True,
                "writes": True,
            },
            {
                "step": 6,
                "action": "preview_feedback_record",
                "command": (
                    "archive operator-feedback-record <archive-root> "
                    "--feedback-id <safe-id> --feedback-ref <safe-ref> "
                    "--status draft --intent create --dry-run --format json"
                ),
                "requires_completed_human_review": True,
                "writes": False,
            },
            {
                "step": 7,
                "action": "approve_feedback_record",
                "command": (
                    "archive operator-feedback-record <archive-root> "
                    "--feedback-id <safe-id> --feedback-ref <safe-ref> "
                    "--status draft --intent create --approve "
                    "--reviewed-by <human-actor> "
                    "--format json"
                ),
                "requires_completed_human_review": True,
                "writes": True,
            },
            {
                "step": 8,
                "action": "verify_feedback_body_binding",
                "command": (
                    "archive operator-feedback-body-check <archive-root> "
                    "--feedback-id <safe-id> --dry-run --format json"
                ),
                "requires_completed_human_review": True,
                "writes": False,
            },
        ],
        "truth_boundaries": {
            "feedback_body_read": False,
            "feedback_body_companion_supported": True,
            "external_submission_performed": False,
            "delivered_status_proves_external_submission": False,
            "delivered_status_proves_human_receipt": False,
            "approval_inferred": False,
        },
    }


def operator_feedback_plan(archive_root: Path | str, *, dry_run: bool = True) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    if not dry_run:
        blockers.append("operator-feedback-plan is read-only and requires --dry-run.")
    return {
        "ok": not blockers,
        "state": "ready" if not blockers else "blocked",
        "dry_run": True,
        "lifecycle_action": "operator_feedback_plan",
        "archive_id": read_archive_id(root),
        "summary": {
            "feedback_dir": OPERATOR_FEEDBACK_DIR,
            "receipt_dir": OPERATOR_FEEDBACK_RECEIPTS_DIR,
            "statuses": list(OPERATOR_FEEDBACK_STATUSES),
            "body_storage": "managed_by_companion_commands_not_this_plan",
            "external_submission": "future_boundary",
        },
        "data": {
            "record_schema": OPERATOR_FEEDBACK_SCHEMA,
            "receipt_schema": OPERATOR_FEEDBACK_RECEIPT_SCHEMA,
            "recommended_record_command": (
                "archive operator-feedback-record <archive-root> --feedback-id <safe-id> "
                "--feedback-ref <safe-ref> --status draft --intent create "
                "--dry-run --format json"
            ),
            "recommended_body_plan_command": (
                "archive operator-feedback-compose <archive-root> "
                "--request profiles/local/operator-feedback/requests/<private>.json "
                "--dry-run --format json"
            ),
            "recommended_body_check_command": (
                "archive operator-feedback-body-check <archive-root> "
                "--feedback-id <safe-id> --dry-run --format json"
            ),
            "recommended_managed_body_first_sequence": [
                "preview and human-review operator-feedback-compose",
                "approve the unchanged compose plan so the body and receipt exist",
                "create metadata with the exact feedback-body-sha256 digest",
                "run operator-feedback-body-check after creation to verify the binding",
            ],
            "wrong_draft_withdrawal": {
                "status": "archived",
                "intent": "update",
                "requires_fresh_current_record_sha256": True,
                "preserves_feedback_ref": True,
                "corrected_record_requires_new_feedback_id": True,
            },
            "lifecycle": [
                {"status": "draft", "meaning": "feedback exists but has not been sent or recorded as delivered"},
                {"status": "delivered", "meaning": "feedback was delivered to the project team or relay channel"},
                {"status": "acknowledged", "meaning": "the project team confirmed receipt"},
                {"status": "resolved", "meaning": "a release or decision closed the feedback"},
                {"status": "archived", "meaning": "feedback is kept for history and no active action remains"},
            ],
            "storage_boundary": [
                "operator feedback metadata belongs under ops/feedback/",
                "user knowledge objets should not be used as the canonical lifecycle tracker for tool feedback",
                "this command does not copy, move, read, or submit feedback body files",
            ],
            "runtime_routing": operator_feedback_runtime_routing(),
        },
        "blockers": blockers,
        "warnings": [],
        "would_change": [],
        "privacy_guards": {
            "feedback_body_read": False,
            "feedback_ref_value_echoed": False,
            "title_value_echoed": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "writes": False,
        },
    }


def operator_feedback_record(
    archive_root: Path | str,
    *,
    feedback_id: str | None,
    feedback_ref: str | None,
    status: str,
    intent: str = "create",
    expected_record_sha256: str | None = None,
    title: str | None = None,
    related_release: list[str] | None = None,
    resolved_in: str | None = None,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    blocker_codes: list[str] = []
    warnings: list[str] = []
    warning_codes: list[str] = []
    feedback_body_reference_kind = "unclassified"
    feedback_body_preflight_performed = False
    feedback_body_authority_verified = False
    feedback_body_receipt_path: str | None = None
    feedback_body_receipt_sha256: str | None = None

    def block(code: str, message: str) -> None:
        if code not in blocker_codes:
            blocker_codes.append(code)
        if message not in blockers:
            blockers.append(message)

    def warn(code: str, message: str) -> None:
        if code not in warning_codes:
            warning_codes.append(code)
        if message not in warnings:
            warnings.append(message)

    if dry_run == approve:
        block(
            "operator_feedback_mode_invalid",
            "operator-feedback-record requires exactly one of --dry-run or --approve.",
        )

    safe_id = safe_operator_feedback_id(feedback_id)
    if safe_id is None:
        block(
            "feedback_id_invalid",
            "feedback_id must be a safe id using letters, numbers, dot, underscore, or hyphen.",
        )

    safe_ref = safe_operator_feedback_scalar(feedback_ref, max_length=240)
    if safe_ref is None:
        block(
            "feedback_ref_invalid",
            "feedback_ref must be a safe non-secret ref, not a URL, email, token, or local path.",
        )

    normalized_status = (status or "").strip().lower()
    if normalized_status not in OPERATOR_FEEDBACK_STATUSES:
        block(
            "feedback_status_invalid",
            "status must be one of: " + ", ".join(OPERATOR_FEEDBACK_STATUSES) + ".",
        )

    normalized_intent = (intent or "").strip().lower()
    if normalized_intent not in OPERATOR_FEEDBACK_RECORD_INTENTS:
        block(
            "feedback_record_intent_invalid",
            "intent must be one of: " + ", ".join(OPERATOR_FEEDBACK_RECORD_INTENTS) + ".",
        )

    expected_digest = (
        expected_record_sha256.strip().lower()
        if isinstance(expected_record_sha256, str)
        else None
    )
    if expected_digest and not re.fullmatch(r"[0-9a-f]{64}", expected_digest):
        block(
            "expected_record_sha256_invalid",
            "expected_record_sha256 must be exactly 64 lowercase hexadecimal characters.",
        )
    if approve and normalized_intent == "update" and not expected_digest:
        block(
            "expected_record_sha256_required",
            "update approval requires --expected-record-sha256 from a fresh dry-run.",
        )

    safe_title: str | None = None
    title_normalized = False
    if title is not None:
        safe_title, title_rejection, title_normalized = normalize_operator_feedback_title(
            title,
            max_length=240,
        )
        if title_rejection is not None:
            block(
                f"feedback_title_{title_rejection}",
                "title must be one line of descriptive text without a secret value, provider URL, email-like value, or local path.",
            )

    releases: list[str] = []
    for item in related_release or []:
        safe_release = safe_operator_feedback_scalar(item, max_length=80)
        if safe_release is None:
            block(
                "related_release_invalid",
                "related_release values must be safe non-secret labels.",
            )
        elif safe_release not in releases:
            releases.append(safe_release)

    safe_resolved_in = safe_operator_feedback_scalar(resolved_in, max_length=80) if resolved_in else None
    if resolved_in and safe_resolved_in is None:
        block(
            "resolved_in_invalid",
            "resolved_in must be a safe non-secret release label.",
        )
    if normalized_status == "resolved" and not safe_resolved_in:
        block("resolved_in_required", "resolved status requires --resolved-in.")

    reviewer = safe_project_intake_actor_id(reviewed_by)
    if approve and reviewer is None:
        block(
            "reviewer_required",
            "--approve requires a safe --reviewed-by actor id.",
        )
    if reviewed_by and reviewer is None:
        block(
            "reviewer_invalid",
            "reviewed_by must be a safe non-secret actor id.",
        )

    now = datetime.now(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")
    record_relative = operator_feedback_record_relative_path(safe_id or "invalid-feedback-id")
    target_path = archive_internal_path(root, record_relative)
    current_record_sha256: str | None = None
    current_record: dict[str, Any] | None = None

    def draft_ref_rebind_requested() -> bool:
        return bool(
            normalized_intent == "update"
            and isinstance(current_record, dict)
            and current_record.get("status") == "draft"
            and normalized_status == "draft"
            and current_record.get("feedback_ref") != safe_ref
        )

    def inspect_feedback_body_authority() -> None:
        nonlocal feedback_body_reference_kind
        nonlocal feedback_body_preflight_performed
        nonlocal feedback_body_authority_verified
        nonlocal feedback_body_receipt_path
        nonlocal feedback_body_receipt_sha256

        if safe_id is None or safe_ref is None:
            return
        if normalized_intent != "create" and not draft_ref_rebind_requested():
            return
        if not safe_ref.startswith("feedback-body-sha256:"):
            feedback_body_reference_kind = "legacy_or_external"
            warn(
                "feedback_body_reference_unverified",
                (
                    "create uses a legacy or external feedback_ref that is not "
                    "verified by the managed feedback-body receipt; compose and "
                    "approve the body first when this record represents a managed "
                    "WOM feedback letter."
                ),
            )
            return
        if re.fullmatch(r"feedback-body-sha256:[0-9a-f]{64}", safe_ref) is None:
            feedback_body_reference_kind = "managed_body_digest_invalid"
            block(
                "feedback_body_reference_invalid",
                (
                    "a managed feedback-body reference must be "
                    "feedback-body-sha256 followed by exactly 64 lowercase "
                    "hexadecimal characters."
                ),
            )
            return

        feedback_body_reference_kind = "managed_body_digest"
        feedback_body_preflight_performed = True
        try:
            from . import operator_feedback_body

            inspection = operator_feedback_body.check_operator_feedback_body(
                root,
                safe_id,
            )
        except Exception:
            inspection = {}

        def inspection_verifies_managed_body(value: Any) -> bool:
            if not isinstance(value, dict):
                return False
            body_check = (
                value.get("body_check")
                if isinstance(value.get("body_check"), dict)
                else {}
            )
            record_binding = (
                value.get("record_binding")
                if isinstance(value.get("record_binding"), dict)
                else {}
            )
            inspection_blockers = (
                value.get("blockers")
                if isinstance(value.get("blockers"), list)
                else []
            )
            if draft_ref_rebind_requested():
                record_binding_valid_for_preflight = bool(
                    record_binding.get("record_present") is True
                    and record_binding.get("feedback_ref_bound") is False
                    and inspection_blockers
                    == ["feedback_record_binding_mismatch"]
                )
            else:
                record_binding_valid_for_preflight = bool(
                    (
                        record_binding.get("record_present") is False
                        and inspection_blockers
                        == ["feedback_record_binding_missing"]
                    )
                    or (
                        record_binding.get("record_present") is True
                        and record_binding.get("feedback_ref_bound") is True
                        and inspection_blockers == []
                    )
                )
            return bool(
                value.get("feedback_ref") == safe_ref
                and value.get("body_persisted") is True
                and value.get("receipt_persisted") is True
                and body_check.get("structure_valid") is True
                and body_check.get("privacy_valid") is True
                and body_check.get("exact_hash_bound_by_receipt") is True
                and record_binding_valid_for_preflight
            )

        verified = inspection_verifies_managed_body(inspection)
        receipt_relative = inspection.get("proposed_receipt_relative_path")
        if verified and isinstance(receipt_relative, str):
            try:
                receipt_path = archive_internal_path(root, receipt_relative)
                receipt_raw_before, receipt_reason_before = (
                    _bounded_stable_regular_file_read(
                        receipt_path,
                        max_bytes=64 * 1024,
                    )
                )
                confirmation = operator_feedback_body.check_operator_feedback_body(
                    root,
                    safe_id,
                )
                receipt_raw_after, receipt_reason_after = (
                    _bounded_stable_regular_file_read(
                        receipt_path,
                        max_bytes=64 * 1024,
                    )
                )
            except Exception:
                receipt_raw_before = None
                receipt_raw_after = None
                receipt_reason_before = "unavailable"
                receipt_reason_after = "unavailable"
                confirmation = {}
            if (
                receipt_reason_before is None
                and receipt_reason_after is None
                and receipt_raw_before is not None
                and receipt_raw_after is not None
                and receipt_raw_after == receipt_raw_before
                and inspection_verifies_managed_body(confirmation)
                and confirmation.get("proposed_receipt_relative_path")
                == receipt_relative
            ):
                feedback_body_receipt_path = receipt_relative
                feedback_body_receipt_sha256 = hashlib.sha256(
                    receipt_raw_after
                ).hexdigest()
            else:
                verified = False
        feedback_body_authority_verified = verified
        if not verified:
            feedback_body_receipt_path = None
            feedback_body_receipt_sha256 = None
            block(
                "feedback_body_authority_unverified",
                (
                    "the managed feedback body and its approval receipt must be "
                    "present, structurally valid, privacy-checked, and exactly "
                    "digest-bound before the metadata record is created."
                ),
            )

    def inspect_current_record() -> None:
        nonlocal current_record, current_record_sha256
        current_record = None
        current_record_sha256 = None
        if normalized_intent == "create":
            if target_path.exists() or target_path.is_symlink():
                block(
                    "feedback_record_exists",
                    "create intent requires the feedback record to be absent.",
                )
            return
        if not target_path.is_file() or target_path.is_symlink():
            block(
                "feedback_record_missing",
                "update intent requires an existing regular feedback record.",
            )
            return
        try:
            current_bytes = target_path.read_bytes()
            current_record = load_yaml(current_bytes.decode("utf-8"))
        except (OSError, UnicodeDecodeError, yaml.YAMLError):  # type: ignore[union-attr]
            block(
                "feedback_record_unreadable",
                "the existing feedback record could not be safely decoded.",
            )
            return
        if not isinstance(current_record, dict):
            block(
                "feedback_record_unreadable",
                "the existing feedback record must be a YAML mapping.",
            )
            return
        normalized_current = json_safe(current_record)
        if (
            not isinstance(normalized_current, dict)
            or validate_schema(
                normalized_current,
                "operator-feedback.schema.json",
            )
        ):
            block(
                "feedback_record_unreadable",
                "the existing feedback record does not match the public schema.",
            )
            return
        current_record = normalized_current
        if current_record.get("feedback_id") != safe_id:
            block(
                "feedback_record_identity_mismatch",
                "the existing feedback record identity does not match the requested id.",
            )
        if (
            current_record.get("feedback_ref") != safe_ref
            and not draft_ref_rebind_requested()
        ):
            block(
                "feedback_ref_rebind_forbidden",
                (
                    "feedback_ref can change only while both the current and "
                    "requested status are draft, after a managed body revision."
                ),
            )
        current_record_sha256 = hashlib.sha256(current_bytes).hexdigest()
        if approve and expected_digest and current_record_sha256 != expected_digest:
            block(
                "feedback_record_changed",
                "the existing feedback record changed after review; run a fresh dry-run.",
            )

    if safe_id and safe_ref and normalized_intent in OPERATOR_FEEDBACK_RECORD_INTENTS:
        inspect_current_record()
        inspect_feedback_body_authority()

    updating = normalized_intent == "update" and current_record is not None
    record = {
        "schema": OPERATOR_FEEDBACK_SCHEMA,
        "feedback_id": safe_id,
        "feedback_ref": safe_ref,
        "status": normalized_status,
        "title": (
            safe_title
            if title
            else (current_record.get("title") if updating else None)
        ),
        "related_releases": (
            releases
            if related_release is not None
            else (
                list(current_record.get("related_releases", []))
                if updating
                else []
            )
        ),
        "resolved_in": (
            safe_resolved_in
            if resolved_in
            else (current_record.get("resolved_in") if updating else None)
        ),
        "updated_at": now,
        "reviewed_by": reviewer if approve else None,
        "body_managed_by_this_record": False,
        "external_submission_performed": False,
    }
    if updating:
        for timestamp_field in ("delivered_at", "acknowledged_at"):
            timestamp_value = current_record.get(timestamp_field)
            if isinstance(timestamp_value, str) and timestamp_value:
                record[timestamp_field] = timestamp_value
    if validate_schema(json_safe(record), "operator-feedback.schema.json"):
        block(
            "feedback_record_proposed_schema_invalid",
            "the proposed feedback record does not match the public schema.",
        )
    record_bytes = dump_yaml(json_safe(record)).encode("utf-8")
    proposed_record_sha256 = hashlib.sha256(record_bytes).hexdigest()
    receipt_relative = operator_feedback_receipt_relative_path(
        safe_id or "invalid-feedback-id",
        now,
        proposed_record_sha256,
    )
    receipt_path = archive_internal_path(root, receipt_relative)
    receipt = {
        "schema": OPERATOR_FEEDBACK_RECEIPT_SCHEMA,
        "dry_run": dry_run,
        "approved": approve,
        "intent": normalized_intent,
        "feedback_id": safe_id,
        "record_path": record_relative,
        "status": normalized_status,
        "reviewed_by": reviewer if approve else None,
        "previous_record_sha256": current_record_sha256,
        "record_sha256": proposed_record_sha256 if safe_id and safe_ref and normalized_status in OPERATOR_FEEDBACK_STATUSES else None,
        "created_at": now,
    }

    if approve and not blockers:
        receipt_bytes = (
            json.dumps(json_safe(receipt), indent=2, ensure_ascii=False) + "\n"
        ).encode("utf-8")
        with _OperatorFeedbackRecordLock(root, safe_id):
            # Re-evaluate the create/update precondition while holding the same
            # cross-process lock used by every sanctioned writer.
            before_commit_blocker_count = len(blockers)
            inspect_current_record()
            inspect_feedback_body_authority()
            if len(blockers) == before_commit_blocker_count:
                try:
                    _write_bytes_create_if_absent(receipt_path, receipt_bytes)
                    if normalized_intent == "create":
                        _write_bytes_create_if_absent(target_path, record_bytes)
                    else:
                        write_bytes_atomic(target_path, record_bytes)
                    fsync_directory(target_path.parent)
                except FileExistsError:
                    receipt_path.unlink(missing_ok=True)
                    block(
                        "feedback_record_concurrent_conflict",
                        "the feedback record or receipt was created concurrently; run a fresh dry-run.",
                    )
                except OSError:
                    receipt_path.unlink(missing_ok=True)
                    block(
                        "feedback_record_write_failed",
                        "the approved feedback record could not be committed safely.",
                    )

    state = "blocked" if blockers else ("written" if approve else "preview")
    next_safe_actions: list[str] = []
    if "feedback_body_reference_unverified" in warning_codes:
        next_safe_actions.append(
            (
                "Before approving a managed WOM feedback letter, run "
                "operator-feedback-compose dry-run and approval, then create the "
                "metadata record with its feedback-body-sha256 digest."
            )
        )
    if "feedback_body_authority_unverified" in blocker_codes:
        next_safe_actions.append(
            (
                "Repair or recreate the unchanged reviewed feedback body and "
                "approval receipt, then run a fresh metadata-record dry-run."
            )
        )
    if normalized_status == "draft" or normalized_intent == "create":
        next_safe_actions.append(
            (
                "A draft body may be revised under the same id with "
                "operator-feedback-compose --intent revise and exact body SHA-256; "
                "then rebind this draft record with a fresh record SHA-256. "
                "Delivered, acknowledged, resolved, and archived bodies remain immutable."
            )
        )
    return {
        "ok": not blockers,
        "state": state,
        "dry_run": dry_run or not approve,
        "approved": approve and not blockers,
        "lifecycle_action": "operator_feedback_record",
        "archive_id": read_archive_id(root),
        "summary": {
            "feedback_id": safe_id,
            "status": normalized_status if normalized_status in OPERATOR_FEEDBACK_STATUSES else None,
            "intent": normalized_intent if normalized_intent in OPERATOR_FEEDBACK_RECORD_INTENTS else None,
            "record_path": record_relative if safe_id else None,
            "receipt_path": receipt_relative if approve and not blockers else None,
            "current_record_sha256": current_record_sha256,
            "proposed_record_sha256": proposed_record_sha256 if not blockers else None,
            "title_present": bool(safe_title),
            "feedback_ref_present": bool(safe_ref),
            "related_release_count": len(releases),
            "resolved_in_present": bool(safe_resolved_in),
            "feedback_body_reference_kind": feedback_body_reference_kind,
            "feedback_body_authority_verified": feedback_body_authority_verified,
            "feedback_body_receipt_path": feedback_body_receipt_path,
            "feedback_body_receipt_sha256": feedback_body_receipt_sha256,
        },
        "data": {
            "record_schema": OPERATOR_FEEDBACK_SCHEMA,
            "receipt_schema": OPERATOR_FEEDBACK_RECEIPT_SCHEMA,
            "status_lifecycle": list(OPERATOR_FEEDBACK_STATUSES),
            "record_intents": list(OPERATOR_FEEDBACK_RECORD_INTENTS),
            "update_requires_expected_record_sha256": True,
            "feedback_ref_rebinding_allowed": True,
            "feedback_ref_rebinding_scope": "draft_only_managed_body_cas",
            "title_policy": {
                "max_length": 240,
                "descriptive_security_words_allowed": True,
                "horizontal_whitespace_normalized": True,
                "secret_value_shapes_allowed": False,
                "provider_urls_allowed": False,
                "email_like_values_allowed": False,
                "local_paths_allowed": False,
                "line_breaks_allowed": False,
            },
            "title_normalized": title_normalized,
            "body_managed_by_this_command": False,
            "external_submission_performed": False,
            "feedback_body_preflight": {
                "performed": feedback_body_preflight_performed,
                "authority_verified": feedback_body_authority_verified,
                "approval_receipt_ref_available": bool(
                    feedback_body_receipt_path
                    and feedback_body_receipt_sha256
                ),
                "feedback_ref_value_echoed": False,
            },
            "safe_withdrawal": {
                "supported": True,
                "target_status": "archived",
                "intent": "update",
                "requires_fresh_current_record_sha256": True,
                "preserves_feedback_ref": True,
                "feedback_ref_rebinding_allowed": False,
                "command_template": (
                    "archive operator-feedback-record <archive-root> "
                    "--feedback-id <same-id> --feedback-ref <same-ref> "
                    "--status archived --intent update --dry-run --format json"
                ),
            },
        },
        "blocker_codes": blocker_codes,
        "warning_codes": warning_codes,
        "blockers": blockers,
        "warnings": warnings,
        "next_safe_actions": next_safe_actions,
        "would_change": [] if approve and not blockers else ([record_relative, receipt_relative] if not blockers else []),
        "files_written": [record_relative, receipt_relative] if approve and not blockers else [],
        "privacy_guards": {
            "feedback_body_read": feedback_body_preflight_performed,
            "feedback_body_value_echoed": False,
            "feedback_ref_value_echoed": False,
            "title_value_echoed": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "writes": approve and not blockers,
        },
    }


def _read_operator_feedback_record_projection(path: Path) -> dict[str, Any] | None:
    """Read one ops/feedback/<id>.yml and project ONLY non-sensitive lifecycle fields.

    Returns a dict with {feedback_id, status, delivered_at, acknowledged_at,
    updated_at} — never feedback_ref, title, or any body/path/url/secret — or
    ``None`` when the file is missing, unreadable, non-YAML, or not a mapping.
    The projection is deliberate: the raw record holds feedback_ref + title and
    must never be spread into ledger/board output (runtime privacy contract).
    """

    try:
        loaded = load_yaml(path.read_text(encoding="utf-8"))
    except (OSError, yaml.YAMLError):  # type: ignore[union-attr]
        return None
    if not isinstance(loaded, dict):
        return None

    status = loaded.get("status")
    status = status.strip().lower() if isinstance(status, str) else None
    # Re-sanitize the id read back from disk. The sanctioned record writer rejects
    # unsafe ids, but records are documented as hand-editable, so a hand-authored
    # feedback_id could hold a URL/token. safe_operator_feedback_id re-checks it;
    # on failure fall back to the on-disk file stem (a safe filename by
    # construction) so no unsafe id value is ever projected into ledger output.
    raw_feedback_id = loaded.get("feedback_id")
    feedback_id = safe_operator_feedback_id(raw_feedback_id if isinstance(raw_feedback_id, str) else None)
    if feedback_id is None:
        feedback_id = safe_operator_feedback_id(path.stem)

    def _safe_ts(value: Any) -> str | None:
        if isinstance(value, str):
            text = value.strip()
            return text or None
        if isinstance(value, (date, datetime)):
            return value.isoformat()
        return None

    return {
        "feedback_id": feedback_id,
        "status": status,
        "delivered_at": _safe_ts(loaded.get("delivered_at")),
        "acknowledged_at": _safe_ts(loaded.get("acknowledged_at")),
        "updated_at": _safe_ts(loaded.get("updated_at")),
    }


def operator_feedback_ledger(archive_root: Path | str, *, dry_run: bool = True) -> dict[str, Any]:
    """Read-only delivery-status ledger over ops/feedback/*.yml.

    Aggregates STATUS + FEEDBACK-ID (+ safe delivered_at/acknowledged_at
    timestamps) ONLY. It never reads or echoes feedback bodies, refs, titles,
    paths, urls, or secrets, and writes nothing.

    Honesty note on the delivery boundary: only records stamped by
    ``operator-feedback-mark-delivered`` carry ``delivered_at``. Records that
    reached ``delivered`` via the older ``operator-feedback-record --status
    delivered`` path have no ``delivered_at``; for those the boundary falls back
    to their ``updated_at``. The boundary is therefore the newest available
    delivery timestamp among delivered records, not an authoritative proof of
    when (or whether) anything was externally delivered.
    """

    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    if not dry_run:
        blockers.append("operator-feedback-ledger is read-only and requires --dry-run.")

    counts = {status: 0 for status in OPERATOR_FEEDBACK_STATUSES}
    counts["unknown_status"] = 0
    unreadable = 0
    total = 0
    pending: list[str] = []
    delivered_boundary: str | None = None
    stamped_delivered = 0

    feedback_dir = root / OPERATOR_FEEDBACK_DIR
    if feedback_dir.is_dir():
        for path in safe_archive_glob(feedback_dir, "*.yml", root):
            total += 1
            projection = _read_operator_feedback_record_projection(path)
            if projection is None:
                unreadable += 1
                continue
            status = projection["status"]
            if status in counts:
                counts[status] += 1
            else:
                counts["unknown_status"] += 1
            if status == OPERATOR_FEEDBACK_PENDING_STATUS and projection["feedback_id"]:
                pending.append(projection["feedback_id"])
            if status == "delivered":
                if projection["delivered_at"]:
                    stamped_delivered += 1
                # Delivery boundary: prefer delivered_at, fall back to updated_at
                # for records delivered via the older --status path.
                candidate = projection["delivered_at"] or projection["updated_at"]
                if candidate and (delivered_boundary is None or candidate > delivered_boundary):
                    delivered_boundary = candidate

    pending.sort()

    return {
        "ok": not blockers,
        "state": "ready" if not blockers else "blocked",
        "dry_run": True,
        "lifecycle_action": "operator_feedback_ledger",
        "archive_id": read_archive_id(root),
        "summary": {
            "feedback_dir": OPERATOR_FEEDBACK_DIR,
            "receipt_dir": OPERATOR_FEEDBACK_RECEIPTS_DIR,
            "record_count": total,
            "pending_count": len(pending),
            "unreadable_count": unreadable,
            "delivery_boundary": delivered_boundary,
            "delivery_boundary_stamped_count": stamped_delivered,
            "pending_status": OPERATOR_FEEDBACK_PENDING_STATUS,
        },
        "counts": counts,
        "pending": pending,
        "data": {
            "statuses": list(OPERATOR_FEEDBACK_STATUSES),
            "record_schema": OPERATOR_FEEDBACK_SCHEMA,
            "delivery_boundary_meaning": (
                "newest delivery timestamp among delivered records; delivered_at is present "
                "only on records stamped by mark-delivered, otherwise updated_at is used"
            ),
            "delivery_is_metadata_only": True,
            "no_external_submission_performed": True,
        },
        "blockers": blockers,
        "warnings": [],
        "would_change": [],
        "privacy_guards": {
            "feedback_body_read": False,
            "feedback_ref_value_echoed": False,
            "title_value_echoed": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "writes": False,
        },
    }


def operator_feedback_delivery_receipt_relative_path(timestamp: str, batch_digest: str) -> str:
    # The timestamp is whole-second UTC, so two batches committed within the same
    # wall-clock second would collide on filename and the earlier batch's audit
    # receipt would be silently overwritten. Key the filename on a per-batch
    # content digest (mirroring mint_batch/retire_draft_batch receipt paths) so
    # each delivery-boundary receipt is durable and uniquely named.
    compact = re.sub(r"[^0-9TZ]", "", timestamp)
    digest = re.sub(r"[^0-9a-f]", "", (batch_digest or "").lower())[:24] or "0"
    return f"{OPERATOR_FEEDBACK_RECEIPTS_DIR}/delivery-batch.{compact}.{digest}.json"


def operator_feedback_mark_delivered(
    archive_root: Path | str,
    *,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    only: str | None = None,
) -> dict[str, Any]:
    """Batch delivery-boundary commit: transition pending (draft) records to delivered.

    In one action this marks draft records as ``delivered``, stamps
    ``delivered_at``, sets ``reviewed_by``, and refreshes ``updated_at`` — so the
    operator AI no longer hand-edits each record's status one at a time.

    Truth boundary (no overclaim): this is metadata lifecycle only. It performs
    NO external submission and proves NO human receipt. ``delivered`` here means
    "the operator marked it delivered" — the same trust level as the existing
    ``operator-feedback-record --status delivered``, just batched, timestamped,
    and receipted. ``external_submission_performed`` stays ``False``.

    It ONLY transitions ``draft`` -> ``delivered`` and never touches
    acknowledged/resolved/archived records. It reads each existing record and
    preserves every other field verbatim (feedback_ref, title, related_releases,
    resolved_in, body_managed_by_this_record, external_submission_performed),
    re-validating against the shipped schema before writing atomically per
    record. A malformed target record is reported and skipped, never aborting
    records already validated. Re-running is a no-op once no drafts remain
    (idempotent). It never reads or echoes feedback bodies, refs, or titles.
    """

    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    warnings: list[str] = []
    if dry_run == approve:
        blockers.append("operator-feedback-mark-delivered requires exactly one of --dry-run or --approve.")

    reviewer = safe_project_intake_actor_id(reviewed_by)
    if approve and reviewer is None:
        blockers.append("--approve requires a safe --reviewed-by actor id.")
    if reviewed_by and reviewer is None:
        blockers.append("reviewed_by must be a safe non-secret actor id.")

    safe_only = safe_operator_feedback_id(only) if only is not None else None
    if only is not None and safe_only is None:
        blockers.append("--only must be a safe feedback id using letters, numbers, dot, underscore, or hyphen.")

    now = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    would_change: list[dict[str, Any]] = []
    files_written: list[str] = []
    skipped_unreadable: list[str] = []
    matched_only = False

    if not blockers:
        feedback_dir = root / OPERATOR_FEEDBACK_DIR
        if feedback_dir.is_dir():
            for path in safe_archive_glob(feedback_dir, "*.yml", root):
                # Scope by --only against the on-disk file stem (never echoed).
                if safe_only is not None and path.stem != safe_only:
                    continue
                try:
                    loaded = load_yaml(path.read_text(encoding="utf-8"))
                except (OSError, yaml.YAMLError):  # type: ignore[union-attr]
                    if safe_only is not None:
                        matched_only = True
                    skipped_unreadable.append(path.stem)
                    continue
                if not isinstance(loaded, dict):
                    if safe_only is not None:
                        matched_only = True
                    skipped_unreadable.append(path.stem)
                    continue

                if safe_only is not None:
                    matched_only = True

                # Re-sanitize the id read back from disk before echoing it into
                # would_change / delivered_feedback_ids / the receipt. Records are
                # documented as hand-editable, so a hand-authored feedback_id could
                # hold a URL/token; fall back to the safe on-disk file stem so no
                # unsafe id value is ever echoed. (The actual on-disk record and
                # receipt paths already key on path.stem, never this value.)
                raw_record_id = loaded.get("feedback_id")
                record_id = safe_operator_feedback_id(raw_record_id if isinstance(raw_record_id, str) else None)
                if record_id is None:
                    record_id = safe_operator_feedback_id(path.stem) or path.stem
                current_status = loaded.get("status")
                current_status = current_status.strip().lower() if isinstance(current_status, str) else None

                # Only transition the pending state; never touch delivered/
                # acknowledged/resolved/archived (idempotent by construction).
                if current_status != OPERATOR_FEEDBACK_PENDING_STATUS:
                    continue

                would_change.append(
                    {
                        "feedback_id": record_id,
                        "from_status": current_status,
                        "to_status": "delivered",
                    }
                )

                if approve:
                    updated = dict(loaded)
                    updated["status"] = "delivered"
                    updated["delivered_at"] = now
                    updated["updated_at"] = now
                    updated["reviewed_by"] = reviewer
                    # Never claim external submission from a metadata stamp.
                    updated["external_submission_performed"] = False
                    normalized = json_safe(updated)
                    schema_issues = validate_schema(normalized, "operator-feedback.schema.json")
                    if schema_issues:
                        # A malformed/corrupt record must not corrupt or half-write
                        # others: report and skip, keep going per-record.
                        skipped_unreadable.append(record_id)
                        would_change.pop()
                        continue
                    write_text_atomic(path, dump_yaml(normalized))
                    files_written.append(operator_feedback_record_relative_path(path.stem))

        if safe_only is not None and not matched_only:
            warnings.append("--only did not match any operator feedback record.")
        if skipped_unreadable:
            warnings.append("One or more operator feedback records were unreadable or malformed and were skipped.")

    delivered_ids = [entry["feedback_id"] for entry in would_change]
    receipt_relative: str | None = None
    receipt: dict[str, Any] | None = None

    # Write the delivery-boundary receipt only when this approve actually
    # transitioned at least one record. An idempotent no-op approve (no drafts
    # remain) transitions nothing, so it must NOT emit a zero-delivery receipt —
    # that would accumulate misleading empty boundary artifacts and contradict
    # "re-running marks nothing new".
    if approve and not blockers and delivered_ids:
        # Uniquely name the receipt per batch so two commits within the same
        # wall-clock second cannot collapse to one file (see path helper).
        batch_digest = sha256_json_hex(
            {
                "delivered_feedback_ids": sorted(delivered_ids),
                "reviewed_by": reviewer,
                "created_at": now,
                "only": safe_only,
            }
        )
        receipt_relative = operator_feedback_delivery_receipt_relative_path(now, batch_digest)
        receipt = {
            "schema": OPERATOR_FEEDBACK_DELIVERY_RECEIPT_SCHEMA,
            "dry_run": False,
            "approved": True,
            "reviewed_by": reviewer,
            "delivered_feedback_ids": delivered_ids,
            "delivered_count": len(delivered_ids),
            "skipped_unreadable_count": len(skipped_unreadable),
            "only": safe_only,
            "batch_digest": batch_digest,
            "external_submission_performed": False,
            "delivery_is_metadata_only": True,
            "created_at": now,
        }
        receipt_path = root / receipt_relative
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        write_text_atomic(receipt_path, json.dumps(json_safe(receipt), indent=2, ensure_ascii=False) + "\n")

    state = "blocked" if blockers else ("written" if approve else "preview")
    return {
        "ok": not blockers,
        "state": state,
        "dry_run": dry_run or not approve,
        "approved": approve and not blockers,
        "lifecycle_action": "operator_feedback_mark_delivered",
        "archive_id": read_archive_id(root),
        "summary": {
            "transition": "draft->delivered",
            "candidate_count": len(would_change),
            "delivered_count": len(files_written) if approve else 0,
            "skipped_unreadable_count": len(skipped_unreadable),
            "receipt_path": receipt_relative,
            "reviewed_by": reviewer if approve else None,
            "only": safe_only,
        },
        "would_change": would_change if not (approve and not blockers) else [],
        "delivered_feedback_ids": delivered_ids if approve and not blockers else [],
        "files_written": files_written,
        "data": {
            "record_schema": OPERATOR_FEEDBACK_SCHEMA,
            "delivery_receipt_schema": OPERATOR_FEEDBACK_DELIVERY_RECEIPT_SCHEMA,
            "pending_status": OPERATOR_FEEDBACK_PENDING_STATUS,
            "delivery_is_metadata_only": True,
            "no_external_submission_performed": True,
            "delivered_meaning": "the operator marked it delivered; nothing was submitted externally or proven received",
        },
        "blockers": blockers,
        "warnings": warnings,
        "privacy_guards": {
            "feedback_body_read": False,
            "feedback_ref_value_echoed": False,
            "title_value_echoed": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "writes": approve and not blockers,
        },
    }


def safe_approval_handoff_id(value: str | None) -> str | None:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if not APPROVAL_HANDOFF_ID_RE.match(text):
        return None
    if contains_forbidden_location_reference(text) or source_intake_has_provider_url(text) or source_intake_secret_like(text):
        return None
    return text


def safe_approval_handoff_scalar(value: str | None, *, max_length: int = 240) -> str | None:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if not text or len(text) > max_length:
        return None
    if not safe_source_intake_plan_scalar(text):
        return None
    return text


def approval_handoff_record_relative_path(handoff_id: str) -> str:
    return f"{APPROVAL_HANDOFF_DIR}/{handoff_id}.yml"


def approval_handoff_receipt_relative_path(handoff_id: str, timestamp: str) -> str:
    compact = re.sub(r"[^0-9TZ]", "", timestamp)
    return f"{APPROVAL_HANDOFF_RECEIPTS_DIR}/{handoff_id}.{compact}.json"


def approval_handoff_plan(archive_root: Path | str, *, dry_run: bool = True) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    if not dry_run:
        blockers.append("approval-handoff-plan is read-only and requires --dry-run.")
    return {
        "ok": not blockers,
        "state": "ready" if not blockers else "blocked",
        "dry_run": True,
        "lifecycle_action": "approval_handoff_plan",
        "archive_id": read_archive_id(root),
        "summary": {
            "handoff_dir": APPROVAL_HANDOFF_DIR,
            "receipt_dir": APPROVAL_HANDOFF_RECEIPTS_DIR,
            "statuses": list(APPROVAL_HANDOFF_STATUSES),
            "operation_kinds": list(APPROVAL_HANDOFF_OPERATION_KINDS),
            "execution_performed": False,
        },
        "data": {
            "record_schema": APPROVAL_HANDOFF_SCHEMA,
            "receipt_schema": APPROVAL_HANDOFF_RECEIPT_SCHEMA,
            "recommended_record_command": (
                "archive approval-handoff-record <archive-root> --handoff-id <safe-id> "
                "--operation-kind <kind> --target-ref <safe-ref> --requested-action <safe-label> "
                "--status needs_review --dry-run --format json"
            ),
            "specialized_approval_commands": [
                "credential-access-approval-plan",
                "imap-mailbox-material-capture-approval-plan",
                "project-intake-record-answer",
            ],
            "handoff_boundary": [
                "handoff records document the human approval state for an operation",
                "this command never executes the underlying operation",
                "this command never reads private material, provider data, local secrets, or external URLs",
                "AI operators should show the summary, blockers, warnings, and next safe action before asking a human to approve",
            ],
            "status_lifecycle": [
                {"status": "needs_review", "meaning": "a human decision is required before the operation continues"},
                {"status": "approved_once", "meaning": "one future operation attempt may proceed if all other guards pass"},
                {"status": "denied", "meaning": "the operation must not proceed"},
                {"status": "superseded", "meaning": "a later handoff replaced this one"},
                {"status": "resolved", "meaning": "the operation is closed by a receipt, release, or decision"},
            ],
        },
        "blockers": blockers,
        "warnings": [],
        "would_change": [],
        "privacy_guards": {
            "target_ref_value_echoed": False,
            "requested_action_value_echoed": False,
            "private_material_read": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "operation_executed": False,
            "writes": False,
        },
    }


def approval_handoff_record(
    archive_root: Path | str,
    *,
    handoff_id: str | None,
    operation_kind: str,
    target_ref: str | None,
    requested_action: str | None,
    status: str,
    requested_by: str | None = None,
    reviewed_by: str | None = None,
    related_command: list[str] | None = None,
    related_release: list[str] | None = None,
    supersedes: str | None = None,
    resolved_in: str | None = None,
    dry_run: bool = False,
    approve: bool = False,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    warnings: list[str] = []
    if dry_run == approve:
        blockers.append("approval-handoff-record requires exactly one of --dry-run or --approve.")

    safe_id = safe_approval_handoff_id(handoff_id)
    if safe_id is None:
        blockers.append("handoff_id must be a safe id using letters, numbers, dot, underscore, or hyphen.")

    normalized_kind = (operation_kind or "").strip()
    if normalized_kind not in APPROVAL_HANDOFF_OPERATION_KINDS:
        blockers.append("operation_kind must be one of: " + ", ".join(APPROVAL_HANDOFF_OPERATION_KINDS) + ".")

    normalized_status = (status or "").strip().lower()
    if normalized_status not in APPROVAL_HANDOFF_STATUSES:
        blockers.append("status must be one of: " + ", ".join(APPROVAL_HANDOFF_STATUSES) + ".")

    safe_target_ref = safe_approval_handoff_scalar(target_ref, max_length=240)
    if safe_target_ref is None:
        blockers.append("target_ref must be a safe non-secret ref, not a URL, email, token, or local path.")

    safe_requested_action = safe_approval_handoff_scalar(requested_action, max_length=240)
    if safe_requested_action is None:
        blockers.append("requested_action must be a safe non-secret single-line label.")

    requester = safe_project_intake_actor_id(requested_by) if requested_by else None
    if requested_by and requester is None:
        blockers.append("requested_by must be a safe non-secret actor id.")

    reviewer = safe_project_intake_actor_id(reviewed_by) if reviewed_by else None
    if approve and reviewer is None:
        blockers.append("--approve requires a safe --reviewed-by actor id.")
    if reviewed_by and reviewer is None:
        blockers.append("reviewed_by must be a safe non-secret actor id.")

    commands: list[str] = []
    for item in related_command or []:
        safe_command = safe_approval_handoff_scalar(item, max_length=120)
        if safe_command is None:
            blockers.append("related_command values must be safe non-secret labels.")
        elif safe_command not in commands:
            commands.append(safe_command)

    releases: list[str] = []
    for item in related_release or []:
        safe_release = safe_approval_handoff_scalar(item, max_length=80)
        if safe_release is None:
            blockers.append("related_release values must be safe non-secret labels.")
        elif safe_release not in releases:
            releases.append(safe_release)

    safe_supersedes = safe_approval_handoff_id(supersedes) if supersedes else None
    if supersedes and safe_supersedes is None:
        blockers.append("supersedes must be a safe handoff id.")
    if normalized_status == "superseded" and not safe_supersedes:
        blockers.append("superseded status requires --supersedes.")

    safe_resolved_in = safe_approval_handoff_scalar(resolved_in, max_length=80) if resolved_in else None
    if resolved_in and safe_resolved_in is None:
        blockers.append("resolved_in must be a safe non-secret release or receipt label.")
    if normalized_status == "resolved" and not safe_resolved_in:
        blockers.append("resolved status requires --resolved-in.")

    now = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    record_relative = approval_handoff_record_relative_path(safe_id or "invalid-handoff-id")
    receipt_relative = approval_handoff_receipt_relative_path(safe_id or "invalid-handoff-id", now)
    target_path = root / record_relative
    receipt_path = root / receipt_relative
    if target_path.exists() and approve:
        warnings.append("Existing approval handoff record will be replaced with the approved metadata update.")

    record = {
        "schema": APPROVAL_HANDOFF_SCHEMA,
        "handoff_id": safe_id,
        "operation_kind": normalized_kind if normalized_kind in APPROVAL_HANDOFF_OPERATION_KINDS else None,
        "target_ref": safe_target_ref,
        "requested_action": safe_requested_action,
        "status": normalized_status if normalized_status in APPROVAL_HANDOFF_STATUSES else None,
        "requested_by": requester,
        "reviewed_by": reviewer if approve else None,
        "related_commands": commands,
        "related_releases": releases,
        "supersedes": safe_supersedes,
        "resolved_in": safe_resolved_in,
        "updated_at": now,
        "operation_executed_by_this_record": False,
        "private_material_read_by_this_record": False,
        "external_provider_called_by_this_record": False,
    }
    receipt = {
        "schema": APPROVAL_HANDOFF_RECEIPT_SCHEMA,
        "dry_run": dry_run,
        "approved": approve,
        "handoff_id": safe_id,
        "record_path": record_relative,
        "operation_kind": normalized_kind if normalized_kind in APPROVAL_HANDOFF_OPERATION_KINDS else None,
        "status": normalized_status if normalized_status in APPROVAL_HANDOFF_STATUSES else None,
        "reviewed_by": reviewer if approve else None,
        "record_sha256": sha256_text(dump_yaml(record))
        if safe_id
        and safe_target_ref
        and safe_requested_action
        and normalized_kind in APPROVAL_HANDOFF_OPERATION_KINDS
        and normalized_status in APPROVAL_HANDOFF_STATUSES
        else None,
        "created_at": now,
        "closed_actions": {
            "operation_executed": False,
            "private_material_read": False,
            "provider_called": False,
            "secrets_read": False,
        },
    }

    if approve and not blockers:
        target_path.parent.mkdir(parents=True, exist_ok=True)
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        write_text_atomic(target_path, dump_yaml(json_safe(record)))
        write_text_atomic(receipt_path, json.dumps(json_safe(receipt), indent=2, ensure_ascii=False) + "\n")

    state = "blocked" if blockers else ("written" if approve else "preview")
    return {
        "ok": not blockers,
        "state": state,
        "dry_run": dry_run or not approve,
        "approved": approve and not blockers,
        "lifecycle_action": "approval_handoff_record",
        "archive_id": read_archive_id(root),
        "summary": {
            "handoff_id": safe_id,
            "operation_kind": normalized_kind if normalized_kind in APPROVAL_HANDOFF_OPERATION_KINDS else None,
            "status": normalized_status if normalized_status in APPROVAL_HANDOFF_STATUSES else None,
            "record_path": record_relative if safe_id else None,
            "receipt_path": receipt_relative if approve and not blockers else None,
            "target_ref_present": bool(safe_target_ref),
            "requested_action_present": bool(safe_requested_action),
            "related_command_count": len(commands),
            "related_release_count": len(releases),
            "operation_executed": False,
        },
        "data": {
            "record_schema": APPROVAL_HANDOFF_SCHEMA,
            "receipt_schema": APPROVAL_HANDOFF_RECEIPT_SCHEMA,
            "status_lifecycle": list(APPROVAL_HANDOFF_STATUSES),
            "operation_kinds": list(APPROVAL_HANDOFF_OPERATION_KINDS),
            "handoff_only": True,
        },
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
        "would_change": [] if approve and not blockers else ([record_relative, receipt_relative] if not blockers else []),
        "files_written": [record_relative, receipt_relative] if approve and not blockers else [],
        "privacy_guards": {
            "target_ref_value_echoed": False,
            "requested_action_value_echoed": False,
            "private_material_read": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "operation_executed": False,
            "writes": approve and not blockers,
        },
    }


def approval_handoff_audit(
    archive_root: Path | str,
    *,
    handoff_record: str | None,
    expected_operation_kind: str | None = None,
    expected_status: str = "approved_once",
    dry_run: bool = True,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    warnings: list[str] = []
    if not dry_run:
        blockers.append("approval-handoff-audit is read-only and requires --dry-run.")

    record_relative: str | None = None
    record: dict[str, Any] | None = None
    raw_record = str(handoff_record or "").strip()
    if not raw_record:
        blockers.append("handoff_record is required.")
    else:
        try:
            record_path = resolve_archive_relative_path(root, raw_record)
            record_relative = archive_relative_path(record_path, root)
        except ArchivePathError:
            blockers.append("handoff_record must be an archive-relative path inside the archive root.")
            record_path = None
        if record_relative and (
            not record_relative.startswith(f"{APPROVAL_HANDOFF_DIR}/") or not record_relative.endswith(".yml")
        ):
            blockers.append(f"handoff_record must point under {APPROVAL_HANDOFF_DIR}/ and end with .yml.")
        if record_path is not None and not record_path.is_file():
            blockers.append("approval handoff record is missing.")
        if record_path is not None and record_path.is_file() and not blockers:
            loaded = load_yaml(record_path.read_text(encoding="utf-8"))
            if not isinstance(loaded, dict):
                blockers.append("approval handoff record must be a YAML object.")
            else:
                record = json_safe(loaded)

    normalized_expected_status = (expected_status or "").strip().lower()
    if normalized_expected_status not in APPROVAL_HANDOFF_STATUSES:
        blockers.append("expected_status must be one of: " + ", ".join(APPROVAL_HANDOFF_STATUSES) + ".")
    normalized_expected_kind = (expected_operation_kind or "").strip() or None
    if normalized_expected_kind and normalized_expected_kind not in APPROVAL_HANDOFF_OPERATION_KINDS:
        blockers.append("expected_operation_kind must be one of: " + ", ".join(APPROVAL_HANDOFF_OPERATION_KINDS) + ".")

    handoff_id = None
    status = None
    operation_kind = None
    reviewed_by_present = False
    target_ref_present = False
    requested_action_present = False
    if record is not None:
        if record.get("schema") != APPROVAL_HANDOFF_SCHEMA:
            blockers.append(f"approval handoff record schema must be {APPROVAL_HANDOFF_SCHEMA}.")
        handoff_id = record.get("handoff_id") if isinstance(record.get("handoff_id"), str) else None
        status = str(record.get("status") or "")
        operation_kind = str(record.get("operation_kind") or "")
        reviewed_by_present = bool(record.get("reviewed_by"))
        target_ref_present = bool(record.get("target_ref"))
        requested_action_present = bool(record.get("requested_action"))
        if status != normalized_expected_status:
            blockers.append("approval handoff status does not match expected_status.")
        if normalized_expected_kind and operation_kind != normalized_expected_kind:
            blockers.append("approval handoff operation_kind does not match expected_operation_kind.")
        if status == "approved_once" and not reviewed_by_present:
            blockers.append("approved_once handoff requires reviewed_by.")
        if record.get("operation_executed_by_this_record") is not False:
            blockers.append("approval handoff record must not report operation execution.")
        if record.get("private_material_read_by_this_record") is not False:
            blockers.append("approval handoff record must not report private material reads.")
        if record.get("external_provider_called_by_this_record") is not False:
            blockers.append("approval handoff record must not report provider calls.")

    future_operation_authorized = False
    if status == "needs_review":
        warnings.append("The handoff still needs human review before any future operation proceeds.")
    if status == "denied":
        warnings.append("The handoff was denied; the future operation must not proceed.")
    if status == "superseded":
        warnings.append("The handoff was superseded; audit the replacement handoff before proceeding.")
    if status == "resolved":
        warnings.append("The handoff is resolved; use the closing receipt or release as the authority.")

    return {
        "ok": not blockers,
        "state": "blocked" if blockers else "not_authorized",
        "dry_run": True,
        "lifecycle_action": "approval_handoff_audit",
        "binding_state": "legacy_unbound",
        "authority_classification": "advisory",
        "future_operation_authorized": False,
        "archive_id": read_archive_id(root),
        "summary": {
            "handoff_id": handoff_id,
            "record_path": record_relative,
            "status": status or None,
            "operation_kind": operation_kind or None,
            "expected_status": normalized_expected_status if normalized_expected_status in APPROVAL_HANDOFF_STATUSES else None,
            "expected_operation_kind": normalized_expected_kind,
            "target_ref_present": target_ref_present,
            "requested_action_present": requested_action_present,
            "reviewed_by_present": reviewed_by_present,
            "future_operation_authorized": future_operation_authorized,
            "binding_state": "legacy_unbound",
            "authority_classification": "advisory",
        },
        "data": {
            "record_schema": APPROVAL_HANDOFF_SCHEMA,
            "status_lifecycle": list(APPROVAL_HANDOFF_STATUSES),
            "operation_kinds": list(APPROVAL_HANDOFF_OPERATION_KINDS),
            "audit_only": True,
        },
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
        "would_change": [],
        "privacy_guards": {
            "handoff_record_body_read": bool(record is not None),
            "target_ref_value_echoed": False,
            "requested_action_value_echoed": False,
            "private_material_read": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "operation_executed": False,
            "writes": False,
        },
    }


def operation_status_taxonomy(archive_root: Path | str, *, dry_run: bool = True) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    if not dry_run:
        blockers.append("operation-status-taxonomy is read-only and requires --dry-run.")
    envelope = operator_envelope_classes(status_class="blocked" if blockers else "preview")

    statuses = [
        {
            "status_class": "succeeded",
            "ok": True,
            "terminal": True,
            "meaning": "the requested read-only or verification operation completed fully",
            "ai_operator_rule": "it may be summarized as complete if warnings are empty or explicitly explained",
        },
        {
            "status_class": "preview",
            "ok": True,
            "terminal": False,
            "meaning": "a dry-run preview or plan completed without writing",
            "ai_operator_rule": "do not claim the planned write or external action happened",
        },
        {
            "status_class": "written",
            "ok": True,
            "terminal": True,
            "meaning": "an approval-gated local write completed and receipts should name what changed",
            "ai_operator_rule": "summarize files_written or receipt_path before saying the write is done",
        },
        {
            "status_class": "no_change",
            "ok": True,
            "terminal": True,
            "meaning": "the operation was valid but idempotent and nothing needed to change",
            "ai_operator_rule": "say no change was needed rather than implying a new write happened",
        },
        {
            "status_class": "partial",
            "ok": False,
            "terminal": False,
            "meaning": "some items completed but at least one requested item did not",
            "ai_operator_rule": "never report this as success; list incomplete counts and next safe actions",
        },
        {
            "status_class": "truncated",
            "ok": False,
            "terminal": False,
            "meaning": "the command intentionally omitted results because of limits, caps, or paging",
            "ai_operator_rule": "never report this as complete coverage; ask for a narrower scope or continue paging",
        },
        {
            "status_class": "blocked",
            "ok": False,
            "terminal": False,
            "meaning": "preconditions or safety gates stopped the operation before it could run",
            "ai_operator_rule": "surface blockers first and do not retry with broader permissions automatically",
        },
        {
            "status_class": "failed",
            "ok": False,
            "terminal": True,
            "meaning": "the command failed unexpectedly or an operation error occurred",
            "ai_operator_rule": "report the failure and preserve evidence instead of claiming a policy blocker",
        },
    ]
    return {
        "ok": not blockers,
        "state": "ready" if not blockers else "blocked",
        "status_class": envelope["status_class"],
        "input_provenance_class": envelope["input_provenance_class"],
        "secret_signal_class": envelope["secret_signal_class"],
        "operator_envelope": envelope,
        "dry_run": True,
        "lifecycle_action": "operation_status_taxonomy",
        "archive_id": read_archive_id(root),
        "summary": {
            "schema": OPERATION_STATUS_TAXONOMY_SCHEMA,
            "status_class_count": len(statuses),
            "failure_class_count": len(OPERATION_STATUS_FAILURE_CLASSES),
            "partial_and_truncated_are_success": False,
            "writes": False,
        },
        "data": {
            "schema": OPERATION_STATUS_TAXONOMY_SCHEMA,
            "required_envelope_fields": [
                "ok",
                "state",
                "summary",
                "data",
                "blockers",
                "warnings",
                "privacy_guards",
            ],
            "status_classes": statuses,
            "failure_classes": list(OPERATION_STATUS_FAILURE_CLASSES),
            "recommended_state_mapping": {
                "complete_and_verified": "succeeded",
                "dry_run_only": "preview",
                "approval_gated_write_done": "written",
                "idempotent": "no_change",
                "item_level_gaps": "partial",
                "limit_or_page_cap_hit": "truncated",
                "precondition_missing": "blocked",
                "unexpected_exception": "failed",
            },
            "agent_operator_checks": [
                "If ok is false, lead with blockers, incomplete counts, or truncation before any success wording.",
                "If a summary contains truncated=true, limit_hit=true, omitted_count>0, or incomplete_count>0, classify as truncated or partial even when some items were returned.",
                "If dry_run=true, do not say files were written or external actions were performed.",
                "If privacy_guards say values were not echoed, do not invent those values in the user-facing answer.",
            ],
        },
        "blockers": blockers,
        "warnings": [],
        "would_change": [],
        "privacy_guards": {
            "archive_body_text_read": False,
            "zettel_body_text_echoed": False,
            "source_values_echoed": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "writes": False,
        },
    }


def input_provenance_taxonomy(archive_root: Path | str, *, dry_run: bool = True) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    if not dry_run:
        blockers.append("input-provenance-taxonomy is read-only and requires --dry-run.")
    envelope = operator_envelope_classes(status_class="blocked" if blockers else "preview")

    provenance_classes = [
        {
            "provenance_class": "tool_discovered",
            "verified_by_tool": True,
            "owner": "tool",
            "meaning": "the command discovered the input from archive metadata, an index, or a local manifest",
            "ai_operator_rule": "the AI may say the tool found the input, while still respecting privacy guards",
        },
        {
            "provenance_class": "receipt_verified",
            "verified_by_tool": True,
            "owner": "prior_receipt",
            "meaning": "the input came from a receipt that the command parsed and matched to the current archive",
            "ai_operator_rule": "cite the receipt path or hash when the command output exposes a safe reference",
        },
        {
            "provenance_class": "human_selected",
            "verified_by_tool": False,
            "owner": "human",
            "meaning": "a human selected the input, but the command may not have independently verified the target",
            "ai_operator_rule": "say the human selected it; do not claim the tool discovered it unless a receipt confirms it",
        },
        {
            "provenance_class": "caller_supplied",
            "verified_by_tool": False,
            "owner": "caller",
            "meaning": "the invoking AI, script, or shell supplied the input argument",
            "ai_operator_rule": "treat it as brittle until the command validates it against archive state or a receipt",
        },
        {
            "provenance_class": "ai_generated",
            "verified_by_tool": False,
            "owner": "ai",
            "meaning": "an AI generated the input label, path, identifier, or mapping",
            "ai_operator_rule": "never treat it as source truth without a validation command or human correction event",
        },
        {
            "provenance_class": "fixture_supplied",
            "verified_by_tool": False,
            "owner": "test_fixture",
            "meaning": "the input came from a local fixture or sanitized sample",
            "ai_operator_rule": "do not generalize fixture success to live provider or full archive coverage",
        },
        {
            "provenance_class": "environment_inferred",
            "verified_by_tool": False,
            "owner": "runtime_environment",
            "meaning": "the input was inferred from cwd, environment variables, path conventions, or local defaults",
            "ai_operator_rule": "re-check explicit archive roots, accounts, and release state before writing or publishing",
        },
        {
            "provenance_class": "unknown",
            "verified_by_tool": False,
            "owner": "unknown",
            "meaning": "the command cannot tell where the input came from",
            "ai_operator_rule": "do not claim provenance; ask for or generate a receipt-backed validation step",
        },
    ]

    return {
        "ok": not blockers,
        "state": "ready" if not blockers else "blocked",
        "status_class": envelope["status_class"],
        "input_provenance_class": envelope["input_provenance_class"],
        "secret_signal_class": envelope["secret_signal_class"],
        "operator_envelope": envelope,
        "dry_run": True,
        "lifecycle_action": "input_provenance_taxonomy",
        "archive_id": read_archive_id(root),
        "summary": {
            "schema": INPUT_PROVENANCE_TAXONOMY_SCHEMA,
            "provenance_class_count": len(provenance_classes),
            "unverified_class_count": len(INPUT_PROVENANCE_UNVERIFIED_CLASSES),
            "caller_supplied_is_verified": False,
            "writes": False,
        },
        "data": {
            "schema": INPUT_PROVENANCE_TAXONOMY_SCHEMA,
            "provenance_classes": provenance_classes,
            "unverified_classes": list(INPUT_PROVENANCE_UNVERIFIED_CLASSES),
            "recommended_fields_for_future_commands": [
                "input_provenance",
                "input_provenance_class",
                "input_verified_by_tool",
                "source_receipt_path",
                "source_receipt_sha256",
                "caller_supplied_fields",
            ],
            "agent_operator_checks": [
                "If an input is caller_supplied, say it was supplied to the command, not discovered by the command.",
                "If an input is ai_generated, require validation before minting, linking, fetching, or publishing.",
                "If an input is fixture_supplied, do not claim live provider coverage.",
                "If provenance is unknown, add a validation or receipt step before treating it as canonical.",
            ],
        },
        "blockers": blockers,
        "warnings": [],
        "would_change": [],
        "privacy_guards": {
            "archive_body_text_read": False,
            "zettel_body_text_echoed": False,
            "input_values_echoed": False,
            "source_values_echoed": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "writes": False,
        },
    }


def secret_signal_taxonomy(archive_root: Path | str, *, dry_run: bool = True) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    if not dry_run:
        blockers.append("secret-signal-taxonomy is read-only and requires --dry-run.")
    envelope = operator_envelope_classes(status_class="blocked" if blockers else "preview")

    signal_classes = [
        {
            "signal_class": "concept_word",
            "blocking": False,
            "meaning": "a documentation or schema word such as secret, token, credential, password, or key",
            "ai_operator_rule": "do not treat a concept word as a leaked value by itself",
        },
        {
            "signal_class": "safe_reference",
            "blocking": False,
            "meaning": "a non-secret label that points to a vault, OS store, approval receipt, or future adapter",
            "ai_operator_rule": "safe refs may be shown when the command explicitly marks them safe",
        },
        {
            "signal_class": "credential_reference",
            "blocking": False,
            "meaning": "a structured reference such as secret:ref, credential id, or vault entry label without the value",
            "ai_operator_rule": "do not resolve or echo the actual secret value; keep it as an indirection",
        },
        {
            "signal_class": "secret_value_pattern",
            "blocking": True,
            "meaning": "a value-shaped token, API key, password, private key block, session cookie, or high-entropy bearer string",
            "ai_operator_rule": "block echoing, record only non-reversible fingerprints or safe receipt metadata when needed",
        },
        {
            "signal_class": "private_locator",
            "blocking": True,
            "meaning": "a local absolute path, provider locator, private file URL, or object location that exposes where private material lives",
            "ai_operator_rule": "do not echo; replace with durable WOM refs, manifests, object ids, or redacted summaries",
        },
        {
            "signal_class": "account_identifier",
            "blocking": True,
            "meaning": "an email address, account id, org id, tenant id, or provider profile that can identify a private account",
            "ai_operator_rule": "do not expose in public outputs unless an explicit public-safe policy says it is allowed",
        },
        {
            "signal_class": "unknown_sensitive_context",
            "blocking": True,
            "meaning": "text appears near auth, provider, mailbox, credential, or private-material context but is not classified safely",
            "ai_operator_rule": "fail closed and ask for a safer ref or approval receipt instead of guessing",
        },
    ]

    return {
        "ok": not blockers,
        "state": "ready" if not blockers else "blocked",
        "status_class": envelope["status_class"],
        "input_provenance_class": envelope["input_provenance_class"],
        "secret_signal_class": envelope["secret_signal_class"],
        "operator_envelope": envelope,
        "dry_run": True,
        "lifecycle_action": "secret_signal_taxonomy",
        "archive_id": read_archive_id(root),
        "summary": {
            "schema": SECRET_SIGNAL_TAXONOMY_SCHEMA,
            "signal_class_count": len(signal_classes),
            "blocking_class_count": len(SECRET_SIGNAL_BLOCKING_CLASSES),
            "concept_words_are_secret_values": False,
            "writes": False,
        },
        "data": {
            "schema": SECRET_SIGNAL_TAXONOMY_SCHEMA,
            "signal_classes": signal_classes,
            "blocking_classes": list(SECRET_SIGNAL_BLOCKING_CLASSES),
            "recommended_fields_for_future_commands": [
                "secret_signal_class",
                "secret_value_echoed",
                "safe_reference_echoed",
                "private_locator_echoed",
                "account_identifier_echoed",
            ],
            "agent_operator_checks": [
                "Do not flag concept words alone as leaked secret values.",
                "Block value-shaped tokens, private locators, and account identifiers in public outputs.",
                "Prefer safe refs, object ids, receipt paths, or non-reversible fingerprints over secret values.",
                "When context is ambiguous and sensitive, fail closed and request a safer reference.",
            ],
        },
        "blockers": blockers,
        "warnings": [],
        "would_change": [],
        "privacy_guards": {
            "archive_body_text_read": False,
            "sample_values_read": False,
            "sample_values_echoed": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "writes": False,
        },
    }


def ai_response_contract(archive_root: Path | str, *, dry_run: bool = True) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    if not dry_run:
        blockers.append("ai-response-contract is read-only and requires --dry-run.")
    envelope = operator_envelope_classes(status_class="blocked" if blockers else "preview")

    response_sections = [
        {
            "section": "operation_outcome",
            "required": True,
            "operator_rule": "classify the result before saying work is complete",
            "safe_status_classes": ["succeeded", "preview", "written", "no_change"],
            "not_success_status_classes": ["partial", "truncated", "blocked", "failed"],
        },
        {
            "section": "evidence_basis",
            "required": True,
            "operator_rule": "name whether evidence came from command output, a receipt, a release, a tag, or a caller-supplied input",
            "source_truth_rule": "do not describe caller-supplied or AI-generated values as tool-discovered source truth",
        },
        {
            "section": "privacy_boundary",
            "required": True,
            "operator_rule": "do not echo secret-like values, private locators, account identifiers, local absolute paths, tokens, or secret values",
            "safe_alternatives": ["safe refs", "archive-relative refs", "object ids", "receipt paths", "non-reversible fingerprints"],
        },
        {
            "section": "approval_boundary",
            "required": True,
            "operator_rule": "only claim writes, live fetches, uploads, external actions, or privileged execution after explicit approval and receipt evidence",
        },
        {
            "section": "remaining_work",
            "required": True,
            "operator_rule": "surface blockers, warnings, incomplete coverage, and next safe action instead of burying them in a summary",
        },
        {
            "section": "openable_archive_references",
            "required": True,
            "operator_rule": "when reporting an archive file, include an archive-relative path or another client-openable reference instead of an identifier alone",
            "applies_to": ["zettels", "letters", "objets", "receipts", "plans", "scripts"],
        },
        {
            "section": "human_record_integrity",
            "required": True,
            "operator_rule": "keep command names, plan hashes, receipt counts, and execution status in receipts or operator reports unless the human explicitly asked to preserve operations as zet content",
            "draft_rule": "revise an unminted draft in place, including its title, rather than deleting and recreating it",
        },
        {
            "section": "conversation_status_board",
            "required": False,
            "operator_rule": "a compact conversational status board is allowed; a web UI is not required",
            "web_ui_required": False,
        },
    ]

    return {
        "ok": not blockers,
        "state": "ready" if not blockers else "blocked",
        "status_class": envelope["status_class"],
        "input_provenance_class": envelope["input_provenance_class"],
        "secret_signal_class": envelope["secret_signal_class"],
        "operator_envelope": envelope,
        "dry_run": True,
        "lifecycle_action": "ai_response_contract",
        "archive_id": read_archive_id(root),
        "source_fidelity_policy": source_fidelity_policy(),
        "summary": {
            "schema": AI_RESPONSE_CONTRACT_SCHEMA,
            "required_section_count": sum(1 for item in response_sections if item.get("required")),
            "optional_section_count": sum(1 for item in response_sections if not item.get("required")),
            "conversation_status_board_allowed": True,
            "web_ui_required": False,
            "writes": False,
        },
        "data": {
            "schema": AI_RESPONSE_CONTRACT_SCHEMA,
            "taxonomy_dependencies": [
                "operation-status-taxonomy",
                "input-provenance-taxonomy",
                "secret-signal-taxonomy",
                "approval-handoff-audit",
                "status-board",
                "authoring-conventions",
            ],
            "minimum_result_fields_to_check": [
                "ok",
                "state",
                "summary",
                "blockers",
                "warnings",
                "privacy_guards",
                "would_change",
                "files_written",
                "receipt_path",
            ],
            "response_sections": response_sections,
            "must_not_claim": [
                "partial, truncated, blocked, or failed results are complete",
                "caller-supplied input was discovered or verified by the tool",
                "a dry-run preview performed a write or live external action",
                "a future adapter boundary has already executed",
                "secret concept words are leaked secret values by themselves",
                "an archive file is available when no openable archive reference was provided",
                "tool execution metadata belongs in a human-facing zet body by default",
            ],
            "recommended_answer_order": [
                "outcome",
                "evidence",
                "privacy/approval boundary",
                "remaining blockers or next safe action",
            ],
        },
        "blockers": blockers,
        "warnings": [],
        "would_change": [],
        "privacy_guards": {
            "archive_body_text_read": False,
            "zettel_body_text_echoed": False,
            "source_values_echoed": False,
            "sample_values_read": False,
            "sample_values_echoed": False,
            "provider_called": False,
            "network_checked": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "writes": False,
        },
    }


def operator_envelope_classes(
    *,
    status_class: str,
    input_provenance_class: str = "caller_supplied",
    secret_signal_class: str = "concept_word",
) -> dict[str, Any]:
    return {
        "schema": OPERATOR_ENVELOPE_CLASS_SCHEMA,
        "status_class": status_class,
        "input_provenance_class": input_provenance_class,
        "secret_signal_class": secret_signal_class,
        "classification_note": (
            "archive_root is caller-supplied and validated before use; "
            "these safety commands return built-in concept words and safe refs, not secret values"
        ),
    }


def zettel_summary(path: Path, archive_root: Path, expected_status: str) -> dict[str, Any]:
    boundary = read_zettel_content_boundary(path)
    if boundary["state"] == "blocked":
        # The path is already part of the caller-visible archive listing, but
        # no untrusted frontmatter or body value may cross this boundary.
        return {
            "path": archive_relative_path(path, archive_root),
            "id": None,
            "title": None,
            "status": ZETTEL_QUARANTINED_STATUS,
            "kind": None,
            "created_at": None,
            "updated_at": None,
            "facets": {},
            "visibility": {},
            "redacted": False,
            "frontmatter_readable": False,
            "content_available": False,
            "content_issue_code": boundary["reason"],
        }
    frontmatter = boundary["frontmatter"]
    if boundary["state"] == "redacted":
        # Privacy: a redacted zettel still appears in listings (so its existence is known), but its
        # content-bearing fields (title/kind/facets/visibility) are suppressed.
        return {
            "path": archive_relative_path(path, archive_root),
            "id": frontmatter.get("id"),
            "title": None,
            "status": "redacted",
            "kind": None,
            "created_at": frontmatter.get("created_at"),
            "updated_at": frontmatter.get("updated_at"),
            "facets": {},
            "visibility": {},
            "redacted": True,
        }
    return {
        "path": archive_relative_path(path, archive_root),
        "id": frontmatter.get("id"),
        "title": frontmatter.get("title"),
        "status": frontmatter.get("status", expected_status),
        "kind": frontmatter.get("kind"),
        "created_at": frontmatter.get("created_at"),
        "updated_at": frontmatter.get("updated_at"),
        "facets": frontmatter.get("facets", {}),
        "visibility": frontmatter.get("visibility", {}),
    }


def compact_zettel_overview_text(value: str, *, max_chars: int = ZETTEL_OVERVIEW_GIST_CHAR_LIMIT) -> str:
    text = re.sub(r"\s+", " ", value).strip()
    if len(text) <= max_chars:
        return text
    return text[: max_chars - 3].rstrip() + "..."


def safe_zettel_overview_string(value: Any, warnings: list[str], field_path: str) -> str | None:
    if value is None:
        return None
    text = compact_zettel_overview_text(str(value))
    if not text:
        return None
    if header_string_is_private_or_unsafe(text) or source_intake_has_provider_url(text) or source_intake_secret_like(text):
        warnings.append(f"Redacted private or unsafe first-read value in {field_path}.")
        return None
    return text


def markdown_body_overview_candidates(body: str) -> list[str]:
    candidates: list[str] = []
    in_fence = False
    current: list[str] = []
    for raw_line in normalize_text_for_block_hash(body).splitlines():
        stripped = raw_line.strip()
        if stripped.startswith("```") or stripped.startswith("~~~"):
            in_fence = not in_fence
            continue
        if in_fence:
            continue
        if not stripped:
            if current:
                candidates.append(" ".join(current))
                current = []
            continue
        if stripped.startswith("#"):
            continue
        if stripped.startswith(("|", ">", "![", "<")):
            continue
        cleaned = re.sub(r"^\s*[-*+]\s+", "", stripped)
        cleaned = re.sub(r"^\s*\d+[.)]\s+", "", cleaned)
        cleaned = re.sub(r"`([^`]+)`", r"\1", cleaned)
        cleaned = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", cleaned)
        if cleaned:
            current.append(cleaned)
    if current:
        candidates.append(" ".join(current))
    return candidates


def zettel_gist(frontmatter: dict[str, Any], body: str, warnings: list[str]) -> tuple[str | None, str]:
    for field in ZETTEL_OVERVIEW_FRONTMATTER_FIELDS:
        value = frontmatter.get(field)
        if isinstance(value, str):
            gist = safe_zettel_overview_string(value, warnings, f"$.frontmatter.{field}")
            if gist:
                return gist, f"frontmatter.{field}"
    for paragraph in markdown_body_overview_candidates(body):
        gist = safe_zettel_overview_string(paragraph, warnings, "$.body")
        if gist:
            return gist, "body.first_safe_paragraph"
    return None, "unavailable"


def safe_overview_facets(frontmatter: dict[str, Any], warnings: list[str]) -> dict[str, Any]:
    facets = frontmatter.get("facets")
    if not isinstance(facets, dict):
        return {}
    sanitized = sanitize_block_header_value(facets, warnings, "$.first_read.facets")
    return sanitized if isinstance(sanitized, dict) else {}


def safe_overview_edge_preview(edge: dict[str, Any], warnings: list[str], index: int) -> dict[str, Any]:
    edge_type = safe_zettel_overview_string(edge.get("type"), warnings, f"$.first_read.edges_preview[{index}].type")
    raw_target = edge.get("target") or edge.get("zettel_id") or edge.get("target_id")
    if raw_target is not None and not isinstance(raw_target, str):
        warnings.append(
            f"Redacted non-string edge target in $.first_read.edges_preview[{index}].target."
        )
        target = "<redacted-reference>"
    elif (
        isinstance(raw_target, str)
        and "sha256:" in raw_target.casefold()
        and OBJET_REF_TOKEN_RE.fullmatch(raw_target.strip()) is None
    ):
        warnings.append(
            f"Redacted incomplete or malformed objet reference in $.first_read.edges_preview[{index}].target."
        )
        target = "<redacted-reference>"
    else:
        target = safe_zettel_overview_string(
            raw_target,
            warnings,
            f"$.first_read.edges_preview[{index}].target",
        )
    if target is None and any(edge.get(key) for key in ("target", "zettel_id", "target_id")):
        target = "<redacted-reference>"
    target_kind = None
    if isinstance(target, str):
        if target.startswith("zet_"):
            target_kind = "zettel"
        elif target.startswith("objet:sha256:") or target.startswith("sha256:"):
            target_kind = "objet"
    return drop_none_values({"type": edge_type, "target": target, "target_kind": target_kind})


def zettel_first_read_summary(frontmatter: dict[str, Any], body: str, *, redacted: bool = False) -> tuple[dict[str, Any], list[str]]:
    warnings: list[str] = []
    zettel_id = frontmatter.get("id")
    status = frontmatter.get("status")
    if redacted:
        return (
            {
                "zettel_id": zettel_id,
                "title": None,
                "status": "redacted",
                "kind": None,
                "gist": None,
                "gist_source": "redacted",
                "gist_char_limit": ZETTEL_OVERVIEW_GIST_CHAR_LIMIT,
                "facets": {},
                "tie_summary": {
                    "edge_count": 0,
                    "edge_types": [],
                    "referenced_zets_count": 0,
                    "referenced_objets_count": 0,
                    "referenced_receipts_count": 0,
                },
                "edges_preview": [],
                "redacted": True,
                "body_omitted": True,
            },
            warnings,
        )

    title = safe_zettel_overview_string(frontmatter.get("title"), warnings, "$.frontmatter.title")
    kind = safe_zettel_overview_string(frontmatter.get("kind"), warnings, "$.frontmatter.kind")
    gist, gist_source = zettel_gist(frontmatter, body, warnings)
    edges = frontmatter.get("edges") if isinstance(frontmatter.get("edges"), list) else []
    edge_dicts = [edge for edge in edges if isinstance(edge, dict)]
    edge_types = sorted(
        {
            str(edge.get("type")).strip()
            for edge in edge_dicts
            if edge.get("type") and not header_string_is_private_or_unsafe(str(edge.get("type")))
        }
    )
    referenced_zets = collect_referenced_zets(frontmatter)
    tie_summary_objet_ids = collect_tie_summary_objet_ids(frontmatter)
    referenced_receipts = collect_referenced_receipts(frontmatter)
    return (
        {
            "zettel_id": zettel_id,
            "title": title,
            "status": status,
            "kind": kind,
            "gist": gist,
            "gist_source": gist_source,
            "gist_char_limit": ZETTEL_OVERVIEW_GIST_CHAR_LIMIT,
            "facets": safe_overview_facets(frontmatter, warnings),
            "tie_summary": {
                "edge_count": len(edge_dicts),
                "edge_types": edge_types,
                "referenced_zets_count": len(referenced_zets),
                "referenced_objets_count": len(tie_summary_objet_ids),
                "referenced_receipts_count": len(referenced_receipts),
            },
            "edges_preview": [safe_overview_edge_preview(edge, warnings, index) for index, edge in enumerate(edge_dicts[:10])],
            "redacted": False,
            "body_omitted": True,
        },
        warnings,
    )


def zettel_overview_frontmatter(frontmatter: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": frontmatter.get("id"),
        "title": frontmatter.get("title"),
        "status": frontmatter.get("status"),
        "kind": frontmatter.get("kind"),
        "created_at": frontmatter.get("created_at"),
        "updated_at": frontmatter.get("updated_at"),
        "facets": frontmatter.get("facets") if isinstance(frontmatter.get("facets"), dict) else {},
        "visibility": frontmatter.get("visibility") if isinstance(frontmatter.get("visibility"), dict) else {},
    }


def read_zettel(
    archive_root: Path | str,
    *,
    zettel_id: str | None = None,
    relative_path: str | None = None,
    section: str = "body",
    body_cursor: int = 0,
    body_max_chars: int | None = None,
    expected_body_sha256: str | None = None,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    if not zettel_id and not relative_path:
        raise ArchiveServiceError("Provide zettel_id or path.")
    if section not in ZETTEL_READ_SECTIONS:
        raise ArchiveServiceError("section must be one of: overview, body, document, details, all")
    if isinstance(body_cursor, bool) or not isinstance(body_cursor, int) or body_cursor < 0:
        raise ArchiveServiceError("body_cursor must be a non-negative integer.")
    if body_max_chars is not None:
        if isinstance(body_max_chars, bool) or not isinstance(body_max_chars, int):
            raise ArchiveServiceError("body_max_chars must be an integer.")
        if body_max_chars < 1 or body_max_chars > ZETTEL_READ_BODY_MAX_CHARS:
            raise ArchiveServiceError(
                f"body_max_chars must be between 1 and {ZETTEL_READ_BODY_MAX_CHARS}."
            )
    if body_cursor and body_max_chars is None:
        raise ArchiveServiceError("body_cursor requires body_max_chars.")
    if body_cursor and expected_body_sha256 is None:
        raise ArchiveServiceError(
            "body_cursor greater than zero requires expected_body_sha256 from the first page."
        )
    if expected_body_sha256 is not None:
        if not isinstance(expected_body_sha256, str) or not re.fullmatch(
            r"sha256:[0-9a-f]{64}", expected_body_sha256
        ):
            raise ArchiveServiceError("expected_body_sha256 must use sha256:<64 lowercase hex> syntax.")
        if body_max_chars is None:
            raise ArchiveServiceError("expected_body_sha256 requires body_max_chars.")
    page_requested = body_max_chars is not None
    if page_requested and section not in {"body", "document", "all"}:
        raise ArchiveServiceError("body paging requires section body, document, or all.")

    path = resolve_zettel_path(root, zettel_id=zettel_id, relative_path=relative_path)
    try:
        raw_bytes = path.read_bytes()
        text = raw_bytes.decode("utf-8")
    except (OSError, UnicodeError):
        raise ArchiveServiceError(
            "Zettel content is unavailable because it could not be read safely."
        ) from None
    boundary = parse_zettel_content_boundary(text)
    if boundary["state"] == "blocked":
        raise ArchiveServiceError(
            "Zettel content is unavailable because its frontmatter could not be validated."
        )
    frontmatter = boundary["frontmatter"]
    body = boundary["body"]
    if boundary["state"] == "redacted":
        # Privacy: a redacted zettel's body and frontmatter are suppressed on read; only its id and
        # redacted status are returned so callers can see it exists without exposing the content.
        overview, overview_warnings = zettel_first_read_summary(frontmatter, "", redacted=True)
        return {
            "path": archive_relative_path(path, root),
            "frontmatter": {"id": frontmatter.get("id"), "status": "redacted"},
            "body": "",
            "section": section,
            "overview": overview,
            "viewer_mode": "redacted",
            "frontmatter_hidden": True,
            "raw_frontmatter_delimiters_echoed": False,
            "redacted": True,
            "integrity": {
                "suppressed_for_redacted": True,
                "file_sha256": None,
                "body_sha256": None,
            },
            "warnings": overview_warnings,
        }
    overview, overview_warnings = zettel_first_read_summary(frontmatter, body)
    include_body = section in {"body", "document", "all"}
    include_full_frontmatter = section in {"body", "details", "all"}
    body_sha256 = "sha256:" + hashlib.sha256(body.encode("utf-8")).hexdigest()
    if expected_body_sha256 is not None and expected_body_sha256 != body_sha256:
        raise ArchiveServiceError(
            "body snapshot changed: expected_body_sha256 does not match the current decoded body."
        )
    body_page: dict[str, Any] | None = None
    returned_body = body if include_body else ""
    if page_requested:
        assert body_max_chars is not None
        if body_cursor > len(body):
            raise ArchiveServiceError("body_cursor must not exceed the current decoded body length.")
        page_end = min(len(body), body_cursor + body_max_chars)
        returned_body = body[body_cursor:page_end]
        complete = page_end >= len(body)
        body_page = {
            "unit": "unicode_code_points",
            "cursor": body_cursor,
            "max_chars": body_max_chars,
            "returned_chars": len(returned_body),
            "total_chars": len(body),
            "complete": complete,
            "next_cursor": None if complete else page_end,
            "body_sha256": body_sha256,
        }
    display_projection: dict[str, Any] | None = None
    if section == "document" and include_body and not page_requested:
        projected = project_wom_safe_markdown(returned_body)
        returned_body = str(projected["text"])
        projection_metadata = projected["metadata"]
        display_projection = {
            "profile": projection_metadata["profile"],
            "schema": projection_metadata["schema"],
            "display_only": True,
            "canonical_source_unchanged": True,
            "projection_applied": True,
            "projection_changed_text": bool(projection_metadata["changed"]),
            "source_body_sha256": (
                "sha256:" + str(projection_metadata["source_sha256"])
            ),
            "projected_body_sha256": (
                "sha256:" + str(projection_metadata["projected_sha256"])
            ),
            "marker_counts": dict(projection_metadata["counts"]),
            "source_body_available_via": "section=body",
        }
    if body_page is not None:
        body_page["display_projection_state"] = (
            "deferred_until_complete_body"
        )
        body_page["display_projection_reason"] = (
            "page_boundary_context_incomplete"
        )

    result = {
        "path": archive_relative_path(path, root),
        "frontmatter": frontmatter if include_full_frontmatter else zettel_overview_frontmatter(frontmatter),
        "body": returned_body,
        "section": section,
        "overview": overview,
        "body_omitted": not include_body,
        "details_omitted": not include_full_frontmatter,
        "viewer_mode": "human_document" if section == "document" else "structured_read",
        "frontmatter_hidden": not include_full_frontmatter,
        "raw_frontmatter_delimiters_echoed": False,
        "redacted": False,
        "integrity": {
            "suppressed_for_redacted": False,
            "file_sha256": "sha256:" + hashlib.sha256(raw_bytes).hexdigest(),
            "body_sha256": body_sha256,
            "exact_file_bytes_hashed": True,
            "body_hash_basis": "decoded_canonical_body_before_section_omission",
            "body_text_returned": include_body,
            "returned_body_sha256": (
                "sha256:" + hashlib.sha256(returned_body.encode("utf-8")).hexdigest()
                if include_body
                else None
            ),
            "returned_body_is_display_projection": display_projection is not None,
        },
        "warnings": unique_preserve_order(overview_warnings),
    }
    if body_page is not None:
        result["body_page"] = body_page
    if display_projection is not None:
        result["display"] = display_projection
    return result


def zet_catalog_paths(root: Path, status: str) -> list[tuple[Path, str]]:
    if status not in {"all", "draft", "canonical"}:
        raise ArchiveServiceError("status must be one of: all, draft, canonical")
    if status == "all":
        folders = [("zettels", "canonical"), ("inbox", "draft")]
    elif status == "draft":
        folders = [("inbox", "draft")]
    else:
        folders = [("zettels", "canonical")]

    paths: list[tuple[Path, str]] = []
    for folder, expected_status in folders:
        folder_root = root / folder
        if folder_root.is_dir():
            paths.extend(
                (path, expected_status)
                for path in safe_archive_glob(folder_root, "*.md", root, recursive=True)
            )
    return sorted(paths, key=lambda item: archive_relative_path(item[0], root))


def zet_catalog_abstract(
    frontmatter: dict[str, Any],
    warnings: list[str],
) -> tuple[str | None, str, str, bool]:
    for field in ZETTEL_OVERVIEW_FRONTMATTER_FIELDS:
        value = frontmatter.get(field)
        if not isinstance(value, str):
            continue
        compact = re.sub(r"\s+", " ", value).strip()
        abstract = safe_zettel_overview_string(value, warnings, f"$.frontmatter.{field}")
        if abstract:
            return (
                abstract,
                f"frontmatter.{field}",
                "explicit" if field == "abstract" else "compatibility_field",
                len(compact) > ZET_ABSTRACT_MAX_CHARS,
            )
    return None, "unavailable", "missing", False


def zet_catalog_item(path: Path, root: Path, expected_status: str) -> dict[str, Any]:
    relative = archive_relative_path(path, root)
    inspection = inspect_zettel_frontmatter_boundary(path)
    frontmatter = inspection["frontmatter"]
    if not inspection["metadata_readable"]:
        return {
            "path": relative,
            "id": None,
            "status": ZETTEL_QUARANTINED_STATUS,
            "title": None,
            "kind": None,
            "created_at": None,
            "updated_at": None,
            "abstract": None,
            "abstract_source": "unavailable",
            "abstract_status": "frontmatter_unreadable",
            "abstract_char_count": 0,
            "abstract_truncated": False,
            "facets": {},
            "tie_summary": {
                "edge_count": 0,
                "edge_types": [],
                "referenced_zets_count": 0,
                "referenced_objets_count": 0,
                "referenced_receipts_count": 0,
            },
            "edges": [],
            "edges_complete": True,
            "redacted": False,
            "frontmatter_readable": False,
            "body_read": bool(inspection.get("body_text_read")),
            "warnings": [
                "Zet frontmatter could not be validated.",
                str(inspection.get("issue_code") or "frontmatter_unreadable"),
            ],
        }

    safe_frontmatter = frontmatter
    raw_status = str(safe_frontmatter.get("status"))
    redacted = raw_status == "redacted"
    if redacted:
        safe_frontmatter = redacted_zettel_safe_frontmatter(frontmatter)
        return {
            "path": relative,
            "id": safe_frontmatter.get("id"),
            "status": "redacted",
            "title": None,
            "kind": None,
            "created_at": safe_frontmatter.get("created_at"),
            "updated_at": safe_frontmatter.get("updated_at"),
            "abstract": None,
            "abstract_source": "redacted",
            "abstract_status": "redacted",
            "abstract_char_count": 0,
            "abstract_truncated": False,
            "facets": {},
            "tie_summary": {
                "edge_count": 0,
                "edge_types": [],
                "referenced_zets_count": 0,
                "referenced_objets_count": 0,
                "referenced_receipts_count": 0,
            },
            "edges": [],
            "edges_complete": True,
            "redacted": True,
            "frontmatter_readable": True,
            "body_read": False,
            "warnings": [],
        }

    warnings: list[str] = []
    title = safe_zettel_overview_string(safe_frontmatter.get("title"), warnings, "$.frontmatter.title")
    kind = safe_zettel_overview_string(safe_frontmatter.get("kind"), warnings, "$.frontmatter.kind")
    abstract, abstract_source, abstract_status, abstract_truncated = zet_catalog_abstract(safe_frontmatter, warnings)
    edges = safe_frontmatter.get("edges") if isinstance(safe_frontmatter.get("edges"), list) else []
    edge_dicts = [edge for edge in edges if isinstance(edge, dict)]
    edge_types = sorted(
        {
            str(edge.get("type")).strip()
            for edge in edge_dicts
            if edge.get("type") and not header_string_is_private_or_unsafe(str(edge.get("type")))
        }
    )
    referenced_zets = collect_referenced_zets(safe_frontmatter)
    tie_summary_objet_ids = collect_tie_summary_objet_ids(safe_frontmatter)
    referenced_receipts = collect_referenced_receipts(safe_frontmatter)
    safe_edges = [safe_overview_edge_preview(edge, warnings, index) for index, edge in enumerate(edge_dicts)]
    return {
        "path": relative,
        "id": safe_frontmatter.get("id") or path.stem,
        "status": raw_status,
        "title": title,
        "kind": kind,
        "created_at": safe_frontmatter.get("created_at"),
        "updated_at": safe_frontmatter.get("updated_at"),
        "abstract": abstract,
        "abstract_source": abstract_source,
        "abstract_status": abstract_status,
        "abstract_char_count": len(abstract) if abstract else 0,
        "abstract_truncated": abstract_truncated,
        "facets": safe_overview_facets(safe_frontmatter, warnings),
        "tie_summary": {
            "edge_count": len(edge_dicts),
            "edge_types": edge_types,
            "referenced_zets_count": len(referenced_zets),
            "referenced_objets_count": len(tie_summary_objet_ids),
            "referenced_receipts_count": len(referenced_receipts),
        },
        "edges": safe_edges,
        "edges_complete": True,
        "redacted": False,
        "frontmatter_readable": True,
        "body_read": False,
        "warnings": unique_preserve_order(warnings),
    }


def zet_catalog_entries(
    root: Path,
    path_entries: list[tuple[Path, str]],
    item_cache: dict[str, dict[str, Any]] | None,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> tuple[list[tuple[Path, str, dict[str, Any], tuple[int, int] | None]], dict[str, Any]]:
    active_cache_keys: set[str] = set()
    cached_items_reused = 0
    resolved_items: list[dict[str, Any] | None] = [None] * len(path_entries)
    signatures: list[tuple[int, int] | None] = [None] * len(path_entries)
    misses: list[tuple[int, Path, str, str, tuple[int, int] | None]] = []
    path_total = len(path_entries)
    if progress_callback is not None:
        progress_callback("catalog-path-metadata", "start", 0, path_total)
    for index, (path, expected_status) in enumerate(path_entries):
        relative = archive_relative_path(path, root)
        cache_key = f"{expected_status}:{relative}"
        active_cache_keys.add(cache_key)
        try:
            stat = path.stat()
            signature: tuple[int, int] | None = (stat.st_size, stat.st_mtime_ns)
        except OSError:
            signature = None
        signatures[index] = signature

        cached = item_cache.get(cache_key) if item_cache is not None else None
        if (
            cached is not None
            and signature is not None
            and cached.get("file_signature") == signature
            and isinstance(cached.get("item"), dict)
        ):
            resolved_items[index] = cached["item"]
            cached_items_reused += 1
        else:
            misses.append((index, path, expected_status, cache_key, signature))
        completed = index + 1
        if progress_callback is not None and (completed == 1 or completed == path_total or completed % 250 == 0):
            progress_callback("catalog-path-metadata", "scanned", completed, path_total)
    if progress_callback is not None:
        progress_callback("catalog-path-metadata", "done", path_total, path_total)

    worker_count = min(8, len(misses), max(1, os.cpu_count() or 1))

    def parse_missing(row: tuple[int, Path, str, str, tuple[int, int] | None]) -> tuple[int, str, tuple[int, int] | None, dict[str, Any]]:
        index, path, expected_status, cache_key, signature = row
        return index, cache_key, signature, zet_catalog_item(path, root, expected_status)

    miss_total = len(misses)
    if progress_callback is not None:
        progress_callback("catalog-frontmatter", "start", 0, miss_total)
    parsed_rows: list[tuple[int, str, tuple[int, int] | None, dict[str, Any]]] = []
    if worker_count > 1 and miss_total >= 64:
        with ThreadPoolExecutor(max_workers=worker_count, thread_name_prefix="wom-zet-catalog") as executor:
            for completed, parsed_row in enumerate(executor.map(parse_missing, misses), start=1):
                parsed_rows.append(parsed_row)
                if progress_callback is not None and (
                    completed == 1 or completed == miss_total or completed % 250 == 0
                ):
                    progress_callback("catalog-frontmatter", "scanned", completed, miss_total)
        scan_mode = "bounded_thread_pool"
    else:
        for completed, row in enumerate(misses, start=1):
            parsed_rows.append(parse_missing(row))
            if progress_callback is not None and (
                completed == 1 or completed == miss_total or completed % 250 == 0
            ):
                progress_callback("catalog-frontmatter", "scanned", completed, miss_total)
        scan_mode = "sequential"
    if progress_callback is not None:
        progress_callback("catalog-frontmatter", "done", miss_total, miss_total)

    for index, cache_key, signature, item in parsed_rows:
        resolved_items[index] = item
        if item_cache is not None and signature is not None:
            item_cache[cache_key] = {
                "file_signature": signature,
                "item": item,
            }

    entries: list[tuple[Path, str, dict[str, Any], tuple[int, int] | None]] = []
    for index, (path, expected_status) in enumerate(path_entries):
        item = resolved_items[index]
        if item is None:
            item = zet_catalog_item(path, root, expected_status)
            if item_cache is not None and signatures[index] is not None:
                relative = archive_relative_path(path, root)
                item_cache[f"{expected_status}:{relative}"] = {
                    "file_signature": signatures[index],
                    "item": item,
                }
        entries.append((path, expected_status, item, signatures[index]))

    if item_cache is not None:
        for cache_key in list(item_cache):
            if not cache_key.startswith("__") and cache_key not in active_cache_keys:
                del item_cache[cache_key]

    return entries, {
        "path_count": len(path_entries),
        "path_metadata_checked": len(path_entries),
        "frontmatter_files_scanned": len(misses),
        "frontmatter_scan_mode": scan_mode,
        "frontmatter_scan_workers": worker_count if scan_mode == "bounded_thread_pool" else 1,
        "cached_items_reused": cached_items_reused,
        "cache_mode": "process_local_ephemeral" if item_cache is not None else "none",
        "cache_authoritative": False,
        "cache_persisted": False,
    }


def zet_catalog_item_json(item: dict[str, Any]) -> str:
    return json.dumps(item, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def zet_catalog_project_item(
    item: dict[str, Any],
    projection: str,
    *,
    catalog_order_index: int | None = None,
    reading_route: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if projection == "full":
        return item
    projected = {
        "id": item.get("id"),
        "status": item.get("status"),
        "title": item.get("title"),
        "kind": item.get("kind"),
        "updated_at": item.get("updated_at"),
        "abstract": item.get("abstract"),
        "abstract_status": item.get("abstract_status"),
        "facets": item.get("facets") if isinstance(item.get("facets"), dict) else {},
        "tie_summary": item.get("tie_summary") if isinstance(item.get("tie_summary"), dict) else {},
        "edges": item.get("edges") if isinstance(item.get("edges"), list) else [],
    }
    if projection == "routed_reading":
        if catalog_order_index is not None:
            projected["catalog_order_index"] = catalog_order_index
        if isinstance(reading_route, dict):
            projected["reading_route"] = reading_route
    return projected


def zet_catalog_order_descriptor(order_mode: str) -> str:
    if order_mode == "seeded_connection_walk":
        return "seeded_undirected_connection_bfs_then_path_components"
    return "archive_relative_path_ascending"


def zet_catalog_normalize_seed_ids(seed_zettel_ids: list[str] | None, blockers: list[str]) -> list[str]:
    normalized: list[str] = []
    for raw_value in seed_zettel_ids or []:
        value = str(raw_value or "").strip()
        if not ZETTEL_EDGE_ZETTEL_ID_RE.match(value):
            blockers.append("Each start_zettel_id must be a safe zet id.")
            continue
        if value not in normalized:
            normalized.append(value)
    if len(normalized) > ZET_CATALOG_MAX_SEED_IDS:
        blockers.append(f"At most {ZET_CATALOG_MAX_SEED_IDS} unique start_zettel_id values may be provided.")
    return normalized[:ZET_CATALOG_MAX_SEED_IDS]


def zet_catalog_order_entries(
    entries: list[tuple[Path, str, dict[str, Any], tuple[int, int] | None]],
    *,
    order_mode: str,
    seed_zettel_ids: list[str],
) -> tuple[
    list[tuple[Path, str, dict[str, Any], tuple[int, int] | None]],
    dict[str, Any],
    list[dict[str, Any] | None],
]:
    if order_mode == "path":
        return (
            entries,
            {
                "mode": "path",
                "descriptor": zet_catalog_order_descriptor(order_mode),
                "seed_zettel_ids": [],
                "resolved_seed_ids": [],
                "missing_seed_ids": [],
                "seed_connected_prefix_count": 0,
                "fallback_component_count": 0,
                "connection_direction_for_ordering": "not_used",
                "item_route_evidence_in_routed_reading_projection": False,
                "all_nodes_preserved": True,
                "ranking_performed": False,
                "global_map_persisted": False,
            },
            [None for _entry in entries],
        )

    id_to_indices: dict[str, list[int]] = {}
    for index, (_path, _status, item, _signature) in enumerate(entries):
        zettel_id = item.get("id")
        if isinstance(zettel_id, str) and ZETTEL_EDGE_ZETTEL_ID_RE.match(zettel_id):
            id_to_indices.setdefault(zettel_id, []).append(index)

    missing_seed_ids = [zettel_id for zettel_id in seed_zettel_ids if zettel_id not in id_to_indices]
    adjacency: list[dict[int, list[dict[str, Any]]]] = [{} for _entry in entries]
    for source_index, (_path, _status, item, _signature) in enumerate(entries):
        source_zettel_id = item.get("id")
        if not isinstance(source_zettel_id, str) or not ZETTEL_EDGE_ZETTEL_ID_RE.match(source_zettel_id):
            continue
        edges = item.get("edges") if isinstance(item.get("edges"), list) else []
        for edge in edges:
            if not isinstance(edge, dict):
                continue
            target = edge.get("target")
            if not isinstance(target, str) or not ZETTEL_EDGE_ZETTEL_ID_RE.match(target):
                continue
            edge_type = edge.get("type") if isinstance(edge.get("type"), str) else None
            for target_index in id_to_indices.get(target, []):
                if target_index == source_index:
                    continue
                forward = {
                    "edge_type": edge_type,
                    "stored_source_zettel_id": source_zettel_id,
                    "stored_target_zettel_id": target,
                    "walk_direction": "with_stored_direction",
                }
                reverse = {
                    **forward,
                    "walk_direction": "against_stored_direction",
                }
                adjacency[source_index].setdefault(target_index, []).append(forward)
                adjacency[target_index].setdefault(source_index, []).append(reverse)

    visited: set[int] = set()
    ordered_indices: list[int] = []
    route_by_index: dict[int, dict[str, Any]] = {}
    order_position_by_index: dict[int, int] = {}

    def passage_sort_key(passage: dict[str, Any]) -> tuple[str, str, str, str]:
        return (
            str(passage.get("edge_type") or ""),
            str(passage.get("stored_source_zettel_id") or ""),
            str(passage.get("stored_target_zettel_id") or ""),
            str(passage.get("walk_direction") or ""),
        )

    def walk(root_indices: list[int], *, phase: str, fallback_component_index: int | None) -> None:
        discovered = set(visited)
        queue: list[tuple[int, int | None, int]] = []
        for index in root_indices:
            if index in discovered:
                continue
            discovered.add(index)
            queue.append((index, None, 0))
        queue_offset = 0
        while queue_offset < len(queue):
            index, parent_index, distance = queue[queue_offset]
            queue_offset += 1
            if index in visited:
                continue
            visited.add(index)
            catalog_order_index = len(ordered_indices)
            ordered_indices.append(index)
            order_position_by_index[index] = catalog_order_index
            route: dict[str, Any] = {
                "reason": (
                    "verified_seed"
                    if parent_index is None and phase == "verified_seed_prefix"
                    else "fallback_component_root"
                    if parent_index is None
                    else "connection_passage"
                ),
                "distance": distance,
            }
            if fallback_component_index is not None:
                route["component_index"] = fallback_component_index
            if parent_index is not None:
                passages = sorted(adjacency[parent_index].get(index, []), key=passage_sort_key)
                selected_passage = passages[0] if passages else {}
                parent_item = entries[parent_index][2]
                via = {
                    "edge_type": selected_passage.get("edge_type"),
                    "walk_direction": selected_passage.get("walk_direction"),
                }
                if len(passages) > 1:
                    via["parallel_candidate_count"] = len(passages)
                route.update(
                    {
                        "from_catalog_order_index": order_position_by_index[parent_index],
                        "from_zettel_id": parent_item.get("id"),
                        "via": via,
                    }
                )
            route_by_index[index] = route
            for neighbor in sorted(adjacency[index]):
                if neighbor in discovered:
                    continue
                discovered.add(neighbor)
                queue.append((neighbor, index, distance + 1))

    seed_indices: list[int] = []
    for zettel_id in seed_zettel_ids:
        seed_indices.extend(id_to_indices.get(zettel_id, []))
    walk(seed_indices, phase="verified_seed_prefix", fallback_component_index=None)
    seed_connected_prefix_count = len(ordered_indices)

    fallback_component_count = 0
    for index in range(len(entries)):
        if index in visited:
            continue
        fallback_component_count += 1
        walk(
            [index],
            phase="fallback_component",
            fallback_component_index=fallback_component_count,
        )

    ordered_entries = [entries[index] for index in ordered_indices]
    ordered_routes = [route_by_index.get(index) for index in ordered_indices]
    return (
        ordered_entries,
        {
            "mode": order_mode,
            "descriptor": zet_catalog_order_descriptor(order_mode),
            "seed_zettel_ids": seed_zettel_ids,
            "resolved_seed_ids": [zettel_id for zettel_id in seed_zettel_ids if zettel_id in id_to_indices],
            "missing_seed_ids": missing_seed_ids,
            "seed_entry_count": len(seed_indices),
            "seed_connected_prefix_count": seed_connected_prefix_count,
            "fallback_component_count": fallback_component_count,
            "connection_passage_count": sum(len(neighbors) for neighbors in adjacency) // 2,
            "connection_direction_for_ordering": "undirected_reading_passage_only",
            "item_route_evidence_in_routed_reading_projection": True,
            "item_route_evidence_count": len(ordered_routes),
            "edge_meaning_or_direction_rewritten": False,
            "all_nodes_preserved": len(ordered_entries) == len(entries),
            "ranking_performed": False,
            "global_map_persisted": False,
        },
        ordered_routes,
    )


def zet_catalog_encode_continuation(payload: dict[str, Any]) -> str:
    raw = json.dumps(payload, ensure_ascii=True, sort_keys=True, separators=(",", ":")).encode("utf-8")
    encoded = base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")
    checksum = hashlib.sha256(raw).hexdigest()
    return f"{encoded}.{checksum}"


def zet_catalog_decode_continuation(token: str) -> dict[str, Any]:
    text = str(token or "").strip()
    if not text or "." not in text or len(text) > 4096:
        raise ValueError("continuation token shape is invalid")
    encoded, checksum = text.rsplit(".", 1)
    if not re.match(r"^[0-9a-f]{64}$", checksum):
        raise ValueError("continuation token checksum is invalid")
    padding = "=" * (-len(encoded) % 4)
    try:
        raw = base64.urlsafe_b64decode((encoded + padding).encode("ascii"))
    except (ValueError, UnicodeEncodeError, binascii.Error) as exc:
        raise ValueError("continuation token encoding is invalid") from exc
    if not hmac.compare_digest(hashlib.sha256(raw).hexdigest(), checksum):
        raise ValueError("continuation token checksum does not match")
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("continuation token payload is invalid") from exc
    if not isinstance(payload, dict) or payload.get("schema") != ZET_CATALOG_CONTINUATION_SCHEMA:
        raise ValueError("continuation token schema is invalid")
    return payload


def zet_catalog_continuation_context(
    *,
    coverage_mode: str,
    continuation_token: str | None,
    cursor: int,
    status: str,
    projection: str,
    order_descriptor: str,
    seed_zettel_ids: list[str],
    expected_snapshot_id: str | None,
    blockers: list[str],
) -> tuple[dict[str, Any] | None, str | None]:
    if coverage_mode != "strict":
        if continuation_token:
            blockers.append("continuation_token requires coverage_mode=strict.")
        return None, expected_snapshot_id

    if cursor == 0:
        if continuation_token:
            blockers.append("A strict catalog pass must start at cursor 0 without a continuation token.")
        return None, expected_snapshot_id
    if not continuation_token:
        blockers.append("Strict catalog continuation requires the continuation token returned by the prior page.")
        return None, expected_snapshot_id

    try:
        payload = zet_catalog_decode_continuation(continuation_token)
    except ValueError as exc:
        blockers.append(f"Strict catalog continuation token is invalid: {exc}.")
        return None, expected_snapshot_id

    token_snapshot = payload.get("snapshot_id")
    if payload.get("status_filter") != status:
        blockers.append("Strict catalog continuation status filter does not match the prior page.")
    if payload.get("projection") != projection:
        blockers.append("Strict catalog continuation projection does not match the prior page.")
    if payload.get("order") != order_descriptor:
        blockers.append("Strict catalog continuation order does not match the catalog order.")
    if payload.get("seed_zettel_ids_sha256") != sha256_json_value(seed_zettel_ids):
        blockers.append("Strict catalog continuation seed ids do not match the prior page.")
    if payload.get("entry_identity_basis") != ZET_CATALOG_ENTRY_IDENTITY_BASIS:
        blockers.append("Strict catalog continuation entry identity basis does not match.")
    token_next_cursor = payload.get("next_cursor")
    token_covered_count = payload.get("covered_count")
    if (
        not isinstance(token_next_cursor, int)
        or isinstance(token_next_cursor, bool)
        or not isinstance(token_covered_count, int)
        or isinstance(token_covered_count, bool)
        or token_next_cursor != cursor
        or token_covered_count != cursor
    ):
        blockers.append("Strict catalog continuation cursor does not match the prior page.")
    if not isinstance(token_snapshot, str) or not re.match(r"^sha256:[0-9a-f]{64}$", token_snapshot):
        blockers.append("Strict catalog continuation snapshot id is invalid.")
    elif expected_snapshot_id and expected_snapshot_id != token_snapshot:
        blockers.append("expected_snapshot_id does not match the strict continuation token.")
    else:
        expected_snapshot_id = token_snapshot
    chain_hash = payload.get("chain_hash")
    if not isinstance(chain_hash, str) or not re.match(r"^sha256:[0-9a-f]{64}$", chain_hash):
        blockers.append("Strict catalog continuation chain hash is invalid.")
    return payload, expected_snapshot_id


def zet_catalog_estimated_tokens_from_chars(char_count: int) -> int:
    if char_count <= 0:
        return 0
    return max(1, (char_count + 3) // 4)


def zet_catalog_workload_estimate(items: list[dict[str, Any]]) -> dict[str, int]:
    abstract_chars = sum(
        len(item["abstract"])
        if isinstance(item.get("abstract"), str)
        else int(item.get("abstract_char_count") or 0)
        for item in items
    )
    payload = "[" + ",".join(zet_catalog_item_json(item) for item in items) + "]"
    payload_chars = len(payload)
    return {
        "item_count": len(items),
        "abstract_chars": abstract_chars,
        "estimated_abstract_tokens": zet_catalog_estimated_tokens_from_chars(abstract_chars),
        "items_json_chars": payload_chars,
        "items_json_utf8_bytes": len(payload.encode("utf-8")),
        "estimated_items_json_tokens": zet_catalog_estimated_tokens_from_chars(payload_chars),
    }


def zet_catalog_response_measurement(result: dict[str, Any]) -> dict[str, Any]:
    probe = dict(result)
    workload = dict(probe.get("workload_estimate", {}))
    workload.pop("response", None)
    probe["workload_estimate"] = workload
    payload = json.dumps(probe, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    items = probe.get("items") if isinstance(probe.get("items"), list) else []
    items_payload = "[" + ",".join(zet_catalog_item_json(item) for item in items if isinstance(item, dict)) + "]"
    payload_chars = len(payload)
    payload_bytes = len(payload.encode("utf-8"))
    items_chars = len(items_payload)
    items_bytes = len(items_payload.encode("utf-8"))
    envelope_chars = max(0, payload_chars - items_chars)
    envelope_bytes = max(0, payload_bytes - items_bytes)
    return {
        "basis": "compact_sorted_service_result_json_excluding_this_measurement",
        "provider_reported": False,
        "service_result_json_chars": payload_chars,
        "service_result_json_utf8_bytes": payload_bytes,
        "estimated_service_result_json_tokens": zet_catalog_estimated_tokens_from_chars(payload_chars),
        "items_json_chars": items_chars,
        "estimated_items_json_tokens": zet_catalog_estimated_tokens_from_chars(items_chars),
        "response_envelope_json_chars": envelope_chars,
        "response_envelope_json_utf8_bytes": envelope_bytes,
        "estimated_response_envelope_tokens": zet_catalog_estimated_tokens_from_chars(envelope_chars),
        "includes_this_measurement": False,
        "includes_cli_pretty_print_whitespace": False,
        "includes_mcp_jsonrpc_envelope": False,
        "includes_zet_bodies": False,
    }


def zet_catalog_budgeted_page(
    items: list[dict[str, Any]],
    *,
    max_estimated_tokens: int | None,
) -> tuple[list[dict[str, Any]], bool, bool]:
    if max_estimated_tokens is None:
        return items, False, False

    selected: list[dict[str, Any]] = []
    payload_chars = 2
    single_item_exceeds_budget = False
    stopped_for_budget = False
    for item in items:
        item_chars = len(zet_catalog_item_json(item))
        candidate_payload_chars = payload_chars + item_chars + (1 if selected else 0)
        candidate_tokens = zet_catalog_estimated_tokens_from_chars(candidate_payload_chars)
        if selected and candidate_tokens > max_estimated_tokens:
            stopped_for_budget = True
            break
        selected.append(item)
        payload_chars = candidate_payload_chars
        if len(selected) == 1 and candidate_tokens > max_estimated_tokens:
            single_item_exceeds_budget = True
            stopped_for_budget = len(items) > 1
            break
    return selected, stopped_for_budget, single_item_exceeds_budget


def zet_catalog_snapshot(
    root: Path,
    entries: list[tuple[Path, str, dict[str, Any], tuple[int, int] | None]],
) -> dict[str, Any]:
    evidence: list[dict[str, Any]] = []
    for path, _expected_status, item, signature in entries:
        file_size = signature[0] if signature is not None else None
        file_mtime_ns = signature[1] if signature is not None else None
        evidence.append(
            {
                "path": archive_relative_path(path, root),
                "file_size": file_size,
                "file_mtime_ns": file_mtime_ns,
                "id": item.get("id"),
                "updated_at": item.get("updated_at"),
                "abstract_status": item.get("abstract_status"),
                "abstract_sha256": "sha256:" + sha256_text(item["abstract"]) if item.get("abstract") else None,
                "edge_count": item.get("tie_summary", {}).get("edge_count", 0),
            }
        )
    return {
        "id": sha256_json_value(evidence),
        "basis": "path_size_mtime_frontmatter_projection",
        "frontmatter_projection_hashed": True,
        "body_content_hashed": False,
        "item_count": len(evidence),
    }


def zet_catalog_abstract_coverage(
    entries: list[tuple[Path, str, dict[str, Any], tuple[int, int] | None]],
) -> dict[str, Any]:
    counts = {
        "explicit": 0,
        "compatibility_field": 0,
        "missing": 0,
        "redacted": 0,
        "frontmatter_unreadable": 0,
    }
    for _path, _expected_status, item, _signature in entries:
        abstract_status = str(item.get("abstract_status") or "missing")
        counts[abstract_status] = counts.get(abstract_status, 0) + 1

    readable_count = counts["explicit"] + counts["compatibility_field"]
    redacted_count = counts["redacted"]
    required_count = max(0, len(entries) - redacted_count)
    gap_count = counts["missing"] + counts["frontmatter_unreadable"]
    return {
        "selected_entry_count": len(entries),
        "first_read_required_count": required_count,
        "readable_first_read_count": readable_count,
        "first_read_gap_count": gap_count,
        "redacted_by_policy_count": redacted_count,
        "all_required_first_reads_available": gap_count == 0 and readable_count == required_count,
        "redacted_entries_excluded_from_requirement": True,
        "counts": counts,
    }


def zet_catalog_identity_coverage(
    entries: list[tuple[Path, str, dict[str, Any], tuple[int, int] | None]],
) -> dict[str, Any]:
    safe_id_counts: dict[str, int] = {}
    unaddressable_entry_count = 0
    for _path, _expected_status, item, _signature in entries:
        zettel_id = item.get("id")
        if (
            not item.get("frontmatter_readable")
            or not isinstance(zettel_id, str)
            or not ZETTEL_EDGE_ZETTEL_ID_RE.match(zettel_id)
        ):
            unaddressable_entry_count += 1
            continue
        safe_id_counts[zettel_id] = safe_id_counts.get(zettel_id, 0) + 1

    duplicate_counts = [count for count in safe_id_counts.values() if count > 1]
    duplicate_entry_count = sum(duplicate_counts)
    all_entries_uniquely_addressable = (
        unaddressable_entry_count == 0
        and duplicate_entry_count == 0
        and len(safe_id_counts) == len(entries)
    )
    return {
        "selected_entry_count": len(entries),
        "safe_frontmatter_id_entry_count": len(entries) - unaddressable_entry_count,
        "unique_safe_id_count": len(safe_id_counts),
        "duplicate_id_value_count": len(duplicate_counts),
        "duplicate_id_entry_count": duplicate_entry_count,
        "unaddressable_entry_count": unaddressable_entry_count,
        "all_entries_uniquely_addressable": all_entries_uniquely_addressable,
        "paths_or_duplicate_id_values_echoed": False,
    }


def normalize_abstract_evidence_sha256(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    normalized = value.strip().lower()
    if re.fullmatch(r"sha256:[0-9a-f]{64}", normalized):
        return normalized
    if re.fullmatch(r"[0-9a-f]{64}", normalized):
        return "sha256:" + normalized
    return None


def normalize_abstract_evidence_canonical_path(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    try:
        normalized = normalize_archive_relative_path(value)
    except ArchivePathError:
        return None
    if not normalized.startswith("zettels/") or PurePosixPath(normalized).suffix.lower() != ".md":
        return None
    return normalized


def add_abstract_review_evidence(
    evidence_by_path: dict[str, dict[tuple[str, str], set[str]]],
    *,
    canonical_path: str,
    abstract_sha256: str,
    body_sha256: str,
    evidence_kind: str,
) -> bool:
    pairs = evidence_by_path.setdefault(canonical_path, {})
    kinds = pairs.setdefault((abstract_sha256, body_sha256), set())
    before = len(kinds)
    kinds.add(evidence_kind)
    return len(kinds) != before


def read_bounded_abstract_evidence_file(path: Path, max_bytes: int) -> bytes:
    if path.is_symlink() or not path.is_file():
        raise OSError("Evidence file is unavailable.")
    with path.open("rb") as handle:
        data = handle.read(max_bytes + 1)
    if len(data) > max_bytes:
        raise OSError("Evidence file exceeds the bounded read limit.")
    return data


def read_bounded_abstract_freshness_frontmatter(
    path: Path,
    max_file_bytes: int,
) -> dict[str, Any]:
    """Read only one bounded zet frontmatter block for freshness triage."""
    if path.is_symlink() or not path.is_file():
        raise OSError("Canonical zet is unavailable.")
    before = path.stat()
    if before.st_size > max_file_bytes:
        raise OSError("Canonical zet exceeds the bounded read limit.")

    with path.open("rb") as handle:
        first = handle.readline()
        if re.fullmatch(rb"---[ \t]*\r?\n", first.removeprefix(b"\xef\xbb\xbf")) is None:
            raise ValueError("Canonical zet frontmatter is unavailable.")
        frontmatter_lines: list[bytes] = []
        bytes_read = len(first)
        while True:
            line = handle.readline()
            if not line:
                raise ValueError("Canonical zet frontmatter is not terminated.")
            bytes_read += len(line)
            if bytes_read > max_file_bytes:
                raise OSError("Canonical zet frontmatter exceeds the bounded read limit.")
            if re.fullmatch(rb"---[ \t]*\r?\n", line) is not None:
                break
            frontmatter_lines.append(line)

    after = path.stat()
    if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
        raise OSError("Canonical zet changed during frontmatter inspection.")
    try:
        frontmatter = load_yaml(b"".join(frontmatter_lines).decode("utf-8"))
    except Exception as exc:
        raise ValueError("Canonical zet frontmatter is unreadable.") from exc
    if not isinstance(frontmatter, dict):
        raise ValueError("Canonical zet frontmatter must be an object.")
    if frontmatter.get("status") not in {"canonical", "redacted"}:
        raise ValueError("Canonical zet frontmatter status is invalid.")
    return frontmatter


def parse_abstract_evidence_zettel_bytes(data: bytes) -> tuple[dict[str, Any], str] | None:
    try:
        return require_readable_zettel_text(decode_utf8_with_universal_newlines(data))
    except Exception:
        return None


def legacy_publication_abstract_evidence(
    root: Path,
    receipt: dict[str, Any],
) -> tuple[str, str, str, str] | None:
    action = receipt.get("action")
    if action not in {"mint_zettel", "promote_zettel"} or receipt.get("dry_run") is not False:
        return None
    target = receipt.get("target") if isinstance(receipt.get("target"), dict) else {}
    canonical_path = normalize_abstract_evidence_canonical_path(target.get("path"))
    first_read_check = (
        receipt.get("first_read_check")
        if isinstance(receipt.get("first_read_check"), dict)
        else {}
    )
    abstract_sha256 = normalize_abstract_evidence_sha256(
        first_read_check.get("abstract_sha256")
    )
    if (
        canonical_path is None
        or first_read_check.get("contract") != "wom-kit/explicit-abstract-publication/v0.1"
        or first_read_check.get("ready_for_publication") is not True
        or abstract_sha256 is None
    ):
        return None

    source = receipt.get("source") if isinstance(receipt.get("source"), dict) else {}
    if action == "mint_zettel":
        evidence_ref = receipt.get("snapshot") if isinstance(receipt.get("snapshot"), dict) else {}
        evidence_path_value = evidence_ref.get("path")
        expected_sha256 = normalize_abstract_evidence_sha256(evidence_ref.get("sha256"))
        source_sha256 = normalize_abstract_evidence_sha256(source.get("sha256"))
        required_prefix = f"{MINT_DRAFT_SNAPSHOTS_DIR}/"
        evidence_kind = "legacy_mint_snapshot"
        if expected_sha256 is None or expected_sha256 != source_sha256:
            return None
    else:
        evidence_ref = source
        evidence_path_value = evidence_ref.get("path")
        expected_sha256 = normalize_abstract_evidence_sha256(evidence_ref.get("sha256"))
        required_prefix = "inbox/"
        evidence_kind = "legacy_promotion_source"
        if expected_sha256 is None:
            return None

    if not isinstance(evidence_path_value, str):
        return None
    try:
        evidence_relative = normalize_archive_relative_path(evidence_path_value)
        if not evidence_relative.startswith(required_prefix):
            return None
        evidence_path = resolve_archive_relative_path(root, evidence_relative)
        raw_bytes = read_bounded_abstract_evidence_file(
            evidence_path, ABSTRACT_FRESHNESS_MAX_ZET_BYTES
        )
        if "sha256:" + hashlib.sha256(raw_bytes).hexdigest() != expected_sha256:
            return None
        parsed = parse_abstract_evidence_zettel_bytes(raw_bytes)
        if parsed is None:
            return None
        frontmatter, body = parsed
    except (ArchivePathError, OSError, UnicodeDecodeError):
        return None
    evidence_first_read = explicit_abstract_publication_check(frontmatter)
    if (
        not evidence_first_read.get("ready_for_publication")
        or evidence_first_read.get("abstract_sha256") != abstract_sha256
    ):
        return None
    return (
        canonical_path,
        abstract_sha256,
        canonical_body_sha256(canonical_publication_body(body)),
        evidence_kind,
    )


def abstract_review_evidence_candidate_paths(
    root: Path,
    publication_zettel_ids: set[str] | None,
) -> tuple[list[Path], str]:
    paths: list[Path] = []
    if publication_zettel_ids is None:
        lookup_mode = "bounded_publication_directory_fallback"
        for relative_root, pattern in (
            (MINT_RECEIPTS_DIR, "*.mint.json"),
            ("receipts/promotion", "*.promotion.json"),
        ):
            candidate_root = archive_internal_path(root, relative_root)
            if candidate_root.is_dir():
                paths.extend(
                    safe_archive_glob(
                        candidate_root,
                        pattern,
                        root,
                        recursive=True,
                    )
                )
    elif publication_zettel_ids:
        lookup_mode = "direct_publication_receipt_by_safe_zettel_id"
        for zettel_id in sorted(publication_zettel_ids):
            for relative in (
                f"{MINT_RECEIPTS_DIR}/{zettel_id}.mint.json",
                f"receipts/promotion/{zettel_id}.promotion.json",
            ):
                candidate = archive_internal_path(root, relative)
                if candidate.is_file():
                    paths.append(candidate)
    else:
        lookup_mode = "no_explicit_abstract_targets"

    if publication_zettel_ids is None or publication_zettel_ids:
        for relative_root, pattern in (
            (ZET_REVISION_RECEIPTS_DIR, "*.zet-revision.json"),
            (
                ZET_ABSTRACT_BACKFILL_RECEIPTS_DIR,
                "*.zet-abstract-backfill.json",
            ),
        ):
            candidate_root = archive_internal_path(root, relative_root)
            if candidate_root.is_dir():
                paths.extend(safe_archive_glob(candidate_root, pattern, root))

    unique_paths = list(dict.fromkeys(paths))
    unique_paths.sort(key=lambda path: archive_relative_path(path, root))
    return unique_paths, lookup_mode


def index_abstract_review_evidence(
    root: Path,
    *,
    publication_zettel_ids: set[str] | None = None,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> tuple[dict[str, dict[tuple[str, str], set[str]]], dict[str, Any], list[str]]:
    evidence_by_path: dict[str, dict[tuple[str, str], set[str]]] = {}
    blockers: list[str] = []
    archive_id = read_archive_id(root)
    receipt_paths, lookup_mode = abstract_review_evidence_candidate_paths(
        root,
        publication_zettel_ids,
    )
    discovered_count = len(receipt_paths)
    if discovered_count > ABSTRACT_FRESHNESS_MAX_RECEIPTS:
        blockers.append("abstract_review_receipt_scan_limit_exceeded")
        receipt_paths = receipt_paths[:ABSTRACT_FRESHNESS_MAX_RECEIPTS]

    stats = {
        "receipt_files_discovered": discovered_count,
        "receipt_files_scanned": 0,
        "recognized_receipt_count": 0,
        "evidence_record_count": 0,
        "legacy_evidence_unavailable_count": 0,
        "invalid_or_oversized_receipt_count": 0,
        "unrelated_receipt_count": 0,
        "candidate_lookup_mode": lookup_mode,
        "publication_target_id_count": (
            len(publication_zettel_ids)
            if publication_zettel_ids is not None
            else None
        ),
        "whole_receipt_tree_enumerated": False,
        "persistent_cache_used": False,
        "max_receipts": ABSTRACT_FRESHNESS_MAX_RECEIPTS,
        "max_receipt_bytes": ABSTRACT_FRESHNESS_MAX_RECEIPT_BYTES,
    }
    if progress_callback is not None:
        progress_callback("abstract-evidence", "start", 0, len(receipt_paths))

    for index, receipt_path in enumerate(receipt_paths, start=1):
        stats["receipt_files_scanned"] += 1
        try:
            raw_bytes = read_bounded_abstract_evidence_file(
                receipt_path, ABSTRACT_FRESHNESS_MAX_RECEIPT_BYTES
            )
            receipt = json.loads(raw_bytes.decode("utf-8-sig"))
            if not isinstance(receipt, dict):
                raise ValueError("Receipt must be an object.")
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, ValueError):
            stats["invalid_or_oversized_receipt_count"] += 1
            continue

        receipt_relative = archive_relative_path(receipt_path, root)
        added_from_receipt = 0
        if receipt.get("schema") in ZET_REVISION_RECEIPT_SCHEMAS:
            basis = (
                receipt.get("abstract_review_basis")
                if isinstance(receipt.get("abstract_review_basis"), dict)
                else {}
            )
            human_review = (
                receipt.get("human_review")
                if isinstance(receipt.get("human_review"), dict)
                else {}
            )
            canonical_path = normalize_abstract_evidence_canonical_path(
                receipt.get("canonical_path")
            )
            abstract_sha256 = normalize_abstract_evidence_sha256(
                basis.get("abstract_sha256")
            )
            body_sha256 = normalize_abstract_evidence_sha256(
                basis.get("body_sha256")
            )
            if (
                receipt_relative.startswith(f"{ZET_REVISION_RECEIPTS_DIR}/")
                and receipt_relative.endswith(".zet-revision.json")
                and receipt.get("action") == "zet_revision_write"
                and receipt.get("status") == "applied"
                and receipt.get("archive_id") == archive_id
                and basis.get("contract") == ABSTRACT_REVIEW_BASIS_CONTRACT
                and basis.get("review_status") == "reviewed_at_revision"
                and basis.get("evidence_kind") == "zet_revision_write"
                and basis.get("body_hash_basis") == ABSTRACT_REVIEW_BODY_HASH_BASIS
                and basis.get("abstract_text_stored") is False
                and basis.get("body_text_stored") is False
                and human_review.get("revision_reviewed") is True
                and human_review.get("abstract_body_pair_reviewed") is True
                and (
                    human_review.get("edge_review_required") is not True
                    or human_review.get("edge_changes_reviewed") is True
                )
                and canonical_path
                and abstract_sha256
                and body_sha256
                and (
                    (revision_schema_file := zet_revision_event_receipt_schema_file(receipt))
                    is not None
                )
                and not validate_schema(receipt, revision_schema_file)
            ):
                if add_abstract_review_evidence(
                    evidence_by_path,
                    canonical_path=canonical_path,
                    abstract_sha256=abstract_sha256,
                    body_sha256=body_sha256,
                    evidence_kind="reviewed_canonical_revision",
                ):
                    added_from_receipt += 1
            else:
                stats["invalid_or_oversized_receipt_count"] += 1
        elif receipt.get("schema") == ZET_REVISION_RESTORE_RECEIPT_SCHEMA:
            basis = (
                receipt.get("abstract_review_basis")
                if isinstance(receipt.get("abstract_review_basis"), dict)
                else {}
            )
            human_review = (
                receipt.get("human_review")
                if isinstance(receipt.get("human_review"), dict)
                else {}
            )
            canonical_path = normalize_abstract_evidence_canonical_path(
                receipt.get("canonical_path")
            )
            abstract_sha256 = normalize_abstract_evidence_sha256(
                basis.get("abstract_sha256")
            )
            body_sha256 = normalize_abstract_evidence_sha256(
                basis.get("body_sha256")
            )
            if (
                receipt_relative.startswith(f"{ZET_REVISION_RECEIPTS_DIR}/")
                and receipt_relative.endswith(".zet-revision.json")
                and receipt.get("action") == "zet_revision_restore_write"
                and receipt.get("status") == "applied"
                and receipt.get("archive_id") == archive_id
                and basis.get("contract") == ABSTRACT_REVIEW_BASIS_CONTRACT
                and basis.get("review_status") == "reviewed_at_restore"
                and basis.get("evidence_kind")
                == "zet_revision_restore_write"
                and basis.get("body_hash_basis")
                == ABSTRACT_REVIEW_BODY_HASH_BASIS
                and basis.get("abstract_text_stored") is False
                and basis.get("body_text_stored") is False
                and human_review.get("restore_reviewed") is True
                and human_review.get("abstract_body_pair_reviewed") is True
                and (
                    human_review.get("edge_review_required") is not True
                    or human_review.get("edge_changes_reviewed") is True
                )
                and canonical_path
                and abstract_sha256
                and body_sha256
                and not validate_schema(
                    receipt, "zet-revision-restore-receipt.schema.json"
                )
            ):
                if add_abstract_review_evidence(
                    evidence_by_path,
                    canonical_path=canonical_path,
                    abstract_sha256=abstract_sha256,
                    body_sha256=body_sha256,
                    evidence_kind="reviewed_canonical_restore",
                ):
                    added_from_receipt += 1
            else:
                stats["invalid_or_oversized_receipt_count"] += 1
        elif receipt.get("schema") == ZET_ABSTRACT_BACKFILL_RECEIPT_SCHEMA:
            if (
                receipt_relative.startswith(f"{ZET_ABSTRACT_BACKFILL_RECEIPTS_DIR}/")
                and receipt_relative.endswith(".zet-abstract-backfill.json")
                and receipt.get("action") == "zet_abstract_backfill_write"
                and receipt.get("status") == "applied"
                and receipt.get("archive_id") == archive_id
                and receipt.get("human_affirmation") == "all_proposed_abstracts_reviewed"
                and not validate_schema(receipt, "zet-abstract-backfill-receipt.schema.json")
            ):
                for item in receipt.get("items", []):
                    canonical_path = normalize_abstract_evidence_canonical_path(
                        item.get("canonical_path") if isinstance(item, dict) else None
                    )
                    abstract_sha256 = normalize_abstract_evidence_sha256(
                        item.get("abstract_sha256") if isinstance(item, dict) else None
                    )
                    body_sha256 = normalize_abstract_evidence_sha256(
                        item.get("body_sha256") if isinstance(item, dict) else None
                    )
                    if canonical_path and abstract_sha256 and body_sha256:
                        if add_abstract_review_evidence(
                            evidence_by_path,
                            canonical_path=canonical_path,
                            abstract_sha256=abstract_sha256,
                            body_sha256=body_sha256,
                            evidence_kind="reviewed_abstract_backfill",
                        ):
                            added_from_receipt += 1
            else:
                stats["invalid_or_oversized_receipt_count"] += 1
        elif (
            receipt.get("action") in {"mint_zettel", "promote_zettel"}
            and receipt.get("dry_run") is False
        ):
            action = str(receipt.get("action"))
            receipt_path_matches_action = (
                receipt_relative.startswith(f"{MINT_RECEIPTS_DIR}/")
                and receipt_relative.endswith(".mint.json")
                if action == "mint_zettel"
                else receipt_relative.startswith("receipts/promotion/")
                and receipt_relative.endswith(".promotion.json")
            )
            basis = receipt.get("abstract_review_basis")
            target = receipt.get("target") if isinstance(receipt.get("target"), dict) else {}
            if isinstance(basis, dict):
                canonical_path = normalize_abstract_evidence_canonical_path(target.get("path"))
                abstract_sha256 = normalize_abstract_evidence_sha256(basis.get("abstract_sha256"))
                body_sha256 = normalize_abstract_evidence_sha256(basis.get("body_sha256"))
                expected_kind = receipt.get("action")
                first_read = (
                    receipt.get("first_read_check")
                    if isinstance(receipt.get("first_read_check"), dict)
                    else {}
                )
                if (
                    receipt_path_matches_action
                    and canonical_path
                    and abstract_sha256
                    and body_sha256
                    and basis.get("contract") == ABSTRACT_REVIEW_BASIS_CONTRACT
                    and basis.get("review_status") == "reviewed_at_publication"
                    and basis.get("evidence_kind") == expected_kind
                    and basis.get("body_hash_basis") == ABSTRACT_REVIEW_BODY_HASH_BASIS
                    and basis.get("abstract_text_stored") is False
                    and basis.get("body_text_stored") is False
                    and first_read.get("ready_for_publication") is True
                    and first_read.get("abstract_sha256") == abstract_sha256
                    and isinstance(receipt.get("reviewed_by"), str)
                    and bool(str(receipt.get("reviewed_by")).strip())
                ):
                    if add_abstract_review_evidence(
                        evidence_by_path,
                        canonical_path=canonical_path,
                        abstract_sha256=abstract_sha256,
                        body_sha256=body_sha256,
                        evidence_kind=str(expected_kind),
                    ):
                        added_from_receipt += 1
                else:
                    stats["invalid_or_oversized_receipt_count"] += 1
            else:
                legacy = (
                    legacy_publication_abstract_evidence(root, receipt)
                    if receipt_path_matches_action
                    else None
                )
                if legacy is None:
                    stats["legacy_evidence_unavailable_count"] += 1
                else:
                    canonical_path, abstract_sha256, body_sha256, evidence_kind = legacy
                    if add_abstract_review_evidence(
                        evidence_by_path,
                        canonical_path=canonical_path,
                        abstract_sha256=abstract_sha256,
                        body_sha256=body_sha256,
                        evidence_kind=evidence_kind,
                    ):
                        added_from_receipt += 1
        else:
            stats["unrelated_receipt_count"] += 1

        if added_from_receipt:
            stats["recognized_receipt_count"] += 1
            stats["evidence_record_count"] += added_from_receipt
        if progress_callback is not None and (index == len(receipt_paths) or index % 100 == 0):
            progress_callback("abstract-evidence", "scan", index, len(receipt_paths))

    if progress_callback is not None:
        progress_callback("abstract-evidence", "done", len(receipt_paths), len(receipt_paths))
    return evidence_by_path, stats, blockers


def abstract_freshness(
    archive_root: Path | str,
    *,
    dry_run: bool = False,
    max_items: int = 100,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> dict[str, Any]:
    """Compare canonical abstract/body hashes with human-review evidence without echoing text."""
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    requested_max_items = int(max_items)
    effective_max_items = max(
        1, min(requested_max_items, ABSTRACT_FRESHNESS_MAX_ATTENTION_ITEMS)
    )
    if requested_max_items != effective_max_items:
        blockers.append("max_items_out_of_range")
    if not dry_run:
        blockers.append("abstract-freshness is read-only and requires --dry-run.")

    canonical_paths = zet_catalog_paths(root, "canonical")
    canonical_records: list[dict[str, Any]] = []
    publication_zettel_ids: set[str] = set()
    publication_lookup_requires_fallback = False
    counts = {
        "fresh": 0,
        "stale": 0,
        "unverified": 0,
        "missing": 0,
        "unreadable": 0,
        "excluded": 0,
    }
    reasons: dict[str, int] = {}
    attention_items: list[dict[str, Any]] = []
    attention_count = 0
    if progress_callback is not None:
        progress_callback("abstract-canonical", "start", 0, len(canonical_paths))

    def inspect_canonical(row: tuple[Path, str]) -> dict[str, Any]:
        path, _expected_status = row
        relative = archive_relative_path(path, root)
        status = "unreadable"
        reason = "canonical_unreadable"
        zettel_id: str | None = None
        abstract_sha256: str | None = None
        body_sha256_candidates: set[str] = set()
        body_read = False
        try:
            frontmatter = read_bounded_abstract_freshness_frontmatter(
                path,
                ABSTRACT_FRESHNESS_MAX_ZET_BYTES,
            )
            raw_id = frontmatter.get("id")
            if isinstance(raw_id, str) and ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(raw_id):
                zettel_id = raw_id
            if frontmatter.get("status") == "redacted":
                status = "excluded"
                reason = "redacted_by_policy"
            else:
                first_read_check = explicit_abstract_publication_check(frontmatter)
                frontmatter_abstract_sha256 = first_read_check.get("abstract_sha256")
                if not first_read_check.get("ready_for_publication") or not isinstance(
                    frontmatter_abstract_sha256, str
                ):
                    status = "missing"
                    reason = "abstract_" + str(first_read_check.get("status") or "invalid")
                else:
                    body_read = True
                    raw_bytes = read_bounded_abstract_evidence_file(
                        path,
                        ABSTRACT_FRESHNESS_MAX_ZET_BYTES,
                    )
                    parsed = parse_abstract_evidence_zettel_bytes(raw_bytes)
                    if parsed is None:
                        raise ValueError("Canonical zet is unreadable.")
                    complete_frontmatter, body = parsed
                    complete_id = complete_frontmatter.get("id")
                    zettel_id = (
                        complete_id
                        if isinstance(complete_id, str)
                        and ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(complete_id)
                        else None
                    )
                    if complete_frontmatter.get("status") == "redacted":
                        status = "excluded"
                        reason = "redacted_by_policy"
                        abstract_sha256 = None
                    else:
                        complete_first_read = explicit_abstract_publication_check(
                            complete_frontmatter
                        )
                        complete_abstract_sha256 = complete_first_read.get(
                            "abstract_sha256"
                        )
                        if not complete_first_read.get(
                            "ready_for_publication"
                        ) or not isinstance(complete_abstract_sha256, str):
                            status = "missing"
                            reason = "abstract_" + str(
                                complete_first_read.get("status") or "invalid"
                            )
                            abstract_sha256 = None
                        else:
                            status = "pending_evidence"
                            reason = "pending_evidence"
                            abstract_sha256 = complete_abstract_sha256
                            body_sha256_candidates.add(canonical_body_sha256(body))
                            try:
                                raw_frontmatter, raw_body = require_readable_zettel_text(
                                    raw_bytes.decode("utf-8")
                                )
                                if raw_frontmatter:
                                    body_sha256_candidates.add(
                                        canonical_body_sha256(raw_body)
                                    )
                            except Exception:
                                pass
        except (OSError, UnicodeDecodeError, ValueError):
            pass

        return {
            "path": relative,
            "zettel_id": zettel_id,
            "status": status,
            "reason": reason,
            "abstract_sha256": abstract_sha256,
            "body_sha256_candidates": body_sha256_candidates,
            "body_read": body_read,
        }

    canonical_worker_count = min(
        8,
        len(canonical_paths),
        max(1, os.cpu_count() or 1),
    )
    if canonical_worker_count > 1 and len(canonical_paths) >= 64:
        with ThreadPoolExecutor(
            max_workers=canonical_worker_count,
            thread_name_prefix="wom-abstract-freshness",
        ) as executor:
            inspected_records = executor.map(inspect_canonical, canonical_paths)
            for index, record in enumerate(inspected_records, start=1):
                canonical_records.append(record)
                if progress_callback is not None and (
                    index == len(canonical_paths) or index % 100 == 0
                ):
                    progress_callback(
                        "abstract-canonical",
                        "scan",
                        index,
                        len(canonical_paths),
                    )
        canonical_scan_mode = "bounded_thread_pool"
    else:
        for index, row in enumerate(canonical_paths, start=1):
            canonical_records.append(inspect_canonical(row))
            if progress_callback is not None and (
                index == len(canonical_paths) or index % 100 == 0
            ):
                progress_callback(
                    "abstract-canonical",
                    "scan",
                    index,
                    len(canonical_paths),
                )
        canonical_scan_mode = "sequential"

    for record in canonical_records:
        if record["status"] != "pending_evidence":
            continue
        zettel_id = record["zettel_id"]
        if zettel_id is None:
            publication_lookup_requires_fallback = True
        else:
            publication_zettel_ids.add(str(zettel_id))

    if progress_callback is not None:
        progress_callback("abstract-canonical", "done", len(canonical_paths), len(canonical_paths))

    evidence_by_path, evidence_scan, evidence_blockers = index_abstract_review_evidence(
        root,
        publication_zettel_ids=(
            None
            if publication_lookup_requires_fallback
            else publication_zettel_ids
        ),
        progress_callback=progress_callback,
    )
    blockers.extend(evidence_blockers)

    for record in canonical_records:
        status = str(record["status"])
        reason = str(record["reason"])
        evidence_count = 0
        if status == "pending_evidence":
            abstract_sha256 = record["abstract_sha256"]
            body_sha256_candidates = record["body_sha256_candidates"]
            pairs = evidence_by_path.get(str(record["path"]), {})
            evidence_count = sum(len(kinds) for kinds in pairs.values())
            if any(
                (abstract_sha256, body_sha256) in pairs
                for body_sha256 in body_sha256_candidates
            ):
                status = "fresh"
                reason = "reviewed_pair_matches"
            elif not pairs:
                status = "unverified"
                reason = "no_review_evidence"
            elif any(pair[0] == abstract_sha256 for pair in pairs):
                status = "stale"
                reason = "body_changed"
            elif any(pair[1] in body_sha256_candidates for pair in pairs):
                status = "stale"
                reason = "abstract_changed"
            else:
                status = "stale"
                reason = "abstract_and_body_changed"

        counts[status] += 1
        reasons[reason] = reasons.get(reason, 0) + 1
        if status not in {"fresh", "excluded"}:
            attention_count += 1
            if len(attention_items) < effective_max_items:
                attention_items.append(
                    {
                        "path": record["path"],
                        "zettel_id": record["zettel_id"],
                        "status": status,
                        "reason": reason,
                        "review_evidence_count": evidence_count,
                    }
                )
    all_required_fresh = attention_count == 0
    state = "blocked" if blockers else "ready" if all_required_fresh else "needs_attention"
    canonical_body_files_read = sum(
        1 for record in canonical_records if record["body_read"]
    )
    warnings: list[str] = []
    if evidence_scan["invalid_or_oversized_receipt_count"]:
        warnings.append("Some receipt files were invalid or exceeded the bounded read limit.")
    if evidence_scan["legacy_evidence_unavailable_count"]:
        warnings.append("Some older publication receipts lacked a retained source needed to reconstruct review evidence.")

    return {
        "ok": not blockers,
        "schema": ABSTRACT_FRESHNESS_SCHEMA,
        "lifecycle_action": "abstract_freshness",
        "state": state,
        "archive_id": read_archive_id(root),
        "dry_run": True,
        "canonical_zet_count": len(canonical_paths),
        "counts": counts,
        "reason_counts": dict(sorted(reasons.items())),
        "readiness": {
            "all_required_abstracts_have_review_evidence_for_current_body": all_required_fresh,
            "redacted_zets_excluded": True,
        },
        "attention": {
            "total_count": attention_count,
            "returned_count": len(attention_items),
            "truncated": attention_count > len(attention_items),
            "max_items": effective_max_items,
            "items": attention_items,
        },
        "scan": {
            "canonical_paths_scanned": len(canonical_paths),
            "receipt_index_passes": 1,
            "canonical_passes": 1,
            "complexity_contract": "O(canonical_zets + evidence_candidate_receipts + receipt_items)",
            "explicit_abstract_evidence_target_count": sum(
                1 for record in canonical_records if record["status"] == "pending_evidence"
            ),
            "canonical_frontmatter_files_scanned": len(canonical_records),
            "canonical_body_files_read": canonical_body_files_read,
            "canonical_body_files_not_read": len(canonical_records)
            - canonical_body_files_read,
            "canonical_body_read_policy": "valid_explicit_abstract_targets_only",
            "canonical_scan_mode": canonical_scan_mode,
            "canonical_scan_workers": (
                canonical_worker_count
                if canonical_scan_mode == "bounded_thread_pool"
                else 1
            ),
            "publication_lookup_fallback_required": publication_lookup_requires_fallback,
            "max_canonical_file_bytes": ABSTRACT_FRESHNESS_MAX_ZET_BYTES,
            **evidence_scan,
        },
        "claim_boundary": {
            "checked": "Exact current abstract/body hash pairs against retained human-review evidence.",
            "not_checked": [
                "abstract semantic quality or factual correctness",
                "whether a model consumed the abstract",
                "body readability for zets without a valid explicit abstract",
                "objet bytes or derived text",
                "provider or backup freshness",
            ],
        },
        "blockers": unique_preserve_order(blockers),
        "warnings": warnings,
        "next_actions": (
            ["Review each attention item, then publish a revised zet or use the reviewed abstract backfill flow."]
            if attention_count
            else ["No abstract freshness review is currently required for canonical zets."]
        ),
        "would_change": [],
        "privacy_guards": {
            "abstract_text_echoed": False,
            "body_text_echoed": False,
            "title_values_echoed": False,
            "hash_values_echoed": False,
            "receipt_paths_echoed": False,
            "reviewer_ids_echoed": False,
            "absolute_local_paths_echoed": False,
            "provider_urls_echoed": False,
            "writes": False,
        },
    }


