def compact_zet_title_comparison_form(value: str) -> str:
    """Collapse a title or identifier to the house comparison form.

    Uses the same separator set as the promotion checklist's title compaction so
    `32634f64-2e1b-80b6` and `32634f642e1b80b6` compare equal.
    """
    return re.sub(r"[\s._-]+", "", str(value).casefold())


def zet_title_identifier_duplicate_suffix(value: Any) -> str | None:
    """Return the identifier base for a standard duplicate `` (n)`` suffix.

    Notion-style duplicate names append a single space plus a positive integer
    in parentheses.  Only an already-valid bare identifier base is accepted;
    arbitrary parenthesized titles therefore remain human-readable.
    """

    if not isinstance(value, str):
        return None
    match = re.fullmatch(r"(?s)(.+?)[ \t]+\([1-9][0-9]*\)", value)
    if match is None:
        return None
    base = match.group(1)
    compact = compact_zet_title_comparison_form(base)
    if (
        len(compact) < ZET_TITLE_IDENTIFIER_MIN_HEX_CHARS
        or ZET_TITLE_HEX_RE.fullmatch(compact) is None
    ):
        return None
    return base


def zet_title_is_identifier_shaped(value: Any) -> bool:
    """Whether a title is a bare identifier or its standard duplicate form."""

    if not isinstance(value, str):
        return False
    compact = compact_zet_title_comparison_form(value)
    if bool(
        len(compact) >= ZET_TITLE_IDENTIFIER_MIN_HEX_CHARS
        and ZET_TITLE_HEX_RE.match(compact)
    ):
        return True
    return zet_title_identifier_duplicate_suffix(value) is not None


def zet_title_reference_discloses_title(reference: Any, compact_title: str) -> bool:
    """Whether emitting `reference` would reproduce the title it is reported for.

    The house mints a zet id -- and therefore its filename -- from the title
    (`make_zettel_id`), so an attention row's own path or id can carry the very
    value this census withholds. The mint truncates its slug at 32 characters, so
    a long title survives as a prefix rather than whole; a prefix of identifier
    length is still the identifier.

    The test is title-relative on purpose. A shape-only rule would also suppress
    importer-minted names like `zet_import_<system>_<digest16>`
    (`external_import_zettel_id`), whose hex run digests the source record and
    cannot disclose a title -- and those are the names the imported population
    this census exists for actually carries.

    Testing the first `ZET_TITLE_IDENTIFIER_MIN_HEX_CHARS` characters covers every
    longer prefix too: if a prefix of length n >= that floor appears in the
    reference, its own opening characters appear with it. So the two checks below
    are the whole rule -- the title entire, at any length, or identifier-length
    evidence of it.
    """
    if not isinstance(reference, str) or not compact_title:
        return False
    compact_reference = compact_zet_title_comparison_form(reference)
    if not compact_reference:
        return False
    if compact_title in compact_reference:
        return True
    return compact_title[:ZET_TITLE_IDENTIFIER_MIN_HEX_CHARS] in compact_reference


def zet_title_identifier_signals(item: dict[str, Any]) -> list[str]:
    """Return which identifier-shaped signals a catalog item's title matches.

    Signal `title_matches_external_id` is provenance-bound: the title is literally
    the record's own imported identifier, which is provable from the zet alone.
    Signal `title_is_identifier_shaped` is a shape heuristic for the same failure
    when the source identifier was not preserved in frontmatter. They are reported
    separately because only the first proves what the title was supposed to be.
    """
    title = item.get("title")
    if not isinstance(title, str):
        return []
    compact_title = compact_zet_title_comparison_form(title)
    if not compact_title:
        return []

    signals: list[str] = []
    facets = item.get("facets")
    if isinstance(facets, dict):
        # Consult the house's registered provider page-reference vocabulary rather
        # than a hand-written pair. The previous pair named `source_page_id`, a key
        # nothing in this project writes, so the signal covered one key while
        # appearing to cover two.
        for facet_key in sorted(facets, key=str):
            if notion_source_map_ref_family_for_key(facet_key) != "page_refs":
                continue
            facet_value = facets.get(facet_key)
            if isinstance(facet_value, (str, int)) and compact_zet_title_comparison_form(
                facet_value
            ) == compact_title:
                signals.append("title_matches_external_id")
                break
    if zet_title_is_identifier_shaped(title):
        signals.append("title_is_identifier_shaped")
    return signals


def zet_title_readiness(
    archive_root: Path | str,
    *,
    dry_run: bool = False,
    max_items: int = 100,
    item_cache: dict[str, dict[str, Any]] | None = None,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> dict[str, Any]:
    """Report canonical zets whose title is an identifier rather than a name.

    An import can faithfully copy a source title that was itself a page id. The
    bytes are correct and nothing is lost, but the archive becomes unbrowsable by
    title and title search stops reaching those zets. This is a read-only census
    of that condition; it proposes nothing and writes nothing.
    """
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    max_items = max(1, min(int(max_items), 500))
    if not dry_run:
        blockers.append("zet-title-readiness is read-only and requires --dry-run.")

    path_entries = zet_catalog_paths(root, "canonical")
    entries, scan = zet_catalog_entries(
        root,
        path_entries,
        item_cache,
        progress_callback=progress_callback,
    )
    snapshot = zet_catalog_snapshot(root, entries)

    # `counts` partitions the entries this census saw; `signal_counts` reports how
    # often each rule fired. They are kept apart because a single zet can trip both
    # rules, so the signal numbers do not sum to a count of zets.
    counts = {
        "human_readable": 0,
        "title_unavailable": 0,
        "redacted": 0,
        "frontmatter_unreadable": 0,
    }
    signal_counts = {
        "title_matches_external_id": 0,
        "title_is_identifier_shaped": 0,
        "both_signals": 0,
    }
    attention_items: list[dict[str, Any]] = []
    attention_count = 0
    paths_withheld_count = 0
    zettel_ids_withheld_count = 0
    title_values_echoed = False
    external_id_values_echoed = False
    for _path, _expected_status, item, _signature in entries:
        if bool(item.get("redacted")):
            # A redacted zet exposes no title to judge, and its content is
            # deliberately suppressed. It is not an attention item.
            counts["redacted"] += 1
            continue
        if not bool(item.get("frontmatter_readable")):
            counts["frontmatter_unreadable"] += 1
            continue
        title = item.get("title")
        compact_title = (
            compact_zet_title_comparison_form(title) if isinstance(title, str) else ""
        )
        if not compact_title:
            # The title is absent, or the catalog suppressed it as private or
            # unsafe before this census could see it. Either way it was not judged,
            # and scoring it as human-readable would claim a check that never ran.
            counts["title_unavailable"] += 1
            continue
        signals = zet_title_identifier_signals(item)
        if not signals:
            counts["human_readable"] += 1
            continue
        for signal in signals:
            signal_counts[signal] += 1
        if len(signals) > 1:
            signal_counts["both_signals"] += 1
        attention_count += 1
        if len(attention_items) >= max_items:
            continue

        path_value = item.get("path")
        path_discloses = zet_title_reference_discloses_title(path_value, compact_title)
        if path_discloses:
            paths_withheld_count += 1
        zettel_id = item.get("id")
        if zet_title_reference_discloses_title(zettel_id, compact_title):
            # Checked before the syntax gate: disclosure is why the value is being
            # withheld, and that is true whether or not the id is well formed.
            safe_zettel_id: str | None = None
            zettel_id_withheld_reason: str | None = "discloses_title"
            zettel_ids_withheld_count += 1
        elif not (
            isinstance(zettel_id, str) and ZETTEL_EDGE_ZETTEL_ID_RE.match(zettel_id)
        ):
            safe_zettel_id = None
            zettel_id_withheld_reason = "unsafe_id_syntax"
        else:
            safe_zettel_id = zettel_id
            zettel_id_withheld_reason = None

        row = {
            "path": None if path_discloses else path_value,
            "path_withheld_reason": "discloses_title" if path_discloses else None,
            "zettel_id": safe_zettel_id,
            "zettel_id_withheld_reason": zettel_id_withheld_reason,
            "signals": signals,
            "provenance_bound": "title_matches_external_id" in signals,
        }
        # Derive the privacy guards from what this row actually carries rather than
        # asserting a literal, so the flags cannot disagree with the payload if a
        # gate above ever stops firing.
        if any(
            zet_title_reference_discloses_title(value, compact_title)
            for value in (row["path"], row["zettel_id"])
        ):
            title_values_echoed = True
            if row["provenance_bound"]:
                external_id_values_echoed = True
        attention_items.append(row)

    # A zet whose frontmatter could not be read, or whose title the catalog
    # suppressed, was never judged. Redacted zets are excluded by an explicit and
    # separately reported decision, so they do not count as unjudged.
    unjudged_count = counts["frontmatter_unreadable"] + counts["title_unavailable"]
    titles_are_human_readable = attention_count == 0 and unjudged_count == 0
    if blockers:
        state = "blocked"
    elif titles_are_human_readable:
        state = "ready"
    else:
        state = "needs_attention"

    next_actions: list[str] = []
    if attention_count:
        next_actions.append(
            "Review the listed canonical zets against their original source records; a reviewed "
            "retitle is a separate approval-gated flow and this command never proposes replacement text."
        )
        next_actions.append(
            "Keep the original source export that carries the human-readable names; it is the only "
            "evidence that can justify a later reviewed retitle."
        )
    if paths_withheld_count or zettel_ids_withheld_count:
        next_actions.append(
            "Some attention rows withheld their path or id because the value was minted from the "
            "offending title and would have reproduced it; locate those zets from the archive "
            "itself rather than from this report."
        )
    if unjudged_count:
        next_actions.append(
            "Resolve the canonical zets whose frontmatter could not be read or whose title was "
            "suppressed as private or unsafe; this census could not judge them and does not count "
            "them as human-readable."
        )
    if not attention_count and not unjudged_count:
        next_actions.append(
            "No canonical zet title looks like a bare identifier at this snapshot, across the "
            f"{counts['human_readable']} canonical zets whose title could be read."
        )

    return {
        "ok": not blockers,
        "schema": ZET_TITLE_READINESS_SCHEMA,
        "lifecycle_action": "zet_title_readiness",
        "state": state,
        "readiness_met": titles_are_human_readable,
        "archive_id": read_archive_id(root),
        "dry_run": dry_run,
        "canonical_zet_count": len(entries),
        "counts": counts,
        "signal_counts": signal_counts,
        "readiness": {
            "canonical_node_inventory_checked": not blockers,
            "all_titles_human_readable": titles_are_human_readable,
            "judged_count": counts["human_readable"] + attention_count,
            "unjudged_count": unjudged_count,
            "redacted_entries_excluded": True,
        },
        "detection": {
            "title_matches_external_id": (
                "The compared title equals the record's own imported identifier after case folding "
                "and separator removal. Provable from the zet alone."
            ),
            "title_is_identifier_shaped": (
                f"The compared title is a bare hexadecimal run of at least "
                f"{ZET_TITLE_IDENTIFIER_MIN_HEX_CHARS} characters. A shape heuristic, not proof."
            ),
            "comparison_form": "casefold_then_remove_whitespace_dot_underscore_hyphen",
            "compared_facet_keys": sorted(NOTION_SOURCE_MAP_PAGE_REF_KEYS),
            "compared_facet_key_suffix_rule": "_page_id",
            "signals_may_overlap_one_zet": True,
            "per_zet_count_is": "attention.total_count",
        },
        "attention": {
            "total_count": attention_count,
            "returned_count": len(attention_items),
            "truncated": attention_count > len(attention_items),
            "max_items": max_items,
            "paths_withheld_count": paths_withheld_count,
            "zettel_ids_withheld_count": zettel_ids_withheld_count,
            "items": attention_items,
        },
        "scan": {
            **scan,
            "status": "canonical",
            "frontmatter_only": True,
            "zettel_bodies_read": False,
            "objet_bytes_read": False,
            "provider_api_called": False,
            "secrets_read": False,
        },
        "snapshot": snapshot,
        "claim_boundary": {
            "checked": "Canonical zet frontmatter titles and imported identifiers at this snapshot.",
            "not_checked": [
                "Whether a human-readable replacement title exists anywhere.",
                "Whether a title that is not identifier-shaped is actually meaningful.",
                "Draft, archived, or redacted zets.",
                "Canonical zets whose frontmatter could not be read.",
                "Canonical zets whose title was absent or suppressed as private or unsafe.",
            ],
        },
        "blockers": blockers,
        "warnings": [],
        "exit_policy": {
            "zero_when_diagnostic_completed": True,
            "needs_attention_is_command_failure": False,
            "nonzero_reserved_for_blocked_input_or_execution_failure": True,
        },
        "next_actions": next_actions,
        "would_change": [],
        "privacy_guards": {
            "title_values_echoed": title_values_echoed,
            "external_id_values_echoed": external_id_values_echoed,
            "abstract_text_echoed": False,
            "body_text_echoed": False,
            "local_absolute_paths_echoed": False,
            "provider_urls_echoed": False,
            "title_derived_references_withheld": bool(
                paths_withheld_count or zettel_ids_withheld_count
            ),
            "writes": False,
        },
    }


def resolve_zet_title_remap_proposal_path(root: Path, raw_path: str) -> Path:
    try:
        normalized = normalize_archive_relative_path(raw_path)
    except ArchivePathError as exc:
        raise ZetTitleRemapInputError(
            "proposal_path_not_archive_relative",
            "Title remap proposal path must be archive-relative.",
        ) from exc
    if not normalized.startswith(ZET_TITLE_REMAP_PROPOSAL_PREFIX) or not normalized.lower().endswith(".jsonl"):
        raise ZetTitleRemapInputError(
            "proposal_path_outside_private_scratch",
            (
                "Title remap proposal must be a .jsonl file under "
                f"{ZET_TITLE_REMAP_PROPOSAL_PREFIX}"
            ),
        )
    unresolved = root.resolve()
    for part in normalized.split("/"):
        unresolved = unresolved / part
        if unresolved.is_symlink():
            raise ZetTitleRemapInputError(
                "proposal_path_contains_symbolic_link",
                "Title remap proposal paths must not contain symbolic links.",
            )
    path = resolve_archive_relative_path(root, normalized)
    if path.is_symlink() or not path.is_file():
        raise ZetTitleRemapInputError(
            "proposal_file_missing_or_not_regular",
            "Title remap proposal must be an existing regular file.",
        )
    return path


def read_zet_title_remap_proposal_bytes(
    proposal_path: Path,
    *,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None,
) -> tuple[bytes, str]:
    size = proposal_path.stat().st_size
    if size > ZET_TITLE_REMAP_MAX_FILE_BYTES:
        raise ZetTitleRemapInputError(
            "proposal_file_exceeds_64_mib",
            "Title remap proposal exceeds the 64 MiB safety limit.",
        )
    chunks: list[bytes] = []
    completed = 0
    if progress_callback is not None:
        progress_callback("title-remap-proposal", "start", 0, size)
    with proposal_path.open("rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            chunks.append(chunk)
            completed += len(chunk)
            if completed > ZET_TITLE_REMAP_MAX_FILE_BYTES:
                raise ZetTitleRemapInputError(
                    "proposal_file_exceeds_64_mib",
                    "Title remap proposal exceeds the 64 MiB safety limit.",
                )
            if progress_callback is not None:
                progress_callback("title-remap-proposal", "scanned", completed, size)
    if progress_callback is not None:
        progress_callback("title-remap-proposal", "done", completed, size)
    raw_bytes = b"".join(chunks)
    return raw_bytes, "sha256:" + hashlib.sha256(raw_bytes).hexdigest()


def read_zet_title_remap_canonical_bytes(path: Path) -> bytes:
    """Read a canonical zet under the published ceiling, checked after the read.

    A stat-then-unbounded-read makes the ceiling advisory: the file can grow
    between the two calls. Reading one byte past the limit and re-checking makes
    the number the report publishes actually hold.
    """
    if path.stat().st_size > ZET_TITLE_REMAP_MAX_CANONICAL_FILE_BYTES:
        raise ArchiveServiceError("Canonical zet exceeds the 16 MiB title remap limit.")
    with path.open("rb") as handle:
        value = handle.read(ZET_TITLE_REMAP_MAX_CANONICAL_FILE_BYTES + 1)
    if len(value) > ZET_TITLE_REMAP_MAX_CANONICAL_FILE_BYTES:
        raise ArchiveServiceError("Canonical zet exceeds the 16 MiB title remap limit.")
    return value


def zet_title_remap_safety_rules(value: str) -> list[str]:
    """Return fixed rule names without returning the matched private values."""

    rules: list[str] = []
    private_provider_url = bool(
        ZET_TITLE_REMAP_PRIVATE_PROVIDER_URL_RE.search(value)
        or ZETTEL_PRIVATE_PROVIDER_LOCATOR_RE.search(value)
    )
    if private_provider_url:
        rules.append("private_provider_url")
    if contains_forbidden_location_reference(value) and not bool(
        ZET_TITLE_REMAP_PRIVATE_PROVIDER_URL_RE.search(value)
    ):
        rules.append("local_absolute_path")
    token_shaped_value = bool(ZET_TITLE_REMAP_TOKEN_VALUE_RE.search(value))
    if DRAFT_SECRET_VALUE_RE.search(value) and not token_shaped_value:
        rules.append("credential_assignment_or_private_key")
    if token_shaped_value:
        rules.append("token_shaped_value")
    return unique_preserve_order(rules)


def normalized_zet_title_candidate(
    value: Any,
    blocker_codes: list[str],
    *,
    matched_safety_rules: list[str] | None = None,
    warning_codes: list[str] | None = None,
    basis: str | None = None,
) -> str | None:
    """Validate one private replacement title without echoing its value."""

    if not isinstance(value, str):
        blocker_codes.append("title_not_string")
        return None
    normalized = re.sub(r"\s+", " ", value).strip()
    if not normalized:
        blocker_codes.append("title_empty")
        return None
    contains_line_break = any(
        character in ZET_TITLE_REMAP_LINE_BREAK_CHARS for character in value
    )
    contains_non_normalized_whitespace = bool(
        value.startswith(" ")
        or value.endswith(" ")
        or "  " in value
        or any(
            character.isspace()
            and character != " "
            and character not in ZET_TITLE_REMAP_LINE_BREAK_CHARS
            for character in value
        )
    )
    if contains_line_break:
        blocker_codes.append("title_contains_line_break")
    if contains_non_normalized_whitespace:
        blocker_codes.append("title_contains_non_normalized_whitespace")
    if contains_line_break or contains_non_normalized_whitespace:
        return None
    if len(normalized) > ZET_TITLE_REMAP_MAX_TITLE_CHARS:
        blocker_codes.append("title_too_long")
        return None
    safety_rules = zet_title_remap_safety_rules(normalized)
    if matched_safety_rules is not None:
        matched_safety_rules.extend(safety_rules)
    if safety_rules:
        blocker_codes.append("title_private_locator_or_secret_like")
        return None
    if (
        warning_codes is not None
        and ZET_TITLE_REMAP_PUBLIC_WEB_URL_RE.search(normalized)
    ):
        warning_codes.append("title_contains_public_web_url")
    # A replacement that is itself identifier-shaped would be scored by
    # zet-title-readiness exactly as the value it replaces. Refuse it here rather
    # than let the census re-flag the archive after an approved write.
    if zet_title_is_identifier_shaped(normalized):
        blocker_codes.append("title_is_identifier_shaped")
        return None
    if not title_is_specific_enough_for_checklist(normalized):
        if (
            basis == "source_export_property"
            and title_is_short_exact_source_name_allowed(normalized)
        ):
            if warning_codes is not None:
                warning_codes.append(
                    "source_export_title_below_promotion_threshold"
                )
        else:
            blocker_codes.append(
                "title_not_specific_enough_for_promotion_checklist"
            )
            return None
    return normalized


def zet_title_remap_plan(
    archive_root: Path | str,
    *,
    proposal_path: str,
    max_items: int = ZET_TITLE_REMAP_MAX_ITEMS,
    dry_run: bool = False,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> dict[str, Any]:
    """Validate reviewed replacement titles against exact current canonical bytes.

    v0.3.262 counts canonical zets whose title is an imported identifier. This is
    the next rung: an operator supplies the names that already exist in the source
    export, and this checks each one against the archive without writing. It
    proposes no text of its own -- every replacement comes from the proposal file.

    The rule that keeps this from becoming a general title rewriter: a row is only
    accepted when the *current* title is one the census would flag. A title a human
    chose is not remappable through this path.
    """
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []
    if not dry_run:
        blockers.append("dry_run_required")
    requested_max_items = int(max_items)
    effective_max_items = max(1, min(requested_max_items, ZET_TITLE_REMAP_MAX_ITEMS))
    if requested_max_items != effective_max_items:
        blockers.append("max_items_out_of_range")
    resolved_proposal = resolve_zet_title_remap_proposal_path(root, proposal_path)
    raw_bytes, proposal_sha256 = read_zet_title_remap_proposal_bytes(
        resolved_proposal,
        progress_callback=progress_callback,
    )
    raw_lines = raw_bytes.splitlines(keepends=True)
    if not raw_lines:
        blockers.append("proposal_empty")
    truncated_due_to_max_items = len(raw_lines) > effective_max_items
    if truncated_due_to_max_items:
        blockers.append("proposal_exceeds_max_items")

    rows: list[dict[str, Any] | None] = []
    for raw_line in raw_lines[:effective_max_items]:
        if len(raw_line) > ZET_TITLE_REMAP_MAX_LINE_BYTES:
            rows.append(None)
            continue
        if not raw_line.strip():
            rows.append(None)
            continue
        try:
            parsed = json.loads(raw_line.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError, RecursionError):
            # RecursionError is not a JSONDecodeError. A deeply nested array well
            # under the per-line ceiling would otherwise escape to the default
            # excepthook and print a traceback carrying local absolute paths.
            parsed = None
        rows.append(parsed if isinstance(parsed, dict) else None)

    seen_zettel_ids: set[str] = set()
    item_results: list[dict[str, Any]] = []
    fingerprint_rows: list[dict[str, Any]] = []
    basis_counts = {basis: 0 for basis in sorted(ZET_TITLE_REMAP_BASIS_VALUES)}
    current_signal_counts = {
        "title_matches_external_id": 0,
        "title_is_identifier_shaped": 0,
    }
    safety_rule_counts = {
        rule: 0 for rule in ZET_TITLE_REMAP_SAFETY_RULES
    }
    warning_code_counts = {
        "title_contains_public_web_url": 0,
        "source_export_title_below_promotion_threshold": 0,
    }
    if progress_callback is not None:
        progress_callback("title-remap-candidates", "start", 0, len(rows))
    for index, row in enumerate(rows):
        row_blockers: list[str] = []
        row_warnings: list[str] = []
        matched_safety_rules: list[str] = []
        expected_file_sha256: str | None = None
        normalized_title: str | None = None
        basis: str | None = None
        expected_matches: bool | None = None
        current_signals: list[str] = []

        if row is None:
            row_blockers.append("row_not_valid_json_object")
        else:
            allowed_keys = {"schema", "zettel_id", "expected_file_sha256", "title", "basis"}
            if set(row) - allowed_keys:
                row_blockers.append("unsupported_fields")
            if row.get("schema") != ZET_TITLE_REMAP_PROPOSAL_SCHEMA:
                row_blockers.append("unsupported_schema")
            zettel_id = row.get("zettel_id")
            if not isinstance(zettel_id, str) or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(zettel_id):
                row_blockers.append("zettel_id_invalid")
                zettel_id = None
            elif zettel_id in seen_zettel_ids:
                row_blockers.append("zettel_id_duplicate")
                # Stop here: inspecting the same zet twice would read it twice and
                # tally its signals twice for one zet.
                zettel_id = None
            else:
                seen_zettel_ids.add(zettel_id)

            raw_expected_sha256 = row.get("expected_file_sha256")
            if (
                not isinstance(raw_expected_sha256, str)
                or not re.fullmatch(r"sha256:[0-9a-f]{64}", raw_expected_sha256)
            ):
                row_blockers.append("expected_file_sha256_invalid")
            else:
                expected_file_sha256 = raw_expected_sha256

            basis_value = row.get("basis")
            if basis_value not in ZET_TITLE_REMAP_BASIS_VALUES:
                row_blockers.append("basis_invalid")
            else:
                basis = str(basis_value)

            normalized_title = normalized_zet_title_candidate(
                row.get("title"),
                row_blockers,
                matched_safety_rules=matched_safety_rules,
                warning_codes=row_warnings,
                basis=basis,
            )

            if zettel_id is not None:
                try:
                    zettel_path = resolve_zettel_path(root, zettel_id=zettel_id, relative_path=None)
                    relative = archive_relative_path(zettel_path, root)
                    if not relative.startswith("zettels/") or zettel_path.is_symlink():
                        row_blockers.append("target_not_plain_canonical_zet")
                    else:
                        canonical_bytes = read_zet_title_remap_canonical_bytes(zettel_path)
                        current_file_sha256 = "sha256:" + hashlib.sha256(canonical_bytes).hexdigest()
                        expected_matches = bool(
                            expected_file_sha256 and expected_file_sha256 == current_file_sha256
                        )
                        if not expected_matches:
                            row_blockers.append("canonical_file_sha256_mismatch")
                        # Parse the frontmatter out of the bytes that were just
                        # hashed. Re-reading the path would let every decision below
                        # rest on content the recorded hash never covered.
                        try:
                            canonical_text = canonical_bytes.decode("utf-8-sig")
                        except UnicodeDecodeError as exc:
                            raise ArchiveServiceError("Canonical zet is not valid UTF-8.") from exc
                        frontmatter, _canonical_body = split_zettel_text(canonical_text)
                        if not frontmatter or frontmatter.get("id") != zettel_id:
                            row_blockers.append("canonical_frontmatter_identity_mismatch")
                        if frontmatter.get("status") != "canonical":
                            # A redacted or otherwise non-canonical zet is not judged
                            # at all. The census excludes redacted zets because they
                            # expose no title to judge; publishing title-derived facts
                            # about one here would undo that.
                            row_blockers.append("target_status_not_canonical")
                        else:
                            current_signals = zet_title_identifier_signals(
                                {
                                    "title": frontmatter.get("title"),
                                    "facets": frontmatter.get("facets"),
                                }
                            )
                            # Shape is the requirement, not merely "the census would
                            # flag it". `title_matches_external_id` fires whenever the
                            # title equals a registered page-ref facet value, and that
                            # value can be an ordinary human name -- which would make
                            # this a general title editor for any zet whose facets
                            # happen to repeat its title.
                            if "title_is_identifier_shaped" not in current_signals:
                                row_blockers.append("current_title_not_identifier_shaped")
                            current_title = frontmatter.get("title")
                            if (
                                normalized_title is not None
                                and isinstance(current_title, str)
                                and compact_zet_title_comparison_form(current_title)
                                == compact_zet_title_comparison_form(normalized_title)
                            ):
                                row_blockers.append("title_unchanged")
                            # Run the full census predicate on the replacement, with
                            # this target's facets in scope. Refusing only
                            # identifier-shaped replacements missed the other signal:
                            # a replacement equal to the record's own page-ref value
                            # would be re-flagged the moment the write landed.
                            if normalized_title is not None and zet_title_identifier_signals(
                                {
                                    "title": normalized_title,
                                    "facets": frontmatter.get("facets"),
                                }
                            ):
                                row_blockers.append("replacement_would_be_reflagged_by_census")
                except (ArchiveServiceError, ArchivePathError, OSError, ValueError):
                    row_blockers.append("canonical_target_unavailable_or_unreadable")

        row_blockers = unique_preserve_order(row_blockers)
        row_warnings = unique_preserve_order(row_warnings)
        matched_safety_rules = unique_preserve_order(
            matched_safety_rules
        )
        for rule in matched_safety_rules:
            safety_rule_counts[rule] += 1
        for code in row_warnings:
            warning_code_counts[code] += 1
        ready = not row_blockers
        if ready:
            # The proposal file's own sha256 already binds every replacement title
            # collectively, so the plan digest carries no per-title digest. A digest
            # of a short human-scale title is recoverable by search once the other
            # row fields are published beside it.
            fingerprint_rows.append(
                {
                    "row_index": index,
                    "expected_file_sha256": expected_file_sha256,
                    "basis": basis,
                }
            )
            if basis is not None:
                basis_counts[basis] += 1
            for signal in current_signals:
                current_signal_counts[signal] += 1
        item_results.append(
            {
                "row_index": index,
                "status": "ready_for_review" if ready else "blocked",
                "basis": basis,
                "expected_file_sha256_matches": expected_matches,
                "current_title_signals": current_signals,
                "provenance_bound": "title_matches_external_id" in current_signals,
                "matched_safety_rules": matched_safety_rules,
                "blocker_codes": row_blockers,
                "warning_codes": row_warnings,
            }
        )
        if progress_callback is not None and (
            index == 0 or index + 1 == len(rows) or (index + 1) % 250 == 0
        ):
            progress_callback("title-remap-candidates", "scanned", index + 1, len(rows))
    if progress_callback is not None:
        progress_callback("title-remap-candidates", "done", len(rows), len(rows))

    ready_count = sum(1 for item in item_results if item["status"] == "ready_for_review")
    blocked_count = len(item_results) - ready_count
    provenance_bound_ready = sum(
        1
        for item in item_results
        if item["status"] == "ready_for_review" and item["provenance_bound"]
    )
    if blocked_count:
        blockers.append("one_or_more_proposals_blocked")
    if not item_results:
        blockers.append("no_proposal_rows")
    if ready_count and provenance_bound_ready < ready_count:
        warnings.append(
            "Some ready rows replace a title that is only identifier-shaped, not provably this "
            "record's own imported identifier. Those rest on the operator's source, not on the zet."
        )
    if len(item_results) >= 1000:
        warnings.append("Large proposal batch: review in bounded groups before any future approved write.")
    blockers = unique_preserve_order(blockers)
    ok = not blockers

    next_safe_actions: list[str] = []
    if blocked_count:
        next_safe_actions.append(
            "Fix only the blocked row indexes in the private proposal and run the plan again; "
            "each row reports why it blocked in blocker_codes."
        )
    if truncated_due_to_max_items:
        next_safe_actions.append(
            "The proposal has more rows than --max-items allows. Raise --max-items or split the "
            "proposal; nothing was planned for the rows past the ceiling."
        )
    if ok:
        next_safe_actions.append(
            "Have a human review the ready rows against the source record that holds each name. "
            "Then run zet-title-remap-write in dry-run mode, bind its write-plan digest, "
            "and use the explicit approved write."
        )

    # Derived from what the payload actually carries rather than asserted. A
    # literal cannot notice a field that starts echoing a value.
    payload_probe = json.dumps(json_safe(item_results), ensure_ascii=False)
    replacement_echoed = any(
        isinstance(row, dict)
        and isinstance(row.get("title"), str)
        and row["title"].strip()
        and row["title"] in payload_probe
        for row in rows
    )
    return {
        "ok": ok,
        "dry_run": bool(dry_run),
        "schema": ZET_TITLE_REMAP_PLAN_SCHEMA,
        "lifecycle_action": "zet_title_remap_plan",
        "status": "ready_for_human_review" if ok else "blocked",
        "archive_id": archive_id,
        "proposal": {
            "schema": ZET_TITLE_REMAP_PROPOSAL_SCHEMA,
            "sha256": proposal_sha256,
            "path_policy": ZET_TITLE_REMAP_PROPOSAL_PREFIX + "<private>.jsonl",
            "path_echoed": False,
            "bytes_read": len(raw_bytes),
            "line_count": len(raw_lines),
            "contains_private_zettel_ids_and_titles": True,
            "expected_content": "proposal_metadata_and_replacement_title_text_not_canonical_body_text",
            "untrusted_extra_content_possible": True,
            "untrusted_content_echoed": False,
            "tracking_policy": "private_ai_working_file_do_not_commit",
        },
        "plan_digest": sha256_json_value(
            {
                "proposal_sha256": proposal_sha256,
                "archive_id": archive_id,
                "items": fingerprint_rows,
            }
        ),
        "summary": {
            "candidate_count": len(item_results),
            "proposal_line_count": len(raw_lines),
            "inspected_count": len(item_results),
            "truncated_due_to_max_items": truncated_due_to_max_items,
            "ready_for_review_count": ready_count,
            "blocked_count": blocked_count,
            "provenance_bound_ready_count": provenance_bound_ready,
            "ready_row_basis_counts": basis_counts,
            "ready_row_current_title_signal_counts": current_signal_counts,
            "matched_safety_rule_counts": safety_rule_counts,
            "warning_code_counts": warning_code_counts,
            "signals_may_overlap_one_row": True,
            "per_row_count_is": "summary.ready_for_review_count",
            "max_items": effective_max_items,
            "max_canonical_file_bytes": ZET_TITLE_REMAP_MAX_CANONICAL_FILE_BYTES,
            "all_candidates_bound_to_current_canonical_bytes": bool(item_results)
            and all(item["expected_file_sha256_matches"] for item in item_results),
        },
        "items": item_results,
        "detection": {
            "remappable_only_when_current_title_is_identifier_shaped": True,
            "identifier_shape_is_required_not_merely_a_census_signal": True,
            "replacement_must_not_trip_either_census_signal": True,
            "replacement_must_pass_promotion_checklist_specificity": True,
            "replacement_title_max_characters": (
                ZET_TITLE_REMAP_MAX_TITLE_CHARS
            ),
            "replacement_text_originates_from": sorted(ZET_TITLE_REMAP_BASIS_VALUES),
            "non_canonical_or_redacted_targets_are_not_judged": True,
        },
        "normalization_contract": {
            "performed_automatically": False,
            "proposal_author_supplies_normalized_title": True,
            "line_breaks_allowed": False,
            "allowed_whitespace_character": "U+0020 SPACE",
            "leading_or_trailing_space_allowed": False,
            "consecutive_spaces_allowed": False,
            "other_unicode_whitespace_allowed": False,
            "review_normalization_against_source_before_resubmitting": True,
        },
        "title_safety_contract": {
            "matched_rule_names_reported": True,
            "matched_values_reported": False,
            "blocking_rule_names": list(ZET_TITLE_REMAP_SAFETY_RULES),
            "ordinary_public_http_https_url_allowed": True,
            "ordinary_public_http_https_url_warning_code": (
                "title_contains_public_web_url"
            ),
            "bare_security_topic_words_blocked": False,
        },
        "claim_boundary": {
            "checked": (
                "Each proposed replacement against the exact current bytes and frontmatter of its "
                "named canonical zet at this run."
            ),
            "not_checked": [
                "Whether the replacement title is the name the source record actually carried.",
                "Whether the operator's source export is itself complete or correct.",
                "Any canonical zet not named by a proposal row.",
            ],
        },
        "approval_contract": {
            "approved_write_implemented": True,
            "approved_write_command": "zet-title-remap-write",
            "human_review_required": True,
            "write_binds_proposal_sha256": True,
            "write_binds_plan_digest": True,
            "write_binds_write_plan_digest": True,
            "write_revalidates_each_canonical_sha256": True,
            "write_records_before_after_and_title_hashes": True,
            "write_preserves_exact_prior_bytes": True,
            "manual_canonical_edit_recommended": False,
        },
        "write_boundary": {
            "files_written": False,
            "canonical_zets_changed": False,
            "receipts_written": False,
            "provider_state_written": False,
        },
        "blockers": blockers,
        "warnings": warnings,
        "next_safe_actions": next_safe_actions,
        "exit_policy": {
            "zero_only_when_no_blockers_and_every_row_is_ready_for_review": True,
            "nonzero_when_any_row_is_blocked": True,
            "nonzero_also_when_the_proposal_is_empty_exceeds_max_items_or_max_items_is_out_of_range": True,
        },
        "privacy_guards": {
            "title_values_echoed": False,
            "external_id_values_echoed": False,
            "replacement_title_values_echoed": replacement_echoed,
            "replacement_title_digests_published": False,
            "matched_safety_rule_names_echoed": True,
            "matched_safety_rule_values_echoed": False,
            "replacement_title_lengths_published": False,
            "proposal_path_echoed": False,
            "zettel_ids_echoed": False,
            "zettel_paths_echoed": False,
            "body_text_echoed": False,
            "local_absolute_paths_echoed": False,
            "provider_urls_echoed": False,
            "canonical_file_bytes_read": True,
            "untrusted_proposal_text_read": True,
            "writes": False,
        },
    }


def zet_title_remap_candidate_bytes(raw_bytes: bytes, title: str) -> bytes:
    """Replace exactly one top-level YAML title scalar and verify the boundary."""

    require_yaml()
    try:
        text = raw_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ArchiveServiceError("Canonical zet is not valid UTF-8.") from exc
    has_bom = text.startswith("\ufeff")
    payload = text[1:] if has_bom else text
    match = FRONTMATTER_RE.match(payload)
    if match is None:
        raise ArchiveServiceError("Canonical zet has no supported YAML frontmatter.")
    frontmatter_source = match.group(1)
    try:
        node = yaml.compose(frontmatter_source)  # type: ignore[union-attr]
    except Exception as exc:
        raise ArchiveServiceError("Canonical zet frontmatter YAML is unreadable.") from exc
    title_nodes: list[Any] = []
    if node is not None and getattr(node, "id", None) == "mapping":
        for key_node, value_node in getattr(node, "value", []):
            if (
                getattr(key_node, "id", None) == "scalar"
                and getattr(key_node, "value", None) == "title"
            ):
                title_nodes.append(value_node)
    if len(title_nodes) != 1 or getattr(title_nodes[0], "id", None) != "scalar":
        raise ArchiveServiceError("Canonical zet must contain exactly one top-level scalar title.")
    value_node = title_nodes[0]
    start = int(value_node.start_mark.index)
    end = int(value_node.end_mark.index)
    original_scalar = frontmatter_source[start:end]
    trailing_newline = ""
    if original_scalar.endswith("\r\n"):
        trailing_newline = "\r\n"
    elif original_scalar.endswith("\n"):
        trailing_newline = "\n"
    serialized = json.dumps(title, ensure_ascii=False)
    candidate_frontmatter = (
        frontmatter_source[:start]
        + serialized
        + trailing_newline
        + frontmatter_source[end:]
    )
    candidate_payload = (
        payload[: match.start(1)]
        + candidate_frontmatter
        + payload[match.end(1) :]
    )
    candidate_text = ("\ufeff" if has_bom else "") + candidate_payload

    before_frontmatter, before_body = split_zettel_text(text)
    after_frontmatter, after_body = split_zettel_text(candidate_text)
    before_title = before_frontmatter.pop("title", None)
    after_title = after_frontmatter.pop("title", None)
    if (
        not isinstance(before_title, str)
        or after_title != title
        or after_frontmatter != before_frontmatter
        or after_body != before_body
    ):
        raise ArchiveServiceError(
            "Title replacement would change canonical content beyond the title field."
        )
    candidate_bytes = candidate_text.encode("utf-8")
    if candidate_bytes == raw_bytes:
        raise ArchiveServiceError("Title replacement would not change canonical bytes.")
    return candidate_bytes


def materialize_zet_title_remap_candidates(
    root: Path,
    raw_proposal_bytes: bytes,
    plan: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[str]]:
    """Build private write candidates and bind them to the public plan."""

    candidates: list[dict[str, Any]] = []
    blockers: list[str] = []
    plan_items = plan.get("items") if isinstance(plan.get("items"), list) else []
    total_canonical_bytes = 0
    for index, raw_line in enumerate(raw_proposal_bytes.splitlines(keepends=True)):
        try:
            row = json.loads(raw_line.decode("utf-8"))
            if not isinstance(row, dict):
                raise ValueError("proposal_row_not_object")
            zettel_id = row.get("zettel_id")
            expected_file_sha256 = row.get("expected_file_sha256")
            basis = row.get("basis")
            title_blockers: list[str] = []
            title = normalized_zet_title_candidate(
                row.get("title"),
                title_blockers,
                basis=str(basis) if basis in ZET_TITLE_REMAP_BASIS_VALUES else None,
            )
            if (
                title_blockers
                or not isinstance(zettel_id, str)
                or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(zettel_id)
                or not isinstance(expected_file_sha256, str)
                or not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_file_sha256)
                or basis not in ZET_TITLE_REMAP_BASIS_VALUES
                or row.get("schema") != ZET_TITLE_REMAP_PROPOSAL_SCHEMA
                or title is None
            ):
                raise ValueError("proposal_row_changed_after_plan")
            path = resolve_zettel_path(root, zettel_id=zettel_id, relative_path=None)
            relative = archive_relative_path(path, root)
            if path.is_symlink() or not relative.startswith("zettels/"):
                raise ValueError("canonical_target_changed_after_plan")
            before_bytes = read_zet_title_remap_canonical_bytes(path)
            total_canonical_bytes += len(before_bytes)
            if total_canonical_bytes > ZET_TITLE_REMAP_MAX_TOTAL_CANONICAL_BYTES:
                blockers.append("canonical_batch_exceeds_write_limit")
                break
            before_file_sha256 = "sha256:" + hashlib.sha256(before_bytes).hexdigest()
            if before_file_sha256 != expected_file_sha256:
                raise ValueError("canonical_hash_changed_after_plan")
            before_frontmatter, before_body = split_zettel_text(
                before_bytes.decode("utf-8")
            )
            current_title = before_frontmatter.get("title")
            if (
                before_frontmatter.get("id") != zettel_id
                or before_frontmatter.get("status") != "canonical"
                or not isinstance(current_title, str)
                or "title_is_identifier_shaped"
                not in zet_title_identifier_signals(
                    {
                        "title": current_title,
                        "facets": before_frontmatter.get("facets"),
                    }
                )
            ):
                raise ValueError("canonical_metadata_changed_after_plan")
            candidate_bytes = zet_title_remap_candidate_bytes(before_bytes, title)
            after_file_sha256 = (
                "sha256:" + hashlib.sha256(candidate_bytes).hexdigest()
            )
            before_title_sha256 = (
                "sha256:" + hashlib.sha256(current_title.encode("utf-8")).hexdigest()
            )
            after_title_sha256 = (
                "sha256:" + hashlib.sha256(title.encode("utf-8")).hexdigest()
            )
            body_sha256 = (
                "sha256:" + hashlib.sha256(before_body.encode("utf-8")).hexdigest()
            )
            plan_item = (
                plan_items[index]
                if index < len(plan_items) and isinstance(plan_items[index], dict)
                else {}
            )
            if (
                plan_item.get("status") != "ready_for_review"
                or plan_item.get("basis") != basis
                or plan_item.get("expected_file_sha256_matches") is not True
            ):
                raise ValueError("plan_fingerprint_changed")
            before_snapshot = zet_revision_before_snapshot_descriptor(before_bytes)
            candidates.append(
                {
                    "row_index": index,
                    "zettel_id": zettel_id,
                    "path": path,
                    "relative_path": relative,
                    "basis": basis,
                    "before_bytes": before_bytes,
                    "after_bytes": candidate_bytes,
                    "before_file_sha256": before_file_sha256,
                    "after_file_sha256": after_file_sha256,
                    "before_title_sha256": before_title_sha256,
                    "after_title_sha256": after_title_sha256,
                    "body_sha256": body_sha256,
                    "title": title,
                    "before_snapshot": before_snapshot,
                }
            )
        except (
            ArchiveServiceError,
            ArchivePathError,
            OSError,
            UnicodeDecodeError,
            json.JSONDecodeError,
            ValueError,
        ):
            blockers.append("proposal_or_canonical_changed_after_plan")
            break
    if len(candidates) != len(plan_items):
        blockers.append("materialized_candidate_count_mismatch")
    return candidates, unique_preserve_order(blockers)


def zet_title_remap_write_plan_digest(
    *,
    archive_id: str,
    proposal_sha256: str,
    plan_digest: str,
    candidates: list[dict[str, Any]],
) -> str:
    return sha256_json_value(
        {
            "schema": ZET_TITLE_REMAP_WRITE_SCHEMA,
            "archive_id": archive_id,
            "proposal_sha256": proposal_sha256,
            "plan_digest": plan_digest,
            "items": [
                {
                    "row_index": item["row_index"],
                    "zettel_id": item["zettel_id"],
                    "canonical_path": item["relative_path"],
                    "basis": item["basis"],
                    "before_file_sha256": item["before_file_sha256"],
                    "after_file_sha256": item["after_file_sha256"],
                    "before_title_sha256": item["before_title_sha256"],
                    "after_title_sha256": item["after_title_sha256"],
                    "body_sha256": item["body_sha256"],
                    "before_snapshot": item["before_snapshot"],
                }
                for item in candidates
            ],
        }
    )


def zet_title_remap_receipt_relative_path(proposal_sha256: str) -> str:
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", proposal_sha256):
        raise ArchiveServiceError("Title remap proposal SHA-256 is invalid.")
    digest = proposal_sha256.removeprefix("sha256:")
    return f"{ZET_TITLE_REMAP_RECEIPTS_DIR}/{digest}.zet-title-remap.json"


def zet_title_remap_transaction_journal_path(
    title_remap_root: Path,
    proposal_sha256: str,
) -> Path:
    digest = proposal_sha256.removeprefix("sha256:")
    return title_remap_root / f".{digest}.write.transaction.json"


def zet_title_remap_receipt_items(
    candidates: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    return [
        {
            "row_index": item["row_index"],
            "zettel_id": item["zettel_id"],
            "canonical_path": item["relative_path"],
            "basis": item["basis"],
            "before_file_sha256": item["before_file_sha256"],
            "after_file_sha256": item["after_file_sha256"],
            "before_title_sha256": item["before_title_sha256"],
            "after_title_sha256": item["after_title_sha256"],
            "body_sha256": item["body_sha256"],
            "before_snapshot": item["before_snapshot"],
        }
        for item in candidates
    ]


def zet_title_remap_private_items_valid(items: Any) -> bool:
    if not isinstance(items, list) or not 1 <= len(items) <= ZET_TITLE_REMAP_MAX_ITEMS:
        return False
    expected_keys = {
        "row_index",
        "zettel_id",
        "canonical_path",
        "basis",
        "before_file_sha256",
        "after_file_sha256",
        "before_title_sha256",
        "after_title_sha256",
        "body_sha256",
        "before_snapshot",
    }
    snapshot_keys = {
        "object_id",
        "logical_key",
        "size_bytes",
        "mime",
        "stored_sha256_verified",
        "manifest_registered",
    }
    digest_fields = {
        "before_file_sha256",
        "after_file_sha256",
        "before_title_sha256",
        "after_title_sha256",
        "body_sha256",
    }
    for index, item in enumerate(items):
        if not isinstance(item, dict) or set(item) != expected_keys:
            return False
        zettel_id = item.get("zettel_id")
        canonical_path = item.get("canonical_path")
        if (
            item.get("row_index") != index
            or not isinstance(zettel_id, str)
            or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(zettel_id)
            or not isinstance(canonical_path, str)
            or "\\" in canonical_path
            or not canonical_path.startswith("zettels/")
            or not canonical_path.endswith(".md")
            or ".." in PurePosixPath(canonical_path).parts
            or item.get("basis") not in ZET_TITLE_REMAP_BASIS_VALUES
        ):
            return False
        if any(
            not isinstance(item.get(field), str)
            or not re.fullmatch(r"sha256:[0-9a-f]{64}", item[field])
            for field in digest_fields
        ):
            return False
        if item["before_file_sha256"] == item["after_file_sha256"]:
            return False
        snapshot = item.get("before_snapshot")
        if not isinstance(snapshot, dict) or set(snapshot) != snapshot_keys:
            return False
        before_digest = item["before_file_sha256"].removeprefix("sha256:")
        if (
            snapshot.get("object_id") != item["before_file_sha256"]
            or snapshot.get("logical_key")
            != f"objects/sha256/{before_digest[:2]}/{before_digest}"
            or isinstance(snapshot.get("size_bytes"), bool)
            or not isinstance(snapshot.get("size_bytes"), int)
            or not 1
            <= snapshot["size_bytes"]
            <= ZET_TITLE_REMAP_MAX_CANONICAL_FILE_BYTES
            or snapshot.get("mime") != "text/markdown"
            or snapshot.get("stored_sha256_verified") is not True
            or snapshot.get("manifest_registered") is not True
        ):
            return False
    return True


def zet_title_remap_receipt_document_valid(receipt: Any) -> bool:
    if not isinstance(receipt, dict) or set(receipt) != {
        "schema",
        "action",
        "status",
        "applied_at",
        "archive_id",
        "proposal_sha256",
        "plan_digest",
        "write_plan_digest",
        "reviewed_by",
        "human_affirmation",
        "item_count",
        "items",
        "mutation_contract",
        "privacy_guards",
    }:
        return False
    digests = (
        receipt.get("proposal_sha256"),
        receipt.get("plan_digest"),
        receipt.get("write_plan_digest"),
    )
    mutation_contract = receipt.get("mutation_contract")
    privacy_guards = receipt.get("privacy_guards")
    items = receipt.get("items")
    if not isinstance(items, list):
        return False
    return bool(
        receipt.get("schema") == ZET_TITLE_REMAP_RECEIPT_SCHEMA
        and receipt.get("action") == "zet_title_remap_write"
        and receipt.get("status") == "applied"
        and isinstance(receipt.get("applied_at"), str)
        and receipt["applied_at"]
        and isinstance(receipt.get("archive_id"), str)
        and receipt["archive_id"]
        and all(
            isinstance(value, str)
            and re.fullmatch(r"sha256:[0-9a-f]{64}", value)
            for value in digests
        )
        and isinstance(receipt.get("reviewed_by"), str)
        and safe_foreign_quarantine_actor_id(receipt["reviewed_by"])
        == receipt["reviewed_by"]
        and receipt.get("human_affirmation")
        == "all_proposed_titles_reviewed"
        and receipt.get("item_count") == len(items)
    ) and bool(
        zet_title_remap_private_items_valid(items)
        and mutation_contract
        == {
            "field_replaced": "frontmatter.title",
            "body_bytes_preserved": True,
            "other_frontmatter_semantics_preserved": True,
            "updated_at_changed": False,
            "prior_byte_snapshots_verified_before_first_canonical_write": True,
            "rollback_on_runtime_failure": True,
            "crash_recovery_journal_written": True,
        }
        and privacy_guards
        == {
            "old_title_text_stored_in_receipt": False,
            "new_title_text_stored_in_receipt": False,
            "body_text_stored_in_receipt": False,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        }
    )


def zet_title_remap_transaction_journal_document_valid(journal: Any) -> bool:
    if not isinstance(journal, dict) or set(journal) != {
        "schema",
        "action",
        "status",
        "operation",
        "prepared_at",
        "archive_id",
        "proposal_sha256",
        "plan_digest",
        "write_plan_digest",
        "reviewed_by",
        "human_affirmation",
        "final_receipt_path",
        "item_count",
        "items",
        "recovery_contract",
        "privacy_guards",
        "journal_digest",
    }:
        return False
    items = journal.get("items")
    digests = (
        journal.get("proposal_sha256"),
        journal.get("plan_digest"),
        journal.get("write_plan_digest"),
        journal.get("journal_digest"),
    )
    receipt_path = journal.get("final_receipt_path")
    if not isinstance(items, list):
        return False
    digest_document = dict(journal)
    journal_digest = digest_document.pop("journal_digest", None)
    return bool(
        journal.get("schema")
        == ZET_TITLE_REMAP_TRANSACTION_JOURNAL_SCHEMA
        and journal.get("action") == "zet_title_remap_transaction"
        and journal.get("status") == "prepared"
        and journal.get("operation") == "apply"
        and isinstance(journal.get("prepared_at"), str)
        and journal["prepared_at"]
        and isinstance(journal.get("archive_id"), str)
        and journal["archive_id"]
        and all(
            isinstance(value, str)
            and re.fullmatch(r"sha256:[0-9a-f]{64}", value)
            for value in digests
        )
        and isinstance(journal.get("reviewed_by"), str)
        and safe_foreign_quarantine_actor_id(journal["reviewed_by"])
        == journal["reviewed_by"]
        and journal.get("human_affirmation")
        == "all_proposed_titles_reviewed"
        and isinstance(receipt_path, str)
        and re.fullmatch(
            r"receipts/revisions/title-remap/"
            r"[0-9a-f]{64}\.zet-title-remap\.json",
            receipt_path,
        )
        and journal.get("item_count") == len(items)
    ) and bool(
        zet_title_remap_private_items_valid(items)
        and journal.get("recovery_contract")
        == {
            "journal_published_before_first_canonical_write": True,
            "current_state_inferred_from_participant_hashes": True,
            "prior_byte_snapshots_verified_before_journal": True,
            "automatic_resume_implemented": False,
            "automatic_rollback_after_hard_exit_implemented": False,
        }
        and journal.get("privacy_guards")
        == {
            "old_title_text_stored": False,
            "new_title_text_stored": False,
            "body_text_stored": False,
            "contains_private_zettel_ids_and_paths": True,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        }
        and journal_digest == sha256_json_value(digest_document)
    )


def _append_zet_title_remap_snapshot_manifest_records_atomic(
    manifest_path: Path,
    records: list[dict[str, Any]],
) -> None:
    if not records:
        return
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    temporary_path: Path | None = None
    descriptor: int | None = None
    try:
        for _ in range(8):
            candidate = manifest_path.parent / (
                f".{manifest_path.name}.{secrets.token_hex(8)}.title-remap-snapshot.tmp"
            )
            try:
                descriptor = os.open(
                    candidate,
                    os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                    0o600,
                )
                temporary_path = candidate
                break
            except FileExistsError:
                continue
        if temporary_path is None or descriptor is None:
            raise OSError("title_snapshot_manifest_temp_reservation_failed")
        last_byte = b""
        with os.fdopen(descriptor, "wb") as output:
            descriptor = None
            if manifest_path.is_file():
                with manifest_path.open("rb") as source:
                    while True:
                        chunk = source.read(1024 * 1024)
                        if not chunk:
                            break
                        output.write(chunk)
                        last_byte = chunk[-1:]
            if last_byte and last_byte != b"\n":
                output.write(b"\n")
            for record in records:
                output.write(
                    (
                        json.dumps(
                            record,
                            ensure_ascii=False,
                            separators=(",", ":"),
                        )
                        + "\n"
                    ).encode("utf-8")
                )
            output.flush()
            os.fsync(output.fileno())
        os.replace(temporary_path, manifest_path)
        temporary_path = None
        _objet_capture_fsync_dir(manifest_path.parent)
    finally:
        if descriptor is not None:
            os.close(descriptor)
        if temporary_path is not None and temporary_path.exists():
            temporary_path.unlink(missing_ok=True)


def _write_or_verify_zet_title_remap_snapshot_bytes(
    root: Path,
    *,
    canonical_bytes: bytes,
    snapshot: dict[str, Any],
) -> bool:
    expected = zet_revision_before_snapshot_descriptor(canonical_bytes)
    if snapshot != expected:
        raise ArchiveServiceError("title_before_snapshot_binding_mismatch")
    digest = expected["object_id"].removeprefix("sha256:")
    snapshot_path = root.joinpath(
        *PurePosixPath(expected["logical_key"]).parts
    )
    if snapshot_path.exists():
        if (
            snapshot_path.is_symlink()
            or zet_revision_path_has_symlink_component(root, snapshot_path)
            or not snapshot_path.is_file()
            or os.lstat(snapshot_path).st_size != len(canonical_bytes)
            or sha256_path(snapshot_path) != digest
        ):
            raise ArchiveServiceError("title_before_snapshot_bytes_invalid")
        return False
    if zet_revision_path_has_symlink_component(root, snapshot_path):
        raise ArchiveServiceError("title_before_snapshot_path_unsafe")
    snapshot_path.parent.mkdir(parents=True, exist_ok=True)
    temporary_path = snapshot_path.parent / (
        f".{snapshot_path.name}.{secrets.token_hex(8)}.title-remap-snapshot.tmp"
    )
    bytes_written = False
    try:
        descriptor = os.open(
            temporary_path,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL,
            0o600,
        )
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(canonical_bytes)
            handle.flush()
            os.fsync(handle.fileno())
        if sha256_path(temporary_path) != digest:
            raise ArchiveServiceError("title_before_snapshot_write_verification_failed")
        try:
            os.link(temporary_path, snapshot_path)
            bytes_written = True
        except FileExistsError:
            pass
        except OSError:
            final_descriptor: int | None = None
            final_created = False
            final_complete = False
            try:
                final_descriptor = os.open(
                    snapshot_path,
                    os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                    0o600,
                )
                final_created = True
                with os.fdopen(final_descriptor, "wb") as final_handle:
                    final_descriptor = None
                    final_handle.write(canonical_bytes)
                    final_handle.flush()
                    os.fsync(final_handle.fileno())
                final_complete = True
                bytes_written = True
            except FileExistsError:
                final_complete = True
            finally:
                if final_descriptor is not None:
                    os.close(final_descriptor)
                if (
                    final_created
                    and not final_complete
                    and snapshot_path.exists()
                ):
                    snapshot_path.unlink(missing_ok=True)
        _objet_capture_fsync_dir(snapshot_path.parent)
    finally:
        temporary_path.unlink(missing_ok=True)
    if (
        not snapshot_path.is_file()
        or snapshot_path.is_symlink()
        or os.lstat(snapshot_path).st_size != len(canonical_bytes)
        or sha256_path(snapshot_path) != digest
    ):
        raise ArchiveServiceError("title_before_snapshot_write_verification_failed")
    return bytes_written


def _preserve_zet_title_remap_before_snapshots(
    root: Path,
    *,
    candidates: list[dict[str, Any]],
    archive_id: str,
    captured_at: str,
    reviewed_by: str,
    write_plan_digest: str,
) -> dict[str, int]:
    bytes_written = 0
    records_appended = 0
    manifest_path = archive_internal_path(root, "objects/manifests/files.jsonl")
    with _ObjetCaptureManifestLock(root):
        manifest_index, manifest_blockers = zet_revision_snapshot_manifest_index(root)
        if manifest_blockers:
            raise ArchiveServiceError(manifest_blockers[0])
        pending_records: list[dict[str, Any]] = []
        for item in candidates:
            snapshot = item["before_snapshot"]
            if _write_or_verify_zet_title_remap_snapshot_bytes(
                root,
                canonical_bytes=item["before_bytes"],
                snapshot=snapshot,
            ):
                bytes_written += 1
            object_id = snapshot["object_id"]
            digest = object_id.removeprefix("sha256:")
            logical_key = snapshot["logical_key"]

            def record_is_complete(record: Any) -> bool:
                if not isinstance(record, dict):
                    return False
                locations = record.get("locations")
                return bool(
                    record.get("logical_key") == logical_key
                    and record.get("sha256") == digest
                    and record.get("mime") == "text/markdown"
                    and record.get("size_bytes") == len(item["before_bytes"])
                    and isinstance(locations, list)
                    and any(
                        isinstance(location, dict)
                        and location.get("provider") == "local"
                        and location.get("path") == logical_key
                        and location.get("availability") == "available"
                        for location in locations
                    )
                )

            if any(
                record_is_complete(record)
                for record in manifest_index.get(object_id, [])
            ):
                continue
            record = {
                "object_id": object_id,
                "sha256": digest,
                "logical_key": logical_key,
                "mime": "text/markdown",
                "size_bytes": len(item["before_bytes"]),
                "locations": [
                    {
                        "provider": "local",
                        "path": logical_key,
                        "availability": "available",
                    }
                ],
                "provenance": {
                    "created_in": f"archive:{archive_id}",
                    "source": "canonical_zet_before_title_remap",
                    "captured_at": captured_at,
                    "captured_by": reviewed_by,
                    "title_remap_write_plan_digest": write_plan_digest,
                },
            }
            if validate_schema(record, "object-manifest-entry.schema.json"):
                raise ArchiveServiceError("title_before_snapshot_manifest_record_invalid")
            pending_records.append(record)
            manifest_index.setdefault(object_id, []).append(record)
        _append_zet_title_remap_snapshot_manifest_records_atomic(
            manifest_path,
            pending_records,
        )
        records_appended = len(pending_records)
        final_index, final_blockers = zet_revision_snapshot_manifest_index(root)
        if final_blockers:
            raise ArchiveServiceError(final_blockers[0])
        for item in candidates:
            snapshot_blockers = verify_zet_revision_before_snapshot(
                root,
                item["before_snapshot"],
                expected_before_sha256=item["before_file_sha256"],
                manifest_index=final_index,
            )
            if snapshot_blockers:
                raise ArchiveServiceError(snapshot_blockers[0])
    return {
        "snapshot_objects_written_this_run": bytes_written,
        "manifest_records_appended_this_run": records_appended,
        "verified_snapshot_count": len(candidates),
    }


def verify_zet_title_remap_receipt(
    root: Path,
    receipt_path: Path,
    *,
    archive_id: str,
    proposal_sha256: str,
    snapshot_manifest_index: dict[str, list[dict[str, Any]]] | None = None,
    snapshot_manifest_blockers: list[str] | None = None,
) -> dict[str, Any]:
    blockers: list[str] = []
    public_items: list[dict[str, Any]] = []
    try:
        if receipt_path.stat().st_size > ZET_TITLE_REMAP_MAX_RECEIPT_BYTES:
            raise ValueError("receipt_too_large")
        receipt_bytes = receipt_path.read_bytes()
        receipt = json.loads(receipt_bytes.decode("utf-8"))
        if not isinstance(receipt, dict):
            raise ValueError("receipt_not_object")
    except (OSError, UnicodeError, json.JSONDecodeError, ValueError):
        return {
            "ok": False,
            "blockers": ["existing_receipt_unreadable_or_invalid"],
            "items": [],
        }
    if (
        not zet_title_remap_receipt_document_valid(receipt)
        or validate_schema(receipt, "zet-title-remap-receipt.schema.json")
    ):
        blockers.append("existing_receipt_schema_invalid")
    if (
        receipt.get("archive_id") != archive_id
        or receipt.get("proposal_sha256") != proposal_sha256
    ):
        blockers.append("existing_receipt_binding_mismatch")
    items = receipt.get("items") if isinstance(receipt.get("items"), list) else []
    if snapshot_manifest_index is None:
        manifest_index, manifest_blockers = (
            zet_revision_snapshot_manifest_index(root)
        )
    else:
        manifest_index = snapshot_manifest_index
        manifest_blockers = list(snapshot_manifest_blockers or [])
    blockers.extend(manifest_blockers)
    for index, item in enumerate(items):
        item_blockers: list[str] = []
        if not isinstance(item, dict) or item.get("row_index") != index:
            item_blockers.append("receipt_item_invalid")
        else:
            try:
                path = archive_internal_path(root, item["canonical_path"])
                if (
                    path.is_symlink()
                    or not path.is_file()
                    or archive_relative_path(path, root) != item["canonical_path"]
                ):
                    raise ValueError("canonical_path_invalid")
                current = read_zet_title_remap_canonical_bytes(path)
                current_sha256 = (
                    "sha256:" + hashlib.sha256(current).hexdigest()
                )
                if current_sha256 != item.get("after_file_sha256"):
                    item_blockers.append("current_file_sha256_mismatch")
                frontmatter, body = split_zettel_text(current.decode("utf-8"))
                title = frontmatter.get("title")
                if (
                    not isinstance(title, str)
                    or "sha256:" + hashlib.sha256(title.encode("utf-8")).hexdigest()
                    != item.get("after_title_sha256")
                ):
                    item_blockers.append("current_title_sha256_mismatch")
                if (
                    "sha256:" + hashlib.sha256(body.encode("utf-8")).hexdigest()
                    != item.get("body_sha256")
                ):
                    item_blockers.append("current_body_sha256_mismatch")
                item_blockers.extend(
                    verify_zet_revision_before_snapshot(
                        root,
                        item.get("before_snapshot"),
                        expected_before_sha256=item.get("before_file_sha256"),
                        manifest_index=manifest_index,
                    )
                )
            except (
                ArchiveServiceError,
                ArchivePathError,
                OSError,
                UnicodeError,
                ValueError,
            ):
                item_blockers.append("canonical_or_snapshot_unavailable")
        item_blockers = unique_preserve_order(item_blockers)
        blockers.extend(item_blockers)
        public_items.append(
            {
                "row_index": index,
                "status": "already_applied" if not item_blockers else "blocked",
                "blocker_codes": item_blockers,
            }
        )
    if receipt.get("item_count") != len(items) or not items:
        blockers.append("existing_receipt_item_count_mismatch")
    return {
        "ok": not blockers,
        "receipt_sha256": "sha256:" + hashlib.sha256(receipt_bytes).hexdigest(),
        "plan_digest": receipt.get("plan_digest"),
        "write_plan_digest": receipt.get("write_plan_digest"),
        "review_affirmation_verified": (
            receipt.get("human_affirmation") == "all_proposed_titles_reviewed"
        ),
        "items": public_items,
        "blockers": unique_preserve_order(blockers),
    }


def zet_title_remap_write(
    archive_root: Path | str,
    *,
    proposal_path: str,
    expected_proposal_sha256: str,
    expected_plan_digest: str,
    expected_write_plan_digest: str | None = None,
    max_items: int = ZET_TITLE_REMAP_MAX_ITEMS,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    affirm_titles_reviewed: bool = False,
    progress_callback: Callable[
        [str, str, int | None, int | None], None
    ]
    | None = None,
) -> dict[str, Any]:
    if type(dry_run) is not bool or type(approve) is not bool or approve:
        return _compound_exact_human_approval_blocked(
            lifecycle_action="zet_title_remap_write",
        )
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    requested_max_items = int(max_items)
    effective_max_items = max(
        1,
        min(requested_max_items, ZET_TITLE_REMAP_MAX_ITEMS),
    )
    expected_proposal = str(expected_proposal_sha256 or "").strip()
    expected_plan = str(expected_plan_digest or "").strip()
    expected_write = str(expected_write_plan_digest or "").strip()
    reviewer = safe_foreign_quarantine_actor_id(reviewed_by)
    blockers: list[str] = []
    warnings: list[str] = []
    public_items: list[dict[str, Any]] = []
    actual_proposal_sha256: str | None = None
    actual_plan_digest: str | None = None
    actual_write_plan_digest: str | None = None
    receipt_relative: str | None = None
    receipt_sha256: str | None = None
    receipt_exists = False
    receipt_written_this_run = False
    review_affirmation_verified = False
    transaction_journal_path: Path | None = None
    transaction_journal_written = False
    transaction_journal_removed: bool | None = None
    write_lock_path: Path | None = None
    write_lock_removed: bool | None = None
    canonical_files_written: int | None = 0
    canonical_write_attempt_count = 0
    snapshot_result = {
        "snapshot_objects_written_this_run": 0,
        "manifest_records_appended_this_run": 0,
        "verified_snapshot_count": 0,
    }
    rollback = {
        "attempted": False,
        "succeeded": None,
        "canonical_files_restored": 0,
        "receipt_removed": None,
        "transaction_journal_removed": None,
        "transaction_journal_retained": None,
        "write_lock_removed": None,
    }

    def result_payload(status: str) -> dict[str, Any]:
        ok = (
            status in {"ready_to_apply", "applied", "already_applied"}
            and not blockers
        )
        return {
            "ok": ok,
            "schema": ZET_TITLE_REMAP_WRITE_SCHEMA,
            "lifecycle_action": "zet_title_remap_write",
            "status": status,
            "dry_run": bool(dry_run),
            "approved": bool(approve and status == "applied"),
            "archive_id": archive_id,
            "proposal": {
                "sha256": actual_proposal_sha256,
                "expected_sha256_matches": bool(
                    actual_proposal_sha256
                    and actual_proposal_sha256 == expected_proposal
                ),
                "path_echoed": False,
                "tracking_policy": "private_ai_working_file_do_not_commit",
            },
            "plan_digest": actual_plan_digest,
            "expected_plan_digest_matches": bool(
                actual_plan_digest and actual_plan_digest == expected_plan
            ),
            "write_plan_digest": actual_write_plan_digest,
            "expected_write_plan_digest_matches": (
                bool(
                    expected_write
                    and actual_write_plan_digest == expected_write
                )
                if expected_write
                else None
            ),
            "receipt": {
                "path": receipt_relative,
                "path_contains_only_proposal_digest": bool(receipt_relative),
                "exists": receipt_exists,
                "written_this_run": receipt_written_this_run,
                "sha256": receipt_sha256,
                "contains_private_zettel_ids_and_paths": (
                    True
                    if receipt_exists
                    and status in {"applied", "already_applied"}
                    else None
                ),
                "contains_title_or_body_text": (
                    False
                    if receipt_exists
                    and status in {"applied", "already_applied"}
                    else None
                ),
            },
            "transaction_journal": {
                "written_before_first_canonical_write": (
                    True if transaction_journal_written else None
                ),
                "exists": bool(
                    transaction_journal_path
                    and transaction_journal_path.exists()
                ),
                "removed_after_completion": transaction_journal_removed,
                "contains_title_or_body_text": False,
                "path_echoed": False,
                "automatic_resume_implemented": False,
            },
            "prior_byte_snapshots": {
                **snapshot_result,
                "content_addressed": True,
                "exact_complete_before_file_bytes": True,
                "paths_echoed": False,
                "remote_backup_proven": False,
            },
            "summary": {
                "candidate_count": len(public_items),
                "ready_count": sum(
                    1
                    for item in public_items
                    if item.get("status") == "ready_to_apply"
                ),
                "applied_count": sum(
                    1
                    for item in public_items
                    if item.get("status") == "applied"
                ),
                "already_applied_count": sum(
                    1
                    for item in public_items
                    if item.get("status") == "already_applied"
                ),
                "blocked_count": sum(
                    1
                    for item in public_items
                    if item.get("status") == "blocked"
                ),
                "canonical_files_written_this_run": canonical_files_written,
                "canonical_write_attempt_count": canonical_write_attempt_count,
                "max_items": effective_max_items,
                "max_canonical_file_bytes": (
                    ZET_TITLE_REMAP_MAX_CANONICAL_FILE_BYTES
                ),
                "max_total_canonical_bytes": (
                    ZET_TITLE_REMAP_MAX_TOTAL_CANONICAL_BYTES
                ),
            },
            "items": public_items,
            "human_review": {
                "required_for_new_write": True,
                "reviewed_by_supplied": bool(reviewer),
                "reviewed_by_echoed": False,
                "all_titles_reviewed_affirmed": bool(
                    affirm_titles_reviewed
                ),
                "receipt_human_affirmation_verified": (
                    review_affirmation_verified
                ),
            },
            "write_boundary": {
                "canonical_frontmatter_field_replaced": (
                    "title" if status == "applied" else None
                ),
                "canonical_body_bytes_changed": (
                    None if status == "failed_rollback_incomplete" else False
                ),
                "other_frontmatter_fields_changed": (
                    None if status == "failed_rollback_incomplete" else False
                ),
                "updated_at_changed": (
                    None if status == "failed_rollback_incomplete" else False
                ),
                "temporary_write_lock_removed": write_lock_removed,
                "provider_state_written": False,
                "database_rows_written": False,
                "local_prior_byte_objects_may_be_written": bool(approve),
            },
            "rollback": rollback,
            "privacy_guards": {
                "proposal_path_echoed": False,
                "zettel_ids_echoed": False,
                "zettel_paths_echoed": False,
                "old_or_new_title_values_echoed": False,
                "title_hashes_echoed": False,
                "title_lengths_echoed": False,
                "zettel_body_text_echoed": False,
                "snapshot_paths_echoed": False,
                "reviewed_by_echoed": False,
                "absolute_local_paths_echoed": False,
                "provider_urls_echoed": False,
                "provider_api_called": False,
                "model_called": False,
                "secret_store_or_environment_read": False,
            },
            "blockers": unique_preserve_order(blockers),
            "warnings": unique_preserve_order(warnings),
            "next_safe_actions": (
                [
                    "Use the private receipt as title revision evidence and keep the retained prior-byte snapshots."
                ]
                if status == "applied"
                else [
                    "No write is needed; the proposal receipt, current after hashes, and prior-byte snapshots agree."
                ]
                if status == "already_applied"
                else [
                    "Run the unchanged candidate with --approve, the expected write-plan digest, a safe reviewer id, and the explicit title-review affirmation."
                ]
                if status == "ready_to_apply"
                else [
                    "Fix blockers and rerun the read-only title plan when proposal or canonical bytes change."
                ]
            ),
        }

    if requested_max_items != effective_max_items:
        blockers.append("max_items_out_of_range")
    if bool(dry_run) == bool(approve):
        blockers.append("choose_exactly_one_of_dry_run_or_approve")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_proposal):
        blockers.append("expected_proposal_sha256_invalid")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_plan):
        blockers.append("expected_plan_digest_invalid")
    if expected_write and not re.fullmatch(
        r"sha256:[0-9a-f]{64}",
        expected_write,
    ):
        blockers.append("expected_write_plan_digest_invalid")
    if approve and not expected_write:
        blockers.append("expected_write_plan_digest_required_for_approve")

    resolved_proposal = resolve_zet_title_remap_proposal_path(
        root,
        proposal_path,
    )
    raw_proposal_bytes, actual_proposal_sha256 = (
        read_zet_title_remap_proposal_bytes(
            resolved_proposal,
            progress_callback=progress_callback,
        )
    )
    if actual_proposal_sha256 != expected_proposal:
        blockers.append("proposal_sha256_mismatch")
    raw_line_count = len(raw_proposal_bytes.splitlines(keepends=True))
    if raw_line_count > effective_max_items:
        blockers.append("proposal_exceeds_max_items")
    if not raw_line_count:
        blockers.append("proposal_empty")
    title_remap_root = archive_internal_path(
        root,
        ZET_TITLE_REMAP_PROPOSAL_PREFIX.rstrip("/"),
    )
    write_lock_path = title_remap_root / ".title-remap.write.lock"
    if actual_proposal_sha256 and re.fullmatch(
        r"sha256:[0-9a-f]{64}",
        actual_proposal_sha256,
    ):
        receipt_relative = zet_title_remap_receipt_relative_path(
            actual_proposal_sha256
        )
        transaction_journal_path = zet_title_remap_transaction_journal_path(
            title_remap_root,
            actual_proposal_sha256,
        )
    if blockers:
        return result_payload("blocked")

    assert receipt_relative is not None
    assert transaction_journal_path is not None
    receipt_path = archive_internal_path(root, receipt_relative)
    if receipt_path.exists():
        if write_lock_path.exists():
            warnings.append(
                "title_remap_write_lock_remains_inspect_before_cleanup"
            )
        if transaction_journal_path.exists():
            warnings.append(
                "completed_title_transaction_journal_remains_inspect_before_cleanup"
            )
        receipt_exists = True
        verification = verify_zet_title_remap_receipt(
            root,
            receipt_path,
            archive_id=archive_id,
            proposal_sha256=actual_proposal_sha256,
        )
        receipt_sha256 = verification.get("receipt_sha256")
        actual_plan_digest = verification.get("plan_digest")
        actual_write_plan_digest = verification.get("write_plan_digest")
        public_items = (
            verification.get("items")
            if isinstance(verification.get("items"), list)
            else []
        )
        blockers.extend(
            str(item) for item in verification.get("blockers", [])
        )
        if actual_plan_digest != expected_plan:
            blockers.append("existing_receipt_plan_digest_mismatch")
        if expected_write and actual_write_plan_digest != expected_write:
            blockers.append("existing_receipt_write_plan_digest_mismatch")
        review_affirmation_verified = bool(
            verification.get("review_affirmation_verified")
        )
        return result_payload(
            "already_applied" if verification.get("ok") else "blocked"
        )

    if approve:
        if reviewer is None:
            blockers.append("safe_reviewed_by_required")
        if not affirm_titles_reviewed:
            blockers.append("affirm_titles_reviewed_required")
    elif reviewed_by:
        blockers.append("reviewed_by_only_valid_with_approve")
    elif affirm_titles_reviewed:
        blockers.append("affirmation_only_valid_with_approve")
    if blockers:
        return result_payload("blocked")

    def filtered_progress(
        stage: str,
        state: str,
        completed: int | None,
        total: int | None,
    ) -> None:
        if progress_callback is not None and stage != "title-remap-proposal":
            progress_callback(stage, state, completed, total)

    plan = zet_title_remap_plan(
        root,
        proposal_path=proposal_path,
        max_items=effective_max_items,
        dry_run=True,
        progress_callback=filtered_progress,
    )
    actual_plan_digest = (
        plan.get("plan_digest")
        if isinstance(plan.get("plan_digest"), str)
        else None
    )
    if plan.get("proposal", {}).get("sha256") != actual_proposal_sha256:
        blockers.append("proposal_changed_during_plan")
    if not plan.get("ok"):
        blockers.extend(
            f"plan:{item}" for item in plan.get("blockers", [])
        )
    if actual_plan_digest != expected_plan:
        blockers.append("plan_digest_mismatch")
    candidates, materialize_blockers = materialize_zet_title_remap_candidates(
        root,
        raw_proposal_bytes,
        plan,
    )
    blockers.extend(materialize_blockers)
    if not candidates:
        blockers.append("no_write_candidates")
    if blockers:
        public_items = [
            {
                "row_index": item.get("row_index"),
                "status": "blocked",
                "basis": item.get("basis"),
                "blocker_codes": list(item.get("blocker_codes") or []),
            }
            for item in plan.get("items", [])
            if isinstance(item, dict)
        ]
        return result_payload("blocked")
    actual_write_plan_digest = zet_title_remap_write_plan_digest(
        archive_id=archive_id,
        proposal_sha256=actual_proposal_sha256,
        plan_digest=actual_plan_digest,
        candidates=candidates,
    )
    if expected_write and expected_write != actual_write_plan_digest:
        blockers.append("write_plan_digest_mismatch")
    public_items = [
        {
            "row_index": item["row_index"],
            "status": "ready_to_apply",
            "basis": item["basis"],
            "blocker_codes": [],
        }
        for item in candidates
    ]
    if blockers:
        for item in public_items:
            item["status"] = "blocked"
        return result_payload("blocked")
    if dry_run:
        return result_payload("ready_to_apply")

    assert reviewer is not None
    assert actual_plan_digest is not None
    assert actual_write_plan_digest is not None
    applied_at = (
        datetime.now(timezone.utc)
        .replace(microsecond=0)
        .isoformat()
        .replace("+00:00", "Z")
    )
    private_items = zet_title_remap_receipt_items(candidates)
    receipt = {
        "schema": ZET_TITLE_REMAP_RECEIPT_SCHEMA,
        "action": "zet_title_remap_write",
        "status": "applied",
        "applied_at": applied_at,
        "archive_id": archive_id,
        "proposal_sha256": actual_proposal_sha256,
        "plan_digest": actual_plan_digest,
        "write_plan_digest": actual_write_plan_digest,
        "reviewed_by": reviewer,
        "human_affirmation": "all_proposed_titles_reviewed",
        "item_count": len(private_items),
        "items": private_items,
        "mutation_contract": {
            "field_replaced": "frontmatter.title",
            "body_bytes_preserved": True,
            "other_frontmatter_semantics_preserved": True,
            "updated_at_changed": False,
            "prior_byte_snapshots_verified_before_first_canonical_write": True,
            "rollback_on_runtime_failure": True,
            "crash_recovery_journal_written": True,
        },
        "privacy_guards": {
            "old_title_text_stored_in_receipt": False,
            "new_title_text_stored_in_receipt": False,
            "body_text_stored_in_receipt": False,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        },
    }
    if (
        not zet_title_remap_receipt_document_valid(receipt)
        or validate_schema(receipt, "zet-title-remap-receipt.schema.json")
    ):
        blockers.append("receipt_schema_validation_failed")
        return result_payload("blocked")
    transaction_journal = {
        "schema": ZET_TITLE_REMAP_TRANSACTION_JOURNAL_SCHEMA,
        "action": "zet_title_remap_transaction",
        "status": "prepared",
        "operation": "apply",
        "prepared_at": applied_at,
        "archive_id": archive_id,
        "proposal_sha256": actual_proposal_sha256,
        "plan_digest": actual_plan_digest,
        "write_plan_digest": actual_write_plan_digest,
        "reviewed_by": reviewer,
        "human_affirmation": "all_proposed_titles_reviewed",
        "final_receipt_path": receipt_relative,
        "item_count": len(private_items),
        "items": private_items,
        "recovery_contract": {
            "journal_published_before_first_canonical_write": True,
            "current_state_inferred_from_participant_hashes": True,
            "prior_byte_snapshots_verified_before_journal": True,
            "automatic_resume_implemented": False,
            "automatic_rollback_after_hard_exit_implemented": False,
        },
        "privacy_guards": {
            "old_title_text_stored": False,
            "new_title_text_stored": False,
            "body_text_stored": False,
            "contains_private_zettel_ids_and_paths": True,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        },
    }
    transaction_journal["journal_digest"] = sha256_json_value(
        transaction_journal
    )
    if (
        not zet_title_remap_transaction_journal_document_valid(
            transaction_journal
        )
        or validate_schema(
            transaction_journal,
            "zet-title-remap-transaction-journal.schema.json",
        )
    ):
        blockers.append("transaction_journal_schema_validation_failed")
        return result_payload("blocked")

    lock_descriptor: int | None = None
    try:
        lock_descriptor = os.open(
            write_lock_path,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL,
            0o600,
        )
        lock_document = {
            "schema": "wom-kit/zet-title-remap-write-lock/v0.1",
            "proposal_sha256": actual_proposal_sha256,
            "plan_digest": actual_plan_digest,
            "write_plan_digest": actual_write_plan_digest,
            "transaction_journal_name": transaction_journal_path.name,
        }
        with os.fdopen(lock_descriptor, "wb") as lock_handle:
            lock_descriptor = None
            lock_handle.write(
                (
                    json.dumps(
                        lock_document,
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    + "\n"
                ).encode("utf-8")
            )
            lock_handle.flush()
            os.fsync(lock_handle.fileno())
        fsync_directory(write_lock_path.parent)
    except FileExistsError:
        blockers.append("title_remap_write_lock_exists")
        return result_payload("blocked")
    except OSError:
        try:
            if write_lock_path.exists():
                write_lock_path.unlink()
        except OSError:
            pass
        blockers.append("title_remap_write_lock_create_failed")
        return result_payload("blocked")
    finally:
        if lock_descriptor is not None:
            os.close(lock_descriptor)

    try:
        locked_raw_bytes, locked_proposal_sha256 = (
            read_zet_title_remap_proposal_bytes(
                resolved_proposal,
                progress_callback=None,
            )
        )
        locked_plan = zet_title_remap_plan(
            root,
            proposal_path=proposal_path,
            max_items=effective_max_items,
            dry_run=True,
            progress_callback=None,
        )
        locked_candidates, locked_blockers = (
            materialize_zet_title_remap_candidates(
                root,
                locked_raw_bytes,
                locked_plan,
            )
        )
        locked_plan_digest = locked_plan.get("plan_digest")
        locked_write_digest = (
            zet_title_remap_write_plan_digest(
                archive_id=archive_id,
                proposal_sha256=locked_proposal_sha256,
                plan_digest=locked_plan_digest,
                candidates=locked_candidates,
            )
            if (
                locked_plan.get("ok")
                and isinstance(locked_plan_digest, str)
                and not locked_blockers
            )
            else None
        )
        if (
            locked_proposal_sha256 != actual_proposal_sha256
            or locked_plan_digest != actual_plan_digest
            or locked_write_digest != actual_write_plan_digest
        ):
            raise ArchiveServiceError("title_write_candidate_changed_under_lock")
        candidates = locked_candidates
        snapshot_result = _preserve_zet_title_remap_before_snapshots(
            root,
            candidates=candidates,
            archive_id=archive_id,
            captured_at=applied_at,
            reviewed_by=reviewer,
            write_plan_digest=actual_write_plan_digest,
        )
    except Exception:
        try:
            if write_lock_path.exists():
                write_lock_path.unlink()
                fsync_directory(write_lock_path.parent)
            write_lock_removed = not write_lock_path.exists()
        except OSError:
            write_lock_removed = False
        blockers.append("title_write_preflight_or_snapshot_failed")
        return result_payload("blocked")

    try:
        write_json_new_file(transaction_journal_path, transaction_journal)
        transaction_journal_written = True
    except FileExistsError:
        try:
            write_lock_path.unlink()
            fsync_directory(write_lock_path.parent)
            write_lock_removed = True
        except OSError:
            write_lock_removed = False
        blockers.append("title_transaction_journal_exists")
        return result_payload("blocked")
    except OSError:
        try:
            if write_lock_path.exists():
                write_lock_path.unlink()
                fsync_directory(write_lock_path.parent)
            write_lock_removed = not write_lock_path.exists()
        except OSError:
            write_lock_removed = False
        blockers.append("title_transaction_journal_create_failed")
        return result_payload("blocked")

    attempted_candidates: list[dict[str, Any]] = []
    receipt_parent_existed = receipt_path.parent.exists()
    receipt_write_attempted = False
    receipt_owned_this_run = False
    try:
        if progress_callback is not None:
            progress_callback("title-remap-write", "start", 0, len(candidates))
        for index, item in enumerate(candidates, start=1):
            if (
                read_zet_title_remap_canonical_bytes(item["path"])
                != item["before_bytes"]
            ):
                raise RuntimeError("canonical_changed_immediately_before_write")
            attempted_candidates.append(item)
            canonical_write_attempt_count += 1
            write_bytes_atomic(item["path"], item["after_bytes"])
            if (
                read_zet_title_remap_canonical_bytes(item["path"])
                != item["after_bytes"]
            ):
                raise RuntimeError("canonical_write_verification_failed")
            canonical_files_written += 1
            public_items[index - 1]["status"] = "applied"
            if progress_callback is not None:
                progress_callback(
                    "title-remap-write",
                    "written",
                    index,
                    len(candidates),
                )
        for item in candidates:
            current = read_zet_title_remap_canonical_bytes(item["path"])
            if (
                "sha256:" + hashlib.sha256(current).hexdigest()
                != item["after_file_sha256"]
            ):
                raise RuntimeError("canonical_batch_revalidation_failed")
        if progress_callback is not None:
            progress_callback(
                "title-remap-write",
                "done",
                len(candidates),
                len(candidates),
            )
            progress_callback("title-remap-receipt", "start", None, None)
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        receipt_write_attempted = True
        try:
            write_json_new_file(receipt_path, receipt)
            receipt_owned_this_run = True
        except FileExistsError:
            receipt_write_attempted = False
            raise RuntimeError("receipt_created_concurrently")
        except Exception:
            receipt_owned_this_run = receipt_path.exists()
            raise
        receipt_bytes = receipt_path.read_bytes()
        written_receipt = json.loads(receipt_bytes.decode("utf-8"))
        if (
            not zet_title_remap_receipt_document_valid(written_receipt)
            or validate_schema(
                written_receipt,
                "zet-title-remap-receipt.schema.json",
            )
        ):
            raise RuntimeError("written_receipt_schema_validation_failed")
        receipt_sha256 = "sha256:" + hashlib.sha256(receipt_bytes).hexdigest()
        receipt_exists = True
        receipt_written_this_run = True
        review_affirmation_verified = True
        try:
            transaction_journal_path.unlink()
            fsync_directory(transaction_journal_path.parent)
            transaction_journal_removed = True
        except OSError:
            transaction_journal_removed = False
            warnings.append("completed_title_transaction_journal_cleanup_failed")
        if transaction_journal_removed:
            try:
                write_lock_path.unlink()
                fsync_directory(write_lock_path.parent)
                write_lock_removed = True
            except OSError:
                write_lock_removed = False
                warnings.append("temporary_title_write_lock_cleanup_failed")
        else:
            write_lock_removed = False
            warnings.append("title_write_lock_retained_with_transaction_journal")
        if progress_callback is not None:
            progress_callback("title-remap-receipt", "done", None, None)
        return result_payload("applied")
    except Exception:
        rollback["attempted"] = bool(
            attempted_candidates or receipt_write_attempted
        )
        if receipt_owned_this_run and receipt_path.exists():
            try:
                receipt_path.unlink()
            except OSError:
                pass
        receipt_removed = not receipt_path.exists()
        restored = 0
        canonical_restore_ok = True
        for item in reversed(attempted_candidates):
            try:
                write_bytes_atomic(item["path"], item["before_bytes"])
                if (
                    read_zet_title_remap_canonical_bytes(item["path"])
                    != item["before_bytes"]
                ):
                    raise OSError("canonical_restore_verification_failed")
                restored += 1
            except Exception:
                canonical_restore_ok = False
        if canonical_restore_ok and receipt_removed:
            try:
                if transaction_journal_path.exists():
                    transaction_journal_path.unlink()
                    fsync_directory(transaction_journal_path.parent)
                    transaction_journal_removed = True
                else:
                    transaction_journal_removed = False
            except OSError:
                transaction_journal_removed = False
        else:
            transaction_journal_removed = False
        if transaction_journal_removed:
            try:
                if write_lock_path.exists():
                    write_lock_path.unlink()
                    fsync_directory(write_lock_path.parent)
                write_lock_removed = True
            except OSError:
                write_lock_removed = False
        else:
            write_lock_removed = False
        rollback["canonical_files_restored"] = restored
        rollback["receipt_removed"] = receipt_removed
        rollback["transaction_journal_removed"] = (
            transaction_journal_removed
        )
        rollback["transaction_journal_retained"] = bool(
            transaction_journal_path.exists()
        )
        rollback["write_lock_removed"] = write_lock_removed
        rollback["succeeded"] = bool(
            canonical_restore_ok
            and receipt_removed
            and transaction_journal_removed
            and write_lock_removed
        )
        canonical_files_written = None if not rollback["succeeded"] else 0
        receipt_exists = receipt_path.exists()
        receipt_written_this_run = False
        attempted_rows = {
            item["row_index"] for item in attempted_candidates
        }
        for item in public_items:
            item["status"] = (
                "rolled_back"
                if item.get("row_index") in attempted_rows
                else "not_attempted"
            )
        blockers.append(
            "transaction_failed_and_rolled_back"
            if rollback["succeeded"]
            else "transaction_failed_rollback_incomplete"
        )
        return result_payload(
            "failed_rolled_back"
            if rollback["succeeded"]
            else "failed_rollback_incomplete"
        )


def read_zet_title_remap_transaction_journal(
    root: Path,
    path: Path,
    *,
    archive_id: str,
) -> tuple[bytes, dict[str, Any]]:
    if (
        path.is_symlink()
        or zet_revision_path_has_symlink_component(root, path)
        or not path.is_file()
        or not is_path_within_root(path, root)
    ):
        raise ArchiveServiceError("Title transaction journal path is unsafe.")
    try:
        if (
            path.stat().st_size
            > ZET_TITLE_REMAP_MAX_TRANSACTION_JOURNAL_BYTES
        ):
            raise ArchiveServiceError(
                "Title transaction journal exceeds the size limit."
            )
        raw = path.read_bytes()

        def reject_duplicate_pairs(
            pairs: list[tuple[str, Any]],
        ) -> dict[str, Any]:
            parsed: dict[str, Any] = {}
            for key, value in pairs:
                if key in parsed:
                    raise ValueError("title_transaction_journal_duplicate_key")
                parsed[key] = value
            return parsed

        document = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=reject_duplicate_pairs,
        )
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        ValueError,
    ) as exc:
        raise ArchiveServiceError(
            "Title transaction journal is unreadable."
        ) from exc
    match = re.fullmatch(
        r"\.(?P<digest>[0-9a-f]{64})\.write\.transaction\.json",
        path.name,
    )
    if (
        not zet_title_remap_transaction_journal_document_valid(document)
        or validate_schema(
            document,
            "zet-title-remap-transaction-journal.schema.json",
        )
        or match is None
        or document.get("archive_id") != archive_id
    ):
        raise ArchiveServiceError(
            "Title transaction journal binding is invalid."
        )
    proposal_sha256 = "sha256:" + match.group("digest")
    expected_receipt = zet_title_remap_receipt_relative_path(
        proposal_sha256
    )
    if (
        document.get("proposal_sha256") != proposal_sha256
        or document.get("final_receipt_path") != expected_receipt
    ):
        raise ArchiveServiceError(
            "Title transaction journal evidence does not match its filename."
        )
    return raw, document


def read_zet_title_remap_receipt_for_audit(
    root: Path,
    path: Path,
    *,
    archive_id: str,
) -> tuple[bytes, dict[str, Any], str]:
    if (
        path.is_symlink()
        or zet_revision_path_has_symlink_component(root, path)
        or not path.is_file()
        or not is_path_within_root(path, root)
    ):
        raise ArchiveServiceError("Title remap receipt path is unsafe.")
    try:
        if path.stat().st_size > ZET_TITLE_REMAP_MAX_RECEIPT_BYTES:
            raise ArchiveServiceError(
                "Title remap receipt exceeds the size limit."
            )
        raw = path.read_bytes()

        def reject_duplicate_pairs(
            pairs: list[tuple[str, Any]],
        ) -> dict[str, Any]:
            parsed: dict[str, Any] = {}
            for key, value in pairs:
                if key in parsed:
                    raise ValueError("title_remap_receipt_duplicate_key")
                parsed[key] = value
            return parsed

        document = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=reject_duplicate_pairs,
        )
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        ValueError,
    ) as exc:
        raise ArchiveServiceError(
            "Title remap receipt is unreadable."
        ) from exc
    match = re.fullmatch(
        r"(?P<digest>[0-9a-f]{64})\.zet-title-remap\.json",
        path.name,
    )
    if (
        match is None
        or not zet_title_remap_receipt_document_valid(document)
        or document.get("archive_id") != archive_id
    ):
        raise ArchiveServiceError(
            "Title remap receipt binding is invalid."
        )
    proposal_sha256 = "sha256:" + match.group("digest")
    if document.get("proposal_sha256") != proposal_sha256:
        raise ArchiveServiceError(
            "Title remap receipt does not match its filename."
        )
    return raw, document, proposal_sha256


def resolve_zet_title_remap_revert_source_receipt_path(
    root: Path,
    raw_path: str,
) -> tuple[Path, str]:
    try:
        normalized = normalize_archive_relative_path(raw_path)
    except ArchivePathError as exc:
        raise ArchiveServiceError(
            "Title remap receipt path must be archive-relative."
        ) from exc
    if not re.fullmatch(
        rf"{re.escape(ZET_TITLE_REMAP_RECEIPTS_DIR)}/"
        r"[0-9a-f]{64}\.zet-title-remap\.json",
        normalized,
    ):
        raise ArchiveServiceError(
            "Title remap receipt path is outside the supported receipt directory."
        )
    unresolved = root.resolve()
    for part in normalized.split("/"):
        unresolved = unresolved / part
        if unresolved.is_symlink():
            raise ArchiveServiceError(
                "Title remap receipt paths must not contain symbolic links."
            )
    path = archive_internal_path(root, normalized)
    if path.is_symlink() or not path.is_file():
        raise ArchiveServiceError(
            "Title remap receipt must be an existing regular file."
        )
    return path, normalized


def zet_title_remap_revert_receipt_relative_path(
    source_receipt_sha256: str,
) -> str:
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", source_receipt_sha256):
        raise ArchiveServiceError(
            "Title remap source receipt SHA-256 is invalid."
        )
    digest = source_receipt_sha256.removeprefix("sha256:")
    return (
        f"{ZET_TITLE_REMAP_REVERT_RECEIPTS_DIR}/"
        f"{digest}.zet-title-remap-revert.json"
    )


def materialize_zet_title_remap_revert_plan_items(
    root: Path,
    receipt: dict[str, Any],
    *,
    max_items: int,
    manifest_index: dict[str, list[dict[str, Any]]],
    progress_callback: Callable[
        [str, str, int | None, int | None], None
    ]
    | None = None,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[str]]:
    private_items = (
        receipt.get("items")
        if isinstance(receipt.get("items"), list)
        else []
    )
    blockers: list[str] = []
    private_bindings: list[dict[str, Any]] = []
    public_items: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    seen_paths: set[str] = set()
    if not 1 <= len(private_items) <= max_items:
        blockers.append("source_receipt_item_count_exceeds_max_items")
        return private_bindings, public_items, blockers

    if progress_callback is not None:
        progress_callback(
            "title-revert-participants",
            "start",
            0,
            len(private_items),
        )
    for index, item in enumerate(private_items):
        item_blockers: list[str] = []
        current_bytes: bytes | None = None
        snapshot_bytes: bytes | None = None
        deterministic_inverse_verified = False
        zettel_id = item.get("zettel_id")
        canonical_relative = item.get("canonical_path")
        if zettel_id in seen_ids:
            item_blockers.append("source_receipt_duplicate_zettel_id")
        if canonical_relative in seen_paths:
            item_blockers.append("source_receipt_duplicate_canonical_path")
        if isinstance(zettel_id, str):
            seen_ids.add(zettel_id)
        if isinstance(canonical_relative, str):
            seen_paths.add(canonical_relative)

        try:
            canonical_path = archive_internal_path(
                root,
                str(canonical_relative),
            )
            if (
                canonical_path.is_symlink()
                or zet_revision_path_has_symlink_component(
                    root,
                    canonical_path,
                )
                or not canonical_path.is_file()
                or archive_relative_path(canonical_path, root)
                != canonical_relative
            ):
                raise ArchiveServiceError("unsafe_current_canonical")
            current_bytes = read_zet_title_remap_canonical_bytes(
                canonical_path
            )
            current_sha256 = (
                "sha256:" + hashlib.sha256(current_bytes).hexdigest()
            )
            if current_sha256 != item.get("after_file_sha256"):
                item_blockers.append(
                    "current_file_does_not_match_source_receipt_after"
                )
            current_frontmatter, current_body = split_zettel_text(
                current_bytes.decode("utf-8")
            )
            current_title = current_frontmatter.get("title")
            if current_frontmatter.get("id") != zettel_id:
                item_blockers.append("current_zettel_identity_mismatch")
            if (
                not isinstance(current_title, str)
                or "sha256:"
                + hashlib.sha256(current_title.encode("utf-8")).hexdigest()
                != item.get("after_title_sha256")
            ):
                item_blockers.append(
                    "current_title_does_not_match_source_receipt_after"
                )
            if (
                "sha256:"
                + hashlib.sha256(current_body.encode("utf-8")).hexdigest()
                != item.get("body_sha256")
            ):
                item_blockers.append(
                    "current_body_does_not_match_source_receipt"
                )

            snapshot_issues = verify_zet_revision_before_snapshot(
                root,
                item.get("before_snapshot"),
                expected_before_sha256=item.get("before_file_sha256"),
                manifest_index=manifest_index,
            )
            item_blockers.extend(snapshot_issues)
            snapshot = item.get("before_snapshot")
            if not snapshot_issues and isinstance(snapshot, dict):
                snapshot_path = archive_internal_path(
                    root,
                    str(snapshot.get("logical_key")),
                )
                snapshot_bytes = snapshot_path.read_bytes()
                snapshot_sha256 = (
                    "sha256:" + hashlib.sha256(snapshot_bytes).hexdigest()
                )
                if snapshot_sha256 != item.get("before_file_sha256"):
                    item_blockers.append(
                        "prior_snapshot_file_sha256_mismatch"
                    )
                snapshot_frontmatter, snapshot_body = split_zettel_text(
                    snapshot_bytes.decode("utf-8")
                )
                snapshot_title = snapshot_frontmatter.get("title")
                if snapshot_frontmatter.get("id") != zettel_id:
                    item_blockers.append(
                        "prior_snapshot_zettel_identity_mismatch"
                    )
                if (
                    not isinstance(snapshot_title, str)
                    or "sha256:"
                    + hashlib.sha256(
                        snapshot_title.encode("utf-8")
                    ).hexdigest()
                    != item.get("before_title_sha256")
                ):
                    item_blockers.append(
                        "prior_snapshot_title_sha256_mismatch"
                    )
                if (
                    "sha256:"
                    + hashlib.sha256(
                        snapshot_body.encode("utf-8")
                    ).hexdigest()
                    != item.get("body_sha256")
                ):
                    item_blockers.append(
                        "prior_snapshot_body_sha256_mismatch"
                    )
                if isinstance(current_title, str):
                    deterministic_inverse_verified = bool(
                        zet_title_remap_candidate_bytes(
                            snapshot_bytes,
                            current_title,
                        )
                        == current_bytes
                    )
                    if not deterministic_inverse_verified:
                        item_blockers.append(
                            "source_receipt_not_exact_title_only_transition"
                        )
        except (
            ArchiveServiceError,
            ArchivePathError,
            OSError,
            UnicodeError,
            ValueError,
        ):
            item_blockers.append(
                "current_or_prior_snapshot_unavailable"
            )
        except yaml.YAMLError:  # type: ignore[union-attr]
            item_blockers.append(
                "current_or_prior_snapshot_unavailable"
            )

        item_blockers = unique_preserve_order(item_blockers)
        blockers.extend(item_blockers)
        public_items.append(
            {
                "row_index": index,
                "status": (
                    "ready_to_revert" if not item_blockers else "blocked"
                ),
                "current_matches_applied_receipt": bool(
                    current_bytes is not None
                    and "current_file_does_not_match_source_receipt_after"
                    not in item_blockers
                ),
                "prior_snapshot_verified": bool(
                    snapshot_bytes is not None
                    and not any(
                        code.startswith("before_snapshot_")
                        or code.startswith("prior_snapshot_")
                        for code in item_blockers
                    )
                ),
                "deterministic_title_only_inverse_verified": (
                    deterministic_inverse_verified
                ),
                "blocker_codes": item_blockers,
            }
        )
        if not item_blockers:
            private_bindings.append(
                {
                    "row_index": index,
                    "zettel_id": zettel_id,
                    "canonical_path": canonical_relative,
                    "applied_file_sha256": item["after_file_sha256"],
                    "reverted_file_sha256": item["before_file_sha256"],
                    "applied_title_sha256": item["after_title_sha256"],
                    "reverted_title_sha256": item[
                        "before_title_sha256"
                    ],
                    "body_sha256": item["body_sha256"],
                    "before_snapshot": item["before_snapshot"],
                }
            )
        if progress_callback is not None and (
            index == 0
            or index + 1 == len(private_items)
            or (index + 1) % 100 == 0
        ):
            progress_callback(
                "title-revert-participants",
                "verified",
                index + 1,
                len(private_items),
            )
    if progress_callback is not None:
        progress_callback(
            "title-revert-participants",
            "done",
            len(private_items),
            len(private_items),
        )
    return (
        private_bindings,
        public_items,
        unique_preserve_order(blockers),
    )


def zet_title_remap_revert_transaction_journal_path(
    title_remap_root: Path,
    source_receipt_sha256: str,
) -> Path:
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", source_receipt_sha256):
        raise ArchiveServiceError(
            "Title remap source receipt SHA-256 is invalid."
        )
    digest = source_receipt_sha256.removeprefix("sha256:")
    return title_remap_root / f".{digest}.revert.transaction.json"


def zet_title_remap_revert_receipt_document_valid(
    receipt: Any,
) -> bool:
    if not isinstance(receipt, dict) or set(receipt) != {
        "schema",
        "action",
        "status",
        "reverted_at",
        "archive_id",
        "source_receipt_path",
        "source_receipt_sha256",
        "source_proposal_sha256",
        "source_plan_digest",
        "source_write_plan_digest",
        "planner_wom_kit_version",
        "source_history_audit_digest",
        "revert_plan_digest",
        "reviewed_by",
        "human_affirmations",
        "item_count",
        "items",
        "mutation_contract",
        "privacy_guards",
    }:
        return False
    items = receipt.get("items")
    digest_fields = (
        "source_receipt_sha256",
        "source_proposal_sha256",
        "source_plan_digest",
        "source_write_plan_digest",
        "source_history_audit_digest",
        "revert_plan_digest",
    )
    return bool(
        receipt.get("schema")
        == ZET_TITLE_REMAP_REVERT_RECEIPT_SCHEMA
        and receipt.get("action") == "zet_title_remap_revert"
        and receipt.get("status") == "reverted"
        and isinstance(receipt.get("reverted_at"), str)
        and receipt["reverted_at"]
        and isinstance(receipt.get("archive_id"), str)
        and receipt["archive_id"]
        and isinstance(receipt.get("source_receipt_path"), str)
        and re.fullmatch(
            r"receipts/revisions/title-remap/"
            r"[0-9a-f]{64}\.zet-title-remap\.json",
            receipt["source_receipt_path"],
        )
        and all(
            isinstance(receipt.get(field), str)
            and re.fullmatch(
                r"sha256:[0-9a-f]{64}",
                receipt[field],
            )
            for field in digest_fields
        )
        and isinstance(
            receipt.get("planner_wom_kit_version"),
            str,
        )
        and re.fullmatch(
            r"[0-9]+\.[0-9]+\.[0-9]+",
            receipt["planner_wom_kit_version"],
        )
        and isinstance(receipt.get("reviewed_by"), str)
        and safe_foreign_quarantine_actor_id(receipt["reviewed_by"])
        == receipt["reviewed_by"]
        and receipt.get("human_affirmations")
        == {
            "all_title_reversions_reviewed": True,
            "archive_quiescence_confirmed": True,
        }
        and isinstance(items, list)
        and receipt.get("item_count") == len(items)
        and zet_title_remap_private_items_valid(items)
        and receipt.get("mutation_contract")
        == {
            "field_restored": "frontmatter.title",
            "exact_prior_file_bytes_restored": True,
            "body_bytes_preserved": True,
            "other_frontmatter_semantics_restored": True,
            "updated_at_changed": False,
            "source_receipt_preserved": True,
            "rollback_on_runtime_failure": True,
            "crash_recovery_journal_written": True,
        }
        and receipt.get("privacy_guards")
        == {
            "old_title_text_stored_in_receipt": False,
            "new_title_text_stored_in_receipt": False,
            "body_text_stored_in_receipt": False,
            "contains_private_zettel_ids_and_paths": True,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        }
    )


def zet_title_remap_revert_transaction_journal_document_valid(
    journal: Any,
) -> bool:
    if not isinstance(journal, dict) or set(journal) != {
        "schema",
        "action",
        "status",
        "operation",
        "prepared_at",
        "archive_id",
        "source_receipt_path",
        "source_receipt_sha256",
        "planner_wom_kit_version",
        "source_history_audit_digest",
        "revert_plan_digest",
        "reviewed_by",
        "human_affirmations",
        "final_receipt_path",
        "item_count",
        "items",
        "recovery_contract",
        "privacy_guards",
        "journal_digest",
    }:
        return False
    items = journal.get("items")
    final_receipt_path = journal.get("final_receipt_path")
    digest_document = dict(journal)
    journal_digest = digest_document.pop("journal_digest", None)
    return bool(
        journal.get("schema")
        == ZET_TITLE_REMAP_REVERT_TRANSACTION_JOURNAL_SCHEMA
        and journal.get("action")
        == "zet_title_remap_revert_transaction"
        and journal.get("status") == "prepared"
        and journal.get("operation") == "revert"
        and isinstance(journal.get("prepared_at"), str)
        and journal["prepared_at"]
        and isinstance(journal.get("archive_id"), str)
        and journal["archive_id"]
        and isinstance(journal.get("source_receipt_path"), str)
        and re.fullmatch(
            r"receipts/revisions/title-remap/"
            r"[0-9a-f]{64}\.zet-title-remap\.json",
            journal["source_receipt_path"],
        )
        and all(
            isinstance(journal.get(field), str)
            and re.fullmatch(
                r"sha256:[0-9a-f]{64}",
                journal[field],
            )
            for field in (
                "source_receipt_sha256",
                "source_history_audit_digest",
                "revert_plan_digest",
                "journal_digest",
            )
        )
        and isinstance(
            journal.get("planner_wom_kit_version"),
            str,
        )
        and re.fullmatch(
            r"[0-9]+\.[0-9]+\.[0-9]+",
            journal["planner_wom_kit_version"],
        )
        and isinstance(journal.get("reviewed_by"), str)
        and safe_foreign_quarantine_actor_id(journal["reviewed_by"])
        == journal["reviewed_by"]
        and journal.get("human_affirmations")
        == {
            "all_title_reversions_reviewed": True,
            "archive_quiescence_confirmed": True,
        }
        and isinstance(final_receipt_path, str)
        and re.fullmatch(
            r"receipts/revisions/title-remap/reverts/"
            r"[0-9a-f]{64}\.zet-title-remap-revert\.json",
            final_receipt_path,
        )
        and isinstance(items, list)
        and journal.get("item_count") == len(items)
        and zet_title_remap_private_items_valid(items)
        and journal.get("recovery_contract")
        == {
            "journal_published_before_first_canonical_write": True,
            "current_state_inferred_from_participant_hashes": True,
            "prior_byte_snapshots_verified_before_journal": True,
            "automatic_resume_implemented": False,
            "automatic_rollback_after_hard_exit_implemented": False,
        }
        and journal.get("privacy_guards")
        == {
            "old_title_text_stored": False,
            "new_title_text_stored": False,
            "body_text_stored": False,
            "contains_private_zettel_ids_and_paths": True,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        }
        and journal_digest == sha256_json_value(digest_document)
    )


def read_zet_title_remap_revert_receipt(
    root: Path,
    path: Path,
    *,
    archive_id: str,
    source_receipt_sha256: str,
) -> tuple[bytes, dict[str, Any], str]:
    expected_relative = zet_title_remap_revert_receipt_relative_path(
        source_receipt_sha256
    )
    expected_path = archive_internal_path(root, expected_relative)
    if (
        path.resolve() != expected_path.resolve()
        or path.is_symlink()
        or zet_revision_path_has_symlink_component(root, path)
        or not path.is_file()
        or not is_path_within_root(path, root)
    ):
        raise ArchiveServiceError(
            "Title remap revert receipt path is unsafe."
        )
    try:
        if path.stat().st_size > ZET_TITLE_REMAP_MAX_RECEIPT_BYTES:
            raise ValueError("title_revert_receipt_too_large")
        raw = path.read_bytes()

        def reject_duplicate_pairs(
            pairs: list[tuple[str, Any]],
        ) -> dict[str, Any]:
            parsed: dict[str, Any] = {}
            for key, value in pairs:
                if key in parsed:
                    raise ValueError(
                        "title_revert_receipt_duplicate_key"
                    )
                parsed[key] = value
            return parsed

        document = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=reject_duplicate_pairs,
        )
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        ValueError,
    ) as exc:
        raise ArchiveServiceError(
            "Title remap revert receipt is unreadable."
        ) from exc
    if (
        not zet_title_remap_revert_receipt_document_valid(document)
        or validate_schema(
            document,
            "zet-title-remap-revert-receipt.schema.json",
        )
        or document.get("archive_id") != archive_id
        or document.get("source_receipt_sha256")
        != source_receipt_sha256
    ):
        raise ArchiveServiceError(
            "Title remap revert receipt binding is invalid."
        )
    return (
        raw,
        document,
        "sha256:" + hashlib.sha256(raw).hexdigest(),
    )


def read_zet_title_remap_revert_transaction_journal(
    root: Path,
    path: Path,
    *,
    archive_id: str,
) -> tuple[bytes, dict[str, Any]]:
    if (
        path.is_symlink()
        or zet_revision_path_has_symlink_component(root, path)
        or not path.is_file()
        or not is_path_within_root(path, root)
    ):
        raise ArchiveServiceError(
            "Title remap revert journal path is unsafe."
        )
    try:
        if (
            path.stat().st_size
            > ZET_TITLE_REMAP_MAX_TRANSACTION_JOURNAL_BYTES
        ):
            raise ValueError("title_revert_journal_too_large")
        raw = path.read_bytes()

        def reject_duplicate_pairs(
            pairs: list[tuple[str, Any]],
        ) -> dict[str, Any]:
            parsed: dict[str, Any] = {}
            for key, value in pairs:
                if key in parsed:
                    raise ValueError(
                        "title_revert_journal_duplicate_key"
                    )
                parsed[key] = value
            return parsed

        document = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=reject_duplicate_pairs,
        )
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        ValueError,
    ) as exc:
        raise ArchiveServiceError(
            "Title remap revert journal is unreadable."
        ) from exc
    source_receipt_sha256 = document.get("source_receipt_sha256")
    expected_path = (
        zet_title_remap_revert_transaction_journal_path(
            path.parent,
            source_receipt_sha256,
        )
        if isinstance(source_receipt_sha256, str)
        and re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            source_receipt_sha256,
        )
        else None
    )
    if (
        expected_path is None
        or path.resolve() != expected_path.resolve()
        or document.get("archive_id") != archive_id
        or not zet_title_remap_revert_transaction_journal_document_valid(
            document
        )
        or validate_schema(
            document,
            "zet-title-remap-revert-transaction-journal.schema.json",
        )
    ):
        raise ArchiveServiceError(
            "Title remap revert journal binding is invalid."
        )
    return raw, document


def classify_zet_title_remap_revert_transaction_journal(
    root: Path,
    journal: dict[str, Any],
) -> dict[str, Any]:
    classified = classify_zet_title_remap_transaction_journal(
        root,
        journal,
    )
    status = classified["status"]
    if status == "prepared":
        # The generic classifier calls all-before prepared. For a revert,
        # original apply "after" bytes are the transaction's before state.
        status = "fully_reverted_receipt_missing"
    elif status == "fully_applied_receipt_missing":
        status = "prepared"
    elif status == "partially_applied":
        status = "partially_reverted"
    classified["status"] = status
    return classified


def verify_zet_title_remap_revert_receipt(
    root: Path,
    revert_receipt_path: Path,
    *,
    archive_id: str,
    source_receipt_path: str,
    source_receipt_sha256: str,
    source_receipt: dict[str, Any],
    manifest_index: dict[str, list[dict[str, Any]]],
) -> dict[str, Any]:
    blockers: list[str] = []
    public_items: list[dict[str, Any]] = []
    try:
        (
            raw,
            revert_receipt,
            receipt_sha256,
        ) = read_zet_title_remap_revert_receipt(
            root,
            revert_receipt_path,
            archive_id=archive_id,
            source_receipt_sha256=source_receipt_sha256,
        )
    except ArchiveServiceError:
        return {
            "ok": False,
            "receipt_sha256": None,
            "items": [],
            "blockers": [
                "title_revert_receipt_unreadable_or_invalid"
            ],
        }
    expected_fields = {
        "source_receipt_path": source_receipt_path,
        "source_receipt_sha256": source_receipt_sha256,
        "source_proposal_sha256": source_receipt.get(
            "proposal_sha256"
        ),
        "source_plan_digest": source_receipt.get("plan_digest"),
        "source_write_plan_digest": source_receipt.get(
            "write_plan_digest"
        ),
        "item_count": source_receipt.get("item_count"),
        "items": source_receipt.get("items"),
    }
    if any(
        revert_receipt.get(field) != value
        for field, value in expected_fields.items()
    ):
        blockers.append(
            "title_revert_receipt_source_binding_mismatch"
        )
    source_items = (
        source_receipt.get("items")
        if isinstance(source_receipt.get("items"), list)
        else []
    )
    expected_revert_plan_digest = sha256_json_value(
        {
            "schema": ZET_TITLE_REMAP_REVERT_PLAN_SCHEMA,
            "wom_kit_version": revert_receipt.get(
                "planner_wom_kit_version"
            ),
            "archive_id": archive_id,
            "source_receipt_path": source_receipt_path,
            "source_receipt_sha256": source_receipt_sha256,
            "source_proposal_sha256": source_receipt.get(
                "proposal_sha256"
            ),
            "source_plan_digest": source_receipt.get(
                "plan_digest"
            ),
            "source_write_plan_digest": source_receipt.get(
                "write_plan_digest"
            ),
            "source_applied_at": source_receipt.get("applied_at"),
            "history_audit_digest": revert_receipt.get(
                "source_history_audit_digest"
            ),
            "future_revert_receipt_path": (
                zet_title_remap_revert_receipt_relative_path(
                    source_receipt_sha256
                )
            ),
            "items": [
                {
                    "row_index": index,
                    "zettel_id": item["zettel_id"],
                    "canonical_path": item["canonical_path"],
                    "applied_file_sha256": item[
                        "after_file_sha256"
                    ],
                    "reverted_file_sha256": item[
                        "before_file_sha256"
                    ],
                    "applied_title_sha256": item[
                        "after_title_sha256"
                    ],
                    "reverted_title_sha256": item[
                        "before_title_sha256"
                    ],
                    "body_sha256": item["body_sha256"],
                    "before_snapshot": item["before_snapshot"],
                }
                for index, item in enumerate(source_items)
            ],
        }
    )
    if (
        revert_receipt.get("revert_plan_digest")
        != expected_revert_plan_digest
    ):
        blockers.append(
            "title_revert_receipt_plan_digest_mismatch"
        )
    for index, item in enumerate(
        source_items
    ):
        item_blockers: list[str] = []
        current_matches = False
        title_matches = False
        body_matches = False
        snapshot_matches = False
        try:
            canonical_path = archive_internal_path(
                root,
                item["canonical_path"],
            )
            if (
                canonical_path.is_symlink()
                or zet_revision_path_has_symlink_component(
                    root,
                    canonical_path,
                )
                or not canonical_path.is_file()
                or archive_relative_path(canonical_path, root)
                != item["canonical_path"]
            ):
                raise ArchiveServiceError(
                    "unsafe_reverted_canonical"
                )
            current = read_zet_title_remap_canonical_bytes(
                canonical_path
            )
            current_matches = (
                "sha256:" + hashlib.sha256(current).hexdigest()
                == item["before_file_sha256"]
            )
            frontmatter, body = split_zettel_text(
                current.decode("utf-8")
            )
            title = frontmatter.get("title")
            title_matches = bool(
                isinstance(title, str)
                and "sha256:"
                + hashlib.sha256(title.encode("utf-8")).hexdigest()
                == item["before_title_sha256"]
            )
            body_matches = bool(
                "sha256:"
                + hashlib.sha256(body.encode("utf-8")).hexdigest()
                == item["body_sha256"]
            )
            snapshot_issues = verify_zet_revision_before_snapshot(
                root,
                item.get("before_snapshot"),
                expected_before_sha256=item.get(
                    "before_file_sha256"
                ),
                manifest_index=manifest_index,
            )
            snapshot_matches = not snapshot_issues
            item_blockers.extend(snapshot_issues)
            if frontmatter.get("id") != item.get("zettel_id"):
                item_blockers.append(
                    "reverted_zettel_identity_mismatch"
                )
            if not current_matches:
                item_blockers.append(
                    "reverted_file_sha256_mismatch"
                )
            if not title_matches:
                item_blockers.append(
                    "reverted_title_sha256_mismatch"
                )
            if not body_matches:
                item_blockers.append(
                    "reverted_body_sha256_mismatch"
                )
        except (
            ArchiveServiceError,
            ArchivePathError,
            OSError,
            UnicodeError,
            ValueError,
        ):
            item_blockers.append(
                "reverted_canonical_unavailable_or_invalid"
            )
        except yaml.YAMLError:  # type: ignore[union-attr]
            item_blockers.append(
                "reverted_canonical_unavailable_or_invalid"
            )
        item_blockers = unique_preserve_order(item_blockers)
        blockers.extend(item_blockers)
        public_items.append(
            {
                "row_index": index,
                "status": (
                    "reverted_verified"
                    if not item_blockers
                    else "blocked"
                ),
                "current_matches_prior_file_hash": current_matches,
                "title_matches_prior_hash": title_matches,
                "body_hash_preserved": body_matches,
                "prior_snapshot_verified": snapshot_matches,
                "blocker_codes": item_blockers,
            }
        )
    return {
        "ok": not blockers,
        "receipt_sha256": receipt_sha256,
        "receipt_bytes_read": len(raw),
        "revert_plan_digest": revert_receipt.get(
            "revert_plan_digest"
        ),
        "review_affirmations_verified": bool(
            revert_receipt.get("human_affirmations")
            == {
                "all_title_reversions_reviewed": True,
                "archive_quiescence_confirmed": True,
            }
        ),
        "items": public_items,
        "blockers": unique_preserve_order(blockers),
    }


def classify_zet_title_remap_transaction_journal(
    root: Path,
    journal: dict[str, Any],
) -> dict[str, Any]:
    before_count = 0
    after_count = 0
    divergent_count = 0
    missing_count = 0
    for item in journal["items"]:
        try:
            path = archive_internal_path(root, item["canonical_path"])
            if (
                path.is_symlink()
                or zet_revision_path_has_symlink_component(root, path)
                or not path.is_file()
                or archive_relative_path(path, root)
                != item["canonical_path"]
            ):
                missing_count += 1
                continue
            current = read_zet_title_remap_canonical_bytes(path)
            current_sha256 = (
                "sha256:" + hashlib.sha256(current).hexdigest()
            )
            current_frontmatter, _current_body = split_zettel_text(
                current.decode("utf-8")
            )
            if current_frontmatter.get("id") != item["zettel_id"]:
                divergent_count += 1
                continue
        except (
            ArchiveServiceError,
            ArchivePathError,
            OSError,
            UnicodeError,
            ValueError,
        ):
            missing_count += 1
            continue
        if current_sha256 == item["before_file_sha256"]:
            before_count += 1
        elif current_sha256 == item["after_file_sha256"]:
            after_count += 1
        else:
            divergent_count += 1
    if missing_count or divergent_count:
        status = "divergent"
    elif after_count == 0:
        status = "prepared"
    elif before_count == 0:
        status = "fully_applied_receipt_missing"
    else:
        status = "partially_applied"
    return {
        "status": status,
        "before_count": before_count,
        "after_count": after_count,
        "divergent_count": divergent_count,
        "missing_count": missing_count,
    }


def read_zet_title_remap_write_lock(
    root: Path,
    path: Path,
) -> dict[str, Any]:
    if (
        path.is_symlink()
        or zet_revision_path_has_symlink_component(root, path)
        or not path.is_file()
        or not is_path_within_root(path, root)
    ):
        raise ArchiveServiceError("Title write lock path is unsafe.")
    try:
        if path.stat().st_size > 64 * 1024:
            raise ValueError("title_write_lock_too_large")

        def reject_duplicate_pairs(
            pairs: list[tuple[str, Any]],
        ) -> dict[str, Any]:
            parsed: dict[str, Any] = {}
            for key, value in pairs:
                if key in parsed:
                    raise ValueError("title_write_lock_duplicate_key")
                parsed[key] = value
            return parsed

        document = json.loads(
            path.read_text(encoding="utf-8"),
            object_pairs_hook=reject_duplicate_pairs,
        )
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        ValueError,
    ) as exc:
        raise ArchiveServiceError("Title write lock is unreadable.") from exc
    if not isinstance(document, dict):
        raise ArchiveServiceError("Title write lock shape is invalid.")
    if document.get("schema") == "wom-kit/zet-title-remap-write-lock/v0.1":
        if set(document) != {
            "schema",
            "proposal_sha256",
            "plan_digest",
            "write_plan_digest",
            "transaction_journal_name",
        }:
            raise ArchiveServiceError("Title write lock shape is invalid.")
        if (
            any(
                not isinstance(document.get(field), str)
                or not re.fullmatch(
                    r"sha256:[0-9a-f]{64}",
                    document[field],
                )
                for field in (
                    "proposal_sha256",
                    "plan_digest",
                    "write_plan_digest",
                )
            )
            or not isinstance(
                document.get("transaction_journal_name"),
                str,
            )
            or not re.fullmatch(
                r"\.[0-9a-f]{64}\.write\.transaction\.json",
                document["transaction_journal_name"],
            )
        ):
            raise ArchiveServiceError(
                "Title write lock binding is invalid."
            )
        expected_journal_name = (
            "."
            + document["proposal_sha256"].removeprefix("sha256:")
            + ".write.transaction.json"
        )
        if document["transaction_journal_name"] != expected_journal_name:
            raise ArchiveServiceError(
                "Title write lock journal is invalid."
            )
        return document
    if document.get("schema") == "wom-kit/zet-title-remap-write-lock/v0.2":
        if set(document) != {
            "schema",
            "operation",
            "source_receipt_sha256",
            "revert_plan_digest",
            "transaction_journal_name",
        }:
            raise ArchiveServiceError("Title write lock shape is invalid.")
        if (
            document.get("operation") != "revert"
            or any(
                not isinstance(document.get(field), str)
                or not re.fullmatch(
                    r"sha256:[0-9a-f]{64}",
                    document[field],
                )
                for field in (
                    "source_receipt_sha256",
                    "revert_plan_digest",
                )
            )
            or not isinstance(
                document.get("transaction_journal_name"),
                str,
            )
            or not re.fullmatch(
                r"\.[0-9a-f]{64}\.revert\.transaction\.json",
                document["transaction_journal_name"],
            )
        ):
            raise ArchiveServiceError(
                "Title revert write lock binding is invalid."
            )
        expected_journal_name = (
            "."
            + document["source_receipt_sha256"].removeprefix("sha256:")
            + ".revert.transaction.json"
        )
        if document["transaction_journal_name"] != expected_journal_name:
            raise ArchiveServiceError(
                "Title revert write lock journal is invalid."
            )
        return document
    raise ArchiveServiceError("Title write lock schema is unsupported.")


def zet_title_remap_receipt_audit(
    archive_root: Path | str,
    *,
    dry_run: bool = False,
    max_receipts: int = 5000,
    max_journals: int = 100,
    max_problems: int = 100,
    progress_callback: Callable[
        [str, str, int | None, int | None], None
    ]
    | None = None,
    _ignored_write_lock_document: dict[str, Any] | None = None,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    requested_max_receipts = int(max_receipts)
    requested_max_journals = int(max_journals)
    requested_max_problems = int(max_problems)
    effective_max_receipts = max(
        1,
        min(
            requested_max_receipts,
            ZET_TITLE_REMAP_AUDIT_MAX_RECEIPTS,
        ),
    )
    effective_max_journals = max(
        1,
        min(
            requested_max_journals,
            ZET_TITLE_REMAP_AUDIT_MAX_JOURNALS,
        ),
    )
    effective_max_problems = max(
        1,
        min(
            requested_max_problems,
            ZET_TITLE_REMAP_AUDIT_MAX_PROBLEMS,
        ),
    )
    blockers: list[str] = []
    warnings: list[str] = []
    problems: list[dict[str, Any]] = []
    journal_cases: list[dict[str, Any]] = []
    outcomes: list[dict[str, Any]] = []
    problem_total = 0
    counters = {
        "receipt_verified": 0,
        "revert_receipt_verified": 0,
        "receipt_invalid_or_divergent": 0,
        "revert_receipt_invalid_or_divergent": 0,
        "orphan_revert_receipt": 0,
        "receipt_participant_count": 0,
        "revert_receipt_participant_count": 0,
        "journal_prepared": 0,
        "journal_partially_applied": 0,
        "journal_fully_applied_receipt_missing": 0,
        "journal_divergent": 0,
        "journal_stale_completed": 0,
        "journal_invalid": 0,
        "revert_journal_prepared": 0,
        "revert_journal_partially_reverted": 0,
        "revert_journal_fully_reverted_receipt_missing": 0,
        "revert_journal_divergent": 0,
        "revert_journal_stale_completed": 0,
        "revert_journal_invalid": 0,
        "journal_snapshot_evidence_invalid": 0,
        "write_lock_matching": 0,
        "write_lock_missing_for_journal": 0,
        "write_lock_orphaned_or_invalid": 0,
    }

    if not dry_run:
        blockers.append("dry_run_required")
    if requested_max_receipts != effective_max_receipts:
        blockers.append("max_receipts_out_of_range")
    if requested_max_journals != effective_max_journals:
        blockers.append("max_journals_out_of_range")
    if requested_max_problems != effective_max_problems:
        blockers.append("max_problems_out_of_range")

    receipt_root = archive_internal_path(
        root,
        ZET_TITLE_REMAP_RECEIPTS_DIR,
    )
    revert_receipt_root = archive_internal_path(
        root,
        ZET_TITLE_REMAP_REVERT_RECEIPTS_DIR,
    )
    title_remap_root = archive_internal_path(
        root,
        ZET_TITLE_REMAP_PROPOSAL_PREFIX.rstrip("/"),
    )
    if (receipt_root.exists() or receipt_root.is_symlink()) and (
        receipt_root.is_symlink()
        or zet_revision_path_has_symlink_component(root, receipt_root)
        or not receipt_root.is_dir()
    ):
        blockers.append("title_receipt_root_unsafe")
    if (
        revert_receipt_root.exists()
        or revert_receipt_root.is_symlink()
    ) and (
        revert_receipt_root.is_symlink()
        or zet_revision_path_has_symlink_component(
            root,
            revert_receipt_root,
        )
        or not revert_receipt_root.is_dir()
    ):
        blockers.append("title_revert_receipt_root_unsafe")
    if (title_remap_root.exists() or title_remap_root.is_symlink()) and (
        title_remap_root.is_symlink()
        or zet_revision_path_has_symlink_component(root, title_remap_root)
        or not title_remap_root.is_dir()
    ):
        blockers.append("title_remap_private_root_unsafe")
    receipt_paths = (
        sorted(receipt_root.glob("*.zet-title-remap.json"))
        if receipt_root.is_dir()
        and not receipt_root.is_symlink()
        and not zet_revision_path_has_symlink_component(root, receipt_root)
        else []
    )
    revert_receipt_paths = (
        sorted(
            revert_receipt_root.glob(
                "*.zet-title-remap-revert.json"
            )
        )
        if revert_receipt_root.is_dir()
        and not revert_receipt_root.is_symlink()
        and not zet_revision_path_has_symlink_component(
            root,
            revert_receipt_root,
        )
        else []
    )
    apply_journal_paths = (
        sorted(title_remap_root.glob(".*.write.transaction.json"))
        if title_remap_root.is_dir()
        and not title_remap_root.is_symlink()
        and not zet_revision_path_has_symlink_component(
            root,
            title_remap_root,
        )
        else []
    )
    revert_journal_paths = (
        sorted(
            title_remap_root.glob(
                ".*.revert.transaction.json"
            )
        )
        if title_remap_root.is_dir()
        and not title_remap_root.is_symlink()
        and not zet_revision_path_has_symlink_component(
            root,
            title_remap_root,
        )
        else []
    )
    journal_paths = sorted(
        [*apply_journal_paths, *revert_journal_paths]
    )
    write_lock_path = title_remap_root / ".title-remap.write.lock"
    logical_write_lock_present = bool(
        write_lock_path.exists() or write_lock_path.is_symlink()
    )
    receipt_count = len(receipt_paths) + len(revert_receipt_paths)
    if receipt_count > effective_max_receipts:
        blockers.append("receipt_count_exceeds_max_receipts")
    if len(journal_paths) > effective_max_journals:
        blockers.append("journal_count_exceeds_max_journals")

    scan_allowed = not any(
        blocker
        in {
            "dry_run_required",
            "max_receipts_out_of_range",
            "max_journals_out_of_range",
            "max_problems_out_of_range",
            "receipt_count_exceeds_max_receipts",
            "journal_count_exceeds_max_journals",
            "title_receipt_root_unsafe",
            "title_revert_receipt_root_unsafe",
            "title_remap_private_root_unsafe",
        }
        for blocker in blockers
    )

    def add_problem(problem: dict[str, Any]) -> None:
        nonlocal problem_total
        problem_total += 1
        if len(problems) < effective_max_problems:
            problems.append(problem)

    verified_receipts: dict[str, dict[str, Any]] = {}
    structurally_valid_receipts: dict[str, dict[str, Any]] = {}
    verified_revert_receipts: dict[str, dict[str, Any]] = {}
    matched_revert_receipt_paths: set[Path] = set()
    journal_records: list[dict[str, Any]] = []
    manifest_index: dict[str, list[dict[str, Any]]] = {}
    manifest_blockers: list[str] = []
    if scan_allowed:
        if receipt_paths or revert_receipt_paths or journal_paths:
            manifest_index, manifest_blockers = (
                zet_revision_snapshot_manifest_index(root)
            )
        if manifest_blockers:
            blockers.append("title_snapshot_manifest_unreadable_or_invalid")
        if progress_callback is not None:
            progress_callback(
                "title-remap-receipt-audit",
                "start",
                0,
                len(receipt_paths),
            )
        for index, receipt_path in enumerate(receipt_paths):
            issue_codes: list[str] = []
            verification: dict[str, Any] = {}
            proposal_sha256: str | None = None
            receipt_evidence_sha256: str | None = None
            revert_evidence_sha256: str | None = None
            source_receipt_sha256: str | None = None
            receipt_document: dict[str, Any] = {}
            revert_receipt_document: dict[str, Any] = {}
            lifecycle_reverted = False
            try:
                receipt_raw, receipt_document, proposal_sha256 = (
                    read_zet_title_remap_receipt_for_audit(
                        root,
                        receipt_path,
                        archive_id=archive_id,
                    )
                )
                receipt_evidence_sha256 = (
                    "sha256:" + hashlib.sha256(receipt_raw).hexdigest()
                )
                source_receipt_sha256 = receipt_evidence_sha256
                source_relative = archive_relative_path(
                    receipt_path,
                    root,
                )
                structurally_valid_receipts[source_relative] = {
                    "document": receipt_document,
                    "sha256": source_receipt_sha256,
                }
                expected_revert_relative = (
                    zet_title_remap_revert_receipt_relative_path(
                        source_receipt_sha256
                    )
                )
                expected_revert_path = archive_internal_path(
                    root,
                    expected_revert_relative,
                )
                if (
                    expected_revert_path.exists()
                    or expected_revert_path.is_symlink()
                ):
                    matched_revert_receipt_paths.add(
                        expected_revert_path.resolve()
                    )
                    (
                        _revert_raw,
                        revert_receipt_document,
                        _revert_sha256,
                    ) = read_zet_title_remap_revert_receipt(
                        root,
                        expected_revert_path,
                        archive_id=archive_id,
                        source_receipt_sha256=source_receipt_sha256,
                    )
                    verification = (
                        verify_zet_title_remap_revert_receipt(
                            root,
                            expected_revert_path,
                            archive_id=archive_id,
                            source_receipt_path=source_relative,
                            source_receipt_sha256=source_receipt_sha256,
                            source_receipt=receipt_document,
                            manifest_index=manifest_index,
                        )
                    )
                    revert_evidence_sha256 = verification.get(
                        "receipt_sha256"
                    )
                    lifecycle_reverted = True
                else:
                    verification = verify_zet_title_remap_receipt(
                        root,
                        receipt_path,
                        archive_id=archive_id,
                        proposal_sha256=proposal_sha256,
                        snapshot_manifest_index=manifest_index,
                        snapshot_manifest_blockers=manifest_blockers,
                    )
                issue_codes.extend(
                    str(code)
                    for code in verification.get("blockers", [])
                )
            except (
                ArchiveServiceError,
                ArchivePathError,
                OSError,
                UnicodeError,
                ValueError,
            ):
                issue_codes.append(
                    "title_receipt_unreadable_or_invalid"
                )
            participant_count = len(
                verification.get("items")
                if isinstance(verification.get("items"), list)
                else []
            )
            counters["receipt_participant_count"] += participant_count
            if lifecycle_reverted:
                counters[
                    "revert_receipt_participant_count"
                ] += participant_count
            if (
                not issue_codes
                and verification.get("ok")
                and proposal_sha256
            ):
                counters["receipt_verified"] += 1
                if lifecycle_reverted:
                    counters["revert_receipt_verified"] += 1
                verified_receipts[
                    zet_title_remap_receipt_relative_path(
                        proposal_sha256
                    )
                ] = receipt_document
                if lifecycle_reverted:
                    assert source_receipt_sha256 is not None
                    verified_revert_receipts[
                        zet_title_remap_revert_receipt_relative_path(
                            source_receipt_sha256
                        )
                    ] = revert_receipt_document
                    status = "reverted_verified"
                else:
                    status = "verified"
            else:
                counters["receipt_invalid_or_divergent"] += 1
                if lifecycle_reverted:
                    counters[
                        "revert_receipt_invalid_or_divergent"
                    ] += 1
                status = "invalid_or_divergent"
                blockers.append(
                    "one_or_more_title_remap_receipts_invalid_or_divergent"
                )
                add_problem(
                    {
                        "kind": "receipt",
                        "index": index,
                        "status": status,
                        "participant_count": participant_count,
                        "issue_codes": unique_preserve_order(issue_codes),
                    }
                )
            outcomes.append(
                {
                    "kind": "receipt",
                    "index": index,
                    "status": status,
                    "participant_count": participant_count,
                    "issue_codes": unique_preserve_order(issue_codes),
                    "evidence_sha256": receipt_evidence_sha256,
                    "revert_evidence_sha256": revert_evidence_sha256,
                }
            )
            if progress_callback is not None and (
                index == 0
                or index + 1 == len(receipt_paths)
                or (index + 1) % 100 == 0
            ):
                progress_callback(
                    "title-remap-receipt-audit",
                    "scanned",
                    index + 1,
                    len(receipt_paths),
                )
        for revert_index, revert_path in enumerate(
            revert_receipt_paths
        ):
            if revert_path.resolve() in matched_revert_receipt_paths:
                continue
            counters["orphan_revert_receipt"] += 1
            counters[
                "revert_receipt_invalid_or_divergent"
            ] += 1
            blockers.append(
                "one_or_more_title_revert_receipts_orphaned_or_invalid"
            )
            orphan_problem = {
                "kind": "revert_receipt",
                "index": revert_index,
                "status": "orphaned_or_invalid",
                "participant_count": 0,
                "issue_codes": [
                    "title_revert_receipt_has_no_matching_source"
                ],
            }
            add_problem(orphan_problem)
            outcomes.append(
                {
                    **orphan_problem,
                    "evidence_sha256": (
                        "sha256:" + sha256_path(revert_path)
                        if revert_path.is_file()
                        and not revert_path.is_symlink()
                        else None
                    ),
                }
            )
        if progress_callback is not None:
            progress_callback(
                "title-remap-receipt-audit",
                "done",
                len(receipt_paths),
                len(receipt_paths),
            )
            progress_callback(
                "title-remap-journal-audit",
                "start",
                0,
                len(journal_paths),
            )

        for index, journal_path in enumerate(journal_paths):
            issue_codes: list[str] = []
            state_counts = {
                "before_count": 0,
                "after_count": 0,
                "divergent_count": 0,
                "missing_count": 0,
            }
            state = "invalid"
            final_receipt_state = "unknown"
            case_sha256: str | None = None
            journal: dict[str, Any] | None = None
            raw_journal: bytes | None = None
            operation = (
                "revert"
                if journal_path.name.endswith(
                    ".revert.transaction.json"
                )
                else "apply"
            )
            try:
                if operation == "revert":
                    raw_journal, journal = (
                        read_zet_title_remap_revert_transaction_journal(
                            root,
                            journal_path,
                            archive_id=archive_id,
                        )
                    )
                    classified = (
                        classify_zet_title_remap_revert_transaction_journal(
                            root,
                            journal,
                        )
                    )
                else:
                    raw_journal, journal = (
                        read_zet_title_remap_transaction_journal(
                            root,
                            journal_path,
                            archive_id=archive_id,
                        )
                    )
                    classified = (
                        classify_zet_title_remap_transaction_journal(
                            root,
                            journal,
                        )
                    )
                case_sha256 = (
                    "sha256:" + hashlib.sha256(raw_journal).hexdigest()
                )
                state = str(classified.pop("status"))
                state_counts = classified
                for item in journal["items"]:
                    snapshot_issues = verify_zet_revision_before_snapshot(
                        root,
                        item.get("before_snapshot"),
                        expected_before_sha256=item.get(
                            "before_file_sha256"
                        ),
                        manifest_index=manifest_index,
                    )
                    if snapshot_issues:
                        issue_codes.append(
                            "title_transaction_before_snapshot_invalid"
                        )
                final_receipt_relative = journal["final_receipt_path"]
                final_receipt = archive_internal_path(
                    root,
                    final_receipt_relative,
                )
                if operation == "revert":
                    source_receipt_relative = journal[
                        "source_receipt_path"
                    ]
                    source_receipt_record = (
                        structurally_valid_receipts.get(
                            source_receipt_relative
                        )
                    )
                    source_receipt = (
                        source_receipt_record.get("document")
                        if isinstance(source_receipt_record, dict)
                        else None
                    )
                    source_receipt_record_sha256 = (
                        source_receipt_record.get("sha256")
                        if isinstance(source_receipt_record, dict)
                        else None
                    )
                    verified_source_receipt = (
                        verified_receipts.get(
                            source_receipt_relative
                        )
                    )
                    if verified_source_receipt is not None:
                        source_receipt = verified_source_receipt
                    source_receipt_path = archive_internal_path(
                        root,
                        source_receipt_relative
                    )
                    source_receipt_digest_matches = bool(
                        source_receipt is not None
                        and source_receipt_path.is_file()
                        and not source_receipt_path.is_symlink()
                        and source_receipt_record_sha256
                        == journal["source_receipt_sha256"]
                        and "sha256:"
                        + sha256_path(source_receipt_path)
                        == journal["source_receipt_sha256"]
                    )
                    if not source_receipt_digest_matches:
                        state = "divergent"
                        issue_codes.append(
                            "title_revert_transaction_source_receipt_unverified"
                        )
                    verified_receipt = verified_revert_receipts.get(
                        final_receipt_relative
                    )
                else:
                    verified_receipt = verified_receipts.get(
                        final_receipt_relative
                    )
                if verified_receipt is not None:
                    if operation == "revert":
                        receipt_matches_journal = all(
                            verified_receipt.get(field)
                            == journal.get(field)
                            for field in (
                                "archive_id",
                                "source_receipt_path",
                                "source_receipt_sha256",
                                "planner_wom_kit_version",
                                "source_history_audit_digest",
                                "revert_plan_digest",
                                "reviewed_by",
                                "human_affirmations",
                                "item_count",
                                "items",
                            )
                        ) and (
                            verified_receipt.get("reverted_at")
                            == journal.get("prepared_at")
                        )
                    else:
                        receipt_matches_journal = all(
                            verified_receipt.get(field)
                            == journal.get(field)
                            for field in (
                                "archive_id",
                                "proposal_sha256",
                                "plan_digest",
                                "write_plan_digest",
                                "reviewed_by",
                                "human_affirmation",
                                "item_count",
                                "items",
                            )
                        ) and (
                            verified_receipt.get("applied_at")
                            == journal.get("prepared_at")
                        )
                    if receipt_matches_journal and not issue_codes:
                        final_receipt_state = "verified"
                        state = "stale_completed"
                    else:
                        final_receipt_state = "present_unverified"
                        state = "divergent"
                        issue_codes.append(
                            "title_transaction_final_receipt_binding_mismatch"
                        )
                elif final_receipt.exists() or final_receipt.is_symlink():
                    final_receipt_state = "present_unverified"
                    state = "divergent"
                    issue_codes.append(
                        "title_transaction_final_receipt_present_unverified"
                    )
                else:
                    final_receipt_state = "absent"
            except (
                ArchiveServiceError,
                ArchivePathError,
                OSError,
                ValueError,
            ):
                issue_codes.append(
                    "title_transaction_journal_unreadable_or_invalid"
                )

            if "title_transaction_before_snapshot_invalid" in issue_codes:
                counters["journal_snapshot_evidence_invalid"] += 1
                blockers.append(
                    "one_or_more_title_transaction_snapshots_invalid"
                )
            if operation == "revert" and state == "prepared":
                counters["revert_journal_prepared"] += 1
                issue_codes.append(
                    "title_revert_transaction_prepared"
                )
                blockers.append(
                    "one_or_more_interrupted_title_revert_transactions"
                )
            elif operation == "revert" and state == "partially_reverted":
                counters[
                    "revert_journal_partially_reverted"
                ] += 1
                issue_codes.append(
                    "title_revert_transaction_partially_reverted"
                )
                blockers.append(
                    "one_or_more_interrupted_title_revert_transactions"
                )
            elif (
                operation == "revert"
                and state == "fully_reverted_receipt_missing"
            ):
                counters[
                    "revert_journal_fully_reverted_receipt_missing"
                ] += 1
                issue_codes.append(
                    "title_revert_transaction_canonical_writes_complete_receipt_missing"
                )
                blockers.append(
                    "one_or_more_interrupted_title_revert_transactions"
                )
            elif operation == "revert" and state == "divergent":
                counters["revert_journal_divergent"] += 1
                issue_codes.append(
                    "title_revert_transaction_participant_missing_or_divergent"
                )
                blockers.append(
                    "one_or_more_title_revert_transaction_journals_invalid_or_divergent"
                )
            elif operation == "revert" and state == "stale_completed":
                counters["revert_journal_stale_completed"] += 1
                warnings.append(
                    "one_or_more_completed_title_revert_transaction_journals_remain"
                )
            elif operation == "revert":
                counters["revert_journal_invalid"] += 1
                blockers.append(
                    "one_or_more_title_revert_transaction_journals_invalid_or_divergent"
                )
            elif state == "prepared":
                counters["journal_prepared"] += 1
                issue_codes.append("title_transaction_prepared")
                blockers.append(
                    "one_or_more_interrupted_title_transactions"
                )
            elif state == "partially_applied":
                counters["journal_partially_applied"] += 1
                issue_codes.append("title_transaction_partially_applied")
                blockers.append(
                    "one_or_more_interrupted_title_transactions"
                )
            elif state == "fully_applied_receipt_missing":
                counters["journal_fully_applied_receipt_missing"] += 1
                issue_codes.append(
                    "title_transaction_canonical_writes_complete_receipt_missing"
                )
                blockers.append(
                    "one_or_more_interrupted_title_transactions"
                )
            elif state == "divergent":
                counters["journal_divergent"] += 1
                issue_codes.append(
                    "title_transaction_participant_missing_or_divergent"
                )
                blockers.append(
                    "one_or_more_title_transaction_journals_invalid_or_divergent"
                )
            elif state == "stale_completed":
                counters["journal_stale_completed"] += 1
                warnings.append(
                    "one_or_more_completed_title_transaction_journals_remain"
                )
            else:
                counters["journal_invalid"] += 1
                blockers.append(
                    "one_or_more_title_transaction_journals_invalid_or_divergent"
                )
            case = {
                "case_index": index,
                "case_sha256": case_sha256,
                "operation": operation,
                "observed_state": state,
                **state_counts,
                "participant_count": (
                    int(journal.get("item_count") or 0)
                    if isinstance(journal, dict)
                    else 0
                ),
                "final_receipt_state": final_receipt_state,
                "write_lock_state": "unchecked",
                "issue_codes": unique_preserve_order(issue_codes),
            }
            journal_cases.append(case)
            journal_records.append(
                {
                    "path": journal_path,
                    "document": journal,
                    "case": case,
                }
            )
            if progress_callback is not None and (
                index == 0
                or index + 1 == len(journal_paths)
                or (index + 1) % 100 == 0
            ):
                progress_callback(
                    "title-remap-journal-audit",
                    "scanned",
                    index + 1,
                    len(journal_paths),
                )
        if progress_callback is not None:
            progress_callback(
                "title-remap-journal-audit",
                "done",
                len(journal_paths),
                len(journal_paths),
            )

        physical_lock_exists = (
            write_lock_path.exists() or write_lock_path.is_symlink()
        )
        ignored_owned_lock = False
        if (
            physical_lock_exists
            and _ignored_write_lock_document is not None
        ):
            try:
                ignored_owned_lock = bool(
                    read_zet_title_remap_write_lock(
                        root,
                        write_lock_path,
                    )
                    == _ignored_write_lock_document
                )
            except ArchiveServiceError:
                ignored_owned_lock = False
        lock_exists = physical_lock_exists and not ignored_owned_lock
        logical_write_lock_present = lock_exists
        matching_record: dict[str, Any] | None = None
        lock_audit_state = "absent"
        lock_evidence_sha256: str | None = None
        if lock_exists:
            try:
                lock = read_zet_title_remap_write_lock(
                    root,
                    write_lock_path,
                )
                lock_evidence_sha256 = (
                    "sha256:" + sha256_path(write_lock_path)
                )
                if (
                    lock.get("schema")
                    == "wom-kit/zet-title-remap-write-lock/v0.2"
                ):
                    matches = [
                        record
                        for record in journal_records
                        if isinstance(
                            record.get("document"),
                            dict,
                        )
                        and record["path"].name
                        == lock["transaction_journal_name"]
                        and record["document"].get("operation")
                        == "revert"
                        and record["document"].get(
                            "source_receipt_sha256"
                        )
                        == lock["source_receipt_sha256"]
                        and record["document"].get(
                            "revert_plan_digest"
                        )
                        == lock["revert_plan_digest"]
                    ]
                else:
                    matches = [
                        record
                        for record in journal_records
                        if isinstance(
                            record.get("document"),
                            dict,
                        )
                        and record["path"].name
                        == lock["transaction_journal_name"]
                        and record["document"].get(
                            "proposal_sha256"
                        )
                        == lock["proposal_sha256"]
                        and record["document"].get("plan_digest")
                        == lock["plan_digest"]
                        and record["document"].get(
                            "write_plan_digest"
                        )
                        == lock["write_plan_digest"]
                    ]
                if len(matches) == 1:
                    matching_record = matches[0]
                    lock_audit_state = "present_matching"
                    counters["write_lock_matching"] += 1
                    matching_record["case"][
                        "write_lock_state"
                    ] = "present_matching"
                else:
                    raise ArchiveServiceError(
                        "Title write lock has no unique journal."
                    )
            except (
                ArchiveServiceError,
                ArchivePathError,
                OSError,
                ValueError,
            ):
                lock_audit_state = "orphaned_or_invalid"
                counters["write_lock_orphaned_or_invalid"] += 1
                blockers.append("title_remap_write_lock_orphaned_or_invalid")
                add_problem(
                    {
                        "kind": "write_lock",
                        "status": "orphaned_or_invalid",
                        "issue_codes": [
                            "title_remap_write_lock_orphaned_or_invalid"
                        ],
                    }
                )
        for record in journal_records:
            if record is matching_record:
                continue
            if not isinstance(record.get("document"), dict):
                record["case"]["write_lock_state"] = "not_verifiable"
                continue
            record["case"]["write_lock_state"] = "missing_or_mismatched"
            counters["write_lock_missing_for_journal"] += 1
            blockers.append(
                "one_or_more_title_transaction_journals_missing_matching_lock"
            )
            record["case"]["issue_codes"] = unique_preserve_order(
                [
                    *record["case"]["issue_codes"],
                    "title_transaction_matching_write_lock_missing",
                ]
            )
        if lock_exists and matching_record is not None:
            warnings.append("title_remap_write_lock_remains")
        outcomes.append(
            {
                "kind": "write_lock",
                "state": lock_audit_state,
                "matching_case_index": (
                    matching_record["case"]["case_index"]
                    if matching_record is not None
                    else None
                ),
                "evidence_sha256": lock_evidence_sha256,
            }
        )
        for record in journal_records:
            case = record["case"]
            if (
                case["observed_state"] != "stale_completed"
                or case["issue_codes"]
            ):
                add_problem(
                    {
                        "kind": "transaction_journal",
                        **case,
                    }
                )
            outcomes.append(
                {
                    "kind": "transaction_journal",
                    **case,
                }
            )

    blockers = unique_preserve_order(blockers)
    warnings = unique_preserve_order(warnings)
    complete = bool(
        scan_allowed
        and not manifest_blockers
        and "title_receipt_root_unsafe" not in blockers
        and "title_revert_receipt_root_unsafe" not in blockers
        and "title_remap_private_root_unsafe" not in blockers
    )
    return {
        "ok": not blockers,
        "dry_run": bool(dry_run),
        "schema": ZET_TITLE_REMAP_RECEIPT_AUDIT_SCHEMA,
        "lifecycle_action": "zet_title_remap_receipt_audit",
        "status": (
            "healthy" if not blockers and not warnings else "attention_required"
        ),
        "archive_id": archive_id,
        "audit_digest": sha256_json_value(outcomes),
        "summary": {
            "complete": complete,
            "receipt_count": receipt_count,
            "source_receipt_count": len(receipt_paths),
            "revert_receipt_count": len(revert_receipt_paths),
            "journal_count": len(journal_paths),
            "apply_journal_count": len(apply_journal_paths),
            "revert_journal_count": len(revert_journal_paths),
            "write_lock_present": logical_write_lock_present,
            **counters,
            "problem_count": problem_total,
            "problems_returned": len(problems),
            "problems_truncated": len(problems) < problem_total,
            "journal_cases_returned": len(journal_cases),
            "journal_cases_truncated": (
                len(journal_cases) < len(journal_paths)
            ),
            "max_receipts": effective_max_receipts,
            "max_journals": effective_max_journals,
            "max_problems": effective_max_problems,
        },
        "problems": problems,
        "transaction_journal_cases": journal_cases,
        "write_boundary": {
            "files_written": False,
            "files_deleted": False,
            "locks_deleted": False,
            "receipts_modified": False,
            "canonical_zets_modified": False,
        },
        "recovery_boundary": {
            "recovery_planned": False,
            "recovery_executed": False,
            "receipt_finalized": False,
            "automatic_cleanup_implemented": False,
            "completed_revert_plan_implemented": True,
            "approved_revert_implemented": True,
            "revert_hard_exit_recovery_plan_implemented": False,
            "revert_hard_exit_recovery_executor_implemented": False,
        },
        "privacy_guards": {
            "canonical_file_bytes_read_for_hash_validation": bool(
                receipt_paths
                or revert_receipt_paths
                or journal_paths
            ),
            "canonical_body_text_echoed": False,
            "old_or_new_title_text_echoed": False,
            "title_hashes_echoed": False,
            "title_lengths_echoed": False,
            "receipt_private_metadata_read": bool(
                receipt_paths or revert_receipt_paths
            ),
            "receipt_paths_echoed": False,
            "journal_private_metadata_read": bool(journal_paths),
            "journal_paths_echoed": False,
            "lock_file_content_read": bool(
                write_lock_path.is_file()
                and not write_lock_path.is_symlink()
            ),
            "lock_file_content_echoed": False,
            "zettel_ids_echoed": False,
            "zettel_paths_echoed": False,
            "reviewed_by_echoed": False,
            "proposal_sha256_echoed": False,
            "snapshot_paths_echoed": False,
            "absolute_local_paths_echoed": False,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        },
        "blockers": blockers,
        "warnings": warnings,
        "next_safe_actions": (
            ["No title-remap receipt or transaction evidence action is required."]
            if not blockers and not warnings
            else [
                "Retain every title-remap receipt, transaction journal, write lock, and prior-byte snapshot.",
                "Do not delete, rewrite, resume, roll back, or finalize title-remap evidence by hand.",
                "Automatic hard-exit recovery for a retained title revert transaction is not implemented in this release.",
            ]
        ),
    }


def zet_title_remap_revert_plan(
    archive_root: Path | str,
    *,
    receipt_path: str,
    expected_receipt_sha256: str,
    max_items: int = 500,
    dry_run: bool = False,
    progress_callback: Callable[
        [str, str, int | None, int | None], None
    ]
    | None = None,
    _held_write_lock_document: dict[str, Any] | None = None,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    requested_max_items = int(max_items)
    effective_max_items = max(
        1,
        min(requested_max_items, ZET_TITLE_REMAP_MAX_ITEMS),
    )
    expected_sha256 = str(expected_receipt_sha256 or "").strip()
    blockers: list[str] = []
    warnings: list[str] = []
    public_items: list[dict[str, Any]] = []
    private_bindings: list[dict[str, Any]] = []
    source_receipt_sha256: str | None = None
    source_receipt: dict[str, Any] = {}
    source_receipt_relative: str | None = None
    receipt_audit_digest: str | None = None
    revert_receipt_relative: str | None = None
    plan_digest: str | None = None

    if not dry_run:
        blockers.append("dry_run_required")
    if requested_max_items != effective_max_items:
        blockers.append("max_items_out_of_range")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_sha256):
        blockers.append("expected_receipt_sha256_invalid")

    source_path, source_receipt_relative = (
        resolve_zet_title_remap_revert_source_receipt_path(
            root,
            receipt_path,
        )
    )
    if progress_callback is not None:
        progress_callback("title-revert-receipt", "start", 0, None)
    receipt_raw, source_receipt, proposal_sha256 = (
        read_zet_title_remap_receipt_for_audit(
            root,
            source_path,
            archive_id=archive_id,
        )
    )
    source_receipt_sha256 = (
        "sha256:" + hashlib.sha256(receipt_raw).hexdigest()
    )
    if progress_callback is not None:
        progress_callback(
            "title-revert-receipt",
            "done",
            len(receipt_raw),
            len(receipt_raw),
        )
    if source_receipt_sha256 != expected_sha256:
        blockers.append("source_receipt_sha256_mismatch")
    if source_receipt.get("item_count") > effective_max_items:
        blockers.append("source_receipt_item_count_exceeds_max_items")

    revert_receipt_relative = (
        zet_title_remap_revert_receipt_relative_path(
            source_receipt_sha256
        )
    )
    revert_receipt_path = archive_internal_path(
        root,
        revert_receipt_relative,
    )
    if (
        revert_receipt_path.exists()
        or revert_receipt_path.is_symlink()
    ):
        blockers.append("title_revert_receipt_already_exists")
    if zet_revision_path_has_symlink_component(
        root,
        revert_receipt_path,
    ):
        blockers.append("title_revert_receipt_path_unsafe")

    if progress_callback is not None:
        progress_callback("title-revert-history-audit", "start", 0, None)
    history_audit = zet_title_remap_receipt_audit(
        root,
        dry_run=True,
        max_receipts=ZET_TITLE_REMAP_AUDIT_MAX_RECEIPTS,
        max_journals=ZET_TITLE_REMAP_AUDIT_MAX_JOURNALS,
        max_problems=ZET_TITLE_REMAP_AUDIT_MAX_PROBLEMS,
        progress_callback=progress_callback,
        _ignored_write_lock_document=_held_write_lock_document,
    )
    if progress_callback is not None:
        progress_callback("title-revert-history-audit", "done", None, None)
    receipt_audit_digest = history_audit.get("audit_digest")
    if not history_audit.get("ok"):
        blockers.append("title_receipt_audit_not_healthy")
    if history_audit.get("warnings"):
        blockers.append("title_receipt_audit_not_clean")
    audit_summary = (
        history_audit.get("summary")
        if isinstance(history_audit.get("summary"), dict)
        else {}
    )
    if not audit_summary.get("complete"):
        blockers.append("title_receipt_audit_incomplete")
    if audit_summary.get("journal_count") or audit_summary.get(
        "write_lock_present"
    ):
        blockers.append(
            "title_transaction_evidence_must_be_resolved_before_revert"
        )

    manifest_index, manifest_blockers = (
        zet_revision_snapshot_manifest_index(root)
    )
    if manifest_blockers:
        blockers.append("title_snapshot_manifest_unreadable_or_invalid")
    source_verification = verify_zet_title_remap_receipt(
        root,
        source_path,
        archive_id=archive_id,
        proposal_sha256=proposal_sha256,
        snapshot_manifest_index=manifest_index,
        snapshot_manifest_blockers=manifest_blockers,
    )
    if not source_verification.get("ok"):
        blockers.append("source_title_remap_receipt_not_current")
        blockers.extend(
            str(code)
            for code in source_verification.get("blockers", [])
        )
    if (
        source_verification.get("receipt_sha256")
        != source_receipt_sha256
    ):
        blockers.append("source_receipt_verification_digest_mismatch")
    if not source_verification.get("review_affirmation_verified"):
        blockers.append("source_receipt_human_review_invalid")

    (
        private_bindings,
        public_items,
        item_blockers,
    ) = materialize_zet_title_remap_revert_plan_items(
        root,
        source_receipt,
        max_items=effective_max_items,
        manifest_index=manifest_index,
        progress_callback=progress_callback,
    )
    blockers.extend(item_blockers)
    blockers = unique_preserve_order(blockers)
    warnings = unique_preserve_order(warnings)

    if not blockers:
        plan_digest = sha256_json_value(
            {
                "schema": ZET_TITLE_REMAP_REVERT_PLAN_SCHEMA,
                "wom_kit_version": WOM_KIT_VERSION,
                "archive_id": archive_id,
                "source_receipt_path": source_receipt_relative,
                "source_receipt_sha256": source_receipt_sha256,
                "source_proposal_sha256": source_receipt.get(
                    "proposal_sha256"
                ),
                "source_plan_digest": source_receipt.get("plan_digest"),
                "source_write_plan_digest": source_receipt.get(
                    "write_plan_digest"
                ),
                "source_applied_at": source_receipt.get("applied_at"),
                "history_audit_digest": receipt_audit_digest,
                "future_revert_receipt_path": revert_receipt_relative,
                "items": private_bindings,
            }
        )

    item_ready_count = sum(
        1 for item in public_items if item.get("status") == "ready_to_revert"
    )
    ready_for_review_count = item_ready_count if not blockers else 0
    return {
        "ok": not blockers,
        "dry_run": bool(dry_run),
        "schema": ZET_TITLE_REMAP_REVERT_PLAN_SCHEMA,
        "lifecycle_action": "zet_title_remap_revert_plan",
        "status": "ready_for_human_review" if not blockers else "blocked",
        "archive_id": archive_id,
        "plan_digest": plan_digest,
        "source_receipt": {
            "expected_sha256": (
                expected_sha256
                if re.fullmatch(
                    r"sha256:[0-9a-f]{64}",
                    expected_sha256,
                )
                else None
            ),
            "actual_sha256": source_receipt_sha256,
            "expected_sha256_matches": bool(
                source_receipt_sha256
                and source_receipt_sha256 == expected_sha256
            ),
            "path_echoed": False,
            "preserved": True,
            "human_review_verified": bool(
                source_verification.get(
                    "review_affirmation_verified"
                )
            ),
        },
        "history_audit": {
            "digest": receipt_audit_digest,
            "complete": bool(audit_summary.get("complete")),
            "healthy": bool(history_audit.get("ok")),
            "clean": bool(
                history_audit.get("ok")
                and not history_audit.get("warnings")
                and not audit_summary.get("journal_count")
                and not audit_summary.get("write_lock_present")
            ),
        },
        "summary": {
            "candidate_count": len(public_items),
            "ready_for_review_count": ready_for_review_count,
            "blocked_count": len(public_items) - ready_for_review_count,
            "max_items": effective_max_items,
            "current_files_verified_at_applied_hash": sum(
                1
                for item in public_items
                if item.get("current_matches_applied_receipt")
            ),
            "prior_byte_snapshots_verified": sum(
                1
                for item in public_items
                if item.get("prior_snapshot_verified")
            ),
            "deterministic_title_only_inverses_verified": sum(
                1
                for item in public_items
                if item.get(
                    "deterministic_title_only_inverse_verified"
                )
            ),
        },
        "items": public_items,
        "approval_contract": {
            "approved_revert_implemented": False,
            "future_approved_revert_command": "zet-title-remap-revert",
            "future_write_must_bind_source_receipt_sha256": True,
            "future_write_must_bind_plan_digest": True,
            "future_write_must_repeat_complete_history_audit": True,
            "future_write_must_revalidate_current_after_hashes": True,
            "future_write_must_restore_only_verified_prior_bytes": True,
            "future_write_must_preserve_source_receipt": True,
            "future_write_must_create_immutable_revert_receipt": True,
            "future_write_must_serialize_with_title_writer": True,
            "future_write_must_use_crash_recovery_journal": True,
            "human_review_required": True,
            "manual_canonical_edit_recommended": False,
        },
        "write_boundary": {
            "files_written": False,
            "files_deleted": False,
            "canonical_zets_modified": False,
            "receipts_written_or_modified": False,
            "locks_created_or_deleted": False,
            "snapshots_written_or_deleted": False,
            "provider_state_written": False,
        },
        "privacy_guards": {
            "canonical_file_bytes_read_for_validation": bool(public_items),
            "prior_snapshot_bytes_read_for_validation": bool(public_items),
            "title_text_echoed": False,
            "title_hashes_echoed": False,
            "title_lengths_echoed": False,
            "body_text_echoed": False,
            "zettel_ids_echoed": False,
            "zettel_paths_echoed": False,
            "source_receipt_path_echoed": False,
            "proposal_sha256_echoed": False,
            "reviewer_id_echoed": False,
            "snapshot_paths_echoed": False,
            "absolute_local_paths_echoed": False,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        },
        "blockers": blockers,
        "warnings": warnings,
        "next_safe_actions": (
            [
                "Privately review the completed title-remap receipt and this exact plan digest before any compensation.",
                "Keep the source receipt and every prior-byte snapshot immutable.",
                "A later approval-gated writer must rerun this plan and bind the unchanged source-receipt SHA-256 and plan digest.",
            ]
            if not blockers
            else [
                "Resolve every receipt-audit, current-state, snapshot, or retained-transaction blocker first.",
                "Do not edit the canonical zets, source receipt, or prior-byte snapshots to bypass this result.",
            ]
        ),
    }


def zet_title_remap_revert(
    archive_root: Path | str,
    *,
    receipt_path: str,
    expected_receipt_sha256: str,
    expected_plan_digest: str,
    max_items: int = 500,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    affirm_title_reversions_reviewed: bool = False,
    affirm_archive_quiescent: bool = False,
    progress_callback: Callable[
        [str, str, int | None, int | None], None
    ]
    | None = None,
) -> dict[str, Any]:
    if type(dry_run) is not bool or type(approve) is not bool or approve:
        return _compound_exact_human_approval_blocked(
            lifecycle_action="zet_title_remap_revert",
        )
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    requested_max_items = int(max_items)
    effective_max_items = max(
        1,
        min(requested_max_items, ZET_TITLE_REMAP_MAX_ITEMS),
    )
    expected_receipt = str(expected_receipt_sha256 or "").strip()
    expected_plan = str(expected_plan_digest or "").strip()
    reviewer = safe_foreign_quarantine_actor_id(reviewed_by)
    blockers: list[str] = []
    warnings: list[str] = []
    public_items: list[dict[str, Any]] = []
    actual_receipt_sha256: str | None = None
    actual_plan_digest: str | None = None
    source_history_audit_digest: str | None = None
    source_receipt_relative: str | None = None
    source_receipt: dict[str, Any] = {}
    revert_receipt_relative: str | None = None
    revert_receipt_sha256: str | None = None
    revert_receipt_exists = False
    revert_receipt_written_this_run = False
    transaction_journal_path: Path | None = None
    transaction_journal_written = False
    transaction_journal_removed: bool | None = None
    write_lock_path: Path | None = None
    write_lock_removed: bool | None = None
    canonical_files_written: int | None = 0
    canonical_write_attempt_count = 0
    rollback = {
        "attempted": False,
        "succeeded": None,
        "canonical_files_restored": 0,
        "revert_receipt_removed": None,
        "transaction_journal_removed": None,
        "transaction_journal_retained": None,
        "write_lock_removed": None,
    }

    def result_payload(status: str) -> dict[str, Any]:
        ok = (
            status
            in {"ready_to_revert", "reverted", "already_reverted"}
            and not blockers
        )
        valid_revert_receipt = bool(
            revert_receipt_exists
            and status in {"reverted", "already_reverted"}
        )
        return {
            "ok": ok,
            "schema": ZET_TITLE_REMAP_REVERT_SCHEMA,
            "lifecycle_action": "zet_title_remap_revert",
            "status": status,
            "dry_run": bool(dry_run),
            "approved": bool(approve and status == "reverted"),
            "archive_id": archive_id,
            "source_receipt": {
                "actual_sha256": actual_receipt_sha256,
                "expected_sha256_matches": bool(
                    actual_receipt_sha256
                    and actual_receipt_sha256 == expected_receipt
                ),
                "path_echoed": False,
                "preserved": True,
            },
            "plan_digest": actual_plan_digest,
            "expected_plan_digest_matches": bool(
                actual_plan_digest
                and actual_plan_digest == expected_plan
            ),
            "revert_receipt": {
                "exists": revert_receipt_exists,
                "written_this_run": revert_receipt_written_this_run,
                "sha256": revert_receipt_sha256,
                "path_echoed": False,
                "path_contains_only_source_receipt_digest": bool(
                    revert_receipt_relative
                ),
                "contains_private_zettel_ids_and_paths": (
                    True if valid_revert_receipt else None
                ),
                "contains_title_or_body_text": (
                    False if valid_revert_receipt else None
                ),
            },
            "transaction_journal": {
                "written_before_first_canonical_write": (
                    True if transaction_journal_written else None
                ),
                "exists": bool(
                    transaction_journal_path
                    and transaction_journal_path.exists()
                ),
                "removed_after_completion": transaction_journal_removed,
                "contains_title_or_body_text": False,
                "path_echoed": False,
                "automatic_resume_implemented": False,
                "hard_exit_recovery_plan_implemented": False,
                "hard_exit_recovery_executor_implemented": False,
            },
            "summary": {
                "candidate_count": len(public_items),
                "ready_count": sum(
                    1
                    for item in public_items
                    if item.get("status") == "ready_to_revert"
                ),
                "reverted_count": sum(
                    1
                    for item in public_items
                    if item.get("status") == "reverted"
                ),
                "already_reverted_count": sum(
                    1
                    for item in public_items
                    if item.get("status") == "already_reverted"
                ),
                "blocked_count": sum(
                    1
                    for item in public_items
                    if item.get("status") == "blocked"
                ),
                "canonical_files_written_this_run": (
                    canonical_files_written
                ),
                "canonical_write_attempt_count": (
                    canonical_write_attempt_count
                ),
                "max_items": effective_max_items,
                "max_canonical_file_bytes": (
                    ZET_TITLE_REMAP_MAX_CANONICAL_FILE_BYTES
                ),
                "max_total_canonical_bytes": (
                    ZET_TITLE_REMAP_MAX_TOTAL_CANONICAL_BYTES
                ),
            },
            "items": public_items,
            "human_review": {
                "required_for_new_revert": True,
                "reviewed_by_supplied": bool(reviewer),
                "reviewed_by_echoed": False,
                "all_title_reversions_reviewed_affirmed": bool(
                    affirm_title_reversions_reviewed
                ),
                "archive_quiescence_affirmed": bool(
                    affirm_archive_quiescent
                ),
                "source_approval_preserved": True,
            },
            "write_boundary": {
                "exact_prior_file_bytes_restored": (
                    True if status == "reverted" else None
                ),
                "canonical_body_bytes_changed": (
                    None
                    if status == "failed_rollback_incomplete"
                    else False
                ),
                "source_receipt_deleted_or_modified": False,
                "prior_snapshots_deleted_or_modified": False,
                "temporary_write_lock_removed": write_lock_removed,
                "provider_state_written": False,
                "database_rows_written": False,
            },
            "rollback": rollback,
            "privacy_guards": {
                "source_receipt_path_echoed": False,
                "zettel_ids_echoed": False,
                "zettel_paths_echoed": False,
                "old_or_new_title_values_echoed": False,
                "title_hashes_echoed": False,
                "title_lengths_echoed": False,
                "zettel_body_text_echoed": False,
                "snapshot_paths_echoed": False,
                "reviewed_by_echoed": False,
                "proposal_sha256_echoed": False,
                "absolute_local_paths_echoed": False,
                "provider_urls_echoed": False,
                "provider_api_called": False,
                "model_called": False,
                "secret_store_or_environment_read": False,
            },
            "blockers": unique_preserve_order(blockers),
            "warnings": unique_preserve_order(warnings),
            "next_safe_actions": (
                [
                    "Retain the immutable source and revert receipts plus every prior-byte snapshot."
                ]
                if status == "reverted"
                else [
                    "No write is needed; the completed revert receipt and current prior bytes agree."
                ]
                if status == "already_reverted"
                else [
                    "Approve the unchanged source-receipt and plan digests with a safe reviewer and both human affirmations."
                ]
                if status == "ready_to_revert"
                else [
                    "Do not force the title revert. Resolve every receipt, current-state, snapshot, journal, or lock blocker first."
                ]
            ),
        }

    if requested_max_items != effective_max_items:
        blockers.append("max_items_out_of_range")
    if bool(dry_run) == bool(approve):
        blockers.append("choose_exactly_one_of_dry_run_or_approve")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_receipt):
        blockers.append("expected_receipt_sha256_invalid")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_plan):
        blockers.append("expected_plan_digest_invalid")

    source_path, source_receipt_relative = (
        resolve_zet_title_remap_revert_source_receipt_path(
            root,
            receipt_path,
        )
    )
    source_raw, source_receipt, _proposal_sha256 = (
        read_zet_title_remap_receipt_for_audit(
            root,
            source_path,
            archive_id=archive_id,
        )
    )
    actual_receipt_sha256 = (
        "sha256:" + hashlib.sha256(source_raw).hexdigest()
    )
    if actual_receipt_sha256 != expected_receipt:
        blockers.append("source_receipt_sha256_mismatch")
    if source_receipt.get("item_count") > effective_max_items:
        blockers.append(
            "source_receipt_item_count_exceeds_max_items"
        )
    revert_receipt_relative = (
        zet_title_remap_revert_receipt_relative_path(
            actual_receipt_sha256
        )
    )
    revert_receipt_path = archive_internal_path(
        root,
        revert_receipt_relative,
    )
    title_remap_root = archive_internal_path(
        root,
        ZET_TITLE_REMAP_PROPOSAL_PREFIX.rstrip("/"),
    )
    write_lock_path = title_remap_root / ".title-remap.write.lock"
    transaction_journal_path = (
        zet_title_remap_revert_transaction_journal_path(
            title_remap_root,
            actual_receipt_sha256,
        )
    )
    if blockers:
        return result_payload("blocked")

    manifest_index, manifest_blockers = (
        zet_revision_snapshot_manifest_index(root)
    )
    if revert_receipt_path.exists() or revert_receipt_path.is_symlink():
        revert_receipt_exists = True
        verification = verify_zet_title_remap_revert_receipt(
            root,
            revert_receipt_path,
            archive_id=archive_id,
            source_receipt_path=source_receipt_relative,
            source_receipt_sha256=actual_receipt_sha256,
            source_receipt=source_receipt,
            manifest_index=manifest_index,
        )
        blockers.extend(
            str(code)
            for code in verification.get("blockers", [])
        )
        revert_receipt_sha256 = verification.get("receipt_sha256")
        actual_plan_digest = verification.get(
            "revert_plan_digest"
        )
        public_items = (
            verification.get("items")
            if isinstance(verification.get("items"), list)
            else []
        )
        for item in public_items:
            if item.get("status") == "reverted_verified":
                item["status"] = "already_reverted"
        if actual_plan_digest != expected_plan:
            blockers.append(
                "existing_revert_receipt_plan_digest_mismatch"
            )
        if write_lock_path.exists():
            warnings.append(
                "title_remap_write_lock_remains_inspect_before_cleanup"
            )
        if transaction_journal_path.exists():
            warnings.append(
                "completed_title_revert_journal_remains_inspect_before_cleanup"
            )
        return result_payload(
            "already_reverted"
            if verification.get("ok") and not blockers
            else "blocked"
        )
    if manifest_blockers:
        blockers.append(
            "title_snapshot_manifest_unreadable_or_invalid"
        )
    if approve:
        if reviewer is None:
            blockers.append("safe_reviewed_by_required")
        if not affirm_title_reversions_reviewed:
            blockers.append(
                "affirm_title_reversions_reviewed_required"
            )
        if not affirm_archive_quiescent:
            blockers.append("affirm_archive_quiescent_required")
    elif reviewed_by:
        blockers.append("reviewed_by_only_valid_with_approve")
    elif (
        affirm_title_reversions_reviewed
        or affirm_archive_quiescent
    ):
        blockers.append("affirmations_only_valid_with_approve")
    if blockers:
        return result_payload("blocked")

    plan = zet_title_remap_revert_plan(
        root,
        receipt_path=source_receipt_relative,
        expected_receipt_sha256=actual_receipt_sha256,
        max_items=effective_max_items,
        dry_run=True,
        progress_callback=progress_callback,
    )
    actual_plan_digest = (
        plan.get("plan_digest")
        if isinstance(plan.get("plan_digest"), str)
        else None
    )
    source_history_audit_digest = (
        plan.get("history_audit", {}).get("digest")
        if isinstance(plan.get("history_audit"), dict)
        else None
    )
    public_items = (
        plan.get("items")
        if isinstance(plan.get("items"), list)
        else []
    )
    if not plan.get("ok"):
        blockers.extend(
            f"plan:{code}" for code in plan.get("blockers", [])
        )
    if actual_plan_digest != expected_plan:
        blockers.append("revert_plan_digest_mismatch")
    if not isinstance(
        source_history_audit_digest,
        str,
    ) or not re.fullmatch(
        r"sha256:[0-9a-f]{64}",
        source_history_audit_digest,
    ):
        blockers.append("source_history_audit_digest_missing")
    if blockers:
        for item in public_items:
            item["status"] = "blocked"
        return result_payload("blocked")
    if dry_run:
        return result_payload("ready_to_revert")

    assert reviewer is not None
    assert actual_plan_digest is not None
    assert source_history_audit_digest is not None
    assert source_receipt_relative is not None
    reverted_at = (
        datetime.now(timezone.utc)
        .replace(microsecond=0)
        .isoformat()
        .replace("+00:00", "Z")
    )
    private_items = source_receipt["items"]
    lock_document = {
        "schema": "wom-kit/zet-title-remap-write-lock/v0.2",
        "operation": "revert",
        "source_receipt_sha256": actual_receipt_sha256,
        "revert_plan_digest": actual_plan_digest,
        "transaction_journal_name": transaction_journal_path.name,
    }
    lock_descriptor: int | None = None
    try:
        title_remap_root.mkdir(parents=True, exist_ok=True)
        lock_descriptor = os.open(
            write_lock_path,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL,
            0o600,
        )
        with os.fdopen(lock_descriptor, "wb") as lock_handle:
            lock_descriptor = None
            lock_handle.write(
                (
                    json.dumps(
                        lock_document,
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    + "\n"
                ).encode("utf-8")
            )
            lock_handle.flush()
            os.fsync(lock_handle.fileno())
        fsync_directory(write_lock_path.parent)
    except FileExistsError:
        blockers.append("title_remap_write_lock_exists")
        return result_payload("blocked")
    except OSError:
        try:
            if write_lock_path.exists():
                write_lock_path.unlink()
        except OSError:
            pass
        blockers.append("title_remap_write_lock_create_failed")
        return result_payload("blocked")
    finally:
        if lock_descriptor is not None:
            os.close(lock_descriptor)

    candidates: list[dict[str, Any]] = []
    try:
        if read_zet_title_remap_write_lock(
            root,
            write_lock_path,
        ) != lock_document:
            raise ArchiveServiceError(
                "title_revert_write_lock_verification_failed"
            )
        locked_plan = zet_title_remap_revert_plan(
            root,
            receipt_path=source_receipt_relative,
            expected_receipt_sha256=actual_receipt_sha256,
            max_items=effective_max_items,
            dry_run=True,
            progress_callback=None,
            _held_write_lock_document=lock_document,
        )
        if (
            not locked_plan.get("ok")
            or locked_plan.get("plan_digest")
            != actual_plan_digest
        ):
            raise ArchiveServiceError(
                "title_revert_plan_changed_under_lock"
            )
        locked_source_raw, locked_source_receipt, _locked_proposal = (
            read_zet_title_remap_receipt_for_audit(
                root,
                source_path,
                archive_id=archive_id,
            )
        )
        if (
            "sha256:"
            + hashlib.sha256(locked_source_raw).hexdigest()
            != actual_receipt_sha256
            or locked_source_receipt != source_receipt
        ):
            raise ArchiveServiceError(
                "title_revert_source_receipt_changed_under_lock"
            )
        total_bytes = 0
        for item in private_items:
            canonical_path = archive_internal_path(
                root,
                item["canonical_path"],
            )
            applied_bytes = read_zet_title_remap_canonical_bytes(
                canonical_path
            )
            if (
                "sha256:"
                + hashlib.sha256(applied_bytes).hexdigest()
                != item["after_file_sha256"]
            ):
                raise ArchiveServiceError(
                    "title_revert_current_bytes_changed_under_lock"
                )
            snapshot_path = archive_internal_path(
                root,
                item["before_snapshot"]["logical_key"],
            )
            reverted_bytes = snapshot_path.read_bytes()
            if (
                "sha256:"
                + hashlib.sha256(reverted_bytes).hexdigest()
                != item["before_file_sha256"]
                or len(reverted_bytes)
                != item["before_snapshot"]["size_bytes"]
            ):
                raise ArchiveServiceError(
                    "title_revert_snapshot_changed_under_lock"
                )
            total_bytes += len(applied_bytes) + len(reverted_bytes)
            if total_bytes > (
                2 * ZET_TITLE_REMAP_MAX_TOTAL_CANONICAL_BYTES
            ):
                raise ArchiveServiceError(
                    "title_revert_batch_exceeds_byte_limit"
                )
            candidates.append(
                {
                    "item": item,
                    "path": canonical_path,
                    "applied_bytes": applied_bytes,
                    "reverted_bytes": reverted_bytes,
                }
            )
    except Exception:
        try:
            if write_lock_path.exists():
                write_lock_path.unlink()
                fsync_directory(write_lock_path.parent)
            write_lock_removed = not write_lock_path.exists()
        except OSError:
            write_lock_removed = False
        blockers.append("title_revert_locked_preflight_failed")
        return result_payload("blocked")

    revert_receipt = {
        "schema": ZET_TITLE_REMAP_REVERT_RECEIPT_SCHEMA,
        "action": "zet_title_remap_revert",
        "status": "reverted",
        "reverted_at": reverted_at,
        "archive_id": archive_id,
        "source_receipt_path": source_receipt_relative,
        "source_receipt_sha256": actual_receipt_sha256,
        "source_proposal_sha256": source_receipt["proposal_sha256"],
        "source_plan_digest": source_receipt["plan_digest"],
        "source_write_plan_digest": source_receipt[
            "write_plan_digest"
        ],
        "planner_wom_kit_version": WOM_KIT_VERSION,
        "source_history_audit_digest": source_history_audit_digest,
        "revert_plan_digest": actual_plan_digest,
        "reviewed_by": reviewer,
        "human_affirmations": {
            "all_title_reversions_reviewed": True,
            "archive_quiescence_confirmed": True,
        },
        "item_count": len(private_items),
        "items": private_items,
        "mutation_contract": {
            "field_restored": "frontmatter.title",
            "exact_prior_file_bytes_restored": True,
            "body_bytes_preserved": True,
            "other_frontmatter_semantics_restored": True,
            "updated_at_changed": False,
            "source_receipt_preserved": True,
            "rollback_on_runtime_failure": True,
            "crash_recovery_journal_written": True,
        },
        "privacy_guards": {
            "old_title_text_stored_in_receipt": False,
            "new_title_text_stored_in_receipt": False,
            "body_text_stored_in_receipt": False,
            "contains_private_zettel_ids_and_paths": True,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        },
    }
    if (
        not zet_title_remap_revert_receipt_document_valid(
            revert_receipt
        )
        or validate_schema(
            revert_receipt,
            "zet-title-remap-revert-receipt.schema.json",
        )
    ):
        try:
            write_lock_path.unlink()
            fsync_directory(write_lock_path.parent)
            write_lock_removed = True
        except OSError:
            write_lock_removed = False
        blockers.append("title_revert_receipt_schema_validation_failed")
        return result_payload("blocked")

    transaction_journal = {
        "schema": ZET_TITLE_REMAP_REVERT_TRANSACTION_JOURNAL_SCHEMA,
        "action": "zet_title_remap_revert_transaction",
        "status": "prepared",
        "operation": "revert",
        "prepared_at": reverted_at,
        "archive_id": archive_id,
        "source_receipt_path": source_receipt_relative,
        "source_receipt_sha256": actual_receipt_sha256,
        "planner_wom_kit_version": WOM_KIT_VERSION,
        "source_history_audit_digest": source_history_audit_digest,
        "revert_plan_digest": actual_plan_digest,
        "reviewed_by": reviewer,
        "human_affirmations": {
            "all_title_reversions_reviewed": True,
            "archive_quiescence_confirmed": True,
        },
        "final_receipt_path": revert_receipt_relative,
        "item_count": len(private_items),
        "items": private_items,
        "recovery_contract": {
            "journal_published_before_first_canonical_write": True,
            "current_state_inferred_from_participant_hashes": True,
            "prior_byte_snapshots_verified_before_journal": True,
            "automatic_resume_implemented": False,
            "automatic_rollback_after_hard_exit_implemented": False,
        },
        "privacy_guards": {
            "old_title_text_stored": False,
            "new_title_text_stored": False,
            "body_text_stored": False,
            "contains_private_zettel_ids_and_paths": True,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        },
    }
    transaction_journal["journal_digest"] = sha256_json_value(
        transaction_journal
    )
    if (
        not zet_title_remap_revert_transaction_journal_document_valid(
            transaction_journal
        )
        or validate_schema(
            transaction_journal,
            "zet-title-remap-revert-transaction-journal.schema.json",
        )
    ):
        try:
            write_lock_path.unlink()
            fsync_directory(write_lock_path.parent)
            write_lock_removed = True
        except OSError:
            write_lock_removed = False
        blockers.append(
            "title_revert_transaction_journal_schema_validation_failed"
        )
        return result_payload("blocked")
    try:
        write_json_new_file(
            transaction_journal_path,
            transaction_journal,
        )
        transaction_journal_written = True
    except (FileExistsError, OSError):
        try:
            if write_lock_path.exists():
                write_lock_path.unlink()
                fsync_directory(write_lock_path.parent)
            write_lock_removed = not write_lock_path.exists()
        except OSError:
            write_lock_removed = False
        blockers.append("title_revert_transaction_journal_create_failed")
        return result_payload("blocked")

    attempted_candidates: list[dict[str, Any]] = []
    revert_receipt_parent_existed = revert_receipt_path.parent.exists()
    revert_receipt_write_attempted = False
    revert_receipt_owned_this_run = False
    try:
        if progress_callback is not None:
            progress_callback(
                "title-revert-write",
                "start",
                0,
                len(candidates),
            )
        for index, candidate in enumerate(candidates, start=1):
            if (
                read_zet_title_remap_canonical_bytes(
                    candidate["path"]
                )
                != candidate["applied_bytes"]
            ):
                raise RuntimeError(
                    "canonical_changed_immediately_before_title_revert"
                )
            attempted_candidates.append(candidate)
            canonical_write_attempt_count += 1
            write_bytes_atomic(
                candidate["path"],
                candidate["reverted_bytes"],
            )
            if (
                read_zet_title_remap_canonical_bytes(
                    candidate["path"]
                )
                != candidate["reverted_bytes"]
            ):
                raise RuntimeError(
                    "canonical_title_revert_verification_failed"
                )
            canonical_files_written = int(
                canonical_files_written or 0
            ) + 1
            public_items[index - 1]["status"] = "reverted"
            if progress_callback is not None:
                progress_callback(
                    "title-revert-write",
                    "written",
                    index,
                    len(candidates),
                )
        for candidate in candidates:
            if (
                read_zet_title_remap_canonical_bytes(
                    candidate["path"]
                )
                != candidate["reverted_bytes"]
            ):
                raise RuntimeError(
                    "canonical_title_revert_batch_revalidation_failed"
                )
        if progress_callback is not None:
            progress_callback(
                "title-revert-write",
                "done",
                len(candidates),
                len(candidates),
            )
            progress_callback(
                "title-revert-receipt",
                "start",
                None,
                None,
            )
        revert_receipt_path.parent.mkdir(
            parents=True,
            exist_ok=True,
        )
        revert_receipt_write_attempted = True
        try:
            write_json_new_file(
                revert_receipt_path,
                revert_receipt,
            )
            revert_receipt_owned_this_run = True
        except FileExistsError:
            revert_receipt_write_attempted = False
            raise RuntimeError(
                "title_revert_receipt_created_concurrently"
            )
        except Exception:
            revert_receipt_owned_this_run = (
                revert_receipt_path.exists()
            )
            raise
        verification = verify_zet_title_remap_revert_receipt(
            root,
            revert_receipt_path,
            archive_id=archive_id,
            source_receipt_path=source_receipt_relative,
            source_receipt_sha256=actual_receipt_sha256,
            source_receipt=source_receipt,
            manifest_index=manifest_index,
        )
        if not verification.get("ok"):
            raise RuntimeError(
                "written_title_revert_receipt_verification_failed"
            )
        revert_receipt_exists = True
        revert_receipt_written_this_run = True
        revert_receipt_sha256 = verification.get("receipt_sha256")
        try:
            transaction_journal_path.unlink()
            fsync_directory(transaction_journal_path.parent)
            transaction_journal_removed = True
        except OSError:
            transaction_journal_removed = False
            warnings.append(
                "completed_title_revert_journal_cleanup_failed"
            )
        if transaction_journal_removed:
            try:
                write_lock_path.unlink()
                fsync_directory(write_lock_path.parent)
                write_lock_removed = True
            except OSError:
                write_lock_removed = False
                warnings.append(
                    "temporary_title_revert_lock_cleanup_failed"
                )
        else:
            write_lock_removed = False
            warnings.append(
                "title_write_lock_retained_with_revert_journal"
            )
        if progress_callback is not None:
            progress_callback(
                "title-revert-receipt",
                "done",
                None,
                None,
            )
        return result_payload("reverted")
    except Exception:
        rollback["attempted"] = bool(
            attempted_candidates
            or revert_receipt_write_attempted
        )
        if (
            revert_receipt_owned_this_run
            and revert_receipt_path.exists()
        ):
            try:
                revert_receipt_path.unlink()
            except OSError:
                pass
        revert_receipt_removed = not revert_receipt_path.exists()
        restored = 0
        canonical_restore_ok = True
        for candidate in reversed(attempted_candidates):
            try:
                write_bytes_atomic(
                    candidate["path"],
                    candidate["applied_bytes"],
                )
                if (
                    read_zet_title_remap_canonical_bytes(
                        candidate["path"]
                    )
                    != candidate["applied_bytes"]
                ):
                    raise OSError(
                        "title_revert_rollback_verification_failed"
                    )
                restored += 1
            except Exception:
                canonical_restore_ok = False
        if canonical_restore_ok and revert_receipt_removed:
            try:
                if transaction_journal_path.exists():
                    transaction_journal_path.unlink()
                    fsync_directory(
                        transaction_journal_path.parent
                    )
                transaction_journal_removed = (
                    not transaction_journal_path.exists()
                )
            except OSError:
                transaction_journal_removed = False
        else:
            transaction_journal_removed = False
        if transaction_journal_removed:
            try:
                if write_lock_path.exists():
                    write_lock_path.unlink()
                    fsync_directory(write_lock_path.parent)
                write_lock_removed = not write_lock_path.exists()
            except OSError:
                write_lock_removed = False
        else:
            write_lock_removed = False
        if not revert_receipt_parent_existed:
            cleanup_empty_archive_dirs(
                root,
                [revert_receipt_path],
            )
        rollback["canonical_files_restored"] = restored
        rollback["revert_receipt_removed"] = (
            revert_receipt_removed
        )
        rollback["transaction_journal_removed"] = (
            transaction_journal_removed
        )
        rollback["transaction_journal_retained"] = bool(
            transaction_journal_path.exists()
        )
        rollback["write_lock_removed"] = write_lock_removed
        rollback["succeeded"] = bool(
            canonical_restore_ok
            and revert_receipt_removed
            and transaction_journal_removed
            and write_lock_removed
        )
        canonical_files_written = (
            0 if rollback["succeeded"] else None
        )
        revert_receipt_exists = revert_receipt_path.exists()
        revert_receipt_written_this_run = False
        attempted_indexes = {
            candidate["item"]["row_index"]
            for candidate in attempted_candidates
        }
        for item in public_items:
            item["status"] = (
                "rolled_back"
                if item.get("row_index") in attempted_indexes
                else "not_attempted"
            )
        blockers.append(
            "title_revert_transaction_failed_and_rolled_back"
            if rollback["succeeded"]
            else "title_revert_transaction_failed_rollback_incomplete"
        )
        return result_payload(
            "failed_rolled_back"
            if rollback["succeeded"]
            else "failed_rollback_incomplete"
        )


def zet_title_remap_recovery_decision(
    case: dict[str, Any],
    *,
    common_lock_invalid: bool = False,
) -> tuple[str, str]:
    operation = str(case.get("operation") or "apply")
    observed_state = str(case.get("observed_state") or "invalid")
    final_receipt_state = str(
        case.get("final_receipt_state") or "unknown"
    )
    write_lock_state = str(case.get("write_lock_state") or "unchecked")
    issue_codes = {
        str(code)
        for code in case.get("issue_codes", [])
        if isinstance(code, str)
    }
    if operation == "revert":
        return (
            "manual_forensic_hold",
            "title_revert_hard_exit_recovery_not_implemented",
        )
    if common_lock_invalid:
        return (
            "manual_forensic_hold",
            "common_title_write_lock_is_orphaned_or_invalid",
        )
    if final_receipt_state == "present_unverified":
        return (
            "manual_forensic_hold",
            "deterministic_final_receipt_exists_but_lifecycle_is_unverified",
        )
    if "title_transaction_before_snapshot_invalid" in issue_codes:
        return (
            "manual_forensic_hold",
            "one_or_more_prior_byte_snapshots_are_invalid",
        )
    if observed_state == "invalid":
        return "manual_forensic_hold", "journal_contract_is_invalid"
    if observed_state == "divergent":
        return (
            "manual_forensic_hold",
            "participant_state_is_missing_or_outside_recorded_hashes",
        )
    if write_lock_state == "not_verifiable":
        return (
            "manual_forensic_hold",
            "journal_lock_binding_cannot_be_verified",
        )
    if observed_state == "stale_completed":
        return (
            "cleanup_verified_completed_title_evidence",
            "verified_receipt_committed_transaction_cleanup_did_not_finish",
        )
    if observed_state == "prepared":
        return (
            "cleanup_unstarted_title_transaction_evidence",
            "all_participants_remain_at_before_hash",
        )
    if observed_state in {
        "partially_applied",
        "fully_applied_receipt_missing",
    }:
        return (
            "rollback_uncommitted_title_apply_to_before",
            "title_apply_has_no_verified_commit_receipt_and_prior_bytes_are_reconstructible",
        )
    return (
        "manual_forensic_hold",
        "transaction_state_has_no_approved_recovery_policy",
    )


def zet_title_remap_recovery_plan(
    archive_root: Path | str,
    *,
    dry_run: bool = False,
    max_receipts: int = ZET_TITLE_REMAP_AUDIT_MAX_RECEIPTS,
    max_journals: int = ZET_TITLE_REMAP_AUDIT_MAX_JOURNALS,
    max_cases: int = 100,
    progress_callback: Callable[
        [str, str, int | None, int | None], None
    ]
    | None = None,
) -> dict[str, Any]:
    """Plan, but never execute, recovery for retained title-remap journals."""

    requested_max_receipts = int(max_receipts)
    requested_max_journals = int(max_journals)
    requested_max_cases = int(max_cases)
    effective_max_receipts = max(
        1,
        min(
            requested_max_receipts,
            ZET_TITLE_REMAP_AUDIT_MAX_RECEIPTS,
        ),
    )
    effective_max_journals = max(
        1,
        min(
            requested_max_journals,
            ZET_TITLE_REMAP_AUDIT_MAX_JOURNALS,
        ),
    )
    effective_max_cases = max(
        1,
        min(
            requested_max_cases,
            ZET_TITLE_REMAP_AUDIT_MAX_PROBLEMS,
        ),
    )
    blockers: list[str] = []
    warnings: list[str] = []
    if not dry_run:
        blockers.append("dry_run_required")
    if requested_max_receipts != effective_max_receipts:
        blockers.append("max_receipts_out_of_range")
    if requested_max_journals != effective_max_journals:
        blockers.append("max_journals_out_of_range")
    if requested_max_cases != effective_max_cases:
        blockers.append("max_cases_out_of_range")

    audit = zet_title_remap_receipt_audit(
        archive_root,
        dry_run=bool(dry_run),
        max_receipts=effective_max_receipts,
        max_journals=effective_max_journals,
        max_problems=effective_max_cases,
        progress_callback=progress_callback,
    )
    audit_summary = (
        audit.get("summary")
        if isinstance(audit.get("summary"), dict)
        else {}
    )
    raw_cases = (
        audit.get("transaction_journal_cases")
        if isinstance(audit.get("transaction_journal_cases"), list)
        else []
    )
    if not audit_summary.get("complete"):
        blockers.append("recovery_source_audit_incomplete")
    if (
        audit_summary.get("journal_cases_truncated")
        or len(raw_cases) > effective_max_cases
    ):
        blockers.append("recovery_cases_truncated")

    common_lock_invalid = bool(
        int(audit_summary.get("write_lock_orphaned_or_invalid") or 0)
    )
    planned_cases: list[dict[str, Any]] = []
    action_counts = {
        "cleanup_unstarted_title_transaction_evidence": 0,
        "rollback_uncommitted_title_apply_to_before": 0,
        "cleanup_verified_completed_title_evidence": 0,
        "manual_forensic_hold": 0,
    }
    for case in raw_cases:
        if not isinstance(case, dict):
            continue
        observed_state = str(case.get("observed_state") or "invalid")
        final_receipt_state = str(
            case.get("final_receipt_state") or "unknown"
        )
        write_lock_state = str(
            case.get("write_lock_state") or "unchecked"
        )
        before_count = int(case.get("before_count") or 0)
        after_count = int(case.get("after_count") or 0)
        recommended_action, reason_code = (
            zet_title_remap_recovery_decision(
                case,
                common_lock_invalid=common_lock_invalid,
            )
        )
        participant_write_count = (
            after_count
            if recommended_action
            == "rollback_uncommitted_title_apply_to_before"
            else 0
        )
        evidence_cleanup_required = (
            recommended_action != "manual_forensic_hold"
        )
        action_counts[recommended_action] += 1
        planned_cases.append(
            {
                "case_index": int(case.get("case_index") or 0),
                "case_sha256": case.get("case_sha256"),
                "operation": str(case.get("operation") or "apply"),
                "observed_state": observed_state,
                "before_count": before_count,
                "after_count": after_count,
                "divergent_count": int(
                    case.get("divergent_count") or 0
                ),
                "missing_count": int(case.get("missing_count") or 0),
                "participant_count": int(
                    case.get("participant_count") or 0
                ),
                "final_receipt_state": final_receipt_state,
                "write_lock_state": write_lock_state,
                "recommended_action": recommended_action,
                "reason_code": reason_code,
                "participant_write_count": participant_write_count,
                "receipt_write_required": False,
                "evidence_cleanup_required": evidence_cleanup_required,
                "lock_reacquisition_required": bool(
                    write_lock_state != "present_matching"
                    and recommended_action != "manual_forensic_hold"
                ),
                "current_state_revalidation_required": True,
                "prior_byte_snapshot_revalidation_required": True,
                "fresh_recovery_approval_required": True,
                "archive_quiescence_affirmation_required": True,
                "execution_implemented": (
                    recommended_action
                    in ZET_TITLE_REMAP_EXECUTABLE_RECOVERY_ACTIONS
                ),
                "safe_to_execute_now": False,
                "issue_codes": [
                    str(code)
                    for code in case.get("issue_codes", [])
                    if isinstance(code, str)
                ],
            }
        )

    if action_counts["manual_forensic_hold"]:
        warnings.append(
            "one_or_more_title_recovery_cases_require_manual_forensic_hold"
        )
    if common_lock_invalid and not planned_cases:
        warnings.append(
            "title_recovery_common_lock_requires_manual_forensic_hold"
        )
    receipt_problem_count = int(
        audit_summary.get("receipt_invalid_or_divergent") or 0
    )
    if receipt_problem_count:
        warnings.append(
            "one_or_more_non_journal_title_receipt_problems_exist"
        )

    blockers = unique_preserve_order(blockers)
    warnings = unique_preserve_order(warnings)
    complete_cases = planned_cases[:effective_max_cases]
    ok = not blockers
    if not ok:
        status = "blocked"
    elif action_counts["manual_forensic_hold"] or common_lock_invalid:
        status = "manual_forensic_hold"
    elif not planned_cases:
        status = "no_recovery_needed"
    else:
        status = "ready_for_human_recovery_review"
    privacy = (
        audit.get("privacy_guards")
        if isinstance(audit.get("privacy_guards"), dict)
        else {}
    )
    return {
        "ok": ok,
        "dry_run": bool(dry_run),
        "schema": ZET_TITLE_REMAP_RECOVERY_PLAN_SCHEMA,
        "lifecycle_action": "zet_title_remap_recovery_plan",
        "status": status,
        "archive_id": audit.get("archive_id"),
        "source_audit_digest": audit.get("audit_digest"),
        "plan_digest": sha256_json_value(planned_cases),
        "summary": {
            "complete": ok,
            "receipt_count": int(audit_summary.get("receipt_count") or 0),
            "transaction_journal_count": int(
                audit_summary.get("journal_count") or 0
            ),
            "recovery_case_count": len(planned_cases),
            "cases_returned": len(complete_cases),
            "cases_truncated": len(complete_cases) < len(planned_cases),
            "manual_forensic_hold_count": action_counts[
                "manual_forensic_hold"
            ],
            "participant_write_count_if_approved": sum(
                int(case["participant_write_count"])
                for case in planned_cases
            ),
            "receipt_write_count_if_approved": 0,
            "evidence_cleanup_count_if_approved": sum(
                1
                for case in planned_cases
                if case["evidence_cleanup_required"]
            ),
            "source_audit_problem_count": int(
                audit_summary.get("problem_count") or 0
            ),
            "common_write_lock_present": bool(
                audit_summary.get("write_lock_present")
            ),
            "common_write_lock_orphaned_or_invalid": (
                common_lock_invalid
            ),
            "max_receipts": effective_max_receipts,
            "max_journals": effective_max_journals,
            "max_cases": effective_max_cases,
            "action_counts": action_counts,
        },
        "cases": complete_cases,
        "execution_boundary": {
            "execution_implemented": True,
            "automatic_recovery": False,
            "fresh_recovery_approval_required": True,
            "archive_quiescence_affirmation_required": True,
            "single_case_sha_and_plan_bound_execution_required": True,
            "common_write_lock_reacquisition_required_when_absent": True,
            "recovery_executor_serialization_implemented": True,
            "approved_title_revert_implemented": True,
            "revert_hard_exit_recovery_implemented": False,
        },
        "write_boundary": {
            "files_written": False,
            "files_deleted": False,
            "locks_created": False,
            "locks_deleted": False,
            "receipts_created": False,
            "receipts_modified": False,
            "canonical_zets_modified": False,
        },
        "privacy_guards": {
            "canonical_file_bytes_read_for_hash_validation": bool(
                privacy.get(
                    "canonical_file_bytes_read_for_hash_validation"
                )
            ),
            "receipt_private_metadata_read": bool(
                privacy.get("receipt_private_metadata_read")
            ),
            "journal_private_metadata_read": bool(
                privacy.get("journal_private_metadata_read")
            ),
            "case_sha256_echoed_as_handle": True,
            "canonical_body_text_echoed": False,
            "old_or_new_title_text_echoed": False,
            "title_hashes_echoed": False,
            "title_lengths_echoed": False,
            "receipt_paths_echoed": False,
            "journal_paths_echoed": False,
            "zettel_ids_echoed": False,
            "zettel_paths_echoed": False,
            "reviewed_by_echoed": False,
            "proposal_sha256_echoed": False,
            "snapshot_paths_echoed": False,
            "absolute_local_paths_echoed": False,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        },
        "blockers": blockers,
        "warnings": warnings,
        "next_safe_actions": (
            [
                "No retained title-remap transaction journal requires recovery planning."
            ]
            if not planned_cases and ok and not common_lock_invalid
            else [
                "Retain every title-remap receipt, transaction journal, common write lock, and prior-byte snapshot.",
                "Have a human review each fixed recovery decision; do not execute, delete, resume, roll back, finalize, or revert title evidence by hand.",
                "Use zet-title-remap-recover only for one reviewed executable action, bound to this complete plan digest and case SHA-256, after fresh state and snapshot revalidation.",
            ]
        ),
    }


def zet_title_remap_revert_recovery_decision(
    case: dict[str, Any],
    *,
    common_lock_invalid: bool = False,
) -> tuple[str, str]:
    operation = str(case.get("operation") or "unknown")
    observed_state = str(case.get("observed_state") or "invalid")
    final_receipt_state = str(
        case.get("final_receipt_state") or "unknown"
    )
    write_lock_state = str(
        case.get("write_lock_state") or "unchecked"
    )
    issue_codes = {
        str(code)
        for code in case.get("issue_codes", [])
        if isinstance(code, str)
    }
    if operation != "revert":
        return (
            "manual_forensic_hold",
            "case_is_not_a_title_revert_transaction",
        )
    if common_lock_invalid:
        return (
            "manual_forensic_hold",
            "common_title_write_lock_is_orphaned_or_invalid",
        )
    if final_receipt_state == "present_unverified":
        return (
            "manual_forensic_hold",
            "deterministic_revert_receipt_exists_but_lifecycle_is_unverified",
        )
    if "title_transaction_before_snapshot_invalid" in issue_codes:
        return (
            "manual_forensic_hold",
            "one_or_more_prior_byte_snapshots_are_invalid",
        )
    if observed_state == "invalid":
        return "manual_forensic_hold", "revert_journal_contract_is_invalid"
    if observed_state == "divergent":
        return (
            "manual_forensic_hold",
            "participant_or_source_receipt_state_is_missing_or_outside_recorded_hashes",
        )
    if write_lock_state == "not_verifiable":
        return (
            "manual_forensic_hold",
            "revert_journal_lock_binding_cannot_be_verified",
        )
    if observed_state == "stale_completed":
        return (
            "cleanup_verified_completed_title_revert_evidence",
            "verified_revert_receipt_committed_transaction_cleanup_did_not_finish",
        )
    if observed_state == "prepared":
        return (
            "cleanup_unstarted_title_revert_transaction_evidence",
            "all_participants_remain_at_applied_hash",
        )
    if observed_state == "partially_reverted":
        return (
            "resume_title_revert_forward_and_finalize_receipt",
            "reviewed_revert_is_partially_complete_and_remaining_prior_bytes_are_reconstructible",
        )
    if observed_state == "fully_reverted_receipt_missing":
        return (
            "finalize_title_revert_receipt",
            "all_participants_reached_prior_hash_but_compensation_receipt_is_missing",
        )
    return (
        "manual_forensic_hold",
        "revert_transaction_state_has_no_approved_recovery_policy",
    )


def zet_title_remap_revert_recovery_plan(
    archive_root: Path | str,
    *,
    dry_run: bool = False,
    max_receipts: int = ZET_TITLE_REMAP_AUDIT_MAX_RECEIPTS,
    max_journals: int = ZET_TITLE_REMAP_AUDIT_MAX_JOURNALS,
    max_cases: int = 100,
    progress_callback: Callable[
        [str, str, int | None, int | None], None
    ]
    | None = None,
) -> dict[str, Any]:
    """Plan, but never execute, recovery for retained title-revert journals."""

    requested_max_receipts = int(max_receipts)
    requested_max_journals = int(max_journals)
    requested_max_cases = int(max_cases)
    effective_max_receipts = max(
        1,
        min(
            requested_max_receipts,
            ZET_TITLE_REMAP_AUDIT_MAX_RECEIPTS,
        ),
    )
    effective_max_journals = max(
        1,
        min(
            requested_max_journals,
            ZET_TITLE_REMAP_AUDIT_MAX_JOURNALS,
        ),
    )
    effective_max_cases = max(
        1,
        min(
            requested_max_cases,
            ZET_TITLE_REMAP_AUDIT_MAX_PROBLEMS,
        ),
    )
    blockers: list[str] = []
    warnings: list[str] = []
    if not dry_run:
        blockers.append("dry_run_required")
    if requested_max_receipts != effective_max_receipts:
        blockers.append("max_receipts_out_of_range")
    if requested_max_journals != effective_max_journals:
        blockers.append("max_journals_out_of_range")
    if requested_max_cases != effective_max_cases:
        blockers.append("max_cases_out_of_range")

    audit = zet_title_remap_receipt_audit(
        archive_root,
        dry_run=bool(dry_run),
        max_receipts=effective_max_receipts,
        max_journals=effective_max_journals,
        max_problems=effective_max_cases,
        progress_callback=progress_callback,
    )
    audit_summary = (
        audit.get("summary")
        if isinstance(audit.get("summary"), dict)
        else {}
    )
    raw_cases = (
        audit.get("transaction_journal_cases")
        if isinstance(audit.get("transaction_journal_cases"), list)
        else []
    )
    if not audit_summary.get("complete"):
        blockers.append("revert_recovery_source_audit_incomplete")
    if (
        audit_summary.get("journal_cases_truncated")
        or len(raw_cases) > effective_max_cases
    ):
        blockers.append("revert_recovery_cases_truncated")

    common_lock_invalid = bool(
        int(audit_summary.get("write_lock_orphaned_or_invalid") or 0)
    )
    apply_case_count = sum(
        1
        for case in raw_cases
        if isinstance(case, dict)
        and str(case.get("operation") or "apply") != "revert"
    )
    revert_cases = [
        case
        for case in raw_cases
        if isinstance(case, dict)
        and str(case.get("operation") or "unknown") == "revert"
    ]
    action_counts = {
        "cleanup_unstarted_title_revert_transaction_evidence": 0,
        "resume_title_revert_forward_and_finalize_receipt": 0,
        "finalize_title_revert_receipt": 0,
        "cleanup_verified_completed_title_revert_evidence": 0,
        "manual_forensic_hold": 0,
    }
    planned_cases: list[dict[str, Any]] = []
    for case in revert_cases:
        observed_state = str(case.get("observed_state") or "invalid")
        final_receipt_state = str(
            case.get("final_receipt_state") or "unknown"
        )
        write_lock_state = str(
            case.get("write_lock_state") or "unchecked"
        )
        before_count = int(case.get("before_count") or 0)
        after_count = int(case.get("after_count") or 0)
        recommended_action, reason_code = (
            zet_title_remap_revert_recovery_decision(
                case,
                common_lock_invalid=common_lock_invalid,
            )
        )
        participant_write_count = (
            after_count
            if recommended_action
            == "resume_title_revert_forward_and_finalize_receipt"
            else 0
        )
        receipt_write_required = recommended_action in {
            "resume_title_revert_forward_and_finalize_receipt",
            "finalize_title_revert_receipt",
        }
        evidence_cleanup_required = (
            recommended_action != "manual_forensic_hold"
        )
        action_counts[recommended_action] += 1
        planned_cases.append(
            {
                "case_index": int(case.get("case_index") or 0),
                "case_sha256": case.get("case_sha256"),
                "operation": "revert",
                "observed_state": observed_state,
                "before_count": before_count,
                "after_count": after_count,
                "divergent_count": int(
                    case.get("divergent_count") or 0
                ),
                "missing_count": int(case.get("missing_count") or 0),
                "participant_count": int(
                    case.get("participant_count") or 0
                ),
                "final_receipt_state": final_receipt_state,
                "write_lock_state": write_lock_state,
                "recommended_action": recommended_action,
                "reason_code": reason_code,
                "participant_write_count": participant_write_count,
                "receipt_write_required": receipt_write_required,
                "evidence_cleanup_required": evidence_cleanup_required,
                "lock_reacquisition_required": bool(
                    write_lock_state != "present_matching"
                    and recommended_action != "manual_forensic_hold"
                ),
                "current_state_revalidation_required": True,
                "prior_byte_snapshot_revalidation_required": True,
                "source_receipt_revalidation_required": True,
                "fresh_recovery_approval_required": True,
                "archive_quiescence_affirmation_required": True,
                "execution_implemented": (
                    recommended_action
                    in ZET_TITLE_REMAP_EXECUTABLE_REVERT_RECOVERY_ACTIONS
                ),
                "safe_to_execute_now": False,
                "issue_codes": [
                    str(code)
                    for code in case.get("issue_codes", [])
                    if isinstance(code, str)
                ],
            }
        )

    if apply_case_count:
        warnings.append(
            "one_or_more_interrupted_title_apply_cases_require_the_apply_recovery_plan"
        )
    if action_counts["manual_forensic_hold"]:
        warnings.append(
            "one_or_more_title_revert_recovery_cases_require_manual_forensic_hold"
        )
    if common_lock_invalid and not planned_cases:
        warnings.append(
            "title_revert_recovery_common_lock_requires_manual_forensic_hold"
        )
    receipt_problem_count = int(
        audit_summary.get("receipt_invalid_or_divergent") or 0
    ) + int(
        audit_summary.get("revert_receipt_invalid_or_divergent") or 0
    )
    if receipt_problem_count:
        warnings.append(
            "one_or_more_non_journal_title_receipt_problems_exist"
        )

    blockers = unique_preserve_order(blockers)
    warnings = unique_preserve_order(warnings)
    complete_cases = planned_cases[:effective_max_cases]
    ok = not blockers
    if not ok:
        status = "blocked"
    elif action_counts["manual_forensic_hold"] or (
        common_lock_invalid and planned_cases
    ):
        status = "manual_forensic_hold"
    elif planned_cases:
        status = "ready_for_human_recovery_review"
    elif apply_case_count:
        status = "apply_recovery_required_elsewhere"
    else:
        status = "no_recovery_needed"
    privacy = (
        audit.get("privacy_guards")
        if isinstance(audit.get("privacy_guards"), dict)
        else {}
    )
    return {
        "ok": ok,
        "dry_run": bool(dry_run),
        "schema": ZET_TITLE_REMAP_REVERT_RECOVERY_PLAN_SCHEMA,
        "lifecycle_action": "zet_title_remap_revert_recovery_plan",
        "status": status,
        "archive_id": audit.get("archive_id"),
        "source_audit_digest": audit.get("audit_digest"),
        "plan_digest": sha256_json_value(planned_cases),
        "summary": {
            "complete": ok,
            "receipt_count": int(
                audit_summary.get("receipt_count") or 0
            ),
            "transaction_journal_count": int(
                audit_summary.get("journal_count") or 0
            ),
            "revert_recovery_case_count": len(planned_cases),
            "apply_recovery_case_count": apply_case_count,
            "cases_returned": len(complete_cases),
            "cases_truncated": len(complete_cases) < len(planned_cases),
            "manual_forensic_hold_count": action_counts[
                "manual_forensic_hold"
            ],
            "participant_write_count_if_later_approved": sum(
                int(case["participant_write_count"])
                for case in planned_cases
            ),
            "receipt_write_count_if_later_approved": sum(
                1
                for case in planned_cases
                if case["receipt_write_required"]
            ),
            "evidence_cleanup_count_if_later_approved": sum(
                1
                for case in planned_cases
                if case["evidence_cleanup_required"]
            ),
            "source_audit_problem_count": int(
                audit_summary.get("problem_count") or 0
            ),
            "common_write_lock_present": bool(
                audit_summary.get("write_lock_present")
            ),
            "common_write_lock_orphaned_or_invalid": (
                common_lock_invalid
            ),
            "max_receipts": effective_max_receipts,
            "max_journals": effective_max_journals,
            "max_cases": effective_max_cases,
            "action_counts": action_counts,
        },
        "cases": complete_cases,
        "execution_boundary": {
            "execution_implemented": True,
            "automatic_recovery": False,
            "approval_gated_single_case_executor_implemented": True,
            "fresh_recovery_approval_required": True,
            "archive_quiescence_affirmation_required": True,
            "single_case_sha_and_plan_bound_execution_required": True,
            "common_write_lock_reacquisition_required_when_absent": True,
            "apply_recovery_executor_must_not_execute_revert_cases": True,
        },
        "write_boundary": {
            "files_written": False,
            "files_deleted": False,
            "locks_created": False,
            "locks_deleted": False,
            "receipts_created": False,
            "receipts_modified": False,
            "canonical_zets_modified": False,
        },
        "privacy_guards": {
            "canonical_file_bytes_read_for_hash_validation": bool(
                privacy.get(
                    "canonical_file_bytes_read_for_hash_validation"
                )
            ),
            "receipt_private_metadata_read": bool(
                privacy.get("receipt_private_metadata_read")
            ),
            "journal_private_metadata_read": bool(
                privacy.get("journal_private_metadata_read")
            ),
            "case_sha256_echoed_as_handle": True,
            "canonical_body_text_echoed": False,
            "old_or_new_title_text_echoed": False,
            "title_hashes_echoed": False,
            "title_lengths_echoed": False,
            "receipt_paths_echoed": False,
            "journal_paths_echoed": False,
            "zettel_ids_echoed": False,
            "zettel_paths_echoed": False,
            "reviewed_by_echoed": False,
            "proposal_sha256_echoed": False,
            "snapshot_paths_echoed": False,
            "absolute_local_paths_echoed": False,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        },
        "blockers": blockers,
        "warnings": warnings,
        "next_safe_actions": (
            [
                "No retained title-revert transaction journal requires recovery planning."
            ]
            if not planned_cases and not apply_case_count and ok
            else [
                "Retain every title-remap apply/revert receipt, transaction journal, common write lock, and prior-byte snapshot.",
                "Have a human review each fixed title-revert recovery decision; this plan command itself grants no write or cleanup authority.",
                "Use zet-title-remap-revert-recover only for one reviewed executable action bound to this complete plan digest and case SHA-256 after fresh state and snapshot revalidation.",
            ]
        ),
    }


@contextmanager
def _zet_title_remap_recovery_guard(
    root: Path,
) -> Iterable[dict[str, bool]]:
    guard_root = archive_internal_path(
        root,
        ZET_TITLE_REMAP_PROPOSAL_PREFIX.rstrip("/"),
    )
    if (guard_root.exists() or guard_root.is_symlink()) and (
        guard_root.is_symlink()
        or zet_revision_path_has_symlink_component(root, guard_root)
        or not guard_root.is_dir()
    ):
        raise ArchiveServiceError("Title recovery guard root is unsafe.")
    guard_root.mkdir(parents=True, exist_ok=True)
    guard_path = guard_root / ".recovery-executor.guard"
    if guard_path.is_symlink() or (
        guard_path.exists() and not guard_path.is_file()
    ):
        raise ArchiveServiceError("Title recovery guard path is unsafe.")
    created_this_run = not guard_path.exists()
    handle = guard_path.open("a+b")
    locked = False
    try:
        handle.seek(0, os.SEEK_END)
        if handle.tell() == 0:
            handle.write(b"\0")
            handle.flush()
            os.fsync(handle.fileno())
        handle.seek(0)
        try:
            if os.name == "nt":
                import msvcrt

                msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl

                fcntl.flock(
                    handle.fileno(),
                    fcntl.LOCK_EX | fcntl.LOCK_NB,
                )
            locked = True
        except (BlockingIOError, OSError) as exc:
            raise ArchiveServiceError(
                "Another title recovery executor is active."
            ) from exc
        yield {
            "acquired": True,
            "guard_file_created_this_run": created_this_run,
        }
    finally:
        if locked:
            try:
                handle.seek(0)
                if os.name == "nt":
                    import msvcrt

                    msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
                else:
                    import fcntl

                    fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
            except OSError:
                pass
        handle.close()


def find_zet_title_remap_recovery_journal(
    root: Path,
    *,
    archive_id: str,
    case_sha256: str,
    max_journals: int,
) -> tuple[Path, bytes, dict[str, Any]]:
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", case_sha256):
        raise ArchiveServiceError("Title recovery case SHA-256 is invalid.")
    title_remap_root = archive_internal_path(
        root,
        ZET_TITLE_REMAP_PROPOSAL_PREFIX.rstrip("/"),
    )
    if (
        title_remap_root.is_symlink()
        or zet_revision_path_has_symlink_component(root, title_remap_root)
        or not title_remap_root.is_dir()
    ):
        raise ArchiveServiceError("Title recovery journal root is unsafe.")
    journal_paths = sorted(
        title_remap_root.glob(".*.write.transaction.json")
    )
    if len(journal_paths) > int(max_journals):
        raise ArchiveServiceError(
            "Title recovery journal scan is incomplete."
        )
    matches: list[tuple[Path, bytes, dict[str, Any]]] = []
    for journal_path in journal_paths:
        try:
            raw, journal = read_zet_title_remap_transaction_journal(
                root,
                journal_path,
                archive_id=archive_id,
            )
        except ArchiveServiceError:
            continue
        actual_case_sha256 = (
            "sha256:" + hashlib.sha256(raw).hexdigest()
        )
        if actual_case_sha256 == case_sha256:
            matches.append((journal_path, raw, journal))
    if len(matches) != 1:
        raise ArchiveServiceError(
            "Title recovery journal is missing or ambiguous."
        )
    return matches[0]


def zet_title_remap_write_lock_document(
    journal_path: Path,
    journal: dict[str, Any],
) -> dict[str, Any]:
    return {
        "schema": "wom-kit/zet-title-remap-write-lock/v0.1",
        "proposal_sha256": journal["proposal_sha256"],
        "plan_digest": journal["plan_digest"],
        "write_plan_digest": journal["write_plan_digest"],
        "transaction_journal_name": journal_path.name,
    }


def _ensure_zet_title_remap_recovery_write_lock(
    root: Path,
    *,
    lock_path: Path,
    journal_path: Path,
    journal: dict[str, Any],
) -> bool:
    expected = zet_title_remap_write_lock_document(
        journal_path,
        journal,
    )
    if lock_path.is_symlink() or (
        lock_path.exists() and not lock_path.is_file()
    ):
        raise ArchiveServiceError(
            "Title recovery common write lock path is unsafe."
        )
    if lock_path.is_file():
        existing = read_zet_title_remap_write_lock(root, lock_path)
        if existing != expected:
            raise ArchiveServiceError(
                "Title recovery common write lock belongs to another case."
            )
        return False

    descriptor: int | None = None
    created = False
    try:
        descriptor = os.open(
            lock_path,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL,
            0o600,
        )
        created = True
        with os.fdopen(descriptor, "wb") as handle:
            descriptor = None
            handle.write(
                (
                    json.dumps(
                        expected,
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    + "\n"
                ).encode("utf-8")
            )
            handle.flush()
            os.fsync(handle.fileno())
        fsync_directory(lock_path.parent)
        if read_zet_title_remap_write_lock(root, lock_path) != expected:
            raise ArchiveServiceError(
                "Title recovery common write lock verification failed."
            )
        return True
    except FileExistsError as exc:
        raise ArchiveServiceError(
            "Title recovery common write lock was created concurrently."
        ) from exc
    except (ArchiveServiceError, OSError) as exc:
        if descriptor is not None:
            os.close(descriptor)
        if created:
            try:
                lock_path.unlink()
                fsync_directory(lock_path.parent)
            except OSError:
                pass
        if isinstance(exc, ArchiveServiceError):
            raise
        raise ArchiveServiceError(
            "Title recovery common write lock could not be acquired."
        ) from exc


def read_zet_title_remap_recovery_snapshot_bytes(
    root: Path,
    item: dict[str, Any],
) -> bytes:
    snapshot = item["before_snapshot"]
    snapshot_path = archive_internal_path(
        root,
        snapshot["logical_key"],
    )
    if (
        snapshot_path.is_symlink()
        or zet_revision_path_has_symlink_component(root, snapshot_path)
        or not snapshot_path.is_file()
        or not is_path_within_root(snapshot_path, root)
    ):
        raise ArchiveServiceError(
            "Title recovery prior-byte snapshot is unsafe."
        )
    try:
        if snapshot_path.stat().st_size != snapshot["size_bytes"]:
            raise ArchiveServiceError(
                "Title recovery prior-byte snapshot size changed."
            )
        snapshot_bytes = snapshot_path.read_bytes()
    except OSError as exc:
        raise ArchiveServiceError(
            "Title recovery prior-byte snapshot is unreadable."
        ) from exc
    actual_sha256 = (
        "sha256:" + hashlib.sha256(snapshot_bytes).hexdigest()
    )
    if (
        actual_sha256 != item["before_file_sha256"]
        or actual_sha256 != snapshot["object_id"]
        or len(snapshot_bytes) != snapshot["size_bytes"]
    ):
        raise ArchiveServiceError(
            "Title recovery prior-byte snapshot binding changed."
        )
    return snapshot_bytes


def _materialize_zet_title_remap_recovery_writes(
    root: Path,
    journal: dict[str, Any],
    *,
    rollback_to_before: bool,
) -> list[dict[str, Any]]:
    writes: list[dict[str, Any]] = []
    total_bytes = 0
    for item in journal["items"]:
        canonical_path = archive_internal_path(
            root,
            item["canonical_path"],
        )
        if (
            canonical_path.is_symlink()
            or zet_revision_path_has_symlink_component(
                root,
                canonical_path,
            )
            or not canonical_path.is_file()
            or archive_relative_path(canonical_path, root)
            != item["canonical_path"]
        ):
            raise ArchiveServiceError(
                "Title recovery participant is unavailable."
            )
        current_bytes = read_zet_title_remap_canonical_bytes(
            canonical_path
        )
        snapshot_bytes = read_zet_title_remap_recovery_snapshot_bytes(
            root,
            item,
        )
        total_bytes += len(snapshot_bytes)
        if total_bytes > ZET_TITLE_REMAP_MAX_TOTAL_CANONICAL_BYTES:
            raise ArchiveServiceError(
                "Title recovery participants exceed the total byte limit."
            )
        current_sha256 = (
            "sha256:" + hashlib.sha256(current_bytes).hexdigest()
        )
        if current_sha256 not in {
            item["before_file_sha256"],
            item["after_file_sha256"],
        }:
            raise ArchiveServiceError(
                "Title recovery participant hash changed."
            )
        if (
            rollback_to_before
            and current_sha256 == item["after_file_sha256"]
        ):
            writes.append(
                {
                    "row_index": item["row_index"],
                    "path": canonical_path,
                    "source_bytes": current_bytes,
                    "target_bytes": snapshot_bytes,
                    "target_sha256": item["before_file_sha256"],
                }
            )
    return writes


def _remove_zet_title_remap_recovery_evidence(path: Path) -> bool:
    path.unlink()
    fsync_directory(path.parent)
    return not path.exists()


def zet_title_remap_recover(
    archive_root: Path | str,
    *,
    case_sha256: str,
    expected_plan_digest: str,
    expected_action: str,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    affirm_recovery_reviewed: bool = False,
    affirm_archive_quiescent: bool = False,
    max_receipts: int = ZET_TITLE_REMAP_AUDIT_MAX_RECEIPTS,
    max_journals: int = ZET_TITLE_REMAP_AUDIT_MAX_JOURNALS,
    max_cases: int = 100,
    progress_callback: Callable[
        [str, str, int | None, int | None],
        None,
    ]
    | None = None,
) -> dict[str, Any]:
    if type(dry_run) is not bool or type(approve) is not bool or approve:
        return _compound_exact_human_approval_blocked(
            lifecycle_action="zet_title_remap_recover",
        )
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    case_sha256 = str(case_sha256 or "").strip()
    expected_plan_digest = str(expected_plan_digest or "").strip()
    expected_action = str(expected_action or "").strip()
    reviewer = safe_foreign_quarantine_actor_id(reviewed_by)
    blockers: list[str] = []
    warnings: list[str] = []
    selected_case: dict[str, Any] | None = None
    actual_plan_digest: str | None = None
    canonical_files_written = 0
    canonical_write_attempt_count = 0
    write_lock_reacquired = False
    write_lock_removed: bool | None = None
    transaction_journal_removed: bool | None = None
    verified_receipt_preserved: bool | None = None
    recovery_guard_acquired = False
    recovery_guard_file_created = False
    cleanup_attempted = False
    private_journal_read = False
    prior_snapshot_bytes_read = False
    lock_path: Path | None = None
    journal_path: Path | None = None

    def result_payload(status: str) -> dict[str, Any]:
        ok = status in {"ready_to_recover", "recovered"} and not blockers
        case_payload = (
            {
                "case_sha256": selected_case.get("case_sha256"),
                "observed_state": selected_case.get("observed_state"),
                "final_receipt_state": selected_case.get(
                    "final_receipt_state"
                ),
                "write_lock_state": selected_case.get(
                    "write_lock_state"
                ),
                "recommended_action": selected_case.get(
                    "recommended_action"
                ),
                "participant_write_count": selected_case.get(
                    "participant_write_count"
                ),
                "receipt_write_required": selected_case.get(
                    "receipt_write_required"
                ),
            }
            if selected_case is not None
            else None
        )
        evidence_retained = bool(
            journal_path is not None and journal_path.exists()
        )
        return {
            "ok": ok,
            "schema": ZET_TITLE_REMAP_RECOVER_SCHEMA,
            "lifecycle_action": "zet_title_remap_recover",
            "status": status,
            "dry_run": bool(dry_run),
            "approved": bool(approve and status == "recovered"),
            "archive_id": archive_id,
            "case_sha256": (
                case_sha256
                if re.fullmatch(r"sha256:[0-9a-f]{64}", case_sha256)
                else None
            ),
            "expected_plan_digest": (
                expected_plan_digest
                if re.fullmatch(
                    r"sha256:[0-9a-f]{64}",
                    expected_plan_digest,
                )
                else None
            ),
            "actual_plan_digest": actual_plan_digest,
            "expected_plan_digest_matches": bool(
                actual_plan_digest
                and actual_plan_digest == expected_plan_digest
            ),
            "expected_action": (
                expected_action
                if expected_action in ZET_TITLE_REMAP_RECOVERY_ACTIONS
                else None
            ),
            "case": case_payload,
            "summary": {
                "canonical_files_written_this_run": (
                    canonical_files_written
                ),
                "canonical_write_attempt_count": (
                    canonical_write_attempt_count
                ),
                "receipt_written_this_run": False,
                "verified_completed_receipt_preserved": (
                    verified_receipt_preserved
                ),
                "write_lock_reacquired": write_lock_reacquired,
                "write_lock_removed": write_lock_removed,
                "transaction_journal_removed": (
                    transaction_journal_removed
                ),
            },
            "approval_contract": {
                "fresh_recovery_approval_required": True,
                "reviewed_by_supplied": bool(reviewer),
                "reviewed_by_echoed": False,
                "recovery_reviewed_affirmed": bool(
                    affirm_recovery_reviewed
                ),
                "archive_quiescent_affirmed": bool(
                    affirm_archive_quiescent
                ),
                "plan_digest_case_and_action_bound": bool(
                    selected_case is not None
                    and actual_plan_digest == expected_plan_digest
                    and selected_case.get("case_sha256")
                    == case_sha256
                    and selected_case.get("recommended_action")
                    == expected_action
                ),
            },
            "recovery_guard": {
                "acquired": recovery_guard_acquired,
                "guard_file_created_this_run": (
                    recovery_guard_file_created
                ),
                "automatically_released": (
                    True if recovery_guard_acquired else None
                ),
                "path_echoed": False,
                "serializes_recovery_executors_only": True,
            },
            "write_boundary": {
                "canonical_zets_modified": (
                    canonical_files_written > 0
                ),
                "canonical_files_restored_to_prior_bytes": (
                    canonical_files_written
                ),
                "canonical_body_bytes_restored_from_snapshot": bool(
                    canonical_files_written
                ),
                "other_frontmatter_fields_restored_from_snapshot": bool(
                    canonical_files_written
                ),
                "updated_at_changed": False,
                "receipts_created_modified_or_deleted": False,
                "common_write_lock_created": write_lock_reacquired,
                "common_write_lock_deleted": bool(write_lock_removed),
                "transaction_journal_deleted": bool(
                    transaction_journal_removed
                ),
                "prior_byte_snapshots_modified_or_deleted": False,
                "recovery_guard_file_created": (
                    recovery_guard_file_created
                ),
                "provider_state_written": False,
                "objet_bytes_written": False,
                "database_rows_written": False,
            },
            "retry_contract": {
                "safe_direction_only": True,
                "successful_restores_rolled_back_on_later_failure": False,
                "journal_retained_on_incomplete_recovery": (
                    evidence_retained
                ),
                "fresh_plan_and_approval_required_after_incomplete_recovery": (
                    True
                ),
            },
            "privacy_guards": {
                "journal_private_metadata_read": private_journal_read,
                "prior_snapshot_bytes_read": prior_snapshot_bytes_read,
                "journal_receipt_or_snapshot_paths_echoed": False,
                "zettel_ids_echoed": False,
                "zettel_paths_echoed": False,
                "old_or_new_title_values_echoed": False,
                "title_hashes_echoed": False,
                "title_lengths_echoed": False,
                "zettel_body_text_echoed": False,
                "reviewed_by_echoed": False,
                "proposal_sha256_echoed": False,
                "lock_content_echoed": False,
                "absolute_local_paths_echoed": False,
                "provider_api_called": False,
                "model_called": False,
                "secret_store_or_environment_read": False,
            },
            "blockers": unique_preserve_order(blockers),
            "warnings": unique_preserve_order(warnings),
            "next_safe_actions": (
                [
                    "Run this exact case SHA, plan digest, and action with --approve only after recovery review and archive-quiescence confirmation."
                ]
                if status == "ready_to_recover"
                else [
                    "Recovery completed; matching transaction residue was removed and retained snapshots were preserved."
                ]
                if status == "recovered"
                else [
                    "Retain every journal, lock, receipt, and prior-byte snapshot; generate a fresh plan before another approved attempt."
                ]
            ),
        }

    if bool(dry_run) == bool(approve):
        blockers.append("choose_exactly_one_of_dry_run_or_approve")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", case_sha256):
        blockers.append("recovery_case_sha256_invalid")
    if not re.fullmatch(
        r"sha256:[0-9a-f]{64}",
        expected_plan_digest,
    ):
        blockers.append("expected_recovery_plan_digest_invalid")
    if expected_action not in ZET_TITLE_REMAP_RECOVERY_ACTIONS:
        blockers.append("expected_recovery_action_invalid")
    if approve:
        if reviewer is None:
            blockers.append("safe_reviewed_by_required")
        if not affirm_recovery_reviewed:
            blockers.append("affirm_recovery_reviewed_required")
        if not affirm_archive_quiescent:
            blockers.append("affirm_archive_quiescent_required")
    elif (
        reviewed_by
        or affirm_recovery_reviewed
        or affirm_archive_quiescent
    ):
        blockers.append("approval_fields_only_valid_with_approve")
    if blockers:
        return result_payload("blocked")

    def fresh_plan() -> dict[str, Any]:
        return zet_title_remap_recovery_plan(
            root,
            dry_run=True,
            max_receipts=max_receipts,
            max_journals=max_journals,
            max_cases=max_cases,
            progress_callback=progress_callback,
        )

    def select_case(plan: dict[str, Any]) -> dict[str, Any] | None:
        matches = [
            case
            for case in plan.get("cases", [])
            if isinstance(case, dict)
            and case.get("case_sha256") == case_sha256
        ]
        return matches[0] if len(matches) == 1 else None

    plan = fresh_plan()
    actual_plan_digest = (
        plan.get("plan_digest")
        if isinstance(plan.get("plan_digest"), str)
        else None
    )
    if not plan.get("ok"):
        blockers.extend(
            f"plan:{code}" for code in plan.get("blockers", [])
        )
    if actual_plan_digest != expected_plan_digest:
        blockers.append("recovery_plan_digest_mismatch")
    selected_case = select_case(plan)
    if selected_case is None:
        blockers.append("recovery_case_not_found_or_ambiguous")
    elif selected_case.get("recommended_action") != expected_action:
        blockers.append("recovery_expected_action_mismatch")
    elif expected_action == "manual_forensic_hold":
        blockers.append("manual_forensic_hold_not_executable")
    elif not selected_case.get("execution_implemented"):
        blockers.append("recovery_action_not_implemented")
    if blockers:
        return result_payload("blocked")
    if dry_run:
        return result_payload("ready_to_recover")

    assert reviewer is not None
    try:
        with _zet_title_remap_recovery_guard(root) as guard:
            recovery_guard_acquired = bool(guard.get("acquired"))
            recovery_guard_file_created = bool(
                guard.get("guard_file_created_this_run")
            )
            plan = fresh_plan()
            actual_plan_digest = (
                plan.get("plan_digest")
                if isinstance(plan.get("plan_digest"), str)
                else None
            )
            fresh_case = select_case(plan)
            if (
                not plan.get("ok")
                or actual_plan_digest != expected_plan_digest
                or fresh_case is None
                or fresh_case.get("recommended_action")
                != expected_action
            ):
                blockers.append(
                    "recovery_case_changed_before_execution"
                )
                return result_payload("blocked")
            selected_case = fresh_case

            journal_path, journal_raw, journal = (
                find_zet_title_remap_recovery_journal(
                    root,
                    archive_id=archive_id,
                    case_sha256=case_sha256,
                    max_journals=int(max_journals),
                )
            )
            private_journal_read = True
            title_remap_root = archive_internal_path(
                root,
                ZET_TITLE_REMAP_PROPOSAL_PREFIX.rstrip("/"),
            )
            lock_path = title_remap_root / ".title-remap.write.lock"
            receipt_path = archive_internal_path(
                root,
                journal["final_receipt_path"],
            )

            state = classify_zet_title_remap_transaction_journal(
                root,
                journal,
            )
            observed_state = str(state.get("status") or "invalid")
            planned_state = str(
                fresh_case.get("observed_state") or "invalid"
            )
            state_matches_case = (
                observed_state == planned_state
                or (
                    planned_state == "stale_completed"
                    and observed_state
                    == "fully_applied_receipt_missing"
                )
            )
            if (
                not state_matches_case
                or any(
                    int(state.get(key) or 0)
                    != int(fresh_case.get(key) or 0)
                    for key in (
                        "before_count",
                        "after_count",
                        "divergent_count",
                        "missing_count",
                    )
                )
            ):
                blockers.append(
                    "recovery_participant_state_changed_after_plan"
                )
                return result_payload("blocked")

            verified_receipt_bytes: bytes | None = None
            if (
                expected_action
                == "cleanup_verified_completed_title_evidence"
            ):
                (
                    verified_receipt_bytes,
                    verified_receipt,
                    receipt_proposal_sha256,
                ) = read_zet_title_remap_receipt_for_audit(
                    root,
                    receipt_path,
                    archive_id=archive_id,
                )
                if (
                    receipt_proposal_sha256
                    != journal["proposal_sha256"]
                    or any(
                        verified_receipt.get(field)
                        != journal.get(field)
                        for field in (
                            "archive_id",
                            "proposal_sha256",
                            "plan_digest",
                            "write_plan_digest",
                            "reviewed_by",
                            "human_affirmation",
                            "item_count",
                            "items",
                        )
                    )
                    or verified_receipt.get("applied_at")
                    != journal.get("prepared_at")
                ):
                    blockers.append(
                        "recovery_verified_receipt_binding_changed"
                    )
                    return result_payload("blocked")
                verified_receipt_preserved = True
            elif receipt_path.exists() or receipt_path.is_symlink():
                blockers.append(
                    "recovery_final_receipt_became_occupied"
                )
                return result_payload("blocked")

            write_lock_reacquired = (
                _ensure_zet_title_remap_recovery_write_lock(
                    root,
                    lock_path=lock_path,
                    journal_path=journal_path,
                    journal=journal,
                )
            )
            locked_raw, locked_journal = (
                read_zet_title_remap_transaction_journal(
                    root,
                    journal_path,
                    archive_id=archive_id,
                )
            )
            if (
                locked_raw != journal_raw
                or "sha256:" + hashlib.sha256(locked_raw).hexdigest()
                != case_sha256
                or locked_journal != journal
            ):
                blockers.append("recovery_journal_binding_changed")
                return result_payload("blocked")

            participant_writes = (
                _materialize_zet_title_remap_recovery_writes(
                    root,
                    journal,
                    rollback_to_before=(
                        expected_action
                        == "rollback_uncommitted_title_apply_to_before"
                    ),
                )
            )
            prior_snapshot_bytes_read = True
            if len(participant_writes) != int(
                fresh_case.get("participant_write_count") or 0
            ):
                blockers.append(
                    "recovery_participant_write_set_changed"
                )
                return result_payload("blocked")
            if participant_writes and progress_callback is not None:
                progress_callback(
                    "title-remap-recovery-write",
                    "start",
                    0,
                    len(participant_writes),
                )
            for index, item in enumerate(participant_writes, start=1):
                if (
                    read_zet_title_remap_canonical_bytes(item["path"])
                    != item["source_bytes"]
                ):
                    raise ArchiveServiceError(
                        "Title recovery participant changed immediately before write."
                    )
                canonical_write_attempt_count += 1
                write_bytes_atomic(
                    item["path"],
                    item["target_bytes"],
                )
                written_bytes = read_zet_title_remap_canonical_bytes(
                    item["path"]
                )
                if (
                    written_bytes != item["target_bytes"]
                    or "sha256:"
                    + hashlib.sha256(written_bytes).hexdigest()
                    != item["target_sha256"]
                ):
                    raise ArchiveServiceError(
                        "Title recovery canonical write verification failed."
                    )
                canonical_files_written += 1
                if progress_callback is not None:
                    progress_callback(
                        "title-remap-recovery-write",
                        "written",
                        index,
                        len(participant_writes),
                    )
            if participant_writes and progress_callback is not None:
                progress_callback(
                    "title-remap-recovery-write",
                    "done",
                    len(participant_writes),
                    len(participant_writes),
                )

            final_state = classify_zet_title_remap_transaction_journal(
                root,
                journal,
            )
            expected_final_state = (
                "fully_applied_receipt_missing"
                if expected_action
                == "cleanup_verified_completed_title_evidence"
                else "prepared"
            )
            if (
                final_state.get("status") != expected_final_state
                or (
                    expected_final_state == "prepared"
                    and int(final_state.get("before_count") or 0)
                    != int(journal["item_count"])
                )
                or (
                    expected_final_state
                    == "fully_applied_receipt_missing"
                    and int(final_state.get("after_count") or 0)
                    != int(journal["item_count"])
                )
            ):
                raise ArchiveServiceError(
                    "Title recovery final participant state did not verify."
                )
            if verified_receipt_bytes is not None:
                if (
                    not receipt_path.is_file()
                    or receipt_path.is_symlink()
                    or receipt_path.read_bytes()
                    != verified_receipt_bytes
                ):
                    raise ArchiveServiceError(
                        "Title recovery verified receipt changed."
                    )
                verified_receipt_preserved = True
            elif receipt_path.exists() or receipt_path.is_symlink():
                raise ArchiveServiceError(
                    "Title recovery final receipt became occupied."
                )

            expected_lock = zet_title_remap_write_lock_document(
                journal_path,
                journal,
            )
            if (
                read_zet_title_remap_write_lock(root, lock_path)
                != expected_lock
            ):
                raise ArchiveServiceError(
                    "Title recovery common write lock changed."
                )
            cleanup_attempted = True
            try:
                write_lock_removed = (
                    _remove_zet_title_remap_recovery_evidence(
                        lock_path
                    )
                )
            except OSError:
                write_lock_removed = False
            if not write_lock_removed:
                blockers.append(
                    "recovery_completed_but_write_lock_cleanup_failed"
                )
                return result_payload(
                    "recovery_incomplete_evidence_retained"
                )

            current_journal_raw, _current_journal = (
                read_zet_title_remap_transaction_journal(
                    root,
                    journal_path,
                    archive_id=archive_id,
                )
            )
            if current_journal_raw != journal_raw:
                blockers.append(
                    "recovery_journal_changed_before_cleanup"
                )
                return result_payload(
                    "recovery_incomplete_evidence_retained"
                )
            try:
                transaction_journal_removed = (
                    _remove_zet_title_remap_recovery_evidence(
                        journal_path
                    )
                )
            except OSError:
                transaction_journal_removed = False
            if not transaction_journal_removed:
                blockers.append(
                    "recovery_completed_but_journal_cleanup_failed"
                )
                return result_payload(
                    "recovery_incomplete_evidence_retained"
                )
            if verified_receipt_bytes is not None:
                verified_receipt_preserved = bool(
                    receipt_path.is_file()
                    and not receipt_path.is_symlink()
                    and receipt_path.read_bytes()
                    == verified_receipt_bytes
                )
                if not verified_receipt_preserved:
                    blockers.append(
                        "recovery_completed_but_verified_receipt_changed"
                    )
                    return result_payload(
                        "recovery_incomplete_evidence_retained"
                    )
            return result_payload("recovered")
    except (
        ArchiveServiceError,
        ArchivePathError,
        OSError,
        UnicodeDecodeError,
        ValueError,
    ):
        blockers.append("recovery_execution_failed_evidence_retained")
        if lock_path is not None:
            write_lock_removed = not lock_path.exists()
        if journal_path is not None:
            transaction_journal_removed = not journal_path.exists()
        return result_payload(
            "recovery_incomplete_evidence_retained"
            if (
                canonical_files_written
                or write_lock_reacquired
                or cleanup_attempted
            )
            else "blocked"
        )


def find_zet_title_remap_revert_recovery_journal(
    root: Path,
    *,
    archive_id: str,
    case_sha256: str,
    max_journals: int,
) -> tuple[Path, bytes, dict[str, Any]]:
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", case_sha256):
        raise ArchiveServiceError(
            "Title revert recovery case SHA-256 is invalid."
        )
    title_remap_root = archive_internal_path(
        root,
        ZET_TITLE_REMAP_PROPOSAL_PREFIX.rstrip("/"),
    )
    if (
        title_remap_root.is_symlink()
        or zet_revision_path_has_symlink_component(
            root,
            title_remap_root,
        )
        or not title_remap_root.is_dir()
    ):
        raise ArchiveServiceError(
            "Title revert recovery journal root is unsafe."
        )
    journal_paths = sorted(
        title_remap_root.glob(".*.revert.transaction.json")
    )
    if len(journal_paths) > int(max_journals):
        raise ArchiveServiceError(
            "Title revert recovery journal scan is incomplete."
        )
    matches: list[tuple[Path, bytes, dict[str, Any]]] = []
    for journal_path in journal_paths:
        try:
            raw, journal = (
                read_zet_title_remap_revert_transaction_journal(
                    root,
                    journal_path,
                    archive_id=archive_id,
                )
            )
        except ArchiveServiceError:
            continue
        actual_case_sha256 = (
            "sha256:" + hashlib.sha256(raw).hexdigest()
        )
        if actual_case_sha256 == case_sha256:
            matches.append((journal_path, raw, journal))
    if len(matches) != 1:
        raise ArchiveServiceError(
            "Title revert recovery journal is missing or ambiguous."
        )
    return matches[0]


def zet_title_remap_revert_write_lock_document(
    journal_path: Path,
    journal: dict[str, Any],
) -> dict[str, Any]:
    return {
        "schema": "wom-kit/zet-title-remap-write-lock/v0.2",
        "operation": "revert",
        "source_receipt_sha256": journal[
            "source_receipt_sha256"
        ],
        "revert_plan_digest": journal["revert_plan_digest"],
        "transaction_journal_name": journal_path.name,
    }


def _ensure_zet_title_remap_revert_recovery_write_lock(
    root: Path,
    *,
    lock_path: Path,
    journal_path: Path,
    journal: dict[str, Any],
) -> bool:
    expected = zet_title_remap_revert_write_lock_document(
        journal_path,
        journal,
    )
    if lock_path.is_symlink() or (
        lock_path.exists() and not lock_path.is_file()
    ):
        raise ArchiveServiceError(
            "Title revert recovery common write lock path is unsafe."
        )
    if lock_path.is_file():
        existing = read_zet_title_remap_write_lock(root, lock_path)
        if existing != expected:
            raise ArchiveServiceError(
                "Title revert recovery common write lock belongs to another case."
            )
        return False

    descriptor: int | None = None
    created = False
    try:
        descriptor = os.open(
            lock_path,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL,
            0o600,
        )
        created = True
        with os.fdopen(descriptor, "wb") as handle:
            descriptor = None
            handle.write(
                (
                    json.dumps(
                        expected,
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    + "\n"
                ).encode("utf-8")
            )
            handle.flush()
            os.fsync(handle.fileno())
        fsync_directory(lock_path.parent)
        if read_zet_title_remap_write_lock(
            root,
            lock_path,
        ) != expected:
            raise ArchiveServiceError(
                "Title revert recovery common write lock verification failed."
            )
        return True
    except FileExistsError as exc:
        raise ArchiveServiceError(
            "Title revert recovery common write lock was created concurrently."
        ) from exc
    except (ArchiveServiceError, OSError) as exc:
        if descriptor is not None:
            os.close(descriptor)
        if created:
            try:
                lock_path.unlink()
                fsync_directory(lock_path.parent)
            except OSError:
                pass
        if isinstance(exc, ArchiveServiceError):
            raise
        raise ArchiveServiceError(
            "Title revert recovery common write lock could not be acquired."
        ) from exc


def zet_title_remap_revert_receipt_from_journal(
    journal: dict[str, Any],
    source_receipt: dict[str, Any],
    *,
    source_receipt_path: str,
    source_receipt_sha256: str,
) -> dict[str, Any]:
    if (
        journal.get("source_receipt_path") != source_receipt_path
        or journal.get("source_receipt_sha256")
        != source_receipt_sha256
        or journal.get("items") != source_receipt.get("items")
        or journal.get("item_count") != source_receipt.get("item_count")
    ):
        raise ArchiveServiceError(
            "Title revert recovery source receipt binding changed."
        )
    return {
        "schema": ZET_TITLE_REMAP_REVERT_RECEIPT_SCHEMA,
        "action": "zet_title_remap_revert",
        "status": "reverted",
        "reverted_at": journal["prepared_at"],
        "archive_id": journal["archive_id"],
        "source_receipt_path": journal["source_receipt_path"],
        "source_receipt_sha256": journal[
            "source_receipt_sha256"
        ],
        "source_proposal_sha256": source_receipt[
            "proposal_sha256"
        ],
        "source_plan_digest": source_receipt["plan_digest"],
        "source_write_plan_digest": source_receipt[
            "write_plan_digest"
        ],
        "planner_wom_kit_version": journal[
            "planner_wom_kit_version"
        ],
        "source_history_audit_digest": journal[
            "source_history_audit_digest"
        ],
        "revert_plan_digest": journal["revert_plan_digest"],
        "reviewed_by": journal["reviewed_by"],
        "human_affirmations": journal["human_affirmations"],
        "item_count": journal["item_count"],
        "items": journal["items"],
        "mutation_contract": {
            "field_restored": "frontmatter.title",
            "exact_prior_file_bytes_restored": True,
            "body_bytes_preserved": True,
            "other_frontmatter_semantics_restored": True,
            "updated_at_changed": False,
            "source_receipt_preserved": True,
            "rollback_on_runtime_failure": True,
            "crash_recovery_journal_written": True,
        },
        "privacy_guards": {
            "old_title_text_stored_in_receipt": False,
            "new_title_text_stored_in_receipt": False,
            "body_text_stored_in_receipt": False,
            "contains_private_zettel_ids_and_paths": True,
            "provider_api_called": False,
            "model_called": False,
            "secret_store_or_environment_read": False,
        },
    }


def zet_title_remap_revert_recover(
    archive_root: Path | str,
    *,
    case_sha256: str,
    expected_plan_digest: str,
    expected_action: str,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    affirm_recovery_reviewed: bool = False,
    affirm_archive_quiescent: bool = False,
    max_receipts: int = ZET_TITLE_REMAP_AUDIT_MAX_RECEIPTS,
    max_journals: int = ZET_TITLE_REMAP_AUDIT_MAX_JOURNALS,
    max_cases: int = 100,
    progress_callback: Callable[
        [str, str, int | None, int | None],
        None,
    ]
    | None = None,
) -> dict[str, Any]:
    if type(dry_run) is not bool or type(approve) is not bool or approve:
        return _compound_exact_human_approval_blocked(
            lifecycle_action="zet_title_remap_revert_recover",
        )
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    case_sha256 = str(case_sha256 or "").strip()
    expected_plan_digest = str(
        expected_plan_digest or ""
    ).strip()
    expected_action = str(expected_action or "").strip()
    reviewer = safe_foreign_quarantine_actor_id(reviewed_by)
    blockers: list[str] = []
    warnings: list[str] = []
    selected_case: dict[str, Any] | None = None
    actual_plan_digest: str | None = None
    recovery_guard_acquired = False
    recovery_guard_file_created = False
    private_journal_read = False
    source_receipt_read = False
    prior_snapshot_bytes_read = False
    canonical_files_written = 0
    canonical_write_attempt_count = 0
    receipt_written_this_run = False
    receipt_preserved = False
    write_lock_reacquired = False
    write_lock_removed: bool | None = None
    transaction_journal_removed: bool | None = None
    cleanup_attempted = False
    execution_started = False
    journal_path: Path | None = None
    lock_path: Path | None = None
    revert_receipt_path: Path | None = None

    def result_payload(status: str) -> dict[str, Any]:
        ok = (
            status in {"ready_to_recover", "recovered"}
            and not blockers
        )
        evidence_retained = bool(
            journal_path is not None and journal_path.exists()
        )
        case_payload = (
            {
                "case_sha256": selected_case.get("case_sha256"),
                "operation": selected_case.get("operation"),
                "observed_state": selected_case.get(
                    "observed_state"
                ),
                "final_receipt_state": selected_case.get(
                    "final_receipt_state"
                ),
                "write_lock_state": selected_case.get(
                    "write_lock_state"
                ),
                "recommended_action": selected_case.get(
                    "recommended_action"
                ),
                "participant_write_count": selected_case.get(
                    "participant_write_count"
                ),
                "receipt_write_required": selected_case.get(
                    "receipt_write_required"
                ),
                "evidence_cleanup_required": selected_case.get(
                    "evidence_cleanup_required"
                ),
            }
            if selected_case is not None
            else None
        )
        return {
            "ok": ok,
            "schema": ZET_TITLE_REMAP_REVERT_RECOVER_SCHEMA,
            "lifecycle_action": "zet_title_remap_revert_recover",
            "status": status,
            "dry_run": bool(dry_run),
            "approved": bool(approve and status == "recovered"),
            "archive_id": archive_id,
            "case_sha256": (
                case_sha256
                if re.fullmatch(
                    r"sha256:[0-9a-f]{64}",
                    case_sha256,
                )
                else None
            ),
            "expected_plan_digest": (
                expected_plan_digest
                if re.fullmatch(
                    r"sha256:[0-9a-f]{64}",
                    expected_plan_digest,
                )
                else None
            ),
            "actual_plan_digest": actual_plan_digest,
            "expected_plan_digest_matches": bool(
                actual_plan_digest
                and actual_plan_digest == expected_plan_digest
            ),
            "expected_action": (
                expected_action
                if expected_action
                in ZET_TITLE_REMAP_REVERT_RECOVERY_ACTIONS
                else None
            ),
            "case": case_payload,
            "summary": {
                "canonical_files_written_this_run": (
                    canonical_files_written
                ),
                "canonical_write_attempt_count": (
                    canonical_write_attempt_count
                ),
                "revert_receipt_written_this_run": (
                    receipt_written_this_run
                ),
                "verified_revert_receipt_preserved": (
                    receipt_preserved
                ),
                "write_lock_reacquired": write_lock_reacquired,
                "write_lock_removed": write_lock_removed,
                "transaction_journal_removed": (
                    transaction_journal_removed
                ),
            },
            "approval_contract": {
                "fresh_recovery_approval_required": True,
                "reviewed_by_supplied": bool(reviewer),
                "reviewed_by_echoed": False,
                "recovery_reviewed_affirmed": bool(
                    affirm_recovery_reviewed
                ),
                "archive_quiescent_affirmed": bool(
                    affirm_archive_quiescent
                ),
                "plan_digest_case_and_action_bound": bool(
                    selected_case is not None
                    and actual_plan_digest == expected_plan_digest
                    and selected_case.get("case_sha256")
                    == case_sha256
                    and selected_case.get("recommended_action")
                    == expected_action
                ),
                "original_revert_authorization_preserved": True,
                "new_recovery_approval_persisted_in_separate_receipt": (
                    False
                ),
            },
            "recovery_guard": {
                "acquired": recovery_guard_acquired,
                "guard_file_created_this_run": (
                    recovery_guard_file_created
                ),
                "automatically_released": (
                    True if recovery_guard_acquired else None
                ),
                "path_echoed": False,
                "serializes_apply_and_revert_recovery_executors": True,
            },
            "write_boundary": {
                "canonical_zets_modified": (
                    canonical_files_written > 0
                ),
                "canonical_files_restored_to_prior_bytes": (
                    canonical_files_written
                ),
                "canonical_files_moved_back_to_applied_bytes": 0,
                "source_apply_receipt_modified_or_deleted": False,
                "revert_receipt_created": receipt_written_this_run,
                "verified_revert_receipt_modified_or_deleted": False,
                "common_write_lock_created": write_lock_reacquired,
                "common_write_lock_deleted": bool(
                    write_lock_removed
                ),
                "transaction_journal_deleted": bool(
                    transaction_journal_removed
                ),
                "prior_byte_snapshots_modified_or_deleted": False,
                "recovery_guard_file_created": (
                    recovery_guard_file_created
                ),
                "provider_state_written": False,
                "objet_bytes_written": False,
                "database_rows_written": False,
            },
            "retry_contract": {
                "safe_direction_only": True,
                "successful_prior_byte_restores_reapplied_on_failure": (
                    False
                ),
                "journal_retained_on_incomplete_recovery": (
                    evidence_retained
                ),
                "fresh_plan_and_approval_required_after_incomplete_recovery": (
                    True
                ),
            },
            "privacy_guards": {
                "journal_private_metadata_read": private_journal_read,
                "source_receipt_private_metadata_read": (
                    source_receipt_read
                ),
                "prior_snapshot_bytes_read": prior_snapshot_bytes_read,
                "journal_receipt_lock_or_snapshot_paths_echoed": False,
                "zettel_ids_echoed": False,
                "zettel_paths_echoed": False,
                "old_or_new_title_values_echoed": False,
                "title_hashes_echoed": False,
                "title_lengths_echoed": False,
                "zettel_body_text_echoed": False,
                "reviewed_by_echoed": False,
                "proposal_sha256_echoed": False,
                "absolute_local_paths_echoed": False,
                "provider_api_called": False,
                "model_called": False,
                "secret_store_or_environment_read": False,
            },
            "blockers": unique_preserve_order(blockers),
            "warnings": unique_preserve_order(warnings),
            "next_safe_actions": (
                [
                    "Run this exact revert case SHA, complete plan digest, and fixed action with --approve only after fresh recovery review and archive-quiescence confirmation."
                ]
                if status == "ready_to_recover"
                else [
                    "Title-revert recovery completed in the reviewed compensation direction; preserve the immutable source and revert receipts plus prior-byte snapshots."
                ]
                if status == "recovered"
                else [
                    "Retain every source/revert receipt, journal, lock, canonical participant, and prior-byte snapshot; generate a fresh plan before another approved attempt."
                ]
            ),
        }

    if bool(dry_run) == bool(approve):
        blockers.append("choose_exactly_one_of_dry_run_or_approve")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", case_sha256):
        blockers.append("revert_recovery_case_sha256_invalid")
    if not re.fullmatch(
        r"sha256:[0-9a-f]{64}",
        expected_plan_digest,
    ):
        blockers.append(
            "expected_revert_recovery_plan_digest_invalid"
        )
    if (
        expected_action
        not in ZET_TITLE_REMAP_REVERT_RECOVERY_ACTIONS
    ):
        blockers.append("expected_revert_recovery_action_invalid")
    if approve:
        if reviewer is None:
            blockers.append("safe_reviewed_by_required")
        if not affirm_recovery_reviewed:
            blockers.append("affirm_recovery_reviewed_required")
        if not affirm_archive_quiescent:
            blockers.append("affirm_archive_quiescent_required")
    elif (
        reviewed_by
        or affirm_recovery_reviewed
        or affirm_archive_quiescent
    ):
        blockers.append("approval_fields_only_valid_with_approve")
    if blockers:
        return result_payload("blocked")

    def fresh_plan() -> dict[str, Any]:
        return zet_title_remap_revert_recovery_plan(
            root,
            dry_run=True,
            max_receipts=max_receipts,
            max_journals=max_journals,
            max_cases=max_cases,
            progress_callback=progress_callback,
        )

    def select_case(
        plan: dict[str, Any],
    ) -> dict[str, Any] | None:
        matches = [
            case
            for case in plan.get("cases", [])
            if isinstance(case, dict)
            and case.get("case_sha256") == case_sha256
        ]
        return matches[0] if len(matches) == 1 else None

    plan = fresh_plan()
    actual_plan_digest = (
        plan.get("plan_digest")
        if isinstance(plan.get("plan_digest"), str)
        else None
    )
    if not plan.get("ok"):
        blockers.extend(
            f"plan:{code}" for code in plan.get("blockers", [])
        )
    if actual_plan_digest != expected_plan_digest:
        blockers.append("revert_recovery_plan_digest_mismatch")
    selected_case = select_case(plan)
    if selected_case is None:
        blockers.append(
            "revert_recovery_case_not_found_or_ambiguous"
        )
    elif selected_case.get("operation") != "revert":
        blockers.append("selected_case_is_not_revert")
    elif selected_case.get("recommended_action") != expected_action:
        blockers.append("revert_recovery_expected_action_mismatch")
    elif expected_action == "manual_forensic_hold":
        blockers.append("manual_forensic_hold_not_executable")
    elif (
        expected_action
        not in ZET_TITLE_REMAP_EXECUTABLE_REVERT_RECOVERY_ACTIONS
    ):
        blockers.append("revert_recovery_action_not_implemented")
    if blockers:
        return result_payload("blocked")
    if dry_run:
        return result_payload("ready_to_recover")

    assert reviewer is not None
    try:
        with _zet_title_remap_recovery_guard(root) as guard:
            recovery_guard_acquired = bool(guard.get("acquired"))
            recovery_guard_file_created = bool(
                guard.get("guard_file_created_this_run")
            )
            plan = fresh_plan()
            actual_plan_digest = (
                plan.get("plan_digest")
                if isinstance(plan.get("plan_digest"), str)
                else None
            )
            fresh_case = select_case(plan)
            if (
                not plan.get("ok")
                or actual_plan_digest != expected_plan_digest
                or fresh_case is None
                or fresh_case.get("recommended_action")
                != expected_action
            ):
                blockers.append(
                    "revert_recovery_case_changed_before_execution"
                )
                return result_payload("blocked")
            selected_case = fresh_case

            journal_path, journal_raw, journal = (
                find_zet_title_remap_revert_recovery_journal(
                    root,
                    archive_id=archive_id,
                    case_sha256=case_sha256,
                    max_journals=int(max_journals),
                )
            )
            private_journal_read = True
            title_remap_root = archive_internal_path(
                root,
                ZET_TITLE_REMAP_PROPOSAL_PREFIX.rstrip("/"),
            )
            lock_path = title_remap_root / ".title-remap.write.lock"
            source_receipt_path = archive_internal_path(
                root,
                journal["source_receipt_path"],
            )
            source_raw, source_receipt, source_proposal_sha256 = (
                read_zet_title_remap_receipt_for_audit(
                    root,
                    source_receipt_path,
                    archive_id=archive_id,
                )
            )
            source_receipt_read = True
            if (
                "sha256:"
                + hashlib.sha256(source_raw).hexdigest()
                != journal["source_receipt_sha256"]
                or source_proposal_sha256
                != source_receipt.get("proposal_sha256")
                or source_receipt.get("items")
                != journal.get("items")
                or source_receipt.get("item_count")
                != journal.get("item_count")
            ):
                blockers.append(
                    "revert_recovery_source_receipt_binding_changed"
                )
                return result_payload("blocked")
            expected_revert_receipt = (
                zet_title_remap_revert_receipt_from_journal(
                    journal,
                    source_receipt,
                    source_receipt_path=journal["source_receipt_path"],
                    source_receipt_sha256=journal[
                        "source_receipt_sha256"
                    ],
                )
            )
            if (
                not zet_title_remap_revert_receipt_document_valid(
                    expected_revert_receipt
                )
                or validate_schema(
                    expected_revert_receipt,
                    "zet-title-remap-revert-receipt.schema.json",
                )
            ):
                blockers.append(
                    "revert_recovery_receipt_reconstruction_invalid"
                )
                return result_payload("blocked")
            revert_receipt_path = archive_internal_path(
                root,
                journal["final_receipt_path"],
            )
            if (
                archive_relative_path(revert_receipt_path, root)
                != journal["final_receipt_path"]
                or journal["final_receipt_path"]
                != zet_title_remap_revert_receipt_relative_path(
                    journal["source_receipt_sha256"]
                )
                or zet_revision_path_has_symlink_component(
                    root,
                    revert_receipt_path,
                )
                or revert_receipt_path.is_symlink()
            ):
                blockers.append(
                    "revert_recovery_receipt_path_unsafe"
                )
                return result_payload("blocked")

            state = (
                classify_zet_title_remap_revert_transaction_journal(
                    root,
                    journal,
                )
            )
            observed_state = str(state.get("status") or "invalid")
            planned_state = str(
                fresh_case.get("observed_state") or "invalid"
            )
            state_matches_case = (
                observed_state == planned_state
                or (
                    planned_state == "stale_completed"
                    and observed_state
                    == "fully_reverted_receipt_missing"
                )
            )
            if (
                not state_matches_case
                or any(
                    int(state.get(key) or 0)
                    != int(fresh_case.get(key) or 0)
                    for key in (
                        "before_count",
                        "after_count",
                        "divergent_count",
                        "missing_count",
                    )
                )
            ):
                blockers.append(
                    "revert_recovery_participant_state_changed_after_plan"
                )
                return result_payload("blocked")

            manifest_index, manifest_blockers = (
                zet_revision_snapshot_manifest_index(root)
            )
            if manifest_blockers:
                blockers.append(
                    "revert_recovery_snapshot_manifest_invalid"
                )
                return result_payload("blocked")
            existing_revert_receipt_bytes: bytes | None = None
            if expected_action == (
                "cleanup_verified_completed_title_revert_evidence"
            ):
                (
                    existing_revert_receipt_bytes,
                    existing_revert_receipt,
                    _existing_revert_receipt_sha256,
                ) = read_zet_title_remap_revert_receipt(
                    root,
                    revert_receipt_path,
                    archive_id=archive_id,
                    source_receipt_sha256=journal[
                        "source_receipt_sha256"
                    ],
                )
                verification = verify_zet_title_remap_revert_receipt(
                    root,
                    revert_receipt_path,
                    archive_id=archive_id,
                    source_receipt_path=journal[
                        "source_receipt_path"
                    ],
                    source_receipt_sha256=journal[
                        "source_receipt_sha256"
                    ],
                    source_receipt=source_receipt,
                    manifest_index=manifest_index,
                )
                if (
                    existing_revert_receipt
                    != expected_revert_receipt
                    or not verification.get("ok")
                ):
                    blockers.append(
                        "revert_recovery_verified_receipt_binding_changed"
                    )
                    return result_payload("blocked")
                receipt_preserved = True
            elif (
                revert_receipt_path.exists()
                or revert_receipt_path.is_symlink()
            ):
                blockers.append(
                    "revert_recovery_receipt_became_occupied"
                )
                return result_payload("blocked")

            write_lock_reacquired = (
                _ensure_zet_title_remap_revert_recovery_write_lock(
                    root,
                    lock_path=lock_path,
                    journal_path=journal_path,
                    journal=journal,
                )
            )
            locked_raw, locked_journal = (
                read_zet_title_remap_revert_transaction_journal(
                    root,
                    journal_path,
                    archive_id=archive_id,
                )
            )
            if (
                locked_raw != journal_raw
                or "sha256:"
                + hashlib.sha256(locked_raw).hexdigest()
                != case_sha256
                or locked_journal != journal
                or read_zet_title_remap_write_lock(root, lock_path)
                != zet_title_remap_revert_write_lock_document(
                    journal_path,
                    journal,
                )
            ):
                blockers.append(
                    "revert_recovery_journal_or_lock_binding_changed"
                )
                return result_payload("blocked")
            execution_started = True

            safe_direction_candidates = (
                _materialize_zet_title_remap_recovery_writes(
                    root,
                    journal,
                    rollback_to_before=True,
                )
            )
            prior_snapshot_bytes_read = True
            if expected_action == (
                "resume_title_revert_forward_and_finalize_receipt"
            ):
                participant_writes = safe_direction_candidates
                expected_write_count = int(
                    fresh_case.get("participant_write_count") or 0
                )
            else:
                participant_writes = []
                expected_write_count = 0
            if len(participant_writes) != expected_write_count:
                blockers.append(
                    "revert_recovery_participant_write_set_changed"
                )
                return result_payload("blocked")
            if participant_writes and progress_callback is not None:
                progress_callback(
                    "title-revert-recovery-write",
                    "start",
                    0,
                    len(participant_writes),
                )
            for index, item in enumerate(
                participant_writes,
                start=1,
            ):
                if (
                    read_zet_title_remap_canonical_bytes(item["path"])
                    != item["source_bytes"]
                ):
                    raise ArchiveServiceError(
                        "Title revert recovery participant changed immediately before write."
                    )
                canonical_write_attempt_count += 1
                write_bytes_atomic(
                    item["path"],
                    item["target_bytes"],
                )
                written_bytes = (
                    read_zet_title_remap_canonical_bytes(item["path"])
                )
                if (
                    written_bytes != item["target_bytes"]
                    or "sha256:"
                    + hashlib.sha256(written_bytes).hexdigest()
                    != item["target_sha256"]
                ):
                    raise ArchiveServiceError(
                        "Title revert recovery canonical write verification failed."
                    )
                canonical_files_written += 1
                if progress_callback is not None:
                    progress_callback(
                        "title-revert-recovery-write",
                        "written",
                        index,
                        len(participant_writes),
                    )
            if participant_writes and progress_callback is not None:
                progress_callback(
                    "title-revert-recovery-write",
                    "done",
                    len(participant_writes),
                    len(participant_writes),
                )

            final_state = (
                classify_zet_title_remap_revert_transaction_journal(
                    root,
                    journal,
                )
            )
            if expected_action == (
                "cleanup_unstarted_title_revert_transaction_evidence"
            ):
                expected_final_state = "prepared"
            elif expected_action == (
                "cleanup_verified_completed_title_revert_evidence"
            ):
                expected_final_state = (
                    "fully_reverted_receipt_missing"
                )
            else:
                expected_final_state = (
                    "fully_reverted_receipt_missing"
                )
            if (
                final_state.get("status") != expected_final_state
                or (
                    expected_final_state == "prepared"
                    and int(final_state.get("after_count") or 0)
                    != int(journal["item_count"])
                )
                or (
                    expected_final_state
                    == "fully_reverted_receipt_missing"
                    and int(final_state.get("before_count") or 0)
                    != int(journal["item_count"])
                )
            ):
                raise ArchiveServiceError(
                    "Title revert recovery final participant state did not verify."
                )

            must_write_receipt = expected_action in {
                "resume_title_revert_forward_and_finalize_receipt",
                "finalize_title_revert_receipt",
            }
            if must_write_receipt:
                revert_receipt_path.parent.mkdir(
                    parents=True,
                    exist_ok=True,
                )
                write_json_new_file(
                    revert_receipt_path,
                    expected_revert_receipt,
                )
                receipt_written_this_run = True
                verification = verify_zet_title_remap_revert_receipt(
                    root,
                    revert_receipt_path,
                    archive_id=archive_id,
                    source_receipt_path=journal[
                        "source_receipt_path"
                    ],
                    source_receipt_sha256=journal[
                        "source_receipt_sha256"
                    ],
                    source_receipt=source_receipt,
                    manifest_index=manifest_index,
                )
                if not verification.get("ok"):
                    raise ArchiveServiceError(
                        "Title revert recovery receipt verification failed."
                    )
                receipt_preserved = True
            elif existing_revert_receipt_bytes is not None:
                if (
                    not revert_receipt_path.is_file()
                    or revert_receipt_path.is_symlink()
                    or revert_receipt_path.read_bytes()
                    != existing_revert_receipt_bytes
                ):
                    raise ArchiveServiceError(
                        "Title revert recovery verified receipt changed."
                    )
                receipt_preserved = True
            elif (
                revert_receipt_path.exists()
                or revert_receipt_path.is_symlink()
            ):
                raise ArchiveServiceError(
                    "Title revert recovery receipt became occupied."
                )

            if source_receipt_path.read_bytes() != source_raw:
                raise ArchiveServiceError(
                    "Title revert recovery source receipt changed."
                )
            if (
                read_zet_title_remap_write_lock(root, lock_path)
                != zet_title_remap_revert_write_lock_document(
                    journal_path,
                    journal,
                )
            ):
                raise ArchiveServiceError(
                    "Title revert recovery common write lock changed."
                )
            cleanup_attempted = True
            try:
                write_lock_removed = (
                    _remove_zet_title_remap_recovery_evidence(
                        lock_path
                    )
                )
            except OSError:
                write_lock_removed = False
            if not write_lock_removed:
                blockers.append(
                    "revert_recovery_completed_but_write_lock_cleanup_failed"
                )
                return result_payload(
                    "recovery_incomplete_evidence_retained"
                )

            current_journal_raw, _current_journal = (
                read_zet_title_remap_revert_transaction_journal(
                    root,
                    journal_path,
                    archive_id=archive_id,
                )
            )
            if current_journal_raw != journal_raw:
                blockers.append(
                    "revert_recovery_journal_changed_before_cleanup"
                )
                return result_payload(
                    "recovery_incomplete_evidence_retained"
                )
            try:
                transaction_journal_removed = (
                    _remove_zet_title_remap_recovery_evidence(
                        journal_path
                    )
                )
            except OSError:
                transaction_journal_removed = False
            if not transaction_journal_removed:
                blockers.append(
                    "revert_recovery_completed_but_journal_cleanup_failed"
                )
                return result_payload(
                    "recovery_incomplete_evidence_retained"
                )
            if receipt_preserved:
                final_receipt_raw, final_receipt, _digest = (
                    read_zet_title_remap_revert_receipt(
                        root,
                        revert_receipt_path,
                        archive_id=archive_id,
                        source_receipt_sha256=journal[
                            "source_receipt_sha256"
                        ],
                    )
                )
                receipt_preserved = bool(
                    final_receipt == expected_revert_receipt
                    and final_receipt_raw
                )
                if not receipt_preserved:
                    blockers.append(
                        "revert_recovery_completed_but_receipt_changed"
                    )
                    return result_payload(
                        "recovery_incomplete_evidence_retained"
                    )
            return result_payload("recovered")
    except (
        ArchiveServiceError,
        ArchivePathError,
        OSError,
        UnicodeDecodeError,
        ValueError,
    ):
        blockers.append(
            "revert_recovery_execution_failed_evidence_retained"
        )
        if lock_path is not None:
            write_lock_removed = not lock_path.exists()
        if journal_path is not None:
            transaction_journal_removed = not journal_path.exists()
        return result_payload(
            "recovery_incomplete_evidence_retained"
            if (
                canonical_files_written
                or receipt_written_this_run
                or write_lock_reacquired
                or cleanup_attempted
                or execution_started
            )
            else "blocked"
        )


def first_read_readiness(
    archive_root: Path | str,
    *,
    dry_run: bool = False,
    max_items: int = 100,
    item_cache: dict[str, dict[str, Any]] | None = None,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> dict[str, Any]:
    """Check whether every canonical zet has a compact, uniquely addressable first read."""
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    max_items = max(1, min(int(max_items), 500))
    if not dry_run:
        blockers.append("first-read-readiness is read-only and requires --dry-run.")

    path_entries = zet_catalog_paths(root, "canonical")
    entries, scan = zet_catalog_entries(
        root,
        path_entries,
        item_cache,
        progress_callback=progress_callback,
    )
    snapshot = zet_catalog_snapshot(root, entries)
    abstract_coverage = zet_catalog_abstract_coverage(entries)
    identity_coverage = zet_catalog_identity_coverage(entries)
    abstract_counts = abstract_coverage["counts"]
    required_count = int(abstract_coverage["first_read_required_count"])
    all_required_explicit = int(abstract_counts["explicit"]) == required_count
    compact_first_reads_available = bool(
        abstract_coverage["all_required_first_reads_available"]
    )
    followup_ids_ready = bool(identity_coverage["all_entries_uniquely_addressable"])
    surface_ready = all_required_explicit and followup_ids_ready

    attention_items: list[dict[str, Any]] = []
    abstract_attention_count = 0
    for _path, _expected_status, item, _signature in entries:
        abstract_status = str(item.get("abstract_status") or "missing")
        if abstract_status in {"explicit", "redacted"}:
            continue
        abstract_attention_count += 1
        if len(attention_items) >= max_items:
            continue
        zettel_id = item.get("id")
        safe_zettel_id = (
            zettel_id
            if isinstance(zettel_id, str) and ZETTEL_EDGE_ZETTEL_ID_RE.match(zettel_id)
            else None
        )
        attention_items.append(
            {
                "path": item.get("path"),
                "zettel_id": safe_zettel_id,
                "abstract_status": abstract_status,
                "frontmatter_readable": bool(item.get("frontmatter_readable")),
                "redacted": bool(item.get("redacted")),
            }
        )

    if blockers:
        state = "blocked"
    elif surface_ready:
        state = "ready"
    elif compact_first_reads_available and followup_ids_ready:
        state = "compatibility_only"
    else:
        state = "needs_attention"

    next_actions: list[str] = []
    if abstract_attention_count:
        next_actions.append(
            "Review the listed canonical zets and prepare human-reviewed explicit abstract backfills; do not auto-write them."
        )
    if not followup_ids_ready:
        next_actions.append(
            "Resolve missing, unsafe, or duplicate canonical zet ids before relying on id-based follow-up reads."
        )
    if surface_ready:
        next_actions.append(
            "Proceed to zet-catalog-pass for the private exhaustive first-read artifact, then consume it from page zero."
        )
    elif not blockers:
        next_actions.append(
            "Rerun first-read-readiness after reviewed fixes; do not claim archive-wide explicit first-read readiness yet."
        )

    return {
        "ok": not blockers,
        "schema": FIRST_READ_READINESS_SCHEMA,
        "lifecycle_action": "first_read_readiness",
        "state": state,
        "readiness_met": surface_ready,
        "archive_id": read_archive_id(root),
        "dry_run": True,
        "canonical_zet_count": len(entries),
        "abstract_coverage": abstract_coverage,
        "identity_coverage": identity_coverage,
        "readiness": {
            "canonical_node_inventory_checked": not blockers,
            "all_required_compact_first_reads_available": compact_first_reads_available,
            "all_required_explicit_abstracts_present": all_required_explicit,
            "all_followup_ids_uniquely_resolvable": followup_ids_ready,
            "first_read_surface_ready": surface_ready,
            "redacted_entries_excluded_from_abstract_requirement": True,
        },
        "attention": {
            "total_count": abstract_attention_count,
            "returned_count": len(attention_items),
            "truncated": abstract_attention_count > len(attention_items),
            "max_items": max_items,
            "items": attention_items,
            "duplicate_id_values_echoed": False,
        },
        "scan": {
            **scan,
            "status": "canonical",
            "frontmatter_only": True,
            "zettel_bodies_read": False,
            "objet_bytes_read": False,
            "provider_api_called": False,
            "secrets_read": False,
        },
        "snapshot": snapshot,
        "claim_boundary": {
            "checked": "Canonical zet paths, frontmatter abstract status, and safe frontmatter id uniqueness at this snapshot.",
            "not_checked": [
                "zet body meaning or completeness",
                "abstract semantic quality",
                "whether a host model actually consumed every abstract",
                "objet bytes or derived text",
                "provider or backup freshness",
            ],
        },
        "blockers": blockers,
        "warnings": [],
        "exit_policy": {
            "zero_when_diagnostic_completed": True,
            "needs_attention_is_command_failure": False,
            "nonzero_reserved_for_blocked_input_or_execution_failure": True,
        },
        "next_actions": next_actions,
        "would_change": [],
        "privacy_guards": {
            "abstract_text_echoed": False,
            "title_values_echoed": False,
            "body_text_echoed": False,
            "duplicate_id_values_echoed": False,
            "local_absolute_paths_echoed": False,
            "provider_urls_echoed": False,
            "writes": False,
        },
    }


def zet_catalog(
    archive_root: Path | str,
    *,
    status: str = "canonical",
    projection: str = "full",
    coverage_mode: str = "page",
    order_mode: str = "path",
    start_zettel_ids: list[str] | None = None,
    cursor: int = 0,
    page_size: int = 200,
    max_estimated_tokens: int | None = None,
    response_envelope_reserve_tokens: int = 0,
    response_profile: str = "full",
    expected_snapshot_id: str | None = None,
    continuation_token: str | None = None,
    dry_run: bool = False,
    item_cache: dict[str, dict[str, Any]] | None = None,
    materialize_session_snapshot: bool = False,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []
    if not dry_run:
        blockers.append("zet-catalog is read-only and requires --dry-run.")
    if status not in {"all", "draft", "canonical"}:
        blockers.append("status must be one of: all, draft, canonical")
    if projection not in ZET_CATALOG_PROJECTIONS:
        blockers.append("projection must be one of: full, reading, routed_reading")
    if coverage_mode not in ZET_CATALOG_COVERAGE_MODES:
        blockers.append("coverage_mode must be one of: page, strict")
    if order_mode not in ZET_CATALOG_ORDER_MODES:
        blockers.append("order_mode must be one of: path, seeded_connection_walk")
    if response_profile not in ZET_CATALOG_RESPONSE_PROFILES:
        blockers.append("response_profile must be one of: full, continuation")
    seed_zettel_ids = zet_catalog_normalize_seed_ids(start_zettel_ids, blockers)
    if order_mode == "path" and seed_zettel_ids:
        blockers.append("start_zettel_id requires order_mode=seeded_connection_walk.")
    if order_mode == "seeded_connection_walk" and not seed_zettel_ids:
        blockers.append("seeded_connection_walk requires at least one start_zettel_id.")
    if projection == "routed_reading" and order_mode != "seeded_connection_walk":
        blockers.append("routed_reading requires order_mode=seeded_connection_walk.")
    if response_profile == "continuation" and (coverage_mode != "strict" or cursor == 0):
        blockers.append("response_profile=continuation requires a nonzero strict continuation cursor.")
    order_descriptor = zet_catalog_order_descriptor(order_mode)
    if cursor < 0:
        blockers.append("cursor must be a non-negative integer.")
    if page_size < 1 or page_size > ZET_CATALOG_MAX_PAGE_SIZE:
        blockers.append(f"page_size must be between 1 and {ZET_CATALOG_MAX_PAGE_SIZE}.")
    if max_estimated_tokens is not None and max_estimated_tokens < 1:
        blockers.append("max_estimated_tokens must be a positive integer when provided.")
    if response_envelope_reserve_tokens < 0:
        blockers.append("response_envelope_reserve_tokens must be a non-negative integer.")
    if response_envelope_reserve_tokens and max_estimated_tokens is None:
        blockers.append("response_envelope_reserve_tokens requires max_estimated_tokens.")
    effective_items_token_budget = (
        max(1, max_estimated_tokens - response_envelope_reserve_tokens)
        if max_estimated_tokens is not None
        else None
    )
    if expected_snapshot_id and not re.match(r"^sha256:[0-9a-f]{64}$", expected_snapshot_id):
        blockers.append("expected_snapshot_id must use sha256:<64 lowercase hex> syntax.")
    continuation_payload, expected_snapshot_id = zet_catalog_continuation_context(
        coverage_mode=coverage_mode,
        continuation_token=continuation_token,
        cursor=cursor,
        status=status,
        projection=projection,
        order_descriptor=order_descriptor,
        seed_zettel_ids=seed_zettel_ids,
        expected_snapshot_id=expected_snapshot_id,
        blockers=blockers,
    )

    cached_scope = item_cache.get("__catalog_scope__") if item_cache is not None else None
    materialized_entries = cached_scope.get("entries") if isinstance(cached_scope, dict) else None
    materialized_snapshot = cached_scope.get("snapshot") if isinstance(cached_scope, dict) else None
    order_cache_key = sha256_json_value(
        {"order_mode": order_mode, "seed_zettel_ids": seed_zettel_ids}
    )
    cached_orders = cached_scope.get("ordered_entries") if isinstance(cached_scope, dict) else None
    cached_order_record = (
        cached_orders.get(order_cache_key)
        if isinstance(cached_orders, dict) and isinstance(cached_orders.get(order_cache_key), dict)
        else None
    )
    materialized_ordered_entries = (
        cached_order_record.get("entries") if isinstance(cached_order_record, dict) else None
    )
    materialized_ordered_routes = (
        cached_order_record.get("routes") if isinstance(cached_order_record, dict) else None
    )
    materialized_snapshot_reused = False
    completion_revalidation_performed = False
    if (
        materialize_session_snapshot
        and expected_snapshot_id
        and isinstance(materialized_entries, list)
        and isinstance(materialized_snapshot, dict)
        and isinstance(materialized_ordered_entries, list)
        and isinstance(materialized_ordered_routes, list)
        and len(materialized_ordered_routes) == len(materialized_ordered_entries)
        and materialized_snapshot.get("id") == expected_snapshot_id
    ):
        preview_candidates = [
            zet_catalog_project_item(
                entry[2],
                projection,
                catalog_order_index=cursor + offset,
                reading_route=materialized_ordered_routes[cursor + offset],
            )
            for offset, entry in enumerate(materialized_ordered_entries[cursor : cursor + page_size])
        ]
        preview_page, _preview_stopped, _preview_single = zet_catalog_budgeted_page(
            preview_candidates,
            max_estimated_tokens=effective_items_token_budget,
        )
        preview_would_complete = cursor + len(preview_page) >= len(materialized_ordered_entries)
        if not preview_would_complete:
            materialized_snapshot_reused = True
        else:
            completion_revalidation_performed = True

    if materialized_snapshot_reused:
        if progress_callback is not None:
            progress_callback(
                "catalog-session-snapshot",
                "reused",
                len(materialized_entries),
                len(materialized_entries),
            )
        entries = materialized_entries
        snapshot = cached_scope["snapshot"]
        scan = {
            "path_count": len(entries),
            "path_metadata_checked": 0,
            "frontmatter_files_scanned": 0,
            "frontmatter_scan_mode": "materialized_session_snapshot",
            "frontmatter_scan_workers": 0,
            "cached_items_reused": len(entries),
            "cache_mode": "process_local_ephemeral",
            "cache_authoritative": False,
            "cache_persisted": False,
            "snapshot_cache_reused": True,
        }
    else:
        if progress_callback is not None:
            progress_callback("catalog-scope", "start", None, None)
        path_entries = zet_catalog_paths(root, status) if status in {"all", "draft", "canonical"} else []
        if progress_callback is not None:
            progress_callback("catalog-scope", "done", len(path_entries), len(path_entries))
        entries, scan = zet_catalog_entries(
            root,
            path_entries,
            item_cache,
            progress_callback=progress_callback,
        )
        scope_cache_reusable = bool(
            isinstance(cached_scope, dict)
            and scan["frontmatter_files_scanned"] == 0
            and scan["cached_items_reused"] == len(entries)
            and cached_scope.get("path_count") == len(entries)
            and isinstance(cached_scope.get("snapshot"), dict)
        )
        if scope_cache_reusable:
            snapshot = cached_scope["snapshot"]
        else:
            snapshot = zet_catalog_snapshot(root, entries)
        if item_cache is not None:
            workload_estimates = (
                dict(cached_scope.get("workload_estimates", {}))
                if scope_cache_reusable and isinstance(cached_scope.get("workload_estimates"), dict)
                else {}
            )
            projected_items = (
                dict(cached_scope.get("projected_items", {}))
                if scope_cache_reusable and isinstance(cached_scope.get("projected_items"), dict)
                else {}
            )
            ordered_entries_cache = (
                dict(cached_scope.get("ordered_entries", {}))
                if scope_cache_reusable and isinstance(cached_scope.get("ordered_entries"), dict)
                else {}
            )
            item_cache["__catalog_scope__"] = {
                "path_count": len(entries),
                "snapshot": snapshot,
                "workload_estimates": workload_estimates,
                "projected_items": projected_items,
                "ordered_entries": ordered_entries_cache,
                "entries": entries,
            }
        scan["snapshot_cache_reused"] = scope_cache_reusable

    current_scope = item_cache.get("__catalog_scope__") if item_cache is not None else None
    current_order_cache = current_scope.get("ordered_entries") if isinstance(current_scope, dict) else None
    current_order_record = (
        current_order_cache.get(order_cache_key)
        if isinstance(current_order_cache, dict) and isinstance(current_order_cache.get(order_cache_key), dict)
        else None
    )
    cached_ordered_entries = (
        current_order_record.get("entries") if isinstance(current_order_record, dict) else None
    )
    cached_order_evidence = (
        current_order_record.get("evidence") if isinstance(current_order_record, dict) else None
    )
    cached_ordered_routes = (
        current_order_record.get("routes") if isinstance(current_order_record, dict) else None
    )
    order_cache_reused = bool(
        isinstance(cached_ordered_entries, list)
        and len(cached_ordered_entries) == len(entries)
        and isinstance(cached_order_evidence, dict)
        and isinstance(cached_ordered_routes, list)
        and len(cached_ordered_routes) == len(entries)
    )
    if order_cache_reused:
        ordered_entries = cached_ordered_entries
        order_evidence = cached_order_evidence
        ordered_routes = cached_ordered_routes
    else:
        ordered_entries, order_evidence, ordered_routes = zet_catalog_order_entries(
            entries,
            order_mode=order_mode,
            seed_zettel_ids=seed_zettel_ids,
        )
        if isinstance(current_scope, dict):
            cached_orderings = current_scope.setdefault("ordered_entries", {})
            if isinstance(cached_orderings, dict):
                current_order_record = {
                    "entries": ordered_entries,
                    "evidence": order_evidence,
                    "routes": ordered_routes,
                }
                cached_orderings[order_cache_key] = current_order_record
    scan["order_cache_reused"] = order_cache_reused
    if order_evidence.get("missing_seed_ids"):
        blockers.append("One or more start_zettel_id values do not exist in the selected catalog scope.")

    projection_cache_key = f"{projection}:{order_cache_key}"
    projected_items = current_scope.get("projected_items") if isinstance(current_scope, dict) else None
    cached_projected_items = (
        projected_items.get(projection_cache_key)
        if isinstance(projected_items, dict) and isinstance(projected_items.get(projection_cache_key), list)
        else None
    )
    projection_cache_reused = bool(
        isinstance(cached_projected_items, list) and len(cached_projected_items) == len(ordered_entries)
    )
    if projection_cache_reused:
        all_items = cached_projected_items
    else:
        all_items = [
            zet_catalog_project_item(
                entry[2],
                projection,
                catalog_order_index=index,
                reading_route=ordered_routes[index],
            )
            for index, entry in enumerate(ordered_entries)
        ]
        if isinstance(current_scope, dict):
            cached_projections = current_scope.setdefault("projected_items", {})
            if isinstance(cached_projections, dict):
                cached_projections[projection_cache_key] = all_items
    scan["projection_cache_reused"] = projection_cache_reused
    workload_estimates = current_scope.get("workload_estimates") if isinstance(current_scope, dict) else None
    scope_workload_estimate = (
        workload_estimates.get(projection_cache_key)
        if isinstance(workload_estimates, dict)
        and isinstance(workload_estimates.get(projection_cache_key), dict)
        else None
    )
    scope_metrics_cache_reused = scope_workload_estimate is not None
    if scope_workload_estimate is None:
        scope_workload_estimate = zet_catalog_workload_estimate(all_items)
        if isinstance(current_scope, dict):
            cached_workloads = current_scope.setdefault("workload_estimates", {})
            if isinstance(cached_workloads, dict):
                cached_workloads[projection_cache_key] = scope_workload_estimate
    scan["scope_metrics_cache_reused"] = scope_metrics_cache_reused
    if expected_snapshot_id and expected_snapshot_id != snapshot["id"]:
        blockers.append("catalog_snapshot_changed")

    total_count = len(ordered_entries)
    if cursor > total_count:
        blockers.append("cursor is beyond the current catalog item count.")

    cached_entry_identities = (
        current_order_record.get("entry_identities") if isinstance(current_order_record, dict) else None
    )
    entry_identity_cache_reused = bool(
        isinstance(cached_entry_identities, list)
        and len(cached_entry_identities) == len(ordered_entries)
    )
    if entry_identity_cache_reused:
        ordered_entry_identities = cached_entry_identities
    else:
        path_order_index_by_path = {entry[0]: index for index, entry in enumerate(entries)}
        ordered_entry_identities = [
            sha256_json_value(
                {
                    "basis": ZET_CATALOG_ENTRY_IDENTITY_BASIS,
                    "snapshot_id": snapshot["id"],
                    "path_order_ordinal": path_order_index_by_path[entry[0]],
                    "status": entry[1],
                }
            )
            for entry in ordered_entries
        ]
        if isinstance(current_order_record, dict):
            current_order_record["entry_identities"] = ordered_entry_identities
    scan["entry_identity_cache_reused"] = entry_identity_cache_reused

    abstract_coverage = zet_catalog_abstract_coverage(entries)
    abstract_counts = abstract_coverage["counts"]
    identity_coverage = zet_catalog_identity_coverage(entries)

    page_items: list[dict[str, Any]] = []
    stopped_for_token_budget = False
    single_item_exceeds_token_budget = False
    if not blockers:
        candidate_items = all_items[cursor : cursor + page_size]
        page_items, stopped_for_token_budget, single_item_exceeds_token_budget = zet_catalog_budgeted_page(
            candidate_items,
            max_estimated_tokens=effective_items_token_budget,
        )
    returned_count = len(page_items)
    next_cursor_value = cursor + returned_count
    complete = not blockers and next_cursor_value >= total_count
    next_cursor = None if complete or blockers else next_cursor_value
    remaining_count = total_count if blockers else max(0, total_count - next_cursor_value)
    page_entry_identity_sha256 = sha256_json_value(
        ordered_entry_identities[cursor:next_cursor_value] if not blockers else []
    )

    strict_contiguous_prefix_verified = False
    strict_chain_hash: str | None = None
    strict_continuation_token: str | None = None
    strict_covered_count = 0
    archive_wide_coverage_claim_ready = False
    archive_wide_abstract_reading_claim_ready = False
    archive_wide_followup_resolution_ready = False
    if coverage_mode == "strict" and not blockers:
        previous_chain_hash = (
            continuation_payload.get("chain_hash")
            if isinstance(continuation_payload, dict)
            else sha256_json_value(
                {
                    "schema": ZET_CATALOG_CONTINUATION_SCHEMA,
                    "snapshot_id": snapshot["id"],
                    "status_filter": status,
                    "projection": projection,
                    "order": order_descriptor,
                    "seed_zettel_ids_sha256": sha256_json_value(seed_zettel_ids),
                    "entry_identity_basis": ZET_CATALOG_ENTRY_IDENTITY_BASIS,
                    "covered_count": 0,
                }
            )
        )
        strict_chain_hash = sha256_json_value(
            {
                "previous_chain_hash": previous_chain_hash,
                "cursor": cursor,
                "page_entry_identity_sha256": page_entry_identity_sha256,
            }
        )
        strict_covered_count = next_cursor_value
        strict_contiguous_prefix_verified = True
        archive_wide_coverage_claim_ready = complete
        archive_wide_abstract_reading_claim_ready = bool(
            complete and abstract_coverage["all_required_first_reads_available"]
        )
        archive_wide_followup_resolution_ready = bool(
            complete and identity_coverage["all_entries_uniquely_addressable"]
        )
        if not complete:
            strict_continuation_token = zet_catalog_encode_continuation(
                {
                    "schema": ZET_CATALOG_CONTINUATION_SCHEMA,
                    "snapshot_id": snapshot["id"],
                    "status_filter": status,
                    "projection": projection,
                    "order": order_descriptor,
                    "seed_zettel_ids_sha256": sha256_json_value(seed_zettel_ids),
                    "entry_identity_basis": ZET_CATALOG_ENTRY_IDENTITY_BASIS,
                    "next_cursor": next_cursor,
                    "covered_count": strict_covered_count,
                    "chain_hash": strict_chain_hash,
                }
            )

    if abstract_counts.get("missing"):
        warnings.append(f"{abstract_counts['missing']} zet(s) have no explicit or compatibility abstract field.")
    if abstract_counts.get("frontmatter_unreadable"):
        warnings.append(f"{abstract_counts['frontmatter_unreadable']} zet(s) have unreadable frontmatter.")
    if identity_coverage["duplicate_id_entry_count"]:
        warnings.append(
            f"{identity_coverage['duplicate_id_entry_count']} zet file(s) share duplicate frontmatter ids."
        )
    if identity_coverage["unaddressable_entry_count"]:
        warnings.append(
            f"{identity_coverage['unaddressable_entry_count']} zet file(s) lack a readable safe frontmatter id."
        )
    if single_item_exceeds_token_budget:
        warnings.append("One catalog item exceeds the effective items token budget by itself and was returned to preserve progress.")
    if (
        max_estimated_tokens is not None
        and response_envelope_reserve_tokens >= max_estimated_tokens
    ):
        warnings.append(
            "The response envelope reserve leaves no positive items budget; one item is still allowed to preserve progress."
        )

    workload_estimate = {
        "method": "unicode_character_count_divided_by_4_heuristic",
        "provider_reported": False,
        "includes_response_envelope": False,
        "includes_zet_bodies": False,
        "scope": scope_workload_estimate,
        "page": zet_catalog_workload_estimate(page_items),
    }

    next_safe_actions = []
    if blockers:
        next_safe_actions.append("Restart the catalog from cursor 0 and use the newly returned snapshot id.")
    elif next_cursor is not None:
        if coverage_mode == "strict":
            next_safe_actions.append(
                "Continue with next_cursor, snapshot.id, and the returned coverage.continuation_token."
            )
        else:
            next_safe_actions.append(
                f"Continue with --cursor {next_cursor} --expected-snapshot-id {snapshot['id']}."
            )
    else:
        next_safe_actions.append("Catalog coverage is complete for the declared status filter and snapshot.")
        if not abstract_coverage["all_required_first_reads_available"]:
            next_safe_actions.append(
                "Report missing or unreadable first-read text as an abstract gap; do not claim that every abstract was read or auto-write replacements."
            )
            next_safe_actions.append(
                "For a selected missing-abstract zet, read its canonical body and integrity.file_sha256 with read-zettel, prepare a private .wom-scratch/abstract-backfill proposal row, run zet-abstract-backfill-plan, require human review, then preview and explicitly approve zet-abstract-backfill-write with the exact proposal SHA-256; never infer approval."
            )
        if not identity_coverage["all_entries_uniquely_addressable"]:
            next_safe_actions.append(
                "Resolve duplicate, missing, or unsafe zet ids before relying on id-only follow-up body reads."
            )

    result = {
        "ok": not blockers,
        "dry_run": bool(dry_run),
        "lifecycle_action": "zet_catalog",
        "schema": ZET_CATALOG_SCHEMA,
        "archive_id": archive_id,
        "status_filter": status,
        "projection": projection,
        "response_profile": response_profile,
        "order": order_descriptor,
        "order_evidence": order_evidence,
        "snapshot": snapshot,
        "coverage": {
            "cursor": cursor,
            "mode": coverage_mode,
            "page_size": page_size,
            "max_estimated_tokens": max_estimated_tokens,
            "response_envelope_reserve_tokens": response_envelope_reserve_tokens,
            "effective_items_token_budget": effective_items_token_budget,
            "stopped_for_token_budget": stopped_for_token_budget,
            "single_item_exceeds_token_budget": single_item_exceeds_token_budget,
            "total_count": total_count,
            "returned_count": returned_count,
            "remaining_count": remaining_count,
            "next_cursor": next_cursor,
            "complete": complete,
            "truncated": not complete,
            "contiguous_prefix_verified": strict_contiguous_prefix_verified,
            "covered_count": strict_covered_count,
            "continuation_token": strict_continuation_token,
            "chain_hash": strict_chain_hash,
            "page_entry_identity_sha256": page_entry_identity_sha256,
            "archive_wide_coverage_claim_ready": archive_wide_coverage_claim_ready,
            "archive_wide_abstract_reading_claim_ready": archive_wide_abstract_reading_claim_ready,
            "archive_wide_followup_resolution_ready": archive_wide_followup_resolution_ready,
        },
        "continuation_contract": {
            "schema": ZET_CATALOG_CONTINUATION_SCHEMA,
            "stateless": True,
            "checksum_validated": isinstance(continuation_payload, dict),
            "entry_identity_basis": ZET_CATALOG_ENTRY_IDENTITY_BASIS,
            "duplicate_ids_distinguished_in_chain": True,
            "entry_identity_values_echoed": False,
            "response_profile_bound": False,
            "response_profile_may_change_between_pages": True,
            "cryptographic_attestation": False,
            "persistent_loop_state_created": False,
        },
        "abstract_counts": abstract_counts,
        "abstract_coverage": abstract_coverage,
        "identity_coverage": identity_coverage,
        "workload_estimate": workload_estimate,
        "scan": scan,
        "session_consistency": {
            "mode": (
                "materialized_snapshot_with_completion_revalidation"
                if materialize_session_snapshot
                else "live_verify_every_page"
            ),
            "materialized_snapshot_reused": materialized_snapshot_reused,
            "completion_revalidation_required": bool(materialize_session_snapshot),
            "completion_revalidation_performed": completion_revalidation_performed,
            "changed_snapshot_blocks_completion": True,
        },
        "items": page_items,
        "privacy_guards": {
            "zettel_body_text_read": False,
            "zettel_body_text_echoed": False,
            "object_file_bytes_read": False,
            "provider_api_called": False,
            "secrets_read": False,
            "absolute_local_paths_echoed": False,
            "writes": False,
        },
        "closed_actions": {
            "goal_or_loop_created": False,
            "coverage_state_persisted": False,
            "generated_index_required": False,
            "files_written": False,
        },
        "next_safe_actions": next_safe_actions,
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
    }
    if response_profile == "continuation":
        omitted_sections = [
            "abstract_counts",
            "abstract_coverage",
            "identity_coverage",
            "order_evidence",
            "scan",
            "closed_actions",
            "workload_estimate.scope",
        ]
        for key in (
            "abstract_counts",
            "abstract_coverage",
            "identity_coverage",
            "order_evidence",
            "scan",
            "closed_actions",
        ):
            result.pop(key, None)
        continuation_workload = dict(result["workload_estimate"])
        continuation_workload.pop("scope", None)
        continuation_workload["scope_omitted_in_continuation_profile"] = True
        result["workload_estimate"] = continuation_workload
        result["response_profile_contract"] = {
            "schema": "wom-kit/zet-catalog-response-profile/v0.1",
            "first_page_full_required": True,
            "continuation_cursor_required": True,
            "items_unchanged": True,
            "coverage_semantics_unchanged": True,
            "snapshot_and_token_retained": True,
            "omitted_repeated_sections": omitted_sections,
        }
    provisional_response_measurement = zet_catalog_response_measurement(result)
    response_budget_active = bool(response_envelope_reserve_tokens and max_estimated_tokens is not None)
    estimated_response_tokens = provisional_response_measurement["estimated_service_result_json_tokens"]
    if response_budget_active and estimated_response_tokens > int(max_estimated_tokens or 0):
        result["warnings"] = unique_preserve_order(
            [
                *result["warnings"],
                "The measured compact service-result estimate exceeds max_estimated_tokens; increase response_envelope_reserve_tokens or the total host budget.",
            ]
        )
        result["next_safe_actions"] = unique_preserve_order(
            [
                *result["next_safe_actions"],
                "Use the measured response envelope estimate to reserve more tokens on the next page; never drop nodes to fit the context.",
            ]
        )
    response_measurement = zet_catalog_response_measurement(result)
    response_measurement["budget"] = {
        "reserve_active": response_budget_active,
        "requested_total_estimated_tokens": max_estimated_tokens if response_budget_active else None,
        "response_envelope_reserve_tokens": response_envelope_reserve_tokens,
        "effective_items_token_budget": effective_items_token_budget,
        "estimated_total_within_requested_budget": (
            response_measurement["estimated_service_result_json_tokens"] <= int(max_estimated_tokens or 0)
            if response_budget_active
            else None
        ),
        "reserve_covers_measured_envelope": (
            response_envelope_reserve_tokens >= response_measurement["estimated_response_envelope_tokens"]
            if response_budget_active
            else None
        ),
    }
    result["workload_estimate"]["response"] = response_measurement
    if progress_callback is not None:
        progress_callback("catalog-page", "done", next_cursor_value, total_count)
    return result


def resolve_zet_revision_proposal_path(root: Path, raw_path: str) -> Path:
    try:
        normalized = normalize_archive_relative_path(raw_path)
    except ArchivePathError as exc:
        raise ArchiveServiceError("Zet revision proposal path must be archive-relative.") from exc
    if not normalized.startswith(ZET_REVISION_PROPOSAL_PREFIX) or PurePosixPath(
        normalized
    ).suffix.lower() != ".md":
        raise ArchiveServiceError(
            f"Zet revision proposal must be a Markdown file under {ZET_REVISION_PROPOSAL_PREFIX}"
        )
    lexical_path = root.joinpath(*PurePosixPath(normalized).parts)
    if zet_revision_path_has_symlink_component(root, lexical_path):
        raise ArchiveServiceError(
            "Zet revision proposal paths must not contain symbolic links or reparse points."
        )
    path = resolve_archive_relative_path(root, normalized)
    if (
        path.is_symlink()
        or zet_revision_path_has_symlink_component(root, path)
        or not path.is_file()
    ):
        raise ArchiveServiceError("Zet revision proposal must be an existing regular file.")
    return path


def resolve_zet_revision_restore_proposal_path(root: Path, raw_path: str) -> Path:
    try:
        normalized = normalize_archive_relative_path(raw_path)
    except ArchivePathError as exc:
        raise ArchiveServiceError(
            "Zet revision restore proposal path must be archive-relative."
        ) from exc
    if not normalized.startswith(
        ZET_REVISION_RESTORE_PROPOSAL_PREFIX
    ) or PurePosixPath(normalized).suffix.lower() != ".md":
        raise ArchiveServiceError(
            "Zet revision restore proposal must be a Markdown file under the private restore scratch folder."
        )
    lexical_path = root.joinpath(*PurePosixPath(normalized).parts)
    if zet_revision_path_has_symlink_component(root, lexical_path):
        raise ArchiveServiceError(
            "Zet revision restore proposal paths must not contain symbolic links or reparse points."
        )
    path = resolve_archive_relative_path(root, normalized)
    if (
        path.is_symlink()
        or zet_revision_path_has_symlink_component(root, path)
        or not path.is_file()
    ):
        raise ArchiveServiceError(
            "Zet revision restore proposal must be an existing regular file."
        )
    return path


def resolve_zet_revision_restore_receipt_path(root: Path, raw_path: str) -> Path:
    try:
        normalized = normalize_archive_relative_path(raw_path)
    except ArchivePathError as exc:
        raise ArchiveServiceError(
            "Zet revision restore receipt path must be archive-relative."
        ) from exc
    normalized_path = PurePosixPath(normalized)
    if (
        normalized_path.parent.as_posix() != ZET_REVISION_RECEIPTS_DIR
        or not normalized_path.name.endswith(".zet-revision.json")
    ):
        raise ArchiveServiceError(
            "Zet revision restore receipt must be a canonical revision receipt."
        )
    lexical_path = root.joinpath(*normalized_path.parts)
    if zet_revision_path_has_symlink_component(root, lexical_path):
        raise ArchiveServiceError(
            "Zet revision restore receipt paths must not contain symbolic links or reparse points."
        )
    path = resolve_archive_relative_path(root, normalized)
    if (
        path.is_symlink()
        or zet_revision_path_has_symlink_component(root, path)
        or not path.is_file()
    ):
        raise ArchiveServiceError(
            "Zet revision restore receipt must be an existing regular file."
        )
    return path


def read_zet_revision_file_bytes(path: Path, label: str) -> bytes:
    try:
        size = path.stat().st_size
    except OSError as exc:
        raise ArchiveServiceError(f"{label} is unavailable.") from exc
    if size > ZET_REVISION_MAX_FILE_BYTES:
        raise ArchiveServiceError(f"{label} exceeds the 16 MiB revision safety limit.")
    try:
        with path.open("rb") as handle:
            value = handle.read(ZET_REVISION_MAX_FILE_BYTES + 1)
    except OSError as exc:
        raise ArchiveServiceError(f"{label} is unavailable.") from exc
    if len(value) > ZET_REVISION_MAX_FILE_BYTES:
        raise ArchiveServiceError(f"{label} exceeds the 16 MiB revision safety limit.")
    return value


def validated_zet_revision_snapshot(
    path: Path,
    *,
    expected_zettel_id: str,
    expected_archive_id: str,
) -> dict[str, Any]:
    """Validate one canonical revision participant before deriving evidence."""
    return validated_approval_zettel_snapshot(
        path,
        max_bytes=ZET_REVISION_MAX_FILE_BYTES,
        expected_zettel_id=expected_zettel_id,
        expected_archive_id=expected_archive_id,
        expected_status="canonical",
    )


def resolve_zet_revision_canonical_candidate(root: Path, zettel_id: str) -> Path:
    """Locate the direct canonical path without trusting its frontmatter first."""
    direct = root / "zettels" / f"{zettel_id}.md"
    if os.path.lexists(direct):
        return direct
    return resolve_zettel_path(root, zettel_id=zettel_id, relative_path=None)


def zet_revision_snapshot_blockers(
    snapshot: dict[str, Any],
    *,
    identity_code: str,
    archive_identity_code: str,
    status_code: str,
) -> list[str]:
    """Translate shared boundary issues without exposing rejected content."""
    translated: list[str] = []
    for raw_issue in snapshot.get("issue_codes", []):
        issue = str(raw_issue)
        if issue in {"frontmatter_identity_invalid", "frontmatter_identity_mismatch"}:
            translated.append(identity_code)
        elif issue == "frontmatter_archive_identity_mismatch":
            translated.append(archive_identity_code)
        elif issue in {"frontmatter_status_invalid", "frontmatter_status_mismatch"}:
            translated.append(status_code)
        else:
            translated.append(issue)
    return unique_preserve_order(translated)


def zet_revision_state_from_validated_snapshot(
    snapshot: dict[str, Any],
) -> dict[str, Any]:
    """Derive revision fingerprints only from an approved immutable snapshot."""
    if snapshot.get("ok") is not True or not isinstance(snapshot.get("bytes"), bytes):
        raise ArchiveServiceError("revision_zettel_snapshot_not_validated")
    frontmatter = snapshot["frontmatter"]
    body = snapshot["body"]
    raw_bytes = snapshot["bytes"]
    first_read = explicit_abstract_publication_check(frontmatter)
    return {
        "file_sha256": "sha256:" + hashlib.sha256(raw_bytes).hexdigest(),
        "semantic_sha256": zet_revision_semantic_sha256(frontmatter, body),
        "abstract_sha256": (
            first_read.get("abstract_sha256")
            if first_read.get("ready_for_publication")
            else None
        ),
        "body_sha256": canonical_body_sha256(canonical_publication_body(body)),
    }


