def _source_fidelity_frontmatter_authority_sha256(
    frontmatter: dict[str, Any],
) -> str:
    # These two fields contain the plan itself and its approval projection, so
    # including them would make the digest recursive. Every other frontmatter
    # field belongs to the exact reviewed candidate authority.
    selected = {
        key: value
        for key, value in frontmatter.items()
        if key not in {"draft_creation", "source_fidelity"}
    }
    return _source_fidelity_digest_json(
        {
            "schema": "wom-kit/source-fidelity-frontmatter-authority/v0.1",
            "frontmatter": selected,
            "excluded_recursive_fields": [
                "draft_creation",
                "source_fidelity",
            ],
        }
    )


def _source_fidelity_plan_sha256(
    *,
    archive_id: str,
    archive_type: str | None,
    draft_id: str,
    draft_path: str,
    created_at: str,
    creation_mode: str,
    fidelity: dict[str, Any],
    final_body_sha256: str,
    region: dict[str, Any] | None,
    frontmatter: dict[str, Any],
    frontmatter_authority_sha256: str | None = None,
) -> str:
    fidelity_authority = {
        key: value
        for key, value in fidelity.items()
        if key != "creation_plan_sha256"
    }
    fidelity_schema = fidelity.get("schema")
    if fidelity_schema not in {
        SOURCE_FIDELITY_SCHEMA_V1,
        SOURCE_FIDELITY_SCHEMA_V2,
    }:
        fidelity_schema = SOURCE_FIDELITY_SCHEMA
    authority = {
        "schema": fidelity_schema,
        "archive_id": archive_id,
        "archive_type": archive_type,
        "draft_id": draft_id,
        "draft_path": draft_path,
        "created_at": created_at,
        "creation_mode": creation_mode,
        "source_fidelity": json_safe(fidelity_authority),
        "final_body_sha256": final_body_sha256,
        "region": json_safe(region) if isinstance(region, dict) else None,
        "frontmatter_authority_sha256": (
            frontmatter_authority_sha256
            or _source_fidelity_frontmatter_authority_sha256(frontmatter)
        ),
    }
    return _source_fidelity_digest_json(authority)


def _source_fidelity_review_binding_sha256(
    *,
    archive_id: str,
    draft_id: str,
    draft_path: str,
    body_sha256: str,
    source_fidelity_plan_sha256: str,
    reviewed_by: str,
) -> str:
    return _source_fidelity_digest_json(
        {
            "schema": SOURCE_FIDELITY_REVIEW_BINDING_SCHEMA,
            "archive_id": archive_id,
            "draft_id": draft_id,
            "draft_path": draft_path,
            "body_sha256": body_sha256,
            "source_fidelity_plan_sha256": (
                source_fidelity_plan_sha256
            ),
            "reviewed_by": reviewed_by,
        }
    )


def _source_fidelity_safe_projection(
    fidelity: dict[str, Any] | None,
    *,
    review_state: str | None = None,
    publication_plan_sha256: str | None = None,
    publication_reviewed_by: str | None = None,
    publication_reviewed_at: str | None = None,
) -> dict[str, Any] | None:
    """Project fidelity state without any private objet identity or digest."""

    if not isinstance(fidelity, dict):
        return None
    fidelity_schema = fidelity.get("schema")
    if fidelity_schema not in {
        SOURCE_FIDELITY_SCHEMA_V1,
        SOURCE_FIDELITY_SCHEMA_V2,
    }:
        fidelity_schema = SOURCE_FIDELITY_SCHEMA
    source = fidelity.get("source") if isinstance(fidelity.get("source"), dict) else {}
    authority_kind = source.get("authority_kind") or "manifested_object"
    provenance = source.get("provenance") if isinstance(source.get("provenance"), dict) else {}
    authority_binding_state = (
        "reviewed_session_evidence"
        if authority_kind == "reviewed_session_evidence"
        else provenance.get("binding_state") or "legacy_unbound"
    )
    projection: dict[str, Any] = {
        "schema": fidelity_schema,
        "mode": fidelity.get("mode"),
        "audience": fidelity.get("audience"),
        "comparison_basis": SOURCE_FIDELITY_COMPARISON_BASIS,
        "evidence_id": fidelity.get("evidence_id"),
        "creation_plan_sha256": fidelity.get("creation_plan_sha256"),
        "byte_exact": False,
        "mechanically_verified": fidelity.get("mechanically_verified") is True,
        "semantic_fidelity_machine_verified": False,
        "human_review_required": True,
        "source_changed": False,
        "share_performed": False,
        "private_source_authority_stored_in_frontmatter": False,
        "source_text_stored": False,
        "source_locator_stored": False,
    }
    if fidelity_schema == SOURCE_FIDELITY_SCHEMA_V2:
        projection.update(
            {
                "authority_kind": authority_kind,
                "authority_binding_state": authority_binding_state,
                "source_role": (
                    source.get("source_role")
                    if authority_kind == "reviewed_session_evidence"
                    else provenance.get("source_role")
                ),
            }
        )
    if review_state:
        projection["review_state"] = review_state
    if publication_plan_sha256:
        projection["publication_plan_sha256"] = publication_plan_sha256
    if publication_reviewed_by:
        projection["publication_reviewed_by"] = publication_reviewed_by
    if publication_reviewed_at:
        projection["publication_reviewed_at"] = publication_reviewed_at
    return projection


def _source_fidelity_private_visibility_valid(value: Any) -> bool:
    return bool(
        isinstance(value, dict)
        and value.get("scope") == "private"
        and value.get("source_visibility") == "private"
        and isinstance(value.get("allowed_archives"), list)
        and not value.get("allowed_archives")
    )


def _source_fidelity_prepare_candidate(
    root: Path,
    *,
    archive_type: str | None,
    context_body: str,
    mode_value: Any,
    audience_value: Any,
    object_id_value: Any,
    session_evidence_id_value: Any,
    candidate_created_at: str,
    local_ai_sessions: Any,
) -> tuple[bytes, dict[str, Any] | None, list[str]]:
    blockers: list[str] = []
    mode = str(mode_value or "").strip()
    audience = str(audience_value or "").strip()
    if mode not in SOURCE_FIDELITY_MODES:
        blockers.append("source_fidelity_mode_required_or_invalid")
    if audience not in ZET_QUALITY_AUDIENCES:
        blockers.append("source_fidelity_audience_required_or_invalid")
    if mode == "verbatim" and (
        archive_type != "personal" or audience != "private_self"
    ):
        blockers.append("verbatim_requires_personal_private_self")

    object_authority_supplied = bool(str(object_id_value or "").strip())
    session_authority_supplied = bool(
        str(session_evidence_id_value or "").strip()
    )
    source: dict[str, Any] | None = None
    normalized_source: bytes | None = None
    source_blockers: list[str] = []
    if object_authority_supplied == session_authority_supplied:
        source_blockers.append(
            "source_fidelity_exactly_one_authority_required"
        )
    elif object_authority_supplied:
        source, normalized_source, source_blockers = (
            _source_fidelity_read_manifested_object(root, object_id_value)
        )
    else:
        source, normalized_source, source_blockers = (
            _read_verified_session_evidence(
                root, session_evidence_id_value
            )
        )
    blockers.extend(source_blockers)
    source_has_reviewable_text = bool(
        normalized_source is not None
        and normalized_source.decode("utf-8").lstrip("\ufeff").strip()
    )
    if normalized_source is not None and not source_has_reviewable_text:
        blockers.append(
            "source_fidelity_source_must_contain_non_whitespace_text"
        )
    context = (
        normalize_draft_body(context_body).encode("utf-8")
        if context_body
        else b""
    )
    region: dict[str, Any] | None = None
    candidate = context
    if mode == "verbatim" and normalized_source is not None:
        region = {
            "offset_bytes": len(context),
            "length_bytes": len(normalized_source),
            "sha256": _source_fidelity_digest_bytes(normalized_source),
        }
        candidate = context + normalized_source
    if isinstance(source, dict) and normalized_source is not None:
        exact_full_candidate = hmac.compare_digest(
            candidate, normalized_source
        )
        authority_kind = source.get("authority_kind")
        if authority_kind == "reviewed_session_evidence":
            source_role = source.get("source_role")
            producer_kind = source.get("producer_kind")
            local_session_hashes = {
                "sha256:"
                + _source_fidelity_digest_bytes(
                    str(item.get("session_ref") or "").encode("utf-8")
                )
                for item in (
                    local_ai_sessions
                    if isinstance(local_ai_sessions, list)
                    else []
                )
                if isinstance(item, dict)
                and isinstance(item.get("session_ref"), str)
                and item.get("session_ref")
            }
            same_session = source.get("session_ref_sha256") in local_session_hashes
            produced_at = normalize_zet_revision_timestamp(
                source.get("produced_at")
                if isinstance(source.get("produced_at"), str)
                else None,
                default_now=False,
            )
            created_at_normalized = normalize_zet_revision_timestamp(
                candidate_created_at, default_now=False
            )
            produced_after_candidate = bool(
                produced_at
                and created_at_normalized
                and produced_at >= created_at_normalized
            )
            if source_role == "self_authored_candidate" or (
                exact_full_candidate
                and producer_kind == "ai_runtime"
                and (same_session or produced_after_candidate)
            ):
                blockers.append("circular_self_source")
        elif authority_kind == "manifested_object":
            provenance = (
                source.get("provenance")
                if isinstance(source.get("provenance"), dict)
                else {}
            )
            captured_at = normalize_zet_revision_timestamp(
                provenance.get("captured_at")
                if isinstance(provenance.get("captured_at"), str)
                else None,
                default_now=False,
            )
            created_at_normalized = normalize_zet_revision_timestamp(
                candidate_created_at, default_now=False
            )
            if (
                captured_at
                and created_at_normalized
                and captured_at > created_at_normalized
            ):
                blockers.append(
                    "source_fidelity_object_temporal_order_invalid"
                )
            circular_positive_evidence = bool(
                exact_full_candidate
                and not provenance.get("independent_external_provenance")
                and (
                    provenance.get("source_role") == "derived_context"
                    or provenance.get("staged_source_class")
                    == "archive_ai_scratch"
                )
            )
            if circular_positive_evidence:
                blockers.append("circular_self_source")
    if "credential_secret_present" in (
        _source_fidelity_request_metadata_blockers(
            candidate.decode("utf-8", errors="ignore")
        )
    ):
        blockers.append("credential_secret_present")
    if source is None:
        return candidate, None, unique_preserve_order(blockers)

    mechanically_verified = (
        mode == "verbatim"
        and not source_blockers
        and source_has_reviewable_text
        and "circular_self_source" not in blockers
    )
    authority_kind = source.get("authority_kind")
    fidelity_schema = (
        SOURCE_FIDELITY_SCHEMA_V2
        if authority_kind == "reviewed_session_evidence"
        else SOURCE_FIDELITY_SCHEMA_V1
    )
    receipt_source = (
        source
        if fidelity_schema == SOURCE_FIDELITY_SCHEMA_V2
        else {
            key: value
            for key, value in source.items()
            if key not in {"authority_kind", "provenance"}
        }
    )
    fidelity = {
        "schema": fidelity_schema,
        "mode": mode,
        "audience": audience,
        "comparison_basis": SOURCE_FIDELITY_COMPARISON_BASIS,
        "source": receipt_source,
        "region": region,
        "byte_exact": False,
        "mechanically_verified": mechanically_verified,
        "semantic_fidelity_machine_verified": False,
        "human_review_required": True,
        "source_changed": False,
        "share_performed": False,
        "source_text_stored": False,
        "source_locator_stored": False,
    }
    fidelity["evidence_id"] = (
        "source-fidelity-evidence:"
        + _source_fidelity_digest_json(
            {
                "source": receipt_source,
                "region": region,
                "mode": mode,
                "audience": audience,
                "comparison_basis": SOURCE_FIDELITY_COMPARISON_BASIS,
            }
        )[:24]
    )
    return candidate, fidelity, unique_preserve_order(blockers)


def _source_fidelity_draft_receipt(
    *,
    archive_id: str,
    archive_type: str | None,
    draft_id: str,
    draft_path: str,
    body_sha256: str,
    creation_mode: str,
    frontmatter_authority_sha256: str,
    reviewed_by: str,
    review_binding_sha256: str,
    candidate_created_at: str,
    fidelity: dict[str, Any],
    plan_sha256: str,
) -> dict[str, Any]:
    receipt_schema = (
        SOURCE_FIDELITY_DRAFT_RECEIPT_SCHEMA_V2
        if fidelity.get("schema") == SOURCE_FIDELITY_SCHEMA_V2
        else SOURCE_FIDELITY_DRAFT_RECEIPT_SCHEMA_V1
    )
    return {
        "schema": receipt_schema,
        "action": "create_source_fidelity_draft",
        "archive_id": archive_id,
        "archive_type": archive_type,
        "draft_id": draft_id,
        "draft_path": draft_path,
        "body_sha256": body_sha256,
        "creation_mode": creation_mode,
        "frontmatter_authority_sha256": frontmatter_authority_sha256,
        "source_fidelity_plan_sha256": plan_sha256,
        "reviewed_by": reviewed_by,
        "review_binding_sha256": review_binding_sha256,
        "candidate_created_at": candidate_created_at,
        "source_fidelity": json_safe(fidelity),
        "content_contract": {
            "source_text_stored": False,
            "source_locator_stored": False,
            "source_path_stored": False,
        },
        "result": {
            "draft_written_create_only": True,
            "receipt_written_create_only": True,
            "source_changed": False,
            "share_performed": False,
        },
    }


def _source_fidelity_existing_state(
    root: Path,
    path: Path,
    expected: bytes,
) -> str:
    try:
        bound_root, bound_path = _source_fidelity_bound_root_and_path(
            root, path
        )
        with _hold_activity_group_evidence_file(
            bound_root,
            bound_path,
            max_bytes=max(len(expected), 1),
        ) as snapshot:
            actual = snapshot["raw"]
    except FileNotFoundError:
        return "absent"
    except OSError:
        return "absent" if not path.exists() else "conflict"
    return "exact" if hmac.compare_digest(actual, expected) else "conflict"


def _source_fidelity_publish_create_only(
    root: Path,
    path: Path,
    expected: bytes,
    *,
    conflict_code: str,
) -> bool:
    state = _source_fidelity_existing_state(root, path, expected)
    if state == "exact":
        return False
    if state == "conflict":
        raise ArchiveServiceError(conflict_code)
    # Bind and, when needed, create every parent component from the archive
    # root outward.  Calling mkdir(parents=True) before this check could follow
    # a junction/reparse point and mutate a location outside the archive.
    try:
        bound_root, bound_path = _source_fidelity_bound_root_and_path(
            root, path
        )
        with _activity_group_bound_directory_chain(
            bound_root,
            bound_path.parent,
            create=True,
        ):
            if zet_revision_path_has_symlink_component(
                bound_root, bound_path.parent
            ):
                raise ArchiveServiceError(conflict_code)
            try:
                _write_bytes_create_if_absent(bound_path, expected)
            except FileExistsError:
                if (
                    _source_fidelity_existing_state(
                        bound_root, bound_path, expected
                    )
                    == "exact"
                ):
                    return False
                raise ArchiveServiceError(conflict_code) from None
            if (
                zet_revision_path_has_symlink_component(
                    bound_root, bound_path
                )
                or _source_fidelity_existing_state(
                    bound_root, bound_path, expected
                )
                != "exact"
            ):
                raise ArchiveServiceError(conflict_code)
    except ArchiveServiceError:
        raise
    except OSError as exc:
        raise ArchiveServiceError(conflict_code) from exc
    return True


def create_draft_zettel(
    archive_root: Path | str,
    *,
    title: str,
    body: str,
    abstract: str | None = None,
    archive_id: str | None = None,
    kind: str = "fleeting_capture",
    facets: dict[str, Any] | None = None,
    visibility: dict[str, Any] | None = None,
    created_by: str = "cli:archive",
    source: str = "cli_command",
    dry_run: bool = False,
    expected_archive_id: str | None = None,
    expected_type: str | None = None,
    profile_id: str | None = None,
    profile_operator_id: str | None = None,
    profile_authority_mode: str | None = None,
    creation_mode: str | None = None,
    assisted_by: list[str] | None = None,
    supervised_by: list[str] | None = None,
    derived_from: list[str] | None = None,
    source_refs: list[dict[str, Any]] | None = None,
    source_intake_plan: dict[str, Any] | None = None,
    prompt_boundary_report: dict[str, Any] | None = None,
    local_ai_sessions: list[dict[str, Any]] | None = None,
    draft_id: str | None = None,
    created_at: str | None = None,
    expected_body_sha256: str | None = None,
    draft_approved_by: str | None = None,
    approved: bool = False,
    source_fidelity_mode: str | None = None,
    source_fidelity_audience: str | None = None,
    fidelity_source_object_id: str | None = None,
    fidelity_session_evidence_id: str | None = None,
    expected_source_fidelity_plan_sha256: str | None = None,
    exact_human_approval_claim: _ClaimedExactHumanApproval | None = None,
) -> dict[str, Any]:
    ai_request_declared = _source_fidelity_ai_provenance_declared(
        creation_mode=creation_mode,
        created_by=created_by,
        assisted_by=assisted_by,
        local_ai_sessions=local_ai_sessions,
    )
    if not dry_run and not (
        approved
        and ai_request_declared
        and type(exact_human_approval_claim) is _ClaimedExactHumanApproval
    ):
        return _compound_exact_human_approval_blocked(
            lifecycle_action="create_draft",
        )
    require_yaml()
    root = require_existing_archive_root(archive_root)
    archive_config = read_archive_config(root)
    if not title:
        raise ArchiveServiceError("title is required.")
    if body is None:
        body = ""
    blockers: list[str] = []
    warnings: list[str] = []
    if approved and not ai_request_declared:
        blockers.append("create_draft_non_ai_approve_forbidden")
    request_metadata_blockers = (
        _source_fidelity_request_metadata_blockers(
            {
                "title": title,
                "body": body,
                "abstract": abstract,
                "archive_id": archive_id,
                "kind": kind,
                "facets": facets,
                "visibility": visibility,
                "created_by": created_by,
                "source": source,
                "expected_archive_id": expected_archive_id,
                "expected_type": expected_type,
                "profile_id": profile_id,
                "profile_operator_id": profile_operator_id,
                "profile_authority_mode": profile_authority_mode,
                "creation_mode": creation_mode,
                "assisted_by": assisted_by,
                "supervised_by": supervised_by,
                "derived_from": derived_from,
                "source_refs": source_refs,
                "source_intake_plan": source_intake_plan,
                "prompt_boundary_report": prompt_boundary_report,
                "local_ai_sessions": local_ai_sessions,
                "draft_id": draft_id,
                "created_at": created_at,
                "expected_body_sha256": expected_body_sha256,
                "draft_approved_by": draft_approved_by,
                "source_fidelity_mode": source_fidelity_mode,
                "source_fidelity_audience": source_fidelity_audience,
                "fidelity_source_object_id": fidelity_source_object_id,
                "fidelity_session_evidence_id": (
                    fidelity_session_evidence_id
                ),
                "expected_source_fidelity_plan_sha256": (
                    expected_source_fidelity_plan_sha256
                ),
            }
        )
        if ai_request_declared
        else []
    )
    if request_metadata_blockers:
        if dry_run:
            return _source_fidelity_content_free_blocked_preview(
                request_metadata_blockers
            )
        raise ArchiveServiceError(
            "Draft creation blocked: "
            + "; ".join(request_metadata_blockers)
        )
    if not body.strip() and source_fidelity_mode != "verbatim":
        blockers.append("body is required and must contain non-whitespace text.")

    normalized_abstract: str | None = None
    if abstract is not None:
        normalized_abstract = re.sub(r"\s+", " ", abstract).strip()
        if not normalized_abstract:
            blockers.append("abstract must contain non-whitespace text when provided.")
        elif len(normalized_abstract) > ZET_ABSTRACT_MAX_CHARS:
            blockers.append(f"abstract must be at most {ZET_ABSTRACT_MAX_CHARS} characters.")
        elif (
            header_string_is_private_or_unsafe(normalized_abstract)
            or source_intake_has_provider_url(normalized_abstract)
            or source_intake_secret_like(normalized_abstract)
        ):
            blockers.append("abstract appears to contain a private locator, local path, account identifier, or secret-like value.")

    resolved_archive_id = archive_id or str(archive_config.get("archive_id") or "")
    archive_type = archive_config.get("type") if isinstance(archive_config.get("type"), str) else None
    if not resolved_archive_id:
        blockers.append("archive.yml does not contain archive_id and archive_id was not provided.")
    if expected_archive_id and expected_archive_id != resolved_archive_id:
        blockers.append(
            "expected_archive_id_mismatch"
            if ai_request_declared
            else f"Expected archive id mismatch: expected {expected_archive_id}, found {resolved_archive_id}."
        )
    if expected_type and expected_type != archive_type:
        blockers.append(
            "expected_archive_type_mismatch"
            if ai_request_declared
            else f"Expected archive type mismatch: expected {expected_type}, found {archive_type or 'unknown'}."
        )

    if ai_request_declared and approved and not dry_run and (
        not isinstance(draft_id, str)
        or not draft_id.strip()
        or not isinstance(created_at, str)
        or not created_at.strip()
    ):
        blockers.append("create_draft_ai_replay_identity_required")

    now = (created_at or datetime.now().astimezone().replace(microsecond=0).isoformat()).strip()
    if not now:
        blockers.append("created_at must not be empty.")
        now = datetime.now().astimezone().replace(microsecond=0).isoformat()
    elif created_at and not valid_iso_timestamp(now):
        blockers.append("created_at must be an ISO 8601 timestamp.")

    if draft_id is not None:
        zettel_id = draft_id.strip()
        if not valid_draft_zettel_id(zettel_id):
            blockers.append("draft_id must be a safe zet id without path separators.")
    else:
        zettel_id = make_zettel_id(title, now)

    assisted = clean_optional_string_list(assisted_by)
    ai_provenance_declared = _source_fidelity_ai_provenance_declared(
        created_by=created_by,
        assisted_by=assisted,
        local_ai_sessions=local_ai_sessions,
    )
    is_ai_draft = _source_fidelity_ai_provenance_declared(
        creation_mode=creation_mode,
        created_by=created_by,
        assisted_by=assisted,
        local_ai_sessions=local_ai_sessions,
    )
    if ai_provenance_declared and creation_mode not in {
        "ai_assisted",
        "ai_generated",
    }:
        blockers.append("ai_provenance_requires_ai_creation_mode")
    source_fidelity: dict[str, Any] | None = None
    if is_ai_draft:
        candidate_body_bytes, source_fidelity, fidelity_blockers = (
            _source_fidelity_prepare_candidate(
                root,
                archive_type=archive_type,
                context_body=body,
                mode_value=source_fidelity_mode,
                audience_value=source_fidelity_audience,
                object_id_value=fidelity_source_object_id,
                session_evidence_id_value=fidelity_session_evidence_id,
                candidate_created_at=now,
                local_ai_sessions=local_ai_sessions,
            )
        )
        blockers.extend(fidelity_blockers)
        if "credential_secret_present" in fidelity_blockers:
            if dry_run:
                return _source_fidelity_content_free_blocked_preview(
                    ["credential_secret_present"]
                )
            raise ArchiveServiceError(
                "Draft creation blocked: credential_secret_present"
            )
    else:
        candidate_body_bytes = normalize_draft_body(body).encode("utf-8")
        if any(
            value is not None
            for value in (
                source_fidelity_mode,
                source_fidelity_audience,
                fidelity_source_object_id,
                fidelity_session_evidence_id,
                expected_source_fidelity_plan_sha256,
            )
        ):
            blockers.append("source_fidelity_only_valid_for_ai_drafts")
    normalized_body = candidate_body_bytes.decode("utf-8")
    if source_fidelity_mode == "verbatim" and not normalized_body.strip():
        blockers.append("verbatim_source_must_contain_non_whitespace_text")
    body_sha256 = _source_fidelity_digest_bytes(candidate_body_bytes)
    if expected_body_sha256:
        expected_hash = expected_body_sha256.strip().lower()
        if not SHA256_RE.match(expected_hash):
            blockers.append("expected_body_sha256 must be a 64-character lowercase hex SHA-256 value.")
        elif expected_hash != body_sha256:
            blockers.append("Expected body SHA-256 does not match the draft body.")

    if zettel_body_has_forbidden_location_reference(body):
        blockers.append("Draft body appears to contain a private provider locator or local absolute path.")
    if (
        DRAFT_SECRET_VALUE_RE.search(body)
        or _source_fidelity_sensitive_assignment_contains_secret(body)
    ):
        blockers.append("Draft body appears to contain a secret-like value.")

    if creation_mode:
        if creation_mode not in DRAFT_CREATION_MODES:
            blockers.append("creation_mode must be one of: " + ", ".join(sorted(DRAFT_CREATION_MODES)) + ".")

    if kind:
        valid_kinds = sorted(note_kind_rules(load_zettel_rules(root)).keys())
        if kind not in valid_kinds:
            warnings.append(
                f"Unknown note kind '{kind}'. Valid kinds in this archive's zettel-rules: "
                + ", ".join(valid_kinds)
                + ". The draft was created; mint will warn on this kind too."
            )

    if isinstance(facets, dict) and facets:
        vocabulary_result = facet_vocabulary(root, dry_run=True)
        known_facet_keys = {
            str(item.get("key"))
            for item in vocabulary_result.get("keys", [])
            if isinstance(item, dict) and isinstance(item.get("key"), str)
        }
        if any(
            str(key or "").strip().lower().replace("-", "_")
            not in known_facet_keys
            for key in facets
        ):
            warnings.append("unknown_facet_key_requires_human_review")

    supervised = clean_optional_string_list(supervised_by)
    explicit_derived = clean_optional_string_list(derived_from)
    source_intake = prepare_source_intake_plan_for_draft(source_intake_plan, blockers)
    prompt_boundary = prepare_prompt_boundary_report_for_draft(prompt_boundary_report, blockers, warnings)
    plan_profile_id = source_intake.get("profile_id")
    if not profile_id and isinstance(plan_profile_id, str):
        profile_id = plan_profile_id
    derived = merge_unique_strings(explicit_derived, source_intake.get("derived_from", []))
    explicit_refs = normalize_source_refs(source_refs or [], blockers)
    refs = [*explicit_refs, *source_intake.get("source_refs", [])]
    sessions = normalize_local_ai_sessions(local_ai_sessions or [], blockers)
    fidelity_source_object_id = None
    resolved_fidelity_session_evidence_id: str | None = None
    fidelity_private_authority_values: set[str] = set()
    if is_ai_draft and isinstance(source_fidelity, dict):
        fidelity_source = source_fidelity.get("source")
        fidelity_private_authority_values = (
            _source_fidelity_private_authority_values(fidelity_source)
        )
        if isinstance(fidelity_source, dict) and isinstance(
            fidelity_source.get("object_id"), str
        ):
            fidelity_source_object_id = fidelity_source["object_id"]
        if isinstance(fidelity_source, dict) and isinstance(
            fidelity_source.get("evidence_id"), str
        ):
            resolved_fidelity_session_evidence_id = fidelity_source[
                "evidence_id"
            ]
    if fidelity_source_object_id or resolved_fidelity_session_evidence_id:
        private_authority_refs = {
            value
            for value in {
                fidelity_source_object_id,
                (
                    f"objet:{fidelity_source_object_id}"
                    if fidelity_source_object_id
                    else None
                ),
                resolved_fidelity_session_evidence_id,
            }
            if isinstance(value, str) and value
        }
        refs = [
            ref
            for ref in refs
            if not (
                isinstance(ref, dict)
                and ref.get("value") in private_authority_refs
            )
        ]
        derived = [
            value
            for value in derived
            if value not in private_authority_refs
        ]
    validate_safe_draft_values(
        {
            "created_by": created_by,
            "source": source,
            "profile_id": profile_id,
            "profile_operator_id": profile_operator_id,
            "profile_authority_mode": profile_authority_mode,
            "assisted_by": assisted,
            "supervised_by": supervised,
            "derived_from": derived,
            "source_refs": refs,
            "local_ai_sessions": sessions,
            "draft_approved_by": draft_approved_by,
        },
        blockers,
    )

    profile_bound = any(
        value
        for value in [
            profile_id,
            profile_operator_id,
            profile_authority_mode,
            sessions,
        ]
    )
    if profile_bound and not dry_run:
        if not draft_approved_by:
            blockers.append("Profile-bound draft creation requires draft_approved_by.")
        if not expected_body_sha256:
            blockers.append("Profile-bound draft creation requires expected_body_sha256.")
    elif profile_bound and dry_run:
        if not draft_approved_by:
            warnings.append("Profile-bound write replay will require draft_approved_by.")
        if not expected_body_sha256:
            warnings.append("Profile-bound write replay will require expected_body_sha256.")

    if is_ai_draft:
        if not assisted:
            blockers.append("AI-assisted or AI-generated drafts must identify the assisting AI runtime.")
        if normalized_abstract is None:
            blockers.append(
                "AI-assisted or AI-generated drafts require an explicit abstract before creation."
            )
        if not isinstance(facets, dict) or not facets:
            blockers.append(
                "AI-assisted or AI-generated drafts require at least one stable facet before creation."
            )
        if not dry_run:
            if approved is not True:
                blockers.append("ai_draft_write_requires_approved")
            if not draft_approved_by:
                blockers.append("ai_draft_write_requires_reviewer")
            if not expected_body_sha256:
                blockers.append("ai_draft_write_requires_expected_body_sha256")
            if not expected_source_fidelity_plan_sha256:
                blockers.append(
                    "ai_draft_write_requires_expected_source_fidelity_plan_sha256"
                )
        else:
            if not draft_approved_by:
                warnings.append("AI draft write replay requires draft_approved_by.")
            if not expected_body_sha256:
                warnings.append("AI draft write replay requires expected_body_sha256.")
            if not expected_source_fidelity_plan_sha256:
                warnings.append(
                    "AI draft write replay requires expected_source_fidelity_plan_sha256."
                )

    frontmatter = {
        "id": zettel_id,
        "title": title,
        "created_at": now,
        "updated_at": now,
        "archive_id": resolved_archive_id,
        "status": "draft",
        "kind": kind or "fleeting_capture",
        "facets": facets or {},
        "assets": [],
        "edges": [],
        "provenance": {
            "created_by": created_by,
            "created_in": resolved_archive_id,
            "source": source,
            "derived_from": derived,
        },
        "visibility": visibility or default_private_visibility(),
        "promotion": {
            "stage": "captured",
            "ready_for_promotion": False,
        },
    }
    if (
        is_ai_draft
        and source_fidelity_mode == "verbatim"
        and not _source_fidelity_private_visibility_valid(
            frontmatter.get("visibility")
        )
    ):
        blockers.append("verbatim_requires_private_visibility")
    if normalized_abstract:
        frontmatter["abstract"] = normalized_abstract
    first_read_check = explicit_abstract_publication_check(frontmatter)
    if creation_mode:
        frontmatter["provenance"]["creation_mode"] = creation_mode
    if assisted:
        frontmatter["provenance"]["assisted_by"] = assisted
    if supervised:
        frontmatter["provenance"]["supervised_by"] = supervised
    if refs:
        frontmatter["source_refs"] = refs
    if source_intake.get("source_intake"):
        frontmatter["source_intake"] = source_intake["source_intake"]
    if prompt_boundary:
        frontmatter["prompt_boundary"] = prompt_boundary
    if sessions:
        frontmatter["local_ai_sessions"] = sessions
    frontmatter_serialized = json.dumps(
        json_safe(frontmatter),
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    frontmatter_credential_secret_present = bool(
        is_ai_draft
        and (
            SOURCE_FIDELITY_CREDENTIAL_SECRET_RE.search(
                frontmatter_serialized
            )
            or _source_fidelity_sensitive_assignment_contains_secret(
                frontmatter_serialized
            )
        )
    )
    frontmatter_private_authority_exposed = bool(
        fidelity_private_authority_values
        and _source_fidelity_value_contains_private_authority(
            {
                "frontmatter": frontmatter,
                "draft_approved_by": draft_approved_by,
                "expected_archive_id": expected_archive_id,
                "expected_type": expected_type,
                "profile_id": profile_id,
                "profile_operator_id": profile_operator_id,
                "profile_authority_mode": profile_authority_mode,
            },
            private_values=fidelity_private_authority_values,
        )
    )
    if frontmatter_credential_secret_present:
        blockers.append("credential_secret_present")
    if frontmatter_private_authority_exposed:
        blockers.append("source_fidelity_private_authority_exposed")
    if (
        frontmatter_credential_secret_present
        or frontmatter_private_authority_exposed
    ):
        fixed_reason_codes = []
        if frontmatter_credential_secret_present:
            fixed_reason_codes.append("credential_secret_present")
        if frontmatter_private_authority_exposed:
            fixed_reason_codes.append(
                "source_fidelity_private_authority_exposed"
            )
        if dry_run:
            return _source_fidelity_content_free_blocked_preview(
                fixed_reason_codes
            )
        raise ArchiveServiceError(
            "Draft creation blocked: " + "; ".join(fixed_reason_codes)
        )
    if (draft_approved_by or expected_body_sha256) and not is_ai_draft:
        frontmatter["draft_creation"] = {
            "approved_by": draft_approved_by,
            "approval_scope": "inbox_draft_only",
            "approved_body_sha256": expected_body_sha256.strip().lower() if expected_body_sha256 else None,
        }

    existing_draft_title_check = inbox_existing_draft_title_check(
        root,
        title,
    )
    inbox = archive_internal_path(root, "inbox")
    path = inbox / f"{zettel_id}.md"
    if draft_id is None and not dry_run and not is_ai_draft:
        suffix = 2
        base_zettel_id = zettel_id
        while path.exists():
            zettel_id = f"{base_zettel_id}_{suffix}"
            frontmatter["id"] = zettel_id
            path = inbox / f"{zettel_id}.md"
            suffix += 1
    elif path.exists() and not is_ai_draft:
        blockers.append(f"Proposed draft path already exists: inbox/{zettel_id}.md.")

    proposed_path = f"inbox/{zettel_id}.md"
    if not existing_draft_title_check["complete"]:
        blockers.append(
            "Existing inbox draft title check could not complete safely."
        )
    elif existing_draft_title_check["same_title_count"]:
        if is_ai_draft:
            if not (
                path.exists()
                and existing_draft_title_check["same_title_count"] == 1
            ):
                blockers.append(
                    "An unminted inbox draft with the same normalized title already exists; revise that draft in place instead of creating another one."
                )
        else:
            warnings.append(
                "One or more unminted inbox drafts have the same normalized title; review and revise an existing draft in place when they represent the same record."
            )

    source_fidelity_plan_sha256: str | None = None
    source_fidelity_frontmatter_authority_sha256: str | None = None
    source_fidelity_review_binding_sha256: str | None = None
    fidelity_receipt_relative: str | None = None
    fidelity_receipt_path: Path | None = None
    fidelity_receipt_bytes: bytes | None = None
    if is_ai_draft and source_fidelity is not None:
        source_fidelity_frontmatter_authority_sha256 = (
            _source_fidelity_frontmatter_authority_sha256(frontmatter)
        )
        source_fidelity_plan_sha256 = _source_fidelity_plan_sha256(
            archive_id=resolved_archive_id,
            archive_type=archive_type,
            draft_id=zettel_id,
            draft_path=proposed_path,
            created_at=now,
            creation_mode=str(creation_mode),
            fidelity=source_fidelity,
            final_body_sha256=body_sha256,
            region=(
                source_fidelity.get("region")
                if isinstance(source_fidelity.get("region"), dict)
                else None
            ),
            frontmatter=frontmatter,
            frontmatter_authority_sha256=(
                source_fidelity_frontmatter_authority_sha256
            ),
        )
        source_fidelity["creation_plan_sha256"] = (
            source_fidelity_plan_sha256
        )
        source_fidelity_review_binding_sha256 = (
            _source_fidelity_review_binding_sha256(
                archive_id=resolved_archive_id,
                draft_id=zettel_id,
                draft_path=proposed_path,
                body_sha256=body_sha256,
                source_fidelity_plan_sha256=(
                    source_fidelity_plan_sha256
                ),
                reviewed_by=str(
                    draft_approved_by or "<required-on-approve>"
                ),
            )
        )
        frontmatter["source_fidelity"] = _source_fidelity_safe_projection(
            source_fidelity
        )
        frontmatter["draft_creation"] = {
            "approved_by": draft_approved_by,
            "approval_scope": "inbox_draft_only",
            "approved_body_sha256": body_sha256,
            "approved_source_fidelity_plan_sha256": (
                source_fidelity_plan_sha256
            ),
            "approved_source_fidelity_review_binding_sha256": (
                source_fidelity_review_binding_sha256
            ),
        }
        expected_plan = str(
            expected_source_fidelity_plan_sha256 or ""
        ).strip().lower()
        if expected_source_fidelity_plan_sha256:
            if not SHA256_RE.fullmatch(expected_plan):
                blockers.append(
                    "expected_source_fidelity_plan_sha256_invalid"
                )
            elif expected_plan != source_fidelity_plan_sha256:
                blockers.append(
                    "expected_source_fidelity_plan_sha256_mismatch"
                )

    draft_bytes = (
        "---\n" + dump_yaml(frontmatter) + "---\n\n"
    ).encode("utf-8") + candidate_body_bytes
    if source_fidelity_plan_sha256 and source_fidelity is not None:
        fidelity_receipt_relative = (
            f"{SOURCE_FIDELITY_DRAFT_RECEIPTS_DIR}/"
            f"{source_fidelity_plan_sha256}.json"
        )
        fidelity_receipt_path = resolve_archive_relative_path(
            root, fidelity_receipt_relative
        )
        fidelity_receipt = _source_fidelity_draft_receipt(
            archive_id=resolved_archive_id,
            archive_type=archive_type,
            draft_id=zettel_id,
            draft_path=proposed_path,
            body_sha256=body_sha256,
            creation_mode=str(creation_mode),
            frontmatter_authority_sha256=str(
                source_fidelity_frontmatter_authority_sha256
            ),
            reviewed_by=str(draft_approved_by or "<required-on-approve>"),
            review_binding_sha256=str(
                source_fidelity_review_binding_sha256
            ),
            candidate_created_at=now,
            fidelity=source_fidelity,
            plan_sha256=source_fidelity_plan_sha256,
        )
        fidelity_receipt_bytes = (
            json.dumps(
                json_safe(fidelity_receipt),
                indent=2,
                ensure_ascii=False,
                default=str,
            )
            + "\n"
        ).encode("utf-8")

    planned_writes = [proposed_path]
    if fidelity_receipt_relative:
        planned_writes.append(fidelity_receipt_relative)
    if is_ai_draft and path.exists():
        draft_state = _source_fidelity_existing_state(root, path, draft_bytes)
        if draft_state == "conflict":
            blockers.append("source_fidelity_draft_create_only_conflict")
        elif draft_state == "exact":
            planned_writes = [item for item in planned_writes if item != proposed_path]
    if fidelity_receipt_path is not None and fidelity_receipt_bytes is not None:
        receipt_state = _source_fidelity_existing_state(
            root, fidelity_receipt_path, fidelity_receipt_bytes
        )
        if receipt_state == "conflict":
            blockers.append("source_fidelity_receipt_create_only_conflict")
        elif receipt_state == "exact":
            planned_writes = [
                item
                for item in planned_writes
                if item != fidelity_receipt_relative
            ]

    # The AI approval command replays the dry-run with ``approved=True``.
    # Prove the generated Zet index is current during that replay, before the
    # native human broker can be opened.  A plain exploratory dry-run remains
    # read-only and can still explain the draft itself; an idempotent replay
    # that will not create a Zet also has no index delta to protect.
    if is_ai_draft and approved and proposed_path in planned_writes:
        try:
            index_evidence = require_current_zettel_index(root)
        except (ArchiveServiceError, OSError, ValueError):
            index_evidence = {"ok": False}
        if index_evidence.get("ok") is not True:
            blockers.append(INDEX_REBUILD_REQUIRED)

    approval_replay = {
        "draft_id": (
            None
            if (
                frontmatter_credential_secret_present
                or frontmatter_private_authority_exposed
            )
            else zettel_id
        ),
        "created_at": now,
        "expected_body_sha256": body_sha256,
        "expected_source_fidelity_plan_sha256": (
            source_fidelity_plan_sha256
        ),
        "expected_archive_id": expected_archive_id or resolved_archive_id,
        "expected_type": expected_type or archive_type,
        "profile_id": profile_id,
    }
    target_archive = {
        "archive_id": resolved_archive_id,
        "archive_type": archive_type,
        "profile_id": profile_id,
        "profile_operator_id": profile_operator_id,
        "profile_authority_mode": profile_authority_mode,
    }
    preview = {
        "ok": not blockers,
        "dry_run": True,
        "lifecycle_action": "create_draft",
        "target_archive": target_archive,
        "proposed_path": (
            None
            if (
                frontmatter_credential_secret_present
                or frontmatter_private_authority_exposed
            )
            else proposed_path
        ),
        "frontmatter_preview": (
            {}
            if (
                frontmatter_credential_secret_present
                or frontmatter_private_authority_exposed
            )
            else json_safe(frontmatter)
        ),
        "body_sha256": body_sha256,
        "source_fidelity": json_safe(
            _source_fidelity_safe_projection(source_fidelity)
        ),
        "source_fidelity_plan_sha256": source_fidelity_plan_sha256,
        "source_fidelity_draft_receipt_path": fidelity_receipt_relative,
        "first_read_check": first_read_check,
        "existing_draft_title_check": existing_draft_title_check,
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
        "would_change": (
            [] if blockers else [f"write {item}" for item in planned_writes]
        ),
        "approval_replay": approval_replay,
        "approval_handoff": _create_draft_approval_handoff(
            ready=not blockers,
            approval_replay=approval_replay,
        ),
    }
    if dry_run:
        return preview
    if blockers:
        raise ArchiveServiceError("Draft creation blocked: " + "; ".join(unique_preserve_order(blockers)))

    exact_approval_reference: dict[str, Any] | None = None
    exact_approval_context: ExactHumanApprovalContext | None = None
    if is_ai_draft and approved:
        if (
            type(exact_human_approval_claim) is not _ClaimedExactHumanApproval
            or not isinstance(source_fidelity_plan_sha256, str)
        ):
            raise ArchiveServiceError("exact_human_approval_required")
        context = ExactHumanApprovalContext(
            operation=ExactHumanApprovalOperation.create_draft,
            archive_identity_sha256=exact_human_approval_archive_identity_sha256(
                resolved_archive_id
            ),
            plan_sha256="sha256:" + source_fidelity_plan_sha256,
            target_binding_sha256="sha256:" + body_sha256,
            reviewer_claim=str(draft_approved_by or "").strip(),
            review_binding_codes=(
                "body_digest_reviewed",
                "draft_identity_reviewed",
                "source_fidelity_reviewed",
            ),
            warning_codes=exact_human_approval_warning_codes(warnings),
        )
        try:
            exact_approval_reference = (
                exact_human_approval_claim.assert_ready_for_context(context)
            )
        except ExactHumanApprovalError:
            raise ArchiveServiceError("exact_human_approval_invalid") from None
        exact_approval_context = context

    inbox.mkdir(parents=True, exist_ok=True)
    created_paths: list[str] = []
    draft_index_write_planned = proposed_path in planned_writes
    expected_index_generation: str | None = None
    index_lease_token: ArchiveIndexMutationLeaseToken | None = None
    draft_created_by_run = False
    if draft_index_write_planned:
        expected_index_generation = (
            _current_archive_index_generation_for_mutation(root)
        )
        index_lease_token = begin_archive_index_mutation(
            root,
            expected_generation=expected_index_generation,
        )
    try:
        if is_ai_draft:
            draft_created_by_run = _source_fidelity_publish_create_only(
                root,
                path,
                draft_bytes,
                conflict_code="source_fidelity_draft_create_only_conflict",
            )
            if draft_created_by_run:
                created_paths.append(proposed_path)
            if fidelity_receipt_path is None or fidelity_receipt_bytes is None:
                raise ArchiveServiceError("source_fidelity_receipt_plan_missing")
            if _source_fidelity_publish_create_only(
                root,
                fidelity_receipt_path,
                fidelity_receipt_bytes,
                conflict_code="source_fidelity_receipt_create_only_conflict",
            ):
                created_paths.append(str(fidelity_receipt_relative))
        else:
            try:
                _write_bytes_create_if_absent(path, draft_bytes)
            except FileExistsError as exc:
                raise ArchiveServiceError(
                    "draft_create_only_conflict"
                ) from exc
            draft_created_by_run = True
            created_paths.append(proposed_path)
    except (ArchiveServiceError, OSError):
        if expected_index_generation is not None:
            draft_removed = (
                not draft_created_by_run
                or _created_file_cleanup_if_exact(
                    path,
                    hashlib.sha256(draft_bytes).hexdigest(),
                )
            )
            if not (
                draft_removed
                and reseal_archive_index_mutation_without_delta(
                    root,
                    expected_generation=expected_index_generation,
                    lease_token=index_lease_token,
                )
            ):
                mark_archive_index_dirty(
                    root,
                    expected_generation=expected_index_generation,
                    lease_token=index_lease_token,
                )
        raise
    exact_approval_link: dict[str, Any] | None = None
    if exact_approval_reference is not None:
        if (
            type(exact_human_approval_claim) is not _ClaimedExactHumanApproval
            or type(exact_approval_context) is not ExactHumanApprovalContext
            or not isinstance(fidelity_receipt_relative, str)
            or not isinstance(fidelity_receipt_bytes, bytes)
        ):
            raise ArchiveServiceError("exact_human_approval_link_required")
        exact_approval_link = write_exact_human_approval_link(
            root,
            approval_claim=exact_human_approval_claim,
            approval_context=exact_approval_context,
            operation=ExactHumanApprovalOperation.create_draft,
            plan_sha256=exact_approval_context.plan_sha256,
            target_binding_sha256=(
                exact_approval_context.target_binding_sha256
            ),
            source_operation_receipt=fidelity_receipt_relative,
            expected_source_operation_receipt_sha256=(
                "sha256:" + hashlib.sha256(fidelity_receipt_bytes).hexdigest()
            ),
            effect=(
                "created"
                if proposed_path in created_paths
                else "already_present_exact"
            ),
        )
    result = {
        "ok": True,
        "dry_run": False,
        "lifecycle_action": "create_draft",
        "zettel_id": zettel_id,
        "path": archive_relative_path(path, root),
        "status": "draft",
        "target_archive": target_archive,
        "frontmatter": json_safe(frontmatter),
        "body_sha256": body_sha256,
        "source_fidelity": json_safe(
            _source_fidelity_safe_projection(source_fidelity)
        ),
        "source_fidelity_plan_sha256": source_fidelity_plan_sha256,
        "source_fidelity_draft_receipt_path": fidelity_receipt_relative,
        "first_read_check": first_read_check,
        "existing_draft_title_check": existing_draft_title_check,
        "warnings": unique_preserve_order(warnings),
        "created_paths": created_paths,
        "idempotent_replay": not created_paths,
        "approval_replay": approval_replay,
        "approval_handoff": _create_draft_approval_handoff(
            ready=False,
            approval_replay=approval_replay,
            completed=True,
            receipt_ref=(
                {
                    "schema": (
                        "wom-kit/exact-human-approval-link-receipt/v0.1"
                    ),
                    "receipt_id": exact_approval_link["approval_id"],
                    "receipt_sha256": exact_approval_link["receipt_sha256"],
                    "one_use": True,
                    "consumed": True,
                }
                if exact_approval_link is not None
                else None
            ),
        ),
    }
    if exact_approval_reference is not None:
        result["exact_human_approval_reference"] = exact_approval_reference
    if exact_approval_link is not None:
        result["exact_human_approval_link"] = exact_approval_link
    if expected_index_generation is not None:
        generated_index_updated = False
        try:
            generated_index_updated = upsert_zettel_index_entry(
                root,
                path,
                frontmatter,
                normalized_body,
                expected_generation=expected_index_generation,
                expected_file_sha256=hashlib.sha256(draft_bytes).hexdigest(),
                lease_token=index_lease_token,
            )
            if not generated_index_updated:
                raise sqlite3.IntegrityError(INDEX_REBUILD_REQUIRED)
        except (ArchiveServiceError, OSError, sqlite3.Error):
            index_marked_dirty = mark_archive_index_dirty(
                root,
                expected_generation=expected_index_generation,
                lease_token=index_lease_token,
            )
            result.update(
                {
                    "ok": False,
                    "state": "draft_written_index_update_failed",
                    "blockers": [INDEX_REBUILD_REQUIRED],
                    "generated_index_updated": False,
                    "index_marked_dirty": index_marked_dirty,
                    "index_generation": expected_index_generation,
                    "partial_result": {
                        "draft_and_receipts_written": True,
                        "index_current": False,
                    },
                }
            )
            return result
        result.update(
            {
                "generated_index_updated": True,
                "index_marked_dirty": False,
                "index_generation": expected_index_generation,
            }
        )
    else:
        result.update(
            {
                "generated_index_updated": False,
                "index_marked_dirty": False,
                "index_generation": None,
            }
        )
    return result


def _source_fidelity_raw_draft_snapshot(
    root: Path,
    path: Path,
) -> dict[str, Any]:
    """Parse a fidelity draft without BOM removal, newline conversion, or lstrip."""

    blocked = lambda code: {
        "ok": False,
        "blockers": [code],
        "frontmatter": {},
        "body_bytes": b"",
        "raw": b"",
    }
    try:
        bound_root, bound_path = _source_fidelity_bound_root_and_path(
            root, path
        )
        with _hold_activity_group_evidence_file(
            bound_root,
            bound_path,
            max_bytes=SOURCE_FIDELITY_MAX_DRAFT_BYTES,
        ) as snapshot:
            raw = snapshot["raw"]
    except (OSError, ValueError):
        return blocked("source_fidelity_draft_missing_or_unsafe")
    if raw.startswith(b"\xef\xbb\xbf"):
        return blocked("source_fidelity_draft_frontmatter_bom_forbidden")
    if not raw.startswith(b"---\n"):
        return blocked("source_fidelity_draft_frontmatter_boundary_invalid")
    cursor = 4
    closing_start: int | None = None
    closing_end: int | None = None
    while cursor < len(raw):
        newline = raw.find(b"\n", cursor)
        if newline < 0:
            break
        if raw[cursor : newline + 1] == b"---\n":
            closing_start = cursor
            closing_end = newline + 1
            break
        cursor = newline + 1
    if closing_start is None or closing_end is None:
        return blocked("source_fidelity_draft_frontmatter_boundary_invalid")
    if raw[closing_end : closing_end + 1] != b"\n":
        return blocked("source_fidelity_draft_body_separator_invalid")
    try:
        frontmatter_text = raw[4:closing_start].decode("utf-8")
        loaded = load_approval_yaml_without_duplicate_keys(frontmatter_text)
        frontmatter = normalize_approval_json_tree(loaded)
    except ApprovalYamlDuplicateKeyError:
        return blocked("source_fidelity_draft_frontmatter_duplicate_key")
    except (UnicodeError, ApprovalYamlValueError, ValueError, RecursionError):
        return blocked("source_fidelity_draft_frontmatter_invalid")
    except Exception:
        return blocked("source_fidelity_draft_frontmatter_invalid")
    if not isinstance(frontmatter, dict):
        return blocked("source_fidelity_draft_frontmatter_not_object")
    body_start = closing_end + 1
    body_bytes = raw[body_start:]
    try:
        body_bytes.decode("utf-8")
    except UnicodeDecodeError:
        return blocked("source_fidelity_draft_body_not_utf8")
    return {
        "ok": True,
        "blockers": [],
        "frontmatter": frontmatter,
        "body_bytes": body_bytes,
        "body_start": body_start,
        "raw": raw,
        "raw_sha256": _source_fidelity_digest_bytes(raw),
    }


def _source_fidelity_find_exact_regions(
    body: bytes,
    needle: bytes,
    *,
    limit: int = 2,
) -> list[int]:
    if not needle:
        return []
    positions: list[int] = []
    cursor = 0
    while len(positions) < limit:
        position = body.find(needle, cursor)
        if position < 0:
            break
        positions.append(position)
        cursor = position + 1
    return positions


def _source_fidelity_private_receipt_shape_valid_v1(value: Any) -> bool:
    """Validate the complete private receipt contract without a runtime dependency.

    The packaged JSON Schema is the public contract.  WOM-kit deliberately
    keeps ``jsonschema`` out of the installed runtime, so this verifier mirrors
    the schema's closed keys, primitive types, constants, and nested source and
    region shapes before mint trusts any receipt field.
    """

    if not isinstance(value, dict) or set(value) != {
        "schema",
        "action",
        "archive_id",
        "archive_type",
        "draft_id",
        "draft_path",
        "body_sha256",
        "creation_mode",
        "frontmatter_authority_sha256",
        "source_fidelity_plan_sha256",
        "reviewed_by",
        "review_binding_sha256",
        "candidate_created_at",
        "source_fidelity",
        "content_contract",
        "result",
    }:
        return False
    if (
        value.get("schema") != SOURCE_FIDELITY_DRAFT_RECEIPT_SCHEMA_V1
        or value.get("action") != "create_source_fidelity_draft"
        or not isinstance(value.get("archive_id"), str)
        or not value.get("archive_id")
        or (
            value.get("archive_type") is not None
            and not isinstance(value.get("archive_type"), str)
        )
        or not isinstance(value.get("draft_id"), str)
        or not valid_draft_zettel_id(value["draft_id"])
        or not isinstance(value.get("draft_path"), str)
        or re.fullmatch(r"inbox/[A-Za-z0-9_-]+\.md", value["draft_path"])
        is None
        or not isinstance(value.get("reviewed_by"), str)
        or not value.get("reviewed_by")
        or not isinstance(value.get("review_binding_sha256"), str)
        or SHA256_RE.fullmatch(value["review_binding_sha256"]) is None
        or not isinstance(value.get("candidate_created_at"), str)
        or not valid_iso_timestamp(value["candidate_created_at"])
        or value.get("creation_mode") not in {
            "ai_assisted",
            "ai_generated",
        }
    ):
        return False
    for key in (
        "body_sha256",
        "frontmatter_authority_sha256",
        "source_fidelity_plan_sha256",
    ):
        if not isinstance(value.get(key), str) or SHA256_RE.fullmatch(
            value[key]
        ) is None:
            return False

    content_contract = value.get("content_contract")
    if not isinstance(content_contract, dict) or set(content_contract) != {
        "source_text_stored",
        "source_locator_stored",
        "source_path_stored",
    }:
        return False
    if any(content_contract.get(key) is not False for key in content_contract):
        return False

    result = value.get("result")
    if not isinstance(result, dict) or set(result) != {
        "draft_written_create_only",
        "receipt_written_create_only",
        "source_changed",
        "share_performed",
    }:
        return False
    if (
        result.get("draft_written_create_only") is not True
        or result.get("receipt_written_create_only") is not True
        or result.get("source_changed") is not False
        or result.get("share_performed") is not False
    ):
        return False

    fidelity = value.get("source_fidelity")
    if not isinstance(fidelity, dict) or set(fidelity) != {
        "schema",
        "mode",
        "audience",
        "comparison_basis",
        "source",
        "region",
        "byte_exact",
        "mechanically_verified",
        "semantic_fidelity_machine_verified",
        "human_review_required",
        "source_changed",
        "share_performed",
        "source_text_stored",
        "source_locator_stored",
        "creation_plan_sha256",
        "evidence_id",
    }:
        return False
    mode = fidelity.get("mode")
    if (
        fidelity.get("schema") != SOURCE_FIDELITY_SCHEMA_V1
        or mode not in SOURCE_FIDELITY_MODES
        or fidelity.get("audience") not in ZET_QUALITY_AUDIENCES
        or fidelity.get("comparison_basis")
        != SOURCE_FIDELITY_COMPARISON_BASIS
        or fidelity.get("byte_exact") is not False
        or fidelity.get("mechanically_verified") is not (mode == "verbatim")
        or fidelity.get("semantic_fidelity_machine_verified") is not False
        or fidelity.get("human_review_required") is not True
        or fidelity.get("source_changed") is not False
        or fidelity.get("share_performed") is not False
        or fidelity.get("source_text_stored") is not False
        or fidelity.get("source_locator_stored") is not False
        or not isinstance(fidelity.get("creation_plan_sha256"), str)
        or SHA256_RE.fullmatch(fidelity["creation_plan_sha256"]) is None
        or not isinstance(fidelity.get("evidence_id"), str)
        or re.fullmatch(
            r"source-fidelity-evidence:[0-9a-f]{24}",
            fidelity["evidence_id"],
        )
        is None
    ):
        return False

    source = fidelity.get("source")
    if not isinstance(source, dict) or set(source) != {
        "object_id",
        "raw_sha256",
        "raw_size_bytes",
        "normalized_sha256",
        "normalized_size_bytes",
        "comparison_basis",
        "newline_transformation_applied",
        "source_text_stored",
        "source_locator_stored",
    }:
        return False
    if (
        not isinstance(source.get("object_id"), str)
        or OBJECT_ID_RE.fullmatch(source["object_id"]) is None
        or source["object_id"].removeprefix("sha256:")
        != source.get("raw_sha256")
        or not isinstance(source.get("raw_sha256"), str)
        or SHA256_RE.fullmatch(source["raw_sha256"]) is None
        or not isinstance(source.get("normalized_sha256"), str)
        or SHA256_RE.fullmatch(source["normalized_sha256"]) is None
        or isinstance(source.get("raw_size_bytes"), bool)
        or not isinstance(source.get("raw_size_bytes"), int)
        or source["raw_size_bytes"] < 0
        or isinstance(source.get("normalized_size_bytes"), bool)
        or not isinstance(source.get("normalized_size_bytes"), int)
        or source["normalized_size_bytes"] < 0
        or source.get("comparison_basis")
        != SOURCE_FIDELITY_COMPARISON_BASIS
        or not isinstance(source.get("newline_transformation_applied"), bool)
        or source.get("source_text_stored") is not False
        or source.get("source_locator_stored") is not False
    ):
        return False

    region = fidelity.get("region")
    if mode == "verbatim":
        if not isinstance(region, dict) or set(region) != {
            "offset_bytes",
            "length_bytes",
            "sha256",
        }:
            return False
        if (
            isinstance(region.get("offset_bytes"), bool)
            or not isinstance(region.get("offset_bytes"), int)
            or region["offset_bytes"] < 0
            or isinstance(region.get("length_bytes"), bool)
            or not isinstance(region.get("length_bytes"), int)
            or region["length_bytes"] < 0
            or not isinstance(region.get("sha256"), str)
            or SHA256_RE.fullmatch(region["sha256"]) is None
        ):
            return False
    elif region is not None:
        return False
    return True


def _source_fidelity_private_receipt_shape_valid_v2(value: Any) -> bool:
    """Validate v0.2 by reusing v0.1 common/region checks plus its union."""

    if not isinstance(value, dict):
        return False
    fidelity = value.get("source_fidelity")
    source = fidelity.get("source") if isinstance(fidelity, dict) else None
    if not isinstance(fidelity, dict) or not isinstance(source, dict):
        return False
    if (
        value.get("schema") != SOURCE_FIDELITY_DRAFT_RECEIPT_SCHEMA_V2
        or fidelity.get("schema") != SOURCE_FIDELITY_SCHEMA_V2
    ):
        return False

    # The outer receipt contract, generic fidelity booleans, and region rules
    # are unchanged.  Adapt only the version and private authority source so
    # the already strict v0.1 verifier remains one source of truth.
    legacy_projection = copy.deepcopy(value)
    legacy_projection["schema"] = SOURCE_FIDELITY_DRAFT_RECEIPT_SCHEMA_V1
    legacy_fidelity = legacy_projection["source_fidelity"]
    legacy_fidelity["schema"] = SOURCE_FIDELITY_SCHEMA_V1
    raw_sha = str(source.get("raw_sha256") or "")
    legacy_fidelity["source"] = {
        "object_id": "sha256:" + raw_sha,
        "raw_sha256": raw_sha,
        "raw_size_bytes": source.get("raw_size_bytes"),
        "normalized_sha256": source.get("normalized_sha256"),
        "normalized_size_bytes": source.get("normalized_size_bytes"),
        "comparison_basis": source.get("comparison_basis"),
        "newline_transformation_applied": source.get(
            "newline_transformation_applied"
        ),
        "source_text_stored": source.get("source_text_stored"),
        "source_locator_stored": source.get("source_locator_stored"),
    }
    if not _source_fidelity_private_receipt_shape_valid_v1(
        legacy_projection
    ):
        return False

    authority_kind = source.get("authority_kind")
    common_keys = {
        "authority_kind",
        "raw_sha256",
        "raw_size_bytes",
        "normalized_sha256",
        "normalized_size_bytes",
        "comparison_basis",
        "newline_transformation_applied",
        "source_text_stored",
        "source_locator_stored",
    }
    if authority_kind == "manifested_object":
        if set(source) != common_keys | {"object_id", "provenance"}:
            return False
        if (
            not isinstance(source.get("object_id"), str)
            or OBJECT_ID_RE.fullmatch(source["object_id"]) is None
            or source["object_id"].removeprefix("sha256:") != raw_sha
        ):
            return False
        provenance = source.get("provenance")
        expected_provenance_keys = {
            "binding_state",
            "captured_at",
            "source_role",
            "input_kind",
            "source_intake_plan_sha256",
            "staged_source_class",
            "independent_external_provenance",
            "raw_source_locator_stored",
            "raw_source_locator_echoed",
        }
        if not isinstance(provenance, dict) or set(provenance) != expected_provenance_keys:
            return False
        if provenance.get("binding_state") not in {
            "manifest_intake_bound",
            "legacy_unbound",
        }:
            return False
        captured_at = provenance.get("captured_at")
        if captured_at is not None and (
            not isinstance(captured_at, str)
            or normalize_zet_revision_timestamp(
                captured_at, default_now=False
            )
            is None
        ):
            return False
        if provenance.get("source_role") is not None and provenance.get(
            "source_role"
        ) not in SOURCE_INTAKE_ROLES:
            return False
        plan_sha = provenance.get("source_intake_plan_sha256")
        if plan_sha is not None and (
            not isinstance(plan_sha, str)
            or re.fullmatch(r"sha256:[0-9a-f]{64}", plan_sha) is None
        ):
            return False
        if (
            not isinstance(provenance.get("staged_source_class"), str)
            or not isinstance(
                provenance.get("independent_external_provenance"), bool
            )
            or provenance.get("raw_source_locator_stored") is not False
            or provenance.get("raw_source_locator_echoed") is not False
        ):
            return False
    elif authority_kind == "reviewed_session_evidence":
        session_keys = {
            "evidence_id",
            "source_role",
            "producer_kind",
            "produced_at",
            "captured_at",
            "session_ref_sha256",
            "input_provenance_sha256",
            "semantic_fidelity_machine_verified",
            "receipt_sha256",
        }
        if set(source) != common_keys | session_keys:
            return False
        if re.fullmatch(
            r"source-fidelity-session-evidence:[0-9a-f]{64}",
            str(source.get("evidence_id") or ""),
        ) is None:
            return False
        if source.get("source_role") not in SOURCE_FIDELITY_SESSION_SOURCE_ROLES:
            return False
        if source.get("producer_kind") not in SOURCE_FIDELITY_SESSION_PRODUCER_KINDS:
            return False
        produced_at = normalize_zet_revision_timestamp(
            source.get("produced_at")
            if isinstance(source.get("produced_at"), str)
            else None,
            default_now=False,
        )
        captured_at = normalize_zet_revision_timestamp(
            source.get("captured_at")
            if isinstance(source.get("captured_at"), str)
            else None,
            default_now=False,
        )
        if (
            produced_at is None
            or captured_at is None
            or produced_at > captured_at
        ):
            return False
        if re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            str(source.get("session_ref_sha256") or ""),
        ) is None or re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            str(source.get("receipt_sha256") or ""),
        ) is None:
            return False
        input_provenance = source.get("input_provenance_sha256")
        if not isinstance(input_provenance, list) or any(
            not isinstance(item, str)
            or re.fullmatch(r"sha256:[0-9a-f]{64}", item) is None
            for item in input_provenance
        ):
            return False
        if source.get("semantic_fidelity_machine_verified") is not False:
            return False
    else:
        return False
    return True


def _source_fidelity_private_receipt_shape_valid(value: Any) -> bool:
    if not isinstance(value, dict):
        return False
    if value.get("schema") == SOURCE_FIDELITY_DRAFT_RECEIPT_SCHEMA_V1:
        return _source_fidelity_private_receipt_shape_valid_v1(value)
    if value.get("schema") == SOURCE_FIDELITY_DRAFT_RECEIPT_SCHEMA_V2:
        return _source_fidelity_private_receipt_shape_valid_v2(value)
    return False


def _source_fidelity_private_receipt_for_mint(
    root: Path,
    *,
    frontmatter: dict[str, Any],
    draft_path: str,
) -> tuple[dict[str, Any] | None, list[str]]:
    projection = frontmatter.get("source_fidelity")
    if not isinstance(projection, dict):
        return None, ["source_fidelity_metadata_invalid"]
    plan_sha256 = str(
        projection.get("creation_plan_sha256") or ""
    ).strip().lower()
    if not SHA256_RE.fullmatch(plan_sha256):
        return None, ["source_fidelity_creation_plan_sha256_invalid"]
    receipt_relative = (
        f"{SOURCE_FIDELITY_DRAFT_RECEIPTS_DIR}/{plan_sha256}.json"
    )
    receipt_path = root.joinpath(*PurePosixPath(receipt_relative).parts)
    try:
        bound_root, bound_path = _source_fidelity_bound_root_and_path(
            root, receipt_path
        )
        with _hold_activity_group_evidence_file(
            bound_root,
            bound_path,
            max_bytes=1024 * 1024,
        ) as snapshot:
            raw = snapshot["raw"]
    except (OSError, ValueError):
        return None, ["source_fidelity_private_receipt_missing_or_unsafe"]

    class DuplicateReceiptKey(ValueError):
        pass

    def reject_duplicate_pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise DuplicateReceiptKey(key)
            result[key] = value
        return result

    try:
        receipt = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=reject_duplicate_pairs,
            parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)),
        )
    except (
        UnicodeDecodeError,
        json.JSONDecodeError,
        DuplicateReceiptKey,
        ValueError,
        RecursionError,
    ):
        return None, ["source_fidelity_private_receipt_invalid"]
    if not isinstance(receipt, dict):
        return None, ["source_fidelity_private_receipt_invalid"]
    if not _source_fidelity_private_receipt_shape_valid(receipt):
        return None, ["source_fidelity_private_receipt_schema_invalid"]
    draft_creation = (
        frontmatter.get("draft_creation")
        if isinstance(frontmatter.get("draft_creation"), dict)
        else {}
    )
    receipt_archive_config = read_archive_config(root)
    expected = {
        "schema": receipt.get("schema"),
        "action": "create_source_fidelity_draft",
        "archive_id": str(frontmatter.get("archive_id") or ""),
        "archive_type": (
            receipt_archive_config.get("type")
            if isinstance(receipt_archive_config.get("type"), str)
            else None
        ),
        "draft_id": str(frontmatter.get("id") or ""),
        "draft_path": draft_path,
        "body_sha256": draft_creation.get("approved_body_sha256"),
        "source_fidelity_plan_sha256": plan_sha256,
        "reviewed_by": draft_creation.get("approved_by"),
        "review_binding_sha256": draft_creation.get(
            "approved_source_fidelity_review_binding_sha256"
        ),
        "candidate_created_at": frontmatter.get("created_at"),
    }
    if any(receipt.get(key) != value for key, value in expected.items()):
        return receipt, [
            "source_fidelity_private_receipt_authority_mismatch"
        ]
    expected_review_binding = _source_fidelity_review_binding_sha256(
        archive_id=str(receipt.get("archive_id") or ""),
        draft_id=str(receipt.get("draft_id") or ""),
        draft_path=str(receipt.get("draft_path") or ""),
        body_sha256=str(receipt.get("body_sha256") or ""),
        source_fidelity_plan_sha256=str(
            receipt.get("source_fidelity_plan_sha256") or ""
        ),
        reviewed_by=str(receipt.get("reviewed_by") or ""),
    )
    if not hmac.compare_digest(
        expected_review_binding,
        str(receipt.get("review_binding_sha256") or ""),
    ):
        return receipt, ["source_fidelity_review_binding_invalid"]
    full_fidelity = receipt.get("source_fidelity")
    if not isinstance(full_fidelity, dict):
        return receipt, [
            "source_fidelity_private_receipt_evidence_invalid"
        ]
    expected_projection = _source_fidelity_safe_projection(full_fidelity)
    if projection != expected_projection:
        return receipt, [
            "source_fidelity_private_receipt_projection_mismatch"
        ]
    return receipt, []


def _source_fidelity_verify_for_mint(
    root: Path,
    path: Path,
    *,
    affirmations: dict[str, str] | None,
) -> dict[str, Any]:
    legacy_snapshot = validated_approval_zettel_snapshot(
        path,
        max_bytes=SOURCE_FIDELITY_MAX_DRAFT_BYTES,
        expected_zettel_id=None,
        expected_archive_id=read_archive_id(root),
        expected_status="draft",
    )
    if not legacy_snapshot.get("ok"):
        return {
            "applicable": True,
            "ok": False,
            "legacy_review": False,
            "current_plan_sha256": None,
            "source_fidelity": None,
            "blockers": [
                "source_fidelity_legacy_boundary_invalid"
            ],
        }
    frontmatter = legacy_snapshot["frontmatter"]
    provenance = (
        frontmatter.get("provenance")
        if isinstance(frontmatter.get("provenance"), dict)
        else {}
    )
    creation_mode = provenance.get("creation_mode")
    is_ai = _source_fidelity_ai_provenance_declared(
        creation_mode=creation_mode,
        created_by=provenance.get("created_by"),
        assisted_by=provenance.get("assisted_by"),
        local_ai_sessions=frontmatter.get("local_ai_sessions"),
    )
    fidelity_projection = frontmatter.get("source_fidelity")
    metadata_blockers = _source_fidelity_request_metadata_blockers(
        frontmatter
    )
    legacy_body_blockers = [
        code
        for code in _source_fidelity_request_metadata_blockers(
            legacy_snapshot.get("body")
        )
        if code == "credential_secret_present"
    ]
    if is_ai and (metadata_blockers or legacy_body_blockers):
        return {
            "applicable": True,
            "ok": False,
            "legacy_review": False,
            "current_plan_sha256": None,
            "source_fidelity": None,
            "blockers": unique_preserve_order(
                [*metadata_blockers, *legacy_body_blockers]
            ),
        }
    if not is_ai and not isinstance(fidelity_projection, dict):
        return {
            "applicable": False,
            "ok": True,
            "legacy_review": False,
            "current_plan_sha256": None,
            "source_fidelity": None,
            "blockers": [],
        }
    if is_ai and not isinstance(fidelity_projection, dict):
        affirmed = bool(
            affirmations
            and affirmations.get("legacy_source_fidelity_reviewed")
        )
        return {
            "applicable": True,
            "ok": affirmed,
            "legacy_review": affirmed,
            "current_plan_sha256": None,
            "source_fidelity": {
                "schema": SOURCE_FIDELITY_SCHEMA,
                "state": (
                    "legacy_human_reviewed"
                    if affirmed
                    else "legacy_human_review_required"
                ),
                "inferred_from_legacy_content": False,
                "source_text_echoed": False,
            },
            "blockers": (
                []
                if affirmed
                else ["legacy_source_fidelity_review_required"]
            ),
        }
    if not isinstance(fidelity_projection, dict):
        return {
            "applicable": True,
            "ok": False,
            "legacy_review": False,
            "current_plan_sha256": None,
            "source_fidelity": None,
            "blockers": ["source_fidelity_metadata_invalid"],
        }

    # v0.3.313 fidelity drafts use an LF-only byte contract.  Legacy AI drafts
    # are classified and affirmed above through the tolerant, duplicate-safe
    # approval parser so old Windows CRLF records remain reviewable.
    snapshot = _source_fidelity_raw_draft_snapshot(root, path)
    if not snapshot.get("ok"):
        return {
            "applicable": True,
            "ok": False,
            "legacy_review": False,
            "current_plan_sha256": None,
            "source_fidelity": None,
            "blockers": snapshot.get("blockers", []),
        }
    frontmatter = snapshot["frontmatter"]
    provenance = (
        frontmatter.get("provenance")
        if isinstance(frontmatter.get("provenance"), dict)
        else {}
    )
    creation_mode = provenance.get("creation_mode")
    fidelity_projection = frontmatter.get("source_fidelity")

    draft_relative = archive_relative_path(path, root)
    private_receipt, receipt_blockers = (
        _source_fidelity_private_receipt_for_mint(
            root,
            frontmatter=frontmatter,
            draft_path=draft_relative,
        )
    )
    blockers: list[str] = list(receipt_blockers)
    warnings: list[str] = []
    fidelity = (
        private_receipt.get("source_fidelity")
        if isinstance(private_receipt, dict)
        and isinstance(private_receipt.get("source_fidelity"), dict)
        else {}
    )
    mode = fidelity.get("mode")
    audience = fidelity.get("audience")
    fidelity_schema = fidelity.get("schema")
    if fidelity_schema not in {
        SOURCE_FIDELITY_SCHEMA_V1,
        SOURCE_FIDELITY_SCHEMA_V2,
    }:
        blockers.append("source_fidelity_schema_invalid")
    authority_binding_state = (
        "legacy_unbound"
        if fidelity_schema == SOURCE_FIDELITY_SCHEMA_V1
        else "reviewed_session_evidence"
        if (
            isinstance(fidelity.get("source"), dict)
            and fidelity["source"].get("authority_kind")
            == "reviewed_session_evidence"
        )
        else (
            fidelity.get("source", {}).get("provenance", {}).get(
                "binding_state"
            )
            if isinstance(fidelity.get("source"), dict)
            and isinstance(
                fidelity.get("source", {}).get("provenance"), dict
            )
            else "legacy_unbound"
        )
    )
    if fidelity_schema == SOURCE_FIDELITY_SCHEMA_V1:
        warnings.append("legacy_source_fidelity_authority_unbound")
    if mode not in SOURCE_FIDELITY_MODES:
        blockers.append("source_fidelity_mode_invalid")
    if audience not in ZET_QUALITY_AUDIENCES:
        blockers.append("source_fidelity_audience_invalid")
    if fidelity.get("comparison_basis") != SOURCE_FIDELITY_COMPARISON_BASIS:
        blockers.append("source_fidelity_comparison_basis_invalid")
    archive_config = read_archive_config(root)
    archive_id = str(archive_config.get("archive_id") or "")
    archive_type = (
        archive_config.get("type")
        if isinstance(archive_config.get("type"), str)
        else None
    )
    if mode == "verbatim" and (
        archive_type != "personal" or audience != "private_self"
    ):
        blockers.append("verbatim_requires_personal_private_self")
    if mode == "verbatim" and not _source_fidelity_private_visibility_valid(
        frontmatter.get("visibility")
    ):
        blockers.append("verbatim_requires_private_visibility")

    source_meta = (
        fidelity.get("source")
        if isinstance(fidelity.get("source"), dict)
        else {}
    )
    authority_kind = source_meta.get("authority_kind") or "manifested_object"
    if authority_kind == "reviewed_session_evidence":
        current_source, normalized_source, source_blockers = (
            _read_verified_session_evidence(
                root, source_meta.get("evidence_id")
            )
        )
    else:
        current_source, normalized_source, source_blockers = (
            _source_fidelity_read_manifested_object(
                root,
                source_meta.get("object_id"),
            )
        )
        if (
            fidelity_schema == SOURCE_FIDELITY_SCHEMA_V1
            and isinstance(current_source, dict)
        ):
            current_source = {
                key: value
                for key, value in current_source.items()
                if key not in {"authority_kind", "provenance"}
            }
    blockers.extend(source_blockers)
    if current_source is None or normalized_source is None:
        blockers.append("source_fidelity_source_authority_unavailable")
    else:
        if json_safe(source_meta) != json_safe(current_source):
            blockers.append("source_fidelity_source_authority_drift")

    private_authority_values = _source_fidelity_private_authority_values(
        source_meta
    )
    public_frontmatter_authority = {
        key: value
        for key, value in frontmatter.items()
        if key not in {"source_fidelity", "draft_creation"}
    }
    draft_creation = (
        frontmatter.get("draft_creation")
        if isinstance(frontmatter.get("draft_creation"), dict)
        else {}
    )
    if set(draft_creation) != SOURCE_FIDELITY_DRAFT_CREATION_KEYS:
        blockers.append("source_fidelity_draft_creation_schema_invalid")
    draft_creation_private_authority = {
        key: value
        for key, value in draft_creation.items()
        if key != "approved_body_sha256"
    }
    if (
        private_authority_values
        and _source_fidelity_value_contains_private_authority(
            {
                "frontmatter": public_frontmatter_authority,
                "draft_creation": draft_creation_private_authority,
            },
            private_values=private_authority_values,
        )
    ):
        blockers.append("source_fidelity_private_authority_exposed")

    approved_body_sha256 = str(
        draft_creation.get("approved_body_sha256") or ""
    ).strip().lower()
    creation_plan_sha256 = str(
        fidelity.get("creation_plan_sha256") or ""
    ).strip().lower()
    if not SHA256_RE.fullmatch(approved_body_sha256):
        blockers.append("source_fidelity_approved_body_sha256_invalid")
    if not SHA256_RE.fullmatch(creation_plan_sha256):
        blockers.append("source_fidelity_creation_plan_sha256_invalid")
    if (
        draft_creation.get("approved_source_fidelity_plan_sha256")
        != creation_plan_sha256
    ):
        blockers.append("source_fidelity_creation_approval_binding_invalid")

    stored_region = (
        fidelity.get("region")
        if isinstance(fidelity.get("region"), dict)
        else None
    )
    expected_evidence_id = (
        "source-fidelity-evidence:"
        + _source_fidelity_digest_json(
            {
                "source": source_meta,
                "region": stored_region,
                "mode": mode,
                "audience": audience,
                "comparison_basis": SOURCE_FIDELITY_COMPARISON_BASIS,
            }
        )[:24]
    )
    if fidelity.get("evidence_id") != expected_evidence_id:
        blockers.append("source_fidelity_evidence_id_invalid")
    if isinstance(private_receipt, dict) and SHA256_RE.fullmatch(
        creation_plan_sha256
    ):
        expected_creation_plan = _source_fidelity_plan_sha256(
            archive_id=str(private_receipt.get("archive_id") or ""),
            archive_type=(
                private_receipt.get("archive_type")
                if isinstance(private_receipt.get("archive_type"), str)
                else None
            ),
            draft_id=str(private_receipt.get("draft_id") or ""),
            draft_path=str(private_receipt.get("draft_path") or ""),
            created_at=str(
                private_receipt.get("candidate_created_at") or ""
            ),
            creation_mode=str(private_receipt.get("creation_mode") or ""),
            fidelity=fidelity,
            final_body_sha256=str(
                private_receipt.get("body_sha256") or ""
            ),
            region=stored_region,
            frontmatter=frontmatter,
            frontmatter_authority_sha256=str(
                private_receipt.get("frontmatter_authority_sha256") or ""
            ),
        )
        if not hmac.compare_digest(
            expected_creation_plan, creation_plan_sha256
        ):
            blockers.append("source_fidelity_creation_plan_tampered")

    body_bytes = snapshot["body_bytes"]
    current_body_sha256 = _source_fidelity_digest_bytes(body_bytes)
    current_region: dict[str, Any] | None = None
    if normalized_source is not None and hmac.compare_digest(
        body_bytes, normalized_source
    ):
        if authority_kind == "reviewed_session_evidence":
            local_session_hashes = {
                "sha256:"
                + _source_fidelity_digest_bytes(
                    str(item.get("session_ref") or "").encode("utf-8")
                )
                for item in (
                    frontmatter.get("local_ai_sessions")
                    if isinstance(frontmatter.get("local_ai_sessions"), list)
                    else []
                )
                if isinstance(item, dict)
                and isinstance(item.get("session_ref"), str)
                and item.get("session_ref")
            }
            source_produced_at = normalize_zet_revision_timestamp(
                source_meta.get("produced_at")
                if isinstance(source_meta.get("produced_at"), str)
                else None,
                default_now=False,
            )
            candidate_created_at = normalize_zet_revision_timestamp(
                frontmatter.get("created_at")
                if isinstance(frontmatter.get("created_at"), str)
                else None,
                default_now=False,
            )
            if source_meta.get("source_role") == "self_authored_candidate" or (
                source_meta.get("producer_kind") == "ai_runtime"
                and (
                    source_meta.get("session_ref_sha256")
                    in local_session_hashes
                    or (
                        source_produced_at
                        and candidate_created_at
                        and source_produced_at >= candidate_created_at
                    )
                )
            ):
                blockers.append("circular_self_source")
        elif fidelity_schema == SOURCE_FIDELITY_SCHEMA_V2:
            object_provenance = (
                source_meta.get("provenance")
                if isinstance(source_meta.get("provenance"), dict)
                else {}
            )
            if (
                not object_provenance.get("independent_external_provenance")
                and (
                    object_provenance.get("source_role")
                    == "derived_context"
                    or object_provenance.get("staged_source_class")
                    == "archive_ai_scratch"
                )
            ):
                blockers.append("circular_self_source")
    decoded_body = body_bytes.decode("utf-8", errors="ignore")
    if (
        SOURCE_FIDELITY_CREDENTIAL_SECRET_RE.search(decoded_body)
        or _source_fidelity_sensitive_assignment_contains_secret(
            decoded_body
        )
    ):
        blockers.append("credential_secret_present")
    if mode == "verbatim" and normalized_source is not None:
        if not isinstance(stored_region, dict):
            blockers.append("source_fidelity_region_missing")
        else:
            offset = stored_region.get("offset_bytes")
            length = stored_region.get("length_bytes")
            region_sha = stored_region.get("sha256")
            region_shape_valid = (
                not isinstance(offset, bool)
                and isinstance(offset, int)
                and offset >= 0
                and not isinstance(length, bool)
                and isinstance(length, int)
                and length == len(normalized_source)
                and region_sha
                == _source_fidelity_digest_bytes(normalized_source)
            )
            if not region_shape_valid:
                blockers.append("source_fidelity_region_metadata_invalid")
            else:
                selected = body_bytes[offset : offset + length]
                if hmac.compare_digest(selected, normalized_source):
                    current_region = dict(stored_region)
                elif current_body_sha256 == approved_body_sha256:
                    blockers.append("source_fidelity_region_mismatch")
                else:
                    matches = _source_fidelity_find_exact_regions(
                        body_bytes, normalized_source
                    )
                    if len(matches) != 1:
                        blockers.append("source_fidelity_region_mismatch")
                    else:
                        current_region = {
                            "offset_bytes": matches[0],
                            "length_bytes": len(normalized_source),
                            "sha256": _source_fidelity_digest_bytes(
                                normalized_source
                            ),
                        }
    elif mode in {"faithful_summary", "sanitized_derivative"}:
        if stored_region is not None:
            blockers.append("source_fidelity_region_for_non_verbatim")

    if mode == "verbatim" and isinstance(current_region, dict):
        region_offset = current_region["offset_bytes"]
        region_length = current_region["length_bytes"]
        context_bytes = (
            body_bytes[:region_offset]
            + body_bytes[region_offset + region_length :]
        )
        if zettel_body_has_forbidden_location_reference(
            context_bytes.decode("utf-8")
        ):
            blockers.append(
                "private_locator_outside_verified_verbatim_region"
            )

    current_plan_sha256: str | None = None
    if not blockers:
        current_plan_sha256 = _source_fidelity_plan_sha256(
            archive_id=archive_id,
            archive_type=archive_type,
            draft_id=str(frontmatter.get("id") or path.stem),
            draft_path=draft_relative,
            created_at=str(frontmatter.get("created_at") or ""),
            creation_mode=str(creation_mode),
            fidelity=fidelity,
            final_body_sha256=current_body_sha256,
            region=current_region,
            frontmatter=frontmatter,
        )
    safe_fidelity = _source_fidelity_safe_projection(
        fidelity,
        review_state=(
            "unchanged_since_draft_approval"
            if current_body_sha256 == approved_body_sha256
            else "mint_reapproval_required"
        ),
    )
    if isinstance(safe_fidelity, dict):
        safe_fidelity["mechanically_verified"] = (
            mode == "verbatim" and not blockers
        )
    privacy_blocked = any(
        code
        in {
            "credential_secret_present",
            "private_locator_or_path_present",
            "source_fidelity_private_authority_exposed",
        }
        for code in blockers
    )
    return {
        "applicable": True,
        "ok": not blockers,
        "legacy_review": False,
        "current_plan_sha256": (
            None if privacy_blocked else current_plan_sha256
        ),
        "creation_plan_sha256": (
            None if privacy_blocked else creation_plan_sha256 or None
        ),
        "current_body_sha256": (
            None if privacy_blocked else current_body_sha256
        ),
        "source_fidelity": None if privacy_blocked else safe_fidelity,
        "authority_binding_state": (
            None if privacy_blocked else authority_binding_state
        ),
        "raw_snapshot": snapshot if not blockers else None,
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
    }


def _read_bounded_inbox_draft_frontmatter(
    path: Path,
    *,
    max_frontmatter_bytes: int,
) -> dict[str, Any]:
    """Read one bounded frontmatter block without following links or reading a valid body."""

    result: dict[str, Any] = {
        "frontmatter": {},
        "metadata_readable": False,
        "issue_code": None,
        "body_text_read": False,
        "frontmatter_bytes_read": 0,
    }
    if path.is_symlink():
        result["issue_code"] = "symlink_not_followed"
        return result
    try:
        if not path.is_file():
            result["issue_code"] = "draft_file_unavailable"
            return result
        before = path.stat()
        with path.open("rb") as handle:
            first = handle.readline(max_frontmatter_bytes + 1)
            result["frontmatter_bytes_read"] = len(first)
            opening = first.removeprefix(b"\xef\xbb\xbf")
            if (
                len(first) > max_frontmatter_bytes
                or re.fullmatch(rb"---[ \t]*\r?\n", opening) is None
            ):
                result["issue_code"] = (
                    "frontmatter_limit_exceeded"
                    if len(first) > max_frontmatter_bytes
                    else "frontmatter_boundary_invalid"
                )
                result["body_text_read"] = bool(first)
                return result

            lines: list[bytes] = []
            while True:
                remaining = max_frontmatter_bytes - int(
                    result["frontmatter_bytes_read"]
                )
                if remaining <= 0:
                    result["issue_code"] = "frontmatter_limit_exceeded"
                    result["body_text_read"] = bool(lines)
                    return result
                line = handle.readline(remaining + 1)
                result["frontmatter_bytes_read"] = int(
                    result["frontmatter_bytes_read"]
                ) + len(line)
                if not line:
                    result["issue_code"] = "frontmatter_boundary_invalid"
                    result["body_text_read"] = bool(lines)
                    return result
                if (
                    int(result["frontmatter_bytes_read"])
                    > max_frontmatter_bytes
                ):
                    result["issue_code"] = "frontmatter_limit_exceeded"
                    result["body_text_read"] = True
                    return result
                if re.fullmatch(rb"---[ \t]*\r?\n", line) is not None:
                    break
                lines.append(line)
        after = path.stat()
    except UnicodeError:
        result["issue_code"] = "frontmatter_unicode_error"
        return result
    except OSError:
        result["issue_code"] = "frontmatter_io_error"
        return result

    if (
        before.st_size,
        before.st_mtime_ns,
    ) != (
        after.st_size,
        after.st_mtime_ns,
    ):
        result["issue_code"] = "draft_changed_during_audit"
        return result
    try:
        loaded = load_yaml(b"".join(lines).decode("utf-8"))
    except (UnicodeError, ValueError):
        result["issue_code"] = "frontmatter_yaml_invalid"
        return result
    except Exception:
        result["issue_code"] = "frontmatter_yaml_invalid"
        return result
    if not isinstance(loaded, dict):
        result["issue_code"] = "frontmatter_not_object"
        return result
    result["frontmatter"] = json_safe(loaded)
    result["metadata_readable"] = True
    return result


def inbox_existing_draft_title_check(
    archive_root: Path,
    title: str,
    *,
    max_drafts: int = INBOX_PIPELINE_AUDIT_MAX_DRAFTS,
) -> dict[str, Any]:
    """Return a content-free same-title signal without reading inbox bodies."""

    inbox = archive_internal_path(archive_root, "inbox")
    draft_paths = (
        sorted(inbox.glob("*.md"), key=lambda item: item.name)
        if inbox.is_dir()
        else []
    )
    if len(draft_paths) > max_drafts:
        return {
            "complete": False,
            "drafts_checked": 0,
            "same_title_count": 0,
            "unreadable_frontmatter_count": 0,
            "body_text_read": False,
            "paths_or_titles_echoed": False,
            "reason": "draft_count_exceeds_max_drafts",
        }

    title_key = normalize_compare_text(title)
    same_title_count = 0
    unreadable_count = 0
    body_text_read = False
    for path in draft_paths:
        inspection = _read_bounded_inbox_draft_frontmatter(
            path,
            max_frontmatter_bytes=INBOX_PIPELINE_AUDIT_MAX_FRONTMATTER_BYTES,
        )
        body_text_read = body_text_read or bool(inspection.get("body_text_read"))
        if not inspection.get("metadata_readable"):
            unreadable_count += 1
            continue
        frontmatter = inspection.get("frontmatter")
        existing_title = (
            frontmatter.get("title")
            if isinstance(frontmatter, dict)
            else None
        )
        if (
            isinstance(existing_title, str)
            and title_key
            and normalize_compare_text(existing_title) == title_key
        ):
            same_title_count += 1

    complete = unreadable_count == 0 and not body_text_read
    return {
        "complete": complete,
        "drafts_checked": len(draft_paths),
        "same_title_count": same_title_count,
        "unreadable_frontmatter_count": unreadable_count,
        "body_text_read": body_text_read,
        "paths_or_titles_echoed": False,
        "reason": (
            None
            if complete
            else "one_or_more_draft_frontmatter_records_unreadable"
        ),
    }


def _inbox_pipeline_shape_reason_codes(
    *,
    relative_path: str,
    frontmatter: dict[str, Any],
) -> tuple[str, list[str], dict[str, Any]]:
    provenance = (
        frontmatter.get("provenance")
        if isinstance(frontmatter.get("provenance"), dict)
        else {}
    )
    creation_mode = provenance.get("creation_mode")
    if creation_mode not in INBOX_PIPELINE_AUDIT_AI_CREATION_MODES:
        return (
            "insufficient_evidence",
            ["creation_mode_not_ai_declared"],
            {
                "creation_mode_bucket": (
                    "missing"
                    if creation_mode is None
                    else "not_ai_declared"
                ),
                "draft_creation_present": "draft_creation" in frontmatter,
            },
        )

    shape_reasons: list[str] = []
    optional_approval_reasons: list[str] = []
    if frontmatter.get("status") != "draft":
        shape_reasons.append("status_not_draft")

    zettel_id = frontmatter.get("id")
    if not isinstance(zettel_id, str) or not valid_draft_zettel_id(
        zettel_id.strip()
    ):
        shape_reasons.append("id_missing_or_unsafe")
    elif relative_path != f"inbox/{zettel_id.strip()}.md":
        shape_reasons.append("path_not_current_create_draft_shape")

    promotion = (
        frontmatter.get("promotion")
        if isinstance(frontmatter.get("promotion"), dict)
        else None
    )
    if promotion is None:
        shape_reasons.append("promotion_missing_or_invalid")
    else:
        if promotion.get("stage") != "captured":
            shape_reasons.append("promotion_stage_not_captured")
        if promotion.get("ready_for_promotion") is not False:
            shape_reasons.append("ready_for_promotion_not_false")

    for field in ("created_by", "created_in", "source"):
        value = provenance.get(field)
        if not isinstance(value, str) or not value.strip():
            shape_reasons.append(f"provenance_{field}_missing")

    assisted_by = provenance.get("assisted_by")
    if not (
        isinstance(assisted_by, list)
        and any(isinstance(value, str) and value.strip() for value in assisted_by)
    ):
        shape_reasons.append("assisted_by_missing")

    draft_creation_present = "draft_creation" in frontmatter
    if draft_creation_present:
        draft_creation = frontmatter.get("draft_creation")
        if not isinstance(draft_creation, dict):
            optional_approval_reasons.append("draft_creation_invalid")
        else:
            approved_by = draft_creation.get("approved_by")
            if not isinstance(approved_by, str) or not approved_by.strip():
                optional_approval_reasons.append(
                    "draft_creation_approved_by_missing"
                )
            if draft_creation.get("approval_scope") != "inbox_draft_only":
                optional_approval_reasons.append(
                    "draft_creation_scope_invalid"
                )
            approved_body_sha256 = draft_creation.get(
                "approved_body_sha256"
            )
            if not (
                isinstance(approved_body_sha256, str)
                and re.fullmatch(r"[0-9a-f]{64}", approved_body_sha256)
            ):
                optional_approval_reasons.append(
                    "draft_creation_body_sha256_invalid"
                )

    if shape_reasons:
        classification = "possible_out_of_pipeline_draft"
        reasons = [*shape_reasons, *optional_approval_reasons]
    elif optional_approval_reasons:
        classification = "insufficient_evidence"
        reasons = [
            *optional_approval_reasons,
            "optional_draft_creation_not_authoritative",
        ]
    else:
        classification = "pipeline_shape_consistent"
        reasons = []
    return (
        classification,
        unique_preserve_order(reasons),
        {
            "creation_mode_bucket": "ai_declared",
            "draft_creation_present": draft_creation_present,
        },
    )


def inbox_pipeline_audit(
    archive_root: Path | str,
    *,
    dry_run: bool = False,
    max_drafts: int = INBOX_PIPELINE_AUDIT_MAX_DRAFTS,
    max_findings: int = 100,
    max_frontmatter_bytes: int = INBOX_PIPELINE_AUDIT_MAX_FRONTMATTER_BYTES,
    progress_callback: Callable[
        [str, str, int | None, int | None], None
    ]
    | None = None,
) -> dict[str, Any]:
    require_yaml()
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    warnings: list[str] = []
    if not dry_run:
        blockers.append("dry_run_required")
    if not 1 <= max_drafts <= INBOX_PIPELINE_AUDIT_MAX_DRAFTS:
        blockers.append("max_drafts_out_of_range")
    if not 1 <= max_findings <= INBOX_PIPELINE_AUDIT_MAX_FINDINGS:
        blockers.append("max_findings_out_of_range")
    if not 1024 <= max_frontmatter_bytes <= INBOX_PIPELINE_AUDIT_MAX_FRONTMATTER_BYTES:
        blockers.append("max_frontmatter_bytes_out_of_range")

    inbox = archive_internal_path(root, "inbox")
    draft_paths = (
        sorted(inbox.glob("*.md"), key=lambda item: item.name)
        if inbox.is_dir()
        else []
    )
    discarded_receipts_root = archive_internal_path(
        root,
        "receipts/discarded-drafts",
    )
    discarded_draft_receipt_count = len(
        safe_archive_direct_files(
            discarded_receipts_root,
            "*.discard.json",
            root,
        )
    ) if discarded_receipts_root.is_dir() else 0
    if len(draft_paths) > max_drafts:
        blockers.append("draft_count_exceeds_max_drafts")

    outcomes: list[dict[str, Any]] = []
    findings: list[dict[str, Any]] = []
    counts = {
        "pipeline_shape_consistent": 0,
        "possible_out_of_pipeline_draft": 0,
        "insufficient_evidence": 0,
    }
    publication_readiness = {
        "mint_readiness_gap_count": 0,
        "missing_or_invalid_abstract_count": 0,
        "missing_or_empty_facets_count": 0,
        "created_at_unavailable_count": 0,
        "oldest_draft_age_days": None,
    }
    now_utc = datetime.now(timezone.utc)
    body_text_may_have_been_read = False
    frontmatter_bytes_read = 0
    if not blockers:
        if progress_callback is not None:
            progress_callback(
                "inbox-pipeline-audit", "start", 0, len(draft_paths)
            )
        for index, path in enumerate(draft_paths, start=1):
            relative_path = archive_relative_path(path, root)
            path_sha256 = "sha256:" + hashlib.sha256(
                relative_path.encode("utf-8")
            ).hexdigest()
            inspection = _read_bounded_inbox_draft_frontmatter(
                path,
                max_frontmatter_bytes=max_frontmatter_bytes,
            )
            frontmatter_bytes_read += int(
                inspection.get("frontmatter_bytes_read") or 0
            )
            body_text_read = bool(inspection.get("body_text_read"))
            body_text_may_have_been_read = (
                body_text_may_have_been_read or body_text_read
            )
            if inspection.get("metadata_readable"):
                inspected_frontmatter = inspection["frontmatter"]
                first_read_check = explicit_abstract_publication_check(
                    inspected_frontmatter
                )
                abstract_gap = not bool(
                    first_read_check.get("ready_for_publication")
                )
                facets_value = inspected_frontmatter.get("facets")
                facets_gap = not (
                    isinstance(facets_value, dict) and bool(facets_value)
                )
                if abstract_gap:
                    publication_readiness[
                        "missing_or_invalid_abstract_count"
                    ] += 1
                if facets_gap:
                    publication_readiness[
                        "missing_or_empty_facets_count"
                    ] += 1
                if abstract_gap or facets_gap:
                    publication_readiness["mint_readiness_gap_count"] += 1

                created_at_value = inspected_frontmatter.get("created_at")
                parsed_created_at: datetime | None = None
                if isinstance(created_at_value, str):
                    try:
                        parsed_created_at = datetime.fromisoformat(
                            created_at_value.strip().replace("Z", "+00:00")
                        )
                    except ValueError:
                        parsed_created_at = None
                if parsed_created_at is None:
                    publication_readiness[
                        "created_at_unavailable_count"
                    ] += 1
                else:
                    if parsed_created_at.tzinfo is None:
                        parsed_created_at = parsed_created_at.replace(
                            tzinfo=timezone.utc
                        )
                    age_days = max(
                        0,
                        int(
                            (
                                now_utc
                                - parsed_created_at.astimezone(timezone.utc)
                            ).total_seconds()
                            // 86400
                        ),
                    )
                    current_oldest = publication_readiness[
                        "oldest_draft_age_days"
                    ]
                    if current_oldest is None or age_days > current_oldest:
                        publication_readiness[
                            "oldest_draft_age_days"
                        ] = age_days
                classification, reason_codes, safe_metadata = (
                    _inbox_pipeline_shape_reason_codes(
                        relative_path=relative_path,
                        frontmatter=inspected_frontmatter,
                    )
                )
            else:
                publication_readiness["created_at_unavailable_count"] += 1
                classification = "insufficient_evidence"
                reason_codes = [
                    str(inspection.get("issue_code") or "metadata_unreadable")
                ]
                safe_metadata = {
                    "creation_mode_bucket": "unreadable",
                    "draft_creation_present": None,
                }
            counts[classification] += 1
            outcome = {
                "draft_ref": f"inbox-draft:{index:04d}",
                "path_sha256": path_sha256,
                "classification": classification,
                "reason_codes": reason_codes,
                "metadata": {
                    **safe_metadata,
                    "frontmatter_readable": bool(
                        inspection.get("metadata_readable")
                    ),
                    "body_text_read": body_text_read,
                },
            }
            outcomes.append(outcome)
            if classification != "pipeline_shape_consistent":
                if len(findings) < max_findings:
                    findings.append(outcome)
            if progress_callback is not None and (
                index == 1 or index == len(draft_paths) or index % 250 == 0
            ):
                progress_callback(
                    "inbox-pipeline-audit",
                    "scanned",
                    index,
                    len(draft_paths),
                )
        if progress_callback is not None:
            progress_callback(
                "inbox-pipeline-audit",
                "done",
                len(draft_paths),
                len(draft_paths),
            )

    possible_count = counts["possible_out_of_pipeline_draft"]
    insufficient_count = counts["insufficient_evidence"]
    readiness_gap_count = int(
        publication_readiness["mint_readiness_gap_count"] or 0
    )
    if blockers:
        status = "blocked"
    elif possible_count or readiness_gap_count:
        status = "review_recommended"
        if possible_count:
            warnings.append(
                "One or more AI-declared inbox drafts have metadata inconsistent "
                "with the current archive create-draft output shape."
            )
        if readiness_gap_count:
            warnings.append(
                "One or more inbox drafts are missing publication-critical abstract or facet metadata."
            )
    elif insufficient_count:
        status = "insufficient_evidence"
    elif draft_paths:
        status = "pipeline_shape_consistent"
    else:
        status = "empty"

    finding_total = possible_count + insufficient_count
    return {
        "ok": not blockers,
        "dry_run": True,
        "lifecycle_action": "inbox_pipeline_audit",
        "schema": INBOX_PIPELINE_AUDIT_SCHEMA,
        "status": status,
        "review_recommended": possible_count > 0 or readiness_gap_count > 0,
        "classification_is_proof_of_command_execution": False,
        "summary": {
            "complete": not blockers,
            "top_level_markdown_draft_count": len(draft_paths),
            "drafts_scanned": len(outcomes),
            **counts,
            "finding_count": finding_total,
            "findings_returned": len(findings),
            "findings_truncated": finding_total > len(findings),
            "frontmatter_bytes_read": frontmatter_bytes_read,
            "body_text_may_have_been_read": body_text_may_have_been_read,
            "intentionally_discarded_draft_receipt_count": discarded_draft_receipt_count,
            **publication_readiness,
        },
        "findings": findings,
        "audit_digest": sha256_json_value(outcomes),
        "scope": {
            "included": ["inbox/*.md", "receipts/discarded-drafts/*.discard.json"],
            "nested_paths_scanned": False,
            "max_drafts": max_drafts,
            "max_findings": max_findings,
            "max_frontmatter_bytes_per_draft": max_frontmatter_bytes,
        },
        "redaction": {
            "raw_paths_in_findings": False,
            "zettel_ids_in_findings": False,
            "titles_in_findings": False,
            "actors_in_findings": False,
            "source_values_in_findings": False,
            "body_text_in_findings": False,
            "path_fingerprints_only": True,
        },
        "content_access": {
            "frontmatter_only_when_well_formed": True,
            "body_text_returned": False,
            "provider_api_called": False,
            "model_called": False,
            "network_called": False,
            "index_or_database_read": False,
            "secret_store_or_environment_read": False,
        },
        "write_boundary": {
            "files_written": [],
            "files_deleted": [],
            "files_renamed": [],
            "drafts_repaired": 0,
            "drafts_minted": 0,
        },
        "complexity": {
            "class": "O(top_level_inbox_markdown_drafts * bounded_frontmatter_bytes)",
        },
        "blockers": blockers,
        "warnings": warnings,
        "next_safe_actions": (
            [
                "No possible out-of-pipeline AI draft shape requires review."
            ]
            if not possible_count and not blockers
            else (
                [
                    "Raise max_drafts only within the documented bound and rerun the read-only audit."
                ]
                if "draft_count_exceeds_max_drafts" in blockers
                else [
                    "Review the content-free reason codes and path fingerprints with the archive owner.",
                    "Do not rewrite or delete a historical draft merely to silence this signal.",
                    "If repair is needed, design a separate preview, approval, and receipt workflow.",
                ]
            )
        ),
    }


def _activity_group_request_path(
    root: Path,
    raw_path: str,
    blockers: list[str],
    *,
    request_prefix: str = ACTIVITY_GROUP_MEMBERSHIP_REQUEST_PREFIX,
) -> tuple[str, Path | None]:
    try:
        normalized = normalize_archive_relative_path(raw_path)
    except ArchivePathError:
        blockers.append("request_path_not_archive_relative")
        return "", None
    if (
        not normalized.startswith(request_prefix)
        or not normalized.lower().endswith(".json")
    ):
        blockers.append("request_path_outside_private_activity_group_scratch")
        return normalized, None
    unresolved = root.resolve()
    for part in normalized.split("/"):
        unresolved = unresolved / part
        if unresolved.is_symlink():
            blockers.append("request_path_contains_symbolic_link")
            return normalized, None
    try:
        resolved = resolve_archive_relative_path(root, normalized)
    except ArchivePathError:
        blockers.append("request_path_not_archive_relative")
        return normalized, None
    if resolved.is_symlink() or not resolved.is_file():
        blockers.append("request_file_missing_or_not_regular")
        return normalized, None
    return normalized, resolved


def _read_activity_group_request(
    path: Path,
    blockers: list[str],
) -> tuple[bytes, dict[str, Any] | None]:
    try:
        before = path.stat()
        if before.st_size > ACTIVITY_GROUP_MEMBERSHIP_MAX_REQUEST_BYTES:
            blockers.append("request_file_exceeds_2_mib")
            return b"", None
        with path.open("rb") as handle:
            raw = handle.read(ACTIVITY_GROUP_MEMBERSHIP_MAX_REQUEST_BYTES + 1)
        after = path.stat()
    except OSError:
        blockers.append("request_file_unreadable")
        return b"", None
    if len(raw) > ACTIVITY_GROUP_MEMBERSHIP_MAX_REQUEST_BYTES:
        blockers.append("request_file_exceeds_2_mib")
        return b"", None
    if (
        before.st_size,
        before.st_mtime_ns,
    ) != (
        after.st_size,
        after.st_mtime_ns,
    ):
        blockers.append("request_file_changed_during_read")
        return b"", None
    def reject_duplicate_pairs(
        pairs: list[tuple[str, Any]],
    ) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ActivityGroupRequestDuplicateKeyError(
                    "activity_group_request_duplicate_key"
                )
            result[key] = value
        return result

    try:
        payload = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=reject_duplicate_pairs,
        )
    except ActivityGroupRequestDuplicateKeyError:
        blockers.append("request_json_duplicate_key")
        return raw, None
    except (UnicodeDecodeError, json.JSONDecodeError, RecursionError):
        blockers.append("request_not_valid_utf8_json")
        return raw, None
    if not isinstance(payload, dict):
        blockers.append("request_not_json_object")
        return raw, None
    return raw, payload


def _activity_group_event_coordinate(value: Any) -> tuple[str | None, Any | None]:
    if isinstance(value, datetime):
        if value.tzinfo is None or value.utcoffset() is None:
            return None, None
        return "date_time_with_offset", value
    if isinstance(value, date):
        return "date", value
    if not isinstance(value, str) or not value.strip() or value != value.strip():
        return None, None
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
        try:
            return "date", date.fromisoformat(value)
        except ValueError:
            return None, None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None, None
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        return None, None
    return "date_time_with_offset", parsed


def _read_activity_group_canonical_bytes(
    path: Path,
    *,
    max_bytes: int = ACTIVITY_GROUP_MEMBERSHIP_MAX_CANONICAL_FILE_BYTES,
) -> tuple[bytes, os.stat_result]:
    if path.is_symlink():
        raise ArchiveServiceError("canonical_target_is_symbolic_link")
    effective_max_bytes = max(
        0,
        min(max_bytes, ACTIVITY_GROUP_MEMBERSHIP_MAX_CANONICAL_FILE_BYTES),
    )
    limit_code = (
        "canonical_target_exceeds_16_mib"
        if effective_max_bytes
        == ACTIVITY_GROUP_MEMBERSHIP_MAX_CANONICAL_FILE_BYTES
        else "canonical_target_exceeds_remaining_total_budget"
    )
    before = path.stat()
    if before.st_size > effective_max_bytes:
        raise ArchiveServiceError(limit_code)
    with path.open("rb") as handle:
        raw = handle.read(effective_max_bytes + 1)
    after = path.stat()
    if len(raw) > effective_max_bytes:
        raise ArchiveServiceError(limit_code)
    if (
        before.st_size,
        before.st_mtime_ns,
    ) != (
        after.st_size,
        after.st_mtime_ns,
    ):
        raise ArchiveServiceError("canonical_target_changed_during_read")
    return raw, after


def _parse_activity_group_canonical(
    raw: bytes,
) -> tuple[dict[str, Any], str, str]:
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ArchiveServiceError("canonical_target_not_utf8") from exc
    payload = text[1:] if text.startswith("\ufeff") else text
    match = FRONTMATTER_RE.match(payload)
    if match is None:
        raise ArchiveServiceError("canonical_frontmatter_boundary_invalid")
    try:
        frontmatter = normalize_approval_json_tree(
            load_approval_yaml_without_duplicate_keys(match.group(1))
        )
    except ApprovalYamlDuplicateKeyError as exc:
        raise ArchiveServiceError(
            "canonical_frontmatter_duplicate_key"
        ) from exc
    except Exception as exc:
        raise ArchiveServiceError("canonical_frontmatter_yaml_invalid") from exc
    if not isinstance(frontmatter, dict):
        raise ArchiveServiceError("canonical_frontmatter_not_object")
    return frontmatter, payload, match.group(1)


def _activity_group_current_membership(
    frontmatter: dict[str, Any],
    anchor_zettel_id: str,
) -> tuple[str, list[str]]:
    facets = frontmatter.get("facets")
    if not isinstance(facets, dict):
        return "conflicting_current_shape", []
    if "activity_group" not in facets:
        return "ready_to_add", []
    current = facets.get("activity_group")
    if isinstance(current, str):
        if not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(current):
            return "conflicting_current_shape", []
        if current == anchor_zettel_id:
            return "already_member", [current]
        return "ready_to_add", [current]
    if not isinstance(current, list) or not current:
        return "conflicting_current_shape", []
    normalized: list[str] = []
    seen_memberships: set[str] = set()
    for value in current:
        if (
            not isinstance(value, str)
            or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(value)
            or value in seen_memberships
        ):
            return "conflicting_current_shape", []
        seen_memberships.add(value)
        normalized.append(value)
    if anchor_zettel_id in normalized:
        return "already_member", normalized
    return "ready_to_add", normalized


def _activity_group_candidate_bytes(
    raw: bytes,
    *,
    anchor_zettel_id: str,
    operation: str = "add",
) -> bytes:
    """Replace only the facets YAML node and verify all other content is equal."""

    if operation not in {"add", "remove"}:
        raise ArchiveServiceError("activity_group_operation_unsupported")
    require_yaml()
    frontmatter, payload, frontmatter_source = _parse_activity_group_canonical(raw)
    facets = frontmatter.get("facets")
    if not isinstance(facets, dict):
        raise ArchiveServiceError("facets_not_object")
    state, current = _activity_group_current_membership(
        frontmatter, anchor_zettel_id
    )
    updated_facets = copy.deepcopy(facets)
    if operation == "add":
        if state != "ready_to_add":
            raise ArchiveServiceError("activity_group_not_ready_to_add")
        if not current:
            updated_facets["activity_group"] = anchor_zettel_id
        elif len(current) == 1 and isinstance(
            facets.get("activity_group"), str
        ):
            updated_facets["activity_group"] = [
                current[0],
                anchor_zettel_id,
            ]
        else:
            updated_facets["activity_group"] = [*current, anchor_zettel_id]
    else:
        if state != "already_member":
            raise ArchiveServiceError("activity_group_not_ready_to_remove")
        remaining = [
            membership
            for membership in current
            if membership != anchor_zettel_id
        ]
        if remaining:
            # Preserve both list shape and relative order. Collapsing a
            # one-item list to a scalar would be an unrelated normalization.
            updated_facets["activity_group"] = remaining
        else:
            updated_facets.pop("activity_group", None)

    try:
        node = yaml.compose(frontmatter_source)  # type: ignore[union-attr]
    except Exception as exc:
        raise ArchiveServiceError("canonical_frontmatter_yaml_invalid") from exc
    facet_nodes: list[tuple[Any, Any]] = []
    if node is not None and getattr(node, "id", None) == "mapping":
        for key_node, value_node in getattr(node, "value", []):
            if (
                getattr(key_node, "id", None) == "scalar"
                and getattr(key_node, "value", None) == "facets"
            ):
                facet_nodes.append((key_node, value_node))
    if (
        len(facet_nodes) != 1
        or getattr(facet_nodes[0][1], "id", None) != "mapping"
    ):
        raise ArchiveServiceError("facets_yaml_node_not_unique_mapping")
    key_node, value_node = facet_nodes[0]
    start = int(key_node.start_mark.index)
    end = int(value_node.end_mark.index)
    line_break = "\r\n" if "\r\n" in frontmatter_source else "\n"
    replacement = dump_yaml({"facets": updated_facets}).rstrip("\n")
    replacement = replacement.replace("\n", line_break)
    if not frontmatter_source[end:].startswith(("\r", "\n")):
        replacement += line_break
    candidate_frontmatter = (
        frontmatter_source[:start] + replacement + frontmatter_source[end:]
    )
    match = FRONTMATTER_RE.match(payload)
    if match is None:
        raise ArchiveServiceError("canonical_frontmatter_boundary_invalid")
    candidate_payload = (
        payload[: match.start(1)]
        + candidate_frontmatter
        + payload[match.end(1) :]
    )
    candidate_text = ("\ufeff" if raw.startswith(b"\xef\xbb\xbf") else "")
    candidate_text += candidate_payload
    candidate_bytes = candidate_text.encode("utf-8")

    candidate_frontmatter_doc, candidate_payload_check, _source = (
        _parse_activity_group_canonical(candidate_bytes)
    )
    expected_frontmatter = copy.deepcopy(frontmatter)
    expected_frontmatter["facets"] = updated_facets
    if candidate_frontmatter_doc != expected_frontmatter:
        raise ArchiveServiceError("activity_group_candidate_frontmatter_mismatch")
    original_match = FRONTMATTER_RE.match(payload)
    candidate_match = FRONTMATTER_RE.match(candidate_payload_check)
    if (
        original_match is None
        or candidate_match is None
        or payload[original_match.end() :]
        != candidate_payload_check[candidate_match.end() :]
    ):
        raise ArchiveServiceError("activity_group_candidate_body_changed")
    if candidate_bytes == raw:
        raise ArchiveServiceError("activity_group_candidate_bytes_unchanged")
    return candidate_bytes


def _activity_group_membership_plan(
    archive_root: Path | str,
    *,
    request_path: str,
    dry_run: bool = False,
    max_members: int = ACTIVITY_GROUP_MEMBERSHIP_MAX_MEMBERS,
    progress_callback: Callable[[str, str, int | None, int | None], None]
    | None = None,
    operation: str,
    request_schema: str,
    request_prefix: str,
    plan_schema: str,
    future_write_implemented: bool,
    planned_write_command: str,
) -> dict[str, Any]:
    """Validate one explicit event-membership add/remove request without writes."""

    if operation not in {"add", "remove"}:
        raise ArchiveServiceError("activity_group_operation_unsupported")
    progress_prefix = (
        "activity-group-removal"
        if operation == "remove"
        else "activity-group"
    )
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []
    if not dry_run:
        blockers.append("dry_run_required")
    requested_max_members = int(max_members)
    effective_max_members = max(
        1,
        min(requested_max_members, ACTIVITY_GROUP_MEMBERSHIP_MAX_MEMBERS),
    )
    if requested_max_members != effective_max_members:
        blockers.append("max_members_out_of_range")

    _normalized_request_path, request_file = _activity_group_request_path(
        root,
        request_path,
        blockers,
        request_prefix=request_prefix,
    )
    request_bytes = b""
    request_doc: dict[str, Any] | None = None
    if request_file is not None:
        if progress_callback is not None:
            progress_callback(
                f"{progress_prefix}-request",
                "start",
                0,
                int(request_file.stat().st_size),
            )
        request_bytes, request_doc = _read_activity_group_request(
            request_file, blockers
        )
        if progress_callback is not None:
            progress_callback(
                f"{progress_prefix}-request",
                "done",
                len(request_bytes),
                len(request_bytes),
            )

    anchor_zettel_id: str | None = None
    member_zettel_ids: list[str] = []
    requested_member_count = 0
    if request_doc is not None:
        allowed_fields = {
            "schema",
            "archive_id",
            "anchor_zettel_id",
            "member_zettel_ids",
        }
        if set(request_doc) - allowed_fields:
            blockers.append("request_contains_unsupported_fields")
        if request_doc.get("schema") != request_schema:
            blockers.append("request_schema_unsupported")
        if request_doc.get("archive_id") != archive_id:
            blockers.append("request_archive_id_mismatch")
        raw_anchor = request_doc.get("anchor_zettel_id")
        if (
            not isinstance(raw_anchor, str)
            or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(raw_anchor)
        ):
            blockers.append("anchor_zettel_id_invalid")
        else:
            anchor_zettel_id = raw_anchor
        raw_members = request_doc.get("member_zettel_ids")
        if isinstance(raw_members, list):
            requested_member_count = len(raw_members)
        if not isinstance(raw_members, list) or not raw_members:
            blockers.append("member_zettel_ids_must_be_nonempty_list")
        elif len(raw_members) > effective_max_members:
            blockers.append("request_exceeds_max_members")
        else:
            seen_members: set[str] = set()
            for value in raw_members:
                if (
                    not isinstance(value, str)
                    or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(value)
                ):
                    blockers.append("member_zettel_id_invalid")
                    continue
                if value in seen_members:
                    blockers.append("member_zettel_id_duplicate")
                    continue
                seen_members.add(value)
                member_zettel_ids.append(value)
            if (
                anchor_zettel_id is not None
                and anchor_zettel_id in seen_members
            ):
                blockers.append("anchor_cannot_be_member")

    request_sha256 = (
        "sha256:" + hashlib.sha256(request_bytes).hexdigest()
        if request_bytes
        else None
    )
    anchor_result: dict[str, Any] = {
        "status": "not_checked",
        "blocker_codes": [],
        "title_present": False,
        "event_start_present": False,
        "event_end_present": False,
        "event_time_granularity": None,
        "current_file_sha256": None,
    }
    total_canonical_bytes = 0

    def resolve_requested_zettel(zettel_id: str) -> Path:
        try:
            direct = root / "zettels" / f"{zettel_id}.md"
            if (
                direct.is_symlink()
                or not is_path_within_root(direct, root)
                or not direct.is_file()
            ):
                raise ArchiveServiceError(
                    "requested_zettel_missing_standard_canonical_path"
                )
            return direct
        except (ArchiveServiceError, ArchivePathError, OSError) as exc:
            # Do not fall back to an archive-wide id scan: one explicit request
            # must read only its standard zettels/<id>.md targets. Keep the
            # error content-free so the private requested id is never echoed.
            raise ArchiveServiceError(
                "requested_zettel_missing_standard_canonical_path"
            ) from exc

    if anchor_zettel_id is not None and not blockers:
        anchor_blockers: list[str] = []
        try:
            anchor_path = resolve_requested_zettel(anchor_zettel_id)
            anchor_relative = archive_relative_path(anchor_path, root)
            if (
                not anchor_relative.startswith("zettels/")
                or anchor_path.is_symlink()
            ):
                raise ArchiveServiceError("anchor_not_plain_canonical_path")
            anchor_bytes, _anchor_stat = _read_activity_group_canonical_bytes(
                anchor_path
            )
            total_canonical_bytes += len(anchor_bytes)
            anchor_frontmatter, _payload, _source = (
                _parse_activity_group_canonical(anchor_bytes)
            )
            if anchor_frontmatter.get("id") != anchor_zettel_id:
                anchor_blockers.append("anchor_frontmatter_identity_mismatch")
            if anchor_frontmatter.get("status") != "canonical":
                anchor_blockers.append("anchor_status_not_canonical")
            if anchor_frontmatter.get("kind") != "record_note":
                anchor_blockers.append("anchor_kind_not_record_note")
            title = anchor_frontmatter.get("title")
            title_present = isinstance(title, str) and bool(title.strip())
            if not title_present:
                anchor_blockers.append("anchor_title_missing")
            facets = anchor_frontmatter.get("facets")
            if not isinstance(facets, dict):
                anchor_blockers.append("anchor_facets_not_object")
                facets = {}
            if facets.get("record_type") != "event":
                anchor_blockers.append("anchor_record_type_not_event")
            start_kind, start_value = _activity_group_event_coordinate(
                facets.get("event_start")
            )
            if start_kind is None:
                anchor_blockers.append("anchor_event_start_invalid_or_missing")
            end_present = "event_end" in facets
            end_kind: str | None = None
            end_value: Any | None = None
            if end_present:
                end_kind, end_value = _activity_group_event_coordinate(
                    facets.get("event_end")
                )
                if end_kind is None:
                    anchor_blockers.append("anchor_event_end_invalid")
                elif start_kind != end_kind:
                    anchor_blockers.append(
                        "anchor_event_start_end_granularity_mismatch"
                    )
                elif (
                    start_value is not None
                    and end_value is not None
                    and end_value <= start_value
                ):
                    anchor_blockers.append(
                        "anchor_event_end_not_after_start"
                    )
            anchor_result = {
                "status": (
                    "ready_for_review" if not anchor_blockers else "blocked"
                ),
                "blocker_codes": unique_preserve_order(anchor_blockers),
                "title_present": title_present,
                "event_start_present": start_kind is not None,
                "event_end_present": end_present,
                "event_time_granularity": start_kind,
                "current_file_sha256": (
                    "sha256:" + hashlib.sha256(anchor_bytes).hexdigest()
                ),
            }
        except ArchiveServiceError as exc:
            anchor_result = {
                **anchor_result,
                "status": "blocked",
                "blocker_codes": [str(exc)],
            }
        except (ArchivePathError, OSError, ValueError):
            anchor_result = {
                **anchor_result,
                "status": "blocked",
                "blocker_codes": ["anchor_unavailable_or_unreadable"],
            }
        if anchor_result["blocker_codes"]:
            blockers.append("anchor_validation_blocked")

    item_results: list[dict[str, Any]] = []
    plan_fingerprint_items: list[dict[str, Any]] = []
    ready_action_count = 0
    no_op_count = 0
    blocked_member_count = 0
    if member_zettel_ids and anchor_zettel_id is not None and not blockers:
        if progress_callback is not None:
            progress_callback(
                f"{progress_prefix}-members",
                "start",
                0,
                len(member_zettel_ids),
            )
        for index, member_zettel_id in enumerate(member_zettel_ids):
            item_blockers: list[str] = []
            state = "blocked"
            before_sha256: str | None = None
            after_sha256: str | None = None
            existing_membership_count: int | None = None
            try:
                member_path = resolve_requested_zettel(member_zettel_id)
                member_relative = archive_relative_path(member_path, root)
                if (
                    not member_relative.startswith("zettels/")
                    or member_path.is_symlink()
                ):
                    raise ArchiveServiceError(
                        "member_not_plain_canonical_path"
                    )
                remaining_total_bytes = (
                    ACTIVITY_GROUP_MEMBERSHIP_MAX_TOTAL_CANONICAL_BYTES
                    - total_canonical_bytes
                )
                member_bytes, _member_stat = (
                    _read_activity_group_canonical_bytes(
                        member_path,
                        max_bytes=remaining_total_bytes,
                    )
                )
                total_canonical_bytes += len(member_bytes)
                member_frontmatter, _payload, _source = (
                    _parse_activity_group_canonical(member_bytes)
                )
                if member_frontmatter.get("id") != member_zettel_id:
                    item_blockers.append(
                        "member_frontmatter_identity_mismatch"
                    )
                if member_frontmatter.get("status") != "canonical":
                    item_blockers.append("member_status_not_canonical")
                current_state, current_memberships = (
                    _activity_group_current_membership(
                        member_frontmatter, anchor_zettel_id
                    )
                )
                existing_membership_count = len(current_memberships)
                before_sha256 = (
                    "sha256:" + hashlib.sha256(member_bytes).hexdigest()
                )
                if current_state == "conflicting_current_shape":
                    item_blockers.append(
                        "activity_group_current_shape_conflicts_with_anchor_contract"
                    )
                elif operation == "add":
                    if current_state == "already_member":
                        state = "already_member"
                        after_sha256 = before_sha256
                        no_op_count += 1
                    elif not item_blockers:
                        candidate_bytes = _activity_group_candidate_bytes(
                            member_bytes,
                            anchor_zettel_id=anchor_zettel_id,
                            operation="add",
                        )
                        after_sha256 = (
                            "sha256:"
                            + hashlib.sha256(candidate_bytes).hexdigest()
                        )
                        state = "ready_to_add"
                        ready_action_count += 1
                elif (
                    current_state == "already_member"
                    and not item_blockers
                ):
                    candidate_bytes = _activity_group_candidate_bytes(
                        member_bytes,
                        anchor_zettel_id=anchor_zettel_id,
                        operation="remove",
                    )
                    after_sha256 = (
                        "sha256:"
                        + hashlib.sha256(candidate_bytes).hexdigest()
                    )
                    state = "ready_to_remove"
                    ready_action_count += 1
                elif not item_blockers:
                    state = "already_absent"
                    after_sha256 = before_sha256
                    no_op_count += 1
            except ArchiveServiceError as exc:
                item_blockers.append(str(exc))
            except (ArchivePathError, OSError, ValueError):
                item_blockers.append("member_unavailable_or_unreadable")
            item_blockers = unique_preserve_order(item_blockers)
            if item_blockers:
                state = "blocked"
                blocked_member_count += 1
            item_result = {
                "row_index": index,
                "status": state,
                "blocker_codes": item_blockers,
                "existing_membership_count": existing_membership_count,
                "current_file_sha256": before_sha256,
                "proposed_file_sha256": after_sha256,
                "body_text_returned": False,
            }
            item_results.append(item_result)
            plan_fingerprint_items.append(
                {
                    "row_index": index,
                    "status": state,
                    "blocker_codes": item_blockers,
                    "current_file_sha256": before_sha256,
                    "proposed_file_sha256": after_sha256,
                }
            )
            if progress_callback is not None and (
                index == 0
                or index + 1 == len(member_zettel_ids)
                or (index + 1) % 100 == 0
            ):
                progress_callback(
                    f"{progress_prefix}-members",
                    "scanned",
                    index + 1,
                    len(member_zettel_ids),
                )
        if progress_callback is not None:
            progress_callback(
                f"{progress_prefix}-members",
                "done",
                len(member_zettel_ids),
                len(member_zettel_ids),
            )

    if blocked_member_count:
        blockers.append("one_or_more_members_blocked")
    blockers = unique_preserve_order(blockers)
    warnings = unique_preserve_order(warnings)
    ready = not blockers
    review_plan_sha256 = sha256_json_value(
        {
            "schema": plan_schema,
            "archive_id": archive_id,
            "request_sha256": request_sha256,
            "anchor_current_file_sha256": anchor_result.get(
                "current_file_sha256"
            ),
            "items": plan_fingerprint_items,
        }
    )
    action_counts = (
        {
            "ready_to_add_count": ready_action_count,
            "already_member_count": no_op_count,
        }
        if operation == "add"
        else {
            "ready_to_remove_count": ready_action_count,
            "already_absent_count": no_op_count,
        }
    )
    return {
        "ok": ready,
        "dry_run": True,
        "schema": plan_schema,
        "lifecycle_action": (
            "activity_group_membership_removal_plan"
            if operation == "remove"
            else "activity_group_membership_plan"
        ),
        "status": "ready_for_human_review" if ready else "blocked",
        "archive_id": archive_id,
        "request": {
            "schema": request_schema,
            "sha256": request_sha256,
            "path_policy": request_prefix + "<private>.json",
            "path_echoed": False,
            "bytes_read": len(request_bytes),
            "member_count": requested_member_count,
            "valid_member_id_count": len(member_zettel_ids),
            "anchor_zettel_id_echoed": False,
            "member_zettel_ids_echoed": False,
            "contains_private_zettel_ids": True,
            "tracking_policy": "private_ai_working_file_do_not_commit",
        },
        "anchor": anchor_result,
        "summary": {
            "complete": ready,
            "requested_member_count": requested_member_count,
            "valid_member_id_count": len(member_zettel_ids),
            "inspected_member_count": len(item_results),
            **action_counts,
            "blocked_member_count": blocked_member_count,
            "max_members": effective_max_members,
            "canonical_bytes_read": total_canonical_bytes,
            "max_canonical_file_bytes": (
                ACTIVITY_GROUP_MEMBERSHIP_MAX_CANONICAL_FILE_BYTES
            ),
            "max_total_canonical_bytes": (
                ACTIVITY_GROUP_MEMBERSHIP_MAX_TOTAL_CANONICAL_BYTES
            ),
        },
        "items": item_results,
        "review_plan_sha256": review_plan_sha256,
        "event_anchor_contract": {
            "representation": "canonical_record_note_anchor",
            "identifier_field": "zettel.id",
            "name_field": "zettel.title",
            "record_type_facet": "event",
            "start_facet": "event_start",
            "end_facet": "event_end",
            "start_inclusive": True,
            "end_non_inclusive": True,
            "accepted_time_values": [
                "ISO_8601_date",
                "ISO_8601_datetime_with_explicit_offset",
            ],
        },
        "membership_contract": {
            "operation": operation,
            "member_field": "facets.activity_group",
            "member_value": "event_anchor_zettel_id",
            "multiple_memberships_supported": True,
            "membership_is_undirected_co_membership": True,
            "membership_implies_sequence": False,
            "membership_implies_continuation": False,
            "membership_implies_source_or_derivation": False,
            "membership_was_inferred": False,
            "request_is_explicit_human_selected_input": True,
            "only_named_anchor_is_changed": True,
            "other_activity_group_memberships_preserved": True,
            "body_and_updated_at_preserved": True,
        },
        "claim_boundary": {
            "checked": (
                "Only the explicit request ids against exact current live "
                "canonical zettel bytes and the event-anchor shape."
            ),
            "not_checked": [
                "Whether search results belong to the event.",
                "Whether the human selected every correct member.",
                "Any zettel id absent from the request.",
                "Whether event membership caused or derived the zettel.",
            ],
        },
        "index_evidence": {
            "index_used": False,
            "index_freshness": "not_checked_not_required_for_live_file_validation",
            "live_file_bytes_are_authoritative_for_this_plan": True,
        },
        "write_boundary": {
            "write_implemented": False,
            "files_written": [],
            "zettels_changed": 0,
            "facets_changed": 0,
            "receipts_written": 0,
        },
        "privacy_guards": {
            "request_path_echoed": False,
            "zettel_ids_echoed": False,
            "zettel_paths_echoed": False,
            "zettel_titles_echoed": False,
            "frontmatter_values_echoed": False,
            "body_text_read": bool(total_canonical_bytes),
            "body_text_echoed": False,
            "provider_urls_echoed": False,
            "absolute_local_paths_echoed": False,
            "account_ids_echoed": False,
            "emails_echoed": False,
            "tokens_echoed": False,
            "secret_values_echoed": False,
            "provider_api_called": False,
            "model_called": False,
            "network_called": False,
            "writes": False,
        },
        "future_write_preview": {
            "eligible_member_count": ready_action_count if ready else 0,
            "implemented_now": future_write_implemented,
            "official_command": (
                planned_write_command if future_write_implemented else None
            ),
            "planned_command": (
                None if future_write_implemented else planned_write_command
            ),
        },
        "would_change": [],
        "blockers": blockers,
        "warnings": warnings,
        "next_safe_actions": (
            [
                "Fix only the content-free blocker codes in the private request or current canonical shapes, then rerun this read-only plan."
            ]
            if blockers
            else (
                [
                    "Review the anchor and ordered member selection with the archive owner.",
                    "Keep this request and review-plan digest as evidence, then preview the dedicated approval-gated activity-group-membership-write command.",
                ]
                if operation == "add"
                else [
                    "Review every named removal and every already-absent row with the archive owner.",
                    (
                        "Keep this private request and review-plan digest as evidence, then preview the dedicated approval-gated activity-group-membership-removal-write command."
                        if future_write_implemented
                        else "Keep this private request and review-plan digest as evidence. The approval-gated activity-group-membership-removal-write command is not implemented in this release."
                    ),
                ]
            )
        ),
    }


def activity_group_membership_plan(
    archive_root: Path | str,
    *,
    request_path: str,
    dry_run: bool = False,
    max_members: int = ACTIVITY_GROUP_MEMBERSHIP_MAX_MEMBERS,
    progress_callback: Callable[[str, str, int | None, int | None], None]
    | None = None,
) -> dict[str, Any]:
    """Validate an explicit event anchor and member-add list without writes."""

    return _activity_group_membership_plan(
        archive_root,
        request_path=request_path,
        dry_run=dry_run,
        max_members=max_members,
        progress_callback=progress_callback,
        operation="add",
        request_schema=ACTIVITY_GROUP_MEMBERSHIP_REQUEST_SCHEMA,
        request_prefix=ACTIVITY_GROUP_MEMBERSHIP_REQUEST_PREFIX,
        plan_schema=ACTIVITY_GROUP_MEMBERSHIP_PLAN_SCHEMA,
        future_write_implemented=True,
        planned_write_command="archive activity-group-membership-write",
    )


def activity_group_membership_removal_plan(
    archive_root: Path | str,
    *,
    request_path: str,
    dry_run: bool = False,
    max_members: int = ACTIVITY_GROUP_MEMBERSHIP_MAX_MEMBERS,
    progress_callback: Callable[[str, str, int | None, int | None], None]
    | None = None,
) -> dict[str, Any]:
    """Plan removal of one named event anchor from explicit canonical members."""

    return _activity_group_membership_plan(
        archive_root,
        request_path=request_path,
        dry_run=dry_run,
        max_members=max_members,
        progress_callback=progress_callback,
        operation="remove",
        request_schema=ACTIVITY_GROUP_MEMBERSHIP_REMOVAL_REQUEST_SCHEMA,
        request_prefix=ACTIVITY_GROUP_MEMBERSHIP_REMOVAL_REQUEST_PREFIX,
        plan_schema=ACTIVITY_GROUP_MEMBERSHIP_REMOVAL_PLAN_SCHEMA,
        future_write_implemented=True,
        planned_write_command=(
            "archive activity-group-membership-removal-write"
        ),
    )


def _activity_group_private_root(root: Path) -> Path:
    canonical_root = root.resolve()
    return canonical_root.joinpath(
        *PurePosixPath(
            ACTIVITY_GROUP_MEMBERSHIP_REQUEST_PREFIX.rstrip("/")
        ).parts
    )


def _activity_group_removal_private_root(root: Path) -> Path:
    canonical_root = root.resolve()
    return canonical_root.joinpath(
        *PurePosixPath(
            ACTIVITY_GROUP_MEMBERSHIP_REMOVAL_REQUEST_PREFIX.rstrip("/")
        ).parts
    )


def _activity_group_operation_private_root(
    root: Path,
    operation_contract: _ActivityGroupMembershipOperationContract,
) -> Path:
    return (
        _activity_group_removal_private_root(root)
        if operation_contract.operation == "remove"
        else _activity_group_private_root(root)
    )


def _activity_group_membership_receipt_relative_path(
    request_sha256: str,
    operation_contract: _ActivityGroupMembershipOperationContract,
) -> str:
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", request_sha256):
        raise ValueError("activity_group_request_sha256_invalid")
    digest = request_sha256.removeprefix("sha256:")
    return (
        f"{operation_contract.receipts_dir}/"
        f"{digest}{operation_contract.receipt_suffix}"
    )


def activity_group_membership_receipt_relative_path(
    request_sha256: str,
) -> str:
    return _activity_group_membership_receipt_relative_path(
        request_sha256,
        ACTIVITY_GROUP_MEMBERSHIP_ADD,
    )


def activity_group_membership_removal_receipt_relative_path(
    request_sha256: str,
) -> str:
    return _activity_group_membership_receipt_relative_path(
        request_sha256,
        ACTIVITY_GROUP_MEMBERSHIP_REMOVE,
    )


def _activity_group_membership_receipt_path(
    root: Path,
    request_sha256: str,
    operation_contract: _ActivityGroupMembershipOperationContract,
) -> Path:
    relative = _activity_group_membership_receipt_relative_path(
        request_sha256,
        operation_contract,
    )
    canonical_root = root.resolve()
    return canonical_root.joinpath(*PurePosixPath(relative).parts)


def activity_group_membership_receipt_path(
    root: Path,
    request_sha256: str,
) -> Path:
    return _activity_group_membership_receipt_path(
        root,
        request_sha256,
        ACTIVITY_GROUP_MEMBERSHIP_ADD,
    )


def activity_group_membership_removal_receipt_path(
    root: Path,
    request_sha256: str,
) -> Path:
    return _activity_group_membership_receipt_path(
        root,
        request_sha256,
        ACTIVITY_GROUP_MEMBERSHIP_REMOVE,
    )


def activity_group_membership_receipt_path_is_safe(
    root: Path,
    receipt_path: Path,
) -> bool:
    try:
        return bool(
            not zet_revision_path_has_symlink_component(
                root,
                receipt_path,
            )
            and is_path_within_root(receipt_path, root)
        )
    except (ArchivePathError, OSError):
        return False


def activity_group_membership_transaction_journal_path(
    root: Path,
    request_sha256: str,
) -> Path:
    return _activity_group_membership_transaction_journal_path(
        root,
        request_sha256,
        ACTIVITY_GROUP_MEMBERSHIP_ADD,
    )


def activity_group_membership_removal_transaction_journal_path(
    root: Path,
    request_sha256: str,
) -> Path:
    return _activity_group_membership_transaction_journal_path(
        root,
        request_sha256,
        ACTIVITY_GROUP_MEMBERSHIP_REMOVE,
    )


def _activity_group_membership_transaction_journal_path(
    root: Path,
    request_sha256: str,
    operation_contract: _ActivityGroupMembershipOperationContract,
) -> Path:
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", request_sha256):
        raise ValueError("activity_group_request_sha256_invalid")
    digest = request_sha256.removeprefix("sha256:")
    return _activity_group_operation_private_root(
        root,
        operation_contract,
    ) / (
        f".{digest}{operation_contract.journal_suffix}"
    )


@contextmanager
def _activity_group_bound_directory_chain(
    root: Path,
    target: Path,
    *,
    create: bool = False,
) -> Iterable[dict[str, Any]]:
    """Bind every component from the archive root to one directory."""

    canonical_root = root.resolve()
    try:
        relative = target.relative_to(canonical_root)
    except ValueError as exc:
        raise OSError(
            "activity_group_transaction_scan_root_outside_archive"
        ) from exc

    if os.name != "nt":
        flags = os.O_RDONLY
        flags |= getattr(os, "O_DIRECTORY", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        descriptors: list[int] = []
        identities: list[tuple[Path, tuple[int, int]]] = []
        try:
            root_descriptor = os.open(canonical_root, flags)
            descriptors.append(root_descriptor)
            root_stat = os.fstat(root_descriptor)
            identities.append(
                (
                    canonical_root,
                    (root_stat.st_dev, root_stat.st_ino),
                )
            )
            current_descriptor = root_descriptor
            current_path = canonical_root
            for part in relative.parts:
                try:
                    entry_stat = os.stat(
                        part,
                        dir_fd=current_descriptor,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    if not create:
                        raise
                    os.mkdir(
                        part,
                        mode=0o700,
                        dir_fd=current_descriptor,
                    )
                    entry_stat = os.stat(
                        part,
                        dir_fd=current_descriptor,
                        follow_symlinks=False,
                    )
                if (
                    stat.S_ISLNK(entry_stat.st_mode)
                    or not stat.S_ISDIR(entry_stat.st_mode)
                ):
                    raise OSError(
                        "activity_group_transaction_scan_root_unsafe"
                    )
                child_descriptor = os.open(
                    part,
                    flags,
                    dir_fd=current_descriptor,
                )
                child_stat = os.fstat(child_descriptor)
                if (
                    child_stat.st_dev,
                    child_stat.st_ino,
                ) != (
                    entry_stat.st_dev,
                    entry_stat.st_ino,
                ):
                    os.close(child_descriptor)
                    raise OSError(
                        "activity_group_transaction_scan_root_changed"
                    )
                descriptors.append(child_descriptor)
                current_descriptor = child_descriptor
                current_path = current_path / part
                identities.append(
                    (
                        current_path,
                        (child_stat.st_dev, child_stat.st_ino),
                    )
                )
            yield {
                "path": target,
                "descriptor": current_descriptor,
                "windows_handles": None,
            }
            for path, expected_identity in identities:
                current_stat = os.stat(
                    path,
                    follow_symlinks=False,
                )
                if (
                    current_stat.st_dev,
                    current_stat.st_ino,
                ) != expected_identity:
                    raise OSError(
                        "activity_group_transaction_scan_root_changed"
                    )
        finally:
            for descriptor in reversed(descriptors):
                os.close(descriptor)
        return

    # Windows path operations cannot consume a directory descriptor. Hold a
    # FILE_LIST_DIRECTORY handle without delete sharing for the archive root
    # and every descendant component. This prevents a checked parent from
    # being replaced while a child or the final scan is opened.
    import ctypes
    from ctypes import wintypes

    class ByHandleFileInformation(ctypes.Structure):
        _fields_ = [
            ("dwFileAttributes", wintypes.DWORD),
            ("ftCreationTime", wintypes.FILETIME),
            ("ftLastAccessTime", wintypes.FILETIME),
            ("ftLastWriteTime", wintypes.FILETIME),
            ("dwVolumeSerialNumber", wintypes.DWORD),
            ("nFileSizeHigh", wintypes.DWORD),
            ("nFileSizeLow", wintypes.DWORD),
            ("nNumberOfLinks", wintypes.DWORD),
            ("nFileIndexHigh", wintypes.DWORD),
            ("nFileIndexLow", wintypes.DWORD),
        ]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    create_file = kernel32.CreateFileW
    create_file.argtypes = [
        wintypes.LPCWSTR,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.LPVOID,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.HANDLE,
    ]
    create_file.restype = wintypes.HANDLE
    get_information = kernel32.GetFileInformationByHandle
    get_information.argtypes = [
        wintypes.HANDLE,
        ctypes.POINTER(ByHandleFileInformation),
    ]
    get_information.restype = wintypes.BOOL
    read_file = kernel32.ReadFile
    read_file.argtypes = [
        wintypes.HANDLE,
        ctypes.c_void_p,
        wintypes.DWORD,
        ctypes.POINTER(wintypes.DWORD),
        ctypes.c_void_p,
    ]
    read_file.restype = wintypes.BOOL
    close_handle = kernel32.CloseHandle
    close_handle.argtypes = [wintypes.HANDLE]
    close_handle.restype = wintypes.BOOL

    file_share_read = 0x00000001
    file_share_write = 0x00000002
    file_list_directory = 0x00000001
    open_existing = 3
    file_flag_open_reparse_point = 0x00200000
    file_flag_backup_semantics = 0x02000000
    invalid_handle = wintypes.HANDLE(-1).value
    file_attribute_directory = 0x00000010
    file_attribute_reparse_point = 0x00000400
    handles: list[Any] = []
    identities: list[tuple[Path, tuple[int, int]]] = []

    def open_bound_directory(path: Path) -> Any:
        entry_stat = os.stat(path, follow_symlinks=False)
        reparse_flag = getattr(
            stat,
            "FILE_ATTRIBUTE_REPARSE_POINT",
            0,
        )
        if (
            not stat.S_ISDIR(entry_stat.st_mode)
            or (
                reparse_flag
                and getattr(
                    entry_stat,
                    "st_file_attributes",
                    0,
                )
                & reparse_flag
            )
        ):
            raise OSError(
                "activity_group_transaction_scan_root_unsafe"
            )
        handle = create_file(
            str(path),
            file_list_directory,
            file_share_read | file_share_write,
            None,
            open_existing,
            (
                file_flag_open_reparse_point
                | file_flag_backup_semantics
            ),
            None,
        )
        if handle == invalid_handle:
            raise ctypes.WinError(ctypes.get_last_error())
        information = ByHandleFileInformation()
        if not get_information(handle, ctypes.byref(information)):
            error = ctypes.WinError(ctypes.get_last_error())
            close_handle(handle)
            raise error
        opened_file_index = (
            int(information.nFileIndexHigh) << 32
        ) | int(information.nFileIndexLow)
        if (
            opened_file_index != entry_stat.st_ino
            or not (
                information.dwFileAttributes
                & file_attribute_directory
            )
            or (
                information.dwFileAttributes
                & file_attribute_reparse_point
            )
        ):
            close_handle(handle)
            raise OSError(
                "activity_group_transaction_scan_root_changed"
            )
        identities.append(
            (
                path,
                (entry_stat.st_dev, entry_stat.st_ino),
            )
        )
        return handle

    try:
        current_path = canonical_root
        handles.append(open_bound_directory(current_path))
        for part in relative.parts:
            current_path = current_path / part
            if create and not current_path.exists():
                os.mkdir(current_path, mode=0o700)
            handles.append(open_bound_directory(current_path))
        yield {
            "path": target,
            "descriptor": None,
            "windows_handles": handles,
        }
        for path, expected_identity in identities:
            current_stat = os.stat(path, follow_symlinks=False)
            if (
                current_stat.st_dev,
                current_stat.st_ino,
            ) != expected_identity:
                raise OSError(
                    "activity_group_transaction_scan_root_changed"
                )
    finally:
        for handle in reversed(handles):
            close_handle(handle)


@contextmanager
def activity_group_transaction_scan_entries(
    root: Path,
    private_root: Path,
) -> Iterable[os.DirEntry[str]]:
    with _activity_group_bound_directory_chain(
        root,
        private_root,
    ) as binding:
        scan_target = (
            binding["descriptor"]
            if binding["descriptor"] is not None
            else private_root
        )
        with os.scandir(scan_target) as entries:
            yield entries


def scan_activity_group_transaction_evidence(
    root: Path,
    *,
    max_entries: int = (
        ACTIVITY_GROUP_MEMBERSHIP_MAX_TRANSACTION_SCAN_ENTRIES
    ),
) -> dict[str, Any]:
    """Boundedly discover unresolved add/removal journals without reading them."""

    blockers: list[str] = []
    journal_paths: list[Path] = []
    scanned_entry_count = 0
    scan_complete = True
    roots = (
        _activity_group_private_root(root),
        _activity_group_removal_private_root(root),
    )
    suffixes = (
        ACTIVITY_GROUP_MEMBERSHIP_TRANSACTION_JOURNAL_SUFFIX,
        ACTIVITY_GROUP_MEMBERSHIP_REMOVAL_TRANSACTION_JOURNAL_SUFFIX,
    )

    for private_root in roots:
        try:
            with activity_group_transaction_scan_entries(
                root,
                private_root,
            ) as entries:
                for entry in entries:
                    scanned_entry_count += 1
                    if scanned_entry_count > max_entries:
                        blockers.append(
                            "activity_group_transaction_evidence_scan_failed"
                        )
                        scan_complete = False
                        break
                    lowered_name = entry.name.lower()
                    if not any(
                        lowered_name.endswith(suffix)
                        for suffix in suffixes
                    ):
                        continue
                    journal_paths.append(private_root / entry.name)
        except FileNotFoundError:
            continue
        except OSError:
            blockers.append(
                "activity_group_transaction_evidence_scan_failed"
            )
            scan_complete = False
        if not scan_complete:
            break

    journal_paths.sort(key=lambda path: str(path).casefold())
    if journal_paths:
        blockers.append(
            "activity_group_unresolved_transaction_evidence_exists"
        )
    return {
        "ok": not blockers,
        "complete": scan_complete,
        "journal_count": len(journal_paths),
        "journal_paths": journal_paths,
        "blockers": unique_preserve_order(blockers),
    }


def activity_group_evidence_json_bytes(
    payload: dict[str, Any],
) -> bytes:
    return (
        json.dumps(
            json_safe(payload),
            indent=2,
            ensure_ascii=False,
            default=str,
        )
        + "\n"
    ).encode("utf-8")


def _write_activity_group_bytes_new_file_bound(
    binding: dict[str, Any],
    path: Path,
    raw: bytes,
    *,
    heartbeat: Callable[[], None] | None = None,
) -> None:
    callback = heartbeat or (lambda: None)
    if path.parent != binding.get("path"):
        raise OSError("activity_group_bound_parent_mismatch")
    descriptor = binding.get("descriptor")
    if isinstance(descriptor, int):
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        flags |= getattr(os, "O_BINARY", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        temporary_name: str | None = None
        file_descriptor: int | None = None
        try:
            for _ in range(8):
                candidate = f".{path.name}.{secrets.token_hex(8)}.tmp"
                try:
                    file_descriptor = os.open(
                        candidate,
                        flags,
                        0o600,
                        dir_fd=descriptor,
                    )
                    temporary_name = candidate
                    break
                except FileExistsError:
                    continue
            if file_descriptor is None or temporary_name is None:
                raise OSError("activity_group_bound_temp_reservation_failed")
            opened = os.fstat(file_descriptor)
            if not stat.S_ISREG(opened.st_mode) or int(opened.st_nlink) != 1:
                raise OSError("activity_group_bound_temp_unsafe")
            offset = 0
            while offset < len(raw):
                callback()
                written = os.write(
                    file_descriptor,
                    raw[offset : offset + 64 * 1024],
                )
                if written <= 0:
                    raise OSError(
                        "activity_group_bound_write_incomplete"
                    )
                offset += written
            callback()
            os.fsync(file_descriptor)
            completed = os.fstat(file_descriptor)
            if (
                (completed.st_dev, completed.st_ino)
                != (opened.st_dev, opened.st_ino)
                or int(completed.st_nlink) != 1
                or int(completed.st_size) != len(raw)
            ):
                raise OSError("activity_group_bound_temp_changed")
            os.close(file_descriptor)
            file_descriptor = None

            os.link(
                temporary_name,
                path.name,
                src_dir_fd=descriptor,
                dst_dir_fd=descriptor,
                follow_symlinks=False,
            )
            published = os.stat(
                path.name,
                dir_fd=descriptor,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISREG(published.st_mode)
                or (published.st_dev, published.st_ino)
                != (completed.st_dev, completed.st_ino)
                or int(published.st_size) != len(raw)
                or int(published.st_nlink) != 2
            ):
                raise OSError("activity_group_bound_publication_changed")
            os.fsync(descriptor)
            os.unlink(temporary_name, dir_fd=descriptor)
            temporary_name = None
            os.fsync(descriptor)
            final = os.stat(
                path.name,
                dir_fd=descriptor,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISREG(final.st_mode)
                or (final.st_dev, final.st_ino)
                != (completed.st_dev, completed.st_ino)
                or int(final.st_size) != len(raw)
                or int(final.st_nlink) != 1
            ):
                raise OSError("activity_group_bound_publication_changed")
        finally:
            if file_descriptor is not None:
                os.close(file_descriptor)
            if temporary_name is not None:
                try:
                    os.unlink(temporary_name, dir_fd=descriptor)
                except FileNotFoundError:
                    pass
        return

    # On Windows the ancestor chain is held without delete sharing. Build the
    # complete bytes under a private sibling name, then publish with a
    # create-only hard link. A crash can leave only a private temp or a complete
    # final file; it cannot expose a truncated final receipt.
    temporary_path: Path | None = None
    completed: os.stat_result | None = None
    try:
        for _ in range(8):
            candidate = path.with_name(
                f".{path.name}.{secrets.token_hex(8)}.tmp"
            )
            try:
                with candidate.open("xb") as handle:
                    temporary_path = candidate
                    opened = os.fstat(handle.fileno())
                    if (
                        not stat.S_ISREG(opened.st_mode)
                        or int(opened.st_nlink) != 1
                    ):
                        raise OSError("activity_group_bound_temp_unsafe")
                    offset = 0
                    while offset < len(raw):
                        callback()
                        written = handle.write(raw[offset : offset + 64 * 1024])
                        if written is None or written <= 0:
                            raise OSError(
                                "activity_group_bound_write_incomplete"
                            )
                        offset += written
                    handle.flush()
                    callback()
                    os.fsync(handle.fileno())
                    completed = os.fstat(handle.fileno())
                break
            except FileExistsError:
                continue
        if temporary_path is None or completed is None:
            raise OSError("activity_group_bound_temp_reservation_failed")
        if (
            (completed.st_dev, completed.st_ino)
            != (opened.st_dev, opened.st_ino)
            or int(completed.st_nlink) != 1
            or int(completed.st_size) != len(raw)
        ):
            raise OSError("activity_group_bound_temp_changed")
        os.link(temporary_path, path, follow_symlinks=False)
        published = os.lstat(path)
        if (
            not stat.S_ISREG(published.st_mode)
            or (published.st_dev, published.st_ino)
            != (completed.st_dev, completed.st_ino)
            or int(published.st_size) != len(raw)
            or int(published.st_nlink) != 2
        ):
            raise OSError("activity_group_bound_publication_changed")
        fsync_directory(path.parent)
        temporary_path.unlink()
        temporary_path = None
        fsync_directory(path.parent)
        final = os.lstat(path)
        if (
            not stat.S_ISREG(final.st_mode)
            or (final.st_dev, final.st_ino)
            != (completed.st_dev, completed.st_ino)
            or int(final.st_size) != len(raw)
            or int(final.st_nlink) != 1
        ):
            raise OSError("activity_group_bound_publication_changed")
    finally:
        if temporary_path is not None:
            temporary_path.unlink(missing_ok=True)


@contextmanager
def _hold_activity_group_evidence_file(
    root: Path,
    path: Path,
    *,
    max_bytes: int,
) -> Iterable[dict[str, Any]]:
    """Hold one exact non-reparse evidence file stable while authority is used."""

    with _activity_group_bound_directory_chain(
        root,
        path.parent,
    ) as binding:
        if os.name != "nt":
            parent_descriptor = binding["descriptor"]
            flags = os.O_RDONLY
            flags |= getattr(os, "O_BINARY", 0)
            flags |= getattr(os, "O_NOFOLLOW", 0)
            descriptor = os.open(
                path.name,
                flags,
                dir_fd=parent_descriptor,
            )
            try:
                opened_stat = os.fstat(descriptor)
                entry_stat = os.stat(
                    path.name,
                    dir_fd=parent_descriptor,
                    follow_symlinks=False,
                )
                if (
                    not stat.S_ISREG(opened_stat.st_mode)
                    or (
                        opened_stat.st_dev,
                        opened_stat.st_ino,
                    )
                    != (
                        entry_stat.st_dev,
                        entry_stat.st_ino,
                    )
                    or opened_stat.st_size > max_bytes
                ):
                    raise OSError(
                        "activity_group_evidence_file_unsafe"
                    )
                chunks: list[bytes] = []
                remaining = max_bytes + 1
                while remaining:
                    chunk = os.read(
                        descriptor,
                        min(1024 * 1024, remaining),
                    )
                    if not chunk:
                        break
                    chunks.append(chunk)
                    remaining -= len(chunk)
                raw = b"".join(chunks)
                if len(raw) > max_bytes:
                    raise OSError(
                        "activity_group_evidence_file_too_large"
                    )
                yield {
                    "raw": raw,
                    "identity": (
                        opened_stat.st_dev,
                        opened_stat.st_ino,
                    ),
                    "descriptor": descriptor,
                    "windows_handle": None,
                }
            finally:
                os.close(descriptor)
            return

        import ctypes
        from ctypes import wintypes

        class ByHandleFileInformation(ctypes.Structure):
            _fields_ = [
                ("dwFileAttributes", wintypes.DWORD),
                ("ftCreationTime", wintypes.FILETIME),
                ("ftLastAccessTime", wintypes.FILETIME),
                ("ftLastWriteTime", wintypes.FILETIME),
                ("dwVolumeSerialNumber", wintypes.DWORD),
                ("nFileSizeHigh", wintypes.DWORD),
                ("nFileSizeLow", wintypes.DWORD),
                ("nNumberOfLinks", wintypes.DWORD),
                ("nFileIndexHigh", wintypes.DWORD),
                ("nFileIndexLow", wintypes.DWORD),
            ]

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        create_file = kernel32.CreateFileW
        create_file.argtypes = [
            wintypes.LPCWSTR,
            wintypes.DWORD,
            wintypes.DWORD,
            wintypes.LPVOID,
            wintypes.DWORD,
            wintypes.DWORD,
            wintypes.HANDLE,
        ]
        create_file.restype = wintypes.HANDLE
        get_information = kernel32.GetFileInformationByHandle
        get_information.argtypes = [
            wintypes.HANDLE,
            ctypes.POINTER(ByHandleFileInformation),
        ]
        get_information.restype = wintypes.BOOL
        read_file = kernel32.ReadFile
        read_file.argtypes = [
            wintypes.HANDLE,
            wintypes.LPVOID,
            wintypes.DWORD,
            ctypes.POINTER(wintypes.DWORD),
            wintypes.LPVOID,
        ]
        read_file.restype = wintypes.BOOL
        close_handle = kernel32.CloseHandle
        close_handle.argtypes = [wintypes.HANDLE]
        close_handle.restype = wintypes.BOOL

        generic_read = 0x80000000
        file_share_read = 0x00000001
        open_existing = 3
        file_flag_open_reparse_point = 0x00200000
        handle = create_file(
            str(path),
            generic_read,
            file_share_read,
            None,
            open_existing,
            file_flag_open_reparse_point,
            None,
        )
        invalid_handle = wintypes.HANDLE(-1).value
        if handle == invalid_handle:
            raise ctypes.WinError(ctypes.get_last_error())
        try:
            information = ByHandleFileInformation()
            if not get_information(
                handle,
                ctypes.byref(information),
            ):
                raise ctypes.WinError(ctypes.get_last_error())
            file_attribute_directory = 0x00000010
            file_attribute_reparse_point = 0x00000400
            size = (
                int(information.nFileSizeHigh) << 32
            ) | int(information.nFileSizeLow)
            file_index = (
                int(information.nFileIndexHigh) << 32
            ) | int(information.nFileIndexLow)
            entry_stat = os.stat(path, follow_symlinks=False)
            if (
                size > max_bytes
                or entry_stat.st_ino != file_index
                or (
                    information.dwFileAttributes
                    & (
                        file_attribute_directory
                        | file_attribute_reparse_point
                    )
                )
            ):
                raise OSError(
                    "activity_group_evidence_file_unsafe"
                )
            chunks: list[bytes] = []
            remaining = size
            while remaining:
                chunk_size = min(1024 * 1024, remaining)
                buffer = ctypes.create_string_buffer(chunk_size)
                read_count = wintypes.DWORD()
                if not read_file(
                    handle,
                    buffer,
                    chunk_size,
                    ctypes.byref(read_count),
                    None,
                ):
                    raise ctypes.WinError(ctypes.get_last_error())
                if read_count.value == 0:
                    raise OSError(
                        "activity_group_evidence_read_incomplete"
                    )
                chunks.append(buffer.raw[: read_count.value])
                remaining -= read_count.value
            yield {
                "raw": b"".join(chunks),
                "identity": (entry_stat.st_dev, file_index),
                "descriptor": None,
                "windows_handle": handle,
            }
        finally:
            close_handle(handle)


def _delete_activity_group_evidence_exact(
    root: Path,
    path: Path,
    *,
    expected_sha256: str,
    max_bytes: int,
    parent_binding: dict[str, Any] | None = None,
    expected_identity: tuple[int, int, int] | None = None,
    expected_windows_metadata: tuple[int, bytes] | None = None,
    windows_cas_error_prefix: str | None = None,
) -> None:
    """Delete only the exact non-reparse evidence bytes that were reviewed.

    CAS residue callers provide ``windows_cas_error_prefix`` to require an
    immediate POSIX namespace unlink.  Ordinary evidence deletion retains its
    historical delayed-disposition behavior and can never be selected as a
    fallback from that CAS mode.
    """

    if not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_sha256):
        raise OSError("activity_group_evidence_sha256_invalid")
    if windows_cas_error_prefix is not None and not re.fullmatch(
        r"[a-z][a-z0-9_]{0,63}",
        windows_cas_error_prefix,
    ):
        raise OSError("canonical_swap_error_prefix_invalid")
    if os.name != "nt":
        binding_context = (
            nullcontext(parent_binding)
            if parent_binding is not None
            else _activity_group_bound_directory_chain(
                root,
                path.parent,
            )
        )
        with binding_context as binding:
            if (
                not isinstance(binding, dict)
                or binding.get("path") != path.parent
            ):
                raise OSError("activity_group_bound_parent_mismatch")
            parent_descriptor = binding["descriptor"]
            quarantine_parent_path = _activity_group_private_root(root)
            quarantine_binding_context = (
                nullcontext(binding)
                if quarantine_parent_path == path.parent
                else _activity_group_bound_directory_chain(
                    root,
                    quarantine_parent_path,
                    create=True,
                )
            )
            with quarantine_binding_context as quarantine_binding:
                if (
                    not isinstance(quarantine_binding, dict)
                    or quarantine_binding.get("path")
                    != quarantine_parent_path
                ):
                    raise OSError(
                        "activity_group_bound_quarantine_parent_mismatch"
                    )
                quarantine_parent_descriptor = quarantine_binding[
                    "descriptor"
                ]
                quarantine_name = (
                    f".exact-delete-{secrets.token_hex(16)}"
                    f"{ACTIVITY_GROUP_MEMBERSHIP_TRANSACTION_JOURNAL_SUFFIX}"
                )
                os.mkdir(
                    quarantine_name,
                    mode=0o700,
                    dir_fd=quarantine_parent_descriptor,
                )
                directory_flags = os.O_RDONLY
                directory_flags |= getattr(os, "O_DIRECTORY", 0)
                directory_flags |= getattr(os, "O_NOFOLLOW", 0)
                quarantine_descriptor = os.open(
                    quarantine_name,
                    directory_flags,
                    dir_fd=quarantine_parent_descriptor,
                )
                captured = False
                try:
                    os.rename(
                        path.name,
                        "evidence",
                        src_dir_fd=parent_descriptor,
                        dst_dir_fd=quarantine_descriptor,
                    )
                    captured = True
                    os.fsync(parent_descriptor)
                    os.fsync(quarantine_descriptor)
                    os.fsync(quarantine_parent_descriptor)
                    flags = os.O_RDONLY
                    flags |= getattr(os, "O_BINARY", 0)
                    flags |= getattr(os, "O_NOFOLLOW", 0)
                    descriptor = os.open(
                        "evidence",
                        flags,
                        dir_fd=quarantine_descriptor,
                    )
                    try:
                        opened_stat = os.fstat(descriptor)
                        if (
                            not stat.S_ISREG(opened_stat.st_mode)
                            or int(opened_stat.st_nlink) != 1
                            or opened_stat.st_size > max_bytes
                            or (
                                expected_identity is not None
                                and (
                                    int(opened_stat.st_dev),
                                    int(opened_stat.st_ino),
                                    int(opened_stat.st_size),
                                )
                                != tuple(
                                    int(value)
                                    for value in expected_identity
                                )
                            )
                        ):
                            raise OSError(
                                "activity_group_evidence_file_unsafe"
                            )
                        chunks: list[bytes] = []
                        remaining = max_bytes + 1
                        while remaining:
                            chunk = os.read(
                                descriptor,
                                min(1024 * 1024, remaining),
                            )
                            if not chunk:
                                break
                            chunks.append(chunk)
                            remaining -= len(chunk)
                        raw = b"".join(chunks)
                        entry_stat = os.stat(
                            "evidence",
                            dir_fd=quarantine_descriptor,
                            follow_symlinks=False,
                        )
                        if (
                            len(raw) > max_bytes
                            or (
                                entry_stat.st_dev,
                                entry_stat.st_ino,
                            )
                            != (
                                opened_stat.st_dev,
                                opened_stat.st_ino,
                            )
                            or (
                                "sha256:"
                                + hashlib.sha256(raw).hexdigest()
                            )
                            != expected_sha256
                        ):
                            raise OSError(
                                "activity_group_evidence_changed"
                            )
                        os.lseek(descriptor, 0, os.SEEK_SET)
                        stable_chunks: list[bytes] = []
                        stable_remaining = max_bytes + 1
                        while stable_remaining:
                            stable_chunk = os.read(
                                descriptor,
                                min(1024 * 1024, stable_remaining),
                            )
                            if not stable_chunk:
                                break
                            stable_chunks.append(stable_chunk)
                            stable_remaining -= len(stable_chunk)
                        stable_raw = b"".join(stable_chunks)
                        final_descriptor_stat = os.fstat(descriptor)
                        final_entry_stat = os.stat(
                            "evidence",
                            dir_fd=quarantine_descriptor,
                            follow_symlinks=False,
                        )
                        if (
                            stable_raw != raw
                            or (
                                "sha256:"
                                + hashlib.sha256(stable_raw).hexdigest()
                            )
                            != expected_sha256
                            or (
                                opened_stat.st_dev,
                                opened_stat.st_ino,
                                opened_stat.st_size,
                                opened_stat.st_mtime_ns,
                                opened_stat.st_ctime_ns,
                                opened_stat.st_nlink,
                            )
                            != (
                                final_descriptor_stat.st_dev,
                                final_descriptor_stat.st_ino,
                                final_descriptor_stat.st_size,
                                final_descriptor_stat.st_mtime_ns,
                                final_descriptor_stat.st_ctime_ns,
                                final_descriptor_stat.st_nlink,
                            )
                            or int(final_descriptor_stat.st_nlink) != 1
                            or int(final_entry_stat.st_nlink) != 1
                            or (
                                final_entry_stat.st_dev,
                                final_entry_stat.st_ino,
                            )
                            != (
                                opened_stat.st_dev,
                                opened_stat.st_ino,
                            )
                        ):
                            raise OSError(
                                "activity_group_evidence_changed"
                            )
                        os.unlink(
                            "evidence",
                            dir_fd=quarantine_descriptor,
                        )
                        captured = False
                        os.fsync(quarantine_descriptor)
                        os.fsync(parent_descriptor)
                        os.fsync(quarantine_parent_descriptor)
                    finally:
                        os.close(descriptor)
                finally:
                    if captured:
                        try:
                            captured_stat = os.stat(
                                "evidence",
                                dir_fd=quarantine_descriptor,
                                follow_symlinks=False,
                            )
                            if stat.S_ISREG(captured_stat.st_mode):
                                os.link(
                                    "evidence",
                                    path.name,
                                    src_dir_fd=quarantine_descriptor,
                                    dst_dir_fd=parent_descriptor,
                                    follow_symlinks=False,
                                )
                                os.unlink(
                                    "evidence",
                                    dir_fd=quarantine_descriptor,
                                )
                                captured = False
                                os.fsync(parent_descriptor)
                                os.fsync(quarantine_descriptor)
                                os.fsync(
                                    quarantine_parent_descriptor
                                )
                        except OSError:
                            pass
                    os.close(quarantine_descriptor)
                    if not captured:
                        os.rmdir(
                            quarantine_name,
                            dir_fd=quarantine_parent_descriptor,
                        )
                        os.fsync(quarantine_parent_descriptor)
        return

    import ctypes
    from ctypes import wintypes

    class ByHandleFileInformation(ctypes.Structure):
        _fields_ = [
            ("dwFileAttributes", wintypes.DWORD),
            ("ftCreationTime", wintypes.FILETIME),
            ("ftLastAccessTime", wintypes.FILETIME),
            ("ftLastWriteTime", wintypes.FILETIME),
            ("dwVolumeSerialNumber", wintypes.DWORD),
            ("nFileSizeHigh", wintypes.DWORD),
            ("nFileSizeLow", wintypes.DWORD),
            ("nNumberOfLinks", wintypes.DWORD),
            ("nFileIndexHigh", wintypes.DWORD),
            ("nFileIndexLow", wintypes.DWORD),
        ]

    class FileDispositionInformation(ctypes.Structure):
        _fields_ = [("DeleteFile", ctypes.c_ubyte)]

    binding_context = (
        nullcontext(parent_binding)
        if parent_binding is not None
        else _activity_group_bound_directory_chain(
            root,
            path.parent,
        )
    )
    with binding_context as binding:
        if (
            not isinstance(binding, dict)
            or binding.get("path") != path.parent
        ):
            raise OSError("activity_group_bound_parent_mismatch")
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        create_file = kernel32.CreateFileW
        create_file.argtypes = [
            wintypes.LPCWSTR,
            wintypes.DWORD,
            wintypes.DWORD,
            wintypes.LPVOID,
            wintypes.DWORD,
            wintypes.DWORD,
            wintypes.HANDLE,
        ]
        create_file.restype = wintypes.HANDLE
        get_information = kernel32.GetFileInformationByHandle
        get_information.argtypes = [
            wintypes.HANDLE,
            ctypes.POINTER(ByHandleFileInformation),
        ]
        get_information.restype = wintypes.BOOL
        read_file = kernel32.ReadFile
        read_file.argtypes = [
            wintypes.HANDLE,
            wintypes.LPVOID,
            wintypes.DWORD,
            ctypes.POINTER(wintypes.DWORD),
            wintypes.LPVOID,
        ]
        read_file.restype = wintypes.BOOL
        set_information = kernel32.SetFileInformationByHandle
        set_information.argtypes = [
            wintypes.HANDLE,
            ctypes.c_int,
            wintypes.LPVOID,
            wintypes.DWORD,
        ]
        set_information.restype = wintypes.BOOL
        close_handle = kernel32.CloseHandle
        close_handle.argtypes = [wintypes.HANDLE]
        close_handle.restype = wintypes.BOOL

        generic_read = 0x80000000
        delete_access = 0x00010000
        file_share_read = 0x00000001
        open_existing = 3
        file_flag_open_reparse_point = 0x00200000
        handle = create_file(
            str(path),
            generic_read | delete_access,
            file_share_read,
            None,
            open_existing,
            file_flag_open_reparse_point,
            None,
        )
        invalid_handle = wintypes.HANDLE(-1).value
        if handle == invalid_handle:
            raise ctypes.WinError(ctypes.get_last_error())
        delete_marked = False
        close_failed = False
        try:
            information = ByHandleFileInformation()
            if not get_information(
                handle,
                ctypes.byref(information),
            ):
                raise ctypes.WinError(ctypes.get_last_error())
            file_attribute_directory = 0x00000010
            file_attribute_reparse_point = 0x00000400
            size = (
                int(information.nFileSizeHigh) << 32
            ) | int(information.nFileSizeLow)
            file_index = (
                int(information.nFileIndexHigh) << 32
            ) | int(information.nFileIndexLow)
            entry_stat = os.stat(path, follow_symlinks=False)
            if (
                size > max_bytes
                or int(information.nNumberOfLinks) != 1
                or int(entry_stat.st_nlink) != 1
                or entry_stat.st_ino != file_index
                or (
                    expected_identity is not None
                    and (
                        int(entry_stat.st_dev),
                        int(entry_stat.st_ino),
                        int(entry_stat.st_size),
                    )
                    != tuple(int(value) for value in expected_identity)
                )
                or (
                    information.dwFileAttributes
                    & (
                        file_attribute_directory
                        | file_attribute_reparse_point
                    )
                )
            ):
                raise OSError(
                    "activity_group_evidence_file_unsafe"
                )
            observed_windows_metadata = (
                _windows_regular_file_supported_metadata(
                    handle,
                    error_prefix="activity_group_evidence",
                )
            )
            if (
                expected_windows_metadata is not None
                and observed_windows_metadata != expected_windows_metadata
            ):
                raise OSError("activity_group_evidence_changed")
            chunks: list[bytes] = []
            remaining = size
            while remaining:
                chunk_size = min(1024 * 1024, remaining)
                buffer = ctypes.create_string_buffer(chunk_size)
                read_count = wintypes.DWORD()
                if not read_file(
                    handle,
                    buffer,
                    chunk_size,
                    ctypes.byref(read_count),
                    None,
                ):
                    raise ctypes.WinError(ctypes.get_last_error())
                if read_count.value == 0:
                    raise OSError(
                        "activity_group_evidence_read_incomplete"
                    )
                chunks.append(buffer.raw[: read_count.value])
                remaining -= read_count.value
            raw = b"".join(chunks)
            if (
                "sha256:" + hashlib.sha256(raw).hexdigest()
                != expected_sha256
            ):
                raise OSError("activity_group_evidence_changed")
            final_information = ByHandleFileInformation()
            if not get_information(
                handle,
                ctypes.byref(final_information),
            ):
                raise ctypes.WinError(ctypes.get_last_error())
            final_size = (
                int(final_information.nFileSizeHigh) << 32
            ) | int(final_information.nFileSizeLow)
            final_file_index = (
                int(final_information.nFileIndexHigh) << 32
            ) | int(final_information.nFileIndexLow)
            if (
                final_size != size
                or final_file_index != file_index
                or int(final_information.dwVolumeSerialNumber)
                != int(information.dwVolumeSerialNumber)
                or int(final_information.nNumberOfLinks) != 1
            ):
                raise OSError("activity_group_evidence_changed")
            if windows_cas_error_prefix is None:
                disposition = FileDispositionInformation(1)
                if not set_information(
                    handle,
                    4,
                    ctypes.byref(disposition),
                    ctypes.sizeof(disposition),
                ):
                    raise ctypes.WinError(ctypes.get_last_error())
            else:
                _windows_mark_handle_posix_delete(
                    handle,
                    error_prefix=windows_cas_error_prefix,
                )
            delete_marked = True
        finally:
            close_failed = not bool(close_handle(handle))
        if close_failed:
            raise ctypes.WinError(ctypes.get_last_error())
        if not delete_marked or path.exists() or path.is_symlink():
            if windows_cas_error_prefix is not None:
                raise OSError(
                    f"{windows_cas_error_prefix}"
                    "_canonical_swap_cleanup_failed"
                )
            raise OSError("activity_group_evidence_delete_failed")
        fsync_directory(path.parent)


def regular_file_canonical_swap_paths(
    path: Path,
    transaction_sha256: str,
    *,
    swap_suffix: str,
) -> tuple[Path, Path]:
    """Return content-free deterministic names for one interrupted CAS."""

    if not re.fullmatch(r"sha256:[0-9a-f]{64}", transaction_sha256):
        raise ValueError("canonical_swap_transaction_sha256_invalid")
    if not re.fullmatch(r"\.[a-z0-9][a-z0-9.-]{0,79}", swap_suffix):
        raise ValueError("canonical_swap_suffix_invalid")
    request_digest = transaction_sha256.removeprefix("sha256:")
    path_digest = hashlib.sha256(path.name.encode("utf-8")).hexdigest()[:24]
    swap_path = path.with_name(
        f".{request_digest}.{path_digest}{swap_suffix}"
    )
    return swap_path, swap_path.with_name(swap_path.name + ".previous")


def activity_group_canonical_swap_paths(
    path: Path,
    request_sha256: str,
) -> tuple[Path, Path]:
    """Return the historical activity-group CAS residue names."""

    try:
        return regular_file_canonical_swap_paths(
            path,
            request_sha256,
            swap_suffix=ACTIVITY_GROUP_MEMBERSHIP_CANONICAL_SWAP_SUFFIX,
        )
    except ValueError as exc:
        raise ValueError("activity_group_request_sha256_invalid") from exc


def _read_activity_group_regular_bytes_bound(
    root: Path,
    binding: dict[str, Any],
    path: Path,
    *,
    max_bytes: int,
) -> bytes:
    if binding.get("path") != path.parent:
        raise OSError("activity_group_bound_parent_mismatch")
    if os.name == "nt":
        with _hold_activity_group_evidence_file(
            root,
            path,
            max_bytes=max_bytes,
        ) as held:
            return held["raw"]

    parent_descriptor = binding.get("descriptor")
    if not isinstance(parent_descriptor, int):
        raise OSError("activity_group_bound_parent_descriptor_missing")
    flags = os.O_RDONLY
    flags |= getattr(os, "O_BINARY", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(
        path.name,
        flags,
        dir_fd=parent_descriptor,
    )
    try:
        opened_stat = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened_stat.st_mode)
            or opened_stat.st_size > max_bytes
        ):
            raise OSError("activity_group_canonical_swap_file_unsafe")
        chunks: list[bytes] = []
        remaining = max_bytes + 1
        while remaining:
            chunk = os.read(
                descriptor,
                min(1024 * 1024, remaining),
            )
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        raw = b"".join(chunks)
        final_stat = os.fstat(descriptor)
        entry_stat = os.stat(
            path.name,
            dir_fd=parent_descriptor,
            follow_symlinks=False,
        )
        if (
            len(raw) > max_bytes
            or (
                opened_stat.st_dev,
                opened_stat.st_ino,
                opened_stat.st_size,
                opened_stat.st_mtime_ns,
            )
            != (
                final_stat.st_dev,
                final_stat.st_ino,
                final_stat.st_size,
                final_stat.st_mtime_ns,
            )
            or (
                opened_stat.st_dev,
                opened_stat.st_ino,
            )
            != (
                entry_stat.st_dev,
                entry_stat.st_ino,
            )
        ):
            raise OSError("activity_group_canonical_swap_file_changed")
        return raw
    finally:
        os.close(descriptor)


def _exchange_activity_group_entries_posix(
    binding: dict[str, Any],
    first: Path,
    second: Path,
) -> None:
    """Atomically exchange two bound sibling names without deleting either."""

    if os.name == "nt":
        raise OSError("activity_group_atomic_exchange_wrong_platform")
    if (
        binding.get("path") != first.parent
        or first.parent != second.parent
    ):
        raise OSError("activity_group_bound_parent_mismatch")
    parent_descriptor = binding.get("descriptor")
    if not isinstance(parent_descriptor, int):
        raise OSError("activity_group_bound_parent_descriptor_missing")

    import ctypes

    libc = ctypes.CDLL(None, use_errno=True)
    rename_exchange_function = getattr(libc, "renameat2", None)
    if rename_exchange_function is None:
        rename_exchange_function = getattr(
            libc,
            "renameatx_np",
            None,
        )
    if rename_exchange_function is None:
        raise OSError("activity_group_atomic_exchange_unsupported")
    rename_exchange_function.argtypes = [
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    ]
    rename_exchange_function.restype = ctypes.c_int
    rename_exchange = 0x2
    if (
        rename_exchange_function(
            parent_descriptor,
            os.fsencode(first.name),
            parent_descriptor,
            os.fsencode(second.name),
            rename_exchange,
        )
        != 0
    ):
        error_number = ctypes.get_errno()
        raise OSError(
            error_number,
            os.strerror(error_number),
        )
    os.fsync(parent_descriptor)


def _move_activity_group_entry_no_replace(
    binding: dict[str, Any],
    source: Path,
    destination: Path,
) -> None:
    """Atomically move one bound sibling only while the destination is absent."""

    if (
        binding.get("path") != source.parent
        or source.parent != destination.parent
    ):
        raise OSError("activity_group_bound_parent_mismatch")
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        move_file_ex = kernel32.MoveFileExW
        move_file_ex.argtypes = [
            wintypes.LPCWSTR,
            wintypes.LPCWSTR,
            wintypes.DWORD,
        ]
        move_file_ex.restype = wintypes.BOOL
        movefile_write_through = 0x00000008
        if not move_file_ex(
            str(source),
            str(destination),
            movefile_write_through,
        ):
            raise ctypes.WinError(ctypes.get_last_error())
        return

    parent_descriptor = binding.get("descriptor")
    if not isinstance(parent_descriptor, int):
        raise OSError("activity_group_bound_parent_descriptor_missing")

    import ctypes

    libc = ctypes.CDLL(None, use_errno=True)
    rename_no_replace_function = getattr(libc, "renameat2", None)
    rename_no_replace_flag = 0x1
    if rename_no_replace_function is None:
        rename_no_replace_function = getattr(
            libc,
            "renameatx_np",
            None,
        )
        rename_no_replace_flag = 0x4
    if rename_no_replace_function is None:
        raise OSError("activity_group_atomic_no_replace_unsupported")
    rename_no_replace_function.argtypes = [
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    ]
    rename_no_replace_function.restype = ctypes.c_int
    if (
        rename_no_replace_function(
            parent_descriptor,
            os.fsencode(source.name),
            parent_descriptor,
            os.fsencode(destination.name),
            rename_no_replace_flag,
        )
        != 0
    ):
        error_number = ctypes.get_errno()
        raise OSError(
            error_number,
            os.strerror(error_number),
        )
    os.fsync(parent_descriptor)


def _windows_assert_default_backup_stream_only(
    handle: Any,
    *,
    expected_size: int,
    error_prefix: str,
) -> None:
    """Reject NTFS metadata that a plain namespace swap would discard.

    ``FileStreamInfo`` only inventories named ``$DATA`` streams.  BackupRead's
    stream headers also expose EAs, object IDs, sparse blocks, property data,
    and the other metadata stream types that must not be silently deleted with
    the old file.  The held handle keeps this inventory bound to the exact file
    that may be moved.  BackupRead advances the file pointer, so preserve it.
    """

    if os.name != "nt":
        raise OSError("canonical_swap_metadata_wrong_platform")
    if (
        not isinstance(expected_size, int)
        or isinstance(expected_size, bool)
        or expected_size < 0
    ):
        raise OSError(f"{error_prefix}_canonical_swap_streams_unverified")

    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    backup_read = kernel32.BackupRead
    backup_read.argtypes = [
        wintypes.HANDLE,
        wintypes.LPVOID,
        wintypes.DWORD,
        ctypes.POINTER(wintypes.DWORD),
        wintypes.BOOL,
        wintypes.BOOL,
        ctypes.POINTER(ctypes.c_void_p),
    ]
    backup_read.restype = wintypes.BOOL
    backup_seek = kernel32.BackupSeek
    backup_seek.argtypes = [
        wintypes.HANDLE,
        wintypes.DWORD,
        wintypes.DWORD,
        ctypes.POINTER(wintypes.DWORD),
        ctypes.POINTER(wintypes.DWORD),
        ctypes.POINTER(ctypes.c_void_p),
    ]
    backup_seek.restype = wintypes.BOOL
    set_file_pointer_ex = kernel32.SetFilePointerEx
    set_file_pointer_ex.argtypes = [
        wintypes.HANDLE,
        ctypes.c_longlong,
        ctypes.POINTER(ctypes.c_longlong),
        wintypes.DWORD,
    ]
    set_file_pointer_ex.restype = wintypes.BOOL

    file_begin = 0
    file_current = 1
    header_bytes = 20
    backup_data = 0x00000001
    original_position = ctypes.c_longlong()
    if not set_file_pointer_ex(
        handle,
        0,
        ctypes.byref(original_position),
        file_current,
    ):
        raise OSError(f"{error_prefix}_canonical_swap_streams_unverified")
    if not set_file_pointer_ex(handle, 0, None, file_begin):
        raise OSError(f"{error_prefix}_canonical_swap_streams_unverified")

    context = ctypes.c_void_p()
    cleanup_failed = False
    try:
        default_stream_seen = False
        while True:
            header = ctypes.create_string_buffer(header_bytes)
            read_count = wintypes.DWORD()
            if not backup_read(
                handle,
                header,
                header_bytes,
                ctypes.byref(read_count),
                False,
                False,
                ctypes.byref(context),
            ):
                raise OSError(
                    f"{error_prefix}_canonical_swap_streams_unverified"
                )
            if int(read_count.value) == 0:
                break
            if int(read_count.value) != header_bytes:
                raise OSError(
                    f"{error_prefix}_canonical_swap_streams_unverified"
                )
            stream_id = int.from_bytes(header.raw[0:4], "little")
            stream_attributes = int.from_bytes(
                header.raw[4:8],
                "little",
            )
            stream_size = int.from_bytes(
                header.raw[8:16],
                "little",
                signed=True,
            )
            stream_name_size = int.from_bytes(
                header.raw[16:20],
                "little",
            )
            if (
                stream_id != backup_data
                or stream_attributes != 0
                or stream_name_size != 0
            ):
                raise OSError(
                    f"{error_prefix}_canonical_swap_backup_stream_unsupported"
                )
            if (
                default_stream_seen
                or stream_size < 0
                or stream_size != expected_size
            ):
                raise OSError(
                    f"{error_prefix}_canonical_swap_streams_unverified"
                )
            default_stream_seen = True
            if stream_size == 0:
                continue
            low_seeked = wintypes.DWORD()
            high_seeked = wintypes.DWORD()
            if not backup_seek(
                handle,
                stream_size & 0xFFFFFFFF,
                (stream_size >> 32) & 0xFFFFFFFF,
                ctypes.byref(low_seeked),
                ctypes.byref(high_seeked),
                ctypes.byref(context),
            ):
                raise OSError(
                    f"{error_prefix}_canonical_swap_streams_unverified"
                )
            actual_seeked = (
                int(high_seeked.value) << 32
            ) | int(low_seeked.value)
            if actual_seeked != stream_size:
                raise OSError(
                    f"{error_prefix}_canonical_swap_streams_unverified"
                )
        if not default_stream_seen and expected_size != 0:
            raise OSError(
                f"{error_prefix}_canonical_swap_streams_unverified"
            )
    finally:
        active_error = sys.exc_info()[0] is not None
        if context.value is not None:
            ignored = wintypes.DWORD()
            if not backup_read(
                handle,
                None,
                0,
                ctypes.byref(ignored),
                True,
                False,
                ctypes.byref(context),
            ):
                cleanup_failed = True
        if not set_file_pointer_ex(
            handle,
            int(original_position.value),
            None,
            file_begin,
        ):
            cleanup_failed = True
        if cleanup_failed and not active_error:
            raise OSError(
                f"{error_prefix}_canonical_swap_streams_unverified"
            )


def _windows_regular_file_supported_metadata(
    handle: Any,
    *,
    error_prefix: str,
) -> tuple[int, bytes]:
    """Return supported Windows metadata and reject named data streams."""

    if os.name != "nt":
        raise OSError("canonical_swap_metadata_wrong_platform")
    if not re.fullmatch(r"[a-z][a-z0-9_]{0,63}", error_prefix):
        raise OSError("canonical_swap_error_prefix_invalid")

    import ctypes
    from ctypes import wintypes

    class ByHandleFileInformation(ctypes.Structure):
        _fields_ = [
            ("dwFileAttributes", wintypes.DWORD),
            ("ftCreationTime", wintypes.FILETIME),
            ("ftLastAccessTime", wintypes.FILETIME),
            ("ftLastWriteTime", wintypes.FILETIME),
            ("dwVolumeSerialNumber", wintypes.DWORD),
            ("nFileSizeHigh", wintypes.DWORD),
            ("nFileSizeLow", wintypes.DWORD),
            ("nNumberOfLinks", wintypes.DWORD),
            ("nFileIndexHigh", wintypes.DWORD),
            ("nFileIndexLow", wintypes.DWORD),
        ]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    get_information = kernel32.GetFileInformationByHandle
    get_information.argtypes = [
        wintypes.HANDLE,
        ctypes.POINTER(ByHandleFileInformation),
    ]
    get_information.restype = wintypes.BOOL
    get_information_ex = kernel32.GetFileInformationByHandleEx
    get_information_ex.argtypes = [
        wintypes.HANDLE,
        ctypes.c_int,
        wintypes.LPVOID,
        wintypes.DWORD,
    ]
    get_information_ex.restype = wintypes.BOOL

    information = ByHandleFileInformation()
    if not get_information(handle, ctypes.byref(information)):
        raise OSError(f"{error_prefix}_canonical_swap_metadata_unverified")
    file_attribute_directory = 0x00000010
    file_attribute_archive = 0x00000020
    file_attribute_normal = 0x00000080
    file_attribute_reparse_point = 0x00000400
    if information.dwFileAttributes & (
        file_attribute_directory | file_attribute_reparse_point
    ):
        raise OSError(f"{error_prefix}_canonical_swap_file_unsafe")

    stream_info_buffer_bytes = 64 * 1024
    stream_info_header_bytes = 24
    stream_buffer = ctypes.create_string_buffer(stream_info_buffer_bytes)
    if not get_information_ex(
        handle,
        7,  # FileStreamInfo
        stream_buffer,
        stream_info_buffer_bytes,
    ):
        raise OSError(f"{error_prefix}_canonical_swap_streams_unverified")
    offset = 0
    default_stream_seen = False
    while True:
        if offset + stream_info_header_bytes > stream_info_buffer_bytes:
            raise OSError(
                f"{error_prefix}_canonical_swap_streams_unverified"
            )
        next_offset = int.from_bytes(
            stream_buffer.raw[offset : offset + 4],
            "little",
        )
        name_length = int.from_bytes(
            stream_buffer.raw[offset + 4 : offset + 8],
            "little",
        )
        name_start = offset + stream_info_header_bytes
        name_end = name_start + name_length
        if (
            name_length % 2
            or name_end > stream_info_buffer_bytes
            or (next_offset and (next_offset < 24 or next_offset % 8))
        ):
            raise OSError(
                f"{error_prefix}_canonical_swap_streams_unverified"
            )
        try:
            stream_name = stream_buffer.raw[name_start:name_end].decode(
                "utf-16-le",
                errors="strict",
            )
        except UnicodeDecodeError:
            raise OSError(
                f"{error_prefix}_canonical_swap_streams_unverified"
            ) from None
        if stream_name and stream_name.casefold() != "::$data":
            raise OSError(
                f"{error_prefix}_canonical_swap_named_stream_unsupported"
            )
        if default_stream_seen:
            raise OSError(
                f"{error_prefix}_canonical_swap_streams_unverified"
            )
        default_stream_seen = True
        if next_offset == 0:
            break
        if offset + next_offset <= offset:
            raise OSError(
                f"{error_prefix}_canonical_swap_streams_unverified"
            )
        offset += next_offset
    if not default_stream_seen:
        raise OSError(f"{error_prefix}_canonical_swap_streams_unverified")

    file_size = (
        int(information.nFileSizeHigh) << 32
    ) | int(information.nFileSizeLow)
    _windows_assert_default_backup_stream_only(
        handle,
        expected_size=file_size,
        error_prefix=error_prefix,
    )

    advapi32 = ctypes.WinDLL("advapi32", use_last_error=True)
    get_kernel_object_security = advapi32.GetKernelObjectSecurity
    get_kernel_object_security.argtypes = [
        wintypes.HANDLE,
        wintypes.DWORD,
        wintypes.LPVOID,
        wintypes.DWORD,
        ctypes.POINTER(wintypes.DWORD),
    ]
    get_kernel_object_security.restype = wintypes.BOOL
    security_information = (
        0x00000001  # OWNER_SECURITY_INFORMATION
        | 0x00000002  # GROUP_SECURITY_INFORMATION
        | 0x00000004  # DACL_SECURITY_INFORMATION
        | 0x00000010  # LABEL_SECURITY_INFORMATION
        | 0x00000020  # ATTRIBUTE_SECURITY_INFORMATION
        | 0x00000040  # SCOPE_SECURITY_INFORMATION
    )
    needed = wintypes.DWORD()
    ctypes.set_last_error(0)
    first_ok = get_kernel_object_security(
        handle,
        security_information,
        None,
        0,
        ctypes.byref(needed),
    )
    first_error = ctypes.get_last_error()
    if first_ok or first_error != 122:  # ERROR_INSUFFICIENT_BUFFER
        raise OSError(f"{error_prefix}_canonical_swap_security_unverified")
    if int(needed.value) < 1 or int(needed.value) > 1024 * 1024:
        raise OSError(f"{error_prefix}_canonical_swap_security_unverified")
    security_buffer = ctypes.create_string_buffer(int(needed.value))
    final_needed = wintypes.DWORD()
    if not get_kernel_object_security(
        handle,
        security_information,
        security_buffer,
        int(needed.value),
        ctypes.byref(final_needed),
    ):
        raise OSError(f"{error_prefix}_canonical_swap_security_unverified")
    if (
        int(final_needed.value) < 1
        or int(final_needed.value) > int(needed.value)
    ):
        raise OSError(f"{error_prefix}_canonical_swap_security_unverified")
    semantic_attributes = int(information.dwFileAttributes) & ~(
        file_attribute_archive | file_attribute_normal
    )
    return (
        semantic_attributes,
        bytes(security_buffer.raw[: int(final_needed.value)]),
    )


def _windows_mark_handle_posix_delete(
    handle: Any,
    *,
    error_prefix: str,
) -> None:
    """Mark one held Windows file for immediate POSIX namespace unlink."""

    if os.name != "nt":
        raise OSError("canonical_swap_posix_delete_wrong_platform")
    if not re.fullmatch(r"[a-z][a-z0-9_]{0,63}", error_prefix):
        raise OSError("canonical_swap_error_prefix_invalid")

    import ctypes
    from ctypes import wintypes

    class FileDispositionInformationEx(ctypes.Structure):
        _fields_ = [("Flags", wintypes.DWORD)]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    set_information = kernel32.SetFileInformationByHandle
    set_information.argtypes = [
        wintypes.HANDLE,
        ctypes.c_int,
        wintypes.LPVOID,
        wintypes.DWORD,
    ]
    set_information.restype = wintypes.BOOL
    file_disposition_flag_delete = 0x00000001
    file_disposition_flag_posix_semantics = 0x00000002
    file_disposition_flag_ignore_readonly_attribute = 0x00000010
    disposition = FileDispositionInformationEx(
        file_disposition_flag_delete
        | file_disposition_flag_posix_semantics
        | file_disposition_flag_ignore_readonly_attribute
    )
    if not set_information(
        handle,
        21,  # FileDispositionInfoEx
        ctypes.byref(disposition),
        ctypes.sizeof(disposition),
    ):
        raise OSError(
            f"{error_prefix}_canonical_swap_posix_delete_unsupported"
        )


def _replace_activity_group_file_with_backup_windows(
    replaced_path: Path,
    replacement_path: Path,
    backup_path: Path,
    *,
    expected_replaced_bytes: bytes | None = None,
    expected_replacement_bytes: bytes | None = None,
    max_bytes: int = ACTIVITY_GROUP_MEMBERSHIP_MAX_CANONICAL_FILE_BYTES,
    error_prefix: str = "activity_group",
    _failpoint: Callable[[str], None] | None = None,
) -> None:
    """Install one exact Windows file without ever replacing an unknown name.

    ``ReplaceFileW`` cannot express "create the backup only if absent": when a
    file appears at ``backup_path`` between a userspace absence check and the
    API call, Windows overwrites that file.  This primitive instead retains
    write/delete-denying handles for both exact source files and renames those
    same handles with ``FileRenameInfo.ReplaceIfExists = FALSE``.

    There is deliberately a recoverable namespace gap between the two moves.
    A process exit after the first move leaves ``backup_path`` holding the old
    bytes and ``replacement_path`` holding the new bytes.  A retry can finish
    that exact state.  If another process wins the public name during the gap,
    the second move refuses and all three occupants remain visible.
    """

    if os.name != "nt":
        raise OSError("activity_group_replace_with_backup_wrong_platform")
    if (
        replaced_path.parent != replacement_path.parent
        or replaced_path.parent != backup_path.parent
    ):
        raise OSError("activity_group_bound_parent_mismatch")
    if len(
        {
            os.path.normcase(os.path.abspath(candidate))
            for candidate in (
                replaced_path,
                replacement_path,
                backup_path,
            )
        }
    ) != 3:
        raise OSError("activity_group_canonical_swap_paths_overlap")
    if not re.fullmatch(r"[a-z][a-z0-9_]{0,63}", error_prefix):
        raise OSError("canonical_swap_error_prefix_invalid")
    if (
        not isinstance(max_bytes, int)
        or isinstance(max_bytes, bool)
        or max_bytes < 1
    ):
        raise OSError(f"{error_prefix}_canonical_swap_binding_invalid")
    for expected in (
        expected_replaced_bytes,
        expected_replacement_bytes,
    ):
        if expected is not None and (
            not isinstance(expected, bytes) or len(expected) > max_bytes
        ):
            raise OSError(f"{error_prefix}_canonical_swap_bytes_too_large")

    import ctypes
    from ctypes import wintypes

    class ByHandleFileInformation(ctypes.Structure):
        _fields_ = [
            ("dwFileAttributes", wintypes.DWORD),
            ("ftCreationTime", wintypes.FILETIME),
            ("ftLastAccessTime", wintypes.FILETIME),
            ("ftLastWriteTime", wintypes.FILETIME),
            ("dwVolumeSerialNumber", wintypes.DWORD),
            ("nFileSizeHigh", wintypes.DWORD),
            ("nFileSizeLow", wintypes.DWORD),
            ("nNumberOfLinks", wintypes.DWORD),
            ("nFileIndexHigh", wintypes.DWORD),
            ("nFileIndexLow", wintypes.DWORD),
        ]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    create_file = kernel32.CreateFileW
    create_file.argtypes = [
        wintypes.LPCWSTR,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.LPVOID,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.HANDLE,
    ]
    create_file.restype = wintypes.HANDLE
    get_information = kernel32.GetFileInformationByHandle
    get_information.argtypes = [
        wintypes.HANDLE,
        ctypes.POINTER(ByHandleFileInformation),
    ]
    get_information.restype = wintypes.BOOL
    read_file = kernel32.ReadFile
    read_file.argtypes = [
        wintypes.HANDLE,
        wintypes.LPVOID,
        wintypes.DWORD,
        ctypes.POINTER(wintypes.DWORD),
        wintypes.LPVOID,
    ]
    read_file.restype = wintypes.BOOL
    get_information_ex = kernel32.GetFileInformationByHandleEx
    get_information_ex.argtypes = [
        wintypes.HANDLE,
        ctypes.c_int,
        wintypes.LPVOID,
        wintypes.DWORD,
    ]
    get_information_ex.restype = wintypes.BOOL
    set_information = kernel32.SetFileInformationByHandle
    set_information.argtypes = [
        wintypes.HANDLE,
        ctypes.c_int,
        wintypes.LPVOID,
        wintypes.DWORD,
    ]
    set_information.restype = wintypes.BOOL
    close_handle = kernel32.CloseHandle
    close_handle.argtypes = [wintypes.HANDLE]
    close_handle.restype = wintypes.BOOL

    advapi32 = ctypes.WinDLL("advapi32", use_last_error=True)
    get_kernel_object_security = advapi32.GetKernelObjectSecurity
    get_kernel_object_security.argtypes = [
        wintypes.HANDLE,
        wintypes.DWORD,
        wintypes.LPVOID,
        wintypes.DWORD,
        ctypes.POINTER(wintypes.DWORD),
    ]
    get_kernel_object_security.restype = wintypes.BOOL

    generic_read = 0x80000000
    delete_access = 0x00010000
    read_control = 0x00020000
    file_read_attributes = 0x00000080
    file_share_read = 0x00000001
    open_existing = 3
    file_flag_open_reparse_point = 0x00200000
    file_flag_sequential_scan = 0x08000000
    invalid_handle = wintypes.HANDLE(-1).value
    file_attribute_directory = 0x00000010
    file_attribute_archive = 0x00000020
    file_attribute_normal = 0x00000080
    file_attribute_reparse_point = 0x00000400
    file_stream_info = 7
    stream_info_buffer_bytes = 64 * 1024
    stream_info_header_bytes = 24
    owner_security_information = 0x00000001
    group_security_information = 0x00000002
    dacl_security_information = 0x00000004
    label_security_information = 0x00000010
    attribute_security_information = 0x00000020
    scope_security_information = 0x00000040
    security_information = (
        owner_security_information
        | group_security_information
        | dacl_security_information
        | label_security_information
        | attribute_security_information
        | scope_security_information
    )
    error_insufficient_buffer = 122
    max_security_descriptor_bytes = 1024 * 1024

    def handle_value(handle: Any) -> int | None:
        value = (
            handle
            if isinstance(handle, int)
            else getattr(handle, "value", None)
        )
        if value in {None, invalid_handle}:
            return None
        return int(value)

    def query(handle: Any) -> ByHandleFileInformation:
        information = ByHandleFileInformation()
        if not get_information(handle, ctypes.byref(information)):
            raise ctypes.WinError(ctypes.get_last_error())
        return information

    def identity(
        information: ByHandleFileInformation,
    ) -> tuple[int, int]:
        return (
            int(information.dwVolumeSerialNumber),
            (int(information.nFileIndexHigh) << 32)
            | int(information.nFileIndexLow),
        )

    def size(information: ByHandleFileInformation) -> int:
        return (int(information.nFileSizeHigh) << 32) | int(
            information.nFileSizeLow
        )

    def named_identity(path: Path) -> tuple[int, int] | None:
        try:
            entry = os.lstat(path)
        except FileNotFoundError:
            return None
        if (
            not stat.S_ISREG(entry.st_mode)
            or stat.S_ISLNK(entry.st_mode)
            or (
                getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
                and getattr(entry, "st_file_attributes", 0)
                & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
            )
        ):
            raise OSError(f"{error_prefix}_canonical_swap_file_unsafe")
        return (int(entry.st_dev), int(entry.st_ino))

    def assert_default_data_stream_only(handle: Any) -> None:
        buffer = ctypes.create_string_buffer(stream_info_buffer_bytes)
        if not get_information_ex(
            handle,
            file_stream_info,
            buffer,
            stream_info_buffer_bytes,
        ):
            raise OSError(
                f"{error_prefix}_canonical_swap_streams_unverified"
            )
        offset = 0
        default_stream_seen = False
        while True:
            if offset + stream_info_header_bytes > stream_info_buffer_bytes:
                raise OSError(
                    f"{error_prefix}_canonical_swap_streams_unverified"
                )
            next_offset = int.from_bytes(
                buffer.raw[offset : offset + 4],
                "little",
            )
            name_length = int.from_bytes(
                buffer.raw[offset + 4 : offset + 8],
                "little",
            )
            name_start = offset + stream_info_header_bytes
            name_end = name_start + name_length
            if (
                name_length % 2
                or name_end > stream_info_buffer_bytes
                or (next_offset and (next_offset < 24 or next_offset % 8))
            ):
                raise OSError(
                    f"{error_prefix}_canonical_swap_streams_unverified"
                )
            try:
                stream_name = buffer.raw[name_start:name_end].decode(
                    "utf-16-le",
                    errors="strict",
                )
            except UnicodeDecodeError:
                raise OSError(
                    f"{error_prefix}_canonical_swap_streams_unverified"
                ) from None
            if stream_name not in {""} and stream_name.casefold() != "::$data":
                raise OSError(
                    f"{error_prefix}_canonical_swap_named_stream_unsupported"
                )
            if default_stream_seen:
                raise OSError(
                    f"{error_prefix}_canonical_swap_streams_unverified"
                )
            default_stream_seen = True
            if next_offset == 0:
                break
            if offset + next_offset <= offset:
                raise OSError(
                    f"{error_prefix}_canonical_swap_streams_unverified"
                )
            offset += next_offset
        if not default_stream_seen:
            raise OSError(
                f"{error_prefix}_canonical_swap_streams_unverified"
            )

    def security_descriptor(handle: Any) -> bytes:
        needed = wintypes.DWORD()
        ctypes.set_last_error(0)
        first_ok = get_kernel_object_security(
            handle,
            security_information,
            None,
            0,
            ctypes.byref(needed),
        )
        first_error = ctypes.get_last_error()
        if first_ok or first_error != error_insufficient_buffer:
            raise OSError(
                f"{error_prefix}_canonical_swap_security_unverified"
            )
        if (
            int(needed.value) < 1
            or int(needed.value) > max_security_descriptor_bytes
        ):
            raise OSError(
                f"{error_prefix}_canonical_swap_security_unverified"
            )
        buffer = ctypes.create_string_buffer(int(needed.value))
        final_needed = wintypes.DWORD()
        if not get_kernel_object_security(
            handle,
            security_information,
            buffer,
            int(needed.value),
            ctypes.byref(final_needed),
        ):
            raise OSError(
                f"{error_prefix}_canonical_swap_security_unverified"
            )
        if (
            int(final_needed.value) < 1
            or int(final_needed.value) > int(needed.value)
        ):
            raise OSError(
                f"{error_prefix}_canonical_swap_security_unverified"
            )
        return bytes(buffer.raw[: int(final_needed.value)])

    def supported_metadata(
        handle: Any,
        information: ByHandleFileInformation,
    ) -> tuple[int, bytes]:
        assert_default_data_stream_only(handle)
        _windows_assert_default_backup_stream_only(
            handle,
            expected_size=size(information),
            error_prefix=error_prefix,
        )
        semantic_attributes = int(information.dwFileAttributes) & ~(
            file_attribute_archive | file_attribute_normal
        )
        return semantic_attributes, security_descriptor(handle)

    def open_exact(
        path: Path,
        expected: bytes | None,
    ) -> tuple[Any, bytes, tuple[int, int], tuple[int, bytes]]:
        handle = create_file(
            str(path),
            (
                generic_read
                | delete_access
                | read_control
                | file_read_attributes
            ),
            file_share_read,
            None,
            open_existing,
            file_flag_open_reparse_point | file_flag_sequential_scan,
            None,
        )
        if handle_value(handle) is None:
            raise ctypes.WinError(ctypes.get_last_error())
        try:
            before = query(handle)
            byte_count = size(before)
            file_identity = identity(before)
            entry_identity = named_identity(path)
            if (
                byte_count > max_bytes
                or file_identity[1] <= 0
                or int(before.nNumberOfLinks) != 1
                or before.dwFileAttributes
                & (file_attribute_directory | file_attribute_reparse_point)
                or entry_identity is None
                or (
                    entry_identity[1]
                    and entry_identity[1] != file_identity[1]
                )
            ):
                raise OSError(
                    f"{error_prefix}_canonical_swap_file_unsafe"
                )
            exact_metadata = supported_metadata(handle, before)
            chunks: list[bytes] = []
            remaining = byte_count
            while remaining:
                requested = min(1024 * 1024, remaining)
                buffer = ctypes.create_string_buffer(requested)
                read_count = wintypes.DWORD()
                if not read_file(
                    handle,
                    buffer,
                    requested,
                    ctypes.byref(read_count),
                    None,
                ):
                    raise ctypes.WinError(ctypes.get_last_error())
                if read_count.value <= 0 or read_count.value > requested:
                    raise OSError(
                        f"{error_prefix}_canonical_swap_read_incomplete"
                    )
                chunks.append(buffer.raw[: read_count.value])
                remaining -= read_count.value
            trailing = ctypes.create_string_buffer(1)
            trailing_count = wintypes.DWORD()
            if not read_file(
                handle,
                trailing,
                1,
                ctypes.byref(trailing_count),
                None,
            ) or int(trailing_count.value) != 0:
                raise OSError(
                    f"{error_prefix}_canonical_swap_read_incomplete"
                )
            raw = b"".join(chunks)
            after = query(handle)
            if (
                identity(after) != file_identity
                or size(after) != byte_count
                or int(after.nNumberOfLinks) != 1
                or (expected is not None and raw != expected)
            ):
                raise OSError(
                    f"{error_prefix}_canonical_changed_before_swap"
                )
            return (
                handle,
                raw,
                file_identity,
                exact_metadata,
            )
        except BaseException:
            close_handle(handle)
            raise

    def rename_exact_handle(
        handle: Any,
        source: Path,
        destination: Path,
        file_identity: tuple[int, int],
    ) -> None:
        from . import private_metadata_win32

        rename_information = private_metadata_win32.file_rename_info_buffer(
            destination,
            replace_if_exists=False,
        )
        api_ok = bool(
            set_information(
                handle,
                3,  # FileRenameInfo
                rename_information.backing,
                rename_information.api_buffer_size,
            )
        )
        source_identity = named_identity(source)
        destination_identity = named_identity(destination)
        source_matches = bool(
            source_identity is not None
            and (
                not source_identity[1]
                or source_identity[1] == file_identity[1]
            )
        )
        destination_matches = bool(
            destination_identity is not None
            and (
                not destination_identity[1]
                or destination_identity[1] == file_identity[1]
            )
        )
        if destination_matches and not source_matches:
            return
        if not api_ok:
            raise ctypes.WinError(ctypes.get_last_error())
        raise OSError(f"{error_prefix}_canonical_swap_state_uncertain")

    old_handle: Any = None
    new_handle: Any = None
    old_delete_marked = False
    try:
        # A prior process may have exited after the first no-replace move.  In
        # that exact state the public name is absent and the approved old bytes
        # are already held at the deterministic backup name.
        try:
            old_handle, old_raw, old_identity, old_metadata = open_exact(
                replaced_path,
                expected_replaced_bytes,
            )
            first_move_required = True
        except FileNotFoundError:
            old_handle, old_raw, old_identity, old_metadata = open_exact(
                backup_path,
                expected_replaced_bytes,
            )
            first_move_required = False
        new_handle, new_raw, new_identity, new_metadata = open_exact(
            replacement_path,
            expected_replacement_bytes,
        )
        if (
            expected_replaced_bytes is not None
            and old_raw != expected_replaced_bytes
        ):
            raise OSError(f"{error_prefix}_canonical_changed_before_swap")
        if (
            expected_replacement_bytes is not None
            and new_raw != expected_replacement_bytes
        ):
            raise OSError(
                f"{error_prefix}_canonical_swap_evidence_changed"
            )
        if old_metadata != new_metadata:
            raise OSError(
                f"{error_prefix}_canonical_swap_metadata_mismatch"
            )

        if first_move_required:
            rename_exact_handle(
                old_handle,
                replaced_path,
                backup_path,
                old_identity,
            )
            if _failpoint is not None:
                _failpoint("canonical_moved_to_previous")
        elif named_identity(replaced_path) is not None:
            raise OSError(f"{error_prefix}_canonical_changed_during_swap")

        rename_exact_handle(
            new_handle,
            replacement_path,
            replaced_path,
            new_identity,
        )
        if _failpoint is not None:
            _failpoint("replacement_moved_to_canonical")

        old_after = query(old_handle)
        new_after = query(new_handle)
        old_after_metadata = supported_metadata(old_handle, old_after)
        new_after_metadata = supported_metadata(new_handle, new_after)
        named_old = named_identity(backup_path)
        named_new = named_identity(replaced_path)
        if (
            identity(old_after) != old_identity
            or identity(new_after) != new_identity
            or size(old_after) != len(old_raw)
            or size(new_after) != len(new_raw)
            or int(old_after.nNumberOfLinks) != 1
            or int(new_after.nNumberOfLinks) != 1
            or old_after_metadata != old_metadata
            or new_after_metadata != new_metadata
            or named_old is None
            or named_new is None
            or (named_old[1] and named_old[1] != old_identity[1])
            or (named_new[1] and named_new[1] != new_identity[1])
            or named_identity(replacement_path) is not None
        ):
            raise OSError(f"{error_prefix}_canonical_swap_state_uncertain")

        # The canonical-new verification above is the CAS linearization point.
        # Remove the obsolete namespace link with POSIX semantics only: a
        # pre-existing, share-compatible handle may retain the now-detached old
        # object, but must not keep ``backup_path`` visible or turn a successful
        # disposition into a delayed-delete cleanup error.  Never fall back to
        # ordinary delete disposition; if this filesystem cannot prove the
        # immediate namespace contract, preserve ``backup_path`` for explicit
        # reconciliation.
        _windows_mark_handle_posix_delete(
            old_handle,
            error_prefix=error_prefix,
        )
        old_delete_marked = True
        if _failpoint is not None:
            _failpoint("previous_delete_marked")
    finally:
        close_error: OSError | None = None
        if old_handle is not None:
            try:
                if not close_handle(old_handle):
                    close_error = ctypes.WinError(ctypes.get_last_error())
            except OSError as exc:
                close_error = exc
        if new_handle is not None:
            try:
                if not close_handle(new_handle) and close_error is None:
                    close_error = ctypes.WinError(ctypes.get_last_error())
            except OSError as exc:
                if close_error is None:
                    close_error = exc
        if close_error is not None and sys.exc_info()[0] is None:
            raise close_error
    if not old_delete_marked:
        raise OSError(f"{error_prefix}_canonical_swap_state_uncertain")
    if backup_path.exists() or backup_path.is_symlink():
        raise OSError(f"{error_prefix}_canonical_swap_cleanup_failed")


def _activity_group_swap_residue_bytes(
    root: Path,
    binding: dict[str, Any],
    path: Path,
    *,
    max_bytes: int = ACTIVITY_GROUP_MEMBERSHIP_MAX_CANONICAL_FILE_BYTES,
) -> bytes | None:
    try:
        return _read_activity_group_regular_bytes_bound(
            root,
            binding,
            path,
            max_bytes=max_bytes,
        )
    except FileNotFoundError:
        return None


def _delete_cas_residue_while_canonical_stable(
    root: Path,
    binding: dict[str, Any],
    canonical_path: Path,
    residue_path: Path,
    *,
    expected_current_sha256: str,
    expected_residue_sha256: str,
    max_bytes: int,
    error_prefix: str,
) -> None:
    """Delete one residue only while Windows keeps canonical bytes stable.

    A detached pathname read followed by residue deletion is unsafe: another
    process can change the canonical file in between and make the residue the
    last durable copy of the prior bytes.  A Windows read handle opened with
    only read sharing prevents compatible write/delete/rename opens until the
    deletion and final verification finish.

    Portable POSIX file descriptors do not reserve a pathname or deny writes
    by an uncoordinated process.  An interrupted, already-installed CAS is
    therefore preserved for explicit reconciliation instead of deleting its
    last complementary residue on those platforms.
    """

    if os.name != "nt":
        raise OSError(
            f"{error_prefix}_canonical_swap_cleanup_stability_unsupported"
        )
    if binding.get("path") != canonical_path.parent or (
        canonical_path.parent != residue_path.parent
    ):
        raise OSError("activity_group_bound_parent_mismatch")
    for expected_sha256 in (
        expected_current_sha256,
        expected_residue_sha256,
    ):
        if not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_sha256):
            raise OSError(f"{error_prefix}_canonical_swap_sha256_invalid")

    with _hold_activity_group_evidence_file(
        root,
        canonical_path,
        max_bytes=max_bytes,
    ) as held_canonical:
        held_raw = held_canonical.get("raw")
        if not isinstance(held_raw, bytes) or (
            "sha256:" + hashlib.sha256(held_raw).hexdigest()
            != expected_current_sha256
        ):
            raise OSError(
                f"{error_prefix}_canonical_changed_before_swap_cleanup"
            )
        canonical_handle = held_canonical.get("windows_handle")
        if canonical_handle is None:
            raise OSError(
                f"{error_prefix}_canonical_swap_cleanup_stability_unsupported"
            )
        canonical_metadata = _windows_regular_file_supported_metadata(
            canonical_handle,
            error_prefix=error_prefix,
        )
        with _hold_activity_group_evidence_file(
            root,
            residue_path,
            max_bytes=max_bytes,
        ) as held_residue:
            residue_raw = held_residue.get("raw")
            residue_handle = held_residue.get("windows_handle")
            residue_identity = held_residue.get("identity")
            if (
                not isinstance(residue_raw, bytes)
                or (
                    "sha256:" + hashlib.sha256(residue_raw).hexdigest()
                    != expected_residue_sha256
                )
                or residue_handle is None
                or not isinstance(residue_identity, tuple)
                or len(residue_identity) != 2
            ):
                raise OSError(
                    f"{error_prefix}_canonical_swap_evidence_changed"
                )
            residue_metadata = _windows_regular_file_supported_metadata(
                residue_handle,
                error_prefix=error_prefix,
            )
            exact_residue_identity = (
                int(residue_identity[0]),
                int(residue_identity[1]),
                len(residue_raw),
            )
        if residue_metadata != canonical_metadata:
            raise OSError(
                f"{error_prefix}_canonical_swap_metadata_mismatch"
            )
        _delete_activity_group_evidence_exact(
            root,
            residue_path,
            expected_sha256=expected_residue_sha256,
            max_bytes=max_bytes,
            parent_binding=binding,
            expected_identity=exact_residue_identity,
            expected_windows_metadata=residue_metadata,
            windows_cas_error_prefix=error_prefix,
        )
        final_bytes = _read_activity_group_regular_bytes_bound(
            root,
            binding,
            canonical_path,
            max_bytes=max_bytes,
        )
        if final_bytes != held_raw:
            raise OSError(
                f"{error_prefix}_canonical_changed_during_swap_cleanup"
            )
        if (
            _windows_regular_file_supported_metadata(
                canonical_handle,
                error_prefix=error_prefix,
            )
            != canonical_metadata
        ):
            raise OSError(
                f"{error_prefix}_canonical_changed_during_swap_cleanup"
            )


def _cleanup_activity_group_canonical_swap_residue(
    root: Path,
    path: Path,
    *,
    request_sha256: str,
    expected_current_sha256: str,
    expected_complementary_sha256: str,
) -> int:
    """Remove only a known complementary CAS residue beside stable canonical bytes."""

    for expected_sha256 in (
        expected_current_sha256,
        expected_complementary_sha256,
    ):
        if not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_sha256):
            raise OSError("activity_group_canonical_swap_sha256_invalid")
    swap_path, previous_path = activity_group_canonical_swap_paths(
        path,
        request_sha256,
    )
    removed = 0
    with _activity_group_bound_directory_chain(
        root,
        path.parent,
    ) as binding:
        stable_bytes = _read_activity_group_regular_bytes_bound(
            root,
            binding,
            path,
            max_bytes=ACTIVITY_GROUP_MEMBERSHIP_MAX_CANONICAL_FILE_BYTES,
        )
        if (
            "sha256:" + hashlib.sha256(stable_bytes).hexdigest()
            != expected_current_sha256
        ):
            raise OSError("activity_group_canonical_changed_before_swap_cleanup")
        residues = [
            (candidate, residue_bytes)
            for candidate in (swap_path, previous_path)
            if (
                residue_bytes := _activity_group_swap_residue_bytes(
                    root,
                    binding,
                    candidate,
                )
            )
            is not None
        ]
        if len(residues) > 1:
            raise OSError("activity_group_canonical_swap_evidence_ambiguous")
        for residue, residue_bytes in residues:
            residue_sha256 = (
                "sha256:" + hashlib.sha256(residue_bytes).hexdigest()
            )
            if residue_sha256 != expected_complementary_sha256:
                raise OSError(
                    "activity_group_canonical_swap_evidence_changed"
                )
            _delete_cas_residue_while_canonical_stable(
                root,
                binding,
                path,
                residue,
                expected_current_sha256=expected_current_sha256,
                expected_residue_sha256=residue_sha256,
                max_bytes=(
                    ACTIVITY_GROUP_MEMBERSHIP_MAX_CANONICAL_FILE_BYTES
                ),
                error_prefix="activity_group",
            )
            removed += 1
        final_bytes = _read_activity_group_regular_bytes_bound(
            root,
            binding,
            path,
            max_bytes=ACTIVITY_GROUP_MEMBERSHIP_MAX_CANONICAL_FILE_BYTES,
        )
        if (
            "sha256:" + hashlib.sha256(final_bytes).hexdigest()
            != expected_current_sha256
        ):
            raise OSError("activity_group_canonical_changed_during_swap_cleanup")
    return removed


def _replace_regular_file_bytes_compare_and_swap(
    root: Path,
    path: Path,
    *,
    expected_bytes: bytes,
    replacement_bytes: bytes,
    transaction_sha256: str,
    swap_suffix: str,
    max_bytes: int,
    error_prefix: str,
    allow_already_replacement: bool = False,
    parent_binding: dict[str, Any] | None = None,
) -> bool:
    """Atomically compare-and-swap one regular file without hiding unknown data."""

    if (
        not isinstance(max_bytes, int)
        or isinstance(max_bytes, bool)
        or max_bytes < 1
        or len(expected_bytes) > max_bytes
        or len(replacement_bytes) > max_bytes
    ):
        raise OSError(f"{error_prefix}_canonical_swap_bytes_too_large")
    if not re.fullmatch(r"[a-z][a-z0-9_]{0,63}", error_prefix):
        raise OSError("canonical_swap_error_prefix_invalid")
    try:
        swap_path, previous_path = regular_file_canonical_swap_paths(
            path,
            transaction_sha256,
            swap_suffix=swap_suffix,
        )
    except ValueError:
        raise OSError(f"{error_prefix}_canonical_swap_binding_invalid") from None
    if parent_binding is not None and parent_binding.get("path") != path.parent:
        raise OSError("activity_group_bound_parent_mismatch")
    binding_context = (
        nullcontext(parent_binding)
        if parent_binding is not None
        else _activity_group_bound_directory_chain(root, path.parent)
    )
    with binding_context as binding:
        try:
            current_bytes: bytes | None = (
                _read_activity_group_regular_bytes_bound(
                    root,
                    binding,
                    path,
                    max_bytes=max_bytes,
                )
            )
        except FileNotFoundError:
            current_bytes = None
        swap_bytes = _activity_group_swap_residue_bytes(
            root,
            binding,
            swap_path,
            max_bytes=max_bytes,
        )
        previous_bytes = _activity_group_swap_residue_bytes(
            root,
            binding,
            previous_path,
            max_bytes=max_bytes,
        )
        windows_gap_resume = bool(
            os.name == "nt"
            and current_bytes is None
            and swap_bytes == replacement_bytes
            and previous_bytes == expected_bytes
        )
        if (
            swap_bytes is not None
            and previous_bytes is not None
            and not windows_gap_resume
        ):
            raise OSError(f"{error_prefix}_canonical_swap_evidence_ambiguous")

        if windows_gap_resume:
            _replace_activity_group_file_with_backup_windows(
                path,
                swap_path,
                previous_path,
                expected_replaced_bytes=expected_bytes,
                expected_replacement_bytes=replacement_bytes,
                max_bytes=max_bytes,
                error_prefix=error_prefix,
            )
            final_bytes = _read_activity_group_regular_bytes_bound(
                root,
                binding,
                path,
                max_bytes=max_bytes,
            )
            if final_bytes != replacement_bytes:
                raise OSError(
                    f"{error_prefix}_canonical_swap_verification_failed"
                )
            return True
        if current_bytes is None:
            raise OSError(f"{error_prefix}_canonical_changed_before_swap")

        residue_path: Path | None = None
        residue_bytes: bytes | None = None
        if swap_bytes is not None:
            residue_path = swap_path
            residue_bytes = swap_bytes
        elif previous_bytes is not None:
            residue_path = previous_path
            residue_bytes = previous_bytes

        if residue_path is not None:
            if (
                current_bytes == replacement_bytes
                and residue_bytes == expected_bytes
            ):
                _delete_cas_residue_while_canonical_stable(
                    root,
                    binding,
                    path,
                    residue_path,
                    expected_current_sha256=(
                        "sha256:"
                        + hashlib.sha256(current_bytes).hexdigest()
                    ),
                    expected_residue_sha256=(
                        "sha256:"
                        + hashlib.sha256(residue_bytes).hexdigest()
                    ),
                    max_bytes=max_bytes,
                    error_prefix=error_prefix,
                )
                return True
            if (
                current_bytes == expected_bytes
                and residue_bytes == replacement_bytes
            ):
                _delete_activity_group_evidence_exact(
                    root,
                    residue_path,
                    expected_sha256=(
                        "sha256:"
                        + hashlib.sha256(residue_bytes).hexdigest()
                    ),
                    max_bytes=max_bytes,
                    parent_binding=binding,
                )
                current_bytes = _read_activity_group_regular_bytes_bound(
                    root,
                    binding,
                    path,
                    max_bytes=max_bytes,
                )
            else:
                raise OSError(
                    f"{error_prefix}_canonical_swap_evidence_changed"
                )

        if current_bytes == replacement_bytes:
            if allow_already_replacement:
                return False
            raise OSError(f"{error_prefix}_canonical_changed_before_swap")
        if current_bytes != expected_bytes:
            raise OSError(f"{error_prefix}_canonical_changed_before_swap")
        if expected_bytes == replacement_bytes:
            return False

        if os.name != "nt":
            # Refuse before creating a replacement entry on POSIX platforms
            # that cannot atomically exchange two sibling names.
            import ctypes

            libc = ctypes.CDLL(None)
            if (
                getattr(libc, "renameat2", None) is None
                and getattr(libc, "renameatx_np", None) is None
            ):
                raise OSError(f"{error_prefix}_atomic_exchange_unsupported")

        _write_activity_group_bytes_new_file_bound(
            binding,
            swap_path,
            replacement_bytes,
        )
        capture_path = swap_path
        swap_performed = False
        try:
            if os.name == "nt":
                _replace_activity_group_file_with_backup_windows(
                    path,
                    swap_path,
                    previous_path,
                    expected_replaced_bytes=expected_bytes,
                    expected_replacement_bytes=replacement_bytes,
                    max_bytes=max_bytes,
                    error_prefix=error_prefix,
                )
                swap_performed = True
                final_bytes = _read_activity_group_regular_bytes_bound(
                    root,
                    binding,
                    path,
                    max_bytes=max_bytes,
                )
                if final_bytes != replacement_bytes:
                    raise OSError(
                        f"{error_prefix}_canonical_swap_verification_failed"
                    )
                return True
            else:
                _exchange_activity_group_entries_posix(
                    binding,
                    path,
                    swap_path,
                )
            swap_performed = True

            captured_bytes = _read_activity_group_regular_bytes_bound(
                root,
                binding,
                capture_path,
                max_bytes=max_bytes,
            )
            installed_bytes = _read_activity_group_regular_bytes_bound(
                root,
                binding,
                path,
                max_bytes=max_bytes,
            )
            if installed_bytes != replacement_bytes:
                # An external edit arrived after the atomic swap. Keep that
                # unknown occupant at the public canonical name and retain the
                # captured entry as recovery evidence.
                raise OSError(
                    f"{error_prefix}_canonical_changed_during_swap"
                )
            if captured_bytes != expected_bytes:
                # The swap captured an edit that arrived before commit. First
                # capture our installed replacement without overwrite, then
                # restore the unknown bytes only if the canonical name remains
                # absent. This avoids an exchange-back race that could hide a
                # newer external edit under the private residue name.
                replacement_capture_path = (
                    previous_path
                    if capture_path == swap_path
                    else swap_path
                )
                _move_activity_group_entry_no_replace(
                    binding,
                    path,
                    replacement_capture_path,
                )
                installed_capture_bytes = (
                    _read_activity_group_regular_bytes_bound(
                        root,
                        binding,
                        replacement_capture_path,
                        max_bytes=max_bytes,
                    )
                )
                restore_source = capture_path
                if installed_capture_bytes != replacement_bytes:
                    # A second external edit won the name before capture.
                    # Restore that newer edit first and retain both older
                    # occupants for forensic review.
                    restore_source = replacement_capture_path
                try:
                    _move_activity_group_entry_no_replace(
                        binding,
                        restore_source,
                        path,
                    )
                except OSError:
                    # A third party already recreated the canonical name. It
                    # remains visible; all captured bytes remain private.
                    pass
                raise OSError(
                    f"{error_prefix}_canonical_changed_during_swap"
                )

            _delete_activity_group_evidence_exact(
                root,
                capture_path,
                expected_sha256=(
                    "sha256:"
                    + hashlib.sha256(captured_bytes).hexdigest()
                ),
                max_bytes=max_bytes,
                parent_binding=binding,
            )
            final_bytes = _read_activity_group_regular_bytes_bound(
                root,
                binding,
                path,
                max_bytes=max_bytes,
            )
            if final_bytes != replacement_bytes:
                raise OSError(
                    f"{error_prefix}_canonical_swap_verification_failed"
                )
            return True
        finally:
            if not swap_performed:
                # Once the first Windows move has happened, `.previous` is the
                # only durable copy of the old occupant.  Never clean either
                # residue from a failure path while that name exists.
                try:
                    preserve_residues = (
                        _activity_group_swap_residue_bytes(
                            root,
                            binding,
                            previous_path,
                            max_bytes=max_bytes,
                        )
                        is not None
                    )
                except OSError:
                    preserve_residues = True
                for candidate in (() if preserve_residues else (swap_path,)):
                    try:
                        candidate_bytes = (
                            _activity_group_swap_residue_bytes(
                                root,
                                binding,
                                candidate,
                                max_bytes=max_bytes,
                            )
                        )
                        if candidate_bytes != replacement_bytes:
                            continue
                        _delete_activity_group_evidence_exact(
                            root,
                            candidate,
                            expected_sha256=(
                                "sha256:"
                                + hashlib.sha256(
                                    candidate_bytes
                                ).hexdigest()
                            ),
                            max_bytes=max_bytes,
                            parent_binding=binding,
                        )
                    except OSError:
                        pass


def _replace_activity_group_canonical_bytes_compare_and_swap(
    root: Path,
    path: Path,
    *,
    expected_bytes: bytes,
    replacement_bytes: bytes,
    request_sha256: str,
    allow_already_replacement: bool = False,
) -> bool:
    """Preserve the activity-group CAS API over the shared safe primitive."""

    return _replace_regular_file_bytes_compare_and_swap(
        root,
        path,
        expected_bytes=expected_bytes,
        replacement_bytes=replacement_bytes,
        transaction_sha256=request_sha256,
        swap_suffix=ACTIVITY_GROUP_MEMBERSHIP_CANONICAL_SWAP_SUFFIX,
        max_bytes=ACTIVITY_GROUP_MEMBERSHIP_MAX_CANONICAL_FILE_BYTES,
        error_prefix="activity_group",
        allow_already_replacement=allow_already_replacement,
    )


def _stage_regular_file_bytes_compare_and_swap_delete(
    root: Path,
    path: Path,
    *,
    expected_bytes: bytes,
    expected_file_generation: Mapping[str, int],
    transaction_sha256: str,
    evidence_suffix: str,
    max_bytes: int,
    error_prefix: str,
) -> tuple[Path, tuple[int, int, int]]:
    """Move one exact occupant to hidden evidence without deleting a racer.

    The no-replace namespace move is the deletion linearization point.  The
    moved occupant is verified *after* the move; if another process won the
    source name just before that point, its bytes are moved back without
    overwrite.  Exact expected bytes remain staged until the caller has durably
    written the operation receipt.
    """

    if (
        not isinstance(max_bytes, int)
        or isinstance(max_bytes, bool)
        or max_bytes < 1
        or len(expected_bytes) > max_bytes
    ):
        raise OSError(f"{error_prefix}_delete_bytes_too_large")
    if not re.fullmatch(r"[a-z][a-z0-9_]{0,63}", error_prefix):
        raise OSError("compare_and_swap_delete_error_prefix_invalid")
    try:
        evidence_path, previous_path = regular_file_canonical_swap_paths(
            path,
            transaction_sha256,
            swap_suffix=evidence_suffix,
        )
    except ValueError:
        raise OSError(f"{error_prefix}_delete_binding_invalid") from None

    generation_fields = (
        "file_dev",
        "file_ino",
        "file_ctime_ns",
        "file_size",
        "file_mtime_ns",
    )
    try:
        expected_generation = {
            field: int(expected_file_generation[field])
            for field in generation_fields
        }
    except (KeyError, TypeError, ValueError):
        raise OSError(f"{error_prefix}_delete_generation_invalid") from None
    if (
        expected_generation["file_size"] != len(expected_bytes)
        or any(value < 0 for value in expected_generation.values())
    ):
        raise OSError(f"{error_prefix}_delete_generation_invalid")
    expected_identity = (
        expected_generation["file_dev"],
        expected_generation["file_ino"],
        expected_generation["file_size"],
    )

    with _activity_group_bound_directory_chain(root, path.parent) as binding:
        for residue in (evidence_path, previous_path):
            try:
                _read_activity_group_regular_bytes_bound(
                    root,
                    binding,
                    residue,
                    max_bytes=max_bytes,
                )
            except FileNotFoundError:
                continue
            except OSError:
                raise OSError(
                    f"{error_prefix}_delete_evidence_ambiguous"
                ) from None
            raise OSError(f"{error_prefix}_delete_evidence_ambiguous")

        try:
            current_snapshot = archive_index_stable_file_snapshot(
                root,
                path,
                max_bytes=max_bytes,
            )
        except FileNotFoundError:
            raise OSError(f"{error_prefix}_source_changed_before_delete") from None
        except OSError:
            raise OSError(f"{error_prefix}_source_changed_before_delete") from None
        if (
            current_snapshot.get("raw") != expected_bytes
            or current_snapshot.get("file_generation") != expected_generation
        ):
            raise OSError(f"{error_prefix}_source_changed_before_delete")

        _move_activity_group_entry_no_replace(
            binding,
            path,
            evidence_path,
        )
        captured_exact = False
        try:
            captured_snapshot = archive_index_stable_file_snapshot(
                root,
                evidence_path,
                max_bytes=max_bytes,
            )
            captured_generation = captured_snapshot.get("file_generation")
            captured_identity = (
                int(captured_generation["file_dev"]),
                int(captured_generation["file_ino"]),
                int(captured_generation["file_size"]),
            )
            captured_exact = (
                captured_snapshot.get("raw") == expected_bytes
                and captured_identity == expected_identity
            )
        except OSError:
            captured_exact = False
        except (KeyError, TypeError, ValueError):
            captured_exact = False
        if not captured_exact:
            # Restore the captured (possibly foreign) occupant only if the
            # public name is still absent.  A newer replacement always wins and
            # the captured evidence is retained for reconciliation.
            try:
                _move_activity_group_entry_no_replace(
                    binding,
                    evidence_path,
                    path,
                )
            except OSError:
                pass
            raise OSError(f"{error_prefix}_source_changed_during_delete")

        try:
            _read_activity_group_regular_bytes_bound(
                root,
                binding,
                path,
                max_bytes=max_bytes,
            )
        except FileNotFoundError:
            return evidence_path, expected_identity
        except OSError:
            raise OSError(
                f"{error_prefix}_source_recreated_during_delete"
            ) from None
        raise OSError(f"{error_prefix}_source_recreated_during_delete")


def _restore_staged_regular_file_delete(
    root: Path,
    path: Path,
    evidence_path: Path,
    *,
    expected_bytes: bytes,
    expected_identity: tuple[int, int, int],
    max_bytes: int,
) -> bool:
    """Restore exact staged bytes without overwriting a replacement."""

    try:
        with _activity_group_bound_directory_chain(
            root,
            path.parent,
        ) as binding:
            evidence_snapshot = archive_index_stable_file_snapshot(
                root,
                evidence_path,
                max_bytes=max_bytes,
            )
            evidence_generation = evidence_snapshot.get("file_generation")
            evidence_identity = (
                int(evidence_generation["file_dev"]),
                int(evidence_generation["file_ino"]),
                int(evidence_generation["file_size"]),
            )
            if (
                evidence_snapshot.get("raw") != expected_bytes
                or evidence_identity != expected_identity
            ):
                return False
            try:
                current_bytes = _read_activity_group_regular_bytes_bound(
                    root,
                    binding,
                    path,
                    max_bytes=max_bytes,
                )
            except FileNotFoundError:
                _move_activity_group_entry_no_replace(
                    binding,
                    evidence_path,
                    path,
                )
                restored_snapshot = archive_index_stable_file_snapshot(
                    root,
                    path,
                    max_bytes=max_bytes,
                )
                restored_generation = restored_snapshot.get("file_generation")
                restored_identity = (
                    int(restored_generation["file_dev"]),
                    int(restored_generation["file_ino"]),
                    int(restored_generation["file_size"]),
                )
                return (
                    restored_snapshot.get("raw") == expected_bytes
                    and restored_identity == expected_identity
                )
            if current_bytes != expected_bytes:
                return False
            _delete_activity_group_evidence_exact(
                root,
                evidence_path,
                expected_sha256=(
                    "sha256:" + hashlib.sha256(expected_bytes).hexdigest()
                ),
                max_bytes=max_bytes,
                parent_binding=binding,
                expected_identity=expected_identity,
            )
            return True
    except (KeyError, OSError, TypeError, ValueError):
        return False


def _finalize_staged_regular_file_delete(
    root: Path,
    evidence_path: Path,
    *,
    expected_bytes: bytes,
    expected_identity: tuple[int, int, int],
    max_bytes: int,
) -> None:
    """Delete only the exact staged source after its receipt is durable."""

    with _activity_group_bound_directory_chain(
        root,
        evidence_path.parent,
    ) as binding:
        captured_snapshot = archive_index_stable_file_snapshot(
            root,
            evidence_path,
            max_bytes=max_bytes,
        )
        captured_generation = captured_snapshot.get("file_generation")
        captured_identity = (
            int(captured_generation["file_dev"]),
            int(captured_generation["file_ino"]),
            int(captured_generation["file_size"]),
        )
        if (
            captured_snapshot.get("raw") != expected_bytes
            or captured_identity != expected_identity
        ):
            raise OSError("staged_delete_evidence_changed")
        _delete_activity_group_evidence_exact(
            root,
            evidence_path,
            expected_sha256=(
                "sha256:" + hashlib.sha256(expected_bytes).hexdigest()
            ),
            max_bytes=max_bytes,
            parent_binding=binding,
            expected_identity=expected_identity,
        )


def _activity_group_private_request(
    root: Path,
    request_path: str,
    operation_contract: _ActivityGroupMembershipOperationContract = (
        ACTIVITY_GROUP_MEMBERSHIP_ADD
    ),
) -> tuple[bytes, dict[str, Any]]:
    blockers: list[str] = []
    _normalized, path = _activity_group_request_path(
        root,
        request_path,
        blockers,
        request_prefix=operation_contract.request_prefix,
    )
    raw = b""
    document: dict[str, Any] | None = None
    if path is not None:
        raw, document = _read_activity_group_request(path, blockers)
    if blockers or document is None:
        raise ArchiveServiceError(
            blockers[0] if blockers else "activity_group_request_unavailable"
        )
    return raw, document


def _activity_group_standard_canonical_path(
    root: Path,
    zettel_id: str,
) -> Path:
    path = root / "zettels" / f"{zettel_id}.md"
    try:
        if (
            path.is_symlink()
            or not is_path_within_root(path, root)
            or not path.is_file()
            or archive_relative_path(path, root)
            != f"zettels/{zettel_id}.md"
        ):
            raise ArchiveServiceError(
                "requested_zettel_missing_standard_canonical_path"
            )
    except (ArchivePathError, OSError) as exc:
        raise ArchiveServiceError(
            "requested_zettel_missing_standard_canonical_path"
        ) from exc
    return path


def materialize_activity_group_membership_candidates(
    root: Path,
    *,
    request_bytes: bytes,
    request_document: dict[str, Any],
    plan: dict[str, Any],
    operation_contract: _ActivityGroupMembershipOperationContract = (
        ACTIVITY_GROUP_MEMBERSHIP_ADD
    ),
) -> tuple[list[dict[str, Any]], list[str]]:
    blockers: list[str] = []
    candidates: list[dict[str, Any]] = []
    request_sha256 = (
        "sha256:" + hashlib.sha256(request_bytes).hexdigest()
    )
    plan_request = (
        plan.get("request") if isinstance(plan.get("request"), dict) else {}
    )
    if (
        not plan.get("ok")
        or plan_request.get("sha256") != request_sha256
    ):
        return [], ["activity_group_plan_request_binding_invalid"]
    anchor_zettel_id = request_document.get("anchor_zettel_id")
    member_zettel_ids = request_document.get("member_zettel_ids")
    plan_items = plan.get("items")
    if (
        not isinstance(anchor_zettel_id, str)
        or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(anchor_zettel_id)
        or not isinstance(member_zettel_ids, list)
        or not isinstance(plan_items, list)
        or len(member_zettel_ids) != len(plan_items)
    ):
        return [], ["activity_group_plan_shape_invalid"]

    total_bytes = 0
    for row_index, (member_zettel_id, plan_item) in enumerate(
        zip(member_zettel_ids, plan_items, strict=True)
    ):
        if (
            not isinstance(member_zettel_id, str)
            or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(member_zettel_id)
            or not isinstance(plan_item, dict)
            or plan_item.get("row_index") != row_index
        ):
            blockers.append("activity_group_plan_row_binding_invalid")
            continue
        status = plan_item.get("status")
        if status == operation_contract.already_status:
            continue
        if status != operation_contract.ready_status:
            blockers.append("activity_group_plan_contains_nonwritable_row")
            continue
        try:
            path = _activity_group_standard_canonical_path(
                root,
                member_zettel_id,
            )
            remaining = (
                ACTIVITY_GROUP_MEMBERSHIP_MAX_TOTAL_CANONICAL_BYTES
                - total_bytes
            )
            before_bytes, _stat = _read_activity_group_canonical_bytes(
                path,
                max_bytes=remaining,
            )
            total_bytes += len(before_bytes)
            before_sha256 = (
                "sha256:" + hashlib.sha256(before_bytes).hexdigest()
            )
            if before_sha256 != plan_item.get("current_file_sha256"):
                raise ArchiveServiceError(
                    "activity_group_member_changed_after_plan"
                )
            frontmatter, _payload, _source = (
                _parse_activity_group_canonical(before_bytes)
            )
            if frontmatter.get("id") != member_zettel_id:
                raise ArchiveServiceError(
                    "member_frontmatter_identity_mismatch"
                )
            after_bytes = _activity_group_candidate_bytes(
                before_bytes,
                anchor_zettel_id=anchor_zettel_id,
                operation=operation_contract.operation,
            )
            after_sha256 = (
                "sha256:" + hashlib.sha256(after_bytes).hexdigest()
            )
            if after_sha256 != plan_item.get("proposed_file_sha256"):
                raise ArchiveServiceError(
                    "activity_group_candidate_changed_after_plan"
                )
            candidates.append(
                {
                    "row_index": row_index,
                    "zettel_id": member_zettel_id,
                    "path": path,
                    "relative_path": f"zettels/{member_zettel_id}.md",
                    "before_bytes": before_bytes,
                    "after_bytes": after_bytes,
                    "before_file_sha256": before_sha256,
                    "after_file_sha256": after_sha256,
                    "before_snapshot": (
                        zet_revision_before_snapshot_descriptor(before_bytes)
                    ),
                }
            )
        except ArchiveServiceError as exc:
            blockers.append(str(exc))
        except (ArchivePathError, OSError, ValueError):
            blockers.append("activity_group_candidate_unavailable")
    return candidates, unique_preserve_order(blockers)


def activity_group_membership_write_plan_sha256(
    *,
    archive_id: str,
    request_sha256: str,
    review_plan_sha256: str,
    anchor_current_file_sha256: str,
    candidates: list[dict[str, Any]],
    operation_contract: _ActivityGroupMembershipOperationContract = (
        ACTIVITY_GROUP_MEMBERSHIP_ADD
    ),
) -> str:
    return sha256_json_value(
        {
            "schema": operation_contract.write_schema,
            "archive_id": archive_id,
            "request_sha256": request_sha256,
            "review_plan_sha256": review_plan_sha256,
            "anchor_current_file_sha256": anchor_current_file_sha256,
            "items": [
                {
                    "row_index": item["row_index"],
                    "before_file_sha256": item["before_file_sha256"],
                    "after_file_sha256": item["after_file_sha256"],
                    "before_snapshot": item["before_snapshot"],
                }
                for item in candidates
            ],
        }
    )


def activity_group_membership_removal_write_plan_sha256(
    *,
    archive_id: str,
    request_sha256: str,
    review_plan_sha256: str,
    anchor_current_file_sha256: str,
    candidates: list[dict[str, Any]],
) -> str:
    return activity_group_membership_write_plan_sha256(
        archive_id=archive_id,
        request_sha256=request_sha256,
        review_plan_sha256=review_plan_sha256,
        anchor_current_file_sha256=anchor_current_file_sha256,
        candidates=candidates,
        operation_contract=ACTIVITY_GROUP_MEMBERSHIP_REMOVE,
    )


def activity_group_membership_private_items(
    candidates: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    return [
        {
            "row_index": item["row_index"],
            "zettel_id": item["zettel_id"],
            "canonical_path": item["relative_path"],
            "before_file_sha256": item["before_file_sha256"],
            "after_file_sha256": item["after_file_sha256"],
            "before_snapshot": item["before_snapshot"],
        }
        for item in candidates
    ]


def preserve_activity_group_membership_before_snapshots(
    root: Path,
    *,
    candidates: list[dict[str, Any]],
    archive_id: str,
    captured_at: str,
    reviewed_by: str,
    write_plan_sha256: str,
    operation_contract: _ActivityGroupMembershipOperationContract = (
        ACTIVITY_GROUP_MEMBERSHIP_ADD
    ),
) -> dict[str, int]:
    bytes_written = 0
    records_appended = 0
    manifest_path = archive_internal_path(
        root,
        "objects/manifests/files.jsonl",
    )
    with _ObjetCaptureManifestLock(root):
        manifest_index, manifest_blockers = (
            zet_revision_snapshot_manifest_index(root)
        )
        if manifest_blockers:
            raise ArchiveServiceError(manifest_blockers[0])
        pending_records: list[dict[str, Any]] = []
        for item in candidates:
            snapshot = item["before_snapshot"]
            if _write_or_verify_zet_title_remap_snapshot_bytes(
                root,
                canonical_bytes=item["before_bytes"],
                snapshot=snapshot,
            ):
                bytes_written += 1
            object_id = snapshot["object_id"]
            digest = object_id.removeprefix("sha256:")
            logical_key = snapshot["logical_key"]

            def record_is_complete(record: Any) -> bool:
                if not isinstance(record, dict):
                    return False
                locations = record.get("locations")
                return bool(
                    record.get("logical_key") == logical_key
                    and record.get("sha256") == digest
                    and record.get("mime") == "text/markdown"
                    and record.get("size_bytes")
                    == len(item["before_bytes"])
                    and isinstance(locations, list)
                    and any(
                        isinstance(location, dict)
                        and location.get("provider") == "local"
                        and location.get("path") == logical_key
                        and location.get("availability") == "available"
                        for location in locations
                    )
                )

            if any(
                record_is_complete(record)
                for record in manifest_index.get(object_id, [])
            ):
                continue
            record = {
                "object_id": object_id,
                "sha256": digest,
                "logical_key": logical_key,
                "mime": "text/markdown",
                "size_bytes": len(item["before_bytes"]),
                "locations": [
                    {
                        "provider": "local",
                        "path": logical_key,
                        "availability": "available",
                    }
                ],
                "provenance": {
                    "created_in": f"archive:{archive_id}",
                    "source": operation_contract.snapshot_source,
                    "captured_at": captured_at,
                    "captured_by": reviewed_by,
                    operation_contract.snapshot_write_plan_field: (
                        write_plan_sha256
                    ),
                },
            }
            if validate_schema(
                record,
                "object-manifest-entry.schema.json",
            ):
                raise ArchiveServiceError(
                    "activity_group_before_snapshot_manifest_record_invalid"
                )
            pending_records.append(record)
            manifest_index.setdefault(object_id, []).append(record)
        _append_zet_title_remap_snapshot_manifest_records_atomic(
            manifest_path,
            pending_records,
        )
        records_appended = len(pending_records)
        final_index, final_blockers = (
            zet_revision_snapshot_manifest_index(root)
        )
        if final_blockers:
            raise ArchiveServiceError(final_blockers[0])
        for item in candidates:
            snapshot_blockers = verify_zet_revision_before_snapshot(
                root,
                item["before_snapshot"],
                expected_before_sha256=item["before_file_sha256"],
                manifest_index=final_index,
            )
            if snapshot_blockers:
                raise ArchiveServiceError(snapshot_blockers[0])
    return {
        "snapshot_objects_written_this_run": bytes_written,
        "manifest_records_appended_this_run": records_appended,
        "verified_snapshot_count": len(candidates),
    }


def _read_activity_group_evidence_json(
    root: Path,
    path: Path,
    *,
    max_bytes: int,
    unreadable_code: str,
) -> tuple[bytes, dict[str, Any]]:
    if (
        path.is_symlink()
        or not is_path_within_root(path, root)
        or zet_revision_path_has_symlink_component(root, path)
        or not path.is_file()
    ):
        raise ArchiveServiceError(unreadable_code)
    try:
        if path.stat().st_size > max_bytes:
            raise ArchiveServiceError(unreadable_code)
        with path.open("rb") as handle:
            raw = handle.read(max_bytes + 1)
        if len(raw) > max_bytes:
            raise ArchiveServiceError(unreadable_code)

        def reject_duplicate_pairs(
            pairs: list[tuple[str, Any]],
        ) -> dict[str, Any]:
            result: dict[str, Any] = {}
            for key, value in pairs:
                if key in result:
                    raise ValueError("duplicate_key")
                result[key] = value
            return result

        document = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=reject_duplicate_pairs,
        )
    except ArchiveServiceError:
        raise
    except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as exc:
        raise ArchiveServiceError(unreadable_code) from exc
    if not isinstance(document, dict):
        raise ArchiveServiceError(unreadable_code)
    return raw, document


def _activity_group_membership_binding_items(
    value: Any,
) -> list[Any]:
    if not isinstance(value, list):
        return []
    projected: list[Any] = []
    snapshot_fields = (
        "object_id",
        "logical_key",
        "size_bytes",
        "mime",
        "stored_sha256_verified",
        "manifest_registered",
    )
    for item in value:
        if not isinstance(item, dict):
            projected.append(None)
            continue
        snapshot = item.get("before_snapshot")
        projected.append(
            {
                "row_index": item.get("row_index"),
                "zettel_id": item.get("zettel_id"),
                "canonical_path": item.get("canonical_path"),
                "before_file_sha256": item.get("before_file_sha256"),
                "after_file_sha256": item.get("after_file_sha256"),
                "before_snapshot": (
                    {
                        field: snapshot.get(field)
                        for field in snapshot_fields
                    }
                    if isinstance(snapshot, dict)
                    else None
                ),
            }
        )
    return projected


def _activity_group_membership_receipt_journal_projection(
    document: dict[str, Any],
    *,
    receipt_relative_path: str,
    journal: bool,
    operation_contract: _ActivityGroupMembershipOperationContract = (
        ACTIVITY_GROUP_MEMBERSHIP_ADD
    ),
) -> dict[str, Any]:
    return {
        "schema": operation_contract.transaction_binding_schema,
        "membership_operation": operation_contract.operation,
        "recorded_at": document.get(
            "prepared_at" if journal else "applied_at"
        ),
        "archive_id": document.get("archive_id"),
        "request_sha256": document.get("request_sha256"),
        "review_plan_sha256": document.get("review_plan_sha256"),
        "write_plan_sha256": document.get("write_plan_sha256"),
        "anchor_zettel_id": document.get("anchor_zettel_id"),
        "reviewed_by": document.get("reviewed_by"),
        "human_affirmation": document.get("human_affirmation"),
        "final_receipt_path": (
            document.get("final_receipt_path")
            if journal
            else receipt_relative_path
        ),
        "item_count": document.get("item_count"),
        "items": _activity_group_membership_binding_items(
            document.get("items")
        ),
        "privacy_guards": {
            field: (
                document.get("privacy_guards", {}).get(field)
                if isinstance(document.get("privacy_guards"), dict)
                else None
            )
            for field in (
                "request_path_stored",
                "title_text_stored",
                "body_text_stored",
                "contains_private_zettel_ids_and_paths",
                "provider_api_called",
                "model_called",
                "network_called",
                "secret_store_or_environment_read",
            )
        },
    }


def _activity_group_membership_receipt_lock_projection(
    document: dict[str, Any],
    *,
    receipt_relative_path: str,
    lock: bool,
    operation_contract: _ActivityGroupMembershipOperationContract = (
        ACTIVITY_GROUP_MEMBERSHIP_ADD
    ),
) -> dict[str, Any]:
    request_sha256 = document.get("request_sha256")
    expected_journal_name: str | None = None
    expected_journal_path: str | None = None
    expected_receipt_path: str | None = None
    if (
        isinstance(request_sha256, str)
        and re.fullmatch(r"sha256:[0-9a-f]{64}", request_sha256)
    ):
        digest = request_sha256.removeprefix("sha256:")
        expected_journal_name = (
            f".{digest}{operation_contract.journal_suffix}"
        )
        expected_journal_path = (
            f"{operation_contract.request_prefix}{expected_journal_name}"
        )
        expected_receipt_path = (
            _activity_group_membership_receipt_relative_path(
                request_sha256,
                operation_contract,
            )
        )
    projection = {
        "schema": operation_contract.lock_receipt_binding_schema,
        "membership_operation": operation_contract.operation,
        "request_sha256": request_sha256,
        "review_plan_sha256": document.get("review_plan_sha256"),
        "write_plan_sha256": document.get("write_plan_sha256"),
        "final_receipt_path": (
            expected_receipt_path if lock else receipt_relative_path
        ),
        "transaction_binding_sha256": (
            document.get("transaction_binding_sha256")
            if lock
            else sha256_json_value(
                _activity_group_membership_receipt_journal_projection(
                    document,
                    receipt_relative_path=receipt_relative_path,
                    journal=False,
                    operation_contract=operation_contract,
                )
            )
        ),
    }
    if operation_contract.operation == "add":
        projection["transaction_journal_name"] = (
            document.get("transaction_journal_name")
            if lock
            else expected_journal_name
        )
        # Preserve the exact insertion order of the historical add projection.
        projection = {
            "schema": projection["schema"],
            "membership_operation": projection["membership_operation"],
            "request_sha256": projection["request_sha256"],
            "review_plan_sha256": projection["review_plan_sha256"],
            "write_plan_sha256": projection["write_plan_sha256"],
            "transaction_journal_name": projection[
                "transaction_journal_name"
            ],
            "final_receipt_path": projection["final_receipt_path"],
            "transaction_binding_sha256": projection[
                "transaction_binding_sha256"
            ],
        }
    else:
        projection["transaction_journal_path"] = (
            document.get("transaction_journal_path")
            if lock
            else expected_journal_path
        )
        projection = {
            "schema": projection["schema"],
            "membership_operation": projection["membership_operation"],
            "request_sha256": projection["request_sha256"],
            "review_plan_sha256": projection["review_plan_sha256"],
            "write_plan_sha256": projection["write_plan_sha256"],
            "transaction_journal_path": projection[
                "transaction_journal_path"
            ],
            "final_receipt_path": projection["final_receipt_path"],
            "transaction_binding_sha256": projection[
                "transaction_binding_sha256"
            ],
        }
    return projection


def activity_group_write_lock_matches_journal(
    lock_document: dict[str, Any],
    journal: dict[str, Any],
    *,
    operation_contract: _ActivityGroupMembershipOperationContract = (
        ACTIVITY_GROUP_MEMBERSHIP_ADD
    ),
) -> bool:
    if (
        lock_document.get("review_plan_sha256")
        != journal.get("review_plan_sha256")
        or lock_document.get("write_plan_sha256")
        != journal.get("write_plan_sha256")
    ):
        return False
    if (
        lock_document.get("schema")
        == "wom-kit/activity-group-membership-write-lock/v0.1"
    ):
        return operation_contract.operation == "add"
    receipt_relative = journal.get("final_receipt_path")
    if not isinstance(receipt_relative, str):
        return False
    return lock_document.get(
        "transaction_binding_sha256"
    ) == sha256_json_value(
        _activity_group_membership_receipt_journal_projection(
            journal,
            receipt_relative_path=receipt_relative,
            journal=True,
            operation_contract=operation_contract,
        )
    )


def read_activity_group_membership_receipt_for_cleanup(
    root: Path,
    receipt_path: Path,
    *,
    expected_sha256: str,
) -> tuple[bytes, dict[str, Any]]:
    """Read one cleanup-authorizing receipt only at its reviewed raw hash."""

    raw, document = _read_activity_group_evidence_json(
        root,
        receipt_path,
        max_bytes=ACTIVITY_GROUP_MEMBERSHIP_MAX_RECEIPT_BYTES,
        unreadable_code="activity_group_receipt_unreadable",
    )
    if (
        not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_sha256)
        or "sha256:" + hashlib.sha256(raw).hexdigest()
        != expected_sha256
    ):
        raise ArchiveServiceError(
            "activity_group_recovery_receipt_changed"
        )
    return raw, document


def verify_activity_group_membership_receipt(
    root: Path,
    receipt_path: Path,
    *,
    archive_id: str,
    request_sha256: str,
    expected_journal: dict[str, Any] | None = None,
    expected_write_lock: dict[str, Any] | None = None,
    operation_contract: _ActivityGroupMembershipOperationContract = (
        ACTIVITY_GROUP_MEMBERSHIP_ADD
    ),
) -> dict[str, Any]:
    blockers: list[str] = []
    try:
        receipt_bytes, receipt = _read_activity_group_evidence_json(
            root,
            receipt_path,
            max_bytes=ACTIVITY_GROUP_MEMBERSHIP_MAX_RECEIPT_BYTES,
            unreadable_code="activity_group_receipt_unreadable",
        )
    except ArchiveServiceError as exc:
        return {
            "ok": False,
            "blockers": [str(exc)],
            "items": [],
            "receipt_sha256": None,
        }
    if validate_schema(
        receipt,
        operation_contract.receipt_schema_filename,
    ):
        blockers.append("activity_group_receipt_schema_invalid")
    expected_relative = (
        _activity_group_membership_receipt_relative_path(
            request_sha256,
            operation_contract,
        )
    )
    try:
        actual_relative = archive_relative_path(receipt_path, root)
    except ArchivePathError:
        actual_relative = ""
    if (
        receipt.get("archive_id") != archive_id
        or receipt.get("request_sha256") != request_sha256
        or actual_relative != expected_relative
    ):
        blockers.append("activity_group_receipt_binding_invalid")
    transaction_binding_sha256: str | None = None
    if expected_journal is not None:
        receipt_projection = (
            _activity_group_membership_receipt_journal_projection(
                receipt,
                receipt_relative_path=actual_relative,
                journal=False,
                operation_contract=operation_contract,
            )
        )
        journal_projection = (
            _activity_group_membership_receipt_journal_projection(
                expected_journal,
                receipt_relative_path=actual_relative,
                journal=True,
                operation_contract=operation_contract,
            )
        )
        transaction_binding_sha256 = sha256_json_value(
            receipt_projection
        )
        if receipt_projection != journal_projection:
            blockers.append(
                "activity_group_receipt_journal_binding_invalid"
            )
    elif expected_write_lock is not None:
        receipt_projection = (
            _activity_group_membership_receipt_lock_projection(
                receipt,
                receipt_relative_path=actual_relative,
                lock=False,
                operation_contract=operation_contract,
            )
        )
        lock_projection = (
            _activity_group_membership_receipt_lock_projection(
                expected_write_lock,
                receipt_relative_path=actual_relative,
                lock=True,
                operation_contract=operation_contract,
            )
        )
        transaction_binding_sha256 = sha256_json_value(
            receipt_projection
        )
        if receipt_projection != lock_projection:
            blockers.append(
                "activity_group_receipt_write_lock_binding_invalid"
            )
    anchor_zettel_id = receipt.get("anchor_zettel_id")
    items = receipt.get("items")
    if (
        not isinstance(anchor_zettel_id, str)
        or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(anchor_zettel_id)
        or not isinstance(items, list)
        or receipt.get("item_count") != len(items)
    ):
        blockers.append("activity_group_receipt_shape_invalid")
        items = []
    public_items: list[dict[str, Any]] = []
    seen_rows: set[int] = set()
    seen_ids: set[str] = set()
    for item in items:
        item_blockers: list[str] = []
        row_index = item.get("row_index") if isinstance(item, dict) else None
        zettel_id = item.get("zettel_id") if isinstance(item, dict) else None
        canonical_relative = (
            item.get("canonical_path") if isinstance(item, dict) else None
        )
        if (
            not isinstance(row_index, int)
            or row_index < 0
            or row_index in seen_rows
            or not isinstance(zettel_id, str)
            or not ZETTEL_EDGE_ZETTEL_ID_RE.fullmatch(zettel_id)
            or zettel_id in seen_ids
            or canonical_relative != f"zettels/{zettel_id}.md"
            or zettel_id == anchor_zettel_id
        ):
            item_blockers.append(
                "activity_group_receipt_item_binding_invalid"
            )
        else:
            seen_rows.add(row_index)
            seen_ids.add(zettel_id)
            try:
                path = _activity_group_standard_canonical_path(
                    root,
                    zettel_id,
                )
                current_bytes, _stat = (
                    _read_activity_group_canonical_bytes(path)
                )
                frontmatter, _payload, _source = (
                    _parse_activity_group_canonical(current_bytes)
                )
                if frontmatter.get("id") != zettel_id:
                    raise ArchiveServiceError(
                        "member_frontmatter_identity_mismatch"
                    )
                state, current = _activity_group_current_membership(
                    frontmatter,
                    anchor_zettel_id,
                )
                if operation_contract.operation == "add":
                    if (
                        state != "already_member"
                        or anchor_zettel_id not in current
                    ):
                        raise ArchiveServiceError(
                            "activity_group_receipt_membership_missing"
                        )
                elif (
                    state != "ready_to_add"
                    or anchor_zettel_id in current
                ):
                    raise ArchiveServiceError(
                        "activity_group_removal_receipt_membership_present"
                    )
            except ArchiveServiceError as exc:
                item_blockers.append(str(exc))
            except (ArchivePathError, OSError, ValueError):
                item_blockers.append(
                    "activity_group_receipt_member_unavailable"
                )
        item_blockers = unique_preserve_order(item_blockers)
        public_items.append(
            {
                "row_index": row_index,
                "status": (
                    "verified_applied" if not item_blockers else "blocked"
                ),
                "blocker_codes": item_blockers,
            }
        )
        blockers.extend(item_blockers)
    blockers = unique_preserve_order(blockers)
    return {
        "ok": not blockers,
        "blockers": blockers,
        "items": public_items,
        "receipt_sha256": (
            "sha256:" + hashlib.sha256(receipt_bytes).hexdigest()
        ),
        "review_plan_sha256": receipt.get("review_plan_sha256"),
        "write_plan_sha256": receipt.get("write_plan_sha256"),
        "transaction_binding_sha256": transaction_binding_sha256,
        "review_affirmation_verified": (
            receipt.get("human_affirmation")
            == operation_contract.human_affirmation
        ),
    }


def verify_activity_group_membership_removal_receipt(
    root: Path,
    receipt_path: Path,
    *,
    archive_id: str,
    request_sha256: str,
    expected_journal: dict[str, Any] | None = None,
    expected_write_lock: dict[str, Any] | None = None,
) -> dict[str, Any]:
    return verify_activity_group_membership_receipt(
        root,
        receipt_path,
        archive_id=archive_id,
        request_sha256=request_sha256,
        expected_journal=expected_journal,
        expected_write_lock=expected_write_lock,
        operation_contract=ACTIVITY_GROUP_MEMBERSHIP_REMOVE,
    )


def _activity_group_membership_write(
    archive_root: Path | str,
    *,
    request_path: str,
    expected_request_sha256: str,
    expected_review_plan_sha256: str,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    affirm_memberships_reviewed: bool = False,
    max_members: int = ACTIVITY_GROUP_MEMBERSHIP_MAX_MEMBERS,
    progress_callback: Callable[
        [str, str, int | None, int | None], None
    ]
    | None = None,
    operation_contract: _ActivityGroupMembershipOperationContract,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    expected_request = str(expected_request_sha256 or "").strip()
    expected_review_plan = str(
        expected_review_plan_sha256 or ""
    ).strip()
    reviewer = safe_foreign_quarantine_actor_id(reviewed_by)
    requested_max_members = int(max_members)
    effective_max_members = max(
        1,
        min(
            requested_max_members,
            ACTIVITY_GROUP_MEMBERSHIP_MAX_MEMBERS,
        ),
    )
    blockers: list[str] = []
    warnings: list[str] = []
    actual_request_sha256: str | None = None
    actual_review_plan_sha256: str | None = None
    actual_write_plan_sha256: str | None = None
    receipt_relative: str | None = None
    receipt_sha256: str | None = None
    receipt_exists = False
    receipt_written_this_run = False
    transaction_journal_path: Path | None = None
    transaction_journal_written = False
    transaction_journal_removed: bool | None = None
    final_transaction_inventory_clean: bool | None = None
    coordination_private_root = _activity_group_private_root(root)
    operation_private_root = _activity_group_operation_private_root(
        root,
        operation_contract,
    )
    write_lock_path = (
        coordination_private_root
        / ACTIVITY_GROUP_MEMBERSHIP_WRITE_LOCK_NAME
    )
    recovery_guard_path = (
        coordination_private_root
        / ACTIVITY_GROUP_MEMBERSHIP_RECOVERY_GUARD_NAME
    )
    write_lock_removed: bool | None = None
    canonical_files_written: int | None = 0
    canonical_write_attempt_count = 0
    public_items: list[dict[str, Any]] = []
    snapshot_result = {
        "snapshot_objects_written_this_run": 0,
        "manifest_records_appended_this_run": 0,
        "verified_snapshot_count": 0,
    }
    rollback: dict[str, Any] = {
        "attempted": False,
        "succeeded": None,
        "canonical_files_restored": 0,
        "receipt_removed": None,
        "transaction_journal_removed": None,
        "transaction_journal_retained": None,
        "write_lock_removed": None,
    }
    ready_action_count = 0
    already_satisfied_count = 0
    requested_member_count = 0

    def result_payload(status: str) -> dict[str, Any]:
        return {
            "ok": (
                status
                in {
                    "ready_to_apply",
                    "applied",
                    "already_applied",
                    "already_satisfied",
                }
                and not blockers
            ),
            "schema": operation_contract.write_schema,
            "lifecycle_action": operation_contract.write_action,
            "status": status,
            "dry_run": bool(dry_run),
            "approved": bool(approve and status == "applied"),
            "archive_id": archive_id,
            "request": {
                "sha256": actual_request_sha256,
                "expected_sha256_matches": bool(
                    actual_request_sha256
                    and actual_request_sha256 == expected_request
                ),
                "path_echoed": False,
                "tracking_policy": "private_ai_working_file_do_not_commit",
            },
            "review_plan_sha256": actual_review_plan_sha256,
            "expected_review_plan_sha256_matches": bool(
                actual_review_plan_sha256
                and actual_review_plan_sha256 == expected_review_plan
            ),
            "write_plan_sha256": actual_write_plan_sha256,
            "summary": {
                "requested_member_count": requested_member_count,
                operation_contract.ready_count_key: ready_action_count,
                operation_contract.already_count_key: (
                    already_satisfied_count
                ),
                "canonical_files_written_this_run": (
                    canonical_files_written
                ),
                "canonical_write_attempt_count": (
                    canonical_write_attempt_count
                ),
                "max_members": effective_max_members,
            },
            "items": public_items,
            "human_review": {
                "required_for_new_write": True,
                "reviewed_by_supplied": bool(reviewer),
                "reviewed_by_echoed": False,
                (
                    "all_removals_reviewed_affirmed"
                    if operation_contract.operation == "remove"
                    else "all_memberships_reviewed_affirmed"
                ): bool(affirm_memberships_reviewed),
            },
            "receipt": {
                "path": receipt_relative,
                "path_contains_only_request_digest": bool(receipt_relative),
                "exists": receipt_exists,
                "written_this_run": receipt_written_this_run,
                "sha256": receipt_sha256,
                "contains_private_zettel_ids_and_paths": (
                    True if receipt_exists else None
                ),
                "contains_title_or_body_text": (
                    False if receipt_exists else None
                ),
            },
            "transaction_journal": {
                "written_before_first_canonical_write": (
                    True if transaction_journal_written else None
                ),
                "exists": bool(
                    transaction_journal_path
                    and transaction_journal_path.exists()
                ),
                "removed_after_completion": (
                    transaction_journal_removed
                ),
                "contains_private_zettel_ids_and_paths": (
                    True if transaction_journal_written else None
                ),
                "contains_title_or_body_text": False,
                "path_echoed": False,
            },
            "prior_byte_snapshots": {
                **snapshot_result,
                "content_addressed": True,
                "exact_complete_before_file_bytes": True,
                "paths_echoed": False,
                "remote_backup_proven": False,
            },
            "write_boundary": {
                "field_changed": "frontmatter.facets.activity_group",
                "event_anchor_changed": False,
                "body_bytes_changed": (
                    None
                    if status == "failed_rollback_incomplete"
                    else False
                ),
                "other_frontmatter_semantics_changed": (
                    None
                    if status == "failed_rollback_incomplete"
                    else False
                ),
                "updated_at_changed": (
                    None
                    if status == "failed_rollback_incomplete"
                    else False
                ),
                "membership_inferred": False,
                "membership_removal_implemented": (
                    operation_contract.membership_removal_implemented
                ),
                "temporary_write_lock_removed": write_lock_removed,
                "provider_state_written": False,
                "database_rows_written": False,
            },
            "rollback": rollback,
            "privacy_guards": {
                "request_path_echoed": False,
                "zettel_ids_echoed": False,
                "zettel_paths_echoed": False,
                "zettel_titles_echoed": False,
                "facet_values_echoed": False,
                "body_text_echoed": False,
                "reviewed_by_echoed": False,
                "absolute_local_paths_echoed": False,
                "provider_urls_echoed": False,
                "provider_api_called": False,
                "model_called": False,
                "network_called": False,
                "secret_store_or_environment_read": False,
            },
            "blockers": unique_preserve_order(blockers),
            "warnings": unique_preserve_order(warnings),
            "next_safe_actions": (
                [
                    (
                        "Use the immutable private receipt as removal evidence and retain the prior-byte snapshots."
                        if operation_contract.operation == "remove"
                        else "Use the immutable private receipt as membership evidence and retain the prior-byte snapshots."
                    )
                ]
                if status == "applied"
                else [
                    (
                        "No write is needed; the private receipt verifies and every named anchor remains absent."
                        if operation_contract.operation == "remove"
                        else "No write is needed; the private receipt verifies and every recorded membership remains present."
                    )
                ]
                if status == "already_applied"
                else [
                    (
                        "No write is needed; every explicitly requested membership is already absent."
                        if operation_contract.operation == "remove"
                        else "No write is needed; every explicitly requested membership is already present."
                    )
                ]
                if status == "already_satisfied"
                else [
                    (
                        "Run the unchanged removal request with --approve, the exact request and review-plan digests, a safe reviewer id, and the explicit removal-review affirmation."
                        if operation_contract.operation == "remove"
                        else "Run the unchanged request with --approve, the exact request and review-plan digests, a safe reviewer id, and the explicit membership-review affirmation."
                    )
                ]
                if status == "ready_to_apply"
                else [
                    "Do not mutate or delete retained activity-group transaction evidence; resolve it through the approved recovery workflow before retrying."
                ]
                if any(
                    code
                    in {
                        "activity_group_unresolved_transaction_evidence_exists",
                        "activity_group_transaction_evidence_scan_failed",
                    }
                    for code in blockers
                )
                else [
                    "Fix content-free blockers and rerun the read-only membership plan before approving any write."
                ]
            ),
        }

    if bool(dry_run) == bool(approve):
        blockers.append("choose_exactly_one_of_dry_run_or_approve")
    if requested_max_members != effective_max_members:
        blockers.append("max_members_out_of_range")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", expected_request):
        blockers.append("expected_request_sha256_invalid")
    if not re.fullmatch(
        r"sha256:[0-9a-f]{64}",
        expected_review_plan,
    ):
        blockers.append("expected_review_plan_sha256_invalid")

    try:
        request_bytes, request_document = (
            _activity_group_private_request(
                root,
                request_path,
                operation_contract,
            )
        )
    except ArchiveServiceError as exc:
        blockers.append(str(exc))
        return result_payload("blocked")
    actual_request_sha256 = (
        "sha256:" + hashlib.sha256(request_bytes).hexdigest()
    )
    request_members = request_document.get("member_zettel_ids")
    requested_member_count = (
        len(request_members) if isinstance(request_members, list) else 0
    )
    if actual_request_sha256 != expected_request:
        blockers.append("request_sha256_mismatch")
    try:
        receipt_relative = (
            _activity_group_membership_receipt_relative_path(
                actual_request_sha256,
                operation_contract,
            )
        )
        transaction_journal_path = (
            _activity_group_membership_transaction_journal_path(
                root,
                actual_request_sha256,
                operation_contract,
            )
        )
    except ValueError:
        blockers.append("request_sha256_invalid")
        return result_payload("blocked")
    if blockers:
        return result_payload("blocked")

    transaction_evidence_scan = (
        scan_activity_group_transaction_evidence(root)
    )
    blockers.extend(transaction_evidence_scan["blockers"])
    if blockers:
        return result_payload("blocked")

    receipt_path = _activity_group_membership_receipt_path(
        root,
        actual_request_sha256,
        operation_contract,
    )
    if not activity_group_membership_receipt_path_is_safe(
        root,
        receipt_path,
    ):
        blockers.append("activity_group_receipt_path_unsafe")
        return result_payload("blocked")
    if receipt_path.exists():
        receipt_exists = True
        if write_lock_path.exists():
            warnings.append(
                "activity_group_write_lock_remains_inspect_before_cleanup"
            )
        if (
            transaction_journal_path is not None
            and transaction_journal_path.exists()
        ):
            warnings.append(
                "completed_activity_group_transaction_journal_remains"
            )
        verification = verify_activity_group_membership_receipt(
            root,
            receipt_path,
            archive_id=archive_id,
            request_sha256=actual_request_sha256,
            operation_contract=operation_contract,
        )
        receipt_sha256 = verification.get("receipt_sha256")
        actual_review_plan_sha256 = verification.get(
            "review_plan_sha256"
        )
        actual_write_plan_sha256 = verification.get(
            "write_plan_sha256"
        )
        blockers.extend(
            str(item) for item in verification.get("blockers", [])
        )
        if actual_review_plan_sha256 != expected_review_plan:
            blockers.append(
                "existing_receipt_review_plan_sha256_mismatch"
            )
        current_plan = _activity_group_membership_plan(
            root,
            request_path=request_path,
            dry_run=True,
            max_members=effective_max_members,
            progress_callback=None,
            operation=operation_contract.operation,
            request_schema=operation_contract.request_schema,
            request_prefix=operation_contract.request_prefix,
            plan_schema=operation_contract.plan_schema,
            future_write_implemented=True,
            planned_write_command=(
                "archive activity-group-membership-removal-write"
                if operation_contract.operation == "remove"
                else "archive activity-group-membership-write"
            ),
        )
        current_plan_items = (
            current_plan.get("items")
            if isinstance(current_plan.get("items"), list)
            else []
        )
        if (
            not current_plan.get("ok")
            or len(current_plan_items) != requested_member_count
            or any(
                not isinstance(item, dict)
                or item.get("status") != operation_contract.already_status
                for item in current_plan_items
            )
        ):
            blockers.append(
                "existing_receipt_requested_membership_state_invalid"
            )
        public_items = [
            {
                "row_index": item.get("row_index"),
                "status": (
                    "verified_applied"
                    if item.get("status") == operation_contract.already_status
                    else "blocked"
                ),
                "current_file_sha256": item.get(
                    "current_file_sha256"
                ),
                "proposed_file_sha256": item.get(
                    "proposed_file_sha256"
                ),
                "blocker_codes": list(
                    item.get("blocker_codes") or []
                ),
            }
            for item in current_plan_items
            if isinstance(item, dict)
        ]
        ready_action_count = 0
        already_satisfied_count = sum(
            1
            for item in current_plan_items
            if isinstance(item, dict)
            and item.get("status") == operation_contract.already_status
        )
        return result_payload(
            "already_applied" if not blockers else "blocked"
        )

    if approve:
        if reviewer is None:
            blockers.append("safe_reviewed_by_required")
        if not affirm_memberships_reviewed:
            blockers.append(
                operation_contract.affirmation_required_blocker
            )
    elif reviewed_by:
        blockers.append("reviewed_by_only_valid_with_approve")
    elif affirm_memberships_reviewed:
        blockers.append("affirmation_only_valid_with_approve")
    if blockers:
        return result_payload("blocked")

    plan = _activity_group_membership_plan(
        root,
        request_path=request_path,
        dry_run=True,
        max_members=effective_max_members,
        progress_callback=progress_callback,
        operation=operation_contract.operation,
        request_schema=operation_contract.request_schema,
        request_prefix=operation_contract.request_prefix,
        plan_schema=operation_contract.plan_schema,
        future_write_implemented=True,
        planned_write_command=(
            "archive activity-group-membership-removal-write"
            if operation_contract.operation == "remove"
            else "archive activity-group-membership-write"
        ),
    )
    actual_review_plan_sha256 = (
        plan.get("review_plan_sha256")
        if isinstance(plan.get("review_plan_sha256"), str)
        else None
    )
    if plan.get("request", {}).get("sha256") != actual_request_sha256:
        blockers.append("request_changed_during_plan")
    if not plan.get("ok"):
        blockers.extend(
            f"plan:{item}" for item in plan.get("blockers", [])
        )
    if actual_review_plan_sha256 != expected_review_plan:
        blockers.append("review_plan_sha256_mismatch")
    plan_items = (
        plan.get("items") if isinstance(plan.get("items"), list) else []
    )
    public_items = [
        {
            "row_index": item.get("row_index"),
            "status": (
                "ready_to_apply"
                if item.get("status") == operation_contract.ready_status
                else item.get("status")
            ),
            "current_file_sha256": item.get("current_file_sha256"),
            "proposed_file_sha256": item.get("proposed_file_sha256"),
            "blocker_codes": list(item.get("blocker_codes") or []),
        }
        for item in plan_items
        if isinstance(item, dict)
    ]
    ready_action_count = int(
        plan.get("summary", {}).get(operation_contract.ready_count_key) or 0
    )
    already_satisfied_count = int(
        plan.get("summary", {}).get(operation_contract.already_count_key) or 0
    )
    if blockers:
        for item in public_items:
            if item.get("status") == "ready_to_apply":
                item["status"] = "blocked"
        return result_payload("blocked")

    candidates, materialize_blockers = (
        materialize_activity_group_membership_candidates(
            root,
            request_bytes=request_bytes,
            request_document=request_document,
            plan=plan,
            operation_contract=operation_contract,
        )
    )
    blockers.extend(materialize_blockers)
    if ready_action_count != len(candidates):
        blockers.append("activity_group_candidate_count_mismatch")
    if not candidates and already_satisfied_count:
        return result_payload(
            "already_satisfied" if not blockers else "blocked"
        )
    if not candidates:
        blockers.append("no_activity_group_write_candidates")
    anchor_sha256 = plan.get("anchor", {}).get(
        "current_file_sha256"
    )
    if not isinstance(anchor_sha256, str):
        blockers.append("anchor_sha256_unavailable")
    if blockers:
        return result_payload("blocked")
    assert actual_review_plan_sha256 is not None
    assert isinstance(anchor_sha256, str)
    actual_write_plan_sha256 = (
        activity_group_membership_write_plan_sha256(
            archive_id=archive_id,
            request_sha256=actual_request_sha256,
            review_plan_sha256=actual_review_plan_sha256,
            anchor_current_file_sha256=anchor_sha256,
            candidates=candidates,
            operation_contract=operation_contract,
        )
    )
    if dry_run:
        return result_payload("ready_to_apply")

    assert reviewer is not None
    assert transaction_journal_path is not None
    applied_at = (
        datetime.now(timezone.utc)
        .replace(microsecond=0)
        .isoformat()
        .replace("+00:00", "Z")
    )
    private_items = activity_group_membership_private_items(candidates)
    anchor_zettel_id = request_document["anchor_zettel_id"]
    mutation_contract = {
        "field_changed": "frontmatter.facets.activity_group",
        "anchor_changed": False,
        "body_bytes_preserved": True,
        "other_frontmatter_semantics_preserved": True,
        "updated_at_changed": False,
        "prior_byte_snapshots_verified_before_first_canonical_write": True,
        "rollback_on_runtime_failure": True,
        "crash_recovery_journal_written": True,
        "membership_inferred": False,
        "membership_removal_implemented": (
            operation_contract.membership_removal_implemented
        ),
    }
    private_privacy_guards = {
        "request_path_stored": False,
        "title_text_stored": False,
        "body_text_stored": False,
        "contains_private_zettel_ids_and_paths": True,
        "provider_api_called": False,
        "model_called": False,
        "network_called": False,
        "secret_store_or_environment_read": False,
    }
    receipt = {
        "schema": operation_contract.receipt_schema,
        "action": operation_contract.write_action,
        "status": "applied",
        "applied_at": applied_at,
        "archive_id": archive_id,
        "request_sha256": actual_request_sha256,
        "review_plan_sha256": actual_review_plan_sha256,
        "write_plan_sha256": actual_write_plan_sha256,
        "anchor_zettel_id": anchor_zettel_id,
        "reviewed_by": reviewer,
        "human_affirmation": operation_contract.human_affirmation,
        "item_count": len(private_items),
        "items": private_items,
        "mutation_contract": mutation_contract,
        "privacy_guards": private_privacy_guards,
    }
    if validate_schema(
        receipt,
        operation_contract.receipt_schema_filename,
    ):
        blockers.append("activity_group_receipt_schema_validation_failed")
        return result_payload("blocked")
    journal = {
        "schema": operation_contract.transaction_journal_schema,
        "action": operation_contract.transaction_action,
        "status": "prepared",
        "operation": operation_contract.journal_operation,
        "prepared_at": applied_at,
        "archive_id": archive_id,
        "request_sha256": actual_request_sha256,
        "review_plan_sha256": actual_review_plan_sha256,
        "write_plan_sha256": actual_write_plan_sha256,
        "anchor_zettel_id": anchor_zettel_id,
        "reviewed_by": reviewer,
        "human_affirmation": operation_contract.human_affirmation,
        "final_receipt_path": receipt_relative,
        "item_count": len(private_items),
        "items": private_items,
        "recovery_contract": {
            "journal_published_before_first_canonical_write": True,
            "current_state_inferred_from_participant_hashes": True,
            "prior_byte_snapshots_verified_before_journal": True,
            "automatic_resume_implemented": False,
            "automatic_rollback_after_runtime_failure": True,
            "approved_recovery_command_required_after_hard_exit": True,
        },
        "privacy_guards": private_privacy_guards,
    }
    journal["journal_digest"] = sha256_json_value(journal)
    if validate_schema(
        journal,
        operation_contract.journal_schema_filename,
    ):
        blockers.append(
            "activity_group_transaction_journal_schema_validation_failed"
        )
        return result_payload("blocked")

    if recovery_guard_path.exists():
        blockers.append("activity_group_recovery_guard_exists")
        return result_payload("blocked")
    lock_transaction_binding_sha256 = sha256_json_value(
        _activity_group_membership_receipt_journal_projection(
            receipt,
            receipt_relative_path=receipt_relative,
            journal=False,
            operation_contract=operation_contract,
        )
    )
    if operation_contract.operation == "add":
        # v0.1/v0.2 add evidence is a public compatibility boundary.
        lock_document = {
            "schema": operation_contract.write_lock_schema,
            "request_sha256": actual_request_sha256,
            "review_plan_sha256": actual_review_plan_sha256,
            "write_plan_sha256": actual_write_plan_sha256,
            "transaction_journal_name": transaction_journal_path.name,
            "transaction_binding_sha256": (
                lock_transaction_binding_sha256
            ),
        }
    else:
        lock_document = {
            "schema": operation_contract.write_lock_schema,
            "membership_operation": operation_contract.operation,
            "request_sha256": actual_request_sha256,
            "review_plan_sha256": actual_review_plan_sha256,
            "write_plan_sha256": actual_write_plan_sha256,
            "transaction_journal_path": archive_relative_path(
                transaction_journal_path,
                root,
            ),
            "transaction_binding_sha256": (
                lock_transaction_binding_sha256
            ),
        }
    lock_raw = (
        json.dumps(
            lock_document,
            ensure_ascii=False,
            separators=(",", ":"),
        )
        + "\n"
    ).encode("utf-8")
    lock_sha256 = (
        "sha256:" + hashlib.sha256(lock_raw).hexdigest()
    )
    private_root_context = _activity_group_bound_directory_chain(
        root,
        write_lock_path.parent,
        create=True,
    )
    private_root_context_entered = False
    private_root_context_closed = False
    operation_root_context: Any | None = None
    operation_root_context_entered = False
    operation_root_context_closed = False
    journal_root_binding: dict[str, Any] | None = None

    def close_private_root_context() -> None:
        nonlocal private_root_context_closed
        try:
            close_operation_root_context()
        finally:
            if (
                private_root_context_entered
                and not private_root_context_closed
            ):
                private_root_context.__exit__(None, None, None)
                private_root_context_closed = True

    def close_operation_root_context() -> None:
        nonlocal operation_root_context_closed
        if (
            operation_root_context_entered
            and not operation_root_context_closed
            and operation_root_context is not None
        ):
            operation_root_context.__exit__(None, None, None)
            operation_root_context_closed = True

    try:
        private_root_binding = private_root_context.__enter__()
        private_root_context_entered = True
        _write_activity_group_bytes_new_file_bound(
            private_root_binding,
            write_lock_path,
            lock_raw,
        )
        if recovery_guard_path.exists():
            try:
                _delete_activity_group_evidence_exact(
                    root,
                    write_lock_path,
                    expected_sha256=lock_sha256,
                    max_bytes=(
                        ACTIVITY_GROUP_MEMBERSHIP_MAX_LOCK_BYTES
                    ),
                    parent_binding=private_root_binding,
                )
                write_lock_removed = True
            except OSError:
                write_lock_removed = False
            blockers.append("activity_group_recovery_guard_exists")
            close_private_root_context()
            return result_payload("blocked")
    except FileExistsError:
        blockers.append("activity_group_write_lock_exists")
        close_private_root_context()
        return result_payload("blocked")
    except OSError:
        try:
            if write_lock_path.exists():
                _delete_activity_group_evidence_exact(
                    root,
                    write_lock_path,
                    expected_sha256=lock_sha256,
                    max_bytes=(
                        ACTIVITY_GROUP_MEMBERSHIP_MAX_LOCK_BYTES
                    ),
                    parent_binding=private_root_binding,
                )
        except OSError:
            pass
        blockers.append("activity_group_write_lock_create_failed")
        close_private_root_context()
        return result_payload("blocked")

    try:
        locked_transaction_evidence_scan = (
            scan_activity_group_transaction_evidence(root)
        )
    except (OSError, ValueError):
        locked_transaction_evidence_scan = {
            "ok": False,
            "blockers": [
                "activity_group_transaction_evidence_scan_failed"
            ],
        }
    if not locked_transaction_evidence_scan.get("ok"):
        blockers.extend(
            locked_transaction_evidence_scan.get("blockers", [])
        )
        try:
            if write_lock_path.exists():
                _delete_activity_group_evidence_exact(
                    root,
                    write_lock_path,
                    expected_sha256=lock_sha256,
                    max_bytes=(
                        ACTIVITY_GROUP_MEMBERSHIP_MAX_LOCK_BYTES
                    ),
                    parent_binding=private_root_binding,
                )
            write_lock_removed = not write_lock_path.exists()
        except OSError:
            write_lock_removed = False
        close_private_root_context()
        return result_payload("blocked")

    if operation_private_root == coordination_private_root:
        journal_root_binding = private_root_binding
    else:
        try:
            operation_root_context = _activity_group_bound_directory_chain(
                root,
                operation_private_root,
                create=True,
            )
            journal_root_binding = operation_root_context.__enter__()
            operation_root_context_entered = True
        except (OSError, ValueError):
            try:
                _delete_activity_group_evidence_exact(
                    root,
                    write_lock_path,
                    expected_sha256=lock_sha256,
                    max_bytes=ACTIVITY_GROUP_MEMBERSHIP_MAX_LOCK_BYTES,
                    parent_binding=private_root_binding,
                )
                write_lock_removed = True
            except OSError:
                write_lock_removed = False
            blockers.append(
                "activity_group_transaction_journal_root_unsafe"
            )
            close_operation_root_context()
            close_private_root_context()
            return result_payload("blocked")
    assert journal_root_binding is not None

    try:
        locked_request_bytes, locked_request_document = (
            _activity_group_private_request(
                root,
                request_path,
                operation_contract,
            )
        )
        locked_request_sha256 = (
            "sha256:"
            + hashlib.sha256(locked_request_bytes).hexdigest()
        )
        locked_plan = _activity_group_membership_plan(
            root,
            request_path=request_path,
            dry_run=True,
            max_members=effective_max_members,
            progress_callback=None,
            operation=operation_contract.operation,
            request_schema=operation_contract.request_schema,
            request_prefix=operation_contract.request_prefix,
            plan_schema=operation_contract.plan_schema,
            future_write_implemented=True,
            planned_write_command=(
                "archive activity-group-membership-removal-write"
                if operation_contract.operation == "remove"
                else "archive activity-group-membership-write"
            ),
        )
        locked_review_plan_sha256 = locked_plan.get(
            "review_plan_sha256"
        )
        locked_candidates, locked_blockers = (
            materialize_activity_group_membership_candidates(
                root,
                request_bytes=locked_request_bytes,
                request_document=locked_request_document,
                plan=locked_plan,
                operation_contract=operation_contract,
            )
        )
        locked_anchor_sha256 = locked_plan.get("anchor", {}).get(
            "current_file_sha256"
        )
        locked_write_plan_sha256 = (
            activity_group_membership_write_plan_sha256(
                archive_id=archive_id,
                request_sha256=locked_request_sha256,
                review_plan_sha256=locked_review_plan_sha256,
                anchor_current_file_sha256=locked_anchor_sha256,
                candidates=locked_candidates,
                operation_contract=operation_contract,
            )
            if (
                locked_plan.get("ok")
                and isinstance(locked_review_plan_sha256, str)
                and isinstance(locked_anchor_sha256, str)
                and not locked_blockers
            )
            else None
        )
        if (
            locked_request_sha256 != actual_request_sha256
            or locked_review_plan_sha256
            != actual_review_plan_sha256
            or locked_write_plan_sha256
            != actual_write_plan_sha256
        ):
            raise ArchiveServiceError(
                "activity_group_candidate_changed_under_lock"
            )
        candidates = locked_candidates
        snapshot_result = (
            preserve_activity_group_membership_before_snapshots(
                root,
                candidates=candidates,
                archive_id=archive_id,
                captured_at=applied_at,
                reviewed_by=reviewer,
                write_plan_sha256=actual_write_plan_sha256,
                operation_contract=operation_contract,
            )
        )
    except Exception:
        try:
            if write_lock_path.exists():
                _delete_activity_group_evidence_exact(
                    root,
                    write_lock_path,
                    expected_sha256=lock_sha256,
                    max_bytes=(
                        ACTIVITY_GROUP_MEMBERSHIP_MAX_LOCK_BYTES
                    ),
                    parent_binding=private_root_binding,
                )
            write_lock_removed = not write_lock_path.exists()
        except OSError:
            write_lock_removed = False
        blockers.append(
            "activity_group_write_preflight_or_snapshot_failed"
        )
        close_private_root_context()
        return result_payload("blocked")

    journal_raw = activity_group_evidence_json_bytes(journal)
    journal_sha256 = (
        "sha256:" + hashlib.sha256(journal_raw).hexdigest()
    )
    try:
        _write_activity_group_bytes_new_file_bound(
            journal_root_binding,
            transaction_journal_path,
            journal_raw,
        )
        journal_raw, written_journal = (
            read_activity_group_membership_transaction_journal(
                root,
                transaction_journal_path,
                archive_id=archive_id,
                request_sha256=actual_request_sha256,
                operation_contract=operation_contract,
            )
        )
        if written_journal != journal:
            raise OSError(
                "activity_group_transaction_journal_write_changed"
            )
        journal_sha256 = (
            "sha256:" + hashlib.sha256(journal_raw).hexdigest()
        )
        transaction_journal_written = True
    except FileExistsError:
        try:
            _delete_activity_group_evidence_exact(
                root,
                write_lock_path,
                expected_sha256=lock_sha256,
                max_bytes=(
                    ACTIVITY_GROUP_MEMBERSHIP_MAX_LOCK_BYTES
                ),
                parent_binding=private_root_binding,
            )
            write_lock_removed = True
        except OSError:
            write_lock_removed = False
        blockers.append("activity_group_transaction_journal_exists")
        close_private_root_context()
        return result_payload("blocked")
    except OSError:
        try:
            if write_lock_path.exists():
                _delete_activity_group_evidence_exact(
                    root,
                    write_lock_path,
                    expected_sha256=lock_sha256,
                    max_bytes=(
                        ACTIVITY_GROUP_MEMBERSHIP_MAX_LOCK_BYTES
                    ),
                    parent_binding=private_root_binding,
                )
            write_lock_removed = not write_lock_path.exists()
        except OSError:
            write_lock_removed = False
        blockers.append(
            "activity_group_transaction_journal_create_failed"
        )
        close_private_root_context()
        return result_payload("blocked")

    attempted_candidates: list[dict[str, Any]] = []
    receipt_parent_existed = receipt_path.parent.exists()
    receipt_parent_context = _activity_group_bound_directory_chain(
        root,
        receipt_path.parent,
        create=True,
    )
    try:
        receipt_parent_binding = receipt_parent_context.__enter__()
    except (OSError, ValueError):
        try:
            _delete_activity_group_evidence_exact(
                root,
                write_lock_path,
                expected_sha256=lock_sha256,
                max_bytes=(
                    ACTIVITY_GROUP_MEMBERSHIP_MAX_LOCK_BYTES
                ),
                parent_binding=private_root_binding,
            )
            write_lock_removed = True
        except OSError:
            write_lock_removed = False
        if write_lock_removed:
            try:
                _delete_activity_group_evidence_exact(
                    root,
                    transaction_journal_path,
                    expected_sha256=journal_sha256,
                    max_bytes=(
                        ACTIVITY_GROUP_MEMBERSHIP_MAX_TRANSACTION_JOURNAL_BYTES
                    ),
                    parent_binding=journal_root_binding,
                )
                transaction_journal_removed = True
            except OSError:
                transaction_journal_removed = False
        else:
            transaction_journal_removed = False
        blockers.append("activity_group_receipt_path_unsafe")
        close_private_root_context()
        return result_payload("blocked")
    receipt_write_attempted = False
    receipt_owned_this_run = False
    receipt_raw: bytes | None = None
    receipt_expected_sha256: str | None = None
    try:
        if progress_callback is not None:
            progress_callback(
                operation_contract.progress_write,
                "start",
                0,
                len(candidates),
            )
        for index, item in enumerate(candidates, start=1):
            current_bytes, _stat = (
                _read_activity_group_canonical_bytes(item["path"])
            )
            if current_bytes != item["before_bytes"]:
                raise RuntimeError(
                    "canonical_changed_immediately_before_write"
                )
            attempted_candidates.append(item)
            canonical_write_attempt_count += 1
            _replace_activity_group_canonical_bytes_compare_and_swap(
                root,
                item["path"],
                expected_bytes=item["before_bytes"],
                replacement_bytes=item["after_bytes"],
                request_sha256=actual_request_sha256,
            )
            written_bytes, _written_stat = (
                _read_activity_group_canonical_bytes(item["path"])
            )
            if written_bytes != item["after_bytes"]:
                raise RuntimeError(
                    "canonical_write_verification_failed"
                )
            canonical_files_written += 1
            public_items[item["row_index"]]["status"] = "applied"
            if progress_callback is not None:
                progress_callback(
                    operation_contract.progress_write,
                    "written",
                    index,
                    len(candidates),
                )
        for item in candidates:
            current_bytes, _stat = (
                _read_activity_group_canonical_bytes(item["path"])
            )
            current_sha256 = (
                "sha256:" + hashlib.sha256(current_bytes).hexdigest()
            )
            if current_sha256 != item["after_file_sha256"]:
                raise RuntimeError(
                    "canonical_batch_revalidation_failed"
                )
        if progress_callback is not None:
            progress_callback(
                operation_contract.progress_write,
                "done",
                len(candidates),
                len(candidates),
            )
            progress_callback(
                operation_contract.progress_receipt,
                "start",
                None,
                None,
            )
        receipt_write_attempted = True
        try:
            receipt_raw = activity_group_evidence_json_bytes(receipt)
            receipt_expected_sha256 = (
                "sha256:" + hashlib.sha256(receipt_raw).hexdigest()
            )
            _write_activity_group_bytes_new_file_bound(
                receipt_parent_binding,
                receipt_path,
                receipt_raw,
            )
            receipt_owned_this_run = True
        except FileExistsError:
            receipt_write_attempted = False
            raise RuntimeError("receipt_created_concurrently")
        except Exception:
            raise
        with _hold_activity_group_evidence_file(
            root,
            receipt_path,
            max_bytes=ACTIVITY_GROUP_MEMBERSHIP_MAX_RECEIPT_BYTES,
        ) as held_receipt:
            held_receipt_sha256 = (
                "sha256:"
                + hashlib.sha256(held_receipt["raw"]).hexdigest()
            )
            verification = verify_activity_group_membership_receipt(
                root,
                receipt_path,
                archive_id=archive_id,
                request_sha256=actual_request_sha256,
                expected_journal=journal,
                operation_contract=operation_contract,
            )
            if (
                not verification.get("ok")
                or verification.get("receipt_sha256")
                != held_receipt_sha256
            ):
                raise RuntimeError(
                    "written_receipt_verification_failed"
                )
            receipt_exists = True
            receipt_written_this_run = True
            receipt_sha256 = held_receipt_sha256
            try:
                lock_bytes, current_lock_document = (
                    read_activity_group_membership_write_lock(
                        root,
                        write_lock_path,
                        request_sha256=actual_request_sha256,
                        operation_contract=operation_contract,
                    )
                )
                if (
                    "sha256:"
                    + hashlib.sha256(lock_bytes).hexdigest()
                    != lock_sha256
                    or current_lock_document != lock_document
                    or not activity_group_write_lock_matches_journal(
                        current_lock_document,
                        journal,
                        operation_contract=operation_contract,
                    )
                ):
                    raise OSError(
                        "activity_group_write_lock_changed_before_cleanup"
                    )
                _delete_activity_group_evidence_exact(
                    root,
                    write_lock_path,
                    expected_sha256=lock_sha256,
                    max_bytes=(
                        ACTIVITY_GROUP_MEMBERSHIP_MAX_LOCK_BYTES
                    ),
                    parent_binding=private_root_binding,
                )
                write_lock_removed = True
            except (ArchiveServiceError, OSError):
                write_lock_removed = False
                final_transaction_inventory_clean = False
                warnings.append(
                    "activity_group_write_lock_cleanup_failed"
                )
            if write_lock_removed:
                try:
                    verification = (
                        verify_activity_group_membership_receipt(
                            root,
                            receipt_path,
                            archive_id=archive_id,
                            request_sha256=actual_request_sha256,
                            expected_journal=journal,
                            operation_contract=operation_contract,
                        )
                    )
                    if (
                        not verification.get("ok")
                        or verification.get("receipt_sha256")
                        != held_receipt_sha256
                    ):
                        raise OSError(
                            "activity_group_receipt_changed_before_cleanup"
                        )
                    for item in candidates:
                        current_bytes, _stat = (
                            _read_activity_group_canonical_bytes(
                                item["path"]
                            )
                        )
                        if (
                            "sha256:"
                            + hashlib.sha256(current_bytes).hexdigest()
                            != item["after_file_sha256"]
                        ):
                            raise OSError(
                                "activity_group_participant_changed_before_cleanup"
                            )
                    cleanup_scan = (
                        scan_activity_group_transaction_evidence(root)
                    )
                    cleanup_paths = cleanup_scan.get("journal_paths")
                    if (
                        not cleanup_scan.get("complete")
                        or not isinstance(cleanup_paths, list)
                        or cleanup_paths != [transaction_journal_path]
                    ):
                        final_transaction_inventory_clean = False
                        raise OSError(
                            "activity_group_unresolved_transaction_evidence_exists"
                        )
                    _delete_activity_group_evidence_exact(
                        root,
                        transaction_journal_path,
                        expected_sha256=journal_sha256,
                        max_bytes=(
                            ACTIVITY_GROUP_MEMBERSHIP_MAX_TRANSACTION_JOURNAL_BYTES
                        ),
                        parent_binding=journal_root_binding,
                    )
                    transaction_journal_removed = True
                    final_scan = (
                        scan_activity_group_transaction_evidence(root)
                    )
                    if not final_scan.get("ok"):
                        final_transaction_inventory_clean = False
                        raise OSError(
                            "activity_group_unresolved_transaction_evidence_exists"
                        )
                    final_transaction_inventory_clean = True
                except (ArchiveServiceError, OSError):
                    final_transaction_inventory_clean = False
                    transaction_journal_removed = not (
                        transaction_journal_path.exists()
                        or transaction_journal_path.is_symlink()
                    )
                    warnings.append(
                        "completed_activity_group_transaction_journal_cleanup_failed"
                    )
            else:
                transaction_journal_removed = False
                final_transaction_inventory_clean = False
                warnings.append(
                    "activity_group_transaction_journal_retained_with_lock"
                )
        if progress_callback is not None:
            progress_callback(
                operation_contract.progress_receipt,
                "done",
                None,
                None,
            )
        if final_transaction_inventory_clean is False:
            blockers.append(
                "activity_group_unresolved_transaction_evidence_exists"
            )
            return result_payload("applied_evidence_conflict")
        return result_payload("applied")
    except Exception:
        rollback["attempted"] = bool(
            attempted_candidates or receipt_write_attempted
        )
        if (
            receipt_owned_this_run
            and receipt_expected_sha256 is not None
            and receipt_path.exists()
        ):
            try:
                _delete_activity_group_evidence_exact(
                    root,
                    receipt_path,
                    expected_sha256=receipt_expected_sha256,
                    max_bytes=(
                        ACTIVITY_GROUP_MEMBERSHIP_MAX_RECEIPT_BYTES
                    ),
                    parent_binding=receipt_parent_binding,
                )
            except OSError:
                pass
        receipt_removed = not receipt_path.exists()
        restored = 0
        canonical_restore_ok = True
        for item in reversed(attempted_candidates):
            try:
                current_bytes, _current_stat = (
                    _read_activity_group_canonical_bytes(item["path"])
                )
                if current_bytes == item["before_bytes"]:
                    _cleanup_activity_group_canonical_swap_residue(
                        root,
                        item["path"],
                        request_sha256=actual_request_sha256,
                        expected_current_sha256=(
                            item["before_file_sha256"]
                        ),
                        expected_complementary_sha256=(
                            item["after_file_sha256"]
                        ),
                    )
                elif current_bytes == item["after_bytes"]:
                    changed = (
                        _replace_activity_group_canonical_bytes_compare_and_swap(
                            root,
                            item["path"],
                            expected_bytes=item["after_bytes"],
                            replacement_bytes=item["before_bytes"],
                            request_sha256=actual_request_sha256,
                            allow_already_replacement=True,
                        )
                    )
                    if changed:
                        restored += 1
                else:
                    raise OSError(
                        "activity_group_rollback_participant_changed"
                    )
                restored_bytes, _restored_stat = (
                    _read_activity_group_canonical_bytes(item["path"])
                )
                if restored_bytes != item["before_bytes"]:
                    raise OSError(
                        "canonical_restore_verification_failed"
                    )
            except Exception:
                canonical_restore_ok = False
        rollback_evidence_consistent = True
        if canonical_restore_ok and receipt_removed:
            try:
                if write_lock_path.exists():
                    _delete_activity_group_evidence_exact(
                        root,
                        write_lock_path,
                        expected_sha256=lock_sha256,
                        max_bytes=(
                            ACTIVITY_GROUP_MEMBERSHIP_MAX_LOCK_BYTES
                        ),
                        parent_binding=private_root_binding,
                    )
                write_lock_removed = not write_lock_path.exists()
            except OSError:
                write_lock_removed = False
        else:
            write_lock_removed = False
        if (
            canonical_restore_ok
            and receipt_removed
            and write_lock_removed
        ):
            try:
                for item in candidates:
                    current_bytes, _current_stat = (
                        _read_activity_group_canonical_bytes(
                            item["path"]
                        )
                    )
                    if current_bytes != item["before_bytes"]:
                        raise OSError(
                            "activity_group_rollback_participant_changed"
                        )
                if receipt_path.exists():
                    raise OSError(
                        "activity_group_rollback_receipt_appeared"
                    )
                rollback_scan = (
                    scan_activity_group_transaction_evidence(root)
                )
                rollback_paths = rollback_scan.get("journal_paths")
                if (
                    not rollback_scan.get("complete")
                    or not isinstance(rollback_paths, list)
                    or rollback_paths != [transaction_journal_path]
                ):
                    raise OSError(
                        "activity_group_unresolved_transaction_evidence_exists"
                    )
                _delete_activity_group_evidence_exact(
                    root,
                    transaction_journal_path,
                    expected_sha256=journal_sha256,
                    max_bytes=(
                        ACTIVITY_GROUP_MEMBERSHIP_MAX_TRANSACTION_JOURNAL_BYTES
                    ),
                    parent_binding=journal_root_binding,
                )
                transaction_journal_removed = True
                final_rollback_scan = (
                    scan_activity_group_transaction_evidence(root)
                )
                if (
                    receipt_path.exists()
                    or not final_rollback_scan.get("ok")
                ):
                    rollback_evidence_consistent = False
            except (ArchiveServiceError, OSError):
                transaction_journal_removed = False
        else:
            transaction_journal_removed = False
        rollback["canonical_files_restored"] = restored
        rollback["receipt_removed"] = receipt_removed
        rollback["transaction_journal_removed"] = (
            transaction_journal_removed
        )
        rollback["transaction_journal_retained"] = bool(
            transaction_journal_path.exists()
        )
        rollback["write_lock_removed"] = write_lock_removed
        rollback["succeeded"] = bool(
            canonical_restore_ok
            and receipt_removed
            and transaction_journal_removed
            and write_lock_removed
            and rollback_evidence_consistent
        )
        canonical_files_written = (
            0 if rollback["succeeded"] else None
        )
        receipt_exists = receipt_path.exists()
        receipt_written_this_run = False
        attempted_rows = {
            item["row_index"] for item in attempted_candidates
        }
        for item in public_items:
            if item.get("row_index") in attempted_rows:
                item["status"] = (
                    "rolled_back"
                    if rollback["succeeded"]
                    else "recovery_required"
                )
            elif item.get("status") == "ready_to_apply":
                item["status"] = "not_attempted"
        blockers.append(
            "activity_group_transaction_failed_and_rolled_back"
            if rollback["succeeded"]
            else "activity_group_transaction_failed_recovery_required"
        )
        return result_payload(
            "failed_rolled_back"
            if rollback["succeeded"]
            else "failed_rollback_incomplete"
        )
    finally:
        receipt_parent_context.__exit__(None, None, None)
        close_private_root_context()
        if (
            not receipt_parent_existed
            and not receipt_path.exists()
        ):
            cleanup_empty_archive_dirs(root, [receipt_path])


def activity_group_membership_write(
    archive_root: Path | str,
    *,
    request_path: str,
    expected_request_sha256: str,
    expected_review_plan_sha256: str,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    affirm_memberships_reviewed: bool = False,
    max_members: int = ACTIVITY_GROUP_MEMBERSHIP_MAX_MEMBERS,
    progress_callback: Callable[
        [str, str, int | None, int | None], None
    ]
    | None = None,
) -> dict[str, Any]:
    if type(dry_run) is not bool or type(approve) is not bool or approve:
        return _compound_exact_human_approval_blocked(
            lifecycle_action="activity_group_membership_write",
        )
    return _activity_group_membership_write(
        archive_root,
        request_path=request_path,
        expected_request_sha256=expected_request_sha256,
        expected_review_plan_sha256=expected_review_plan_sha256,
        dry_run=dry_run,
        approve=approve,
        reviewed_by=reviewed_by,
        affirm_memberships_reviewed=affirm_memberships_reviewed,
        max_members=max_members,
        progress_callback=progress_callback,
        operation_contract=ACTIVITY_GROUP_MEMBERSHIP_ADD,
    )


