def imap_mailbox_material_capture_approval_audit(
    archive_root: Path | str,
    *,
    material_selection_receipt: str,
    approval_receipt: str,
    capture_action: str = "message_body_capture",
    expected_decision: str = "approve_once",
    dry_run: bool = True,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []

    if not dry_run:
        blockers.append("imap-mailbox-material-capture-approval-audit is read-only and requires --dry-run.")

    normalized_expected_decision = (expected_decision or "approve_once").strip().lower().replace("-", "_")
    if normalized_expected_decision not in IMAP_MAILBOX_MATERIAL_CAPTURE_APPROVAL_DECISIONS:
        blockers.append(
            "expected_decision must be one of: "
            + ", ".join(sorted(IMAP_MAILBOX_MATERIAL_CAPTURE_APPROVAL_DECISIONS))
            + "."
        )
        normalized_expected_decision = "approve_once"

    contract = imap_mailbox_material_capture_execution_contract(
        root,
        material_selection_receipt=material_selection_receipt,
        capture_action=capture_action,
        dry_run=True,
    )
    blockers.extend(str(item) for item in contract.get("blockers") or [])
    warnings.extend(str(item) for item in contract.get("warnings") or [])
    normalized_action = str(contract.get("capture_action") or "message_body_capture")
    material_summary = (
        contract.get("material_selection_summary")
        if isinstance(contract.get("material_selection_summary"), dict)
        else {}
    )
    future_contract = (
        contract.get("future_adapter_contract")
        if isinstance(contract.get("future_adapter_contract"), dict)
        else {}
    )
    allowed = (
        future_contract.get("allowed_actions_after_implementation_and_approval")
        if isinstance(future_contract.get("allowed_actions_after_implementation_and_approval"), dict)
        else {}
    )

    receipt_relative = (approval_receipt or "").strip().replace("\\", "/")
    if not receipt_relative:
        blockers.append("approval_receipt is required.")
    elif (
        receipt_relative.startswith("/")
        or ":" in receipt_relative
        or "\x00" in receipt_relative
        or ".." in receipt_relative.split("/")
        or not receipt_relative.startswith(f"{IMAP_MAILBOX_MATERIAL_CAPTURE_APPROVAL_RECEIPTS_DIR}/")
        or not receipt_relative.endswith(".json")
    ):
        blockers.append("approval_receipt must be an archive-relative IMAP material capture approval receipt JSON path.")

    approval_payload: dict[str, Any] = {}
    if not blockers:
        receipt_path = archive_internal_path(root, receipt_relative)
        if not receipt_path.is_file():
            blockers.append("approval_receipt file is missing.")
        else:
            try:
                loaded = json.loads(receipt_path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    approval_payload = loaded
                else:
                    blockers.append("approval_receipt must contain a JSON object.")
            except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                blockers.append("approval_receipt could not be read as UTF-8 JSON.")

    serialized_approval = json.dumps(json_safe(approval_payload), ensure_ascii=False, sort_keys=True, default=str)
    if approval_payload and (contains_forbidden_location_reference(serialized_approval) or DRAFT_SECRET_VALUE_RE.search(serialized_approval)):
        blockers.append("approval_receipt contains private locator or secret-like material and cannot be used.")

    decision = approval_payload.get("decision") if isinstance(approval_payload.get("decision"), dict) else {}
    approval_material = (
        approval_payload.get("material_selection")
        if isinstance(approval_payload.get("material_selection"), dict)
        else {}
    )
    capture_request = (
        approval_payload.get("capture_request")
        if isinstance(approval_payload.get("capture_request"), dict)
        else {}
    )
    approval_future_contract = (
        approval_payload.get("future_adapter_contract")
        if isinstance(approval_payload.get("future_adapter_contract"), dict)
        else {}
    )
    approval_closed_actions = (
        approval_payload.get("closed_actions")
        if isinstance(approval_payload.get("closed_actions"), dict)
        else {}
    )
    approval_redaction = approval_payload.get("redaction") if isinstance(approval_payload.get("redaction"), dict) else {}

    receipt_kind_valid = approval_payload.get("receipt_kind") == "imap_mailbox_material_capture_approval"
    lifecycle_valid = approval_payload.get("lifecycle_action") == "imap_mailbox_material_capture_approval_record"
    schema_valid = approval_payload.get("schema_version") == "wom-imap-mailbox-material-capture-approval/v0.1"
    archive_id_valid = approval_payload.get("archive_id") == archive_id
    if approval_payload:
        if not receipt_kind_valid:
            blockers.append("approval_receipt is not an IMAP material capture approval receipt.")
        if not lifecycle_valid:
            blockers.append("approval_receipt lifecycle action is not imap_mailbox_material_capture_approval_record.")
        if not schema_valid:
            blockers.append("approval_receipt schema_version is not supported.")
        if not archive_id_valid:
            blockers.append("approval_receipt archive_id does not match this archive.")

    receipt_decision = decision.get("decision") if isinstance(decision.get("decision"), str) else None
    if approval_payload and receipt_decision not in IMAP_MAILBOX_MATERIAL_CAPTURE_APPROVAL_DECISIONS:
        blockers.append("approval_receipt decision is not valid.")
        receipt_decision = None
    if approval_payload and receipt_decision != normalized_expected_decision:
        blockers.append("approval_receipt decision does not match expected_decision.")
    if approval_payload and receipt_decision == "needs_review":
        blockers.append("approval_receipt must record approve_once or deny, not needs_review.")

    expected_sha = material_summary.get("material_selection_receipt_sha256")
    sha_matches = bool(expected_sha and approval_material.get("sha256") == expected_sha)
    if approval_payload and not sha_matches:
        blockers.append("approval_receipt material selection sha256 does not match the selected receipt.")

    expected_indexes = material_summary.get("selected_indexes") if isinstance(material_summary.get("selected_indexes"), list) else []
    receipt_indexes = approval_material.get("selected_indexes") if isinstance(approval_material.get("selected_indexes"), list) else []
    indexes_match = list(receipt_indexes) == list(expected_indexes)
    if approval_payload and not indexes_match:
        blockers.append("approval_receipt selected_indexes do not match the selected receipt.")

    expected_selected_count = material_summary.get("selected_count")
    selected_count_matches = approval_material.get("selected_count") == expected_selected_count
    if approval_payload and not selected_count_matches:
        blockers.append("approval_receipt selected_count does not match the selected receipt.")

    candidate_pool_matches = approval_material.get("candidate_pool_count") == material_summary.get("candidate_pool_count")
    if approval_payload and not candidate_pool_matches:
        blockers.append("approval_receipt candidate_pool_count does not match the selected receipt.")

    selection_mode_matches = approval_material.get("selection_mode") == material_summary.get("selection_mode")
    if approval_payload and not selection_mode_matches:
        blockers.append("approval_receipt selection_mode does not match the selected receipt.")

    action_matches = capture_request.get("capture_action") == normalized_action
    if approval_payload and not action_matches:
        blockers.append("approval_receipt capture_action does not match the requested action.")

    if approval_payload and approval_material.get("path_included") is not False:
        blockers.append("approval_receipt must not include the material selection receipt path.")
    if approval_payload and approval_material.get("candidate_refs_included") is not False:
        blockers.append("approval_receipt must not include candidate refs.")
    if approval_payload and approval_material.get("execution_receipt_path_included") is not False:
        blockers.append("approval_receipt must not include the execution receipt path.")

    body_allowed_matches = approval_future_contract.get("read_selected_message_bodies_after_approval") is (
        allowed.get("read_selected_message_bodies") is True
    )
    attachment_allowed_matches = approval_future_contract.get("read_selected_attachments_after_approval") is (
        allowed.get("read_selected_attachments") is True
    )
    derived_text_allowed_matches = approval_future_contract.get("create_mail_derived_text_after_approval") is (
        allowed.get("create_mail_derived_text") is True
    )
    if approval_payload and not (body_allowed_matches and attachment_allowed_matches and derived_text_allowed_matches):
        blockers.append("approval_receipt future adapter action flags do not match the capture action.")

    required_false_redaction_flags = (
        "credential_values_included",
        "credential_refs_included",
        "env_var_names_included",
        "imap_host_included",
        "mailbox_ref_included",
        "material_selection_receipt_path_included",
        "execution_receipt_path_included",
        "candidate_refs_included",
        "message_uid_values_included",
        "message_id_values_included",
        "headers_included",
        "bodies_included",
        "attachment_names_included",
        "attachment_bytes_included",
        "local_absolute_paths_included",
        "secret_values_included",
    )
    failed_redaction_flags: list[str] = []
    if approval_payload:
        for flag in required_false_redaction_flags:
            if approval_redaction.get(flag) is not False:
                failed_redaction_flags.append(flag)
        if failed_redaction_flags:
            blockers.append("approval_receipt redaction flags do not prove a non-secret approval receipt.")

    required_false_closed_actions = (
        "live_adapter_executed",
        "imap_connection_opened",
        "imap_login_attempted",
        "mailbox_selected",
        "mailbox_searched",
        "message_uids_read",
        "message_ids_read",
        "message_headers_read",
        "message_bodies_read",
        "attachments_read",
        "derived_text_created",
        "credential_value_read",
        "secret_value_read",
        "password_manager_opened",
        "os_keyring_opened",
        "environment_read",
        "oauth_started",
        "provider_api_called",
    )
    failed_closed_actions: list[str] = []
    if approval_payload:
        for action in required_false_closed_actions:
            if approval_closed_actions.get(action) is not False:
                failed_closed_actions.append(action)
        if failed_closed_actions:
            blockers.append("approval_receipt closed-action flags do not prove material capture stayed closed.")

    return {
        "ok": not blockers,
        "dry_run": bool(dry_run),
        "lifecycle_action": "imap_mailbox_material_capture_approval_audit",
        "archive_id": archive_id,
        "audit_state": (
            "legacy_unbound_approval_receipt_audited"
            if not blockers
            else "blocked"
        ),
        "binding_state": "legacy_unbound",
        "authority_classification": "advisory",
        "capture_action": normalized_action,
        "expected_decision": normalized_expected_decision,
        "future_capture_authorized": False,
        "approval_receipt_summary": {
            "receipt_loaded": bool(approval_payload),
            "approval_receipt_path_echoed": False,
            "receipt_kind_valid": receipt_kind_valid,
            "lifecycle_action_valid": lifecycle_valid,
            "schema_valid": schema_valid,
            "archive_id_valid": archive_id_valid,
            "decision": receipt_decision,
            "expected_decision": normalized_expected_decision,
            "single_action_only": decision.get("single_action_only") is True,
            "replay_requires_new_approval": decision.get("replay_requires_new_approval") is True,
            "background_use_allowed": decision.get("background_use_allowed") is True,
        },
        "material_selection_summary": {
            **material_summary,
            "material_selection_receipt_path_echoed": False,
            "execution_receipt_path_echoed": False,
            "candidate_refs_echoed": False,
        },
        "validation_summary": {
            "material_selection_sha256_matches": sha_matches,
            "selected_indexes_match": indexes_match,
            "selected_count_matches": selected_count_matches,
            "candidate_pool_count_matches": candidate_pool_matches,
            "selection_mode_matches": selection_mode_matches,
            "capture_action_matches": action_matches,
            "future_adapter_action_flags_match": (
                body_allowed_matches and attachment_allowed_matches and derived_text_allowed_matches
            ),
            "redaction_ok": not failed_redaction_flags,
            "failed_redaction_flags": failed_redaction_flags,
            "closed_actions_ok": not failed_closed_actions,
            "failed_closed_actions": failed_closed_actions,
            "approval_receipt_path_echoed": False,
            "material_selection_receipt_path_echoed": False,
            "execution_receipt_path_echoed": False,
            "candidate_refs_echoed": False,
        },
        "current_capability": {
            "material_capture_approval_audit_implemented": True,
            "material_capture_approval_receipt_read_implemented": True,
            "material_capture_approval_receipt_write_implemented": True,
            "message_body_capture_implemented": False,
            "attachment_capture_implemented": False,
            "derived_text_capture_implemented": False,
            "future_live_adapter_implemented": False,
        },
        "closed_actions": {
            "material_selection_receipt_read": contract.get("closed_actions", {}).get("material_selection_receipt_read") is True
            if isinstance(contract.get("closed_actions"), dict)
            else False,
            "material_capture_approval_receipt_read": bool(approval_payload),
            "execution_receipt_read": False,
            "live_adapter_executed": False,
            "imap_connection_opened": False,
            "imap_login_attempted": False,
            "mailbox_selected": False,
            "mailbox_searched": False,
            "message_uids_read": False,
            "message_ids_read": False,
            "message_headers_read": False,
            "message_bodies_read": False,
            "attachments_read": False,
            "derived_text_created": False,
            "credential_value_read": False,
            "secret_value_read": False,
            "password_manager_opened": False,
            "os_keyring_opened": False,
            "environment_read": False,
            "oauth_started": False,
            "provider_api_called": False,
            "files_written": False,
        },
        "privacy_guards": {
            "email_addresses_echoed": False,
            "username_values_echoed": False,
            "exact_account_refs_echoed": False,
            "exact_credential_refs_echoed": False,
            "exact_mailbox_refs_echoed": False,
            "env_var_names_echoed": False,
            "imap_host_values_echoed": False,
            "provider_urls_echoed": False,
            "message_uid_values_echoed": False,
            "message_id_values_echoed": False,
            "message_headers_echoed": False,
            "message_bodies_echoed": False,
            "subject_values_echoed": False,
            "sender_values_echoed": False,
            "recipient_values_echoed": False,
            "attachment_names_echoed": False,
            "attachment_bytes_echoed": False,
            "secret_values_echoed": False,
            "approval_receipt_path_echoed": False,
            "material_selection_receipt_path_echoed": False,
            "execution_receipt_path_echoed": False,
            "candidate_refs_echoed": False,
            "candidate_refs_recorded": False,
            "local_absolute_paths_echoed": False,
        },
        "would_change": [],
        "files_written": [],
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
    }


def credential_ref_plan(
    archive_root: Path | str,
    *,
    credential_id: str,
    credential_ref: str,
    credential_kind: str | None = None,
    purpose: str | None = None,
    provider: str | None = None,
    dry_run: bool = True,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []

    if not dry_run:
        blockers.append("credential-ref-plan is dry-run only; pass --dry-run.")

    resolved_credential_id = (credential_id or "").strip()
    if not resolved_credential_id:
        blockers.append("credential_id is required.")
    elif not safe_source_intake_plan_scalar(resolved_credential_id):
        blockers.append("credential_id must be a safe non-secret label such as cred:openai-api.")
        resolved_credential_id = ""

    resolved_kind = (credential_kind or "generic_secret").strip().lower().replace("-", "_")
    if resolved_kind not in CREDENTIAL_REF_ALLOWED_KINDS:
        blockers.append("credential_kind must be one of: " + ", ".join(sorted(CREDENTIAL_REF_ALLOWED_KINDS)) + ".")
        resolved_kind = "generic_secret"

    resolved_purpose = (purpose or default_credential_ref_purpose(resolved_kind)).strip().lower().replace("-", "_")
    if resolved_purpose not in CREDENTIAL_REF_ALLOWED_PURPOSES:
        blockers.append("purpose must be one of: " + ", ".join(sorted(CREDENTIAL_REF_ALLOWED_PURPOSES)) + ".")
        resolved_purpose = default_credential_ref_purpose(resolved_kind)

    resolved_provider = (provider or default_credential_ref_provider(resolved_kind)).strip().lower().replace("-", "_")
    if resolved_provider not in CREDENTIAL_REF_ALLOWED_PROVIDERS:
        blockers.append("provider must be one of: " + ", ".join(sorted(CREDENTIAL_REF_ALLOWED_PROVIDERS)) + ".")
        resolved_provider = "generic_provider"

    resolved_ref = (credential_ref or "").strip()
    if not safe_credential_ref(resolved_ref):
        blockers.append("credential_ref must be an env/keyring/secret/wallet reference, not a raw key, token, password, email, URL, or local path.")
        resolved_ref = ""

    store = credential_ref_store(resolved_ref)
    if store == "env":
        warnings.append("Environment variables are useful for automation, but OS keyring or a local secret manager is preferred for long-lived personal credentials.")
    if resolved_provider == "openai" and resolved_kind != "openai_api_key":
        warnings.append("OpenAI model access should normally use credential_kind=openai_api_key.")
    if resolved_purpose == "ocr_api_access" and resolved_kind not in {"ocr_api_key", "provider_api_key"}:
        warnings.append("Paid OCR access should normally use credential_kind=ocr_api_key or provider_api_key.")
    if resolved_purpose == "mail_source_access" and resolved_kind not in {"mail_username", "mail_app_password", "mail_oauth_token"}:
        warnings.append("Mail source access should normally use a mail_username, mail_app_password, or mail_oauth_token credential kind.")

    return {
        "ok": not blockers,
        "dry_run": True,
        "lifecycle_action": "credential_ref_plan",
        "archive_id": archive_id,
        "credential_id": resolved_credential_id,
        "credential_kind": resolved_kind,
        "purpose": resolved_purpose,
        "provider": resolved_provider,
        "credential_ref": resolved_ref or None,
        "credential_store": store,
        "storage_contract": {
            "archive_records_store_refs_only": True,
            "secret_values_allowed_in_git": False,
            "secret_values_allowed_in_zets": False,
            "secret_values_allowed_in_receipts": False,
            "secret_values_allowed_in_logs": False,
            "allowed_ref_prefixes": list(CREDENTIAL_REF_PREFIXES),
            "local_only_locations": [
                "OS credential manager or keyring",
                "environment variable supplied outside the archive",
                "ignored local secret manager profile",
                "external password manager such as KeePassXC",
            ],
        },
        "consumer_examples": [
            "imap_mailbox_plan username_ref/app_password_ref/oauth_token_ref",
            "future OCR adapter api_key_ref",
            "future OpenAI model adapter api_key_ref",
            "future object-storage adapter token_ref",
        ],
        "current_capability": {
            "credential_ref_contract_available": True,
            "os_keyring_write_implemented": False,
            "os_keyring_read_implemented": False,
            "secret_value_storage_implemented": False,
            "secret_value_retrieval_implemented": False,
            "provider_api_call_implemented": False,
            "paid_ocr_call_implemented": False,
            "openai_api_call_implemented": False,
        },
        "future_workflow": [
            "Store or rotate the real secret outside the archive.",
            "Record only the credential ref in WOM archive metadata.",
            "A future trusted local adapter may resolve the ref after policy and human approval.",
            "The adapter must never echo the secret into chat, zets, receipts, logs, source maps, or public docs.",
            "Record only non-secret result metadata such as provider, cost class, derivation method, and source object ids.",
        ],
        "closed_actions": {
            "secret_prompted_in_chat": False,
            "secret_value_read": False,
            "secret_value_written": False,
            "os_keyring_opened": False,
            "environment_read": False,
            "provider_api_called": False,
            "oauth_started": False,
            "paid_ocr_called": False,
            "openai_api_called": False,
            "files_written": False,
        },
        "privacy_guards": {
            "secret_values_echoed": False,
            "email_addresses_echoed": False,
            "tokens_echoed": False,
            "local_absolute_paths_echoed": False,
            "provider_urls_echoed": False,
            "writes": False,
        },
        "would_change": [],
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
    }


def credential_ref_inventory(
    archive_root: Path | str,
    *,
    dry_run: bool = True,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []
    credentials: list[dict[str, Any]] = []
    sources_checked: list[dict[str, Any]] = []

    if not dry_run:
        blockers.append("credential-ref-inventory is read-only and requires --dry-run.")

    provider_path = archive_internal_path(root, "provider-bindings.yml")
    sources_checked.append({"path": "provider-bindings.yml", "present": provider_path.is_file(), "scope": "archive"})
    if provider_path.is_file():
        try:
            provider_doc = load_provider_bindings(root)
            for index, binding in enumerate(provider_bindings_list(provider_doc), start=1):
                provider = str(binding.get("provider") or "generic_provider").strip().lower().replace("-", "_")
                credentials.extend(
                    discover_credential_refs_in_value(
                        binding,
                        document="provider-bindings.yml",
                        base_id=f"provider-{index:04d}",
                        provider=provider if provider in CREDENTIAL_REF_ALLOWED_PROVIDERS else "generic_provider",
                        context={"binding_kind": str(binding.get("kind") or "provider")},
                    )
                )
        except (ArchiveServiceError, OSError, UnicodeError) as exc:
            blockers.append(f"provider-bindings.yml could not be read safely: {exc}")

    source_path = archive_internal_path(root, "source-bindings.yml")
    sources_checked.append({"path": "source-bindings.yml", "present": source_path.is_file(), "scope": "archive"})
    if source_path.is_file():
        try:
            source_doc = load_source_bindings(root)
            for index, binding in enumerate(source_bindings_list(source_doc), start=1):
                source_type = str(binding.get("source_type") or "")
                provider = "generic_imap" if source_type == IMAP_MAILBOX_SOURCE_TYPE else "generic_provider"
                credentials.extend(
                    discover_credential_refs_in_value(
                        binding,
                        document="source-bindings.yml",
                        base_id=f"source-{index:04d}",
                        provider=provider,
                        context={"source_type": source_type or "unknown"},
                    )
                )
        except (ArchiveServiceError, OSError, UnicodeError) as exc:
            blockers.append(f"source-bindings.yml could not be read safely: {exc}")

    local_path = archive_internal_path(root, CREDENTIAL_REF_LOCAL_INVENTORY_RELATIVE)
    sources_checked.append(
        {
            "path": CREDENTIAL_REF_LOCAL_INVENTORY_RELATIVE,
            "present": local_path.is_file(),
            "scope": "local_ignored",
        }
    )
    if local_path.is_file():
        try:
            local_doc = load_yaml(local_path.read_text(encoding="utf-8"))
            if not isinstance(local_doc, dict):
                blockers.append(f"{CREDENTIAL_REF_LOCAL_INVENTORY_RELATIVE} must be a YAML object.")
            else:
                credentials.extend(local_credential_inventory_entries(local_doc, blockers))
        except (OSError, UnicodeError) as exc:
            blockers.append(f"{CREDENTIAL_REF_LOCAL_INVENTORY_RELATIVE} could not be read safely: {exc}")

    deduped = dedupe_credential_inventory(credentials)
    return {
        "ok": not blockers,
        "dry_run": True,
        "lifecycle_action": "credential_ref_inventory",
        "archive_id": archive_id,
        "credential_count": len(deduped),
        "credentials": deduped,
        "sources_checked": sources_checked,
        "local_inventory_path": CREDENTIAL_REF_LOCAL_INVENTORY_RELATIVE,
        "current_capability": {
            "read_only_inventory_available": True,
            "local_inventory_file_read_supported": True,
            "secret_value_read_implemented": False,
            "secret_value_write_implemented": False,
            "os_keyring_open_implemented": False,
            "provider_api_call_implemented": False,
        },
        "closed_actions": {
            "secret_value_read": False,
            "secret_value_written": False,
            "os_keyring_opened": False,
            "environment_read": False,
            "provider_api_called": False,
            "oauth_started": False,
            "files_written": False,
        },
        "privacy_guards": {
            "credential_ref_values_echoed": False,
            "secret_values_echoed": False,
            "email_addresses_echoed": False,
            "tokens_echoed": False,
            "local_absolute_paths_echoed": False,
            "provider_urls_echoed": False,
            "writes": False,
        },
        "next_safe_actions": [
            "Use a password manager or OS keyring for the actual secret values.",
            f"Optionally maintain {CREDENTIAL_REF_LOCAL_INVENTORY_RELATIVE} as an ignored local catalog of refs.",
            "Use credential-ref-plan to validate a new ref before adding it to a binding or local inventory.",
            "Use imap:account:* for mail account labels and keyring:/env:/secret:/wallet: only for usernames, app passwords, OAuth tokens, and API keys.",
        ],
        "would_change": [],
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
    }


def connected_accounts_overview(
    archive_root: Path | str,
    *,
    include_disabled: bool = False,
    dry_run: bool = True,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []
    accounts: list[dict[str, Any]] = []
    sources_checked: list[dict[str, Any]] = []

    if not dry_run:
        blockers.append("connected-accounts is read-only and requires --dry-run.")

    provider_path = archive_internal_path(root, "provider-bindings.yml")
    sources_checked.append({"path": "provider-bindings.yml", "present": provider_path.is_file(), "scope": "archive"})
    if provider_path.is_file():
        try:
            provider_doc = load_provider_bindings(root)
            if provider_doc.get("archive_id") and provider_doc.get("archive_id") != archive_id:
                blockers.append("provider-bindings.yml archive_id must match archive.yml archive_id.")
            for index, binding in enumerate(provider_bindings_list(provider_doc), start=1):
                account = connected_account_from_provider_binding(
                    binding,
                    entry_index=index,
                    include_disabled=include_disabled,
                    blockers=blockers,
                    warnings=warnings,
                )
                if account is not None:
                    accounts.append(account)
        except (ArchiveServiceError, OSError, UnicodeError) as exc:
            blockers.append(f"provider-bindings.yml could not be read safely: {exc}")

    source_path = archive_internal_path(root, "source-bindings.yml")
    sources_checked.append({"path": "source-bindings.yml", "present": source_path.is_file(), "scope": "archive"})
    if source_path.is_file():
        try:
            source_doc = load_source_bindings(root)
            if source_doc.get("archive_id") and source_doc.get("archive_id") != archive_id:
                blockers.append("source-bindings.yml archive_id must match archive.yml archive_id.")
            for index, binding in enumerate(source_bindings_list(source_doc), start=1):
                account = connected_account_from_source_binding(
                    binding,
                    entry_index=index,
                    include_disabled=include_disabled,
                    blockers=blockers,
                    warnings=warnings,
                )
                if account is not None:
                    accounts.append(account)
        except (ArchiveServiceError, OSError, UnicodeError) as exc:
            blockers.append(f"source-bindings.yml could not be read safely: {exc}")

    inventory = credential_ref_inventory(root, dry_run=True)
    inventory_blockers = [str(item) for item in inventory.get("blockers") or []]
    inventory_warnings = [str(item) for item in inventory.get("warnings") or []]
    for item in inventory_blockers:
        warnings.append(f"credential catalog issue: {item}")
    warnings.extend(inventory_warnings)
    sources_checked.extend(
        item
        for item in inventory.get("sources_checked") or []
        if isinstance(item, dict) and item.get("path") == CREDENTIAL_REF_LOCAL_INVENTORY_RELATIVE
    )
    credential_catalog = [
        connected_account_safe_credential_summary(item)
        for item in inventory.get("credentials") or []
        if isinstance(item, dict)
    ]

    account_store_summary: dict[str, int] = {}
    for account in accounts:
        for location in account.get("credential_locations") or []:
            if not isinstance(location, dict):
                continue
            store = str(location.get("ref_store") or "unknown")
            account_store_summary[store] = account_store_summary.get(store, 0) + 1

    catalog_store_summary = connected_account_credential_store_summary(credential_catalog)

    return {
        "ok": not blockers,
        "dry_run": True,
        "lifecycle_action": "connected_accounts_overview",
        "archive_id": archive_id,
        "account_count": len(accounts),
        "accounts": accounts,
        "credential_catalog": {
            "ok": not inventory_blockers,
            "status": "metadata_only_unverified" if not inventory_blockers else "needs_review",
            "credential_count": len(credential_catalog),
            "metadata_reference_count": len(credential_catalog),
            "persisted_credential_count": 0,
            "store_presence": "not_checked",
            "credentials": credential_catalog,
            "store_summary": catalog_store_summary,
            "blockers": unique_preserve_order(inventory_blockers),
            "warnings": unique_preserve_order(inventory_warnings),
        },
        "credential_store_summary": account_store_summary,
        "sources_checked": connected_account_dedupe_sources_checked(sources_checked),
        "current_capability": {
            "connected_accounts_bridge_available": True,
            "provider_binding_metadata_read_supported": True,
            "source_binding_metadata_read_supported": True,
            "local_credential_inventory_metadata_read_supported": True,
            "live_account_verification_implemented": False,
            "secret_value_retrieval_implemented": False,
            "oauth_flow_implemented": False,
            "imap_live_scan_implemented": False,
            "provider_api_call_implemented": False,
        },
        "closed_actions": {
            "secret_value_read": False,
            "secret_value_written": False,
            "environment_read": False,
            "password_manager_opened": False,
            "os_keyring_opened": False,
            "browser_password_store_opened": False,
            "provider_api_called": False,
            "oauth_started": False,
            "imap_connection_opened": False,
            "imap_login_attempted": False,
            "message_headers_read": False,
            "message_bodies_read": False,
            "source_bytes_read": False,
            "files_written": False,
        },
        "privacy_guards": {
            "secret_values_echoed": False,
            "credential_ref_values_echoed": False,
            "email_addresses_echoed": False,
            "username_values_echoed": False,
            "tokens_echoed": False,
            "provider_urls_echoed": False,
            "local_absolute_paths_echoed": False,
            "raw_provider_auth_values_echoed": False,
            "source_bodies_read": False,
            "writes": False,
        },
        "next_safe_actions": [
            "Use connected-accounts as a map of non-secret account labels and credential store types.",
            "Use credential-ref-inventory to inspect credential catalog metadata without exact ref values.",
            "Use provider-status before relying on setup-managed GitHub or object-storage metadata.",
            "Use imap-mailbox-plan before adding or changing a mail source; live IMAP scan remains closed.",
        ],
        "would_change": [],
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
    }


def connected_account_from_provider_binding(
    binding: dict[str, Any],
    *,
    entry_index: int,
    include_disabled: bool,
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any] | None:
    enabled = binding.get("enabled") is not False
    if not enabled and not include_disabled:
        return None

    provider = str(binding.get("provider") or "generic_provider").strip().lower().replace("-", "_")
    provider_for_credentials = provider if provider in CREDENTIAL_REF_ALLOWED_PROVIDERS else "generic_provider"
    binding_id = connected_account_safe_or_hidden(
        binding.get("binding_id"),
        fallback=f"provider-binding-{entry_index:04d}",
        field_name="provider-bindings.yml.binding_id",
        blockers=blockers,
    )
    auth = binding.get("auth") if isinstance(binding.get("auth"), dict) else {}
    raw_account_ref = auth.get("account_ref")
    account_ref = None
    if raw_account_ref is not None:
        account_ref = connected_account_safe_or_hidden(
            raw_account_ref,
            fallback=f"hidden-provider-account-{entry_index:04d}",
            field_name="provider-bindings.yml.auth.account_ref",
            blockers=blockers,
        )
        if account_ref.startswith("hidden-"):
            account_ref = None

    purpose = connected_account_optional_safe_text(binding.get("purpose"), field_name="provider-bindings.yml.purpose", warnings=warnings)
    credentials = dedupe_credential_inventory(
        discover_credential_refs_in_value(
            binding,
            document="provider-bindings.yml",
            base_id=f"provider-account-{entry_index:04d}",
            provider=provider_for_credentials,
            context={
                "binding_kind": str(binding.get("kind") or "provider"),
                "binding_id": binding_id,
            },
        )
    )
    credential_locations = [connected_account_safe_credential_summary(item) for item in credentials]
    label = account_ref or binding_id

    return {
        "account_id": f"provider:{binding_id}",
        "account_kind": "provider_binding",
        "account_label": label,
        "account_ref": account_ref,
        "binding_id": binding_id,
        "provider": provider,
        "provider_kind": connected_account_optional_safe_text(binding.get("provider_kind"), field_name="provider-bindings.yml.provider_kind", warnings=warnings),
        "enabled": enabled,
        "purpose": purpose,
        "credential_locations": credential_locations,
        "credential_store_summary": connected_account_credential_store_summary(credential_locations),
        "source": {
            "document": "provider-bindings.yml",
            "scope": "archive",
            "entry_index": entry_index,
        },
        "live_status": "metadata_only",
    }


def connected_account_from_source_binding(
    binding: dict[str, Any],
    *,
    entry_index: int,
    include_disabled: bool,
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any] | None:
    enabled = binding.get("enabled") is not False
    if not enabled and not include_disabled:
        return None

    source_type = str(binding.get("source_type") or "").strip().lower()
    connection = binding.get("connection") if isinstance(binding.get("connection"), dict) else {}
    has_account_connection = source_type == IMAP_MAILBOX_SOURCE_TYPE or bool(connection.get("account_ref"))
    if not has_account_connection:
        return None

    source_id = connected_account_safe_or_hidden(
        binding.get("source_id"),
        fallback=f"source-binding-{entry_index:04d}",
        field_name="source-bindings.yml.source_id",
        blockers=blockers,
    )
    provider = str(connection.get("provider") or ("generic_imap" if source_type == IMAP_MAILBOX_SOURCE_TYPE else "generic_provider")).strip().lower().replace("-", "_")
    provider_for_credentials = provider if provider in CREDENTIAL_REF_ALLOWED_PROVIDERS else "generic_provider"
    raw_account_ref = connection.get("account_ref") or binding.get("root_ref")
    account_ref = connected_account_safe_or_hidden(
        raw_account_ref,
        fallback=f"hidden-source-account-{entry_index:04d}",
        field_name="source-bindings.yml.connection.account_ref",
        blockers=blockers,
    )
    if account_ref.startswith("hidden-"):
        account_ref = None

    credentials = dedupe_credential_inventory(
        discover_credential_refs_in_value(
            connection or binding,
            document="source-bindings.yml",
            base_id=f"source-account-{entry_index:04d}",
            provider=provider_for_credentials,
            context={
                "source_type": source_type or "unknown",
                "source_id": source_id,
            },
        )
    )
    credential_locations = [connected_account_safe_credential_summary(item) for item in credentials]

    return {
        "account_id": f"source:{source_id}",
        "account_kind": "imap_mailbox_source" if source_type == IMAP_MAILBOX_SOURCE_TYPE else "source_binding",
        "account_label": account_ref or source_id,
        "account_ref": account_ref,
        "source_id": source_id,
        "source_type": source_type or None,
        "provider": provider,
        "enabled": enabled,
        "credential_locations": credential_locations,
        "credential_store_summary": connected_account_credential_store_summary(credential_locations),
        "source": {
            "document": "source-bindings.yml",
            "scope": "archive",
            "entry_index": entry_index,
        },
        "live_status": "metadata_only",
    }


def connected_account_safe_or_hidden(
    value: Any,
    *,
    fallback: str,
    field_name: str,
    blockers: list[str],
) -> str:
    text = str(value or "").strip()
    if safe_connected_account_label(text):
        return text
    blockers.append(f"{field_name} must be a safe non-secret account label; value hidden.")
    return fallback


def connected_account_optional_safe_text(value: Any, *, field_name: str, warnings: list[str]) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    if safe_connected_account_label(text):
        return text
    warnings.append(f"{field_name} was hidden because it is not a safe non-secret label.")
    return None


def safe_connected_account_label(value: str) -> bool:
    text = value.strip()
    if not text or not text.isascii() or "\x00" in text or "\n" in text or "\r" in text:
        return False
    if "@" in text or "://" in text or "/" in text or "\\" in text or "#" in text or "?" in text:
        return False
    if contains_forbidden_location_reference(text) or DRAFT_SECRET_VALUE_RE.search(text):
        return False
    return bool(CONNECTED_ACCOUNT_SAFE_LABEL_RE.match(text))


def connected_account_safe_credential_summary(entry: dict[str, Any]) -> dict[str, Any]:
    source = entry.get("source") if isinstance(entry.get("source"), dict) else {}
    return {
        "credential_id": entry.get("credential_id"),
        "credential_id_status": entry.get("credential_id_status") or "metadata_label_only",
        "credential_id_authoritative": entry.get("credential_id_authoritative") is True,
        "credential_kind": entry.get("credential_kind"),
        "purpose": entry.get("purpose"),
        "provider": entry.get("provider"),
        "ref_store": entry.get("ref_store"),
        "ref_prefix": entry.get("ref_prefix"),
        "ref_format": entry.get("ref_format"),
        "store_presence": entry.get("store_presence") or "not_checked",
        "source": {
            "document": source.get("document"),
            "scope": source.get("scope"),
            "field_path": source.get("field_path"),
            "entry_index": source.get("entry_index"),
            "binding_id": source.get("binding_id"),
            "source_id": source.get("source_id"),
            "source_type": source.get("source_type"),
        },
        "secret_value_present_in_metadata": False,
    }


def connected_account_credential_store_summary(entries: list[dict[str, Any]]) -> dict[str, int]:
    summary: dict[str, int] = {}
    for entry in entries:
        store = str(entry.get("ref_store") or "unknown")
        summary[store] = summary.get(store, 0) + 1
    return dict(sorted(summary.items()))


def connected_account_dedupe_sources_checked(entries: list[dict[str, Any]]) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for item in entries:
        path = str(item.get("path") or "")
        scope = str(item.get("scope") or "")
        key = (path, scope)
        if not path or key in seen:
            continue
        seen.add(key)
        result.append(json_safe(item))
    return result


def credential_store_recommendation(
    archive_root: Path | str,
    *,
    scenario: str,
    platform: str = "windows",
    dry_run: bool = True,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []

    if not dry_run:
        blockers.append("credential-store-recommendation is read-only and requires --dry-run.")

    resolved_scenario = (scenario or "").strip().lower().replace("-", "_")
    if resolved_scenario not in CREDENTIAL_STORE_RECOMMENDATION_SCENARIOS:
        blockers.append(
            "scenario must be one of: "
            + ", ".join(sorted(CREDENTIAL_STORE_RECOMMENDATION_SCENARIOS))
            + "."
        )
        resolved_scenario = "personal_local_first"

    resolved_platform = (platform or "windows").strip().lower().replace("-", "_")
    if resolved_platform not in CREDENTIAL_STORE_RECOMMENDATION_PLATFORMS:
        blockers.append(
            "platform must be one of: "
            + ", ".join(sorted(CREDENTIAL_STORE_RECOMMENDATION_PLATFORMS))
            + "."
        )
        resolved_platform = "cross_platform"

    platform_keyring = {
        "windows": "Windows Credential Manager",
        "macos": "macOS Keychain",
        "linux": "Linux Secret Service compatible keyring",
        "cross_platform": "OS credential manager/keyring",
    }[resolved_platform]

    profiles = credential_store_scenario_profiles(platform_keyring)
    selected = profiles[resolved_scenario]

    if resolved_scenario == "automation_or_dev_secrets":
        warnings.append("Environment variables are suitable for short-lived automation shells, not long-lived personal password storage.")
    if resolved_scenario == "local_app_adapter":
        warnings.append("OS keyring adapters should stay behind explicit policy checks and human approval before any future read.")
    if resolved_scenario in {"account_recovery_codes", "break_glass_secrets"}:
        warnings.append("Recovery codes are break-glass material; do not keep the only copy in one digital vault or device.")

    return {
        "ok": not blockers,
        "dry_run": True,
        "lifecycle_action": "credential_store_recommendation",
        "archive_id": archive_id,
        "scenario": resolved_scenario,
        "platform": resolved_platform,
        "human_need": selected["human_need"],
        "recommendation_summary": selected["summary"],
        "primary_recommendation": selected["primary"],
        "secondary_recommendations": selected["secondary"],
        "scenario_guidance": selected.get("scenario_guidance", {}),
        "wom_compatibility": {
            "wom_stores_secret_values": False,
            "wom_stores_refs_and_catalog_only": True,
            "credential_ref_prefixes": [
                {
                    "prefix": "secret:",
                    "meaning": "External password manager or secret manager entry label.",
                    "best_for": "KeePassXC, Bitwarden, 1Password, Bitwarden Secrets Manager, and similar external vaults.",
                },
                {
                    "prefix": "keyring:",
                    "meaning": "Operating-system credential manager entry label.",
                    "best_for": platform_keyring + " and future local app adapters.",
                },
                {
                    "prefix": "env:",
                    "meaning": "Environment variable supplied outside the archive.",
                    "best_for": "Short-lived automation shells and CI-style runtime injection.",
                },
                {
                    "prefix": "wallet:",
                    "meaning": "Future WOM wallet/local custody reference.",
                    "best_for": "Not implemented; reserved for future local custody design.",
                },
            ],
            "inventory_command": "archive credential-ref-inventory --dry-run",
            "validation_command": "archive credential-ref-plan --dry-run",
            "local_inventory_path": CREDENTIAL_REF_LOCAL_INVENTORY_RELATIVE,
        },
        "selection_logic": [
            "If local-first control matters more than sync, prefer KeePassXC-style offline vaults.",
            "If multi-device sync and sharing matter most, prefer Bitwarden or 1Password-style managed vaults.",
            "If the secret already lives in a browser/platform manager, treat it as a login/autofill source, not a general API-key vault.",
            "If a local WOM adapter must retrieve a secret without chat copy/paste, prefer the OS keyring surface.",
            "If automation needs injection, prefer a secrets manager or short-lived environment variable over committed files.",
            "If the value is account recovery or break-glass material, require independent offline redundancy and check for circular vault/account dependency.",
            "If the value is a mail/app/API secret, WOM should store only a credential ref and purpose metadata.",
        ],
        "non_goals": [
            "Do not build a plaintext WOM password vault.",
            "Do not put real usernames, passwords, app passwords, OAuth tokens, or API keys in zets.",
            "Do not put secrets in Git, receipts, logs, source maps, screenshots, prompts, or public docs.",
            "Do not ask the user to paste secrets into chat.",
            "Do not read a keyring, password manager, or environment variable in this release.",
        ],
        "next_safe_actions": selected["next_safe_actions"],
        "current_capability": {
            "scenario_recommendation_available": True,
            "credential_ref_contract_available": True,
            "credential_ref_inventory_available": True,
            "password_manager_adapter_implemented": False,
            "os_keyring_adapter_implemented": False,
            "secret_value_storage_implemented": False,
            "secret_value_retrieval_implemented": False,
        },
        "closed_actions": {
            "secret_prompted_in_chat": False,
            "secret_value_read": False,
            "secret_value_written": False,
            "os_keyring_opened": False,
            "password_manager_opened": False,
            "environment_read": False,
            "provider_api_called": False,
            "oauth_started": False,
            "files_written": False,
        },
        "privacy_guards": {
            "secret_values_echoed": False,
            "credential_ref_values_echoed": False,
            "email_addresses_echoed": False,
            "tokens_echoed": False,
            "local_absolute_paths_echoed": False,
            "provider_urls_echoed": False,
            "writes": False,
        },
        "would_change": [],
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
    }


