def backup_evidence_receipt_validation_codes(
    root: Path,
    *,
    archive_id: str,
    object_id: str,
    location: dict[str, Any],
    receipt_cache: dict[str, tuple[dict[str, Any] | None, str | None]],
) -> tuple[list[str], bool]:
    codes: list[str] = []
    digest = object_id.removeprefix("sha256:").lower()
    provider_kind = str(location.get("provider_kind") or "")
    store_ref = str(location.get("store_ref") or "")
    if object_storage_wom_uploaded_audit_location_errors(
        location,
        digest=digest,
        provider_kind=provider_kind,
        store_ref=store_ref,
    ):
        codes.append("location_contract_invalid")
    if not object_storage_location_digest_matches_record(location, object_id):
        codes.append("location_digest_mismatch")

    receipt_ref = location.get("execution_receipt_ref")
    if not isinstance(receipt_ref, str) or not safe_object_storage_execution_receipt_relative(receipt_ref):
        codes.append("execution_receipt_ref_invalid")
        return unique_preserve_order(codes), False

    receipt_read = False
    if receipt_ref not in receipt_cache:
        receipt_path = archive_internal_path(root, receipt_ref)
        receipt: dict[str, Any] | None = None
        load_error: str | None = None
        try:
            if (
                receipt_path.is_symlink()
                or zet_revision_path_has_symlink_component(root, receipt_path)
                or not receipt_path.is_file()
            ):
                load_error = "execution_receipt_missing_or_unsafe"
            elif receipt_path.stat().st_size > BACKUP_EVIDENCE_MAX_RECEIPT_BYTES:
                load_error = "execution_receipt_too_large"
            else:
                receipt = read_json_object(receipt_path, "object-storage execution receipt")
        except ArchiveServiceError:
            load_error = "execution_receipt_invalid_json"
        except (OSError, UnicodeError):
            if load_error is None:
                load_error = "execution_receipt_unreadable"
        if receipt is None and load_error is None:
            load_error = "execution_receipt_invalid_json"
        receipt_cache[receipt_ref] = (receipt, load_error)
        receipt_read = receipt is not None

    receipt, load_error = receipt_cache[receipt_ref]
    if load_error:
        codes.append(load_error)
        return unique_preserve_order(codes), receipt_read
    assert receipt is not None

    if receipt.get("schema") != OBJECT_STORAGE_UPLOAD_RECEIPT_SCHEMA:
        codes.append("execution_receipt_schema_invalid")
    if receipt.get("lifecycle_action") != "object_storage_upload_execute":
        codes.append("execution_receipt_action_invalid")
    if receipt.get("operation") != "upload_object" or receipt.get("dry_run") is not False:
        codes.append("execution_receipt_operation_invalid")
    if receipt.get("archive_id") != archive_id or receipt.get("object_id") != object_id:
        codes.append("execution_receipt_identity_mismatch")
    if receipt.get("provider_kind") != provider_kind or receipt.get("store_ref") != store_ref:
        codes.append("execution_receipt_store_mismatch")
    if receipt.get("receipt_path") != receipt_ref:
        codes.append("execution_receipt_path_mismatch")
    if receipt.get("result_status") not in {"uploaded", "skipped_remote_same"}:
        codes.append("execution_receipt_result_not_verified")
    if receipt.get("checksum_algorithm") != OBJECT_STORAGE_CHECKSUM_ALGORITHM:
        codes.append("execution_receipt_checksum_invalid")
    receipt_strategy = receipt.get("key_strategy")
    if receipt_strategy not in OBJECT_STORAGE_UPLOAD_KEY_STRATEGIES:
        codes.append("execution_receipt_key_strategy_invalid")
    receipt_remote_key = (
        receipt.get("remote_key")
        if receipt.get("remote_key") is not None
        else receipt.get("key_hint")
    )
    if (
        not isinstance(receipt_remote_key, str)
        or not safe_object_storage_remote_key(receipt_remote_key)
        or digest not in receipt_remote_key
    ):
        codes.append("execution_receipt_remote_key_invalid")
    if receipt_strategy == OBJECT_STORAGE_UPLOAD_KEY_STRATEGY and receipt_remote_key != receipt.get("key_hint"):
        codes.append("execution_receipt_default_key_mismatch")
    bytes_uploaded = receipt.get("bytes_uploaded")
    if isinstance(bytes_uploaded, bool) or not isinstance(bytes_uploaded, int) or bytes_uploaded < 0:
        codes.append("execution_receipt_bytes_invalid")
    if receipt.get("object_count") != 1:
        codes.append("execution_receipt_object_count_invalid")
    retry_summary = receipt.get("retry_summary")
    if not isinstance(retry_summary, dict) or any(
        not isinstance(value, (int, float, str, bool)) and value is not None
        for value in retry_summary.values()
    ):
        codes.append("execution_receipt_retry_summary_invalid")
    if receipt.get("manifest_update_applied") is not True:
        codes.append("execution_receipt_manifest_transition_missing")
    reviewer = receipt.get("reviewed_by")
    if not isinstance(reviewer, str) or safe_foreign_quarantine_actor_id(reviewer) is None:
        codes.append("execution_receipt_reviewer_invalid")
    if receipt.get("key_hint") != location.get("key_hint"):
        codes.append("execution_receipt_key_hint_mismatch")
    location_remote_key = (
        location.get("remote_key")
        if location.get("remote_key") is not None
        else location.get("key_hint")
    )
    if receipt_remote_key != location_remote_key:
        codes.append("execution_receipt_remote_key_mismatch")
    privacy_guards = receipt.get("privacy_guards") if isinstance(receipt.get("privacy_guards"), dict) else {}
    for key in (
        "secret_values_echoed",
        "exact_credential_refs_echoed",
        "bucket_names_echoed",
        "provider_urls_echoed",
        "local_absolute_paths_echoed",
        "generated_urls_echoed",
    ):
        if privacy_guards.get(key) is not False:
            codes.append("execution_receipt_privacy_guard_invalid")
            break
    return unique_preserve_order(codes), receipt_read


def backup_evidence_status(
    archive_root: Path | str,
    *,
    max_records: int = BACKUP_EVIDENCE_DEFAULT_MAX_RECORDS,
    dry_run: bool = True,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []
    if not dry_run:
        blockers.append("backup-evidence is read-only and requires --dry-run.")
    try:
        record_limit = int(max_records)
    except (TypeError, ValueError):
        record_limit = BACKUP_EVIDENCE_DEFAULT_MAX_RECORDS
        blockers.append("max_records must be an integer.")
    if record_limit < 1:
        blockers.append("max_records must be at least 1.")
        record_limit = 1
    if record_limit > BACKUP_EVIDENCE_MAX_RECORDS:
        warnings.append(f"max_records was capped at {BACKUP_EVIDENCE_MAX_RECORDS}.")
        record_limit = BACKUP_EVIDENCE_MAX_RECORDS

    manifest_relative = "objects/manifests/files.jsonl"
    manifest_path = archive_internal_path(root, manifest_relative)
    manifest_present = manifest_path.is_file()
    manifest_body_read = False
    records_scanned = 0
    malformed_record_count = 0
    non_object_record_count = 0
    invalid_object_id_count = 0
    object_digest_field_mismatch_count = 0
    truncated = False
    grouped_records: dict[str, list[dict[str, Any]]] = {}

    if manifest_present:
        if manifest_path.is_symlink() or zet_revision_path_has_symlink_component(root, manifest_path):
            blockers.append("object manifest path is symbolic-link-backed and cannot be trusted for backup evidence.")
        else:
            manifest_body_read = True
            try:
                with manifest_path.open("r", encoding="utf-8-sig") as handle:
                    for raw_line in handle:
                        line = raw_line.strip()
                        if not line:
                            continue
                        if records_scanned >= record_limit:
                            truncated = True
                            break
                        records_scanned += 1
                        try:
                            record = json.loads(line)
                        except json.JSONDecodeError:
                            malformed_record_count += 1
                            continue
                        if not isinstance(record, dict):
                            non_object_record_count += 1
                            continue
                        object_id = str(record.get("object_id") or "").lower()
                        if not re.fullmatch(r"sha256:[0-9a-f]{64}", object_id):
                            invalid_object_id_count += 1
                            continue
                        if str(record.get("sha256") or "").lower() != object_id.removeprefix("sha256:"):
                            object_digest_field_mismatch_count += 1
                            continue
                        grouped_records.setdefault(object_id, []).append(record)
            except (OSError, UnicodeError):
                blockers.append("object manifest could not be read as a regular UTF-8 JSONL file.")
    if truncated:
        warnings.append("Object manifest scan reached max_records; no complete coverage claim is allowed.")

    duplicate_object_id_count = sum(1 for records in grouped_records.values() if len(records) > 1)
    duplicate_record_count = sum(max(0, len(records) - 1) for records in grouped_records.values())
    eligible_records = [records[0] for records in grouped_records.values() if len(records) == 1]
    eligible_object_count = len(eligible_records)

    local_location_object_count = 0
    declared_location_count = 0
    wom_uploaded_location_count = 0
    valid_wom_uploaded_location_count = 0
    receipt_verified_object_count = 0
    declared_only_object_count = 0
    invalid_wom_evidence_object_count = 0
    no_external_evidence_object_count = 0
    invalid_locations_field_count = 0
    non_object_location_count = 0
    receipt_cache: dict[str, tuple[dict[str, Any] | None, str | None]] = {}
    invalid_evidence_counts: dict[str, int] = {}

    for record in eligible_records:
        object_id = str(record.get("object_id") or "").lower()
        if not isinstance(record.get("locations"), list):
            invalid_locations_field_count += 1
            locations = []
        else:
            locations = record["locations"]
        has_local = False
        has_declared = False
        has_wom_claim = False
        has_valid_wom_evidence = False
        has_invalid_wom_evidence = False
        for location in locations:
            if not isinstance(location, dict):
                non_object_location_count += 1
                continue
            if location.get("provider") == "local" and location.get("availability") == "available":
                has_local = True
            if location.get("provider") == "object_storage" and location.get("availability") == "declared_uploaded":
                has_declared = True
                declared_location_count += 1
            if location.get("provider") != "object_storage" or location.get("availability") != "wom_uploaded":
                continue
            has_wom_claim = True
            wom_uploaded_location_count += 1
            validation_codes, _receipt_read = backup_evidence_receipt_validation_codes(
                root,
                archive_id=archive_id,
                object_id=object_id,
                location=location,
                receipt_cache=receipt_cache,
            )
            if validation_codes:
                has_invalid_wom_evidence = True
                for code in validation_codes:
                    invalid_evidence_counts[code] = invalid_evidence_counts.get(code, 0) + 1
            else:
                has_valid_wom_evidence = True
                valid_wom_uploaded_location_count += 1

        if has_local:
            local_location_object_count += 1
        if has_valid_wom_evidence:
            receipt_verified_object_count += 1
        if has_invalid_wom_evidence:
            invalid_wom_evidence_object_count += 1
        if has_declared and not has_valid_wom_evidence:
            declared_only_object_count += 1
        if not has_declared and not has_wom_claim:
            no_external_evidence_object_count += 1

    receipt_files_read_count = sum(1 for receipt, _error in receipt_cache.values() if receipt is not None)
    receipt_load_error_count = sum(1 for _receipt, error in receipt_cache.values() if error is not None)
    structural_problem_count = (
        malformed_record_count
        + non_object_record_count
        + invalid_object_id_count
        + object_digest_field_mismatch_count
        + invalid_locations_field_count
        + non_object_location_count
        + duplicate_record_count
        + sum(invalid_evidence_counts.values())
    )
    scan_complete = bool(not blockers and not truncated)
    evidence_integrity_clear = bool(scan_complete and manifest_present and structural_problem_count == 0)
    full_recorded_time_coverage = bool(
        evidence_integrity_clear
        and eligible_object_count > 0
        and receipt_verified_object_count == eligible_object_count
    )

    if blockers:
        object_storage_status = "blocked"
    elif truncated:
        object_storage_status = "incomplete_truncated"
    elif not manifest_present:
        object_storage_status = "object_manifest_missing"
    elif structural_problem_count:
        object_storage_status = "invalid_or_conflicting_evidence"
    elif eligible_object_count == 0:
        object_storage_status = "not_applicable_no_manifest_objects"
    elif full_recorded_time_coverage:
        object_storage_status = "receipt_verified_full_coverage_at_recorded_time"
    elif receipt_verified_object_count:
        object_storage_status = "receipt_verified_partial_coverage_at_recorded_time"
    elif declared_only_object_count:
        object_storage_status = "declared_only_no_wom_byte_proof"
    else:
        object_storage_status = "no_remote_byte_evidence"

    object_storage_lane = {
        "role": "objet_original_byte_backup",
        "status": object_storage_status,
        "manifest_present": manifest_present,
        "records_scanned": records_scanned,
        "scan_limit": record_limit,
        "scan_complete": scan_complete,
        "truncated": truncated,
        "eligible_object_count": eligible_object_count,
        "local_location_object_count": local_location_object_count,
        "receipt_verified_object_count": receipt_verified_object_count,
        "declared_only_object_count": declared_only_object_count,
        "invalid_wom_evidence_object_count": invalid_wom_evidence_object_count,
        "no_external_evidence_object_count": no_external_evidence_object_count,
        "declared_location_count": declared_location_count,
        "wom_uploaded_location_count": wom_uploaded_location_count,
        "valid_wom_uploaded_location_count": valid_wom_uploaded_location_count,
        "execution_receipt_files_read_count": receipt_files_read_count,
        "execution_receipt_load_error_count": receipt_load_error_count,
        "malformed_record_count": malformed_record_count,
        "non_object_record_count": non_object_record_count,
        "invalid_object_id_count": invalid_object_id_count,
        "object_digest_field_mismatch_count": object_digest_field_mismatch_count,
        "invalid_locations_field_count": invalid_locations_field_count,
        "non_object_location_count": non_object_location_count,
        "duplicate_object_id_count": duplicate_object_id_count,
        "duplicate_record_count": duplicate_record_count,
        "invalid_evidence_counts": dict(sorted(invalid_evidence_counts.items())),
        "evidence_integrity_clear": evidence_integrity_clear,
        "recorded_time_coverage_report_ready": evidence_integrity_clear,
        "all_manifest_objects_receipt_verified_at_recorded_time": full_recorded_time_coverage,
        "current_remote_availability_checked": False,
        "current_remote_availability_claim_ready": False,
        "evidence_scope": "local provider-confirmed execution receipts and linked wom_uploaded manifest locations at their recorded time",
    }

    github_lane = {
        "role": "metadata_and_version_history_backup",
        "status": "unverified_no_generic_completion_receipt",
        "local_commit_inspected": False,
        "remote_ref_checked": False,
        "provider_api_called": False,
        "completion_claim_ready": False,
        "reason": "a local commit or cached remote-tracking ref is not proof that GitHub currently contains it",
    }
    external_database_lane = {
        "role": "map_backup_or_replica",
        "status": "unverified_no_generic_completion_receipt",
        "configuration_inspected": False,
        "snapshot_or_replication_receipt_verified": False,
        "provider_api_called": False,
        "completion_claim_ready": False,
        "reason": "configured database labels and regenerable local indexes are not provider-specific snapshot or replication evidence",
    }
    next_safe_actions = [
        "Do not claim complete backup: GitHub remote-ref and external-database completion evidence are not verified by this command.",
    ]
    if object_storage_status in {"no_remote_byte_evidence", "declared_only_no_wom_byte_proof"}:
        next_safe_actions.append(
            "Use the existing object-storage upload or verified-adopt workflow; declared_uploaded alone never proves remote bytes."
        )
    elif object_storage_status == "receipt_verified_partial_coverage_at_recorded_time":
        next_safe_actions.append(
            "Review the uncovered manifest-object count and continue the existing object-storage upload or verified-adopt workflow."
        )
    elif object_storage_status in {"invalid_or_conflicting_evidence", "object_manifest_missing", "blocked"}:
        next_safe_actions.append(
            "Run full Doctor and repair receipt/manifest disagreement through the owning object-storage workflow; never hand-edit evidence."
        )
    elif object_storage_status == "incomplete_truncated":
        next_safe_actions.append("Rerun with a sufficient --max-records value before making any coverage claim.")
    elif full_recorded_time_coverage:
        next_safe_actions.append(
            "Recorded-time object coverage is complete, but use a live provider-specific check before claiming current remote availability."
        )
    next_safe_actions.append(
        "Keep local reviewed WOM state authoritative even when an external backup or replica is later verified."
    )

    return {
        "ok": not blockers,
        "schema": BACKUP_EVIDENCE_STATUS_SCHEMA,
        "dry_run": True,
        "lifecycle_action": "backup_evidence_status",
        "archive_id": archive_id,
        "authority": {
            "canonical": "local_reviewed_wom_state",
            "external_layers_never_silently_outrank_local": True,
        },
        "lanes": {
            "github": github_lane,
            "object_storage": object_storage_lane,
            "external_database": external_database_lane,
        },
        "overall": {
            "status": "backup_completion_unverified",
            "all_intended_backup_lanes_verified": False,
            "backup_completion_claim_ready": False,
            "configured_services_count_as_completed_evidence": False,
            "local_commit_counts_as_github_backup_proof": False,
            "declared_uploaded_counts_as_remote_byte_proof": False,
            "generated_index_counts_as_external_database_backup_proof": False,
        },
        "next_safe_actions": next_safe_actions,
        "closed_actions": {
            "manifest_metadata_body_read": manifest_body_read,
            "execution_receipt_metadata_read": bool(receipt_cache),
            "objet_bytes_read": False,
            "zet_bodies_read": False,
            "git_repository_inspected": False,
            "provider_api_called": False,
            "network_checked": False,
            "database_called": False,
            "secrets_read": False,
            "files_written": False,
        },
        "privacy_guards": {
            "object_ids_echoed": False,
            "receipt_paths_echoed": False,
            "provider_or_store_labels_echoed": False,
            "local_absolute_paths_echoed": False,
            "source_body_text_echoed": False,
        },
        "would_change": [],
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
    }


def local_sovereignty_contract(archive_root: Path | str, *, dry_run: bool = True) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    blockers = [] if dry_run else ["local-sovereignty is read-only and requires --dry-run."]
    return {
        "ok": not blockers,
        "dry_run": True,
        "lifecycle_action": "local_sovereignty_contract",
        "archive_id": read_archive_id(root),
        "authority": local_sovereignty_authority_model(),
        "blockers": blockers,
        "warnings": [],
        "would_change": [],
        "privacy_guards": {
            "archive_body_text_read": False,
            "objet_bytes_read": False,
            "provider_api_called": False,
            "network_checked": False,
            "secrets_read": False,
            "local_absolute_paths_echoed": False,
            "files_written": False,
        },
    }


def recovery_plan(archive_root: Path | str) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    sources = list_sources(root)
    providers = provider_bindings_summary(root)
    latest_receipt = latest_successful_restore_drill_receipt(root)
    return {
        "ok": True,
        "action": "archive_recovery_plan",
        "archive_root": str(root),
        "archive_id": archive_id,
        "local_only": True,
        "external_api_called": False,
        "secret_values_required": False,
        "control_plane_units": [
            "archive.yml",
            "archive-identity.yml",
            "provider-bindings.yml",
            "source-bindings.yml",
            "zettels/",
            "inbox/",
            "views/",
            "source-maps/",
            "objects/manifests/files.jsonl",
            "receipts/",
            "zettel-kasten/",
            "AGENTS.md",
        ],
        "excluded_from_restore_copy": RESTORE_DRILL_EXCLUDED_PATHS,
        "does_not_copy": [
            "external PC/SSD/SaaS/object-storage originals",
            "local-only profiles and keyrings",
            "generated SQLite search indexes",
            "provider secrets",
            "git history",
        ],
        "source_summary": {
            "source_count": sources["source_count"],
            "mapped_sources": [
                source["source_id"]
                for source in sources["sources"]
                if source.get("source_map_present")
            ],
            "unmapped_sources": [
                source["source_id"]
                for source in sources["sources"]
                if not source.get("source_map_present")
            ],
        },
        "provider_summary": {
            "binding_count": providers["binding_count"],
            "manual_required": True,
            "providers": [
                provider["provider"]
                for provider in providers["providers"]
                if provider.get("enabled") is not False
            ],
        },
        "latest_successful_restore_drill": latest_receipt,
        "storage_authority": local_sovereignty_authority_model(),
        "next_steps": [
            "Run restore-drill --dry-run against an empty target folder.",
            "Run restore-drill --approve --reviewed-by <actor> before first real source scan.",
            "Keep external originals in their current systems; restore drill verifies the archive control plane.",
        ],
    }


def upgrade_check(
    archive_root: Path | str,
    *,
    diagnostics: list[dict[str, Any]] | None = None,
    require_restore_drill: bool = False,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    recovery = recovery_plan(root)
    preflight = preflight_check(
        root,
        diagnostics=diagnostics,
        require_restore_drill=require_restore_drill,
    )
    latest_restore = preflight["restore_drill"]["latest_successful"]
    findings = list(preflight["findings"])
    warnings = list(preflight["warnings"])
    blockers = list(preflight["blockers"])

    upgrade_restore_required_message = "A successful restore-drill receipt is required before a real upgrade readiness review."
    for finding in findings:
        if finding.get("code") == "restore_drill_required":
            original = str(finding.get("message") or "")
            finding["message"] = upgrade_restore_required_message
            blockers = [upgrade_restore_required_message if item == original else item for item in blockers]

    if latest_restore is None and not require_restore_drill:
        message = "No successful restore-drill receipt found; run one on a sandbox copy before a real upgrade."
        findings.append(
            {
                "severity": "WARN",
                "code": "restore_drill_recommended",
                "message": message,
                "path": RESTORE_DRILL_RECEIPTS_DIR,
            }
        )
        warnings.append(message)

    upgrade_policy = {
        "read_only": True,
        "migration_engine": "not_implemented",
        "release_note_review_required": True,
        "sandbox_copy_required_before_real_upgrade": True,
        "real_archive_rewrite": False,
        "provider_calls": False,
        "object_store_operations": False,
        "recommended_windows_sandbox": r"C:\Users\<user>\zettel-kasten-upgrade-sandbox",
    }
    next_safe_actions = [
        "Read the target release note in wom-kit/docs/releases/.",
        "Run archive doctor --strict on the archive or sandbox copy.",
        "Use archive restore-drill --dry-run against a disposable sandbox target before any real upgrade.",
        "Run migration commands in dry-run mode first when available.",
        "Commit private archive changes only after reviewing generated outputs and receipts.",
    ]
    if latest_restore is None:
        next_safe_actions.insert(2, "Create or verify a sandbox copy before approving any restore-drill receipt.")

    readiness_status = "ready"
    if blockers:
        readiness_status = "blocked"
    elif warnings:
        readiness_status = "warnings"
    restore_drill_recency = {
        "has_successful_receipt": latest_restore is not None,
        "has_recent_drill": latest_restore is not None,
        "receipt_path": latest_restore.get("receipt_path") if latest_restore else None,
        "reviewed_at": latest_restore.get("reviewed_at") if latest_restore else None,
        "target_root": latest_restore.get("target_root") if latest_restore else None,
        "status": latest_restore.get("status") if latest_restore else None,
        "latest_receipt_note": (
            f"latest successful restore drill receipt: {latest_restore.get('receipt_path')}"
            if latest_restore
            else "no successful restore-drill receipt found"
        ),
    }
    migration_honesty = {
        "migration_engine_available": False,
        "migration_commands_run": False,
        "provider_calls": False,
        "object_store_operations": False,
        "guarantees_safe_upgrade": False,
        "summary": "upgrade-check reports readiness signals only; it does not perform or guarantee migration safety.",
    }
    return {
        "ok": True,
        "dry_run": True,
        "action": "archive_upgrade_check",
        "archive_root": str(root),
        "archive_id": archive_id,
        "doctor": preflight["doctor"],
        "restore_drill": {
            "required": require_restore_drill,
            "latest_successful": latest_restore,
            "recency": restore_drill_recency,
        },
        "recovery_plan": {
            "action": recovery["action"],
            "local_only": recovery["local_only"],
            "external_api_called": recovery["external_api_called"],
            "secret_values_required": recovery["secret_values_required"],
            "control_plane_units": recovery["control_plane_units"],
            "excluded_from_restore_copy": recovery["excluded_from_restore_copy"],
            "does_not_copy": recovery["does_not_copy"],
            "source_summary": recovery["source_summary"],
            "provider_summary": recovery["provider_summary"],
            "storage_authority": recovery["storage_authority"],
        },
        "upgrade_policy": upgrade_policy,
        "migration_honesty": migration_honesty,
        "upgrade_readiness": {
            "status": readiness_status,
            "ready_for_manual_upgrade_review": readiness_status == "ready",
            "blockers": unique_preserve_order(blockers),
            "warnings": unique_preserve_order(warnings),
        },
        "findings": findings,
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
        "next_safe_actions": unique_preserve_order(next_safe_actions),
        "would_change": [],
    }


def resolve_project_intake_staged_folder(
    root: Path,
    staged_folder: Path | str,
) -> tuple[Path, str, str | None]:
    """Resolve relative intake paths from archive authority, never process CWD."""

    candidate = Path(staged_folder).expanduser()
    if candidate.is_absolute():
        staged = candidate.resolve()
        relative = (
            staged.relative_to(root).as_posix()
            if is_path_within_root(staged, root)
            else None
        )
        return staged, "absolute_compatibility", relative
    try:
        relative = normalize_archive_relative_path(os.fspath(staged_folder))
        return archive_internal_path(root, relative), "archive_root_relative", relative
    except (ArchivePathError, ArchiveServiceError, OSError, ValueError) as exc:
        raise ArchiveServiceError(
            "Staged folder path is not a safe archive-relative path."
        ) from exc


def project_intake_plan(archive_root: Path | str, staged_folder: Path | str) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    staged, staged_folder_basis, staged_folder_relative = (
        resolve_project_intake_staged_folder(root, staged_folder)
    )
    if not staged.exists():
        raise ArchiveServiceError(f"Staged folder does not exist: {staged}")
    if not staged.is_dir():
        raise ArchiveServiceError(f"Staged folder is not a directory: {staged}")

    folder_summary = summarize_project_intake_folder(staged)
    staging_convention = project_intake_staging_convention(root, staged)
    warnings: list[str] = []
    if not staging_convention["follows_staging_convention"]:
        warnings.append(
            "Staged folder is outside the recommended intake staging shapes: "
            "<archive-root>/staging/incoming/<YYYY-MM-DD>/<project_slug> (in-archive capture staging) or "
            r"C:\Users\<user>\zettel-kasten-<profile_slug>-objets\intake\<project_slug> (bulk external originals)."
        )

    return {
        "ok": True,
        "dry_run": True,
        "action": "archive_project_intake_plan",
        "archive_root": str(root),
        "archive_id": archive_id,
        "staged_folder": str(staged),
        "staged_folder_basis": staged_folder_basis,
        "staged_folder_relative": staged_folder_relative,
        "follows_staging_convention": staging_convention["follows_staging_convention"],
        "staging_convention": staging_convention,
        "folder_summary": folder_summary,
        "privacy_guards": {
            "top_level_only": True,
            "recursive_scan": False,
            "entry_names_included": False,
            "file_bodies_read": False,
            "content_hashes_calculated": False,
            "extension_histogram_included": False,
            "suggested_labels_only": True,
            "human_answers_required": True,
            "provider_calls": False,
            "writes": False,
        },
        "session_plan": project_intake_session_plan(),
        "classification_labels": project_intake_classification_labels(),
        "human_review_checklist": project_intake_human_review_checklist(folder_summary, staging_convention),
        "decision_record_template": project_intake_decision_record_template(),
        "next_session_questions": project_intake_next_session_questions(folder_summary, staging_convention),
        "next_safe_actions": project_intake_next_safe_actions(staging_convention),
        "blockers": [],
        "warnings": warnings,
        "would_change": [],
    }


def summarize_project_intake_folder(staged_folder: Path) -> dict[str, Any]:
    files = 0
    dirs = 0
    other = 0
    for child in staged_folder.iterdir():
        if child.is_symlink():
            other += 1
        elif child.is_file():
            files += 1
        elif child.is_dir():
            dirs += 1
        else:
            other += 1

    return {
        "exists": True,
        "is_dir": True,
        "top_level_file_count": files,
        "top_level_dir_count": dirs,
        "top_level_other_count": other,
        "top_level_entry_count": files + dirs + other,
        "recursive_scan": False,
        "entry_names_included": False,
        "file_bodies_read": False,
        "content_hashes_calculated": False,
        "extension_histogram_included": False,
    }


def project_intake_unpack_queue(
    archive_root: Path | str,
    staged_folder: Path | str,
    *,
    receipt: str | None = None,
    max_items: int = 25,
    dry_run: bool = True,
) -> dict[str, Any]:
    if not dry_run:
        raise ArchiveServiceError("project-intake-unpack-queue is dry-run only.")
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    staged, staged_folder_basis, staged_folder_relative = (
        resolve_project_intake_staged_folder(root, staged_folder)
    )
    if not staged.exists():
        raise ArchiveServiceError(f"Staged folder does not exist: {staged}")
    if not staged.is_dir():
        raise ArchiveServiceError(f"Staged folder is not a directory: {staged}")
    try:
        item_limit = max(1, min(int(max_items), 100))
    except (TypeError, ValueError):
        raise ArchiveServiceError("max_items must be an integer.")

    folder_summary = summarize_project_intake_folder(staged)
    staging_convention = project_intake_staging_convention(root, staged)
    warnings: list[str] = []
    blockers: list[str] = []
    if not staging_convention["follows_staging_convention"]:
        warnings.append(
            "Staged folder is outside the recommended intake staging shapes: "
            "<archive-root>/staging/incoming/<YYYY-MM-DD>/<project_slug> (in-archive capture staging) or "
            r"C:\Users\<user>\zettel-kasten-<profile_slug>-objets\intake\<project_slug> (bulk external originals)."
        )

    receipt_status: dict[str, Any] | None = None
    if receipt:
        receipt_status = project_intake_status(root, receipt, dry_run=True)
        blockers.extend(str(item) for item in receipt_status.get("blockers", []))
        warnings.extend(str(item) for item in receipt_status.get("warnings", []))

    queue_items, total_items, truncated = project_intake_unpack_queue_items(staged, item_limit)
    action_counts: dict[str, int] = {}
    for item in queue_items:
        for action in item["suggested_human_actions"]:
            action_counts[action] = action_counts.get(action, 0) + 1

    if blockers:
        state = "blocked"
    elif receipt_status is None:
        state = "needs_project_review"
    else:
        coverage = receipt_status.get("checklist_coverage") if isinstance(receipt_status.get("checklist_coverage"), dict) else {}
        state = "ready_for_manual_unpack_choice" if coverage.get("complete") else "needs_more_project_review"

    return {
        "ok": not blockers,
        "dry_run": True,
        "action": "archive_project_intake_unpack_queue",
        "archive_id": archive_id,
        "state": state,
        "receipt_path": receipt_status.get("receipt_path") if receipt_status else None,
        "staged_folder_basis": staged_folder_basis,
        "staged_folder_relative": staged_folder_relative,
        "staged_folder_path_included": False,
        "folder_summary": folder_summary,
        "staging_convention": staging_convention,
        "unpack_queue": {
            "queue_kind": "top_level_staged_items",
            "item_ref_policy": "opaque_local_order_refs_not_paths",
            "total_item_count": total_items,
            "returned_item_count": len(queue_items),
            "truncated": truncated,
            "max_items": item_limit,
            "items": queue_items,
            "entry_names_included": False,
            "local_paths_included": False,
        },
        "next_human_turn": project_intake_unpack_next_human_turn(state, len(queue_items), bool(receipt_status)),
        "command_guidance": {
            "review_project_questions_first": "archive project-intake-next-question <archive-root> --staged-folder <staged-folder> --dry-run --format json",
            "record_project_answer_with": "archive project-intake-record-answer <archive-root> --answer <answer-json> --dry-run, then --approve after human review",
            "record_unpack_choice_with": (
                "archive project-intake-unpack-choice <archive-root> --choice <choice-json> "
                "--receipt <project-intake-receipt> --staged-folder <staged-folder> "
                "--dry-run, then --approve after human review"
            ),
            "after_human_selects_file": (
                "archive project-intake-item-plan <archive-root> --receipt <project-intake-receipt> "
                "--local-path <human-selected-local-path> --dry-run --format json"
            ),
            "selection_requires_human_to_map_item_ref_locally": True,
            "automatic_execution_authorized": False,
        },
        "privacy_guards": {
            "top_level_only": True,
            "recursive_scan": False,
            "entry_names_included": False,
            "local_paths_included": False,
            "decision_values_included": False,
            "file_bodies_read": False,
            "content_hashes_calculated": False,
            "provider_calls": False,
            "writes": False,
        },
        "closed_actions": {
            "automatic_classification": False,
            "source_intake_run": False,
            "objet_capture_run": False,
            "draft_created": False,
            "minted": False,
            "provider_upload": False,
            "cleanup_performed": False,
        },
        "suggested_action_counts": action_counts,
        "next_safe_actions": project_intake_unpack_queue_safe_actions(state),
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
        "would_change": [],
    }


def project_intake_unpack_queue_items(staged_folder: Path, max_items: int) -> tuple[list[dict[str, Any]], int, bool]:
    children = sorted(staged_folder.iterdir(), key=lambda item: item.name.casefold())
    items: list[dict[str, Any]] = []
    for index, child in enumerate(children[:max_items], start=1):
        items.append(project_intake_unpack_queue_item(child, index))
    return items, len(children), len(children) > max_items


def project_intake_unpack_queue_item(path: Path, index: int) -> dict[str, Any]:
    kind = "other"
    extension = None
    size_bucket = "unknown"
    if path.is_symlink():
        kind = "other"
    elif path.is_file():
        kind = "file"
        extension = project_intake_safe_extension(path.suffix)
        size_bucket = project_intake_size_bucket(project_intake_file_size(path))
    elif path.is_dir():
        kind = "folder"

    return {
        "item_ref": f"item-{index:04d}",
        "kind": kind,
        "extension": extension,
        "size_bucket": size_bucket,
        "selection_hint": "Map this item_ref to the matching top-level item in the local staged folder view.",
        "suggested_human_actions": project_intake_unpack_suggested_actions(kind, extension),
        "name_included": False,
        "local_path_included": False,
        "file_body_read": False,
        "content_hash_calculated": False,
    }


def project_intake_safe_extension(suffix: str) -> str | None:
    normalized = suffix.lower().strip()
    if not normalized or len(normalized) > 16:
        return None
    if re.fullmatch(r"\.[a-z0-9][a-z0-9._+-]*", normalized):
        return normalized
    return None


def project_intake_file_size(path: Path) -> int | None:
    try:
        return path.stat().st_size
    except OSError:
        return None


def project_intake_size_bucket(size: int | None) -> str:
    if size is None:
        return "unknown"
    if size == 0:
        return "empty"
    if size < 1024 * 1024:
        return "small"
    if size < 100 * 1024 * 1024:
        return "medium"
    return "large"


def project_intake_unpack_suggested_actions(kind: str, extension: str | None) -> list[str]:
    if kind == "folder":
        return ["open_as_next_box", "split_into_new_session", "defer", "mark_noise_after_review"]
    if kind == "file" and extension in {".md", ".txt", ".rst", ".html", ".csv", ".json"}:
        return ["review_as_working_note_or_source", "plan_source_intake", "defer", "mark_noise_after_review"]
    if kind == "file":
        return ["review_as_original_objet", "plan_source_intake", "defer", "mark_noise_after_review"]
    return ["inspect_manually", "defer", "mark_noise_after_review"]


def project_intake_unpack_next_human_turn(state: str, item_count: int, has_receipt: bool) -> dict[str, Any]:
    if state == "blocked":
        return {
            "kind": "blocked",
            "ask_user": "Fix the blocker before choosing the next staged item.",
            "answer_type": "manual_fix_then_continue",
            "writes": False,
        }
    if state == "needs_project_review":
        ask = "Choose whether to answer project-intake review questions first, or pick one item_ref only for discussion without source-intake."
    elif state == "needs_more_project_review":
        ask = "Finish the remaining project-intake review questions, then choose one item_ref for the next source-intake plan."
    elif item_count == 0:
        ask = "No top-level staged items were found. Should this intake session stop, restage, or defer?"
    else:
        ask = "Which item_ref should we unpack next, and should it be inspected, preserved as an objet, drafted from, deferred, marked as noise, or split into another session?"
    return {
        "kind": "choose_next_unpack_item",
        "ask_user": ask,
        "answer_type": "item_ref_and_human_action",
        "allowed_actions": [
            "inspect_next",
            "preserve_as_objet",
            "draft_from",
            "defer",
            "mark_noise_after_review",
            "split_session",
            "stop",
        ],
        "requires_project_intake_receipt_before_source_intake": not has_receipt,
        "decision_values_included": False,
        "writes": False,
    }


def project_intake_unpack_queue_safe_actions(state: str) -> list[str]:
    if state == "blocked":
        return [
            "Fix the blocker before asking the human to choose a staged item.",
            "Do not run source-intake, capture, drafting, minting, provider sync, or cleanup from a blocked unpack queue.",
        ]
    actions = [
        "Ask the human to choose exactly one item_ref and one intended action.",
        "Have the human map the item_ref to the local staged item; this queue does not expose names or paths.",
        "Record the reviewed item_ref and intended action with project-intake-unpack-choice before per-item source-intake planning.",
        "Run project-intake-item-plan only after a reviewed project-intake receipt exists and one local file is selected.",
        "Keep capture, drafting, minting, provider sync, and cleanup as separate approval gates.",
    ]
    if state == "needs_project_review":
        actions.insert(0, "Run project-intake-next-question and record the required human answers before source-intake.")
    elif state == "needs_more_project_review":
        actions.insert(0, "Finish the remaining project-intake questions before using the queue for source-intake.")
    return actions


def project_intake_unpack_choice_allowed_actions() -> list[str]:
    return [
        "inspect_next",
        "preserve_as_objet",
        "draft_from",
        "defer",
        "mark_noise_after_review",
        "split_session",
        "stop",
    ]


def load_project_intake_unpack_choice_payload(choice_path: Path | str) -> dict[str, Any]:
    path = Path(choice_path).expanduser().resolve()
    if not path.is_file():
        raise ArchiveServiceError("Project intake unpack choice file does not exist or is not a file.")
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ArchiveServiceError("Project intake unpack choice file must contain one JSON object.") from exc
    except OSError as exc:
        raise ArchiveServiceError("Project intake unpack choice file could not be read.") from exc
    if not isinstance(data, dict):
        raise ArchiveServiceError("Project intake unpack choice file must contain one JSON object.")
    return data


def normalize_project_intake_unpack_choice_payload(payload: dict[str, Any], blockers: list[str]) -> dict[str, Any]:
    schema = payload.get("schema")
    if schema != PROJECT_INTAKE_UNPACK_CHOICE_SCHEMA:
        blockers.append(f"Project intake unpack choice schema must be {PROJECT_INTAKE_UNPACK_CHOICE_SCHEMA}.")

    allowed_keys = {"schema", "item_ref", "intended_action", "human_confirmed", "notes"}
    unknown_keys = sorted(set(str(key) for key in payload) - allowed_keys)
    if unknown_keys:
        blockers.append("Project intake unpack choice contains unsupported field(s).")

    item_ref = payload.get("item_ref")
    if not isinstance(item_ref, str) or not PROJECT_INTAKE_ITEM_REF_RE.match(item_ref) or item_ref == "item-0000":
        blockers.append("Project intake unpack choice item_ref must look like item-0001.")
        item_ref = "item-0000"

    intended_action = payload.get("intended_action")
    if not isinstance(intended_action, str) or intended_action not in set(project_intake_unpack_choice_allowed_actions()):
        blockers.append("Project intake unpack choice intended_action must be one of the allowed unpack actions.")
        intended_action = "invalid"

    if payload.get("human_confirmed") is not True:
        blockers.append("Project intake unpack choice requires human_confirmed: true.")

    normalized: dict[str, Any] = {
        "item_ref": item_ref,
        "intended_action": intended_action,
        "human_confirmed": payload.get("human_confirmed") is True,
    }
    if "notes" in payload and payload.get("notes") is not None:
        if not isinstance(payload.get("notes"), str):
            blockers.append("Project intake unpack choice notes must be a string when provided.")
        else:
            normalized["notes"] = validate_project_intake_safe_value(payload.get("notes"), blockers, "$.notes")
    return normalized


def project_intake_unpack_choice_receipt_path(session_id: str, choice_sha256: str) -> str:
    session_slug = safe_slug(session_id)
    return (
        f"{PROJECT_INTAKE_UNPACK_CHOICE_RECEIPTS_DIR}/"
        f"{session_slug}-{choice_sha256[:16]}.project-intake-unpack-choice.json"
    )


def project_intake_unpack_queue_digest(queue: dict[str, Any]) -> str:
    items = queue.get("items") if isinstance(queue.get("items"), list) else []
    digest_items = []
    for item in items:
        if isinstance(item, dict):
            digest_items.append(
                {
                    "item_ref": item.get("item_ref"),
                    "kind": item.get("kind"),
                    "extension": item.get("extension"),
                    "size_bucket": item.get("size_bucket"),
                }
            )
    return sha256_json_hex(
        {
            "queue_kind": queue.get("queue_kind"),
            "item_ref_policy": queue.get("item_ref_policy"),
            "total_item_count": queue.get("total_item_count"),
            "returned_item_count": queue.get("returned_item_count"),
            "truncated": queue.get("truncated"),
            "items": digest_items,
        }
    )


def project_intake_unpack_choice_safe_actions(blocked: bool, intended_action: str) -> list[str]:
    if blocked:
        return [
            "Fix the choice file, project-intake receipt, staged folder, or approval mode before writing an unpack choice receipt.",
            "Do not run source-intake, capture, drafting, minting, provider sync, or cleanup from a blocked unpack choice.",
        ]
    if intended_action in {"preserve_as_objet", "draft_from", "inspect_next"}:
        return [
            "Use this choice receipt only as human-reviewed context for the next local item discussion.",
            "Have the human map the chosen item_ref to one actual local staged item before project-intake-item-plan.",
            "Run project-intake-item-plan and source-intake as separate dry-runs; this receipt does not authorize capture or drafting.",
            "Keep capture, drafting, minting, provider sync, and cleanup as later approval gates.",
        ]
    if intended_action == "split_session":
        return [
            "Start a separate project-intake session for the selected box before source-intake or capture.",
            "Do not treat this choice receipt as permission to move, copy, upload, or delete staged files.",
        ]
    return [
        "Record the human choice as session context only.",
        "Do not run source-intake, capture, drafting, minting, provider sync, or cleanup for a deferred, noise, or stopped item.",
    ]


def project_intake_unpack_choice(
    archive_root: Path | str,
    choice_path: Path | str,
    *,
    receipt: str,
    staged_folder: Path | str,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []

    if dry_run is approve:
        blockers.append("Choose exactly one mode: --dry-run or --approve.")

    reviewer = safe_project_intake_actor_id(reviewed_by)
    if approve and reviewer is None:
        blockers.append("Project intake unpack choice approval requires --reviewed-by with a safe actor id.")
    if reviewed_by and reviewer is None:
        blockers.append("reviewed_by must be a safe non-secret actor id.")

    status = project_intake_status(root, receipt, dry_run=True)
    blockers.extend(str(item) for item in status.get("blockers", []))
    warnings.extend(str(item) for item in status.get("warnings", []))
    coverage = status.get("checklist_coverage") if isinstance(status.get("checklist_coverage"), dict) else {}
    if not coverage.get("complete"):
        blockers.append("Project intake checklist must be complete before recording an unpack choice.")

    queue_result = project_intake_unpack_queue(root, staged_folder, receipt=receipt, max_items=100, dry_run=True)
    blockers.extend(str(item) for item in queue_result.get("blockers", []))
    warnings.extend(str(item) for item in queue_result.get("warnings", []))
    queue = queue_result.get("unpack_queue") if isinstance(queue_result.get("unpack_queue"), dict) else {}

    choice_payload = load_project_intake_unpack_choice_payload(choice_path)
    normalized_choice = normalize_project_intake_unpack_choice_payload(choice_payload, blockers)
    item_ref = normalized_choice["item_ref"]
    intended_action = normalized_choice["intended_action"]

    queue_items = [item for item in queue.get("items", []) if isinstance(item, dict)]
    selected_item = next((item for item in queue_items if item.get("item_ref") == item_ref), None)
    if selected_item is None:
        blockers.append("Project intake unpack choice item_ref must match the current unpack queue.")

    selected_item_context = None
    if selected_item is not None:
        selected_item_context = {
            "item_ref": selected_item.get("item_ref"),
            "kind": selected_item.get("kind"),
            "extension": selected_item.get("extension"),
            "size_bucket": selected_item.get("size_bucket"),
            "entry_name_included": False,
            "local_path_included": False,
            "file_body_read": False,
            "content_hash_calculated": False,
        }

    queue_sha256 = project_intake_unpack_queue_digest(queue)
    session_id = status.get("session_id") if isinstance(status.get("session_id"), str) else "invalid-session"
    project_receipt_path = status.get("receipt_path") if isinstance(status.get("receipt_path"), str) else receipt
    choice_record = {
        "schema": PROJECT_INTAKE_UNPACK_CHOICE_SCHEMA,
        "session_id": session_id,
        "project_intake_receipt": project_receipt_path,
        "queue_sha256": queue_sha256,
        "choice": normalized_choice,
        "selected_item_context": selected_item_context,
    }
    choice_sha256 = sha256_json_hex(choice_record)
    receipt_relative = project_intake_unpack_choice_receipt_path(session_id, choice_sha256)
    receipt_path = archive_internal_path(root, receipt_relative)
    if approve and receipt_path.exists():
        blockers.append("Project intake unpack choice receipt already exists for this session and choice hash.")

    privacy_guards = {
        "choice_file_read": True,
        "project_intake_receipt_read": True,
        "staged_folder_scanned_top_level_only": True,
        "entry_names_included": False,
        "local_paths_included": False,
        "choice_notes_echoed": False,
        "decision_values_included": False,
        "file_bodies_read": False,
        "content_hashes_calculated": False,
        "provider_calls": False,
        "writes": approve and not blockers,
    }
    closed_actions = {
        "source_intake_run": False,
        "objet_capture_run": False,
        "derived_text_capture_run": False,
        "draft_created": False,
        "zet_minted": False,
        "staged_cleanup_performed": False,
        "provider_api_called": False,
        "automatic_classification": False,
    }
    result: dict[str, Any] = {
        "ok": not blockers,
        "dry_run": dry_run,
        "action": "archive_project_intake_unpack_choice",
        "archive_root": str(root),
        "archive_id": archive_id,
        "session_id": session_id,
        "project_intake_receipt": project_receipt_path,
        "reviewed_by": reviewer,
        "choice_sha256": choice_sha256,
        "choice_summary": {
            "item_ref": item_ref,
            "intended_action": intended_action,
            "human_confirmed": normalized_choice.get("human_confirmed") is True,
            "notes_recorded": "notes" in normalized_choice,
            "notes_included_in_output": False,
        },
        "queue_context": {
            "queue_sha256": queue_sha256,
            "total_item_count": queue.get("total_item_count"),
            "returned_item_count": queue.get("returned_item_count"),
            "truncated": queue.get("truncated"),
            "selected_item": selected_item_context,
            "entry_names_included": False,
            "local_paths_included": False,
        },
        "privacy_guards": privacy_guards,
        "closed_actions": closed_actions,
        "proposed_receipt_path": receipt_relative,
        "would_change": [receipt_relative] if dry_run and not blockers else [],
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
        "next_safe_actions": project_intake_unpack_choice_safe_actions(bool(blockers), intended_action),
    }
    if blockers or dry_run:
        return result

    assert reviewer is not None
    reviewed_at = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    receipt_doc = {
        "schema": PROJECT_INTAKE_UNPACK_CHOICE_RECEIPT_SCHEMA,
        "receipt_id": f"receipt:project-intake-unpack-choice:{safe_slug(session_id)}:{choice_sha256[:16]}",
        "receipt_kind": "project_intake_unpack_choice",
        "receipt_path": receipt_relative,
        "action": "archive_project_intake_unpack_choice",
        "dry_run": False,
        "timestamp": reviewed_at,
        "archive_id": archive_id,
        "session_id": session_id,
        "project_intake_receipt": project_receipt_path,
        "project_intake_decision_sha256": status.get("decision_sha256"),
        "reviewed_by": reviewer,
        "reviewed_at": reviewed_at,
        "choice_sha256": choice_sha256,
        "source_choice_schema": PROJECT_INTAKE_UNPACK_CHOICE_SCHEMA,
        "choice": normalized_choice,
        "queue_context": result["queue_context"],
        "privacy_guards": privacy_guards,
        "closed_actions": closed_actions,
        "files_written": [receipt_relative],
        "blockers": [],
        "warnings": unique_preserve_order(warnings),
    }

    created_dirs = missing_parent_dirs_before_write(root, [receipt_path])
    created_paths: list[Path] = []
    try:
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        write_json_new_file(receipt_path, receipt_doc)
        created_paths.append(receipt_path)
    except Exception:
        for path in created_paths:
            try:
                path.unlink()
            except OSError:
                pass
        cleanup_created_empty_dirs(root, created_dirs)
        raise

    result.update(
        {
            "ok": True,
            "dry_run": False,
            "receipt_path": receipt_relative,
            "files_written": [receipt_relative],
            "would_change": [],
            "privacy_guards": privacy_guards,
        }
    )
    return result


def project_intake_staging_convention(archive_root: Path, staged_folder: Path) -> dict[str, Any]:
    expected_intake_root = (archive_root.parent / f"{archive_root.name}-objets" / "intake").resolve()
    in_archive_staging_root = (archive_root / "staging" / "incoming").resolve()
    follows_sibling = staged_folder.parent == expected_intake_root and staged_folder.name != "intake"
    try:
        resolved_staged = staged_folder.resolve()
        follows_in_archive = (
            resolved_staged == in_archive_staging_root or in_archive_staging_root in resolved_staged.parents
        )
    except OSError:
        follows_in_archive = False
    follows = follows_sibling or follows_in_archive
    if follows_in_archive:
        matched_shape = "in_archive_capture_staging"
    elif follows_sibling:
        matched_shape = "sibling_objet_store_intake"
    else:
        matched_shape = None
    status = "matches_recommended_shape" if follows else "outside_recommended_shape"
    return {
        "follows_staging_convention": follows,
        "status": status,
        "matched_shape": matched_shape,
        # Canonical capture intake stages INSIDE the archive root (D2, v0.3.160):
        # objet-capture-selection requires archive-relative staged paths, so only
        # in-archive staging can feed capture. The date layer is recommended, not
        # required. The sibling store remains the bulk external-originals home.
        "recommended_in_archive_shape": "<archive-root>/staging/incoming/<YYYY-MM-DD>/<project_slug>",
        "in_archive_staging_supports_capture": True,
        "recommended_shape": r"C:\Users\<user>\zettel-kasten-<profile_slug>-objets\intake\<project_slug>",
        "recommended_objet_store_suffix": "-objets",
        "recommended_intake_folder_name": "intake",
        "requires_one_project_folder": True,
    }


def project_intake_staging_guide(
    archive_root: Path | str,
    *,
    project_slug: str,
    dry_run: bool = True,
) -> dict[str, Any]:
    if not dry_run:
        raise ArchiveServiceError("project-intake-staging-guide is dry-run only.")
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    normalized_slug = (project_slug or "").strip().lower()
    blockers: list[str] = []
    if not safe_project_intake_slug(normalized_slug):
        blockers.append("project_slug must use lowercase ASCII letters, numbers, and hyphens only.")

    objet_store = (root.parent / f"{root.name}-objets").resolve()
    intake_root = (objet_store / "intake").resolve()
    staged_folder = (intake_root / (normalized_slug or "<project-slug>")).resolve()
    follows_expected_parent = staged_folder.parent == intake_root
    return {
        "ok": not blockers,
        "dry_run": True,
        "action": "archive_project_intake_staging_guide",
        "archive_id": archive_id,
        "project_slug": normalized_slug or None,
        "recommended_paths": {
            "archive_root": str(root),
            "objet_store_root": str(objet_store),
            "intake_root": str(intake_root),
            "staged_project_folder": str(staged_folder),
            # Canonical capture intake (D2, v0.3.160) stages INSIDE the archive
            # root; these two are archive-relative on purpose.
            "in_archive_staging_root": "staging/incoming",
            "in_archive_staged_project_folder": "staging/incoming/<YYYY-MM-DD>/" + (normalized_slug or "<project-slug>"),
        },
        "path_policy": {
            "one_project_per_staged_folder": True,
            "staged_folder_is_temporary": True,
            "archive_root_is_git_control_plane": True,
            "objet_store_holds_raw_originals": True,
            "do_not_commit_raw_sources_to_public_repo": True,
            "create_directories": False,
            "move_files": False,
            "copy_files": False,
            "delete_files": False,
            "provider_calls": False,
            "writes": False,
        },
        "staging_convention": {
            "recommended_in_archive_shape": "<archive-root>/staging/incoming/<YYYY-MM-DD>/<project_slug>",
            "in_archive_staging_supports_capture": True,
            "recommended_shape": r"C:\Users\<user>\zettel-kasten-<profile_slug>-objets\intake\<project_slug>",
            "recommended_objet_store_suffix": "-objets",
            "recommended_intake_folder_name": "intake",
            "follows_expected_parent": follows_expected_parent,
        },
        "next_safe_actions": [
            "For capture intake, stage INSIDE the archive root: create the in_archive_staged_project_folder manually (objet-capture-selection requires archive-relative staged paths; the date layer is recommended, not required).",
            "For bulk external originals that must stay outside git, create the sibling staged_project_folder manually if it does not exist.",
            "Place exactly one project folder's temporary intake materials there before running project-intake-plan.",
            "Run project-intake-next-question --staged-folder <folder> --dry-run to start the human review loop.",
            "Do not upload, capture, draft, mint, or clean staged files from this guide.",
        ],
        "blockers": unique_preserve_order(blockers),
        "warnings": [],
        "would_change": [],
    }


def project_intake_session_guide(
    archive_root: Path | str,
    *,
    project_slug: str | None = None,
    staged_folder: Path | str | None = None,
    receipt: str | None = None,
    session_id: str | None = None,
    staged_folder_ref: str | None = None,
    dry_run: bool = True,
) -> dict[str, Any]:
    if not dry_run:
        raise ArchiveServiceError("project-intake-session-guide is dry-run only.")
    selected_inputs = [project_slug is not None, staged_folder is not None, bool(receipt)]
    if sum(1 for item in selected_inputs if item) != 1:
        raise ArchiveServiceError("Pass exactly one of project_slug, staged_folder, or receipt.")

    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []
    mode = "unknown"
    state = "blocked"
    current_context: dict[str, Any] = {}
    next_human_turn: dict[str, Any] | None = None
    decision_record_template: dict[str, Any] | None = None
    command_guidance: dict[str, Any] = {}

    if project_slug is not None:
        mode = "staging"
        guide = project_intake_staging_guide(root, project_slug=project_slug, dry_run=True)
        blockers.extend(guide.get("blockers") or [])
        warnings.extend(guide.get("warnings") or [])
        paths = guide.get("recommended_paths") if isinstance(guide.get("recommended_paths"), dict) else {}
        current_context = {
            "project_slug": guide.get("project_slug"),
            "recommended_paths": paths,
            "path_policy": guide.get("path_policy"),
            "staged_folder_exists": False,
            "staged_folder_created": False,
        }
        state = "blocked" if blockers else "needs_manual_staging"
        next_human_turn = {
            "kind": "manual_staging",
            "ask_user": "Create the staged project folder manually, place exactly one project there, then run project-intake-plan.",
            "answer_type": "manual_action_then_continue",
            "writes": False,
        }
        command_guidance = {
            "current_safe_command": (
                "archive project-intake-staging-guide <archive-root> "
                "--project-slug <project-slug> --dry-run --format json"
            ),
            "next_safe_command_after_manual_staging": (
                "archive project-intake-plan <archive-root> "
                "--staged-folder <staged-project-folder> --dry-run --format json"
            ),
            "automatic_execution_authorized": False,
        }
    elif staged_folder is not None:
        mode = "new_session"
        plan = project_intake_plan(root, staged_folder)
        question = project_intake_next_question(root, staged_folder=staged_folder, dry_run=True)
        template = project_intake_decision_template(
            root,
            staged_folder=staged_folder,
            session_id=session_id,
            staged_folder_ref=staged_folder_ref,
            dry_run=True,
        )
        blockers.extend(question.get("blockers") or [])
        warnings.extend(plan.get("warnings") or [])
        warnings.extend(question.get("warnings") or [])
        current_context = {
            "folder_summary": plan["folder_summary"],
            "follows_staging_convention": plan["follows_staging_convention"],
            "staging_convention": plan["staging_convention"],
            "entry_names_included": False,
            "file_bodies_read": False,
        }
        next_human_turn = question.get("next_question")
        decision_record_template = template.get("decision_record_template")
        state = "blocked" if blockers else str(question.get("state") or "needs_first_review")
        command_guidance = {
            "ask_next_question_with": (
                "archive project-intake-next-question <archive-root> "
                "--staged-folder <staged-folder> --dry-run --format json"
            ),
            "build_answer_template_with": (
                "archive project-intake-decision-template <archive-root> "
                "--staged-folder <staged-folder> --session-id <safe-session-id> --dry-run --format json"
            ),
            "record_reviewed_answer_with": (
                "archive project-intake-decisions <archive-root> "
                "--decisions <reviewed-decisions.json> --dry-run, then --approve --reviewed-by <actor>"
            ),
            "automatic_execution_authorized": False,
        }
    else:
        mode = "continuing_session"
        assert receipt is not None
        status = project_intake_status(root, receipt, dry_run=True)
        question = project_intake_next_question(root, receipt=receipt, dry_run=True)
        template = project_intake_decision_template(
            root,
            receipt=receipt,
            session_id=session_id,
            staged_folder_ref=staged_folder_ref,
            dry_run=True,
        )
        blockers.extend(status.get("blockers") or [])
        blockers.extend(question.get("blockers") or [])
        warnings.extend(status.get("warnings") or [])
        warnings.extend(question.get("warnings") or [])
        coverage = status.get("checklist_coverage") if isinstance(status.get("checklist_coverage"), dict) else {}
        current_context = {
            "receipt_path": status.get("receipt_path"),
            "session_id": status.get("session_id"),
            "readiness": status.get("readiness"),
            "checklist_coverage": coverage,
            "decision_values_included": False,
        }
        next_human_turn = question.get("next_question")
        decision_record_template = template.get("decision_record_template")
        if blockers:
            state = "blocked"
        elif coverage.get("complete"):
            state = "ready_for_item_selection"
        else:
            state = str(question.get("state") or "needs_more_review")
        command_guidance = {
            "review_receipt_with": (
                "archive project-intake-status <archive-root> "
                "--receipt <project-intake-receipt> --dry-run --format json"
            ),
            "ask_next_question_with": (
                "archive project-intake-next-question <archive-root> "
                "--receipt <project-intake-receipt> --dry-run --format json"
            ),
            "build_answer_template_with": (
                "archive project-intake-decision-template <archive-root> "
                "--receipt <project-intake-receipt> --dry-run --format json"
            ),
            "queue_unpack_items_with": (
                "archive project-intake-unpack-queue <archive-root> "
                "--staged-folder <staged-folder> --receipt <project-intake-receipt> --dry-run --format json"
            ),
            "record_unpack_choice_with": (
                "archive project-intake-unpack-choice <archive-root> --choice <choice-json> "
                "--receipt <project-intake-receipt> --staged-folder <staged-folder> "
                "--dry-run, then --approve after human review"
            ),
            "plan_one_selected_item_with": (
                "archive project-intake-item-plan <archive-root> "
                "--receipt <project-intake-receipt> --local-path <human-selected-file> --dry-run --format json"
            ),
            "automatic_execution_authorized": False,
        }

    return {
        "ok": not blockers,
        "dry_run": True,
        "action": "archive_project_intake_session_guide",
        "archive_id": archive_id,
        "mode": mode,
        "state": state,
        "current_context": current_context,
        "next_human_turn": next_human_turn,
        "decision_record_template": decision_record_template,
        "command_guidance": command_guidance,
        "privacy_guards": {
            "entry_names_included": False,
            "decision_values_included": False,
            "file_bodies_read": False,
            "content_hashes_calculated": False,
            "provider_calls": False,
            "writes": False,
        },
        "closed_actions": {
            "source_intake_run": False,
            "objet_capture_run": False,
            "draft_created": False,
            "minted": False,
            "provider_upload": False,
            "cleanup_performed": False,
            "full_auto_used": False,
        },
        "next_safe_actions": project_intake_session_guide_safe_actions(state),
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
        "would_change": [],
    }


def project_intake_session_guide_safe_actions(state: str) -> list[str]:
    if state == "blocked":
        return [
            "Fix the blocker before continuing the project intake session.",
            "Do not run source-intake, capture, drafting, minting, upload, or cleanup from a blocked guide.",
        ]
    if state == "needs_manual_staging":
        return [
            "Create the staged folder manually and place exactly one project there.",
            "Run project-intake-plan or project-intake-session-guide with --staged-folder after staging.",
            "Do not capture, draft, mint, upload, or clean from the staging guide.",
        ]
    if state == "ready_for_item_selection":
        return [
            "Ask the human to select exactly one opaque item_ref and intended action from project-intake-unpack-queue.",
            "Record the reviewed selection with project-intake-unpack-choice before per-item planning.",
            "Have the human map that item_ref to exactly one local file for the next item plan.",
            "Run project-intake-item-plan for that selected file before source-intake recording or capture selection.",
            "Keep capture, drafting, minting, provider sync, and cleanup as separate approval gates.",
        ]
    return [
        "Ask the next_human_turn.ask_user question.",
        "Record only the human-reviewed answer in a decisions JSON file.",
        "Run project-intake-decisions --dry-run before approving any new receipt.",
    ]


def safe_project_intake_slug(value: str) -> bool:
    text = value.strip()
    if not text or not text.isascii():
        return False
    if contains_forbidden_location_reference(text) or GITHUB_SECRET_LIKE_RE.search(text):
        return False
    return bool(PROJECT_INTAKE_SLUG_RE.match(text))


