def _project_update_terminal_handoff_recovery_required_result() -> dict[str, Any]:
    """Route one exact active terminal capsule to identifier-free resume."""

    result = _project_update_terminal_cleanup_required_result(
        exact_history_count=1,
        resumable_transaction_present=True,
    )
    result.update(
        {
            "outcome_basis": "exact_active_terminal_handoff_requires_resume",
            "terminal_handoff_recovery_required": True,
        }
    )
    return result


def _project_update_exact_preapproval_resume_classification_read_only(
    project_root: Path,
    transaction_ref: str,
) -> str | None:
    """Return one fully classified preapproval crash state, never a guess."""

    matching = [
        item
        for item in project_update_transaction.inspect_prelock_orphans(
            project_root
        )
        if item.transaction_ref == transaction_ref
    ]
    if len(matching) != 1:
        return None
    classification = matching[0].classification
    return (
        classification
        if classification
        in {
            "reserved_locked_unsealed",
            "reserved_abort_receipt_pending",
            "intent_sealed_lock_binding_incomplete",
        }
        else None
    )


def _project_update_terminal_cleanup_namespace_classification_read_only(
    project_root: Path,
    *,
    allowed_reservation: (
        project_update_transaction.ReservedProjectUpdateTransaction | None
    ) = None,
    allowed_lock_bytes: bytes | None = None,
) -> tuple[str, int] | None:
    """Classify one exact bounded transaction namespace allowlist.

    Proof bytes are not authenticated success authority. This strict read-only
    classifier proves every namespace entry. Besides canonical cleanup proofs,
    it recognizes only two original-directory states: one transaction selected
    by the authenticated resume locator, and exact pre-intent abort receipts
    whose five-file tree proves that no project-domain writer ran. Unknown
    originals, arbitrary names, unsafe types, scan races, and partial cleanup
    all return ``None``. This keeps a fresh approval from treating an ignored
    namespace entry as ordinary absence while allowing the public ``--resume``
    path to compact terminal control history produced by WOM itself.
    """

    if (
        allowed_reservation is None
        and allowed_lock_bytes is not None
    ):
        return None
    lock_path = project_root.joinpath(
        *PurePosixPath(
            project_update_transaction.PROJECT_UPDATE_LOCK_LOGICAL
        ).parts
    )
    try:
        live_lock_present = os.path.lexists(lock_path)
        # A lock is not itself cleanup authority, but neither is it an
        # automatic classification failure. Without an explicitly supplied
        # reservation, the strict active locator and orphan inspection below
        # must bind it to the one exact resumable transaction.
        if allowed_lock_bytes is not None:
            if not live_lock_present or not hmac.compare_digest(
                project_update_transaction._read_regular(
                    lock_path,
                    within=project_root,
                    maximum=(
                        project_update_transaction.MAX_DOCUMENT_BYTES + 1
                    ),
                ),
                allowed_lock_bytes,
            ):
                return None
    except (
        OSError,
        project_update_transaction.ProjectUpdateTransactionError,
    ):
        return None
    transaction_root = project_root.joinpath(
        *PurePosixPath(
            project_update_transaction.TRANSACTION_ROOT_LOGICAL
        ).parts
    )
    try:
        if not os.path.lexists(transaction_root):
            return (
                ("absent", 0)
                if allowed_reservation is None and not live_lock_present
                else None
            )
        project_update_transaction._safe_existing_chain(
            transaction_root,
            directory=True,
        )
        before = os.lstat(transaction_root)
        runtime_cleanup_inventory = (
            project_runtime.runtime_candidate_cleanup_sidecar_inventory(
                project_root
            )
        )
        if (
            not isinstance(runtime_cleanup_inventory, Mapping)
            or runtime_cleanup_inventory.get("state") != "passed"
            or runtime_cleanup_inventory.get("unattributed_sidecar_count") != 0
            or any(
                runtime_cleanup_inventory.get(key)
                for key in (
                    "orphaned_transaction_refs",
                    "review_required_transaction_refs",
                    "unavailable_transaction_refs",
                )
            )
        ):
            return None
        recoverable_runtime_cleanup_refs = set(
            runtime_cleanup_inventory.get("recoverable_transaction_refs", ())
        )
        if any(
            type(item) is not str
            or project_update_transaction.TRANSACTION_REF_RE.fullmatch(item)
            is None
            for item in recoverable_runtime_cleanup_refs
        ):
            return None
        observed_runtime_cleanup_refs: set[str] = set()
        expected_reservation_ref = (
            allowed_reservation.transaction_ref
            if allowed_reservation is not None
            else None
        )
        expected_reservation_sha256 = (
            allowed_reservation.reservation.sha256
            if allowed_reservation is not None
            else None
        )
        expected_resume_ref: str | None = expected_reservation_ref
        if allowed_reservation is None:
            try:
                expected_resume_ref = (
                    project_update_transaction
                    .active_transaction_ref_for_resume_read_only(project_root)
                )
            except project_update_transaction.ProjectUpdateTransactionError as failure:
                if failure.code != "project_update_transaction_not_found":
                    return None
        exact_preapproval_classification: str | None = None
        if allowed_reservation is None and expected_resume_ref is not None:
            matching_orphans = [
                item
                for item in project_update_transaction.inspect_prelock_orphans(
                    project_root
                )
                if item.transaction_ref == expected_resume_ref
            ]
            if len(matching_orphans) != 1:
                return None
            candidate_classification = matching_orphans[0].classification
            if candidate_classification in {
                "reserved_locked_unsealed",
                "reserved_abort_receipt_pending",
                "intent_sealed_lock_binding_incomplete",
            }:
                exact_preapproval_classification = candidate_classification
        allowed_reservation_seen = False
        resumable_transaction_seen = False
        terminal_original_seen = False
        abort_original_refs: set[str] = set()
        tombstone_refs: set[str] = set()
        seen = 0
        proof_count = 0
        with os.scandir(transaction_root) as entries:
            for entry in entries:
                seen += 1
                if (
                    seen
                    > project_update_transaction
                    .MAX_TERMINAL_CLEANUP_SCAN_ENTRIES
                ):
                    return None
                name = entry.name
                original_match = re.fullmatch(
                    r"update_[0-9a-f]{32}",
                    name,
                )
                tombstone_match = re.fullmatch(
                    r"\.cleanup_(update_[0-9a-f]{32})",
                    name,
                )
                proof_match = re.fullmatch(
                    r"\.cleanup-proof_(update_[0-9a-f]{32})\.json",
                    name,
                )
                runtime_cleanup_match = re.fullmatch(
                    re.escape(
                        project_runtime.PROJECT_RUNTIME_CLEANUP_CAPSULE_PREFIX
                    )
                    + r"(update_[0-9a-f]{32})"
                    + re.escape(
                        project_runtime.PROJECT_RUNTIME_CLEANUP_CAPSULE_SUFFIX
                    ),
                    name,
                )
                if original_match is not None:
                    if not entry.is_dir(follow_symlinks=False):
                        return None
                    reservation_root = Path(entry.path)
                    reservation_before = os.lstat(reservation_root)
                    if name == expected_resume_ref:
                        if resumable_transaction_seen:
                            return None
                        if allowed_reservation is not None:
                            reopened = (
                                project_update_transaction
                                .ReservedProjectUpdateTransaction.open(
                                    project_root,
                                    expected_reservation_ref,
                                )
                            )
                            if (
                                expected_reservation_sha256 is None
                                or reopened.reservation.sha256
                                != expected_reservation_sha256
                            ):
                                return None
                            files, directories = (
                                project_update_transaction
                                .ProjectUpdateTransaction._descendant_names(
                                    reservation_root
                                )
                            )
                            expected_files = {
                                "append.guard",
                                "marker.json",
                            }
                            if allowed_lock_bytes is not None:
                                expected_files.add(
                                    project_update_transaction
                                    .RESERVATION_LOCK_BACKLINK_NAME
                                )
                                if not hmac.compare_digest(
                                    reopened.existing_lock_bytes_read_only(),
                                    allowed_lock_bytes,
                                ):
                                    return None
                            if directories or files != expected_files:
                                return None
                            allowed_reservation_seen = True
                        else:
                            if exact_preapproval_classification in {
                                "reserved_locked_unsealed",
                                "reserved_abort_receipt_pending",
                            }:
                                active_reservation = (
                                    project_update_transaction
                                    .ReservedProjectUpdateTransaction.open(
                                        project_root,
                                        name,
                                    )
                                )
                                if (
                                    exact_preapproval_classification
                                    == "reserved_locked_unsealed"
                                ):
                                    active_reservation.existing_lock_bytes_read_only()
                                elif (
                                    active_reservation
                                    .inspect_abort_receipt_pending_read_only()
                                    is None
                                ):
                                    return None
                            else:
                                active = (
                                    project_update_transaction
                                    .ProjectUpdateTransaction.open(
                                        project_root,
                                        name,
                                        verify_candidate_content=False,
                                    )
                                )
                                active_inspection = active.inspect(
                                    verify_candidate_content=False
                                )
                                active_prefix = (
                                    active_inspection.journal.verified_prefix
                                )
                                if exact_preapproval_classification == (
                                    "intent_sealed_lock_binding_incomplete"
                                ):
                                    if (
                                        active_inspection.lock_backlinked
                                        or active_inspection.journal.state
                                        != "exact"
                                        or active_prefix
                                    ):
                                        return None
                                elif (
                                    not active_inspection.lock_backlinked
                                    or active_inspection.journal.state
                                    != "exact"
                                ):
                                    return None
                                elif active_inspection.terminal:
                                    # v0.4.18: a completed original whose own
                                    # durable plan names the journal approval
                                    # reference is finished by the
                                    # terminal-original route.  Shapes this
                                    # contract does not own keep today's
                                    # label; only positive contradicting
                                    # evidence becomes unresolved residue.
                                    terminal_state, _terminal_inspection = (
                                        project_update_transaction
                                        .classify_terminal_original_for_resume_read_only(
                                            project_root,
                                            name,
                                        )
                                    )
                                    if terminal_state == "refused":
                                        return None
                                    if terminal_state == "exact":
                                        terminal_original_seen = True
                            resumable_transaction_seen = True
                    else:
                        if allowed_reservation is not None:
                            return None
                        # The bounded abort-cleanup discovery below validates
                        # both the five-file terminal form and the crash state
                        # where its identity-bound cleanup plan is already
                        # durable. Merely seeing this name grants nothing.
                        abort_original_refs.add(name)
                    reservation_after = os.lstat(reservation_root)
                    if (
                        (
                            int(reservation_before.st_dev),
                            int(reservation_before.st_ino),
                            int(reservation_before.st_mtime_ns),
                        )
                        != (
                            int(reservation_after.st_dev),
                            int(reservation_after.st_ino),
                            int(reservation_after.st_mtime_ns),
                        )
                    ):
                        return None
                    continue
                if tombstone_match is not None:
                    if (
                        allowed_reservation is not None
                        or not entry.is_dir(follow_symlinks=False)
                    ):
                        return None
                    tombstone_ref = tombstone_match.group(1)
                    if tombstone_ref in tombstone_refs:
                        return None
                    tombstone_refs.add(tombstone_ref)
                    continue
                if runtime_cleanup_match is not None:
                    runtime_cleanup_ref = runtime_cleanup_match.group(1)
                    if (
                        allowed_reservation is not None
                        or expected_resume_ref != runtime_cleanup_ref
                        or runtime_cleanup_ref
                        not in recoverable_runtime_cleanup_refs
                        or runtime_cleanup_ref in observed_runtime_cleanup_refs
                        or not entry.is_file(follow_symlinks=False)
                    ):
                        return None
                    observed_runtime_cleanup_refs.add(runtime_cleanup_ref)
                    continue
                if proof_match is None:
                    return None
                transaction_ref = proof_match.group(1)
                proof_path = Path(entry.path)
                proof_raw, proof_info = (
                    project_update_transaction
                    ._read_cleanup_linked_regular(
                        project_root,
                        proof_path,
                        maximum=(
                            project_update_transaction.MAX_DOCUMENT_BYTES
                        ),
                    )
                )
                if int(proof_info.st_nlink) != 1:
                    return None
                proof = project_update_transaction._parse_document(
                    proof_raw,
                    code="project_update_transaction_cleanup_refused",
                )
                authority = (
                    proof.get("cleanup_authority_sha256")
                    if type(proof) is dict
                    else None
                )
                if (
                    not isinstance(authority, str)
                    or re.fullmatch(r"sha256:[0-9a-f]{64}", authority)
                    is None
                    or project_update_transaction._document_bytes(proof)
                    != proof_raw
                ):
                    return None
                project_update_transaction.ProjectUpdateTransaction._validate_cleanup_plan_document(
                    proof,
                    transaction_ref,
                    authority,
                )
                if os.path.lexists(
                    transaction_root / transaction_ref
                ) or os.path.lexists(
                    transaction_root / f".cleanup_{transaction_ref}"
                ):
                    return None
                proof_count += 1
        if (
            expected_reservation_ref is not None
            and not allowed_reservation_seen
        ):
            return None
        if (
            allowed_reservation is None
            and expected_resume_ref is not None
            and not resumable_transaction_seen
        ):
            return None
        if (
            observed_runtime_cleanup_refs
            != recoverable_runtime_cleanup_refs
            or runtime_cleanup_inventory
            != project_runtime.runtime_candidate_cleanup_sidecar_inventory(
                project_root
            )
        ):
            return None
        after = os.lstat(transaction_root)
        if (
            (int(before.st_dev), int(before.st_ino))
            != (int(after.st_dev), int(after.st_ino))
            or int(before.st_mtime_ns) != int(after.st_mtime_ns)
        ):
            return None
        abort_cleanup_states: tuple[
            project_update_transaction.ReservationAbortCleanupInspection,
            ...,
        ] = ()
        if allowed_reservation is None and (
            abort_original_refs or tombstone_refs
        ):
            abort_cleanup_states = (
                project_update_transaction
                .discover_exact_reservation_abort_cleanup_read_only(
                    project_root
                )
            )
        discovered_abort_original_refs = {
            item.transaction_ref
            for item in abort_cleanup_states
            if item.state in {"terminal_original", "planned_original"}
        }
        discovered_abort_tombstone_refs = {
            item.transaction_ref
            for item in abort_cleanup_states
            if item.state == "cleanup_tombstone"
        }
        if discovered_abort_original_refs != abort_original_refs:
            return None
        if not discovered_abort_tombstone_refs.issubset(tombstone_refs):
            return None
        normal_tombstone_refs = tombstone_refs - discovered_abort_tombstone_refs
        if len(normal_tombstone_refs) > 1:
            return None
        exact_abort_history_count = len(abort_cleanup_states)
        if normal_tombstone_refs:
            if terminal_original_seen:
                # Two terminal transactions each needing cleanup is not one
                # exact recoverable shape.  Preserve both and fail closed.
                return None
            recoverable_tombstone_ref = next(iter(normal_tombstone_refs))
            tombstone = (
                project_update_transaction.ProjectUpdateTransaction
                .discover_complete_cleanup_tombstone_for_resume_read_only(
                    project_root
                )
            )
            if (
                tombstone is None
                or tombstone.transaction_ref
                != recoverable_tombstone_ref
            ):
                return None
            return (
                "recoverable_exact",
                proof_count + exact_abort_history_count + 1,
            )
        if allowed_reservation is not None:
            if exact_abort_history_count:
                return None
            return "reservation_exact", proof_count
        if terminal_original_seen:
            # v0.4.18: one exact completed original without handoff authority.
            # Identifier-free resume finishes its private control cleanup
            # after re-authenticating the journal's approval reference.
            return (
                "terminal_original_exact",
                proof_count + exact_abort_history_count + 1,
            )
        if resumable_transaction_seen:
            return (
                "resume_required_exact",
                proof_count + exact_abort_history_count + 1,
            )
        if exact_abort_history_count:
            return (
                "terminal_history_exact",
                proof_count + exact_abort_history_count,
            )
        if proof_count:
            return "history_only_exact", proof_count
        return "absent", 0
    except (
        OSError,
        KeyError,
        TypeError,
        ValueError,
        project_update_transaction.ProjectUpdateTransactionError,
    ):
        return None


def _project_update_terminal_cleanup_artifact_classification_read_only(
    project_root: Path,
    *,
    allowed_reservation: (
        project_update_transaction.ReservedProjectUpdateTransaction | None
    ) = None,
    allowed_lock_bytes: bytes | None = None,
) -> tuple[str, int]:
    """Classify cleanup namespace without granting cleanup or write authority."""

    classification = (
        _project_update_terminal_cleanup_namespace_classification_read_only(
        project_root,
        allowed_reservation=allowed_reservation,
        allowed_lock_bytes=allowed_lock_bytes,
        )
    )
    if classification is None:
        return "unresolved", 0
    return classification


def _project_update_fresh_update_cleanup_preflight_read_only(
    inspection_root: Path | str,
) -> dict[str, Any] | None:
    """Give dry-run and approve the same privacy-safe cleanup decision."""

    project_root = _project_update_resume_project_root_read_only(
        inspection_root
    )
    handoff_observation: list[
        _ProjectUpdateTerminalHandoffObservation | None
    ] = []
    try:
        handoff_state = _project_update_terminal_handoff_state_read_only(
            inspection_root,
            _observation_out=handoff_observation,
        )
    except ArchiveServiceError as failure:
        if _project_update_exact_terminal_handoff_invalid_failure(failure):
            return _project_update_terminal_cleanup_outcome_unknown_result(
                operator_resume_identifiers_supplied=False,
                archive_identity_metadata_read=False,
            )
        raise
    if len(handoff_observation) != 1:
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    classification, exact_history_count = (
        _project_update_terminal_cleanup_artifact_classification_read_only(
            project_root
        )
    )
    if classification == "unresolved":
        return _project_update_terminal_cleanup_outcome_unknown_result(
            operator_resume_identifiers_supplied=False,
            archive_identity_metadata_read=False,
        )
    if handoff_state is not None:
        observation = handoff_observation[0]
        if observation is None:
            return _project_update_terminal_cleanup_outcome_unknown_result(
                operator_resume_identifiers_supplied=False,
                archive_identity_metadata_read=False,
            )
        try:
            active_ref = (
                project_update_transaction
                .active_transaction_ref_for_resume_read_only(project_root)
            )
        except project_update_transaction.ProjectUpdateTransactionError as failure:
            if failure.code == "project_update_transaction_not_found":
                active_ref = None
            else:
                return _project_update_terminal_cleanup_outcome_unknown_result(
                    operator_resume_identifiers_supplied=False,
                    archive_identity_metadata_read=False,
                )
        active_handoff_ref_matches = bool(
            active_ref is not None
            and observation.transaction_ref is not None
            and hmac.compare_digest(
                observation.transaction_ref,
                active_ref,
            )
        )
        tombstone_handoff_ref_matches = False
        if classification == "recoverable_exact":
            try:
                tombstone = (
                    project_update_transaction.ProjectUpdateTransaction
                    .discover_complete_cleanup_tombstone_for_resume_read_only(
                        project_root
                    )
                )
            except project_update_transaction.ProjectUpdateTransactionError:
                tombstone = None
            if (
                tombstone is None
                or observation.transaction_ref is None
                or not hmac.compare_digest(
                    observation.transaction_ref,
                    tombstone.transaction_ref,
                )
            ):
                return _project_update_terminal_cleanup_outcome_unknown_result(
                    operator_resume_identifiers_supplied=False,
                    archive_identity_metadata_read=False,
                )
            tombstone_handoff_ref_matches = True
        handoff_ref_matches = bool(
            active_handoff_ref_matches
            or (
                active_ref is None
                and tombstone_handoff_ref_matches
            )
        )
        if (
            handoff_state == "claim_succeeded_pre_unlock"
            and not handoff_ref_matches
        ) or (
            handoff_state == "terminal_ready"
            and active_ref is not None
            and not active_handoff_ref_matches
        ):
            return _project_update_terminal_cleanup_outcome_unknown_result(
                operator_resume_identifiers_supplied=False,
                archive_identity_metadata_read=False,
            )
        return _project_update_terminal_handoff_recovery_required_result()
    if classification in {"absent", "history_only_exact"}:
        return None
    if classification == "terminal_original_exact":
        return _project_update_terminal_transaction_cleanup_required_result(
            exact_history_count=exact_history_count,
        )
    if classification in {
        "recoverable_exact",
        "resume_required_exact",
        "terminal_history_exact",
    }:
        return _project_update_terminal_cleanup_required_result(
            exact_history_count=exact_history_count,
            resumable_transaction_present=classification
            in {"recoverable_exact", "resume_required_exact"},
        )
    return _project_update_terminal_cleanup_outcome_unknown_result(
        operator_resume_identifiers_supplied=False,
        archive_identity_metadata_read=False,
    )


@dataclass(frozen=True)
class _ProjectUpdateAbortHistoryCompactionOutcome:
    """Privacy-safe truth about one bounded abort-history compaction pass."""

    discovered_count: int
    attempted_count: int
    completed_count: int
    cleanup_proof_count: int
    incomplete: bool


def _project_update_compact_exact_abort_histories_for_resume(
    project_root: Path,
) -> _ProjectUpdateAbortHistoryCompactionOutcome:
    """Compact only machine-verified pre-intent abort histories.

    A terminal abort receipt is the cleanup authority for a newly discovered
    five-file history. If a previous cleanup invocation already persisted its
    plan or tombstone, that exact persisted authority is reused. An
    incomplete outcome means the caller must preserve all remaining
    evidence and report cleanup outcome unknown.  The structured return keeps
    already completed proof publication visible without disclosing refs,
    paths, or authorities and never authorizes a best-effort deletion.
    """

    discovered_count = 0
    attempted_count = 0
    completed = 0
    try:
        inspections = (
            project_update_transaction
            .discover_exact_reservation_abort_cleanup_read_only(project_root)
        )
        discovered_count = len(inspections)
        for inspection in inspections:
            authority = inspection.cleanup_authority_sha256
            if authority is None:
                reservation = (
                    project_update_transaction
                    .ReservedProjectUpdateTransaction.open(
                        project_root,
                        inspection.transaction_ref,
                    )
                )
                terminal = reservation.inspect_abort_receipt()
                authority = (
                    terminal.get("receipt_sha256")
                    if isinstance(terminal, Mapping)
                    else None
                )
            if (
                type(authority) is not str
                or re.fullmatch(r"sha256:[0-9a-f]{64}", authority) is None
            ):
                return _ProjectUpdateAbortHistoryCompactionOutcome(
                    discovered_count=discovered_count,
                    attempted_count=attempted_count,
                    completed_count=completed,
                    cleanup_proof_count=completed,
                    incomplete=True,
                )
            attempted_count += 1
            if not (
                project_update_transaction
                .compact_exact_reservation_abort_history(
                    project_root,
                    inspection.transaction_ref,
                    cleanup_authority_sha256=authority,
                )
            ):
                return _ProjectUpdateAbortHistoryCompactionOutcome(
                    discovered_count=discovered_count,
                    attempted_count=attempted_count,
                    completed_count=completed,
                    cleanup_proof_count=completed,
                    incomplete=True,
                )
            completed += 1
        if (
            project_update_transaction
            .discover_exact_reservation_abort_cleanup_read_only(project_root)
        ):
            return _ProjectUpdateAbortHistoryCompactionOutcome(
                discovered_count=discovered_count,
                attempted_count=attempted_count,
                completed_count=completed,
                cleanup_proof_count=completed,
                incomplete=True,
            )
        return _ProjectUpdateAbortHistoryCompactionOutcome(
            discovered_count=discovered_count,
            attempted_count=attempted_count,
            completed_count=completed,
            cleanup_proof_count=completed,
            incomplete=False,
        )
    except (
        OSError,
        KeyError,
        TypeError,
        ValueError,
        project_update_transaction.ProjectUpdateTransactionError,
    ):
        return _ProjectUpdateAbortHistoryCompactionOutcome(
            discovered_count=discovered_count,
            attempted_count=attempted_count,
            completed_count=completed,
            cleanup_proof_count=completed,
            incomplete=True,
        )


def _project_update_attach_abort_history_compaction_effect(
    result: Mapping[str, Any],
    outcome: _ProjectUpdateAbortHistoryCompactionOutcome,
) -> dict[str, Any]:
    """Attach exact private-control effects without widening public paths.

    ``files_written`` remains the project-domain-only compatibility list.  A
    caller can therefore see that private control evidence changed while no
    private path, transaction ref, or cleanup authority is reflected.
    """

    if not isinstance(result, Mapping) or not isinstance(
        outcome,
        _ProjectUpdateAbortHistoryCompactionOutcome,
    ):
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    if (
        outcome.discovered_count < 0
        or outcome.attempted_count < 0
        or outcome.completed_count < 0
        or outcome.cleanup_proof_count < 0
        or outcome.completed_count > outcome.attempted_count
        or outcome.cleanup_proof_count != outcome.completed_count
        or outcome.attempted_count > outcome.discovered_count
    ):
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    attached = dict(result)
    domain_files = attached.get("files_written")
    if type(domain_files) is not list:
        domain_files = attached.get("project_domain_files_written")
    public_domain_files = (
        list(domain_files) if type(domain_files) is list else []
    )
    existing_summary = attached.get("effect_summary")
    summary = (
        dict(existing_summary)
        if isinstance(existing_summary, Mapping)
        else {}
    )
    project_domain_writes_performed = bool(
        summary.get("project_domain_writes_performed") is True
        or public_domain_files
        or attached.get("domain_writer_entered") is True
    )
    summary.update(
        {
            "project_domain_writes_performed": (
                project_domain_writes_performed
            ),
            "project_domain_files_written": public_domain_files,
            "durable_control_evidence_written_or_verified": bool(
                outcome.cleanup_proof_count
            ),
            "private_control_mutation_performed_or_verified": bool(
                outcome.completed_count
            ),
            "private_control_mutation_may_be_incomplete": bool(
                outcome.incomplete
                and outcome.attempted_count > outcome.completed_count
            ),
            "terminal_abort_history_compaction_performed_or_verified": bool(
                outcome.completed_count
            ),
            "terminal_abort_history_cleanup_incomplete": bool(
                outcome.incomplete
            ),
            "paths_or_identifiers_disclosed": False,
        }
    )
    attached.update(
        {
            "terminal_abort_histories_compacted": outcome.completed_count,
            "cleanup_proofs_written_or_verified": (
                outcome.cleanup_proof_count
            ),
            "terminal_abort_history_compaction_state": (
                "partial"
                if outcome.incomplete and outcome.completed_count
                else "incomplete"
                if outcome.incomplete
                else "complete"
            ),
            "terminal_abort_history_compaction_incomplete": bool(
                outcome.incomplete
            ),
            "files_written_scope": "project_domain_only",
            "effect_summary": summary,
        }
    )
    return attached


def _project_update_abort_history_compacted_result(
    *,
    compacted_count: int,
) -> dict[str, Any]:
    """Report an exact private-control cleanup with zero project-domain write."""

    if (
        type(compacted_count) is not int
        or compacted_count < 1
        or compacted_count
        > project_update_transaction.MAX_TERMINAL_CLEANUP_SCAN_ENTRIES
    ):
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    return {
        "ok": True,
        "status": "terminal_history_compacted",
        "update_completed": False,
        "fresh_approval_required": True,
        "native_approval_redisplayed": False,
        "automatic_resume_discovery": True,
        "operator_resume_identifiers_supplied": False,
        "terminal_abort_histories_compacted": compacted_count,
        "cleanup_proofs_written_or_verified": compacted_count,
        "project_domain_effects": "none",
        "domain_writer_entered": False,
        "project_domain_files_written": [],
        "files_written_scope": "project_domain_only",
        "files_written": [],
        "effect_summary": {
            "project_domain_writes_performed": False,
            "project_domain_files_written": [],
            "durable_control_evidence_written_or_verified": True,
            "terminal_abort_history_compaction_performed_or_verified": True,
            "paths_or_identifiers_disclosed": False,
        },
        "privacy_guards": {
            "private_paths_echoed": False,
            "private_identifiers_echoed": False,
            "private_hashes_echoed": False,
        },
        "next_safe_actions": [
            "Run a fresh project-version-update preview, then request one new exact approval."
        ],
    }


def _project_update_terminal_cleanup_unknown_gate_read_only(
    inspection_root: Path | str,
    *,
    operator_resume_identifiers_supplied: bool,
    archive_identity_metadata_read: bool = False,
    exact_terminal_delivery_observed: bool = False,
    _handoff_observation_out: (
        list[_ProjectUpdateTerminalHandoffObservation | None] | None
    ) = None,
) -> dict[str, Any] | None:
    """Separate ordinary not-found from untrusted cleanup-shaped residue."""

    if (
        type(archive_identity_metadata_read) is not bool
        or type(exact_terminal_delivery_observed) is not bool
        or (
            _handoff_observation_out is not None
            and (
                type(_handoff_observation_out) is not list
                or _handoff_observation_out
            )
        )
    ):
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )

    project_root = _project_update_resume_project_root_read_only(
        inspection_root
    )
    observed_handoff: list[
        _ProjectUpdateTerminalHandoffObservation | None
    ] = []
    try:
        handoff_state = _project_update_terminal_handoff_state_read_only(
            inspection_root,
            _observation_out=observed_handoff,
        )
    except ArchiveServiceError as failure:
        if _project_update_exact_terminal_handoff_invalid_failure(failure):
            return _project_update_terminal_cleanup_outcome_unknown_result(
                operator_resume_identifiers_supplied=(
                    operator_resume_identifiers_supplied
                ),
                archive_identity_metadata_read=(
                    archive_identity_metadata_read
                ),
            )
        raise
    if len(observed_handoff) != 1:
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    handoff_observation = observed_handoff[0]
    if _handoff_observation_out is not None:
        _handoff_observation_out.append(handoff_observation)
    for attempt in range(2):
        regular_scan_incomplete = False
        active_transaction_observed = False
        active_transaction_ref: str | None = None
        try:
            active_transaction_ref = (
                project_update_transaction
                .active_transaction_ref_for_resume_read_only(project_root)
            )
            active_transaction_observed = True
        except project_update_transaction.ProjectUpdateTransactionError as failure:
            if failure.code == "project_update_transaction_not_found":
                active_transaction_observed = False
            else:
                # A malformed live lock, ambiguous lockless locator, unsafe
                # entry, or bounded-scan failure is cleanup outcome unknown.
                # None of these read-only failures may fall through to a
                # generic CLI error or authorize a writer.
                regular_scan_incomplete = True
        try:
            cleanup_state = (
                project_update_transaction
                .inspect_terminal_cleanup_artifacts_for_resume_read_only(
                    project_root
                )
            )
        except project_update_transaction.ProjectUpdateTransactionError:
            return _project_update_terminal_cleanup_outcome_unknown_result(
                operator_resume_identifiers_supplied=(
                    operator_resume_identifiers_supplied
                ),
                archive_identity_metadata_read=(
                    archive_identity_metadata_read
                ),
            )
        if (
            cleanup_state == "active_lock_changed"
            and not active_transaction_observed
            and attempt == 0
        ):
            continue
        cleanup_classification, history_only_count = (
            _project_update_terminal_cleanup_artifact_classification_read_only(
                project_root
            )
            if not regular_scan_incomplete
            else ("unresolved", 0)
        )
        if handoff_observation is not None:
            active_handoff_ref_matches = bool(
                active_transaction_ref is not None
                and handoff_observation.transaction_ref is not None
                and hmac.compare_digest(
                    handoff_observation.transaction_ref,
                    active_transaction_ref,
                )
            )
            tombstone_handoff_ref_matches = False
            if cleanup_classification == "recoverable_exact":
                try:
                    tombstone = (
                        project_update_transaction.ProjectUpdateTransaction
                        .discover_complete_cleanup_tombstone_for_resume_read_only(
                            project_root
                        )
                    )
                except project_update_transaction.ProjectUpdateTransactionError:
                    tombstone = None
                if (
                    tombstone is None
                    or handoff_observation.transaction_ref is None
                    or not hmac.compare_digest(
                        handoff_observation.transaction_ref,
                        tombstone.transaction_ref,
                    )
                ):
                    return _project_update_terminal_cleanup_outcome_unknown_result(
                        operator_resume_identifiers_supplied=(
                            operator_resume_identifiers_supplied
                        ),
                        archive_identity_metadata_read=(
                            archive_identity_metadata_read
                        ),
                    )
                tombstone_handoff_ref_matches = True
            handoff_ref_matches = bool(
                active_handoff_ref_matches
                or (
                    active_transaction_ref is None
                    and tombstone_handoff_ref_matches
                )
            )
            if (
                handoff_observation.state
                == "claim_succeeded_pre_unlock"
                and not handoff_ref_matches
            ) or (
                handoff_observation.state == "terminal_ready"
                and active_transaction_ref is not None
                and not active_handoff_ref_matches
            ):
                return _project_update_terminal_cleanup_outcome_unknown_result(
                    operator_resume_identifiers_supplied=(
                        operator_resume_identifiers_supplied
                    ),
                    archive_identity_metadata_read=(
                        archive_identity_metadata_read
                    ),
                )
        if cleanup_classification == "history_only_exact":
            if handoff_state is not None or exact_terminal_delivery_observed:
                return None
            return _project_update_history_only_cleanup_result(
                operator_resume_identifiers_supplied=(
                    operator_resume_identifiers_supplied
                ),
                proof_count=history_only_count,
            )
        if cleanup_classification in {
            "recoverable_exact",
            "resume_required_exact",
            "terminal_history_exact",
            "terminal_original_exact",
        }:
            # Restoration/compaction is allowed only after the archive identity
            # boundary opens in the live resume service. This read-only gate
            # merely routes an exact state there; it grants no success or
            # project-domain write authority itself.
            return None
        if (
            regular_scan_incomplete
            or cleanup_state == "observed_or_scan_incomplete"
            or cleanup_classification == "unresolved"
            or (
                active_transaction_observed
                and cleanup_classification == "absent"
            )
        ):
            return _project_update_terminal_cleanup_outcome_unknown_result(
                operator_resume_identifiers_supplied=(
                    operator_resume_identifiers_supplied
                ),
                archive_identity_metadata_read=(
                    archive_identity_metadata_read
                ),
            )
        if cleanup_classification != "absent":
            raise ArchiveServiceError(
                "project_version_update_resume_locator_changed"
            )
        if handoff_state is not None or exact_terminal_delivery_observed:
            return None
        raise project_update_transaction.ProjectUpdateTransactionError(
            "project_update_transaction_not_found"
        )
    raise ArchiveServiceError(
        "project_version_update_resume_locator_changed"
    )


@dataclass(frozen=True)
class _ProjectUpdateTerminalHandoffObservation:
    """Private continuity token for one exact active terminal document."""

    state: str
    raw_sha256: str
    pending_record_sha256: str | None
    transaction_ref: str | None


def _project_update_exact_terminal_handoff_invalid_failure(
    failure: BaseException,
) -> bool:
    """Recognize only the one fixed, argument-free public safety sentinel."""

    return bool(
        type(failure) is ArchiveServiceError
        and len(failure.args) == 1
        and type(failure.args[0]) is str
        and failure.args[0]
        == "project_version_update_terminal_handoff_invalid"
    )


def _project_update_terminal_handoff_state_read_only(
    inspection_root: Path | str,
    *,
    _observation_out: (
        list[_ProjectUpdateTerminalHandoffObservation | None] | None
    ) = None,
) -> str | None:
    if _observation_out is not None and (
        type(_observation_out) is not list or _observation_out
    ):
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    project_root = _project_update_resume_project_root_read_only(
        inspection_root
    )
    handoff, _guard = _project_update_terminal_handoff_paths(
        project_root
    )
    observed = _project_update_read_terminal_document(project_root, handoff)
    if observed is None:
        if _observation_out is not None:
            _observation_out.append(None)
        return None
    value, raw = observed
    state = value.get("state")
    if state == "terminal_ready_unapproved":
        payload = value.get("payload")
        authentication = value.get("authentication")
        if (
            value.get("schema")
            != _PROJECT_UPDATE_CANCELLATION_TERMINAL_HANDOFF_SCHEMA
            or set(value)
            != {"authentication", "payload", "schema", "state"}
            or not isinstance(payload, Mapping)
            or payload.get("schema")
            != _PROJECT_UPDATE_CANCELLATION_TERMINAL_PAYLOAD_SCHEMA
            or payload.get("outcome") != "unapproved_restored"
            or not isinstance(authentication, Mapping)
            or set(authentication) != {"algorithm", "mac"}
            or authentication.get("algorithm") != "hmac-sha256"
            or re.fullmatch(
                r"hmac-sha256:[0-9a-f]{64}",
                str(authentication.get("mac") or ""),
            )
            is None
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        if _observation_out is not None:
            _observation_out.append(
                _ProjectUpdateTerminalHandoffObservation(
                    state="terminal_ready_unapproved",
                    raw_sha256=(
                        project_update_transaction.sha256_bytes(raw)
                    ),
                    pending_record_sha256=(
                        project_update_transaction.sha256_document(
                            dict(payload)
                        )
                    ),
                    transaction_ref=None,
                )
            )
        return "terminal_ready_unapproved"
    expected_keys = (
        {"schema", "state", "pending"}
        if state == "claim_succeeded_pre_unlock"
        else {"schema", "state", "pending", "ready"}
        if state == "terminal_ready"
        else set()
    )
    if (
        value.get("schema") != _PROJECT_UPDATE_TERMINAL_HANDOFF_SCHEMA
        or set(value) != expected_keys
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    pending = value.get("pending")
    pending_payload = (
        pending.get("payload") if type(pending) is dict else None
    )
    transaction_ref = (
        pending_payload.get("transaction_ref")
        if type(pending_payload) is dict
        and type(pending_payload.get("transaction_ref")) is str
        and project_update_transaction.TRANSACTION_REF_RE.fullmatch(
            pending_payload["transaction_ref"]
        )
        is not None
        else None
    )
    if _observation_out is not None:
        _observation_out.append(
            _ProjectUpdateTerminalHandoffObservation(
                state=str(state),
                raw_sha256=project_update_transaction.sha256_bytes(raw),
                pending_record_sha256=(
                    project_update_transaction.sha256_document(pending)
                    if type(pending) is dict
                    else None
                ),
                transaction_ref=transaction_ref,
            )
        )
    return str(state)


@contextmanager
def _project_update_terminal_execution_lease(
    state: _ProjectVersionUpdateDurableApprovalState,
    *,
    expected_handoff_observation: (
        _ProjectUpdateTerminalHandoffObservation | None
    ),
    fresh_absence: bool,
) -> Iterator[None]:
    """Bind the terminal namespace from native approval through publication.

    The project update transaction and its project lock already exist when
    this boundary is entered.  Fresh approval expects no active handoff;
    mutation-bearing resume may instead bind the exact pre-unlock handoff it
    observed during the strict read-only gate.  The same non-reentrant OS
    guard remains owned while nested terminal reads and CAS publications reuse
    the ContextVar-bound parent/guard handles.
    """

    if type(fresh_absence) is not bool or (
        expected_handoff_observation is not None
        and expected_handoff_observation.state
        != "claim_succeeded_pre_unlock"
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_execution_boundary_unknown"
        )
    try:
        with _project_update_terminal_control_boundary(state.project_root):
            observed: list[
                _ProjectUpdateTerminalHandoffObservation | None
            ] = []
            try:
                _project_update_terminal_handoff_state_read_only(
                    state.inspection_root,
                    _observation_out=observed,
                )
            except ArchiveServiceError as failure:
                if _project_update_exact_terminal_handoff_invalid_failure(
                    failure
                ):
                    raise ArchiveServiceError(
                        "project_version_update_terminal_execution_boundary_unknown"
                    ) from None
                raise
            if len(observed) != 1:
                raise ArchiveServiceError(
                    "project_version_update_terminal_execution_boundary_unknown"
                )
            current = observed[0]
            if expected_handoff_observation is None:
                if current is not None:
                    raise ArchiveServiceError(
                        "project_version_update_terminal_execution_boundary_unknown"
                    )
            elif (
                current != expected_handoff_observation
                or current.transaction_ref
                != state.transaction.transaction_ref
            ):
                raise ArchiveServiceError(
                    "project_version_update_terminal_execution_boundary_unknown"
                )
            if getattr(state, "legacy_prewrite_recovery_control", None) is not None:
                if not _project_update_legacy_recovery_execution_state_exact(
                    state
                ):
                    raise ArchiveServiceError(
                        "project_version_update_terminal_execution_boundary_unknown"
                    )
            else:
                cleanup_result = (
                    _project_update_terminal_cleanup_unknown_gate_read_only(
                        state.inspection_root,
                        operator_resume_identifiers_supplied=False,
                        archive_identity_metadata_read=True,
                    )
                )
                if cleanup_result is not None:
                    raise ArchiveServiceError(
                        "project_version_update_terminal_execution_boundary_unknown"
                    )
            execution_token = (
                _PROJECT_UPDATE_TERMINAL_EXECUTION_LEASE.set(
                    (id(state), state.transaction.transaction_ref)
                )
            )
            try:
                yield
            finally:
                _PROJECT_UPDATE_TERMINAL_EXECUTION_LEASE.reset(
                    execution_token
                )
    except ArchiveServiceError:
        raise
    except (
        OSError,
        project_update_transaction.ProjectUpdateTransactionError,
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_execution_boundary_unknown"
        ) from None


def _project_update_legacy_recovery_preapproval_state_exact(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> bool:
    """Verify the only intentional terminal-cleanup exception.

    A legacy recovery deliberately has two control trees while its fresh
    composite approval is pending: the immutable predecessor is in the
    authenticated vault and the current-schema transaction is sealed at its
    canonical ref.  The ordinary cleanup gate quite correctly classifies that
    shape as nonterminal residue, so this narrow branch binds every component
    before the approval executor may publish a fresh claim.
    """

    control = getattr(state, "legacy_prewrite_recovery_control", None)
    if not isinstance(control, dict):
        return False
    paths = control.get("paths")
    old_ref = control.get("old_transaction_ref")
    old_tree_sha256 = control.get("old_transaction_tree_sha256")
    old_lock_bytes = control.get("old_lock_bytes")
    fresh_inventory = control.get("fresh_transaction_inventory")
    fresh_inventory_document_sha256 = control.get(
        "fresh_transaction_inventory_document_sha256"
    )
    intent_sha256 = control.get("intent_sha256")
    journal_head_sha256 = control.get("journal_head_sha256")
    locator_sha256 = control.get("locator_sha256")
    with_store = control.get("with_store")
    progress_callback = control.get("progress_callback")
    lock_handoff_state = control.get("lock_handoff_state")
    if (
        not isinstance(paths, project_update_legacy_recovery.RecoveryPaths)
        or type(old_ref) is not str
        or project_update_transaction.TRANSACTION_REF_RE.fullmatch(old_ref)
        is None
        or type(old_tree_sha256) is not str
        or type(old_lock_bytes) is not bytes
        or not isinstance(fresh_inventory, Mapping)
        or type(fresh_inventory_document_sha256) is not str
        or type(intent_sha256) is not str
        or type(journal_head_sha256) is not str
        or type(locator_sha256) is not str
        or not callable(with_store)
        or (progress_callback is not None and not callable(progress_callback))
    ):
        return False

    def report(count: int, byte_count: int) -> None:
        if progress_callback is not None:
            try:
                progress_callback(
                    "project-recovery-inventory",
                    "running",
                    count,
                    byte_count,
                )
            except Exception:
                pass

    old_canonical = paths.project_root.joinpath(
        *PurePosixPath(
            project_update_legacy_recovery.TRANSACTION_ROOT_LOGICAL
        ).parts,
        old_ref,
    )
    try:
        if os.path.lexists(old_canonical):
            return False
        if not hmac.compare_digest(
            project_update_legacy_recovery._read_regular(
                state.transaction._lock_path
            ),
            old_lock_bytes,
        ):
            return False
        if not hmac.compare_digest(
            project_update_legacy_recovery.directory_tree_sha256(
                paths.old_transaction_vault,
                progress_callback=report,
            ),
            old_tree_sha256,
        ):
            return False
        if not hmac.compare_digest(
            project_update_legacy_recovery.directory_tree_sha256(
                state.transaction.transaction_root,
                progress_callback=report,
            ),
            project_update_legacy_recovery.sha256_document(
                fresh_inventory
            ),
        ):
            return False
        locator_raw = project_update_legacy_recovery._read_regular(
            paths.locator_path
        )
        if not hmac.compare_digest(
            project_update_legacy_recovery.sha256_bytes(locator_raw),
            locator_sha256,
        ):
            return False
        locator = with_store(lambda store: store.read_locator())
        return bool(
            isinstance(locator, Mapping)
            and locator.get("state") == "fresh_plan_sealed"
            and locator.get("intent_sha256") == intent_sha256
            and locator.get("journal_head_sha256")
            == journal_head_sha256
        )
    except BaseException:
        return False


def _project_update_legacy_recovery_execution_state_exact(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> bool:
    """Bind the exact recovery shape appropriate to the fresh tx phase.

    Claim publication deliberately continues to use the narrower preapproval
    predicate above.  The terminal execution lease, however, remains held
    while the fresh lock is installed, components are written, the lock is
    released, and the completed transaction is terminalized.  Requiring the
    old-lock/preapproval shape throughout that lifetime makes every legitimate
    post-activation resume fail closed.  This phase-aware predicate accepts
    only those exact, authenticated shapes and still requires the immutable
    predecessor vault at every stage.
    """

    control = getattr(state, "legacy_prewrite_recovery_control", None)
    if not isinstance(control, dict):
        return False
    paths = control.get("paths")
    old_ref = control.get("old_transaction_ref")
    old_tree_sha256 = control.get("old_transaction_tree_sha256")
    old_lock_bytes = control.get("old_lock_bytes")
    fresh_inventory = control.get("fresh_transaction_inventory")
    intent_sha256 = control.get("intent_sha256")
    with_store = control.get("with_store")
    progress_callback = control.get("progress_callback")
    lock_handoff_state = control.get("lock_handoff_state")
    if (
        not isinstance(paths, project_update_legacy_recovery.RecoveryPaths)
        or type(old_ref) is not str
        or project_update_transaction.TRANSACTION_REF_RE.fullmatch(old_ref)
        is None
        or type(old_tree_sha256) is not str
        or type(old_lock_bytes) is not bytes
        or not isinstance(fresh_inventory, Mapping)
        or type(intent_sha256) is not str
        or not callable(with_store)
        or (progress_callback is not None and not callable(progress_callback))
    ):
        return False

    def report(count: int, byte_count: int) -> None:
        if progress_callback is not None:
            try:
                progress_callback(
                    "project-recovery-inventory",
                    "running",
                    count,
                    byte_count,
                )
            except Exception:
                pass

    old_canonical = paths.project_root.joinpath(
        *PurePosixPath(
            project_update_legacy_recovery.TRANSACTION_ROOT_LOGICAL
        ).parts,
        old_ref,
    )
    lock_path = state.transaction._lock_path
    public_old_backup = lock_path.parent / (
        ".legacy-recovery-"
        + paths.recovery_ref.removeprefix("recovery_")
        + ".old-lock"
    )
    vaulted_old_backup = paths.recovery_root / "old-lock-backup"
    try:
        if os.path.lexists(old_canonical):
            return False
        if not hmac.compare_digest(
            project_update_legacy_recovery.directory_tree_sha256(
                paths.old_transaction_vault,
                progress_callback=report,
            ),
            old_tree_sha256,
        ):
            return False
        locator = with_store(lambda store: store.read_locator())
        if (
            not isinstance(locator, Mapping)
            or locator.get("intent_sha256") != intent_sha256
        ):
            return False

        # A legacy fresh transaction is intentionally sealed before it owns
        # the public lock.  Until the atomic handoff, it therefore has no
        # reservation/sealed-lock backlink and the ordinary ``inspect()``
        # contract must reject it.  Prove that one special preapproval shape
        # from the authenticated recovery inventory instead.  Once any fresh
        # checkpoint exists, the regular transaction verifier below is again
        # the single source of truth.
        journal_path = state.transaction.transaction_root / "checkpoints.jsonl"
        if lock_handoff_state in {None, "old", "backup_linked"} and not (
            os.path.lexists(journal_path)
        ):
            return bool(
                locator.get("state") == "fresh_plan_sealed"
                and (
                    lock_handoff_state == "backup_linked"
                    or lock_handoff_state in {None, "old"}
                    and os.path.lexists(lock_path)
                    and hmac.compare_digest(
                        project_update_legacy_recovery._read_regular(
                            lock_path
                        ),
                        old_lock_bytes,
                    )
                )
                and project_update_legacy_recovery.directory_tree_matches_inventory(
                    state.transaction.transaction_root,
                    fresh_inventory,
                    retained_guard_logical="append.guard",
                )
            )

        inspection = state.transaction.inspect()
        if inspection.journal.state != "exact":
            return False
        checkpoints = tuple(inspection.journal.verified_prefix)
        if not checkpoints:
            return False

        if checkpoints[0].phase != "lock_backlinked":
            return False
        head_phase = checkpoints[-1].phase
        if head_phase in {"lock_released", "completed"}:
            if os.path.lexists(lock_path):
                return False
        elif (
            not os.path.lexists(lock_path)
            or not hmac.compare_digest(
                project_update_legacy_recovery._read_regular(lock_path),
                state.expected_lock_bytes,
            )
        ):
            return False

        exact_backup_count = 0
        for backup_path in (public_old_backup, vaulted_old_backup):
            if not os.path.lexists(backup_path):
                continue
            if not hmac.compare_digest(
                project_update_legacy_recovery._read_regular(backup_path),
                old_lock_bytes,
            ):
                return False
            exact_backup_count += 1
        if exact_backup_count != 1:
            return False
        return locator.get("state") in {
            "fresh_plan_sealed",
            "fresh_lock_backlinked",
            "fresh_transaction_completed",
            "terminal_completed",
        }
    except project_update_legacy_recovery.LegacyProjectUpdateRecoveryError as failure:
        raise ArchiveServiceError(failure.code) from None
    except BaseException:
        return False


def _project_update_terminal_handoff_attachments(
    pending_record: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], dict[str, str]]:
    payload = pending_record.get("payload")
    attachments = pending_record.get("attachments")
    if type(payload) is not dict or type(attachments) is not dict:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    preview = attachments.get("prepared_preview")
    result = attachments.get("domain_result")
    basis = attachments.get("recovery_basis")
    postimage = attachments.get("exact_postimage")
    if (
        type(preview) is not dict
        or type(result) is not dict
        or type(basis) is not dict
        or type(postimage) is not dict
        or any(type(key) is not str or type(value) is not str for key, value in postimage.items())
        or project_update_transaction.sha256_document(preview)
        != payload.get("prepared_preview_sha256")
        or project_update_transaction.sha256_document(result)
        != payload.get("domain_result_sha256")
        or len(project_update_transaction.canonical_json_bytes(result))
        != payload.get("domain_result_size_bytes")
        or project_update_transaction.sha256_document(basis)
        != payload.get("recovery_basis_sha256")
        or project_update_transaction.sha256_document(postimage)
        != payload.get("exact_postimage_sha256")
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    return preview, result, basis, postimage


def _project_update_terminal_postimage_matches(
    project_root: Path,
    basis: Mapping[str, Any],
    expected_postimage: Mapping[str, str],
) -> bool:
    if (
        basis.get("schema")
        != "wom-kit/project-version-update-terminal-recovery-basis/v0.4.16"
        or type(basis.get("components")) is not list
        or type(basis.get("runtime")) is not dict
    ):
        return False
    components = basis["components"]
    expected_components: dict[str, str] = {}
    regular_components: list[dict[str, Any]] = []
    for component in components:
        if (
            type(component) is not dict
            or set(component)
            != {"component_ref", "role", "logical_target", "post_sha256"}
            or type(component.get("component_ref")) is not str
            or type(component.get("role")) is not str
            or type(component.get("logical_target")) is not str
            or type(component.get("post_sha256")) is not str
            or component["component_ref"] in expected_components
        ):
            return False
        expected_components[component["component_ref"]] = component["post_sha256"]
        if component["role"] not in {"source", "runtime"}:
            regular_components.append(component)
    if expected_components != dict(expected_postimage):
        return False
    lock_path = project_root.joinpath(
        *PurePosixPath(
            project_update_transaction.PROJECT_UPDATE_LOCK_LOGICAL
        ).parts
    )
    if os.path.lexists(lock_path):
        return False
    mirror_logical = PurePosixPath(str(basis.get("mirror_logical") or ""))
    if mirror_logical.is_absolute() or ".." in mirror_logical.parts:
        return False
    mirror_path = project_root.joinpath(*mirror_logical.parts)
    runner: project_update_git_runner.TrustedProjectUpdateGitRunner | None = None
    verified = False
    try:
        runner_bytes = _project_update_private_json_restore(
            basis.get("git_runner_binding")
        )
        if not isinstance(runner_bytes, bytes):
            return False
        runner_binding = project_update_git_runner.load_private_binding_bytes(
            runner_bytes
        )
        runner = (
            project_update_git_runner.TrustedProjectUpdateGitRunner
            .reopen_private(runner_binding)
        )
        runner.close_transport_boundary()
        snapshot = _wom_kit_project_update_git_snapshot(
            mirror_path,
            runner=runner,
        )
        target_commit = str(basis.get("target_commit") or "")
        target_tag = str(basis.get("target_tag") or "")
        target_version = str(basis.get("target_version") or "")
        source_exact = bool(
            wom_kit_project_update_snapshot_is_clean(
                snapshot,
                expected_head=target_commit,
                expected_branch=None,
            )
            and all(
                normalize_version_label(value) == target_version
                for value in wom_kit_project_update_source_versions(
                    mirror_path
                ).values()
            )
            and wom_kit_project_update_target_ref_snapshot(
                mirror_path,
                target_tag,
                runner=runner,
            )
            == basis.get("target_ref_snapshot")
            and wom_kit_runtime_tracked_python_integrity(
                project_root,
                mirror_path,
                runner=runner,
            ).get("tracked_python_sources_verified")
            is True
            and wom_kit_runtime_resource_integrity(
                project_root,
                mirror_path,
                ref=target_commit,
                runner=runner,
            ).get("runtime_resources_verified")
            is True
        )
        runtime_expected = basis["runtime"]
        runtime_observed = project_runtime.inspect_runtime(
            project_root,
            target_version,
            expected_commit=target_commit,
            expected_wheel_sha256=runtime_expected.get("wheel_sha256"),
            expected_supply_lock_sha256=runtime_expected.get(
                "supply_lock_sha256"
            ),
        )
        runtime_exact = bool(
            runtime_observed.get("receipt_candidate_valid") is True
            and runtime_observed.get("live_payload_aligned") is True
            and runtime_observed.get("installed_payload_sha256")
            == runtime_expected.get("installed_payload_sha256")
            and runtime_observed.get("receipt_sha256")
            == runtime_expected.get("receipt_sha256")
        )
        if not source_exact or not runtime_exact:
            return False
        for component in regular_components:
            logical = PurePosixPath(component["logical_target"])
            if logical.is_absolute() or ".." in logical.parts:
                return False
            path = project_root.joinpath(*logical.parts)
            maximum = (
                _PROJECT_UPDATE_RECEIPT_MAX_BYTES
                if component["role"] == "receipt"
                else 64 * 1024
            )
            observed = _project_update_safe_read_component(
                project_root,
                path,
                maximum=maximum,
            )
            if (
                observed
                in {
                    _PROJECT_UPDATE_UNSAFE_LIVE_COMPONENT,
                    _PROJECT_UPDATE_UNAVAILABLE_LIVE_COMPONENT,
                }
                or _project_update_raw_component_sha256(observed)
                != component["post_sha256"]
            ):
                return False
        verified = True
    except (
        ArchiveServiceError,
        OSError,
        RuntimeError,
        TypeError,
        ValueError,
        project_runtime.ProjectRuntimeError,
        project_update_git_runner.ProjectUpdateGitRunnerError,
    ):
        return False
    finally:
        if runner is not None:
            try:
                runner.close()
            except project_update_git_runner.ProjectUpdateGitRunnerError:
                verified = False
    return verified


def _project_update_replayed_terminal_finalization(
    *,
    cleanup_completed: bool,
) -> dict[str, Any]:
    """Project replay truth without inventing pre-crash close evidence."""

    return {
        "schema": "wom-kit/project-version-update-terminal-finalization/v0.1",
        "update_result_verified_in_current_invocation": False,
        "update_result_reauthenticated_from_durable_handoff": True,
        "claim_succeeded_verified": True,
        "transaction_completed_checkpoint_verified": True,
        "lock_absence_verified": True,
        "transaction_cleanup_completed": bool(cleanup_completed),
        "service_resource_close_verified": False,
        "git_runner_close_verified": False,
        "attention_required": True,
        "domain_writer_reentry_allowed": False,
        "automatic_retry_allowed": False,
        "cleanup_proof_used_as_success_authority": False,
        "durable_terminal_handoff_ready": True,
        "durable_terminal_handoff_replayed": True,
        "durable_result_delivery_acknowledged": False,
        "private_paths_echoed": False,
        "private_identifiers_echoed": False,
    }


def _project_update_replay_ready_terminal_handoff(
    inspection_root: Path | str,
    *,
    target: str | None,
    reviewed_by: str | None,
    transaction_ref: str | None,
    approval_executor: Callable[..., Mapping[str, Any]],
    expected_approval_root: Path,
    expected_archive_id: str,
    _expected_handoff_observation: (
        _ProjectUpdateTerminalHandoffObservation | None
    ) = None,
    _terminal_control_lease_held: bool = False,
    _legacy_recovery_terminalizer: (
        Callable[[_ClaimedExactHumanApproval], None] | None
    ) = None,
) -> dict[str, Any] | None:
    project_root = _project_update_resume_project_root_read_only(
        inspection_root
    )
    if (
        type(_terminal_control_lease_held) is not bool
        or (
            _legacy_recovery_terminalizer is not None
            and not callable(_legacy_recovery_terminalizer)
        )
        or _expected_handoff_observation is None
        or _expected_handoff_observation.state != "terminal_ready"
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    if not _terminal_control_lease_held:
        try:
            with _project_update_terminal_control_boundary(project_root):
                return _project_update_replay_ready_terminal_handoff(
                    inspection_root,
                    target=target,
                    reviewed_by=reviewed_by,
                    transaction_ref=transaction_ref,
                    approval_executor=approval_executor,
                    expected_approval_root=expected_approval_root,
                    expected_archive_id=expected_archive_id,
                    _expected_handoff_observation=(
                        _expected_handoff_observation
                    ),
                    _terminal_control_lease_held=True,
                    _legacy_recovery_terminalizer=(
                        _legacy_recovery_terminalizer
                    ),
                )
        except ArchiveServiceError:
            raise
        except OSError:
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            ) from None
    if _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.get() is None:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    handoff, _guard = _project_update_terminal_handoff_paths(
        project_root
    )
    observed = _project_update_read_terminal_document(project_root, handoff)
    if observed is None:
        return None
    active, active_bytes = observed
    if (
        active.get("schema") != _PROJECT_UPDATE_TERMINAL_HANDOFF_SCHEMA
        or active.get("state") != "terminal_ready"
        or set(active) != {"schema", "state", "pending", "ready"}
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    pending_record = active["pending"]
    ready_record = active["ready"]
    if _expected_handoff_observation is not None and (
        _expected_handoff_observation.state != "terminal_ready"
        or not hmac.compare_digest(
            _expected_handoff_observation.raw_sha256,
            project_update_transaction.sha256_bytes(active_bytes),
        )
        or _expected_handoff_observation.pending_record_sha256 is None
        or not hmac.compare_digest(
            _expected_handoff_observation.pending_record_sha256,
            project_update_transaction.sha256_document(pending_record),
        )
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    preview, domain_result, basis, postimage = (
        _project_update_terminal_handoff_attachments(pending_record)
    )
    pending_payload = pending_record.get("payload")
    ready_payload = (
        ready_record.get("payload")
        if isinstance(ready_record, dict)
        else None
    )
    if type(pending_payload) is not dict or type(ready_payload) is not dict:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    binding = project_version_update_approval_binding(preview)
    supplied_target = str(target or "").strip()
    supplied_reviewer = str(reviewed_by or "").strip()
    supplied_transaction = str(transaction_ref or "").strip()
    legacy_cleanup_authority = pending_payload.get(
        "legacy_cleanup_authority_sha256"
    )
    if (
        pending_payload.get("plan_sha256") != binding.plan_sha256
        or pending_payload.get("target_binding_sha256")
        != binding.target_binding_sha256
        or ready_payload.get("plan_sha256") != binding.plan_sha256
        or ready_payload.get("target_binding_sha256")
        != binding.target_binding_sha256
        or ready_payload.get("pending_record_sha256")
        != project_update_transaction.sha256_document(pending_record)
        or ready_payload.get("claim_succeeded_checkpoint_sha256")
        != pending_payload.get("claim_succeeded_checkpoint_sha256")
        or ready_payload.get("exact_postimage_sha256")
        != pending_payload.get("exact_postimage_sha256")
        or ready_payload.get("legacy_cleanup_authority_sha256")
        != legacy_cleanup_authority
        or (
            legacy_cleanup_authority is not None
            and re.fullmatch(
                r"sha256:[0-9a-f]{64}",
                str(legacy_cleanup_authority),
            )
            is None
        )
        or supplied_target
        and supplied_target != basis.get("target_tag")
        or supplied_reviewer
        and supplied_reviewer != pending_payload.get("reviewer")
        or supplied_transaction
        and supplied_transaction != pending_payload.get("transaction_ref")
        or not _wom_kit_project_version_update_approval_authority_matches(
            inspection_root,
            expected_root=expected_approval_root,
            expected_archive_id=expected_archive_id,
        )
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    verified = False
    replay_delivery_capability: str | None = None

    def started_guard(_claim: _ClaimedExactHumanApproval) -> bool:
        return False

    def succeeded_guard(claim: _ClaimedExactHumanApproval) -> bool:
        nonlocal verified, replay_delivery_capability
        candidate_capability = _project_update_terminal_delivery_capability(
            claim,
            pending_record,
        )
        claim_reference_sha256 = project_update_transaction.sha256_bytes(
            _project_update_canonical_bytes(claim.public_reference())
        )
        verified = bool(
            _project_update_terminal_record_matches_claim(
                pending_record,
                claim,
                expected_plan_sha256=binding.plan_sha256,
                expected_target_binding_sha256=(
                    binding.target_binding_sha256
                ),
            )
            and _project_update_terminal_record_matches_claim(
                ready_record,
                claim,
                expected_plan_sha256=binding.plan_sha256,
                expected_target_binding_sha256=(
                    binding.target_binding_sha256
                ),
            )
            and _project_update_terminal_postimage_matches(
                project_root,
                basis,
                postimage,
            )
            and hmac.compare_digest(
                project_update_transaction.sha256_bytes(
                    candidate_capability.encode("ascii")
                ),
                str(
                    ready_payload.get("delivery_capability_sha256") or ""
                ),
            )
            and (
                legacy_cleanup_authority is None
                or hmac.compare_digest(
                    legacy_cleanup_authority,
                    claim_reference_sha256,
                )
            )
        )
        if verified:
            replay_delivery_capability = candidate_capability
        return verified

    def started_writer(_claim: _ClaimedExactHumanApproval) -> Mapping[str, Any]:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )

    def finalizer(_claim: _ClaimedExactHumanApproval) -> None:
        if verified is not True:
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        if _legacy_recovery_terminalizer is not None:
            _legacy_recovery_terminalizer(_claim)

    approval_executor(
        copy.deepcopy(preview),
        started_writer,
        finalizer,
        started_guard,
        succeeded_guard,
        str(pending_payload["reviewer"]),
        candidate_missing_handler=None,
        **(
            {"resume_existing_composite": True}
            if _legacy_recovery_terminalizer is not None
            else {}
        ),
    )
    if verified is not True:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    if replay_delivery_capability is None:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    _project_update_register_terminal_delivery_capability(
        project_update_transaction.sha256_bytes(active_bytes),
        replay_delivery_capability,
    )
    handoff_sha256 = project_update_transaction.sha256_bytes(active_bytes)
    cleanup_authority_sha256 = (
        legacy_cleanup_authority or handoff_sha256
    )
    try:
        cleanup_completed = _project_update_resume_authenticated_terminal_cleanup(
            project_root,
            str(pending_payload["transaction_ref"]),
            cleanup_authority_sha256=cleanup_authority_sha256,
        )
    except project_update_transaction.ProjectUpdateTransactionError:
        cleanup_completed = False
    projected_domain = _project_update_privacy_safe_domain_result(
        domain_result
    )
    terminal = _project_update_replayed_terminal_finalization(
        cleanup_completed=bool(cleanup_completed),
    )
    projected = _project_update_terminal_result_from_domain(
        projected_domain,
        terminal,
    )
    if projected is None:
        raise ArchiveServiceError(
            "project_version_update_terminal_result_unverified"
        )
    return projected


def _project_update_reauthenticate_consumed_terminal_delivery(
    inspection_root: Path | str,
    *,
    capsule_bytes: bytes,
    expected_handoff_sha256: str,
    expected_result: Mapping[str, Any],
    target: str | None,
    reviewed_by: str | None,
    transaction_ref: str | None,
    approval_executor: Callable[..., Mapping[str, Any]],
    expected_approval_root: Path,
    expected_archive_id: str,
) -> str:
    """Recover the claim-derived capability for one exact consumed capsule."""

    if (
        not isinstance(capsule_bytes, bytes)
        or not capsule_bytes
        or re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            str(expected_handoff_sha256 or ""),
        )
        is None
        or not isinstance(expected_result, Mapping)
        or expected_result.get("ok") is not True
        or not callable(approval_executor)
        or not hmac.compare_digest(
            project_update_transaction.sha256_bytes(capsule_bytes),
            expected_handoff_sha256,
        )
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    try:
        consumed = project_update_transaction._parse_document(
            capsule_bytes,
            code="project_update_transaction_invalid",
        )
    except project_update_transaction.ProjectUpdateTransactionError:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        ) from None
    if (
        type(consumed) is not dict
        or _project_update_canonical_bytes(consumed) != capsule_bytes
        or consumed.get("schema") != _PROJECT_UPDATE_TERMINAL_HANDOFF_SCHEMA
        or consumed.get("state") != "terminal_ready"
        or set(consumed) != {"schema", "state", "pending", "ready"}
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    project_root = _project_update_resume_project_root_read_only(
        inspection_root
    )
    pending_record = consumed["pending"]
    ready_record = consumed["ready"]
    preview, domain_result, basis, postimage = (
        _project_update_terminal_handoff_attachments(pending_record)
    )
    pending_payload = pending_record.get("payload")
    ready_payload = (
        ready_record.get("payload")
        if isinstance(ready_record, dict)
        else None
    )
    if type(pending_payload) is not dict or type(ready_payload) is not dict:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    binding = project_version_update_approval_binding(preview)
    supplied_target = str(target or "").strip()
    supplied_reviewer = str(reviewed_by or "").strip()
    supplied_transaction = str(transaction_ref or "").strip()
    legacy_cleanup_authority = pending_payload.get(
        "legacy_cleanup_authority_sha256"
    )
    if (
        pending_payload.get("plan_sha256") != binding.plan_sha256
        or pending_payload.get("target_binding_sha256")
        != binding.target_binding_sha256
        or ready_payload.get("plan_sha256") != binding.plan_sha256
        or ready_payload.get("target_binding_sha256")
        != binding.target_binding_sha256
        or ready_payload.get("pending_record_sha256")
        != project_update_transaction.sha256_document(pending_record)
        or ready_payload.get("claim_succeeded_checkpoint_sha256")
        != pending_payload.get("claim_succeeded_checkpoint_sha256")
        or ready_payload.get("exact_postimage_sha256")
        != pending_payload.get("exact_postimage_sha256")
        or ready_payload.get("legacy_cleanup_authority_sha256")
        != legacy_cleanup_authority
        or (
            legacy_cleanup_authority is not None
            and re.fullmatch(
                r"sha256:[0-9a-f]{64}",
                str(legacy_cleanup_authority),
            )
            is None
        )
        or supplied_target
        and supplied_target != basis.get("target_tag")
        or supplied_reviewer
        and supplied_reviewer != pending_payload.get("reviewer")
        or supplied_transaction
        and supplied_transaction != pending_payload.get("transaction_ref")
        or not _wom_kit_project_version_update_approval_authority_matches(
            inspection_root,
            expected_root=expected_approval_root,
            expected_archive_id=expected_archive_id,
        )
        or not _project_update_terminal_result_matches_pending(
            expected_result,
            pending_record,
        )
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    verified = False
    delivery_capability: str | None = None

    def started_guard(_claim: _ClaimedExactHumanApproval) -> bool:
        return False

    def succeeded_guard(claim: _ClaimedExactHumanApproval) -> bool:
        nonlocal verified, delivery_capability
        candidate_capability = _project_update_terminal_delivery_capability(
            claim,
            pending_record,
        )
        claim_reference_sha256 = project_update_transaction.sha256_bytes(
            _project_update_canonical_bytes(claim.public_reference())
        )
        verified = bool(
            _project_update_terminal_record_matches_claim(
                pending_record,
                claim,
                expected_plan_sha256=binding.plan_sha256,
                expected_target_binding_sha256=(
                    binding.target_binding_sha256
                ),
            )
            and _project_update_terminal_record_matches_claim(
                ready_record,
                claim,
                expected_plan_sha256=binding.plan_sha256,
                expected_target_binding_sha256=(
                    binding.target_binding_sha256
                ),
            )
            and _project_update_terminal_postimage_matches(
                project_root,
                basis,
                postimage,
            )
            and hmac.compare_digest(
                project_update_transaction.sha256_bytes(
                    candidate_capability.encode("ascii")
                ),
                str(
                    ready_payload.get("delivery_capability_sha256") or ""
                ),
            )
            and (
                legacy_cleanup_authority is None
                or hmac.compare_digest(
                    legacy_cleanup_authority,
                    claim_reference_sha256,
                )
            )
        )
        if verified:
            delivery_capability = candidate_capability
        return verified

    def started_writer(_claim: _ClaimedExactHumanApproval) -> Mapping[str, Any]:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )

    def finalizer(_claim: _ClaimedExactHumanApproval) -> None:
        if verified is not True:
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )

    approval_executor(
        copy.deepcopy(preview),
        started_writer,
        finalizer,
        started_guard,
        succeeded_guard,
        str(pending_payload["reviewer"]),
        candidate_missing_handler=None,
    )
    if verified is not True or delivery_capability is None:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    return delivery_capability


def _project_update_reauthenticate_cancellation_terminal_delivery(
    inspection_root: Path | str,
    *,
    capsule_bytes: bytes,
    expected_handoff_sha256: str,
    expected_result: Mapping[str, Any],
    key_provider: Any,
    expected_approval_root: Path,
    expected_archive_id: str,
    _terminal_control_lease_held: bool = False,
) -> str:
    """Re-authenticate one retired cancellation capsule after process restart."""

    if (
        type(_terminal_control_lease_held) is not bool
        or not isinstance(capsule_bytes, bytes)
        or not capsule_bytes
        or not _project_update_is_legacy_unapproved_terminal_result(
            expected_result
        )
        or re.fullmatch(
            r"sha256:[0-9a-f]{64}", str(expected_handoff_sha256 or "")
        )
        is None
        or not hmac.compare_digest(
            project_update_transaction.sha256_bytes(capsule_bytes),
            expected_handoff_sha256,
        )
        or not callable(getattr(key_provider, "use_key", None))
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    project_root = _project_update_resume_project_root_read_only(inspection_root)
    if not _terminal_control_lease_held:
        try:
            with _project_update_terminal_control_boundary(project_root):
                return _project_update_reauthenticate_cancellation_terminal_delivery(
                    inspection_root,
                    capsule_bytes=capsule_bytes,
                    expected_handoff_sha256=expected_handoff_sha256,
                    expected_result=expected_result,
                    key_provider=key_provider,
                    expected_approval_root=expected_approval_root,
                    expected_archive_id=expected_archive_id,
                    _terminal_control_lease_held=True,
                )
        except ArchiveServiceError:
            raise
        except BaseException:
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            ) from None
    if _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.get() is None:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    try:
        document = project_update_transaction._parse_document(
            capsule_bytes,
            code="project_update_transaction_invalid",
        )
        if (
            type(document) is not dict
            or _project_update_canonical_bytes(document) != capsule_bytes
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        payload = document.get("payload")
        recovery_ref = (
            payload.get("recovery_ref") if isinstance(payload, Mapping) else None
        )
        if (
            type(recovery_ref) is not str
            or re.fullmatch(r"recovery_[0-9a-f]{32}", recovery_ref) is None
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        resolved = project_update_legacy_recovery.resolve_terminal_recovery(
            project_root,
            expected_approval_root,
            recovery_ref,
            key_provider,
            create_if_missing=False,
        )
        expected_archive_identity_sha256 = (
            exact_human_approval_archive_identity_sha256(expected_archive_id)
        )
        if (
            resolved.outcome != "unapproved_restored"
            or resolved.archive_identity_sha256
            != expected_archive_identity_sha256
            or resolved.recovery_ref != recovery_ref
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )

        def authenticate(key: memoryview) -> str:
            verified_result, capability = (
                _project_update_verify_cancellation_terminal_document(
                    document,
                    expected_archive_identity_sha256=(
                        expected_archive_identity_sha256
                    ),
                    key=key,
                )
            )
            verified_payload = document.get("payload")
            if (
                not _project_update_is_legacy_unapproved_terminal_result(
                    verified_result
                )
                or not hmac.compare_digest(
                    project_update_transaction.canonical_json_bytes(
                        dict(verified_result)
                    ),
                    project_update_transaction.canonical_json_bytes(
                        dict(expected_result)
                    ),
                )
                or not isinstance(verified_payload, Mapping)
                or verified_payload.get("intent_sha256")
                != resolved.intent_sha256
                or verified_payload.get("terminal_receipt_sha256")
                != resolved.terminal_receipt_document_sha256
                or verified_payload.get(
                    "cancellation_result_document_sha256"
                )
                != resolved.cancellation_result_document_sha256
                or verified_payload.get("result_payload_sha256")
                != resolved.cancellation_result_sha256
            ):
                raise ArchiveServiceError(
                    "project_version_update_terminal_handoff_invalid"
                )
            return capability

        capability = key_provider.use_key(
            expected_approval_root,
            authenticate,
            create_if_missing=False,
        )
        if type(capability) is not str:
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        _project_update_register_terminal_delivery_capability(
            expected_handoff_sha256,
            capability,
        )
        return capability
    except ArchiveServiceError:
        raise
    except (
        project_update_legacy_recovery.LegacyProjectUpdateRecoveryError,
        project_update_transaction.ProjectUpdateTransactionError,
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        ) from None
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        ) from None


def _project_update_resume_authenticated_terminal_cleanup(
    project_root: Path,
    transaction_ref: str,
    *,
    cleanup_authority_sha256: str,
) -> bool:
    """Continue exact cleanup from either the live terminal tree or tombstone.

    A process can stop after publishing the authenticated ready handoff but
    before ``exact_cleanup`` moves the completed transaction to its tombstone.
    The handoff is the cleanup authority in both states.  Reopen the original
    exact completed transaction when it still exists; use the tombstone/proof
    resume path only after that original name is absent.
    """

    transaction_parent = project_root.joinpath(
        *PurePosixPath(
            project_update_transaction.TRANSACTION_ROOT_LOGICAL
        ).parts
    )
    original = transaction_parent / transaction_ref
    if os.path.lexists(original):
        transaction = (
            project_update_transaction.ProjectUpdateTransaction.open(
                project_root,
                transaction_ref,
            )
        )
        return transaction.exact_cleanup(
            cleanup_authority_sha256=cleanup_authority_sha256
        )
    return project_update_transaction.ProjectUpdateTransaction.resume_cleanup(
        project_root,
        transaction_ref,
        cleanup_authority_sha256=cleanup_authority_sha256,
    )


_PROJECT_UPDATE_APPROVAL_CLAIM_FILENAME_RE = re.compile(
    r"^(approval_[0-9a-f]{32})\.json$"
)
_PROJECT_UPDATE_MAX_TERMINAL_CLAIM_DIRECTORY_ENTRIES = 100_000


def _project_update_terminal_transaction_cleanup_required_result(
    *,
    exact_history_count: int,
) -> dict[str, Any]:
    """Route one exact completed original without handoff to --resume.

    v0.4.18: the same structured blocker as other exact terminal history, with
    a distinct content-free basis so dry-run, approval, and resume all name
    the same recovery.  Nothing here attributes a past update success or
    grants cleanup, retry, or fresh approval authority.
    """

    result = _project_update_terminal_cleanup_required_result(
        exact_history_count=exact_history_count,
        resumable_transaction_present=True,
    )
    result.update(
        {
            "outcome_basis": (
                "exact_terminal_transaction_cleanup_requires_resume"
            ),
            "terminal_transaction_cleanup_required": True,
            "past_update_success_attributed": False,
        }
    )
    return result


def _project_update_terminal_cleanup_platform_unsupported_result(
    *,
    operator_resume_identifiers_supplied: bool,
) -> dict[str, Any]:
    """Refuse terminal-original cleanup off Windows with zero writes."""

    return {
        "ok": False,
        "status": "terminal_cleanup_platform_unsupported",
        "reason_code": (
            "project_version_update_terminal_cleanup_platform_unsupported"
        ),
        "reason_codes": [
            "project_version_update_terminal_cleanup_platform_unsupported"
        ],
        "blocker_codes": [
            "project_version_update_terminal_cleanup_platform_unsupported"
        ],
        "lifecycle_action": "project_version_update",
        "error_class": "reconciliation",
        "effects_state": "none",
        "reconciliation_required": True,
        "outcome_basis": (
            "exact_terminal_transaction_cleanup_requires_windows_resume"
        ),
        "update_completed": False,
        "past_update_success_attributed": False,
        "automatic_resume_discovery": True,
        "operator_resume_identifiers_supplied": bool(
            operator_resume_identifiers_supplied
        ),
        "automatic_retry_authorized": False,
        "cleanup_authorized": False,
        "fresh_approval_authorized": False,
        "native_approval_redisplayed": False,
        "domain_writer_reentered": False,
        "approval_key_accessed": False,
        "approval_claim_store_accessed": False,
        "native_approval_ui_entered": False,
        "domain_writer_entered": False,
        "client_archive_domain_content_accessed": False,
        "project_domain_files_written": [],
        "files_written": [],
        "next_safe_actions": [
            "Run identifier-free project-version-update --resume on the Windows machine that owns this project; mutation-bearing cleanup is Windows-only.",
            "Do not delete locks, transaction directories, tombstones, or proofs by hand.",
        ],
    }


def _project_update_terminal_original_cleanup_completed_result(
    *,
    operator_resume_identifiers_supplied: bool,
    cleanup_proof_count: int,
) -> dict[str, Any]:
    """Report exact private-control cleanup of one completed original."""

    if (
        type(cleanup_proof_count) is not int
        or cleanup_proof_count < 1
        or cleanup_proof_count
        > project_update_transaction.MAX_TERMINAL_CLEANUP_SCAN_ENTRIES
    ):
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    return {
        "ok": True,
        "status": "terminal_transaction_cleanup_completed",
        "update_completed": False,
        "past_update_success_attributed": False,
        "current_project_state_independently_verified": False,
        "fresh_approval_required": True,
        "native_approval_redisplayed": False,
        "automatic_resume_discovery": True,
        "operator_resume_identifiers_supplied": bool(
            operator_resume_identifiers_supplied
        ),
        "terminal_transactions_cleaned": 1,
        "cleanup_proofs_written_or_verified": 1,
        "namespace_cleanup_proof_count": cleanup_proof_count,
        "cleanup_authority_basis": (
            "journal_approval_reference_reauthenticated_against_succeeded_claim"
        ),
        "approval_key_accessed": True,
        "approval_claim_store_accessed": True,
        "project_domain_effects": "none",
        "domain_writer_entered": False,
        "domain_writer_reentered": False,
        "native_approval_ui_entered": False,
        "project_domain_files_written": [],
        "files_written_scope": "project_domain_only",
        "files_written": [],
        "effect_summary": {
            "project_domain_writes_performed": False,
            "project_domain_files_written": [],
            "durable_control_evidence_written_or_verified": True,
            "private_control_mutation_performed_or_verified": True,
            "private_control_mutation_may_be_incomplete": False,
            "terminal_transaction_cleanup_performed_or_verified": True,
            "paths_or_identifiers_disclosed": False,
        },
        "privacy_guards": {
            "private_paths_echoed": False,
            "private_identifiers_echoed": False,
            "private_hashes_echoed": False,
        },
        "next_safe_actions": [
            "Run a fresh project-version-update preview, then request one new exact approval."
        ],
    }


def _project_update_terminal_original_key_provider() -> Any:
    """Return the production archive key provider (test seam)."""

    from .exact_human_approval_workflow import _production_key_provider

    return _production_key_provider()


_PROJECT_UPDATE_TERMINAL_ORIGINAL_PIN_MAX_BYTES = 4096


def _project_update_terminal_original_postimage_superseded_read_only(
    project_root: Path,
    transaction_ref: str,
) -> bool:
    """Report whether the live active pin left the transaction's post-image.

    A completed transaction whose active pin still equals its post-image can
    be finished by the v0.4.16 replay contract (claim rediscovery, terminal
    handoff, bound result).  Once the project has moved on, that contract's
    live-component guard can never pass again, so identifier-free resume
    finishes only the private control cleanup.  An absent, unsafe, or
    unreadable pin counts as superseded because the replay contract would
    refuse it as well.  Read-only; echoes nothing.
    """

    try:
        transaction = project_update_transaction.ProjectUpdateTransaction.open(
            project_root,
            transaction_ref,
            verify_candidate_content=False,
        )
        pin = next(
            (
                component
                for component in transaction.intent.components
                if component.role == "active_pin"
            ),
            None,
        )
        if pin is None:
            return False
        target = project_root.joinpath(
            *PurePosixPath(pin.logical_target).parts
        )
        value = _project_update_safe_read_component(
            project_root,
            target,
            maximum=_PROJECT_UPDATE_TERMINAL_ORIGINAL_PIN_MAX_BYTES,
        )
        if not isinstance(value, bytes):
            return True
        return not hmac.compare_digest(
            project_update_transaction.digest_component(value),
            pin.post_sha256,
        )
    except (
        OSError,
        TypeError,
        ValueError,
        project_update_transaction.ProjectUpdateTransactionError,
    ):
        return True


def _project_update_authenticate_terminal_original_authority(
    *,
    expected_approval_root: Path | None,
    expected_archive_id: str | None,
    approval_reference_sha256: str,
) -> bool:
    """Prove one succeeded claim authorized the journal's approval reference.

    The transaction journal binds ``sha256(canonical(public_reference))`` at
    ``approval_bound`` and repeats it through ``completed``.  Exactly one
    MAC-verified ``succeeded`` claim in the bound archive claim store must
    reproduce that digest.  No approval context is rebuilt, no live component
    is classified, no key or claim is created, and nothing is echoed.  Any
    unreadable, unauthenticated, ambiguous, or non-succeeded match fails
    closed.
    """

    if (
        not isinstance(expected_approval_root, Path)
        or type(expected_archive_id) is not str
        or type(approval_reference_sha256) is not str
        or re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            approval_reference_sha256,
        )
        is None
    ):
        return False
    try:
        canonical_root = require_existing_archive_root(expected_approval_root)
        if read_archive_id(canonical_root) != expected_archive_id:
            return False
        claims_parent = canonical_root.joinpath(
            *Path(CLAIMS_RELATIVE_ROOT).parts
        )
        with _activity_group_bound_directory_chain(
            canonical_root,
            claims_parent,
            create=False,
        ) as binding:
            if binding.get("path") != claims_parent:
                return False
            directory_target = binding.get("descriptor")
            if type(directory_target) is not int:
                directory_target = claims_parent
            names = os.listdir(directory_target)
            if (
                len(names)
                > _PROJECT_UPDATE_MAX_TERMINAL_CLAIM_DIRECTORY_ENTRIES
                or any(type(name) is not str for name in names)
            ):
                return False
            approval_ids = tuple(
                match.group(1)
                for name in sorted(names)
                if (
                    match := _PROJECT_UPDATE_APPROVAL_CLAIM_FILENAME_RE
                    .fullmatch(name)
                )
                is not None
            )
            if not approval_ids:
                return False

            def _with_key(key: memoryview) -> bool:
                matches = 0
                for approval_id in approval_ids:
                    try:
                        reference, status = (
                            _authenticated_claim_reference_core(
                                canonical_root,
                                approval_id,
                                key,
                                bound_archive_root=canonical_root,
                                claim_parent_binding=binding,
                            )
                        )
                    except ExactHumanApprovalError:
                        # An unreadable, foreign-key, or torn sibling claim
                        # cannot be the candidate: the reference digest
                        # covers the approval id, so it can neither hide nor
                        # forge a match.  Only the candidate must verify.
                        continue
                    digest = project_update_transaction.sha256_bytes(
                        _project_update_canonical_bytes(reference)
                    )
                    if hmac.compare_digest(digest, approval_reference_sha256):
                        if status != "succeeded":
                            return False
                        matches += 1
                return matches == 1

            provider = _project_update_terminal_original_key_provider()
            return bool(
                provider.use_key(
                    canonical_root,
                    _with_key,
                    create_if_missing=False,
                )
            )
    except (
        OSError,
        ArchiveServiceError,
        ExactHumanApprovalError,
        RuntimeError,
        TypeError,
        ValueError,
    ):
        return False


def _project_update_resume_terminal_original_cleanup(
    inspection_root: Path | str,
    *,
    project_root: Path,
    transaction_ref: str,
    terminal_inspection: Any,
    operator_resume_identifiers_supplied: bool,
    expected_approval_root: Path | None,
    expected_archive_id: str | None,
    report_progress: Callable[[str, str], None],
    route: str = "direct",
) -> dict[str, Any]:
    """Finish exact private cleanup of one completed original without handoff.

    v0.4.18.  Runs only for ``terminal_original_exact`` with no terminal
    handoff.  Holds the project terminal guard from the final read-only
    observation through cleanup, re-authenticates the journal's approval
    reference against exactly one succeeded claim, and then reuses the
    existing ``exact_cleanup`` primitive.  It never enters the domain writer,
    reopens durable approval state, opens native approval, changes source,
    runtime, pin, or archive content, or attributes a past update success.
    """

    if os.name != "nt":
        # Mutation-bearing cleanup is Windows-only.  Refuse before holding the
        # terminal guard so POSIX resume performs zero writes.
        return _project_update_terminal_cleanup_platform_unsupported_result(
            operator_resume_identifiers_supplied=(
                operator_resume_identifiers_supplied
            ),
        )

    authority_attempted = False

    def unknown(basis: str) -> dict[str, Any]:
        result = _project_update_terminal_cleanup_outcome_unknown_result(
            operator_resume_identifiers_supplied=(
                operator_resume_identifiers_supplied
            ),
            archive_identity_metadata_read=True,
        )
        result["outcome_basis"] = basis
        # Forensic truth: once the archive key and claim store were consulted
        # for this route, the result must say so even when it fails closed.
        result["approval_key_accessed"] = authority_attempted
        result["approval_claim_store_accessed"] = authority_attempted
        return result

    proof_count = 0
    try:
        with _project_update_terminal_control_boundary(project_root):
            observed: list[
                _ProjectUpdateTerminalHandoffObservation | None
            ] = []
            handoff_state = _project_update_terminal_handoff_state_read_only(
                inspection_root,
                _observation_out=observed,
            )
            if handoff_state is not None or observed != [None]:
                return unknown("terminal_transaction_cleanup_boundary_changed")
            current = (
                project_update_transaction
                .inspect_terminal_original_for_resume_read_only(
                    project_root,
                    transaction_ref,
                )
            )
            if current is None or current != terminal_inspection:
                return unknown("terminal_transaction_cleanup_boundary_changed")
            gate = _project_update_terminal_cleanup_unknown_gate_read_only(
                inspection_root,
                operator_resume_identifiers_supplied=(
                    operator_resume_identifiers_supplied
                ),
                archive_identity_metadata_read=True,
            )
            if gate is not None:
                return gate
            report_progress(
                "project-preflight",
                "resume-terminal-original-authority",
            )
            authority_attempted = True
            if not _project_update_authenticate_terminal_original_authority(
                expected_approval_root=expected_approval_root,
                expected_archive_id=expected_archive_id,
                approval_reference_sha256=(
                    current.approval_reference_sha256
                ),
            ):
                return unknown(
                    "terminal_transaction_cleanup_authority_unverified"
                )
            report_progress(
                "project-preflight",
                "resume-terminal-original-cleanup",
            )
            transaction = (
                project_update_transaction.ProjectUpdateTransaction.open(
                    project_root,
                    transaction_ref,
                )
            )
            if not transaction.exact_cleanup(
                cleanup_authority_sha256=current.approval_reference_sha256
            ):
                return unknown("terminal_transaction_cleanup_incomplete")
            classification, proof_count = (
                _project_update_terminal_cleanup_artifact_classification_read_only(
                    project_root
                )
            )
            if classification not in {
                "history_only_exact",
                "terminal_history_exact",
            }:
                return unknown(
                    "terminal_transaction_cleanup_namespace_unverified"
                )
    except ArchiveServiceError as failure:
        if _project_update_exact_terminal_handoff_invalid_failure(failure):
            return unknown("terminal_transaction_cleanup_boundary_changed")
        raise
    except (
        OSError,
        project_update_transaction.ProjectUpdateTransactionError,
    ):
        return unknown("terminal_transaction_cleanup_boundary_unknown")
    report_progress(
        "project-preflight",
        "resume-terminal-original-cleanup-completed",
    )
    completed = _project_update_terminal_original_cleanup_completed_result(
        operator_resume_identifiers_supplied=(
            operator_resume_identifiers_supplied
        ),
        cleanup_proof_count=proof_count,
    )
    completed["terminal_transaction_cleanup_route"] = (
        route
        if route in {"direct", "fallback_after_generic_resume_refusal"}
        else "direct"
    )
    return completed


def _project_update_acknowledge_terminal_result_delivery(
    inspection_root: Path | str,
    result: Mapping[str, Any],
    *,
    output_relative: str,
    run_id: str,
    operation_ref: str | None,
) -> bool:
    """Move one exact ready handoff to durable display-pending state."""

    terminal = result.get("terminal_finalization")
    cancellation_result = (
        _project_update_is_legacy_unapproved_terminal_result(result)
    )
    if (
        not isinstance(terminal, Mapping)
        or terminal.get("durable_terminal_handoff_ready") is not True
        or not (
            cancellation_result
            or terminal.get("transaction_cleanup_completed") is True
            and result.get("ok") is True
        )
        or type(output_relative) is not str
        or not output_relative.startswith(
            _PROJECT_UPDATE_OUTPUT_LOGICAL_PREFIX
        )
        or type(run_id) is not str
        or re.fullmatch(r"[0-9a-f]{32}", run_id) is None
        or type(operation_ref) is not str
        or re.fullmatch(r"op:sha256:[0-9a-f]{64}", operation_ref) is None
    ):
        return False
    project_root = _project_update_resume_project_root_read_only(
        inspection_root
    )
    logical = PurePosixPath(output_relative)
    if logical.is_absolute() or ".." in logical.parts:
        return False
    output_path = project_root.joinpath(*logical.parts)
    output_raw = _wom_kit_read_bounded_real_bytes(
        project_root,
        output_path,
        max_bytes=_PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES,
    )
    if not isinstance(output_raw, bytes):
        return False
    def unique_output_object(
        pairs: list[tuple[str, Any]],
    ) -> dict[str, Any]:
        value: dict[str, Any] = {}
        for key, item in pairs:
            if key in value:
                raise ValueError("duplicate_json_member")
            value[key] = item
        return value

    try:
        output_document = json.loads(
            output_raw.decode("utf-8"),
            object_pairs_hook=unique_output_object,
        )
    except (UnicodeError, json.JSONDecodeError, ValueError):
        return False
    cli_execution = (
        output_document.get("cli_execution")
        if isinstance(output_document, dict)
        else None
    )
    if (
        type(output_document) is not dict
        or type(cli_execution) is not dict
        or cli_execution.get("status") != "completed"
        or cli_execution.get("command") != "project-version-update"
        or cli_execution.get("result_available") is not True
        or cli_execution.get("exit_code")
        != (1 if cancellation_result else 0)
        or cli_execution.get("run_id") != run_id
        or output_document.get("ok")
        is not (False if cancellation_result else True)
        or output_document.get("status") != result.get("status")
    ):
        return False
    output_result_payload = dict(output_document)
    output_result_payload.pop("cli_execution", None)
    output_result_payload.pop("cli_output_artifact", None)
    result_payload_sha256 = project_update_transaction.sha256_document(
        dict(result)
    )
    if not hmac.compare_digest(
        project_update_transaction.sha256_document(output_result_payload),
        result_payload_sha256,
    ):
        return False
    handoff, _guard = _project_update_terminal_handoff_paths(
        project_root
    )
    observed = _project_update_read_terminal_document(project_root, handoff)
    expected_handoff_state = (
        "terminal_ready_unapproved"
        if cancellation_result
        else "terminal_ready"
    )
    if (
        observed is None
        or observed[0].get("state") != expected_handoff_state
    ):
        return False
    handoff_sha256 = project_update_transaction.sha256_bytes(observed[1])
    pending = observed[0].get("pending")
    ready = observed[0].get("ready")
    ready_payload = ready.get("payload") if type(ready) is dict else None
    delivery = cli_execution.get("terminal_delivery")
    artifact = output_document.get("cli_output_artifact")
    operation = artifact.get("operation") if type(artifact) is dict else None
    with _PROJECT_UPDATE_TERMINAL_DELIVERY_CAPABILITIES_LOCK:
        capability = _PROJECT_UPDATE_TERMINAL_DELIVERY_CAPABILITIES.get(
            handoff_sha256
        )
    cancellation_payload = observed[0].get("payload")
    capability_sha256 = (
        _project_update_terminal_document_capability_sha256(observed[0])
    )
    if (
        not (
            cancellation_result
            and isinstance(cancellation_payload, Mapping)
            and cancellation_payload.get("result_payload_sha256")
            == result_payload_sha256
            or not cancellation_result
            and type(ready_payload) is dict
            and type(pending) is dict
            and _project_update_terminal_result_matches_pending(
                result,
                pending,
            )
        )
        or type(capability) is not str
        or re.fullmatch(r"hmac-sha256:[0-9a-f]{64}", capability) is None
        or not hmac.compare_digest(
            project_update_transaction.sha256_bytes(
                capability.encode("ascii")
            ),
            str(capability_sha256 or ""),
        )
        or type(operation) is not dict
        or operation.get("operation_ref") != operation_ref
        or type(delivery) is not dict
        or delivery.get("terminal_handoff_sha256") != handoff_sha256
        or not hmac.compare_digest(
            project_update_transaction.canonical_json_bytes(delivery),
            project_update_transaction.canonical_json_bytes(
                _project_update_terminal_delivery_output_proof(
                    capability,
                    result,
                    handoff_sha256=handoff_sha256,
                    output_relative=output_relative,
                    run_id=run_id,
                    operation_ref=operation_ref,
                )
            ),
        )
    ):
        return False
    display_pending_path = _project_update_terminal_display_pending_path(
        project_root
    )
    display_pending_verified = False
    try:
        # The CLI may already hold this exact boundary across service replay,
        # immutable output publication, journal completion, and acknowledgement.
        # Reuse that ContextVar-bound lease instead of attempting to acquire the
        # non-reentrant OS guard a second time.  A standalone caller still takes
        # the same boundary here before the final compare-and-move.
        with _project_update_terminal_control_boundary(project_root) as (
            scaffold,
            binding,
        ):
            bound_handoff = scaffold.terminal_root / handoff.name
            bound_display_pending = (
                scaffold.terminal_root / display_pending_path.name
            )
            current = _project_update_read_terminal_document_bound(
                scaffold.project_root,
                binding,
                bound_handoff,
            )
            if (
                current is None
                or not hmac.compare_digest(
                    project_update_transaction.sha256_bytes(current[1]),
                    handoff_sha256,
                )
                or current[0].get("state") != expected_handoff_state
                or not hmac.compare_digest(
                    project_update_transaction.sha256_bytes(
                        capability.encode("ascii")
                    ),
                    str(
                        _project_update_terminal_document_capability_sha256(
                            current[0]
                        )
                        or ""
                    ),
                )
            ):
                return False
            consumed_root = scaffold.terminal_root
            try:
                original_parent_matches = bool(
                    os.path.samefile(handoff.parent, consumed_root)
                    and os.path.samefile(
                        display_pending_path.parent,
                        consumed_root,
                    )
                )
            except OSError:
                original_parent_matches = False
            if not original_parent_matches:
                return False
            if os.path.lexists(display_pending_path):
                return False
            project_update_transaction._atomic_move_file_no_replace(
                handoff,
                display_pending_path,
            )
            # Both names share one directory, so this single flush commits
            # both sides of the atomic rename.
            project_update_transaction._require_directory_durable(
                display_pending_path.parent
            )
            display_pending = _project_update_read_terminal_document_bound(
                scaffold.project_root,
                binding,
                bound_display_pending,
            )
            if (
                display_pending is None
                or not hmac.compare_digest(
                    display_pending[1],
                    current[1],
                )
                or not hmac.compare_digest(
                    project_update_transaction.sha256_bytes(
                        display_pending[1]
                    ),
                    handoff_sha256,
                )
                or os.path.lexists(handoff)
            ):
                return False
            display_pending_verified = True
    except (
        ArchiveServiceError,
        OSError,
        project_update_transaction.ProjectUpdateTransactionError,
    ):
        return False
    return display_pending_verified


def _project_update_finalize_terminal_result_display(
    inspection_root: Path | str,
    *,
    expected_handoff_sha256: str,
    delivery_capability: str,
) -> bool:
    """Atomically finalize one displayed capsule without writer re-entry."""

    if (
        re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            str(expected_handoff_sha256 or ""),
        )
        is None
        or re.fullmatch(
            r"hmac-sha256:[0-9a-f]{64}",
            str(delivery_capability or ""),
        )
        is None
    ):
        return False
    project_root = _project_update_resume_project_root_read_only(
        inspection_root
    )
    active, guard = _project_update_terminal_handoff_paths(project_root)
    display_pending = _project_update_terminal_display_pending_path(
        project_root
    )
    consumed = _project_update_terminal_consumed_path(
        project_root,
        expected_handoff_sha256,
    )
    try:
        with project_update_transaction._exclusive_guard(
            guard,
            within=project_root,
        ):
            if os.path.lexists(active):
                return False
            if os.path.lexists(consumed):
                if os.path.lexists(display_pending):
                    return False
                existing = _project_update_read_terminal_document(
                    project_root,
                    consumed,
                )
                if (
                    existing is None
                    or not hmac.compare_digest(
                        project_update_transaction.sha256_bytes(
                            existing[1]
                        ),
                        expected_handoff_sha256,
                    )
                ):
                    return False
                existing_capability_sha256 = (
                    _project_update_terminal_document_capability_sha256(
                        existing[0]
                    )
                )
                if (
                    existing_capability_sha256 is None
                    or not hmac.compare_digest(
                        project_update_transaction.sha256_bytes(
                            delivery_capability.encode("ascii")
                        ),
                        existing_capability_sha256,
                    )
                ):
                    return False
                project_update_transaction._require_directory_durable(
                    consumed.parent
                )
                return True
            observed = _project_update_read_terminal_document(
                project_root,
                display_pending,
            )
            if (
                observed is None
                or not hmac.compare_digest(
                    project_update_transaction.sha256_bytes(observed[1]),
                    expected_handoff_sha256,
                )
            ):
                return False
            observed_capability_sha256 = (
                _project_update_terminal_document_capability_sha256(
                    observed[0]
                )
            )
            if (
                observed_capability_sha256 is None
                or not hmac.compare_digest(
                    project_update_transaction.sha256_bytes(
                        delivery_capability.encode("ascii")
                    ),
                    observed_capability_sha256,
                )
            ):
                return False
            terminal_root = project_update_transaction._mkdirs(
                project_root,
                _PROJECT_UPDATE_TERMINAL_CONSUMED_ROOT_LOGICAL,
            )
            if (
                display_pending.parent != terminal_root
                or consumed.parent != terminal_root
            ):
                return False
            project_update_transaction._atomic_move_file_no_replace(
                display_pending,
                consumed,
            )
            project_update_transaction._require_directory_durable(
                terminal_root
            )
            final = _project_update_read_terminal_document(
                project_root,
                consumed,
            )
            if (
                final is None
                or not hmac.compare_digest(final[1], observed[1])
                or os.path.lexists(active)
                or os.path.lexists(display_pending)
            ):
                return False
    except (
        ArchiveServiceError,
        OSError,
        project_update_transaction.ProjectUpdateTransactionError,
    ):
        return False
    with _PROJECT_UPDATE_TERMINAL_DELIVERY_CAPABILITIES_LOCK:
        _PROJECT_UPDATE_TERMINAL_DELIVERY_CAPABILITIES.pop(
            expected_handoff_sha256,
            None,
        )
    return True


def _project_update_terminal_cleanup_unknown_preflight_read_only(
    inspection_root: Path | str,
    *,
    operator_resume_identifiers_supplied: bool,
    approval_identifier_supplied: bool,
    exact_terminal_delivery_observed: bool = False,
) -> dict[str, Any] | None:
    """Return cleanup-unknown before any archive identity boundary is opened.

    This helper observes only project update metadata. It never opens an
    archive marker, approval root, key, claim store, native decision, or cleanup
    artifact content. A supplied approval id remains an assertion about one
    authenticated claim and therefore cannot select this claimless outcome.
    """

    if (
        type(operator_resume_identifiers_supplied) is not bool
        or type(approval_identifier_supplied) is not bool
        or type(exact_terminal_delivery_observed) is not bool
    ):
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    project_root = _project_update_resume_project_root_read_only(
        inspection_root
    )

    legacy_locator_presence = (
        project_update_legacy_recovery.active_locator_presence_read_only(
            project_root
        )
    )
    if legacy_locator_presence == "present_unverified":
        # Content remains unread here.  The caller proceeds only far enough to
        # enter the existing archive-key and terminal-control boundaries,
        # where the locator, intent, and checkpoint chain are authenticated
        # before any transaction or domain writer can be selected.
        if approval_identifier_supplied:
            raise ArchiveServiceError(
                "exact_human_approval_resume_claim_invalid"
            )
        return None
    result = _project_update_terminal_cleanup_unknown_gate_read_only(
        inspection_root,
        operator_resume_identifiers_supplied=(
            operator_resume_identifiers_supplied
        ),
        archive_identity_metadata_read=False,
        exact_terminal_delivery_observed=(
            exact_terminal_delivery_observed
        ),
    )
    if result is not None and approval_identifier_supplied:
        raise ArchiveServiceError(
            "exact_human_approval_resume_claim_invalid"
        )
    return result


_PROJECT_UPDATE_LEGACY_RECOVERY_LOCATOR_TAIL = {
    "intent_sealed": None,
    "legacy_eligible": "legacy_eligibility_verified",
    "old_transaction_staged": "old_transaction_staged",
    "fresh_transaction_allocated": "fresh_transaction_allocated",
    "fresh_reservation_bound": "fresh_reservation_bound",
    "fresh_plan_sealed": "fresh_plan_sealed",
    "fresh_lock_backlinked": "fresh_lock_backlinked",
    "cancelled_fresh_staged": "cancelled_fresh_staged",
    "cancelled_fresh_cleaned": "cancelled_fresh_cleaned",
    "unapproved_restored": "unapproved_restored",
    "fresh_transaction_completed": "fresh_transaction_completed",
    # The terminal tail is outcome-dependent and is selected only after the
    # authenticated terminal receipt has been verified.
    "terminal_completed": None,
}


_PROJECT_UPDATE_LEGACY_RECOVERY_BRANCH_BY_LOCATOR = {
    "intent_sealed": "bootstrap",
    "legacy_eligible": "bootstrap",
    "old_transaction_staged": "reserve",
    "fresh_transaction_allocated": "reserve",
    "fresh_reservation_bound": "prepare_plan",
    "fresh_plan_sealed": "approval_or_claim_resume",
    "fresh_lock_backlinked": "writer_resume",
    "cancelled_fresh_staged": "cancellation",
    "cancelled_fresh_cleaned": "cancellation",
    "unapproved_restored": "cancellation",
    "fresh_transaction_completed": "terminal",
    "terminal_completed": "terminal",
}


def _project_update_legacy_recovery_branch(
    locator_state: str,
    *,
    terminal_outcome: str | None,
) -> str:
    """Classify one authenticated recovery tail before opening artifacts.

    This table is intentionally content-free.  In particular, callers must
    not open the fresh transaction tree until the returned branch requires
    it: cancellation and terminal recovery remain valid after that tree has
    been moved to its exact vault or removed.
    """

    branch = _PROJECT_UPDATE_LEGACY_RECOVERY_BRANCH_BY_LOCATOR.get(
        locator_state
    )
    if branch is None:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )
    if locator_state == "terminal_completed":
        if terminal_outcome not in {"success", "unapproved_restored"}:
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
    elif locator_state == "fresh_transaction_completed":
        if terminal_outcome != "success":
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
    elif locator_state == "unapproved_restored":
        if terminal_outcome not in {None, "unapproved_restored"}:
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
    elif terminal_outcome is not None:
        # A terminal receipt is authority only at the documented terminal
        # phases.  An authenticated but out-of-order receipt is preserved and
        # blocked instead of being used to infer a transition.
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )
    return branch


def _project_update_legacy_unapproved_restored_result() -> dict[str, Any]:
    """Return the one content-free replay for a proven claimless restore."""

    return project_update_legacy_recovery.cancellation_result_document()


def _project_update_is_exact_native_approval_denial(
    failure: BaseException,
) -> bool:
    """Admit cancellation authority only from the exact native broker type."""

    try:
        from .exact_human_approval_workflow import (
            ExactHumanApprovalWorkflowError,
        )

        return bool(
            type(failure) is ExactHumanApprovalWorkflowError
            and getattr(failure, "code", None)
            == "exact_human_approval_cancelled"
        )
    except BaseException:
        return False


def _project_update_is_legacy_unapproved_terminal_result(
    result: Mapping[str, Any],
) -> bool:
    """Recognize only the fixed, content-free cancellation projection."""

    if not isinstance(result, Mapping):
        return False
    expected = _project_update_legacy_unapproved_restored_result()
    try:
        return hmac.compare_digest(
            project_update_transaction.canonical_json_bytes(dict(result)),
            project_update_transaction.canonical_json_bytes(expected),
        )
    except (TypeError, ValueError):
        return False


def _project_update_legacy_old_lock_bytes(
    resolved: project_update_legacy_recovery.ResolvedActiveRecovery,
) -> bytes:
    """Reconstruct predecessor lock bytes from its sole exact transaction tree."""

    try:
        expected_tree = str(
            resolved.intent.get("old_transaction_sha256") or ""
        )
        old_ref = str(resolved.intent.get("old_transaction_ref") or "")
        old_canonical = resolved.paths.project_root.joinpath(
            *PurePosixPath(
                project_update_transaction.TRANSACTION_ROOT_LOGICAL
            ).parts,
            old_ref,
        )
        candidates = tuple(
            path
            for path in (resolved.paths.old_transaction_vault, old_canonical)
            if os.path.lexists(path)
        )
        if (
            len(candidates) != 1
            or re.fullmatch(r"update_[0-9a-f]{32}", old_ref) is None
            or
            project_update_legacy_recovery.directory_tree_sha256(
                candidates[0]
            )
            != expected_tree
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_changed"
            )
        marker_raw = project_update_legacy_recovery._read_regular(
            candidates[0] / "marker.json"
        )
        marker = json.loads(marker_raw.decode("utf-8"))
        reservation = (
            project_update_transaction.ProjectUpdateReservation.from_document(
                marker
            )
        )
        old_lock_bytes = project_update_transaction.lock_document_bytes(
            project_update_transaction.build_lock_document(reservation)
        )
        if project_update_transaction.sha256_bytes(
            old_lock_bytes
        ) != resolved.intent.get("old_lock_sha256"):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_changed"
            )
        return old_lock_bytes
    except ArchiveServiceError:
        raise
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        ) from None


def _project_update_resume_legacy_cancellation(
    *,
    resolved: project_update_legacy_recovery.ResolvedActiveRecovery,
    with_store: Callable[[Callable[[Any], Any]], Any],
    expected_approval_root: Path,
    expected_archive_id: str,
    key_provider: Any,
) -> dict[str, Any]:
    """Advance only the authenticated cancellation prefix to one terminal result."""

    plan = resolved.cancellation_plan
    inventory = resolved.fresh_transaction_inventory
    prospective = resolved.prospective_plan
    result = resolved.cancellation_result
    fresh_ref = resolved.fresh_transaction_ref
    if (
        not isinstance(plan, Mapping)
        or not isinstance(inventory, Mapping)
        or not isinstance(prospective, Mapping)
        or not _project_update_is_legacy_unapproved_terminal_result(result or {})
        or type(fresh_ref) is not str
        or type(resolved.cancellation_plan_document_sha256) is not str
        or type(resolved.cancellation_result_document_sha256) is not str
        or type(resolved.cancellation_result_sha256) is not str
        or type(resolved.fresh_transaction_inventory_document_sha256) is not str
        or type(resolved.fresh_transaction_inventory_sha256) is not str
        or plan.get("fresh_transaction_ref") != fresh_ref
        or plan.get("intent_sha256") != resolved.intent_sha256
        or plan.get("prospective_plan_document_sha256")
        != resolved.prospective_plan_document_sha256
        or _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.get() is None
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )
    phases = [str(item.get("phase") or "") for item in resolved.checkpoints]
    control: dict[str, Any] = {
        "with_store": with_store,
        "intent_sha256": resolved.intent_sha256,
        "journal_head_sha256": resolved.journal_head_sha256,
        "locator_sha256": resolved.locator_sha256,
        "recovery_phase": str(resolved.locator.get("state") or ""),
    }

    stage_document = resolved.cancellation_stage_evidence
    stage_document_sha256 = resolved.cancellation_stage_evidence_document_sha256
    if stage_document is None:
        stage_state = (
            project_update_legacy_recovery.stage_cancelled_fresh_transaction(
                resolved.paths,
                fresh_transaction_ref=fresh_ref,
                fresh_transaction_inventory=inventory,
            )
        )
        stage_document = (
            project_update_legacy_recovery.cancellation_stage_evidence_document(
                recovery_ref=resolved.paths.recovery_ref,
                intent_sha256=resolved.intent_sha256,
                fresh_transaction_ref=fresh_ref,
                cancellation_plan_document_sha256=(
                    resolved.cancellation_plan_document_sha256
                ),
                claim_absence_evidence_sha256=str(
                    plan.get("claim_absence_evidence_sha256") or ""
                ),
                fresh_transaction_inventory_sha256=(
                    resolved.fresh_transaction_inventory_sha256
                ),
                fresh_transaction_inventory_document_sha256=(
                    resolved.fresh_transaction_inventory_document_sha256
                ),
                stage_state=stage_state,
            )
        )
        stage_document_sha256 = with_store(
            lambda store: store.write_cancellation_stage_evidence(
                stage_document
            )
        )
    if type(stage_document_sha256) is not str:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )
    if not phases or phases[-1] == "fresh_plan_sealed":
        _project_update_legacy_recovery_checkpoint_control(
            control,
            phase="cancelled_fresh_staged",
            evidence_sha256=stage_document_sha256,
            locator_state="cancelled_fresh_staged",
        )
        phases.append("cancelled_fresh_staged")
    elif phases[-1] not in {
        "cancelled_fresh_staged",
        "cancelled_fresh_cleaned",
        "unapproved_restored",
    }:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )

    cleanup_document = resolved.cancellation_cleanup_evidence
    cleanup_document_sha256 = (
        resolved.cancellation_cleanup_evidence_document_sha256
    )
    if cleanup_document is None:
        cleanup_state = (
            project_update_legacy_recovery.delete_cancelled_fresh_transaction(
                resolved.paths,
                fresh_transaction_inventory=inventory,
            )
        )
        cleanup_document = (
            project_update_legacy_recovery.cancellation_cleanup_evidence_document(
                recovery_ref=resolved.paths.recovery_ref,
                intent_sha256=resolved.intent_sha256,
                fresh_transaction_ref=fresh_ref,
                cancellation_plan_document_sha256=(
                    resolved.cancellation_plan_document_sha256
                ),
                cancellation_stage_evidence_document_sha256=(
                    stage_document_sha256
                ),
                fresh_transaction_inventory_sha256=(
                    resolved.fresh_transaction_inventory_sha256
                ),
                fresh_transaction_inventory_document_sha256=(
                    resolved.fresh_transaction_inventory_document_sha256
                ),
                cleanup_state=cleanup_state,
            )
        )
        cleanup_document_sha256 = with_store(
            lambda store: store.write_cancellation_cleanup_evidence(
                cleanup_document
            )
        )
    if type(cleanup_document_sha256) is not str:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )
    if phases[-1] == "cancelled_fresh_staged":
        _project_update_legacy_recovery_checkpoint_control(
            control,
            phase="cancelled_fresh_cleaned",
            evidence_sha256=cleanup_document_sha256,
            locator_state="cancelled_fresh_cleaned",
        )
        phases.append("cancelled_fresh_cleaned")
    elif phases[-1] not in {"cancelled_fresh_cleaned", "unapproved_restored"}:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )

    old_lock_bytes = _project_update_legacy_old_lock_bytes(resolved)
    restore_document = resolved.cancellation_restore_evidence
    restore_document_sha256 = (
        resolved.cancellation_restore_evidence_document_sha256
    )
    if restore_document is None:
        restore_state = project_update_legacy_recovery.restore_old_transaction(
            resolved.paths,
            old_transaction_ref=str(resolved.intent["old_transaction_ref"]),
            expected_tree_sha256=str(
                resolved.intent["old_transaction_sha256"]
            ),
        )
        lock_path = resolved.paths.project_root.joinpath(
            *PurePosixPath(project_update_legacy_recovery.LOCK_LOGICAL).parts
        )
        if not hmac.compare_digest(
            project_update_legacy_recovery._read_regular(lock_path),
            old_lock_bytes,
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_changed"
            )
        restore_document = (
            project_update_legacy_recovery.cancellation_restore_evidence_document(
                recovery_ref=resolved.paths.recovery_ref,
                intent_sha256=resolved.intent_sha256,
                fresh_transaction_ref=fresh_ref,
                cancellation_plan_document_sha256=(
                    resolved.cancellation_plan_document_sha256
                ),
                cancellation_cleanup_evidence_document_sha256=(
                    cleanup_document_sha256
                ),
                old_transaction_ref=str(resolved.intent["old_transaction_ref"]),
                old_transaction_sha256=str(
                    resolved.intent["old_transaction_sha256"]
                ),
                old_lock_sha256=str(resolved.intent["old_lock_sha256"]),
                restore_state=restore_state,
            )
        )
        restore_document_sha256 = with_store(
            lambda store: store.write_cancellation_restore_evidence(
                restore_document
            )
        )
    if type(restore_document_sha256) is not str:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )
    if phases[-1] == "cancelled_fresh_cleaned":
        _project_update_legacy_recovery_checkpoint_control(
            control,
            phase="unapproved_restored",
            evidence_sha256=restore_document_sha256,
            locator_state="unapproved_restored",
        )
        phases.append("unapproved_restored")
    elif phases[-1] != "unapproved_restored":
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )

    receipt = resolved.terminal_receipt
    receipt_sha256 = resolved.terminal_receipt_document_sha256
    if receipt is None:
        journal_head_sha256 = control.get("journal_head_sha256")
        if type(journal_head_sha256) is not str:
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
        receipt = project_update_legacy_recovery.terminal_receipt_document(
            recovery_ref=resolved.paths.recovery_ref,
            outcome="unapproved_restored",
            intent_sha256=resolved.intent_sha256,
            journal_head_sha256=journal_head_sha256,
            fresh_transaction_ref=fresh_ref,
            old_transaction_inventory_sha256=str(
                resolved.intent["old_transaction_sha256"]
            ),
            claim_absence_evidence_sha256=str(
                plan["claim_absence_evidence_sha256"]
            ),
            cancelled_fresh_staging_sha256=(
                project_update_legacy_recovery.sha256_document(stage_document)
            ),
            cancelled_fresh_transaction_inventory_sha256=(
                resolved.fresh_transaction_inventory_sha256
            ),
            cancelled_fresh_transaction_inventory_document_sha256=(
                resolved.fresh_transaction_inventory_document_sha256
            ),
            cancelled_fresh_cleanup_evidence_sha256=(
                project_update_legacy_recovery.sha256_document(cleanup_document)
            ),
            restored_old_transaction_sha256=str(
                resolved.intent["old_transaction_sha256"]
            ),
            preserved_old_lock_sha256=str(resolved.intent["old_lock_sha256"]),
            cancellation_plan_document_sha256=(
                resolved.cancellation_plan_document_sha256
            ),
            cancellation_result_document_sha256=(
                resolved.cancellation_result_document_sha256
            ),
            cancellation_result_sha256=resolved.cancellation_result_sha256,
            cancelled_fresh_staging_document_sha256=stage_document_sha256,
            cancelled_fresh_cleanup_evidence_document_sha256=(
                cleanup_document_sha256
            ),
            restored_evidence_sha256=(
                project_update_legacy_recovery.sha256_document(restore_document)
            ),
            restored_evidence_document_sha256=restore_document_sha256,
        )
        receipt_sha256 = with_store(
            lambda store: store.write_terminal_receipt(receipt)
        )
    if type(receipt_sha256) is not str:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )
    _project_update_publish_legacy_cancellation_handoff_exact(
        project_root=resolved.paths.project_root,
        expected_approval_root=expected_approval_root,
        expected_archive_id=expected_archive_id,
        paths=resolved.paths,
        intent_sha256=resolved.intent_sha256,
        terminal_receipt_sha256=receipt_sha256,
        cancellation_result_document_sha256=(
            resolved.cancellation_result_document_sha256
        ),
        key_provider=key_provider,
    )
    with_store(
        lambda store: store.publish_terminal_locator_and_retire(
            intent_sha256=resolved.intent_sha256,
            journal_head_sha256=str(control["journal_head_sha256"]),
            previous_locator_sha256=str(control["locator_sha256"]),
            terminal_receipt_sha256=receipt_sha256,
        )
    )
    return project_update_legacy_recovery.cancellation_result_document()


def _project_update_legacy_abandonment_sha256(
    resolved: project_update_legacy_recovery.ResolvedActiveRecovery,
) -> str:
    """Rebuild the content-free predecessor abandonment authority exactly."""

    old_ref = str(resolved.intent.get("old_transaction_ref") or "")
    old_canonical = resolved.paths.project_root.joinpath(
        *PurePosixPath(
            project_update_transaction.TRANSACTION_ROOT_LOGICAL
        ).parts,
        old_ref,
    )
    candidates = tuple(
        path
        for path in (old_canonical, resolved.paths.old_transaction_vault)
        if os.path.lexists(path)
    )
    try:
        if (
            len(candidates) != 1
            or project_update_transaction.TRANSACTION_REF_RE.fullmatch(
                old_ref
            )
            is None
            or project_update_legacy_recovery.directory_tree_sha256(
                candidates[0]
            )
            != resolved.intent.get("old_transaction_sha256")
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_changed"
            )
        old_intent_sha256 = project_update_transaction.sha256_bytes(
            project_update_legacy_recovery._read_regular(
                candidates[0] / "intent.json"
            )
        )
        return project_update_transaction.sha256_document(
            {
                "old_claim_sha256": resolved.intent["old_claim_sha256"],
                "old_intent_sha256": old_intent_sha256,
                "old_live_components_sha256": resolved.intent[
                    "old_live_components_sha256"
                ],
                "old_lock_sha256": resolved.intent["old_lock_sha256"],
                "old_transaction_sha256": resolved.intent[
                    "old_transaction_sha256"
                ],
                "schema": (
                    "wom-kit/project-update-legacy-abandonment/v0.4.19"
                ),
            }
        )
    except ArchiveServiceError:
        raise
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        ) from None


def _project_update_resume_legacy_preplan(
    inspection_root: Path | str,
    *,
    resolved: project_update_legacy_recovery.ResolvedActiveRecovery,
    with_store: Callable[[Callable[[Any], Any]], Any],
    approval_executor: Callable[..., Mapping[str, Any]],
    progress_callback: (
        Callable[[str, str, int | None, int | None], None] | None
    ),
    expected_approval_root: Path,
    expected_archive_id: str,
    key_provider: Any,
    resume_boundary: Callable[[], Any],
) -> dict[str, Any]:
    """Advance authenticated A-C recovery phases before native approval.

    Every filesystem effect is idempotently re-observed, then followed by its
    authenticated checkpoint and locator before the next phase starts.  A
    power cut at any of those boundaries therefore performs no UI or domain
    write; the next invocation repeats only the exact unfinished transition.
    """

    project_root = resolved.paths.project_root

    def refresh() -> project_update_legacy_recovery.ResolvedActiveRecovery:
        return project_update_legacy_recovery.resolve_active_recovery(
            project_root,
            expected_approval_root,
            key_provider,
            create_if_missing=False,
        )

    def checkpoint(
        current: project_update_legacy_recovery.ResolvedActiveRecovery,
        *,
        phase: str,
        evidence_sha256: str,
        locator_state: str,
    ) -> project_update_legacy_recovery.ResolvedActiveRecovery:
        control = {
            "with_store": with_store,
            "intent_sha256": current.intent_sha256,
            "journal_head_sha256": current.journal_head_sha256,
            "locator_sha256": current.locator_sha256,
            "recovery_phase": str(current.locator.get("state") or ""),
        }
        _project_update_legacy_recovery_checkpoint_control(
            control,
            phase=phase,
            evidence_sha256=evidence_sha256,
            locator_state=locator_state,
        )
        return refresh()

    while True:
        locator_state = str(resolved.locator.get("state") or "")
        abandonment_sha256 = _project_update_legacy_abandonment_sha256(
            resolved
        )
        if locator_state == "intent_sealed":
            resolved = checkpoint(
                resolved,
                phase="legacy_eligibility_verified",
                evidence_sha256=abandonment_sha256,
                locator_state="legacy_eligible",
            )
            continue
        if locator_state == "legacy_eligible":
            staged = project_update_legacy_recovery.stage_old_transaction(
                resolved.paths,
                old_transaction_ref=str(
                    resolved.intent["old_transaction_ref"]
                ),
                expected_tree_sha256=str(
                    resolved.intent["old_transaction_sha256"]
                ),
            )
            stage_evidence_sha256 = (
                project_update_transaction.sha256_document(
                    {
                        "old_transaction_sha256": resolved.intent[
                            "old_transaction_sha256"
                        ],
                        "schema": (
                            "wom-kit/project-update-legacy-stage-evidence/"
                            "v0.4.19"
                        ),
                        "state": staged,
                    }
                )
            )
            resolved = checkpoint(
                resolved,
                phase="old_transaction_staged",
                evidence_sha256=stage_evidence_sha256,
                locator_state="old_transaction_staged",
            )
            continue
        if locator_state == "old_transaction_staged":
            if resolved.fresh_allocation is not None:
                if type(
                    resolved.fresh_allocation_document_sha256
                ) is not str:
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_ambiguous"
                    )
                resolved = checkpoint(
                    resolved,
                    phase="fresh_transaction_allocated",
                    evidence_sha256=(
                        resolved.fresh_allocation_document_sha256
                    ),
                    locator_state="fresh_transaction_allocated",
                )
                continue
            if resolved.pre_fetch_ref_snapshot is None:
                runner_lifetime = _ProjectVersionUpdateGitRunnerLifetime()
                try:
                    runner = runner_lifetime.acquire_preapproval()
                    observation = (
                        _wom_kit_project_update_pre_fetch_ref_snapshot_observation(
                            project_root / ".zettel-kasten" / "source",
                            str(
                                resolved.fresh_approval_seed[
                                    "requested_target_tag"
                                ]
                            ),
                            runner=runner,
                        )
                    )
                finally:
                    runner_lifetime.close_after_service_transaction()
                snapshot = observation.get("snapshot")
                target_tag = str(
                    resolved.fresh_approval_seed.get(
                        "requested_target_tag"
                    )
                    or ""
                )
                if (
                    observation.get("state") != "passed"
                    or observation.get("reason_code") != "verified"
                    or not isinstance(snapshot, Mapping)
                    or set(snapshot)
                    != {
                        "refs",
                        "requested_target_present",
                        "requested_target_ref",
                    }
                    or not isinstance(snapshot.get("refs"), Mapping)
                    or type(snapshot.get("requested_target_present"))
                    is not bool
                    or snapshot.get("requested_target_ref")
                    != f"refs/tags/{target_tag}"
                ):
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_ambiguous"
                    )
                with_store(
                    lambda store: store.write_pre_fetch_ref_snapshot(
                        observation
                    )
                )
                resolved = refresh()
            pre_record = resolved.pre_fetch_ref_snapshot
            if not isinstance(pre_record, Mapping):
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_ambiguous"
                )
            prepared = (
                project_update_transaction.ProjectUpdateTransaction.prepare_reservation(
                    project_identity_sha256=str(
                        resolved.intent["project_identity_sha256"]
                    ),
                    requested_target_tag=str(
                        resolved.fresh_approval_seed[
                            "requested_target_tag"
                        ]
                    ),
                    transaction_ref="update_" + secrets.token_hex(16),
                    ownership_nonce=secrets.token_hex(16),
                    created_at=(
                        datetime.now(timezone.utc)
                        .replace(microsecond=0)
                        .isoformat()
                        .replace("+00:00", "Z")
                    ),
                )
            )
            allocation = (
                project_update_legacy_recovery.fresh_allocation_document(
                    recovery_ref=resolved.paths.recovery_ref,
                    prepared_reservation_document=prepared.document(),
                    old_abandonment_sha256=abandonment_sha256,
                    pre_ref_snapshot_document_sha256=str(
                        resolved.pre_fetch_ref_snapshot_document_sha256
                    ),
                    pre_ref_snapshot_sha256=str(
                        resolved.pre_fetch_ref_snapshot_sha256
                    ),
                )
            )
            with_store(
                lambda store: store.write_fresh_allocation(allocation)
            )
            resolved = refresh()
            continue
        if locator_state == "fresh_transaction_allocated":
            allocation = resolved.fresh_allocation
            if not isinstance(allocation, Mapping):
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_ambiguous"
                )
            prepared = (
                project_update_transaction.ProjectUpdateTransaction.prepare_reservation(
                    project_identity_sha256=str(
                        allocation["project_identity_sha256"]
                    ),
                    requested_target_tag=str(
                        allocation["requested_target_tag"]
                    ),
                    transaction_ref=str(
                        allocation["fresh_transaction_ref"]
                    ),
                    ownership_nonce=str(allocation["fresh_ownership_nonce"]),
                    created_at=str(allocation["fresh_created_at"]),
                )
            )
            if prepared.sha256 != allocation.get(
                "prepared_reservation_document_sha256"
            ):
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_changed"
                )
            reservation = (
                project_update_transaction.ProjectUpdateTransaction.reserve_or_resume_exact(
                    project_root,
                    reservation=prepared,
                )
            )
            reservation_document = (
                project_update_legacy_recovery.fresh_reservation_document(
                    recovery_ref=resolved.paths.recovery_ref,
                    fresh_transaction_ref=reservation.transaction_ref,
                    fresh_reservation_sha256=reservation.reservation.sha256,
                    fresh_allocation_document_sha256=str(
                        resolved.fresh_allocation_document_sha256
                    ),
                    old_abandonment_sha256=abandonment_sha256,
                )
            )
            with_store(
                lambda store: store.write_fresh_reservation(
                    reservation_document
                )
            )
            resolved = refresh()
            if str(resolved.locator.get("state") or "") == (
                "fresh_transaction_allocated"
            ):
                resolved = checkpoint(
                    resolved,
                    phase="fresh_reservation_bound",
                    evidence_sha256=str(
                        resolved.fresh_reservation_document_sha256
                    ),
                    locator_state="fresh_reservation_bound",
                )
            continue
        if locator_state != "fresh_reservation_bound":
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
        break

    allocation = resolved.fresh_allocation
    reservation_record = resolved.fresh_reservation
    if (
        not isinstance(allocation, Mapping)
        or not isinstance(reservation_record, Mapping)
        or type(resolved.fresh_allocation_document_sha256) is not str
        or type(resolved.pre_fetch_ref_snapshot_document_sha256) is not str
        or type(resolved.pre_fetch_ref_snapshot_sha256) is not str
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )
    prepared = (
        project_update_transaction.ProjectUpdateTransaction.prepare_reservation(
            project_identity_sha256=str(allocation["project_identity_sha256"]),
            requested_target_tag=str(allocation["requested_target_tag"]),
            transaction_ref=str(allocation["fresh_transaction_ref"]),
            ownership_nonce=str(allocation["fresh_ownership_nonce"]),
            created_at=str(allocation["fresh_created_at"]),
        )
    )
    if (
        prepared.sha256
        != allocation.get("prepared_reservation_document_sha256")
        or reservation_record.get("fresh_reservation_sha256")
        != prepared.sha256
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_changed"
        )
    reviewer = safe_foreign_quarantine_actor_id(
        resolved.fresh_approval_seed.get("reviewer")
    )
    target_tag = str(allocation["requested_target_tag"])
    if reviewer is None or target_tag != f"v{WOM_KIT_VERSION}":
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    abandonment_sha256 = _project_update_legacy_abandonment_sha256(resolved)
    prospective_seed_sha256 = project_update_transaction.sha256_document(
        {
            "old_abandonment_sha256": abandonment_sha256,
            "schema": (
                "wom-kit/project-update-legacy-prospective-seed/v0.4.19"
            ),
            "target_tag": target_tag,
        }
    )
    recovery_summary = {
        "schema": "wom-kit/project-update-legacy-prewrite-approval/v0.4.19",
        "old_abandonment_sha256": abandonment_sha256,
        "prospective_fresh_plan_sha256": prospective_seed_sha256,
        "single_composite_approval": True,
        "old_claim_reused": False,
        "old_transaction_mutated": False,
    }
    control: dict[str, Any] = {
        "paths": resolved.paths,
        "old_transaction_ref": resolved.intent["old_transaction_ref"],
        "old_transaction_tree_sha256": resolved.intent[
            "old_transaction_sha256"
        ],
        "old_lock_bytes": _project_update_legacy_old_lock_bytes(resolved),
        "old_abandonment_sha256": abandonment_sha256,
        "intent_sha256": resolved.intent_sha256,
        "journal_head_sha256": resolved.journal_head_sha256,
        "locator_sha256": resolved.locator_sha256,
        "recovery_phase": "fresh_reservation_bound",
        "with_store": with_store,
        "confirm_fresh_claim_absent": (
            lambda context: _project_update_confirm_context_claim_absent(
                expected_approval_root=expected_approval_root,
                context=context,
                key_provider=key_provider,
                resume_boundary=resume_boundary,
            )
        ),
        "progress_callback": progress_callback,
        "approval_key_provider": key_provider,
        "fresh_transaction_ref": prepared.transaction_ref,
        "prepared_fresh_reservation": prepared,
        "fresh_allocation_sha256": (
            resolved.fresh_allocation_document_sha256
        ),
        "fresh_reservation_sha256": (
            resolved.fresh_reservation_document_sha256
        ),
        "pre_ref_snapshot_document_sha256": (
            resolved.pre_fetch_ref_snapshot_document_sha256
        ),
        "pre_ref_snapshot_sha256": resolved.pre_fetch_ref_snapshot_sha256,
        "recovery_evidence_sha256": (
            resolved.fresh_reservation_document_sha256
        ),
    }

    def bind_existing_reservation(
        reservation: project_update_transaction.ReservedProjectUpdateTransaction,
    ) -> None:
        if (
            reservation.transaction_ref != prepared.transaction_ref
            or reservation.reservation.sha256 != prepared.sha256
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_binding_invalid"
            )
        document = project_update_legacy_recovery.fresh_reservation_document(
            recovery_ref=resolved.paths.recovery_ref,
            fresh_transaction_ref=reservation.transaction_ref,
            fresh_reservation_sha256=reservation.reservation.sha256,
            fresh_allocation_document_sha256=str(
                resolved.fresh_allocation_document_sha256
            ),
            old_abandonment_sha256=abandonment_sha256,
        )
        document_sha256 = with_store(
            lambda store: store.write_fresh_reservation(document)
        )
        if document_sha256 != resolved.fresh_reservation_document_sha256:
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_changed"
            )

    control["fresh_reservation_callback"] = bind_existing_reservation
    return _wom_kit_project_version_update_legacy_core(
        inspection_root,
        target=target_tag,
        dry_run=False,
        approve=True,
        reviewed_by=reviewer,
        affirm_external_writers_quiescent=True,
        approval_executor=approval_executor,
        progress_callback=progress_callback,
        _expected_approval_root=expected_approval_root,
        _expected_archive_id=expected_archive_id,
        _legacy_recovery_old_lock_bytes=control["old_lock_bytes"],
        _legacy_recovery_approval_summary=recovery_summary,
        _legacy_recovery_control=control,
    )


def _project_update_resume_active_legacy_recovery(
    inspection_root: Path | str,
    *,
    project_root: Path,
    approval_executor: Callable[..., Mapping[str, Any]],
    progress_callback: (
        Callable[[str, str, int | None, int | None], None] | None
    ),
    expected_approval_root: Path,
    expected_archive_id: str,
    key_provider: Any,
    resume_boundary: Callable[[], Any],
) -> dict[str, Any]:
    """Resume only a fully authenticated current-schema recovery plan."""

    if (
        not callable(approval_executor)
        or not callable(getattr(key_provider, "use_key", None))
        or not callable(resume_boundary)
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )

    def report(stage: str, event: str) -> None:
        if progress_callback is not None:
            try:
                progress_callback(stage, event, None, None)
            except Exception:
                pass

    try:
        with (
            _project_update_terminal_control_boundary(project_root),
            project_update_legacy_recovery.legacy_recovery_process_guard(
                project_root,
                terminal_control_lease_held=lambda: (
                    _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.get() is not None
                ),
            ),
        ):
            resolved = (
                project_update_legacy_recovery.resolve_active_recovery(
                    project_root,
                    expected_approval_root,
                    key_provider,
                    create_if_missing=False,
                )
            )

            def with_store(action: Callable[[Any], Any]) -> Any:
                def consume(key: memoryview) -> Any:
                    with project_update_legacy_recovery.LegacyRecoveryStore(
                        project_root,
                        resolved.paths.recovery_ref,
                        key,
                    ) as store:
                        return action(store)

                return key_provider.use_key(
                    expected_approval_root,
                    consume,
                    create_if_missing=False,
                )
            handoff_observations: list[
                _ProjectUpdateTerminalHandoffObservation | None
            ] = []
            handoff_state = _project_update_terminal_handoff_state_read_only(
                inspection_root,
                _observation_out=handoff_observations,
            )
            if len(handoff_observations) != 1:
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_ambiguous"
                )
            handoff_observation = handoff_observations[0]
            plan = resolved.prospective_plan
            locator_state = str(resolved.locator.get("state") or "")
            phases = tuple(
                str(item.get("phase") or "")
                for item in resolved.checkpoints
            )
            allowed_tail = _PROJECT_UPDATE_LEGACY_RECOVERY_LOCATOR_TAIL.get(
                locator_state
            )
            if locator_state == "terminal_completed":
                terminal_receipt = resolved.terminal_receipt
                if not isinstance(terminal_receipt, Mapping):
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_ambiguous"
                    )
                outcome = terminal_receipt.get("outcome")
                allowed_tail = (
                    "fresh_transaction_completed"
                    if outcome == "success"
                    else "unapproved_restored"
                    if outcome == "unapproved_restored"
                    else None
                )
            chain_matches_locator = bool(
                locator_state == "intent_sealed" and not phases
                or allowed_tail is not None
                and bool(phases)
                and phases[-1] == allowed_tail
            )
            if resolved.intent.get(
                "archive_identity_sha256"
            ) != exact_human_approval_archive_identity_sha256(
                expected_archive_id
            ):
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_changed"
                )
            if (
                locator_state
                not in _PROJECT_UPDATE_LEGACY_RECOVERY_LOCATOR_TAIL
                or not chain_matches_locator
            ):
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_ambiguous"
                )

            terminal_receipt = resolved.terminal_receipt
            terminal_outcome = (
                terminal_receipt.get("outcome")
                if isinstance(terminal_receipt, Mapping)
                else None
            )
            recovery_branch = _project_update_legacy_recovery_branch(
                locator_state,
                terminal_outcome=(
                    str(terminal_outcome)
                    if type(terminal_outcome) is str
                    else None
                ),
            )
            if recovery_branch in {"bootstrap", "reserve", "prepare_plan"}:
                return _project_update_resume_legacy_preplan(
                    inspection_root,
                    resolved=resolved,
                    with_store=with_store,
                    approval_executor=approval_executor,
                    progress_callback=progress_callback,
                    expected_approval_root=expected_approval_root,
                    expected_archive_id=expected_archive_id,
                    key_provider=key_provider,
                    resume_boundary=resume_boundary,
                )
            if terminal_outcome == "success" and locator_state in {
                "fresh_transaction_completed",
                "terminal_completed",
            }:
                if (
                    handoff_state != "terminal_ready"
                    or handoff_observation is None
                ):
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_ambiguous"
                    )
                receipt_sha256 = (
                    resolved.terminal_receipt_document_sha256
                )
                if type(receipt_sha256) is not str:
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_ambiguous"
                    )
                if locator_state == "fresh_transaction_completed":
                    with_store(
                        lambda store: store.publish_terminal_locator_and_retire(
                            intent_sha256=resolved.intent_sha256,
                            journal_head_sha256=resolved.journal_head_sha256,
                            previous_locator_sha256=resolved.locator_sha256,
                            terminal_receipt_sha256=receipt_sha256,
                        )
                    )
                else:
                    with_store(
                        lambda store: store.retire_locator(
                            expected_locator_sha256=resolved.locator_sha256
                        )
                    )
                replayed = _project_update_replay_ready_terminal_handoff(
                    inspection_root,
                    target=None,
                    reviewed_by=None,
                    transaction_ref=None,
                    approval_executor=approval_executor,
                    expected_approval_root=expected_approval_root,
                    expected_archive_id=expected_archive_id,
                    _expected_handoff_observation=handoff_observation,
                    _terminal_control_lease_held=True,
                )
                if replayed is None:
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_ambiguous"
                    )
                return replayed
            if (
                terminal_outcome == "unapproved_restored"
                and locator_state == "unapproved_restored"
            ):
                old_ref = str(resolved.intent.get("old_transaction_ref") or "")
                old_canonical = project_root.joinpath(
                    *PurePosixPath(
                        project_update_transaction.TRANSACTION_ROOT_LOGICAL
                    ).parts,
                    old_ref,
                )
                lock_path = project_root.joinpath(
                    *PurePosixPath(
                        project_update_transaction.PROJECT_UPDATE_LOCK_LOGICAL
                    ).parts
                )
                old_lock = project_update_legacy_recovery._read_regular(
                    lock_path
                )
                if (
                    project_update_legacy_recovery.directory_tree_sha256(
                        old_canonical
                    )
                    != resolved.intent.get("old_transaction_sha256")
                    or project_update_transaction.sha256_bytes(old_lock)
                    != resolved.intent.get("old_lock_sha256")
                ):
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_changed"
                    )
                receipt_sha256 = resolved.terminal_receipt_document_sha256
                cancellation_result_document_sha256 = (
                    resolved.cancellation_result_document_sha256
                )
                if (
                    handoff_state not in {None, "terminal_ready_unapproved"}
                    or type(receipt_sha256) is not str
                    or type(cancellation_result_document_sha256) is not str
                ):
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_ambiguous"
                    )
                pending_terminal = resolved.pending_cancellation_terminal
                expected_result_payload_sha256 = (
                    project_update_transaction.sha256_document(
                        _project_update_legacy_unapproved_restored_result()
                    )
                )
                expected_archive_identity_sha256 = (
                    exact_human_approval_archive_identity_sha256(
                        expected_archive_id
                    )
                )
                if handoff_state == "terminal_ready_unapproved":
                    if (
                        handoff_observation is None
                        or not isinstance(
                            pending_terminal,
                            project_update_legacy_recovery.ResolvedPendingCancellationTerminal,
                        )
                        or pending_terminal.recovery_ref
                        != resolved.paths.recovery_ref
                        or pending_terminal.outcome != "unapproved_restored"
                        or pending_terminal.archive_identity_sha256
                        != expected_archive_identity_sha256
                        or pending_terminal.intent_sha256
                        != resolved.intent_sha256
                        or pending_terminal.journal_head_sha256
                        != resolved.journal_head_sha256
                        or pending_terminal.active_locator_state
                        != "unapproved_restored"
                        or pending_terminal.active_locator_sha256
                        != resolved.locator_sha256
                        or pending_terminal.terminal_receipt_document_sha256
                        != receipt_sha256
                        or pending_terminal.cancellation_result_document_sha256
                        != cancellation_result_document_sha256
                        or pending_terminal.cancellation_result_sha256
                        != resolved.cancellation_result_sha256
                        or pending_terminal.result_payload_sha256
                        != expected_result_payload_sha256
                        or pending_terminal.terminal_handoff_document_sha256
                        != handoff_observation.raw_sha256
                        or re.fullmatch(
                            r"sha256:[0-9a-f]{64}",
                            pending_terminal.delivery_capability_sha256,
                        )
                        is None
                    ):
                        raise ArchiveServiceError(
                            "project_version_update_legacy_recovery_state_ambiguous"
                        )
                elif pending_terminal is not None:
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_ambiguous"
                    )
                handoff_sha256, capability = (
                    _project_update_publish_legacy_cancellation_handoff_exact(
                        project_root=project_root,
                        expected_approval_root=expected_approval_root,
                        expected_archive_id=expected_archive_id,
                        paths=resolved.paths,
                        intent_sha256=resolved.intent_sha256,
                        terminal_receipt_sha256=receipt_sha256,
                        cancellation_result_document_sha256=(
                            cancellation_result_document_sha256
                        ),
                        key_provider=key_provider,
                    )
                )
                if (
                    pending_terminal is not None
                    and (
                        handoff_sha256
                        != pending_terminal.terminal_handoff_document_sha256
                        or project_update_transaction.sha256_bytes(
                            capability.encode("ascii")
                        )
                        != pending_terminal.delivery_capability_sha256
                    )
                ):
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_ambiguous"
                    )
                with_store(
                    lambda store: store.publish_terminal_locator_and_retire(
                        intent_sha256=resolved.intent_sha256,
                        journal_head_sha256=resolved.journal_head_sha256,
                        previous_locator_sha256=resolved.locator_sha256,
                        terminal_receipt_sha256=receipt_sha256,
                    )
                )
                return _project_update_legacy_unapproved_restored_result()

            if (
                resolved.cancellation_result is not None
                and resolved.cancellation_plan is None
            ):
                # The fixed result alone does not prove that an exact native
                # denial was durably bound before destructive cancellation.
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_ambiguous"
                )
            if (
                recovery_branch == "cancellation"
                or resolved.cancellation_plan is not None
            ):
                return _project_update_resume_legacy_cancellation(
                    resolved=resolved,
                    with_store=with_store,
                    expected_approval_root=expected_approval_root,
                    expected_archive_id=expected_archive_id,
                    key_provider=key_provider,
                )

            if (
                not isinstance(plan, Mapping)
                or resolved.fresh_transaction_ref is None
                or plan.get("fresh_transaction_ref")
                != resolved.fresh_transaction_ref
                or plan.get("recovery_ref")
                != resolved.paths.recovery_ref
                or resolved.fresh_reservation is None
                or not isinstance(
                    resolved.fresh_transaction_inventory, Mapping
                )
                or type(
                    resolved.fresh_transaction_inventory_document_sha256
                )
                is not str
                or resolved.fresh_reservation.get(
                    "fresh_transaction_ref"
                )
                != resolved.fresh_transaction_ref
            ):
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_ambiguous"
                )

            fresh_root = project_root.joinpath(
                *PurePosixPath(
                    project_update_transaction.TRANSACTION_ROOT_LOGICAL
                ).parts,
                resolved.fresh_transaction_ref,
            )
            live_fresh_inventory = (
                project_update_legacy_recovery.directory_tree_inventory(
                    fresh_root,
                    progress_callback=(
                        (
                            lambda count, byte_count: progress_callback(
                                "project-recovery-inventory",
                                "running",
                                count,
                                byte_count,
                            )
                        )
                        if progress_callback is not None
                        else None
                    ),
                )
            )

            lock_path = project_root.joinpath(
                *PurePosixPath(
                    project_update_transaction.PROJECT_UPDATE_LOCK_LOGICAL
                ).parts
            )
            old_lock_sha256 = str(
                resolved.intent.get("old_lock_sha256") or ""
            )
            old_lock_bytes = _project_update_legacy_old_lock_bytes(
                resolved
            )
            fresh_reservation_for_lock = (
                project_update_transaction.ReservedProjectUpdateTransaction.open(
                    project_root,
                    resolved.fresh_transaction_ref,
                )
            )
            fresh_lock_bytes = fresh_reservation_for_lock.lock_bytes()
            suffix = resolved.paths.recovery_ref.removeprefix("recovery_")
            replacement_path = lock_path.parent / (
                f".legacy-recovery-{suffix}.fresh-lock"
            )
            public_backup_path = lock_path.parent / (
                f".legacy-recovery-{suffix}.old-lock"
            )
            if os.path.lexists(replacement_path) or os.path.lexists(
                public_backup_path
            ):
                lock_handoff_state = (
                    project_update_legacy_recovery.classify_lock_handoff(
                        resolved.paths,
                        old_lock_bytes,
                        fresh_lock_bytes,
                    )
                )
                if lock_handoff_state not in {
                    "old",
                    "backup_linked",
                    "fresh",
                }:
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_lock_ambiguous"
                    )
                old_lock_active = lock_handoff_state in {
                    "old",
                    "backup_linked",
                }
                live_lock_bytes: bytes | None = (
                    old_lock_bytes if old_lock_active else fresh_lock_bytes
                )
            else:
                live_lock_bytes = (
                    project_update_legacy_recovery._read_regular(lock_path)
                    if os.path.lexists(lock_path)
                    else None
                )
                old_lock_active = bool(
                    live_lock_bytes is not None
                    and hmac.compare_digest(
                        live_lock_bytes,
                        old_lock_bytes,
                    )
                )
                if live_lock_bytes is not None and not (
                    old_lock_active
                    or hmac.compare_digest(
                        live_lock_bytes,
                        fresh_lock_bytes,
                    )
                ):
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_lock_ambiguous"
                    )
                lock_handoff_state = (
                    "old"
                    if old_lock_active
                    else "fresh"
                    if live_lock_bytes is not None
                    else "absent"
                )

            control: dict[str, Any] = {
                "paths": resolved.paths,
                "old_transaction_ref": resolved.intent[
                    "old_transaction_ref"
                ],
                "old_transaction_tree_sha256": resolved.intent[
                    "old_transaction_sha256"
                ],
                "old_lock_bytes": old_lock_bytes,
                "old_lock_sha256": old_lock_sha256,
                "lock_handoff_state": lock_handoff_state,
                "old_abandonment_sha256": plan[
                    "old_abandonment_sha256"
                ],
                "intent_sha256": resolved.intent_sha256,
                "journal_head_sha256": resolved.journal_head_sha256,
                "locator_sha256": resolved.locator_sha256,
                "with_store": with_store,
                "progress_callback": progress_callback,
                "approval_key_provider": key_provider,
                "fresh_transaction_inventory": dict(
                    resolved.fresh_transaction_inventory
                ),
                "fresh_transaction_inventory_document_sha256": (
                    resolved.fresh_transaction_inventory_document_sha256
                ),
                "fresh_prospective_plan": dict(plan),
                "fresh_prospective_plan_sha256": (
                    resolved.prospective_plan_document_sha256
                ),
                "fresh_recovery_binding_sha256": plan[
                    "fresh_recovery_binding_sha256"
                ],
                "recovery_phase": locator_state,
            }
            state, lifetime = _project_update_reopen_durable_state(
                inspection_root,
                target=None,
                reviewed_by=None,
                transaction_ref=None,
                expected_approval_root=expected_approval_root,
                expected_archive_id=expected_archive_id,
                _authenticated_recovery_transaction_ref=(
                    resolved.fresh_transaction_ref
                ),
                _legacy_recovery_control=control,
            )
            try:
                fresh_binding = project_version_update_approval_binding(
                    state.prepared_preview
                )
                fresh_context = fresh_binding.context(
                    archive_id=expected_archive_id,
                    reviewer_claim=state.reviewer,
                )
                control["confirm_fresh_claim_absent"] = (
                    lambda candidate_context: (
                        _project_update_confirm_context_claim_absent(
                            expected_approval_root=expected_approval_root,
                            context=candidate_context,
                            key_provider=key_provider,
                            resume_boundary=resume_boundary,
                        )
                    )
                )
            except BaseException:
                _project_update_close_after_service_failure(
                    state.directory_guard.close,
                    lifetime,
                )
                raise
            continuation_used = False
            fresh_claim_absence_authenticated = False
            native_approval_attempted = False
            try:
                if (
                    state.transaction.intent.project_identity_sha256
                    != resolved.intent.get("project_identity_sha256")
                    or state.transaction.intent.sha256
                    != plan.get("fresh_intent_sha256")
                    or state.transaction.intent.reservation_sha256
                    != resolved.fresh_reservation.get(
                        "fresh_reservation_sha256"
                    )
                    or resolved.fresh_reservation.get(
                        "old_abandonment_sha256"
                    )
                    != plan.get("old_abandonment_sha256")
                    or fresh_binding.plan_sha256
                    != plan.get("fresh_approval_plan_sha256")
                    or fresh_binding.target_binding_sha256
                    != plan.get(
                        "fresh_approval_target_binding_sha256"
                    )
                    or exact_human_approval_context_sha256(fresh_context)
                    != plan.get("fresh_approval_context_sha256")
                ):
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_changed"
                    )
                reservation_checkpoint = next(
                    (
                        item
                        for item in resolved.checkpoints
                        if item.get("phase") == "fresh_reservation_bound"
                    ),
                    None,
                )
                plan_checkpoint = next(
                    (
                        item
                        for item in resolved.checkpoints
                        if item.get("phase") == "fresh_plan_sealed"
                    ),
                    None,
                )
                if (
                    reservation_checkpoint is None
                    or plan_checkpoint is None
                    or reservation_checkpoint.get("evidence_sha256")
                    != resolved.fresh_reservation_document_sha256
                    or plan_checkpoint.get("evidence_sha256")
                    != resolved.prospective_plan_document_sha256
                ):
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_changed"
                    )
                fresh_journal = state.transaction.inspect().journal
                fresh_checkpoints = tuple(fresh_journal.verified_prefix)
                if fresh_journal.state != "exact":
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_changed"
                    )
                if old_lock_active:
                    if (
                        fresh_checkpoints
                        or project_update_legacy_recovery.sha256_document(
                            live_fresh_inventory
                        )
                        != plan.get(
                            "fresh_transaction_inventory_sha256"
                        )
                    ):
                        raise ArchiveServiceError(
                            "project_version_update_legacy_recovery_state_changed"
                        )
                elif live_lock_bytes == state.expected_lock_bytes:
                    if fresh_checkpoints and (
                        fresh_checkpoints[0].phase != "lock_backlinked"
                    ):
                        raise ArchiveServiceError(
                            "project_version_update_legacy_recovery_state_changed"
                        )
                elif live_lock_bytes is None:
                    if (
                        not fresh_checkpoints
                        or fresh_checkpoints[-1].phase
                        not in {"lock_released", "completed"}
                        or locator_state
                        not in {
                            "fresh_lock_backlinked",
                            "fresh_transaction_completed",
                            "terminal_completed",
                        }
                    ):
                        raise ArchiveServiceError(
                            "project_version_update_legacy_recovery_lock_ambiguous"
                        )
                else:
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_lock_ambiguous"
                    )

                if handoff_state == "terminal_ready":
                    if (
                        handoff_observation is None
                        or live_lock_bytes is not None
                        or not fresh_checkpoints
                        or fresh_checkpoints[-1].phase != "completed"
                    ):
                        raise ArchiveServiceError(
                            "project_version_update_legacy_recovery_state_ambiguous"
                        )

                    def terminalize_ready_recovery(
                        claim: _ClaimedExactHumanApproval,
                    ) -> None:
                        terminal_evidence = claim.succeeded_evidence_digests(
                            fresh_context
                        )
                        terminal_evidence["static_receipt_sha256"] = (
                            project_update_transaction.sha256_bytes(
                                state.static_receipt_bytes
                            )
                        )
                        _project_update_finalize_legacy_recovery_success(
                            state,
                            claim_evidence=terminal_evidence,
                            fresh_transaction_completed_sha256=(
                                fresh_checkpoints[-1].checkpoint_sha256
                            ),
                        )

                    replayed = _project_update_replay_ready_terminal_handoff(
                        inspection_root,
                        target=None,
                        reviewed_by=None,
                        transaction_ref=None,
                        approval_executor=approval_executor,
                        expected_approval_root=expected_approval_root,
                        expected_archive_id=expected_archive_id,
                        _expected_handoff_observation=handoff_observation,
                        _terminal_control_lease_held=True,
                        _legacy_recovery_terminalizer=(
                            terminalize_ready_recovery
                        ),
                    )
                    if replayed is None:
                        raise ArchiveServiceError(
                            "project_version_update_legacy_recovery_state_ambiguous"
                        )
                    return _project_update_finish_nonterminal_service_result(
                        replayed,
                        lifetime,
                        close_owned_resources=state.directory_guard.close,
                    )
                if handoff_state not in {
                    None,
                    "claim_succeeded_pre_unlock",
                }:
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_state_ambiguous"
                    )

                def continue_started_claim(
                    claim: _ClaimedExactHumanApproval,
                    expected_plan_sha256: str,
                    expected_target_binding_sha256: str,
                ) -> Mapping[str, Any]:
                    nonlocal continuation_used
                    assert_same_binding(
                        fresh_binding,
                        expected_plan_sha256=expected_plan_sha256,
                        expected_target_binding_sha256=(
                            expected_target_binding_sha256
                        ),
                    )
                    state.approved_plan_sha256 = fresh_binding.plan_sha256
                    state.approved_target_binding_sha256 = (
                        fresh_binding.target_binding_sha256
                    )
                    if continuation_used:
                        raise ArchiveServiceError(
                            "project_version_update_approval_continuation_reused"
                        )
                    continuation_used = True
                    _project_update_activate_legacy_recovery_state(state)
                    return _project_update_durable_writer(state, claim)

                def finalize_succeeded_claim(
                    claim: _ClaimedExactHumanApproval,
                ) -> None:
                    _project_update_succeeded_claim_finalizer(state, claim)

                def started_guard(
                    claim: _ClaimedExactHumanApproval,
                ) -> bool:
                    state.approved_plan_sha256 = fresh_binding.plan_sha256
                    state.approved_target_binding_sha256 = (
                        fresh_binding.target_binding_sha256
                    )
                    if state.transaction.inspect().journal.verified_prefix:
                        return _project_update_claim_checkpoint_guard(
                            state, claim, succeeded=False
                        )
                    return bool(
                        old_lock_active
                        and _project_update_legacy_recovery_preapproval_state_exact(
                            state
                        )
                    )

                def succeeded_guard(
                    claim: _ClaimedExactHumanApproval,
                ) -> bool:
                    state.approved_plan_sha256 = fresh_binding.plan_sha256
                    state.approved_target_binding_sha256 = (
                        fresh_binding.target_binding_sha256
                    )
                    return _project_update_claim_checkpoint_guard(
                        state, claim, succeeded=True
                    )

                no_claim = {"legacy_recovery_claim_missing": True}

                def authenticated_candidate_missing(
                    _approval_id: str,
                ) -> Mapping[str, Any]:
                    nonlocal fresh_claim_absence_authenticated
                    fresh_claim_absence_authenticated = True
                    return dict(no_claim)

                with _project_update_terminal_execution_lease(
                    state,
                    expected_handoff_observation=(
                        handoff_observation
                        if handoff_state == "claim_succeeded_pre_unlock"
                        else None
                    ),
                    fresh_absence=False,
                ):
                    result = approval_executor(
                        copy.deepcopy(state.prepared_preview),
                        continue_started_claim,
                        finalize_succeeded_claim,
                        started_guard,
                        succeeded_guard,
                        state.reviewer,
                        candidate_missing_handler=(
                            authenticated_candidate_missing
                        ),
                        resume_existing_composite=True,
                    )
                    if (
                        isinstance(result, Mapping)
                        and result.get("legacy_recovery_claim_missing")
                        is True
                    ):
                        if not old_lock_active:
                            raise ArchiveServiceError(
                                "project_version_update_legacy_recovery_state_ambiguous"
                            )
                        native_approval_attempted = True
                        result = approval_executor(
                            copy.deepcopy(state.prepared_preview),
                            continue_started_claim,
                            finalize_succeeded_claim,
                            started_guard,
                            succeeded_guard,
                            claim_publication_boundary=lambda: (
                                _project_update_claim_publication_boundary(
                                    state
                                )
                            ),
                            recovery_key_provider=key_provider,
                        )
                    if not isinstance(result, Mapping):
                        raise ArchiveServiceError(
                            "project_version_update_result_invalid"
                        )
                    completed_result = dict(result)
                    report(
                        "write-receipt",
                        "resume-legacy-terminal-result",
                    )
            except BaseException as failure:
                if (
                    not continuation_used
                    and old_lock_active
                    and fresh_claim_absence_authenticated
                    and native_approval_attempted
                    and _project_update_is_exact_native_approval_denial(
                        failure
                    )
                ):
                    restored_result = (
                        _project_update_restore_legacy_recovery_after_unapproved(
                            state
                        )
                    )
                    if not _project_update_is_legacy_unapproved_terminal_result(
                        restored_result
                    ):
                        raise ArchiveServiceError(
                            "project_version_update_legacy_recovery_state_ambiguous"
                        )
                    return _project_update_finish_legacy_cancellation_result(
                        restored_result,
                        lifetime,
                        close_owned_resources=state.directory_guard.close,
                    )
                _project_update_close_after_service_failure(
                    state.directory_guard.close,
                    lifetime,
                )
                raise
            if not continuation_used:
                # A returned mapping is not cancellation authority.  The
                # production native broker represents a human denial only as
                # the exact typed ``exact_human_approval_cancelled`` error
                # handled above.  Preserve every recovery artifact for any
                # continuation-free or injected mapping instead of turning it
                # into destructive rollback permission.
                _project_update_close_after_service_failure(
                    state.directory_guard.close,
                    lifetime,
                )
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_ambiguous"
                )
            return _project_update_finish_service_result(
                completed_result,
                state,
                lifetime,
                close_owned_resources=state.directory_guard.close,
            )
    except ArchiveServiceError:
        raise
    except project_update_legacy_recovery.LegacyProjectUpdateRecoveryError as failure:
        raise ArchiveServiceError(failure.code) from None
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        ) from None


def _wom_kit_project_version_update_resume_live_transaction(
    inspection_root: Path | str,
    *,
    target: str | None,
    reviewed_by: str | None,
    transaction_ref: str | None,
    approval_executor: Callable[..., Mapping[str, Any]],
    progress_callback: (
        Callable[[str, str, int | None, int | None], None] | None
    ) = None,
    _expected_approval_root: Path,
    _expected_archive_id: str,
    _approval_identifier_supplied: bool = False,
    _archive_identity_metadata_read: bool = False,
    _legacy_recovery_key_provider: Any | None = None,
    _legacy_recovery_resume_boundary: (
        Callable[[], Any] | None
    ) = None,
) -> dict[str, Any]:
    """Resume an authenticated claim/transaction pair with zero new native UI."""

    def report_progress(stage: str, event: str) -> None:
        if progress_callback is None:
            return
        try:
            progress_callback(stage, event, None, None)
        except Exception:
            # Progress is observational. A terminal result must never be
            # rewritten by a console, log, or operation-journal callback.
            return

    if not callable(approval_executor):
        raise ArchiveServiceError(
            "project_version_update_live_approval_executor_required"
        )
    if (
        type(_approval_identifier_supplied) is not bool
        or type(_archive_identity_metadata_read) is not bool
    ):
        raise ArchiveServiceError(
            "exact_human_approval_resume_claim_invalid"
        )
    report_progress("project-preflight", "resume-start")
    operator_resume_identifiers_supplied = bool(
        str(target or "").strip()
        or str(transaction_ref or "").strip()
        or str(reviewed_by or "").strip()
        or _approval_identifier_supplied
    )
    project_root = _project_update_resume_project_root_read_only(
        inspection_root
    )
    legacy_locator_presence = (
        project_update_legacy_recovery.active_locator_presence_read_only(
            project_root
        )
    )
    if legacy_locator_presence == "present_unverified":
        if (
            operator_resume_identifiers_supplied
            or _legacy_recovery_key_provider is None
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_binding_invalid"
            )
        return _project_update_resume_active_legacy_recovery(
            inspection_root,
            project_root=project_root,
            approval_executor=approval_executor,
            progress_callback=progress_callback,
            expected_approval_root=_expected_approval_root,
            expected_archive_id=_expected_archive_id,
            key_provider=_legacy_recovery_key_provider,
            resume_boundary=_legacy_recovery_resume_boundary,
        )
    if legacy_locator_presence in {"unsafe", "unavailable"}:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )
    initial_handoff_observation: list[
        _ProjectUpdateTerminalHandoffObservation | None
    ] = []
    cleanup_unknown = (
        _project_update_terminal_cleanup_unknown_gate_read_only(
            inspection_root,
            operator_resume_identifiers_supplied=(
                operator_resume_identifiers_supplied
            ),
            archive_identity_metadata_read=(
                _archive_identity_metadata_read
            ),
            _handoff_observation_out=initial_handoff_observation,
        )
    )
    if cleanup_unknown is not None:
        if _approval_identifier_supplied:
            raise ArchiveServiceError(
                "exact_human_approval_resume_claim_invalid"
            )
        return cleanup_unknown
    if len(initial_handoff_observation) != 1:
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    initial_handoff = initial_handoff_observation[0]
    if (
        initial_handoff is not None
        and initial_handoff.state == "terminal_ready_unapproved"
    ):
        if (
            operator_resume_identifiers_supplied
            or _legacy_recovery_key_provider is None
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        with _project_update_terminal_control_boundary(project_root):
            handoff_path, _guard = _project_update_terminal_handoff_paths(
                project_root
            )
            observed = _project_update_read_terminal_document(
                project_root,
                handoff_path,
            )
            if (
                observed is None
                or observed[0].get("state") != "terminal_ready_unapproved"
                or not hmac.compare_digest(
                    project_update_transaction.sha256_bytes(observed[1]),
                    initial_handoff.raw_sha256,
                )
            ):
                raise ArchiveServiceError(
                    "project_version_update_terminal_handoff_invalid"
                )
            cancellation_result = (
                project_update_legacy_recovery.cancellation_result_document()
            )
            _project_update_reauthenticate_cancellation_terminal_delivery(
                inspection_root,
                capsule_bytes=observed[1],
                expected_handoff_sha256=initial_handoff.raw_sha256,
                expected_result=cancellation_result,
                key_provider=_legacy_recovery_key_provider,
                expected_approval_root=_expected_approval_root,
                expected_archive_id=_expected_archive_id,
                _terminal_control_lease_held=True,
            )
        report_progress(
            "write-receipt",
            "resume-unapproved-terminal-result-replayed",
        )
        return cancellation_result
    active_transaction_ref: str | None = None
    try:
        active_transaction_ref = (
            project_update_transaction
            .active_transaction_ref_for_resume_read_only(project_root)
        )
        active_transaction_observed = True
    except project_update_transaction.ProjectUpdateTransactionError as failure:
        if failure.code == "project_update_transaction_not_found":
            active_transaction_observed = False
        else:
            return _project_update_terminal_cleanup_outcome_unknown_result(
                operator_resume_identifiers_supplied=(
                    operator_resume_identifiers_supplied
                ),
                archive_identity_metadata_read=(
                    _archive_identity_metadata_read
                ),
            )
    cleanup_classification, _history_count = (
        _project_update_terminal_cleanup_artifact_classification_read_only(
            project_root
        )
    )
    compacted_abort_history_count = 0
    abort_compaction_outcome: (
        _ProjectUpdateAbortHistoryCompactionOutcome | None
    ) = None

    def attach_abort_compaction_effect(
        result: Mapping[str, Any],
    ) -> dict[str, Any]:
        if (
            abort_compaction_outcome is None
            or (
                abort_compaction_outcome.completed_count == 0
                and not abort_compaction_outcome.incomplete
            )
        ):
            return dict(result)
        return _project_update_attach_abort_history_compaction_effect(
            result,
            abort_compaction_outcome,
        )

    if cleanup_classification in {
        "recoverable_exact",
        "resume_required_exact",
        "terminal_history_exact",
        "terminal_original_exact",
    }:
        if not _wom_kit_project_version_update_approval_authority_matches(
            inspection_root,
            expected_root=_expected_approval_root,
            expected_archive_id=_expected_archive_id,
        ):
            raise ArchiveServiceError(
                "project_version_update_approval_archive_identity_changed"
            )
        exact_preapproval_resume = (
            None
            if active_transaction_ref is None
            else _project_update_exact_preapproval_resume_classification_read_only(
                project_root,
                active_transaction_ref,
            )
        )
        runtime_cleanup_resume_pending = (
            False
            if active_transaction_ref is None
            else _project_update_runtime_cleanup_sidecar_pending_read_only(
                project_root=project_root,
                transaction_ref=active_transaction_ref,
            )
        )
        if runtime_cleanup_resume_pending is None:
            return attach_abort_compaction_effect(
                _project_update_terminal_cleanup_outcome_unknown_result(
                    operator_resume_identifiers_supplied=(
                        operator_resume_identifiers_supplied
                    ),
                    archive_identity_metadata_read=True,
                )
            )
        skip_abort_history_compaction = bool(
            cleanup_classification == "resume_required_exact"
            and (
                os.path.lexists(
                    project_root.joinpath(
                        *PurePosixPath(
                            project_update_transaction
                            .PROJECT_UPDATE_LOCK_LOGICAL
                        ).parts
                    )
                )
                or exact_preapproval_resume is not None
                or runtime_cleanup_resume_pending
            )
        )
        if not skip_abort_history_compaction:
            abort_compaction_outcome = (
                _project_update_compact_exact_abort_histories_for_resume(
                    project_root
                )
            )
            if abort_compaction_outcome.incomplete:
                return attach_abort_compaction_effect(
                    _project_update_terminal_cleanup_outcome_unknown_result(
                        operator_resume_identifiers_supplied=(
                            operator_resume_identifiers_supplied
                        ),
                        archive_identity_metadata_read=True,
                    )
                )
            compacted_abort_history_count = (
                abort_compaction_outcome.completed_count
            )
        if compacted_abort_history_count:
            report_progress(
                "project-preflight",
                "resume-terminal-abort-history-compacted",
            )
        cleanup_classification, _history_count = (
            _project_update_terminal_cleanup_artifact_classification_read_only(
                project_root
            )
        )
        active_transaction_ref = None
        try:
            active_transaction_ref = (
                project_update_transaction
                .active_transaction_ref_for_resume_read_only(project_root)
            )
            active_transaction_observed = True
        except project_update_transaction.ProjectUpdateTransactionError as failure:
            if failure.code == "project_update_transaction_not_found":
                active_transaction_observed = False
            else:
                return attach_abort_compaction_effect(
                    _project_update_terminal_cleanup_outcome_unknown_result(
                        operator_resume_identifiers_supplied=(
                            operator_resume_identifiers_supplied
                        ),
                        archive_identity_metadata_read=True,
                    )
                )
        if (
            compacted_abort_history_count
            and not active_transaction_observed
            and cleanup_classification in {"absent", "history_only_exact"}
        ):
            compacted_result = _project_update_abort_history_compacted_result(
                compacted_count=compacted_abort_history_count
            )
            compacted_result["operator_resume_identifiers_supplied"] = bool(
                operator_resume_identifiers_supplied
            )
            return compacted_result
    if cleanup_classification == "unresolved":
        return attach_abort_compaction_effect(
            _project_update_terminal_cleanup_outcome_unknown_result(
                operator_resume_identifiers_supplied=(
                    operator_resume_identifiers_supplied
                ),
                archive_identity_metadata_read=True,
            )
        )
    if (
        not active_transaction_observed
        and cleanup_classification == "recoverable_exact"
    ):
        tombstone = (
            project_update_transaction.ProjectUpdateTransaction
            .discover_complete_cleanup_tombstone_for_resume_read_only(
                project_root
            )
        )
        supplied_transaction_ref = str(transaction_ref or "").strip()
        if (
            tombstone is None
            or (
                supplied_transaction_ref
                and supplied_transaction_ref
                != tombstone.transaction_ref
            )
        ):
            raise ArchiveServiceError(
                "project_version_update_resume_binding_mismatch"
            )
        restored = (
            project_update_transaction.ProjectUpdateTransaction
            .restore_complete_cleanup_tombstone_for_resume(
                project_root,
                tombstone,
            )
        )
        if (
            restored.transaction_ref != tombstone.transaction_ref
            or restored.cleanup_authority_sha256_read_only()
            != tombstone.cleanup_authority_sha256
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_cleanup_authority_invalid"
            )
        report_progress(
            "project-preflight",
            "resume-complete-cleanup-tombstone-restored",
        )
        # v0.4.18: the restored original may already be the exact
        # terminal-original shape.  Re-classify so the handoff-less arm
        # below can finish its private cleanup without routing a superseded
        # transaction into claim rediscovery.
        active_transaction_ref = restored.transaction_ref
        active_transaction_observed = True
        cleanup_classification, _history_count = (
            _project_update_terminal_cleanup_artifact_classification_read_only(
                project_root
            )
        )
    elif (
        not active_transaction_observed
        and cleanup_classification not in {
        "absent",
        "history_only_exact",
        }
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_cleanup_recovery_required"
        )
    current_handoff_observation: list[
        _ProjectUpdateTerminalHandoffObservation | None
    ] = []
    try:
        terminal_handoff_state = (
            _project_update_terminal_handoff_state_read_only(
                inspection_root,
                _observation_out=current_handoff_observation,
            )
        )
    except ArchiveServiceError as failure:
        if (
            len(failure.args) == 1
            and type(failure.args[0]) is str
            and failure.args[0]
            == "project_version_update_terminal_handoff_invalid"
        ):
            return attach_abort_compaction_effect(
                _project_update_terminal_cleanup_outcome_unknown_result(
                    operator_resume_identifiers_supplied=(
                        operator_resume_identifiers_supplied
                    ),
                    archive_identity_metadata_read=(
                        _archive_identity_metadata_read
                    ),
                )
            )
        raise
    if (
        len(current_handoff_observation) != 1
        or current_handoff_observation
        != initial_handoff_observation
    ):
        return attach_abort_compaction_effect(
            _project_update_terminal_cleanup_outcome_unknown_result(
                operator_resume_identifiers_supplied=(
                    operator_resume_identifiers_supplied
                ),
                archive_identity_metadata_read=(
                    _archive_identity_metadata_read
                ),
            )
        )
    terminal_original_fallback: Any = None
    if (
        active_transaction_observed
        and active_transaction_ref is not None
        and cleanup_classification == "terminal_original_exact"
        and terminal_handoff_state is None
    ):
        # v0.4.18: a completed original whose post-image was later superseded
        # cannot pass the succeeded-claim live guard and must never be routed
        # into claimless preapproval cancellation.  Finish only its private
        # control cleanup under the journal's re-authenticated authority.
        if _approval_identifier_supplied:
            raise ArchiveServiceError(
                "exact_human_approval_resume_claim_invalid"
            )
        supplied_transaction_ref = str(transaction_ref or "").strip()
        if (
            supplied_transaction_ref
            and supplied_transaction_ref != active_transaction_ref
        ):
            raise ArchiveServiceError(
                "project_version_update_resume_binding_mismatch"
            )
        terminal_inspection = (
            project_update_transaction
            .inspect_terminal_original_for_resume_read_only(
                project_root,
                active_transaction_ref,
            )
        )
        if terminal_inspection is None:
            return attach_abort_compaction_effect(
                _project_update_terminal_cleanup_outcome_unknown_result(
                    operator_resume_identifiers_supplied=(
                        operator_resume_identifiers_supplied
                    ),
                    archive_identity_metadata_read=True,
                )
            )
        if _project_update_terminal_original_postimage_superseded_read_only(
            project_root,
            active_transaction_ref,
        ):
            return attach_abort_compaction_effect(
                _project_update_resume_terminal_original_cleanup(
                    inspection_root,
                    project_root=project_root,
                    transaction_ref=active_transaction_ref,
                    terminal_inspection=terminal_inspection,
                    operator_resume_identifiers_supplied=(
                        operator_resume_identifiers_supplied
                    ),
                    expected_approval_root=_expected_approval_root,
                    expected_archive_id=_expected_archive_id,
                    report_progress=report_progress,
                    route="direct",
                )
            )
        # The live pin still equals the transaction post-image, so the
        # v0.4.16 replay contract (claim rediscovery, terminal handoff, bound
        # result) stays the route.  Terminal-original cleanup is the fallback
        # only when that contract refuses through its fixed candidate-missing
        # gate, which is the exact dead end this release closes.
        terminal_original_fallback = terminal_inspection
    if terminal_handoff_state == "terminal_ready":
        try:
            replayed = _project_update_replay_ready_terminal_handoff(
                inspection_root,
                target=target,
                reviewed_by=reviewed_by,
                transaction_ref=transaction_ref,
                approval_executor=approval_executor,
                expected_approval_root=_expected_approval_root,
                expected_archive_id=_expected_archive_id,
                _expected_handoff_observation=(
                    current_handoff_observation[0]
                ),
            )
        except ArchiveServiceError as failure:
            if (
                len(failure.args) == 1
                and type(failure.args[0]) is str
                and failure.args[0]
                == "project_version_update_terminal_handoff_invalid"
            ):
                return attach_abort_compaction_effect(
                    _project_update_terminal_cleanup_outcome_unknown_result(
                        operator_resume_identifiers_supplied=(
                            operator_resume_identifiers_supplied
                        ),
                        archive_identity_metadata_read=(
                            _archive_identity_metadata_read
                        ),
                    )
                )
            raise
        if replayed is None:
            return attach_abort_compaction_effect(
                _project_update_terminal_cleanup_outcome_unknown_result(
                    operator_resume_identifiers_supplied=(
                        operator_resume_identifiers_supplied
                    ),
                    archive_identity_metadata_read=(
                        _archive_identity_metadata_read
                    ),
                )
            )
        report_progress("write-receipt", "resume-terminal-result-replayed")
        return attach_abort_compaction_effect(replayed)
    preapproval_recovery: dict[str, Any] | None = None
    for attempt in range(2):
        if attempt:
            cleanup_unknown = (
                _project_update_terminal_cleanup_unknown_gate_read_only(
                    inspection_root,
                    operator_resume_identifiers_supplied=(
                        operator_resume_identifiers_supplied
                    ),
                    archive_identity_metadata_read=(
                        _archive_identity_metadata_read
                    ),
                )
            )
            if cleanup_unknown is not None:
                if _approval_identifier_supplied:
                    raise ArchiveServiceError(
                        "exact_human_approval_resume_claim_invalid"
                    )
                return attach_abort_compaction_effect(cleanup_unknown)
        try:
            preapproval_recovery = (
                _project_update_resume_preapproval_transaction(
                    inspection_root,
                    target=target,
                    reviewed_by=reviewed_by,
                    transaction_ref=transaction_ref,
                    expected_approval_root=_expected_approval_root,
                    expected_archive_id=_expected_archive_id,
                    approval_identifier_supplied=(
                        _approval_identifier_supplied
                    ),
                )
            )
            break
        except project_update_transaction.ProjectUpdateTransactionError as failure:
            if (
                failure.code != "project_update_transaction_not_found"
                or attempt != 0
            ):
                raise
    else:
        raise ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    if preapproval_recovery is not None:
        return attach_abort_compaction_effect(preapproval_recovery)
    try:
        state, lifetime = _project_update_reopen_durable_state(
            inspection_root,
            target=target,
            reviewed_by=reviewed_by,
            transaction_ref=transaction_ref,
            expected_approval_root=_expected_approval_root,
            expected_archive_id=_expected_archive_id,
        )
    except project_update_transaction.ProjectUpdateTransactionError as failure:
        if failure.code != "project_update_transaction_not_found":
            raise
        cleanup_unknown = (
            _project_update_terminal_cleanup_unknown_gate_read_only(
                inspection_root,
                operator_resume_identifiers_supplied=(
                    operator_resume_identifiers_supplied
                ),
                archive_identity_metadata_read=(
                    _archive_identity_metadata_read
                ),
            )
        )
        if cleanup_unknown is not None:
            if _approval_identifier_supplied:
                raise ArchiveServiceError(
                    "exact_human_approval_resume_claim_invalid"
                )
            return attach_abort_compaction_effect(cleanup_unknown)
        raise

    report_progress("verify-release", "resume-authenticated-state")

    legacy_recovery_result = (
        _project_update_resume_legacy_approval_bound_prewrite(
            state,
            lifetime=lifetime,
            approval_executor=approval_executor,
            progress_callback=progress_callback,
            key_provider=_legacy_recovery_key_provider,
            resume_boundary=_legacy_recovery_resume_boundary,
        )
    )
    if legacy_recovery_result is not None:
        return attach_abort_compaction_effect(legacy_recovery_result)

    def continue_started_claim(
        claim: _ClaimedExactHumanApproval,
        expected_plan_sha256: str,
        expected_target_binding_sha256: str,
    ) -> Mapping[str, Any]:
        binding = project_version_update_approval_binding(
            state.prepared_preview
        )
        assert_same_binding(
            binding,
            expected_plan_sha256=expected_plan_sha256,
            expected_target_binding_sha256=(
                expected_target_binding_sha256
            ),
        )
        state.approved_plan_sha256 = binding.plan_sha256
        state.approved_target_binding_sha256 = (
            binding.target_binding_sha256
        )
        return _project_update_durable_writer(state, claim)

    def finalize_succeeded_claim(
        claim: _ClaimedExactHumanApproval,
    ) -> None:
        _project_update_succeeded_claim_finalizer(state, claim)

    def started_guard(claim: _ClaimedExactHumanApproval) -> bool:
        binding = project_version_update_approval_binding(
            state.prepared_preview
        )
        state.approved_plan_sha256 = binding.plan_sha256
        state.approved_target_binding_sha256 = (
            binding.target_binding_sha256
        )
        return _project_update_claim_checkpoint_guard(
            state,
            claim,
            succeeded=False,
        )

    def succeeded_guard(claim: _ClaimedExactHumanApproval) -> bool:
        binding = project_version_update_approval_binding(
            state.prepared_preview
        )
        state.approved_plan_sha256 = binding.plan_sha256
        state.approved_target_binding_sha256 = (
            binding.target_binding_sha256
        )
        return _project_update_claim_checkpoint_guard(
            state,
            claim,
            succeeded=True,
        )

    candidate_missing_handler = _project_update_candidate_missing_handler(
        state,
        operator_resume_identifiers_supplied=bool(
            str(target or "").strip()
            or str(transaction_ref or "").strip()
            or str(reviewed_by or "").strip()
            or _approval_identifier_supplied
        ),
    )
    try:
        with _project_update_terminal_execution_lease(
            state,
            expected_handoff_observation=(
                initial_handoff_observation[0]
            ),
            fresh_absence=False,
        ):
            result = approval_executor(
                copy.deepcopy(state.prepared_preview),
                continue_started_claim,
                finalize_succeeded_claim,
                started_guard,
                succeeded_guard,
                state.reviewer,
                candidate_missing_handler=candidate_missing_handler,
            )
            if not isinstance(result, Mapping):
                raise ArchiveServiceError(
                    "project_version_update_result_invalid"
                )
            completed_result = dict(result)
            report_progress("write-receipt", "resume-terminal-result")
    except BaseException as failure:
        _project_update_close_after_service_failure(
            state.directory_guard.close,
            lifetime,
        )
        if (
            terminal_original_fallback is not None
            and active_transaction_ref is not None
            and getattr(failure, "cause_code", None)
            == "project_version_update_preapproval_recovery_failed"
            and getattr(failure, "cause_stage", None)
            == "candidate_missing_handler"
        ):
            # v0.4.18: the replay contract found no checkpoint-valid claim
            # and its only fallback (claimless preapproval cancellation)
            # refused the completed journal.  Nothing was written.  Finish
            # the exact private control cleanup instead of masking the gate.
            report_progress(
                "project-preflight",
                "resume-terminal-original-fallback",
            )
            return attach_abort_compaction_effect(
                _project_update_resume_terminal_original_cleanup(
                    inspection_root,
                    project_root=project_root,
                    transaction_ref=active_transaction_ref,
                    terminal_inspection=terminal_original_fallback,
                    operator_resume_identifiers_supplied=(
                        operator_resume_identifiers_supplied
                    ),
                    expected_approval_root=_expected_approval_root,
                    expected_archive_id=_expected_archive_id,
                    report_progress=report_progress,
                    route="fallback_after_generic_resume_refusal",
                )
            )
        if (
            type(failure) is ArchiveServiceError
            and len(failure.args) == 1
            and type(failure.args[0]) is str
            and failure.args[0]
            == "project_version_update_terminal_execution_boundary_unknown"
        ):
            return attach_abort_compaction_effect(
                _project_update_terminal_cleanup_outcome_unknown_result(
                    operator_resume_identifiers_supplied=(
                        operator_resume_identifiers_supplied
                    ),
                    archive_identity_metadata_read=(
                        _archive_identity_metadata_read
                    ),
                )
            )
        raise
    return attach_abort_compaction_effect(
        _project_update_finish_service_result(
            completed_result,
            state,
            lifetime,
            close_owned_resources=state.directory_guard.close,
        )
    )


def _wom_kit_project_version_update_cancel_claimless_preapproval_transaction(
    inspection_root: Path | str,
    *,
    target: str | None,
    reviewed_by: str | None,
    transaction_ref: str | None,
    confirm_claim_store_empty: Callable[[], bool] | None = None,
    _expected_approval_root: Path,
    _expected_archive_id: str,
    _approval_identifier_supplied: bool = False,
) -> dict[str, Any]:
    """Cancel or resume one exact claimless preapproval cancellation.

    A fresh ``lock_backlinked`` tail requires the caller's zero-claim proof.
    Once ``preapproval_cancel_requested`` is durable, later public retries use
    that authenticated journal decision monotonically and never re-prove or
    re-select cancellation.  Every live domain component must remain at its
    exact preimage throughout.
    """

    if type(_approval_identifier_supplied) is not bool:
        raise ArchiveServiceError(
            "exact_human_approval_resume_claim_invalid"
        )
    if not callable(confirm_claim_store_empty):
        raise ArchiveServiceError(
            "project_version_update_preapproval_recovery_failed"
        )

    state, lifetime = _project_update_reopen_durable_state(
        inspection_root,
        target=target,
        reviewed_by=reviewed_by,
        transaction_ref=transaction_ref,
        expected_approval_root=_expected_approval_root,
        expected_archive_id=_expected_archive_id,
    )
    live_lock_present_at_resume = os.path.lexists(
        state.transaction._lock_path
    )
    try:
        _project_update_cancel_claimless_preapproval_state(
            state,
            confirm_claim_store_empty=confirm_claim_store_empty,
        )
    except BaseException:
        _project_update_close_after_service_failure(
            state.directory_guard.close,
            lifetime,
        )
        raise
    result = _project_update_claimless_preapproval_cancel_result(
        operator_resume_identifiers_supplied=bool(
            str(target or "").strip()
            or str(transaction_ref or "").strip()
            or str(reviewed_by or "").strip()
            or _approval_identifier_supplied
        ),
        live_lock_verified=live_lock_present_at_resume,
    )
    return _project_update_finish_nonterminal_service_result(
        result,
        lifetime,
        close_owned_resources=state.directory_guard.close,
    )


def wom_kit_project_version_update_approval_archive_root(
    inspection_root: Path | str,
) -> Path:
    """Resolve the bounded archive authority used for the one-use claim."""

    inspection = Path(os.path.abspath(str(Path(inspection_root).expanduser())))
    candidates = [inspection, inspection / "archive"]
    valid: list[Path] = []
    for candidate in candidates:
        if (
            wom_kit_real_path_kind(candidate, candidate) == "directory"
            and wom_kit_real_path_kind(candidate, candidate / "archive.yml")
            == "file"
        ):
            try:
                read_archive_id(candidate)
            except (ArchiveServiceError, OSError, ValueError):
                continue
            valid.append(candidate)
    if len(valid) != 1:
        raise ArchiveServiceError(
            "project_version_update_exact_approval_archive_required"
        )
    return valid[0]


def _wom_kit_project_version_update_approval_authority_matches(
    inspection_root: Path | str,
    *,
    expected_root: Path | None,
    expected_archive_id: str | None,
) -> bool:
    """Re-resolve one held approval authority without exposing its values."""

    if not isinstance(expected_root, Path) or type(expected_archive_id) is not str:
        return False
    try:
        exact_human_approval_archive_identity_sha256(expected_archive_id)
        held_root = require_existing_archive_root(expected_root)
        current_root = require_existing_archive_root(
            wom_kit_project_version_update_approval_archive_root(
                inspection_root
            )
        )
        return bool(
            current_root == held_root
            and read_archive_id(current_root) == expected_archive_id
        )
    except (
        ArchiveServiceError,
        ExactHumanApprovalError,
        OSError,
        RuntimeError,
        ValueError,
    ):
        return False


class _ProjectVersionUpdateGitRunnerLifetime:
    """Own one preapproval Git runner through the whole claim transaction.

    The private handoff seam is intentionally dormant until the durable claim
    finalizer can own the executable handle directly.  For now the service
    transaction keeps ownership and closes only after ``approval_executor``
    has returned, which is after the current claim-succeeded finalizer.
    """

    def __init__(self) -> None:
        self._runner: (
            project_update_git_runner.TrustedProjectUpdateGitRunner | None
        ) = None
        self._handed_to_claim_finalizer = False

    def acquire_preapproval(
        self,
    ) -> project_update_git_runner.TrustedProjectUpdateGitRunner:
        if self._runner is not None:
            raise project_update_git_runner.ProjectUpdateGitRunnerError(
                "project_update_git_runner_resolved_more_than_once"
            )
        self._runner = (
            project_update_git_runner.TrustedProjectUpdateGitRunner
            .resolve_preapproval()
        )
        return self._runner

    def handoff_to_claim_finalizer(
        self,
    ) -> project_update_git_runner.TrustedProjectUpdateGitRunner:
        """Private future seam; the current transaction does not call it."""

        if self._runner is None or self._handed_to_claim_finalizer:
            raise project_update_git_runner.ProjectUpdateGitRunnerError(
                "project_update_git_runner_handoff_invalid"
            )
        self._handed_to_claim_finalizer = True
        return self._runner

    def close_after_service_transaction(self) -> None:
        if self._runner is None or self._handed_to_claim_finalizer:
            return
        runner = self._runner
        runner.close()
        self._runner = None


