_PROJECT_UPDATE_TERMINAL_CLEANUP_WARNING = (
    "The project update reached its authenticated terminal state, but "
    "follow-up control cleanup was not fully verified; do not rerun the "
    "domain writer or delete terminal evidence."
)
_PROJECT_UPDATE_TERMINAL_DELIVERY_WARNING = (
    "The project update reached its authenticated terminal state, but "
    "durable result delivery has not yet been acknowledged; preserve the "
    "terminal handoff until a project-scoped output artifact is verified."
)
_PROJECT_UPDATE_TERMINAL_CLEANUP_ACTION = (
    "Preserve terminal cleanup evidence and use read-only version "
    "verification; do not infer cleanup authority from a cleanup proof or "
    "rerun the approved update writer."
)
_PROJECT_UPDATE_TERMINAL_DELIVERY_ACTION = (
    "Run project-version-update --resume without private identifiers; WOM "
    "will reuse the exact bound output when present or create a "
    "project-scoped output when needed."
)


def _project_update_canonical_bytes(value: Any) -> bytes:
    """Canonical private transaction bytes; never used as a public echo."""

    return project_update_transaction.canonical_json_bytes(value) + b"\n"


def _project_update_exact_terminal_payload_bytes(
    value: Mapping[str, Any],
) -> bytes:
    """Use the exact-human terminal-MAC canonical byte contract.

    This is intentionally separate from the transaction serializer: exact
    human approval authenticates UTF-8 JSON with non-ASCII text preserved and
    one trailing newline.  A byte mismatch here invalidates the authenticated
    terminal handoff even when the decoded JSON document is equivalent.
    """

    return (
        json.dumps(
            dict(value),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        + b"\n"
    )


def _project_update_private_json_value(value: Any) -> Any:
    """Encode the few byte-valued snapshots needed for crash recovery."""

    if type(value) is bytes:
        return {
            "schema": "wom-kit/private-bytes/base64/v0.1",
            "value": base64.b64encode(value).decode("ascii"),
        }
    if type(value) is dict:
        return {
            str(key): _project_update_private_json_value(item)
            for key, item in value.items()
        }
    if type(value) is list:
        return [_project_update_private_json_value(item) for item in value]
    if type(value) is tuple:
        return [_project_update_private_json_value(item) for item in value]
    if value is None or type(value) in {str, int, bool}:
        return value
    raise ArchiveServiceError("project_version_update_private_plan_invalid")


def _project_update_private_json_restore(value: Any) -> Any:
    """Decode only the exact private byte wrapper emitted above."""

    if type(value) is dict:
        if set(value) == {"schema", "value"}:
            if (
                value.get("schema")
                != "wom-kit/private-bytes/base64/v0.1"
                or type(value.get("value")) is not str
            ):
                raise ArchiveServiceError(
                    "project_version_update_private_plan_invalid"
                )
            try:
                return base64.b64decode(
                    value["value"].encode("ascii"),
                    validate=True,
                )
            except (UnicodeError, binascii.Error):
                raise ArchiveServiceError(
                    "project_version_update_private_plan_invalid"
                ) from None
        return {
            str(key): _project_update_private_json_restore(item)
            for key, item in value.items()
        }
    if type(value) is list:
        return [_project_update_private_json_restore(item) for item in value]
    if value is None or type(value) in {str, int, bool}:
        return value
    raise ArchiveServiceError("project_version_update_private_plan_invalid")


def _project_update_parse_private_plan(raw: bytes) -> dict[str, Any]:
    try:
        value = json.loads(raw.decode("ascii", errors="strict"))
    except (UnicodeError, ValueError, TypeError):
        raise ArchiveServiceError(
            "project_version_update_private_plan_invalid"
        ) from None
    restored = _project_update_private_json_restore(value)
    if (
        type(restored) is not dict
        or restored.get("schema") != _PROJECT_UPDATE_PRIVATE_PLAN_SCHEMA
        or _project_update_canonical_bytes(
            _project_update_private_json_value(restored)
        )
        != raw
    ):
        raise ArchiveServiceError("project_version_update_private_plan_invalid")
    return restored


def _project_update_runtime_candidate_private_document(
    candidate: project_runtime.PreparedRuntimeCandidate,
) -> dict[str, Any]:
    """Persist only intent-bound candidate facts needed after a crash.

    A successful promotion moves the candidate directory to its final runtime
    path.  The public seal still proves those bytes, but reopening the Python
    value also needs the original identities and recursive inventory.  This
    private document is sealed by the transaction and is never echoed.
    """

    return {
        "schema": "wom-kit/project-runtime-candidate-private-resume/v0.4.3",
        "target_tag": candidate.target_tag,
        "target_version": candidate.target_version,
        "target_commit": candidate.target_commit,
        "transaction_ref": candidate.transaction_ref,
        "logical_candidate_path": candidate.logical_candidate_path,
        "logical_seal_path": candidate.logical_seal_path,
        "project_root_identity": list(candidate.project_root_identity),
        "transaction_root_identity": list(candidate.transaction_root_identity),
        "candidate_root_identity": list(candidate.candidate_root_identity),
        "runtime_parent_identity": list(candidate.runtime_parent_identity),
        "runtime_parent_existed_before": candidate.runtime_parent_existed_before,
        "runtime_parent_created_identity": (
            None
            if candidate.runtime_parent_created_identity is None
            else list(candidate.runtime_parent_created_identity)
        ),
        "same_volume_identity": candidate.same_volume_identity,
        "inventory": [
            {
                "relative_path": item.relative_path,
                "entry_type": item.entry_type,
                "device": item.device,
                "inode": item.inode,
                "nlink": item.nlink,
                "size_bytes": item.size_bytes,
                "mtime_ns": item.mtime_ns,
                "sha256": item.sha256,
            }
            for item in candidate.inventory
        ],
        "inventory_sha256": candidate.inventory_sha256,
        "candidate_sha256": candidate.candidate_sha256,
        "inventory_count": candidate.inventory_count,
        "inventory_bytes": candidate.inventory_bytes,
        "seal_bytes": candidate.seal_bytes,
        "seal_sha256": candidate.seal_sha256,
        "receipt_bytes": candidate.receipt_bytes,
        "receipt_sha256": candidate.receipt_sha256,
        "wheel_file_name": candidate.wheel_file_name,
        "wheel_sha256": candidate.wheel_sha256,
        "supply_lock_sha256": candidate.supply_lock_sha256,
        "supply_lock_bytes": candidate.supply_lock_bytes,
        "artifact_inventory": [dict(item) for item in candidate.artifact_inventory],
        "installed_payload_sha256": candidate.installed_payload_sha256,
        "normalized_payload_inventory": [list(item) for item in candidate.normalized_payload_inventory],
        "python_version": candidate.python_version,
        "installed_distributions": [dict(item) for item in candidate.installed_distributions],
        "verification": dict(candidate.verification),
        "existing_runtime_reusable": candidate.existing_runtime_reusable,
        "existing_runtime_repair_required": (
            candidate.existing_runtime_repair_required
        ),
        "existing_runtime_root_identity": (
            None
            if candidate.existing_runtime_root_identity is None
            else list(candidate.existing_runtime_root_identity)
        ),
        "existing_runtime_inventory": [
            {
                "relative_path": item.relative_path,
                "entry_type": item.entry_type,
                "device": item.device,
                "inode": item.inode,
                "nlink": item.nlink,
                "size_bytes": item.size_bytes,
                "mtime_ns": item.mtime_ns,
                "sha256": item.sha256,
            }
            for item in candidate.existing_runtime_inventory
        ],
        "existing_runtime_inventory_sha256": (
            candidate.existing_runtime_inventory_sha256
        ),
        "existing_runtime_inventory_count": (
            candidate.existing_runtime_inventory_count
        ),
        "existing_runtime_inventory_bytes": (
            candidate.existing_runtime_inventory_bytes
        ),
    }


def _project_update_restore_runtime_candidate(
    project_root: Path,
    transaction: project_update_transaction.ProjectUpdateTransaction,
    value: Any,
) -> project_runtime.PreparedRuntimeCandidate:
    """Rehydrate one sealed private candidate without PATH or child lookup."""

    legacy_expected_keys = {
        "schema", "target_tag", "target_version", "target_commit",
        "transaction_ref", "logical_candidate_path", "logical_seal_path",
        "project_root_identity", "transaction_root_identity",
        "candidate_root_identity", "runtime_parent_identity",
        "runtime_parent_existed_before", "runtime_parent_created_identity",
        "same_volume_identity", "inventory", "inventory_sha256",
        "candidate_sha256", "inventory_count", "inventory_bytes",
        "seal_bytes", "seal_sha256", "receipt_bytes", "receipt_sha256",
        "wheel_file_name", "wheel_sha256", "supply_lock_sha256",
        "supply_lock_bytes", "artifact_inventory",
        "installed_payload_sha256", "normalized_payload_inventory",
        "python_version", "installed_distributions", "verification",
        "existing_runtime_reusable",
    }
    current_expected_keys = legacy_expected_keys | {
        "existing_runtime_repair_required", "existing_runtime_root_identity",
        "existing_runtime_inventory", "existing_runtime_inventory_sha256",
        "existing_runtime_inventory_count", "existing_runtime_inventory_bytes",
    }
    legacy_resume_shape = (
        type(value) is dict and set(value) == legacy_expected_keys
    )
    if (
        type(value) is not dict
        or (
            not legacy_resume_shape
            and set(value) != current_expected_keys
        )
        or value.get("schema")
        != "wom-kit/project-runtime-candidate-private-resume/v0.4.3"
        or value.get("transaction_ref") != transaction.transaction_ref
        or type(value.get("inventory")) is not list
        or not isinstance(value.get("seal_bytes"), bytes)
        or not isinstance(value.get("receipt_bytes"), bytes)
        or not isinstance(value.get("supply_lock_bytes"), bytes)
    ):
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_resume_invalid"
        )

    def identity(name: str, *, optional: bool = False) -> tuple[int, int] | None:
        raw = value.get(name)
        if optional and raw is None:
            return None
        if (
            type(raw) is not list
            or len(raw) != 2
            or any(type(item) is not int or item < 0 for item in raw)
        ):
            raise ArchiveServiceError(
                "project_version_update_runtime_candidate_resume_invalid"
            )
        return int(raw[0]), int(raw[1])

    try:
        inventory = tuple(
            project_runtime.RuntimeCandidateInventoryEntry(**dict(item))
            for item in value["inventory"]
            if type(item) is dict
        )
        existing_runtime_inventory = (
            ()
            if legacy_resume_shape
            else tuple(
                project_runtime.RuntimeCandidateInventoryEntry(**dict(item))
                for item in value["existing_runtime_inventory"]
                if type(item) is dict
            )
        )
        normalized_payload_inventory = tuple(
            (str(item[0]), int(item[1]), str(item[2]))
            for item in value["normalized_payload_inventory"]
            if type(item) is list and len(item) == 3
        )
        if (
            len(inventory) != len(value["inventory"])
            or (
                not legacy_resume_shape
                and len(existing_runtime_inventory)
                != len(value["existing_runtime_inventory"])
            )
            or len(normalized_payload_inventory)
            != len(value["normalized_payload_inventory"])
        ):
            raise ValueError
        candidate = project_runtime.PreparedRuntimeCandidate(
            target_tag=value["target_tag"],
            target_version=value["target_version"],
            target_commit=value["target_commit"],
            transaction_ref=transaction.transaction_ref,
            logical_candidate_path=value["logical_candidate_path"],
            logical_seal_path=value["logical_seal_path"],
            project_root=project_root,
            transaction_root=transaction.transaction_root,
            candidate_root=transaction.runtime_candidate_path,
            seal_path=(
                transaction.transaction_root
                / project_runtime.PROJECT_RUNTIME_CANDIDATE_SEAL_NAME
            ),
            project_root_identity=identity("project_root_identity"),
            transaction_root_identity=identity("transaction_root_identity"),
            candidate_root_identity=identity("candidate_root_identity"),
            runtime_parent_identity=identity("runtime_parent_identity"),
            runtime_parent_existed_before=value["runtime_parent_existed_before"],
            runtime_parent_created_identity=identity(
                "runtime_parent_created_identity", optional=True
            ),
            same_volume_identity=value["same_volume_identity"],
            inventory=inventory,
            inventory_sha256=value["inventory_sha256"],
            candidate_sha256=value["candidate_sha256"],
            inventory_count=value["inventory_count"],
            inventory_bytes=value["inventory_bytes"],
            seal_bytes=value["seal_bytes"],
            seal_sha256=value["seal_sha256"],
            receipt_bytes=value["receipt_bytes"],
            receipt_sha256=value["receipt_sha256"],
            wheel_file_name=value["wheel_file_name"],
            wheel_sha256=value["wheel_sha256"],
            supply_lock_sha256=value["supply_lock_sha256"],
            supply_lock_bytes=value["supply_lock_bytes"],
            artifact_inventory=tuple(
                dict(item) for item in value["artifact_inventory"]
            ),
            installed_payload_sha256=value["installed_payload_sha256"],
            normalized_payload_inventory=normalized_payload_inventory,
            python_version=value["python_version"],
            installed_distributions=tuple(
                dict(item) for item in value["installed_distributions"]
            ),
            verification=dict(value["verification"]),
            existing_runtime_reusable=value["existing_runtime_reusable"],
            existing_runtime_repair_required=(
                False
                if legacy_resume_shape
                else value["existing_runtime_repair_required"]
            ),
            existing_runtime_root_identity=(
                None
                if legacy_resume_shape
                else identity(
                    "existing_runtime_root_identity", optional=True
                )
            ),
            existing_runtime_inventory=existing_runtime_inventory,
            existing_runtime_inventory_sha256=(
                None
                if legacy_resume_shape
                else value["existing_runtime_inventory_sha256"]
            ),
            existing_runtime_inventory_count=(
                0
                if legacy_resume_shape
                else value["existing_runtime_inventory_count"]
            ),
            existing_runtime_inventory_bytes=(
                0
                if legacy_resume_shape
                else value["existing_runtime_inventory_bytes"]
            ),
            legacy_resume_shape=legacy_resume_shape,
        )
    except (KeyError, TypeError, ValueError, AttributeError):
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_resume_invalid"
        ) from None
    if (
        not hmac.compare_digest(
            project_update_transaction.sha256_bytes(candidate.seal_bytes),
            "sha256:" + candidate.seal_sha256,
        )
        or not hmac.compare_digest(
            project_update_transaction.sha256_bytes(candidate.receipt_bytes),
            "sha256:" + candidate.receipt_sha256,
        )
    ):
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_resume_invalid"
        )
    return candidate


def _project_update_legacy_resume_serialization_family(
    transaction: project_update_transaction.ProjectUpdateTransaction,
    candidate: project_runtime.PreparedRuntimeCandidate,
    private_plan: Mapping[str, Any],
) -> bool:
    """Require one exact predecessor/current serialization family.

    The v0.4.15 transaction binding, private candidate, and private plan all
    omitted the v0.4.16 repair fields together.  Compatibility is valid only
    for that complete historical shape; a partial or cross-family artifact is
    corruption, not a legacy defaulting opportunity.
    """

    transaction_legacy = (
        transaction.intent.runtime_candidate.legacy_document_shape
    )
    candidate_legacy = candidate.legacy_resume_shape
    if (
        type(transaction_legacy) is not bool
        or type(candidate_legacy) is not bool
        or type(private_plan) is not dict
        or candidate_legacy != transaction_legacy
        or ("static_receipt_schema" in private_plan) == transaction_legacy
    ):
        raise ArchiveServiceError(
            "project_version_update_resume_binding_mismatch"
        )
    return transaction_legacy


def _project_update_unknown_component_sha256(component_ref: str) -> str:
    return project_update_transaction.sha256_document(
        {
            "component_ref": component_ref,
            "schema": "wom-kit/project-update-live-state-unknown/v0.4.3",
        }
    )


def _project_update_raw_component_sha256(value: bytes | None) -> str:
    return project_update_transaction.digest_component(value)


def _project_update_safe_read_component(
    project_root: Path,
    path: Path,
    *,
    maximum: int,
) -> bytes | None | object:
    """Return bytes/absence without treating an unreadable path as absent."""

    observation = _project_update_component_bytes_observation(
        project_root,
        path,
        maximum=maximum,
    )
    if observation["state"] == "unavailable":
        return _PROJECT_UPDATE_UNAVAILABLE_LIVE_COMPONENT
    if observation["state"] != "passed":
        return _PROJECT_UPDATE_UNSAFE_LIVE_COMPONENT
    return observation["value"]


def _project_update_component_bytes_observation(
    project_root: Path,
    path: Path,
    *,
    maximum: int,
) -> dict[str, Any]:
    """Read exact component bytes while preserving drift versus I/O loss."""

    if type(maximum) is not int or maximum < 0:
        return {
            "state": "failed",
            "reason_code": "project_update_component_size_policy_invalid",
            "value": None,
        }
    observation = wom_kit_real_path_kind_observation(project_root, path)
    if observation["state"] == "unavailable":
        return {
            "state": "unavailable",
            "reason_code": "project_update_component_observation_unavailable",
            "value": None,
        }
    kind = observation["kind"]
    if kind == "missing":
        return {
            "state": "passed",
            "reason_code": "verified_missing",
            "value": None,
        }
    if observation["state"] != "passed" or kind != "file":
        return {
            "state": "failed",
            "reason_code": "project_update_component_path_unsafe",
            "value": None,
        }
    unavailable = {
        "state": "unavailable",
        "reason_code": "project_update_component_observation_unavailable",
        "value": None,
    }
    changed = {
        "state": "failed",
        "reason_code": "project_update_component_changed",
        "value": None,
    }
    try:
        before = os.lstat(path)
    except FileNotFoundError:
        return changed
    except (OSError, OverflowError):
        return unavailable

    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)

    def is_regular_real(path_stat: os.stat_result) -> bool:
        return bool(
            stat.S_ISREG(path_stat.st_mode)
            and not stat.S_ISLNK(path_stat.st_mode)
            and not (
                reparse_flag
                and getattr(path_stat, "st_file_attributes", 0)
                & reparse_flag
            )
        )

    if not is_regular_real(before):
        return changed
    if before.st_size < 0 or before.st_size > maximum:
        return {
            "state": "failed",
            "reason_code": "project_update_component_too_large",
            "value": None,
        }

    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(path, flags)
    except FileNotFoundError:
        return changed
    except (OSError, OverflowError):
        return unavailable

    result: dict[str, Any] = unavailable
    close_unavailable = False
    try:
        try:
            opened = os.fstat(descriptor)
        except FileNotFoundError:
            result = changed
        except (OSError, OverflowError):
            result = unavailable
        else:
            opened_matches_before = bool(
                is_regular_real(opened)
                and opened.st_size == before.st_size
                and opened.st_mtime_ns == before.st_mtime_ns
                and (
                    not before.st_dev
                    or not opened.st_dev
                    or before.st_dev == opened.st_dev
                )
                and (
                    not before.st_ino
                    or not opened.st_ino
                    or before.st_ino == opened.st_ino
                )
            )
            if not opened_matches_before:
                result = changed
            else:
                chunks: list[bytes] = []
                total = 0
                read_unavailable = False
                while total <= maximum:
                    try:
                        chunk = os.read(
                            descriptor,
                            min(64 * 1024, maximum + 1 - total),
                        )
                    except (OSError, OverflowError):
                        read_unavailable = True
                        break
                    if not chunk:
                        break
                    chunks.append(chunk)
                    total += len(chunk)
                if read_unavailable:
                    result = unavailable
                else:
                    try:
                        after = os.fstat(descriptor)
                        path_after = os.lstat(path)
                    except FileNotFoundError:
                        result = changed
                    except (OSError, OverflowError):
                        result = unavailable
                    else:
                        stable = bool(
                            total == opened.st_size
                            and total <= maximum
                            and is_regular_real(after)
                            and is_regular_real(path_after)
                            and after.st_size == opened.st_size
                            and after.st_mtime_ns == opened.st_mtime_ns
                            and path_after.st_size == opened.st_size
                            and path_after.st_mtime_ns == opened.st_mtime_ns
                            and (
                                not opened.st_dev
                                or not after.st_dev
                                or opened.st_dev == after.st_dev
                            )
                            and (
                                not opened.st_ino
                                or not after.st_ino
                                or opened.st_ino == after.st_ino
                            )
                            and (
                                not opened.st_dev
                                or not path_after.st_dev
                                or opened.st_dev == path_after.st_dev
                            )
                            and (
                                not opened.st_ino
                                or not path_after.st_ino
                                or opened.st_ino == path_after.st_ino
                            )
                        )
                        result = (
                            {
                                "state": "passed",
                                "reason_code": "verified",
                                "value": b"".join(chunks),
                            }
                            if stable
                            else changed
                        )
    finally:
        try:
            os.close(descriptor)
        except OSError:
            close_unavailable = True
    if close_unavailable and result["state"] != "failed":
        return unavailable
    return result


_PROJECT_UPDATE_UNSAFE_LIVE_COMPONENT = object()
_PROJECT_UPDATE_UNAVAILABLE_LIVE_COMPONENT = object()


@dataclass
class _ProjectVersionUpdateDurableApprovalState:
    """Private, non-echoed execution state for one sealed project update."""

    inspection_root: Path
    project_root: Path
    mirror_path: Path
    target_tag: str
    target_version: str
    target_commit: str
    reviewer: str
    expected_approval_root: Path
    expected_archive_id: str
    transaction: project_update_transaction.ProjectUpdateTransaction
    expected_lock_bytes: bytes
    runner: project_update_git_runner.TrustedProjectUpdateGitRunner
    runtime_candidate: project_runtime.PreparedRuntimeCandidate
    runtime_bootstrap: project_runtime.BootstrapWheel
    runtime_supply: project_runtime.RuntimeSupplyLock
    directory_guard: _WomKitProjectUpdateDirectoryGuard
    private_plan: dict[str, Any]
    prepared_preview: dict[str, Any]
    static_receipt_bytes: bytes
    static_receipt_path: Path
    source_pre_sha256: str
    source_post_sha256: str
    runtime_pre_sha256: str
    runtime_post_sha256: str
    component_paths: dict[str, Path]
    runtime_materialization: project_runtime.RuntimeMaterialization | None = None
    runtime_cleanup_capsule: (
        project_runtime.RuntimeCandidateCleanupCapsule | None
    ) = None
    runtime_cleanup_terminal_evidence: dict[str, Any] | None = None
    approved_plan_sha256: str | None = None
    approved_target_binding_sha256: str | None = None
    terminal_update_verified: bool = False
    transaction_cleanup_completed: bool | None = None
    terminal_domain_result: dict[str, Any] | None = None
    terminal_handoff_sha256: str | None = None
    existing_cleanup_authority_sha256: str | None = None
    approved_snapshot_revalidation: dict[str, Any] | None = None
    legacy_prewrite_recovery: dict[str, Any] | None = None
    # Private, in-process-only recovery authority.  It contains callbacks and
    # path objects and is deliberately excluded from every preview/receipt.
    legacy_prewrite_recovery_control: dict[str, Any] | None = None

    def checkpoint_head(self) -> project_update_transaction.ProjectUpdateCheckpoint:
        journal = self.transaction.inspect().journal
        if journal.state != "exact" or not journal.verified_prefix:
            raise ArchiveServiceError(
                "project_version_update_transaction_checkpoint_invalid"
            )
        return journal.verified_prefix[-1]


@dataclass(frozen=True)
class _ProjectVersionUpdatePreparedApproval:
    preview: Mapping[str, Any]
    state: _ProjectVersionUpdateDurableApprovalState


def _project_update_terminal_handoff_paths(
    project_root: Path,
) -> tuple[Path, Path]:
    root = Path(os.path.abspath(str(project_root)))
    handoff = root.joinpath(
        *PurePosixPath(_PROJECT_UPDATE_TERMINAL_HANDOFF_LOGICAL).parts
    )
    guard = root.joinpath(
        *PurePosixPath(_PROJECT_UPDATE_TERMINAL_HANDOFF_GUARD_LOGICAL).parts
    )
    return handoff, guard


def _project_update_terminal_display_pending_path(
    project_root: Path,
) -> Path:
    root = Path(os.path.abspath(str(project_root)))
    return root.joinpath(
        *PurePosixPath(
            _PROJECT_UPDATE_TERMINAL_DISPLAY_PENDING_LOGICAL
        ).parts
    )


@dataclass(frozen=True)
class _ProjectUpdateTerminalControlScaffold:
    project_root: Path
    terminal_root: Path
    terminal_root_identity: tuple[int, int]
    guard: Path
    guard_identity: tuple[int, int]


_PROJECT_UPDATE_TERMINAL_CONTROL_LEASE: ContextVar[
    tuple[_ProjectUpdateTerminalControlScaffold, dict[str, Any]] | None
] = ContextVar(
    "wom_project_update_terminal_control_lease",
    default=None,
)
_PROJECT_UPDATE_TERMINAL_EXECUTION_LEASE: ContextVar[
    tuple[int, str] | None
] = ContextVar(
    "wom_project_update_terminal_execution_lease",
    default=None,
)


def _project_update_terminal_control_scaffold_state(
    project_root: Path,
) -> _ProjectUpdateTerminalControlScaffold:
    """Compatibility snapshot created inside the held control boundary."""

    with _project_update_terminal_control_boundary(project_root) as value:
        return value[0]


def _project_update_terminal_control_scaffold(project_root: Path) -> Path:
    """Compatibility wrapper returning the verified terminal root."""

    return _project_update_terminal_control_scaffold_state(
        project_root
    ).terminal_root


def _project_update_terminal_identity(
    path: Path,
    *,
    regular: bool,
) -> tuple[int, int]:
    observed = os.lstat(path)
    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
    if (
        stat.S_ISLNK(observed.st_mode)
        or bool(
            reparse_flag
            and getattr(observed, "st_file_attributes", 0) & reparse_flag
        )
        or (regular and (not stat.S_ISREG(observed.st_mode) or observed.st_nlink != 1))
        or (not regular and not stat.S_ISDIR(observed.st_mode))
    ):
        raise OSError("project_update_terminal_control_boundary_unsafe")
    return int(observed.st_dev), int(observed.st_ino)


@contextmanager
def _project_update_terminal_bound_guard(
    project_root: Path,
    terminal_root: Path,
    binding: dict[str, Any],
) -> Iterable[tuple[Path, tuple[int, int]]]:
    """Create, lock, and verify the guard through the held parent boundary."""

    guard = terminal_root / Path(
        _PROJECT_UPDATE_TERMINAL_HANDOFF_GUARD_LOGICAL
    ).name
    parent_descriptor = binding.get("descriptor")
    if isinstance(parent_descriptor, int):
        flags = os.O_RDWR | getattr(os, "O_BINARY", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        descriptor: int | None = None
        locked = False
        created = False
        try:
            try:
                descriptor = os.open(
                    guard.name,
                    flags,
                    dir_fd=parent_descriptor,
                )
            except FileNotFoundError:
                try:
                    descriptor = os.open(
                        guard.name,
                        flags | os.O_CREAT | os.O_EXCL,
                        0o600,
                        dir_fd=parent_descriptor,
                    )
                    created = True
                    if os.write(descriptor, b"\x00") != 1:
                        raise OSError(
                            "project_update_terminal_guard_write_incomplete"
                        )
                    os.fsync(descriptor)
                    os.fsync(parent_descriptor)
                except FileExistsError:
                    descriptor = os.open(
                        guard.name,
                        flags,
                        dir_fd=parent_descriptor,
                    )
            opened = os.fstat(descriptor)
            named = os.stat(
                guard.name,
                dir_fd=parent_descriptor,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISREG(opened.st_mode)
                or int(opened.st_nlink) != 1
                or int(opened.st_size) != 1
                or (opened.st_dev, opened.st_ino)
                != (named.st_dev, named.st_ino)
                or stat.S_IMODE(opened.st_mode) & 0o077
                or int(opened.st_uid) != int(os.geteuid())
            ):
                raise OSError("project_update_terminal_guard_unsafe")
            os.lseek(descriptor, 0, os.SEEK_SET)
            if os.read(descriptor, 2) != b"\x00":
                raise OSError("project_update_terminal_guard_invalid")
            import fcntl

            fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
            locked = True
            after_lock = os.fstat(descriptor)
            named_after_lock = os.stat(
                guard.name,
                dir_fd=parent_descriptor,
                follow_symlinks=False,
            )
            identity = (int(opened.st_dev), int(opened.st_ino))
            if (
                (after_lock.st_dev, after_lock.st_ino) != identity
                or (named_after_lock.st_dev, named_after_lock.st_ino)
                != identity
                or int(after_lock.st_size) != 1
            ):
                raise OSError("project_update_terminal_guard_changed")
            yield guard, identity
            named_after = os.stat(
                guard.name,
                dir_fd=parent_descriptor,
                follow_symlinks=False,
            )
            if (
                (named_after.st_dev, named_after.st_ino) != identity
                or os.fstat(descriptor).st_size != 1
            ):
                raise OSError("project_update_terminal_guard_changed")
        finally:
            if descriptor is not None:
                if locked:
                    try:
                        fcntl.flock(descriptor, fcntl.LOCK_UN)
                    except OSError:
                        pass
                os.close(descriptor)
        return

    # The held Windows directory chain denies deletion/replacement of the
    # terminal parent.  Create or recover only the one fixed guard name through
    # an exact no-delete-share handle.  A hard exit may leave exactly zero
    # bytes after CreateFileW(CREATE_NEW); only that regular, single-link,
    # default-stream file may be completed to the canonical one byte.  The
    # returned named identity must then be the same file acquired by the
    # advisory lock, closing the create/lock substitution gap.
    if not binding.get("windows_handles"):
        raise OSError("project_update_terminal_guard_parent_unbound")
    try:
        guard_identity: list[tuple[int, int]] = []
        try:
            guard_raw = _project_update_terminal_windows_move_exact_no_replace(
                guard,
                None,
                expected_raw=None,
                create_raw=b"\x00",
                _named_identity_out=guard_identity,
            )
        except OSError:
            guard_identity.clear()
            guard_raw = _project_update_terminal_windows_move_exact_no_replace(
                guard,
                None,
                expected_raw=b"\x00",
                complete_empty_with=b"\x00",
                _named_identity_out=guard_identity,
            )
        if guard_raw != b"\x00" or len(guard_identity) != 1:
            raise OSError("project_update_terminal_guard_invalid")
        identity = guard_identity[0]
        if _project_update_terminal_identity(guard, regular=True) != identity:
            raise OSError("project_update_terminal_guard_changed")
        project_update_transaction._require_directory_durable(terminal_root)
        with project_update_transaction._exclusive_guard(
            guard,
            within=project_root,
        ):
            if (
                _project_update_terminal_identity(guard, regular=True)
                != identity
            ):
                raise OSError("project_update_terminal_guard_changed")
            yield guard, identity
            if (
                _project_update_terminal_identity(guard, regular=True)
                != identity
            ):
                raise OSError("project_update_terminal_guard_changed")
    except project_update_transaction.ProjectUpdateTransactionError as failure:
        raise OSError(failure.code) from None


@contextmanager
def _project_update_terminal_control_boundary(
    project_root: Path,
) -> Iterable[tuple[_ProjectUpdateTerminalControlScaffold, dict[str, Any]]]:
    """Create and hold the terminal parent before guard or document access."""

    # Approved project-update mutation is a Windows-only contract.  Refuse the
    # terminal writer before ``create=True`` can create even the first private
    # control directory on platforms where the canonical namespace cannot be
    # retained against a whole-directory rename.
    if os.name != "nt":
        raise OSError("project_update_terminal_control_platform_unsupported")
    canonical_project_root = Path(project_root).resolve(strict=True)
    if not os.path.samefile(project_root, canonical_project_root):
        raise OSError("project_update_terminal_control_boundary_changed")
    existing_lease = _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.get()
    if existing_lease is not None:
        existing_scaffold, existing_binding = existing_lease
        if (
            existing_scaffold.project_root != canonical_project_root
            or existing_binding.get("path")
            != existing_scaffold.terminal_root
            or _project_update_terminal_identity(
                existing_scaffold.terminal_root,
                regular=False,
            )
            != existing_scaffold.terminal_root_identity
            or _project_update_terminal_identity(
                existing_scaffold.guard,
                regular=True,
            )
            != existing_scaffold.guard_identity
        ):
            raise OSError("project_update_terminal_control_boundary_changed")
        yield existing_lease
        if (
            _project_update_terminal_identity(
                existing_scaffold.terminal_root,
                regular=False,
            )
            != existing_scaffold.terminal_root_identity
            or _project_update_terminal_identity(
                existing_scaffold.guard,
                regular=True,
            )
            != existing_scaffold.guard_identity
        ):
            raise OSError("project_update_terminal_control_boundary_changed")
        return
    terminal_root = canonical_project_root.joinpath(
        *PurePosixPath(
            _PROJECT_UPDATE_TERMINAL_CONSUMED_ROOT_LOGICAL
        ).parts
    )
    with _activity_group_bound_directory_chain(
        canonical_project_root,
        terminal_root,
        create=True,
    ) as binding:
        if binding.get("path") != terminal_root:
            raise OSError("project_update_terminal_control_boundary_changed")
        parent_descriptor = binding.get("descriptor")
        if isinstance(parent_descriptor, int):
            terminal_info = os.fstat(parent_descriptor)
            if not stat.S_ISDIR(terminal_info.st_mode):
                raise OSError("project_update_terminal_control_boundary_unsafe")
            os.fsync(parent_descriptor)
        else:
            terminal_info = os.lstat(terminal_root)
            if (
                not stat.S_ISDIR(terminal_info.st_mode)
                or stat.S_ISLNK(terminal_info.st_mode)
            ):
                raise OSError("project_update_terminal_control_boundary_unsafe")
            durable_directory = canonical_project_root
            project_update_transaction._require_directory_durable(
                durable_directory
            )
            for part in PurePosixPath(
                _PROJECT_UPDATE_TERMINAL_CONSUMED_ROOT_LOGICAL
            ).parts:
                durable_directory = durable_directory / part
                project_update_transaction._require_directory_durable(
                    durable_directory
                )
        terminal_identity = (
            int(terminal_info.st_dev),
            int(terminal_info.st_ino),
        )
        expected_parent_identity: tuple[int, int] | None = None
        if isinstance(parent_descriptor, int):
            flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            flags |= getattr(os, "O_NOFOLLOW", 0)
            expected_parent_descriptor = os.open(
                "..",
                flags,
                dir_fd=parent_descriptor,
            )
            try:
                expected_parent = os.fstat(expected_parent_descriptor)
                expected_parent_identity = (
                    int(expected_parent.st_dev),
                    int(expected_parent.st_ino),
                )
            finally:
                os.close(expected_parent_descriptor)
            # The bound-chain creator may have created more than the final
            # directory. Flush every ancestor through held relative handles so
            # each new child name is durable before the guard or handoff is
            # published.
            durable_descriptor = os.dup(parent_descriptor)
            try:
                for _part in PurePosixPath(
                    _PROJECT_UPDATE_TERMINAL_CONSUMED_ROOT_LOGICAL
                ).parts:
                    ancestor_descriptor = os.open(
                        "..",
                        flags,
                        dir_fd=durable_descriptor,
                    )
                    os.fsync(ancestor_descriptor)
                    os.close(durable_descriptor)
                    durable_descriptor = ancestor_descriptor
            finally:
                os.close(durable_descriptor)

        def terminal_namespace_matches() -> bool:
            if isinstance(parent_descriptor, int):
                flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
                flags |= getattr(os, "O_NOFOLLOW", 0)
                ancestor_descriptor = os.open(
                    "..",
                    flags,
                    dir_fd=parent_descriptor,
                )
                try:
                    observed_parent = os.fstat(ancestor_descriptor)
                    if (
                        int(observed_parent.st_dev),
                        int(observed_parent.st_ino),
                    ) != expected_parent_identity:
                        return False
                    named = os.stat(
                        terminal_root.name,
                        dir_fd=ancestor_descriptor,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    return False
                finally:
                    os.close(ancestor_descriptor)
                return (
                    stat.S_ISDIR(named.st_mode)
                    and (int(named.st_dev), int(named.st_ino))
                    == terminal_identity
                )
            return (
                _project_update_terminal_identity(
                    terminal_root,
                    regular=False,
                )
                == terminal_identity
            )

        if not terminal_namespace_matches():
            raise OSError("project_update_terminal_control_boundary_changed")
        with _project_update_terminal_bound_guard(
            canonical_project_root,
            terminal_root,
            binding,
        ) as (guard, guard_identity):
            if isinstance(parent_descriptor, int):
                if (
                    int(os.fstat(parent_descriptor).st_dev),
                    int(os.fstat(parent_descriptor).st_ino),
                ) != terminal_identity:
                    raise OSError(
                        "project_update_terminal_control_boundary_changed"
                    )
            elif (
                _project_update_terminal_identity(
                    terminal_root,
                    regular=False,
                )
                != terminal_identity
            ):
                raise OSError(
                    "project_update_terminal_control_boundary_changed"
                )
            lease = (
                _ProjectUpdateTerminalControlScaffold(
                    project_root=canonical_project_root,
                    terminal_root=terminal_root,
                    terminal_root_identity=terminal_identity,
                    guard=guard,
                    guard_identity=guard_identity,
                ),
                binding,
            )
            lease_token = _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.set(lease)
            try:
                yield lease
                if not terminal_namespace_matches():
                    raise OSError(
                        "project_update_terminal_control_boundary_changed"
                    )
            finally:
                _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.reset(lease_token)


def _project_update_terminal_execution_lease_is_held(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> bool:
    """Return only whether this state owns the currently bound guard lease."""

    lease = _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.get()
    execution_owner = _PROJECT_UPDATE_TERMINAL_EXECUTION_LEASE.get()
    transaction_ref = getattr(
        getattr(state, "transaction", None),
        "transaction_ref",
        None,
    )
    if (
        lease is None
        or execution_owner is None
        or type(transaction_ref) is not str
        or execution_owner != (id(state), transaction_ref)
    ):
        return False
    scaffold, _binding = lease
    try:
        if (
            scaffold.project_root
            != Path(state.project_root).resolve(strict=True)
        ):
            return False
        with _project_update_terminal_control_boundary(state.project_root):
            return True
    except (OSError, RuntimeError, ValueError):
        return False


def _project_update_terminal_consumed_path(
    project_root: Path,
    handoff_sha256: str,
) -> Path:
    if re.fullmatch(r"sha256:[0-9a-f]{64}", handoff_sha256) is None:
        raise ArchiveServiceError(
            "project_version_update_terminal_delivery_binding_invalid"
        )
    root = Path(os.path.abspath(str(project_root)))
    consumed_root = root.joinpath(
        *PurePosixPath(
            _PROJECT_UPDATE_TERMINAL_CONSUMED_ROOT_LOGICAL
        ).parts
    )
    return consumed_root / (handoff_sha256.removeprefix("sha256:") + ".json")


def _project_update_read_terminal_document(
    project_root: Path,
    path: Path,
) -> tuple[dict[str, Any], bytes] | None:
    """Read one authority-bearing terminal document through held names.

    The active, display-pending, and consumed terminal documents all live in
    one fixed private directory.  Treating an arbitrary regular file at the
    supplied path as equivalent would let a hard link, alternate data stream,
    or namespace swap lend foreign bytes the terminal document's authority.
    Bind the complete parent chain first, then reuse the same exact file reader
    used by terminal publication.
    """

    try:
        requested_root = Path(os.path.abspath(str(project_root)))
        requested_path = Path(os.path.abspath(str(path)))
        try:
            relative_path = requested_path.relative_to(requested_root)
        except ValueError:
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            ) from None
        if not wom_kit_existing_path_components_are_real(
            requested_root,
            requested_path.parent,
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        # Windows may spell the same existing root through an 8.3 alias.
        # Resolve that already-validated root once, then rebuild rather than
        # resolving the child path (which could follow a hostile reparse point).
        canonical_root = requested_root.resolve(strict=True)
        canonical_path = canonical_root.joinpath(*relative_path.parts)
        terminal_root = canonical_root.joinpath(
            *PurePosixPath(
                _PROJECT_UPDATE_TERMINAL_CONSUMED_ROOT_LOGICAL
            ).parts
        )
        allowed_name = bool(
            canonical_path.name
            in {
                Path(_PROJECT_UPDATE_TERMINAL_HANDOFF_LOGICAL).name,
                Path(_PROJECT_UPDATE_TERMINAL_DISPLAY_PENDING_LOGICAL).name,
            }
            or re.fullmatch(r"[0-9a-f]{64}\.json", canonical_path.name)
        )
        if (
            canonical_path.parent != terminal_root
            or not allowed_name
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        with _activity_group_bound_directory_chain(
            canonical_root,
            canonical_path.parent,
        ) as binding:
            return _project_update_read_terminal_document_bound(
                canonical_root,
                binding,
                canonical_path,
            )
    except FileNotFoundError:
        return None
    except ArchiveServiceError:
        raise
    except OSError:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        ) from None


def _project_update_read_terminal_document_bound(
    project_root: Path,
    binding: dict[str, Any],
    path: Path,
) -> tuple[dict[str, Any], bytes] | None:
    """Read one terminal document only through its already-held parent."""

    if binding.get("path") != path.parent:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    try:
        if os.name == "nt":
            before = os.lstat(path)
            reparse_flag = getattr(
                stat,
                "FILE_ATTRIBUTE_REPARSE_POINT",
                0,
            )
            before_identity = (int(before.st_dev), int(before.st_ino))
            before_snapshot = (
                *before_identity,
                int(before.st_size),
                int(before.st_mtime_ns),
                int(before.st_ctime_ns),
                int(before.st_nlink),
            )
            if (
                not stat.S_ISREG(before.st_mode)
                or stat.S_ISLNK(before.st_mode)
                or int(before.st_nlink) != 1
                or int(before.st_size)
                > _PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES
                or before_identity[1] <= 0
                or bool(
                    reparse_flag
                    and getattr(before, "st_file_attributes", 0)
                    & reparse_flag
                )
            ):
                raise OSError(
                    "project_update_terminal_handoff_file_unsafe"
                )
            # Re-open the exact named file with delete sharing denied, flush
            # that same handle, and require one link plus the default data
            # stream only.  Initial publication and idempotent re-use therefore
            # enforce the same terminal-file invariants.
            named_identity: list[tuple[int, int]] = []
            raw = _project_update_terminal_windows_move_exact_no_replace(
                path,
                None,
                expected_raw=None,
                _named_identity_out=named_identity,
            )
            after = os.lstat(path)
            after_snapshot = (
                int(after.st_dev),
                int(after.st_ino),
                int(after.st_size),
                int(after.st_mtime_ns),
                int(after.st_ctime_ns),
                int(after.st_nlink),
            )
            if (
                named_identity != [before_identity]
                or after_snapshot != before_snapshot
                or int(after.st_size) != len(raw)
            ):
                raise OSError(
                    "project_update_terminal_handoff_file_changed"
                )
        else:
            parent_descriptor = binding.get("descriptor")
            if not isinstance(parent_descriptor, int):
                raise OSError(
                    "project_update_terminal_handoff_parent_unbound"
                )
            flags = os.O_RDONLY | getattr(os, "O_BINARY", 0)
            flags |= getattr(os, "O_NOFOLLOW", 0)
            descriptor = os.open(
                path.name,
                flags,
                dir_fd=parent_descriptor,
            )
            try:
                opened = os.fstat(descriptor)
                named_before = os.stat(
                    path.name,
                    dir_fd=parent_descriptor,
                    follow_symlinks=False,
                )
                opened_snapshot = (
                    int(opened.st_dev),
                    int(opened.st_ino),
                    int(opened.st_size),
                    int(opened.st_mtime_ns),
                    int(opened.st_ctime_ns),
                    int(opened.st_nlink),
                    stat.S_IMODE(opened.st_mode),
                    int(opened.st_uid),
                )
                if (
                    not stat.S_ISREG(opened.st_mode)
                    or int(opened.st_nlink) != 1
                    or int(opened.st_uid) != int(os.geteuid())
                    or stat.S_IMODE(opened.st_mode) & 0o077
                    or int(opened.st_size)
                    > _PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES
                    or (
                        int(named_before.st_dev),
                        int(named_before.st_ino),
                    )
                    != (
                        int(opened.st_dev),
                        int(opened.st_ino),
                    )
                ):
                    raise OSError(
                        "project_update_terminal_handoff_file_unsafe"
                    )

                def read_exact() -> bytes:
                    os.lseek(descriptor, 0, os.SEEK_SET)
                    chunks: list[bytes] = []
                    remaining = (
                        _PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES + 1
                    )
                    while remaining:
                        chunk = os.read(
                            descriptor,
                            min(64 * 1024, remaining),
                        )
                        if not chunk:
                            break
                        chunks.append(chunk)
                        remaining -= len(chunk)
                    return b"".join(chunks)

                raw = read_exact()
                stable_raw = read_exact()
                final = os.fstat(descriptor)
                named_after = os.stat(
                    path.name,
                    dir_fd=parent_descriptor,
                    follow_symlinks=False,
                )
                final_snapshot = (
                    int(final.st_dev),
                    int(final.st_ino),
                    int(final.st_size),
                    int(final.st_mtime_ns),
                    int(final.st_ctime_ns),
                    int(final.st_nlink),
                    stat.S_IMODE(final.st_mode),
                    int(final.st_uid),
                )
                if (
                    len(raw)
                    > _PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES
                    or not hmac.compare_digest(raw, stable_raw)
                    or opened_snapshot != final_snapshot
                    or len(raw) != int(final.st_size)
                    or int(named_after.st_nlink) != 1
                    or (
                        int(named_after.st_dev),
                        int(named_after.st_ino),
                    )
                    != (
                        int(final.st_dev),
                        int(final.st_ino),
                    )
                ):
                    raise OSError(
                        "project_update_terminal_handoff_file_changed"
                    )
            finally:
                os.close(descriptor)
    except FileNotFoundError:
        return None
    except OSError:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        ) from None
    try:
        value = project_update_transaction._parse_document(
            raw,
            code="project_update_transaction_invalid",
        )
    except project_update_transaction.ProjectUpdateTransactionError:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        ) from None
    if type(value) is not dict or _project_update_canonical_bytes(value) != raw:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    return value, raw


def _project_update_terminal_create_stage_path(
    path: Path,
    raw: bytes,
) -> Path:
    """Return the one fixed, bounded initial-publication evidence name."""

    if not isinstance(raw, bytes):
        raise OSError("project_update_terminal_handoff_bytes_invalid")
    return path.with_name(_PROJECT_UPDATE_TERMINAL_CREATE_STAGE_NAME)


def _project_update_terminal_bound_snapshot(
    project_root: Path,
    binding: dict[str, Any],
    path: Path,
) -> tuple[bytes, tuple[int, int]]:
    """Read one sibling while retaining and rechecking its exact identity."""

    if binding.get("path") != path.parent:
        raise OSError("project_update_terminal_handoff_parent_mismatch")
    with _hold_activity_group_evidence_file(
        project_root,
        path,
        max_bytes=_PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES,
    ) as held:
        raw = held.get("raw")
        identity = held.get("identity")
        if (
            not isinstance(raw, bytes)
            or not isinstance(identity, tuple)
            or len(identity) != 2
        ):
            raise OSError("project_update_terminal_handoff_stage_unsafe")
        descriptor = binding.get("descriptor")
        if isinstance(descriptor, int):
            observed = os.stat(
                path.name,
                dir_fd=descriptor,
                follow_symlinks=False,
            )
        else:
            observed = os.lstat(path)
        exact_identity = (int(identity[0]), int(identity[1]))
        if (
            not stat.S_ISREG(observed.st_mode)
            or int(observed.st_nlink) != 1
            or int(observed.st_size) != len(raw)
            or (int(observed.st_dev), int(observed.st_ino))
            != exact_identity
            or (
                os.name != "nt"
                and (
                    stat.S_IMODE(observed.st_mode) & 0o077
                    or int(observed.st_uid) != int(os.geteuid())
                )
            )
        ):
            raise OSError("project_update_terminal_handoff_stage_changed")
        return raw, exact_identity


def _project_update_terminal_create_residue_path(
    stage: Path,
) -> Path:
    """Return the single bounded evidence slot for one exact initial result."""

    return stage.with_name(_PROJECT_UPDATE_TERMINAL_CREATE_RESIDUE_NAME)


def _project_update_terminal_windows_move_exact_no_replace(
    source: Path,
    destination: Path | None,
    *,
    expected_raw: bytes | None,
    create_raw: bytes | None = None,
    complete_empty_with: bytes | None = None,
    _named_identity_out: list[tuple[int, int]] | None = None,
    _failpoint: Callable[[str], None] | None = None,
) -> bytes:
    """Flush one exact Windows file and optionally rename that held handle."""

    if os.name != "nt":
        raise OSError("project_update_terminal_windows_wrong_platform")
    if destination is not None and (
        source.parent != destination.parent or source == destination
    ):
        raise OSError("project_update_terminal_handoff_parent_mismatch")
    if (
        create_raw is not None and expected_raw is not None
        or create_raw is not None and complete_empty_with is not None
        or complete_empty_with is not None and expected_raw is None
        or _named_identity_out is not None and _named_identity_out
    ):
        raise OSError("project_update_terminal_handoff_bytes_invalid")
    for candidate_raw in (create_raw, complete_empty_with, expected_raw):
        if candidate_raw is not None and (
            not isinstance(candidate_raw, bytes)
            or len(candidate_raw)
            > _PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES
        ):
            raise OSError("project_update_terminal_handoff_bytes_invalid")

    from ctypes import wintypes

    class ByHandleFileInformation(ctypes.Structure):
        _fields_ = [
            ("dwFileAttributes", wintypes.DWORD),
            ("ftCreationTime", wintypes.FILETIME),
            ("ftLastAccessTime", wintypes.FILETIME),
            ("ftLastWriteTime", wintypes.FILETIME),
            ("dwVolumeSerialNumber", wintypes.DWORD),
            ("nFileSizeHigh", wintypes.DWORD),
            ("nFileSizeLow", wintypes.DWORD),
            ("nNumberOfLinks", wintypes.DWORD),
            ("nFileIndexHigh", wintypes.DWORD),
            ("nFileIndexLow", wintypes.DWORD),
        ]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    create_file = kernel32.CreateFileW
    create_file.argtypes = [
        wintypes.LPCWSTR,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.LPVOID,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.HANDLE,
    ]
    create_file.restype = wintypes.HANDLE
    get_information = kernel32.GetFileInformationByHandle
    get_information.argtypes = [
        wintypes.HANDLE,
        ctypes.POINTER(ByHandleFileInformation),
    ]
    get_information.restype = wintypes.BOOL
    read_file = kernel32.ReadFile
    read_file.argtypes = [
        wintypes.HANDLE,
        wintypes.LPVOID,
        wintypes.DWORD,
        ctypes.POINTER(wintypes.DWORD),
        wintypes.LPVOID,
    ]
    read_file.restype = wintypes.BOOL
    write_file = kernel32.WriteFile
    write_file.argtypes = [
        wintypes.HANDLE,
        wintypes.LPCVOID,
        wintypes.DWORD,
        ctypes.POINTER(wintypes.DWORD),
        wintypes.LPVOID,
    ]
    write_file.restype = wintypes.BOOL
    set_file_pointer = kernel32.SetFilePointerEx
    set_file_pointer.argtypes = [
        wintypes.HANDLE,
        ctypes.c_longlong,
        ctypes.POINTER(ctypes.c_longlong),
        wintypes.DWORD,
    ]
    set_file_pointer.restype = wintypes.BOOL
    flush_file = kernel32.FlushFileBuffers
    flush_file.argtypes = [wintypes.HANDLE]
    flush_file.restype = wintypes.BOOL
    set_information = kernel32.SetFileInformationByHandle
    set_information.argtypes = [
        wintypes.HANDLE,
        ctypes.c_int,
        wintypes.LPVOID,
        wintypes.DWORD,
    ]
    set_information.restype = wintypes.BOOL
    close_handle = kernel32.CloseHandle
    close_handle.argtypes = [wintypes.HANDLE]
    close_handle.restype = wintypes.BOOL

    generic_read = 0x80000000
    generic_write = 0x40000000
    delete_access = 0x00010000
    file_read_attributes = 0x00000080
    file_share_read = 0x00000001
    create_new = 1
    open_existing = 3
    file_flag_open_reparse_point = 0x00200000
    file_flag_sequential_scan = 0x08000000
    invalid_handle = wintypes.HANDLE(-1).value
    file_attribute_directory = 0x00000010
    file_attribute_reparse_point = 0x00000400

    def handle_value(handle: Any) -> int | None:
        value = handle if isinstance(handle, int) else getattr(handle, "value", None)
        return None if value in {None, invalid_handle} else int(value)

    def query(handle: Any) -> ByHandleFileInformation:
        information = ByHandleFileInformation()
        if not get_information(handle, ctypes.byref(information)):
            raise ctypes.WinError(ctypes.get_last_error())
        return information

    def identity(information: ByHandleFileInformation) -> tuple[int, int]:
        return (
            int(information.dwVolumeSerialNumber),
            (int(information.nFileIndexHigh) << 32)
            | int(information.nFileIndexLow),
        )

    def size(information: ByHandleFileInformation) -> int:
        return (int(information.nFileSizeHigh) << 32) | int(
            information.nFileSizeLow
        )

    def named_identity(path: Path) -> tuple[int, int] | None:
        try:
            observed = os.lstat(path)
        except FileNotFoundError:
            return None
        reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        if (
            not stat.S_ISREG(observed.st_mode)
            or stat.S_ISLNK(observed.st_mode)
            or int(observed.st_nlink) != 1
            or bool(
                reparse_flag
                and getattr(observed, "st_file_attributes", 0) & reparse_flag
            )
        ):
            raise OSError("project_update_terminal_handoff_file_unsafe")
        return int(observed.st_dev), int(observed.st_ino)

    def read_exact(handle: Any, byte_count: int) -> bytes:
        if not set_file_pointer(handle, 0, None, 0):
            raise ctypes.WinError(ctypes.get_last_error())
        chunks: list[bytes] = []
        remaining = byte_count
        while remaining:
            requested = min(1024 * 1024, remaining)
            buffer = ctypes.create_string_buffer(requested)
            observed_count = wintypes.DWORD()
            if not read_file(
                handle,
                buffer,
                requested,
                ctypes.byref(observed_count),
                None,
            ):
                raise ctypes.WinError(ctypes.get_last_error())
            if observed_count.value <= 0 or observed_count.value > requested:
                raise OSError("project_update_terminal_handoff_read_incomplete")
            chunks.append(buffer.raw[: observed_count.value])
            remaining -= observed_count.value
        trailing = ctypes.create_string_buffer(1)
        trailing_count = wintypes.DWORD()
        if not read_file(
            handle,
            trailing,
            1,
            ctypes.byref(trailing_count),
            None,
        ) or int(trailing_count.value) != 0:
            raise OSError("project_update_terminal_handoff_read_incomplete")
        return b"".join(chunks)

    handle: Any = create_file(
        str(source),
        generic_read | generic_write | delete_access | file_read_attributes,
        file_share_read,
        None,
        create_new if create_raw is not None else open_existing,
        file_flag_open_reparse_point | file_flag_sequential_scan,
        None,
    )
    if handle_value(handle) is None:
        raise ctypes.WinError(ctypes.get_last_error())
    close_error: OSError | None = None
    try:
        before = query(handle)
        source_identity = identity(before)
        if (
            source_identity[1] <= 0
            or int(before.nNumberOfLinks) != 1
            or before.dwFileAttributes
            & (file_attribute_directory | file_attribute_reparse_point)
        ):
            raise OSError("project_update_terminal_handoff_file_unsafe")
        bytes_to_write = create_raw
        if (
            bytes_to_write is None
            and complete_empty_with is not None
            and size(before) == 0
        ):
            bytes_to_write = complete_empty_with
        if bytes_to_write is not None:
            if _failpoint is not None and create_raw is not None:
                _failpoint("windows_file_created_before_write")
            if not set_file_pointer(handle, 0, None, 0):
                raise ctypes.WinError(ctypes.get_last_error())
            offset = 0
            while offset < len(bytes_to_write):
                chunk = bytes_to_write[offset : offset + 64 * 1024]
                buffer = ctypes.create_string_buffer(chunk)
                written = wintypes.DWORD()
                if not write_file(
                    handle,
                    buffer,
                    len(chunk),
                    ctypes.byref(written),
                    None,
                ):
                    raise ctypes.WinError(ctypes.get_last_error())
                if int(written.value) != len(chunk):
                    raise OSError(
                        "project_update_terminal_handoff_write_incomplete"
                    )
                offset += int(written.value)
            if _failpoint is not None:
                _failpoint("windows_stage_fully_written_before_flush")
        if not flush_file(handle):
            raise ctypes.WinError(ctypes.get_last_error())
        after_flush = query(handle)
        raw = read_exact(handle, size(after_flush))
        expected = bytes_to_write if bytes_to_write is not None else expected_raw
        if (
            identity(after_flush) != source_identity
            or int(after_flush.nNumberOfLinks) != 1
            or size(after_flush) > _PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES
            or size(after_flush) != len(raw)
            or (expected is not None and not hmac.compare_digest(raw, expected))
        ):
            raise OSError("project_update_terminal_handoff_stage_changed")
        _windows_assert_default_backup_stream_only(
            handle,
            expected_size=len(raw),
            error_prefix="project_update_terminal_handoff",
        )
        named_source = named_identity(source)
        if (
            named_source is None
            or (
                int(named_source[0]) & 0xFFFFFFFF,
                int(named_source[1]),
            )
            != source_identity
        ):
            raise OSError("project_update_terminal_handoff_stage_changed")
        if _named_identity_out is not None:
            _named_identity_out.append(named_source)
        if _failpoint is not None:
            _failpoint("windows_exact_handle_verified_before_rename")

        if destination is None:
            project_update_transaction._require_directory_durable(
                source.parent
            )
            return raw

        from . import private_metadata_win32

        rename_information = private_metadata_win32.file_rename_info_buffer(
            destination,
            replace_if_exists=False,
        )
        api_ok = bool(
            set_information(
                handle,
                3,  # FileRenameInfo
                rename_information.backing,
                rename_information.api_buffer_size,
            )
        )
        named_source_after = named_identity(source)
        named_destination = named_identity(destination)
        source_matches = bool(
            named_source_after is not None
            and (
                int(named_source_after[0]) & 0xFFFFFFFF,
                int(named_source_after[1]),
            )
            == source_identity
        )
        destination_matches = bool(
            named_destination is not None
            and (
                int(named_destination[0]) & 0xFFFFFFFF,
                int(named_destination[1]),
            )
            == source_identity
        )
        if not destination_matches or source_matches:
            if not api_ok:
                raise ctypes.WinError(ctypes.get_last_error())
            raise OSError("project_update_terminal_handoff_state_uncertain")
        if _failpoint is not None:
            _failpoint("windows_exact_handle_renamed_before_parent_flush")
        after_move = query(handle)
        if (
            identity(after_move) != source_identity
            or int(after_move.nNumberOfLinks) != 1
            or size(after_move) != len(raw)
            or not hmac.compare_digest(read_exact(handle, len(raw)), raw)
        ):
            raise OSError("project_update_terminal_handoff_state_uncertain")
        project_update_transaction._require_directory_durable(source.parent)
        return raw
    finally:
        try:
            if not close_handle(handle):
                close_error = ctypes.WinError(ctypes.get_last_error())
        except OSError as failure:
            close_error = failure
        if close_error is not None and sys.exc_info()[0] is None:
            raise close_error


def _project_update_terminal_posix_publish_unnamed_no_replace(
    binding: dict[str, Any],
    path: Path,
    raw: bytes,
    *,
    _failpoint: Callable[[str], None] | None = None,
) -> None:
    """Refuse the retired POSIX terminal-mutation primitive."""

    raise OSError("project_update_terminal_control_platform_unsupported")

def _project_update_publish_terminal_bytes_no_replace(
    project_root: Path,
    parent: Path,
    path: Path,
    raw: bytes,
    *,
    binding: dict[str, Any],
    _failpoint: Callable[[str], None] | None = None,
) -> None:
    """Publish complete terminal bytes inside the already-held boundary."""

    if (
        path.parent != parent
        or binding.get("path") != parent
        or len(raw) > _PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES
    ):
        raise OSError("project_update_terminal_handoff_parent_mismatch")
    if os.name != "nt":
        raise OSError("project_update_terminal_control_platform_unsupported")

    stage = _project_update_terminal_create_stage_path(path, raw)
    residue = _project_update_terminal_create_residue_path(stage)
    try:
        residue_raw, _residue_identity = (
            _project_update_terminal_bound_snapshot(
                project_root,
                binding,
                residue,
            )
        )
    except FileNotFoundError:
        residue_raw = None
    try:
        staged_raw, _staged_identity = (
            _project_update_terminal_bound_snapshot(
                project_root,
                binding,
                stage,
            )
        )
    except FileNotFoundError:
        staged_raw = None

    if staged_raw is not None and not hmac.compare_digest(staged_raw, raw):
        if residue_raw is not None:
            raise OSError("project_update_terminal_handoff_residue_exists")
        moved_partial = _project_update_terminal_windows_move_exact_no_replace(
            stage,
            residue,
            expected_raw=None,
            _failpoint=_failpoint,
        )
        if not hmac.compare_digest(moved_partial, staged_raw):
            raise OSError("project_update_terminal_handoff_stage_changed")
        staged_raw = None

    if staged_raw is None:
        published_raw = _project_update_terminal_windows_move_exact_no_replace(
            stage,
            path,
            expected_raw=None,
            create_raw=raw,
            _failpoint=_failpoint,
        )
    else:
        published_raw = _project_update_terminal_windows_move_exact_no_replace(
            stage,
            path,
            expected_raw=raw,
            _failpoint=_failpoint,
        )
    if not hmac.compare_digest(published_raw, raw):
        raise OSError(
            "project_update_terminal_handoff_publication_changed"
        )


def _project_update_write_terminal_document_exact(
    project_root: Path,
    path: Path,
    value: Mapping[str, Any],
    *,
    expected_previous_value: Mapping[str, Any] | None,
) -> str:
    if os.name != "nt":
        # This check intentionally precedes canonical-root resolution and the
        # held control boundary.  A mutation-bearing call on POSIX therefore
        # has a zero-write failure contract.
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_platform_unsupported"
        )
    raw = _project_update_canonical_bytes(dict(value))
    if len(raw) > _PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    expected_name = Path(_PROJECT_UPDATE_TERMINAL_HANDOFF_LOGICAL).name
    try:
        with _project_update_terminal_control_boundary(
            Path(project_root)
        ) as (scaffold, binding):
            parent = scaffold.terminal_root
            try:
                if (
                    path.name != expected_name
                    or not os.path.samefile(path.parent, parent)
                ):
                    raise OSError(
                        "project_update_terminal_handoff_path_changed"
                    )
            except OSError:
                raise ArchiveServiceError(
                    "project_version_update_terminal_handoff_invalid"
                ) from None
            canonical_path = parent / path.name
            existing = _project_update_read_terminal_document_bound(
                scaffold.project_root,
                binding,
                canonical_path,
            )
            if expected_previous_value is None:
                if existing is not None:
                    if hmac.compare_digest(existing[1], raw):
                        parent_descriptor = binding.get("descriptor")
                        if isinstance(parent_descriptor, int):
                            os.fsync(parent_descriptor)
                        else:
                            project_update_transaction._require_directory_durable(
                                parent
                            )
                        return project_update_transaction.sha256_bytes(raw)
                    raise ArchiveServiceError(
                        "project_version_update_terminal_handoff_conflict"
                    )
                _project_update_publish_terminal_bytes_no_replace(
                    scaffold.project_root,
                    parent,
                    canonical_path,
                    raw,
                    binding=binding,
                )
            else:
                expected_raw = _project_update_canonical_bytes(
                    dict(expected_previous_value)
                )
                if (
                    len(expected_raw)
                    > _PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES
                    or hmac.compare_digest(expected_raw, raw)
                ):
                    raise ArchiveServiceError(
                        "project_version_update_terminal_handoff_conflict"
                    )
                transition_sha256 = project_update_transaction.sha256_document(
                    {
                        "expected_previous_sha256": (
                            project_update_transaction.sha256_bytes(
                                expected_raw
                            )
                        ),
                        "replacement_sha256": (
                            project_update_transaction.sha256_bytes(raw)
                        ),
                        "schema": (
                            "wom-kit/project-version-update-terminal-cas/v0.1"
                        ),
                    }
                )
                swap_path, previous_path = regular_file_canonical_swap_paths(
                    canonical_path,
                    transition_sha256,
                    swap_suffix=".project-update-terminal-v0416",
                )
                if existing is not None and hmac.compare_digest(
                    existing[1],
                    raw,
                ):
                    swap_bytes = _activity_group_swap_residue_bytes(
                        scaffold.project_root,
                        binding,
                        swap_path,
                        max_bytes=_PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES,
                    )
                    previous_bytes = _activity_group_swap_residue_bytes(
                        scaffold.project_root,
                        binding,
                        previous_path,
                        max_bytes=_PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES,
                    )
                    residues = tuple(
                        item
                        for item in (swap_bytes, previous_bytes)
                        if item is not None
                    )
                    if len(residues) > 1 or (
                        residues and residues[0] != expected_raw
                    ):
                        raise ArchiveServiceError(
                            "project_version_update_terminal_handoff_conflict"
                        )
                    parent_descriptor = binding.get("descriptor")
                    if isinstance(parent_descriptor, int):
                        os.fsync(parent_descriptor)
                    else:
                        project_update_transaction._require_directory_durable(
                            parent
                        )
                    written = _project_update_read_terminal_document_bound(
                        scaffold.project_root,
                        binding,
                        canonical_path,
                    )
                    if written is None or not hmac.compare_digest(
                        written[1],
                        raw,
                    ):
                        raise ArchiveServiceError(
                            "project_version_update_terminal_handoff_invalid"
                        )
                    return project_update_transaction.sha256_bytes(raw)
                _replace_regular_file_bytes_compare_and_swap(
                    scaffold.project_root,
                    canonical_path,
                    expected_bytes=expected_raw,
                    replacement_bytes=raw,
                    transaction_sha256=transition_sha256,
                    swap_suffix=".project-update-terminal-v0416",
                    max_bytes=_PROJECT_UPDATE_TERMINAL_HANDOFF_MAX_BYTES,
                    error_prefix="project_update_terminal_handoff",
                    allow_already_replacement=True,
                    parent_binding=binding,
                )
            parent_descriptor = binding.get("descriptor")
            if isinstance(parent_descriptor, int):
                os.fsync(parent_descriptor)
            else:
                project_update_transaction._require_directory_durable(parent)
            written = _project_update_read_terminal_document_bound(
                scaffold.project_root,
                binding,
                canonical_path,
            )
            if written is None or not hmac.compare_digest(written[1], raw):
                raise ArchiveServiceError(
                    "project_version_update_terminal_handoff_invalid"
                )
    except OSError:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_conflict"
        ) from None
    except project_update_transaction.ProjectUpdateTransactionError as failure:
        raise ArchiveServiceError(failure.code) from None
    return project_update_transaction.sha256_bytes(raw)


def _project_update_signed_terminal_record(
    state: _ProjectVersionUpdateDurableApprovalState,
    claim: _ClaimedExactHumanApproval,
    payload: Mapping[str, Any],
    *,
    attachments: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    binding = project_version_update_approval_binding(
        state.prepared_preview
    )
    context = binding.context(
        archive_id=state.expected_archive_id,
        reviewer_claim=state.reviewer,
    )
    raw_payload = _project_update_exact_terminal_payload_bytes(payload)
    record = {
        "schema": _PROJECT_UPDATE_TERMINAL_RECORD_SCHEMA,
        "payload": dict(payload),
        "payload_sha256": project_update_transaction.sha256_bytes(
            raw_payload
        ),
        "exact_human_approval_reference": claim.public_reference(),
        "succeeded_evidence_digests": (
            claim.succeeded_evidence_digests(context)
        ),
        "terminal_record_mac": claim.exact_terminal_record_mac(
            raw_payload
        ),
        "attachments": dict(attachments or {}),
    }
    return record


def _project_update_terminal_record_matches_claim(
    record: Mapping[str, Any],
    claim: _ClaimedExactHumanApproval,
    *,
    expected_plan_sha256: str,
    expected_target_binding_sha256: str,
) -> bool:
    if (
        type(record) is not dict
        or set(record)
        != {
            "schema",
            "payload",
            "payload_sha256",
            "exact_human_approval_reference",
            "succeeded_evidence_digests",
            "terminal_record_mac",
            "attachments",
        }
        or record.get("schema") != _PROJECT_UPDATE_TERMINAL_RECORD_SCHEMA
        or type(record.get("payload")) is not dict
        or type(record.get("attachments")) is not dict
        or type(record.get("succeeded_evidence_digests")) is not dict
    ):
        return False
    raw_payload = _project_update_exact_terminal_payload_bytes(
        record["payload"]
    )
    if not hmac.compare_digest(
        project_update_transaction.sha256_bytes(raw_payload),
        str(record.get("payload_sha256") or ""),
    ):
        return False
    try:
        return bool(
            claim.status == "succeeded"
            and claim.exact_terminal_record_matches(
                record.get("exact_human_approval_reference"),
                ExactHumanApprovalOperation.project_version_update,
                expected_plan_sha256,
                expected_target_binding_sha256,
                {"succeeded"},
                record.get("succeeded_evidence_digests"),
                raw_payload,
                str(record.get("terminal_record_mac") or ""),
            )
        )
    except (ExactHumanApprovalError, TypeError, ValueError):
        return False


def _project_update_terminal_delivery_capability(
    claim: _ClaimedExactHumanApproval,
    pending_record: Mapping[str, Any],
) -> str:
    payload = _project_update_exact_terminal_payload_bytes(
        {
            "schema": (
                "wom-kit/project-version-update-terminal-delivery-capability/v0.4.16"
            ),
            "pending_record_sha256": (
                project_update_transaction.sha256_document(
                    dict(pending_record)
                )
            ),
        }
    )
    capability = claim.exact_terminal_record_mac(payload)
    if re.fullmatch(r"hmac-sha256:[0-9a-f]{64}", capability) is None:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    return capability


def _project_update_terminal_document_capability_sha256(
    document: Mapping[str, Any],
) -> str | None:
    """Read only the fixed capability digest slot for either terminal schema."""

    if document.get("state") == "terminal_ready":
        ready = document.get("ready")
        payload = ready.get("payload") if isinstance(ready, Mapping) else None
    elif document.get("state") == "terminal_ready_unapproved":
        payload = document.get("payload")
    else:
        return None
    value = (
        payload.get("delivery_capability_sha256")
        if isinstance(payload, Mapping)
        else None
    )
    return (
        str(value)
        if type(value) is str
        and re.fullmatch(r"sha256:[0-9a-f]{64}", value) is not None
        else None
    )


def _project_update_cancellation_terminal_capability(
    key: bytes | bytearray | memoryview,
    binding: Mapping[str, Any],
) -> str:
    """Derive a one-result capability without exposing recovery-key bytes."""

    capability_document = (
        project_update_legacy_recovery.authenticated_document(
            {
                "schema": (
                    "wom-kit/project-version-update-cancellation-terminal-"
                    "delivery-capability/v0.4.19"
                ),
                **dict(binding),
            },
            key,
        )
    )
    authentication = capability_document.get("authentication")
    capability = (
        authentication.get("mac")
        if isinstance(authentication, Mapping)
        else None
    )
    if (
        type(capability) is not str
        or re.fullmatch(r"hmac-sha256:[0-9a-f]{64}", capability) is None
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    return capability


def _project_update_cancellation_terminal_document(
    *,
    recovery_ref: str,
    archive_identity_sha256: str,
    intent_sha256: str,
    terminal_receipt_sha256: str,
    cancellation_result_document_sha256: str,
    key: bytes | bytearray | memoryview,
) -> tuple[dict[str, Any], str]:
    """Build one distinct, recovery-key-authenticated cancellation capsule."""

    result = _project_update_legacy_unapproved_restored_result()
    binding = {
        "archive_identity_sha256": archive_identity_sha256,
        "cancellation_result_document_sha256": (
            cancellation_result_document_sha256
        ),
        "intent_sha256": intent_sha256,
        "outcome": "unapproved_restored",
        "recovery_ref": recovery_ref,
        "result_payload_sha256": (
            project_update_transaction.sha256_document(result)
        ),
        "terminal_receipt_sha256": terminal_receipt_sha256,
    }
    if (
        re.fullmatch(r"recovery_[0-9a-f]{32}", recovery_ref) is None
        or any(
            re.fullmatch(r"sha256:[0-9a-f]{64}", str(value or ""))
            is None
            for value in (
                archive_identity_sha256,
                intent_sha256,
                terminal_receipt_sha256,
                cancellation_result_document_sha256,
                binding["result_payload_sha256"],
            )
        )
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    capability = _project_update_cancellation_terminal_capability(
        key,
        binding,
    )
    payload = {
        "schema": _PROJECT_UPDATE_CANCELLATION_TERMINAL_PAYLOAD_SCHEMA,
        **binding,
        "delivery_capability_sha256": (
            project_update_transaction.sha256_bytes(
                capability.encode("ascii")
            )
        ),
    }
    document = project_update_legacy_recovery.authenticated_document(
        {
            "schema": _PROJECT_UPDATE_CANCELLATION_TERMINAL_HANDOFF_SCHEMA,
            "state": "terminal_ready_unapproved",
            "payload": payload,
        },
        key,
    )
    return document, capability


def _project_update_verify_cancellation_terminal_document(
    document: Mapping[str, Any],
    *,
    expected_archive_identity_sha256: str,
    key: bytes | bytearray | memoryview,
) -> tuple[dict[str, Any], str]:
    """Authenticate one cancellation capsule and rebuild its fixed result."""

    try:
        verified = project_update_legacy_recovery.verify_authenticated_document(
            document,
            key,
        )
        payload = verified.get("payload")
        if (
            set(verified) != {"schema", "state", "payload"}
            or verified.get("schema")
            != _PROJECT_UPDATE_CANCELLATION_TERMINAL_HANDOFF_SCHEMA
            or verified.get("state") != "terminal_ready_unapproved"
            or not isinstance(payload, Mapping)
            or set(payload)
            != {
                "archive_identity_sha256",
                "cancellation_result_document_sha256",
                "delivery_capability_sha256",
                "intent_sha256",
                "outcome",
                "recovery_ref",
                "result_payload_sha256",
                "schema",
                "terminal_receipt_sha256",
            }
            or payload.get("schema")
            != _PROJECT_UPDATE_CANCELLATION_TERMINAL_PAYLOAD_SCHEMA
            or payload.get("outcome") != "unapproved_restored"
            or payload.get("archive_identity_sha256")
            != expected_archive_identity_sha256
            or re.fullmatch(
                r"recovery_[0-9a-f]{32}",
                str(payload.get("recovery_ref") or ""),
            )
            is None
            or any(
                re.fullmatch(r"sha256:[0-9a-f]{64}", str(value or ""))
                is None
                for value in (
                    payload.get("archive_identity_sha256"),
                    payload.get("intent_sha256"),
                    payload.get("terminal_receipt_sha256"),
                    payload.get("cancellation_result_document_sha256"),
                    payload.get("result_payload_sha256"),
                    payload.get("delivery_capability_sha256"),
                )
            )
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        binding = {
            key_name: payload[key_name]
            for key_name in (
                "archive_identity_sha256",
                "cancellation_result_document_sha256",
                "intent_sha256",
                "outcome",
                "recovery_ref",
                "result_payload_sha256",
                "terminal_receipt_sha256",
            )
        }
        capability = _project_update_cancellation_terminal_capability(
            key,
            binding,
        )
        result = _project_update_legacy_unapproved_restored_result()
        if (
            not hmac.compare_digest(
                str(payload["result_payload_sha256"]),
                project_update_transaction.sha256_document(result),
            )
            or not hmac.compare_digest(
                str(payload["delivery_capability_sha256"]),
                project_update_transaction.sha256_bytes(
                    capability.encode("ascii")
                ),
            )
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        return result, capability
    except ArchiveServiceError:
        raise
    except project_update_legacy_recovery.LegacyProjectUpdateRecoveryError:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        ) from None
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        ) from None


def _project_update_register_terminal_delivery_capability(
    handoff_sha256: str,
    capability: str,
) -> None:
    if (
        re.fullmatch(r"sha256:[0-9a-f]{64}", handoff_sha256) is None
        or re.fullmatch(r"hmac-sha256:[0-9a-f]{64}", capability) is None
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    with _PROJECT_UPDATE_TERMINAL_DELIVERY_CAPABILITIES_LOCK:
        _PROJECT_UPDATE_TERMINAL_DELIVERY_CAPABILITIES[
            handoff_sha256
        ] = capability


def _project_update_terminal_result_from_domain(
    domain_result: Mapping[str, Any],
    terminal: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Rebuild the only public result one signed domain result may become."""

    expected_terminal_keys = {
        "schema",
        "update_result_verified_in_current_invocation",
        "update_result_reauthenticated_from_durable_handoff",
        "claim_succeeded_verified",
        "transaction_completed_checkpoint_verified",
        "lock_absence_verified",
        "transaction_cleanup_completed",
        "service_resource_close_verified",
        "git_runner_close_verified",
        "attention_required",
        "domain_writer_reentry_allowed",
        "automatic_retry_allowed",
        "cleanup_proof_used_as_success_authority",
        "durable_terminal_handoff_ready",
        "durable_terminal_handoff_replayed",
        "durable_result_delivery_acknowledged",
        "private_paths_echoed",
        "private_identifiers_echoed",
    }
    current_verified = terminal.get(
        "update_result_verified_in_current_invocation"
    )
    replay_verified = terminal.get(
        "update_result_reauthenticated_from_durable_handoff"
    )
    cleanup_completed = terminal.get("transaction_cleanup_completed")
    service_resource_close_verified = terminal.get(
        "service_resource_close_verified"
    )
    runner_close_verified = terminal.get("git_runner_close_verified")
    delivery_acknowledged = terminal.get(
        "durable_result_delivery_acknowledged"
    )
    expected_attention = not (
        cleanup_completed is True
        and service_resource_close_verified is True
        and runner_close_verified is True
        and delivery_acknowledged is True
    )
    if (
        not isinstance(domain_result, Mapping)
        or domain_result.get("ok") is not True
        or type(terminal) is not dict
        or set(terminal) != expected_terminal_keys
        or terminal.get("schema")
        != "wom-kit/project-version-update-terminal-finalization/v0.1"
        or type(current_verified) is not bool
        or type(replay_verified) is not bool
        or current_verified is replay_verified
        or terminal.get("claim_succeeded_verified") is not True
        or terminal.get("transaction_completed_checkpoint_verified")
        is not True
        or terminal.get("lock_absence_verified") is not True
        or type(cleanup_completed) is not bool
        or type(service_resource_close_verified) is not bool
        or type(runner_close_verified) is not bool
        or terminal.get("attention_required") is not expected_attention
        or terminal.get("domain_writer_reentry_allowed") is not False
        or terminal.get("automatic_retry_allowed") is not False
        or terminal.get("cleanup_proof_used_as_success_authority")
        is not False
        or terminal.get("durable_terminal_handoff_ready") is not True
        or terminal.get("durable_terminal_handoff_replayed")
        is not replay_verified
        or type(delivery_acknowledged) is not bool
        or terminal.get("private_paths_echoed") is not False
        or terminal.get("private_identifiers_echoed") is not False
    ):
        return None
    projected = copy.deepcopy(dict(domain_result))
    project_runtime_result = projected.get("project_runtime")
    materialized = (
        project_runtime_result.get("materialized")
        if isinstance(project_runtime_result, dict)
        else None
    )
    if isinstance(materialized, dict) and materialized.get("repaired") is True:
        # The signed domain result is created while the private rollback
        # preimage still exists.  Public terminal truth must describe the
        # post-cleanup filesystem, not repeat that earlier active-stage fact.
        materialized["rollback_preimage_present"] = (
            False if cleanup_completed else None
        )
        materialized["rollback_preimage_presence_verified"] = cleanup_completed
        materialized["old_invalid_runtime_retained_after_success"] = (
            False if cleanup_completed else None
        )
        materialized["repair_preimage_retention_state"] = (
            "removed_by_terminal_cleanup"
            if cleanup_completed
            else "unknown_cleanup_incomplete"
        )
    projected["terminal_finalization"] = copy.deepcopy(dict(terminal))
    projected["post_update_attention_required"] = expected_attention
    if expected_attention:
        cleanup_attention = not (
            cleanup_completed is True
            and service_resource_close_verified is True
            and runner_close_verified is True
        )
        warning = (
            _PROJECT_UPDATE_TERMINAL_CLEANUP_WARNING
            if cleanup_attention
            else _PROJECT_UPDATE_TERMINAL_DELIVERY_WARNING
        )
        action = (
            _PROJECT_UPDATE_TERMINAL_CLEANUP_ACTION
            if cleanup_attention
            else _PROJECT_UPDATE_TERMINAL_DELIVERY_ACTION
        )
        warnings = projected.get("warnings")
        if isinstance(warnings, list) and warning not in warnings:
            projected["warnings"] = [*warnings, warning]
        next_actions = projected.get("next_safe_actions")
        if isinstance(next_actions, list) and action not in next_actions:
            projected["next_safe_actions"] = [action, *next_actions]
    return projected


def _project_update_terminal_result_matches_pending(
    result: Mapping[str, Any],
    pending_record: Mapping[str, Any],
) -> bool:
    try:
        _preview, domain_result, _basis, _postimage = (
            _project_update_terminal_handoff_attachments(pending_record)
        )
    except ArchiveServiceError:
        return False
    terminal = result.get("terminal_finalization")
    if type(terminal) is not dict:
        return False
    expected = _project_update_terminal_result_from_domain(
        domain_result,
        terminal,
    )
    return bool(
        expected is not None
        and hmac.compare_digest(
            project_update_transaction.canonical_json_bytes(expected),
            project_update_transaction.canonical_json_bytes(dict(result)),
        )
    )


def _project_update_terminal_delivery_capability_for_result(
    inspection_root: Path | str,
    result: Mapping[str, Any],
) -> tuple[str, str] | None:
    terminal = result.get("terminal_finalization")
    cancellation_result = (
        _project_update_is_legacy_unapproved_terminal_result(result)
    )
    if not cancellation_result and (
        not isinstance(terminal, Mapping)
        or terminal.get("durable_terminal_handoff_ready") is not True
        or result.get("ok") is not True
    ):
        return None
    project_root = _project_update_resume_project_root_read_only(
        inspection_root
    )
    handoff, _guard = _project_update_terminal_handoff_paths(
        project_root
    )
    observed = _project_update_read_terminal_document(project_root, handoff)
    expected_state = (
        "terminal_ready_unapproved"
        if cancellation_result
        else "terminal_ready"
    )
    if observed is None or observed[0].get("state") != expected_state:
        return None
    handoff_sha256 = project_update_transaction.sha256_bytes(observed[1])
    if cancellation_result:
        payload = observed[0].get("payload")
        with _PROJECT_UPDATE_TERMINAL_DELIVERY_CAPABILITIES_LOCK:
            capability = _PROJECT_UPDATE_TERMINAL_DELIVERY_CAPABILITIES.get(
                handoff_sha256
            )
        if (
            not isinstance(payload, Mapping)
            or payload.get("schema")
            != _PROJECT_UPDATE_CANCELLATION_TERMINAL_PAYLOAD_SCHEMA
            or payload.get("outcome") != "unapproved_restored"
            or payload.get("result_payload_sha256")
            != project_update_transaction.sha256_document(dict(result))
            or type(capability) is not str
            or not hmac.compare_digest(
                project_update_transaction.sha256_bytes(
                    capability.encode("ascii")
                ),
                str(payload.get("delivery_capability_sha256") or ""),
            )
        ):
            return None
        return capability, handoff_sha256
    pending = observed[0].get("pending")
    ready = observed[0].get("ready")
    ready_payload = ready.get("payload") if type(ready) is dict else None
    with _PROJECT_UPDATE_TERMINAL_DELIVERY_CAPABILITIES_LOCK:
        capability = _PROJECT_UPDATE_TERMINAL_DELIVERY_CAPABILITIES.get(
            handoff_sha256
        )
    if (
        type(ready_payload) is not dict
        or type(pending) is not dict
        or not _project_update_terminal_result_matches_pending(
            result,
            pending,
        )
        or type(capability) is not str
        or not hmac.compare_digest(
            project_update_transaction.sha256_bytes(
                capability.encode("ascii")
            ),
            str(
                ready_payload.get("delivery_capability_sha256") or ""
            ),
        )
    ):
        return None
    return capability, handoff_sha256


def _project_update_terminal_delivery_output_proof(
    capability: str,
    result: Mapping[str, Any],
    *,
    handoff_sha256: str,
    output_relative: str,
    run_id: str,
    operation_ref: str,
) -> dict[str, str]:
    """Bind one private capability to the exact immutable output wrapper."""

    if (
        re.fullmatch(r"hmac-sha256:[0-9a-f]{64}", capability) is None
        or re.fullmatch(r"sha256:[0-9a-f]{64}", handoff_sha256) is None
        or not isinstance(result, Mapping)
        or not (
            result.get("ok") is True
            or _project_update_is_legacy_unapproved_terminal_result(result)
        )
        or type(output_relative) is not str
        or not output_relative.startswith(
            _PROJECT_UPDATE_OUTPUT_LOGICAL_PREFIX
        )
        or PurePosixPath(output_relative).is_absolute()
        or ".." in PurePosixPath(output_relative).parts
        or re.fullmatch(r"[0-9a-f]{32}", run_id) is None
        or re.fullmatch(r"op:sha256:[0-9a-f]{64}", operation_ref) is None
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_delivery_binding_invalid"
        )
    binding = {
        "schema": (
            "wom-kit/project-version-update-terminal-delivery-binding/v0.4.16"
        ),
        "terminal_handoff_sha256": handoff_sha256,
        "result_payload_sha256": (
            project_update_transaction.sha256_document(dict(result))
        ),
        "output_relative_sha256": (
            project_update_transaction.sha256_bytes(
                output_relative.encode("utf-8")
            )
        ),
        "run_id": run_id,
        "operation_ref": operation_ref,
    }
    proof = "hmac-sha256:" + hmac.new(
        capability.encode("ascii"),
        b"wom-kit/project-version-update-terminal-delivery-proof/v0.4.16\x00"
        + project_update_transaction.canonical_json_bytes(binding),
        hashlib.sha256,
    ).hexdigest()
    return {**binding, "proof": proof}


def _project_update_privacy_safe_domain_result(
    result: Mapping[str, Any],
) -> dict[str, Any]:
    """Remove private approval/transaction locators from a replayable result."""

    if not isinstance(result, Mapping) or result.get("ok") is not True:
        raise ArchiveServiceError(
            "project_version_update_terminal_result_unverified"
        )
    private_container_keys = {
        "operation_exact_human_approval",
        "exact_human_approval",
        "exact_human_approval_reference",
        "exact_human_approval_resume_branch",
    }
    private_binding_keys = {
        "transaction_ref",
        "transaction_logical_ref",
        "candidate_locator",
        "seal_locator",
        "approval_id",
        "approval_ref",
        "claim_locator",
        "claim_path",
        "transaction_path",
    }
    private_key_suffixes = (
        "_transaction_ref",
        "_transaction_logical_ref",
        "_candidate_locator",
        "_seal_locator",
        "_approval_id",
        "_approval_ref",
        "_claim_locator",
        "_claim_path",
        "_transaction_path",
    )
    private_path_markers = (
        ".zettel-kasten/private",
        ".wom-scratch/private",
        "profiles/local/exact-human-approvals/claims",
    )

    def is_private_key(key: str) -> bool:
        lowered = key.casefold()
        return bool(
            lowered in private_container_keys
            or lowered in private_binding_keys
            or lowered.endswith(private_key_suffixes)
        )

    def is_private_binding_key(key: str) -> bool:
        lowered = key.casefold()
        return bool(
            lowered in private_binding_keys
            or lowered.endswith(private_key_suffixes)
        )

    private_bindings: dict[str, str] = {}
    private_transaction_refs: set[str] = set()
    private_approval_ids: set[str] = set()
    pending_private_locators: list[tuple[str, str]] = []

    def collect_private_binding(key: str, value: Any) -> None:
        if type(value) is not str or not value:
            raise ArchiveServiceError(
                "project_version_update_terminal_result_unverified"
            )
        lowered = key.casefold()
        if lowered.endswith("_transaction_ref") or lowered == "transaction_ref":
            if re.fullmatch(r"update_[0-9a-f]{32}", value) is None:
                raise ArchiveServiceError(
                    "project_version_update_terminal_result_unverified"
                )
            private_transaction_refs.add(value)
            private_bindings[value] = "<private-transaction>"
            return
        if (
            lowered.endswith("_approval_id")
            or lowered.endswith("_approval_ref")
            or lowered in {"approval_id", "approval_ref"}
        ):
            if re.fullmatch(r"approval_[0-9a-f]{32}", value) is None:
                raise ArchiveServiceError(
                    "project_version_update_terminal_result_unverified"
                )
            private_approval_ids.add(value)
            private_bindings[value] = "<private-approval>"
            return
        pending_private_locators.append((lowered, value))

    def collect_private_bindings(value: Any) -> None:
        if isinstance(value, Mapping):
            for key, child in value.items():
                if type(key) is not str:
                    raise ArchiveServiceError(
                        "project_version_update_terminal_result_unverified"
                    )
                if is_private_binding_key(key):
                    collect_private_binding(key, child)
                collect_private_bindings(child)
            return
        if isinstance(value, (list, tuple)):
            for child in value:
                collect_private_bindings(child)
            return
        if value is None or type(value) in {str, bool, int, float}:
            return
        raise ArchiveServiceError(
            "project_version_update_terminal_result_unverified"
        )

    collect_private_bindings(result)
    if len(private_transaction_refs) > 1 or len(private_approval_ids) > 1:
        raise ArchiveServiceError(
            "project_version_update_terminal_result_unverified"
        )

    transaction_root = project_update_transaction.TRANSACTION_ROOT_LOGICAL
    claims_root = CLAIMS_RELATIVE_ROOT

    def safe_private_locator(
        key: str,
        value: str,
    ) -> tuple[str, str] | None:
        if len(value.encode("utf-8", errors="strict")) > 1024 or "\\" in value:
            return None
        candidate = PurePosixPath(value)
        if (
            candidate.is_absolute()
            or candidate.as_posix() != value
            or any(part in {"", ".", ".."} for part in candidate.parts)
            or "://" in value.casefold()
        ):
            return None
        parts = candidate.parts
        transaction_prefix = PurePosixPath(transaction_root).parts
        claims_prefix = PurePosixPath(claims_root).parts
        transaction_key_family = bool(
            key.endswith("transaction_logical_ref")
            or key.endswith("candidate_locator")
            or key.endswith("seal_locator")
            or key == "transaction_path"
        )
        claim_key_family = key in {"claim_locator", "claim_path"}
        if parts[: len(transaction_prefix)] == transaction_prefix:
            if not transaction_key_family:
                return None
            tail = parts[len(transaction_prefix) :]
            if (
                not tail
                or re.fullmatch(r"update_[0-9a-f]{32}", tail[0]) is None
                or tail[0] not in private_transaction_refs
            ):
                return None
            if key.endswith("transaction_logical_ref") or key == "transaction_path":
                if len(tail) != 1:
                    return None
            elif key.endswith("candidate_locator"):
                if tail != (
                    tail[0],
                    project_update_transaction.RUNTIME_CANDIDATE_NAME,
                ):
                    return None
            elif key.endswith("seal_locator"):
                if tail != (
                    tail[0],
                    project_update_transaction.RUNTIME_CANDIDATE_SEAL_NAME,
                ):
                    return None
            elif len(tail) < 1:
                return None
            return value, "<private-control-path>"
        if parts[: len(claims_prefix)] == claims_prefix:
            if not claim_key_family:
                return None
            tail = parts[len(claims_prefix) :]
            if len(tail) != 1:
                return None
            approval_name = tail[0]
            if approval_name.endswith(".json"):
                approval_name = approval_name[:-5]
            if (
                approval_name not in private_approval_ids
                or re.fullmatch(r"approval_[0-9a-f]{32}", approval_name)
                is None
            ):
                return None
            return value, "<private-control-path>"
        return None

    for locator_key, locator_value in pending_private_locators:
        try:
            validated = safe_private_locator(locator_key, locator_value)
        except UnicodeError:
            validated = None
        if validated is None:
            raise ArchiveServiceError(
                "project_version_update_terminal_result_unverified"
            )
        private_bindings[validated[0]] = validated[1]

    def has_private_project_marker(value: str) -> bool:
        normalized = value.replace("\\", "/").casefold()
        for marker in private_path_markers:
            start = 0
            while True:
                index = normalized.find(marker, start)
                if index < 0:
                    break
                end = index + len(marker)
                if end == len(normalized) or normalized[end] == "/":
                    return True
                start = index + 1
        return False

    local_path_patterns = (
        r"(?i)(?<![A-Za-z0-9])[A-Z]:[\\/]",
        r"(?i)file:(?:/{2,3}|\\\\)",
        (
            r"(?<![A-Za-z0-9\\])\\\\"
            r"[^\\/\s]+[\\/][^\\/\s]+"
        ),
        (
            r"(?<![A-Za-z0-9\\])\\(?!\\)(?:$|[^\\\s])"
        ),
        (
            r"(?<![A-Za-z0-9/])//(?=[^/\s])"
        ),
        (
            r"(?i)(?<![A-Za-z0-9/])/(?!/)"
            r"(?:$|[^/\s])"
        ),
    )

    def sanitize_text(
        value: str,
        *,
        public_route_allowed: bool,
    ) -> str:
        if has_private_project_marker(value) and value not in private_bindings:
            return "<private-project-metadata>"
        safe_text = value
        for private_value in sorted(
            private_bindings,
            key=len,
            reverse=True,
        ):
            if private_value:
                safe_text = safe_text.replace(
                    private_value,
                    private_bindings[private_value],
                )
        if re.search(
            r"(?i)(?:update|approval)_[0-9a-f]{32}",
            safe_text,
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_result_unverified"
            )
        if has_private_project_marker(safe_text):
            return "<private-project-metadata>"
        if public_route_allowed and (
            re.fullmatch(r"//[^\s]+", safe_text) is not None
            or re.fullmatch(r"(?i)/api(?:/[^\s]*)?", safe_text) is not None
        ):
            return safe_text
        if any(re.search(pattern, safe_text) for pattern in local_path_patterns):
            return "<private-local-path>"
        return safe_text

    def sanitize(value: Any, key_path: tuple[str, ...] = ()) -> Any:
        if isinstance(value, Mapping):
            safe: dict[str, Any] = {}
            for key, child in value.items():
                if type(key) is not str:
                    raise ArchiveServiceError(
                        "project_version_update_terminal_result_unverified"
                    )
                if is_private_key(key):
                    continue
                safe_key = sanitize_text(
                    key,
                    public_route_allowed=False,
                )
                if safe_key in safe:
                    raise ArchiveServiceError(
                        "project_version_update_terminal_result_unverified"
                    )
                safe[safe_key] = sanitize(child, (*key_path, key))
            return safe
        if isinstance(value, (list, tuple)):
            return [
                sanitize(child, (*key_path, "<sequence-item>"))
                for child in value
            ]
        if type(value) is str:
            return sanitize_text(
                value,
                public_route_allowed=key_path
                in {
                    ("public_routes", "docs"),
                    ("public_routes", "api"),
                },
            )
        if value is None or type(value) in {bool, int, float}:
            return value
        raise ArchiveServiceError(
            "project_version_update_terminal_result_unverified"
        )

    projected = sanitize(result)
    if not isinstance(projected, dict):
        raise ArchiveServiceError(
            "project_version_update_terminal_result_unverified"
        )
    projected["approval_verification"] = {
        "exact_human_approval_succeeded": True,
        "one_use_claim_reauthenticated": True,
        "approval_identifiers_echoed": False,
        "private_paths_echoed": False,
    }
    return projected


def _project_update_terminal_recovery_basis(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> dict[str, Any]:
    components = [
        {
            "component_ref": component.component_ref,
            "role": component.role,
            "logical_target": component.logical_target,
            "post_sha256": component.post_sha256,
        }
        for component in state.transaction.intent.components
    ]
    return {
        "schema": (
            "wom-kit/project-version-update-terminal-recovery-basis/v0.4.16"
        ),
        "mirror_logical": state.private_plan["mirror_logical"],
        "target_tag": state.target_tag,
        "target_version": state.target_version,
        "target_commit": state.target_commit,
        "target_ref_snapshot": copy.deepcopy(
            state.private_plan["target_ref_snapshot"]
        ),
        "git_runner_binding": _project_update_private_json_value(
            state.runner.private_binding_bytes()
        ),
        "runtime": {
            "target_version": state.target_version,
            "target_commit": state.target_commit,
            "wheel_sha256": "sha256:" + state.runtime_candidate.wheel_sha256,
            "supply_lock_sha256": (
                "sha256:" + state.runtime_candidate.supply_lock_sha256
            ),
            "installed_payload_sha256": (
                "sha256:" + state.runtime_candidate.installed_payload_sha256
            ),
            "receipt_sha256": (
                "sha256:" + state.runtime_candidate.receipt_sha256
            ),
        },
        "components": components,
    }


def _project_update_publish_preunlock_terminal_handoff(
    state: _ProjectVersionUpdateDurableApprovalState,
    claim: _ClaimedExactHumanApproval,
    domain_result: Mapping[str, Any],
) -> tuple[dict[str, Any], str]:
    if not _project_update_terminal_execution_lease_is_held(state):
        raise ArchiveServiceError(
            "project_version_update_terminal_execution_boundary_unknown"
        )
    inspection = state.transaction.inspect()
    claim_checkpoints = [
        item
        for item in inspection.journal.verified_prefix
        if item.phase == "claim_succeeded"
    ]
    if (
        inspection.journal.state != "exact"
        or len(claim_checkpoints) != 1
        or inspection.journal.verified_prefix[-1].phase
        not in {
            "claim_succeeded",
            "ready_to_unlock",
            "lock_released",
            "completed",
        }
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    binding = project_version_update_approval_binding(
        state.prepared_preview
    )
    handoff, _guard = _project_update_terminal_handoff_paths(
        state.project_root
    )
    existing = _project_update_read_terminal_document(
        state.project_root,
        handoff,
    )
    if existing is not None:
        active, active_bytes = existing
        pending_record = active.get("pending")
        pending_payload = (
            pending_record.get("payload")
            if isinstance(pending_record, dict)
            else None
        )
        attachments = (
            pending_record.get("attachments")
            if isinstance(pending_record, dict)
            else None
        )
        if (
            active.get("schema") != _PROJECT_UPDATE_TERMINAL_HANDOFF_SCHEMA
            or active.get("state")
            not in {"claim_succeeded_pre_unlock", "terminal_ready"}
            or not _project_update_terminal_record_matches_claim(
                pending_record,
                claim,
                expected_plan_sha256=binding.plan_sha256,
                expected_target_binding_sha256=(
                    binding.target_binding_sha256
                ),
            )
            or type(pending_payload) is not dict
            or pending_payload.get("transaction_ref")
            != state.transaction.transaction_ref
            or pending_payload.get("intent_sha256")
            != state.transaction.intent.sha256
            or pending_payload.get(
                "legacy_cleanup_authority_sha256"
            )
            != state.existing_cleanup_authority_sha256
            or type(attachments) is not dict
            or project_update_transaction.sha256_document(
                attachments.get("prepared_preview")
            )
            != pending_payload.get("prepared_preview_sha256")
            or project_update_transaction.sha256_document(
                attachments.get("domain_result")
            )
            != pending_payload.get("domain_result_sha256")
            or len(
                project_update_transaction.canonical_json_bytes(
                    attachments.get("domain_result")
                )
            )
            != pending_payload.get("domain_result_size_bytes")
            or project_update_transaction.sha256_document(
                attachments.get("recovery_basis")
            )
            != pending_payload.get("recovery_basis_sha256")
            or project_update_transaction.sha256_document(
                attachments.get("exact_postimage")
            )
            != pending_payload.get("exact_postimage_sha256")
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        state.terminal_domain_result = copy.deepcopy(
            attachments["domain_result"]
        )
        return (
            dict(pending_record),
            project_update_transaction.sha256_bytes(active_bytes),
        )
    recovery_basis = _project_update_terminal_recovery_basis(state)
    live = _project_update_live_component_sha256(state)
    safe_result = _project_update_privacy_safe_domain_result(domain_result)
    domain_result_bytes = project_update_transaction.canonical_json_bytes(
        safe_result
    )
    state.terminal_domain_result = copy.deepcopy(safe_result)
    payload = {
        "schema": (
            "wom-kit/project-version-update-preunlock-handoff-payload/v0.4.16"
        ),
        "state": "claim_succeeded_pre_unlock",
        "transaction_ref": state.transaction.transaction_ref,
        "intent_sha256": state.transaction.intent.sha256,
        "project_identity_sha256": (
            state.transaction.intent.project_identity_sha256
        ),
        "plan_sha256": binding.plan_sha256,
        "target_binding_sha256": binding.target_binding_sha256,
        "reviewer": state.reviewer,
        "claim_succeeded_checkpoint_sha256": (
            claim_checkpoints[0].checkpoint_sha256
        ),
        "prepared_preview_sha256": (
            project_update_transaction.sha256_document(
                state.prepared_preview
            )
        ),
        "domain_result_sha256": (
            project_update_transaction.sha256_bytes(domain_result_bytes)
        ),
        "domain_result_size_bytes": len(domain_result_bytes),
        "recovery_basis_sha256": (
            project_update_transaction.sha256_document(recovery_basis)
        ),
        "exact_postimage_sha256": (
            project_update_transaction.sha256_document(live)
        ),
        "legacy_cleanup_authority_sha256": (
            state.existing_cleanup_authority_sha256
        ),
    }
    pending_record = _project_update_signed_terminal_record(
        state,
        claim,
        payload,
        attachments={
            "prepared_preview": copy.deepcopy(state.prepared_preview),
            "domain_result": safe_result,
            "recovery_basis": recovery_basis,
            "exact_postimage": live,
        },
    )
    active = {
        "schema": _PROJECT_UPDATE_TERMINAL_HANDOFF_SCHEMA,
        "state": "claim_succeeded_pre_unlock",
        "pending": pending_record,
    }
    handoff_sha256 = _project_update_write_terminal_document_exact(
        state.project_root,
        handoff,
        active,
        expected_previous_value=None,
    )
    return pending_record, handoff_sha256


def _project_update_publish_ready_terminal_handoff(
    state: _ProjectVersionUpdateDurableApprovalState,
    claim: _ClaimedExactHumanApproval,
    pending_record: Mapping[str, Any],
    pending_handoff_sha256: str,
    live: Mapping[str, str],
) -> str:
    if not _project_update_terminal_execution_lease_is_held(state):
        raise ArchiveServiceError(
            "project_version_update_terminal_execution_boundary_unknown"
        )
    inspection = state.transaction.inspect()
    if (
        not inspection.terminal
        or inspection.journal.state != "exact"
        or not inspection.journal.verified_prefix
        or inspection.journal.verified_prefix[-1].phase != "completed"
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    binding = project_version_update_approval_binding(
        state.prepared_preview
    )
    pending_sha256 = project_update_transaction.sha256_document(
        dict(pending_record)
    )
    delivery_capability = _project_update_terminal_delivery_capability(
        claim,
        pending_record,
    )
    ready_payload = {
        "schema": (
            "wom-kit/project-version-update-ready-handoff-payload/v0.4.16"
        ),
        "state": "terminal_ready",
        "transaction_ref": state.transaction.transaction_ref,
        "intent_sha256": state.transaction.intent.sha256,
        "plan_sha256": binding.plan_sha256,
        "target_binding_sha256": binding.target_binding_sha256,
        "pending_record_sha256": pending_sha256,
        "claim_succeeded_checkpoint_sha256": (
            pending_record["payload"][
                "claim_succeeded_checkpoint_sha256"
            ]
        ),
        "completed_checkpoint_sha256": (
            inspection.journal.verified_prefix[-1].checkpoint_sha256
        ),
        "completed_checkpoint_count": len(
            inspection.journal.verified_prefix
        ),
        "lock_absence_observation_sha256": (
            inspection.journal.verified_prefix[-1]
            .live_lock_observation_sha256
        ),
        "exact_postimage_sha256": (
            project_update_transaction.sha256_document(dict(live))
        ),
        "delivery_capability_sha256": (
            project_update_transaction.sha256_bytes(
                delivery_capability.encode("ascii")
            )
        ),
        "legacy_cleanup_authority_sha256": (
            pending_record["payload"].get(
                "legacy_cleanup_authority_sha256"
            )
        ),
    }
    ready_record = _project_update_signed_terminal_record(
        state,
        claim,
        ready_payload,
    )
    active = {
        "schema": _PROJECT_UPDATE_TERMINAL_HANDOFF_SCHEMA,
        "state": "terminal_ready",
        "pending": dict(pending_record),
        "ready": ready_record,
    }
    handoff, _guard = _project_update_terminal_handoff_paths(
        state.project_root
    )
    expected_pending_active = {
        "schema": _PROJECT_UPDATE_TERMINAL_HANDOFF_SCHEMA,
        "state": "claim_succeeded_pre_unlock",
        "pending": dict(pending_record),
    }
    if not hmac.compare_digest(
        project_update_transaction.sha256_bytes(
            _project_update_canonical_bytes(expected_pending_active)
        ),
        pending_handoff_sha256,
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_handoff_invalid"
        )
    handoff_sha256 = _project_update_write_terminal_document_exact(
        state.project_root,
        handoff,
        active,
        expected_previous_value=expected_pending_active,
    )
    _project_update_register_terminal_delivery_capability(
        handoff_sha256,
        delivery_capability,
    )
    return handoff_sha256


def _project_update_claim_authority(
    state: _ProjectVersionUpdateDurableApprovalState,
    claim: _ClaimedExactHumanApproval,
) -> tuple[str, str]:
    if (
        type(state.approved_plan_sha256) is not str
        or type(state.approved_target_binding_sha256) is not str
    ):
        raise ArchiveServiceError(
            "project_version_update_approval_binding_unavailable"
        )
    reference_sha256 = project_update_transaction.sha256_bytes(
        _project_update_canonical_bytes(claim.public_reference())
    )
    payload = project_update_transaction.canonical_json_bytes(
        {
            "approval_reference_sha256": reference_sha256,
            "intent_sha256": state.transaction.intent.sha256,
            "operation": "project_version_update",
            "plan_sha256": state.approved_plan_sha256,
            "schema": (
                "wom-kit/project-update-transaction-approval-authority/v0.4.3"
            ),
            "target_binding_sha256": (
                state.approved_target_binding_sha256
            ),
            "transaction_ref": state.transaction.transaction_ref,
        }
    )
    approval_mac = claim.approval_integrity_mac(payload)
    return (
        reference_sha256,
        project_update_transaction.sha256_bytes(
            approval_mac.encode("ascii")
        ),
    )


def _project_update_runtime_matches_candidate(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> bool:
    """Compatibility scalar for callers that need only an exact match."""

    return _project_update_runtime_candidate_observation(state)["state"] == "passed"


def _project_update_runtime_candidate_observation(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> dict[str, str]:
    """Preserve runtime candidate drift versus observation failure."""

    try:
        observation = project_runtime._existing_runtime_candidate_observation(
            state.project_root,
            state.runtime_candidate,
        )
    except OSError:
        return {
            "state": "unavailable",
            "reason_code": "project_runtime_existing_observation_unavailable",
        }
    except project_runtime.ProjectRuntimeError as error:
        unavailable = project_runtime._runtime_error_is_observation_unavailable(
            error
        )
        return {
            "state": "unavailable" if unavailable else "failed",
            "reason_code": str(error),
        }
    if observation["state"] == "unavailable":
        return {
            "state": "unavailable",
            "reason_code": str(observation["reason_code"]),
        }
    if observation["matches"]:
        return {"state": "passed", "reason_code": "verified"}
    return {
        "state": "failed",
        "reason_code": str(observation["reason_code"]),
    }


def _project_update_source_live_sha256(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> str:
    plan = state.private_plan
    expected_pre = plan.get("preflight_git_snapshot")
    current = _wom_kit_project_update_git_snapshot(
        state.mirror_path,
        runner=state.runner,
    )
    if current == expected_pre:
        return state.source_pre_sha256
    if state.source_pre_sha256 == state.source_post_sha256:
        return _project_update_unknown_component_sha256("source")
    try:
        versions = wom_kit_project_update_source_versions(state.mirror_path)
        ref_snapshot = wom_kit_project_update_target_ref_snapshot(
            state.mirror_path,
            state.target_tag,
            runner=state.runner,
        )
        runtime_source = wom_kit_runtime_tracked_python_integrity(
            state.project_root,
            state.mirror_path,
            runner=state.runner,
        )
        runtime_resources = wom_kit_runtime_resource_integrity(
            state.project_root,
            state.mirror_path,
            ref=state.target_commit,
            runner=state.runner,
        )
        if (
            wom_kit_project_update_snapshot_is_clean(
                current,
                expected_head=state.target_commit,
                expected_branch=None,
            )
            and all(
                normalize_version_label(value) == state.target_version
                for value in versions.values()
            )
            and ref_snapshot == plan.get("target_ref_snapshot")
            and runtime_source.get("tracked_python_sources_verified") is True
            and runtime_resources.get("runtime_resources_verified") is True
        ):
            return state.source_post_sha256
    except (OSError, RuntimeError, ValueError):
        pass
    return _project_update_unknown_component_sha256("source")


def _project_update_live_component_sha256(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> dict[str, str]:
    """Classify every exact component without exposing any live value."""

    live: dict[str, str] = {
        "source": _project_update_source_live_sha256(state),
    }
    runtime_observation = _project_update_runtime_candidate_observation(state)
    if runtime_observation["state"] == "passed":
        live["runtime"] = state.runtime_post_sha256
    elif runtime_observation["state"] == "unavailable":
        live["runtime"] = _project_update_unknown_component_sha256(
            "runtime"
        )
    elif state.runtime_candidate.existing_runtime_repair_required:
        repair_observation = project_runtime.runtime_repair_state_observation(
            state.runtime_candidate
        )
        if (
            repair_observation["state"] == "passed"
            and repair_observation["repair_state"]
            in {"preimage_final", "backup_only"}
        ):
            live["runtime"] = state.runtime_pre_sha256
        else:
            live["runtime"] = _project_update_unknown_component_sha256(
                "runtime"
            )
    elif state.runtime_pre_sha256 == (
        project_update_transaction.ABSENT_COMPONENT_SHA256
    ):
        final_observation = project_runtime._runtime_path_presence_observation(
            project_runtime.runtime_path(
                state.project_root,
                state.target_version,
            )
        )
        live["runtime"] = (
            state.runtime_pre_sha256
            if final_observation["state"] == "passed"
            and final_observation["present"] is False
            else _project_update_unknown_component_sha256("runtime")
        )
    else:
        live["runtime"] = _project_update_unknown_component_sha256(
            "runtime"
        )

    for component in state.transaction.intent.components:
        if component.component_ref in {"source", "runtime"}:
            continue
        path = state.component_paths.get(component.component_ref)
        if not isinstance(path, Path):
            live[component.component_ref] = (
                _project_update_unknown_component_sha256(
                    component.component_ref
                )
            )
            continue
        maximum = (
            _PROJECT_UPDATE_RECEIPT_MAX_BYTES
            if component.role == "receipt"
            else 64 * 1024
            if component.role == "launcher"
            else WOM_KIT_VERSION_PIN_MAX_BYTES
        )
        value = _project_update_safe_read_component(
            state.project_root,
            path,
            maximum=maximum,
        )
        swap_path = _project_update_component_swap_path(state, component)
        if value is None and os.path.lexists(swap_path):
            # The exact Windows publisher first moves the observed preimage to
            # this transaction-bound no-replace slot.  A hard exit in that
            # narrow interval is still a preimage, not unexplained absence.
            swap_value = _project_update_safe_read_component(
                state.project_root,
                swap_path,
                maximum=maximum,
            )
            if (
                isinstance(swap_value, bytes)
                and hmac.compare_digest(
                    _project_update_raw_component_sha256(swap_value),
                    component.pre_sha256,
                )
            ):
                value = swap_value
        live[component.component_ref] = (
            _project_update_unknown_component_sha256(
                component.component_ref
            )
            if value is not None and not isinstance(value, bytes)
            else _project_update_raw_component_sha256(value)
        )
    return live


def _project_update_component_swap_path(
    state: _ProjectVersionUpdateDurableApprovalState,
    component: project_update_transaction.ProjectUpdateComponent,
) -> Path:
    """Return one content-free, transaction-bound same-volume swap name."""

    target = state.component_paths[component.component_ref]
    transaction_ref = state.transaction.transaction_ref
    token = hashlib.sha256(
        f"{transaction_ref}\0{component.component_ref}".encode("ascii")
    ).hexdigest()[:24]
    return target.with_name(f".{target.name}.wom-swap-{token}")


def _project_update_delete_exact_swap_bytes(
    project_root: Path,
    swap_path: Path,
    expected_raw: bytes,
) -> None:
    """Delete one exact Windows swap while holding a no-write handle.

    A name-based ``unlink`` after a hash check has a check/delete race: another
    process can still mutate or replace the swap between those operations.  The
    retained-handle primitive opens the exact object without sharing write
    access, revalidates its identity and complete digest through that handle,
    marks that handle delete-pending, and only then closes it.  If any writer is
    still able to change the object, the open or validation fails and the swap
    remains recoverable.
    """

    if os.name != "nt":
        raise ArchiveServiceError(
            "project_version_update_component_swap_cleanup_unsupported"
        )
    try:
        observed = os.lstat(swap_path)
    except OSError:
        raise ArchiveServiceError(
            "project_version_update_component_swap_cleanup_failed"
        ) from None
    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
    if (
        not stat.S_ISREG(observed.st_mode)
        or stat.S_ISLNK(observed.st_mode)
        or int(observed.st_nlink) != 1
        or int(observed.st_size) != len(expected_raw)
        or bool(
            reparse_flag
            and getattr(observed, "st_file_attributes", 0) & reparse_flag
        )
    ):
        raise ArchiveServiceError(
            "project_version_update_component_swap_cleanup_failed"
        )
    expected = {
        "type": "file",
        "identity": {
            "device": int(observed.st_dev),
            "inode": int(observed.st_ino),
        },
        "size": len(expected_raw),
        "mtime_ns": int(observed.st_mtime_ns),
        "sha256": hashlib.sha256(expected_raw).hexdigest(),
    }
    try:
        # Local import avoids the intentional reverse dependency used by the
        # generic cleanup module to reuse this module's directory binding.
        from .legacy_cleanup_bound_delete import _delete_exact_approved_file

        _delete_exact_approved_file(project_root, swap_path, expected)
        project_update_transaction._require_directory_durable(swap_path.parent)
    except (OSError, RuntimeError, ValueError):
        raise ArchiveServiceError(
            "project_version_update_component_swap_cleanup_failed"
        ) from None


def _project_update_windows_publish_bytes_no_replace(
    target: Path,
    raw: bytes,
    *,
    _failpoint: Callable[[str, Path], None] | None = None,
) -> None:
    """Publish complete bytes through one crash-clean retained Windows handle.

    The temporary file is opened with ``FILE_FLAG_DELETE_ON_CLOSE`` and
    without write/delete sharing.  The same handle writes, flushes, fully
    re-reads, identity-binds, and renames the file without replacement.  A
    process exit before commit therefore removes that exact handle's file; no
    later path-based cleanup can delete a raced replacement.  After a durable
    rename, ``FileDispositionInfoEx`` clears delete-on-close on that same
    handle.  A process exit before the clear may remove the postimage, but the
    exact component swap remains the recoverable preimage.
    """

    if os.name != "nt" or not isinstance(raw, bytes):
        raise OSError("project_update_component_atomic_publish_unsupported")
    target = Path(os.path.abspath(str(target)))
    from ctypes import wintypes
    import msvcrt
    from . import private_metadata_win32

    class FileDispositionInformationEx(ctypes.Structure):
        _fields_ = [("Flags", wintypes.DWORD)]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    create_file = kernel32.CreateFileW
    create_file.argtypes = [
        wintypes.LPCWSTR,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.LPVOID,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.HANDLE,
    ]
    create_file.restype = wintypes.HANDLE
    set_information = kernel32.SetFileInformationByHandle
    set_information.argtypes = [
        wintypes.HANDLE,
        ctypes.c_int,
        wintypes.LPVOID,
        wintypes.DWORD,
    ]
    set_information.restype = wintypes.BOOL
    close_handle = kernel32.CloseHandle
    close_handle.argtypes = [wintypes.HANDLE]
    close_handle.restype = wintypes.BOOL

    generic_read = 0x80000000
    generic_write = 0x40000000
    delete_access = 0x00010000
    file_share_read = 0x00000001
    create_new = 1
    file_attribute_normal = 0x00000080
    file_flag_delete_on_close = 0x04000000
    invalid_handle = wintypes.HANDLE(-1).value
    error_file_exists = {80, 183}
    descriptor: int | None = None
    handle_value: int | None = None
    temporary_path: Path | None = None

    for _ in range(8):
        candidate = target.with_name(
            f".{target.name}.{secrets.token_hex(8)}.wom-publish"
        )
        ctypes.set_last_error(0)
        handle = create_file(
            str(candidate),
            generic_read | generic_write | delete_access,
            file_share_read,
            None,
            create_new,
            file_attribute_normal | file_flag_delete_on_close,
            None,
        )
        value = handle if isinstance(handle, int) else getattr(handle, "value", None)
        if value not in {None, invalid_handle}:
            handle_value = int(value)
            temporary_path = candidate
            break
        if ctypes.get_last_error() not in error_file_exists:
            raise ctypes.WinError(ctypes.get_last_error())
    if handle_value is None or temporary_path is None:
        raise OSError("project_update_component_atomic_publish_failed")

    try:
        try:
            descriptor = msvcrt.open_osfhandle(
                handle_value,
                os.O_RDWR | getattr(os, "O_BINARY", 0),
            )
        except BaseException:
            close_handle(handle_value)
            handle_value = None
            raise
        # Ownership has transferred to the CRT descriptor.
        handle_value = msvcrt.get_osfhandle(descriptor)

        offset = 0
        while offset < len(raw):
            written = os.write(descriptor, raw[offset : offset + 64 * 1024])
            if written <= 0:
                raise OSError("project_update_component_publish_write_incomplete")
            offset += written
        os.fsync(descriptor)

        def exact_handle_binding(named_path: Path) -> dict[str, Any]:
            before = os.fstat(descriptor)
            reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
            if (
                not stat.S_ISREG(before.st_mode)
                or stat.S_ISLNK(before.st_mode)
                or int(before.st_nlink) != 1
                or int(before.st_size) != len(raw)
                or bool(
                    reparse_flag
                    and getattr(before, "st_file_attributes", 0) & reparse_flag
                )
            ):
                raise OSError("project_update_component_publish_handle_unsafe")
            os.lseek(descriptor, 0, os.SEEK_SET)
            digest = hashlib.sha256()
            remaining = len(raw)
            while remaining:
                chunk = os.read(descriptor, min(1024 * 1024, remaining))
                if not chunk:
                    raise OSError(
                        "project_update_component_publish_read_incomplete"
                    )
                digest.update(chunk)
                remaining -= len(chunk)
            if os.read(descriptor, 1):
                raise OSError(
                    "project_update_component_publish_read_incomplete"
                )
            after = os.fstat(descriptor)
            named = os.lstat(named_path)
            binding = {
                "identity": (int(before.st_dev), int(before.st_ino)),
                "size": int(before.st_size),
                "mtime_ns": int(before.st_mtime_ns),
                "link_count": int(before.st_nlink),
                "sha256": digest.hexdigest(),
            }
            if (
                (int(after.st_dev), int(after.st_ino))
                != binding["identity"]
                or int(after.st_size) != binding["size"]
                or int(after.st_mtime_ns) != binding["mtime_ns"]
                or int(after.st_nlink) != binding["link_count"]
                or not stat.S_ISREG(named.st_mode)
                or stat.S_ISLNK(named.st_mode)
                or (int(named.st_dev), int(named.st_ino))
                != binding["identity"]
                or int(named.st_size) != binding["size"]
                or int(named.st_mtime_ns) != binding["mtime_ns"]
                or int(named.st_nlink) != binding["link_count"]
                or binding["sha256"] != hashlib.sha256(raw).hexdigest()
            ):
                raise OSError("project_update_component_publish_handle_changed")
            return binding

        creation_binding = exact_handle_binding(temporary_path)
        if _failpoint is not None:
            _failpoint("publish_temp_flushed_and_bound", temporary_path)
        if exact_handle_binding(temporary_path) != creation_binding:
            raise OSError("project_update_component_publish_handle_changed")

        rename_information = private_metadata_win32.file_rename_info_buffer(
            target,
            replace_if_exists=False,
        )
        ctypes.set_last_error(0)
        if not set_information(
            handle_value,
            3,  # FileRenameInfo
            rename_information.backing,
            rename_information.api_buffer_size,
        ):
            raise ctypes.WinError(ctypes.get_last_error())
        if exact_handle_binding(target) != creation_binding:
            raise OSError("project_update_component_publish_handle_changed")
        project_update_transaction._require_directory_durable(target.parent)
        if _failpoint is not None:
            _failpoint(
                "publish_target_durable_before_delete_on_close_cancel",
                target,
            )

        # With FILE_FLAG_DELETE_ON_CLOSE, ON_CLOSE without DELETE clears the
        # pending deletion state for this exact handle.  It cannot authorize a
        # different object bearing the same path because that name was never
        # reopened.
        keep_on_close = FileDispositionInformationEx(0x00000008)
        if not set_information(
            handle_value,
            21,  # FileDispositionInfoEx
            ctypes.byref(keep_on_close),
            ctypes.sizeof(keep_on_close),
        ):
            raise ctypes.WinError(ctypes.get_last_error())
        if exact_handle_binding(target) != creation_binding:
            raise OSError("project_update_component_publish_handle_changed")
        if _failpoint is not None:
            _failpoint("publish_delete_on_close_cancelled", target)
    finally:
        if descriptor is not None:
            try:
                os.close(descriptor)
            finally:
                descriptor = None
        elif handle_value is not None:
            close_handle(handle_value)
        # Never perform path-based cleanup here.  Before cancellation, the
        # kernel deletes the retained handle's exact object on close.  After
        # cancellation, the durable target is intentionally preserved.


def _project_update_claim_checkpoint_guard(
    state: _ProjectVersionUpdateDurableApprovalState,
    claim: _ClaimedExactHumanApproval,
    *,
    succeeded: bool,
) -> bool:
    """Authenticate a resume branch against the exact transaction journal."""

    if not _project_update_terminal_execution_lease_is_held(state):
        return False
    reference_sha256 = project_update_transaction.sha256_bytes(
        _project_update_canonical_bytes(claim.public_reference())
    )
    approval_mac_sha256 = (
        None
        if succeeded
        else _project_update_claim_authority(state, claim)[1]
    )
    inspection = state.transaction.inspect()
    if inspection.journal.state != "exact" or not inspection.lock_backlinked:
        return False
    checkpoints = inspection.journal.verified_prefix
    if not checkpoints or checkpoints[0].phase != "lock_backlinked":
        return False
    if any(
        item.phase.startswith("preapproval_cancel")
        for item in checkpoints
    ):
        return False
    approval = next(
        (item for item in checkpoints if item.phase == "approval_bound"),
        None,
    )
    if approval is not None and (
        approval.approval_reference_sha256 != reference_sha256
        or (
            approval_mac_sha256 is not None
            and approval.approval_mac_sha256 != approval_mac_sha256
        )
        or approval.approval_mac_sha256 is None
    ):
        return False
    live = _project_update_live_component_sha256(state)
    classification = state.transaction.classify_live_components(live)
    if succeeded:
        return bool(
            approval is not None
            and classification.overall == "complete_exact"
            and any(
                item.phase in {"domain_committed", "claim_succeeded"}
                for item in checkpoints
            )
        )
    return bool(
        classification.overall in {
            "prewrite_exact",
            "mixed_exact",
            "complete_exact",
        }
        and not any(
            item.phase in {"claim_succeeded", "ready_to_unlock", "lock_released", "completed"}
            for item in checkpoints
        )
    )


def _project_update_exact_write_bytes(
    state: _ProjectVersionUpdateDurableApprovalState,
    component: project_update_transaction.ProjectUpdateComponent,
    target_bytes: bytes,
) -> None:
    if not hmac.compare_digest(
        project_update_transaction.digest_component(target_bytes),
        component.post_sha256,
    ):
        raise ArchiveServiceError(
            "project_version_update_private_plan_invalid"
        )
    path = state.component_paths[component.component_ref]
    maximum = (
        _PROJECT_UPDATE_RECEIPT_MAX_BYTES
        if component.role == "receipt"
        else 64 * 1024
        if component.role == "launcher"
        else WOM_KIT_VERSION_PIN_MAX_BYTES
    )
    swap_path = _project_update_component_swap_path(state, component)
    current = _project_update_safe_read_component(
        state.project_root,
        path,
        maximum=maximum,
    )
    if current is _PROJECT_UPDATE_UNAVAILABLE_LIVE_COMPONENT:
        raise ArchiveServiceError(
            "project_version_update_component_observation_unavailable"
        )
    if current is _PROJECT_UPDATE_UNSAFE_LIVE_COMPONENT:
        raise ArchiveServiceError(
            "project_version_update_component_path_unsafe"
        )
    current_sha256 = _project_update_raw_component_sha256(current)
    swap = (
        _project_update_safe_read_component(
            state.project_root,
            swap_path,
            maximum=maximum,
        )
        if os.path.lexists(swap_path)
        else None
    )
    if swap is _PROJECT_UPDATE_UNAVAILABLE_LIVE_COMPONENT:
        raise ArchiveServiceError(
            "project_version_update_component_observation_unavailable"
        )
    if swap is _PROJECT_UPDATE_UNSAFE_LIVE_COMPONENT:
        raise ArchiveServiceError(
            "project_version_update_component_path_unsafe"
        )
    if hmac.compare_digest(current_sha256, component.post_sha256):
        if swap is not None:
            if not (
                isinstance(swap, bytes)
                and hmac.compare_digest(
                    _project_update_raw_component_sha256(swap),
                    component.pre_sha256,
                )
            ):
                raise ArchiveServiceError(
                    "project_version_update_component_compare_and_swap_failed"
                )
            _project_update_delete_exact_swap_bytes(
                state.project_root,
                swap_path,
                swap,
            )
        return
    if current is None and swap is not None:
        if not (
            isinstance(swap, bytes)
            and hmac.compare_digest(
                _project_update_raw_component_sha256(swap),
                component.pre_sha256,
            )
        ):
            raise ArchiveServiceError(
                "project_version_update_component_compare_and_swap_failed"
            )
        current_sha256 = component.pre_sha256
    elif swap is not None:
        # A target and swap existing together before the intended postimage is
        # an ambiguous external race.  Preserve both and stop.
        raise ArchiveServiceError(
            "project_version_update_component_compare_and_swap_failed"
        )
    if not hmac.compare_digest(current_sha256, component.pre_sha256):
        raise ArchiveServiceError(
            "project_version_update_component_compare_and_swap_failed"
        )
    try:
        relative_parent = path.parent.relative_to(state.project_root)
    except ValueError:
        raise ArchiveServiceError(
            "project_version_update_component_path_unsafe"
        ) from None
    held_parent = state.project_root
    held_parent_observation = state.directory_guard.held_observation(
        held_parent
    )
    if held_parent_observation["state"] == "unavailable":
        raise ArchiveServiceError(
            "project_version_update_component_parent_observation_unavailable"
        )
    if held_parent_observation["state"] != "passed":
        raise ArchiveServiceError(
            "project_version_update_component_parent_unbound"
        )
    for part in relative_parent.parts:
        child = held_parent / part
        child_observation = wom_kit_real_path_kind_observation(
            state.project_root,
            child,
        )
        if child_observation["state"] == "unavailable":
            raise ArchiveServiceError(
                "project_version_update_component_parent_observation_unavailable"
            )
        kind = child_observation["kind"]
        if kind == "directory":
            held = state.directory_guard.hold(child)
        elif kind == "missing":
            held = state.directory_guard.ensure_directory(
                held_parent,
                child,
            )
        else:
            held = False
        if not held:
            after_hold_observation = wom_kit_real_path_kind_observation(
                state.project_root,
                child,
            )
            if (
                after_hold_observation["state"] == "unavailable"
                or (
                    after_hold_observation["state"] == "passed"
                    and after_hold_observation["kind"] == "directory"
                )
            ):
                raise ArchiveServiceError(
                    "project_version_update_component_parent_observation_unavailable"
                )
            raise ArchiveServiceError(
                "project_version_update_component_parent_unbound"
            )
        held_parent = child
    path_components = wom_kit_path_components_observation(
        state.project_root,
        path,
    )
    if path_components["state"] == "unavailable":
        raise ArchiveServiceError(
            "project_version_update_component_observation_unavailable"
        )
    if (
        path_components["state"] != "passed"
        or path_components["kind"] not in {"real", "missing"}
    ):
        raise ArchiveServiceError(
            "project_version_update_component_path_unsafe"
        )
    if os.name != "nt":
        raise ArchiveServiceError(
            "project_version_update_component_atomic_publish_unsupported"
        )
    if current is not None and not os.path.lexists(swap_path):
        # Windows os.rename is no-replace.  Whichever bytes occupy the target
        # at this instant are atomically preserved before WOM can publish.  A
        # raced value is detected from the swap and restored.
        try:
            os.rename(path, swap_path)
            project_update_transaction._require_directory_durable(path.parent)
        except OSError:
            raise ArchiveServiceError(
                "project_version_update_component_compare_and_swap_failed"
            ) from None
        preserved = _project_update_safe_read_component(
            state.project_root,
            swap_path,
            maximum=maximum,
        )
        if not (
            isinstance(preserved, bytes)
            and hmac.compare_digest(
                _project_update_raw_component_sha256(preserved),
                component.pre_sha256,
            )
        ):
            if not os.path.lexists(path):
                try:
                    os.rename(swap_path, path)
                    project_update_transaction._require_directory_durable(
                        path.parent
                    )
                except OSError:
                    pass
            raise ArchiveServiceError(
                "project_version_update_component_compare_and_swap_failed"
            )

    try:
        _project_update_windows_publish_bytes_no_replace(path, target_bytes)
    except Exception:
        # The retained-handle publisher may receive a private Win32 error or
        # filesystem path from a low-level API.  Keep that diagnostic inside
        # this service boundary; public callers receive only the fixed code.
        raise ArchiveServiceError(
            "project_version_update_component_compare_and_swap_failed"
        ) from None
    verified = _project_update_safe_read_component(
        state.project_root,
        path,
        maximum=maximum,
    )
    if verified is _PROJECT_UPDATE_UNAVAILABLE_LIVE_COMPONENT:
        raise ArchiveServiceError(
            "project_version_update_component_verification_unavailable"
        )
    if verified is _PROJECT_UPDATE_UNSAFE_LIVE_COMPONENT or not isinstance(
        verified,
        bytes,
    ) or not hmac.compare_digest(
        _project_update_raw_component_sha256(verified),
        component.post_sha256,
    ):
        raise ArchiveServiceError(
            "project_version_update_component_verification_failed"
        )
    if os.path.lexists(swap_path):
        preserved = _project_update_safe_read_component(
            state.project_root,
            swap_path,
            maximum=maximum,
        )
        if not (
            isinstance(preserved, bytes)
            and hmac.compare_digest(
                _project_update_raw_component_sha256(preserved),
                component.pre_sha256,
            )
        ):
            raise ArchiveServiceError(
                "project_version_update_component_compare_and_swap_failed"
            )
        _project_update_delete_exact_swap_bytes(
            state.project_root,
            swap_path,
            preserved,
        )


def _project_update_prepare_runtime_cleanup(
    candidate: project_runtime.PreparedRuntimeCandidate,
) -> tuple[
    project_runtime.RuntimeCandidateCleanupCapsule,
    dict[str, Any],
]:
    """Finish candidate cleanup while retaining its durable sidecar."""

    capsule = project_runtime.cleanup_prepared_runtime_candidate(candidate)
    if not isinstance(
        capsule,
        project_runtime.RuntimeCandidateCleanupCapsule,
    ):
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        )
    evidence = project_runtime.runtime_candidate_cleanup_terminal_evidence(
        capsule
    )
    if not isinstance(evidence, dict):
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        )
    return capsule, evidence


def _project_update_runtime_cleanup_sidecar_pending_read_only(
    *,
    project_root: Path,
    transaction_ref: str,
) -> bool | None:
    """Classify one exact sidecar reference without granting deletion."""

    inventory = project_runtime.runtime_candidate_cleanup_sidecar_inventory(
        project_root
    )
    if (
        not isinstance(inventory, Mapping)
        or inventory.get("state") != "passed"
        or inventory.get("unattributed_sidecar_count") != 0
        or any(
            inventory.get(key)
            for key in (
                "orphaned_transaction_refs",
                "review_required_transaction_refs",
                "unavailable_transaction_refs",
            )
        )
    ):
        return None
    recoverable = inventory.get("recoverable_transaction_refs")
    if not isinstance(recoverable, (tuple, list)):
        return None
    return sum(item == transaction_ref for item in recoverable) == 1


def _project_update_runtime_cleanup_sidecar_for_transaction(
    *,
    project_root: Path,
    transaction_root: Path,
    transaction_ref: str,
) -> project_runtime.RuntimeCandidateCleanupCapsule | None:
    """Load one exact recoverable sidecar without guessing from filenames."""

    inventory = project_runtime.runtime_candidate_cleanup_sidecar_inventory(
        project_root
    )
    if not isinstance(inventory, Mapping):
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        )
    recoverable = inventory.get("recoverable_transaction_refs")
    unsafe = tuple(
        str(item)
        for key in (
            "orphaned_transaction_refs",
            "review_required_transaction_refs",
            "unavailable_transaction_refs",
        )
        for item in (
            inventory.get(key)
            if isinstance(inventory.get(key), (tuple, list))
            else ()
        )
    )
    if transaction_ref in unsafe:
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        )
    if not isinstance(recoverable, (tuple, list)):
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        )
    matching = [item for item in recoverable if item == transaction_ref]
    if len(matching) > 1:
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        )
    if not matching:
        return None
    try:
        capsule = project_runtime.load_runtime_candidate_cleanup_capsule(
            project_root,
            transaction_root,
        )
        resumed = project_runtime.resume_runtime_candidate_cleanup(capsule)
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        ) from None
    if not isinstance(
        resumed,
        project_runtime.RuntimeCandidateCleanupCapsule,
    ):
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        )
    return resumed


def _project_update_retire_runtime_cleanup_after_durable_ack(
    *,
    project_root: Path,
    transaction_root: Path,
    transaction_ref: str,
    capsule: project_runtime.RuntimeCandidateCleanupCapsule | None,
) -> None:
    """Retire only through a disk-revalidated transaction-issued ack."""

    try:
        durable_ack = (
            project_update_transaction.load_runtime_cleanup_durable_ack(
                project_root,
                transaction_ref,
            )
        )
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        ) from None
    selected = capsule
    if durable_ack is None:
        if selected is None:
            selected = _project_update_runtime_cleanup_sidecar_for_transaction(
                project_root=project_root,
                transaction_root=transaction_root,
                transaction_ref=transaction_ref,
            )
            if selected is None:
                # Historical verified checkpoints did not bind a cleanup
                # sidecar.  Exact absence is the only compatible old shape.
                return
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        )
    if not project_update_transaction.revalidate_runtime_cleanup_durable_ack(
        durable_ack
    ):
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        )
    if selected is None:
        selected = _project_update_runtime_cleanup_sidecar_for_transaction(
            project_root=project_root,
            transaction_root=transaction_root,
            transaction_ref=transaction_ref,
        )
    if not project_runtime.retire_runtime_candidate_cleanup_capsule(
        selected,
        durable_ack=durable_ack,
        project_root=project_root if selected is None else None,
    ):
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        )


def _project_update_perform_component(
    state: _ProjectVersionUpdateDurableApprovalState,
    component: project_update_transaction.ProjectUpdateComponent,
) -> None:
    if component.role == "source":
        if component.pre_sha256 == component.post_sha256:
            if _project_update_source_live_sha256(state) != component.post_sha256:
                raise ArchiveServiceError(
                    "project_version_update_source_snapshot_changed"
                )
            return
        if _project_update_source_live_sha256(state) == component.post_sha256:
            return
        if _project_update_source_live_sha256(state) != component.pre_sha256:
            raise ArchiveServiceError(
                "project_version_update_source_snapshot_changed"
            )
        if not _wom_kit_project_update_materialize_commit(
            state.mirror_path,
            state.target_commit,
            directory_guard=state.directory_guard,
            project_root=state.project_root,
            expected_source_snapshot=state.private_plan[
                "preflight_git_snapshot"
            ],
            runner=state.runner,
        ):
            raise ArchiveServiceError(
                "project_version_update_source_materialization_failed"
            )
        if _project_update_source_live_sha256(state) != component.post_sha256:
            raise ArchiveServiceError(
                "project_version_update_source_verification_failed"
            )
        return
    if component.role == "runtime":
        if _project_update_runtime_matches_candidate(state):
            state.runtime_materialization = (
                project_runtime.reopen_promoted_runtime_materialization(
                    state.runtime_candidate
                )
            )
        else:
            state.runtime_materialization = project_runtime.promote_runtime_candidate(
                state.project_root,
                target=state.target_version,
                target_commit=state.target_commit,
                bootstrap=state.runtime_bootstrap,
                supply=state.runtime_supply,
                prepared_candidate=state.runtime_candidate,
            )
            if not _project_update_runtime_matches_candidate(state):
                raise ArchiveServiceError(
                    "project_version_update_runtime_promotion_failed"
                )
        (
            state.runtime_cleanup_capsule,
            state.runtime_cleanup_terminal_evidence,
        ) = _project_update_prepare_runtime_cleanup(
            state.runtime_candidate
        )
        return
    target_bytes = (
        state.static_receipt_bytes
        if component.role == "receipt"
        else state.private_plan["component_postimages"][
            component.component_ref
        ]
    )
    if not isinstance(target_bytes, bytes):
        raise ArchiveServiceError(
            "project_version_update_private_plan_invalid"
        )
    _project_update_exact_write_bytes(state, component, target_bytes)


_PROJECT_UPDATE_LEGACY_RUNTIME_POLICY_KEYS = frozenset(
    {
        "state",
        "required",
        "schema",
        "policy_sha256",
        "source_path",
        "supply_lock_path",
        "supply_lock_sha256",
    }
)
_PROJECT_UPDATE_OBSERVED_RUNTIME_POLICY_KEYS = (
    _PROJECT_UPDATE_LEGACY_RUNTIME_POLICY_KEYS
    | {"observation_state", "observation_reason_code"}
)
_PROJECT_UPDATE_MISSING_PREDECESSOR_VALUE = object()


def _project_update_approved_policy_uses_predecessor_shape(
    *,
    runtime_candidate_legacy: bool,
    expected_policy: Mapping[str, Any],
) -> bool:
    """Select compatibility only from the exact approved policy shape.

    Candidate serialization and approval-policy serialization evolved on
    independent timelines.  In particular, an older candidate can coexist
    with a current nine-field policy, which must remain strict.  Keep the
    parameter while predecessor transactions still call this helper, but do
    not use candidate age to weaken a current approval.
    """

    _ = runtime_candidate_legacy
    return bool(
        frozenset(expected_policy)
        == _PROJECT_UPDATE_LEGACY_RUNTIME_POLICY_KEYS
    )


def _project_update_approved_comparison_projection(
    live: Any,
    expected: Any,
    *,
    predecessor_shape: bool,
) -> Any:
    """Project additive observations only for an authenticated predecessor."""

    if not predecessor_shape:
        return live
    if type(expected) is dict:
        if type(live) is not dict:
            return live
        return {
            key: (
                _project_update_approved_comparison_projection(
                    live[key],
                    expected_value,
                    predecessor_shape=True,
                )
                if key in live
                else _PROJECT_UPDATE_MISSING_PREDECESSOR_VALUE
            )
            for key, expected_value in expected.items()
        }
    if type(expected) is list:
        if type(live) is not list or len(live) != len(expected):
            return live
        return [
            _project_update_approved_comparison_projection(
                live_value,
                expected_value,
                predecessor_shape=True,
            )
            for live_value, expected_value in zip(live, expected)
        ]
    return live


def _project_update_assert_approved_snapshot_unchanged(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> None:
    """Re-prove every mutable prewrite input before the first component.

    The native decision binds the post-fetch ref/config/source snapshots, the
    project pins, runtime policy/supply/candidate, launcher, and exact
    materialization plan.  None of those may be silently refreshed after the
    person approves.  Reopened transactions call this guard while their
    journal is still before the first component intent; later checkpoints are
    governed by the transaction's exact live-component classifier.
    """

    changed_code = "project_version_update_approved_snapshot_changed"
    unavailable_code = "project_version_update_approved_snapshot_unavailable"

    try:
        plan = state.private_plan
        expected_snapshot = plan.get("preflight_git_snapshot")
        expected_ref_snapshot = plan.get("target_ref_snapshot")
        expected_target_evidence = plan.get("target_evidence")
        expected_policy = plan.get("runtime_policy")
        expected_materialization = plan.get(
            "materialization_preflight"
        )
        expected_launcher = plan.get("launcher_snapshot")
        expected_pin_specs = plan.get("pin_specs")
        if (
            type(expected_snapshot) is not dict
            or type(expected_ref_snapshot) is not dict
            or type(expected_target_evidence) is not dict
            or type(expected_policy) is not dict
            or type(expected_materialization) is not dict
            or type(expected_launcher) is not dict
            or type(expected_pin_specs) is not list
            or type(plan.get("preflight_git_config_digest")) is not str
            or type(plan.get("head_before")) is not str
        ):
            raise ArchiveServiceError(changed_code)
        expected_policy_keys = frozenset(expected_policy)
        if expected_policy_keys not in {
            _PROJECT_UPDATE_LEGACY_RUNTIME_POLICY_KEYS,
            _PROJECT_UPDATE_OBSERVED_RUNTIME_POLICY_KEYS,
        }:
            raise ArchiveServiceError(changed_code)
        predecessor_observation_shape = (
            _project_update_approved_policy_uses_predecessor_shape(
                runtime_candidate_legacy=(
                    state.runtime_candidate.legacy_resume_shape
                ),
                expected_policy=expected_policy,
            )
        )

        live_pin_specs: list[dict[str, Any]] = []
        for private_spec in expected_pin_specs:
            if type(private_spec) is not dict:
                raise ArchiveServiceError(changed_code)
            logical_value = private_spec.get("logical")
            if type(logical_value) is not str:
                raise ArchiveServiceError(changed_code)
            logical = PurePosixPath(logical_value)
            if (
                logical.is_absolute()
                or not logical.parts
                or any(part in {"", ".", ".."} for part in logical.parts)
            ):
                raise ArchiveServiceError(changed_code)
            path = state.project_root.joinpath(*logical.parts)
            if not is_path_within_root(path, state.project_root):
                raise ArchiveServiceError(changed_code)
            live_pin_specs.append({**private_spec, "path": path})

        live_git_snapshot = _wom_kit_project_update_git_snapshot(
            state.mirror_path,
            runner=state.runner,
        )
        live_git_config_digest = wom_kit_project_update_git_config_trust_digest(
            state.mirror_path,
            runner=state.runner,
        )
        live_git_metadata_evidence = (
            wom_kit_project_update_git_metadata_evidence(
                state.project_root,
                state.mirror_path,
                runner=state.runner,
            )
        )
        live_pins_observation = (
            wom_kit_project_update_all_pins_snapshot_observation(
                state.project_root,
                live_pin_specs,
            )
        )
        live_ref_observation = (
            wom_kit_project_update_target_ref_snapshot_observation(
                state.mirror_path,
                state.target_tag,
                runner=state.runner,
            )
        )
        live_ref_snapshot = live_ref_observation.get("snapshot")
        live_target_evidence = wom_kit_project_update_target_evidence(
            state.mirror_path,
            state.target_tag,
            runner=state.runner,
        )
        live_policy = wom_kit_project_update_runtime_policy(
            state.mirror_path,
            state.target_commit,
            runner=state.runner,
        )
        live_policy_state, live_policy_reason = (
            _wom_kit_project_update_policy_observation(live_policy)
        )
        (
            live_supply_state,
            live_supply_reason,
            live_supply,
        ) = _wom_kit_project_update_runtime_supply_revalidation_observation(
            state.mirror_path,
            state.target_commit,
            state.target_version,
            live_policy,
            runner=state.runner,
        )
        live_bootstrap, live_bootstrap_summary = (
            project_runtime.bootstrap_wheel_for_target(state.target_version)
        )
        live_runtime_plan, live_runtime_blockers, _ = (
            project_runtime.plan_runtime(
                state.project_root,
                state.target_version,
                policy_state=str(live_policy["state"]),
                target_commit=state.target_commit,
                bootstrap=live_bootstrap,
                bootstrap_summary=live_bootstrap_summary,
                supply=live_supply,
                enforce_interpreter=True,
            )
        )
        live_runtime_plan["policy"] = copy.deepcopy(live_policy)
        live_runtime_plan["runtime_candidate"] = copy.deepcopy(
            state.runtime_candidate.public_summary()
        )
        live_launcher = project_runtime.launcher_snapshot(
            state.project_root,
            state.target_version,
        )
        live_launcher_private = {
            key: value
            for key, value in live_launcher.items()
            if key != "path"
        }
        live_materialization = (
            wom_kit_project_update_materialization_preflight(
                state.project_root,
                state.mirror_path,
                target_commit=state.target_commit,
                head_before=plan["head_before"],
                original_branch=expected_snapshot.get("branch"),
                runner=state.runner,
            )
        )
        (
            candidate_observation_state,
            candidate_observation_reason,
            live_candidate_observation,
        ) = project_runtime.verify_prepared_runtime_candidate_observation(
            state.runtime_candidate,
            project_root=state.project_root,
            target=state.target_version,
            target_commit=state.target_commit,
            bootstrap=state.runtime_bootstrap,
            supply=state.runtime_supply,
        )
        live_candidate_summary = (
            dict(live_candidate_observation)
            if live_candidate_observation is not None
            else {}
        )
        if live_candidate_summary:
            live_candidate_summary.pop("static_reverified", None)

        expected_branch = expected_snapshot.get("branch")
        source_branch_observation = (
            {"state": "passed", "reason_code": "not_applicable"}
            if expected_branch is None
            else wom_kit_project_update_branch_observation(
                state.mirror_path,
                str(expected_branch),
                str(plan["head_before"]),
                runner=state.runner,
            )
        )
        runtime_plan_state, runtime_plan_reason = (
            _wom_kit_project_update_runtime_plan_observation_state(
                live_runtime_blockers,
                prerequisite_states=(
                    _wom_kit_project_update_runtime_plan_prerequisite_states(
                        policy_state=live_policy_state,
                        supply_state=live_supply_state,
                        bootstrap_available=live_bootstrap is not None,
                        launcher_state=str(
                            live_launcher.get(
                                "observation_state", "unavailable"
                            )
                        ),
                    )
                ),
            )
        )
        observed = {
            "git_snapshot": _wom_kit_project_update_preparation_check(
                "git_snapshot",
                live_git_snapshot == expected_snapshot,
                available=live_git_snapshot is not None,
            ),
            "git_config_trust": _wom_kit_project_update_preparation_check(
                "git_config_trust",
                live_git_config_digest == plan["preflight_git_config_digest"],
                available=live_git_config_digest is not None,
            ),
            "git_metadata": _wom_kit_project_update_observed_preparation_check(
                "git_metadata",
                str(live_git_metadata_evidence["state"]),
                str(live_git_metadata_evidence["reason_code"]),
                live_git_metadata_evidence["state"] == "passed",
            ),
            "version_pins": _wom_kit_project_update_observed_preparation_check(
                "version_pins",
                str(live_pins_observation["state"]),
                str(live_pins_observation["reason_code"]),
                live_pins_observation["state"] == "passed",
            ),
            "target_refs": _wom_kit_project_update_observed_preparation_check(
                "target_refs",
                str(live_ref_observation["state"]),
                str(live_ref_observation["reason_code"]),
                live_ref_snapshot == expected_ref_snapshot,
            ),
            "target_evidence": _wom_kit_project_update_observed_preparation_check(
                "target_evidence",
                str(live_target_evidence.get("observation_state", "unavailable")),
                str(
                    live_target_evidence.get(
                        "observation_reason_code",
                        "project_target_evidence_unavailable",
                    )
                ),
                _project_update_approved_comparison_projection(
                    live_target_evidence,
                    expected_target_evidence,
                    predecessor_shape=predecessor_observation_shape,
                )
                == expected_target_evidence,
            ),
            "runtime_policy": _wom_kit_project_update_observed_preparation_check(
                "runtime_policy",
                live_policy_state,
                live_policy_reason,
                _project_update_approved_comparison_projection(
                    live_policy,
                    expected_policy,
                    predecessor_shape=predecessor_observation_shape,
                )
                == expected_policy,
            ),
            "runtime_supply": _wom_kit_project_update_observed_preparation_check(
                "runtime_supply",
                live_supply_state,
                live_supply_reason,
                live_supply == state.runtime_supply,
            ),
            "runtime_bootstrap": _wom_kit_project_update_preparation_check(
                "runtime_bootstrap",
                live_bootstrap == state.runtime_bootstrap
                and live_bootstrap_summary == plan.get("runtime_bootstrap"),
                available=live_bootstrap is not None,
            ),
            "runtime_plan": _wom_kit_project_update_observed_preparation_check(
                "runtime_plan",
                runtime_plan_state,
                runtime_plan_reason,
                _project_update_approved_comparison_projection(
                    live_runtime_plan,
                    plan.get("runtime_plan"),
                    predecessor_shape=predecessor_observation_shape,
                )
                == plan.get("runtime_plan"),
            ),
            "launcher": _wom_kit_project_update_observed_preparation_check(
                "launcher",
                str(live_launcher.get("observation_state", "unavailable")),
                str(
                    live_launcher.get(
                        "observation_reason_code",
                        "project_runtime_launcher_observation_unavailable",
                    )
                ),
                _project_update_approved_comparison_projection(
                    live_launcher_private,
                    expected_launcher,
                    predecessor_shape=predecessor_observation_shape,
                )
                == expected_launcher,
            ),
            "materialization_preflight": (
                _wom_kit_project_update_observed_preparation_check(
                    "materialization_preflight",
                    str(
                        live_materialization.get(
                            "observation_state", "unavailable"
                        )
                    ),
                    str(
                        live_materialization.get(
                            "observation_reason_code",
                            "project_materialization_preflight_unavailable",
                        )
                    ),
                    _project_update_approved_comparison_projection(
                        live_materialization,
                        expected_materialization,
                        predecessor_shape=predecessor_observation_shape,
                    )
                    == expected_materialization,
                )
            ),
            "prepared_runtime_payload": (
                _wom_kit_project_update_observed_preparation_check(
                    "prepared_runtime_payload",
                    candidate_observation_state,
                    candidate_observation_reason,
                    live_candidate_summary
                    == state.runtime_candidate.public_summary(),
                )
            ),
            "source_branch": _wom_kit_project_update_observed_preparation_check(
                "source_branch",
                str(source_branch_observation["state"]),
                str(source_branch_observation["reason_code"]),
                source_branch_observation["state"] == "passed",
            ),
        }
        revalidation = wom_kit_project_update_runtime_preparation_revalidation(
            observed
        )
        state.approved_snapshot_revalidation = copy.deepcopy(revalidation)
        lock_observations = (
            state.directory_guard.held_observation(state.project_root),
            state.directory_guard.held_observation(
                state.project_root / ".zettel-kasten"
            ),
            state.directory_guard.held_observation(state.mirror_path),
        )
    except ArchiveServiceError:
        raise
    except Exception:
        # Never echo a Git path, runtime path, or provider/tool exception from
        # this post-native boundary.
        raise ArchiveServiceError(unavailable_code) from None
    lock_failure_code = _wom_kit_project_update_approved_lock_failure_code(
        lock_observations
    )
    if lock_failure_code is not None:
        raise ArchiveServiceError(lock_failure_code)
    failure_code = _wom_kit_project_update_revalidation_failure_code(
        revalidation
    )
    if failure_code is not None:
        raise ArchiveServiceError(failure_code)


def _project_update_build_domain_result(
    state: _ProjectVersionUpdateDurableApprovalState,
    *,
    operation_exact_human_approval: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Build the verified domain result without entering any writer."""

    runtime_summary = (
        state.runtime_materialization.public_summary()
        if state.runtime_materialization is not None
        else {
            **state.runtime_candidate.public_summary(),
            "status": "verified",
            "path": project_runtime.runtime_logical_path(
                state.target_version
            ),
            "created": not state.runtime_candidate.existing_runtime_reusable,
            "absolute_paths_echoed": False,
        }
    )
    source_changed = state.source_pre_sha256 != state.source_post_sha256
    source_summary = copy.deepcopy(
        state.prepared_preview.get("source_mirror", {})
    )
    source_summary.update(
        {
            "head_commit_after": state.target_commit,
            "source_checkout_change_attempted": source_changed,
            "source_checkout_is_verified_target": True,
            "runtime_source_rematerialization_attempted": source_changed,
            "runtime_source_rematerialization_succeeded": (
                True if source_changed else None
            ),
            "target_runtime_source_integrity_verified": True,
            "checkout_mode_after_result": "detached_exact_tag",
        }
    )
    target_pin_bytes = (state.target_tag + "\n").encode("utf-8")
    written_pin_paths = [
        str(spec["logical"])
        for spec in state.private_plan["pin_specs"]
        if spec.get("previous_bytes") != target_pin_bytes
    ]
    pins_summary = copy.deepcopy(state.prepared_preview.get("pins", {}))
    pins_summary["written_paths"] = list(written_pin_paths)
    pins_summary["write_attempted_paths"] = list(written_pin_paths)
    for item in pins_summary.get("planned", []):
        if type(item) is not dict:
            continue
        changed = item.get("path") in written_pin_paths
        item["written"] = changed
        item["write_attempted"] = changed
    launcher_snapshot = state.private_plan["launcher_snapshot"]
    launcher_changed = (
        launcher_snapshot.get("previous_bytes")
        != launcher_snapshot.get("target_bytes")
    )
    project_runtime_summary = copy.deepcopy(
        state.prepared_preview.get("project_runtime", {})
    )
    project_runtime_summary.update(
        {
            "launcher_write_attempted": launcher_changed,
            "launcher_written": launcher_changed,
            "materialized": runtime_summary,
            "approved_snapshot_revalidation": copy.deepcopy(
                state.approved_snapshot_revalidation
                or wom_kit_project_update_runtime_preparation_revalidation()
            ),
        }
    )
    return {
        "ok": True,
        "schema": "wom-kit/project-version-update/v0.1",
        "lifecycle_action": "project_version_update",
        "status": "updated_restart_required",
        "mode": "approved",
        "operation_exact_human_approval": (
            copy.deepcopy(dict(operation_exact_human_approval))
            if isinstance(operation_exact_human_approval, Mapping)
            else None
        ),
        "fetch": copy.deepcopy(
            state.prepared_preview.get("fetch", {})
        ),
        "target": copy.deepcopy(state.prepared_preview.get("target", {})),
        "source_mirror": source_summary,
        "pins": pins_summary,
        "project_runtime": project_runtime_summary,
        "runtime": copy.deepcopy(
            state.prepared_preview.get("runtime", {})
        ),
        "receipt": {
            "schema": state.private_plan["static_receipt_schema"],
            "path": state.private_plan["static_receipt_relative"],
            "sha256": project_update_transaction.sha256_bytes(
                state.static_receipt_bytes
            ),
            "written": True,
        },
        "transaction": state.transaction.public_summary(),
        "write_boundary": {
            **copy.deepcopy(
                state.prepared_preview.get("write_boundary", {})
            ),
            "runtime_postapproval_child_process_allowed": False,
            "project_update_postapproval_local_git_allowed": True,
            "postapproval_git_transport_allowed": False,
            "project_update_lock_released_by_succeeded_claim_finalizer": True,
        },
        "files_written": [
            component.logical_target
            for component in state.transaction.intent.components
            if component.pre_sha256 != component.post_sha256
        ],
        "blockers": [],
        "warnings": copy.deepcopy(
            state.prepared_preview.get("warnings", [])
        ),
        "rollback": {
            "attempted": False,
            "succeeded": None,
            "fetched_refs_may_remain": True,
        },
        "privacy_guards": {
            "local_absolute_paths_echoed": False,
            "remote_urls_echoed": False,
            "credential_values_echoed": False,
            "archive_body_text_read": False,
            "objet_bytes_read": False,
        },
    }


def _project_update_durable_writer(
    state: _ProjectVersionUpdateDurableApprovalState,
    claim: _ClaimedExactHumanApproval,
) -> dict[str, Any]:
    """Resume-safe exact component writer; it deliberately keeps the lock."""

    if not _project_update_terminal_execution_lease_is_held(state):
        raise ArchiveServiceError(
            "project_version_update_terminal_execution_boundary_unknown"
        )
    if not _wom_kit_project_version_update_approval_authority_matches(
        state.inspection_root,
        expected_root=state.expected_approval_root,
        expected_archive_id=state.expected_archive_id,
    ):
        raise ArchiveServiceError(
            "project_version_update_approval_archive_identity_changed"
        )
    inspection = state.transaction.inspect()
    if inspection.journal.state != "exact":
        raise ArchiveServiceError(
            "project_version_update_transaction_journal_degraded"
        )
    checkpoints = list(inspection.journal.verified_prefix)
    component_started = any(
        item.phase
        not in {"lock_backlinked", "approval_bound"}
        for item in checkpoints
    )
    if not component_started:
        _project_update_assert_approved_snapshot_unchanged(state)
    reference_sha256, approval_mac_sha256 = _project_update_claim_authority(
        state,
        claim,
    )
    operation_exact_human_approval = (
        _require_exact_human_operation_approval(
            state.expected_approval_root,
            project_version_update_approval_binding(
                state.prepared_preview
            ),
            reviewer_claim=state.reviewer,
            expected_plan_sha256=state.approved_plan_sha256,
            expected_target_binding_sha256=(
                state.approved_target_binding_sha256
            ),
            claim=claim,
            expected_archive_id=state.expected_archive_id,
        )
    )
    if not checkpoints:
        state.transaction.append(
            phase="lock_backlinked",
            stage="verified",
            live_component_sha256=_project_update_live_component_sha256(
                state
            ),
        )
        checkpoints = list(
            state.transaction.inspect().journal.verified_prefix
        )
    if not any(item.phase == "approval_bound" for item in checkpoints):
        state.transaction.append(
            phase="approval_bound",
            stage="verified",
            live_component_sha256=_project_update_live_component_sha256(
                state
            ),
            approval_reference_sha256=reference_sha256,
            approval_mac_sha256=approval_mac_sha256,
        )

    for component in state.transaction.intent.components:
        checkpoints = list(
            state.transaction.inspect().journal.verified_prefix
        )
        verified = any(
            item.phase == component.role
            and item.stage == "verified"
            and item.component_ref == component.component_ref
            for item in checkpoints
        )
        if verified:
            if component.role == "runtime":
                _project_update_retire_runtime_cleanup_after_durable_ack(
                    project_root=state.project_root,
                    transaction_root=state.transaction.transaction_root,
                    transaction_ref=state.transaction.transaction_ref,
                    capsule=state.runtime_cleanup_capsule,
                )
                state.runtime_cleanup_capsule = None
                state.runtime_cleanup_terminal_evidence = None
            continue
        intended = any(
            item.phase == component.role
            and item.stage == "intent"
            and item.component_ref == component.component_ref
            for item in checkpoints
        )
        if not intended:
            state.transaction.append(
                phase=component.role,
                stage="intent",
                component_ref=component.component_ref,
                live_component_sha256=(
                    _project_update_live_component_sha256(state)
                ),
            )
        _project_update_perform_component(state, component)
        state.transaction.append(
            phase=component.role,
            stage="verified",
            component_ref=component.component_ref,
            live_component_sha256=_project_update_live_component_sha256(
                state
            ),
            runtime_cleanup_terminal_evidence=(
                state.runtime_cleanup_terminal_evidence
                if component.role == "runtime"
                else None
            ),
        )
        if component.role == "runtime":
            _project_update_retire_runtime_cleanup_after_durable_ack(
                project_root=state.project_root,
                transaction_root=state.transaction.transaction_root,
                transaction_ref=state.transaction.transaction_ref,
                capsule=state.runtime_cleanup_capsule,
            )
            state.runtime_cleanup_capsule = None
            state.runtime_cleanup_terminal_evidence = None

    checkpoints = state.transaction.inspect().journal.verified_prefix
    if not any(item.phase == "domain_committed" for item in checkpoints):
        state.transaction.append(
            phase="domain_committed",
            stage="verified",
            live_component_sha256=_project_update_live_component_sha256(
                state
            ),
        )
    result = _project_update_build_domain_result(
        state,
        operation_exact_human_approval=(
            operation_exact_human_approval
        ),
    )
    state.terminal_domain_result = _project_update_privacy_safe_domain_result(
        result
    )
    return result


def _project_update_succeeded_claim_finalizer(
    state: _ProjectVersionUpdateDurableApprovalState,
    claim: _ClaimedExactHumanApproval,
) -> None:
    """Finish the authenticated journal tail, exact unlock, then cleanup."""

    if not _project_update_terminal_execution_lease_is_held(state):
        raise ArchiveServiceError(
            "project_version_update_terminal_execution_boundary_unknown"
        )
    evidence = claim.succeeded_evidence_digests(
        project_version_update_approval_binding(
            state.prepared_preview
        ).context(
            archive_id=state.expected_archive_id,
            reviewer_claim=state.reviewer,
        )
    )
    evidence["static_receipt_sha256"] = (
        project_update_transaction.sha256_bytes(
            state.static_receipt_bytes
        )
    )
    legacy_cleanup_authority = (
        state.existing_cleanup_authority_sha256
    )
    if legacy_cleanup_authority is not None:
        claim_reference_sha256 = project_update_transaction.sha256_bytes(
            _project_update_canonical_bytes(claim.public_reference())
        )
        if (
            re.fullmatch(
                r"sha256:[0-9a-f]{64}",
                legacy_cleanup_authority,
            )
            is None
            or not hmac.compare_digest(
                legacy_cleanup_authority,
                claim_reference_sha256,
            )
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_cleanup_authority_invalid"
            )
    inspection = state.transaction.inspect()
    if inspection.journal.state != "exact" or not inspection.journal.verified_prefix:
        raise ArchiveServiceError(
            "project_version_update_transaction_checkpoint_invalid"
        )
    head = inspection.journal.verified_prefix[-1]
    if head.phase in {"domain_committed", "claim_succeeded"}:
        state.transaction.finalize_succeeded_claim(
            checkpoint_guard_sha256=head.checkpoint_sha256,
            live_component_sha256=_project_update_live_component_sha256(
                state
            ),
            claim_receipt_sha256=evidence["claim_receipt_sha256"],
            claim_mac_sha256=evidence["claim_mac_sha256"],
            claim_evidence=evidence,
        )
    inspection = state.transaction.inspect()
    head = inspection.journal.verified_prefix[-1]
    domain_result = state.terminal_domain_result
    if domain_result is None:
        domain_result = _project_update_privacy_safe_domain_result(
            _project_update_build_domain_result(
                state,
                operation_exact_human_approval=None,
            )
        )
    pending_record, pending_handoff_sha256 = (
        _project_update_publish_preunlock_terminal_handoff(
            state,
            claim,
            domain_result,
        )
    )
    if head.phase == "claim_succeeded":
        state.transaction.append(
            phase="ready_to_unlock",
            stage="verified",
            live_component_sha256=_project_update_live_component_sha256(
                state
            ),
        )
    inspection = state.transaction.inspect()
    head = inspection.journal.verified_prefix[-1]
    if head.phase == "ready_to_unlock":
        live_component_sha256 = _project_update_live_component_sha256(
            state
        )
        lock_path = state.project_root.joinpath(
            *PurePosixPath(
                project_update_transaction.PROJECT_UPDATE_LOCK_LOGICAL
            ).parts
        )
        if os.path.lexists(lock_path):
            release = state.transaction.release_lock_exact(
                expected_lock_bytes=state.expected_lock_bytes,
                live_component_sha256=live_component_sha256,
            )
        else:
            # A hard exit may land after the exact unlink+directory fsync but
            # before the lock_released checkpoint.  Re-prove that same absence
            # under the sealed backlink instead of attempting a second unlink.
            release = state.transaction.confirm_lock_absence_durable(
                live_component_sha256=live_component_sha256,
            )
        state.transaction.append(
            phase="lock_released",
            stage="verified",
            live_component_sha256=live_component_sha256,
            lock_release_result=release,
        )
    inspection = state.transaction.inspect()
    head = inspection.journal.verified_prefix[-1]
    if head.phase == "lock_released":
        state.transaction.append(
            phase="completed",
            stage="verified",
            live_component_sha256=_project_update_live_component_sha256(
                state
            ),
        )
    inspection = state.transaction.inspect()
    live = _project_update_live_component_sha256(state)
    classification = state.transaction.classify_live_components(live)
    lock_path = state.project_root.joinpath(
        *PurePosixPath(
            project_update_transaction.PROJECT_UPDATE_LOCK_LOGICAL
        ).parts
    )
    if (
        not inspection.terminal
        or inspection.journal.state != "exact"
        or not inspection.journal.verified_prefix
        or inspection.journal.verified_prefix[-1].phase != "completed"
        or classification.overall != "complete_exact"
        or os.path.lexists(lock_path)
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_result_unverified"
        )
    state.terminal_handoff_sha256 = (
        _project_update_publish_ready_terminal_handoff(
            state,
            claim,
            pending_record,
            pending_handoff_sha256,
            live,
        )
    )
    _project_update_finalize_legacy_recovery_success(
        state,
        claim_evidence=evidence,
        fresh_transaction_completed_sha256=(
            inspection.journal.verified_prefix[-1].checkpoint_sha256
        ),
    )
    # This in-memory authority is established while the authenticated
    # succeeded claim and exact transaction are still open. It is never
    # reconstructed from a cleanup tombstone or proof in a later process.
    state.terminal_update_verified = True
    state.transaction_cleanup_completed = state.transaction.exact_cleanup(
        cleanup_authority_sha256=(
            legacy_cleanup_authority
            or state.terminal_handoff_sha256
        )
    )


def _project_update_finalize_legacy_recovery_success(
    state: _ProjectVersionUpdateDurableApprovalState,
    *,
    claim_evidence: Mapping[str, Any],
    fresh_transaction_completed_sha256: str,
) -> None:
    """Seal the legacy handoff before the fresh transaction is cleaned.

    This record is control-plane evidence only.  It neither mutates nor
    finalizes the predecessor claim and it never serializes a path, claim ID,
    transaction ID, or recovery ID into the public result.
    """

    control = getattr(state, "legacy_prewrite_recovery_control", None)
    if control is None:
        return
    if not isinstance(control, dict):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    paths = control.get("paths")
    old_inventory_sha256 = control.get("old_transaction_tree_sha256")
    old_lock_bytes = control.get("old_lock_bytes")
    with_store = control.get("with_store")
    intent_sha256 = control.get("intent_sha256")
    if (
        not isinstance(paths, project_update_legacy_recovery.RecoveryPaths)
        or type(old_inventory_sha256) is not str
        or type(old_lock_bytes) is not bytes
        or not callable(with_store)
        or type(intent_sha256) is not str
        or type(fresh_transaction_completed_sha256) is not str
        or not isinstance(claim_evidence, Mapping)
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    public_old_backup = state.transaction._lock_path.parent / (
        ".legacy-recovery-"
        + paths.recovery_ref.removeprefix("recovery_")
        + ".old-lock"
    )
    debug_stage = "vault"
    try:
        vaulted = project_update_legacy_recovery.vault_old_lock_backup(
            paths,
            public_old_backup,
            expected_old_lock_bytes=old_lock_bytes,
        )
        old_lock_backup_sha256 = vaulted["old_lock_backup_sha256"]
        completion_evidence_sha256 = (
            project_update_transaction.sha256_document(
                {
                    "claim_evidence_sha256": (
                        project_update_transaction.sha256_document(
                            dict(claim_evidence)
                        )
                    ),
                    "fresh_transaction_completed_sha256": (
                        fresh_transaction_completed_sha256
                    ),
                    "old_lock_backup_sha256": old_lock_backup_sha256,
                    "schema": (
                        "wom-kit/project-update-legacy-success-evidence/"
                        "v0.4.19"
                    ),
                }
            )
        )
        locator = with_store(lambda store: store.read_locator())
        debug_stage = "checkpoint"
        locator_state = str(locator.get("state") or "")
        if locator_state == "fresh_lock_backlinked":
            _project_update_legacy_recovery_checkpoint(
                state,
                phase="fresh_transaction_completed",
                evidence_sha256=completion_evidence_sha256,
                locator_state="fresh_transaction_completed",
            )
        elif locator_state in {
            "fresh_transaction_completed",
            "terminal_completed",
        }:
            checkpoints = with_store(
                lambda store: store.read_checkpoints(
                    intent_sha256=intent_sha256
                )
            )
            if (
                not checkpoints
                or checkpoints[-1].get("phase")
                != "fresh_transaction_completed"
                or checkpoints[-1].get("evidence_sha256")
                != completion_evidence_sha256
            ):
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_changed"
                )
            control["journal_head_sha256"] = locator.get(
                "journal_head_sha256"
            )
            control["locator_sha256"] = (
                project_update_legacy_recovery.sha256_bytes(
                    project_update_legacy_recovery._read_regular(
                        paths.locator_path
                    )
                )
            )
        else:
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )

        journal_head_sha256 = control.get("journal_head_sha256")
        locator_sha256 = control.get("locator_sha256")
        if type(journal_head_sha256) is not str or type(locator_sha256) is not str:
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_binding_invalid"
            )
        receipt = project_update_legacy_recovery.terminal_receipt_document(
            recovery_ref=paths.recovery_ref,
            outcome="success",
            intent_sha256=intent_sha256,
            journal_head_sha256=journal_head_sha256,
            fresh_transaction_ref=state.transaction.transaction_ref,
            old_transaction_inventory_sha256=old_inventory_sha256,
            fresh_transaction_completed_sha256=(
                fresh_transaction_completed_sha256
            ),
            claim_evidence_sha256=(
                project_update_transaction.sha256_document(
                    dict(claim_evidence)
                )
            ),
            old_lock_backup_sha256=old_lock_backup_sha256,
        )
        receipt_sha256 = with_store(
            lambda store: store.write_terminal_receipt(receipt)
        )
        if locator_state == "terminal_completed":
            if locator.get("terminal_receipt_sha256") != receipt_sha256:
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_changed"
                )
            with_store(
                lambda store: store.retire_locator(
                    expected_locator_sha256=locator_sha256
                )
            )
        else:
            with_store(
                lambda store: store.publish_terminal_locator_and_retire(
                    intent_sha256=intent_sha256,
                    journal_head_sha256=journal_head_sha256,
                    previous_locator_sha256=locator_sha256,
                    terminal_receipt_sha256=receipt_sha256,
                )
            )
        control["recovery_phase"] = "terminal_completed"
        control["terminal_receipt_sha256"] = receipt_sha256
    except ArchiveServiceError:
        raise
    except project_update_legacy_recovery.LegacyProjectUpdateRecoveryError as failure:
        raise ArchiveServiceError(failure.code) from None
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        ) from None


def _project_update_attach_terminal_finalization(
    result: Mapping[str, Any],
    state: _ProjectVersionUpdateDurableApprovalState,
    *,
    service_resource_close_verified: bool,
    runner_close_verified: bool,
) -> dict[str, Any]:
    """Keep authenticated update truth separate from follow-up cleanup truth."""

    if (
        not isinstance(result, Mapping)
        or result.get("ok") is not True
        or state.terminal_update_verified is not True
        or type(state.transaction_cleanup_completed) is not bool
        or type(service_resource_close_verified) is not bool
        or type(runner_close_verified) is not bool
        or type(state.terminal_handoff_sha256) is not str
        or not state.terminal_handoff_sha256.startswith("sha256:")
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_result_unverified"
        )
    cleanup_completed = bool(state.transaction_cleanup_completed)
    delivery_acknowledged = False
    attention_required = not (
        cleanup_completed
        and service_resource_close_verified
        and runner_close_verified
        and delivery_acknowledged
    )
    domain_result = copy.deepcopy(
        state.terminal_domain_result
        if isinstance(state.terminal_domain_result, dict)
        else _project_update_privacy_safe_domain_result(result)
    )
    terminal = {
        "schema": (
            "wom-kit/project-version-update-terminal-finalization/v0.1"
        ),
        "update_result_verified_in_current_invocation": True,
        "update_result_reauthenticated_from_durable_handoff": False,
        "claim_succeeded_verified": True,
        "transaction_completed_checkpoint_verified": True,
        "lock_absence_verified": True,
        "transaction_cleanup_completed": cleanup_completed,
        "service_resource_close_verified": (
            service_resource_close_verified
        ),
        "git_runner_close_verified": runner_close_verified,
        "attention_required": attention_required,
        "domain_writer_reentry_allowed": False,
        "automatic_retry_allowed": False,
        "cleanup_proof_used_as_success_authority": False,
        "durable_terminal_handoff_ready": True,
        "durable_terminal_handoff_replayed": False,
        "durable_result_delivery_acknowledged": delivery_acknowledged,
        "private_paths_echoed": False,
        "private_identifiers_echoed": False,
    }
    projected = _project_update_terminal_result_from_domain(
        domain_result,
        terminal,
    )
    if projected is None:
        raise ArchiveServiceError(
            "project_version_update_terminal_result_unverified"
        )
    return projected


def _project_update_attempt_all_service_closes(
    close_owned_resources: Callable[[], None],
    lifetime: _ProjectVersionUpdateGitRunnerLifetime,
) -> tuple[BaseException | None, BaseException | None]:
    """Attempt both independent closes and retain only content-free truth."""

    service_resource_close_failure: BaseException | None = None
    try:
        close_owned_resources()
    except BaseException as failure:
        service_resource_close_failure = failure
    runner_close_failure: BaseException | None = None
    try:
        lifetime.close_after_service_transaction()
    except BaseException as failure:
        runner_close_failure = failure
    return service_resource_close_failure, runner_close_failure


def _project_update_close_after_service_failure(
    close_owned_resources: Callable[[], None],
    lifetime: _ProjectVersionUpdateGitRunnerLifetime,
) -> None:
    """Close after a primary failure without letting close hide that failure."""

    _project_update_attempt_all_service_closes(
        close_owned_resources,
        lifetime,
    )


def _project_update_attach_nonterminal_close_truth(
    result: dict[str, Any],
    *,
    service_resource_close_failure: BaseException | None,
    runner_close_failure: BaseException | None,
) -> dict[str, Any]:
    """Keep one domain/control result while exposing content-free close truth."""

    existing = result.get("service_finalization")
    existing_service_verified = True
    existing_runner_verified = True
    if (
        isinstance(existing, Mapping)
        and existing.get("schema")
        == "wom-kit/project-version-update-service-finalization/v0.4.16"
        and type(existing.get("service_resource_close_verified")) is bool
        and type(existing.get("git_runner_close_verified")) is bool
    ):
        existing_service_verified = bool(
            existing["service_resource_close_verified"]
        )
        existing_runner_verified = bool(
            existing["git_runner_close_verified"]
        )
    service_resource_close_verified = bool(
        existing_service_verified
        and service_resource_close_failure is None
    )
    runner_close_verified = bool(
        existing_runner_verified and runner_close_failure is None
    )
    if service_resource_close_verified and runner_close_verified:
        return result
    result["service_finalization"] = {
        "schema": (
            "wom-kit/project-version-update-service-finalization/v0.4.16"
        ),
        "service_resource_close_verified": (
            service_resource_close_verified
        ),
        "git_runner_close_verified": runner_close_verified,
        "attention_required": True,
        "private_paths_echoed": False,
        "private_identifiers_echoed": False,
        "raw_errors_echoed": False,
    }
    result["post_service_attention_required"] = True
    return result


def _project_update_finish_nonterminal_service_result(
    result: Mapping[str, Any],
    lifetime: _ProjectVersionUpdateGitRunnerLifetime,
    *,
    close_owned_resources: Callable[[], None],
) -> dict[str, Any]:
    """Close a nonterminal service result without replacing its domain truth."""

    try:
        if not isinstance(result, Mapping):
            raise ArchiveServiceError(
                "project_version_update_result_invalid"
            )
        completed_result = dict(result)
    except BaseException:
        _project_update_close_after_service_failure(
            close_owned_resources,
            lifetime,
        )
        raise
    (
        service_resource_close_failure,
        runner_close_failure,
    ) = _project_update_attempt_all_service_closes(
        close_owned_resources,
        lifetime,
    )
    return _project_update_attach_nonterminal_close_truth(
        completed_result,
        service_resource_close_failure=service_resource_close_failure,
        runner_close_failure=runner_close_failure,
    )


def _project_update_finish_legacy_cancellation_result(
    result: Mapping[str, Any],
    lifetime: _ProjectVersionUpdateGitRunnerLifetime,
    *,
    close_owned_resources: Callable[[], None],
) -> dict[str, Any]:
    """Close without mutating one recovery-key-authenticated result."""

    if not _project_update_is_legacy_unapproved_terminal_result(result):
        _project_update_close_after_service_failure(
            close_owned_resources,
            lifetime,
        )
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )
    (
        service_resource_close_failure,
        runner_close_failure,
    ) = _project_update_attempt_all_service_closes(
        close_owned_resources,
        lifetime,
    )
    if (
        service_resource_close_failure is not None
        or runner_close_failure is not None
    ):
        # The durable capsule remains authoritative for a later resume.  Adding
        # close-truth fields here would change the authenticated result bytes.
        raise ArchiveServiceError(
            "project_version_update_terminal_delivery_unverified"
        )
    return dict(result)


def _project_update_finish_resource_only_result(
    result: Mapping[str, Any],
    *,
    close_owned_resources: Callable[[], None],
) -> dict[str, Any]:
    """Preserve one mapping while truthfully closing its only resource owner."""

    try:
        if not isinstance(result, Mapping):
            raise ArchiveServiceError(
                "project_version_update_result_invalid"
            )
        completed_result = dict(result)
    except BaseException:
        try:
            close_owned_resources()
        except BaseException:
            pass
        raise
    close_failure: BaseException | None = None
    try:
        close_owned_resources()
    except BaseException as failure:
        close_failure = failure
    return _project_update_attach_nonterminal_close_truth(
        completed_result,
        service_resource_close_failure=close_failure,
        runner_close_failure=None,
    )


def _project_update_finish_service_result(
    result: Mapping[str, Any],
    state: _ProjectVersionUpdateDurableApprovalState,
    lifetime: _ProjectVersionUpdateGitRunnerLifetime,
    *,
    close_owned_resources: Callable[[], None],
) -> dict[str, Any]:
    """Use one terminal close/result rule for fresh and resumed updates."""

    try:
        if not isinstance(result, Mapping):
            raise ArchiveServiceError(
                "project_version_update_result_invalid"
            )
        completed_result = dict(result)
    except BaseException:
        _project_update_close_after_service_failure(
            close_owned_resources,
            lifetime,
        )
        raise
    (
        service_resource_close_failure,
        runner_close_failure,
    ) = _project_update_attempt_all_service_closes(
        close_owned_resources,
        lifetime,
    )
    service_resource_close_verified = service_resource_close_failure is None
    runner_close_verified = runner_close_failure is None
    terminal_success = bool(
        state.terminal_update_verified is True
        and completed_result.get("ok") is True
    )
    if not terminal_success:
        return _project_update_attach_nonterminal_close_truth(
            completed_result,
            service_resource_close_failure=(
                service_resource_close_failure
            ),
            runner_close_failure=runner_close_failure,
        )
    if state.terminal_update_verified is not True:
        return completed_result
    return _project_update_attach_terminal_finalization(
        completed_result,
        state,
        service_resource_close_verified=(
            service_resource_close_verified
        ),
        runner_close_verified=runner_close_verified,
    )


def _project_update_cancel_before_native(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> None:
    """Use only core-derived deterministic cancellation evidence."""

    live = _project_update_live_component_sha256(state)
    checkpoints = state.transaction.inspect().journal.verified_prefix
    if not any(
        item.phase == "preapproval_cancel_requested"
        for item in checkpoints
    ):
        state.transaction.begin_cancel_before_approval(
            expected_lock_bytes=state.expected_lock_bytes,
            live_component_sha256=live,
        )
    try:
        existing_ack = (
            project_update_transaction.load_runtime_cleanup_durable_ack(
                state.project_root,
                state.transaction.transaction_ref,
            )
        )
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_runtime_candidate_cleanup_failed"
        ) from None
    cleanup_capsule: (
        project_runtime.RuntimeCandidateCleanupCapsule | None
    ) = None
    cleanup_evidence: dict[str, Any] | None = None
    if existing_ack is None:
        cleanup_capsule, cleanup_evidence = (
            _project_update_prepare_runtime_cleanup(
                state.runtime_candidate
            )
        )
    else:
        cleanup_capsule = (
            _project_update_runtime_cleanup_sidecar_for_transaction(
                project_root=state.project_root,
                transaction_root=state.transaction.transaction_root,
                transaction_ref=state.transaction.transaction_ref,
            )
        )
        if cleanup_capsule is not None:
            observed = (
                project_runtime.runtime_candidate_cleanup_terminal_evidence(
                    cleanup_capsule
                )
            )
            if not isinstance(observed, dict):
                raise ArchiveServiceError(
                    "project_version_update_runtime_candidate_cleanup_failed"
                )
            cleanup_evidence = observed
        else:
            tail = state.transaction.inspect().journal.verified_prefix[-1]
            if tail.phase != "completed":
                raise ArchiveServiceError(
                    "project_version_update_runtime_candidate_cleanup_failed"
                )
    if cleanup_evidence is not None:
        state.transaction.cancel_before_approval(
            expected_lock_bytes=state.expected_lock_bytes,
            live_component_sha256=(
                _project_update_live_component_sha256(state)
            ),
            runtime_cleanup_terminal_evidence=cleanup_evidence,
        )
    _project_update_retire_runtime_cleanup_after_durable_ack(
        project_root=state.project_root,
        transaction_root=state.transaction.transaction_root,
        transaction_ref=state.transaction.transaction_ref,
        capsule=cleanup_capsule,
    )
    cleanup_authority = state.transaction.candidate_cleanup_receipt_sha256()
    if not state.transaction.exact_cleanup(
        cleanup_authority_sha256=cleanup_authority
    ):
        raise ArchiveServiceError(
            "project_version_update_transaction_cleanup_incomplete"
        )


def _project_update_abort_unsealed_candidate(
    *,
    reservation: project_update_transaction.ReservedProjectUpdateTransaction,
    expected_lock_bytes: bytes,
    candidate: project_runtime.PreparedRuntimeCandidate,
) -> dict[str, Any]:
    """Remove one complete candidate, then durably abort its unsealed lock."""

    cleanup_capsule, cleanup_evidence = (
        _project_update_prepare_runtime_cleanup(candidate)
    )
    result = reservation.abort_before_intent_seal(
        expected_lock_bytes=expected_lock_bytes,
        runtime_cleanup_terminal_evidence=cleanup_evidence,
    )
    _project_update_retire_runtime_cleanup_after_durable_ack(
        project_root=candidate.project_root,
        transaction_root=reservation.transaction_root,
        transaction_ref=reservation.transaction_ref,
        capsule=cleanup_capsule,
    )
    return result


def _project_update_prepare_durable_state(
    *,
    inspection_root: Path,
    project_root: Path,
    mirror_path: Path,
    mirror_logical: str,
    target_tag: str,
    target_version: str,
    target_commit: str,
    reviewer: str,
    expected_approval_root: Path,
    expected_archive_id: str,
    reservation: project_update_transaction.ReservedProjectUpdateTransaction,
    expected_lock_bytes: bytes,
    runner: project_update_git_runner.TrustedProjectUpdateGitRunner,
    runtime_candidate: project_runtime.PreparedRuntimeCandidate,
    runtime_bootstrap: project_runtime.BootstrapWheel,
    runtime_supply: project_runtime.RuntimeSupplyLock,
    runtime_policy: Mapping[str, Any],
    runtime_plan: Mapping[str, Any],
    directory_guard: _WomKitProjectUpdateDirectoryGuard,
    preflight_git_snapshot: Mapping[str, Any],
    preflight_git_config_digest: str,
    target_ref_snapshot: Mapping[str, str],
    target_evidence: Mapping[str, Any],
    materialization_preflight: Mapping[str, Any],
    head_before: str,
    pin_specs: list[dict[str, Any]],
    launcher_snapshot: Mapping[str, Any],
    prepared_preview_base: Mapping[str, Any],
    legacy_prewrite_recovery: Mapping[str, Any] | None = None,
) -> _ProjectVersionUpdateDurableApprovalState:
    """Construct receipt/intent once; no final approval digest is patched in."""

    if (
        type(target_version) is not str
        or type(target_commit) is not str
        or type(preflight_git_config_digest) is not str
        or type(head_before) is not str
        or not isinstance(preflight_git_snapshot, Mapping)
        or not isinstance(target_ref_snapshot, Mapping)
        or not isinstance(launcher_snapshot, Mapping)
        or not isinstance(prepared_preview_base, Mapping)
        or not isinstance(runtime_candidate, project_runtime.PreparedRuntimeCandidate)
        or not isinstance(runtime_bootstrap, project_runtime.BootstrapWheel)
        or not isinstance(runtime_supply, project_runtime.RuntimeSupplyLock)
    ):
        raise ArchiveServiceError(
            "project_version_update_transaction_preparation_invalid"
        )
    static_receipt_relative = (
        f"{WOM_KIT_PROJECT_UPDATE_RECEIPTS_RELATIVE}/"
        f"{reservation.transaction_ref}.json"
    )
    static_receipt_path = project_root.joinpath(
        *PurePosixPath(static_receipt_relative).parts
    )
    receipt_observation = wom_kit_real_path_kind_observation(
        project_root,
        static_receipt_path,
    )
    if receipt_observation["state"] == "unavailable":
        raise ArchiveServiceError(
            "project_version_update_transaction_receipt_observation_unavailable"
        )
    if (
        receipt_observation["state"] != "passed"
        or receipt_observation["kind"] != "missing"
    ):
        raise ArchiveServiceError(
            "project_version_update_transaction_receipt_exists"
        )

    source_preimage = _project_update_canonical_bytes(
        _project_update_private_json_value(dict(preflight_git_snapshot))
    )
    source_pre_sha256 = project_update_transaction.sha256_bytes(
        source_preimage
    )
    rematerialization_required = bool(
        materialization_preflight.get("required")
    )
    source_post_projection = {
        "branch": None,
        "materialization_plan_sha256": materialization_preflight.get(
            "materialization_plan_sha256"
        ),
        "runtime_source_integrity_required": True,
        "schema": "wom-kit/project-update-source-postimage/v0.4.3",
        "target_commit": target_commit,
        "target_ref_snapshot_sha256": (
            project_update_transaction.sha256_document(
                dict(target_ref_snapshot)
            )
        ),
        "target_version": target_version,
    }
    source_post_sha256 = (
        project_update_transaction.sha256_document(source_post_projection)
        if rematerialization_required
        else source_pre_sha256
    )
    runtime_post_sha256 = "sha256:" + runtime_candidate.installed_payload_sha256
    runtime_pre_sha256 = (
        runtime_post_sha256
        if runtime_candidate.existing_runtime_reusable
        else (
            "sha256:"
            + str(runtime_candidate.existing_runtime_inventory_sha256)
            if runtime_candidate.existing_runtime_repair_required
            and runtime_candidate.existing_runtime_inventory_sha256 is not None
            else project_update_transaction.ABSENT_COMPONENT_SHA256
        )
    )

    target_pin_bytes = (target_tag + "\n").encode("utf-8")
    launcher_previous = launcher_snapshot.get("previous_bytes")
    launcher_target = launcher_snapshot.get("target_bytes")
    if (
        launcher_previous is not None
        and not isinstance(launcher_previous, bytes)
    ) or not isinstance(launcher_target, bytes):
        raise ArchiveServiceError(
            "project_version_update_transaction_preparation_invalid"
        )

    component_specs: list[dict[str, Any]] = [
        {
            "component_ref": "source",
            "role": "source",
            "logical_target": mirror_logical,
            "pre_sha256": source_pre_sha256,
            "post_sha256": source_post_sha256,
            "preimage_key": "source-preimage",
        },
        {
            "component_ref": "runtime",
            "role": "runtime",
            "logical_target": project_runtime.runtime_logical_path(
                target_version
            ),
            "pre_sha256": runtime_pre_sha256,
            "post_sha256": runtime_post_sha256,
            "preimage_key": None,
        },
        {
            "component_ref": "launcher",
            "role": "launcher",
            "logical_target": str(launcher_snapshot.get("logical")),
            "pre_sha256": _project_update_raw_component_sha256(
                launcher_previous
            ),
            "post_sha256": _project_update_raw_component_sha256(
                launcher_target
            ),
            "preimage_key": (
                "launcher-preimage"
                if isinstance(launcher_previous, bytes)
                else None
            ),
        },
    ]
    non_active_specs = [
        spec for spec in pin_specs if spec.get("role") != "project_pin"
    ]
    active_specs = [
        spec for spec in pin_specs if spec.get("role") == "project_pin"
    ]
    if len(active_specs) != 1:
        raise ArchiveServiceError(
            "project_version_update_transaction_preparation_invalid"
        )
    ordered_pin_specs = [*non_active_specs, *active_specs]
    for index, spec in enumerate(ordered_pin_specs, start=1):
        previous = spec.get("previous_bytes")
        if previous is not None and not isinstance(previous, bytes):
            raise ArchiveServiceError(
                "project_version_update_transaction_preparation_invalid"
            )
        is_active = spec.get("role") == "project_pin"
        component_ref = (
            "active-pin" if is_active else f"non-active-pin:{index:02d}"
        )
        component_specs.append(
            {
                "component_ref": component_ref,
                "role": "active_pin" if is_active else "non_active_pin",
                "logical_target": spec["logical"],
                "pre_sha256": _project_update_raw_component_sha256(
                    previous
                ),
                "post_sha256": _project_update_raw_component_sha256(
                    target_pin_bytes
                ),
                "preimage_key": (
                    f"{component_ref}-preimage"
                    if isinstance(previous, bytes)
                    else None
                ),
            }
        )
    # Receipt is the last non-activation component.  The project pin remains
    # the final component even when other pins are already at the target.
    active_component = component_specs.pop()

    domain_target = {
        "component_postimages": {
            item["component_ref"]: item["post_sha256"]
            for item in [*component_specs, active_component]
        },
        "schema": "wom-kit/project-update-domain-target/v0.4.3",
        "target_commit": target_commit,
        "target_ref_snapshot_sha256": (
            project_update_transaction.sha256_document(
                dict(target_ref_snapshot)
            )
        ),
        "target_tag": target_tag,
        "target_version": target_version,
    }
    domain_plan = {
        "components": [
            {
                key: value
                for key, value in item.items()
                if key != "preimage_key"
            }
            for item in [*component_specs, active_component]
        ],
        "external_writer_quiescence": True,
        "git_config_sha256": "sha256:" + preflight_git_config_digest,
        "materialization_preflight_sha256": (
            project_update_transaction.sha256_document(
                dict(materialization_preflight)
            )
        ),
        "runtime_candidate_sha256": (
            project_update_transaction.sha256_document(
                runtime_candidate.public_summary()
            )
        ),
        "schema": "wom-kit/project-update-domain-plan/v0.4.3",
        "source_preimage_sha256": source_pre_sha256,
        "target": domain_target,
    }
    domain_plan_sha256 = project_update_transaction.sha256_document(
        domain_plan
    )
    domain_target_sha256 = project_update_transaction.sha256_document(
        domain_target
    )
    pins_written = [
        spec["logical"]
        for spec in pin_specs
        if spec.get("previous_bytes") != target_pin_bytes
    ]
    runtime_created = not runtime_candidate.existing_runtime_reusable
    runtime_repair = runtime_candidate.existing_runtime_repair_required
    launcher_written = launcher_previous != launcher_target
    receipt = {
        "schema": (
            "wom-kit/project-version-update-receipt/v0.4"
            if runtime_repair
            else "wom-kit/project-version-update-receipt/v0.3"
        ),
        "action": "project_version_update",
        "status": "updated_restart_required",
        "timestamp": reservation.created_at,
        "reviewed_by": reviewer,
        "target_tag": target_tag,
        "target_version": target_version,
        "source_mirror": mirror_logical,
        "head_commit_before": head_before,
        "head_commit_after": target_commit,
        "source_checkout_changed": rematerialization_required,
        "runtime_source_materialization": {
            "attempted": rematerialization_required,
            "succeeded": True if rematerialization_required else None,
            "target_integrity_verified": True,
        },
        "external_writer_quiescence": {
            "affirmed": True,
            "scope": "complete_project_version_update_transaction",
        },
        "pins_written": pins_written,
        "pin_transitions": [
            {
                "path": spec["logical"],
                "previous_version": spec.get("previous_version"),
                "new_version": target_tag,
                "written": spec.get("previous_bytes") != target_pin_bytes,
            }
            for spec in pin_specs
        ],
        "configured_origin": {
            "remote_name": "origin",
            "atomic_fetch_succeeded": True,
            "target_reachable_from_origin_main": True,
            "annotated_tag_verified": True,
            "cryptographic_tag_signature_verified": False,
            "remote_url_echoed": False,
        },
        "project_runtime": {
            "policy_schema": runtime_policy["schema"],
            "policy_sha256": runtime_policy["policy_sha256"],
            "path": project_runtime.runtime_logical_path(target_version),
            "launcher_path": str(launcher_snapshot["logical"]),
            "project_runtime_argv": project_runtime.project_runtime_argv(),
            "target_tag": target_tag,
            "target_version": target_version,
            "target_commit": target_commit,
            "wheel_sha256": "sha256:" + runtime_candidate.wheel_sha256,
            "supply_lock_sha256": (
                "sha256:" + runtime_candidate.supply_lock_sha256
            ),
            "runtime_receipt_sha256": (
                "sha256:" + runtime_candidate.receipt_sha256
            ),
            "artifact_inventory": [
                dict(item) for item in runtime_candidate.artifact_inventory
            ],
            "installed_payload_sha256": runtime_post_sha256,
            "python_version": runtime_candidate.python_version,
            "created": runtime_created,
            "launcher_written": launcher_written,
            "verification": dict(runtime_candidate.verification),
            "new_process_verified": True,
            "global_path_mutation": False,
            **(
                {
                    "runtime_receipt_schema": (
                        runtime_candidate.public_summary()[
                            "runtime_receipt_schema"
                        ]
                    ),
                    "previous_runtime_deleted_during_materialization": False,
                    "terminal_cleanup_required_to_remove_private_repair_preimage": True,
                }
                if runtime_repair
                else {"previous_runtime_deleted": False}
            ),
        },
        "runtime": {
            "running_version_before": WOM_KIT_VERSION,
            "running_process_reloaded": False,
            "restart_required": True,
        },
        "transaction_ref": reservation.transaction_ref,
        # These are the acyclic domain manifest/target-set digests.  They are
        # deliberately not the final native approval binding digests.
        "plan_sha256": domain_plan_sha256,
        "target_binding_sha256": domain_target_sha256,
        "approval_evidence_contract": dict(
            _PROJECT_UPDATE_STATIC_APPROVAL_CONTRACT
        ),
        "privacy_guards": {
            "local_absolute_paths_echoed": False,
            "remote_urls_echoed": False,
            "credential_values_echoed": False,
            "archive_body_text_read": False,
            "objet_bytes_read": False,
        },
    }
    if validate_schema(
        receipt,
        (
            "project-version-update-receipt-v0.4.schema.json"
            if runtime_repair
            else "project-version-update-receipt-v0.3.schema.json"
        ),
    ):
        raise ArchiveServiceError(
            "project_version_update_static_receipt_schema_invalid"
        )
    static_receipt_bytes = _project_update_canonical_bytes(receipt)
    component_specs.append(
        {
            "component_ref": "receipt",
            "role": "receipt",
            "logical_target": static_receipt_relative,
            "pre_sha256": project_update_transaction.ABSENT_COMPONENT_SHA256,
            "post_sha256": project_update_transaction.sha256_bytes(
                static_receipt_bytes
            ),
            "preimage_key": None,
        }
    )
    component_specs.append(active_component)
    components = tuple(
        project_update_transaction.ProjectUpdateComponent(
            sequence=index,
            **spec,
        )
        for index, spec in enumerate(component_specs, start=1)
    )
    preimages: dict[str, bytes] = {"source-preimage": source_preimage}
    if isinstance(launcher_previous, bytes):
        preimages["launcher-preimage"] = launcher_previous
    for component, spec in zip(components, component_specs):
        if component.role not in {"non_active_pin", "active_pin"}:
            continue
        matching = next(
            item
            for item in pin_specs
            if item["logical"] == component.logical_target
        )
        if isinstance(matching.get("previous_bytes"), bytes):
            assert component.preimage_key is not None
            preimages[component.preimage_key] = matching["previous_bytes"]

    recovery_binding_sha256 = None
    recovery_summary: dict[str, Any] | None = None
    if legacy_prewrite_recovery is not None:
        recovery_summary = dict(legacy_prewrite_recovery)
        recovery_binding_sha256 = project_update_transaction.sha256_document(
            recovery_summary
        )
    private_plan = {
        "schema": _PROJECT_UPDATE_PRIVATE_PLAN_SCHEMA,
        "transaction_ref": reservation.transaction_ref,
        "target_tag": target_tag,
        "target_version": target_version,
        "target_commit": target_commit,
        "reviewer": reviewer,
        "mirror_logical": mirror_logical,
        "head_before": head_before,
        "preflight_git_snapshot": dict(preflight_git_snapshot),
        "preflight_git_config_digest": preflight_git_config_digest,
        "target_ref_snapshot": dict(target_ref_snapshot),
        "target_evidence": dict(target_evidence),
        "materialization_preflight": dict(materialization_preflight),
        "runtime_policy": dict(runtime_policy),
        "runtime_plan": dict(runtime_plan),
        "runtime_bootstrap": dict(runtime_bootstrap.public_summary()),
        "runtime_candidate_private": (
            _project_update_runtime_candidate_private_document(
                runtime_candidate
            )
        ),
        "launcher_snapshot": {
            key: value
            for key, value in launcher_snapshot.items()
            if key != "path"
        },
        "pin_specs": [
            {
                key: value
                for key, value in spec.items()
                if key != "path"
            }
            for spec in pin_specs
        ],
        "component_postimages": {
            "launcher": launcher_target,
            **{
                component.component_ref: target_pin_bytes
                for component in components
                if component.role in {"non_active_pin", "active_pin"}
            },
        },
        "static_receipt_relative": static_receipt_relative,
        "static_receipt_schema": receipt["schema"],
        "domain_plan": domain_plan,
        "domain_plan_sha256": domain_plan_sha256,
        "domain_target_sha256": domain_target_sha256,
        "expected_archive_identity_sha256": (
            exact_human_approval_archive_identity_sha256(
                expected_archive_id
            )
        ),
        # This is the complete acyclic service projection before the sealed
        # intent/runner/static-receipt summaries are attached.  It lets a
        # crashed process reconstruct the identical native context without
        # storing the final (self-referential) approval digest.
        "prepared_preview_base": copy.deepcopy(
            dict(prepared_preview_base)
        ),
        **(
            {"legacy_prewrite_recovery": recovery_summary}
            if recovery_summary is not None
            else {}
        ),
    }
    private_plan_bytes = _project_update_canonical_bytes(
        _project_update_private_json_value(private_plan)
    )
    bindings = project_update_transaction.ProjectUpdateBindings(
        preflight_sha256=project_update_transaction.sha256_document(
            dict(materialization_preflight)
        ),
        source_sha256=source_post_sha256,
        config_sha256="sha256:" + preflight_git_config_digest,
        ref_sha256=project_update_transaction.sha256_document(
            dict(target_ref_snapshot)
        ),
        pin_sha256=project_update_transaction.sha256_document(
            [
                {
                    "logical": spec["logical"],
                    "post_sha256": _project_update_raw_component_sha256(
                        target_pin_bytes
                    ),
                }
                for spec in pin_specs
            ]
        ),
        launcher_sha256=_project_update_raw_component_sha256(
            launcher_target
        ),
        runtime_sha256=runtime_post_sha256,
        receipt_sha256=project_update_transaction.sha256_bytes(
            static_receipt_bytes
        ),
        bundle_sha256=project_update_transaction.sha256_document(
            runtime_candidate.public_summary()
        ),
    )
    transaction = reservation.seal_intent(
        bindings=bindings,
        components=components,
        preimages=preimages,
        private_binding_blobs={
            "git-runner-binding": runner.private_binding_bytes(),
            "project-update-domain-plan": private_plan_bytes,
            "runtime-supply-lock": runtime_supply.raw_bytes,
            **(
                {
                    "legacy-prewrite-recovery-binding": (
                        recovery_binding_sha256 + "\n"
                    ).encode("ascii")
                }
                if recovery_binding_sha256 is not None
                else {}
            ),
        },
        static_receipt_postimage=static_receipt_bytes,
        runtime_candidate_inventory_sha256=(
            "sha256:" + runtime_candidate.inventory_sha256
        ),
        runtime_candidate_postimage_sha256=runtime_post_sha256,
        runtime_candidate_receipt_relative_path=(
            project_runtime.PROJECT_RUNTIME_RECEIPT_NAME
        ),
        _legacy_recovery_binding_sha256=recovery_binding_sha256,
    )
    if recovery_binding_sha256 is None:
        transaction.bind_sealed_intent_to_lock(expected_lock_bytes)
    component_paths: dict[str, Path] = {
        "launcher": project_root
        / project_runtime.PROJECT_RUNTIME_LAUNCHER_RELATIVE,
        "receipt": static_receipt_path,
    }
    for component in components:
        if component.role in {"non_active_pin", "active_pin"}:
            matching = next(
                item
                for item in pin_specs
                if item["logical"] == component.logical_target
            )
            component_paths[component.component_ref] = matching["path"]
    state = _ProjectVersionUpdateDurableApprovalState(
        inspection_root=inspection_root,
        project_root=project_root,
        mirror_path=mirror_path,
        target_tag=target_tag,
        target_version=target_version,
        target_commit=target_commit,
        reviewer=reviewer,
        expected_approval_root=expected_approval_root,
        expected_archive_id=expected_archive_id,
        transaction=transaction,
        expected_lock_bytes=expected_lock_bytes,
        runner=runner,
        runtime_candidate=runtime_candidate,
        runtime_bootstrap=runtime_bootstrap,
        runtime_supply=runtime_supply,
        directory_guard=directory_guard,
        private_plan=private_plan,
        prepared_preview={},
        static_receipt_bytes=static_receipt_bytes,
        static_receipt_path=static_receipt_path,
        source_pre_sha256=source_pre_sha256,
        source_post_sha256=source_post_sha256,
        runtime_pre_sha256=runtime_pre_sha256,
        runtime_post_sha256=runtime_post_sha256,
        component_paths=component_paths,
        legacy_prewrite_recovery=(
            copy.deepcopy(recovery_summary)
            if recovery_summary is not None
            else None
        ),
    )
    if recovery_binding_sha256 is None:
        transaction.append(
            phase="lock_backlinked",
            stage="verified",
            live_component_sha256=_project_update_live_component_sha256(state),
        )
    return state


def _project_update_build_prepared_preview(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> dict[str, Any]:
    """Rebuild the one exact native projection from acyclic sealed inputs."""

    base = state.private_plan.get("prepared_preview_base")
    if type(base) is not dict:
        raise ArchiveServiceError(
            "project_version_update_private_plan_invalid"
        )
    prepared = copy.deepcopy(base)
    prepared["mode"] = "approval_prepared"
    prepared_receipt = prepared.get("receipt")
    if not isinstance(prepared_receipt, dict):
        raise ArchiveServiceError(
            "project_version_update_private_plan_invalid"
        )
    prepared_receipt["schema"] = state.private_plan[
        "static_receipt_schema"
    ]
    runner_summary = dict(state.runner.public_summary())
    candidate_summary = dict(state.runtime_candidate.public_summary())
    transaction = state.transaction
    control_scaffold_created = bool(
        not state.runtime_candidate.runtime_parent_existed_before
    )
    prepared["approval_preparation"] = {
        "lock_held": True,
        "network_complete": True,
        "post_approval_network_allowed": False,
        "target_ref_snapshot": copy.deepcopy(
            state.private_plan["target_ref_snapshot"]
        ),
        "preapproval_control_writes_completed": True,
        "preapproval_domain_writes_completed": False,
        "fetched_refs_may_change": True,
        "preapproval_control_scaffold_created": (
            control_scaffold_created
        ),
        "preapproval_persistent_domain_effect": False,
        "preapproval_runtime_content_installed": False,
        "preapproval_activation_changed": False,
        "runtime_postapproval_child_process_allowed": False,
        "project_update_postapproval_local_git_allowed": True,
        "postapproval_git_transport_allowed": False,
        "trusted_git_runner": runner_summary,
        "transaction": {
            "schema": project_update_transaction.PUBLIC_SUMMARY_SCHEMA,
            "transaction_ref": transaction.transaction_ref,
            "transaction_logical_ref": transaction.transaction_logical_ref,
            "intent_sha256": transaction.intent.sha256,
            "lock_backlinked": state.legacy_prewrite_recovery is None,
            "directory_fsync_required": True,
            "static_receipt_domain_plan_sha256": (
                transaction.intent.static_receipt_domain_plan_sha256
            ),
            "static_receipt_domain_target_binding_sha256": (
                transaction.intent
                .static_receipt_domain_target_binding_sha256
            ),
        },
        "runtime_candidate": candidate_summary,
        "static_receipt": {
            "schema": state.private_plan["static_receipt_schema"],
            "logical_path": state.private_plan[
                "static_receipt_relative"
            ],
            "sha256": project_update_transaction.sha256_bytes(
                state.static_receipt_bytes
            ),
            "domain_plan_sha256": state.private_plan[
                "domain_plan_sha256"
            ],
            "domain_target_binding_sha256": state.private_plan[
                "domain_target_sha256"
            ],
            "dynamic_claim_fields_embedded": False,
            "deterministic_one_pass_construction": True,
        },
        **(
            {
                "legacy_prewrite_recovery": copy.deepcopy(
                    state.legacy_prewrite_recovery
                )
            }
            if state.legacy_prewrite_recovery is not None
            else {}
        ),
    }
    prepared["fetch"]["phase"] = "before_native_approval"
    prepared["write_boundary"].update(
        {
            "post_approval_network_allowed": False,
            "project_update_lock_acquired": True,
            "preapproval_control_writes_completed": True,
            "preapproval_domain_writes_completed": False,
            "fetched_refs_may_change": True,
            "preapproval_control_scaffold_created": (
                control_scaffold_created
            ),
            "preapproval_persistent_domain_effect": False,
            "preapproval_runtime_content_installed": False,
            "preapproval_activation_changed": False,
            "runtime_postapproval_child_process_allowed": False,
            "project_update_postapproval_local_git_allowed": True,
            "postapproval_git_transport_allowed": False,
        }
    )
    return prepared


def _project_update_legacy_recovery_checkpoint(
    state: _ProjectVersionUpdateDurableApprovalState,
    *,
    phase: str,
    evidence_sha256: str,
    locator_state: str,
) -> None:
    control = getattr(state, "legacy_prewrite_recovery_control", None)
    if not isinstance(control, dict):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    _project_update_legacy_recovery_checkpoint_control(
        control,
        phase=phase,
        evidence_sha256=evidence_sha256,
        locator_state=locator_state,
    )


def _project_update_legacy_recovery_checkpoint_control(
    control: dict[str, Any],
    *,
    phase: str,
    evidence_sha256: str,
    locator_state: str,
) -> None:
    """Advance one authenticated recovery without requiring a live writer."""

    with_store = control.get("with_store")
    intent_sha256 = control.get("intent_sha256")
    previous_locator_sha256 = control.get("locator_sha256")
    if (
        not callable(with_store)
        or type(intent_sha256) is not str
        or type(previous_locator_sha256) is not str
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )

    def append(store: Any) -> tuple[str, str]:
        journal_head = store.append_checkpoint(
            phase=phase,
            stage="verified",
            intent_sha256=intent_sha256,
            evidence_sha256=evidence_sha256,
            expected_previous_checkpoint_sha256=(
                control.get("journal_head_sha256")
            ),
        )
        locator_sha = store.publish_locator(
            state=locator_state,
            intent_sha256=intent_sha256,
            journal_head_sha256=journal_head,
            previous_locator_sha256=previous_locator_sha256,
        )
        return journal_head, locator_sha

    try:
        journal_head, locator_sha = with_store(append)
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        ) from None
    control["journal_head_sha256"] = journal_head
    control["locator_sha256"] = locator_sha
    control["recovery_phase"] = locator_state
    control["recovery_evidence_sha256"] = evidence_sha256


def _project_update_activate_legacy_recovery_state(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> None:
    """Atomically hand the public lock from the immutable old tx to fresh."""

    control = getattr(state, "legacy_prewrite_recovery_control", None)
    if not isinstance(control, dict):
        return
    paths = control.get("paths")
    old_lock_bytes = control.get("old_lock_bytes")
    if (
        not isinstance(paths, project_update_legacy_recovery.RecoveryPaths)
        or type(old_lock_bytes) is not bytes
        or not old_lock_bytes
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    lock_path = paths.project_root.joinpath(
        *PurePosixPath(project_update_legacy_recovery.LOCK_LOGICAL).parts
    )
    fresh_lock_bytes = state.expected_lock_bytes
    replacement = lock_path.parent / (
        ".legacy-recovery-"
        + paths.recovery_ref.removeprefix("recovery_")
        + ".fresh-lock"
    )
    backup = lock_path.parent / (
        ".legacy-recovery-"
        + paths.recovery_ref.removeprefix("recovery_")
        + ".old-lock"
    )
    try:
        replacement, backup = (
            project_update_legacy_recovery.prepare_lock_handoff_files(
                paths, fresh_lock_bytes=fresh_lock_bytes
            )
        )
        handoff_state = project_update_legacy_recovery.classify_lock_handoff(
            paths,
            old_lock_bytes,
            fresh_lock_bytes,
        )
        if handoff_state in {"old", "backup_linked"}:
            project_update_legacy_recovery.atomic_replace_lock_with_backup_windows(
                lock_path,
                replacement,
                backup,
                expected_old_bytes=old_lock_bytes,
                expected_fresh_bytes=fresh_lock_bytes,
            )
        elif handoff_state != "fresh":
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_lock_ambiguous"
            )
        if (
            project_update_legacy_recovery.classify_lock_handoff(
                paths,
                old_lock_bytes,
                fresh_lock_bytes,
            )
            != "fresh"
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_lock_ambiguous"
            )
        project_update_transaction._require_directory_durable(lock_path.parent)
        reserved = project_update_transaction.ReservedProjectUpdateTransaction.open(
            state.project_root,
            state.transaction.transaction_ref,
        )
        observed = reserved.acquire_lock()
        if not hmac.compare_digest(observed, fresh_lock_bytes):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_lock_ambiguous"
            )
        state.transaction.bind_sealed_intent_to_lock(fresh_lock_bytes)
        journal = state.transaction.inspect().journal
        if not journal.verified_prefix:
            state.transaction.append(
                phase="lock_backlinked",
                stage="verified",
                live_component_sha256=_project_update_live_component_sha256(state),
            )
        elif journal.verified_prefix[-1].phase != "lock_backlinked":
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
        _project_update_legacy_recovery_checkpoint(
            state,
            phase="fresh_lock_backlinked",
            evidence_sha256=project_update_transaction.sha256_document(
                {
                    "fresh_intent_sha256": state.transaction.intent.sha256,
                    "fresh_lock_sha256": project_update_transaction.sha256_bytes(
                        fresh_lock_bytes
                    ),
                    "old_lock_backup_sha256": project_update_transaction.sha256_bytes(
                        old_lock_bytes
                    ),
                    "schema": (
                        "wom-kit/project-update-legacy-lock-handoff-evidence/"
                        "v0.4.19"
                    ),
                }
            ),
            locator_state="fresh_lock_backlinked",
        )
    except ArchiveServiceError:
        raise
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_lock_ambiguous"
        ) from None


def _project_update_publish_legacy_cancellation_handoff_exact(
    *,
    project_root: Path,
    expected_approval_root: Path,
    expected_archive_id: str,
    paths: project_update_legacy_recovery.RecoveryPaths,
    intent_sha256: str,
    terminal_receipt_sha256: str,
    cancellation_result_document_sha256: str,
    key_provider: Any,
) -> tuple[str, str]:
    """Publish and re-authenticate one cancellation capsule before retirement."""

    if (
        not isinstance(paths, project_update_legacy_recovery.RecoveryPaths)
        or type(intent_sha256) is not str
        or type(terminal_receipt_sha256) is not str
        or type(cancellation_result_document_sha256) is not str
        or not callable(getattr(key_provider, "use_key", None))
        or _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.get() is None
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    try:
        # Re-entering the terminal boundary does not take a second OS lease;
        # it verifies that the currently held lease belongs to this exact
        # project root and that its retained directory/guard identities have
        # not changed.  A non-empty ContextVar alone is not sufficient.
        with _project_update_terminal_control_boundary(project_root):
            pass
    except (OSError, RuntimeError, ValueError):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        ) from None
    expected_archive_identity_sha256 = (
        exact_human_approval_archive_identity_sha256(expected_archive_id)
    )

    def publish(key: memoryview) -> tuple[str, str]:
        with project_update_legacy_recovery.LegacyRecoveryStore(
            project_root,
            paths.recovery_ref,
            key,
        ) as store:
            result_record = store.read_cancellation_result()
            receipt = store.read_terminal_receipt()
            receipt_raw = project_update_legacy_recovery._read_regular(
                paths.recovery_root / "terminal-receipt.json"
            )
            if (
                result_record.get("cancellation_result_document_sha256")
                != cancellation_result_document_sha256
                or project_update_legacy_recovery.sha256_bytes(receipt_raw)
                != terminal_receipt_sha256
                or receipt.get("outcome") != "unapproved_restored"
                or receipt.get("intent_sha256") != intent_sha256
                or receipt.get("cancellation_result_document_sha256")
                != cancellation_result_document_sha256
                or receipt.get("cancellation_result_sha256")
                != result_record.get("cancellation_result_sha256")
            ):
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_state_ambiguous"
                )
        document, capability = _project_update_cancellation_terminal_document(
            recovery_ref=paths.recovery_ref,
            archive_identity_sha256=expected_archive_identity_sha256,
            intent_sha256=intent_sha256,
            terminal_receipt_sha256=terminal_receipt_sha256,
            cancellation_result_document_sha256=(
                cancellation_result_document_sha256
            ),
            key=key,
        )
        handoff, _guard = _project_update_terminal_handoff_paths(project_root)
        handoff_sha256 = _project_update_write_terminal_document_exact(
            project_root,
            handoff,
            document,
            expected_previous_value=None,
        )
        observed = _project_update_read_terminal_document(project_root, handoff)
        if observed is None or not hmac.compare_digest(
            project_update_transaction.sha256_bytes(observed[1]),
            handoff_sha256,
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        verified_result, verified_capability = (
            _project_update_verify_cancellation_terminal_document(
                observed[0],
                expected_archive_identity_sha256=(
                    expected_archive_identity_sha256
                ),
                key=key,
            )
        )
        if (
            not _project_update_is_legacy_unapproved_terminal_result(
                verified_result
            )
            or not hmac.compare_digest(capability, verified_capability)
        ):
            raise ArchiveServiceError(
                "project_version_update_terminal_handoff_invalid"
            )
        _project_update_register_terminal_delivery_capability(
            handoff_sha256,
            capability,
        )
        return handoff_sha256, capability

    try:
        return key_provider.use_key(
            expected_approval_root,
            publish,
            create_if_missing=False,
        )
    except ArchiveServiceError:
        raise
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        ) from None


def _project_update_publish_legacy_cancellation_handoff(
    state: _ProjectVersionUpdateDurableApprovalState,
    *,
    terminal_receipt_sha256: str,
    cancellation_result_document_sha256: str,
) -> tuple[str, str]:
    control = getattr(state, "legacy_prewrite_recovery_control", None)
    if (
        not isinstance(control, dict)
        # Native cancellation is observed while the fresh execution lease is
        # held, but Python exits that inner context before the exact restore
        # branch can publish its terminal capsule.  The archive-wide terminal
        # control lease remains held across both steps and the exact publisher
        # below independently requires it.  Requiring the now-ended fresh
        # execution owner here would make every valid denial fail only after
        # the predecessor had already been restored.
        or _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.get() is None
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    return _project_update_publish_legacy_cancellation_handoff_exact(
        project_root=state.project_root,
        expected_approval_root=state.expected_approval_root,
        expected_archive_id=state.expected_archive_id,
        paths=control.get("paths"),
        intent_sha256=control.get("intent_sha256"),
        terminal_receipt_sha256=terminal_receipt_sha256,
        cancellation_result_document_sha256=(
            cancellation_result_document_sha256
        ),
        key_provider=control.get("approval_key_provider"),
    )


def _project_update_restore_legacy_recovery_after_unapproved(
    state: _ProjectVersionUpdateDurableApprovalState,
) -> dict[str, Any]:
    """Restore exact predecessor state only after fresh-claim absence proof."""

    control = state.legacy_prewrite_recovery_control
    if not isinstance(control, dict):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    paths = control.get("paths")
    old_transaction_ref = control.get("old_transaction_ref")
    old_tree_sha256 = control.get("old_transaction_tree_sha256")
    old_lock_bytes = control.get("old_lock_bytes")
    fresh_inventory = control.get("fresh_transaction_inventory")
    fresh_inventory_document_sha256 = control.get(
        "fresh_transaction_inventory_document_sha256"
    )
    confirm = control.get("confirm_fresh_claim_absent")
    with_store = control.get("with_store")
    intent_sha256 = control.get("intent_sha256")
    old_abandonment_sha256 = control.get("old_abandonment_sha256")
    prospective_plan_document_sha256 = control.get(
        "fresh_prospective_plan_sha256"
    )
    if (
        not isinstance(paths, project_update_legacy_recovery.RecoveryPaths)
        or type(old_transaction_ref) is not str
        or type(old_tree_sha256) is not str
        or type(old_lock_bytes) is not bytes
        or not isinstance(fresh_inventory, Mapping)
        or type(fresh_inventory_document_sha256) is not str
        or not callable(confirm)
        or not callable(with_store)
        or type(intent_sha256) is not str
        or type(old_abandonment_sha256) is not str
        or type(prospective_plan_document_sha256) is not str
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    binding = project_version_update_approval_binding(state.prepared_preview)
    context = binding.context(
        archive_id=state.expected_archive_id,
        reviewer_claim=state.reviewer,
    )
    try:
        if not bool(confirm(context)):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
        claim_absence_evidence_sha256 = (
            project_update_transaction.sha256_document(
                {
                    "approval_context_sha256": (
                        exact_human_approval_context_sha256(context)
                    ),
                    "claim_state": "absent_authenticated",
                    "schema": (
                        "wom-kit/project-update-legacy-claim-absence/"
                        "v0.4.19"
                    ),
                }
            )
        )
        fresh_inventory_sha256 = (
            project_update_legacy_recovery.sha256_document(fresh_inventory)
        )
        cancellation_result = (
            project_update_legacy_recovery.cancellation_result_document()
        )
        cancellation_result_record = with_store(
            lambda store: store.write_cancellation_result(
                cancellation_result
            )
        )
        cancellation_plan = (
            project_update_legacy_recovery.cancellation_plan_document(
                recovery_ref=paths.recovery_ref,
                intent_sha256=intent_sha256,
                fresh_transaction_ref=state.transaction.transaction_ref,
                prospective_plan_document_sha256=(
                    prospective_plan_document_sha256
                ),
                fresh_approval_plan_sha256=binding.plan_sha256,
                fresh_approval_context_sha256=(
                    exact_human_approval_context_sha256(context)
                ),
                claim_absence_evidence_sha256=(
                    claim_absence_evidence_sha256
                ),
                old_transaction_ref=old_transaction_ref,
                old_transaction_sha256=old_tree_sha256,
                old_lock_sha256=(
                    project_update_transaction.sha256_bytes(old_lock_bytes)
                ),
                old_abandonment_sha256=old_abandonment_sha256,
                fresh_transaction_inventory_sha256=(
                    fresh_inventory_sha256
                ),
                fresh_transaction_inventory_document_sha256=(
                    fresh_inventory_document_sha256
                ),
                cancellation_result_sha256=(
                    cancellation_result_record[
                        "cancellation_result_sha256"
                    ]
                ),
                cancellation_result_document_sha256=(
                    cancellation_result_record[
                        "cancellation_result_document_sha256"
                    ]
                ),
            )
        )
        cancellation_plan_document_sha256 = with_store(
            lambda store: store.write_cancellation_plan(
                cancellation_plan
            )
        )
        staged = (
            project_update_legacy_recovery.stage_cancelled_fresh_transaction(
                paths,
                fresh_transaction_ref=state.transaction.transaction_ref,
                fresh_transaction_inventory=fresh_inventory,
            )
        )
        cancellation_stage_evidence = (
            project_update_legacy_recovery.cancellation_stage_evidence_document(
                recovery_ref=paths.recovery_ref,
                intent_sha256=intent_sha256,
                fresh_transaction_ref=state.transaction.transaction_ref,
                cancellation_plan_document_sha256=(
                    cancellation_plan_document_sha256
                ),
                claim_absence_evidence_sha256=(
                    claim_absence_evidence_sha256
                ),
                fresh_transaction_inventory_sha256=(
                    fresh_inventory_sha256
                ),
                fresh_transaction_inventory_document_sha256=(
                    fresh_inventory_document_sha256
                ),
                stage_state=staged,
            )
        )
        cancelled_fresh_staging_sha256 = (
            project_update_transaction.sha256_document(
                cancellation_stage_evidence
            )
        )
        cancelled_fresh_staging_document_sha256 = with_store(
            lambda store: store.write_cancellation_stage_evidence(
                cancellation_stage_evidence
            )
        )
        _project_update_legacy_recovery_checkpoint(
            state,
            phase="cancelled_fresh_staged",
            evidence_sha256=(
                cancelled_fresh_staging_document_sha256
            ),
            locator_state="cancelled_fresh_staged",
        )
        deleted = (
            project_update_legacy_recovery.delete_cancelled_fresh_transaction(
                paths,
                fresh_transaction_inventory=fresh_inventory,
            )
        )
        cancellation_cleanup_evidence = (
            project_update_legacy_recovery.cancellation_cleanup_evidence_document(
                recovery_ref=paths.recovery_ref,
                intent_sha256=intent_sha256,
                fresh_transaction_ref=state.transaction.transaction_ref,
                cancellation_plan_document_sha256=(
                    cancellation_plan_document_sha256
                ),
                cancellation_stage_evidence_document_sha256=(
                    cancelled_fresh_staging_document_sha256
                ),
                fresh_transaction_inventory_sha256=(
                    fresh_inventory_sha256
                ),
                fresh_transaction_inventory_document_sha256=(
                    fresh_inventory_document_sha256
                ),
                cleanup_state=deleted,
            )
        )
        cancelled_fresh_cleanup_evidence_sha256 = (
            project_update_transaction.sha256_document(
                cancellation_cleanup_evidence
            )
        )
        cancelled_fresh_cleanup_evidence_document_sha256 = with_store(
            lambda store: store.write_cancellation_cleanup_evidence(
                cancellation_cleanup_evidence
            )
        )
        _project_update_legacy_recovery_checkpoint(
            state,
            phase="cancelled_fresh_cleaned",
            evidence_sha256=(
                cancelled_fresh_cleanup_evidence_document_sha256
            ),
            locator_state="cancelled_fresh_cleaned",
        )
        restored = project_update_legacy_recovery.restore_old_transaction(
            paths,
            old_transaction_ref=old_transaction_ref,
            expected_tree_sha256=old_tree_sha256,
        )
        live_lock = paths.project_root.joinpath(
            *PurePosixPath(project_update_legacy_recovery.LOCK_LOGICAL).parts
        )
        if not hmac.compare_digest(
            project_update_legacy_recovery._read_regular(live_lock),
            old_lock_bytes,
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_changed"
            )
        cancellation_restore_evidence = (
            project_update_legacy_recovery.cancellation_restore_evidence_document(
                recovery_ref=paths.recovery_ref,
                intent_sha256=intent_sha256,
                fresh_transaction_ref=state.transaction.transaction_ref,
                cancellation_plan_document_sha256=(
                    cancellation_plan_document_sha256
                ),
                cancellation_cleanup_evidence_document_sha256=(
                    cancelled_fresh_cleanup_evidence_document_sha256
                ),
                old_transaction_ref=old_transaction_ref,
                old_transaction_sha256=old_tree_sha256,
                old_lock_sha256=(
                    project_update_transaction.sha256_bytes(old_lock_bytes)
                ),
                restore_state=restored,
            )
        )
        restored_evidence_sha256 = (
            project_update_transaction.sha256_document(
                cancellation_restore_evidence
            )
        )
        restored_evidence_document_sha256 = with_store(
            lambda store: store.write_cancellation_restore_evidence(
                cancellation_restore_evidence
            )
        )
        _project_update_legacy_recovery_checkpoint(
            state,
            phase="unapproved_restored",
            evidence_sha256=restored_evidence_document_sha256,
            locator_state="unapproved_restored",
        )
        journal_head_sha256 = control.get("journal_head_sha256")
        locator_sha256 = control.get("locator_sha256")
        if type(journal_head_sha256) is not str or type(locator_sha256) is not str:
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_binding_invalid"
            )
        receipt = project_update_legacy_recovery.terminal_receipt_document(
            recovery_ref=paths.recovery_ref,
            outcome="unapproved_restored",
            intent_sha256=intent_sha256,
            journal_head_sha256=journal_head_sha256,
            fresh_transaction_ref=state.transaction.transaction_ref,
            old_transaction_inventory_sha256=old_tree_sha256,
            claim_absence_evidence_sha256=claim_absence_evidence_sha256,
            cancelled_fresh_staging_sha256=(
                cancelled_fresh_staging_sha256
            ),
            cancelled_fresh_transaction_inventory_sha256=(
                fresh_inventory_sha256
            ),
            cancelled_fresh_transaction_inventory_document_sha256=(
                fresh_inventory_document_sha256
            ),
            cancelled_fresh_cleanup_evidence_sha256=(
                cancelled_fresh_cleanup_evidence_sha256
            ),
            restored_old_transaction_sha256=old_tree_sha256,
            preserved_old_lock_sha256=(
                project_update_transaction.sha256_bytes(old_lock_bytes)
            ),
            cancellation_plan_document_sha256=(
                cancellation_plan_document_sha256
            ),
            cancellation_result_document_sha256=(
                cancellation_result_record[
                    "cancellation_result_document_sha256"
                ]
            ),
            cancellation_result_sha256=(
                cancellation_result_record[
                    "cancellation_result_sha256"
                ]
            ),
            cancelled_fresh_staging_document_sha256=(
                cancelled_fresh_staging_document_sha256
            ),
            cancelled_fresh_cleanup_evidence_document_sha256=(
                cancelled_fresh_cleanup_evidence_document_sha256
            ),
            restored_evidence_sha256=restored_evidence_sha256,
            restored_evidence_document_sha256=(
                restored_evidence_document_sha256
            ),
        )
        receipt_sha256 = with_store(
            lambda store: store.write_terminal_receipt(receipt)
        )
        handoff_sha256, _capability = (
            _project_update_publish_legacy_cancellation_handoff(
                state,
                terminal_receipt_sha256=receipt_sha256,
                cancellation_result_document_sha256=(
                    cancellation_result_record[
                        "cancellation_result_document_sha256"
                    ]
                ),
            )
        )
        with_store(
            lambda store: store.publish_terminal_locator_and_retire(
                intent_sha256=intent_sha256,
                journal_head_sha256=journal_head_sha256,
                previous_locator_sha256=locator_sha256,
                terminal_receipt_sha256=receipt_sha256,
            )
        )
        control["recovery_phase"] = "terminal_completed"
        control["terminal_receipt_sha256"] = receipt_sha256
        control["terminal_handoff_sha256"] = handoff_sha256
        return cancellation_result
    except ArchiveServiceError:
        raise
    except BaseException:
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        ) from None


def _project_update_confirm_context_claim_absent(
    *,
    expected_approval_root: Path,
    context: ExactHumanApprovalContext,
    key_provider: Any,
    resume_boundary: Callable[[], Any],
) -> bool:
    """Re-authenticate exact claim absence without exposing claim names."""

    if (
        type(context) is not ExactHumanApprovalContext
        or not callable(getattr(key_provider, "use_key", None))
        or not callable(resume_boundary)
    ):
        return False
    try:
        with resume_boundary() as filesystem_boundary:
            if (
                not isinstance(filesystem_boundary, tuple)
                or len(filesystem_boundary) != 2
            ):
                return False
            bound_archive_root, claim_parent_binding = filesystem_boundary
            claims_root = bound_archive_root.joinpath(
                *Path(CLAIMS_RELATIVE_ROOT).parts
            )
            if (
                bound_archive_root != expected_approval_root
                or not isinstance(claim_parent_binding, Mapping)
                or claim_parent_binding.get("path") != claims_root
            ):
                return False

            def consume(key: memoryview) -> bool:
                directory_target = claim_parent_binding.get("descriptor")
                if type(directory_target) is not int:
                    directory_target = claim_parent_binding.get("path")
                names = os.listdir(directory_target)
                if len(names) > 100_000:
                    return False
                expected_context_sha256 = exact_human_approval_context_sha256(
                    context
                )
                for name in names:
                    match = re.fullmatch(
                        r"(approval_[0-9a-f]{32})\.json", str(name)
                    )
                    if match is None:
                        continue
                    routed_context, _status = _authenticated_claim_routing_core(
                        bound_archive_root,
                        match.group(1),
                        key,
                        bound_archive_root=bound_archive_root,
                        claim_parent_binding=claim_parent_binding,
                    )
                    if hmac.compare_digest(
                        routed_context,
                        expected_context_sha256,
                    ):
                        return False
                return True

            result = key_provider.use_key(
                expected_approval_root,
                consume,
                create_if_missing=False,
            )
            return type(result) is bool and result
    except BaseException:
        return False


class _ProjectUpdateBorrowedApprovalKeyProvider:
    """Keep the already-authenticated predecessor key inside one handoff.

    The selected-claim handler receives this memoryview only while the
    non-creating claim-directory boundary is held.  The fresh approval uses
    the same archive-local key without creating, exporting, or serializing it.
    """

    def __init__(self, archive_root: Path, key: memoryview) -> None:
        self._archive_root = archive_root
        self._key = key

    def use_key(
        self,
        archive_root: Path | str,
        consumer: Callable[[memoryview], Any],
        *,
        create_if_missing: bool = False,
    ) -> Any:
        try:
            current = require_existing_archive_root(archive_root)
        except BaseException:
            raise ExactHumanApprovalError(
                "exact_human_approval_key_unavailable"
            ) from None
        if (
            current != self._archive_root
            or not callable(consumer)
            or type(create_if_missing) is not bool
            or len(self._key) != 32
        ):
            raise ExactHumanApprovalError(
                "exact_human_approval_key_unavailable"
            )
        return consumer(self._key)


def _project_update_resume_legacy_approval_bound_prewrite(
    state: _ProjectVersionUpdateDurableApprovalState,
    *,
    lifetime: _ProjectVersionUpdateGitRunnerLifetime,
    approval_executor: Callable[..., Mapping[str, Any]],
    progress_callback: (
        Callable[[str, str, int | None, int | None], None] | None
    ),
    key_provider: Any | None,
    resume_boundary: Callable[[], Any] | None,
) -> dict[str, Any] | None:
    """Replace one exact v0.4.15 approval-bound prewrite transaction.

    Discovery authenticates the existing claim and validates its old
    checkpoint while the claim-directory boundary is still held.  The old
    claim is never resumed or finalized.  Its selected handler only creates
    the authenticated recovery control plane, moves the byte-identical old
    transaction to its vault, and synchronously starts one current-schema
    transaction with one fresh native approval.
    """

    transaction = getattr(state, "transaction", None)
    if not isinstance(
        transaction,
        project_update_transaction.ProjectUpdateTransaction,
    ):
        # This compatibility entrypoint is also exercised by narrow service
        # tests whose already-finalized state intentionally omits transaction
        # internals.  Such a state cannot be an authenticated v0.4.15
        # predecessor and must stay on the ordinary resume path.
        return None
    inspection = transaction.inspect()
    checkpoints = tuple(inspection.journal.verified_prefix)
    phases = tuple(item.phase for item in checkpoints)
    state_target_tag = getattr(state, "target_tag", None)
    if state_target_tag is None:
        state_target_tag = getattr(
            getattr(transaction, "reservation", None),
            "requested_target_tag",
            None,
        )
    legacy_candidate = bool(
        state_target_tag == "v0.4.15"
        and transaction.intent.runtime_candidate.legacy_document_shape
    )
    eligible = bool(
        legacy_candidate
        and inspection.journal.state == "exact"
        and inspection.lock_backlinked
        and len(checkpoints) == 2
        and phases == ("lock_backlinked", "approval_bound")
        and all(item.stage == "verified" for item in checkpoints)
        and getattr(state, "existing_cleanup_authority_sha256", None) is None
    )
    if not legacy_candidate:
        return None
    if not eligible or key_provider is None or not callable(resume_boundary):
        _project_update_close_after_service_failure(
            state.directory_guard.close,
            lifetime,
        )
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_ambiguous"
        )

    old_live = _project_update_live_component_sha256(state)
    if transaction.classify_live_components(old_live).overall != "prewrite_exact":
        _project_update_close_after_service_failure(
            state.directory_guard.close,
            lifetime,
        )
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_changed"
        )
    old_binding = project_version_update_approval_binding(
        state.prepared_preview
    )
    state.approved_plan_sha256 = old_binding.plan_sha256
    state.approved_target_binding_sha256 = (
        old_binding.target_binding_sha256
    )
    old_context = old_binding.context(
        archive_id=state.expected_archive_id,
        reviewer_claim=state.reviewer,
    )

    def started_guard(claim: _ClaimedExactHumanApproval) -> bool:
        return _project_update_claim_checkpoint_guard(
            state,
            claim,
            succeeded=False,
        )

    def succeeded_guard(_claim: _ClaimedExactHumanApproval) -> bool:
        # An already-succeeded predecessor is a different terminal-recovery
        # family.  This transition is exclusively for the started prewrite.
        return False

    def selected_handler(
        approval_id: str,
        key: memoryview,
        filesystem_boundary: tuple[Path, dict[str, Any]] | None,
    ) -> Mapping[str, Any]:
        if filesystem_boundary is None:
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
        bound_archive_root, claim_parent_binding = filesystem_boundary
        claims_root = bound_archive_root.joinpath(
            *Path(CLAIMS_RELATIVE_ROOT).parts
        )
        if (
            bound_archive_root != state.expected_approval_root
            or claim_parent_binding.get("path") != claims_root
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
        claim_raw = _read_claim_bytes(
            claims_root / f"{approval_id}.json",
            bound_archive_root=bound_archive_root,
            claim_parent_binding=claim_parent_binding,
        )
        old_claim_sha256 = project_update_transaction.sha256_bytes(
            claim_raw
        )
        old_lock_bytes = state.expected_lock_bytes
        if not hmac.compare_digest(
            project_update_legacy_recovery._read_regular(
                state.transaction._lock_path
            ),
            old_lock_bytes,
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_changed"
            )
        if progress_callback is not None:
            try:
                progress_callback(
                    "project-recovery-inventory", "running", 0, 0
                )
            except Exception:
                pass
        old_inventory = project_update_legacy_recovery.directory_tree_inventory(
            state.transaction.transaction_root,
            progress_callback=(
                (
                    lambda count, byte_count: progress_callback(
                        "project-recovery-inventory",
                        "running",
                        count,
                        byte_count,
                    )
                )
                if progress_callback is not None
                else None
            ),
        )
        old_tree_sha256 = project_update_legacy_recovery.sha256_document(
            old_inventory
        )
        live_sha256 = project_update_transaction.sha256_document(old_live)
        abandonment_sha256 = project_update_transaction.sha256_document(
            {
                "old_claim_sha256": old_claim_sha256,
                "old_intent_sha256": state.transaction.intent.sha256,
                "old_live_components_sha256": live_sha256,
                "old_lock_sha256": (
                    project_update_transaction.sha256_bytes(old_lock_bytes)
                ),
                "old_transaction_sha256": old_tree_sha256,
                "schema": (
                    "wom-kit/project-update-legacy-abandonment/"
                    "v0.4.19"
                ),
            }
        )
        prospective_sha256 = project_update_transaction.sha256_document(
            {
                "old_abandonment_sha256": abandonment_sha256,
                "schema": (
                    "wom-kit/project-update-legacy-prospective-seed/"
                    "v0.4.19"
                ),
                "target_tag": f"v{WOM_KIT_VERSION}",
            }
        )
        recovery_summary = {
            "schema": (
                "wom-kit/project-update-legacy-prewrite-approval/"
                "v0.4.19"
            ),
            "old_abandonment_sha256": abandonment_sha256,
            "prospective_fresh_plan_sha256": prospective_sha256,
            "single_composite_approval": True,
            "old_claim_reused": False,
            "old_transaction_mutated": False,
        }
        recovery_ref = project_update_legacy_recovery.new_recovery_ref()
        paths = project_update_legacy_recovery.RecoveryPaths.build(
            state.project_root,
            recovery_ref,
        )

        def with_store(action: Callable[[Any], Any]) -> Any:
            with project_update_legacy_recovery.LegacyRecoveryStore(
                state.project_root,
                recovery_ref,
                key,
            ) as store:
                return action(store)

        fresh_approval_seed = (
            project_update_legacy_recovery.fresh_approval_seed_document(
                recovery_ref=recovery_ref,
                reviewer=state.reviewer,
                old_transaction_ref=state.transaction.transaction_ref,
                old_transaction_sha256=old_tree_sha256,
                archive_identity_sha256=(
                    exact_human_approval_archive_identity_sha256(
                        state.expected_archive_id
                    )
                ),
                project_identity_sha256=(
                    state.transaction.intent.project_identity_sha256
                ),
                requested_target_tag=f"v{WOM_KIT_VERSION}",
            )
        )
        fresh_approval_seed_document_sha256 = with_store(
            lambda store: store.write_fresh_approval_seed(
                fresh_approval_seed
            )
        )
        recovery_intent = (
            project_update_legacy_recovery.recovery_intent_document(
                recovery_ref=recovery_ref,
                old_transaction_ref=state.transaction.transaction_ref,
                old_transaction_sha256=old_tree_sha256,
                old_claim_sha256=old_claim_sha256,
                old_lock_sha256=(
                    project_update_transaction.sha256_bytes(old_lock_bytes)
                ),
                old_live_components_sha256=live_sha256,
                archive_identity_sha256=(
                    exact_human_approval_archive_identity_sha256(
                        state.expected_archive_id
                    )
                ),
                project_identity_sha256=(
                    state.transaction.intent.project_identity_sha256
                ),
                fresh_approval_seed_document_sha256=(
                    fresh_approval_seed_document_sha256
                ),
            )
        )

        def publish_checkpoint(
            *,
            phase: str,
            evidence_sha256: str,
            locator_state: str,
            intent_sha256: str,
            previous_locator_sha256: str,
            previous_checkpoint_sha256: str | None,
        ) -> tuple[str, str]:
            def append(store: Any) -> tuple[str, str]:
                head = store.append_checkpoint(
                    phase=phase,
                    stage="verified",
                    intent_sha256=intent_sha256,
                    evidence_sha256=evidence_sha256,
                    expected_previous_checkpoint_sha256=(
                        previous_checkpoint_sha256
                    ),
                )
                locator = store.publish_locator(
                    state=locator_state,
                    intent_sha256=intent_sha256,
                    journal_head_sha256=head,
                    previous_locator_sha256=previous_locator_sha256,
                )
                return head, locator

            return with_store(append)

        intent_sha256 = with_store(
            lambda store: store.initialize(recovery_intent)
        )
        locator_sha256 = project_update_legacy_recovery.sha256_bytes(
            project_update_legacy_recovery._read_regular(
                paths.locator_path
            )
        )
        journal_head_sha256, locator_sha256 = publish_checkpoint(
            phase="legacy_eligibility_verified",
            evidence_sha256=abandonment_sha256,
            locator_state="legacy_eligible",
            intent_sha256=intent_sha256,
            previous_locator_sha256=locator_sha256,
            previous_checkpoint_sha256=None,
        )
        staged = project_update_legacy_recovery.stage_old_transaction(
            paths,
            old_transaction_ref=state.transaction.transaction_ref,
            expected_tree_sha256=old_tree_sha256,
        )
        journal_head_sha256, locator_sha256 = publish_checkpoint(
            phase="old_transaction_staged",
            evidence_sha256=project_update_transaction.sha256_document(
                {
                    "old_transaction_sha256": old_tree_sha256,
                    "schema": (
                        "wom-kit/project-update-legacy-stage-evidence/"
                        "v0.4.19"
                    ),
                    "state": staged,
                }
            ),
            locator_state="old_transaction_staged",
            intent_sha256=intent_sha256,
            previous_locator_sha256=locator_sha256,
            previous_checkpoint_sha256=journal_head_sha256,
        )

        # Authenticate the exact fresh ref before reserve() can publish its
        # directory.  Recovery never guesses ownership by enumerating the
        # transaction namespace after a crash in the reserve/callback gap.
        fresh_transaction_ref = "update_" + secrets.token_hex(16)
        fresh_reservation_created_at = (
            datetime.now(timezone.utc)
            .replace(microsecond=0)
            .isoformat()
            .replace("+00:00", "Z")
        )
        fresh_reservation_nonce = secrets.token_hex(16)
        prepared_fresh_reservation = (
            project_update_transaction.ProjectUpdateTransaction.prepare_reservation(
                project_identity_sha256=(
                    state.transaction.intent.project_identity_sha256
                ),
                requested_target_tag=f"v{WOM_KIT_VERSION}",
                transaction_ref=fresh_transaction_ref,
                ownership_nonce=fresh_reservation_nonce,
                created_at=fresh_reservation_created_at,
            )
        )
        pre_fetch_ref_snapshot = (
            _wom_kit_project_update_pre_fetch_ref_snapshot_observation(
                state.mirror_path,
                f"v{WOM_KIT_VERSION}",
                runner=state.runner,
            )
        )
        pre_fetch_snapshot_value = pre_fetch_ref_snapshot.get("snapshot")
        if (
            pre_fetch_ref_snapshot.get("state") != "passed"
            or pre_fetch_ref_snapshot.get("reason_code") != "verified"
            or not isinstance(pre_fetch_snapshot_value, Mapping)
            or set(pre_fetch_snapshot_value)
            != {
                "refs",
                "requested_target_present",
                "requested_target_ref",
            }
            or not isinstance(pre_fetch_snapshot_value.get("refs"), Mapping)
            or type(
                pre_fetch_snapshot_value.get("requested_target_present")
            )
            is not bool
            or pre_fetch_snapshot_value.get("requested_target_ref")
            != f"refs/tags/v{WOM_KIT_VERSION}"
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
        pre_fetch_ref_record = with_store(
            lambda store: store.write_pre_fetch_ref_snapshot(
                pre_fetch_ref_snapshot
            )
        )
        fresh_allocation = (
            project_update_legacy_recovery.fresh_allocation_document(
                recovery_ref=paths.recovery_ref,
                prepared_reservation_document=(
                    prepared_fresh_reservation.document()
                ),
                old_abandonment_sha256=abandonment_sha256,
                pre_ref_snapshot_document_sha256=(
                    pre_fetch_ref_record[
                        "pre_ref_snapshot_document_sha256"
                    ]
                ),
                pre_ref_snapshot_sha256=(
                    pre_fetch_ref_record["pre_ref_snapshot_sha256"]
                ),
            )
        )

        def persist_fresh_allocation(store: Any) -> tuple[str, str, str]:
            allocation_sha256 = store.write_fresh_allocation(
                fresh_allocation
            )
            head = store.append_checkpoint(
                phase="fresh_transaction_allocated",
                stage="verified",
                intent_sha256=intent_sha256,
                evidence_sha256=allocation_sha256,
                expected_previous_checkpoint_sha256=journal_head_sha256,
            )
            locator = store.publish_locator(
                state="fresh_transaction_allocated",
                intent_sha256=intent_sha256,
                journal_head_sha256=head,
                previous_locator_sha256=locator_sha256,
            )
            return allocation_sha256, head, locator

        (
            fresh_allocation_sha256,
            journal_head_sha256,
            locator_sha256,
        ) = with_store(persist_fresh_allocation)

        expected_fresh_context: list[ExactHumanApprovalContext] = []

        def confirm_fresh_claim_absent(
            context: ExactHumanApprovalContext,
        ) -> bool:
            if type(context) is not ExactHumanApprovalContext:
                return False
            expected_fresh_context[:] = [context]
            try:
                directory_target = claim_parent_binding.get("descriptor")
                if type(directory_target) is not int:
                    directory_target = claim_parent_binding.get("path")
                names = os.listdir(directory_target)
                if len(names) > 100_000:
                    return False
                expected_context_sha256 = (
                    exact_human_approval_context_sha256(context)
                )
                for name in names:
                    match = re.fullmatch(
                        r"(approval_[0-9a-f]{32})\.json", str(name)
                    )
                    if match is None:
                        continue
                    routed_context, _status = (
                        _authenticated_claim_routing_core(
                            bound_archive_root,
                            match.group(1),
                            key,
                            bound_archive_root=bound_archive_root,
                            claim_parent_binding=claim_parent_binding,
                        )
                    )
                    if hmac.compare_digest(
                        routed_context,
                        expected_context_sha256,
                    ):
                        return False
                return True
            except BaseException:
                return False

        control: dict[str, Any] = {
            "paths": paths,
            "old_transaction_ref": state.transaction.transaction_ref,
            "old_transaction_tree_sha256": old_tree_sha256,
            "old_lock_bytes": old_lock_bytes,
            "old_abandonment_sha256": abandonment_sha256,
            "intent_sha256": intent_sha256,
            "journal_head_sha256": journal_head_sha256,
            "locator_sha256": locator_sha256,
            "recovery_phase": "fresh_transaction_allocated",
            "with_store": with_store,
            "confirm_fresh_claim_absent": confirm_fresh_claim_absent,
            "progress_callback": progress_callback,
            "approval_key_provider": (
                _ProjectUpdateBorrowedApprovalKeyProvider(
                    bound_archive_root,
                    key,
                )
            ),
            "fresh_transaction_ref": fresh_transaction_ref,
            "prepared_fresh_reservation": prepared_fresh_reservation,
            "fresh_allocation_sha256": fresh_allocation_sha256,
            "pre_ref_snapshot_document_sha256": (
                pre_fetch_ref_record[
                    "pre_ref_snapshot_document_sha256"
                ]
            ),
            "pre_ref_snapshot_sha256": (
                pre_fetch_ref_record["pre_ref_snapshot_sha256"]
            ),
            "recovery_evidence_sha256": fresh_allocation_sha256,
        }

        def bind_fresh_reservation(
            reservation: (
                project_update_transaction.ReservedProjectUpdateTransaction
            ),
        ) -> None:
            if not isinstance(
                reservation,
                project_update_transaction.ReservedProjectUpdateTransaction,
            ):
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_binding_invalid"
                )
            if reservation.transaction_ref != fresh_transaction_ref:
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_binding_invalid"
                )
            document = (
                project_update_legacy_recovery.fresh_reservation_document(
                    recovery_ref=paths.recovery_ref,
                    fresh_transaction_ref=reservation.transaction_ref,
                    fresh_reservation_sha256=(
                        reservation.reservation.sha256
                    ),
                    fresh_allocation_document_sha256=(
                        fresh_allocation_sha256
                    ),
                    old_abandonment_sha256=abandonment_sha256,
                )
            )

            def persist(store: Any) -> tuple[str, str, str]:
                reservation_sha256 = store.write_fresh_reservation(
                    document
                )
                head = store.append_checkpoint(
                    phase="fresh_reservation_bound",
                    stage="verified",
                    intent_sha256=intent_sha256,
                    evidence_sha256=reservation_sha256,
                    expected_previous_checkpoint_sha256=(
                        control["journal_head_sha256"]
                    ),
                )
                locator = store.publish_locator(
                    state="fresh_reservation_bound",
                    intent_sha256=intent_sha256,
                    journal_head_sha256=head,
                    previous_locator_sha256=control["locator_sha256"],
                )
                return reservation_sha256, head, locator

            reservation_sha256, head, locator = with_store(persist)
            control["fresh_reservation_sha256"] = reservation_sha256
            control["journal_head_sha256"] = head
            control["locator_sha256"] = locator
            control["recovery_phase"] = "fresh_reservation_bound"
            control["recovery_evidence_sha256"] = reservation_sha256

        control["fresh_reservation_callback"] = bind_fresh_reservation
        try:
            return _wom_kit_project_version_update_legacy_core(
                state.inspection_root,
                target=f"v{WOM_KIT_VERSION}",
                dry_run=False,
                approve=True,
                reviewed_by=state.reviewer,
                affirm_external_writers_quiescent=True,
                approval_executor=approval_executor,
                progress_callback=progress_callback,
                _expected_approval_root=state.expected_approval_root,
                _expected_archive_id=state.expected_archive_id,
                _legacy_recovery_old_lock_bytes=old_lock_bytes,
                _legacy_recovery_approval_summary=recovery_summary,
                _legacy_recovery_control=control,
            )
        except BaseException:
            raise

    try:
        from .exact_human_approval_workflow import (
            _discover_exact_human_approved_transaction_resume_core,
        )

        with (
            _project_update_terminal_execution_lease(
                state,
                expected_handoff_observation=None,
                fresh_absence=False,
            ),
            project_update_legacy_recovery.legacy_recovery_process_guard(
                state.project_root,
                terminal_control_lease_held=lambda: (
                    _PROJECT_UPDATE_TERMINAL_CONTROL_LEASE.get() is not None
                ),
            ),
        ):
            result = _discover_exact_human_approved_transaction_resume_core(
                state.expected_approval_root,
                old_context,
                started_guard,
                succeeded_guard,
                _selected_candidate_handler=selected_handler,
                key_provider=key_provider,
                resume_boundary=resume_boundary,
            )
        if not isinstance(result, Mapping):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
        return _project_update_finish_nonterminal_service_result(
            result,
            lifetime,
            close_owned_resources=state.directory_guard.close,
        )
    except project_update_legacy_recovery.LegacyProjectUpdateRecoveryError as failure:
        _project_update_close_after_service_failure(
            state.directory_guard.close,
            lifetime,
        )
        raise ArchiveServiceError(failure.code) from None
    except BaseException:
        _project_update_close_after_service_failure(
            state.directory_guard.close,
            lifetime,
        )
        raise


def _project_update_reopen_durable_state(
    inspection_root: Path | str,
    *,
    target: str | None,
    reviewed_by: str | None,
    transaction_ref: str | None,
    expected_approval_root: Path,
    expected_archive_id: str,
    _authenticated_recovery_transaction_ref: str | None = None,
    _legacy_recovery_control: Mapping[str, Any] | None = None,
) -> tuple[
    _ProjectVersionUpdateDurableApprovalState,
    _ProjectVersionUpdateGitRunnerLifetime,
]:
    """Reopen only an intent-bound update; never refetch or redisplay native."""

    inspection = Path(
        os.path.abspath(str(Path(inspection_root).expanduser()))
    )
    project_root = (
        inspection.parent
        if (
            wom_kit_real_path_kind(
                inspection, inspection / ".zettel-kasten"
            )
            == "missing"
            and wom_kit_real_path_kind(
                inspection, inspection / "archive.yml"
            )
            == "file"
            and wom_kit_real_path_kind(
                inspection.parent,
                inspection.parent / ".zettel-kasten",
            )
            == "directory"
        )
        else inspection
    )
    if not _wom_kit_project_version_update_approval_authority_matches(
        inspection,
        expected_root=expected_approval_root,
        expected_archive_id=expected_archive_id,
    ):
        raise ArchiveServiceError(
            "project_version_update_approval_archive_identity_changed"
        )
    supplied_transaction_ref = str(transaction_ref or "").strip()
    if _authenticated_recovery_transaction_ref is None:
        discovered_transaction_ref = (
            project_update_transaction
            .active_transaction_ref_for_resume_read_only(project_root)
        )
    else:
        discovered_transaction_ref = str(
            _authenticated_recovery_transaction_ref
        )
        if (
            project_update_transaction.TRANSACTION_REF_RE.fullmatch(
                discovered_transaction_ref
            )
            is None
            or not isinstance(_legacy_recovery_control, Mapping)
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_binding_invalid"
            )
    if (
        supplied_transaction_ref
        and supplied_transaction_ref != discovered_transaction_ref
    ):
        raise ArchiveServiceError(
            "project_version_update_resume_binding_mismatch"
        )
    transaction_ref = discovered_transaction_ref
    transaction = project_update_transaction.ProjectUpdateTransaction.open(
        project_root,
        transaction_ref,
    )
    existing_cleanup_authority_sha256 = (
        transaction.cleanup_authority_sha256_read_only()
        if isinstance(
            transaction,
            project_update_transaction.ProjectUpdateTransaction,
        )
        else None
    )
    if (
        existing_cleanup_authority_sha256 is not None
        and re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            str(existing_cleanup_authority_sha256),
        )
        is None
    ):
        raise ArchiveServiceError(
            "project_version_update_terminal_cleanup_authority_invalid"
        )
    target_tag = transaction.intent.requested_target_tag
    supplied_target = str(target or "").strip()
    if supplied_target and supplied_target != target_tag:
        raise ArchiveServiceError(
            "project_version_update_resume_target_mismatch"
        )
    private_plan = _project_update_parse_private_plan(
        transaction.private_binding_bytes("project-update-domain-plan")
    )
    if _authenticated_recovery_transaction_ref is not None:
        recovery_summary = private_plan.get("legacy_prewrite_recovery")
        expected_recovery_binding_sha256 = (
            _legacy_recovery_control.get(
                "fresh_recovery_binding_sha256"
            )
            if isinstance(_legacy_recovery_control, Mapping)
            else None
        )
        if (
            not isinstance(recovery_summary, Mapping)
            or type(expected_recovery_binding_sha256) is not str
            or re.fullmatch(
                r"sha256:[0-9a-f]{64}",
                expected_recovery_binding_sha256,
            )
            is None
            or not hmac.compare_digest(
                project_update_transaction.sha256_document(
                    dict(recovery_summary)
                ),
                expected_recovery_binding_sha256,
            )
            or not hmac.compare_digest(
                transaction.private_binding_bytes(
                    "legacy-prewrite-recovery-binding"
                ),
                (expected_recovery_binding_sha256 + "\n").encode(
                    "ascii"
                ),
            )
        ):
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_binding_invalid"
            )
    reviewer = safe_foreign_quarantine_actor_id(private_plan.get("reviewer"))
    supplied_reviewer = str(reviewed_by or "").strip()
    if (
        reviewer is None
        or (supplied_reviewer and supplied_reviewer != reviewer)
        or (
            private_plan.get("transaction_ref") != transaction_ref
            or private_plan.get("target_tag") != target_tag
            or private_plan.get("reviewer") != reviewer
            or private_plan.get("expected_archive_identity_sha256")
            != exact_human_approval_archive_identity_sha256(
                expected_archive_id
            )
        )
    ):
        raise ArchiveServiceError(
            "project_version_update_resume_binding_mismatch"
        )
    lifetime = _ProjectVersionUpdateGitRunnerLifetime()
    directory_guard: _WomKitProjectUpdateDirectoryGuard | None = None
    try:
        runner_binding = project_update_git_runner.load_private_binding_bytes(
            transaction.private_binding_bytes("git-runner-binding")
        )
        runner = project_update_git_runner.TrustedProjectUpdateGitRunner.reopen_private(
            runner_binding
        )
        # Adopt the already-reopened exact runner into the lifetime without a
        # second PATH resolution.  This private assignment is intentionally
        # local to crash recovery.
        lifetime._runner = runner
        runner.close_transport_boundary()
        bootstrap_summary = private_plan.get("runtime_bootstrap")
        if (
            type(bootstrap_summary) is not dict
            or bootstrap_summary.get("available") is not True
            or bootstrap_summary.get("release_tag") != target_tag
        ):
            raise ArchiveServiceError(
                "project_version_update_resume_binding_mismatch"
            )
        target_version = str(private_plan.get("target_version") or "")
        bootstrap = project_runtime.BootstrapWheel(
            version=target_version,
            tag=target_tag,
            url="https://invalid.example/intent-bound-never-fetched",
            sha256=str(
                bootstrap_summary.get("wheel_sha256") or ""
            ).removeprefix("sha256:"),
            file_name=str(
                bootstrap_summary.get("wheel_file_name") or ""
            ),
        )
        supply_raw = transaction.private_binding_bytes(
            "runtime-supply-lock"
        )
        supply = project_runtime.project_runtime_supply_lock(
            supply_raw,
            expected_target=target_tag,
        )
        if supply is None:
            raise ArchiveServiceError(
                "project_version_update_resume_binding_mismatch"
            )
        candidate = _project_update_restore_runtime_candidate(
            project_root,
            transaction,
            private_plan.get("runtime_candidate_private"),
        )
        transaction_uses_legacy_runtime_shape = (
            _project_update_legacy_resume_serialization_family(
                transaction,
                candidate,
                private_plan,
            )
        )
        cancellation_started = any(
            item.phase == "preapproval_cancel_requested"
            for item in transaction.inspect().journal.verified_prefix
        )
        if os.path.lexists(candidate.candidate_root):
            live_candidate = project_runtime.load_prepared_runtime_candidate(
                project_root,
                transaction.transaction_root,
                target=target_version,
                target_commit=str(private_plan.get("target_commit") or ""),
                bootstrap=bootstrap,
                supply=supply,
            )
            if live_candidate.public_summary() != candidate.public_summary():
                raise ArchiveServiceError(
                    "project_version_update_resume_binding_mismatch"
                )
            candidate = live_candidate
        elif (
            not cancellation_started
            and not project_runtime._existing_runtime_matches_candidate(
                project_root,
                candidate,
            )
        ):
            raise ArchiveServiceError(
                "project_version_update_runtime_candidate_resume_invalid"
            )
        if (
            project_update_transaction.sha256_document(
                candidate.public_summary()
            )
            != private_plan.get("domain_plan", {}).get(
                "runtime_candidate_sha256"
            )
        ):
            raise ArchiveServiceError(
                "project_version_update_resume_binding_mismatch"
            )
        directory_guard = _WomKitProjectUpdateDirectoryGuard(project_root)
        metadata_root = project_root / ".zettel-kasten"
        mirror_path = project_root.joinpath(
            *PurePosixPath(str(private_plan["mirror_logical"])).parts
        )
        if not (
            directory_guard.hold(project_root)
            and directory_guard.hold(metadata_root)
            and directory_guard.hold_existing_tree(mirror_path)
        ):
            raise ArchiveServiceError(
                "project_version_update_directory_stability_unavailable"
            )
        component_paths: dict[str, Path] = {}
        for component in transaction.intent.components:
            if component.role in {"source", "runtime"}:
                continue
            logical = PurePosixPath(component.logical_target)
            if logical.is_absolute() or ".." in logical.parts:
                raise ArchiveServiceError(
                    "project_version_update_resume_binding_mismatch"
                )
            component_paths[component.component_ref] = project_root.joinpath(
                *logical.parts
            )
        by_role = {
            component.role: component
            for component in transaction.intent.components
            if component.role in {"source", "runtime", "receipt"}
        }
        if set(by_role) != {"source", "runtime", "receipt"}:
            raise ArchiveServiceError(
                "project_version_update_resume_binding_mismatch"
            )
        static_receipt_bytes = transaction.private_binding_bytes(
            "static-receipt-postimage"
        )
        try:
            static_receipt = project_update_transaction._parse_document(
                static_receipt_bytes,
                code="project_update_transaction_invalid",
            )
        except project_update_transaction.ProjectUpdateTransactionError:
            raise ArchiveServiceError(
                "project_version_update_static_receipt_schema_invalid"
            ) from None
        expected_static_receipt_schema = (
            "wom-kit/project-version-update-receipt/v0.3"
            if transaction_uses_legacy_runtime_shape
            else private_plan.get("static_receipt_schema")
        )
        expected_schema_file = {
            "wom-kit/project-version-update-receipt/v0.3": (
                "project-version-update-receipt-v0.3.schema.json"
            ),
            "wom-kit/project-version-update-receipt/v0.4": (
                "project-version-update-receipt-v0.4.schema.json"
            ),
        }.get(expected_static_receipt_schema)
        expected_schema_for_runtime_shape = (
            "wom-kit/project-version-update-receipt/v0.4"
            if candidate.existing_runtime_repair_required
            else "wom-kit/project-version-update-receipt/v0.3"
        )
        if (
            expected_schema_file is None
            or expected_static_receipt_schema
            != expected_schema_for_runtime_shape
            or static_receipt.get("schema")
            != expected_static_receipt_schema
            or validate_schema(static_receipt, expected_schema_file)
        ):
            raise ArchiveServiceError(
                "project_version_update_static_receipt_schema_invalid"
            )
        if transaction_uses_legacy_runtime_shape:
            # v0.4.15 sealed the exact receipt bytes but did not duplicate its
            # schema in the private domain plan.  Derive that historical fact
            # from the already-bound bytes in memory only; never rewrite the
            # private plan or change its authenticated digest.
            private_plan = dict(private_plan)
            private_plan["static_receipt_schema"] = (
                "wom-kit/project-version-update-receipt/v0.3"
            )
        state = _ProjectVersionUpdateDurableApprovalState(
            inspection_root=inspection,
            project_root=project_root,
            mirror_path=mirror_path,
            target_tag=target_tag,
            target_version=target_version,
            target_commit=str(private_plan["target_commit"]),
            reviewer=reviewer,
            expected_approval_root=expected_approval_root,
            expected_archive_id=expected_archive_id,
            transaction=transaction,
            expected_lock_bytes=transaction.lock_bytes(),
            runner=runner,
            runtime_candidate=candidate,
            runtime_bootstrap=bootstrap,
            runtime_supply=supply,
            directory_guard=directory_guard,
            private_plan=private_plan,
            prepared_preview={},
            static_receipt_bytes=static_receipt_bytes,
            static_receipt_path=component_paths[by_role["receipt"].component_ref],
            source_pre_sha256=by_role["source"].pre_sha256,
            source_post_sha256=by_role["source"].post_sha256,
            runtime_pre_sha256=by_role["runtime"].pre_sha256,
            runtime_post_sha256=by_role["runtime"].post_sha256,
            component_paths=component_paths,
            existing_cleanup_authority_sha256=(
                existing_cleanup_authority_sha256
            ),
            legacy_prewrite_recovery=(
                copy.deepcopy(private_plan["legacy_prewrite_recovery"])
                if isinstance(
                    private_plan.get("legacy_prewrite_recovery"), Mapping
                )
                else None
            ),
            legacy_prewrite_recovery_control=(
                dict(_legacy_recovery_control)
                if _legacy_recovery_control is not None
                else None
            ),
        )
        reopened_checkpoints = tuple(
            transaction.inspect().journal.verified_prefix
        )
        runtime_verified = any(
            item.phase == "runtime"
            and item.stage == "verified"
            and item.component_ref == by_role["runtime"].component_ref
            for item in reopened_checkpoints
        )
        if (
            runtime_verified
            and candidate.existing_runtime_repair_required
        ):
            # A later component may fail after the repaired runtime checkpoint
            # is durable.  The next public --resume skips that already-verified
            # component, so reconstruct its exact live rollback authority here
            # instead of losing the repaired result truth in the new process.
            state.runtime_materialization = (
                project_runtime.reopen_promoted_runtime_materialization(
                    candidate
                )
            )
        state.prepared_preview = _project_update_build_prepared_preview(
            state
        )
        # The reopened runner must match the final approval projection exactly.
        project_version_update_approval_binding(state.prepared_preview)
        # ``state`` now owns the guard through the returned service lifetime.
        directory_guard = None
        return state, lifetime
    except BaseException:
        _project_update_close_after_service_failure(
            (
                directory_guard.close
                if directory_guard is not None
                else (lambda: None)
            ),
            lifetime,
        )
        raise


def _wom_kit_project_version_update_legacy_core_generator(
    inspection_root: Path | str,
    *,
    target: str,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    affirm_external_writers_quiescent: bool = False,
    operation_exact_human_approval: Mapping[str, Any] | None = None,
    prepare_exact_approval: bool = False,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
    _expected_approval_root: Path | None = None,
    _expected_archive_id: str | None = None,
    _git_runner_lifetime: _ProjectVersionUpdateGitRunnerLifetime,
    _legacy_recovery_old_lock_bytes: bytes | None = None,
    _legacy_recovery_approval_summary: Mapping[str, Any] | None = None,
    _legacy_recovery_control: Mapping[str, Any] | None = None,
) -> Any:
    """Run the updater, optionally yielding one lock-held exact preview."""

    git_runner = _git_runner_lifetime.acquire_preapproval()
    blockers: list[str] = []
    warnings: list[str] = []
    target_tag = str(target or "").strip()
    target_version = normalize_version_label(target_tag)
    reviewer = safe_foreign_quarantine_actor_id(reviewed_by)
    inspection = Path(os.path.abspath(str(Path(inspection_root).expanduser())))
    preflight_check_names = (
        "project_root_binding",
        "inspection_root",
        "project_root",
        "metadata_root",
        "source_mirror",
        "update_lock",
        "git_inside_worktree",
        "git_worktree_root_exact",
        "git_metadata_local_real",
        "git_head",
        "git_snapshot",
        "source_mirror_pin_tracking",
        "origin_configuration",
        "source_version_metadata",
        "git_transaction_snapshot",
        "git_config_trust",
    )
    preflight_checks: dict[str, dict[str, str]] = {
        name: {
            "state": "not_reached",
            "reason_code": "project_preflight_not_reached",
        }
        for name in preflight_check_names
    }

    def record_preflight_check(
        name: str,
        state: str,
        reason_code: str,
    ) -> None:
        if name not in preflight_checks or state not in {
            "passed",
            "failed",
            "not_reached",
            "unavailable",
        }:
            raise ArchiveServiceError("project_version_update_preflight_invalid")
        preflight_checks[name] = {
            "state": state,
            "reason_code": reason_code,
        }

    local_metadata_root = inspection / ".zettel-kasten"
    parent_metadata_root = inspection.parent / ".zettel-kasten"
    local_metadata_observation = wom_kit_real_path_kind_observation(
        inspection,
        local_metadata_root,
    )
    archive_config_observation = wom_kit_real_path_kind_observation(
        inspection,
        inspection / "archive.yml",
    )
    parent_metadata_observation = wom_kit_real_path_kind_observation(
        inspection.parent,
        parent_metadata_root,
    )
    root_binding_observations = (
        local_metadata_observation,
        archive_config_observation,
        parent_metadata_observation,
    )
    if any(
        item["state"] == "unavailable"
        for item in root_binding_observations
    ):
        record_preflight_check(
            "project_root_binding",
            "unavailable",
            "project_root_binding_observation_unavailable",
        )
    elif any(item["state"] == "failed" for item in root_binding_observations):
        record_preflight_check(
            "project_root_binding",
            "failed",
            "project_root_binding_unsafe",
        )
    else:
        record_preflight_check(
            "project_root_binding",
            "passed",
            "verified",
        )
    project_root = (
        inspection.parent
        if (
            preflight_checks["project_root_binding"]["state"] == "passed"
            and local_metadata_observation["kind"] == "missing"
            and archive_config_observation["kind"] == "file"
            and parent_metadata_observation["kind"] == "directory"
        )
        else inspection
    )
    root_label = "parent_of_archive" if project_root != inspection else "inspection_root"
    metadata_root = project_root / ".zettel-kasten"
    mirror_path = metadata_root / "source"
    receipts_root = project_root / WOM_KIT_PROJECT_UPDATE_RECEIPTS_RELATIVE
    receipts_parent = metadata_root / "receipts"
    receipts_parent_existed_before = receipts_parent.exists()
    receipts_root_existed_before = receipts_root.exists()
    mirror_logical = wom_kit_project_source_mirror_location(root_label)
    lock_path = project_root / WOM_KIT_PROJECT_UPDATE_LOCK_RELATIVE
    if progress_callback is not None:
        progress_callback("project-preflight", "start", None, None)

    if dry_run is approve:
        blockers.append("Choose exactly one mode: --dry-run or --approve.")
    if approve and not WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED:
        blockers.append(
            "Approved project-version-update is currently supported only on Windows, where every write-path directory can be held against rename or reparse replacement; POSIX approval fails closed."
        )
    elif dry_run and not WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED:
        warnings.append(
            "This read-only preview can run here, but approval is currently supported only on Windows; POSIX approval fails closed until the Git and full-tree transaction is descriptor-relative end to end."
        )
    if (
        (dry_run or approve)
        and WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED
    ):
        warnings.append(
            "Approved project-version-update requires external writers to stay quiescent for the whole transaction; close editors and pause sync, backup, and other Git processes before approval."
        )
    if not WOM_KIT_PROJECT_UPDATE_TAG_RE.fullmatch(target_tag):
        blockers.append("target must be an exact stable release tag such as v0.3.215.")
    if approve and reviewer is None:
        blockers.append("project-version-update approve requires a safe --reviewed-by actor id.")
    if approve and not affirm_external_writers_quiescent:
        blockers.append(
            "project-version-update approve requires --affirm-external-writers-quiescent after editors and sync, backup, and other Git processes have been paused for the complete transaction."
        )
    if reviewed_by and reviewer is None:
        blockers.append("reviewed_by must be a safe non-secret actor id.")
    if preflight_checks["project_root_binding"]["state"] == "unavailable":
        blockers.append(
            "The archive-to-project root binding could not be observed safely."
        )
    elif preflight_checks["project_root_binding"]["state"] == "failed":
        blockers.append("The archive-to-project root binding is unsafe.")

    inspection_observation = wom_kit_real_path_kind_observation(
        inspection,
        inspection,
    )
    inspection_kind = str(inspection_observation["kind"])
    if inspection_observation["state"] == "unavailable":
        record_preflight_check(
            "inspection_root",
            "unavailable",
            "inspection_root_observation_unavailable",
        )
        blockers.append(
            "The project/archive inspection root could not be observed safely."
        )
    elif (
        inspection_observation["state"] != "passed"
        or inspection_kind != "directory"
    ):
        record_preflight_check(
            "inspection_root",
            "failed",
            "inspection_root_missing_or_unsafe",
        )
        blockers.append("The project/archive inspection root must be an existing directory.")
    else:
        record_preflight_check("inspection_root", "passed", "verified")

    project_root_observation = wom_kit_real_path_kind_observation(
        project_root,
        project_root,
    )
    project_root_kind = str(project_root_observation["kind"])
    if project_root_observation["state"] == "unavailable":
        record_preflight_check(
            "project_root",
            "unavailable",
            "project_root_observation_unavailable",
        )
        blockers.append("The resolved project root could not be observed safely.")
    elif (
        project_root_observation["state"] != "passed"
        or project_root_kind != "directory"
    ):
        record_preflight_check(
            "project_root",
            "failed",
            "project_root_missing_or_unsafe",
        )
        blockers.append("The resolved project root must be an existing directory.")
    else:
        record_preflight_check("project_root", "passed", "verified")

    metadata_observation = wom_kit_real_path_kind_observation(
        project_root,
        metadata_root,
    )
    metadata_kind = str(metadata_observation["kind"])
    if metadata_observation["state"] == "unavailable":
        record_preflight_check(
            "metadata_root",
            "unavailable",
            "project_metadata_root_observation_unavailable",
        )
        blockers.append(
            "The project .zettel-kasten directory could not be observed safely."
        )
    elif (
        metadata_observation["state"] != "passed"
        or metadata_kind not in {"directory", "missing"}
    ):
        record_preflight_check(
            "metadata_root",
            "failed",
            "project_metadata_root_unsafe",
        )
        blockers.append(
            "The project .zettel-kasten directory must be a real directory, not a symlink or reparse point."
        )
    else:
        record_preflight_check("metadata_root", "passed", "verified")
    if (
        not wom_kit_existing_path_components_are_real(project_root, receipts_parent)
        or not wom_kit_existing_path_components_are_real(project_root, receipts_root)
        or not is_path_within_root(receipts_root, project_root)
    ):
        blockers.append(
            "The project version-update receipt directory must stay real and inside the project root."
        )
    mirror_observation = wom_kit_real_path_kind_observation(
        project_root,
        mirror_path,
    )
    mirror_kind = str(mirror_observation["kind"])
    if mirror_observation["state"] == "unavailable":
        record_preflight_check(
            "source_mirror",
            "unavailable",
            "project_source_mirror_observation_unavailable",
        )
        blockers.append(
            "The project-local source mirror could not be observed safely."
        )
    elif mirror_observation["state"] != "passed":
        record_preflight_check(
            "source_mirror",
            "failed",
            "project_source_mirror_unsafe",
        )
        blockers.append(
            "The project source mirror must be a real directory without a symlink or reparse component inside the project root."
        )
    elif mirror_kind == "missing":
        record_preflight_check(
            "source_mirror",
            "failed",
            "project_source_mirror_missing",
        )
        blockers.append("The project-local .zettel-kasten/source mirror is missing.")
    elif mirror_kind != "directory" or not is_path_within_root(mirror_path, project_root):
        record_preflight_check(
            "source_mirror",
            "failed",
            "project_source_mirror_unsafe",
        )
        blockers.append(
            "The project source mirror must be a real directory without a symlink or reparse component inside the project root."
        )
    else:
        record_preflight_check("source_mirror", "passed", "verified")

    lock_observation = wom_kit_real_path_kind_observation(
        project_root,
        lock_path,
    )
    lock_kind = str(lock_observation["kind"])
    legacy_recovery_mode = bool(
        type(_legacy_recovery_old_lock_bytes) is bytes
        and _legacy_recovery_old_lock_bytes
        and isinstance(_legacy_recovery_approval_summary, Mapping)
        and isinstance(_legacy_recovery_control, Mapping)
    )
    legacy_recovery_inputs_present = (
        _legacy_recovery_old_lock_bytes is not None,
        _legacy_recovery_approval_summary is not None,
        _legacy_recovery_control is not None,
    )
    if any(legacy_recovery_inputs_present) and not all(
        legacy_recovery_inputs_present
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    if lock_observation["state"] == "unavailable":
        record_preflight_check(
            "update_lock",
            "unavailable",
            "project_update_lock_observation_unavailable",
        )
        blockers.append("The project version update lock could not be observed safely.")
    elif (
        lock_observation["state"] != "passed"
        or not wom_kit_existing_path_components_are_real(project_root, lock_path)
    ):
        record_preflight_check(
            "update_lock",
            "failed",
            "project_update_lock_unsafe",
        )
        blockers.append("The project version-update lock path is unsafe.")
    elif lock_kind != "missing" and not legacy_recovery_mode:
        record_preflight_check(
            "update_lock",
            "failed",
            "project_update_lock_present",
        )
        blockers.append("A project version update lock already exists; review the prior run before continuing.")
    elif lock_kind == "missing" and legacy_recovery_mode:
        record_preflight_check(
            "update_lock",
            "failed",
            "project_update_legacy_recovery_lock_missing",
        )
        blockers.append("project_update_legacy_recovery_lock_missing")
    elif legacy_recovery_mode:
        observed_old_lock = _wom_kit_read_bounded_real_bytes(
            project_root,
            lock_path,
            max_bytes=project_update_transaction.MAX_DOCUMENT_BYTES + 1,
        )
        if observed_old_lock != _legacy_recovery_old_lock_bytes:
            record_preflight_check(
                "update_lock",
                "failed",
                "project_update_legacy_recovery_lock_changed",
            )
            blockers.append("project_update_legacy_recovery_lock_changed")
        else:
            record_preflight_check("update_lock", "passed", "verified")
    else:
        record_preflight_check("update_lock", "passed", "verified")

    git_repo_verified: bool | None = None
    worktree_clean: bool | None = None
    origin_configured: bool | None = None
    mirror_pin_tracked: bool | None = None
    unexpected_worktree_entry_count: int | None = None
    head_before: str | None = None
    head_after: str | None = None
    original_branch: str | None = None
    current_versions: dict[str, str | None] = {"package": None, "pyproject": None, "root_shim": None}
    runtime_import_origin_within_project_source_mirror = bool(
        mirror_observation["state"] == "passed"
        and mirror_kind == "directory"
        and is_path_within_root(Path(__file__).resolve(), mirror_path)
    )

    path_preflight_passed = all(
        preflight_checks[name]["state"] == "passed"
        for name in (
            "project_root_binding",
            "inspection_root",
            "project_root",
            "metadata_root",
            "source_mirror",
            "update_lock",
        )
    )
    if path_preflight_passed:
        inside_available, inside_return_code, inside_text = (
            _wom_kit_project_update_git_observation(
            mirror_path,
            ["rev-parse", "--is-inside-work-tree"],
            runner=git_runner,
            )
        )
        if not inside_available:
            record_preflight_check(
                "git_inside_worktree",
                "unavailable",
                "project_git_inside_worktree_observation_unavailable",
            )
        elif inside_return_code != 0 or inside_text != "true":
            record_preflight_check(
                "git_inside_worktree",
                "failed",
                "project_git_inside_worktree_unverified",
            )
        else:
            record_preflight_check("git_inside_worktree", "passed", "verified")

        if preflight_checks["git_inside_worktree"]["state"] == "passed":
            top_available, top_return_code, top_text = (
                _wom_kit_project_update_git_observation(
                    mirror_path,
                    ["rev-parse", "--show-toplevel"],
                    runner=git_runner,
                )
            )
            top_resolution_unavailable = False
            try:
                exact_top = bool(
                    top_available
                    and top_return_code == 0
                    and Path(top_text).resolve() == mirror_path.resolve()
                )
            except OSError:
                exact_top = False
                top_resolution_unavailable = True
            except (RuntimeError, ValueError):
                exact_top = False
            if not top_available or top_resolution_unavailable:
                record_preflight_check(
                    "git_worktree_root_exact",
                    "unavailable",
                    "project_git_worktree_root_observation_unavailable",
                )
            elif top_return_code != 0 or not exact_top:
                record_preflight_check(
                    "git_worktree_root_exact",
                    "failed",
                    "project_git_worktree_root_unverified",
                )
            else:
                record_preflight_check(
                    "git_worktree_root_exact",
                    "passed",
                    "verified",
                )

        if preflight_checks["git_worktree_root_exact"]["state"] == "passed":
            git_metadata_evidence = wom_kit_project_update_git_metadata_evidence(
                project_root,
                mirror_path,
                runner=git_runner,
            )
            record_preflight_check(
                "git_metadata_local_real",
                str(git_metadata_evidence["state"]),
                str(git_metadata_evidence["reason_code"]),
            )

        git_required_states = {
            preflight_checks[name]["state"]
            for name in (
                "git_inside_worktree",
                "git_worktree_root_exact",
                "git_metadata_local_real",
            )
        }
        git_repo_verified = (
            True
            if git_required_states == {"passed"}
            else False
            if "failed" in git_required_states
            else None
        )
        if git_repo_verified is not True:
            blockers.append(
                "The project source mirror must be the exact root of a Git working tree whose real .git metadata stays inside that mirror."
            )
        else:
            head_available, head_return_code, head_text = (
                _wom_kit_project_update_git_observation(
                    mirror_path,
                    ["rev-parse", "--verify", "HEAD"],
                    runner=git_runner,
                )
            )
            if not head_available:
                record_preflight_check(
                    "git_head",
                    "unavailable",
                    "project_git_head_observation_unavailable",
                )
                blockers.append(
                    "The project source mirror HEAD could not be observed safely."
                )
            elif (
                head_return_code == 0
                and re.fullmatch(r"[0-9a-fA-F]{40,64}", head_text)
            ):
                record_preflight_check("git_head", "passed", "verified")
                head_before = head_text.lower()
                head_after = head_before
            else:
                record_preflight_check(
                    "git_head",
                    "failed",
                    "project_git_head_invalid",
                )
                blockers.append("The project source mirror has no valid HEAD commit.")
            if preflight_checks["git_head"]["state"] == "passed":
                symbolic_head_state, branch_text = (
                    wom_kit_project_update_symbolic_head_state(
                        mirror_path,
                        runner=git_runner,
                    )
                )
                original_branch = (
                    branch_text
                    if symbolic_head_state == "branch"
                    else None
                )
                if symbolic_head_state == "invalid":
                    blockers.append(
                        "The project source mirror symbolic HEAD state could not be read safely."
                    )
                if (
                    original_branch is not None
                    and not wom_kit_project_update_branch_points_to_commit(
                        mirror_path,
                        original_branch,
                        head_before,
                        runner=git_runner,
                    )
                ):
                    blockers.append(
                        "The original project source branch cannot be restored safely with Git's branch-name rules."
                    )
                initial_snapshot = _wom_kit_project_update_git_snapshot(
                    mirror_path,
                    runner=git_runner,
                )
                unexpected_worktree_entry_count = (
                    len(
                        [
                            path
                            for path in initial_snapshot.get(
                                "untracked_paths",
                                [],
                            )
                            if path != "installed-version.txt"
                        ]
                    )
                    if initial_snapshot is not None
                    else None
                )
                if initial_snapshot is None:
                    record_preflight_check(
                        "git_snapshot",
                        "unavailable",
                        "project_git_snapshot_observation_unavailable",
                    )
                    blockers.append(
                        "The project source mirror worktree snapshot could not be read safely."
                    )
                else:
                    worktree_clean = wom_kit_project_update_snapshot_is_clean(
                        initial_snapshot,
                        expected_head=head_before,
                        expected_branch=original_branch,
                    )
                    record_preflight_check(
                        "git_snapshot",
                        "passed" if worktree_clean else "failed",
                        (
                            "verified"
                            if worktree_clean
                            else "project_git_worktree_dirty"
                        ),
                    )
                if worktree_clean is False:
                    blockers.append(
                        "The project source mirror has changed bytes, an unsafe index, or unknown untracked files."
                    )

            if preflight_checks["git_snapshot"]["state"] == "passed":
                tracked_available, tracked_return_code, _ = (
                    _wom_kit_project_update_git_observation(
                        mirror_path,
                        [
                            "ls-files",
                            "--error-unmatch",
                            "--",
                            "installed-version.txt",
                        ],
                        runner=git_runner,
                    )
                )
                if tracked_available and tracked_return_code == 0:
                    mirror_pin_tracked = True
                    record_preflight_check(
                        "source_mirror_pin_tracking",
                        "failed",
                        "project_source_pin_tracked",
                    )
                    blockers.append(
                        "The source-mirror installed-version pin must not be Git-tracked."
                    )
                elif tracked_available and tracked_return_code == 1:
                    mirror_pin_tracked = False
                    record_preflight_check(
                        "source_mirror_pin_tracking",
                        "passed",
                        "verified",
                    )
                else:
                    record_preflight_check(
                        "source_mirror_pin_tracking",
                        "unavailable",
                        "project_source_pin_tracking_unavailable",
                    )
                    blockers.append(
                        "The source-mirror installed-version pin tracking state could not be observed safely."
                    )

            if (
                preflight_checks["source_mirror_pin_tracking"]["state"]
                == "passed"
            ):
                origin_available, origin_return_code, origin_key_text = (
                    _wom_kit_project_update_git_observation(
                        mirror_path,
                        [
                            "config",
                            "--local",
                            "--no-includes",
                            "--name-only",
                            "--get-regexp",
                            r"^remote\.origin\.url$",
                        ],
                        runner=git_runner,
                    )
                )
                origin_key_lines = [
                    line.strip().lower()
                    for line in origin_key_text.splitlines()
                    if line.strip()
                ]
                if (
                    origin_available
                    and origin_return_code == 0
                    and origin_key_lines == ["remote.origin.url"]
                ):
                    origin_configured = True
                    record_preflight_check(
                        "origin_configuration",
                        "passed",
                        "verified",
                    )
                elif origin_available and origin_return_code in {0, 1}:
                    origin_configured = False
                    record_preflight_check(
                        "origin_configuration",
                        "failed",
                        "project_origin_not_configured",
                    )
                    blockers.append(
                        "The project source mirror must have a configured origin remote."
                    )
                else:
                    record_preflight_check(
                        "origin_configuration",
                        "unavailable",
                        "project_origin_configuration_unavailable",
                    )
                    blockers.append(
                        "The project source mirror origin configuration could not be observed safely."
                    )

            if preflight_checks["origin_configuration"]["state"] == "passed":
                current_versions_observation = (
                    wom_kit_project_update_source_versions_observation(
                        mirror_path
                    )
                )
                record_preflight_check(
                    "source_version_metadata",
                    str(current_versions_observation["state"]),
                    str(current_versions_observation["reason_code"]),
                )
                if current_versions_observation["state"] == "passed":
                    current_versions = dict(
                        current_versions_observation["versions"]
                    )
                elif current_versions_observation["state"] == "unavailable":
                    blockers.append(
                        "The project source version metadata could not be observed safely."
                    )
                else:
                    blockers.append(
                        "The project source version metadata is missing, unsafe, or invalid."
                    )

    pin_specs: list[dict[str, Any]] = []
    project_pin_path = metadata_root / "installed-version.txt"
    pin_specs.append(
        {
            "path": project_pin_path,
            "logical": (
                ".zettel-kasten/installed-version.txt"
                if root_label == "inspection_root"
                else f"{root_label}/.zettel-kasten/installed-version.txt"
            ),
            "role": "project_pin",
        }
    )
    mirror_pin_path = mirror_path / "installed-version.txt"
    mirror_pin_observation = wom_kit_real_path_kind_observation(
        project_root,
        mirror_pin_path,
    )
    if mirror_pin_observation["state"] == "unavailable":
        blockers.append(
            "A recognized installed-version pin location could not be observed safely."
        )
    elif not (
        mirror_pin_observation["state"] == "passed"
        and mirror_pin_observation["kind"] == "missing"
    ):
        pin_specs.append(
            {
                "path": mirror_pin_path,
                "logical": f"{mirror_logical}/installed-version.txt",
                "role": "source_mirror_pin",
            }
        )
    legacy_pin_path = project_root / "installed-version.txt"
    legacy_pin_observation = wom_kit_real_path_kind_observation(
        project_root,
        legacy_pin_path,
    )
    if legacy_pin_observation["state"] == "unavailable":
        blockers.append(
            "A recognized installed-version pin location could not be observed safely."
        )
    elif not (
        legacy_pin_observation["state"] == "passed"
        and legacy_pin_observation["kind"] == "missing"
    ):
        pin_specs.append(
            {
                "path": legacy_pin_path,
                "logical": "installed-version.txt" if root_label == "inspection_root" else f"{root_label}/installed-version.txt",
                "role": "legacy_project_pin",
            }
        )

    for spec in pin_specs:
        path = spec["path"]
        path_observation = wom_kit_real_path_kind_observation(
            project_root,
            path,
        )
        path_kind = str(path_observation["kind"])
        spec["existed"] = (
            path_kind == "file"
            if path_observation["state"] == "passed"
            else None
        )
        spec["previous_bytes"] = None
        spec["previous_version"] = None
        if path_observation["state"] == "unavailable":
            blockers.append(
                "A recognized installed-version pin location could not be observed safely."
            )
            continue
        if (
            path_observation["state"] != "passed"
            or path_kind not in {"file", "missing"}
            or not wom_kit_existing_path_components_are_real(project_root, path)
        ):
            blockers.append(
                "Recognized installed-version pins must not contain a symlink, junction, or reparse path component."
            )
            continue
        if path_kind == "file":
            try:
                previous_bytes = _wom_kit_read_bounded_real_bytes(
                    project_root,
                    path,
                    max_bytes=WOM_KIT_VERSION_PIN_MAX_BYTES,
                )
                if previous_bytes is None:
                    raise OSError("pin_unreadable_or_too_large")
                previous_text = previous_bytes.decode("utf-8-sig").strip()
            except (OSError, UnicodeError):
                blockers.append(
                    "A recognized installed-version pin is unreadable or exceeds the size limit."
                )
                continue
            previous_version = normalize_version_label(previous_text)
            if previous_version is None or not WOM_KIT_PROJECT_UPDATE_TAG_RE.fullmatch(f"v{previous_version}"):
                blockers.append("A recognized installed-version pin does not contain an exact stable version.")
                continue
            spec["previous_bytes"] = previous_bytes
            spec["previous_version"] = f"v{previous_version}"

    initial_preflight_complete = (
        preflight_checks["source_version_metadata"]["state"] == "passed"
    )
    preflight_git_snapshot = (
        _wom_kit_project_update_git_snapshot(
            mirror_path,
            runner=git_runner,
        )
        if initial_preflight_complete
        else None
    )
    if initial_preflight_complete:
        transaction_snapshot_clean = bool(
            preflight_git_snapshot is not None
            and wom_kit_project_update_snapshot_is_clean(
                preflight_git_snapshot,
                expected_head=head_before,
                expected_branch=original_branch,
            )
        )
        record_preflight_check(
            "git_transaction_snapshot",
            (
                "unavailable"
                if preflight_git_snapshot is None
                else "passed"
                if transaction_snapshot_clean
                else "failed"
            ),
            (
                "project_git_transaction_snapshot_unavailable"
                if preflight_git_snapshot is None
                else "verified"
                if transaction_snapshot_clean
                else "project_git_transaction_snapshot_changed"
            ),
        )
    preflight_git_config_digest = (
        wom_kit_project_update_git_config_trust_digest(
            mirror_path,
            runner=git_runner,
        )
        if preflight_checks["git_transaction_snapshot"]["state"] == "passed"
        else None
    )
    if preflight_checks["git_transaction_snapshot"]["state"] == "unavailable":
        blockers.append(
            "The project source mirror state snapshot could not be captured safely."
        )
    elif preflight_checks["git_transaction_snapshot"]["state"] == "failed":
        blockers.append(
            "The project source mirror changed during preflight; rerun the dry-run."
        )
    if preflight_checks["git_transaction_snapshot"]["state"] == "passed":
        record_preflight_check(
            "git_config_trust",
            "passed" if preflight_git_config_digest is not None else "unavailable",
            (
                "verified"
                if preflight_git_config_digest is not None
                else "project_git_config_trust_unavailable"
            ),
        )
    if preflight_checks["git_config_trust"]["state"] == "unavailable":
        blockers.append(
            "The effective configured-origin Git trust settings could not be bound safely."
        )

    forward_only_blocked = False
    forward_only_target_is_at_least_every_project_version = False
    recognized_project_versions = [
        *(normalize_version_label(value) for value in current_versions.values()),
        *(normalize_version_label(spec.get("previous_version")) for spec in pin_specs),
    ]
    recognized_project_version_keys = [
        key
        for value in recognized_project_versions
        if value
        for key in [version_sort_key(value)]
        if key is not None
    ]
    if target_version:
        target_key = version_sort_key(target_version)
        forward_only_target_is_at_least_every_project_version = bool(
            target_key is not None
            and all(target_key >= key for key in recognized_project_version_keys)
        )
        if (
            target_key is not None
            and any(target_key < key for key in recognized_project_version_keys)
        ):
            forward_only_blocked = True
            blockers.append("project-version-update is forward-only and refuses a version downgrade.")
        running_version = normalize_version_label(WOM_KIT_VERSION)
        running_key = version_sort_key(running_version) if running_version else None
        if (
            not runtime_import_origin_within_project_source_mirror
            and target_key is not None
            and running_key is not None
            and target_key < running_key
            and forward_only_target_is_at_least_every_project_version
        ):
            warnings.append(
                "The running WOM-kit is newer than the target but was loaded outside the project source mirror; it is reported for context and is not a forward-only blocker. The decision uses recognized project pins and project source versions."
            )

    target_evidence = (
        wom_kit_project_update_target_evidence(
            mirror_path,
            target_tag,
            runner=git_runner,
        )
        if (
            preflight_checks["git_config_trust"]["state"] == "passed"
            and WOM_KIT_PROJECT_UPDATE_TAG_RE.fullmatch(target_tag)
        )
        else {
            "tag_available_locally": False,
            "annotated_tag_verified": False,
            "target_commit": None,
            "origin_main_available_locally": False,
            "target_reachable_from_origin_main": False,
            "source_versions": {"package": None, "pyproject": None, "root_shim": None},
            "all_source_versions_match_target": False,
            "observation_state": "not_reached",
            "observation_reason_code": "project_target_evidence_not_reached",
        }
    )
    project_runtime_bootstrap, project_runtime_bootstrap_summary = (
        project_runtime.bootstrap_wheel_for_target(target_version or "")
    )
    project_runtime_policy = wom_kit_project_update_runtime_policy(
        mirror_path,
        (
            str(target_evidence["target_commit"])
            if isinstance(target_evidence.get("target_commit"), str)
            else None
        ),
        runner=git_runner,
    )
    project_runtime_supply = wom_kit_project_update_runtime_supply(
        mirror_path,
        (
            str(target_evidence["target_commit"])
            if isinstance(target_evidence.get("target_commit"), str)
            else None
        ),
        target_version,
        project_runtime_policy,
        runner=git_runner,
    )
    project_runtime_plan: dict[str, Any] = {
        "policy_state": project_runtime_policy["state"],
        "required": False,
        "target_path": None,
        "launcher_path": project_runtime.PROJECT_RUNTIME_LAUNCHER_RELATIVE.as_posix(),
        "project_runtime_argv": project_runtime.project_runtime_argv(),
        "installed": {"status": "not_checked", "verified": False},
        "bootstrap": dict(project_runtime_bootstrap_summary),
        "materialization_required": False,
        "runtime_creation_required": False,
        "runtime_repair_required": False,
        "repair_preimage_exactly_bound": False,
        "will_bind_repair_preimage_exactly_before_approval": False,
        "will_preserve_during_active_transaction": False,
        "activation_required": False,
        "active_version_pin": ".zettel-kasten/installed-version.txt",
        "global_path_mutation": False,
        "old_invalid_runtime_deletion_stage": "not_applicable",
    }
    project_runtime_plan_blockers: list[str] = []
    project_runtime_plan_warnings: list[str] = []
    project_runtime_launcher_snapshot: dict[str, Any] | None = None
    project_runtime_launcher_write_attempted = False
    project_runtime_launcher_written = False
    project_runtime_materialization: project_runtime.RuntimeMaterialization | None = None
    project_runtime_mutation_tracker = project_runtime.RuntimeMutationTracker()
    prepared_runtime_bundle: Any | None = None
    prepared_runtime_bundle_summary: dict[str, Any] | None = None
    prepared_runtime_bundle_cleanup_state = "not_required"
    runtime_preparation_revalidation = (
        wom_kit_project_update_runtime_preparation_revalidation()
    )

    def refresh_project_runtime_plan(*, enforce_interpreter: bool) -> None:
        nonlocal project_runtime_policy
        nonlocal project_runtime_supply
        nonlocal project_runtime_plan
        nonlocal project_runtime_plan_blockers
        nonlocal project_runtime_plan_warnings
        nonlocal project_runtime_launcher_snapshot
        target_commit_value = (
            str(target_evidence["target_commit"])
            if isinstance(target_evidence.get("target_commit"), str)
            else None
        )
        project_runtime_policy = wom_kit_project_update_runtime_policy(
            mirror_path,
            target_commit_value,
            runner=git_runner,
        )
        project_runtime_supply = wom_kit_project_update_runtime_supply(
            mirror_path,
            target_commit_value,
            target_version,
            project_runtime_policy,
            runner=git_runner,
        )
        if (
            target_version is None
            or not WOM_KIT_PROJECT_UPDATE_TAG_RE.fullmatch(target_tag)
            or project_root_kind != "directory"
        ):
            return
        project_runtime_plan, project_runtime_plan_blockers, project_runtime_plan_warnings = (
            project_runtime.plan_runtime(
                project_root,
                target_version,
                policy_state=str(project_runtime_policy["state"]),
                target_commit=target_commit_value,
                bootstrap=project_runtime_bootstrap,
                bootstrap_summary=project_runtime_bootstrap_summary,
                supply=project_runtime_supply,
                enforce_interpreter=enforce_interpreter,
            )
        )
        project_runtime_plan["policy"] = dict(project_runtime_policy)
        project_runtime_launcher_snapshot = project_runtime.launcher_snapshot(
            project_root,
            target_version,
        )

    # Ordinary previews are portable and strictly read-only.  The exact
    # interpreter/platform lock becomes mandatory only inside the live,
    # lock-held approval transaction before the native dialog is shown.
    refresh_project_runtime_plan(enforce_interpreter=False)
    if project_runtime_policy["state"] == "invalid":
        blockers.append("project_runtime_policy_invalid")
    blockers.extend(project_runtime_plan_blockers)
    warnings.extend(project_runtime_plan_warnings)
    fetch_attempted = False
    fetch_succeeded = False
    source_checkout_changed = False
    runtime_source_rematerialization_attempted = False
    runtime_source_rematerialization_succeeded: bool | None = None
    target_runtime_source_integrity_verified = False
    pin_write_attempted_paths: list[str] = []
    pins_written: list[str] = []
    receipt_relative: str | None = None
    receipt_written = False
    receipt_bytes: bytes | None = None
    receipt_reservation: dict[str, Any] | None = None
    rollback = {
        "attempted": False,
        "succeeded": None,
        "source_restored": None,
        "pins_restored": None,
        "project_runtime_removed": None,
        "prepared_runtime_bundle_removed": None,
        "runtime_reference_cleanup_verified": None,
        "project_runtime_launcher_restored": None,
        "lock_removed": None,
        "fetched_refs_may_remain": False,
    }
    lock_acquired = False
    lock_reservation: dict[str, Any] | None = None
    lock_release_state = "not_acquired"
    lock_release_intent_status: str | None = None
    directory_guard: _WomKitProjectUpdateDirectoryGuard | None = None
    preserve_lock = False
    durable_reservation: (
        project_update_transaction.ReservedProjectUpdateTransaction | None
    ) = None
    durable_transaction: (
        project_update_transaction.ProjectUpdateTransaction | None
    ) = None
    durable_lock_bytes: bytes | None = None
    durable_approval_state: (
        _ProjectVersionUpdateDurableApprovalState | None
    ) = None
    durable_handoff_complete = False
    target_git_snapshot: dict[str, Any] | None = None
    trusted_target_ref_snapshot: dict[str, str] | None = None
    source_materialization_completed = False
    materialization_preflight = (
        wom_kit_project_update_materialization_preflight_state(
            "not_evaluated"
        )
    )

    def validate_target_evidence(*, require_local: bool, require_origin_ancestry: bool) -> None:
        if require_local and not target_evidence.get("tag_available_locally"):
            blockers.append("The exact target tag is not available after the configured-origin fetch.")
            return
        if not target_evidence.get("tag_available_locally"):
            return
        if not target_evidence.get("annotated_tag_verified"):
            blockers.append("The target release ref must be an annotated Git tag.")
        if not target_evidence.get("target_commit"):
            blockers.append("The target release tag does not resolve to a commit.")
        if not target_evidence.get("all_source_versions_match_target"):
            blockers.append("The target tag package, pyproject, and root shim versions must all match the target.")
        if not target_evidence.get("origin_main_available_locally"):
            if require_origin_ancestry:
                blockers.append("The configured origin/main ref is unavailable for target ancestry verification.")
            else:
                warnings.append("Local origin/main evidence is unavailable; approval will refresh and verify it before checkout.")
        elif not target_evidence.get("target_reachable_from_origin_main"):
            if require_origin_ancestry:
                blockers.append("The target tag commit must be reachable from configured origin/main.")
            else:
                warnings.append("Local origin/main evidence is stale or does not contain the target; approval will refresh and verify it.")

    if dry_run and target_evidence.get("tag_available_locally"):
        validate_target_evidence(require_local=True, require_origin_ancestry=False)
    elif dry_run and not target_evidence.get("tag_available_locally"):
        warnings.append("The target tag is not fetched locally; approval will fetch and verify it before any checkout.")
        materialization_preflight = (
            wom_kit_project_update_materialization_preflight_state(
                "deferred_until_approval_fetch"
            )
        )
    if (
        dry_run
        and not blockers
        and target_evidence.get("tag_available_locally")
        and isinstance(target_evidence.get("target_commit"), str)
    ):
        materialization_preflight = (
            wom_kit_project_update_materialization_preflight(
                project_root,
                mirror_path,
                target_commit=str(target_evidence["target_commit"]),
                head_before=head_before,
                original_branch=original_branch,
                runner=git_runner,
            )
        )
        target_runtime_source_integrity_verified = bool(
            materialization_preflight[
                "target_runtime_source_integrity_verified"
            ]
        )
        if materialization_preflight["state"] == "blocked":
            blockers.append(
                WOM_KIT_PROJECT_UPDATE_MATERIALIZATION_BLOCKER
            )

    last_result_payload: dict[str, Any] | None = None

    def result_payload(status: str) -> dict[str, Any]:
        nonlocal last_result_payload
        target_commit = target_evidence.get("target_commit")
        preflight_states = {
            detail["state"] for detail in preflight_checks.values()
        }
        preflight_state = (
            "failed"
            if "failed" in preflight_states
            else "unavailable"
            if "unavailable" in preflight_states
            else "passed"
            if preflight_states == {"passed"}
            else "not_reached"
        )
        rolled_back = (
            status in {"failed_rolled_back", "interrupted_rolled_back"}
            and rollback.get("succeeded") is True
        )
        final_pins_written = [] if rolled_back else list(pins_written)
        final_launcher_written = bool(
            project_runtime_launcher_written and not rolled_back
        )
        runtime_receipt_schema = (
            "wom-kit/project-version-update-receipt/v0.3"
            if project_runtime_plan.get("required")
            else "wom-kit/project-version-update-receipt/v0.2"
        )
        runtime_result = dict(project_runtime_plan)
        runtime_result["preparation_revalidation"] = copy.deepcopy(
            runtime_preparation_revalidation
        )
        if project_runtime_materialization is not None and not rolled_back:
            runtime_result["materialized"] = (
                project_runtime_materialization.public_summary()
            )
        runtime_result["launcher_write_attempted"] = (
            project_runtime_launcher_write_attempted
        )
        runtime_result["launcher_written"] = final_launcher_written
        source_is_target = bool(
            head_after == target_commit
            and target_runtime_source_integrity_verified
        )
        display_receipt_relative = (
            f"{root_label}/{receipt_relative}"
            if receipt_relative and root_label != "inspection_root"
            else receipt_relative
        )
        pin_summaries = [
            {
                "path": spec["logical"],
                "role": spec["role"],
                "existed_before": (
                    spec.get("existed")
                    if type(spec.get("existed")) is bool
                    else None
                ),
                "previous_version": spec.get("previous_version"),
                "target_version": target_tag if WOM_KIT_PROJECT_UPDATE_TAG_RE.fullmatch(target_tag) else None,
                "written": spec["logical"] in final_pins_written,
                "write_attempted": spec["logical"] in pin_write_attempted_paths,
            }
            for spec in pin_specs
        ]
        restart_required = status == "updated_restart_required"
        if status == "blocked":
            next_actions = (
                [
                    "Keep the newly changed source bytes in place and do not reuse the prior approval.",
                    "Pause editors and sync, backup, and other Git processes, then rerun project-version-update in --dry-run mode before a separate approval.",
                ]
                if WOM_KIT_PROJECT_UPDATE_SOURCE_DRIFT_BLOCKER in blockers
                else
                [
                    "Choose a target that is at least every recognized project pin and project source version; the running WOM-kit version is informational only.",
                    "Rerun project-version-update in --dry-run mode before approval.",
                ]
                if forward_only_blocked
                else ["Resolve every blocker before running project-version-update again."]
            )
        elif status == "preview_only_platform_unsupported":
            next_actions = [
                "Review this preview, then run the approved project-version-update from Windows.",
                "Before approval, close editors and pause sync, backup, and other Git processes for the complete transaction, then pass --affirm-external-writers-quiescent.",
            ]
        elif status in {
            "failed_before_mutation",
            "failed_rolled_back",
            "failed_rollback_incomplete",
            "interrupted_rolled_back",
            "interrupted_rollback_incomplete",
        }:
            next_actions = [
                "Do not claim the target runtime is active.",
                (
                    "Preserve the version-update lock and review the source mirror and pins before any retry."
                    if status
                    in {
                        "failed_rollback_incomplete",
                        "interrupted_rollback_incomplete",
                    }
                    else "Review the generic failure or interruption stage, then rerun the dry-run before another approval."
                ),
            ]
        elif status == "no_change":
            next_actions = ["Start a new process and run archive version <project-or-archive-root> --format json."]
        elif restart_required:
            next_actions = [
                "Close this Python process or terminal command invocation.",
                "Start a new process from the project-local source mirror.",
                "Run archive version <project-or-archive-root> --format json and require source, pin, tag, and import-origin agreement.",
            ]
        else:
            next_actions = [
                "Review this preview, then rerun with --approve --reviewed-by <actor> --affirm-external-writers-quiescent.",
                "Pass that affirmation only after editors and sync, backup, and other Git processes are paused for the complete transaction.",
                "Approval will fetch and verify the exact tag before changing the source mirror or pins.",
            ]
        payload = {
            "ok": not blockers
            and status
            not in {
                "failed_before_mutation",
                "failed_rolled_back",
                "failed_rollback_incomplete",
                "interrupted_rolled_back",
                "interrupted_rollback_incomplete",
            },
            "schema": "wom-kit/project-version-update/v0.1",
            "lifecycle_action": "project_version_update",
            "status": status,
            "mode": "approve" if approve else "dry_run",
            "preflight": {
                "state": preflight_state,
                "checks": copy.deepcopy(preflight_checks),
                "private_values_echoed": False,
                "local_paths_echoed": False,
            },
            "target": {
                "tag": target_tag or None,
                "version": target_version,
                **target_evidence,
                "configured_origin_main_ancestry_verified": bool(
                    target_evidence.get("target_reachable_from_origin_main")
                ),
                "cryptographic_tag_signature_verified": False,
            },
            "source_mirror": {
                "path": mirror_logical,
                "git_repo_verified": git_repo_verified,
                "worktree_clean_except_untracked_local_pin": worktree_clean,
                "unexpected_worktree_entry_count": unexpected_worktree_entry_count,
                "unexpected_nonignored_worktree_entry_count": (
                    unexpected_worktree_entry_count
                ),
                "ignored_entries_checked_by_materialization_preflight": (
                    materialization_preflight["evaluated"]
                ),
                "source_mirror_pin_git_tracked": mirror_pin_tracked,
                "origin_configured": origin_configured,
                "origin_url_echoed": False,
                "head_commit_before": head_before,
                "head_commit_after": head_after,
                "source_checkout_change_attempted": source_checkout_changed,
                "source_checkout_is_verified_target": source_is_target,
                "runtime_source_rematerialization_attempted": (
                    runtime_source_rematerialization_attempted
                ),
                "runtime_source_rematerialization_succeeded": (
                    runtime_source_rematerialization_succeeded
                ),
                "target_runtime_source_integrity_verified": (
                    target_runtime_source_integrity_verified
                ),
                "checkout_mode_after_result": (
                    "restored_original"
                    if rolled_back
                    else "detached_exact_tag"
                    if source_is_target
                    else "unchanged"
                ),
            },
            "pins": {
                "target_value": target_tag if WOM_KIT_PROJECT_UPDATE_TAG_RE.fullmatch(target_tag) else None,
                "planned": pin_summaries,
                "written_paths": final_pins_written,
                "write_attempted_paths": list(pin_write_attempted_paths),
            },
            "materialization_preflight": materialization_preflight,
            "project_runtime": runtime_result,
            "forward_only": {
                "comparison_basis": "recognized_project_pins_and_project_source_versions",
                "recognized_project_version_count": len(
                    recognized_project_version_keys
                ),
                "running_runtime_used": False,
                "target_is_at_least_every_recognized_project_version": (
                    forward_only_target_is_at_least_every_project_version
                ),
            },
            "fetch": {
                "remote_name": "origin",
                "atomic_ref_update_requested": True,
                "main_ref": "refs/remotes/origin/main",
                "exact_target_tag_only": True,
                "attempted": fetch_attempted,
                "succeeded": fetch_succeeded,
                "git_transport_called": fetch_attempted,
                "network_may_have_been_called": fetch_attempted,
                "fetched_refs_may_remain_after_result": fetch_succeeded,
                "raw_git_stderr_echoed": False,
                "remote_url_echoed": False,
                "configured_git_transport_may_use_credential_helper": (
                    approve
                    and WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED
                ),
            },
            "receipt": {
                "schema": runtime_receipt_schema,
                "path": display_receipt_relative,
                "written": receipt_written,
            },
            "rollback": rollback,
            "runtime": {
                "running_version_before": WOM_KIT_VERSION,
                "import_origin_within_project_source_mirror": (
                    runtime_import_origin_within_project_source_mirror
                ),
                "used_for_forward_only_decision": False,
                "running_process_reloaded": False,
                "restart_required": restart_required,
                "post_restart_verification_command": (
                    "archive version <project-or-archive-root> --format json"
                    if status in {"updated_restart_required", "no_change"}
                    else None
                ),
            },
            "write_boundary": {
                "approval_platform_supported": (
                    WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED
                ),
                "external_writer_quiescence_required": (
                    WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED
                ),
                "external_writer_quiescence_affirmed": bool(
                    approve and affirm_external_writers_quiescent
                ),
                "atomic_file_compare_and_swap": False,
                "checkpointed_change_detection": True,
                "archive_zets_written": False,
                "archive_objets_written": False,
                "archive_manifests_written": False,
                "provider_state_written": False,
                "project_source_checkout_may_change": (
                    approve
                    and WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED
                ),
                "project_runtime_source_materialization_may_change": (
                    approve
                    and WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED
                ),
                "project_local_runtime_may_change": bool(
                    approve
                    and WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED
                    and project_runtime_plan.get("required")
                ),
                "global_path_or_python_installation_may_change": False,
                "recognized_version_pins_may_change": (
                    approve
                    and WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED
                ),
                "project_update_receipt_may_be_written": (
                    approve
                    and WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED
                ),
            },
            "would_change": (
                []
                if status == "no_change"
                else [
                    f"{mirror_logical} detached checkout to the exact verified target tag",
                    *(
                        [
                            f"{project_runtime_plan['target_path']} exact public-wheel runtime materialized",
                            f"{project_runtime_plan['launcher_path']} project launcher activated",
                        ]
                        if project_runtime_plan.get("required")
                        else []
                    ),
                    "recognized installed-version pins aligned to the target tag",
                    (
                        f"{WOM_KIT_PROJECT_UPDATE_RECEIPTS_RELATIVE}/ one update receipt"
                        if root_label == "inspection_root"
                        else f"{root_label}/{WOM_KIT_PROJECT_UPDATE_RECEIPTS_RELATIVE}/ one update receipt"
                    ),
                ]
            ),
            "files_written": [
                *(
                    [project_runtime_plan["target_path"]]
                    if (
                        project_runtime_materialization is not None
                        and project_runtime_materialization.created
                        and not rolled_back
                    )
                    else []
                ),
                *(
                    [project_runtime_plan["launcher_path"]]
                    if final_launcher_written
                    else []
                ),
                *final_pins_written,
                *([display_receipt_relative] if receipt_written and display_receipt_relative else []),
            ],
            "blockers": unique_preserve_order(blockers),
            "blocker_codes": wom_kit_project_update_blocker_codes(
                unique_preserve_order(blockers)
            ),
            "warnings": unique_preserve_order(warnings),
            "next_safe_actions": next_actions,
            "privacy_guards": {
                "local_absolute_paths_echoed": False,
                "remote_urls_echoed": False,
                "credential_access_may_occur": fetch_attempted,
                "credential_config_values_exposed_to_python_result": False,
                "credential_values_echoed": False,
                "archive_body_text_read": False,
                "objet_bytes_read": False,
            },
        }
        last_result_payload = payload
        return payload

    if blockers:
        if progress_callback is not None:
            progress_callback("project-preflight", "done", None, None)
        return result_payload("blocked")
    if dry_run:
        status = (
            "preview_only_platform_unsupported"
            if not WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED
            else "ready_to_fetch_on_approve"
            if not target_evidence.get("tag_available_locally")
            else "ready_for_approval"
        )
        if progress_callback is not None:
            progress_callback("project-preflight", "done", None, None)
        return result_payload(status)

    if progress_callback is not None:
        progress_callback("project-preflight", "done", None, None)

    directory_guard = _WomKitProjectUpdateDirectoryGuard(project_root)
    guard_ready = bool(
        directory_guard.hold(project_root)
        and directory_guard.hold(metadata_root)
        and directory_guard.hold_existing_tree(mirror_path)
    )
    if (
        guard_ready
        and wom_kit_real_path_kind(project_root, receipts_parent)
        == "directory"
    ):
        guard_ready = directory_guard.hold_existing_tree(receipts_parent)
    if not guard_ready:
        blockers.append(
            "The project update could not hold every existing write-path directory stable against rename or reparse replacement."
        )
        return _project_update_finish_resource_only_result(
            result_payload("blocked"),
            close_owned_resources=directory_guard.close,
        )

    def register_lock_reservation(identity: tuple[int, int]) -> None:
        nonlocal lock_reservation
        lock_reservation = {"identity": identity}

    try:
        if prepare_exact_approval:
            if (
                not isinstance(_expected_approval_root, Path)
                or type(_expected_archive_id) is not str
            ):
                raise ArchiveServiceError(
                    "project_version_update_approval_archive_identity_changed"
                )
            reservation_created_at = (
                datetime.now(timezone.utc)
                .replace(microsecond=0)
                .isoformat()
                .replace("+00:00", "Z")
            )
            project_identity_sha256 = (
                project_update_transaction.sha256_document(
                    {
                        "approval_archive_identity_sha256": (
                            exact_human_approval_archive_identity_sha256(
                                _expected_archive_id
                            )
                        ),
                        "preflight_git_config_sha256": (
                            "sha256:" + str(preflight_git_config_digest)
                        ),
                        "root_label": root_label,
                        "schema": (
                            "wom-kit/project-update-project-identity/v0.4.3"
                        ),
                        "source_head_sha256": (
                            project_update_transaction.sha256_document(
                                {"head": head_before}
                            )
                        ),
                    }
                )
            )
            prepared_legacy_reservation = (
                _legacy_recovery_control.get(
                    "prepared_fresh_reservation"
                )
                if legacy_recovery_mode
                and isinstance(_legacy_recovery_control, Mapping)
                else None
            )
            if legacy_recovery_mode and (
                not isinstance(
                    prepared_legacy_reservation,
                    project_update_transaction.ProjectUpdateReservation,
                )
                or prepared_legacy_reservation.project_identity_sha256
                != project_identity_sha256
                or prepared_legacy_reservation.requested_target_tag
                != target_tag
            ):
                raise ArchiveServiceError(
                    "project_version_update_legacy_recovery_binding_invalid"
                )
            cleanup_classification, _history_count = (
                _project_update_terminal_cleanup_artifact_classification_read_only(
                    project_root
                )
            )
            if not legacy_recovery_mode and cleanup_classification not in {
                "absent",
                "history_only_exact",
            }:
                blockers.append(
                    "A prior project update has unresolved terminal cleanup evidence; no new update lock or writer was entered."
                )
                return _project_update_finish_resource_only_result(
                    result_payload("blocked"),
                    close_owned_resources=directory_guard.close,
                )
            durable_reservation = (
                project_update_transaction.ProjectUpdateTransaction.reserve_or_resume_exact(
                    project_root,
                    reservation=prepared_legacy_reservation,
                )
                if legacy_recovery_mode
                else project_update_transaction.ProjectUpdateTransaction.reserve(
                    project_root,
                    project_identity_sha256=project_identity_sha256,
                    requested_target_tag=target_tag,
                    created_at=reservation_created_at,
                )
            )
            if legacy_recovery_mode:
                fresh_reservation_callback = (
                    _legacy_recovery_control.get(
                        "fresh_reservation_callback"
                    )
                    if isinstance(_legacy_recovery_control, Mapping)
                    else None
                )
                if not callable(fresh_reservation_callback):
                    raise ArchiveServiceError(
                        "project_version_update_legacy_recovery_binding_invalid"
                    )
                fresh_reservation_callback(durable_reservation)
            post_reservation_classification, _history_count = (
                _project_update_terminal_cleanup_artifact_classification_read_only(
                    project_root,
                    allowed_reservation=durable_reservation,
                )
            )
            durable_lock_bytes = durable_reservation.lock_bytes()
            if not legacy_recovery_mode:
                durable_lock_bytes = durable_reservation.acquire_lock()
            lock_acquired = True
            lock_release_state = "held"
            lock_stat = os.lstat(lock_path)
            register_lock_reservation(
                (int(lock_stat.st_dev), int(lock_stat.st_ino))
            )
            post_lock_classification, _history_count = (
                _project_update_terminal_cleanup_artifact_classification_read_only(
                    project_root,
                    allowed_reservation=durable_reservation,
                    allowed_lock_bytes=(
                        _legacy_recovery_old_lock_bytes
                        if legacy_recovery_mode
                        else durable_lock_bytes
                    ),
                )
            )
            if (
                not legacy_recovery_mode
                and (
                    post_reservation_classification != "reservation_exact"
                    or post_lock_classification != "reservation_exact"
                )
            ):
                blockers.append(
                    "The project-update transaction namespace changed at the lock boundary; the exact new reservation was aborted before approval or domain work."
                )
                try:
                    durable_reservation.abort_before_intent_seal(
                        expected_lock_bytes=durable_lock_bytes,
                    )
                except BaseException:
                    preserve_lock = True
                    rollback["attempted"] = True
                    rollback["succeeded"] = False
                    rollback["source_restored"] = True
                    rollback["pins_restored"] = True
                    rollback["lock_removed"] = False
                    return _project_update_finish_resource_only_result(
                        result_payload("failed_rollback_incomplete"),
                        close_owned_resources=directory_guard.close,
                    )
                lock_acquired = False
                lock_release_state = "released"
                lock_release_intent_status = "blocked"
                rollback["attempted"] = True
                rollback["succeeded"] = True
                rollback["source_restored"] = True
                rollback["pins_restored"] = True
                rollback["lock_removed"] = True
                return _project_update_finish_resource_only_result(
                    result_payload("blocked"),
                    close_owned_resources=directory_guard.close,
                )
        else:
            _wom_kit_project_update_acquire_lock_exclusive(
                project_root,
                metadata_root,
                lock_path,
                reservation_callback=register_lock_reservation,
            )
        lock_acquired = True
        lock_release_state = "held"
    except FileExistsError:
        blockers.append("A concurrent project version update acquired the lock first.")
        return _project_update_finish_resource_only_result(
            result_payload("blocked"),
            close_owned_resources=directory_guard.close,
        )
    except WomKitProjectUpdateReceiptUncertainError:
        lock_cleanup = (
            _wom_kit_project_update_reconcile_lock_after_acquire_failure(
                project_root,
                lock_path,
                (
                    lock_reservation.get("identity")
                    if lock_reservation is not None
                    else None
                ),
                expected_lock_bytes=(
                    durable_lock_bytes
                    if isinstance(durable_lock_bytes, bytes)
                    else WOM_KIT_PROJECT_UPDATE_LOCK_BYTES
                ),
                release_owned=False,
            )
        )
        lock_removed = lock_cleanup["lock_removed"]
        lock_acquired = lock_removed is not True
        preserve_lock = bool(lock_cleanup["preserve_lock"])
        rollback["attempted"] = lock_removed is not True
        rollback["succeeded"] = lock_removed is True
        rollback["source_restored"] = True
        rollback["pins_restored"] = True
        rollback["lock_removed"] = lock_removed
        blockers.append(
            "The project version update lock ownership could not be verified; the uncertain path was preserved for review."
            if lock_removed is not True
            else "The project version update lock cleanup was independently verified after an uncertain acquisition failure."
        )
        return _project_update_finish_resource_only_result(
            result_payload(
                "failed_rollback_incomplete"
                if lock_removed is not True
                else "blocked"
            ),
            close_owned_resources=directory_guard.close,
        )
    except OSError:
        lock_cleanup = (
            _wom_kit_project_update_reconcile_lock_after_acquire_failure(
                project_root,
                lock_path,
                (
                    lock_reservation.get("identity")
                    if lock_reservation is not None
                    else None
                ),
                expected_lock_bytes=(
                    durable_lock_bytes
                    if isinstance(durable_lock_bytes, bytes)
                    else WOM_KIT_PROJECT_UPDATE_LOCK_BYTES
                ),
                release_owned=True,
            )
        )
        lock_removed = lock_cleanup["lock_removed"]
        lock_acquired = lock_removed is not True
        preserve_lock = bool(lock_cleanup["preserve_lock"])
        rollback["attempted"] = bool(lock_cleanup["release_attempted"])
        rollback["succeeded"] = lock_removed is True
        rollback["source_restored"] = True
        rollback["pins_restored"] = True
        rollback["lock_removed"] = lock_removed
        blockers.append(
            "The project version update lock could not be created."
            if lock_removed is True
            else "The project version update lock state could not be verified after an acquisition failure; the uncertain path was preserved for review."
        )
        return _project_update_finish_resource_only_result(
            result_payload(
                "blocked"
                if lock_removed is True
                else "failed_rollback_incomplete"
            ),
            close_owned_resources=directory_guard.close,
        )
    except BaseException:
        lock_identity = (
            lock_reservation.get("identity")
            if lock_reservation is not None
            else None
        )
        expected_lock_bytes = (
            durable_lock_bytes
            if isinstance(durable_lock_bytes, bytes)
            else WOM_KIT_PROJECT_UPDATE_LOCK_BYTES
        )
        lock_cleanup = (
            _wom_kit_project_update_reconcile_lock_after_acquire_failure(
                project_root,
                lock_path,
                lock_identity,
                expected_lock_bytes=expected_lock_bytes,
                release_owned=True,
            )
        )
        lock_removed = lock_cleanup["lock_removed"]
        lock_acquired = lock_removed is not True
        preserve_lock = bool(lock_cleanup["preserve_lock"])
        rollback["attempted"] = bool(lock_cleanup["release_attempted"])
        rollback["succeeded"] = lock_removed is True
        rollback["source_restored"] = True
        rollback["pins_restored"] = True
        rollback["lock_removed"] = lock_removed
        blockers.append(
            "The project version update was interrupted while acquiring its lock; an uncertain lock was preserved for review."
            if lock_removed is not True
            else "The project version update was interrupted before local mutation."
        )
        return _project_update_finish_resource_only_result(
            result_payload(
                "interrupted_rollback_incomplete"
                if lock_removed is not True
                else "interrupted_rolled_back"
            ),
            close_owned_resources=directory_guard.close,
        )

    def cleanup_prepared_runtime_bundle_or_raise() -> None:
        nonlocal prepared_runtime_bundle_cleanup_state, preserve_lock
        if prepared_runtime_bundle is None:
            prepared_runtime_bundle_cleanup_state = "not_required"
            rollback["prepared_runtime_bundle_removed"] = True
            return
        if prepared_runtime_bundle_cleanup_state == "verified_absent":
            rollback["prepared_runtime_bundle_removed"] = True
            return
        prepared_runtime_bundle_cleanup_state = "cleaning"
        try:
            removed = project_runtime.cleanup_prepared_runtime_bundle(
                prepared_runtime_bundle
            )
        except BaseException:
            removed = False
        rollback["prepared_runtime_bundle_removed"] = bool(removed)
        if not removed:
            prepared_runtime_bundle_cleanup_state = "uncertain"
            preserve_lock = True
            blockers.append(
                "project_runtime_prepared_bundle_cleanup_unverified"
            )
            raise RuntimeError(
                "project_runtime_prepared_bundle_cleanup_unverified"
            )
        prepared_runtime_bundle_cleanup_state = "verified_absent"

    def release_current_lock_or_raise(intent_status: str) -> None:
        nonlocal lock_acquired, lock_release_intent_status
        nonlocal lock_release_state, preserve_lock
        if not lock_acquired:
            return
        if legacy_recovery_mode:
            # Before the fresh exact plan exists the live public lock still
            # belongs to the immutable predecessor.  Ordinary reservation
            # abort assumes the fresh reservation owns that lock and would
            # therefore either fail or, worse, weaken recovery truth.  Keep
            # every authenticated recovery artifact in place; the phase
            # router will retry the same deterministic pre-plan work.
            preserve_lock = True
            rollback["attempted"] = False
            rollback["succeeded"] = False
            rollback["lock_removed"] = False
            raise ArchiveServiceError(
                "project_version_update_legacy_recovery_state_ambiguous"
            )
        if durable_reservation is not None:
            if durable_approval_state is not None:
                _project_update_cancel_before_native(
                    durable_approval_state
                )
            else:
                cleanup_prepared_runtime_bundle_or_raise()
                if durable_lock_bytes is None:
                    raise RuntimeError(
                        "project_update_transaction_lock_ownership_changed"
                    )
                durable_reservation.abort_before_intent_seal(
                    expected_lock_bytes=durable_lock_bytes,
                )
            lock_release_intent_status = intent_status
            lock_release_state = "released"
            lock_acquired = False
            return
        # Every terminal state removes the exact pre-approval network bundle
        # before releasing the project lock.  Uncertain cleanup preserves the
        # lock for recovery rather than claiming a complete transaction.
        cleanup_prepared_runtime_bundle_or_raise()
        lock_release_intent_status = intent_status
        lock_release_state = "releasing"
        identity = (
            lock_reservation.get("identity")
            if lock_reservation is not None
            else None
        )
        if not _wom_kit_project_update_release_owned_lock(
            project_root,
            lock_path,
            identity,
        ):
            preserve_lock = True
            raise RuntimeError("project_update_lock_ownership_changed")
        lock_release_state = "released"
        lock_acquired = False

    def reserved_receipt_matches() -> bool:
        if (
            receipt_reservation is None
            or receipt_bytes is None
            or not receipt_written
        ):
            return False
        path = receipt_reservation.get("path")
        identity = receipt_reservation.get("identity")
        if not isinstance(path, Path) or not isinstance(identity, tuple):
            return False
        try:
            path_stat = os.lstat(path)
        except OSError:
            return False
        return bool(
            stat.S_ISREG(path_stat.st_mode)
            and len(identity) == 2
            and (
                not identity[0]
                or not path_stat.st_dev
                or identity[0] == path_stat.st_dev
            )
            and (
                not identity[1]
                or not path_stat.st_ino
                or identity[1] == path_stat.st_ino
            )
            and _wom_kit_read_bounded_real_bytes(
                project_root,
                path,
                max_bytes=2 * 1024 * 1024,
            )
            == receipt_bytes
        )

    def unlocked_terminal_state_verified(status: str) -> bool:
        if prepared_runtime_bundle_cleanup_state not in {
            "not_required",
            "verified_absent",
        }:
            return False
        if status in {"blocked", "no_change"}:
            return bool(
                wom_kit_project_update_source_matches_snapshot(
                    project_root,
                    mirror_path,
                    preflight_git_snapshot,
                    runner=git_runner,
                )
                and wom_kit_project_update_all_pins_match_snapshot(
                    project_root,
                    pin_specs,
                )
                and (
                    status == "blocked"
                    or wom_kit_project_update_target_ref_snapshot(
                        mirror_path,
                        target_tag,
                        runner=git_runner,
                    )
                    == trusted_target_ref_snapshot
                )
            )
        if status != "updated_restart_required":
            return False
        target_pin_bytes = (target_tag + "\n").encode("utf-8")
        return bool(
            target_runtime_source_integrity_verified
            and wom_kit_project_update_source_matches_snapshot(
                project_root,
                mirror_path,
                target_git_snapshot,
                runner=git_runner,
            )
            and all(
                _wom_kit_read_bounded_real_bytes(
                    project_root,
                    spec["path"],
                    max_bytes=WOM_KIT_VERSION_PIN_MAX_BYTES,
                )
                == target_pin_bytes
                for spec in pin_specs
            )
            and reserved_receipt_matches()
            and wom_kit_project_update_git_config_trust_digest(
                mirror_path,
                runner=git_runner,
            )
            == preflight_git_config_digest
            and wom_kit_project_update_target_ref_snapshot(
                mirror_path,
                target_tag,
                runner=git_runner,
            )
            == trusted_target_ref_snapshot
        )

    try:
        post_lock_snapshot = _wom_kit_project_update_git_snapshot(
            mirror_path,
            runner=git_runner,
        )
        if (
            preflight_git_snapshot is None
            or post_lock_snapshot != preflight_git_snapshot
            or wom_kit_project_update_git_config_trust_digest(
                mirror_path,
                runner=git_runner,
            )
            != preflight_git_config_digest
            or not wom_kit_project_update_git_metadata_is_local_real(
                project_root,
                mirror_path,
                runner=git_runner,
            )
            or not wom_kit_project_update_all_pins_match_snapshot(
                project_root,
                pin_specs,
            )
        ):
            blockers.append(
                "The project source mirror or a recognized pin changed before the lock boundary; no fetch or project mutation was attempted."
            )
            release_current_lock_or_raise("blocked")
            return result_payload("blocked")
        if progress_callback is not None:
            progress_callback("fetch-release", "start", None, None)
        if (
            wom_kit_project_update_git_config_trust_digest(
                mirror_path,
                runner=git_runner,
            )
            != preflight_git_config_digest
        ):
            blockers.append(
                "The effective configured-origin Git trust settings changed before fetch."
            )
            release_current_lock_or_raise("blocked")
            return result_payload("blocked")
        fetch_attempted = True
        fetch_ok, _ = _wom_kit_project_update_git(
            mirror_path,
            [
                "fetch",
                "--atomic",
                "--quiet",
                "--no-tags",
                "--no-recurse-submodules",
                "--no-auto-maintenance",
                "--no-write-fetch-head",
                "origin",
                "refs/heads/main:refs/remotes/origin/main",
                f"refs/tags/{target_tag}:refs/tags/{target_tag}",
            ],
            timeout_seconds=180,
            allow_transport_environment=True,
            runner=git_runner,
            transport=True,
        )
        fetch_succeeded = fetch_ok
        post_fetch_config_matches = bool(
            wom_kit_project_update_git_config_trust_digest(
                mirror_path,
                runner=git_runner,
            )
            == preflight_git_config_digest
        )
        if progress_callback is not None:
            progress_callback("fetch-release", "done", None, None)
        post_fetch_callback_config_matches = bool(
            wom_kit_project_update_git_config_trust_digest(
                mirror_path,
                runner=git_runner,
            )
            == preflight_git_config_digest
        )
        if not fetch_ok:
            blockers.append("The atomic configured-origin fetch failed; no source checkout or pin write was attempted.")
            release_current_lock_or_raise("blocked")
            return result_payload("blocked")
        if (
            not post_fetch_config_matches
            or not post_fetch_callback_config_matches
        ):
            blockers.append(
                "The effective configured-origin Git trust settings changed during fetch; fetched refs were not trusted or materialized."
            )
            release_current_lock_or_raise("blocked")
            return result_payload("blocked")

        if progress_callback is not None:
            progress_callback("verify-release", "start", None, None)
        target_evidence = wom_kit_project_update_target_evidence(
            mirror_path,
            target_tag,
            runner=git_runner,
        )
        validate_target_evidence(require_local=True, require_origin_ancestry=True)
        refresh_project_runtime_plan(enforce_interpreter=True)
        if project_runtime_policy["state"] == "invalid":
            blockers.append("project_runtime_policy_invalid")
        blockers.extend(project_runtime_plan_blockers)
        warnings.extend(project_runtime_plan_warnings)
        trusted_target_ref_snapshot = (
            wom_kit_project_update_target_ref_snapshot(
                mirror_path,
                target_tag,
                runner=git_runner,
            )
        )
        if (
            trusted_target_ref_snapshot is None
            or trusted_target_ref_snapshot.get("target_commit")
            != target_evidence.get("target_commit")
        ):
            blockers.append(
                "The exact target tag and origin/main ref snapshot could not be bound after fetch."
            )
        if progress_callback is not None:
            progress_callback("verify-release", "done", None, None)
        if blockers:
            release_current_lock_or_raise("blocked")
            return result_payload("blocked")

        before_mutation_snapshot = _wom_kit_project_update_git_snapshot(
            mirror_path,
            runner=git_runner,
        )
        if (
            before_mutation_snapshot != preflight_git_snapshot
            or wom_kit_project_update_git_config_trust_digest(
                mirror_path,
                runner=git_runner,
            )
            != preflight_git_config_digest
            or not wom_kit_project_update_git_metadata_is_local_real(
                project_root,
                mirror_path,
                runner=git_runner,
            )
            or not wom_kit_project_update_all_pins_match_snapshot(
                project_root,
                pin_specs,
            )
            or wom_kit_project_update_target_ref_snapshot(
                mirror_path,
                target_tag,
                runner=git_runner,
            )
            != trusted_target_ref_snapshot
            or (
                original_branch is not None
                and (
                    head_before is None
                    or not wom_kit_project_update_branch_points_to_commit(
                        mirror_path,
                        original_branch,
                        head_before,
                        runner=git_runner,
                    )
                )
            )
        ):
            blockers.append(
                "The project source mirror or a recognized pin changed after fetch but before local mutation."
            )
            release_current_lock_or_raise("blocked")
            return result_payload("blocked")

        target_commit = str(target_evidence["target_commit"])
        pins_already_target = all(spec.get("previous_version") == target_tag for spec in pin_specs)
        materialization_preflight = (
            wom_kit_project_update_materialization_preflight(
                project_root,
                mirror_path,
                target_commit=target_commit,
                head_before=head_before,
                original_branch=original_branch,
                runner=git_runner,
            )
        )
        target_runtime_source_integrity_verified = bool(
            materialization_preflight[
                "target_runtime_source_integrity_verified"
            ]
        )
        checkout_required = bool(
            materialization_preflight["checkout_required"]
        )
        rematerialization_required = bool(
            materialization_preflight["required"]
        )
        if (
            rematerialization_required
            and materialization_preflight["state"] == "blocked"
        ):
            blockers.append(
                WOM_KIT_PROJECT_UPDATE_MATERIALIZATION_BLOCKER
            )
            release_current_lock_or_raise("blocked")
            return result_payload("blocked")
        if (
            head_before == target_commit
            and pins_already_target
            and target_runtime_source_integrity_verified
            and not checkout_required
            and not project_runtime_plan.get("required")
        ):
            head_after = head_before
            release_current_lock_or_raise("no_change")
            return result_payload("no_change")

        # Runtime bytes are prepared only after the fetched tag, origin ref,
        # target policy/supply/bootstrap, interpreter lock, source/pins, and
        # materialization preflight are all exact and blocker-free.  The
        # resulting content-free summary becomes part of the plan that is
        # snapshotted for native approval below; no later plan refresh may
        # overwrite it.
        if prepare_exact_approval and project_runtime_plan.get("required"):
            if (
                project_runtime_bootstrap is None
                or project_runtime_supply is None
                or durable_reservation is None
            ):
                blockers.append(
                    "project_runtime_exact_public_supply_required"
                )
                release_current_lock_or_raise("blocked")
                return result_payload("blocked")
            try:
                prepared_runtime_bundle = (
                    project_runtime.prepare_runtime_candidate(
                        project_root,
                        durable_reservation.transaction_root,
                        target=target_version or "",
                        target_commit=target_commit,
                        bootstrap=project_runtime_bootstrap,
                        supply=project_runtime_supply,
                        running_version=WOM_KIT_VERSION,
                        receipt_created_at=durable_reservation.created_at,
                        progress_callback=progress_callback,
                    )
                )
                prepared_runtime_bundle_cleanup_state = "pending"
                prepared_runtime_bundle_summary = dict(
                    prepared_runtime_bundle.public_summary()
                )
            except project_runtime.PreparedRuntimeBundleCleanupError:
                prepared_runtime_bundle_cleanup_state = "uncertain"
                rollback["prepared_runtime_bundle_removed"] = False
                preserve_lock = True
                raise
            except project_runtime.PreparedRuntimeCandidateIncompleteError as failure:
                prepared_runtime_bundle_cleanup_state = "uncertain"
                rollback["prepared_runtime_bundle_removed"] = False
                preserve_lock = True
                blockers.append(str(failure))
                raise
            except project_runtime.ProjectRuntimeError as failure:
                blockers.append(str(failure))
                release_current_lock_or_raise("blocked")
                return result_payload("blocked")
            project_runtime_plan["runtime_candidate"] = copy.deepcopy(
                prepared_runtime_bundle_summary
            )

            # Bundle preparation may perform bounded downloads for long enough
            # that another process can change the source, pins, refs, policy,
            # runtime candidate, or launcher.  Recompute every approved input
            # now so a stale plan never reaches the native dialog merely to be
            # rejected by the post-approval drift check.
            post_bundle_target_evidence = (
                wom_kit_project_update_target_evidence(
                    mirror_path,
                    target_tag,
                    runner=git_runner,
                )
            )
            post_bundle_ref_observation = (
                wom_kit_project_update_target_ref_snapshot_observation(
                    mirror_path,
                    target_tag,
                    runner=git_runner,
                )
            )
            post_bundle_ref_snapshot = post_bundle_ref_observation.get(
                "snapshot"
            )
            post_bundle_runtime_policy = (
                wom_kit_project_update_runtime_policy(
                    mirror_path,
                    target_commit,
                    runner=git_runner,
                )
            )
            (
                post_bundle_runtime_policy_state,
                post_bundle_runtime_policy_reason,
            ) = _wom_kit_project_update_policy_observation(
                post_bundle_runtime_policy
            )
            (
                post_bundle_runtime_supply_state,
                post_bundle_runtime_supply_reason,
                post_bundle_runtime_supply,
            ) = _wom_kit_project_update_runtime_supply_revalidation_observation(
                    mirror_path,
                    target_commit,
                    target_version,
                    post_bundle_runtime_policy,
                    runner=git_runner,
            )
            (
                post_bundle_bootstrap,
                post_bundle_bootstrap_summary,
            ) = project_runtime.bootstrap_wheel_for_target(
                target_version or ""
            )
            (
                post_bundle_runtime_plan,
                post_bundle_runtime_blockers,
                _post_bundle_runtime_warnings,
            ) = project_runtime.plan_runtime(
                project_root,
                target_version or "",
                policy_state=str(post_bundle_runtime_policy["state"]),
                target_commit=target_commit,
                bootstrap=post_bundle_bootstrap,
                bootstrap_summary=post_bundle_bootstrap_summary,
                supply=post_bundle_runtime_supply,
                enforce_interpreter=True,
            )
            post_bundle_runtime_plan["policy"] = dict(
                post_bundle_runtime_policy
            )
            post_bundle_runtime_plan["runtime_candidate"] = copy.deepcopy(
                prepared_runtime_bundle_summary
            )
            post_bundle_launcher_snapshot = (
                project_runtime.launcher_snapshot(
                    project_root,
                    target_version or "",
                )
            )
            post_bundle_materialization_preflight = (
                wom_kit_project_update_materialization_preflight(
                    project_root,
                    mirror_path,
                    target_commit=target_commit,
                    head_before=head_before,
                    original_branch=original_branch,
                    runner=git_runner,
                )
            )
            (
                prepared_runtime_payload_state,
                prepared_runtime_payload_reason,
                post_bundle_live_observation,
            ) = project_runtime.verify_prepared_runtime_candidate_observation(
                prepared_runtime_bundle,
                project_root=project_root,
                target=target_version or "",
                target_commit=target_commit,
                bootstrap=project_runtime_bootstrap,
                supply=project_runtime_supply,
            )
            post_bundle_live_summary = (
                dict(post_bundle_live_observation)
                if post_bundle_live_observation is not None
                else {}
            )
            if post_bundle_live_summary:
                post_bundle_live_summary.pop(
                    "static_reverified",
                    None,
                )

            post_bundle_git_snapshot = _wom_kit_project_update_git_snapshot(
                mirror_path,
                runner=git_runner,
            )
            post_bundle_git_config_digest = (
                wom_kit_project_update_git_config_trust_digest(
                    mirror_path,
                    runner=git_runner,
                )
            )
            post_bundle_git_metadata_evidence = (
                wom_kit_project_update_git_metadata_evidence(
                    project_root,
                    mirror_path,
                    runner=git_runner,
                )
            )
            post_bundle_pins_observation = (
                wom_kit_project_update_all_pins_snapshot_observation(
                    project_root,
                    pin_specs,
                )
            )
            post_bundle_branch_observation = (
                {"state": "passed", "reason_code": "not_applicable"}
                if original_branch is None
                else wom_kit_project_update_branch_observation(
                        mirror_path,
                        original_branch,
                        head_before or "",
                        runner=git_runner,
                    )
            )

            def preparation_check(
                name: str,
                matches: bool,
                *,
                available: bool = True,
                reason_code: str | None = None,
            ) -> tuple[str, str]:
                return _wom_kit_project_update_preparation_check(
                    name,
                    matches,
                    available=available,
                    reason_code=reason_code,
                )

            def observed_preparation_check(
                name: str,
                observation_state: str,
                observation_reason_code: str,
                matches: bool,
            ) -> tuple[str, str]:
                return _wom_kit_project_update_observed_preparation_check(
                    name,
                    observation_state,
                    observation_reason_code,
                    matches,
                )

            post_runtime_plan_state, post_runtime_plan_reason = (
                _wom_kit_project_update_runtime_plan_observation_state(
                    post_bundle_runtime_blockers,
                    prerequisite_states=(
                        _wom_kit_project_update_runtime_plan_prerequisite_states(
                            policy_state=post_bundle_runtime_policy_state,
                            supply_state=post_bundle_runtime_supply_state,
                            bootstrap_available=(
                                post_bundle_bootstrap is not None
                            ),
                            launcher_state=str(
                                post_bundle_launcher_snapshot.get(
                                    "observation_state", "unavailable"
                                )
                            ),
                        )
                    ),
                )
            )

            runtime_preparation_revalidation = (
                wom_kit_project_update_runtime_preparation_revalidation(
                    {
                        "git_snapshot": preparation_check(
                            "git_snapshot",
                            post_bundle_git_snapshot == preflight_git_snapshot,
                            available=post_bundle_git_snapshot is not None,
                        ),
                        "git_config_trust": preparation_check(
                            "git_config_trust",
                            post_bundle_git_config_digest
                            == preflight_git_config_digest,
                            available=post_bundle_git_config_digest is not None,
                        ),
                        "git_metadata": preparation_check(
                            "git_metadata",
                            post_bundle_git_metadata_evidence["state"]
                            == "passed",
                            available=(
                                post_bundle_git_metadata_evidence["state"]
                                != "unavailable"
                            ),
                            reason_code=str(
                                post_bundle_git_metadata_evidence[
                                    "reason_code"
                                ]
                            ),
                        ),
                        "version_pins": observed_preparation_check(
                            "version_pins",
                            str(post_bundle_pins_observation["state"]),
                            str(post_bundle_pins_observation["reason_code"]),
                            post_bundle_pins_observation["state"] == "passed",
                        ),
                        "target_refs": observed_preparation_check(
                            "target_refs",
                            str(post_bundle_ref_observation["state"]),
                            str(post_bundle_ref_observation["reason_code"]),
                            post_bundle_ref_snapshot
                            == trusted_target_ref_snapshot,
                        ),
                        "target_evidence": observed_preparation_check(
                            "target_evidence",
                            str(
                                post_bundle_target_evidence.get(
                                    "observation_state", "unavailable"
                                )
                            ),
                            str(
                                post_bundle_target_evidence.get(
                                    "observation_reason_code",
                                    "project_target_evidence_unavailable",
                                )
                            ),
                            post_bundle_target_evidence == target_evidence,
                        ),
                        "runtime_policy": observed_preparation_check(
                            "runtime_policy",
                            post_bundle_runtime_policy_state,
                            post_bundle_runtime_policy_reason,
                            post_bundle_runtime_policy
                            == project_runtime_policy,
                        ),
                        "runtime_supply": observed_preparation_check(
                            "runtime_supply",
                            post_bundle_runtime_supply_state,
                            post_bundle_runtime_supply_reason,
                            post_bundle_runtime_supply
                            == project_runtime_supply,
                        ),
                        "runtime_bootstrap": preparation_check(
                            "runtime_bootstrap",
                            post_bundle_bootstrap
                            == project_runtime_bootstrap
                            and post_bundle_bootstrap_summary
                            == project_runtime_bootstrap_summary,
                            available=post_bundle_bootstrap is not None,
                        ),
                        "runtime_plan": observed_preparation_check(
                            "runtime_plan",
                            post_runtime_plan_state,
                            post_runtime_plan_reason,
                            post_bundle_runtime_plan == project_runtime_plan,
                        ),
                        "launcher": observed_preparation_check(
                            "launcher",
                            str(
                                post_bundle_launcher_snapshot.get(
                                    "observation_state", "unavailable"
                                )
                            ),
                            str(
                                post_bundle_launcher_snapshot.get(
                                    "observation_reason_code",
                                    "project_runtime_launcher_observation_unavailable",
                                )
                            ),
                            post_bundle_launcher_snapshot
                            == project_runtime_launcher_snapshot,
                        ),
                        "materialization_preflight": observed_preparation_check(
                            "materialization_preflight",
                            str(
                                post_bundle_materialization_preflight.get(
                                    "observation_state", "unavailable"
                                )
                            ),
                            str(
                                post_bundle_materialization_preflight.get(
                                    "observation_reason_code",
                                    "project_materialization_preflight_unavailable",
                                )
                            ),
                            post_bundle_materialization_preflight
                            == materialization_preflight,
                        ),
                        "prepared_runtime_payload": observed_preparation_check(
                            "prepared_runtime_payload",
                            prepared_runtime_payload_state,
                            prepared_runtime_payload_reason,
                            post_bundle_live_summary
                            == prepared_runtime_bundle_summary,
                        ),
                        "source_branch": observed_preparation_check(
                            "source_branch",
                            str(post_bundle_branch_observation["state"]),
                            str(post_bundle_branch_observation["reason_code"]),
                            post_bundle_branch_observation["state"] == "passed",
                        ),
                    }
                )
            )
            post_bundle_state_still_exact = bool(
                runtime_preparation_revalidation["state"] == "passed"
            )
            if not post_bundle_state_still_exact:
                blockers.append(
                    "project_version_update_state_changed_during_runtime_preparation"
                )
                try:
                    _project_update_abort_unsealed_candidate(
                        reservation=durable_reservation,
                        expected_lock_bytes=durable_lock_bytes,
                        candidate=prepared_runtime_bundle,
                    )
                except BaseException:
                    prepared_runtime_bundle_cleanup_state = "uncertain"
                    rollback["prepared_runtime_bundle_removed"] = False
                    preserve_lock = True
                    raise
                prepared_runtime_bundle_cleanup_state = "verified_absent"
                rollback["prepared_runtime_bundle_removed"] = True
                prepared_runtime_bundle = None
                lock_acquired = False
                lock_release_state = "released"
                return result_payload("blocked")

            # A required project runtime is a policy invariant, not proof that
            # this invocation still has a domain change to make.  Only the
            # complete pre-native candidate can prove the existing runtime is
            # byte-for-byte reusable.  Once that proof is available, an exact
            # source/pin/launcher target is a true no-op: remove the transient
            # candidate, durably abort the still-unsealed reservation, and do
            # not open a second native approval or write another receipt.
            if (
                head_before == target_commit
                and pins_already_target
                and target_runtime_source_integrity_verified
                and not checkout_required
                and prepared_runtime_bundle.existing_runtime_reusable
                and bool(
                    project_runtime_launcher_snapshot.get("already_target")
                )
            ):
                try:
                    _project_update_abort_unsealed_candidate(
                        reservation=durable_reservation,
                        expected_lock_bytes=durable_lock_bytes,
                        candidate=prepared_runtime_bundle,
                    )
                except BaseException:
                    prepared_runtime_bundle_cleanup_state = "uncertain"
                    rollback["prepared_runtime_bundle_removed"] = False
                    preserve_lock = True
                    raise
                prepared_runtime_bundle_cleanup_state = "verified_absent"
                rollback["prepared_runtime_bundle_removed"] = True
                lock_acquired = False
                lock_release_state = "released"
                head_after = head_before
                installed_summary = copy.deepcopy(
                    project_runtime_plan.get("installed", {})
                )
                installed_summary.update(
                    {
                        "status": "verified",
                        "verified": True,
                        "verification_basis": (
                            "sealed_candidate_equivalence_and_live_existing_runtime_verification"
                        ),
                        "live_reverification_required_before_reuse": False,
                    }
                )
                project_runtime_plan.update(
                    {
                        "installed": installed_summary,
                        "materialization_required": False,
                        "runtime_creation_required": False,
                        "live_reverification_required": False,
                    }
                )
                project_runtime_plan.pop("runtime_candidate", None)
                prepared_runtime_bundle = None
                return result_payload("no_change")

        if prepare_exact_approval:
            if (
                not project_runtime_plan.get("required")
                or not isinstance(
                    prepared_runtime_bundle,
                    project_runtime.PreparedRuntimeCandidate,
                )
                or project_runtime_bootstrap is None
                or project_runtime_supply is None
                or project_runtime_launcher_snapshot is None
                or durable_reservation is None
                or durable_lock_bytes is None
                or not isinstance(_expected_approval_root, Path)
                or type(_expected_archive_id) is not str
                or target_version is None
                or head_before is None
                or preflight_git_snapshot is None
                or preflight_git_config_digest is None
                or trusted_target_ref_snapshot is None
                or directory_guard is None
                or reviewer is None
            ):
                blockers.append(
                    "project_version_update_durable_transaction_inputs_invalid"
                )
                release_current_lock_or_raise("blocked")
                return result_payload("blocked")
            prepared_preview_base = result_payload(
                "ready_for_approval"
            )
            durable_approval_state = _project_update_prepare_durable_state(
                inspection_root=inspection,
                project_root=project_root,
                mirror_path=mirror_path,
                mirror_logical=mirror_logical,
                target_tag=target_tag,
                target_version=target_version,
                target_commit=target_commit,
                reviewer=reviewer,
                expected_approval_root=_expected_approval_root,
                expected_archive_id=_expected_archive_id,
                reservation=durable_reservation,
                expected_lock_bytes=durable_lock_bytes,
                runner=git_runner,
                runtime_candidate=prepared_runtime_bundle,
                runtime_bootstrap=project_runtime_bootstrap,
                runtime_supply=project_runtime_supply,
                runtime_policy=project_runtime_policy,
                runtime_plan=project_runtime_plan,
                directory_guard=directory_guard,
                preflight_git_snapshot=preflight_git_snapshot,
                preflight_git_config_digest=preflight_git_config_digest,
                target_ref_snapshot=trusted_target_ref_snapshot,
                target_evidence=target_evidence,
                materialization_preflight=materialization_preflight,
                head_before=head_before,
                pin_specs=pin_specs,
                launcher_snapshot=project_runtime_launcher_snapshot,
                prepared_preview_base=prepared_preview_base,
                legacy_prewrite_recovery=(
                    _legacy_recovery_approval_summary
                    if legacy_recovery_mode
                    else None
                ),
            )
            if legacy_recovery_mode:
                # This is a shallow private handoff on purpose: callbacks and
                # authenticated store handles are not serializable and must
                # never enter the durable/public plan.  The exact content-free
                # approval summary was sealed separately above.
                durable_approval_state.legacy_prewrite_recovery_control = (
                    dict(_legacy_recovery_control)
                )
            # This is the permanent transport boundary.  Every later Git
            # process is the held absolute executable and local plumbing only.
            git_runner.close_transport_boundary()
            prepared_preview = _project_update_build_prepared_preview(
                durable_approval_state
            )
            durable_approval_state.prepared_preview = copy.deepcopy(
                prepared_preview
            )
            # From this assignment onward the sealed transaction and the
            # driver own recovery.  Closing this legacy generator must never
            # enter its historical rollback path after a durable component
            # failure or after successful terminal finalization.
            durable_handoff_complete = True
            yield _ProjectVersionUpdatePreparedApproval(
                preview=copy.deepcopy(prepared_preview),
                state=durable_approval_state,
            )
            # The driver owns the closures and never resumes this generator.
            # Reaching this line means an invalid second continuation attempt.
            raise ArchiveServiceError(
                "project_version_update_approval_continuation_reused"
            )

            if not _wom_kit_project_version_update_approval_authority_matches(
                inspection_root,
                expected_root=_expected_approval_root,
                expected_archive_id=_expected_archive_id,
            ):
                blockers.append(
                    "project_version_update_approval_archive_identity_changed"
                )
                release_current_lock_or_raise("blocked")
                return result_payload("blocked")
            prepared_ref_snapshot = copy.deepcopy(
                trusted_target_ref_snapshot
            )
            prepared_target_evidence = copy.deepcopy(target_evidence)
            prepared_runtime_policy = copy.deepcopy(project_runtime_policy)
            prepared_runtime_supply = project_runtime_supply
            prepared_runtime_plan = copy.deepcopy(project_runtime_plan)
            prepared_bootstrap = project_runtime_bootstrap
            prepared_bootstrap_summary = copy.deepcopy(
                project_runtime_bootstrap_summary
            )
            prepared_materialization_preflight = copy.deepcopy(
                materialization_preflight
            )
            transaction_nonce_sha256 = (
                "sha256:"
                + hashlib.sha256(secrets.token_bytes(32)).hexdigest()
            )
            # This is the last Git transport boundary before native review.
            # The same held executable remains available for local-only claim,
            # mutation, rollback, and claim-finalization checks.
            git_runner.close_transport_boundary()
            trusted_git_runner_summary = dict(
                git_runner.public_summary()
            )
            prepared_preview = result_payload("ready_for_approval")
            prepared_preview["mode"] = "approval_prepared"
            prepared_preview["approval_preparation"] = {
                "lock_held": True,
                "network_complete": True,
                "post_approval_network_allowed": False,
                "transaction_nonce_sha256": transaction_nonce_sha256,
                "target_ref_snapshot": copy.deepcopy(
                    prepared_ref_snapshot
                ),
                "preapproval_control_writes_completed": True,
                "preapproval_domain_writes_completed": False,
                "fetched_refs_may_change": True,
                "trusted_git_runner": trusted_git_runner_summary,
            }
            prepared_preview["fetch"]["phase"] = (
                "before_native_approval"
            )
            prepared_preview["write_boundary"][
                "post_approval_network_allowed"
            ] = False
            prepared_preview["write_boundary"][
                "project_update_lock_acquired"
            ] = True
            prepared_preview["write_boundary"][
                "preapproval_control_writes_completed"
            ] = True
            prepared_preview["write_boundary"][
                "preapproval_domain_writes_completed"
            ] = False
            prepared_preview["write_boundary"][
                "fetched_refs_may_change"
            ] = True

            approval_request = yield copy.deepcopy(prepared_preview)
            if not isinstance(approval_request, Mapping):
                raise ArchiveServiceError(
                    "project_version_update_approval_continuation_invalid"
                )
            claim = approval_request.get("claim")
            expected_plan_sha256 = approval_request.get(
                "expected_plan_sha256"
            )
            expected_target_binding_sha256 = approval_request.get(
                "expected_target_binding_sha256"
            )
            if (
                not isinstance(claim, _ClaimedExactHumanApproval)
                or type(expected_plan_sha256) is not str
                or type(expected_target_binding_sha256) is not str
            ):
                raise ArchiveServiceError(
                    "project_version_update_approval_continuation_invalid"
                )
            if not _wom_kit_project_version_update_approval_authority_matches(
                inspection_root,
                expected_root=_expected_approval_root,
                expected_archive_id=_expected_archive_id,
            ):
                blockers.append(
                    "project_version_update_approval_archive_identity_changed"
                )
                release_current_lock_or_raise("blocked")
                return result_payload("blocked")
            prepared_binding = project_version_update_approval_binding(
                prepared_preview
            )
            approval_root = _expected_approval_root
            if not isinstance(approval_root, Path):
                raise ArchiveServiceError(
                    "project_version_update_approval_archive_identity_changed"
                )
            operation_exact_human_approval = (
                _require_exact_human_operation_approval(
                    approval_root,
                    prepared_binding,
                    reviewer_claim=reviewer or "",
                    expected_plan_sha256=expected_plan_sha256,
                    expected_target_binding_sha256=(
                        expected_target_binding_sha256
                    ),
                    claim=claim,
                    expected_archive_id=_expected_archive_id,
                )
            )

            current_ref_observation = (
                wom_kit_project_update_target_ref_snapshot_observation(
                    mirror_path,
                    target_tag,
                    runner=git_runner,
                )
            )
            current_ref_snapshot = current_ref_observation.get("snapshot")
            current_target_evidence = (
                wom_kit_project_update_target_evidence(
                    mirror_path,
                    target_tag,
                    runner=git_runner,
                )
            )
            current_runtime_policy = (
                wom_kit_project_update_runtime_policy(
                    mirror_path,
                    target_commit,
                    runner=git_runner,
                )
            )
            (
                current_runtime_policy_state,
                current_runtime_policy_reason,
            ) = _wom_kit_project_update_policy_observation(
                current_runtime_policy
            )
            (
                current_runtime_supply_state,
                current_runtime_supply_reason,
                current_runtime_supply,
            ) = _wom_kit_project_update_runtime_supply_revalidation_observation(
                    mirror_path,
                    target_commit,
                    target_version,
                    current_runtime_policy,
                    runner=git_runner,
            )
            current_bootstrap, current_bootstrap_summary = (
                project_runtime.bootstrap_wheel_for_target(
                    target_version or ""
                )
            )
            current_runtime_plan, current_runtime_blockers, _ = (
                project_runtime.plan_runtime(
                    project_root,
                    target_version or "",
                    policy_state=str(current_runtime_policy["state"]),
                    target_commit=target_commit,
                    bootstrap=current_bootstrap,
                    bootstrap_summary=current_bootstrap_summary,
                    supply=current_runtime_supply,
                    enforce_interpreter=True,
                )
            )
            current_runtime_plan["policy"] = copy.deepcopy(
                current_runtime_policy
            )
            current_bundle_observation_state = "passed"
            current_bundle_observation_reason = "not_applicable"
            if prepared_runtime_bundle is not None:
                if current_bootstrap is None or current_runtime_supply is None:
                    current_bundle_summary = {}
                    current_bundle_observation_state = "unavailable"
                    current_bundle_observation_reason = (
                        "runtime_preparation_prepared_runtime_payload_unavailable"
                    )
                else:
                    (
                        current_bundle_observation_state,
                        current_bundle_observation_reason,
                        current_bundle_observation,
                    ) = (
                        project_runtime
                        .verify_prepared_runtime_candidate_observation(
                            prepared_runtime_bundle,
                            project_root=project_root,
                            target=target_version or "",
                            target_commit=target_commit,
                            bootstrap=current_bootstrap,
                            supply=current_runtime_supply,
                        )
                    )
                    live_bundle_summary = (
                        dict(current_bundle_observation)
                        if current_bundle_observation is not None
                        else {}
                    )
                    if live_bundle_summary:
                        live_bundle_summary.pop("static_reverified", None)
                    current_bundle_summary = (
                        live_bundle_summary
                        if live_bundle_summary
                        == prepared_runtime_bundle_summary
                        else {}
                    )
                current_runtime_plan["prepared_bundle"] = copy.deepcopy(
                    current_bundle_summary
                )
                if (
                    current_bundle_observation_state == "passed"
                    and not current_bundle_summary
                ):
                    current_bundle_observation_state = "failed"
                    current_bundle_observation_reason = (
                        "runtime_preparation_prepared_runtime_payload_changed"
                    )
            current_materialization_preflight = (
                wom_kit_project_update_materialization_preflight(
                    project_root,
                    mirror_path,
                    target_commit=target_commit,
                    head_before=head_before,
                    original_branch=original_branch,
                    runner=git_runner,
                )
            )
            current_launcher_snapshot = project_runtime.launcher_snapshot(
                project_root,
                target_version or "",
            )
            current_git_snapshot = _wom_kit_project_update_git_snapshot(
                mirror_path,
                runner=git_runner,
            )
            current_git_config_digest = (
                wom_kit_project_update_git_config_trust_digest(
                    mirror_path,
                    runner=git_runner,
                )
            )
            current_git_metadata_evidence = (
                wom_kit_project_update_git_metadata_evidence(
                    project_root,
                    mirror_path,
                    runner=git_runner,
                )
            )
            current_pins_observation = (
                wom_kit_project_update_all_pins_snapshot_observation(
                    project_root,
                    pin_specs,
                )
            )
            current_branch_observation = (
                {"state": "passed", "reason_code": "not_applicable"}
                if original_branch is None
                else wom_kit_project_update_branch_observation(
                    mirror_path,
                    original_branch,
                    head_before or "",
                    runner=git_runner,
                )
            )
            current_runtime_plan_state, current_runtime_plan_reason = (
                _wom_kit_project_update_runtime_plan_observation_state(
                    current_runtime_blockers,
                    prerequisite_states=(
                        _wom_kit_project_update_runtime_plan_prerequisite_states(
                            policy_state=current_runtime_policy_state,
                            supply_state=current_runtime_supply_state,
                            bootstrap_available=current_bootstrap is not None,
                            launcher_state=str(
                                current_launcher_snapshot.get(
                                    "observation_state", "unavailable"
                                )
                            ),
                        )
                    ),
                )
            )
            runtime_preparation_revalidation = (
                wom_kit_project_update_runtime_preparation_revalidation(
                    {
                        "git_snapshot": (
                            _wom_kit_project_update_preparation_check(
                                "git_snapshot",
                                current_git_snapshot == preflight_git_snapshot,
                                available=current_git_snapshot is not None,
                            )
                        ),
                        "git_config_trust": (
                            _wom_kit_project_update_preparation_check(
                                "git_config_trust",
                                current_git_config_digest
                                == preflight_git_config_digest,
                                available=current_git_config_digest is not None,
                            )
                        ),
                        "git_metadata": (
                            _wom_kit_project_update_observed_preparation_check(
                                "git_metadata",
                                str(current_git_metadata_evidence["state"]),
                                str(
                                    current_git_metadata_evidence[
                                        "reason_code"
                                    ]
                                ),
                                current_git_metadata_evidence["state"]
                                == "passed",
                            )
                        ),
                        "version_pins": (
                            _wom_kit_project_update_observed_preparation_check(
                                "version_pins",
                                str(current_pins_observation["state"]),
                                str(current_pins_observation["reason_code"]),
                                current_pins_observation["state"] == "passed",
                            )
                        ),
                        "target_refs": (
                            _wom_kit_project_update_observed_preparation_check(
                                "target_refs",
                                str(current_ref_observation["state"]),
                                str(current_ref_observation["reason_code"]),
                                current_ref_snapshot == prepared_ref_snapshot,
                            )
                        ),
                        "target_evidence": (
                            _wom_kit_project_update_observed_preparation_check(
                                "target_evidence",
                                str(
                                    current_target_evidence.get(
                                        "observation_state", "unavailable"
                                    )
                                ),
                                str(
                                    current_target_evidence.get(
                                        "observation_reason_code",
                                        "project_target_evidence_unavailable",
                                    )
                                ),
                                current_target_evidence
                                == prepared_target_evidence,
                            )
                        ),
                        "runtime_policy": (
                            _wom_kit_project_update_observed_preparation_check(
                                "runtime_policy",
                                current_runtime_policy_state,
                                current_runtime_policy_reason,
                                current_runtime_policy
                                == prepared_runtime_policy,
                            )
                        ),
                        "runtime_supply": (
                            _wom_kit_project_update_observed_preparation_check(
                                "runtime_supply",
                                current_runtime_supply_state,
                                current_runtime_supply_reason,
                                current_runtime_supply
                                == prepared_runtime_supply,
                            )
                        ),
                        "runtime_bootstrap": (
                            _wom_kit_project_update_preparation_check(
                                "runtime_bootstrap",
                                current_bootstrap == prepared_bootstrap
                                and current_bootstrap_summary
                                == prepared_bootstrap_summary,
                                available=current_bootstrap is not None,
                            )
                        ),
                        "runtime_plan": (
                            _wom_kit_project_update_observed_preparation_check(
                                "runtime_plan",
                                current_runtime_plan_state,
                                current_runtime_plan_reason,
                                current_runtime_plan == prepared_runtime_plan,
                            )
                        ),
                        "launcher": (
                            _wom_kit_project_update_observed_preparation_check(
                                "launcher",
                                str(
                                    current_launcher_snapshot.get(
                                        "observation_state", "unavailable"
                                    )
                                ),
                                str(
                                    current_launcher_snapshot.get(
                                        "observation_reason_code",
                                        "project_runtime_launcher_observation_unavailable",
                                    )
                                ),
                                current_launcher_snapshot
                                == project_runtime_launcher_snapshot,
                            )
                        ),
                        "materialization_preflight": (
                            _wom_kit_project_update_observed_preparation_check(
                                "materialization_preflight",
                                str(
                                    current_materialization_preflight.get(
                                        "observation_state", "unavailable"
                                    )
                                ),
                                str(
                                    current_materialization_preflight.get(
                                        "observation_reason_code",
                                        "project_materialization_preflight_unavailable",
                                    )
                                ),
                                current_materialization_preflight
                                == prepared_materialization_preflight,
                            )
                        ),
                        "prepared_runtime_payload": (
                            _wom_kit_project_update_observed_preparation_check(
                                "prepared_runtime_payload",
                                current_bundle_observation_state,
                                current_bundle_observation_reason,
                                (
                                    prepared_runtime_bundle is None
                                    or bool(current_bundle_summary)
                                ),
                            )
                        ),
                        "source_branch": (
                            _wom_kit_project_update_observed_preparation_check(
                                "source_branch",
                                str(current_branch_observation["state"]),
                                str(
                                    current_branch_observation["reason_code"]
                                ),
                                current_branch_observation["state"]
                                == "passed",
                            )
                        ),
                    }
                )
            )
            lock_identity = (
                lock_reservation.get("identity")
                if lock_reservation is not None
                else None
            )
            prepared_lock_observation = (
                wom_kit_project_update_owned_lock_observation(
                    project_root,
                    lock_path,
                    lock_identity,
                    expected_lock_bytes=(
                        durable_lock_bytes
                        if durable_lock_bytes is not None
                        else WOM_KIT_PROJECT_UPDATE_LOCK_BYTES
                    ),
                )
            )
            prepared_revalidation_failure = (
                _wom_kit_project_update_approved_lock_failure_code(
                    (prepared_lock_observation,)
                )
                or _wom_kit_project_update_revalidation_failure_code(
                    runtime_preparation_revalidation
                )
            )
            if prepared_revalidation_failure is not None:
                blockers.append(prepared_revalidation_failure)
                release_current_lock_or_raise("blocked")
                return result_payload("blocked")

        if progress_callback is not None:
            progress_callback("checkout-release", "start", None, None)
        if rematerialization_required:
            runtime_source_rematerialization_attempted = True
            runtime_source_rematerialization_succeeded = False
            try:
                materialization_succeeded = (
                    _wom_kit_project_update_materialize_commit(
                        mirror_path,
                        target_commit,
                        directory_guard=directory_guard,
                        project_root=project_root,
                        expected_source_snapshot=preflight_git_snapshot,
                        runner=git_runner,
                    )
                )
            except WomKitProjectUpdateSourceSnapshotChangedError:
                blockers.append(WOM_KIT_PROJECT_UPDATE_SOURCE_DRIFT_BLOCKER)
                release_current_lock_or_raise("blocked")
                return result_payload("blocked")
            source_checkout_changed = True
            if not materialization_succeeded:
                # A final pre-HEAD snapshot failure may have been restored by
                # the materializer while the owned lock stayed held.  Prove
                # that exact original snapshot before classifying it as a
                # verified pre-mutation rollback; otherwise the exception path
                # preserves the lock for recovery.
                if (
                    preflight_git_snapshot is not None
                    and _wom_kit_project_update_git_snapshot(
                        mirror_path,
                        runner=git_runner,
                    )
                    == preflight_git_snapshot
                    and wom_kit_project_update_source_matches_snapshot(
                        project_root,
                        mirror_path,
                        preflight_git_snapshot,
                        runner=git_runner,
                    )
                ):
                    source_checkout_changed = False
                raise RuntimeError("verified_source_materialization_failed")
            source_materialization_completed = True
            runtime_source_rematerialization_succeeded = True
        head_ok, checked_out_head = _wom_kit_project_update_git(
            mirror_path,
            ["rev-parse", "--verify", "HEAD"],
            runner=git_runner,
        )
        head_after = checked_out_head.lower() if head_ok else None
        if not head_ok or head_after != target_commit:
            raise RuntimeError("checkout_verification_failed")
        target_git_snapshot = _wom_kit_project_update_git_snapshot(
            mirror_path,
            runner=git_runner,
        )
        if not wom_kit_project_update_snapshot_is_clean(
            target_git_snapshot,
            expected_head=target_commit,
            expected_branch=None,
        ):
            target_git_snapshot = None
            raise RuntimeError("target_source_compare_and_swap_unavailable")

        after_versions = wom_kit_project_update_source_versions(mirror_path)
        if not all(normalize_version_label(value) == target_version for value in after_versions.values()):
            raise RuntimeError("source_version_verification_failed")
        runtime_source_after = wom_kit_runtime_tracked_python_integrity(
            project_root,
            mirror_path,
            runner=git_runner,
        )
        runtime_resources_after = wom_kit_runtime_resource_integrity(
            project_root,
            mirror_path,
            ref=target_commit,
            runner=git_runner,
        )
        target_runtime_source_integrity_verified = bool(
            runtime_source_after["tracked_python_sources_verified"]
            and runtime_resources_after["runtime_resources_verified"]
        )
        if not target_runtime_source_integrity_verified:
            raise RuntimeError("runtime_source_integrity_verification_failed")
        if (
            wom_kit_project_update_target_ref_snapshot(
                mirror_path,
                target_tag,
                runner=git_runner,
            )
            != trusted_target_ref_snapshot
        ):
            raise RuntimeError("target_ref_snapshot_changed")
        if not wom_kit_project_update_source_matches_snapshot(
            project_root,
            mirror_path,
            target_git_snapshot,
            runner=git_runner,
        ):
            raise RuntimeError("target_source_snapshot_unavailable")
        if progress_callback is not None:
            progress_callback("checkout-release", "done", None, None)

        if project_runtime_plan.get("required"):
            if (
                project_runtime_bootstrap is None
                or project_runtime_supply is None
                or prepared_runtime_bundle is None
                or project_runtime_launcher_snapshot is None
            ):
                raise RuntimeError(
                    "project_runtime_exact_public_supply_required"
                )
            runtimes_root = project_root / project_runtime.PROJECT_RUNTIME_RELATIVE_ROOT
            launcher_parent = (
                project_root
                / project_runtime.PROJECT_RUNTIME_LAUNCHER_RELATIVE.parent
            )
            if (
                not directory_guard.ensure_directory(
                    metadata_root,
                    runtimes_root,
                )
                or not directory_guard.ensure_directory(
                    metadata_root,
                    launcher_parent,
                )
            ):
                raise RuntimeError("project_runtime_directory_stability_unavailable")
            current_launcher = project_runtime.launcher_snapshot(
                project_root,
                target_version,
            )
            if (
                current_launcher.get("unsafe")
                or current_launcher.get("previous_bytes")
                != project_runtime_launcher_snapshot.get("previous_bytes")
                or current_launcher.get("existed")
                != project_runtime_launcher_snapshot.get("existed")
            ):
                raise RuntimeError("project_runtime_launcher_compare_and_swap_failed")
            project_runtime_materialization = project_runtime.materialize_runtime(
                project_root,
                target=target_version,
                target_commit=target_commit,
                bootstrap=project_runtime_bootstrap,
                supply=project_runtime_supply,
                prepared_bundle=prepared_runtime_bundle,
                running_version=WOM_KIT_VERSION,
                progress_callback=progress_callback,
                mutation_tracker=project_runtime_mutation_tracker,
            )
            cleanup_prepared_runtime_bundle_or_raise()
            if (
                head_before == target_commit
                and pins_already_target
                and target_runtime_source_integrity_verified
                and not checkout_required
                and project_runtime_materialization.created is False
                and project_runtime_launcher_snapshot.get("already_target")
            ):
                # A required runtime is never accepted from its static receipt
                # alone.  Reaching this branch proves the existing executable,
                # packages, retained artifacts, and payload in a fresh process
                # under the approved supply lock, without a durable write.
                head_after = head_before
                release_current_lock_or_raise("no_change")
                return result_payload("no_change")
            launcher_path = project_runtime_launcher_snapshot["path"]
            launcher_target_bytes = project_runtime_launcher_snapshot["target_bytes"]
            if not project_runtime_launcher_snapshot.get("already_target"):
                project_runtime_launcher_write_attempted = True
                write_bytes_atomic(launcher_path, launcher_target_bytes)
                project_runtime_launcher_written = True
            if (
                _wom_kit_read_bounded_real_bytes(
                    project_root,
                    launcher_path,
                    max_bytes=64 * 1024,
                )
                != launcher_target_bytes
            ):
                raise RuntimeError("project_runtime_launcher_verification_failed")
            if not wom_kit_project_update_source_matches_snapshot(
                project_root,
                mirror_path,
                target_git_snapshot,
                runner=git_runner,
            ):
                raise RuntimeError("project_source_changed_during_runtime_install")

        if progress_callback is not None:
            progress_callback("write-pins", "start", 0, len(pin_specs))
        target_pin_bytes = (target_tag + "\n").encode("utf-8")
        activation_ordered_pin_specs = [
            spec for spec in pin_specs if spec.get("role") != "project_pin"
        ] + [
            spec for spec in pin_specs if spec.get("role") == "project_pin"
        ]
        for index, spec in enumerate(activation_ordered_pin_specs, start=1):
            path = spec["path"]
            if (
                not wom_kit_project_update_source_matches_snapshot(
                    project_root,
                    mirror_path,
                    target_git_snapshot,
                    runner=git_runner,
                )
                or not wom_kit_project_update_pin_matches_snapshot(
                    project_root,
                    spec,
                )
            ):
                raise RuntimeError("project_update_compare_and_swap_failed")
            if spec.get("previous_bytes") != target_pin_bytes:
                pin_write_attempted_paths.append(spec["logical"])
                if not wom_kit_existing_path_components_are_real(
                    project_root,
                    path,
                ):
                    raise RuntimeError("pin_path_became_unsafe")
                path.parent.mkdir(parents=True, exist_ok=True)
                if not wom_kit_existing_path_components_are_real(
                    project_root,
                    path,
                ):
                    raise RuntimeError("pin_parent_became_unsafe")
                write_bytes_atomic(path, target_pin_bytes)
                pins_written.append(spec["logical"])
            if (
                _wom_kit_read_bounded_real_bytes(
                    project_root,
                    path,
                    max_bytes=WOM_KIT_VERSION_PIN_MAX_BYTES,
                )
                != target_pin_bytes
            ):
                raise RuntimeError("pin_verification_failed")
            if progress_callback is not None:
                progress_callback("write-pins", "written", index, len(pin_specs))
        if progress_callback is not None:
            progress_callback("write-pins", "done", len(pin_specs), len(pin_specs))
        if not wom_kit_project_update_source_matches_snapshot(
            project_root,
            mirror_path,
            target_git_snapshot,
            runner=git_runner,
        ):
            raise RuntimeError("project_source_changed_during_pin_write")
        if (
            wom_kit_project_update_target_ref_snapshot(
                mirror_path,
                target_tag,
                runner=git_runner,
            )
            != trusted_target_ref_snapshot
        ):
            raise RuntimeError("target_ref_snapshot_changed_during_pin_write")
        for spec in pin_specs:
            if (
                _wom_kit_read_bounded_real_bytes(
                    project_root,
                    spec["path"],
                    max_bytes=WOM_KIT_VERSION_PIN_MAX_BYTES,
                )
                != target_pin_bytes
            ):
                raise RuntimeError("pin_compare_and_swap_verification_failed")

        timestamp = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        receipt_schema = (
            "wom-kit/project-version-update-receipt/v0.3"
            if project_runtime_plan.get("required")
            else "wom-kit/project-version-update-receipt/v0.2"
        )
        receipt = {
            "schema": receipt_schema,
            "action": "project_version_update",
            "status": "updated_restart_required",
            "timestamp": timestamp,
            "reviewed_by": reviewer,
            "target_tag": target_tag,
            "target_version": target_version,
            "source_mirror": mirror_logical,
            "head_commit_before": head_before,
            "head_commit_after": head_after,
            "source_checkout_changed": source_checkout_changed,
            "runtime_source_materialization": {
                "attempted": runtime_source_rematerialization_attempted,
                "succeeded": runtime_source_rematerialization_succeeded,
                "target_integrity_verified": (
                    target_runtime_source_integrity_verified
                ),
            },
            "external_writer_quiescence": {
                "affirmed": True,
                "scope": (
                    "complete_project_version_update_transaction"
                ),
            },
            "pins_written": list(pins_written),
            **(
                {
                    "pin_transitions": [
                        {
                            "path": spec["logical"],
                            "previous_version": spec.get("previous_version"),
                            "new_version": target_tag,
                            "written": spec["logical"] in pins_written,
                        }
                        for spec in pin_specs
                    ],
                    "project_runtime": {
                        "policy_schema": project_runtime_policy["schema"],
                        "policy_sha256": project_runtime_policy["policy_sha256"],
                        "path": project_runtime_plan["target_path"],
                        "launcher_path": project_runtime_plan["launcher_path"],
                        "project_runtime_argv": project_runtime_plan[
                            "project_runtime_argv"
                        ],
                        "target_tag": target_tag,
                        "target_version": target_version,
                        "target_commit": target_commit,
                        "wheel_sha256": (
                            "sha256:"
                            + project_runtime_materialization.wheel_sha256
                        ),
                        "supply_lock_sha256": (
                            "sha256:"
                            + project_runtime_materialization.supply_lock_sha256
                        ),
                        "artifact_inventory": [
                            dict(item)
                            for item in (
                                project_runtime_materialization.artifact_inventory
                            )
                        ],
                        "installed_payload_sha256": (
                            "sha256:"
                            + project_runtime_materialization.installed_payload_sha256
                        ),
                        "runtime_receipt_sha256": (
                            "sha256:"
                            + project_runtime_materialization.receipt_sha256
                        ),
                        "python_version": (
                            project_runtime_materialization.python_version
                        ),
                        "created": project_runtime_materialization.created,
                        "launcher_written": (
                            project_runtime_launcher_written
                        ),
                        "verification": dict(
                            project_runtime_materialization.verification
                        ),
                        "new_process_verified": True,
                        "global_path_mutation": False,
                        "previous_runtime_deleted": False,
                    },
                }
                if (
                    project_runtime_plan.get("required")
                    and project_runtime_materialization is not None
                )
                else {}
            ),
            "configured_origin": {
                "remote_name": "origin",
                "atomic_fetch_succeeded": fetch_succeeded,
                "target_reachable_from_origin_main": True,
                "annotated_tag_verified": True,
                "cryptographic_tag_signature_verified": False,
                "remote_url_echoed": False,
            },
            "runtime": {
                "running_version_before": WOM_KIT_VERSION,
                "running_process_reloaded": False,
                "restart_required": True,
            },
            "privacy_guards": {
                "local_absolute_paths_echoed": False,
                "remote_urls_echoed": False,
                "credential_values_echoed": False,
                "archive_body_text_read": False,
                "objet_bytes_read": False,
            },
        }
        schema_issues = validate_schema(
            receipt,
            (
                "project-version-update-receipt-v0.3.schema.json"
                if project_runtime_plan.get("required")
                else "project-version-update-receipt-v0.2.schema.json"
            ),
        )
        if schema_issues:
            raise RuntimeError("receipt_schema_validation_failed")
        if progress_callback is not None:
            progress_callback("write-receipt", "start", None, None)
        receipt_bytes = (
            json.dumps(receipt, indent=2, ensure_ascii=False) + "\n"
        ).encode("utf-8")

        def register_receipt_reservation(
            reserved_path: Path,
            reserved_relative: str,
            reserved_identity: tuple[int, int],
        ) -> None:
            nonlocal receipt_reservation
            # One state assignment is the ownership handoff.  If an asynchronous
            # interruption lands before it, the exclusive helper still owns and
            # removes the file; after it, outer rollback has the full CAS journal.
            receipt_reservation = {
                "path": reserved_path,
                "relative": reserved_relative,
                "identity": reserved_identity,
            }

        if (
            not directory_guard.ensure_directory(
                metadata_root,
                receipts_parent,
            )
            or not directory_guard.ensure_directory(
                receipts_parent,
                receipts_root,
            )
        ):
            raise RuntimeError("receipt_directory_stability_unavailable")
        receipt_path, receipt_relative = (
            _wom_kit_project_update_write_receipt_exclusive(
                project_root,
                target_tag,
                timestamp,
                receipt_bytes,
                directory_guard=directory_guard,
                reservation_callback=register_receipt_reservation,
            )
        )
        receipt_written = True
        if progress_callback is not None:
            progress_callback("write-receipt", "done", None, None)
        if (
            wom_kit_project_update_target_ref_snapshot(
                mirror_path,
                target_tag,
                runner=git_runner,
            )
            != trusted_target_ref_snapshot
        ):
            raise RuntimeError("target_ref_snapshot_changed_before_commit")
        release_current_lock_or_raise("updated_restart_required")
        return result_payload("updated_restart_required")
    except BaseException as failure:
        if durable_handoff_complete:
            raise
        interrupted = not isinstance(failure, Exception)
        runtime_reference_cleanup_unverified = isinstance(
            failure,
            project_runtime.RuntimeReferenceCleanupError,
        )
        rollback["runtime_reference_cleanup_verified"] = (
            False if runtime_reference_cleanup_unverified else True
        )
        if runtime_reference_cleanup_unverified:
            preserve_lock = True
            blockers.append(
                "project_runtime_reference_cleanup_unverified"
            )
        prepared_bundle_removed = True
        if (
            prepared_runtime_bundle is not None
            and prepared_runtime_bundle_cleanup_state != "verified_absent"
        ):
            try:
                prepared_bundle_removed = bool(
                    project_runtime.cleanup_prepared_runtime_bundle(
                        prepared_runtime_bundle
                    )
                )
            except BaseException:
                prepared_bundle_removed = False
            prepared_runtime_bundle_cleanup_state = (
                "verified_absent"
                if prepared_bundle_removed
                else "uncertain"
            )
        elif isinstance(
            failure,
            (
                project_runtime.PreparedRuntimeBundleCleanupError,
                project_runtime.PreparedRuntimeCandidateIncompleteError,
            ),
        ):
            prepared_bundle_removed = False
            prepared_runtime_bundle_cleanup_state = "uncertain"
        rollback["prepared_runtime_bundle_removed"] = (
            prepared_bundle_removed
        )
        if not prepared_bundle_removed:
            preserve_lock = True
            blockers.append(
                "project_runtime_candidate_cleanup_unverified"
                if isinstance(
                    failure,
                    project_runtime.PreparedRuntimeCandidateIncompleteError,
                )
                else "project_runtime_prepared_bundle_cleanup_unverified"
            )
        potential_mutation_attempted = bool(
            source_checkout_changed
            or project_runtime_launcher_write_attempted
            or (
                project_runtime_materialization is not None
                and project_runtime_materialization.created
            )
            or project_runtime_mutation_tracker.started
            or pin_write_attempted_paths
            or receipt_written
            or receipt_reservation is not None
            or isinstance(
                failure,
                WomKitProjectUpdateReceiptUncertainError,
            )
        )
        lock_identity = (
            lock_reservation.get("identity")
            if lock_reservation is not None
            else None
        )
        lock_after_failure = (
            _wom_kit_project_update_lock_after_failure_observation(
                project_root,
                lock_path,
                lock_identity,
                expected_lock_bytes=(
                    durable_lock_bytes
                    if durable_lock_bytes is not None
                    else WOM_KIT_PROJECT_UPDATE_LOCK_BYTES
                ),
            )
        )
        lock_confirmed_missing = bool(
            lock_after_failure["state"] == "failed"
            and lock_after_failure["kind"] == "missing"
        )
        if (
            lock_release_state in {"releasing", "released"}
            and lock_after_failure["state"] == "unavailable"
            and lock_release_intent_status is not None
        ):
            preserve_lock = True
            rollback["attempted"] = False
            rollback["succeeded"] = False
            rollback["source_restored"] = None
            rollback["pins_restored"] = None
            rollback["lock_removed"] = None
            rollback["fetched_refs_may_remain"] = fetch_attempted
            blockers.append(
                "The project update lock could not be observed after the lock-release boundary; its state is uncertain and automatic rollback was skipped."
            )
            return result_payload(
                "interrupted_rollback_incomplete"
                if interrupted
                else "failed_rollback_incomplete"
            )
        if (
            lock_release_state in {"releasing", "released"}
            and lock_confirmed_missing
            and lock_release_intent_status is not None
        ):
            lock_acquired = False
            lock_release_state = "released"
            if unlocked_terminal_state_verified(
                lock_release_intent_status
            ):
                warnings.append(
                    "The operation had already crossed its verified lock-release commit boundary before the interruption."
                )
                return result_payload(lock_release_intent_status)
            preserve_lock = False
            rollback["attempted"] = False
            rollback["succeeded"] = False
            rollback["source_restored"] = None
            rollback["pins_restored"] = None
            rollback["lock_removed"] = True
            rollback["fetched_refs_may_remain"] = fetch_attempted
            blockers.append(
                "The owned update lock was already absent when a terminal-state check failed; automatic rollback was skipped because it could no longer run under the lock."
            )
            return result_payload(
                "interrupted_rollback_incomplete"
                if interrupted
                else "failed_rollback_incomplete"
            )

        if (
            (
                lock_acquired
                or lock_release_state in {"releasing", "released"}
            )
            and lock_after_failure["state"] != "passed"
        ):
            if lock_after_failure["state"] == "unavailable":
                preserve_lock = True
                rollback["lock_removed"] = None
                blocker = (
                    "The project update lock could not be observed before rollback; its state is uncertain and automatic rollback was skipped."
                )
            else:
                lock_missing = lock_confirmed_missing
                lock_acquired = not lock_missing
                preserve_lock = not lock_missing
                rollback["lock_removed"] = lock_missing
                blocker = (
                    "The project update lock was removed or replaced before rollback; automatic rollback was skipped to avoid running without the owned lock."
                )
            rollback["attempted"] = False
            rollback["succeeded"] = False
            rollback["source_restored"] = None
            rollback["pins_restored"] = None
            rollback["fetched_refs_may_remain"] = fetch_attempted
            blockers.append(blocker)
            return result_payload(
                "interrupted_rollback_incomplete"
                if interrupted
                else "failed_rollback_incomplete"
            )

        if (
            wom_kit_project_update_git_config_trust_digest(
                mirror_path,
                runner=git_runner,
            )
            != preflight_git_config_digest
        ):
            preserve_lock = True
            target_runtime_source_integrity_verified = False
            rollback["attempted"] = False
            rollback["succeeded"] = False
            rollback["source_restored"] = None
            rollback["pins_restored"] = None
            rollback["lock_removed"] = False
            rollback["fetched_refs_may_remain"] = fetch_attempted
            blockers.append(
                "The effective Git configuration changed before rollback; automatic rollback was skipped and the owned lock was preserved for review."
            )
            return result_payload(
                "interrupted_rollback_incomplete"
                if interrupted
                else "failed_rollback_incomplete"
            )

        preserve_lock = True
        target_runtime_source_integrity_verified = False
        uncertain_receipt_mutation = isinstance(
            failure,
            WomKitProjectUpdateReceiptUncertainError,
        )
        mutation_attempted = potential_mutation_attempted
        rollback["attempted"] = mutation_attempted
        rollback["fetched_refs_may_remain"] = fetch_attempted
        source_restored = True
        source_restore_operation_ok = True
        pins_restored = not uncertain_receipt_mutation
        project_runtime_launcher_restored = True
        project_runtime_removed = True
        if source_checkout_changed and head_before:
            current_ok, current_head = _wom_kit_project_update_git(
                mirror_path,
                ["rev-parse", "--verify", "HEAD"],
                runner=git_runner,
            )
            current_git_snapshot = _wom_kit_project_update_git_snapshot(
                mirror_path,
                runner=git_runner,
            )
            rollback_head_safe = bool(
                current_ok
                and current_head.lower()
                in {
                    head_before,
                    str(target_evidence.get("target_commit") or "").lower(),
                }
                and (
                    source_materialization_completed
                    and target_git_snapshot is not None
                    and current_git_snapshot == target_git_snapshot
                )
            )
            try:
                restored_ok = bool(
                    rollback_head_safe
                    and _wom_kit_project_update_materialize_commit(
                        mirror_path,
                        head_before,
                        attach_branch=original_branch,
                        directory_guard=directory_guard,
                        runner=git_runner,
                    )
                )
            except BaseException:
                restored_ok = False
            verify_ok, restored_head = _wom_kit_project_update_git(
                mirror_path,
                ["rev-parse", "--verify", "HEAD"],
                runner=git_runner,
            )
            source_restore_operation_ok = (
                restored_ok
                and verify_ok
                and restored_head.lower() == head_before
            )
            if source_restore_operation_ok:
                source_restore_operation_ok = (
                    _wom_kit_project_update_restore_eol_overrides(
                        project_root,
                        mirror_path,
                        preflight_git_snapshot,
                    )
                )
            source_restored = source_restore_operation_ok
            head_after = restored_head.lower() if verify_ok else None
        if project_runtime_launcher_write_attempted:
            try:
                if project_runtime_launcher_snapshot is None:
                    raise OSError("missing_project_runtime_launcher_snapshot")
                launcher_path = project_runtime_launcher_snapshot["path"]
                target_launcher_bytes = project_runtime_launcher_snapshot[
                    "target_bytes"
                ]
                current_launcher_bytes = _wom_kit_read_bounded_real_bytes(
                    project_root,
                    launcher_path,
                    max_bytes=64 * 1024,
                )
                previous_launcher_bytes = project_runtime_launcher_snapshot.get(
                    "previous_bytes"
                )
                if current_launcher_bytes == previous_launcher_bytes:
                    pass
                elif current_launcher_bytes != target_launcher_bytes:
                    raise OSError("project_runtime_launcher_compare_and_swap_failed")
                elif project_runtime_launcher_snapshot.get("existed"):
                    if not isinstance(previous_launcher_bytes, bytes):
                        raise OSError("project_runtime_launcher_snapshot_missing")
                    write_bytes_atomic(launcher_path, previous_launcher_bytes)
                else:
                    launcher_path.unlink()
                verified_launcher_bytes = _wom_kit_read_bounded_real_bytes(
                    project_root,
                    launcher_path,
                    max_bytes=64 * 1024,
                )
                if project_runtime_launcher_snapshot.get("existed"):
                    project_runtime_launcher_restored = (
                        verified_launcher_bytes == previous_launcher_bytes
                    )
                else:
                    project_runtime_launcher_restored = (
                        wom_kit_real_path_kind(project_root, launcher_path)
                        == "missing"
                    )
                project_runtime_launcher_written = False
            except BaseException:
                project_runtime_launcher_restored = False
        for spec in pin_specs:
            if spec["logical"] not in pin_write_attempted_paths:
                if not wom_kit_project_update_pin_matches_snapshot(
                    project_root,
                    spec,
                ):
                    pins_restored = False
                continue
            path = spec["path"]
            try:
                path_kind = wom_kit_real_path_kind(project_root, path)
                current_bytes = (
                    _wom_kit_read_bounded_real_bytes(
                        project_root,
                        path,
                        max_bytes=WOM_KIT_VERSION_PIN_MAX_BYTES,
                    )
                    if path_kind == "file"
                    else None
                )
                if spec.get("existed"):
                    previous_bytes = spec.get("previous_bytes")
                    if not isinstance(previous_bytes, bytes):
                        raise OSError("missing_pin_snapshot")
                    if current_bytes == previous_bytes:
                        continue
                    if current_bytes != target_pin_bytes:
                        raise OSError("pin_compare_and_swap_failed")
                    if not wom_kit_existing_path_components_are_real(
                        project_root,
                        path,
                    ):
                        raise OSError("pin_path_unsafe")
                    path.parent.mkdir(parents=True, exist_ok=True)
                    write_bytes_atomic(path, previous_bytes)
                    if (
                        _wom_kit_read_bounded_real_bytes(
                            project_root,
                            path,
                            max_bytes=WOM_KIT_VERSION_PIN_MAX_BYTES,
                        )
                        != previous_bytes
                    ):
                        raise OSError("pin_restore_verification_failed")
                elif path_kind == "missing":
                    continue
                elif current_bytes == target_pin_bytes:
                    path.unlink()
                    if wom_kit_real_path_kind(project_root, path) != "missing":
                        raise OSError("pin_removal_verification_failed")
                else:
                    raise OSError("pin_compare_and_swap_failed")
            except BaseException:
                pins_restored = False
        if project_runtime_mutation_tracker.started:
            try:
                if project_runtime_materialization is not None:
                    project_runtime_removed = (
                        project_runtime.remove_materialized_runtime(
                            project_root,
                            project_runtime_materialization,
                            mutation_tracker=(
                                project_runtime_mutation_tracker
                            ),
                        )
                    )
                else:
                    # materialize_runtime owns cleanup for failures before it
                    # can return a RuntimeMaterialization.  Verify the complete
                    # runtime-root snapshot here before allowing lock release.
                    project_runtime_removed = (
                        project_runtime.runtime_mutation_restored(
                            project_root,
                            project_runtime_mutation_tracker,
                        )
                    )
            except BaseException:
                project_runtime_removed = False
        elif (
            project_runtime_materialization is not None
            and project_runtime_materialization.created
        ):
            # Fail closed for a non-conforming injected materializer which
            # claims creation without using the required mutation tracker.
            try:
                removed_without_snapshot = (
                    project_runtime.remove_materialized_runtime(
                        project_root,
                        project_runtime_materialization,
                    )
                )
                project_runtime_removed = False
                if not removed_without_snapshot:
                    warnings.append(
                        "The project runtime could not be removed after a materializer violated the mutation-tracker contract."
                    )
            except BaseException:
                project_runtime_removed = False
        if receipt_reservation is not None:
            receipt_candidate = receipt_reservation["path"]
            receipt_identity = receipt_reservation["identity"]
            try:
                receipt_kind = wom_kit_real_path_kind(
                    project_root,
                    receipt_candidate,
                )
                if receipt_kind == "file":
                    current_receipt = _wom_kit_read_bounded_real_bytes(
                        project_root,
                        receipt_candidate,
                        max_bytes=2 * 1024 * 1024,
                    )
                    if receipt_bytes is None or current_receipt != receipt_bytes:
                        raise OSError("receipt_compare_and_swap_failed")
                    if not _wom_kit_project_update_remove_exclusive_receipt_if_owned(
                        project_root,
                        receipt_candidate,
                        receipt_identity,
                    ):
                        raise OSError("receipt_removal_verification_failed")
                elif receipt_kind != "missing":
                    raise OSError("receipt_path_unsafe")
                receipt_written = False
            except BaseException:
                pins_restored = False
        for directory, existed_before in (
            (receipts_root, receipts_root_existed_before),
            (receipts_parent, receipts_parent_existed_before),
        ):
            if (
                existed_before
                or wom_kit_real_path_kind(project_root, directory) == "missing"
            ):
                continue
            try:
                directory_guard.release(directory)
                directory.rmdir()
            except BaseException:
                pins_restored = False
        if source_checkout_changed:
            source_restored = bool(
                source_restore_operation_ok
                and preflight_git_snapshot is not None
                and wom_kit_project_update_git_metadata_is_local_real(
                    project_root,
                    mirror_path,
                    runner=git_runner,
                )
                and _wom_kit_project_update_git_snapshot(
                    mirror_path,
                    runner=git_runner,
                )
                == preflight_git_snapshot
            )
        rollback["source_restored"] = source_restored
        rollback["pins_restored"] = pins_restored
        rollback["project_runtime_removed"] = project_runtime_removed
        rollback["project_runtime_launcher_restored"] = (
            project_runtime_launcher_restored
        )
        lock_removed: bool | None = False
        if (
            source_restored
            and pins_restored
            and project_runtime_removed
            and prepared_bundle_removed
            and project_runtime_launcher_restored
            and not runtime_reference_cleanup_unverified
            and lock_acquired
        ):
            identity = (
                lock_reservation.get("identity")
                if lock_reservation is not None
                else None
            )
            try:
                lock_removed = _wom_kit_project_update_release_owned_lock(
                    project_root,
                    lock_path,
                    identity,
                )
                if lock_removed:
                    lock_acquired = False
            except BaseException:
                lock_after_release = (
                    _wom_kit_project_update_lock_after_failure_observation(
                        project_root,
                        lock_path,
                        identity,
                        expected_lock_bytes=(
                            durable_lock_bytes
                            if durable_lock_bytes is not None
                            else WOM_KIT_PROJECT_UPDATE_LOCK_BYTES
                        ),
                    )
                )
                lock_removed = (
                    True
                    if lock_after_release["kind"] == "missing"
                    else None
                    if lock_after_release["state"] == "unavailable"
                    else False
                )
                if lock_removed is True:
                    lock_acquired = False
            if lock_removed is False:
                lock_after_release = (
                    _wom_kit_project_update_lock_after_failure_observation(
                        project_root,
                        lock_path,
                        identity,
                        expected_lock_bytes=(
                            durable_lock_bytes
                            if durable_lock_bytes is not None
                            else WOM_KIT_PROJECT_UPDATE_LOCK_BYTES
                        ),
                    )
                )
                if lock_after_release["kind"] == "missing":
                    lock_removed = True
                    lock_acquired = False
                elif lock_after_release["state"] == "unavailable":
                    lock_removed = None
        elif not lock_acquired:
            lock_removed = True
        rollback["lock_removed"] = lock_removed
        rollback["succeeded"] = bool(
            source_restored
            and pins_restored
            and project_runtime_removed
            and prepared_bundle_removed
            and project_runtime_launcher_restored
            and not runtime_reference_cleanup_unverified
            and lock_removed
        )
        preserve_lock = not bool(rollback["succeeded"])
        if lock_removed is None:
            blockers.append(
                "The project update lock could not be observed after rollback cleanup; its state remains uncertain and no further cleanup was attempted."
            )
        blockers.append(
            (
                "The project version update was interrupted and its local mutation was rolled back."
                if interrupted and rollback["succeeded"]
                else "The project version update was interrupted and rollback could not be fully verified; the lock was preserved."
                if interrupted
                else "The project version update failed after local mutation and was rolled back."
                if mutation_attempted and rollback["succeeded"]
                else "The project version update failed before local mutation."
                if rollback["succeeded"]
                else "The project version update failed and rollback could not be fully verified; the lock was preserved."
            )
        )
        status = (
            "interrupted_rolled_back"
            if interrupted and rollback["succeeded"]
            else "interrupted_rollback_incomplete"
            if interrupted
            else "failed_rolled_back"
            if mutation_attempted and rollback["succeeded"]
            else "failed_before_mutation"
            if rollback["succeeded"]
            else "failed_rollback_incomplete"
        )
        return result_payload(status)
    finally:
        primary_failure = sys.exc_info()[1]
        try:
            directory_guard.close()
        except BaseException as close_failure:
            if isinstance(primary_failure, GeneratorExit):
                raise
            if primary_failure is None:
                if last_result_payload is None:
                    raise
                _project_update_attach_nonterminal_close_truth(
                    last_result_payload,
                    service_resource_close_failure=close_failure,
                    runner_close_failure=None,
                )


def _project_update_seal_legacy_fresh_plan(
    state: _ProjectVersionUpdateDurableApprovalState,
    *,
    safe_progress_callback: (
        Callable[[str, str, int | None, int | None], None] | None
    ),
) -> None:
    """Seal C-phase evidence before the native approval boundary.

    Each private document is immutable and create-only.  Re-entering after a
    power cut therefore either observes the exact prior document or fails
    closed; it never manufactures a second plan, transaction, or approval.
    """

    control = getattr(state, "legacy_prewrite_recovery_control", None)
    if not isinstance(control, dict):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )
    paths = control.get("paths")
    old_abandonment_sha256 = control.get("old_abandonment_sha256")
    with_store = control.get("with_store")
    if (
        not isinstance(
            paths,
            project_update_legacy_recovery.RecoveryPaths,
        )
        or type(old_abandonment_sha256) is not str
        or not callable(with_store)
        or not isinstance(
            getattr(state, "legacy_prewrite_recovery", None), Mapping
        )
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_binding_invalid"
        )

    fresh_inventory = project_update_legacy_recovery.directory_tree_inventory(
        state.transaction.transaction_root,
        progress_callback=(
            (
                lambda count, byte_count: safe_progress_callback(
                    "project-recovery-inventory",
                    "running",
                    count,
                    byte_count,
                )
            )
            if safe_progress_callback is not None
            else None
        ),
    )
    # The recovery inventory's semantic digest uses the recovery protocol's
    # newline-terminated canonical form.  The transaction protocol has a
    # different canonical byte form and must not be mixed into this binding.
    fresh_inventory_sha256 = project_update_legacy_recovery.sha256_document(
        fresh_inventory
    )
    fresh_binding = project_version_update_approval_binding(
        state.prepared_preview
    )
    fresh_context = fresh_binding.context(
        archive_id=state.expected_archive_id,
        reviewer_claim=state.reviewer,
    )
    post_fetch_ref_snapshot = (
        wom_kit_project_update_target_ref_snapshot_observation(
            state.mirror_path,
            state.target_tag,
            runner=state.runner,
        )
    )
    if (
        post_fetch_ref_snapshot.get("state") != "passed"
        or post_fetch_ref_snapshot.get("reason_code") != "verified"
        or post_fetch_ref_snapshot.get("snapshot")
        != state.private_plan.get("target_ref_snapshot")
    ):
        raise ArchiveServiceError(
            "project_version_update_legacy_recovery_state_changed"
        )
    try:
        post_fetch_ref_record = with_store(
            lambda store: store.write_post_fetch_ref_snapshot(
                post_fetch_ref_snapshot,
                pre_ref_snapshot_document_sha256=control[
                    "pre_ref_snapshot_document_sha256"
                ],
                pre_ref_snapshot_sha256=control["pre_ref_snapshot_sha256"],
                requested_target_tag=state.target_tag,
            )
        )
        fresh_inventory_record = with_store(
            lambda store: store.write_fresh_transaction_inventory(
                fresh_transaction_ref=state.transaction.transaction_ref,
                inventory=fresh_inventory,
            )
        )
    except project_update_legacy_recovery.LegacyProjectUpdateRecoveryError as failure:
        raise ArchiveServiceError(failure.code) from None

    fresh_recovery_binding_sha256 = project_update_transaction.sha256_document(
        dict(state.legacy_prewrite_recovery)
    )
    prospective = project_update_legacy_recovery.prospective_plan_document(
        recovery_ref=paths.recovery_ref,
        fresh_transaction_ref=state.transaction.transaction_ref,
        fresh_intent_sha256=state.transaction.intent.sha256,
        fresh_transaction_inventory_sha256=fresh_inventory_sha256,
        fresh_transaction_inventory_document_sha256=(
            fresh_inventory_record[
                "fresh_transaction_inventory_document_sha256"
            ]
        ),
        fresh_allocation_document_sha256=control["fresh_allocation_sha256"],
        post_ref_snapshot_document_sha256=(
            post_fetch_ref_record["post_ref_snapshot_document_sha256"]
        ),
        post_ref_snapshot_sha256=(
            post_fetch_ref_record["post_ref_snapshot_sha256"]
        ),
        fresh_approval_plan_sha256=fresh_binding.plan_sha256,
        fresh_approval_target_binding_sha256=(
            fresh_binding.target_binding_sha256
        ),
        fresh_approval_context_sha256=(
            exact_human_approval_context_sha256(fresh_context)
        ),
        fresh_recovery_binding_sha256=fresh_recovery_binding_sha256,
        old_abandonment_sha256=old_abandonment_sha256,
    )
    try:
        prospective_sha256 = with_store(
            lambda store: store.write_prospective_plan(prospective)
        )
    except project_update_legacy_recovery.LegacyProjectUpdateRecoveryError as failure:
        raise ArchiveServiceError(failure.code) from None

    control["fresh_transaction_inventory"] = fresh_inventory
    control["fresh_prospective_plan"] = prospective
    control["fresh_prospective_plan_sha256"] = prospective_sha256
    control["fresh_transaction_inventory_document_sha256"] = (
        fresh_inventory_record[
            "fresh_transaction_inventory_document_sha256"
        ]
    )
    control["fresh_recovery_binding_sha256"] = (
        fresh_recovery_binding_sha256
    )
    _project_update_legacy_recovery_checkpoint(
        state,
        phase="fresh_plan_sealed",
        evidence_sha256=prospective_sha256,
        locator_state="fresh_plan_sealed",
    )


def _wom_kit_project_version_update_legacy_core(
    inspection_root: Path | str,
    *,
    target: str,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    affirm_external_writers_quiescent: bool = False,
    operation_exact_human_approval: Mapping[str, Any] | None = None,
    approval_executor: Callable[..., Mapping[str, Any]]
    | None = None,
    progress_callback: Callable[[str, str, int | None, int | None], None]
    | None = None,
    _expected_approval_root: Path | None = None,
    _expected_archive_id: str | None = None,
    _legacy_recovery_old_lock_bytes: bytes | None = None,
    _legacy_recovery_approval_summary: Mapping[str, Any] | None = None,
    _legacy_recovery_control: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Drive the historical core or one live lock-held approval yield."""

    safe_progress_callback = progress_callback
    if progress_callback is not None:
        def best_effort_project_update_progress(
            stage: str,
            event: str,
            current: int | None,
            total: int | None,
        ) -> None:
            try:
                progress_callback(stage, event, current, total)
            except Exception:
                # Progress is observational. In particular, a terminal
                # domain result must not be replaced by an output/journal
                # callback failure.
                return

        safe_progress_callback = best_effort_project_update_progress

    git_runner_lifetime = _ProjectVersionUpdateGitRunnerLifetime()
    transaction = _wom_kit_project_version_update_legacy_core_generator(
        inspection_root,
        target=target,
        dry_run=dry_run,
        approve=approve,
        reviewed_by=reviewed_by,
        affirm_external_writers_quiescent=(
            affirm_external_writers_quiescent
        ),
        operation_exact_human_approval=operation_exact_human_approval,
        prepare_exact_approval=approval_executor is not None,
        progress_callback=safe_progress_callback,
        _expected_approval_root=_expected_approval_root,
        _expected_archive_id=_expected_archive_id,
        _git_runner_lifetime=git_runner_lifetime,
        _legacy_recovery_old_lock_bytes=_legacy_recovery_old_lock_bytes,
        _legacy_recovery_approval_summary=(
            _legacy_recovery_approval_summary
        ),
        _legacy_recovery_control=_legacy_recovery_control,
    )
    try:
        prepared_preview = next(transaction)
    except StopIteration as completed:
        return _project_update_finish_nonterminal_service_result(
            completed.value,
            git_runner_lifetime,
            close_owned_resources=transaction.close,
        )
    except BaseException:
        _project_update_close_after_service_failure(
            transaction.close,
            git_runner_lifetime,
        )
        raise

    if approval_executor is None:
        _project_update_close_after_service_failure(
            transaction.close,
            git_runner_lifetime,
        )
        raise ArchiveServiceError(
            "project_version_update_live_approval_executor_required"
        )

    if isinstance(
        prepared_preview,
        _ProjectVersionUpdatePreparedApproval,
    ):
        prepared = prepared_preview
        state = prepared.state
        continuation_used = False

        def durable_continue_after_approval(
            claim: _ClaimedExactHumanApproval,
            expected_plan_sha256: str,
            expected_target_binding_sha256: str,
        ) -> Mapping[str, Any]:
            nonlocal continuation_used
            if continuation_used:
                raise ArchiveServiceError(
                    "project_version_update_approval_continuation_reused"
                )
            with _project_update_fresh_terminal_absence_boundary(
                state.project_root
            ):
                pass
            continuation_used = True
            binding = project_version_update_approval_binding(
                prepared.preview
            )
            assert_same_binding(
                binding,
                expected_plan_sha256=expected_plan_sha256,
                expected_target_binding_sha256=(
                    expected_target_binding_sha256
                ),
            )
            state.approved_plan_sha256 = binding.plan_sha256
            state.approved_target_binding_sha256 = (
                binding.target_binding_sha256
            )
            try:
                _project_update_activate_legacy_recovery_state(state)
                return _project_update_durable_writer(state, claim)
            except ArchiveServiceError:
                raise
            except (
                project_update_transaction.ProjectUpdateTransactionError,
                project_runtime.ProjectRuntimeError,
                project_update_git_runner.ProjectUpdateGitRunnerError,
            ) as failure:
                # All three implementations expose a fixed, path-free code.
                # Translate at the public service boundary so the CLI never
                # renders a traceback or an implementation-local exception.
                code = getattr(
                    failure,
                    "code",
                    "project_version_update_durable_transaction_failed",
                )
                raise ArchiveServiceError(str(code)) from None

        def durable_claim_succeeded_finalizer(
            claim: _ClaimedExactHumanApproval,
        ) -> None:
            try:
                _project_update_succeeded_claim_finalizer(state, claim)
            except ArchiveServiceError:
                raise
            except (
                project_update_transaction.ProjectUpdateTransactionError,
                project_runtime.ProjectRuntimeError,
                project_update_git_runner.ProjectUpdateGitRunnerError,
            ) as failure:
                code = getattr(
                    failure,
                    "code",
                    "project_version_update_durable_transaction_failed",
                )
                raise ArchiveServiceError(str(code)) from None

        def durable_started_guard(
            claim: _ClaimedExactHumanApproval,
        ) -> bool:
            binding = project_version_update_approval_binding(
                prepared.preview
            )
            state.approved_plan_sha256 = binding.plan_sha256
            state.approved_target_binding_sha256 = (
                binding.target_binding_sha256
            )
            return _project_update_claim_checkpoint_guard(
                state,
                claim,
                succeeded=False,
            )

        def durable_succeeded_guard(
            claim: _ClaimedExactHumanApproval,
        ) -> bool:
            binding = project_version_update_approval_binding(
                prepared.preview
            )
            state.approved_plan_sha256 = binding.plan_sha256
            state.approved_target_binding_sha256 = (
                binding.target_binding_sha256
            )
            return _project_update_claim_checkpoint_guard(
                state,
                claim,
                succeeded=True,
            )

        def claim_publication_boundary() -> Any:
            return _project_update_claim_publication_boundary(state)

        legacy_control = getattr(
            state, "legacy_prewrite_recovery_control", None
        )
        if legacy_control is not None:
            _project_update_seal_legacy_fresh_plan(
                state,
                safe_progress_callback=safe_progress_callback,
            )

        try:
            with _project_update_terminal_execution_lease(
                state,
                expected_handoff_observation=None,
                fresh_absence=True,
            ):
                approval_arguments: dict[str, Any] = {
                    "claim_publication_boundary": (
                        claim_publication_boundary
                    )
                }
                if getattr(
                    state, "legacy_prewrite_recovery_control", None
                ) is not None:
                    recovery_key_provider = (
                        getattr(
                            state, "legacy_prewrite_recovery_control", {}
                        ).get(
                            "approval_key_provider"
                        )
                    )
                    if recovery_key_provider is None:
                        raise ArchiveServiceError(
                            "project_version_update_legacy_recovery_binding_invalid"
                        )
                    approval_arguments["recovery_key_provider"] = (
                        recovery_key_provider
                    )
                    # The resume CLI intentionally accepts no new reviewer
                    # identifier.  This composite decision remains bound to
                    # the authenticated predecessor reviewer's content-free
                    # claim rather than accidentally passing ``None`` into
                    # the native context.
                    approval_arguments["resume_reviewer"] = state.reviewer
                result = approval_executor(
                    copy.deepcopy(dict(prepared.preview)),
                    durable_continue_after_approval,
                    durable_claim_succeeded_finalizer,
                    durable_started_guard,
                    durable_succeeded_guard,
                    **approval_arguments,
                )
                if not continuation_used:
                    raise ArchiveServiceError(
                        "project_version_update_approval_continuation_not_used"
                    )
                if not isinstance(result, Mapping):
                    raise ArchiveServiceError(
                        "project_version_update_result_invalid"
                    )
        except BaseException as failure:
            terminal_boundary_unknown = bool(
                type(failure) is ArchiveServiceError
                and len(failure.args) == 1
                and type(failure.args[0]) is str
                and failure.args[0]
                in {
                    "project_version_update_terminal_execution_boundary_unknown",
                    "project_version_update_fresh_terminal_invalid_prewrite",
                    "project_version_update_fresh_terminal_present_prewrite",
                }
            )
            if (
                getattr(state, "legacy_prewrite_recovery_control", None)
                is not None
                and not continuation_used
            ):
                if _project_update_is_exact_native_approval_denial(failure):
                    restored_result = (
                        _project_update_restore_legacy_recovery_after_unapproved(
                            state
                        )
                    )
                    if not _project_update_is_legacy_unapproved_terminal_result(
                        restored_result
                    ):
                        _project_update_close_after_service_failure(
                            transaction.close,
                            git_runner_lifetime,
                        )
                        raise ArchiveServiceError(
                            "project_version_update_legacy_recovery_state_ambiguous"
                        )
                    return _project_update_finish_legacy_cancellation_result(
                        restored_result,
                        git_runner_lifetime,
                        close_owned_resources=transaction.close,
                    )
                _project_update_close_after_service_failure(
                    transaction.close,
                    git_runner_lifetime,
                )
                raise
            if terminal_boundary_unknown and not continuation_used:
                cleanup_completed = False
                try:
                    _project_update_cancel_before_native(state)
                    cleanup_completed = True
                except BaseException:
                    # The public result below intentionally retains only
                    # content-free uncertainty.  The original exception and
                    # all private transaction paths/identifiers stay local.
                    cleanup_completed = False
                unknown = (
                    _project_update_terminal_cleanup_outcome_unknown_result(
                        operator_resume_identifiers_supplied=False,
                        archive_identity_metadata_read=True,
                    )
                )
                unknown["files_written_scope"] = "project_domain_only"
                unknown["files_written"] = []
                unknown["effect_summary"] = (
                    _project_update_preapproval_cancel_effect_summary(
                        reservation_abort_evidence=False,
                        cancellation_checkpoints=True,
                        candidate_cleanup=True,
                    )
                    if cleanup_completed
                    else {
                        "project_domain_writes_performed": False,
                        "project_domain_files_written": [],
                        "durable_control_evidence_written_or_verified": None,
                        "reservation_abort_evidence_written_or_verified": False,
                        "cancellation_checkpoints_written_or_verified": None,
                        "candidate_cleanup_performed_or_verified": None,
                        "private_control_mutation_performed_or_verified": None,
                        "private_control_mutation_may_be_incomplete": True,
                        "candidate_absence_verified": None,
                        "lock_release_performed_or_verified": None,
                        "paths_or_identifiers_disclosed": False,
                    }
                )
                unknown["preapproval_cleanup"] = {
                    "attempted": True,
                    "completed": cleanup_completed,
                    "domain_writer_entered": False,
                    "native_approval_entered": False,
                    "private_paths_echoed": False,
                    "private_identifiers_echoed": False,
                    "raw_errors_echoed": False,
                }
                return _project_update_finish_nonterminal_service_result(
                    unknown,
                    git_runner_lifetime,
                    close_owned_resources=transaction.close,
                )
            try:
                if (
                    not continuation_used
                    and getattr(failure, "code", None)
                    == "exact_human_approval_cancelled"
                ):
                    _project_update_cancel_before_native(state)
            finally:
                _project_update_close_after_service_failure(
                    transaction.close,
                    git_runner_lifetime,
                )
            raise
        return _project_update_finish_service_result(
            result,
            state,
            git_runner_lifetime,
            close_owned_resources=transaction.close,
        )

    continuation_used = False

    def continue_after_approval(
        claim: _ClaimedExactHumanApproval,
        expected_plan_sha256: str,
        expected_target_binding_sha256: str,
    ) -> Mapping[str, Any]:
        nonlocal continuation_used
        if continuation_used:
            raise ArchiveServiceError(
                "project_version_update_approval_continuation_reused"
            )
        with _project_update_fresh_terminal_absence_boundary(
            _project_update_resume_project_root_read_only(inspection_root)
        ):
            pass
        continuation_used = True
        try:
            unexpected = transaction.send(
                {
                    "claim": claim,
                    "expected_plan_sha256": expected_plan_sha256,
                    "expected_target_binding_sha256": (
                        expected_target_binding_sha256
                    ),
                }
            )
        except StopIteration as completed:
            result = completed.value
            if not isinstance(result, Mapping):
                raise ArchiveServiceError(
                    "project_version_update_result_invalid"
                )
            return dict(result)
        raise ArchiveServiceError(
            "project_version_update_approval_continuation_invalid"
        ) from RuntimeError(str(unexpected))

    try:
        result = approval_executor(
            copy.deepcopy(prepared_preview),
            continue_after_approval,
        )
        if not continuation_used:
            raise ArchiveServiceError(
                "project_version_update_approval_continuation_not_used"
            )
        if not isinstance(result, Mapping):
            raise ArchiveServiceError(
                "project_version_update_result_invalid"
            )
    except BaseException:
        _project_update_close_after_service_failure(
            transaction.close,
            git_runner_lifetime,
        )
        raise
    return _project_update_finish_nonterminal_service_result(
        result,
        git_runner_lifetime,
        close_owned_resources=transaction.close,
    )


def ai_start_here_inbox_attention(archive_root: Path) -> dict[str, Any]:
    """Compose the privacy-safe inbox line shown at every archive session start."""

    audit = inbox_pipeline_audit(
        archive_root,
        dry_run=True,
        max_findings=1,
    )
    summary = (
        audit.get("summary")
        if isinstance(audit.get("summary"), dict)
        else {}
    )
    unpublished_count = int(
        summary.get("top_level_markdown_draft_count") or 0
    )
    possible_count = int(
        summary.get("possible_out_of_pipeline_draft") or 0
    )
    readiness_gap_count = int(
        summary.get("mint_readiness_gap_count") or 0
    )
    oldest_age = summary.get("oldest_draft_age_days")
    complete = bool(audit.get("ok")) and bool(summary.get("complete"))
    if not complete:
        human_summary = (
            "Inbox draft attention could not be counted completely; run the detailed read-only audit now."
        )
    elif unpublished_count == 0:
        human_summary = "Inbox has no unpublished drafts."
    else:
        age_phrase = (
            f"; oldest is {oldest_age} day(s) old"
            if isinstance(oldest_age, int)
            else "; oldest age is unknown"
        )
        human_summary = (
            f"Inbox has {unpublished_count} unpublished draft(s){age_phrase}. "
            f"{possible_count} may have bypassed the current create-draft shape; "
            f"{readiness_gap_count} have publication-critical metadata gaps."
        )
    return {
        "status": (
            "incomplete"
            if not complete
            else "attention"
            if unpublished_count
            else "clear"
        ),
        "complete": complete,
        "unpublished_draft_count": unpublished_count,
        "possible_out_of_pipeline_draft_count": possible_count,
        "mint_readiness_gap_count": readiness_gap_count,
        "oldest_draft_age_days": oldest_age
        if isinstance(oldest_age, int)
        else None,
        "review_recommended": bool(
            unpublished_count or possible_count or readiness_gap_count
        ),
        "human_summary": human_summary,
        "next_command": (
            "archive inbox-pipeline-audit <archive-root> --dry-run --format json"
        ),
        "audit_schema": audit.get("schema"),
        "audit_digest": audit.get("audit_digest"),
        "body_text_read": bool(
            summary.get("body_text_may_have_been_read")
        ),
        "paths_titles_or_body_echoed": False,
    }


def ai_start_here(
    archive_root: Path | str,
    *,
    expected_archive_id: str | None = None,
    expected_type: str | None = None,
    strict: bool = False,
    redact_local_paths: bool = True,
    diagnostics: list[dict[str, Any]] | None = None,
    inspection_mode: str | None = None,
    inspection_reads: dict[str, bool] | None = None,
) -> dict[str, Any]:
    mode = inspection_mode or ("full_doctor" if diagnostics is not None else "quick")
    if mode not in {"quick", "full_doctor"}:
        raise ArchiveServiceError("ai-start-here inspection_mode must be quick or full_doctor.")
    if mode == "full_doctor" and diagnostics is None:
        raise ArchiveServiceError("ai-start-here full_doctor mode requires Doctor diagnostics.")
    if mode == "full_doctor" and inspection_reads is None:
        raise ArchiveServiceError("ai-start-here full_doctor mode requires Doctor read observations.")
    full_doctor_run = mode == "full_doctor"
    observed_reads = {
        "zettel_bodies_read": bool((inspection_reads or {}).get("zettel_bodies_read")),
        "objet_bytes_read": bool((inspection_reads or {}).get("objet_bytes_read")),
        "archive_text_scanned_for_secret_patterns": bool(
            (inspection_reads or {}).get("archive_text_scanned_for_secret_patterns")
        ),
    }
    context = runtime_context(
        archive_root,
        expected_archive_id=expected_archive_id,
        expected_type=expected_type,
        strict=strict,
        redact_local_paths=redact_local_paths,
        diagnostics=diagnostics,
        inspection_mode=mode,
        inspection_reads=observed_reads,
    )
    entrypoints = context.get("canonical_entrypoints") if isinstance(context.get("canonical_entrypoints"), dict) else {}
    identity_consistency = (
        context.get("identity_consistency")
        if isinstance(context.get("identity_consistency"), dict)
        else {"status": "identity_document_unavailable"}
    )
    operational_context = context.get("operational_context") if isinstance(context.get("operational_context"), dict) else {}
    read_order = entrypoints.get("read_order") if isinstance(entrypoints.get("read_order"), list) else []
    present_entrypoints = [
        {
            "path": item.get("path"),
            "role": item.get("role"),
            "kind": item.get("kind"),
            "required": bool(item.get("required")),
            "status": item.get("status"),
        }
        for item in read_order
        if isinstance(item, dict) and item.get("status") == "present"
    ]
    missing_required = [
        {
            "path": item.get("path"),
            "role": item.get("role"),
            "kind": item.get("kind"),
            "status": item.get("status"),
        }
        for item in read_order
        if isinstance(item, dict) and item.get("required") and item.get("status") != "present"
    ]
    session_start = (
        operational_context.get("session_start_injection")
        if isinstance(operational_context.get("session_start_injection"), dict)
        else None
    )
    session_start_summary = ai_start_here_session_start_summary(session_start)
    first_commands = (
        entrypoints.get("recommended_first_commands")
        if isinstance(entrypoints.get("recommended_first_commands"), list)
        else []
    )
    completed_commands = (
        entrypoints.get("completed_commands")
        if isinstance(entrypoints.get("completed_commands"), list)
        else []
    )
    next_commands = entrypoints.get("next_commands") if isinstance(entrypoints.get("next_commands"), list) else []
    ai_runtime_order = (
        entrypoints.get("ai_runtime_order") if isinstance(entrypoints.get("ai_runtime_order"), list) else []
    )
    remaining_ai_runtime_order = (
        entrypoints.get("remaining_ai_runtime_order")
        if isinstance(entrypoints.get("remaining_ai_runtime_order"), list)
        else []
    )
    action_routing = (
        context.get("action_routing")
        if isinstance(context.get("action_routing"), dict)
        else runtime_context_action_routing()
    )
    inbox_attention = ai_start_here_inbox_attention(
        require_existing_archive_root(archive_root)
    )

    next_lines: list[str] = []
    if session_start_summary and isinstance(session_start_summary.get("next"), list):
        next_lines.extend(
            item
            for item in session_start_summary["next"]
            if isinstance(item, str) and not runtime_context_step_is_already_satisfied(item)
        )
    if not next_lines:
        next_lines.append("Read AGENTS.md when the entrypoint map marks it present.")

    return {
        "ok": bool(context.get("ok")) and not missing_required,
        "lifecycle_action": "ai_start_here",
        "schema": "wom-kit/ai-start-here/v0.3",
        "archive_id": context.get("archive_id"),
        "archive_type": context.get("archive_type"),
        "scope": context.get("scope"),
        "principal": context.get("principal"),
        "identity_consistency": identity_consistency,
        "owner": context.get("owner"),
        "storage_authority": context.get("storage_authority")
        if isinstance(context.get("storage_authority"), dict)
        else local_sovereignty_authority_model(),
        "summary": {
            "purpose": "Give an entering AI operator one safe start-here map before broad archive exploration.",
            "start_here_file": entrypoints.get("start_here") or "archive.yml",
            "entrypoint_count": len(read_order),
            "present_entrypoint_count": len(present_entrypoints),
            "missing_required_count": len(missing_required),
            "operational_context_status": operational_context.get("status") or "unknown",
            "inspection_mode": mode,
            "runtime_context_included": True,
            "runtime_context_rerun_required": False,
            "identity_consistency_status": identity_consistency.get("status"),
            "doctor_checked": (
                context.get("doctor_summary", {}).get("checked")
                if isinstance(context.get("doctor_summary"), dict)
                else False
            ),
            "unpublished_draft_count": inbox_attention[
                "unpublished_draft_count"
            ],
            "inbox_attention_status": inbox_attention["status"],
        },
        "inspection": {
            "mode": mode,
            "full_doctor_run": full_doctor_run,
            "doctor_summary": context.get("doctor_summary")
            if isinstance(context.get("doctor_summary"), dict)
            else {"checked": False, "errors": 0, "warnings": 0, "infos": 0},
            "doctor_findings_field": "doctor_findings",
            "claim_boundary": (
                "Full Doctor diagnostics were run for this result."
                if full_doctor_run
                else "Quick start verifies identity, policy, entrypoint presence, and operating context only; it is not an archive health claim."
            ),
            "full_doctor_command": (
                "archive ai-start-here <archive-root> --dry-run --full-doctor --progress --format json"
            ),
            "read_observations": observed_reads,
        },
        "doctor_findings": context.get("doctor_findings")
        if isinstance(context.get("doctor_findings"), dict)
        else runtime_context_doctor_findings(
            None,
            root=require_existing_archive_root(archive_root),
            redact_local_paths=redact_local_paths,
        ),
        "first_read": {
            "start_here": entrypoints.get("start_here") or "archive.yml",
            "read_order": present_entrypoints,
            "missing_required": missing_required,
            "source_truths": entrypoints.get("source_truths") if isinstance(entrypoints.get("source_truths"), dict) else {},
        },
        "handoff": {
            "runtime_context_included": True,
            "runtime_context_rerun_required": False,
            "completed_commands_field": "completed_commands",
            "next_commands_field": "next_commands",
            "remaining_runtime_order_field": "remaining_ai_runtime_order",
        },
        "first_commands": first_commands,
        "completed_commands": completed_commands,
        "next_commands": next_commands,
        "ai_runtime_order": ai_runtime_order,
        "remaining_ai_runtime_order": remaining_ai_runtime_order,
        "action_routing": action_routing,
        "source_fidelity_policy": (
            context.get("source_fidelity_policy")
            if isinstance(context.get("source_fidelity_policy"), dict)
            else source_fidelity_policy()
        ),
        "inbox_attention": inbox_attention,
        "runtime_guidance_readiness": context.get("runtime_guidance_readiness"),
        "agent_instruction_policy": context.get("agent_instruction_policy"),
        "operational_context": {
            "status": operational_context.get("status") or "unknown",
            "record_path": operational_context.get("record_path"),
            "session_start": session_start_summary,
            "action_routing": operational_context.get("action_routing")
            if isinstance(operational_context.get("action_routing"), dict)
            else action_routing,
            "recommended_commands": operational_context.get("recommended_commands")
            if isinstance(operational_context.get("recommended_commands"), list)
            else [],
        },
        "conversation_status_board": {
            "allowed": True,
            "web_ui_required": False,
            "suggested_sections": [
                "Outcome",
                "Evidence basis",
                "Privacy and approval boundary",
                "Remaining work",
                "Next safe command",
            ],
        },
        "next_safe_steps": unique_preserve_order(
            [
                "This ai-start-here result already includes runtime-context; do not run runtime-context again before using this map.",
                *(
                    [
                        "Identity declarations need review; run archive identity-reconcile <archive-root> --dry-run --format json before relying on the conflicting metadata."
                    ]
                    if identity_consistency.get("status") not in {"aligned", "identity_document_unavailable"}
                    else []
                ),
                *next_lines,
                (
                    "Review the quick start map first; run ai-start-here --full-doctor only when a complete archive health check is needed."
                    if not full_doctor_run
                    else "Full Doctor completed for this start-here result; inspect its blocker and warning counts before broad work."
                ),
                "Read AGENTS.md when canonical_entrypoints marks it present.",
                "Honor agent_instruction_policy.write_actions_blocked before every write; never infer precedence from unmarked prose or auto-rewrite an instruction file.",
                "Search zets and indexed records through archive search <archive-root> <query> --count-total --format json; raw grep and raw SQL are not authoritative WOM search results.",
                "Create AI-assisted drafts only through archive create-draft dry-run and its reviewed replay; never write Markdown directly into inbox/.",
                *(
                    [
                        "Review the unpublished-draft attention now with archive inbox-pipeline-audit <archive-root> --dry-run --format json; do not let a pending publication disappear into a later session."
                    ]
                    if inbox_attention["review_recommended"]
                    else []
                ),
                "Run first-read-readiness before the exhaustive catalog pass; treat a non-ready result as an explicit abstract or unique-id repair queue, not as permission to invent or auto-write missing memory.",
                "Run abstract-freshness after first-read-readiness; treat stale or unverified rows as a human review queue and never auto-rewrite an abstract or body.",
                "Run zet-catalog with projection=reading and coverage_mode=strict, keep the first response_profile full, inspect item and compact response-envelope estimates, set a host-appropriate max_estimated_tokens plus an explicit response_envelope_reserve_tokens when needed, then optionally use response_profile=continuation on later pages while following every continuation token before claiming archive-wide zet coverage.",
                "Treat archive_wide_coverage_claim_ready as zet visitation only; require archive_wide_abstract_reading_claim_ready before saying every required abstract was available and read, and report abstract gaps without auto-writing replacements.",
                "If the host goal already supplies verified zet ids, use seeded_connection_walk with those ids; never invent a seed or stop after the seeded component.",
                "Keep projection=reading for the compact pass; use routed_reading with seeded_connection_walk only when the host or human needs a per-item explanation of the connection order and can afford the larger payload.",
                "Use only read-only commands until the human approves a write operation.",
                "Treat local WOM records as canonical; GitHub, object storage, and external databases are backup or replica layers and may not silently overwrite local state.",
            ]
        ),
        "safety_boundaries": {
            "read_only": True,
            "provider_api_called": False,
            "files_written": False,
            "secrets_read": False,
            "credential_store_accessed": False,
            "archive_text_scanned_for_secret_patterns": observed_reads[
                "archive_text_scanned_for_secret_patterns"
            ],
            "zettel_bodies_read": observed_reads["zettel_bodies_read"],
            "objet_bytes_read": observed_reads["objet_bytes_read"],
            "local_paths_redacted": bool(redact_local_paths),
            "zettel_or_objet_body_echoed": False,
        },
        "blockers": unique_preserve_order([*context.get("blockers", []), *[f"required entrypoint missing: {item.get('path')}" for item in missing_required]]),
        "warnings": unique_preserve_order(
            [
                *context.get("warnings", []),
                *(
                    [inbox_attention["human_summary"]]
                    if inbox_attention["review_recommended"]
                    or not inbox_attention["complete"]
                    else []
                ),
            ]
        ),
        "redaction": context.get("redaction", {"local_paths_redacted": bool(redact_local_paths)}),
    }


def ai_start_here_session_start_summary(session_start: dict[str, Any] | None) -> dict[str, Any] | None:
    if not session_start:
        return None
    summary: dict[str, Any] = {}
    for key in ("source", "mission_summary", "phase"):
        value = session_start.get(key)
        if isinstance(value, str):
            summary[key] = value
    for key in ("next", "blocked"):
        value = session_start.get(key)
        if isinstance(value, list):
            summary[key] = [item for item in value if isinstance(item, str)]
    return summary


def load_runtime_context_yaml(root: Path, relative_path: str, messages: list[str], *, required: bool) -> dict[str, Any]:
    try:
        data = load_yaml(read_archive_text(root, relative_path))
    except ArchiveServiceError as exc:
        if required:
            messages.append(f"{relative_path} could not be read: {exc}")
        return {}
    except Exception as exc:
        if required:
            messages.append(f"{relative_path} could not be parsed as YAML: {exc}")
        else:
            messages.append(f"{relative_path} could not be parsed as YAML.")
        return {}
    if not isinstance(data, dict):
        messages.append(f"{relative_path} must be a YAML object.")
        return {}
    return json_safe(data)


def runtime_type_mismatch_message(expected_type: str, archive_type: str | None, scope: str | None) -> str:
    found_values = unique_preserve_order([item for item in [archive_type, scope] if item])
    found = ", ".join(found_values) or "unknown"
    return f"Expected archive type {expected_type}, found {found}."


def runtime_context_doctor_summary(
    diagnostics: list[dict[str, Any]] | None,
    *,
    strict: bool,
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any]:
    if diagnostics is None:
        return {"checked": False, "errors": 0, "warnings": 0, "infos": 0}
    errors = sum(1 for item in diagnostics if item.get("severity") == "ERROR")
    warning_count = sum(1 for item in diagnostics if item.get("severity") == "WARN")
    infos = sum(1 for item in diagnostics if item.get("severity") == "INFO")
    if errors:
        blockers.append(f"archive doctor reported {errors} error(s).")
    if warning_count:
        message = f"archive doctor reported {warning_count} warning(s)."
        if strict:
            blockers.append(message)
        else:
            warnings.append(message)
    return {"checked": True, "errors": errors, "warnings": warning_count, "infos": infos}


def runtime_context_doctor_findings(
    diagnostics: list[dict[str, Any]] | None,
    *,
    root: Path,
    redact_local_paths: bool,
    root_aliases: tuple[str, ...] = (),
) -> dict[str, Any]:
    selected_levels = ["ERROR", "WARN"]
    if diagnostics is None:
        return {
            "checked": False,
            "selected_levels": selected_levels,
            "total": 0,
            "returned": 0,
            "truncated": False,
            "code_counts": [],
            "items": [],
            "suggested_commands": [],
            "suggested_command_entries": [],
            "suggested_commands_truncated": False,
            "suggested_command_entries_truncated": False,
            "suggested_command_entries_authoritative": True,
            "claim_boundary": "Doctor did not run; no archive health findings are available.",
        }

    findings: list[dict[str, Any]] = []
    code_counts: dict[tuple[str, str], int] = {}
    suggested_commands: list[str] = []
    suggested_command_entries: list[dict[str, Any]] = []
    seen_suggested_commands: set[str] = set()
    for raw_item in diagnostics:
        if not isinstance(raw_item, dict):
            continue
        severity = str(raw_item.get("severity") or "").upper()
        if severity not in selected_levels:
            continue
        code = str(raw_item.get("code") or "unknown_diagnostic").strip() or "unknown_diagnostic"
        code_counts[(severity, code)] = code_counts.get((severity, code), 0) + 1
        item: dict[str, Any] = {
            "severity": severity,
            "code": code,
            "message": runtime_context_doctor_finding_text(
                raw_item.get("message"),
                root=root,
                redact_local_paths=redact_local_paths,
                root_aliases=root_aliases,
            )
            or "",
            "path": runtime_context_doctor_finding_path(
                raw_item.get("path"),
                root=root,
                redact_local_paths=redact_local_paths,
            ),
        }
        for field in ("hint", "suggested_command", "compatibility_target"):
            value = runtime_context_doctor_finding_text(
                raw_item.get(field),
                root=root,
                redact_local_paths=redact_local_paths,
                root_aliases=root_aliases,
            )
            if value:
                item[field] = value
        raw_suggested_status = raw_item.get("suggested_command_status")
        suggested_status = (
            copy.deepcopy(raw_suggested_status)
            if isinstance(raw_suggested_status, dict)
            else None
        )
        if suggested_status is not None:
            item["suggested_command_status"] = suggested_status
        command = item.get("suggested_command")
        if isinstance(command, str) and command not in seen_suggested_commands:
            seen_suggested_commands.add(command)
            nested_availability = (
                suggested_status.get("capability_availability")
                if isinstance(suggested_status, dict)
                else None
            )
            safe_bare_candidate = bool(
                isinstance(suggested_status, dict)
                and suggested_status.get("resolution_state") == "resolved"
                and suggested_status.get("requested_mode_available") is True
                and isinstance(nested_availability, dict)
                and nested_availability.get("available") is True
            )
            suggested_command_entries.append(
                {
                    "suggested_command": command,
                    "suggested_command_status": suggested_status,
                    "bare_execution_candidate": safe_bare_candidate,
                }
            )
            if safe_bare_candidate:
                suggested_commands.append(command)
        findings.append(item)

    severity_order = {"ERROR": 0, "WARN": 1}
    count_rows = [
        {"severity": severity, "code": code, "count": count}
        for (severity, code), count in sorted(
            code_counts.items(),
            key=lambda row: (severity_order[row[0][0]], row[0][1]),
        )
    ]
    returned_items = findings[:RUNTIME_CONTEXT_DOCTOR_FINDING_LIMIT]
    returned_commands = suggested_commands[:RUNTIME_CONTEXT_DOCTOR_COMMAND_LIMIT]
    returned_command_entries = suggested_command_entries[
        :RUNTIME_CONTEXT_DOCTOR_COMMAND_LIMIT
    ]
    return {
        "checked": True,
        "selected_levels": selected_levels,
        "total": len(findings),
        "returned": len(returned_items),
        "truncated": len(returned_items) < len(findings),
        "code_counts": count_rows,
        "items": returned_items,
        "suggested_commands": returned_commands,
        "suggested_command_entries": returned_command_entries,
        "suggested_commands_truncated": len(returned_commands) < len(suggested_commands),
        "suggested_command_entries_truncated": (
            len(returned_command_entries) < len(suggested_command_entries)
        ),
        "suggested_command_entries_authoritative": True,
        "claim_boundary": (
            "ERROR and WARN findings are included so an operator can identify the completed Doctor result "
            "without rerunning it. INFO diagnostics remain count-only. "
            "suggested_command_entries is authoritative and preserves each parser-derived status; "
            "the compatibility suggested_commands list contains only explicitly available modes."
        ),
    }


def runtime_context_doctor_finding_path(
    value: Any,
    *,
    root: Path,
    redact_local_paths: bool,
) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    candidate = Path(text)
    is_absolute = bool(candidate.is_absolute() or WINDOWS_ABSOLUTE_RE.match(text) or UNC_PATH_RE.match(text))
    if not is_absolute:
        normalized = text.replace("\\", "/")
        if contains_forbidden_location_reference(text):
            return "<local-path-redacted>"
        if normalized == ".":
            return normalized
        try:
            return normalize_archive_relative_path(normalized)
        except ArchivePathError:
            return "<local-path-redacted>"
    if not redact_local_paths:
        return text
    try:
        return archive_relative_path(candidate, root)
    except (ArchivePathError, OSError, RuntimeError, ValueError):
        return "<local-path-redacted>"


def runtime_context_doctor_finding_text(
    value: Any,
    *,
    root: Path,
    redact_local_paths: bool,
    root_aliases: tuple[str, ...] = (),
) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text or not redact_local_paths:
        return text or None
    root_text = str(root)
    variants = {
        root_text,
        root_text.replace("\\", "/"),
        root_text.replace("/", "\\"),
    }
    for alias in root_aliases:
        variants.add(alias)
        variants.add(alias.replace("\\", "/"))
        variants.add(alias.replace("/", "\\"))
    for variant in sorted((item for item in variants if item), key=len, reverse=True):
        text = re.sub(re.escape(variant), "<archive-root>", text, flags=re.IGNORECASE)
    if contains_forbidden_location_reference(text):
        return "<sensitive-diagnostic-text-redacted>"
    return text


def runtime_context_paths(root: Path, archive_config: dict[str, Any], warnings: list[str]) -> dict[str, str | None]:
    root_policy = archive_config.get("root_policy") if isinstance(archive_config.get("root_policy"), dict) else {}
    return {
        "inbox": runtime_context_relative_path(root, root_policy.get("ai_inbox"), "inbox/", warnings, "inbox", directory=True),
        "zettels": runtime_context_relative_path(root, root_policy.get("canonical_zettels"), "zettels/", warnings, "zettels", directory=True),
        "receipts": runtime_context_relative_path(root, None, "receipts/", warnings, "receipts", directory=True),
        "operational_context": runtime_context_relative_path(
            root,
            None,
            OPERATIONAL_CONTEXT_RELATIVE_PATH,
            warnings,
            "operational context",
            directory=False,
        ),
        "object_manifest": runtime_context_relative_path(
            root,
            root_policy.get("object_manifest"),
            "objects/manifests/files.jsonl",
            warnings,
            "object manifest",
            directory=False,
            only_if_exists=True,
        ),
    }


