def derived_text_toolchain_profile(extension: str | None = None, mime: str | None = None) -> dict[str, Any]:
    ext = normalize_extension_label(extension)
    mime_value = (mime or "").strip().lower()
    if not ext and mime_value:
        ext = extension_from_mime_hint(mime_value)

    def profile(
        *,
        family: str,
        textual_candidate: bool,
        extraction_route: str,
        derivation_kind: str,
        primary_tools: list[str],
        fallback_tools: list[str] | None = None,
        human_review: str = "review derived text before capture",
        blockers: list[str] | None = None,
        notes: list[str] | None = None,
    ) -> dict[str, Any]:
        return {
            "format_family": family,
            "extension": ext or None,
            "mime": mime_value or None,
            "textual_candidate": textual_candidate,
            "extraction_route": extraction_route,
            "recommended_derivation_kind": derivation_kind,
            "primary_tools": primary_tools,
            "fallback_tools": fallback_tools or [],
            "human_review": human_review,
            "blocker_labels": blockers or [],
            "notes": notes or [],
            "source_urls": derived_text_toolchain_source_urls(primary_tools + (fallback_tools or [])),
        }

    if ext in DERIVED_TEXT_PLAIN_TEXT_EXTENSIONS or mime_value.startswith("text/"):
        return profile(
            family="plain_text_or_markup",
            textual_candidate=True,
            extraction_route="utf8_parser",
            derivation_kind="parser",
            primary_tools=["built-in utf-8 text parser"],
            notes=["Verify encoding and preserve original objet separately."],
        )
    if ext == ".docx":
        return profile(
            family="office_open_xml_word",
            textual_candidate=True,
            extraction_route="structured_ooxml_parser",
            derivation_kind="parser",
            primary_tools=["python-docx"],
            fallback_tools=["LibreOffice headless conversion"],
            notes=["Also consider headers, footers, comments, and embedded images as separate future coverage cases."],
        )
    if ext == ".xlsx":
        return profile(
            family="office_open_xml_spreadsheet",
            textual_candidate=True,
            extraction_route="structured_ooxml_parser",
            derivation_kind="parser",
            primary_tools=["openpyxl"],
            fallback_tools=["LibreOffice headless conversion"],
            notes=["Preserve sheet names, cell coordinates, and formulas as review metadata when available."],
        )
    if ext == ".pptx":
        return profile(
            family="office_open_xml_presentation",
            textual_candidate=True,
            extraction_route="structured_ooxml_parser",
            derivation_kind="parser",
            primary_tools=["python-pptx"],
            fallback_tools=["LibreOffice headless conversion"],
            notes=["Slides can contain text in shapes, notes, tables, and embedded images."],
        )
    if ext in DERIVED_TEXT_LEGACY_OFFICE_EXTENSIONS:
        return profile(
            family="legacy_office_binary",
            textual_candidate=True,
            extraction_route="libreoffice_headless_conversion_then_parser",
            derivation_kind="parser",
            primary_tools=["LibreOffice headless conversion"],
            fallback_tools=["format-specific parser after conversion", "OCR if rendered output is image-only"],
            notes=["Treat old OLE Office files as text-bearing by default unless conversion fails."],
        )
    if ext in DERIVED_TEXT_HWP_EXTENSIONS:
        return profile(
            family="hwp_or_hwpx",
            textual_candidate=True,
            extraction_route="hwp_parser_or_conversion_fallback",
            derivation_kind="parser",
            primary_tools=["pyhwp hwp5txt"],
            fallback_tools=["LibreOffice headless conversion", "zip+xml extraction for hwpx", "OCR if rendered output is image-only"],
            notes=["Classify unsupported or damaged files honestly instead of pretending coverage."],
        )
    if ext in DERIVED_TEXT_PDF_EXTENSIONS or mime_value == "application/pdf":
        return profile(
            family="pdf",
            textual_candidate=True,
            extraction_route="pdf_triage_then_parser_or_ocr_or_vision",
            derivation_kind="parser",
            primary_tools=["PyMuPDF text extraction", "PyMuPDF render metadata"],
            fallback_tools=["Tesseract OCR", "LLM vision for complex layout", "human password entry for encrypted PDFs"],
            human_review="review reading order, page coverage, and OCR confidence",
            blockers=["encrypted_pdf_needs_password"],
            notes=["Born-digital PDFs can use parser extraction; scans, two-column layouts, forms, and handwriting need OCR or vision routing."],
        )
    if ext in DERIVED_TEXT_IMAGE_EXTENSIONS or mime_value.startswith("image/"):
        return profile(
            family="image_scan",
            textual_candidate=True,
            extraction_route="ocr_then_human_review",
            derivation_kind="ocr",
            primary_tools=["Tesseract OCR"],
            fallback_tools=["LLM vision for handwriting, tables, forms, or complex layout"],
            human_review="review OCR confidence and mark uncertain spans",
            notes=["Skip only when the image is confirmed non-textual or intentionally excluded."],
        )
    if ext in DERIVED_TEXT_AUDIO_EXTENSIONS or mime_value.startswith("audio/"):
        return profile(
            family="audio",
            textual_candidate=True,
            extraction_route="asr_then_human_review",
            derivation_kind="asr",
            primary_tools=["reviewed local ASR tool"],
            fallback_tools=["provider ASR only after credential and cost approval"],
            notes=["ASR is a future extraction route; this planner does not call any model or provider."],
        )
    if ext in {".odt", ".ods", ".odp", ".rtf"}:
        return profile(
            family="open_document_or_rtf",
            textual_candidate=True,
            extraction_route="libreoffice_or_structured_parser",
            derivation_kind="parser",
            primary_tools=["LibreOffice headless conversion"],
            fallback_tools=["format-specific parser"],
            notes=["Treat open office documents and RTF as text-bearing by default."],
        )
    return profile(
        family="unknown_or_non_textual",
        textual_candidate=False,
        extraction_route="manual_triage",
        derivation_kind="parser",
        primary_tools=["manual review"],
        notes=["Not counted as textual coverage unless extension, MIME, or human review marks it as text-bearing."],
    )


def normalize_extension_label(extension: str | None) -> str:
    text = (extension or "").strip().lower()
    if not text:
        return ""
    if "/" in text or "\\" in text or contains_forbidden_location_reference(text):
        return ""
    if not text.startswith("."):
        text = "." + text
    if not re.match(r"^\.[a-z0-9][a-z0-9._+-]{0,20}$", text):
        return ""
    return text


def extension_from_mime_hint(mime: str) -> str:
    mapping = {
        "application/pdf": ".pdf",
        "text/plain": ".txt",
        "text/markdown": ".md",
        "text/csv": ".csv",
        "application/json": ".json",
        "application/xml": ".xml",
        "text/html": ".html",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document": ".docx",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": ".xlsx",
        "application/vnd.openxmlformats-officedocument.presentationml.presentation": ".pptx",
        "application/msword": ".doc",
        "application/vnd.ms-excel": ".xls",
        "application/vnd.ms-powerpoint": ".ppt",
        "application/haansofthwp": ".hwp",
        "application/x-hwp": ".hwp",
    }
    if mime in mapping:
        return mapping[mime]
    if mime.startswith("image/"):
        return ".png"
    if mime.startswith("audio/"):
        return ".wav"
    return ""


def derived_text_toolchain_source_urls(tool_names: list[str]) -> list[dict[str, str]]:
    urls: list[dict[str, str]] = []
    for name in tool_names:
        key = name.lower()
        if "python-docx" in key:
            urls.append({"tool": "python-docx", "url": DERIVED_TEXT_TOOLCHAIN_SOURCE_URLS["python-docx"]})
        elif "openpyxl" in key:
            urls.append({"tool": "openpyxl", "url": DERIVED_TEXT_TOOLCHAIN_SOURCE_URLS["openpyxl"]})
        elif "python-pptx" in key:
            urls.append({"tool": "python-pptx", "url": DERIVED_TEXT_TOOLCHAIN_SOURCE_URLS["python-pptx"]})
        elif "libreoffice" in key:
            urls.append({"tool": "LibreOffice", "url": DERIVED_TEXT_TOOLCHAIN_SOURCE_URLS["libreoffice"]})
        elif "tesseract" in key:
            urls.append({"tool": "Tesseract OCR", "url": DERIVED_TEXT_TOOLCHAIN_SOURCE_URLS["tesseract"]})
        elif "pymupdf" in key:
            urls.append({"tool": "PyMuPDF", "url": DERIVED_TEXT_TOOLCHAIN_SOURCE_URLS["pymupdf"]})
        elif "pyhwp" in key or "hwp5txt" in key:
            urls.append({"tool": "pyhwp/hwp5txt", "url": DERIVED_TEXT_TOOLCHAIN_SOURCE_URLS["pyhwp"]})
    deduped: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for item in urls:
        key = (item["tool"], item["url"])
        if key not in seen:
            seen.add(key)
            deduped.append(item)
    return deduped


def derived_text_python_module_available(module_name: str) -> bool:
    try:
        return importlib.util.find_spec(module_name) is not None
    except (ImportError, AttributeError, ValueError):
        return False


def derived_text_executable_available(executable_name: str) -> bool:
    return shutil.which(executable_name) is not None


def derived_text_tool_hint_probe_key(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", value.strip().lower())


def derived_text_load_tool_hints(tool_hints: Path | str | None) -> tuple[dict[str, list[Path]], dict[str, Any], list[str]]:
    if tool_hints is None:
        return {}, {"provided": False, "accepted_probe_count": 0, "ignored_probe_count": 0, "path_echoed": False}, []

    hints_path = Path(tool_hints)
    raw = json.loads(hints_path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        return {}, {"provided": True, "accepted_probe_count": 0, "ignored_probe_count": 1, "path_echoed": False}, [
            "tool_hints_file_must_be_json_object"
        ]
    executables = raw.get("executables", {})
    if not isinstance(executables, dict):
        return {}, {"provided": True, "accepted_probe_count": 0, "ignored_probe_count": 1, "path_echoed": False}, [
            "tool_hints_executables_must_be_object"
        ]

    allowed_probe_keys = {
        derived_text_tool_hint_probe_key(str(check["probe"])): str(check["probe"])
        for check in DERIVED_TEXT_TOOLCHAIN_DOCTOR_CHECKS
        if check.get("kind") == "executable"
    }
    aliases = {
        "tesseractocr": "tesseract",
        "libreoffice": "libreoffice",
        "soffice": "soffice",
        "hwp5txt": "hwp5txt",
        "pyhwphwp5txt": "hwp5txt",
    }
    by_probe: dict[str, list[Path]] = {}
    ignored_count = 0
    warnings: list[str] = []
    for key, paths in executables.items():
        probe_key = aliases.get(derived_text_tool_hint_probe_key(str(key)), derived_text_tool_hint_probe_key(str(key)))
        probe = allowed_probe_keys.get(probe_key)
        if not probe:
            ignored_count += 1
            warnings.append("tool_hints_unknown_executable_probe_ignored")
            continue
        path_values = paths if isinstance(paths, list) else [paths]
        for item in path_values:
            if not isinstance(item, str) or not item.strip():
                ignored_count += 1
                warnings.append("tool_hints_invalid_path_value_ignored")
                continue
            path = Path(item).expanduser()
            if not path.is_absolute():
                path = hints_path.parent / path
            by_probe.setdefault(probe, []).append(path)
    accepted_count = sum(len(paths) for paths in by_probe.values())
    summary = {
        "provided": True,
        "accepted_probe_count": accepted_count,
        "ignored_probe_count": ignored_count,
        "path_echoed": False,
    }
    return by_probe, summary, unique_preserve_order(warnings)


def derived_text_executable_hint_available(executable_name: str, executable_hints: dict[str, list[Path]]) -> bool:
    for hint in executable_hints.get(executable_name, []):
        try:
            if hint.is_file():
                return True
        except OSError:
            continue
    return False


def derived_text_toolchain_doctor(
    archive_root: Path | str,
    *,
    dry_run: bool = True,
    tool_hints: Path | str | None = None,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    if not dry_run:
        blockers.append("derive-text doctor is read-only; pass --dry-run.")
    executable_hints, tool_hint_summary, hint_warnings = derived_text_load_tool_hints(tool_hints)

    checks: list[dict[str, Any]] = [
        {
            "tool": "built-in utf-8 text parser",
            "kind": "built_in",
            "probe": "python_text_io",
            "available": True,
            "purpose": "plain text and markup extraction route",
            "format_families": ["plain_text_or_markup"],
            "path_echoed": False,
            "secret_echoed": False,
            "hint_used": False,
        }
    ]
    tool_available: dict[str, bool] = {"built-in utf-8 text parser": True}

    for check in DERIVED_TEXT_TOOLCHAIN_DOCTOR_CHECKS:
        kind = str(check["kind"])
        probe = str(check["probe"])
        available = False
        if kind == "python_module":
            available = derived_text_python_module_available(probe)
        elif kind == "executable":
            path_available = derived_text_executable_available(probe)
            hint_available = derived_text_executable_hint_available(probe, executable_hints)
            available = path_available or hint_available
        elif kind == "built_in":
            available = True
        elif kind == "not_configured":
            available = False
        else:
            path_available = False
            hint_available = False
        if kind != "executable":
            path_available = False
            hint_available = False
        tool = str(check["tool"])
        tool_available[tool] = tool_available.get(tool, False) or available
        checks.append(
            {
                "tool": tool,
                "kind": kind,
                "probe": probe,
                "available": available,
                "purpose": check["purpose"],
                "format_families": check["format_families"],
                "path_echoed": False,
                "secret_echoed": False,
                "path_probe_available": path_available if kind == "executable" else None,
                "hint_probe_available": hint_available if kind == "executable" else None,
                "hint_used": hint_available,
            }
        )

    family_readiness: list[dict[str, Any]] = []
    for family in DERIVED_TEXT_TOOLCHAIN_DOCTOR_FAMILIES:
        ready_when_any = [str(tool) for tool in family.get("ready_when_any", [])]
        optional_tools = [str(tool) for tool in family.get("optional_tools", [])]
        available_required = [tool for tool in ready_when_any if tool_available.get(tool, False)]
        missing_required = [tool for tool in ready_when_any if not tool_available.get(tool, False)]
        missing_optional = [tool for tool in optional_tools if not tool_available.get(tool, False)]
        family_readiness.append(
            {
                "format_family": family["format_family"],
                "candidate_extensions": family["candidate_extensions"],
                "ready": bool(available_required),
                "available_tools": available_required,
                "missing_tools": missing_required,
                "missing_optional_tools": missing_optional,
                "notes": family.get("notes", []),
            }
        )

    ready_family_count = sum(1 for item in family_readiness if item["ready"])
    available_tool_count = sum(1 for item in checks if item["available"])
    known_tools = unique_preserve_order(str(item["tool"]) for item in checks if item["kind"] != "not_configured")
    missing_tools = [tool for tool in known_tools if not tool_available.get(tool, False)]
    not_ready_families = [str(item["format_family"]) for item in family_readiness if not item["ready"]]
    warnings: list[str] = []
    if not_ready_families:
        warnings.append("some_derived_text_format_families_need_tool_install_or_policy_configuration")
    return {
        "ok": not blockers,
        "dry_run": True,
        "lifecycle_action": "derived_text_toolchain_doctor",
        "archive_id": archive_id,
        "readiness_summary": {
            "checked_tool_count": len(checks),
            "available_tool_count": available_tool_count,
            "ready_family_count": ready_family_count,
            "total_family_count": len(family_readiness),
            "not_ready_families": not_ready_families,
            "missing_tools": missing_tools,
            "tool_hints": tool_hint_summary,
        },
        "tool_checks": checks,
        "family_readiness": family_readiness,
        "agent_operating_contract": derived_text_agent_operating_contract(),
        "closed_actions": derived_text_read_only_closed_actions(),
        "privacy_guards": {
            **derived_text_read_only_privacy_guards(),
            "tool_paths_echoed": False,
            "import_paths_echoed": False,
            "tool_hint_paths_echoed": False,
        },
        "would_change": [],
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings + hint_warnings),
    }


def derived_text_toolchain(
    archive_root: Path | str,
    *,
    extension: str | None = None,
    mime: str | None = None,
    dry_run: bool = True,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    if not dry_run:
        blockers.append("derive-text toolchain is read-only; pass --dry-run.")
    if not extension and not mime:
        blockers.append("Provide --extension or --mime.")
    profile = derived_text_toolchain_profile(extension, mime)
    return {
        "ok": not blockers,
        "dry_run": True,
        "lifecycle_action": "derived_text_toolchain_recommendation",
        "archive_id": archive_id,
        "toolchain": profile,
        "agent_operating_contract": derived_text_agent_operating_contract(),
        "closed_actions": derived_text_read_only_closed_actions(),
        "privacy_guards": derived_text_read_only_privacy_guards(),
        "would_change": [],
        "blockers": unique_preserve_order(blockers),
        "warnings": [],
    }


def derived_text_record_source_object_ids(records: list[dict[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for record in records:
        source_id = str(record.get("source_object_id") or "").strip().lower()
        if OBJECT_ID_RE.match(source_id):
            counts[source_id] = counts.get(source_id, 0) + 1
    return counts


def derived_text_manifest_record_extension(record: dict[str, Any]) -> str:
    logical_key = str(record.get("logical_key") or "").strip()
    if logical_key:
        suffix = PurePosixPath(logical_key.replace("\\", "/")).suffix.lower()
        if suffix:
            return normalize_extension_label(suffix)
    mime = str(record.get("mime") or "").strip().lower()
    return extension_from_mime_hint(mime)


def derived_text_record_has_encryption_hint(value: Any) -> bool:
    encrypted_keys = {"encrypted", "is_encrypted", "password_required", "requires_password", "needs_password"}
    if isinstance(value, dict):
        for key, child in value.items():
            if str(key).lower() in encrypted_keys and child is True:
                return True
            if derived_text_record_has_encryption_hint(child):
                return True
    if isinstance(value, list):
        return any(derived_text_record_has_encryption_hint(child) for child in value)
    return False


def derived_text_size_bucket(size_value: Any) -> str:
    if isinstance(size_value, bool) or not isinstance(size_value, (int, float)) or size_value < 0:
        return "unknown"
    size = int(size_value)
    if size == 0:
        return "zero"
    if size < 10_000:
        return "tiny"
    if size < 1_000_000:
        return "small"
    if size < 25_000_000:
        return "medium"
    return "large"


def derived_text_manifest_quality(records: list[dict[str, Any]], *, max_items: int) -> dict[str, Any]:
    issue_sample: list[dict[str, Any]] = []
    records_with_issues = 0
    missing_tool_version_count = 0
    unknown_tool_version_count = 0
    invalid_tool_version_count = 0
    missing_tool_name_count = 0
    invalid_derivation_kind_count = 0
    invalid_review_status_count = 0
    required_fields = [
        "source_object_id",
        "derivation_kind",
        "tool_name",
        "tool_version",
        "review_status",
    ]

    def safe_manifest_scalar(value: Any) -> bool:
        if not isinstance(value, str) or not value.strip():
            return False
        text = value.strip()
        if "\n" in text or "\r" in text or "\x00" in text:
            return False
        if contains_forbidden_location_reference(text) or source_intake_has_provider_url(text) or source_intake_secret_like(text):
            return False
        return True

    for index, record in enumerate(records, start=1):
        issues: list[str] = []
        source_object_id = str(record.get("source_object_id") or "").strip().lower()
        if not OBJECT_ID_RE.match(source_object_id):
            issues.append("source_object_id_invalid")

        derivation_kind = str(record.get("derivation_kind") or "").strip()
        if derivation_kind not in DERIVED_TEXT_DERIVATION_KINDS:
            issues.append("derivation_kind_invalid")
            invalid_derivation_kind_count += 1

        if not safe_manifest_scalar(record.get("tool_name")):
            issues.append("tool_name_missing_or_invalid")
            missing_tool_name_count += 1

        tool_version = record.get("tool_version")
        tool_version_text = str(tool_version or "").strip()
        if not tool_version_text:
            issues.append("tool_version_missing")
            missing_tool_version_count += 1
        elif not safe_manifest_scalar(tool_version):
            issues.append("tool_version_invalid")
            invalid_tool_version_count += 1
        elif tool_version_text.lower() in DERIVED_TEXT_UNKNOWN_VERSION_LABELS:
            issues.append("tool_version_unknown")
            unknown_tool_version_count += 1

        review_status = str(record.get("review_status") or "").strip()
        if review_status not in DERIVED_TEXT_REVIEW_STATUSES:
            issues.append("review_status_invalid")
            invalid_review_status_count += 1

        if not issues:
            continue
        records_with_issues += 1
        if len(issue_sample) < max_items:
            issue_sample.append(
                {
                    "record_index": index,
                    "source_object_id": source_object_id if OBJECT_ID_RE.match(source_object_id) else None,
                    "issues": unique_preserve_order(issues),
                    "body_text_echoed": False,
                    "local_path_echoed": False,
                    "tool_path_echoed": False,
                }
            )

    return {
        "status": "passed" if records_with_issues == 0 else "needs_review",
        "required_fields": required_fields,
        "derived_text_record_count": len(records),
        "records_with_required_metadata_count": len(records) - records_with_issues,
        "records_with_issues_count": records_with_issues,
        "missing_tool_version_count": missing_tool_version_count,
        "unknown_tool_version_count": unknown_tool_version_count,
        "invalid_tool_version_count": invalid_tool_version_count,
        "missing_tool_name_count": missing_tool_name_count,
        "invalid_derivation_kind_count": invalid_derivation_kind_count,
        "invalid_review_status_count": invalid_review_status_count,
        "issues_truncated": records_with_issues > len(issue_sample),
        "issue_sample": issue_sample,
        "closed_actions": {
            "source_file_body_read": False,
            "derived_text_body_read": False,
            "tool_executed": False,
            "provider_api_called": False,
            "writes": False,
        },
        "privacy_guards": {
            "body_text_echoed": False,
            "local_absolute_paths_echoed": False,
            "tool_paths_echoed": False,
            "provider_urls_echoed": False,
            "secret_values_echoed": False,
        },
    }


def derived_text_required_source_object_id(record: dict[str, Any]) -> str | None:
    provenance = record.get("provenance") if isinstance(record.get("provenance"), dict) else {}
    source_text_sha256 = provenance.get("source_text_sha256")
    text_sha256 = record.get("text_sha256")
    if not isinstance(source_text_sha256, str) or not SHA256_RE.fullmatch(source_text_sha256):
        return None
    if not isinstance(text_sha256, str) or not SHA256_RE.fullmatch(text_sha256):
        return None
    if source_text_sha256 == text_sha256:
        return None
    return f"sha256:{source_text_sha256}"


def derived_text_source_object_coverage(
    manifest_records: list[dict[str, Any]],
    derived_records: list[dict[str, Any]],
    *,
    max_items: int,
) -> dict[str, Any]:
    manifested_object_ids: set[str] = set()
    for record in manifest_records:
        object_id = str(record.get("object_id") or "").strip()
        sha256 = str(record.get("sha256") or "").strip()
        if (
            OBJECT_ID_RE.fullmatch(object_id)
            and SHA256_RE.fullmatch(sha256)
            and object_id == f"sha256:{sha256}"
        ):
            manifested_object_ids.add(object_id)
    required_by_object: dict[str, list[dict[str, Any]]] = {}
    for record in derived_records:
        required_object_id = derived_text_required_source_object_id(record)
        if required_object_id is None:
            continue
        required_by_object.setdefault(required_object_id, []).append(record)

    required_ids = sorted(required_by_object)
    missing_ids = [object_id for object_id in required_ids if object_id not in manifested_object_ids]
    missing_sample: list[dict[str, Any]] = []
    for object_id in missing_ids[:max_items]:
        records = required_by_object[object_id]
        first_record = records[0]
        missing_sample.append(
            {
                "required_object_id": object_id,
                "derived_text_id": first_record.get("derived_text_id"),
                "source_object_id": first_record.get("source_object_id"),
                "affected_derived_text_record_count": len(records),
                "body_text_echoed": False,
                "local_path_echoed": False,
            }
        )

    return {
        "status": "passed" if not missing_ids else "needs_objet_capture",
        "rule": "changed source text bytes must have a manifested objet identity before manifest-scoped source-byte coverage can pass",
        "scope_statement": (
            "This check proves manifest identity coverage only; it does not prove current local or remote byte availability."
        ),
        "byte_availability_checked": False,
        "manifest_record_proves_current_byte_availability": False,
        "exact_source_bytes_required_count": len(required_ids),
        "exact_source_bytes_manifested_count": len(required_ids) - len(missing_ids),
        "exact_source_bytes_missing_count": len(missing_ids),
        "affected_derived_text_record_count": sum(len(records) for records in required_by_object.values()),
        "missing_items_truncated": len(missing_ids) > len(missing_sample),
        "missing_sample": missing_sample,
        "closed_actions": {
            "source_file_body_read": False,
            "derived_text_body_read": False,
            "original_bytes_recreated": False,
            "files_written": False,
        },
    }


def derived_text_coverage(
    archive_root: Path | str,
    *,
    dry_run: bool = True,
    max_items: int = 25,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []
    if not dry_run:
        blockers.append("derive-text coverage is read-only; pass --dry-run.")
    max_items = max(0, min(int(max_items), 200))

    manifest_records = load_manifest_records(root)
    derived_records = load_derived_text_records(root)
    source_counts = derived_text_record_source_object_ids(derived_records)
    by_status: dict[str, int] = {}
    by_extension: dict[str, int] = {}
    by_toolchain_family: dict[str, int] = {}
    missing_items: list[dict[str, Any]] = []
    blocked_items: list[dict[str, Any]] = []
    covered_items: list[dict[str, Any]] = []
    textual_candidate_count = 0
    covered_textual_count = 0

    for record in manifest_records:
        object_id = str(record.get("object_id") or "").strip().lower()
        if not OBJECT_ID_RE.match(object_id):
            warnings.append("manifest_record_with_invalid_object_id_skipped")
            continue
        extension = derived_text_manifest_record_extension(record)
        mime = str(record.get("mime") or "").strip().lower()
        toolchain = derived_text_toolchain_profile(extension, mime)
        family = str(toolchain.get("format_family") or "unknown_or_non_textual")
        encrypted = derived_text_record_has_encryption_hint(record)
        derived_count = source_counts.get(object_id, 0)
        manifest_textual_signal = bool(toolchain.get("textual_candidate"))
        derived_text_signal = derived_count > 0
        textual_candidate = manifest_textual_signal or derived_text_signal
        textual_signal = "manifest_extension_or_mime" if manifest_textual_signal else None
        if derived_text_signal and not manifest_textual_signal:
            textual_signal = "derived_text_record_present"
            family = "derived_text_present_unknown_source"
            warnings.append("derived_text_records_used_as_textual_signal_for_unknown_manifest_mime")
        if textual_candidate:
            textual_candidate_count += 1
        if not textual_candidate:
            status = "not_textual_or_unknown"
        elif encrypted and derived_count == 0:
            status = "needs_password_or_encrypted"
        elif derived_count > 0:
            status = "covered"
            covered_textual_count += 1
        else:
            status = "missing_derived_text"
        by_status[status] = by_status.get(status, 0) + 1
        by_extension[extension or "<none>"] = by_extension.get(extension or "<none>", 0) + 1
        by_toolchain_family[family] = by_toolchain_family.get(family, 0) + 1
        item = {
            "object_id": object_id,
            "extension": extension or None,
            "mime": mime or None,
            "coverage_status": status,
            "derived_text_record_count": derived_count,
            "textual_signal": textual_signal,
            "toolchain_family": family,
            "recommended_derivation_kind": toolchain.get("recommended_derivation_kind"),
            "suggested_route": toolchain.get("extraction_route"),
            "size_bucket": derived_text_size_bucket(record.get("size_bytes")),
            "source_name_echoed": False,
            "local_path_echoed": False,
        }
        if status == "missing_derived_text":
            if len(missing_items) < max_items:
                missing_items.append(item)
        elif status == "needs_password_or_encrypted":
            if len(blocked_items) < max_items:
                blocked_items.append(item)
        elif status == "covered":
            if len(covered_items) < max_items:
                covered_items.append(item)

    missing_count = by_status.get("missing_derived_text", 0)
    blocked_count = by_status.get("needs_password_or_encrypted", 0)
    manifest_quality = derived_text_manifest_quality(derived_records, max_items=max_items)
    manifest_quality_issue_count = int(manifest_quality.get("records_with_issues_count") or 0)
    source_object_coverage = derived_text_source_object_coverage(
        manifest_records,
        derived_records,
        max_items=max_items,
    )
    source_bytes_missing_count = int(source_object_coverage.get("exact_source_bytes_missing_count") or 0)
    coverage_ratio = None
    if textual_candidate_count:
        coverage_ratio = covered_textual_count / textual_candidate_count
    gate_passed = missing_count == 0 and manifest_quality_issue_count == 0 and source_bytes_missing_count == 0
    if blocked_count:
        warnings.append("encrypted_or_password_required_textual_objets_need_human_resolution")
    if manifest_quality_issue_count:
        warnings.append("derived_text_manifest_quality_needs_review")
    if source_bytes_missing_count:
        warnings.append("derived_text_source_bytes_need_objet_capture")
    return {
        "ok": not blockers and gate_passed,
        "dry_run": True,
        "lifecycle_action": "derived_text_coverage_gate",
        "archive_id": archive_id,
        "coverage_gate": {
            "status": "passed" if gate_passed and not blockers else "blocked",
            "default_posture": "maximum_textual_objet_coverage",
            "textual_candidate_count": textual_candidate_count,
            "covered_textual_count": covered_textual_count,
            "missing_derived_text_count": missing_count,
            "needs_password_or_encrypted_count": blocked_count,
            "manifest_quality_issue_count": manifest_quality_issue_count,
            "exact_source_bytes_missing_count": source_bytes_missing_count,
            "coverage_ratio": coverage_ratio,
            "missing_items_truncated": missing_count > len(missing_items),
            "blocked_items_truncated": blocked_count > len(blocked_items),
        },
        "completeness_signal": derived_text_completeness_signal(
            manifest_record_count=len(manifest_records),
            derived_text_record_count=len(derived_records),
            textual_candidate_count=textual_candidate_count,
            covered_textual_count=covered_textual_count,
            missing_derived_text_count=missing_count,
            needs_password_or_encrypted_count=blocked_count,
            exact_source_bytes_missing_count=source_bytes_missing_count,
        ),
        "manifest_counts": {
            "object_manifest_record_count": len(manifest_records),
            "derived_text_record_count": len(derived_records),
            "by_status": by_status,
            "by_extension": by_extension,
            "by_toolchain_family": by_toolchain_family,
        },
        "manifest_quality": manifest_quality,
        "source_text_original_object_coverage": source_object_coverage,
        "missing_items": missing_items,
        "blocked_items": blocked_items,
        "covered_sample": covered_items,
        "agent_operating_contract": derived_text_agent_operating_contract(),
        "closed_actions": derived_text_read_only_closed_actions(),
        "privacy_guards": derived_text_read_only_privacy_guards(),
        "would_change": [],
        "next_safe_actions": [
            "Run derive-text toolchain for the missing families before extraction.",
            "Produce derived text outside this read-only gate, then capture it with derive-text capture --dry-run and --approve.",
            "Fix derived-text manifest quality issues such as missing tool_version before claiming extraction provenance is complete.",
            *(
                [
                    "Capture changed pre-normalization transcript or export bytes as an objet; never recreate those bytes from normalized derived text."
                ]
                if source_bytes_missing_count
                else []
            ),
            "Re-run derive-text coverage until missing_derived_text_count is zero or every exception has a blocker.",
        ],
        "blockers": unique_preserve_order(
            blockers
            + (["missing_derived_text"] if missing_count else [])
            + (["derived_text_manifest_quality_issues"] if manifest_quality_issue_count else [])
            + (["source_text_original_object_missing"] if source_bytes_missing_count else [])
        ),
        "warnings": unique_preserve_order(warnings),
    }


def derived_text_completeness_signal(
    *,
    manifest_record_count: int,
    derived_text_record_count: int,
    textual_candidate_count: int,
    covered_textual_count: int,
    missing_derived_text_count: int,
    needs_password_or_encrypted_count: int,
    exact_source_bytes_missing_count: int,
) -> dict[str, Any]:
    if manifest_record_count == 0:
        state = "no_manifested_objets"
    elif missing_derived_text_count:
        state = "manifest_scoped_incomplete"
    elif exact_source_bytes_missing_count:
        state = "manifest_scoped_source_bytes_incomplete"
    elif needs_password_or_encrypted_count:
        state = "manifest_scoped_with_blocked_items"
    else:
        state = "manifest_scoped_text_coverage_passed"
    return {
        "lifecycle_action": "derived_text_completeness_signal",
        "state": state,
        "scope_kind": "manifest_scoped",
        "scope_source_of_truth": [
            "objects/manifests/files.jsonl",
            DERIVED_TEXT_MANIFEST_RELATIVE_PATH,
        ],
        "full_mirror_claimed": False,
        "full_mirror_proof_present": False,
        "operator_reading": (
            "This signal covers manifested objets only. It is not proof that an external "
            "workspace, mailbox, cloud drive, or export has been fully mirrored."
        ),
        "counts": {
            "manifest_record_count": manifest_record_count,
            "derived_text_record_count": derived_text_record_count,
            "textual_candidate_count": textual_candidate_count,
            "covered_textual_count": covered_textual_count,
            "missing_derived_text_count": missing_derived_text_count,
            "needs_password_or_encrypted_count": needs_password_or_encrypted_count,
            "exact_source_bytes_missing_count": exact_source_bytes_missing_count,
        },
        "cannot_prove": [
            "external_workspace_fully_exported",
            "external_mailbox_fully_mirrored",
            "cloud_drive_fully_mirrored",
            "notion_or_workspace_full_account_coverage",
            "unmanifested_local_files_absent",
        ],
        "next_safe_actions": [
            "Treat passed coverage as derived-text coverage for manifested objets, not full source mirror completion.",
            "Record a separate source/export mirror receipt before claiming full external account coverage.",
            "Keep partial exports labeled partial until a human-reviewed mirror manifest exists.",
        ],
        "closed_actions": {
            "source_file_body_read": False,
            "external_workspace_scanned": False,
            "provider_api_called": False,
            "files_written": False,
            "secrets_read": False,
        },
    }


def derived_text_identity_digest(
    *,
    source_object_id: str,
    text_sha256: str,
    derivation_kind: str,
    tool_name: str,
    tool_version: str,
    model_name: str | None,
    model_version: str | None,
    review_status: str,
) -> str:
    identity = drop_none_values(
        {
            "source_object_id": source_object_id,
            "text_sha256": text_sha256,
            "derivation_kind": derivation_kind,
            "tool_name": tool_name,
            "tool_version": tool_version,
            "model_name": model_name,
            "model_version": model_version,
            "review_status": review_status,
        }
    )
    encoded = json.dumps(identity, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


def _derived_text_pair_metadata_blockers(
    *,
    derivation_kind: Any,
    tool_name: Any,
    tool_version: Any,
    review_status: Any,
    confidence: Any,
    language: Any,
    model_name: Any = None,
    model_version: Any = None,
    born_digital: Any = False,
) -> list[str]:
    # Shared source-object-free validation: standalone capture (via
    # _derived_text_metadata_blockers), selection generation, and paired envelope
    # validation all reuse this so a validly-approved pair can never be blocked by
    # a divergent reimplementation.
    blockers: list[str] = []
    if derivation_kind not in DERIVED_TEXT_DERIVATION_KINDS:
        blockers.append("derivation_kind_invalid")
    if review_status not in DERIVED_TEXT_REVIEW_STATUSES:
        blockers.append("review_status_invalid")
    for label, value in [("tool_name", tool_name), ("tool_version", tool_version)]:
        if not isinstance(value, str) or not value.strip() or "\n" in value or "\r" in value or "\x00" in value:
            blockers.append(f"{label}_invalid")
    for label, value in [("model_name", model_name), ("model_version", model_version)]:
        if value is not None and not isinstance(value, str):
            blockers.append(f"{label}_invalid")
    if language is not None and (
        not isinstance(language, str) or "\n" in language or "\r" in language or "\x00" in language
    ):
        blockers.append("language_invalid")
    if confidence is not None:
        if isinstance(confidence, bool) or not isinstance(confidence, (int, float)):
            blockers.append("confidence_invalid")
        elif confidence < 0 or confidence > 1:
            blockers.append("confidence_invalid")
    if not isinstance(born_digital, bool):
        blockers.append("born_digital_invalid")
    return unique_preserve_order(blockers)


def _derived_text_metadata_blockers(
    *,
    source_object_id: str,
    derivation_kind: str,
    tool_name: str,
    tool_version: str,
    review_status: str,
    confidence: float | int | None,
    language: str | None,
) -> list[str]:
    blockers: list[str] = []
    normalize_object_id(source_object_id, blockers)
    blockers.extend(
        _derived_text_pair_metadata_blockers(
            derivation_kind=derivation_kind,
            tool_name=tool_name,
            tool_version=tool_version,
            review_status=review_status,
            confidence=confidence,
            language=language,
        )
    )
    return unique_preserve_order(blockers)


# Static, blocker-keyed hint strings (never vary with the input, so they are safe to
# echo on refusal). text_file_not_utf8 keeps its legacy code for BOM-less input only;
# BOM-marked files always report a BOM-specific blocker instead (D8/D9).
DERIVED_TEXT_ENCODING_BLOCKER_HINTS = {
    "text_file_not_utf8": (
        "BOM-less text must be valid UTF-8; BOM-marked UTF-8 (utf-8-sig) and UTF-16 LE/BE are "
        "auto-handled; transcode any other encoding to UTF-8 before capture"
    ),
    "text_file_bom_encoding_unsupported": (
        "a UTF-32 BOM was detected; UTF-32 is not auto-decoded — transcode the file to UTF-8 before capture"
    ),
    "text_file_bom_encoding_undecodable": (
        "the file carries a BOM but its bytes do not decode strictly in that encoding "
        "(truncated, odd-length, or corrupt); re-export or repair the file, then transcode to UTF-8"
    ),
    "text_file_contains_nul": (
        "decoded text contains U+0000; the file is likely BOM-less UTF-16/UTF-32 — "
        "transcode it to UTF-8 before capture"
    ),
    "text_file_too_large": (
        "the text source exceeds the deterministic 64 MiB derived-text source cap; "
        "split or trim the file before capture"
    ),
}


def _bounded_stable_regular_file_read(
    path: Path,
    *,
    max_bytes: int,
) -> tuple[bytes | None, str | None]:
    """Read at most ``max_bytes`` from one stable regular-file identity.

    The fd is identity/size-bound to the pre-open lstat, the cumulative reader
    asks for at most cap+1 bytes, and a final fstat rejects growth, truncation,
    replacement, or same-size writes observed through mtime.  It returns one
    internal reason token so callers can preserve their public blocker vocab.
    """

    try:
        entry_stat = os.lstat(path)
    except FileNotFoundError:
        return None, "missing"
    except OSError:
        return None, "unreadable"
    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)

    def is_reparse(value: os.stat_result) -> bool:
        return bool(
            reparse_flag
            and getattr(value, "st_file_attributes", 0) & reparse_flag
        )

    if stat.S_ISLNK(entry_stat.st_mode):
        return None, "symlink"
    if is_reparse(entry_stat):
        return None, "reparse"
    if stat.S_ISDIR(entry_stat.st_mode):
        return None, "directory"
    if not stat.S_ISREG(entry_stat.st_mode):
        return None, "special"
    open_flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        fd = os.open(str(path), open_flags)
    except OSError:
        return None, "unreadable"

    def changed(before: os.stat_result, after: os.stat_result) -> bool:
        before_ino = int(getattr(before, "st_ino", 0) or 0)
        after_ino = int(getattr(after, "st_ino", 0) or 0)
        identity_changed = (
            int(before.st_dev) != int(after.st_dev)
            or (
                before_ino != 0
                and after_ino != 0
                and before_ino != after_ino
            )
        )
        return (
            identity_changed
            or int(before.st_size) != int(after.st_size)
            or int(getattr(before, "st_mtime_ns", 0))
            != int(getattr(after, "st_mtime_ns", 0))
        )

    try:
        before_stat = os.fstat(fd)
        if not stat.S_ISREG(before_stat.st_mode) or is_reparse(before_stat):
            return None, "special"
        if changed(entry_stat, before_stat):
            return None, "changed"
        if before_stat.st_size > max_bytes:
            return None, "too_large"
        chunks: list[bytes] = []
        total = 0
        while True:
            chunk = os.read(
                fd,
                min(1024 * 1024, max_bytes + 1 - total),
            )
            if not chunk:
                break
            total += len(chunk)
            if total > max_bytes:
                return None, "too_large"
            chunks.append(chunk)
        after_stat = os.fstat(fd)
        try:
            final_entry_stat = os.lstat(path)
        except OSError:
            return None, "changed"
        if (
            not stat.S_ISREG(final_entry_stat.st_mode)
            or stat.S_ISLNK(final_entry_stat.st_mode)
            or is_reparse(final_entry_stat)
            or changed(before_stat, after_stat)
            or changed(after_stat, final_entry_stat)
            or total != after_stat.st_size
        ):
            return None, "changed"
        return b"".join(chunks), None
    except OSError:
        return None, "unreadable"
    finally:
        os.close(fd)


def _stable_exact_file_observation(
    path: Path,
    *,
    expected_size: int,
    expected_sha256: str,
) -> str:
    """Return verified_exact, not_written, or ambiguous for one final path."""

    try:
        entry = os.lstat(path)
    except FileNotFoundError:
        return "not_written"
    except OSError:
        return "ambiguous"
    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)

    def unsafe(value: os.stat_result) -> bool:
        return bool(
            not stat.S_ISREG(value.st_mode)
            or stat.S_ISLNK(value.st_mode)
            or (
                reparse_flag
                and getattr(value, "st_file_attributes", 0) & reparse_flag
            )
        )

    def identity(value: os.stat_result) -> tuple[int, int, int, int]:
        return (
            int(value.st_dev),
            int(getattr(value, "st_ino", 0) or 0),
            int(value.st_size),
            int(getattr(value, "st_mtime_ns", 0)),
        )

    if unsafe(entry) or int(entry.st_size) != expected_size:
        return "ambiguous"
    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        fd = os.open(str(path), flags)
    except OSError:
        return "ambiguous"
    try:
        opened = os.fstat(fd)
        if unsafe(opened) or identity(opened) != identity(entry):
            return "ambiguous"
        digest = hashlib.sha256()
        total = 0
        while True:
            chunk = os.read(fd, 1024 * 1024)
            if not chunk:
                break
            total += len(chunk)
            if total > expected_size:
                return "ambiguous"
            digest.update(chunk)
        opened_after = os.fstat(fd)
        try:
            final_entry = os.lstat(path)
        except OSError:
            return "ambiguous"
        if (
            unsafe(opened_after)
            or unsafe(final_entry)
            or identity(opened_after) != identity(opened)
            or identity(final_entry) != identity(opened)
            or total != expected_size
            or digest.hexdigest() != expected_sha256
        ):
            return "ambiguous"
        return "verified_exact"
    except OSError:
        return "ambiguous"
    finally:
        try:
            os.close(fd)
        except OSError:
            pass


def _stable_exact_bytes_observation(path: Path, expected: bytes) -> str:
    return _stable_exact_file_observation(
        path,
        expected_size=len(expected),
        expected_sha256=hashlib.sha256(expected).hexdigest(),
    )


def _create_only_bytes_outcome_aware(path: Path, value: bytes) -> str:
    """Create one final file and classify any post-publication exception."""

    try:
        _write_bytes_create_if_absent(path, value)
    except FileExistsError:
        raise
    except Exception:
        # Publication helpers must classify ordinary post-publication failures
        # regardless of exception type.  BaseException subclasses such as
        # KeyboardInterrupt and SystemExit remain intentionally uncontained.
        observed = _stable_exact_bytes_observation(path, value)
        if observed == "verified_exact":
            return "verified_exact"
        if observed == "not_written":
            return "not_written"
        raise PublicationOutcomeUnverified("create_only_outcome_unverified")
    observed = _stable_exact_bytes_observation(path, value)
    if observed == "verified_exact":
        return "verified_exact"
    if observed == "not_written":
        return "not_written"
    raise PublicationOutcomeUnverified("create_only_outcome_unverified")


def _append_bytes_once(path: Path, value: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("ab") as handle:
        view = memoryview(value)
        offset = 0
        while offset < len(view):
            written = handle.write(view[offset:])
            if written is None or written <= 0:
                raise OSError("append_write_incomplete")
            offset += written
        handle.flush()
        os.fsync(handle.fileno())


def _jsonl_records_post_bytes(
    before: bytes,
    records: Iterable[Mapping[str, Any]],
) -> bytes:
    appended = (
        (b"\n" if before and not before.endswith(b"\n") else b"")
        + b"".join(
            (
                json.dumps(
                    dict(record),
                    ensure_ascii=False,
                    default=str,
                    separators=(",", ":"),
                )
                + "\n"
            ).encode("utf-8")
            for record in records
        )
    )
    return before + appended


def _append_jsonl_records_outcome_aware(
    path: Path,
    records: list[dict[str, Any]],
) -> str:
    """Append exact JSONL bytes and classify post-append exceptions."""

    if not records:
        return "not_written"
    try:
        before_entry = os.lstat(path)
    except FileNotFoundError:
        before_exists = False
        before = b""
    except OSError as error:
        raise PublicationOutcomeUnverified("manifest_before_unreadable") from error
    else:
        before_exists = True
        raw, reason = _bounded_stable_regular_file_read(
            path,
            max_bytes=int(before_entry.st_size),
        )
        if reason is not None or raw is None:
            raise PublicationOutcomeUnverified("manifest_before_unverified")
        before = raw
    expected = _jsonl_records_post_bytes(before, records)
    appended = expected[len(before) :]

    def classify_after_exception() -> str:
        if _stable_exact_bytes_observation(path, expected) == "verified_exact":
            return "verified_exact"
        if before_exists:
            if _stable_exact_bytes_observation(path, before) == "verified_exact":
                return "not_written"
        elif _stable_exact_bytes_observation(path, b"") == "not_written":
            return "not_written"
        raise PublicationOutcomeUnverified("manifest_append_outcome_unverified")

    try:
        _append_bytes_once(path, appended)
    except Exception:
        # Classify all ordinary exceptions after the append attempt; callers
        # must not lose an exact durable delta merely because a finalizer used
        # a non-OSError exception type.
        return classify_after_exception()
    if _stable_exact_bytes_observation(path, expected) == "verified_exact":
        return "verified_exact"
    return classify_after_exception()


def _derived_text_read_source_file(text_file: Path | str) -> tuple[bytes | None, list[str]]:
    # O_NOFOLLOW-fd + stable bounded read closes both the lstat->open and
    # fstat->unbounded-growth TOCTOU windows. Returns RAW bytes only; decoding
    # is _derived_text_decode_source_bytes' job.
    raw_bytes, reason = _bounded_stable_regular_file_read(
        Path(text_file),
        max_bytes=DERIVED_TEXT_MAX_SOURCE_BYTES,
    )
    blockers = {
        "missing": "text_file_missing",
        "unreadable": "text_file_unreadable",
        "symlink": "text_file_symlink_not_allowed",
        "reparse": "text_file_symlink_not_allowed",
        "directory": "text_file_is_directory",
        "special": "text_file_special_not_allowed",
        "too_large": "text_file_too_large",
        "changed": "text_file_changed_during_read",
    }
    return raw_bytes, ([blockers[reason]] if reason is not None else [])


def _derived_text_decode_source_bytes(
    raw: bytes,
) -> tuple[bytes | None, str | None, str | None, list[str]]:
    """Deterministic BOM-only decode ladder: no chardet, no guessing, strict everywhere.

    Returns (stored_utf8_bytes | None, source_text_encoding | None, detected_bom | None,
    blockers). The ladder ORDER is load-bearing: UTF-32-LE's BOM (FF FE 00 00) prefix-
    collides with UTF-16-LE's (FF FE), and a UTF-16 decode of UTF-32 bytes "succeeds" as
    NUL-interleaved mojibake, so the 4-byte UTF-32 BOM check runs BEFORE the 2-byte
    UTF-16 check. The transform is decode -> strip leading BOM -> encode UTF-8; line
    endings (CRLF included) are preserved byte-for-byte (D11: the transcript is
    evidence). On the BOM-less UTF-8 path stored bytes == raw bytes.
    """
    detected_bom: str | None = None
    encoding_label: str
    codec: str
    if raw[:3] == b"\xef\xbb\xbf":
        detected_bom = "utf-8-sig"
        encoding_label = "utf-8-sig"
        codec = "utf-8-sig"
    elif raw[:4] == b"\xff\xfe\x00\x00" or raw[:4] == b"\x00\x00\xfe\xff":
        detected_bom = "utf-32-le" if raw[:4] == b"\xff\xfe\x00\x00" else "utf-32-be"
        return None, None, detected_bom, ["text_file_bom_encoding_unsupported"]
    elif raw[:2] == b"\xff\xfe":
        # The recorded label comes from the SNIFFED BOM, not the codec name.
        detected_bom = "utf-16-le"
        encoding_label = "utf-16-le"
        codec = "utf-16"
    elif raw[:2] == b"\xfe\xff":
        detected_bom = "utf-16-be"
        encoding_label = "utf-16-be"
        codec = "utf-16"
    else:
        encoding_label = "utf-8"
        codec = "utf-8"
    try:
        text = raw.decode(codec, errors="strict")
    except UnicodeDecodeError:
        if detected_bom is not None:
            # Integrity problem (odd-length/truncated UTF-16, lone surrogates,
            # UTF-8-BOM-then-invalid), not an unsupported encoding (D9).
            return None, None, detected_bom, ["text_file_bom_encoding_undecodable"]
        return None, None, None, ["text_file_not_utf8"]
    if "\x00" in text:
        # Post-decode validity rule (D10): the only deterministic guard for BOM-less
        # UTF-16-of-ASCII (byte-valid UTF-8) and the backstop for any UTF-32 survivor.
        return None, None, detected_bom, ["text_file_contains_nul"]
    return text.encode("utf-8"), encoding_label, detected_bom, []


def _derived_text_build_record(
    *,
    archive_id: str,
    source_object_id: str,
    text_sha256: str,
    text_logical_key: str,
    size_bytes: int,
    text_filename: str,
    derivation_kind: str,
    tool_name: str,
    tool_version: str,
    model_name: str | None,
    model_version: str | None,
    confidence: float | int | None,
    language: str | None,
    review_status: str,
    born_digital: bool,
    captured_at: str,
    reviewed_by: str | None,
    source_text_encoding: str | None = None,
    source_text_sha256: str | None = None,
) -> dict[str, Any]:
    digest = derived_text_identity_digest(
        source_object_id=source_object_id,
        text_sha256=text_sha256,
        derivation_kind=derivation_kind,
        tool_name=tool_name,
        tool_version=tool_version,
        model_name=model_name,
        model_version=model_version,
        review_status=review_status,
    )
    return drop_none_values(
        {
            "schema": DERIVED_TEXT_RECORD_SCHEMA,
            "derived_text_id": f"derived-text:sha256:{digest}",
            "source_object_id": source_object_id,
            "derivation_kind": derivation_kind,
            "tool_name": tool_name,
            "tool_version": tool_version,
            "model_name": model_name,
            "model_version": model_version,
            "confidence": confidence,
            "language": language,
            "review_status": review_status,
            "born_digital": born_digital,
            "text_sha256": text_sha256,
            "text_logical_key": text_logical_key,
            "mime": "text/plain; charset=utf-8",
            "size_bytes": size_bytes,
            "provenance": drop_none_values(
                {
                    "source": "derived_text_capture",
                    "created_in": f"archive:{archive_id}",
                    "captured_at": captured_at,
                    "captured_by": reviewed_by,
                    "source_text_filename": text_filename,
                    # Raw-byte provenance (D12): identity/store/verification stay keyed
                    # to normalized UTF-8. These fields identify the pre-normalization
                    # bytes; exact recovery still requires their manifested objet.
                    "source_text_encoding": source_text_encoding,
                    "source_text_sha256": source_text_sha256,
                }
            ),
        }
    )


def _derived_text_write_receipt(root: Path, receipt: dict[str, Any], captured_at: str) -> str:
    receipts_dir = archive_internal_path(root, DERIVED_TEXT_CAPTURE_RECEIPTS_DIR)
    receipts_dir.mkdir(parents=True, exist_ok=True)
    timestamp_compact = re.sub(r"[^0-9TZ]", "", captured_at)
    while True:
        capture_id = f"{timestamp_compact}-{secrets.token_hex(6)}"
        receipt_path = receipts_dir / f"{capture_id}.json"
        receipt["receipt_id"] = f"receipt:derived-text-capture:{capture_id}"
        receipt_bytes = (
            json.dumps(
                json_safe(receipt),
                indent=2,
                ensure_ascii=False,
                default=str,
            )
            + "\n"
        ).encode("utf-8")
        try:
            outcome = _create_only_bytes_outcome_aware(
                receipt_path,
                receipt_bytes,
            )
        except FileExistsError:
            continue
        if outcome == "not_written":
            raise OSError("derived_text_receipt_not_written")
        return f"{DERIVED_TEXT_CAPTURE_RECEIPTS_DIR}/{capture_id}.json"


def _derived_text_capture_run(
    archive_root: Path | str,
    *,
    text_file: Path | str,
    source_object_id: str,
    derivation_kind: str,
    tool_name: str,
    tool_version: str,
    review_status: str,
    approve: bool,
    reviewed_by: str | None,
    model_name: str | None = None,
    model_version: str | None = None,
    confidence: float | int | None = None,
    language: str | None = None,
    born_digital: bool = False,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    captured_at = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    raw_bytes, file_blockers = _derived_text_read_source_file(text_file)
    return _derived_text_capture_core(
        root,
        archive_id,
        raw_bytes=raw_bytes,
        file_blockers=file_blockers,
        text_filename=Path(text_file).name,
        source_object_id=source_object_id,
        derivation_kind=derivation_kind,
        tool_name=tool_name,
        tool_version=tool_version,
        review_status=review_status,
        approve=approve,
        reviewed_by=reviewed_by,
        captured_at=captured_at,
        model_name=model_name,
        model_version=model_version,
        confidence=confidence,
        language=language,
        born_digital=born_digital,
        source_presence="manifest_lookup",
    )


def _derived_text_capture_core(
    root: Path,
    archive_id: str,
    *,
    raw_bytes: bytes | None,
    file_blockers: list[str],
    text_filename: str,
    source_object_id: str,
    derivation_kind: str,
    tool_name: str,
    tool_version: str,
    review_status: str,
    approve: bool,
    reviewed_by: str | None,
    captured_at: str,
    model_name: str | None = None,
    model_version: str | None = None,
    confidence: float | int | None = None,
    language: str | None = None,
    born_digital: bool = False,
    source_presence: str = "manifest_lookup",
    paired_with: dict[str, Any] | None = None,
) -> dict[str, Any]:
    blockers = _derived_text_metadata_blockers(
        source_object_id=source_object_id,
        derivation_kind=derivation_kind,
        tool_name=tool_name,
        tool_version=tool_version,
        review_status=review_status,
        confidence=confidence,
        language=language,
    )
    normalized_source_object_id = normalize_object_id(source_object_id, []) if not blockers else ""
    source_record_present = False
    if normalized_source_object_id:
        if source_presence == "paired_same_run":
            # Usable ONLY by the paired objet-capture path: phase ordering (original
            # bytes durable -> original manifest line flushed+fsynced -> derived
            # registration) guarantees the source record is durable on approve and
            # planned-non-blocked on dry-run. find_manifest_record reads the manifest
            # from DISK while the paired run's objet manifest handle is buffered, so a
            # disk lookup here would deterministically fail; the caller passes the
            # object_id minted/confirmed in phase 1 instead (no per-item full rescan).
            source_record_present = True
        else:
            source_record_present = find_manifest_record(root, normalized_source_object_id) is not None
            if not source_record_present:
                blockers.append("source_object_missing")

    blockers.extend(file_blockers)
    stored_bytes: bytes | None = None
    source_text_encoding: str | None = None
    detected_bom: str | None = None
    if raw_bytes is not None and not file_blockers:
        stored_bytes, source_text_encoding, detected_bom, decode_blockers = _derived_text_decode_source_bytes(
            raw_bytes
        )
        blockers.extend(decode_blockers)
    if blockers or stored_bytes is None or raw_bytes is None:
        blocked: dict[str, Any] = {
            "ok": False,
            "dry_run": not approve,
            "lifecycle_action": "derived_text_capture_plan" if not approve else "derived_text_capture",
            "item_status": "blocked",
            "archive_id": archive_id,
            "source_object_id": normalized_source_object_id or source_object_id,
            "source_object_present": source_record_present,
            "derived_text_id": None,
            "text_logical_key": None,
            "planned_action": "blocked",
            "action": "blocked",
            "blockers": unique_preserve_order(blockers),
            "warnings": [],
            "would_change": [],
        }
        if detected_bom is not None:
            blocked["detected_bom"] = detected_bom
        hints = {
            code: DERIVED_TEXT_ENCODING_BLOCKER_HINTS[code]
            for code in blocked["blockers"]
            if code in DERIVED_TEXT_ENCODING_BLOCKER_HINTS
        }
        if hints:
            blocked["blocker_hints"] = hints
        return blocked

    return _derived_text_register(
        root,
        archive_id=archive_id,
        stored_text_bytes=stored_bytes,
        source_text_encoding=source_text_encoding,
        source_text_sha256=hashlib.sha256(raw_bytes).hexdigest(),
        text_filename=text_filename,
        source_object_id=normalized_source_object_id,
        source_record_present=source_record_present,
        derivation_kind=derivation_kind,
        tool_name=tool_name,
        tool_version=tool_version,
        review_status=review_status,
        approve=approve,
        reviewed_by=reviewed_by,
        captured_at=captured_at,
        model_name=model_name,
        model_version=model_version,
        confidence=confidence,
        language=language,
        born_digital=born_digital,
        paired_with=paired_with,
    )


def _derived_text_register(
    root: Path,
    *,
    archive_id: str,
    stored_text_bytes: bytes,
    source_text_encoding: str | None,
    source_text_sha256: str,
    text_filename: str,
    source_object_id: str,
    source_record_present: bool,
    derivation_kind: str,
    tool_name: str,
    tool_version: str,
    review_status: str,
    approve: bool,
    reviewed_by: str | None,
    captured_at: str,
    model_name: str | None = None,
    model_version: str | None = None,
    confidence: float | int | None = None,
    language: str | None = None,
    born_digital: bool = False,
    paired_with: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if approve:
        return _compound_exact_human_approval_blocked(
            lifecycle_action="derived_text_register",
        )
    return _derived_text_register_legacy_core(
        root,
        archive_id=archive_id,
        stored_text_bytes=stored_text_bytes,
        source_text_encoding=source_text_encoding,
        source_text_sha256=source_text_sha256,
        text_filename=text_filename,
        source_object_id=source_object_id,
        source_record_present=source_record_present,
        derivation_kind=derivation_kind,
        tool_name=tool_name,
        tool_version=tool_version,
        review_status=review_status,
        approve=False,
        reviewed_by=reviewed_by,
        captured_at=captured_at,
        model_name=model_name,
        model_version=model_version,
        confidence=confidence,
        language=language,
        born_digital=born_digital,
        paired_with=paired_with,
    )


def _derived_text_register_legacy_core(
    root: Path,
    *,
    archive_id: str,
    stored_text_bytes: bytes,
    source_text_encoding: str | None,
    source_text_sha256: str,
    text_filename: str,
    source_object_id: str,
    source_record_present: bool,
    derivation_kind: str,
    tool_name: str,
    tool_version: str,
    review_status: str,
    approve: bool,
    reviewed_by: str | None,
    captured_at: str,
    model_name: str | None = None,
    model_version: str | None = None,
    confidence: float | int | None = None,
    language: str | None = None,
    born_digital: bool = False,
    paired_with: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Historical derived-text engine for bounded regression fixtures only.

    Production callers must enter through ``_derived_text_register``, whose
    approve branch is fixed-closed in v0.4.0. This underscore-only core is not
    exported or dispatched by CLI/MCP code.
    """
    # Everything from record-build through store-write/verify, manifest append+fsync,
    # and receipt write, under _DerivedTextManifestLock. Identity (text_sha256,
    # text_logical_key, derived_text_id, size_bytes) and lossless verification are
    # computed over the STORED normalized UTF-8 bytes (D12); the raw-byte provenance
    # travels alongside as source_text_encoding/source_text_sha256.
    normalized_source_object_id = source_object_id
    blockers: list[str] = []
    warnings: list[str] = []
    if len(stored_text_bytes) == 0:
        # Keyed to STORED length so a BOM-only file still warns.
        warnings.append("zero_byte_text")
    text_bytes = stored_text_bytes
    text_sha256 = hashlib.sha256(text_bytes).hexdigest()
    text_logical_key = f"{DERIVED_TEXT_STORE_PREFIX}/{text_sha256[:2]}/{text_sha256}.txt"
    record = _derived_text_build_record(
        archive_id=archive_id,
        source_object_id=normalized_source_object_id,
        text_sha256=text_sha256,
        text_logical_key=text_logical_key,
        size_bytes=len(text_bytes),
        text_filename=text_filename,
        derivation_kind=derivation_kind,
        tool_name=tool_name.strip(),
        tool_version=tool_version.strip(),
        model_name=model_name.strip() if isinstance(model_name, str) and model_name.strip() else None,
        model_version=model_version.strip() if isinstance(model_version, str) and model_version.strip() else None,
        confidence=confidence,
        language=language.strip() if isinstance(language, str) and language.strip() else None,
        review_status=review_status,
        born_digital=born_digital,
        captured_at=captured_at,
        reviewed_by=reviewed_by,
        source_text_encoding=source_text_encoding,
        source_text_sha256=source_text_sha256,
    )
    derived_text_id = str(record["derived_text_id"])
    dest = archive_internal_path(root, text_logical_key)

    def compute_planned_action(existing_ids: set[str]) -> str:
        record_present = derived_text_id in existing_ids
        dest_present = dest.is_file()
        if dest_present and sha256_path(dest) != text_sha256:
            return "dest_collision"
        if record_present and dest_present:
            return "skip_already_present"
        if record_present and not dest_present:
            return "re_materialize"
        if not record_present and dest_present:
            return "repair_append"
        return "capture"

    existing_ids = derived_text_canonical_record_ids(load_derived_text_records(root))
    planned_action = compute_planned_action(existing_ids)
    if planned_action == "dest_collision":
        blockers.append("dest_collision")

    base_output = {
        "dry_run": not approve,
        "lifecycle_action": "derived_text_capture_plan" if not approve else "derived_text_capture",
        "archive_id": archive_id,
        "source_object_id": normalized_source_object_id,
        "source_object_present": source_record_present,
        "derived_text_id": derived_text_id,
        "derivation_kind": derivation_kind,
        "review_status": review_status,
        "text_sha256": text_sha256,
        "text_logical_key": text_logical_key,
        "size_bytes": len(text_bytes),
        "mime": "text/plain; charset=utf-8",
        "source_text_encoding": source_text_encoding,
        "source_text_sha256": source_text_sha256,
    }
    planned_writes: list[str] = []
    if planned_action in ("capture", "re_materialize"):
        planned_writes.append(text_logical_key)
    if planned_action in ("capture", "repair_append"):
        planned_writes.append(f"{DERIVED_TEXT_MANIFEST_RELATIVE_PATH} (+1 line)")

    if not approve:
        timestamp_compact = re.sub(r"[^0-9TZ]", "", captured_at)
        return {
            "ok": not blockers,
            **base_output,
            "item_status": derived_text_capture_item_status(
                ok=not blockers,
                approve=False,
                planned_action=planned_action if not blockers else "blocked",
            ),
            "planned_action": planned_action if not blockers else "blocked",
            "proposed_receipt_path": f"{DERIVED_TEXT_CAPTURE_RECEIPTS_DIR}/{timestamp_compact}-{secrets.token_hex(6)}.json",
            "planned_writes": [] if blockers else planned_writes,
            "blockers": unique_preserve_order(blockers),
            "warnings": warnings,
            "would_change": [] if blockers else planned_writes,
        }

    if reviewed_by is None or not str(reviewed_by).strip():
        blockers.append("reviewed_by_required")

    manifest_record_appended = False
    stored_sha256_verified = False
    action = planned_action
    receipt_path_value: str | None = None
    if not blockers:
        try:
            archive_internal_path(root, DERIVED_TEXT_CAPTURE_RECEIPTS_DIR).mkdir(parents=True, exist_ok=True)
        except OSError:
            blockers.append("receipts_dir_unavailable")
    if not blockers:
        manifest_path = archive_internal_path(root, DERIVED_TEXT_MANIFEST_RELATIVE_PATH)
        with _DerivedTextManifestLock(root):
            action = compute_planned_action(derived_text_canonical_record_ids(load_derived_text_records(root)))
            if action == "dest_collision":
                blockers.append("dest_collision")
            if not blockers and action in ("capture", "re_materialize"):
                dest.parent.mkdir(parents=True, exist_ok=True)
                tmp = dest.parent / (dest.name + ".part-" + secrets.token_hex(8))
                try:
                    with tmp.open("wb") as handle:
                        handle.write(text_bytes)
                        handle.flush()
                        os.fsync(handle.fileno())
                    if sha256_path(tmp) != text_sha256:
                        tmp.unlink(missing_ok=True)
                        blockers.append("lossless_verification_failed")
                    else:
                        _objet_capture_fsync_dir(dest.parent)
                        os.replace(tmp, dest)
                        _objet_capture_fsync_dir(dest.parent)
                        if sha256_path(dest) != text_sha256:
                            dest.unlink(missing_ok=True)
                            blockers.append("lossless_verification_failed")
                        else:
                            stored_sha256_verified = True
                except Exception:
                    try:
                        tmp.unlink(missing_ok=True)
                    except OSError:
                        pass
                    observed = _stable_exact_file_observation(
                        dest,
                        expected_size=len(text_bytes),
                        expected_sha256=text_sha256,
                    )
                    if observed == "verified_exact":
                        stored_sha256_verified = True
                    elif observed == "not_written":
                        blockers.append("text_store_write_failed")
                    else:
                        raise PublicationOutcomeUnverified(
                            "derived_object_publish_outcome_unverified"
                        )
            elif action == "skip_already_present":
                stored_sha256_verified = dest.is_file() and sha256_path(dest) == text_sha256
            if not blockers and action in ("capture", "repair_append"):
                append_outcome = _append_jsonl_records_outcome_aware(
                    manifest_path,
                    [record],
                )
                if append_outcome == "verified_exact":
                    manifest_record_appended = True
                else:
                    blockers.append("manifest_append_failed")
    receipt = {
        "receipt_id": None,
        "schema": DERIVED_TEXT_CAPTURE_RECEIPT_SCHEMA,
        "dry_run": False,
        "ok": not blockers,
        "archive_id": archive_id,
        "reviewed_by": reviewed_by,
        "captured_at": captured_at,
        "derived_text_id": derived_text_id,
        "source_object_id": normalized_source_object_id,
        "text_sha256": text_sha256,
        "text_logical_key": text_logical_key,
        "source_text_encoding": source_text_encoding,
        "source_text_sha256": source_text_sha256,
        "derivation_kind": derivation_kind,
        "review_status": review_status,
        "planned_action": action,
        "action": {
            "capture": "captured",
            "repair_append": "repair_appended",
            "re_materialize": "re_materialized",
            "skip_already_present": "skip_already_present",
        }.get(action, action)
        if not blockers
        else "blocked",
        "manifest_record_appended": manifest_record_appended,
        "stored_sha256_verified": stored_sha256_verified,
        "blockers": unique_preserve_order(blockers),
        "warnings": warnings,
    }
    if paired_with is not None:
        # Paired-intake back-link (D7): the derived receipt is minted before the objet
        # receipt exists, so the file-path link can only point objet -> derived; this
        # hash-keyed reference is the reverse pointer.
        receipt["paired_with"] = paired_with
    if not (blockers and "receipts_dir_unavailable" in blockers):
        try:
            receipt_path_value = _derived_text_write_receipt(
                root,
                receipt,
                captured_at,
            )
        except PublicationOutcomeUnverified:
            raise
        except OSError:
            # Bytes and/or the manifest line may already be durable and were
            # losslessly verified above. Preserve those authoritative flags and
            # paths in the structured blocked result so callers can report the
            # exact delta and safely converge on replay instead of discarding it
            # behind the generic phase-2 exception boundary.
            blockers.append("derived_text_receipt_write_failed")
    return {
        "ok": not blockers,
        **base_output,
        "item_status": derived_text_capture_item_status(
            ok=not blockers,
            approve=True,
            action=(
                {
                    "capture": "captured",
                    "repair_append": "repair_appended",
                    "re_materialize": "re_materialized",
                    "skip_already_present": "skip_already_present",
                }.get(action, action)
                if not blockers
                else "blocked"
            ),
        ),
        "reviewed_by": reviewed_by,
        "captured_at": captured_at,
        "planned_action": action,
        "action": {
            "capture": "captured",
            "repair_append": "repair_appended",
            "re_materialize": "re_materialized",
            "skip_already_present": "skip_already_present",
        }.get(action, action)
        if not blockers
        else "blocked",
        "manifest_record_appended": manifest_record_appended,
        "stored_sha256_verified": stored_sha256_verified,
        "receipt_path": receipt_path_value,
        "blockers": unique_preserve_order(blockers),
        "warnings": warnings,
    }


def derived_text_capture_dry_run(
    archive_root: Path | str,
    *,
    text_file: Path | str,
    source_object_id: str,
    derivation_kind: str,
    tool_name: str,
    tool_version: str,
    review_status: str,
    model_name: str | None = None,
    model_version: str | None = None,
    confidence: float | int | None = None,
    language: str | None = None,
    born_digital: bool = False,
) -> dict[str, Any]:
    return _derived_text_capture_run(
        archive_root,
        text_file=text_file,
        source_object_id=source_object_id,
        derivation_kind=derivation_kind,
        tool_name=tool_name,
        tool_version=tool_version,
        review_status=review_status,
        approve=False,
        reviewed_by=None,
        model_name=model_name,
        model_version=model_version,
        confidence=confidence,
        language=language,
        born_digital=born_digital,
    )


def derived_text_capture_apply(
    archive_root: Path | str,
    *,
    text_file: Path | str,
    source_object_id: str,
    derivation_kind: str,
    tool_name: str,
    tool_version: str,
    review_status: str,
    reviewed_by: str,
    model_name: str | None = None,
    model_version: str | None = None,
    confidence: float | int | None = None,
    language: str | None = None,
    born_digital: bool = False,
) -> dict[str, Any]:
    return _compound_exact_human_approval_blocked(
        lifecycle_action="derived_text_capture_apply",
    )


def derived_text_capture_item_status(
    *,
    ok: bool,
    approve: bool,
    planned_action: str | None = None,
    action: str | None = None,
) -> str:
    if not ok:
        return "blocked"
    current = str(action or planned_action or "")
    if current == "skip_already_present":
        return "skipped"
    if approve and current in {"captured", "repair_appended", "re_materialized"}:
        return "written"
    if not approve and current in {"capture", "repair_append", "re_materialize"}:
        return "ready"
    return current or "unknown"


def _derived_text_capture_manifest_item_blocked(
    *,
    archive_id: str,
    line_number: int,
    item_id: str,
    blockers: list[str],
    approve: bool,
) -> dict[str, Any]:
    return {
        "ok": False,
        "dry_run": not approve,
        "lifecycle_action": "derived_text_capture_plan" if not approve else "derived_text_capture",
        "item_status": "blocked",
        "archive_id": archive_id,
        "manifest_line": line_number,
        "item_id": item_id,
        "source_object_id": None,
        "derived_text_id": None,
        "text_logical_key": None,
        "planned_action": "blocked",
        "action": "blocked",
        "blockers": unique_preserve_order(blockers),
        "warnings": [],
        "would_change": [],
    }


def _derived_text_capture_manifest_item_kwargs(
    raw: dict[str, Any],
    *,
    manifest_parent: Path,
) -> tuple[dict[str, Any] | None, list[str]]:
    blockers: list[str] = []
    missing = [field for field in DERIVED_TEXT_CAPTURE_MANIFEST_REQUIRED_FIELDS if field not in raw]
    blockers.extend(f"{field}_missing" for field in missing)
    text_file_value = raw.get("text_file")
    if not isinstance(text_file_value, str) or not text_file_value.strip():
        blockers.append("text_file_invalid")
    string_fields = ["source_object_id", "derivation_kind", "tool_name", "tool_version", "review_status"]
    for field in string_fields:
        value = raw.get(field)
        if not isinstance(value, str) or not value.strip():
            blockers.append(f"{field}_invalid")
    for field in ["model_name", "model_version", "language"]:
        value = raw.get(field)
        if value is not None and not isinstance(value, str):
            blockers.append(f"{field}_invalid")
    confidence = raw.get("confidence")
    if confidence is not None and (isinstance(confidence, bool) or not isinstance(confidence, (int, float))):
        blockers.append("confidence_invalid")
    born_digital = raw.get("born_digital", False)
    if not isinstance(born_digital, bool):
        blockers.append("born_digital_invalid")
    if blockers:
        return None, unique_preserve_order(blockers)

    text_file_path = Path(text_file_value.strip())
    if not text_file_path.is_absolute():
        text_file_path = manifest_parent / text_file_path
    return (
        {
            "text_file": text_file_path,
            "source_object_id": raw["source_object_id"].strip(),
            "derivation_kind": raw["derivation_kind"].strip(),
            "tool_name": raw["tool_name"].strip(),
            "tool_version": raw["tool_version"].strip(),
            "review_status": raw["review_status"].strip(),
            "model_name": raw.get("model_name"),
            "model_version": raw.get("model_version"),
            "confidence": confidence,
            "language": raw.get("language"),
            "born_digital": born_digital,
        },
        [],
    )


def _derived_text_capture_manifest_summary(items: list[dict[str, Any]], *, approve: bool) -> dict[str, int]:
    blocked = sum(1 for item in items if item.get("blockers"))
    if approve:
        actions = [str(item.get("action") or item.get("planned_action") or "") for item in items]
        return {
            "captured": actions.count("captured"),
            "repair_appended": actions.count("repair_appended"),
            "re_materialized": actions.count("re_materialized"),
            "skipped": actions.count("skip_already_present"),
            "blocked": blocked,
        }
    actions = [str(item.get("planned_action") or "") for item in items]
    return {
        "would_capture": actions.count("capture"),
        "would_repair_append": actions.count("repair_append"),
        "would_re_materialize": actions.count("re_materialize"),
        "would_skip": actions.count("skip_already_present"),
        "blocked": blocked,
    }


def _derived_text_capture_manifest_run(
    archive_root: Path | str,
    manifest_path: Path | str,
    *,
    approve: bool,
    reviewed_by: str | None,
) -> dict[str, Any]:
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    path = Path(manifest_path)
    try:
        manifest_text = path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return {
            "ok": False,
            "dry_run": not approve,
            "lifecycle_action": "derived_text_capture_batch_plan" if not approve else "derived_text_capture_batch",
            "archive_id": archive_id,
            "items": [],
            "summary": _derived_text_capture_manifest_summary([], approve=approve),
            "blockers": ["capture_manifest_not_utf8"],
            "warnings": [],
            "would_change": [],
        }
    except OSError:
        return {
            "ok": False,
            "dry_run": not approve,
            "lifecycle_action": "derived_text_capture_batch_plan" if not approve else "derived_text_capture_batch",
            "archive_id": archive_id,
            "items": [],
            "summary": _derived_text_capture_manifest_summary([], approve=approve),
            "blockers": ["capture_manifest_unreadable"],
            "warnings": [],
            "would_change": [],
        }
    if approve and (reviewed_by is None or not str(reviewed_by).strip()):
        return {
            "ok": False,
            "dry_run": False,
            "lifecycle_action": "derived_text_capture_batch",
            "archive_id": archive_id,
            "items": [],
            "summary": _derived_text_capture_manifest_summary([], approve=True),
            "blockers": ["reviewed_by_required"],
            "warnings": [],
            "would_change": [],
        }

    items: list[dict[str, Any]] = []
    planned_derived_ids: set[str] = set()
    planned_text_keys: set[str] = set()
    for line_number, line in enumerate(manifest_text.splitlines(), start=1):
        if not line.strip():
            continue
        try:
            raw = json.loads(line)
        except json.JSONDecodeError:
            items.append(
                _derived_text_capture_manifest_item_blocked(
                    archive_id=archive_id,
                    line_number=line_number,
                    item_id=f"line:{line_number}",
                    blockers=["capture_manifest_line_json_invalid"],
                    approve=approve,
                )
            )
            continue
        if not isinstance(raw, dict):
            items.append(
                _derived_text_capture_manifest_item_blocked(
                    archive_id=archive_id,
                    line_number=line_number,
                    item_id=f"line:{line_number}",
                    blockers=["capture_manifest_line_not_object"],
                    approve=approve,
                )
            )
            continue
        item_id = str(raw.get("item_id") or f"line:{line_number}")
        kwargs, blockers = _derived_text_capture_manifest_item_kwargs(raw, manifest_parent=path.parent)
        if blockers or kwargs is None:
            items.append(
                _derived_text_capture_manifest_item_blocked(
                    archive_id=archive_id,
                    line_number=line_number,
                    item_id=item_id,
                    blockers=blockers,
                    approve=approve,
                )
            )
            continue
        if approve:
            item_result = derived_text_capture_apply(
                root,
                reviewed_by=str(reviewed_by),
                **kwargs,
            )
        else:
            item_result = derived_text_capture_dry_run(root, **kwargs)
            derived_text_id = str(item_result.get("derived_text_id") or "")
            text_logical_key = str(item_result.get("text_logical_key") or "")
            if item_result.get("ok") and derived_text_id and text_logical_key:
                if derived_text_id in planned_derived_ids:
                    item_result["planned_action"] = "skip_already_present"
                    item_result["item_status"] = "skipped"
                    item_result["planned_writes"] = []
                    item_result["would_change"] = []
                elif text_logical_key in planned_text_keys and item_result.get("planned_action") == "capture":
                    item_result["planned_action"] = "repair_append"
                    item_result["item_status"] = "ready"
                    item_result["planned_writes"] = [f"{DERIVED_TEXT_MANIFEST_RELATIVE_PATH} (+1 line)"]
                    item_result["would_change"] = list(item_result["planned_writes"])
                if item_result.get("planned_action") in ("capture", "repair_append", "re_materialize"):
                    planned_derived_ids.add(derived_text_id)
                    planned_text_keys.add(text_logical_key)
        item_result["manifest_line"] = line_number
        item_result["item_id"] = item_id
        items.append(item_result)

    run_blockers = unique_preserve_order([code for item in items for code in item.get("blockers", [])])
    warnings = unique_preserve_order([code for item in items for code in item.get("warnings", [])])
    if not items:
        run_blockers.append("capture_manifest_empty")
    would_change = unique_preserve_order(
        [path for item in items for path in item.get("would_change", []) if isinstance(path, str)]
    )
    return {
        "ok": bool(items) and not run_blockers,
        "dry_run": not approve,
        "lifecycle_action": "derived_text_capture_batch_plan" if not approve else "derived_text_capture_batch",
        "archive_id": archive_id,
        "manifest_items": len(items),
        "items": items,
        "summary": _derived_text_capture_manifest_summary(items, approve=approve),
        "blockers": run_blockers,
        "warnings": warnings,
        "would_change": [] if run_blockers else would_change,
    }


def derived_text_capture_manifest_dry_run(
    archive_root: Path | str,
    manifest_path: Path | str,
) -> dict[str, Any]:
    return _derived_text_capture_manifest_run(
        archive_root,
        manifest_path,
        approve=False,
        reviewed_by=None,
    )


def derived_text_capture_manifest_apply(
    archive_root: Path | str,
    manifest_path: Path | str,
    *,
    reviewed_by: str,
) -> dict[str, Any]:
    return _compound_exact_human_approval_blocked(
        lifecycle_action="derived_text_capture_manifest_apply",
    )


OBJET_CAPTURE_RECEIPTS_DIR = "receipts/objet-capture"
OBJET_CAPTURE_SELECTION_MANIFESTS_DIR = "receipts/objet-capture-selections"
OBJET_CAPTURE_SELECTION_ACTION = "local_objet_capture_approved"
# Paired manifests (>= 1 item carrying a derived_text sub-object) MUST use this action
# string: `action` exact-match is the only lever pre-0.3.159 kits enforce, so old kits
# refuse paired manifests with selection_action_invalid instead of silently capturing
# the original and dropping the approved derived half (D3, fail-closed by design).
OBJET_CAPTURE_SELECTION_ACTION_WITH_DERIVED_TEXT = "local_objet_capture_with_derived_text_approved"
OBJET_CAPTURE_SELECTION_SCHEMA = "wom-kit/b4-selection/v0.2"
OBJET_CAPTURE_SELECTION_SCHEMA_WITH_DERIVED_TEXT = "wom-kit/b4-selection/v0.3"
OBJET_CAPTURE_RECEIPT_SCHEMA = "wom-kit/objet-capture-receipt/v0.3"
CAPTURE_ENABLEMENT_SCHEMA = "wom-kit/capture-enablement/v0.1"
CAPTURE_ENABLEMENT_RECEIPT_SCHEMA = "wom-kit/capture-enablement-receipt/v0.1"
CAPTURE_ENABLEMENT_RELATIVE_PATH = "ops/capture-enablement.yml"
CAPTURE_ENABLEMENT_RECEIPTS_DIR = "receipts/capture-enablement"
CAPTURE_ENABLEMENT_SCOPE = "objet-capture"
# The gate requires exact equality with this statement; any deviation fails closed.
CAPTURE_ENABLEMENT_STATEMENT = (
    "I am the owner of this archive and I approve objet-capture writing into it outside sandbox mode."
)
OBJET_CAPTURE_REQUIRED_PRIVACY_GUARDS = (
    "no_full_content_capture",
    "no_automatic_minting",
    "no_bulk_import",
    "requires_per_item_approval",
    "staged_folder_cleanup_last",
)
OBJET_CAPTURE_INTERNAL_PREFIXES = ("objects", "receipts", "source-maps", "zettels", "views", "anchors", "db")
OBJET_CAPTURE_RESERVED_DEVICE_NAMES = frozenset(
    {"con", "prn", "aux", "nul"}
    | {f"com{index}" for index in range(1, 10)}
    | {f"lpt{index}" for index in range(1, 10)}
)
OBJET_CAPTURE_LOGICAL_KEY_RE = re.compile(r"^objects/sha256/[0-9a-f]{2}/[0-9a-f]{64}$")
# Fixed map so the recorded mime is reproducible across machines; the OS/registry-backed
# mimetypes module would make identical bytes yield different manifest records.
OBJET_CAPTURE_MIME_BY_EXTENSION = {
    ".csv": "text/csv",
    ".docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    ".gif": "image/gif",
    ".html": "text/html",
    ".jpeg": "image/jpeg",
    ".jpg": "image/jpeg",
    ".json": "application/json",
    ".jsonl": "application/x-ndjson",
    # audio/mp4 is the standard MP4-audio mime; source-intake (mimetypes.guess_type)
    # records the same value only where the platform mimetypes db maps .m4a — the
    # stdlib table has no .m4a entry, which is exactly why this fixed entry is needed.
    # MP4-family magic ("ftyp") sits at byte offset 4, so the startswith-based
    # OBJET_CAPTURE_MAGIC_SIGNATURES map cannot express it; the extension entry is required.
    ".m4a": "audio/mp4",
    ".md": "text/markdown",
    ".mp3": "audio/mpeg",
    ".mp4": "video/mp4",
    ".pdf": "application/pdf",
    ".png": "image/png",
    ".pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    ".txt": "text/plain",
    ".wav": "audio/x-wav",
    ".webp": "image/webp",
    ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    ".yaml": "text/yaml",
    ".yml": "text/yaml",
    ".zip": "application/zip",
}
OBJET_CAPTURE_MAGIC_SIGNATURES = (
    (b"%PDF", "application/pdf"),
    (b"\x89PNG\r\n\x1a\n", "image/png"),
    (b"\xff\xd8\xff", "image/jpeg"),
    (b"GIF8", "image/gif"),
    (b"PK\x03\x04", "application/zip"),
)


def target_looks_external_live_never_touch(target: Path) -> bool:
    # Duplicated from tools/check_artifact_hygiene.py: wom_kit must never import tools/.
    parts = [part.lower() for part in target.resolve().parts]
    if any(part.startswith("zettel-kasten-") for part in parts):
        return True
    if any(part.endswith("-objets") for part in parts):
        return True
    return False


def read_capture_enablement(root: Path) -> dict[str, Any]:
    """Read and classify the owner capture-enablement record for one archive root.

    Single shared implementation for the objet-capture gate, the per-item capture
    call sites, the objet-capture-enable dry-run reporter, and doctor, so those
    surfaces can never drift. Read footprint: when ops/capture-enablement.yml is
    absent this is a single is_file() stat and reads nothing; when present it
    reads at most the two control files (ops/capture-enablement.yml and
    archive.yml). ANY exception while reading or validating fails closed to a
    non-enabling state; this function never raises.
    """
    result: dict[str, Any] = {
        "present": False,
        "valid": False,
        "state": "absent",
        "record": None,
        "reason": None,
    }
    try:
        record_path = root / "ops" / "capture-enablement.yml"
        if not record_path.is_file():
            return result
        result["present"] = True
        result["state"] = "invalid"
        data = load_yaml(record_path.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            result["reason"] = "record is present but not a readable YAML mapping"
            return result
        result["record"] = data
        if data.get("schema") != CAPTURE_ENABLEMENT_SCHEMA:
            result["reason"] = f"schema must be exactly {CAPTURE_ENABLEMENT_SCHEMA}"
            return result
        if data.get("scope") != CAPTURE_ENABLEMENT_SCOPE:
            result["reason"] = f"scope must be exactly {CAPTURE_ENABLEMENT_SCOPE}"
            return result
        if data.get("statement") != CAPTURE_ENABLEMENT_STATEMENT:
            result["reason"] = "statement does not exactly match the required owner consent statement"
            return result
        # read_archive_id raises ArchiveServiceError on missing/broken archive.yml;
        # the enclosing except turns that into a clean invalid state (never a traceback).
        if data.get("archive_id") != read_archive_id(root):
            result["reason"] = "archive_id does not match archive.yml"
            return result
        enabled = data.get("enabled")
        if enabled is not True:
            # Identity check on purpose: YAML 1.1 truthy strings ("yes", "on", "true"
            # quoted) and integers must not enable capture.
            if enabled is False:
                if isinstance(data.get("revoked_by"), str) and data.get("revoked_by"):
                    result["state"] = "revoked"
                    result["reason"] = "enablement was revoked by the owner"
                else:
                    result["state"] = "disabled"
                    result["reason"] = "enabled is false without revocation metadata"
            else:
                result["reason"] = "enabled must be the YAML boolean true"
            return result
        if target_looks_external_live_never_touch(root) and data.get("never_touch_acknowledged") is not True:
            result["reason"] = (
                "this root matches the external live-store protection name pattern; "
                "the record must carry never_touch_acknowledged: true"
            )
            return result
        result["valid"] = True
        result["state"] = "enabled"
        result["reason"] = None
        return result
    except Exception:
        result["present"] = True
        result["valid"] = False
        result["state"] = "invalid"
        result["reason"] = "record or archive.yml is present but not safe/readable"
        return result


def objet_capture_relative_parts_never_touch(parts: tuple[str, ...] | list[str]) -> bool:
    # Same two name rules as target_looks_external_live_never_touch, applied to
    # already-rooted archive-relative components only. Used by the per-item capture
    # call sites when the run's root carries a VALID enablement record: the root's
    # own (owner-enabled) name is excluded, while any matching component BELOW the
    # root still blocks. target_looks_external_live_never_touch itself is not
    # modified and keeps absolute semantics for non-enabled roots.
    lowered = [str(part).lower() for part in parts]
    if any(part.startswith("zettel-kasten-") for part in lowered):
        return True
    return any(part.endswith("-objets") for part in lowered)


def objet_capture_sandbox_marked(root: Path) -> bool:
    if (root / ".wom-sandbox").is_file():
        return True
    archive_yml = root / "archive.yml"
    if archive_yml.is_file():
        try:
            data = load_yaml(archive_yml.read_text(encoding="utf-8"))
        except Exception:
            return False
        return isinstance(data, dict) and data.get("environment") == "sandbox"
    return False


def objet_capture_sandbox_blockers(root: Path, enablement: dict[str, Any] | None = None) -> list[str]:
    # Gate order: a valid owner enablement record allows capture BEFORE the
    # never-touch name check runs, so a real archive root whose name matches the
    # pattern can graduate after explicit acknowledgment. When the record file is
    # absent, read_capture_enablement adds a single stat and reads nothing.
    if enablement is None:
        enablement = read_capture_enablement(root)
    if enablement.get("valid") is True:
        return []
    if target_looks_external_live_never_touch(root):
        return ["external_live_never_touch"]
    if (root / ".wom-sandbox").is_file():
        return []
    archive_yml = root / "archive.yml"
    if archive_yml.is_file():
        # The marker must be the TOP-LEVEL environment value; a raw line scan would also match
        # the phrase nested in another mapping or block scalar and silently mark a live archive
        # capturable. Malformed YAML counts as no-marker (fail closed).
        try:
            data = load_yaml(archive_yml.read_text(encoding="utf-8"))
        except Exception:
            data = None
        if isinstance(data, dict) and data.get("environment") == "sandbox":
            return []
    return ["sandbox_marker_required"]


OBJET_CAPTURE_REFUSAL_HINTS = {
    "sandbox_marker_required": (
        "objet-capture runs on sandbox-marked archives (a .wom-sandbox marker file or top-level "
        "environment: sandbox in archive.yml), or on a real archive with a valid owner "
        "capture-enablement record; the owner can inspect eligibility with "
        "'archive objet-capture-enable <archive-root> --dry-run' (read-only)"
    ),
    "external_live_never_touch": (
        "this path matches the external live-store protection pattern; capture refuses it by design; "
        "if this is your own archive root, the owner can inspect enablement eligibility with "
        "'archive objet-capture-enable <archive-root> --dry-run' (read-only)"
    ),
}


def objet_capture_refusal(blocked_by: str, *, dry_run: bool, enablement_state: str = "absent") -> dict[str, Any]:
    # Blocker-only on refusal: no item provenance, filenames, or receipt paths may be echoed.
    # Static, blocker-keyed hint strings are allowed because they never vary with the selection.
    # enablement_state is a root-level classification (absent|invalid|revoked|disabled) and
    # carries no item provenance either.
    return {
        "ok": False,
        "dry_run": dry_run,
        "lifecycle_action": "objet_capture_plan" if dry_run else "objet_capture",
        "blocked_by": blocked_by,
        "enablement_state": enablement_state,
        "hint": OBJET_CAPTURE_REFUSAL_HINTS.get(blocked_by),
        "items": [],
        "blockers": [blocked_by],
        "warnings": [],
    }


def objet_capture_deterministic_mime(filename: str, head: bytes) -> str:
    mime = OBJET_CAPTURE_MIME_BY_EXTENSION.get(PurePosixPath(filename).suffix.lower())
    if mime:
        return mime
    for signature, signature_mime in OBJET_CAPTURE_MAGIC_SIGNATURES:
        if head.startswith(signature):
            return signature_mime
    return "application/octet-stream"


def objet_capture_path_chain_blockers(root: Path, relative: str) -> list[str]:
    # Reject a symlink/junction/reparse point on ANY component, not just the final one;
    # resolve_archive_relative_path follows links so containment alone cannot catch this.
    current = root
    for part in PurePosixPath(relative).parts:
        current = current / part
        try:
            entry_stat = os.lstat(current)
        except FileNotFoundError:
            return []
        except OSError:
            return ["source_unreadable"]
        if stat.S_ISLNK(entry_stat.st_mode):
            return ["symlink_not_allowed"]
        reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        if reparse_flag and getattr(entry_stat, "st_file_attributes", 0) & reparse_flag:
            return ["symlink_not_allowed"]
    return []


def objet_capture_envelope_blockers(selection: dict[str, Any], archive_id: str) -> list[str]:
    # Structural checks only; filesystem checks stay in per-item processing.
    blockers: list[str] = []
    action = selection.get("action")
    paired = action == OBJET_CAPTURE_SELECTION_ACTION_WITH_DERIVED_TEXT
    if action not in (OBJET_CAPTURE_SELECTION_ACTION, OBJET_CAPTURE_SELECTION_ACTION_WITH_DERIVED_TEXT):
        blockers.append("selection_action_invalid")
    elif selection.get("schema") != (
        # v0.3.159: the schema field is validated for the first time (it was write-only
        # before: generated on every persisted manifest, never read back). Paired
        # manifests require the v0.3 schema; plain manifests keep requiring the v0.2
        # schema every persisted manifest already carries.
        OBJET_CAPTURE_SELECTION_SCHEMA_WITH_DERIVED_TEXT
        if paired
        else OBJET_CAPTURE_SELECTION_SCHEMA
    ):
        blockers.append("selection_schema_invalid")
    items = selection.get("items")
    if not isinstance(items, list) or not items or any(not isinstance(item, dict) for item in items):
        blockers.append("selection_items_invalid")
        items = []
    guards = selection.get("privacy_guards")
    if not isinstance(guards, dict) or any(
        guards.get(key) is not True for key in OBJET_CAPTURE_REQUIRED_PRIVACY_GUARDS
    ):
        blockers.append("privacy_guards_invalid")
    if str(selection.get("archive_id") or "") != archive_id:
        blockers.append("archive_id_mismatch")
    item_ids = [str(item.get("item_id") or "") for item in items]
    if items and (len(item_ids) != len(set(item_ids)) or any(not value for value in item_ids)):
        blockers.append("duplicate_selection_target")
    staged_keys: list[str] = []
    for item in items:
        try:
            staged_keys.append(normalize_archive_relative_path(str(item.get("staged_path") or "")))
        except ArchivePathError:
            continue
    if len(staged_keys) != len(set(staged_keys)):
        blockers.append("duplicate_selection_target")
    # Cross-consistency, fail-closed in BOTH directions: derived_text items under the
    # plain action, and a paired action carrying no derived_text item at all, both
    # refuse with selection_action_invalid.
    derived_items = [item for item in items if "derived_text" in item]
    if paired and items and not derived_items:
        blockers.append("selection_action_invalid")
    if action == OBJET_CAPTURE_SELECTION_ACTION and derived_items:
        blockers.append("selection_action_invalid")
    staged_text_keys: list[str] = []
    for item in derived_items:
        derived = item.get("derived_text")
        if not isinstance(derived, dict):
            blockers.append("selection_items_invalid")
            continue
        try:
            staged_text_keys.append(
                normalize_archive_relative_path(str(derived.get("staged_text_path") or ""))
            )
        except ArchivePathError:
            blockers.append("unsafe_staged_text_path")
        normalize_object_id(str(derived.get("approved_text_sha256") or ""), blockers)
        blockers.extend(
            _derived_text_pair_metadata_blockers(
                derivation_kind=derived.get("derivation_kind"),
                tool_name=derived.get("tool_name"),
                tool_version=derived.get("tool_version"),
                review_status=derived.get("review_status"),
                confidence=derived.get("confidence"),
                language=derived.get("language"),
                model_name=derived.get("model_name"),
                model_version=derived.get("model_version"),
                born_digital=derived.get("born_digital", False),
            )
        )
    # One file must not be both an approved original and a transcript source in one
    # run, and transcript sources must be unique across items.
    if len(staged_text_keys) != len(set(staged_text_keys)) or set(staged_text_keys) & set(staged_keys):
        blockers.append("duplicate_selection_target")
    return unique_preserve_order(blockers)


def objet_capture_intake_evidence_blockers(root: Path, item: dict[str, Any]) -> list[str]:
    # The selection never carries inline evidence; it must point at a PERSISTED
    # source-intake plan JSON under receipts/sources/ (the source-intake --dry-run
    # output saved to disk in a prior, separately-gated phase).
    raw_receipt_path = str(item.get("source_intake_receipt_path") or "")
    raw_plan_sha = str(item.get("source_intake_plan_sha256") or "")
    if not raw_receipt_path or not raw_plan_sha:
        return ["source_intake_evidence_invalid"]
    try:
        normalized = normalize_archive_relative_path(raw_receipt_path)
        receipt_path = resolve_archive_relative_path(root, normalized)
    except ArchivePathError:
        return ["source_intake_evidence_invalid"]
    if not normalized.startswith("receipts/sources/") or not receipt_path.is_file():
        return ["source_intake_evidence_invalid"]
    try:
        plan = json.loads(receipt_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return ["source_intake_evidence_invalid"]
    if not isinstance(plan, dict):
        return ["source_intake_evidence_invalid"]
    gate_blockers: list[str] = []
    prepare_source_intake_plan_for_draft(plan, gate_blockers)
    if gate_blockers:
        return ["source_intake_evidence_invalid"]
    if sha256_json_value(plan) != raw_plan_sha:
        return ["source_intake_plan_sha256_mismatch"]
    return []


def objet_capture_project_intake_context(
    root: Path,
    selection: dict[str, Any],
    explicit_receipt: str | None,
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any]:
    selection_receipt = selection.get("project_intake_receipt_path")
    if selection_receipt is not None and not isinstance(selection_receipt, str):
        blockers.append("project_intake_receipt_invalid")
        selection_receipt = None
    receipt = explicit_receipt or selection_receipt
    if explicit_receipt and selection_receipt and explicit_receipt != selection_receipt:
        blockers.append("project_intake_receipt_mismatch")
    if not receipt:
        return {
            "provided": False,
            "decision_values_included": False,
            "automatic_execution_authorized": False,
        }
    try:
        status = project_intake_status(root, receipt, dry_run=True)
    except (ArchiveServiceError, OSError):
        blockers.append("project_intake_receipt_invalid")
        return {
            "provided": True,
            "ok": False,
            "decision_values_included": False,
            "automatic_execution_authorized": False,
        }
    if not status.get("ok"):
        blockers.append("project_intake_receipt_invalid")
    warnings.extend(str(item) for item in status.get("warnings", []) if isinstance(item, str))
    return {
        "provided": True,
        "ok": bool(status.get("ok")),
        "receipt_path": status.get("receipt_path"),
        "session_id": status.get("session_id"),
        "reviewed_by": status.get("reviewed_by"),
        "reviewed_at": status.get("reviewed_at"),
        "decision_sha256": status.get("decision_sha256"),
        "checklist_coverage": status.get("checklist_coverage"),
        "readiness": status.get("readiness"),
        "decision_values_included": False,
        "automatic_execution_authorized": False,
    }


def objet_capture_canonical_record_ids(records: list[dict[str, Any]]) -> set[str]:
    # A record counts as canonical only when its logical_key IS the content-addressed
    # path for its own object_id; legacy objects/sample/ records must not satisfy
    # "canonical record present" or the classifier would skip the canonical append.
    canonical: set[str] = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        object_id = str(record.get("object_id") or "").lower()
        if not object_id.startswith("sha256:"):
            continue
        digest = object_id.split(":", 1)[1]
        if str(record.get("logical_key") or "") == f"objects/sha256/{digest[:2]}/{digest}":
            canonical.add(object_id)
    return canonical


def _objet_capture_fsync_dir(path: Path) -> None:
    if os.name == "nt":
        # Windows cannot fsync a directory handle via os.open/os.fsync; directory-entry
        # durability after os.replace is a documented residual risk on this platform
        # (same class as the documented O_NOFOLLOW residual).
        return
    try:
        dir_fd = os.open(str(path), os.O_RDONLY)
    except OSError:
        return
    try:
        os.fsync(dir_fd)
    finally:
        os.close(dir_fd)


def _objet_capture_sha256_and_head_fd(fd: int) -> tuple[str, bytes]:
    os.lseek(fd, 0, os.SEEK_SET)
    digest = hashlib.sha256()
    head = b""
    while True:
        chunk = os.read(fd, 1024 * 1024)
        if not chunk:
            break
        if not head:
            head = chunk[:16]
        digest.update(chunk)
    return digest.hexdigest(), head


class _ObjetCaptureManifestLock:
    def __init__(self, root: Path) -> None:
        resolved_root = Path(root).resolve()
        if os.name == "nt":
            # Keep child lookup lexical until the resolved root is retained by
            # _PrivateMetadataMutationGuard.  Resolving this path here would
            # follow an attacker-controlled reparse point before the guard can
            # inspect and reject it.
            manifests_dir = resolved_root / "objects" / "manifests"
        else:
            manifests_dir = archive_internal_path(
                resolved_root,
                "objects/manifests",
            )
            manifests_dir.mkdir(parents=True, exist_ok=True)
        # Derive the guard root and lexical child paths from the same resolved
        # spelling. On Windows, tempfile may expose an 8.3 short root while
        # Path.resolve() expands it to the long form; mixing those spellings
        # makes a contained directory look like an escape.
        self._root = resolved_root
        self._manifests_dir = manifests_dir
        self._path = manifests_dir / ".files.jsonl.lock"
        self._handle: Any = None
        self._guard: Any = None
        self._win32_lock: Any = None

    def __enter__(self) -> "_ObjetCaptureManifestLock":
        if os.name == "nt":
            from . import private_metadata_win32 as win32

            self._guard = win32._PrivateMetadataMutationGuard(self._root)
            try:
                win32._bootstrap_object_manifest_lock_directories(self._guard)
                self._win32_lock = win32._PersistentCoordinationLock(
                    self._guard,
                    win32.CoordinationLockKind.OBJECT_MANIFEST,
                )
                self._win32_lock.acquire()
            except BaseException:
                try:
                    if self._win32_lock is not None:
                        self._win32_lock.release()
                finally:
                    self._guard.close()
                self._guard = None
                self._win32_lock = None
                raise
        else:
            import fcntl

            self._handle = open(self._path, "a+b")
            fcntl.flock(self._handle.fileno(), fcntl.LOCK_EX)
        return self

    def __exit__(self, *exc_info: Any) -> bool:
        if os.name == "nt":
            try:
                if self._win32_lock is not None:
                    self._win32_lock.release()
            finally:
                if self._guard is not None:
                    self._guard.close()
                self._win32_lock = None
                self._guard = None
        else:
            try:
                import fcntl

                fcntl.flock(self._handle.fileno(), fcntl.LOCK_UN)
            finally:
                self._handle.close()
        return False


def _objet_capture_manifest_needs_leading_newline(manifest_path: Path) -> bool:
    if not manifest_path.is_file() or manifest_path.stat().st_size == 0:
        return False
    with manifest_path.open("rb") as handle:
        handle.seek(-1, os.SEEK_END)
        return handle.read(1) != b"\n"


def objet_capture_selection_manifest(
    archive_root: Path | str,
    *,
    staged_path: str,
    source_intake_receipt: str,
    item_id: str = "item",
    manifest_id: str | None = None,
    project_intake_receipt: str | None = None,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    derived_text_staged_path: str | None = None,
    derivation_kind: str | None = None,
    tool_name: str | None = None,
    tool_version: str | None = None,
    review_status: str | None = None,
    model_name: str | None = None,
    model_version: str | None = None,
    confidence: float | int | None = None,
    language: str | None = None,
    born_digital: bool = False,
) -> dict[str, Any]:
    if type(dry_run) is not bool or type(approve) is not bool or approve:
        return _compound_exact_human_approval_blocked(
            lifecycle_action="objet_capture_selection_record",
        )
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    capture_enabled = read_capture_enablement(root).get("valid") is True
    blockers: list[str] = []
    warnings: list[str] = []
    paired = derived_text_staged_path is not None
    if not paired and any(
        value is not None
        for value in [
            derivation_kind,
            tool_name,
            tool_version,
            review_status,
            model_name,
            model_version,
            confidence,
            language,
            True if born_digital else None,
        ]
    ):
        blockers.append("Derived-text pairing flags require --derived-text-staged-path.")
    if dry_run is approve:
        blockers.append("Choose exactly one mode: --dry-run or --approve.")
    reviewer = safe_project_intake_actor_id(reviewed_by)
    if approve and reviewer is None:
        blockers.append("Objet capture selection approval requires --reviewed-by with a safe actor id.")
    if reviewed_by and reviewer is None:
        blockers.append("reviewed_by must be a safe non-secret actor id.")

    normalized_item_id = str(item_id or "").strip()
    if not safe_source_intake_ref(normalized_item_id):
        blockers.append("item_id must be a safe label/ref, not a URL, path, token, or secret.")
        normalized_item_id = "item"
    normalized_manifest_id = str(manifest_id or "").strip()
    if normalized_manifest_id and not safe_source_intake_ref(normalized_manifest_id):
        blockers.append("manifest_id must be a safe label/ref, not a URL, path, token, or secret.")
        normalized_manifest_id = ""

    normalized_staged = ""
    src: Path | None = None
    try:
        normalized_staged = normalize_archive_relative_path(staged_path)
        src = resolve_archive_relative_path(root, normalized_staged)
    except ArchivePathError:
        blockers.append("unsafe_staged_path")
    if normalized_staged:
        first_segment = normalized_staged.split("/", 1)[0].lower()
        if first_segment in OBJET_CAPTURE_INTERNAL_PREFIXES:
            blockers.append("unsafe_staged_path")
        for part in PurePosixPath(normalized_staged).parts:
            if part.split(".", 1)[0].lower() in OBJET_CAPTURE_RESERVED_DEVICE_NAMES:
                blockers.append("reserved_device_name")
        chain_blockers = objet_capture_path_chain_blockers(root, normalized_staged)
        blockers.extend(chain_blockers)
    if src is not None:
        if not is_path_within_root(src, root):
            blockers.append("unsafe_staged_path")
        if capture_enabled:
            # Enabled roots: evaluate the never-touch name pattern on the
            # archive-relative components only, mirroring _objet_capture_process_item.
            if objet_capture_relative_parts_never_touch(PurePosixPath(normalized_staged).parts):
                blockers.append("resolved_path_never_touch")
        elif target_looks_external_live_never_touch(src):
            blockers.append("resolved_path_never_touch")

    normalized_receipt = ""
    try:
        normalized_receipt = normalize_archive_relative_path(source_intake_receipt)
    except ArchivePathError:
        blockers.append("source_intake_evidence_invalid")
    if normalized_receipt and not normalized_receipt.startswith("receipts/sources/"):
        blockers.append("source_intake_evidence_invalid")

    project_intake_context = objet_capture_project_intake_context(
        root,
        {"project_intake_receipt_path": project_intake_receipt} if project_intake_receipt else {},
        project_intake_receipt,
        blockers,
        warnings,
    )

    digest: str | None = None
    head = b""
    size_bytes: int | None = None
    mime: str | None = None
    if src is not None and not blockers:
        unresolved = root.joinpath(*PurePosixPath(normalized_staged).parts)
        try:
            entry_stat = os.lstat(unresolved)
        except FileNotFoundError:
            blockers.append("source_missing")
        except OSError:
            blockers.append("source_unreadable")
        else:
            if stat.S_ISDIR(entry_stat.st_mode):
                blockers.append("staged_path_is_directory")
            elif not stat.S_ISREG(entry_stat.st_mode):
                blockers.append("special_file_not_allowed")
        if not blockers:
            open_flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
            try:
                fd = os.open(str(unresolved), open_flags)
            except OSError:
                blockers.append("source_unreadable")
            else:
                try:
                    fd_stat = os.fstat(fd)
                    if not stat.S_ISREG(fd_stat.st_mode):
                        blockers.append("special_file_not_allowed")
                    else:
                        size_bytes = fd_stat.st_size
                        digest, head = _objet_capture_sha256_and_head_fd(fd)
                        mime = objet_capture_deterministic_mime(unresolved.name, head)
                        if size_bytes == 0:
                            warnings.append("zero_byte_file")
                except OSError:
                    blockers.append("source_unreadable")
                finally:
                    os.close(fd)

    plan_sha256 = ""
    if normalized_receipt and not blockers:
        try:
            receipt_path = resolve_archive_relative_path(root, normalized_receipt)
            plan = json.loads(receipt_path.read_text(encoding="utf-8"))
        except (ArchivePathError, OSError, json.JSONDecodeError):
            blockers.append("source_intake_evidence_invalid")
            plan = None
        if isinstance(plan, dict):
            gate_blockers: list[str] = []
            prepare_source_intake_plan_for_draft(plan, gate_blockers)
            if gate_blockers:
                blockers.append("source_intake_evidence_invalid")
            else:
                plan_sha256 = sha256_json_value(plan)
        elif plan is not None:
            blockers.append("source_intake_evidence_invalid")

    normalized_text_path = ""
    text_digest: str | None = None
    derived_text_item: dict[str, Any] | None = None
    if paired:
        # A bad pair must block HERE, before a human ever approves it: the full
        # staged_path-parity confinement chain, the raw-byte commitment hash, and the
        # same metadata validation the capture path enforces (minus source_object_id,
        # which is only minted at capture time).
        required_pair_flags = {
            "--derivation-kind": derivation_kind,
            "--tool-name": tool_name,
            "--tool-version": tool_version,
            "--review-status": review_status,
        }
        missing_flags = [flag for flag, value in required_pair_flags.items() if value is None]
        if missing_flags:
            blockers.append(
                "Paired derived text requires " + ", ".join(sorted(missing_flags)) + "."
            )
        else:
            blockers.extend(
                _derived_text_pair_metadata_blockers(
                    derivation_kind=derivation_kind,
                    tool_name=tool_name,
                    tool_version=tool_version,
                    review_status=review_status,
                    confidence=confidence,
                    language=language,
                    model_name=model_name,
                    model_version=model_version,
                    born_digital=born_digital,
                )
            )
        normalized_text_path, text_path_blockers = _objet_capture_staged_text_path_blockers(
            root, derived_text_staged_path, capture_enabled=capture_enabled
        )
        blockers.extend(text_path_blockers)
        if normalized_text_path and normalized_staged and normalized_text_path == normalized_staged:
            # One file must not be both the approved original and its transcript source.
            blockers.append("duplicate_selection_target")
        if normalized_text_path and not blockers:
            raw_text_bytes, text_read_blockers = _objet_capture_read_staged_text_bytes(
                root, normalized_text_path
            )
            blockers.extend(text_read_blockers)
            if raw_text_bytes is not None:
                # approved_text_sha256 commits the RAW file bytes (D2/D12): the stored
                # derived text is transcoded UTF-8, but the approval binds the input.
                text_digest = hashlib.sha256(raw_text_bytes).hexdigest()
                if len(raw_text_bytes) == 0:
                    warnings.append("zero_byte_text")
        derived_text_item = drop_none_values(
            {
                "staged_text_path": normalized_text_path,
                "approved_text_sha256": f"sha256:{text_digest}" if text_digest else "",
                "derivation_kind": derivation_kind,
                "tool_name": tool_name.strip() if isinstance(tool_name, str) else tool_name,
                "tool_version": tool_version.strip() if isinstance(tool_version, str) else tool_version,
                "review_status": review_status,
                "model_name": model_name.strip() if isinstance(model_name, str) and model_name.strip() else None,
                "model_version": model_version.strip()
                if isinstance(model_version, str) and model_version.strip()
                else None,
                "confidence": confidence,
                "language": language.strip() if isinstance(language, str) and language.strip() else None,
                "born_digital": born_digital,
            }
        )

    if digest and not normalized_manifest_id:
        normalized_manifest_id = f"selection:{digest[:16]}"
    captured_at = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    item = {
        "item_id": normalized_item_id,
        "approved": True,
        "input_kind": "local_path",
        "staged_path": normalized_staged,
        "approved_object_id": f"sha256:{digest}" if digest else "",
        "expected_size_bytes": size_bytes,
        "expected_mime": mime,
        "source_intake_receipt_path": normalized_receipt,
        "source_intake_plan_sha256": plan_sha256,
    }
    if derived_text_item is not None:
        item["derived_text"] = derived_text_item
    selection = {
        "manifest_id": normalized_manifest_id or "selection:pending",
        "schema": OBJET_CAPTURE_SELECTION_SCHEMA_WITH_DERIVED_TEXT
        if paired
        else OBJET_CAPTURE_SELECTION_SCHEMA,
        "action": OBJET_CAPTURE_SELECTION_ACTION_WITH_DERIVED_TEXT
        if paired
        else OBJET_CAPTURE_SELECTION_ACTION,
        "archive_id": archive_id,
        "created_at": captured_at,
        "created_by": reviewer,
        "project_intake_receipt_path": project_intake_receipt,
        "items": [item],
        "privacy_guards": {key: True for key in OBJET_CAPTURE_REQUIRED_PRIVACY_GUARDS},
    }
    envelope_blockers = objet_capture_envelope_blockers(selection, archive_id)
    if digest and plan_sha256 and normalized_receipt:
        evidence_blockers = objet_capture_intake_evidence_blockers(root, item)
        blockers.extend(evidence_blockers)
    blockers.extend(envelope_blockers)

    selection_sha256 = sha256_json_value(selection)
    receipt_digest = selection_sha256.removeprefix("sha256:")
    selection_relative = f"{OBJET_CAPTURE_SELECTION_MANIFESTS_DIR}/{receipt_digest[:16]}.selection.json"
    selection_path = archive_internal_path(root, selection_relative)
    if approve and selection_path.exists():
        blockers.append("objet capture selection manifest already exists for this selection hash.")

    result: dict[str, Any] = {
        "ok": not blockers,
        "dry_run": dry_run,
        "lifecycle_action": "objet_capture_selection_plan" if dry_run else "objet_capture_selection_record",
        "archive_id": archive_id,
        "selection_manifest_id": selection["manifest_id"],
        "selection_manifest_sha256": selection_sha256,
        "project_intake_context": project_intake_context,
        "proposed_selection_path": selection_relative,
        "selection_path": None,
        "item": {
            "item_id": normalized_item_id,
            "staged_path": normalized_staged or None,
            "approved_object_id": item["approved_object_id"] or None,
            "expected_size_bytes": size_bytes,
            "expected_mime": mime,
            "source_intake_receipt_path": normalized_receipt or None,
            "source_intake_plan_sha256": plan_sha256 or None,
            **(
                {
                    "derived_text": {
                        # Archive-relative path only: absolute_local_paths_echoed stays false.
                        "staged_text_path": normalized_text_path or None,
                        "approved_text_sha256": f"sha256:{text_digest}" if text_digest else None,
                        "derivation_kind": derivation_kind,
                        "review_status": review_status,
                    }
                }
                if paired
                else {}
            ),
        },
        "selection_manifest": selection if not blockers else None,
        "privacy_guards": {
            "absolute_local_paths_echoed": False,
            "source_intake_receipt_read": bool(normalized_receipt),
            "file_body_hashed": digest is not None,
            "file_body_copied": False,
            "objet_capture_run": False,
            "object_manifest_appended": False,
            "object_bytes_written": False,
            "provider_calls": False,
            "writes": approve and not blockers,
        },
        "next_safe_actions": [
            "Review the selection manifest before running objet-capture.",
            "Run objet-capture --selection <selection-path> --dry-run before any approved capture.",
            "Keep cleanup manual and last; this command never deletes staged files.",
        ],
        "would_change": [selection_relative] if dry_run and not blockers else [],
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
    }
    if blockers or dry_run:
        return result

    created_dirs = missing_parent_dirs_before_write(root, [selection_path])
    created_paths: list[Path] = []
    try:
        selection_path.parent.mkdir(parents=True, exist_ok=True)
        write_json_new_file(selection_path, selection)
        created_paths.append(selection_path)
    except Exception:
        for path in created_paths:
            try:
                path.unlink()
            except OSError:
                pass
        cleanup_created_empty_dirs(root, created_dirs)
        raise

    result.update(
        {
            "ok": True,
            "dry_run": False,
            "selection_path": selection_relative,
            "files_written": [selection_relative],
            "would_change": [],
            "privacy_guards": {**result["privacy_guards"], "writes": True},
        }
    )
    return result


def _objet_capture_staged_text_path_blockers(
    root: Path,
    raw_staged_text: Any,
    *,
    capture_enabled: bool,
) -> tuple[str, list[str]]:
    """Full confinement parity with staged_path for a manifest-carried transcript path.

    Mirrors _objet_capture_process_item's chain exactly: normalize + resolve +
    containment, internal-prefix block (this is what stops a transcript "source"
    pointing INTO receipts/ or objects/ — including objects/derived-text/sha256 itself,
    i.e. laundering archive-internal content in as new derived text), reserved device
    names, enablement-aware never-touch, and the per-component symlink/junction chain.
    """
    try:
        normalized = normalize_archive_relative_path(str(raw_staged_text or ""))
        src = resolve_archive_relative_path(root, normalized)
    except ArchivePathError:
        return "", ["unsafe_staged_text_path"]
    first_segment = normalized.split("/", 1)[0].lower()
    if first_segment in OBJET_CAPTURE_INTERNAL_PREFIXES:
        return normalized, ["unsafe_staged_text_path"]
    for part in PurePosixPath(normalized).parts:
        if part.split(".", 1)[0].lower() in OBJET_CAPTURE_RESERVED_DEVICE_NAMES:
            return normalized, ["reserved_device_name"]
    if not is_path_within_root(src, root):
        return normalized, ["unsafe_staged_text_path"]
    if capture_enabled:
        # Enabled roots: never-touch applies to the archive-relative components only,
        # mirroring the staged_path call site. The derived store key
        # objects/derived-text/sha256/<aa>/<hash>.txt has constant parts that can never
        # match the never-touch patterns, so only the source path needs this check.
        if objet_capture_relative_parts_never_touch(PurePosixPath(normalized).parts):
            return normalized, ["resolved_path_never_touch"]
    elif target_looks_external_live_never_touch(src):
        return normalized, ["resolved_path_never_touch"]
    chain_blockers = objet_capture_path_chain_blockers(root, normalized)
    if chain_blockers:
        return normalized, [chain_blockers[0]]
    return normalized, []


def _objet_capture_read_staged_text_bytes(root: Path, normalized: str) -> tuple[bytes | None, list[str]]:
    unresolved = root.joinpath(*PurePosixPath(normalized).parts)
    raw_bytes, reason = _bounded_stable_regular_file_read(
        unresolved,
        max_bytes=DERIVED_TEXT_MAX_SOURCE_BYTES,
    )
    blockers = {
        "missing": "source_missing",
        "unreadable": "source_unreadable",
        "symlink": "special_file_not_allowed",
        "reparse": "special_file_not_allowed",
        "directory": "staged_path_is_directory",
        "special": "special_file_not_allowed",
        "too_large": "text_file_too_large",
        "changed": "text_file_changed_during_read",
    }
    return raw_bytes, ([blockers[reason]] if reason is not None else [])


def _objet_capture_process_item(
    root: Path,
    item: dict[str, Any],
    *,
    approve: bool,
    canonical_ids: set[str],
    appended_this_run: set[str],
    captured_at: str,
    reviewed_by: str | None,
    selection: dict[str, Any],
    selection_sha256: str,
    manifest_appender: Any,
    capture_enabled: bool = False,
) -> dict[str, Any]:
    result: dict[str, Any] = {
        "item_id": str(item.get("item_id") or ""),
        "object_id": None,
        "logical_key": None,
        "planned_action": None,
        "action": None,
        "size_bytes": None,
        "mime": None,
        "source_staged_path": None,
        "original_filename": None,
        "approved_object_id": str(item.get("approved_object_id") or ""),
        "source_intake_plan_sha256": str(item.get("source_intake_plan_sha256") or ""),
        "stored_sha256_verified": False,
        "manifest_record_appended": False,
        "blockers": [],
        "warnings": [],
    }

    def block(code: str) -> dict[str, Any]:
        result["blockers"].append(code)
        result["planned_action"] = "blocked"
        result["action"] = "blocked"
        return result

    if item.get("approved") is not True:
        return block("item_not_approved")
    if item.get("input_kind") != "local_path":
        return block("unsupported_input_kind")

    raw_staged = str(item.get("staged_path") or "")
    try:
        normalized = normalize_archive_relative_path(raw_staged)
        src = resolve_archive_relative_path(root, normalized)
    except ArchivePathError:
        return block("unsafe_staged_path")
    result["source_staged_path"] = normalized
    result["original_filename"] = PurePosixPath(normalized).name

    first_segment = normalized.split("/", 1)[0].lower()
    if first_segment in OBJET_CAPTURE_INTERNAL_PREFIXES:
        return block("unsafe_staged_path")
    for part in PurePosixPath(normalized).parts:
        if part.split(".", 1)[0].lower() in OBJET_CAPTURE_RESERVED_DEVICE_NAMES:
            return block("reserved_device_name")
    if not is_path_within_root(src, root):
        return block("unsafe_staged_path")
    if capture_enabled:
        # For a validly-enabled root the never-touch name pattern applies to the
        # archive-relative components only (safe: is_path_within_root is enforced
        # immediately above); the root's own owner-enabled name no longer re-blocks
        # every item, while a matching component BELOW the root still blocks.
        if objet_capture_relative_parts_never_touch(PurePosixPath(normalized).parts):
            return block("resolved_path_never_touch")
    elif target_looks_external_live_never_touch(src):
        return block("resolved_path_never_touch")
    chain_blockers = objet_capture_path_chain_blockers(root, normalized)
    if chain_blockers:
        return block(chain_blockers[0])

    unresolved = root.joinpath(*PurePosixPath(normalized).parts)
    try:
        entry_stat = os.lstat(unresolved)
    except FileNotFoundError:
        return block("source_missing")
    except OSError:
        return block("source_unreadable")
    if stat.S_ISDIR(entry_stat.st_mode):
        return block("staged_path_is_directory")
    if not stat.S_ISREG(entry_stat.st_mode):
        return block("special_file_not_allowed")

    open_flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        fd = os.open(str(unresolved), open_flags)
    except OSError:
        return block("source_unreadable")
    try:
        fd_stat = os.fstat(fd)
        if not stat.S_ISREG(fd_stat.st_mode):
            return block("special_file_not_allowed")
        size_bytes = fd_stat.st_size
        try:
            digest, head = _objet_capture_sha256_and_head_fd(fd)
        except OSError:
            return block("source_unreadable")
        object_id = f"sha256:{digest}"
        mime = objet_capture_deterministic_mime(unresolved.name, head)
        result["object_id"] = object_id
        result["size_bytes"] = size_bytes
        result["mime"] = mime
        if size_bytes == 0:
            result["warnings"].append("zero_byte_file")

        commitment_blockers: list[str] = []
        approved_object_id = normalize_object_id(str(item.get("approved_object_id") or ""), commitment_blockers)
        if commitment_blockers or approved_object_id != object_id:
            return block("approved_content_mismatch")

        evidence_blockers = objet_capture_intake_evidence_blockers(root, item)
        if evidence_blockers:
            return block(evidence_blockers[0])

        expected_size = item.get("expected_size_bytes")
        if expected_size is not None:
            if isinstance(expected_size, bool) or not isinstance(expected_size, int):
                return block("expected_size_invalid")
            if expected_size != size_bytes:
                if approve:
                    return block("expected_size_mismatch")
                result["warnings"].append("expected_size_mismatch")
        expected_mime = item.get("expected_mime")
        if expected_mime is not None:
            if not isinstance(expected_mime, str):
                return block("expected_mime_invalid")
            if expected_mime != mime:
                if approve:
                    return block("expected_mime_mismatch")
                result["warnings"].append("expected_mime_mismatch")

        logical_key = f"objects/sha256/{digest[:2]}/{digest}"
        if not OBJET_CAPTURE_LOGICAL_KEY_RE.match(logical_key):
            return block("dest_equals_source")
        dest = archive_internal_path(root, logical_key)
        result["logical_key"] = logical_key
        if capture_enabled:
            # Enabled roots: never-touch applies to the logical_key parts only
            # (the dest components below the root), mirroring the src call site.
            if objet_capture_relative_parts_never_touch(PurePosixPath(logical_key).parts):
                return block("resolved_path_never_touch")
        elif target_looks_external_live_never_touch(dest):
            return block("resolved_path_never_touch")
        dest_chain_blockers = objet_capture_path_chain_blockers(root, logical_key)
        if dest_chain_blockers:
            return block(dest_chain_blockers[0])
        if dest.resolve() == src.resolve():
            return block("dest_equals_source")

        canonical_present = object_id in canonical_ids
        if object_id in appended_this_run:
            # An earlier item this run already planned/published this object: dry-run must
            # predict the same intra-run collapse apply performs, so both modes short-circuit.
            planned = "skip_already_present"
        elif dest.is_file():
            if sha256_path(dest) != digest:
                result["planned_action"] = "dest_collision"
                result["action"] = "dest_collision"
                result["blockers"].append("dest_collision")
                return result
            planned = "skip_already_present" if canonical_present else "repair_append"
        else:
            planned = "re_materialize" if canonical_present else "capture"
        result["planned_action"] = planned
        if planned in ("capture", "repair_append", "re_materialize"):
            appended_this_run.add(object_id)
        if not approve:
            return result

        if planned in ("capture", "re_materialize"):
            dest.parent.mkdir(parents=True, exist_ok=True)
            tmp = dest.parent / (dest.name + ".part-" + secrets.token_hex(8))
            try:
                os.lseek(fd, 0, os.SEEK_SET)
                with tmp.open("wb") as out_handle:
                    while True:
                        chunk = os.read(fd, 1024 * 1024)
                        if not chunk:
                            break
                        out_handle.write(chunk)
                    out_handle.flush()
                    os.fsync(out_handle.fileno())
                if sha256_path(tmp) != digest:
                    tmp.unlink(missing_ok=True)
                    return block("lossless_verification_failed")
                _objet_capture_fsync_dir(dest.parent)
                os.replace(tmp, dest)
                _objet_capture_fsync_dir(dest.parent)
                if sha256_path(dest) != digest:
                    dest.unlink(missing_ok=True)
                    return block("lossless_verification_failed")
                result["stored_sha256_verified"] = True
            except Exception:
                try:
                    tmp.unlink(missing_ok=True)
                except OSError:
                    pass
                observed = _stable_exact_file_observation(
                    dest,
                    expected_size=int(size_bytes),
                    expected_sha256=digest,
                )
                if observed == "verified_exact":
                    result["stored_sha256_verified"] = True
                elif observed == "not_written":
                    return block("source_unreadable")
                else:
                    raise PublicationOutcomeUnverified(
                        "original_object_publish_outcome_unverified"
                    )

        if planned in ("capture", "repair_append"):
            record = {
                "object_id": object_id,
                "sha256": digest,
                "logical_key": logical_key,
                "mime": mime,
                "size_bytes": size_bytes,
                "locations": [{"provider": "local", "path": logical_key, "availability": "available"}],
                "provenance": {
                    "created_in": f"archive:{selection.get('archive_id')}",
                    "source": "b4_local_objet_capture",
                    "captured_at": captured_at,
                    "captured_by": reviewed_by,
                    "original_filename": result["original_filename"],
                    "source_staged_path": normalized,
                    "approved_object_id": object_id,
                    "source_intake_receipt_path": str(item.get("source_intake_receipt_path") or ""),
                    "source_intake_plan_sha256": str(item.get("source_intake_plan_sha256") or ""),
                    "selection_manifest_id": str(selection.get("manifest_id") or ""),
                    "selection_manifest_sha256": selection_sha256,
                },
            }
            try:
                manifest_appender(record)
            except OSError:
                # Bytes may already be durable; surface a clean per-item blocker so the
                # always-written receipt records the unreferenced publish (a re-run repairs it).
                return block("manifest_append_failed")
            result["manifest_record_appended"] = True

        result["action"] = {
            "capture": "captured",
            "repair_append": "repair_appended",
            "re_materialize": "re_materialized",
            "skip_already_present": "skip_already_present",
        }[planned]
        return result
    finally:
        os.close(fd)


OBJET_CAPTURE_ORIGINAL_OK_ACTIONS = frozenset(
    {"captured", "repair_appended", "re_materialized", "skip_already_present"}
)
OBJET_CAPTURE_ORIGINAL_OK_PLANNED_ACTIONS = frozenset(
    {"capture", "repair_append", "re_materialize", "skip_already_present"}
)


def _objet_capture_derived_text_initial_subresult() -> dict[str, Any]:
    # The initialized not-attempted state: visible on the receipt only when phase 2 was
    # never reached (a phase-1 abort); `aborted` then reflects reality at run level.
    return {
        "derived_text_id": None,
        "staged_text_path": None,
        "planned_action": None,
        "action": None,
        "item_status": "not_attempted",
        "source_text_encoding": None,
        "source_text_sha256": None,
        "text_sha256": None,
        "text_logical_key": None,
        "manifest_record_appended": False,
        "stored_sha256_verified": False,
        "blockers": [],
        "warnings": [],
    }


def _objet_capture_paired_derived_text(
    root: Path,
    archive_id: str,
    item: dict[str, Any],
    original_result: dict[str, Any],
    *,
    approve: bool,
    reviewed_by: str | None,
    captured_at: str,
    capture_enabled: bool,
    selection: dict[str, Any],
    selection_sha256: str,
    planned_derived_ids: set[str] | None = None,
    planned_text_keys: set[str] | None = None,
) -> dict[str, Any]:
    """Process the derived-text half of one paired item (phase 2 of _objet_capture_run).

    Returns the item-level derived_text sub-result. Never raises for per-item input
    problems; the caller wraps unexpected exceptions into derived_text_registration_failed.
    """
    derived = item.get("derived_text")
    sub = _objet_capture_derived_text_initial_subresult()
    original_state = original_result.get("action") if approve else original_result.get("planned_action")
    original_ok = original_state in (
        OBJET_CAPTURE_ORIGINAL_OK_ACTIONS if approve else OBJET_CAPTURE_ORIGINAL_OK_PLANNED_ACTIONS
    )
    if not isinstance(derived, dict):
        sub["item_status"] = "blocked"
        sub["blockers"].append("selection_items_invalid")
        return sub
    if not original_ok:
        # Never register (or even hash) text against an uncommitted object (D17);
        # the text file is not read in this case.
        sub["item_status"] = "blocked"
        sub["blockers"].append("blocked_by_original")
        return sub
    normalized_text, path_blockers = _objet_capture_staged_text_path_blockers(
        root, derived.get("staged_text_path"), capture_enabled=capture_enabled
    )
    sub["staged_text_path"] = normalized_text or None
    if path_blockers:
        sub["item_status"] = "blocked"
        sub["blockers"].extend(path_blockers)
        return sub
    raw_bytes, read_blockers = _objet_capture_read_staged_text_bytes(root, normalized_text)
    if read_blockers or raw_bytes is None:
        sub["item_status"] = "blocked"
        sub["blockers"].extend(read_blockers or ["source_unreadable"])
        # Hint parity with the standalone reader: static blocker-keyed hints only
        # (e.g. text_file_too_large), never input-derived content.
        read_hints = {
            code: DERIVED_TEXT_ENCODING_BLOCKER_HINTS[code]
            for code in sub["blockers"]
            if code in DERIVED_TEXT_ENCODING_BLOCKER_HINTS
        }
        if read_hints:
            sub["blocker_hints"] = read_hints
        return sub
    # Approval commitment on RAW bytes, immediately before registration (and in dry-run
    # planning): the mirror of the approved_object_id check on the original half.
    commitment_blockers: list[str] = []
    approved_text = normalize_object_id(str(derived.get("approved_text_sha256") or ""), commitment_blockers)
    raw_digest = hashlib.sha256(raw_bytes).hexdigest()
    if commitment_blockers or approved_text != f"sha256:{raw_digest}":
        sub["item_status"] = "blocked"
        sub["blockers"].append("approved_text_content_mismatch")
        return sub
    core = _derived_text_capture_core(
        root,
        archive_id,
        raw_bytes=raw_bytes,
        file_blockers=[],
        text_filename=PurePosixPath(normalized_text).name,
        source_object_id=str(original_result.get("object_id") or ""),
        derivation_kind=str(derived.get("derivation_kind") or ""),
        tool_name=str(derived.get("tool_name") or ""),
        tool_version=str(derived.get("tool_version") or ""),
        review_status=str(derived.get("review_status") or ""),
        approve=approve,
        reviewed_by=reviewed_by,
        captured_at=captured_at,
        model_name=derived.get("model_name"),
        model_version=derived.get("model_version"),
        confidence=derived.get("confidence"),
        language=derived.get("language"),
        born_digital=bool(derived.get("born_digital", False)),
        source_presence="paired_same_run",
        paired_with={
            "selection_manifest_id": str(selection.get("manifest_id") or ""),
            "selection_manifest_sha256": selection_sha256,
            "item_id": str(item.get("item_id") or ""),
        },
    )
    sub.update(
        {
            "derived_text_id": core.get("derived_text_id"),
            "planned_action": core.get("planned_action"),
            "action": core.get("action") if approve else None,
            "item_status": core.get("item_status"),
            "source_text_encoding": core.get("source_text_encoding"),
            "source_text_sha256": core.get("source_text_sha256"),
            "text_sha256": core.get("text_sha256"),
            "text_logical_key": core.get("text_logical_key"),
            "manifest_record_appended": bool(core.get("manifest_record_appended", False)),
            "stored_sha256_verified": bool(core.get("stored_sha256_verified", False)),
            "blockers": list(core.get("blockers", [])),
            "warnings": list(core.get("warnings", [])),
        }
    )
    if core.get("detected_bom") is not None:
        sub["detected_bom"] = core["detected_bom"]
    if core.get("blocker_hints"):
        sub["blocker_hints"] = core["blocker_hints"]
    if approve:
        sub["receipt_path"] = core.get("receipt_path")
        return sub
    sub["planned_writes"] = list(core.get("planned_writes", []))
    derived_text_id = str(core.get("derived_text_id") or "")
    text_logical_key = str(core.get("text_logical_key") or "")
    if (
        planned_derived_ids is not None
        and planned_text_keys is not None
        and core.get("ok")
        and derived_text_id
        and text_logical_key
    ):
        # Dry-run must predict the same intra-run collapse apply performs when two
        # paired items carry byte-identical transcripts (same simulation as the
        # derive-text batch dry-run).
        if derived_text_id in planned_derived_ids:
            sub["planned_action"] = "skip_already_present"
            sub["item_status"] = "skipped"
            sub["planned_writes"] = []
        elif text_logical_key in planned_text_keys and sub.get("planned_action") == "capture":
            sub["planned_action"] = "repair_append"
            sub["item_status"] = "ready"
            sub["planned_writes"] = [f"{DERIVED_TEXT_MANIFEST_RELATIVE_PATH} (+1 line)"]
        if sub.get("planned_action") in ("capture", "repair_append", "re_materialize"):
            planned_derived_ids.add(derived_text_id)
            planned_text_keys.add(text_logical_key)
    return sub


def _objet_capture_write_receipt(root: Path, receipt: dict[str, Any], captured_at: str) -> str:
    receipts_dir = archive_internal_path(root, OBJET_CAPTURE_RECEIPTS_DIR)
    receipts_dir.mkdir(parents=True, exist_ok=True)
    timestamp_compact = re.sub(r"[^0-9TZ]", "", captured_at)
    while True:
        capture_id = f"{timestamp_compact}-{secrets.token_hex(6)}"
        receipt_path = receipts_dir / f"{capture_id}.json"
        receipt["receipt_id"] = f"receipt:objet-capture:{capture_id}"
        receipt_bytes = (
            json.dumps(
                json_safe(receipt),
                indent=2,
                ensure_ascii=False,
                default=str,
            )
            + "\n"
        ).encode("utf-8")
        try:
            outcome = _create_only_bytes_outcome_aware(
                receipt_path,
                receipt_bytes,
            )
        except FileExistsError:
            continue
        if outcome == "not_written":
            raise OSError("objet_capture_receipt_not_written")
        return f"{OBJET_CAPTURE_RECEIPTS_DIR}/{capture_id}.json"


def _objet_capture_item_all_blockers(entry: dict[str, Any]) -> list[str]:
    derived_sub = entry.get("derived_text")
    if isinstance(derived_sub, dict):
        return [*entry.get("blockers", []), *derived_sub.get("blockers", [])]
    return list(entry.get("blockers", []))


def _objet_capture_item_all_warnings(entry: dict[str, Any]) -> list[str]:
    derived_sub = entry.get("derived_text")
    if isinstance(derived_sub, dict):
        return [*entry.get("warnings", []), *derived_sub.get("warnings", [])]
    return list(entry.get("warnings", []))


def _objet_capture_item_status_class(entry: dict[str, Any], *, approve: bool) -> str:
    # Additive v0.3.151 OPERATION_STATUS_CLASSES field for mixed-outcome paired items;
    # the original action vocabulary is untouched. `partial` means the original half is
    # durable (ok:false, terminal:false) and the derived half is retriable.
    original_state = entry.get("action") if approve else entry.get("planned_action")
    ok_states = OBJET_CAPTURE_ORIGINAL_OK_ACTIONS if approve else OBJET_CAPTURE_ORIGINAL_OK_PLANNED_ACTIONS
    if original_state not in ok_states:
        return "blocked"
    if approve and entry.get("blockers"):
        return "partial"
    derived_sub = entry.get("derived_text")
    if isinstance(derived_sub, dict) and (
        derived_sub.get("blockers") or derived_sub.get("item_status") == "not_attempted"
    ):
        return "partial"
    return "written" if approve else "preview"


def _objet_capture_run_status_class(item_results: list[dict[str, Any]], *, approve: bool) -> str:
    classes = [str(entry.get("status_class") or "") for entry in item_results]
    if classes and all(value == "blocked" for value in classes):
        return "blocked"
    if any(value == "partial" for value in classes) or (
        "blocked" in classes and any(value != "blocked" for value in classes)
    ):
        return "partial"
    return "written" if approve else "preview"


OBJET_CAPTURE_PARTIAL_NEXT_SAFE_ACTIONS = [
    "Re-run objet-capture with the SAME selection manifest: already-completed halves are "
    "idempotent (skip_already_present) and blocked halves are retried (idempotent repair).",
    "If the partial item carried a paired derived_text half, you can instead complete the pair "
    "via standalone capture: archive derive-text capture <archive-root> "
    "--source-object-id <object_id from this receipt> --text-file <staged transcript> "
    "--approve --reviewed-by <actor>.",
]
OBJET_CAPTURE_EVIDENCE_INCOMPLETE_NEXT_SAFE_ACTIONS = [
    "Run objet-capture dry-run again with the same reviewed selection before retrying.",
    "Re-run the same approved selection: completed object and derived-text halves remain idempotent while the missing capture receipt is recreated.",
]


def objet_capture_files_written(
    item_results: list[dict[str, Any]],
    *,
    receipt_path: str | None,
    generated_index_updated: bool = False,
    index_marked_dirty: bool = False,
) -> list[str]:
    """Project only artifacts this exact capture attempt verifiably changed.

    The projection is derived from the lower service's actual write/append
    evidence.  It intentionally excludes staged inputs, locks, directories,
    and already-present object/text files.
    """

    changed: list[str] = []

    def append_relative(value: Any) -> None:
        if not isinstance(value, str) or not value:
            return
        try:
            normalized = normalize_archive_relative_path(value)
        except (ArchivePathError, ArchiveServiceError, OSError, ValueError):
            return
        if normalized == value:
            changed.append(normalized)

    for entry in item_results:
        if not isinstance(entry, dict):
            continue
        # The original path sets stored_sha256_verified only after a newly
        # published/re-materialized object has been losslessly verified.  Skip
        # outcomes leave it false, so this is an exact changed-file signal.
        if entry.get("stored_sha256_verified") is True:
            append_relative(entry.get("logical_key"))
        if entry.get("manifest_record_appended") is True:
            append_relative("objects/manifests/files.jsonl")

        derived = entry.get("derived_text")
        if not isinstance(derived, dict):
            continue
        if (
            derived.get("stored_sha256_verified") is True
            and derived.get("planned_action") in ("capture", "re_materialize")
        ):
            append_relative(derived.get("text_logical_key"))
        if derived.get("manifest_record_appended") is True:
            append_relative(DERIVED_TEXT_MANIFEST_RELATIVE_PATH)
        append_relative(derived.get("receipt_path"))

    if generated_index_updated or index_marked_dirty:
        append_relative(INDEX_RELATIVE_PATH)
    append_relative(receipt_path)
    return unique_preserve_order(changed)


def _objet_capture_selection_input(
    root: Path,
    selection_path: Path | str,
) -> tuple[dict[str, Any] | None, str | None, str | None]:
    """Read one selection using archive-root authority, never process CWD.

    Absolute paths remain compatible for callers that already produced them.
    Relative paths are always resolved from the archive root, never process CWD.
    The returned blocker vocabulary is intentionally small and content-free.
    """

    root = root.resolve()
    raw_value = os.fspath(selection_path).strip()
    if not raw_value:
        return None, None, "selection_path_not_archive_relative"
    candidate = Path(raw_value)
    try:
        if candidate.is_absolute():
            resolved = candidate.resolve()
            relative = (
                resolved.relative_to(root).as_posix()
                if is_path_within_root(resolved, root)
                else None
            )
        else:
            relative = normalize_archive_relative_path(raw_value)
            resolved = archive_internal_path(root, relative)
    except (ArchivePathError, ArchiveServiceError, OSError, ValueError):
        return None, None, "selection_path_not_archive_relative"

    if (
        not resolved.is_file()
        or resolved.is_symlink()
        or (
            is_path_within_root(resolved, root)
            and zet_revision_path_has_symlink_component(root, resolved)
        )
    ):
        return None, relative, "selection_file_missing_or_not_regular"
    try:
        raw_bytes = resolved.read_bytes()
    except OSError:
        return None, relative, "selection_file_unreadable"
    try:
        text = raw_bytes.decode("utf-8")
    except UnicodeDecodeError:
        return None, relative, "selection_manifest_invalid_utf8"
    try:
        loaded = json.loads(text)
    except json.JSONDecodeError:
        return None, relative, "selection_manifest_invalid_json"
    if not isinstance(loaded, dict):
        return None, relative, "selection_manifest_not_object"
    return loaded, relative, None


def _objet_capture_run(
    archive_root: Path | str,
    selection_path: Path | str | None,
    *,
    approve: bool,
    reviewed_by: str | None,
    project_intake_receipt: str | None = None,
    selection_document: dict[str, Any] | None = None,
    selection_document_path: Path | str | None = None,
    native_exact_authorized: bool = False,
    exact_human_approval_receipt: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    root = Path(archive_root).resolve()
    enablement = read_capture_enablement(root)
    sandbox_blockers = (
        []
        if native_exact_authorized
        else objet_capture_sandbox_blockers(root, enablement)
    )
    if sandbox_blockers:
        return objet_capture_refusal(
            sandbox_blockers[0], dry_run=not approve, enablement_state=str(enablement.get("state"))
        )
    capture_enabled = enablement.get("valid") is True or native_exact_authorized
    root = require_existing_archive_root(root)
    archive_id = read_archive_id(root)
    captured_at = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    if selection_document is None:
        selection_raw, selection_relative, selection_input_blocker = (
            _objet_capture_selection_input(root, selection_path or "")
        )
    else:
        selection_raw = copy.deepcopy(selection_document)
        selection_relative: str | None = None
        selection_input_blocker: str | None = None
        if not isinstance(selection_raw, dict):
            selection_input_blocker = "selection_manifest_not_object"
        elif selection_document_path is not None:
            raw_label = os.fspath(selection_document_path).strip()
            try:
                candidate = Path(raw_label)
                if candidate.is_absolute():
                    resolved = candidate.resolve()
                    selection_relative = (
                        resolved.relative_to(root).as_posix()
                        if is_path_within_root(resolved, root)
                        else None
                    )
                else:
                    selection_relative = normalize_archive_relative_path(
                        raw_label
                    )
            except (
                ArchivePathError,
                ArchiveServiceError,
                OSError,
                ValueError,
            ):
                selection_relative = None
            if selection_relative is None:
                selection_input_blocker = "selection_path_not_archive_relative"
    if selection_input_blocker is not None or selection_raw is None:
        return {
            "ok": False,
            "dry_run": not approve,
            "lifecycle_action": "objet_capture_plan" if not approve else "objet_capture",
            "archive_id": archive_id,
            "status_class": "blocked",
            "selection_path": selection_relative,
            "items": [],
            "blockers": [selection_input_blocker or "selection_manifest_not_object"],
            "warnings": [],
            "would_change": [],
            "privacy_guards": {
                "selection_value_echoed": False,
                "local_absolute_paths_echoed": False,
                "exception_text_echoed": False,
                "writes": False,
            },
        }
    selection = selection_raw
    selection_sha256 = sha256_json_value(selection)
    manifest_mutation_owner_sha256 = archive_manifest_mutation_owner_sha256(
        operation="objet_capture",
        operation_binding_sha256=selection_sha256,
    )
    envelope_blockers = objet_capture_envelope_blockers(selection, archive_id)
    context_warnings: list[str] = []
    project_intake_context = objet_capture_project_intake_context(
        root,
        selection,
        project_intake_receipt,
        envelope_blockers,
        context_warnings,
    )
    base_output = {
        "dry_run": not approve,
        "lifecycle_action": "objet_capture_plan" if not approve else "objet_capture",
        "archive_id": archive_id,
        "selection_path": selection_relative,
        "selection_manifest_id": str(selection.get("manifest_id") or ""),
        "selection_manifest_sha256": selection_sha256,
        "project_intake_context": project_intake_context,
    }
    if envelope_blockers:
        return {
            "ok": False,
            **base_output,
            "status_class": "blocked",
            "items": [],
            "blockers": unique_preserve_order(envelope_blockers),
            "warnings": unique_preserve_order(context_warnings),
        }

    items_sorted = sorted(selection["items"], key=lambda item: str(item.get("item_id") or ""))
    appended_this_run: set[str] = set()
    item_results: list[dict[str, Any]] = []
    aborted = False

    if approve:
        # Read-only preflight: if this exact selection needs a central manifest
        # append, index authority must exist before object bytes, receipt
        # directories, or any other operation-owned evidence can be created.
        preflight_canonical_ids = objet_capture_canonical_record_ids(
            load_manifest_records(root)
        )
        preflight_appended: set[str] = set()
        preflight_items = [
            _objet_capture_process_item(
                root,
                item,
                approve=False,
                canonical_ids=preflight_canonical_ids,
                appended_this_run=preflight_appended,
                captured_at=captured_at,
                reviewed_by=None,
                selection=selection,
                selection_sha256=selection_sha256,
                manifest_appender=lambda _record: None,
                capture_enabled=capture_enabled,
            )
            for item in items_sorted
        ]
        manifest_write_planned = any(
            item.get("planned_action") in {"capture", "repair_append"}
            for item in preflight_items
        )
        if manifest_write_planned:
            try:
                preflight_manifest = archive_index_stable_file_snapshot(
                    root,
                    root / ZETTEL_OBJET_LINK_MANIFEST_RELATIVE_PATH,
                    max_bytes=ZETTEL_OBJET_LINK_MANIFEST_MAX_BYTES,
                )
                require_archive_manifest_index_mutation_authority(
                    root,
                    operation_owner_sha256=manifest_mutation_owner_sha256,
                    expected_pre_manifest_sha256=preflight_manifest[
                        "file_sha256"
                    ],
                    expected_post_manifest_sha256=preflight_manifest[
                        "file_sha256"
                    ],
                )
            except (ArchiveServiceError, OSError, sqlite3.Error, ValueError):
                return {
                    "ok": False,
                    **base_output,
                    "status_class": "blocked",
                    "aborted": False,
                    "reviewed_by": reviewed_by,
                    "captured_at": captured_at,
                    "items": preflight_items,
                    "receipt_path": None,
                    "summary": objet_capture_summary(
                        preflight_items,
                        approve=False,
                    ),
                    "blockers": [INDEX_REBUILD_REQUIRED],
                    "warnings": unique_preserve_order(context_warnings),
                    "files_written": [],
                    "generated_index_updated": False,
                    "index_marked_dirty": False,
                    "index_generation": None,
                    "index_mutation_resumed": False,
                }
        # Pre-flight the receipt directory BEFORE any byte/manifest write: the always-receipt
        # audit guarantee is only meaningful if the receipt is known writable up front.
        try:
            archive_internal_path(root, OBJET_CAPTURE_RECEIPTS_DIR).mkdir(parents=True, exist_ok=True)
        except OSError:
            return {"ok": False, **base_output, "items": [], "blockers": ["receipts_dir_unavailable"], "warnings": []}
        manifest_path = archive_internal_path(root, "objects/manifests/files.jsonl")
        receipt_path_value: str | None = None
        receipt_write_failed = False
        manifest_index_generation: str | None = None
        manifest_index_lease_token: ArchiveIndexMutationLeaseToken | None = None
        manifest_index_updated = False
        manifest_index_rebuild_required = False
        manifest_index_resumed = False
        manifest_index_started_this_run = False
        with _ObjetCaptureManifestLock(root):
            canonical_ids = objet_capture_canonical_record_ids(load_manifest_records(root))
            pending_manifest_records: list[dict[str, Any]] = []
            publication_outcome_unverified = False
            try:
                # Phase 1 — original halves, byte-for-byte unchanged in what they write
                # (publish bytes -> manifest_appender record).
                for item in items_sorted:

                    def manifest_appender(record: dict[str, Any]) -> None:
                        pending_manifest_records.append(record)

                    try:
                        item_result = _objet_capture_process_item(
                            root,
                            item,
                            approve=True,
                            canonical_ids=canonical_ids,
                            appended_this_run=appended_this_run,
                            captured_at=captured_at,
                            reviewed_by=reviewed_by,
                            selection=selection,
                            selection_sha256=selection_sha256,
                            manifest_appender=manifest_appender,
                            capture_enabled=capture_enabled,
                        )
                    except PublicationOutcomeUnverified:
                        aborted = True
                        publication_outcome_unverified = True
                        raise
                    except Exception:
                        aborted = True
                        raise
                    if "derived_text" in item:
                        item_result["derived_text"] = _objet_capture_derived_text_initial_subresult()
                    item_results.append(item_result)

                # Phase boundary — ordering is load-bearing: original bytes durable ->
                # original manifest line durable (flush+fsync+close) -> derived
                # registration. The reverse partial (a derived record referencing a
                # nonexistent object_id after a crash) must be impossible by
                # construction: nothing in the codebase detects or repairs that
                # direction. find_manifest_record also reads the manifest from disk,
                # which is why phase 2 may not run against a buffered handle.
                if pending_manifest_records:
                    try:
                        before_manifest = archive_index_stable_file_snapshot(
                            root,
                            manifest_path,
                            max_bytes=ZETTEL_OBJET_LINK_MANIFEST_MAX_BYTES,
                        )
                        expected_manifest_bytes = _jsonl_records_post_bytes(
                            before_manifest["raw"],
                            pending_manifest_records,
                        )
                        expected_manifest_sha256 = (
                            "sha256:"
                            + hashlib.sha256(expected_manifest_bytes).hexdigest()
                        )
                        (
                            manifest_index_generation,
                            manifest_index_began,
                            manifest_index_lease_token,
                        ) = prepare_archive_manifest_index_mutation(
                            root,
                            operation_owner_sha256=(
                                manifest_mutation_owner_sha256
                            ),
                            expected_pre_manifest_sha256=before_manifest[
                                "file_sha256"
                            ],
                            expected_post_manifest_sha256=(
                                expected_manifest_sha256
                            ),
                        )
                        manifest_index_started_this_run = (
                            manifest_index_started_this_run
                            or manifest_index_began
                        )
                        manifest_index_resumed = not manifest_index_began
                    except (ArchiveServiceError, OSError, sqlite3.Error, ValueError):
                        manifest_index_rebuild_required = True
                        aborted = True
                        for entry in item_results:
                            if entry.get("action") in OBJET_CAPTURE_ORIGINAL_OK_ACTIONS:
                                entry.setdefault("blockers", []).append(
                                    INDEX_REBUILD_REQUIRED
                                )
                    if manifest_index_rebuild_required:
                        pending_manifest_records = []

                if pending_manifest_records:
                    try:
                        append_outcome = _append_jsonl_records_outcome_aware(
                            manifest_path,
                            pending_manifest_records,
                        )
                    except PublicationOutcomeUnverified:
                        aborted = True
                        publication_outcome_unverified = True
                        raise
                    if append_outcome == "not_written":
                        for entry in item_results:
                            if entry.get("manifest_record_appended") is True:
                                entry["manifest_record_appended"] = False
                                entry["planned_action"] = "blocked"
                                entry["action"] = "blocked"
                                entry["blockers"].append("manifest_append_failed")
                        manifest_index_updated = (
                            replace_archive_index_manifest_projection(
                                root,
                                expected_generation=str(
                                    manifest_index_generation or ""
                                ),
                                expected_manifest_sha256=before_manifest[
                                    "file_sha256"
                                ],
                                expected_mutation_owner_sha256=(
                                    manifest_mutation_owner_sha256
                                ),
                                lease_token=manifest_index_lease_token,
                            )
                        )
                        if not manifest_index_updated:
                            manifest_index_rebuild_required = True
                    else:
                        manifest_index_updated = (
                            replace_archive_index_manifest_projection(
                                root,
                                expected_generation=str(
                                    manifest_index_generation or ""
                                ),
                                expected_manifest_sha256=(
                                    expected_manifest_sha256
                                ),
                                expected_mutation_owner_sha256=(
                                    manifest_mutation_owner_sha256
                                ),
                                lease_token=manifest_index_lease_token,
                            )
                        )
                        if not manifest_index_updated:
                            manifest_index_rebuild_required = True

                # A previous run can stop after the exact manifest append but
                # before its SQLite delta.  An idempotent replay has no pending
                # manifest rows, so repair that owned dirty generation without
                # beginning a new mutation.  A genuinely current no-op performs
                # no begin and no index write.
                if (
                    not pending_manifest_records
                    and not manifest_index_rebuild_required
                    and item_results
                    and all(
                        entry.get("action") == "skip_already_present"
                        for entry in item_results
                    )
                ):
                    index_evidence = require_current_zettel_index(root)
                    if (
                        not index_evidence.get("ok")
                        and "archive_index_dirty"
                        in set(index_evidence.get("reason_codes") or [])
                    ):
                        try:
                            resumed_manifest = archive_index_stable_file_snapshot(
                                root,
                                manifest_path,
                                max_bytes=ZETTEL_OBJET_LINK_MANIFEST_MAX_BYTES,
                            )
                            (
                                manifest_index_generation,
                                manifest_index_began,
                                manifest_index_lease_token,
                            ) = prepare_archive_manifest_index_mutation(
                                root,
                                operation_owner_sha256=(
                                    manifest_mutation_owner_sha256
                                ),
                                expected_pre_manifest_sha256=resumed_manifest[
                                    "file_sha256"
                                ],
                                expected_post_manifest_sha256=resumed_manifest[
                                    "file_sha256"
                                ],
                            )
                            manifest_index_started_this_run = (
                                manifest_index_started_this_run
                                or manifest_index_began
                            )
                            if manifest_index_began:
                                raise ArchiveServiceError(INDEX_REBUILD_REQUIRED)
                            manifest_index_resumed = True
                            manifest_index_updated = (
                                replace_archive_index_manifest_projection(
                                    root,
                                    expected_generation=manifest_index_generation,
                                    expected_manifest_sha256=resumed_manifest[
                                        "file_sha256"
                                    ],
                                    expected_mutation_owner_sha256=(
                                        manifest_mutation_owner_sha256
                                    ),
                                    lease_token=manifest_index_lease_token,
                                )
                            )
                            if not manifest_index_updated:
                                manifest_index_rebuild_required = True
                        except (
                            ArchiveServiceError,
                            OSError,
                            sqlite3.Error,
                            ValueError,
                        ):
                            manifest_index_rebuild_required = True

                if manifest_index_rebuild_required:
                    aborted = True
                    for entry in item_results:
                        if entry.get("action") in OBJET_CAPTURE_ORIGINAL_OK_ACTIONS:
                            blockers = entry.setdefault("blockers", [])
                            if INDEX_REBUILD_REQUIRED not in blockers:
                                blockers.append(INDEX_REBUILD_REQUIRED)
                        derived = entry.get("derived_text")
                        if isinstance(derived, dict):
                            derived["item_status"] = "not_attempted"
                            derived_blockers = derived.setdefault("blockers", [])
                            if INDEX_REBUILD_REQUIRED not in derived_blockers:
                                derived_blockers.append(INDEX_REBUILD_REQUIRED)

                # Phase 2 — derived halves, same sorted order, inside the still-held
                # _ObjetCaptureManifestLock. _DerivedTextManifestLock nests inside it:
                # lock order is ObjetCapture -> DerivedText, never the reverse; no
                # reverse ordering exists anywhere in this file — keep it that way.
                for item, item_result in zip(items_sorted, item_results):
                    if manifest_index_rebuild_required:
                        break
                    if "derived_text" not in item:
                        continue
                    try:
                        item_result["derived_text"] = _objet_capture_paired_derived_text(
                            root,
                            archive_id,
                            item,
                            item_result,
                            approve=True,
                            reviewed_by=reviewed_by,
                            captured_at=captured_at,
                            capture_enabled=capture_enabled,
                            selection=selection,
                            selection_sha256=selection_sha256,
                        )
                    except PublicationOutcomeUnverified:
                        aborted = True
                        publication_outcome_unverified = True
                        raise
                    except Exception:
                        # Exception containment: _derived_text_write_receipt re-raises
                        # OSError after cleanup; ANY phase-2 exception converts to an
                        # item-level derived blocker and must NOT set aborted or kill
                        # the remaining items.
                        failed = _objet_capture_derived_text_initial_subresult()
                        failed["item_status"] = "blocked"
                        failed["blockers"].append("derived_text_registration_failed")
                        item_result["derived_text"] = failed
            finally:
                # Receipt built and written AFTER both phases (always-written
                # guarantee preserved): if phase 2 was never reached, derived
                # sub-results carry their initialized not-attempted state and
                # `aborted` reflects reality.
                if not publication_outcome_unverified:
                    for entry in item_results:
                        entry["status_class"] = _objet_capture_item_status_class(entry, approve=True)
                    summary = objet_capture_summary(item_results, approve=True)
                    run_blockers = unique_preserve_order(
                        [code for entry in item_results for code in _objet_capture_item_all_blockers(entry)]
                    )
                    receipt = {
                    "receipt_id": None,
                    "schema": OBJET_CAPTURE_RECEIPT_SCHEMA,
                    "dry_run": False,
                    "ok": not run_blockers and not aborted,
                    "status_class": _objet_capture_run_status_class(item_results, approve=True),
                    "aborted": aborted,
                    "archive_id": archive_id,
                    "selection_manifest_id": str(selection.get("manifest_id") or ""),
                    "selection_manifest_sha256": selection_sha256,
                    "project_intake_context": project_intake_context,
                    "reviewed_by": reviewed_by,
                    "captured_at": captured_at,
                    "items": item_results,
                    "summary": summary,
                    "blockers": run_blockers,
                    "warnings": unique_preserve_order(
                        [
                            *context_warnings,
                            *[code for entry in item_results for code in _objet_capture_item_all_warnings(entry)],
                        ]
                    ),
                    }
                    if exact_human_approval_receipt is not None:
                        receipt["exact_human_approval"] = dict(
                            exact_human_approval_receipt
                        )
                    try:
                        receipt_path_value = _objet_capture_write_receipt(
                            root,
                            receipt,
                            captured_at,
                        )
                    except PublicationOutcomeUnverified:
                        raise
                    except OSError:
                        receipt_write_failed = True
        run_blockers = unique_preserve_order(
            [code for entry in item_results for code in _objet_capture_item_all_blockers(entry)]
        )
        if receipt_write_failed:
            run_blockers = unique_preserve_order(
                [*run_blockers, "objet_capture_receipt_write_failed"]
            )
        run_status_class = (
            "evidence_incomplete"
            if receipt_write_failed
            else _objet_capture_run_status_class(item_results, approve=True)
        )
        manifest_index_marked_dirty = False
        if (
            manifest_index_generation is not None
            and manifest_index_lease_token is not None
            and not manifest_index_updated
        ):
            manifest_index_marked_dirty = mark_archive_index_dirty(
                root,
                expected_generation=manifest_index_generation,
                expected_mutation_owner_sha256=(
                    manifest_mutation_owner_sha256
                ),
                lease_token=manifest_index_lease_token,
            )
        result = {
            "ok": not run_blockers and not aborted,
            **base_output,
            "status_class": run_status_class,
            "aborted": aborted,
            "reviewed_by": reviewed_by,
            "captured_at": captured_at,
            "items": item_results,
            "receipt_path": receipt_path_value,
            "summary": objet_capture_summary(item_results, approve=True),
            "blockers": run_blockers,
            "warnings": unique_preserve_order(
                [
                    *context_warnings,
                    *[code for entry in item_results for code in _objet_capture_item_all_warnings(entry)],
                ]
            ),
            "files_written": objet_capture_files_written(
                item_results,
                receipt_path=receipt_path_value,
                generated_index_updated=manifest_index_updated,
                index_marked_dirty=manifest_index_marked_dirty,
            ),
            "generated_index_updated": manifest_index_updated,
            "index_marked_dirty": manifest_index_marked_dirty,
            "index_generation": manifest_index_generation,
            "index_mutation_resumed": manifest_index_resumed,
        }
        if run_status_class == "partial":
            # v0.3.151 ai_operator_rule: a partial outcome must point at the safe
            # completion routes. No absolute local paths are echoed.
            result["next_safe_actions"] = list(OBJET_CAPTURE_PARTIAL_NEXT_SAFE_ACTIONS)
        elif run_status_class == "evidence_incomplete":
            result["next_safe_actions"] = list(
                OBJET_CAPTURE_EVIDENCE_INCOMPLETE_NEXT_SAFE_ACTIONS
            )
        return result

    canonical_ids = objet_capture_canonical_record_ids(load_manifest_records(root))
    for item in items_sorted:
        item_results.append(
            _objet_capture_process_item(
                root,
                item,
                approve=False,
                canonical_ids=canonical_ids,
                appended_this_run=appended_this_run,
                captured_at=captured_at,
                reviewed_by=None,
                selection=selection,
                selection_sha256=selection_sha256,
                manifest_appender=lambda record: None,
                capture_enabled=capture_enabled,
            )
        )
    # Plan the derived half for each paired item whose original half is non-blocked.
    # This runs the SAME confinement chain + commitment check + decode as apply and
    # plans with source_presence="paired_same_run": routing through the unmodified
    # standalone path would report source_object_missing (the original is not yet
    # manifested), violating the dry-run-predicts-apply invariant.
    planned_derived_ids: set[str] = set()
    planned_text_keys: set[str] = set()
    for item, item_result in zip(items_sorted, item_results):
        if "derived_text" not in item:
            continue
        item_result["derived_text"] = _objet_capture_paired_derived_text(
            root,
            archive_id,
            item,
            item_result,
            approve=False,
            reviewed_by=None,
            captured_at=captured_at,
            capture_enabled=capture_enabled,
            selection=selection,
            selection_sha256=selection_sha256,
            planned_derived_ids=planned_derived_ids,
            planned_text_keys=planned_text_keys,
        )
    for entry in item_results:
        entry["status_class"] = _objet_capture_item_status_class(entry, approve=False)
    run_blockers = unique_preserve_order(
        [code for entry in item_results for code in _objet_capture_item_all_blockers(entry)]
    )
    planned_writes: list[str] = []
    for entry in item_results:
        if entry["planned_action"] in ("capture", "re_materialize") and entry["logical_key"]:
            planned_writes.append(entry["logical_key"])
        if entry["planned_action"] in ("capture", "repair_append"):
            planned_writes.append("objects/manifests/files.jsonl (+1 line)")
        derived_sub = entry.get("derived_text")
        if isinstance(derived_sub, dict):
            planned_writes.extend(
                value for value in derived_sub.get("planned_writes") or [] if isinstance(value, str)
            )
    run_status_class = _objet_capture_run_status_class(item_results, approve=False)
    timestamp_compact = re.sub(r"[^0-9TZ]", "", captured_at)
    result = {
        "ok": not run_blockers,
        **base_output,
        "status_class": run_status_class,
        "items": item_results,
        "proposed_receipt_path": f"{OBJET_CAPTURE_RECEIPTS_DIR}/{timestamp_compact}-{secrets.token_hex(6)}.json",
        "planned_writes": planned_writes,
        "summary": objet_capture_summary(item_results, approve=False),
        "blockers": run_blockers,
        "warnings": unique_preserve_order(
            [*context_warnings, *[code for entry in item_results for code in _objet_capture_item_all_warnings(entry)]]
        ),
        "would_change": planned_writes,
    }
    if run_status_class == "partial":
        result["next_safe_actions"] = list(OBJET_CAPTURE_PARTIAL_NEXT_SAFE_ACTIONS)
    return result


def objet_capture_summary(item_results: list[dict[str, Any]], *, approve: bool) -> dict[str, int]:
    counts = {"capture": 0, "repair_append": 0, "re_materialize": 0, "skip_already_present": 0, "blocked": 0}
    for entry in item_results:
        planned = entry.get("planned_action")
        if planned in ("blocked", "dest_collision"):
            counts["blocked"] += 1
        elif planned in counts:
            counts[planned] += 1
    if approve:
        summary = {
            "captured": counts["capture"],
            "repair_appended": counts["repair_append"],
            "re_materialized": counts["re_materialize"],
            "skipped": counts["skip_already_present"],
            "blocked": counts["blocked"],
        }
    else:
        summary = {
            "would_capture": counts["capture"],
            "would_repair_append": counts["repair_append"],
            "would_re_materialize": counts["re_materialize"],
            "would_skip": counts["skip_already_present"],
            "blocked": counts["blocked"],
        }
    # Additive derived-text counters, present only when the run carried >= 1 paired
    # item, so plain-run summaries stay byte-identical to v0.3.158.
    derived_subs = [
        entry.get("derived_text") for entry in item_results if isinstance(entry.get("derived_text"), dict)
    ]
    if derived_subs:
        if approve:
            summary["derived_text_written"] = sum(1 for sub in derived_subs if sub.get("item_status") == "written")
            summary["derived_text_skipped"] = sum(1 for sub in derived_subs if sub.get("item_status") == "skipped")
            summary["derived_text_blocked"] = sum(
                1 for sub in derived_subs if sub.get("item_status") in ("blocked", "not_attempted")
            )
        else:
            summary["would_register_derived_text"] = sum(
                1 for sub in derived_subs if sub.get("item_status") == "ready"
            )
            summary["derived_text_blocked"] = sum(
                1 for sub in derived_subs if sub.get("item_status") in ("blocked", "not_attempted")
            )
    return summary


def _staged_cleanup_strict_json_object(raw: bytes) -> dict[str, Any] | None:
    """Decode one bounded JSON object without accepting duplicate members."""

    def unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate_json_member")
            result[key] = value
        return result

    try:
        value = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=unique_object,
        )
    except (UnicodeError, json.JSONDecodeError, ValueError, RecursionError):
        return None
    return value if isinstance(value, dict) else None


def _staged_cleanup_stat_identity(value: os.stat_result) -> tuple[int, int, int, int, int]:
    return (
        int(value.st_dev),
        int(getattr(value, "st_ino", 0) or 0),
        int(value.st_size),
        int(getattr(value, "st_mtime_ns", 0)),
        int(value.st_mode),
    )


def _staged_cleanup_path_identity(
    root: Path,
    path: Path,
    relative: str,
) -> tuple[int, int, int, int, int] | None:
    if objet_capture_path_chain_blockers(root, relative):
        return None
    try:
        observed = os.lstat(path)
    except OSError:
        return None
    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
    if stat.S_ISLNK(observed.st_mode) or (
        reparse_flag
        and getattr(observed, "st_file_attributes", 0) & reparse_flag
    ):
        return None
    return _staged_cleanup_stat_identity(observed)


def _staged_cleanup_authority_unchanged(
    root: Path,
    authority: tuple[Any, ...],
) -> bool:
    if len(authority) not in {3, 4}:
        return False
    path, relative, expected = authority[:3]
    if _staged_cleanup_path_identity(root, path, relative) != expected:
        return False
    if len(authority) == 3:
        # Directory authorities bind enumeration identity only. File
        # authorities always carry a fourth exact-byte digest below.
        return True
    expected_digest = authority[3]
    digest, size, observed_authority = _staged_cleanup_stable_file_digest(
        root,
        path,
        relative,
    )
    return bool(
        isinstance(expected_digest, str)
        and digest == expected_digest
        and size == expected[2]
        and observed_authority is not None
        and observed_authority[2] == expected
    )


def _staged_cleanup_staged_tree_snapshot(
    root: Path,
    staged_root: Path,
    normalized: str,
) -> tuple[
    tuple[tuple[str, tuple[int, int, int, int, int]], ...] | None,
    list[Path],
]:
    rows: list[tuple[str, tuple[int, int, int, int, int]]] = []
    files: list[Path] = []
    failed = False
    directory_authorities: list[
        tuple[Path, str, tuple[int, int, int, int, int]]
    ] = []

    def onerror(_error: OSError) -> None:
        nonlocal failed
        failed = True

    for dirpath, dirnames, filenames in os.walk(staged_root, onerror=onerror):
        directory = Path(dirpath)
        try:
            relative_dir = directory.relative_to(staged_root).as_posix()
        except ValueError:
            failed = True
            continue
        relative = normalized if relative_dir == "." else f"{normalized}/{relative_dir}"
        identity = _staged_cleanup_path_identity(root, directory, relative)
        if identity is None:
            failed = True
        else:
            rows.append((f"d:{relative_dir}", identity))
            directory_authorities.append((directory, relative, identity))
        for dirname in list(dirnames):
            child = directory / dirname
            try:
                child_stat = os.lstat(child)
            except OSError:
                failed = True
                continue
            reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
            if stat.S_ISLNK(child_stat.st_mode) or (
                reparse_flag
                and getattr(child_stat, "st_file_attributes", 0) & reparse_flag
            ):
                dirnames.remove(dirname)
                child_relative = child.relative_to(staged_root).as_posix()
                rows.append((f"u:{child_relative}", _staged_cleanup_stat_identity(child_stat)))
                files.append(child)
        for filename in filenames:
            child = directory / filename
            child_relative = child.relative_to(staged_root).as_posix()
            relative = f"{normalized}/{child_relative}"
            identity = _staged_cleanup_path_identity(root, child, relative)
            if identity is None:
                failed = True
                continue
            rows.append((f"f:{child_relative}", identity))
            files.append(child)
    if failed:
        return None, files
    if any(
        not _staged_cleanup_authority_unchanged(root, authority)
        for authority in directory_authorities
    ):
        return None, files
    return tuple(sorted(rows)), sorted(files)


def _staged_cleanup_stable_file_digest(
    root: Path,
    path: Path,
    relative: str,
    *,
    progress_callback: Callable[[int], None] | None = None,
) -> tuple[
    str | None,
    int | None,
    tuple[Path, str, tuple[int, int, int, int, int], str] | None,
]:
    """Hash one regular file through a stable, no-follow descriptor."""

    entry_identity = _staged_cleanup_path_identity(root, path, relative)
    if entry_identity is None or not stat.S_ISREG(entry_identity[4]):
        return None, None, None
    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        fd = os.open(str(path), flags)
    except OSError:
        return None, None, None
    try:
        opened = os.fstat(fd)
        if (
            not stat.S_ISREG(opened.st_mode)
            or _staged_cleanup_stat_identity(opened) != entry_identity
        ):
            return None, None, None
        digest = hashlib.sha256()
        total = 0
        while True:
            chunk = os.read(fd, 1024 * 1024)
            if not chunk:
                break
            total += len(chunk)
            digest.update(chunk)
            if progress_callback is not None:
                progress_callback(total)
        opened_after = os.fstat(fd)
        final_identity = _staged_cleanup_path_identity(root, path, relative)
        if (
            _staged_cleanup_stat_identity(opened_after) != entry_identity
            or final_identity != entry_identity
            or total != entry_identity[2]
        ):
            return None, None, None
        digest_hex = digest.hexdigest()
        return digest_hex, total, (path, relative, entry_identity, digest_hex)
    except OSError:
        return None, None, None
    finally:
        try:
            os.close(fd)
        except OSError:
            pass


def _staged_cleanup_strict_object_manifest(
    root: Path,
    archive_id: str,
) -> tuple[
    list[dict[str, Any]],
    set[str],
    bool,
    tuple[Path, str, tuple[int, int, int, int, int], str] | None,
]:
    """Load strict canonical ordinary-object evidence from one stable snapshot."""

    relative = "objects/manifests/files.jsonl"
    manifest = archive_internal_path(root, relative)
    if not manifest.exists():
        return [], set(), True, None
    identity = _staged_cleanup_path_identity(root, manifest, relative)
    if identity is None:
        return [], set(), False, None
    raw, error = _bounded_stable_regular_file_read(
        manifest,
        max_bytes=STAGED_CLEANUP_MANIFEST_MAX_BYTES,
    )
    if raw is None or error is not None:
        return [], set(), False, None
    try:
        lines = raw.decode("utf-8").splitlines()
    except UnicodeError:
        return [], set(), False, None
    if len(lines) > STAGED_CLEANUP_MAX_DERIVED_RECEIPTS:
        return [], set(), False, None

    records: list[dict[str, Any]] = []
    canonical_rows: dict[str, list[tuple[bool, str]]] = {}
    for raw_line in lines:
        if not raw_line.strip():
            continue
        record = _staged_cleanup_strict_json_object(raw_line.encode("utf-8"))
        if record is None:
            return [], set(), False, None
        records.append(record)
        object_id = record.get("object_id")
        if not isinstance(object_id, str) or OBJECT_ID_RE.fullmatch(object_id) is None:
            continue
        digest = object_id.removeprefix("sha256:")
        logical_key = f"objects/sha256/{digest[:2]}/{digest}"
        size_bytes = record.get("size_bytes")
        locations = record.get("locations")
        provenance = record.get("provenance")
        canonical_location = bool(
            isinstance(locations, list)
            and any(
                isinstance(location, dict)
                and location.get("provider") == "local"
                and location.get("path") == logical_key
                and location.get("availability") == "available"
                for location in locations
            )
        )
        canonical_provenance = bool(
            isinstance(provenance, dict)
            and provenance.get("created_in") == f"archive:{archive_id}"
            and isinstance(provenance.get("source"), str)
            and bool(provenance.get("source"))
            and isinstance(provenance.get("captured_at"), str)
            and bool(provenance.get("captured_at"))
        )
        canonical = bool(
            record.get("sha256") == digest
            and record.get("logical_key") == logical_key
            and isinstance(record.get("mime"), str)
            and bool(record.get("mime"))
            and isinstance(size_bytes, int)
            and not isinstance(size_bytes, bool)
            and size_bytes >= 0
            and canonical_location
            and canonical_provenance
        )
        canonical_rows.setdefault(object_id, []).append(
            (canonical, sha256_json_value(record))
        )
    canonical_ids = {
        object_id
        for object_id, rows in canonical_rows.items()
        if len(rows) == 1 and rows[0][0]
    }
    return records, canonical_ids, True, (
        manifest,
        relative,
        identity,
        hashlib.sha256(raw).hexdigest(),
    )


def _staged_cleanup_strict_derived_records(
    root: Path,
) -> tuple[
    list[dict[str, Any]],
    bool,
    tuple[Path, str, tuple[int, int, int, int, int], str] | None,
]:
    """Load the derived manifest as one stable, bounded, strict JSONL snapshot."""

    manifest = archive_internal_path(root, DERIVED_TEXT_MANIFEST_RELATIVE_PATH)
    if not manifest.exists():
        return [], True, None
    identity = _staged_cleanup_path_identity(
        root,
        manifest,
        DERIVED_TEXT_MANIFEST_RELATIVE_PATH,
    )
    if identity is None:
        return [], False, None
    raw, error = _bounded_stable_regular_file_read(
        manifest,
        max_bytes=STAGED_CLEANUP_MANIFEST_MAX_BYTES,
    )
    if raw is None or error is not None:
        return [], False, None
    records: list[dict[str, Any]] = []
    try:
        lines = raw.decode("utf-8").splitlines()
    except UnicodeError:
        return [], False, None
    if len(lines) > STAGED_CLEANUP_MAX_DERIVED_RECEIPTS:
        return [], False, None
    for raw_line in lines:
        if not raw_line.strip():
            continue
        record = _staged_cleanup_strict_json_object(raw_line.encode("utf-8"))
        if record is None:
            return [], False, None
        records.append(record)
    return records, True, (
        manifest,
        DERIVED_TEXT_MANIFEST_RELATIVE_PATH,
        identity,
        hashlib.sha256(raw).hexdigest(),
    )


def _staged_cleanup_receipt_documents(
    root: Path,
    relative_root: str,
    *,
    safety_required: bool,
    filename_prefixes: set[str] | None = None,
) -> tuple[
    list[tuple[str, dict[str, Any]]],
    set[str],
    bool,
    list[tuple[Path, str, tuple[int, int, int, int, int], str]],
]:
    """Read direct JSON receipts once with stable per-file and aggregate bounds.

    Filenames are retained only as private matching authority.  They are never
    returned by staged_cleanup_check.
    """

    receipt_root = archive_internal_path(root, relative_root)
    if not receipt_root.exists():
        return [], set(), True, []
    if objet_capture_path_chain_blockers(root, relative_root):
        return [], set(), not safety_required, []
    try:
        root_stat = os.lstat(receipt_root)
    except OSError:
        return [], set(), not safety_required, []
    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
    if (
        stat.S_ISLNK(root_stat.st_mode)
        or not stat.S_ISDIR(root_stat.st_mode)
        or (
            reparse_flag
            and getattr(root_stat, "st_file_attributes", 0) & reparse_flag
        )
    ):
        return [], set(), not safety_required, []
    try:
        with os.scandir(receipt_root) as iterator:
            entries = sorted(
                [
                    entry
                    for entry in iterator
                    if entry.name.lower().endswith(".json")
                    and (
                        filename_prefixes is None
                        or any(entry.name.startswith(prefix) for prefix in filename_prefixes)
                    )
                ],
                key=lambda entry: entry.name,
            )
    except OSError:
        return [], set(), not safety_required, []
    if len(entries) > STAGED_CLEANUP_MAX_DERIVED_RECEIPTS:
        return [], {entry.name for entry in entries}, not safety_required, []

    documents: list[tuple[str, dict[str, Any]]] = []
    present_names: set[str] = set()
    total_bytes = 0
    complete = True
    authorities: list[
        tuple[Path, str, tuple[int, int, int, int, int], str]
    ] = []
    for entry in entries:
        present_names.add(entry.name)
        try:
            if entry.is_symlink() or not entry.is_file(follow_symlinks=False):
                complete = False
                continue
        except OSError:
            complete = False
            continue
        raw, error = _bounded_stable_regular_file_read(
            Path(entry.path),
            max_bytes=STAGED_CLEANUP_RECEIPT_MAX_BYTES,
        )
        if raw is None or error is not None:
            complete = False
            continue
        total_bytes += len(raw)
        if total_bytes > STAGED_CLEANUP_MAX_DERIVED_RECEIPT_SCAN_BYTES:
            complete = False
            break
        document = _staged_cleanup_strict_json_object(raw)
        if document is None:
            # Malformed receipts remain physically present but cannot prove a
            # completed capture.  Per-entry classification uses the filename's
            # capture timestamp prefix without reflecting that name publicly.
            continue
        documents.append((entry.name, document))
        relative = f"{relative_root}/{entry.name}"
        identity = _staged_cleanup_path_identity(root, Path(entry.path), relative)
        if identity is None:
            complete = False
        else:
            authorities.append(
                (
                    Path(entry.path),
                    relative,
                    identity,
                    hashlib.sha256(raw).hexdigest(),
                )
            )
    return documents, present_names, complete or not safety_required, authorities


def _staged_cleanup_derived_record_info(
    record: dict[str, Any],
    *,
    canonical_object_ids: set[str],
) -> dict[str, Any]:
    provenance = record.get("provenance") if isinstance(record.get("provenance"), dict) else {}
    source_digest = provenance.get("source_text_sha256")
    text_digest = record.get("text_sha256")
    source_object_id = record.get("source_object_id")
    text_logical_key = record.get("text_logical_key")
    derived_text_id = record.get("derived_text_id")
    size_bytes = record.get("size_bytes")
    captured_at = provenance.get("captured_at")
    source_digest_valid = isinstance(source_digest, str) and SHA256_RE.fullmatch(source_digest) is not None
    text_digest_valid = isinstance(text_digest, str) and SHA256_RE.fullmatch(text_digest) is not None
    source_digest_supported = source_digest_valid or (
        source_digest is None
        and isinstance(captured_at, str)
    )
    source_object_valid = (
        isinstance(source_object_id, str)
        and OBJECT_ID_RE.fullmatch(source_object_id) is not None
        and source_object_id in canonical_object_ids
    )
    logical_key_valid = bool(
        text_digest_valid
        and text_logical_key
        == f"{DERIVED_TEXT_STORE_PREFIX}/{text_digest[:2]}/{text_digest}.txt"
    )
    metadata_valid = not _derived_text_pair_metadata_blockers(
        derivation_kind=record.get("derivation_kind"),
        tool_name=record.get("tool_name"),
        tool_version=record.get("tool_version"),
        review_status=record.get("review_status"),
        confidence=record.get("confidence"),
        language=record.get("language"),
        model_name=record.get("model_name"),
        model_version=record.get("model_version"),
        born_digital=record.get("born_digital", False),
    )
    expected_id: str | None = None
    if source_object_valid and text_digest_valid and metadata_valid:
        expected_id = "derived-text:sha256:" + derived_text_identity_digest(
            source_object_id=source_object_id,
            text_sha256=text_digest,
            derivation_kind=str(record.get("derivation_kind")),
            tool_name=str(record.get("tool_name")),
            tool_version=str(record.get("tool_version")),
            model_name=record.get("model_name") if isinstance(record.get("model_name"), str) else None,
            model_version=record.get("model_version") if isinstance(record.get("model_version"), str) else None,
            review_status=str(record.get("review_status")),
        )
    valid = bool(
        record.get("schema") == DERIVED_TEXT_RECORD_SCHEMA
        and source_object_valid
        and text_digest_valid
        and logical_key_valid
        and metadata_valid
        and isinstance(size_bytes, int)
        and not isinstance(size_bytes, bool)
        and 0 <= size_bytes <= DERIVED_TEXT_MAX_SOURCE_BYTES
        and isinstance(derived_text_id, str)
        and derived_text_id == expected_id
        and (
            source_digest_supported
        )
    )
    receipt_prefix = (
        re.sub(r"[^0-9TZ]", "", captured_at) + "-"
        if isinstance(captured_at, str) and captured_at
        else None
    )
    return {
        "record": record,
        "valid": valid,
        "source_digest": source_digest if source_digest_valid else None,
        "text_digest": text_digest if text_digest_valid else None,
        "source_object_id": source_object_id if isinstance(source_object_id, str) else None,
        "text_logical_key": text_logical_key if isinstance(text_logical_key, str) else None,
        "derived_text_id": derived_text_id if isinstance(derived_text_id, str) else None,
        "size_bytes": size_bytes if isinstance(size_bytes, int) and not isinstance(size_bytes, bool) else None,
        "captured_at": captured_at if isinstance(captured_at, str) else None,
        "receipt_prefix": receipt_prefix,
    }


def _staged_cleanup_valid_derived_receipt(
    document: dict[str, Any],
    *,
    filename: str,
    archive_id: str,
    staged_digest: str,
    record_info: dict[str, Any] | None,
) -> bool:
    schema = document.get("schema")
    if schema not in {
        "wom-kit/derived-text-capture-receipt/v0.1",
        DERIVED_TEXT_CAPTURE_RECEIPT_SCHEMA,
    }:
        return False
    receipt_id = document.get("receipt_id")
    captured_at = document.get("captured_at")
    timestamp_prefix = (
        re.sub(r"[^0-9TZ]", "", captured_at) + "-"
        if isinstance(captured_at, str) and captured_at
        else ""
    )
    if (
        not filename.lower().endswith(".json")
        or receipt_id
        != f"receipt:derived-text-capture:{filename[:-5]}"
        or not timestamp_prefix
        or not filename.startswith(timestamp_prefix)
    ):
        return False
    text_digest = document.get("text_sha256")
    if not isinstance(text_digest, str) or SHA256_RE.fullmatch(text_digest) is None:
        return False
    if schema == DERIVED_TEXT_CAPTURE_RECEIPT_SCHEMA:
        if document.get("source_text_sha256") != staged_digest:
            return False
    elif text_digest != staged_digest:
        return False
    planned_action = document.get("planned_action")
    stored_sha256_verified = document.get("stored_sha256_verified")
    # The official repair_append writer verifies the already-present store
    # before appending the missing manifest row, but its historical receipt
    # truthfully leaves stored_sha256_verified=false because this invocation
    # did not publish or re-materialize the bytes.  Cleanup independently
    # rehashes the canonical store below, so retain that legitimate receipt
    # shape while still requiring a real boolean and exact action mapping.
    stored_verification_field_valid = (
        stored_sha256_verified is False
        if planned_action == "repair_append"
        else stored_sha256_verified is True
    )
    if (
        document.get("dry_run") is not False
        or document.get("ok") is not True
        or document.get("archive_id") != archive_id
        or not stored_verification_field_valid
        or not isinstance(document.get("reviewed_by"), str)
        or not document.get("reviewed_by")
        or {
            "capture": "captured",
            "repair_append": "repair_appended",
            "re_materialize": "re_materialized",
            "skip_already_present": "skip_already_present",
        }.get(planned_action)
        != document.get("action")
        or document.get("manifest_record_appended")
        is not (
            planned_action in {"capture", "repair_append"}
        )
        or document.get("blockers") != []
    ):
        return False
    if record_info is None:
        return True
    return bool(
        document.get("derived_text_id") == record_info.get("derived_text_id")
        and document.get("source_object_id") == record_info.get("source_object_id")
        and text_digest == record_info.get("text_digest")
        and document.get("text_logical_key") == record_info.get("text_logical_key")
        and document.get("derivation_kind")
        == record_info.get("record", {}).get("derivation_kind")
        and document.get("review_status")
        == record_info.get("record", {}).get("review_status")
    )


def _staged_cleanup_store_observation(
    root: Path,
    *,
    text_digest: str | None,
    text_logical_key: str | None,
) -> tuple[
    bool,
    bool,
    tuple[Path, str, tuple[int, int, int, int, int], str] | None,
]:
    if (
        text_digest is None
        or text_logical_key
        != f"{DERIVED_TEXT_STORE_PREFIX}/{text_digest[:2]}/{text_digest}.txt"
    ):
        return False, False, None
    store = archive_internal_path(root, text_logical_key)
    if objet_capture_path_chain_blockers(root, text_logical_key):
        return False, store.exists(), None
    present = store.exists()
    raw, error = _bounded_stable_regular_file_read(
        store,
        max_bytes=DERIVED_TEXT_MAX_SOURCE_BYTES,
    )
    verified = bool(
        raw is not None
        and error is None
        and hashlib.sha256(raw).hexdigest() == text_digest
    )
    if verified:
        identity = _staged_cleanup_path_identity(root, store, text_logical_key)
        if identity is None:
            return False, present, None
        return True, present, (store, text_logical_key, identity, text_digest)
    return False, present, None


def _staged_cleanup_valid_objet_receipt_envelope(
    document: dict[str, Any],
    *,
    filename: str,
    archive_id: str,
) -> bool:
    """Accept only a completed official v0.2/v0.3 objet receipt envelope.

    A v0.3 receipt may truthfully be ``partial`` when its ordinary-object half
    is durable and a paired derived-text half (or another item) is blocked.
    That remains usable evidence for the successful ordinary item.  An aborted
    run, inconsistent aggregate blockers, or synthetic scalar/boolean values
    must never become cleanup authority.
    """

    schema = document.get("schema")
    if schema not in {
        "wom-kit/objet-capture-receipt/v0.2",
        OBJET_CAPTURE_RECEIPT_SCHEMA,
    }:
        return False
    captured_at = document.get("captured_at")
    if (
        not isinstance(captured_at, str)
        or re.fullmatch(
            r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z",
            captured_at,
        )
        is None
    ):
        return False
    timestamp_prefix = re.sub(r"[^0-9TZ]", "", captured_at)
    if (
        re.fullmatch(rf"{re.escape(timestamp_prefix)}-[0-9a-f]{{12}}\.json", filename)
        is None
        or document.get("receipt_id")
        != f"receipt:objet-capture:{filename[:-5]}"
        or document.get("dry_run") is not False
        or document.get("archive_id") != archive_id
        # Even a writer-produced aborted receipt is completion evidence, not
        # cleanup evidence. Replay must mint a non-aborted receipt first.
        or document.get("aborted") is not False
    ):
        return False

    reviewer = document.get("reviewed_by")
    selection_manifest_id = document.get("selection_manifest_id")
    selection_manifest_sha256 = document.get("selection_manifest_sha256")
    if (
        not isinstance(reviewer, str)
        or safe_project_intake_actor_id(reviewer) != reviewer
        or not isinstance(selection_manifest_id, str)
        or not safe_source_intake_ref(selection_manifest_id)
        or not isinstance(selection_manifest_sha256, str)
        or OBJECT_ID_RE.fullmatch(selection_manifest_sha256) is None
    ):
        return False

    items = document.get("items")
    blockers = document.get("blockers")
    warnings = document.get("warnings")
    if (
        not isinstance(items, list)
        or not items
        or any(not isinstance(item, dict) for item in items)
        or not isinstance(blockers, list)
        or any(not isinstance(code, str) or not code for code in blockers)
        or not isinstance(warnings, list)
        or any(not isinstance(code, str) or not code for code in warnings)
    ):
        return False

    aggregated_blockers: list[str] = []
    for item in items:
        item_blockers = item.get("blockers")
        item_warnings = item.get("warnings")
        if (
            not isinstance(item_blockers, list)
            or any(not isinstance(code, str) or not code for code in item_blockers)
            or not isinstance(item_warnings, list)
            or any(not isinstance(code, str) or not code for code in item_warnings)
        ):
            return False
        aggregated_blockers.extend(item_blockers)
        derived = item.get("derived_text")
        if schema == "wom-kit/objet-capture-receipt/v0.2":
            if derived is not None:
                return False
        elif derived is not None:
            if not isinstance(derived, dict):
                return False
            derived_blockers = derived.get("blockers")
            derived_warnings = derived.get("warnings")
            if (
                not isinstance(derived_blockers, list)
                or any(
                    not isinstance(code, str) or not code
                    for code in derived_blockers
                )
                or not isinstance(derived_warnings, list)
                or any(
                    not isinstance(code, str) or not code
                    for code in derived_warnings
                )
            ):
                return False
            aggregated_blockers.extend(derived_blockers)
        if schema == OBJET_CAPTURE_RECEIPT_SCHEMA and item.get(
            "status_class"
        ) != _objet_capture_item_status_class(item, approve=True):
            return False

    expected_blockers = unique_preserve_order(aggregated_blockers)
    expected_ok = not expected_blockers
    if (
        blockers != expected_blockers
        or document.get("ok") is not expected_ok
        or document.get("summary")
        != objet_capture_summary(items, approve=True)
    ):
        return False
    if schema == OBJET_CAPTURE_RECEIPT_SCHEMA and document.get(
        "status_class"
    ) != _objet_capture_run_status_class(items, approve=True):
        return False
    return True


def _staged_cleanup_outer_receipt_links(
    root: Path,
    *,
    archive_id: str,
    filename_prefixes: set[str] | None = None,
) -> tuple[
    dict[str, set[int]],
    set[str],
    dict[str, set[str]],
    bool,
    list[tuple[Path, str, tuple[int, int, int, int, int], str]],
]:
    documents, _names, complete, authorities = _staged_cleanup_receipt_documents(
        root,
        OBJET_CAPTURE_RECEIPTS_DIR,
        safety_required=True,
        filename_prefixes=filename_prefixes,
    )
    linked: dict[str, set[int]] = {}
    candidate_object_ids: set[str] = set()
    derived_receipt_names: dict[str, set[str]] = {}
    for filename, document in documents:
        candidate_items = document.get("items")
        if isinstance(candidate_items, list):
            for candidate_item in candidate_items:
                if not isinstance(candidate_item, dict):
                    continue
                candidate_object_id = candidate_item.get("object_id")
                if (
                    isinstance(candidate_object_id, str)
                    and OBJECT_ID_RE.fullmatch(candidate_object_id)
                ):
                    candidate_object_ids.add(candidate_object_id)
        if not _staged_cleanup_valid_objet_receipt_envelope(
            document,
            filename=filename,
            archive_id=archive_id,
        ):
            continue
        items = document.get("items")
        if not isinstance(items, list):
            continue
        for item in items:
            if not isinstance(item, dict):
                continue
            object_id = item.get("object_id")
            digest = object_id.removeprefix("sha256:") if isinstance(object_id, str) else ""
            logical_key = f"objects/sha256/{digest[:2]}/{digest}" if digest else ""
            planned = item.get("planned_action")
            action = item.get("action")
            action_matches_plan = {
                "capture": "captured",
                "repair_append": "repair_appended",
                "re_materialize": "re_materialized",
                "skip_already_present": "skip_already_present",
            }.get(planned) == action
            expected_stored_sha256_verified = {
                "capture": True,
                "repair_append": False,
                "re_materialize": True,
                "skip_already_present": False,
            }.get(planned)
            expected_manifest_record_appended = {
                "capture": True,
                "repair_append": True,
                "re_materialize": False,
                "skip_already_present": False,
            }.get(planned)
            publication_flag_valid = bool(
                expected_stored_sha256_verified is not None
                and item.get("stored_sha256_verified")
                is expected_stored_sha256_verified
            )
            manifest_flag_valid = bool(
                expected_manifest_record_appended is not None
                and item.get("manifest_record_appended")
                is expected_manifest_record_appended
            )
            if (
                isinstance(object_id, str)
                and OBJECT_ID_RE.fullmatch(object_id)
                and item.get("logical_key") == logical_key
                and item.get("approved_object_id") == object_id
                and isinstance(item.get("size_bytes"), int)
                and not isinstance(item.get("size_bytes"), bool)
                and item.get("size_bytes") >= 0
                and isinstance(item.get("mime"), str)
                and bool(item.get("mime"))
                and action_matches_plan
                and publication_flag_valid
                and manifest_flag_valid
                and (
                    document.get("schema") != OBJET_CAPTURE_RECEIPT_SCHEMA
                    or item.get("status_class") in {"written", "partial"}
                )
                and item.get("blockers") == []
            ):
                linked.setdefault(object_id, set()).add(int(item["size_bytes"]))
            derived = item.get("derived_text")
            if isinstance(derived, dict):
                derived_text_id = derived.get("derived_text_id")
                receipt_path = derived.get("receipt_path")
                if (
                    isinstance(derived_text_id, str)
                    and re.fullmatch(
                        r"derived-text:sha256:[0-9a-f]{64}", derived_text_id
                    )
                    is not None
                    and isinstance(receipt_path, str)
                    and receipt_path.startswith(DERIVED_TEXT_CAPTURE_RECEIPTS_DIR + "/")
                ):
                    receipt_name = PurePosixPath(receipt_path).name
                    if (
                        receipt_name == receipt_path.removeprefix(
                            DERIVED_TEXT_CAPTURE_RECEIPTS_DIR + "/"
                        )
                        and receipt_name.lower().endswith(".json")
                    ):
                        derived_receipt_names.setdefault(derived_text_id, set()).add(
                            receipt_name
                        )
    return linked, candidate_object_ids, derived_receipt_names, complete, authorities


def staged_cleanup_check(
    archive_root: Path | str,
    staged_folder: str,
    *,
    deferred_path: Path | str | None = None,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> dict[str, Any]:
    """Report-only G2 deletion-safety verifier for a staged intake folder.

    Answers "is every file in this staged folder durably preserved, so the folder
    could be cleaned up?" Explicitly deferred entries remain unresolved staged
    material and therefore block folder cleanup. It NEVER deletes, moves, or writes
    anything; cleanup itself stays a manual human action after this report plus the
    doctor/hygiene checks listed in next_safe_actions.
    """
    root = require_existing_archive_root(archive_root)
    archive_id = read_archive_id(root)
    blockers: list[str] = []
    warnings: list[str] = []

    def _progress(stage: str, message: str, current: int | None = None, total: int | None = None) -> None:
        if progress_callback is not None:
            progress_callback(stage, message, current, total)

    def _progress_step(index: int, total: int | None = None) -> bool:
        return index == 1 or (total is not None and index == total) or index % 100 == 0

    def _hash_progress(stage: str, total_bytes: int) -> Callable[[int], None] | None:
        if progress_callback is None or total_bytes < 64 * 1024 * 1024:
            return None

        def report(bytes_read: int) -> None:
            _progress(stage, "hashed bytes", min(bytes_read, total_bytes), total_bytes)

        return report

    try:
        normalized = normalize_archive_relative_path(staged_folder)
        staged_root = resolve_archive_relative_path(root, normalized)
    except ArchivePathError:
        return _staged_cleanup_abort(archive_id, ["unsafe_staged_folder"])
    if normalized.split("/", 1)[0].lower() in OBJET_CAPTURE_INTERNAL_PREFIXES:
        return _staged_cleanup_abort(archive_id, ["unsafe_staged_folder"])
    if not is_path_within_root(staged_root, root):
        return _staged_cleanup_abort(archive_id, ["unsafe_staged_folder"])
    if objet_capture_path_chain_blockers(root, normalized):
        return _staged_cleanup_abort(archive_id, ["unsafe_staged_folder"])
    if not staged_root.is_dir():
        return _staged_cleanup_abort(archive_id, ["staged_folder_missing"])

    deferred: set[str] = set()
    if deferred_path is not None:
        try:
            deferred_doc = json.loads(Path(deferred_path).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return _staged_cleanup_abort(archive_id, ["deferred_list_unreadable"])
        raw_deferred = deferred_doc.get("deferred") if isinstance(deferred_doc, dict) else None
        if not isinstance(raw_deferred, list) or any(not isinstance(value, str) for value in raw_deferred):
            return _staged_cleanup_abort(archive_id, ["deferred_list_invalid"])
        deferred = {value.replace("\\", "/").strip("/") for value in raw_deferred}

    _progress("manifest", "start")
    if objet_capture_path_chain_blockers(root, "objects/manifests/files.jsonl"):
        return _staged_cleanup_abort(
            archive_id,
            ["objet_manifest_path_unsafe"],
        )
    (
        manifest_records,
        canonical_ids,
        object_manifest_scan_complete,
        object_manifest_authority,
    ) = _staged_cleanup_strict_object_manifest(root, archive_id)
    if not object_manifest_scan_complete:
        blockers.append("objet_manifest_scan_incomplete")
    derived_records, derived_manifest_scan_complete, derived_manifest_authority = (
        _staged_cleanup_strict_derived_records(root)
    )
    derived_record_infos = [
        _staged_cleanup_derived_record_info(
            record,
            canonical_object_ids=canonical_ids,
        )
        for record in derived_records
    ]
    derived_id_counts: dict[str, int] = {}
    for info in derived_record_infos:
        derived_text_id = info.get("derived_text_id")
        if isinstance(derived_text_id, str):
            derived_id_counts[derived_text_id] = derived_id_counts.get(derived_text_id, 0) + 1
    for info in derived_record_infos:
        derived_text_id = info.get("derived_text_id")
        if isinstance(derived_text_id, str) and derived_id_counts.get(derived_text_id) != 1:
            info["valid"] = False
    if not derived_manifest_scan_complete:
        blockers.append("derived_text_manifest_scan_incomplete")
    _progress(
        "manifest",
        (
            f"loaded {len(canonical_ids)} canonical object records, "
            f"{len(derived_record_infos)} derived records"
        ),
    )
    referencing: dict[str, int] = {}
    _progress("zettel-references", "start")
    zettel_count = 0
    reference_count = 0
    for zettel_path in iter_zettel_paths(root):
        zettel_count += 1
        if _progress_step(zettel_count):
            _progress("zettel-references", f"scanned {zettel_count} notes")
        inspection = inspect_zettel_frontmatter_boundary(zettel_path)
        if (
            not inspection["metadata_readable"]
            or inspection["frontmatter"].get("status")
            not in ZETTEL_QUERYABLE_STATUSES
        ):
            # Reference counts are informative only. Ambiguous and redacted
            # zettels must not contribute content-derived side channels.
            continue
        frontmatter = inspection["frontmatter"]
        for ref in collect_referenced_objets(json_safe(frontmatter)):
            ref_blockers: list[str] = []
            ref_id = normalize_object_id(str(ref.get("value") or ref.get("object_id") or ""), ref_blockers)
            if not ref_blockers and ref_id:
                referencing[ref_id] = referencing.get(ref_id, 0) + 1
                reference_count += 1
    _progress("zettel-references", f"done; scanned {zettel_count} notes and {reference_count} references")

    derived_receipt_cache: dict[
        tuple[str, ...] | None,
        tuple[
            list[tuple[str, dict[str, Any]]],
            set[str],
            bool,
            list[tuple[Path, str, tuple[int, int, int, int, int], str]],
        ],
    ] = {}
    ordinary_receipt_sizes: dict[str, set[int]] | None = None
    ordinary_receipt_candidate_ids: set[str] | None = None
    outer_derived_receipt_names: dict[str, set[str]] | None = None
    evidence_authorities: list[
        tuple[Path, str, tuple[int, int, int, int, int], str]
    ] = []
    if derived_manifest_authority is not None:
        evidence_authorities.append(derived_manifest_authority)
    if object_manifest_authority is not None:
        evidence_authorities.append(object_manifest_authority)

    def derived_receipt_view(
        _prefixes: set[str] | None,
    ) -> tuple[list[tuple[str, dict[str, Any]]], set[str]]:
        # A later official replay writes a new receipt timestamp while retaining
        # the original manifest row. Match receipts by their signed content, not
        # the manifest's original timestamp prefix.
        cache_key = None
        if cache_key not in derived_receipt_cache:
            derived_receipt_cache[cache_key] = _staged_cleanup_receipt_documents(
                root,
                DERIVED_TEXT_CAPTURE_RECEIPTS_DIR,
                safety_required=True,
                filename_prefixes=None,
            )
        documents, names, complete, authorities = derived_receipt_cache[cache_key]
        for authority in authorities:
            if authority not in evidence_authorities:
                evidence_authorities.append(authority)
        if not complete and "derived_text_receipt_scan_incomplete" not in blockers:
            blockers.append("derived_text_receipt_scan_incomplete")
        return documents, names

    def outer_receipt_view() -> tuple[
        dict[str, set[int]],
        set[str],
        dict[str, set[str]],
    ]:
        nonlocal ordinary_receipt_sizes, ordinary_receipt_candidate_ids
        nonlocal outer_derived_receipt_names
        if ordinary_receipt_sizes is None:
            (
                ordinary_receipt_sizes,
                ordinary_receipt_candidate_ids,
                outer_derived_receipt_names,
                complete,
                authorities,
            ) = _staged_cleanup_outer_receipt_links(
                root,
                archive_id=archive_id,
            )
            for authority in authorities:
                if authority not in evidence_authorities:
                    evidence_authorities.append(authority)
            if not complete and "objet_capture_receipt_scan_incomplete" not in blockers:
                blockers.append("objet_capture_receipt_scan_incomplete")
        return (
            ordinary_receipt_sizes,
            ordinary_receipt_candidate_ids or set(),
            outer_derived_receipt_names or {},
        )

    def ordinary_receipt_state(object_id: str, size_bytes: int) -> tuple[bool, bool]:
        receipt_sizes, candidate_ids, _derived_names = outer_receipt_view()
        return (
            size_bytes in receipt_sizes.get(object_id, set()),
            object_id in candidate_ids,
        )

    def derived_evidence_for_digest(digest: str) -> dict[str, Any]:
        current_candidates = [
            info
            for info in derived_record_infos
            if info.get("source_digest") == digest
        ]
        legacy_candidates = [
            info
            for info in derived_record_infos
            if info.get("source_digest") is None
            and info.get("text_digest") == digest
        ]
        candidates = [*current_candidates, *legacy_candidates]
        derived_receipts, derived_receipt_names = derived_receipt_view(None)
        linked_receipts = [
            (name, document)
            for name, document in derived_receipts
            if document.get("source_text_sha256") == digest
            or (
                document.get("schema")
                == "wom-kit/derived-text-capture-receipt/v0.1"
                and document.get("text_sha256") == digest
            )
        ]

        # If the manifest row is missing, a valid direct receipt still tells us
        # where the preserved representation should be.  It never replaces the
        # missing manifest; it only lets the result report store/receipt evidence
        # accurately without exposing a path or digest.
        if not candidates:
            valid_unlinked_receipts = [
                document
                for name, document in linked_receipts
                if _staged_cleanup_valid_derived_receipt(
                    document,
                    filename=name,
                    archive_id=archive_id,
                    staged_digest=digest,
                    record_info=None,
                )
            ]
            receipt = valid_unlinked_receipts[0] if valid_unlinked_receipts else None
            bytes_verified = False
            if receipt is not None:
                bytes_verified, _present, store_authority = _staged_cleanup_store_observation(
                    root,
                    text_digest=receipt.get("text_sha256"),
                    text_logical_key=receipt.get("text_logical_key"),
                )
                if store_authority is not None:
                    evidence_authorities.append(store_authority)
                bytes_verified = bool(
                    bytes_verified and receipt.get("text_sha256") == digest
                )
            return {
                "eligible": bool(linked_receipts),
                "status": "not_preserved",
                "preservation_kind": "none",
                "reason_code": "derived_text_manifest_missing"
                if linked_receipts
                else "staged_entry_not_preserved",
                "manifest_record_present": False,
                "capture_receipt_present": bool(linked_receipts),
                "preserved_bytes_verified": bytes_verified,
            }

        # A candidate is physically present even when strict semantic validation
        # rejects it.  Keep that distinction in booleans while refusing cleanup.
        valid_candidates = [info for info in candidates if info.get("valid")]
        if not valid_candidates:
            _ordinary_sizes, _ordinary_candidates, linked_names_by_id = (
                outer_receipt_view()
            )
            candidate_ids = {
                str(info.get("derived_text_id"))
                for info in candidates
                if info.get("derived_text_id")
            }
            receipt_present = bool(linked_receipts) or any(
                document.get("derived_text_id")
                in candidate_ids
                for _name, document in derived_receipts
            ) or any(
                linked_names_by_id.get(candidate_id, set()) & derived_receipt_names
                for candidate_id in candidate_ids
            )
            first = candidates[0]
            bytes_verified, _present, store_authority = _staged_cleanup_store_observation(
                root,
                text_digest=first.get("text_digest"),
                text_logical_key=first.get("text_logical_key"),
            )
            if store_authority is not None:
                evidence_authorities.append(store_authority)
            return {
                "eligible": True,
                "status": "not_preserved",
                "preservation_kind": "none",
                "reason_code": "derived_text_manifest_invalid",
                "manifest_record_present": True,
                "capture_receipt_present": receipt_present,
                "preserved_bytes_verified": bool(
                    bytes_verified and first.get("text_digest") == digest
                ),
            }

        # Prefer a completely verified exact representation.  This also handles
        # duplicate historical rows deterministically without accepting a weaker
        # row when a stronger one is present.
        evaluations: list[dict[str, Any]] = []
        _ordinary_sizes, _ordinary_candidates, linked_names_by_id = (
            outer_receipt_view()
        )
        for info in valid_candidates:
            matching_receipts = [
                (name, document)
                for name, document in derived_receipts
                if document.get("derived_text_id") == info.get("derived_text_id")
            ]
            physical_receipt_present = bool(matching_receipts) or bool(
                linked_names_by_id.get(str(info.get("derived_text_id")), set())
                & derived_receipt_names
            )
            receipt_valid = any(
                _staged_cleanup_valid_derived_receipt(
                    document,
                    filename=name,
                    archive_id=archive_id,
                    staged_digest=digest,
                    record_info=info,
                )
                for name, document in matching_receipts
            )
            store_verified, store_present, store_authority = _staged_cleanup_store_observation(
                root,
                text_digest=info.get("text_digest"),
                text_logical_key=info.get("text_logical_key"),
            )
            if store_authority is not None:
                evidence_authorities.append(store_authority)
            manifest_size_valid = bool(
                store_authority is not None
                and info.get("size_bytes") == store_authority[2][2]
            )
            evaluations.append(
                {
                    "info": info,
                    "receipt_present": physical_receipt_present,
                    "receipt_valid": receipt_valid,
                    "store_present": store_present,
                    "store_verified": store_verified,
                    "manifest_size_valid": manifest_size_valid,
                }
            )

        for evaluation in evaluations:
            info = evaluation["info"]
            if (
                info.get("text_digest") == digest
                and evaluation["manifest_size_valid"]
                and evaluation["receipt_valid"]
                and evaluation["store_verified"]
            ):
                return {
                    "eligible": True,
                    "status": "preserved",
                    "preservation_kind": "derived_text_exact_bytes",
                    "reason_code": "derived_text_exact_bytes_manifest_store_and_receipt_verified",
                    "manifest_record_present": True,
                    "capture_receipt_present": True,
                    "preserved_bytes_verified": True,
                }

        first = evaluations[0]
        info = first["info"]
        if info.get("text_digest") != digest:
            reason = "derived_text_source_bytes_changed_by_normalization"
        elif not first["store_present"]:
            reason = "derived_text_store_missing"
        elif not first["store_verified"]:
            reason = "derived_text_store_sha256_mismatch"
        elif not first["manifest_size_valid"]:
            reason = "derived_text_manifest_invalid"
        elif not first["receipt_present"]:
            reason = "derived_text_capture_receipt_missing"
        else:
            reason = "derived_text_capture_receipt_invalid"
        return {
            "eligible": True,
            "status": "not_preserved",
            "preservation_kind": "none",
            "reason_code": reason,
            "manifest_record_present": True,
            "capture_receipt_present": bool(first["receipt_present"]),
            "preserved_bytes_verified": bool(first["store_verified"] and info.get("text_digest") == digest),
        }

    files: list[dict[str, Any]] = []
    entries: list[dict[str, Any]] = []
    counts = {"preserved": 0, "deferred": 0, "not_preserved": 0, "unsafe": 0}
    _progress("staged-walk", "start")
    initial_staged_tree_snapshot, staged_files = _staged_cleanup_staged_tree_snapshot(
        root,
        staged_root,
        normalized,
    )
    if initial_staged_tree_snapshot is None:
        blockers.append("staged_tree_unreadable")
    _progress("staged-walk", f"done; found {len(staged_files)} staged entries")
    total_staged_files = len(staged_files)
    for index, path in enumerate(sorted(staged_files), start=1):
        if _progress_step(index, total_staged_files):
            _progress("verify", "checking staged entry", index, total_staged_files)
        if path.is_symlink() or objet_capture_path_chain_blockers(
            root, f"{normalized}/{path.relative_to(staged_root).as_posix()}"
        ):
            counts["unsafe"] += 1
            files.append(
                {
                    "path": path.relative_to(staged_root).as_posix(),
                    "status": "unsafe_symlink",
                    "object_id": None,
                    "preserved_bytes_verified": False,
                    "manifest_record_present": False,
                    "referencing_zets": 0,
                }
            )
            entries.append(
                {
                    "entry_ref": f"staged-entry:{len(entries) + 1:04d}",
                    "status": "unsafe",
                    "preservation_kind": "none",
                    "reason_code": "staged_entry_path_unsafe",
                    "manifest_record_present": False,
                    "capture_receipt_present": False,
                    "preserved_bytes_verified": False,
                    "source_entry_readable": False,
                }
            )
            continue
        if not path.is_file():
            continue
        relative = path.relative_to(staged_root).as_posix()
        source_identity = _staged_cleanup_path_identity(
            root,
            path,
            f"{normalized}/{relative}",
        )
        source_size_hint = source_identity[2] if source_identity is not None else 0
        digest, source_size, source_authority = _staged_cleanup_stable_file_digest(
            root,
            path,
            f"{normalized}/{relative}",
            progress_callback=_hash_progress("source-hash", source_size_hint),
        )
        if digest is None or source_size is None or source_authority is None:
            counts["unsafe"] += 1
            files.append(
                {
                    "path": relative,
                    "status": "unreadable",
                    "object_id": None,
                    "preserved_bytes_verified": False,
                    "manifest_record_present": False,
                    "referencing_zets": 0,
                }
            )
            entries.append(
                {
                    "entry_ref": f"staged-entry:{len(entries) + 1:04d}",
                    "status": "unsafe",
                    "preservation_kind": "none",
                    "reason_code": "staged_entry_unreadable",
                    "manifest_record_present": False,
                    "capture_receipt_present": False,
                    "preserved_bytes_verified": False,
                    "source_entry_readable": False,
                }
            )
            continue
        evidence_authorities.append(source_authority)
        object_id = f"sha256:{digest}"
        dest_relative = f"objects/sha256/{digest[:2]}/{digest}"
        dest = archive_internal_path(root, dest_relative)
        # FALSE-SAFE is the fatal failure mode here: a "safe to clean up" verdict for a
        # file whose stored copy is absent, corrupted, or unreferenced would let the only
        # copy be deleted. So preservation requires ALL THREE: dest exists, stored bytes
        # re-hash to the same digest, and a canonical manifest record exists.
        bytes_verified = False
        if not objet_capture_path_chain_blockers(root, dest_relative):
            bytes_verified = (
                _stable_exact_file_observation(
                    dest,
                    expected_size=source_size,
                    expected_sha256=digest,
                )
                == "verified_exact"
            )
            if bytes_verified:
                dest_identity = _staged_cleanup_path_identity(root, dest, dest_relative)
                if dest_identity is None:
                    bytes_verified = False
                else:
                    evidence_authorities.append(
                        (dest, dest_relative, dest_identity, digest)
                    )
        record_present = bool(
            object_id in canonical_ids
            and any(
                record.get("object_id") == object_id
                and record.get("size_bytes") == source_size
                for record in manifest_records
            )
        )
        receipt_valid, receipt_candidate_present = ordinary_receipt_state(
            object_id,
            source_size,
        )
        if bytes_verified and record_present and receipt_valid:
            status = "preserved"
            preservation_kind = "objet"
            reason_code = "objet_bytes_manifest_store_and_receipt_verified"
            selected_manifest_present = True
            selected_receipt_present = True
            selected_bytes_verified = True
        elif relative in deferred:
            status = "deferred"
            preservation_kind = "explicit_deferment"
            reason_code = "staged_entry_explicitly_deferred"
            selected_manifest_present = record_present
            selected_receipt_present = receipt_candidate_present
            selected_bytes_verified = bytes_verified
        else:
            derived_evidence = derived_evidence_for_digest(digest)
            if (
                derived_evidence.get("eligible")
                and derived_evidence.get("status") == "preserved"
            ):
                status = str(derived_evidence["status"])
                preservation_kind = str(derived_evidence["preservation_kind"])
                reason_code = str(derived_evidence["reason_code"])
                selected_manifest_present = bool(derived_evidence["manifest_record_present"])
                selected_receipt_present = bool(derived_evidence["capture_receipt_present"])
                selected_bytes_verified = bool(derived_evidence["preserved_bytes_verified"])
            elif bytes_verified and record_present:
                status = "not_preserved"
                preservation_kind = "objet"
                reason_code = (
                    "objet_capture_receipt_invalid"
                    if receipt_candidate_present
                    else "objet_capture_receipt_missing"
                )
                selected_manifest_present = True
                selected_receipt_present = receipt_candidate_present
                selected_bytes_verified = True
            elif derived_evidence.get("eligible"):
                status = str(derived_evidence["status"])
                preservation_kind = str(derived_evidence["preservation_kind"])
                reason_code = str(derived_evidence["reason_code"])
                selected_manifest_present = bool(derived_evidence["manifest_record_present"])
                selected_receipt_present = bool(derived_evidence["capture_receipt_present"])
                selected_bytes_verified = bool(derived_evidence["preserved_bytes_verified"])
            else:
                status = "not_preserved"
                preservation_kind = "none"
                if record_present and not bytes_verified:
                    reason_code = "objet_store_missing_or_sha256_mismatch"
                elif bytes_verified and not record_present:
                    reason_code = "objet_manifest_missing"
                else:
                    reason_code = "staged_entry_not_preserved"
                selected_manifest_present = record_present
                selected_receipt_present = receipt_candidate_present
                selected_bytes_verified = bytes_verified
        counts[status if status in counts else "not_preserved"] += 1
        files.append(
            {
                "path": relative,
                "status": status,
                "object_id": object_id,
                "preserved_bytes_verified": selected_bytes_verified,
                "manifest_record_present": selected_manifest_present,
                "referencing_zets": referencing.get(object_id, 0),
            }
        )
        entries.append(
            {
                "entry_ref": f"staged-entry:{len(entries) + 1:04d}",
                "status": status,
                "preservation_kind": preservation_kind,
                "reason_code": reason_code,
                "manifest_record_present": selected_manifest_present,
                "capture_receipt_present": selected_receipt_present,
                "preserved_bytes_verified": selected_bytes_verified,
                "source_entry_readable": True,
            }
        )
    _progress("verify", f"done; checked {len(files)} staged file reports")

    # A cleanup verdict is authority-bound to one complete staging tree and to
    # every source/evidence file used above. Any drift during the inspection
    # invalidates the entire report; the operator must run a fresh check.
    final_staged_tree_snapshot, _final_staged_files = _staged_cleanup_staged_tree_snapshot(
        root,
        staged_root,
        normalized,
    )
    if (
        initial_staged_tree_snapshot is None
        or final_staged_tree_snapshot is None
        or final_staged_tree_snapshot != initial_staged_tree_snapshot
    ):
        blockers.append("staged_tree_changed_during_inspection")
    if any(
        not _staged_cleanup_authority_unchanged(root, authority)
        for authority in dict.fromkeys(evidence_authorities)
    ):
        blockers.append("staged_evidence_changed_during_inspection")

    if not files:
        warnings.append("staged_folder_empty")
    if counts["not_preserved"]:
        warnings.append("staged_entries_not_preserved")
    if counts["deferred"]:
        warnings.append("staged_entries_deferred")
    if counts["unsafe"]:
        warnings.append("staged_entries_unsafe")
    safe_to_cleanup = (
        counts["deferred"] == 0
        and counts["not_preserved"] == 0
        and counts["unsafe"] == 0
        and not blockers
    )
    reason_codes = unique_preserve_order(
        [
            *blockers,
            *[
                str(entry.get("reason_code"))
                for entry in entries
                if entry.get("status") in {"deferred", "not_preserved", "unsafe"}
                and isinstance(entry.get("reason_code"), str)
            ],
        ]
    )
    state = (
        "inspection_blocked"
        if blockers
        else ("safe_to_cleanup" if safe_to_cleanup else "not_safe_to_cleanup")
    )
    return {
        "schema": STAGED_CLEANUP_CHECK_SCHEMA,
        "ok": not blockers,
        "state": state,
        "reason_codes": reason_codes,
        "dry_run": True,
        "lifecycle_action": "staged_cleanup_check",
        "archive_id": archive_id,
        "staged_folder": normalized,
        "safe_to_cleanup": safe_to_cleanup,
        "deletion_performed": False,
        "entries": entries,
        "files": files,
        "summary": counts,
        "next_safe_actions": [
            "When state is not_safe_to_cleanup, do not delete or move the staged folder.",
            "For missing or incomplete paired-capture evidence, preserve the archive and obtain one completed v0.4.10 source-intake-batch execution for the unchanged reviewed request; never edit manifests or receipts manually.",
            "Run archive objet-capture-batch <archive-root> --source-intake-execution-sha256 <completed-intake-execution-sha256> --dry-run --format json; review it, then use a new separate capture approval bound to that fresh plan digest.",
            "For missing or invalid ordinary capture receipts, run archive objet-capture <archive-root> --selection <retained-selection.json> --dry-run --format json, review it, then use a separate approval so replay can mint fresh evidence.",
            "After a partial or uncertain batch capture, never reuse the prior approval or replay individual items; run the same source-execution-bound capture dry-run, obtain a new approval, then run a fresh staged-cleanup-check.",
            "When source bytes changed during text normalization, preserve the raw staged bytes as an ordinary objet; a deferred entry must remain staged and blocks folder cleanup.",
            "Run archive doctor --strict and resolve any errors before cleanup.",
            "Run wom-kit/tools/check_artifact_hygiene.py and resolve unresolved blockers.",
            "Cleanup is a manual, human-approved deletion; this tool never deletes.",
        ],
        "blockers": blockers,
        "warnings": warnings,
        "would_change": [],
    }


def _staged_cleanup_abort(archive_id: str, blockers: list[str]) -> dict[str, Any]:
    return {
        "schema": STAGED_CLEANUP_CHECK_SCHEMA,
        "ok": False,
        "state": "inspection_blocked",
        "reason_codes": unique_preserve_order(blockers),
        "dry_run": True,
        "lifecycle_action": "staged_cleanup_check",
        "archive_id": archive_id,
        "safe_to_cleanup": False,
        "deletion_performed": False,
        "entries": [],
        "files": [],
        "summary": {"preserved": 0, "deferred": 0, "not_preserved": 0, "unsafe": 0},
        "next_safe_actions": [
            "Do not delete or move the staged folder.",
            "Resolve the fixed inspection blocker, then run a fresh staged-cleanup-check dry-run.",
        ],
        "blockers": blockers,
        "warnings": [],
        "would_change": [],
    }


def objet_capture_dry_run(
    archive_root: Path | str,
    selection_path: Path | str,
    *,
    project_intake_receipt: str | None = None,
) -> dict[str, Any]:
    return _objet_capture_run(
        archive_root,
        selection_path,
        approve=False,
        reviewed_by=None,
        project_intake_receipt=project_intake_receipt,
    )


def objet_capture_document_dry_run(
    archive_root: Path | str,
    selection: dict[str, Any],
    *,
    project_intake_receipt: str | None = None,
) -> dict[str, Any]:
    """Preview an already parsed selection without writing a temporary file."""

    return _objet_capture_run(
        archive_root,
        None,
        approve=False,
        reviewed_by=None,
        project_intake_receipt=project_intake_receipt,
        selection_document=selection,
    )


def objet_capture_exact_dry_run(
    archive_root: Path | str,
    selection_path: Path | str,
    *,
    project_intake_receipt: str | None = None,
) -> dict[str, Any]:
    """Plan a live single capture for the native exact-approval boundary.

    This is read-only.  It replaces the forgeable persistent enablement marker
    only for the exact selection that will be bound to the native decision.
    """

    return _objet_capture_run(
        archive_root,
        selection_path,
        approve=False,
        reviewed_by=None,
        project_intake_receipt=project_intake_receipt,
        native_exact_authorized=True,
    )


def objet_capture_apply(
    archive_root: Path | str,
    selection_path: Path | str,
    *,
    reviewed_by: str,
    approval_operation: ExactHumanApprovalOperation = (
        ExactHumanApprovalOperation.objet_capture
    ),
    project_intake_receipt: str | None = None,
    selection_document: dict[str, Any] | None = None,
    expected_exact_approval_plan_sha256: str | None = None,
    expected_exact_approval_target_binding_sha256: str | None = None,
    exact_human_approval_claim: _ClaimedExactHumanApproval | None = None,
) -> dict[str, Any]:
    try:
        if approval_operation not in (
            ExactHumanApprovalOperation.objet_capture,
            ExactHumanApprovalOperation.objet_capture_batch,
        ):
            raise ArchiveServiceError("operation_approval_plan_invalid")
        _require_exact_human_approval_inputs_before_archive_read(
            claim=exact_human_approval_claim,
            expected_plan_sha256=expected_exact_approval_plan_sha256,
            expected_target_binding_sha256=(
                expected_exact_approval_target_binding_sha256
            ),
        )
    except ArchiveServiceError:
        return _compound_exact_human_approval_blocked(
            lifecycle_action="objet_capture",
        )
    preview = _objet_capture_run(
        archive_root,
        selection_path,
        approve=False,
        reviewed_by=None,
        project_intake_receipt=project_intake_receipt,
        selection_document=selection_document,
        selection_document_path=(
            selection_path if selection_document is not None else None
        ),
        native_exact_authorized=True,
    )
    if preview.get("ok") is not True:
        return preview
    root = require_existing_archive_root(archive_root)
    try:
        approval_receipt = _require_exact_human_operation_approval(
            root,
            objet_capture_approval_binding(
                preview,
                operation=approval_operation,
            ),
            reviewer_claim=reviewed_by,
            expected_plan_sha256=expected_exact_approval_plan_sha256,
            expected_target_binding_sha256=(
                expected_exact_approval_target_binding_sha256
            ),
            claim=exact_human_approval_claim,
        )
    except OperationApprovalBindingError as exc:
        raise ArchiveServiceError(exc.code) from None
    return _objet_capture_run(
        archive_root,
        selection_path,
        approve=True,
        reviewed_by=reviewed_by,
        project_intake_receipt=project_intake_receipt,
        selection_document=selection_document,
        selection_document_path=(
            selection_path if selection_document is not None else None
        ),
        native_exact_authorized=True,
        exact_human_approval_receipt=approval_receipt,
    )


def capture_enablement_receipt_relative_path(timestamp: str) -> str:
    # Fixed basename: the record is a singleton per archive, and archive ids contain
    # colons which would become an NTFS alternate data stream on Windows. The compact
    # timestamp mirrors operator_feedback_receipt_relative_path.
    compact = re.sub(r"[^0-9TZ]", "", timestamp)
    return f"{CAPTURE_ENABLEMENT_RECEIPTS_DIR}/capture-enablement.{compact}.json"


def objet_capture_enable(
    archive_root: Path | str,
    *,
    dry_run: bool = False,
    approve: bool = False,
    reviewed_by: str | None = None,
    revoke: bool = False,
    acknowledge_never_touch_name: bool = False,
    reenable: bool = False,
) -> dict[str, Any]:
    """Inspect, approve, or revoke the owner capture-enablement record.

    The record gates ONLY objet-capture (its sole gate consumer is
    _objet_capture_run); derive-text capture and tiro-lossless-recovery-capture
    keep their own rules. --dry-run is a read-only eligibility report and writes
    nothing; --approve evaluates every blocker BEFORE any write, then writes the
    receipt first and the record second (so a valid record implies at least one
    receipt even across a crash). Revocation is advisory and forward-only.
    """
    if type(dry_run) is not bool or type(approve) is not bool or approve:
        return _compound_exact_human_approval_blocked(
            lifecycle_action="objet_capture_enable",
        )
    root = require_existing_archive_root(archive_root)
    blockers: list[str] = []
    warnings: list[str] = []
    if dry_run is approve:
        blockers.append("Choose exactly one mode: --dry-run or --approve.")
    reviewer = safe_project_intake_actor_id(reviewed_by)
    if approve and reviewer is None:
        blockers.append("objet-capture-enable approval requires --reviewed-by with a safe actor id.")
    if reviewed_by and reviewer is None:
        blockers.append("reviewed_by must be a safe non-secret actor id.")

    enablement = read_capture_enablement(root)
    raw_record = enablement.get("record") if isinstance(enablement.get("record"), dict) else None
    never_touch_match = target_looks_external_live_never_touch(root)
    try:
        archive_id: str | None = read_archive_id(root)
    except Exception:
        archive_id = None

    # Eligibility state, by locked precedence:
    # enabled > revoked > invalid_record > sandbox_marked > not_an_archive > not_enabled.
    # never_touch_name_match is orthogonal and never a blocking state for ENABLEMENT.
    if enablement["state"] == "enabled":
        state = "enabled"
    elif enablement["state"] == "revoked":
        state = "revoked"
    elif enablement["state"] in ("invalid", "disabled"):
        state = "invalid_record"
    elif objet_capture_sandbox_marked(root):
        state = "sandbox_marked"
    elif archive_id is None:
        state = "not_an_archive"
    else:
        state = "not_enabled"

    now = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    record_relative = CAPTURE_ENABLEMENT_RELATIVE_PATH
    receipt_relative = capture_enablement_receipt_relative_path(now)
    action = "revoke" if revoke else "enable"

    record_has_revocation = bool(
        raw_record is not None
        and raw_record.get("enabled") is False
        and isinstance(raw_record.get("revoked_by"), str)
        and raw_record.get("revoked_by")
    )

    if approve:
        if revoke:
            if not enablement["present"]:
                blockers.append("nothing_to_revoke")
            elif raw_record is None:
                blockers.append("invalid_record_present")
        else:
            if archive_id is None:
                blockers.append("not_an_archive")
            if never_touch_match and not acknowledge_never_touch_name:
                blockers.append("never_touch_acknowledgement_required")
            if record_has_revocation and not reenable:
                blockers.append("revoked_record_present_use_reenable")

    record_path: Path | None = None
    receipt_path: Path | None = None
    if approve:
        # Resolve write targets and reject unsafe chains BEFORE any write: the
        # enablement paths sit inside a root class the never-touch pattern normally
        # protects, and write_text_atomic does not protect against a symlinked parent.
        try:
            record_path = archive_internal_path(root, record_relative)
            receipt_path = archive_internal_path(root, receipt_relative)
        except ArchiveServiceError:
            blockers.append("unsafe_record_path")
        if record_path is not None and receipt_path is not None:
            if not is_path_within_root(record_path, root) or not is_path_within_root(receipt_path, root):
                blockers.append("unsafe_record_path")
            elif objet_capture_path_chain_blockers(root, record_relative) or objet_capture_path_chain_blockers(
                root, receipt_relative
            ):
                blockers.append("unsafe_record_path")

    if revoke:
        record: dict[str, Any] = dict(raw_record) if raw_record is not None else {}
        record["enabled"] = False
        record["revoked_by"] = reviewer
        record["revoked_at"] = now
    else:
        record = {
            "schema": CAPTURE_ENABLEMENT_SCHEMA,
            "scope": CAPTURE_ENABLEMENT_SCOPE,
            "archive_id": archive_id,
            "enabled": True,
            "statement": CAPTURE_ENABLEMENT_STATEMENT,
            "reviewed_by": reviewer,
            "enabled_at": now,
            "never_touch_acknowledged": bool(acknowledge_never_touch_name),
            "revoked_by": None,
            "revoked_at": None,
        }

    if revoke:
        planned = bool(raw_record is not None and state != "revoked")
    else:
        planned = state in ("not_enabled", "sandbox_marked", "invalid_record", "revoked")
    planned_writes = [receipt_relative, record_relative] if planned else []

    receipt = {
        "schema": CAPTURE_ENABLEMENT_RECEIPT_SCHEMA,
        "dry_run": dry_run,
        "approved": approve and not blockers,
        "action": action,
        "archive_id": record.get("archive_id") if revoke else archive_id,
        "record_path": record_relative,
        "reviewed_by": reviewer,
        "never_touch_acknowledged": record.get("never_touch_acknowledged") is True,
        "reenable": bool(reenable),
        "record_sha256": sha256_text(dump_yaml(json_safe(record))),
        "created_at": now,
    }

    written = False
    if approve and not blockers and record_path is not None and receipt_path is not None:
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        record_path.parent.mkdir(parents=True, exist_ok=True)
        # Receipt FIRST, then record: the gate never requires a receipt, but this
        # ordering makes "a valid record implies a receipt" hold across a crash.
        write_text_atomic(receipt_path, json.dumps(json_safe(receipt), indent=2, ensure_ascii=False) + "\n")
        write_text_atomic(record_path, dump_yaml(json_safe(record)))
        written = True

    if written:
        result_state = "revoked" if revoke else "enabled"
    elif approve and blockers:
        result_state = "blocked"
    else:
        result_state = state

    next_safe_actions = [
        "Review this eligibility report with the archive owner before approving.",
        "Approve with: archive objet-capture-enable <archive-root> --approve --reviewed-by <actor>"
        + (" --acknowledge-never-touch-name" if never_touch_match else ""),
        "Revoke later with: archive objet-capture-enable <archive-root> --revoke --approve --reviewed-by <actor>",
        "Revocation is advisory and forward-only: already-captured bytes, manifest records, and capture receipts remain.",
    ]

    result: dict[str, Any] = {
        "ok": not blockers,
        "state": result_state,
        "dry_run": dry_run or not approve,
        "approved": written,
        "lifecycle_action": "objet_capture_enable_plan" if not approve else "objet_capture_enable",
        "action": action,
        "archive_id": archive_id,
        "never_touch_name_match": never_touch_match,
        "enablement_state": enablement["state"],
        "planned_writes": planned_writes if not written else [],
        "record_path": record_relative if written else None,
        "receipt_path": receipt_relative if written else None,
        "files_written": [receipt_relative, record_relative] if written else [],
        "would_change": planned_writes if (dry_run and not blockers) else [],
        "data": {
            "record_schema": CAPTURE_ENABLEMENT_SCHEMA,
            "receipt_schema": CAPTURE_ENABLEMENT_RECEIPT_SCHEMA,
            "scope": CAPTURE_ENABLEMENT_SCOPE,
            "gate_scope": "objet-capture only; derive-text capture and tiro-lossless-recovery-capture keep their own rules",
        },
        "next_safe_actions": next_safe_actions,
        "blockers": unique_preserve_order(blockers),
        "warnings": unique_preserve_order(warnings),
        "privacy_guards": {
            "provider_calls": False,
            "network_checked": False,
            "file_bodies_read": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "writes": written,
        },
    }
    if result_state == "invalid_record":
        result["reason"] = enablement.get("reason")
    return result
